110	sqlserver	query	Check AG secondary replica lag	{"sql": "SELECT ag.name AS ag_name, ar.replica_server_name,\\n  drs.database_id, DB_NAME(drs.database_id) AS database_name,\\n  drs.log_send_queue_size AS send_queue_kb,\\n  drs.redo_queue_size AS redo_queue_kb,\\n  drs.last_commit_time,\\n  DATEDIFF(second, drs.last_commit_time, GETDATE()) AS lag_seconds,\\n  drs.synchronization_state_desc\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.is_local = 1\\n  AND drs.is_primary_replica = 0\\n  AND DATEDIFF(second, drs.last_commit_time, GETDATE()) > :lag_threshold_sec"}	{"condition": "row_count > 0", "description": "Secondary replica lag exceeds threshold — backups taken here will be stale"}	{"lag_threshold_sec": 300}	2026-02-23 20:18:31.388893
111	sqlserver	query	Check transaction log backup sizes for spikes	{"sql": "WITH log_backups AS (\\n  SELECT database_name, backup_start_date,\\n    CAST(backup_size / 1048576.0 AS decimal(18,2)) AS log_size_mb,\\n    AVG(CAST(backup_size / 1048576.0 AS decimal(18,2))) OVER (PARTITION BY database_name ORDER BY backup_start_date ROWS BETWEEN 7 PRECEDING AND 1 PRECEDING) AS avg_prev_mb\\n  FROM msdb.dbo.backupset\\n  WHERE type = 'L' AND backup_start_date > DATEADD(day, -7, GETDATE())\\n)\\nSELECT database_name, backup_start_date, log_size_mb, avg_prev_mb,\\n  CAST(log_size_mb / NULLIF(avg_prev_mb, 0) AS decimal(5,1)) AS spike_ratio\\nFROM log_backups\\nWHERE avg_prev_mb > 0 AND log_size_mb > avg_prev_mb * :spike_multiplier"}	{"condition": "row_count > 0", "description": "Transaction log backup size spiked beyond threshold vs recent average"}	{"spike_multiplier": 5}	2026-02-23 20:18:31.388894
112	sqlserver	query	Check for gaps in backup schedule	{"sql": "SELECT database_name,\\n  MAX(backup_finish_date) AS last_backup,\\n  DATEDIFF(hour, MAX(backup_finish_date), GETDATE()) AS hours_since_last\\nFROM msdb.dbo.backupset\\nWHERE type IN ('D', 'L')\\nGROUP BY database_name\\nHAVING DATEDIFF(hour, MAX(backup_finish_date), GETDATE()) > :max_gap_hours"}	{"condition": "row_count > 0", "description": "Backup gap exceeds threshold — missed schedules detected"}	{"max_gap_hours": 24}	2026-02-23 20:18:31.388894
165	sqlserver	query	Check backup compression and checksum defaults	{"sql": "SELECT name, CAST(value_in_use AS int) AS is_enabled\\nFROM sys.configurations\\nWHERE name IN ('backup compression default', 'backup checksum default')\\n  AND CAST(value_in_use AS int) = 0"}	{"condition": "row_count > 0", "description": "Backup compression or checksum disabled — reduces backup reliability and increases size"}	null	2026-02-23 20:18:31.388895
113	sqlserver	query	Check backup job enabled status and schedules	{"sql": "SELECT j.name, j.enabled,\\n  CASE WHEN s.schedule_id IS NULL THEN 'No schedule' WHEN s.enabled = 0 THEN 'Schedule disabled' ELSE 'Scheduled' END AS schedule_status,\\n  s.name AS schedule_name, s.freq_type\\nFROM msdb.dbo.sysjobs j\\nLEFT JOIN msdb.dbo.sysjobschedules js ON j.job_id = js.job_id\\nLEFT JOIN msdb.dbo.sysschedules s ON js.schedule_id = s.schedule_id\\nWHERE j.name LIKE '%backup%'\\n  AND (j.enabled = 0 OR s.schedule_id IS NULL OR s.enabled = 0)"}	{"condition": "row_count > 0", "description": "Backup jobs found that are disabled or have no active schedule"}	null	2026-02-23 20:18:31.388895
114	sqlserver	query	Check for backup failures with target connectivity errors	{"sql": "SELECT j.name, h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id\\nWHERE j.name LIKE '%backup%'\\n  AND h.run_status = 0\\n  AND (h.message LIKE '%cannot open backup device%'\\n    OR h.message LIKE '%operating system error 53%'\\n    OR h.message LIKE '%operating system error 5%'\\n    OR h.message LIKE '%network path%'\\n    OR h.message LIKE '%The specified network name is no longer available%')\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))"}	{"condition": "row_count > 0", "description": "Backup failures with storage target connectivity errors (OS error 53=network path not found)"}	null	2026-02-23 20:18:31.388896
115	sqlserver	query	Check for log chain gaps by comparing LSNs	{"sql": "WITH log_chain AS (\\n  SELECT database_name, first_lsn, last_lsn, backup_start_date,\\n    LAG(last_lsn) OVER (PARTITION BY database_name ORDER BY backup_start_date) AS prev_last_lsn\\n  FROM msdb.dbo.backupset\\n  WHERE type = 'L' AND backup_start_date > DATEADD(day, -7, GETDATE())\\n)\\nSELECT database_name, backup_start_date, first_lsn, prev_last_lsn\\nFROM log_chain\\nWHERE prev_last_lsn IS NOT NULL\\n  AND first_lsn != prev_last_lsn"}	{"condition": "row_count > 0", "description": "LSN discontinuity found — log chain is broken"}	null	2026-02-23 20:18:31.388897
