122	sqlserver	query	Check oldest available log backup age	{"sql": "SELECT database_name,\\n  MIN(backup_start_date) AS oldest_log_backup,\\n  MAX(backup_start_date) AS newest_log_backup,\\n  DATEDIFF(hour, MIN(backup_start_date), MAX(backup_start_date)) AS retention_hours,\\n  COUNT(*) AS log_backup_count\\nFROM msdb.dbo.backupset\\nWHERE type = 'L'\\nGROUP BY database_name\\nHAVING DATEDIFF(hour, MIN(backup_start_date), MAX(backup_start_date)) < :min_retention_hours"}	{"condition": "row_count > 0", "description": "Log backup retention is shorter than minimum — PITR window is too narrow"}	{"min_retention_hours": 168}	2026-02-23 20:18:31.388901
123	sqlserver	query	Check maintenance cleanup job status	{"sql": "SELECT j.name, h.run_date, h.run_status,\\n  CASE h.run_status WHEN 0 THEN 'Failed' WHEN 1 THEN 'Succeeded' WHEN 2 THEN 'Retry' WHEN 3 THEN 'Cancelled' END AS status_desc,\\n  h.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id\\nWHERE (j.name LIKE '%cleanup%' OR j.name LIKE '%maintenance%' OR j.name LIKE '%purge%' OR j.name LIKE '%retention%')\\n  AND h.step_id = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\nORDER BY h.run_date DESC"}	{"condition": "run_status = 0", "description": "Cleanup/maintenance jobs failing — old backups not being purged"}	null	2026-02-23 20:18:31.388902
