135	sqlserver	query	Check for backup chain breaks near freeze timestamps	{"sql": "WITH log_chain AS (\\n  SELECT database_name, first_lsn, last_lsn, backup_start_date,\\n    LAG(last_lsn) OVER (PARTITION BY database_name ORDER BY backup_start_date) AS prev_last_lsn\\n  FROM msdb.dbo.backupset\\n  WHERE type = 'L' AND backup_start_date > DATEADD(day, -7, GETDATE())\\n)\\nSELECT database_name, backup_start_date, first_lsn, prev_last_lsn\\nFROM log_chain\\nWHERE prev_last_lsn IS NOT NULL AND first_lsn != prev_last_lsn"}	{"condition": "row_count > 0 AND timestamps_correlate_with_freeze", "description": "Log chain break correlates with VSS freeze events — VM snapshot caused the break"}	null	2026-02-23 20:18:31.388909
138	sqlserver	query	Check transaction log file sizes and usage	{"sql": "SELECT DB_NAME(database_id) AS database_name,\\n  name AS log_file_name,\\n  CAST(size * 8.0 / 1024 AS decimal(10,2)) AS size_mb,\\n  CAST(FILEPROPERTY(name, 'SpaceUsed') * 8.0 / 1024 AS decimal(10,2)) AS used_mb,\\n  CAST(max_size * 8.0 / 1024 AS decimal(10,2)) AS max_size_mb,\\n  growth, is_percent_growth\\nFROM sys.master_files\\nWHERE type = 1\\n  AND CAST(size * 8.0 / 1024 AS decimal(10,2)) > :min_log_size_mb\\nORDER BY size DESC"}	{"condition": "size_mb > min_log_size_mb", "description": "Transaction log files are large — potential unchecked growth"}	{"min_log_size_mb": 10240}	2026-02-23 20:18:31.388911
