140	sqlserver	query	Check for failed backup jobs that started writing	{"sql": "SELECT j.name, h.run_date, h.run_duration, h.message,\\n  CASE WHEN h.message LIKE '%operating system error%' OR h.message LIKE '%I/O%' THEN 'Partial file likely'\\n       WHEN h.message LIKE '%cancel%' THEN 'Cancelled — partial file possible'\\n       ELSE 'Unknown' END AS orphan_risk\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id\\nWHERE j.name LIKE '%backup%'\\n  AND h.run_status IN (0, 3)\\n  AND h.run_duration > 100\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -30, GETDATE()), 112))"}	{"condition": "row_count > 0 AND run_duration > 100", "description": "Failed/cancelled backup jobs that ran for >1 min likely left partial files"}	null	2026-02-23 20:18:31.388912
143	sqlserver	query	Compare differential backup sizes to full backup sizes	{"sql": "WITH full_sizes AS (\\n  SELECT database_name,\\n    MAX(CASE WHEN type = 'D' THEN backup_size END) AS last_full_size\\n  FROM msdb.dbo.backupset\\n  WHERE backup_start_date > DATEADD(day, -30, GETDATE())\\n  GROUP BY database_name\\n)\\nSELECT bs.database_name, bs.backup_start_date,\\n  CAST(bs.backup_size / 1073741824.0 AS decimal(10,2)) AS diff_size_gb,\\n  CAST(fs.last_full_size / 1073741824.0 AS decimal(10,2)) AS full_size_gb,\\n  CAST(100.0 * bs.backup_size / NULLIF(fs.last_full_size, 0) AS decimal(5,1)) AS diff_pct_of_full\\nFROM msdb.dbo.backupset bs\\nJOIN full_sizes fs ON bs.database_name = fs.database_name\\nWHERE bs.type = 'I'\\n  AND bs.backup_start_date > DATEADD(day, -7, GETDATE())\\n  AND bs.backup_size > fs.last_full_size * :max_diff_ratio\\nORDER BY diff_pct_of_full DESC"}	{"condition": "row_count > 0", "description": "Differential backup is larger than threshold percentage of full backup — mass change detected"}	{"max_diff_ratio": 0.7}	2026-02-23 20:18:31.388914
144	sqlserver	query	Check backup accumulation over time	{"sql": "SELECT database_name,\\n  COUNT(*) AS backup_count,\\n  MIN(backup_start_date) AS oldest_backup,\\n  MAX(backup_start_date) AS newest_backup,\\n  DATEDIFF(day, MIN(backup_start_date), GETDATE()) AS retention_span_days,\\n  CAST(SUM(COALESCE(compressed_backup_size, backup_size)) / 1073741824.0 AS decimal(10,2)) AS total_gb\\nFROM msdb.dbo.backupset\\nGROUP BY database_name\\nHAVING DATEDIFF(day, MIN(backup_start_date), GETDATE()) > :expected_retention_days\\nORDER BY total_gb DESC"}	{"condition": "retention_span_days > expected_retention_days", "description": "Backup catalog shows files older than expected retention — cleanup not working"}	{"expected_retention_days": 30}	2026-02-23 20:18:31.388915
