157	sqlserver	query	Find foreign keys with cascade delete actions	{"sql": "SELECT OBJECT_SCHEMA_NAME(fk.parent_object_id) AS child_schema,\\n  OBJECT_NAME(fk.parent_object_id) AS child_table,\\n  OBJECT_SCHEMA_NAME(fk.referenced_object_id) AS parent_schema,\\n  OBJECT_NAME(fk.referenced_object_id) AS parent_table,\\n  fk.name AS fk_name, fk.delete_referential_action_desc,\\n  fk.update_referential_action_desc\\nFROM sys.foreign_keys fk\\nWHERE fk.delete_referential_action_desc = 'CASCADE'\\n  OR fk.update_referential_action_desc = 'CASCADE'"}	{"condition": "row_count > 0", "description": "Cascade foreign keys found — review for unintended mass deletion risk"}	null	2026-02-23 20:18:31.388924
158	sqlserver	query	Check cascade chain depth (multi-level cascades)	{"sql": "WITH cascade_chain AS (\\n  SELECT fk.referenced_object_id AS root_table,\\n    fk.parent_object_id AS child_table, 1 AS depth\\n  FROM sys.foreign_keys fk\\n  WHERE fk.delete_referential_action_desc = 'CASCADE'\\n  UNION ALL\\n  SELECT cc.root_table, fk.parent_object_id, cc.depth + 1\\n  FROM cascade_chain cc\\n  JOIN sys.foreign_keys fk ON fk.referenced_object_id = cc.child_table\\n  WHERE fk.delete_referential_action_desc = 'CASCADE' AND cc.depth < 5\\n)\\nSELECT OBJECT_NAME(root_table) AS root_table, MAX(depth) AS max_cascade_depth,\\n  COUNT(DISTINCT child_table) AS affected_tables\\nFROM cascade_chain\\nGROUP BY root_table\\nHAVING MAX(depth) > 1\\nORDER BY max_cascade_depth DESC"}	{"condition": "max_cascade_depth > 1", "description": "Multi-level cascade chains found — deleting from root can cascade through multiple tables"}	null	2026-02-23 20:18:31.388925
160	sqlserver	query	Check for sessions running at READ UNCOMMITTED	{"sql": "SELECT s.session_id, s.login_name, s.program_name, s.host_name,\\n  s.transaction_isolation_level,\\n  CASE s.transaction_isolation_level\\n    WHEN 0 THEN 'Unspecified' WHEN 1 THEN 'ReadUncommitted'\\n    WHEN 2 THEN 'ReadCommitted' WHEN 3 THEN 'RepeatableRead'\\n    WHEN 4 THEN 'Serializable' WHEN 5 THEN 'Snapshot'\\n  END AS isolation_desc\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.transaction_isolation_level = 1"}	{"condition": "row_count > 0", "description": "Active sessions using READ UNCOMMITTED — dirty reads possible"}	null	2026-02-23 20:18:31.388926
164	sqlserver	query	Check query-related timeout and governor settings	{"sql": "SELECT name, CAST(value_in_use AS bigint) AS current_value,\\n  CASE\\n    WHEN name = 'remote query timeout (s)' AND CAST(value_in_use AS bigint) = 0 THEN 'INFINITE — no timeout'\\n    WHEN name = 'remote query timeout (s)' AND CAST(value_in_use AS bigint) < 5 THEN 'VERY LOW — may fail normal queries'\\n    WHEN name = 'query governor cost limit' AND CAST(value_in_use AS bigint) > 0 AND CAST(value_in_use AS bigint) < 10 THEN 'VERY LOW — blocks most queries'\\n    ELSE 'OK'\\n  END AS assessment\\nFROM sys.configurations\\nWHERE name IN ('remote query timeout (s)', 'query governor cost limit', 'query wait (s)')\\n  AND (\\n    (name = 'remote query timeout (s)' AND (CAST(value_in_use AS bigint) = 0 OR CAST(value_in_use AS bigint) < 5))\\n    OR (name = 'query governor cost limit' AND CAST(value_in_use AS bigint) > 0 AND CAST(value_in_use AS bigint) < 10)\\n    OR (name = 'query wait (s)' AND CAST(value_in_use AS bigint) != -1 AND CAST(value_in_use AS bigint) < 5)\\n  )"}	{"condition": "row_count > 0", "description": "Query timeout or governor settings at extreme values"}	null	2026-02-23 20:18:31.388927
166	sqlserver	query	Check authentication mode	{"sql": "SELECT SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  CASE WHEN SERVERPROPERTY('IsIntegratedSecurityOnly') = 0 THEN 'Mixed Mode (SQL + Windows)'\\n       ELSE 'Windows Authentication Only' END AS auth_mode"}	{"condition": "windows_auth_only = 0", "description": "SQL Server is in Mixed Mode — SQL authentication enabled"}	null	2026-02-23 20:18:31.388927
167	sqlserver	query	Check sa account status and policy enforcement	{"sql": "SELECT name, is_disabled, is_policy_checked, is_expiration_checked,\\n  create_date, modify_date,\\n  LOGINPROPERTY(name, 'DaysUntilExpiration') AS days_until_expiry,\\n  LOGINPROPERTY(name, 'BadPasswordCount') AS bad_password_count\\nFROM sys.sql_logins\\nWHERE name = 'sa'"}	{"condition": "is_disabled = 0 AND (is_policy_checked = 0 OR is_expiration_checked = 0)", "description": "sa account is enabled without password policy or expiration — insecure"}	null	2026-02-23 20:18:31.388928
183	sqlserver	query	Check SQL logins for disabled password policy	{"sql": "SELECT name, is_policy_checked, is_expiration_checked,\\n  is_disabled, create_date, modify_date,\\n  LOGINPROPERTY(name, 'DaysUntilExpiration') AS days_until_expiry\\nFROM sys.sql_logins\\nWHERE (is_policy_checked = 0 OR is_expiration_checked = 0)\\n  AND is_disabled = 0\\nORDER BY name"}	{"condition": "row_count > 0", "description": "Active SQL logins with password policy or expiration disabled"}	null	2026-02-23 20:18:31.388937
172	sqlserver	query	Check AG replica connection and synchronization state	{"sql": "SELECT ag.name AS ag_name, ar.replica_server_name,\\n  ars.connected_state_desc, ars.synchronization_health_desc,\\n  ars.last_connect_error_number, ars.last_connect_error_timestamp\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE ars.connected_state_desc = 'DISCONNECTED'\\n  OR ars.synchronization_health_desc != 'HEALTHY'"}	{"condition": "row_count > 0", "description": "AG replicas disconnected or unhealthy — may have missed configuration changes"}	null	2026-02-23 20:18:31.388931
174	sqlserver	query	Check AG database synchronization state after rejoin	{"sql": "SELECT ag.name AS ag_name, ar.replica_server_name,\\n  drs.database_id, DB_NAME(drs.database_id) AS database_name,\\n  drs.synchronization_state_desc, drs.synchronization_health_desc,\\n  drs.log_send_queue_size AS send_queue_kb,\\n  drs.redo_queue_size AS redo_queue_kb,\\n  drs.last_commit_time, drs.is_suspended,\\n  drs.suspend_reason_desc\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.is_local = 1\\n  AND (drs.synchronization_state_desc IN ('NOT SYNCHRONIZING', 'INITIALIZING')\\n    OR drs.is_suspended = 1\\n    OR drs.redo_queue_size > :max_redo_queue_kb)"}	{"condition": "row_count > 0", "description": "AG databases not synchronizing, suspended, or with large redo queues — stale state after rejoin"}	{"max_redo_queue_kb": 1048576}	2026-02-23 20:18:31.388932
180	sqlserver	query	Check TDE status for all databases	{"sql": "SELECT d.name, dek.encryption_state,\\n  CASE dek.encryption_state\\n    WHEN 0 THEN 'No encryption key'\\n    WHEN 1 THEN 'Unencrypted'\\n    WHEN 2 THEN 'Encryption in progress'\\n    WHEN 3 THEN 'Encrypted'\\n    WHEN 4 THEN 'Key change in progress'\\n    WHEN 5 THEN 'Decryption in progress'\\n  END AS state_desc\\nFROM sys.databases d\\nLEFT JOIN sys.dm_database_encryption_keys dek ON d.database_id = dek.database_id\\nWHERE d.database_id > 4\\n  AND (dek.encryption_state IS NULL OR dek.encryption_state != 3)"}	{"condition": "row_count > 0", "description": "User databases without TDE encryption"}	null	2026-02-23 20:18:31.388935
184	sqlserver	query	Check for non-admin users with security-sensitive permissions	{"sql": "SELECT pr.name AS principal_name, pr.type_desc,\\n  pe.permission_name, pe.state_desc\\nFROM sys.server_permissions pe\\nJOIN sys.server_principals pr ON pe.grantee_principal_id = pr.principal_id\\nWHERE pe.permission_name IN ('ALTER ANY LOGIN', 'ALTER ANY SERVER ROLE',\\n  'CONTROL SERVER', 'ALTER ANY CREDENTIAL', 'ALTER ANY LINKED SERVER')\\n  AND pe.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n  AND pr.name NOT IN ('sa', 'BUILTIN\\\\Administrators')\\n  AND pr.type_desc != 'SERVER_ROLE'"}	{"condition": "row_count > 0", "description": "Non-admin users have security-sensitive server permissions"}	null	2026-02-23 20:18:31.388938
188	sqlserver	query	Check for databases with decryption in progress or unencrypted	{"sql": "SELECT d.name, dek.encryption_state,\\n  CASE dek.encryption_state\\n    WHEN 1 THEN 'Unencrypted (key exists but not encrypting)'\\n    WHEN 5 THEN 'Decryption in progress'\\n    WHEN 6 THEN 'Protection change in progress'\\n  END AS state_desc,\\n  dek.encryptor_type, c.name AS cert_name\\nFROM sys.dm_database_encryption_keys dek\\nJOIN sys.databases d ON dek.database_id = d.database_id\\nLEFT JOIN sys.certificates c ON dek.encryptor_thumbprint = c.thumbprint\\nWHERE dek.encryption_state IN (1, 5, 6)"}	{"condition": "row_count > 0", "description": "Databases with encryption keys but not actively encrypted — TDE was disabled"}	null	2026-02-23 20:18:31.38894
190	sqlserver	query	Check for broad UNMASK permission grants	{"sql": "SELECT pr.name AS principal_name, pe.permission_name, pe.state_desc\\nFROM sys.database_permissions pe\\nJOIN sys.database_principals pr ON pe.grantee_principal_id = pr.principal_id\\nWHERE pe.permission_name = 'UNMASK'\\n  AND pe.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')"}	{"condition": "row_count > 0", "description": "UNMASK permission granted — users can see unmasked data despite masking rules"}	null	2026-02-23 20:18:31.388941
196	sqlserver	query	Check linked server security configuration	{"sql": "SELECT ls.name AS linked_server, ls.data_source, ls.provider,\\n  ll.uses_self_credential, ll.remote_name\\nFROM sys.servers ls\\nLEFT JOIN sys.linked_logins ll ON ls.server_id = ll.server_id\\nWHERE ls.is_linked = 1\\n  AND (ll.uses_self_credential = 0 OR ll.remote_name IS NOT NULL)"}	{"condition": "row_count > 0", "description": "Linked servers configured with explicit credentials (mapped logins) — verify security"}	null	2026-02-23 20:18:31.388945
197	sqlserver	query	Check for direct user permissions bypassing roles	{"sql": "SELECT pr.name AS principal_name, pr.type_desc,\\n  pe.permission_name, pe.state_desc,\\n  OBJECT_SCHEMA_NAME(pe.major_id) AS schema_name,\\n  OBJECT_NAME(pe.major_id) AS object_name\\nFROM sys.database_permissions pe\\nJOIN sys.database_principals pr ON pe.grantee_principal_id = pr.principal_id\\nWHERE pr.type_desc IN ('SQL_USER', 'WINDOWS_USER', 'WINDOWS_GROUP')\\n  AND pe.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n  AND pe.class_desc = 'OBJECT_OR_COLUMN'\\n  AND pr.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys')\\nORDER BY pr.name, pe.permission_name"}	{"condition": "row_count > :max_direct_grants", "description": "Many direct user-to-object grants found — RBAC may have been bypassed"}	{"max_direct_grants": 50}	2026-02-23 20:18:31.388946
198	sqlserver	query	Find recently created sysadmin logins	{"sql": "SELECT p.name AS login_name, p.type_desc, p.create_date, p.modify_date,\\n  p.is_disabled, p.default_database_name\\nFROM sys.server_principals p\\nJOIN sys.server_role_members rm ON p.principal_id = rm.member_principal_id\\nWHERE rm.role_principal_id = SUSER_ID('sysadmin')\\n  AND p.create_date > DATEADD(day, -90, GETDATE())\\n  AND p.name NOT IN ('sa')\\nORDER BY p.create_date DESC"}	{"condition": "row_count > 0", "description": "New sysadmin logins created in last 90 days — verify authorization"}	null	2026-02-23 20:18:31.388946
199	sqlserver	query	Check default trace for login creation events	{"sql": "SELECT te.name AS event_name, t.LoginName AS created_by,\\n  t.TargetLoginName AS new_login, t.StartTime, t.TextData\\nFROM sys.fn_trace_gettable(\\n  (SELECT REVERSE(SUBSTRING(REVERSE(path), CHARINDEX('\\\\', REVERSE(path)), 260)) + 'log.trc'\\n   FROM sys.traces WHERE is_default = 1), DEFAULT) t\\nJOIN sys.trace_events te ON t.EventClass = te.trace_event_id\\nWHERE te.name IN ('Audit Add Login Event', 'Audit Add Member to Server Role Event')\\n  AND t.StartTime > DATEADD(day, -90, GETDATE())\\nORDER BY t.StartTime DESC"}	{"condition": "row_count > 0", "description": "Default trace shows login creation and role membership changes — audit trail"}	null	2026-02-23 20:18:31.388947
201	sqlserver	query	Check sa and built-in account status	{"sql": "SELECT name, principal_id, is_disabled, is_policy_checked,\\n  is_expiration_checked, create_date, modify_date,\\n  LOGINPROPERTY(name, 'PasswordLastSetTime') AS password_last_set,\\n  LOGINPROPERTY(name, 'BadPasswordCount') AS bad_password_count\\nFROM sys.sql_logins\\nWHERE name IN ('sa', '##MS_PolicyEventProcessingLogin##', '##MS_PolicyTsqlExecutionLogin##')\\n  AND is_disabled = 0"}	{"condition": "sa is_disabled = 0", "description": "sa account is enabled — should be disabled in production per best practices"}	null	2026-02-23 20:18:31.388948
6006	postgresql	query	Check if pgcrypto extension is available for backup encryption	{"sql": "SELECT extname FROM pg_extension WHERE extname = 'pgcrypto'"}	{"condition": "row_count = 0", "description": "No pgcrypto means no native encryption tooling for backup workflows"}	\N	2026-02-25 00:28:52.405273
202	sqlserver	query	Count members in each server role	{"sql": "SELECT r.name AS role_name, COUNT(rm.member_principal_id) AS member_count\\nFROM sys.server_principals r\\nLEFT JOIN sys.server_role_members rm ON r.principal_id = rm.role_principal_id\\nWHERE r.type = 'R'\\nGROUP BY r.name\\nHAVING COUNT(rm.member_principal_id) > :max_members\\nORDER BY member_count DESC"}	{"condition": "sysadmin member_count > max_members", "description": "Too many members in high-privilege roles — sysadmin should have minimal membership"}	{"max_members": 5}	2026-02-23 20:18:31.388949
