203	sqlserver	query	Check for GRANT WITH GRANT OPTION on sensitive permissions	{"sql": "SELECT pr.name AS principal_name, pe.permission_name, pe.state_desc\\nFROM sys.server_permissions pe\\nJOIN sys.server_principals pr ON pe.grantee_principal_id = pr.principal_id\\nWHERE pe.state_desc = 'GRANT_WITH_GRANT_OPTION'\\n  AND pe.permission_name IN ('CONTROL SERVER', 'ALTER ANY LOGIN',\\n    'ALTER ANY SERVER ROLE', 'ALTER ANY DATABASE', 'ALTER ANY CREDENTIAL',\\n    'ADMINISTER BULK OPERATIONS', 'ALTER TRACE')\\n  AND pr.name NOT IN ('sa')\\nORDER BY pr.name"}	{"condition": "row_count > 0", "description": "Users have WITH GRANT OPTION on powerful permissions — can delegate privileges"}	null	2026-02-23 20:18:31.38895
204	sqlserver	query	Trace nested role membership for database-level roles	{"sql": "WITH role_tree AS (\\n  SELECT rm.member_principal_id, rm.role_principal_id, 1 AS depth,\\n    CAST(dp.name AS nvarchar(max)) AS chain\\n  FROM sys.database_role_members rm\\n  JOIN sys.database_principals dp ON rm.role_principal_id = dp.principal_id\\n  UNION ALL\\n  SELECT rt.member_principal_id, rm2.role_principal_id, rt.depth + 1,\\n    rt.chain + ' -> ' + dp2.name\\n  FROM role_tree rt\\n  JOIN sys.database_role_members rm2 ON rt.role_principal_id = rm2.member_principal_id\\n  JOIN sys.database_principals dp2 ON rm2.role_principal_id = dp2.principal_id\\n  WHERE rt.depth < 5\\n)\\nSELECT u.name AS user_name, r.name AS effective_role, rt.chain, rt.depth\\nFROM role_tree rt\\nJOIN sys.database_principals u ON rt.member_principal_id = u.principal_id\\nJOIN sys.database_principals r ON rt.role_principal_id = r.principal_id\\nWHERE r.name IN ('db_owner', 'db_securityadmin', 'db_accessadmin')\\n  AND rt.depth > 1\\nORDER BY rt.depth DESC"}	{"condition": "row_count > 0", "description": "Users have elevated database roles through nested role chains"}	null	2026-02-23 20:18:31.38895
205	sqlserver	query	Check service accounts in sysadmin role	{"sql": "SELECT p.name AS login_name, p.type_desc, p.create_date,\\n  r.name AS role_name\\nFROM sys.server_principals p\\nJOIN sys.server_role_members rm ON p.principal_id = rm.member_principal_id\\nJOIN sys.server_principals r ON rm.role_principal_id = r.principal_id\\nWHERE r.name = 'sysadmin'\\n  AND (p.name LIKE '%svc%' OR p.name LIKE '%service%' OR p.name LIKE '%app%'\\n    OR p.name LIKE '%agent%' OR p.name LIKE '%monitor%' OR p.name LIKE '%backup%')\\nORDER BY p.name"}	{"condition": "row_count > 0", "description": "Service/application accounts with sysadmin — likely over-privileged"}	null	2026-02-23 20:18:31.388951
206	sqlserver	query	Check database ownership	{"sql": "SELECT d.name AS database_name, SUSER_SNAME(d.owner_sid) AS owner_login,\\n  p.type_desc AS owner_type\\nFROM sys.databases d\\nJOIN sys.server_principals p ON d.owner_sid = p.sid\\nWHERE d.database_id > 4\\n  AND p.name NOT IN ('sa')\\n  AND p.type_desc NOT LIKE '%SERVICE%'\\nORDER BY d.name"}	{"condition": "row_count > 0", "description": "Databases owned by non-sa, non-service accounts — owners have implicit db_owner"}	null	2026-02-23 20:18:31.388952
207	sqlserver	query	Check for non-dbo schema ownership	{"sql": "SELECT s.name AS schema_name,\\n  dp.name AS owner_name, dp.type_desc\\nFROM sys.schemas s\\nJOIN sys.database_principals dp ON s.principal_id = dp.principal_id\\nWHERE dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'db_owner')\\nORDER BY s.name"}	{"condition": "row_count > 0", "description": "Schemas owned by specific users — owners have full control over schema objects"}	null	2026-02-23 20:18:31.388953
208	sqlserver	query	Check for triggers with EXECUTE AS clause	{"sql": "SELECT OBJECT_SCHEMA_NAME(t.parent_id) AS schema_name,\\n  OBJECT_NAME(t.parent_id) AS table_name,\\n  t.name AS trigger_name, t.type_desc,\\n  sm.execute_as_principal_id,\\n  dp.name AS execute_as_user\\nFROM sys.triggers t\\nJOIN sys.sql_modules sm ON t.object_id = sm.object_id\\nLEFT JOIN sys.database_principals dp ON sm.execute_as_principal_id = dp.principal_id\\nWHERE sm.execute_as_principal_id IS NOT NULL\\n  AND sm.execute_as_principal_id != 0"}	{"condition": "row_count > 0", "description": "Triggers with EXECUTE AS found — could allow non-privileged users to perform elevated operations"}	null	2026-02-23 20:18:31.388953
209	sqlserver	query	Check for procedures with EXECUTE AS owner or elevated user	{"sql": "SELECT OBJECT_SCHEMA_NAME(p.object_id) AS schema_name,\\n  p.name AS proc_name,\\n  sm.execute_as_principal_id,\\n  dp.name AS execute_as_user,\\n  dp.type_desc AS execute_as_type\\nFROM sys.procedures p\\nJOIN sys.sql_modules sm ON p.object_id = sm.object_id\\nLEFT JOIN sys.database_principals dp ON sm.execute_as_principal_id = dp.principal_id\\nWHERE sm.execute_as_principal_id IS NOT NULL\\n  AND sm.execute_as_principal_id NOT IN (0, -2)\\nORDER BY schema_name, proc_name"}	{"condition": "row_count > 0", "description": "Procedures with EXECUTE AS elevation — review for privilege bypass risk"}	null	2026-02-23 20:18:31.388954
210	sqlserver	query	Check for views with broad SELECT grants on sensitive schemas	{"sql": "SELECT v.name AS view_name, SCHEMA_NAME(v.schema_id) AS schema_name,\\n  dp_grantee.name AS grantee, pe.permission_name\\nFROM sys.views v\\nJOIN sys.database_permissions pe ON v.object_id = pe.major_id\\nJOIN sys.database_principals dp_grantee ON pe.grantee_principal_id = dp_grantee.principal_id\\nWHERE pe.permission_name = 'SELECT'\\n  AND pe.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n  AND dp_grantee.name NOT IN ('dbo', 'public', 'db_datareader')\\n  AND SCHEMA_NAME(v.schema_id) NOT IN ('sys', 'INFORMATION_SCHEMA')\\nORDER BY v.name"}	{"condition": "row_count > 0", "description": "Views with explicit SELECT grants to specific users — verify data exposure"}	null	2026-02-23 20:18:31.388954
211	sqlserver	query	Check for synonyms referencing sensitive base objects	{"sql": "SELECT s.name AS synonym_name, SCHEMA_NAME(s.schema_id) AS synonym_schema,\\n  s.base_object_name,\\n  pe.permission_name, dp.name AS grantee\\nFROM sys.synonyms s\\nJOIN sys.database_permissions pe ON s.object_id = pe.major_id\\nJOIN sys.database_principals dp ON pe.grantee_principal_id = dp.principal_id\\nWHERE pe.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\nORDER BY s.name"}	{"condition": "row_count > 0", "description": "Synonyms with explicit permission grants — may bypass object-level security"}	null	2026-02-23 20:18:31.388955
212	sqlserver	query	Check for audit specification filters excluding users	{"sql": "SELECT sa.name AS audit_name, sas.name AS spec_name,\\n  sasd.audit_action_name, sasd.audited_principal_id,\\n  dp.name AS audited_principal\\nFROM sys.server_audits sa\\nJOIN sys.server_audit_specifications sas ON sa.audit_guid = sas.audit_guid\\nJOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\nLEFT JOIN sys.server_principals dp ON sasd.audited_principal_id = dp.principal_id\\nWHERE sasd.audited_principal_id != 0"}	{"condition": "row_count > 0", "description": "Audit specifications scoped to specific principals — some users may be excluded"}	null	2026-02-23 20:18:31.388956
213	sqlserver	query	Check for ALTER on server roles granted with grant option	{"sql": "SELECT pr.name AS principal_name, pe.permission_name,\\n  pe.state_desc, pe2.name AS target_role\\nFROM sys.server_permissions pe\\nJOIN sys.server_principals pr ON pe.grantee_principal_id = pr.principal_id\\nLEFT JOIN sys.server_principals pe2 ON pe.major_id = pe2.principal_id\\nWHERE pe.state_desc = 'GRANT_WITH_GRANT_OPTION'\\n  AND pe.permission_name = 'ALTER'\\n  AND pe2.type = 'R'\\n  AND pr.name NOT IN ('sa')\\nORDER BY pr.name"}	{"condition": "row_count > 0", "description": "Users can alter server roles and delegate — administrative privilege delegation"}	null	2026-02-23 20:18:31.388956
214	sqlserver	query	Check Windows group logins with sysadmin role	{"sql": "SELECT p.name AS login_name, p.type_desc,\\n  r.name AS role_name, p.is_disabled\\nFROM sys.server_principals p\\nJOIN sys.server_role_members rm ON p.principal_id = rm.member_principal_id\\nJOIN sys.server_principals r ON rm.role_principal_id = r.principal_id\\nWHERE r.name = 'sysadmin'\\n  AND p.type_desc = 'WINDOWS_GROUP'\\n  AND p.is_disabled = 0"}	{"condition": "row_count > 0", "description": "Windows groups with sysadmin — any AD member gets full SQL Server control"}	null	2026-02-23 20:18:31.388957
215	sqlserver	query	Check SQL Server service account details	{"sql": "SELECT servicename, service_account, startup_type_desc,\\n  status_desc, filename\\nFROM sys.dm_server_services"}	{"condition": "service_account = 'LocalSystem' OR service_account LIKE '%admin%'", "description": "SQL Server running as LocalSystem or admin account — OS escalation risk"}	null	2026-02-23 20:18:31.388958
216	sqlserver	query	Find privileged logins with no recent activity	{"sql": "SELECT p.name AS login_name, p.type_desc,\\n  r.name AS role_name, p.create_date, p.modify_date,\\n  MAX(s.login_time) AS last_login\\nFROM sys.server_principals p\\nJOIN sys.server_role_members rm ON p.principal_id = rm.member_principal_id\\nJOIN sys.server_principals r ON rm.role_principal_id = r.principal_id\\nLEFT JOIN sys.dm_exec_sessions s ON p.name = s.login_name\\nWHERE r.name IN ('sysadmin', 'securityadmin', 'serveradmin')\\n  AND p.is_disabled = 0\\n  AND p.name NOT IN ('sa', 'NT AUTHORITY\\\\SYSTEM')\\n  AND p.name NOT LIKE 'NT SERVICE%'\\nGROUP BY p.name, p.type_desc, r.name, p.create_date, p.modify_date\\nHAVING MAX(s.login_time) IS NULL OR MAX(s.login_time) < DATEADD(day, -90, GETDATE())"}	{"condition": "row_count > 0", "description": "Privileged logins with no activity in 90 days — likely stale, should be reviewed/disabled"}	null	2026-02-23 20:18:31.388958
217	sqlserver	query	Check default trace for recent role membership changes	{"sql": "SELECT te.name AS event_name, t.LoginName AS changed_by,\\n  t.TargetLoginName AS target_login,\\n  t.RoleName AS role_name, t.StartTime, t.TextData\\nFROM sys.fn_trace_gettable(\\n  (SELECT REVERSE(SUBSTRING(REVERSE(path), CHARINDEX('\\\\', REVERSE(path)), 260)) + 'log.trc'\\n   FROM sys.traces WHERE is_default = 1), DEFAULT) t\\nJOIN sys.trace_events te ON t.EventClass = te.trace_event_id\\nWHERE te.name = 'Audit Add Member to Server Role Event'\\n  AND t.StartTime > DATEADD(day, -90, GETDATE())\\nORDER BY t.StartTime DESC"}	{"condition": "row_count > 0", "description": "Recent role membership additions found — check if corresponding removals exist"}	null	2026-02-23 20:18:31.388959
218	sqlserver	query	Cross-check with removal events	{"sql": "SELECT te.name AS event_name, t.LoginName AS changed_by,\\n  t.TargetLoginName AS target_login,\\n  t.RoleName AS role_name, t.StartTime\\nFROM sys.fn_trace_gettable(\\n  (SELECT REVERSE(SUBSTRING(REVERSE(path), CHARINDEX('\\\\', REVERSE(path)), 260)) + 'log.trc'\\n   FROM sys.traces WHERE is_default = 1), DEFAULT) t\\nJOIN sys.trace_events te ON t.EventClass = te.trace_event_id\\nWHERE te.name = 'Audit Remove Member from Server Role Event'\\n  AND t.StartTime > DATEADD(day, -90, GETDATE())\\nORDER BY t.StartTime DESC"}	{"condition": "add_count > remove_count", "description": "More role additions than removals — temporary elevations likely not revoked"}	null	2026-02-23 20:18:31.388959
220	sqlserver	query	Check auto statistics settings for all databases	{"sql": "SELECT name, is_auto_update_stats_on, is_auto_create_stats_on,\\n  is_auto_update_stats_async_on\\nFROM sys.databases\\nWHERE database_id > 4 AND state_desc = 'ONLINE'\\n  AND (is_auto_update_stats_on = 0 OR is_auto_create_stats_on = 0)"}	{"condition": "row_count > 0", "description": "Databases with automatic statistics disabled — query plans may use stale stats"}	null	2026-02-23 20:18:31.388961
3508	postgresql	log_scan	Scan for cleanup script errors	{"pattern": "pg_archivecleanup.*error|could not remove.*WAL|backup.*retention.*error|pgbackrest.*expire.*error|barman.*delete.*error", "description": "Backup cleanup script errors"}	{"condition": "pattern_found", "description": "Backup cleanup script encountered errors"}	\N	2026-02-25 00:28:52.405273
222	sqlserver	query	Check unique index statistics freshness	{"sql": "SELECT OBJECT_SCHEMA_NAME(i.object_id) AS schema_name,\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, s.name AS stats_name,\\n  sp.last_updated, sp.rows, sp.modification_counter\\nFROM sys.indexes i\\nJOIN sys.stats s ON i.object_id = s.object_id AND i.index_id = s.stats_id\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE i.is_unique = 1\\n  AND sp.last_updated < DATEADD(day, -30, GETDATE())\\n  AND sp.modification_counter > 1000\\nORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0", "description": "Unique index statistics stale for >30 days with many modifications"}	null	2026-02-23 20:18:31.388962
223	sqlserver	query	Find tables with moderate modifications and stale statistics	{"sql": "SELECT OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name, sp.last_updated,\\n  sp.rows, sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(100.0 * sp.modification_counter / sp.rows AS decimal(5,1))\\n    ELSE 0 END AS pct_modified\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > :min_modifications\\n  AND sp.rows > 10000\\n  AND CAST(100.0 * sp.modification_counter / sp.rows AS decimal(5,1)) BETWEEN 5 AND 20\\nORDER BY pct_modified DESC"}	{"condition": "row_count > 0", "description": "Tables with 5-20% modifications — below auto-update but potentially stale enough to affect plans"}	{"min_modifications": 1000}	2026-02-23 20:18:31.388963
224	sqlserver	query	Check for long-running statistics operations	{"sql": "SELECT r.session_id, r.command, r.status,\\n  DATEDIFF(minute, r.start_time, GETDATE()) AS running_minutes,\\n  r.percent_complete, DB_NAME(r.database_id) AS database_name,\\n  SUBSTRING(qt.text, (r.statement_start_offset/2)+1,\\n    ((CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(qt.text)\\n      ELSE r.statement_end_offset END - r.statement_start_offset)/2)+1) AS current_statement\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) qt\\nWHERE r.command LIKE '%STATISTICS%'\\n  AND DATEDIFF(minute, r.start_time, GETDATE()) > :max_stats_minutes"}	{"condition": "row_count > 0", "description": "Statistics operations running longer than threshold"}	{"max_stats_minutes": 60}	2026-02-23 20:18:31.388963
4239	postgresql	query	Check connection utilization	{"sql": "SELECT count(*) AS current_connections, (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') AS max_connections, round(count(*)::numeric / (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') * 100, 2) AS utilization_pct FROM pg_stat_activity"}	{"condition": "utilization_pct > :threshold_pct", "description": "Connection pool near capacity; new job connections may be refused"}	{"threshold_pct": 90}	2026-02-25 00:28:52.405273
227	sqlserver	query	Check for statistics with no_recompute flag	{"sql": "SELECT OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name, s.no_recompute,\\n  sp.last_updated, sp.rows, sp.modification_counter\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.no_recompute = 1"}	{"condition": "row_count > 0", "description": "Statistics with NORECOMPUTE — will never auto-update regardless of modification count"}	null	2026-02-23 20:18:31.388965
228	sqlserver	query	Check for tables with bulk-loaded data and stale statistics	{"sql": "SELECT OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name, sp.last_updated,\\n  sp.rows, sp.modification_counter,\\n  p.rows AS actual_rows\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.partitions p ON s.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE sp.rows != p.rows\\n  AND ABS(p.rows - sp.rows) > :row_discrepancy_threshold\\nORDER BY ABS(p.rows - sp.rows) DESC"}	{"condition": "row_count > 0", "description": "Statistics row count differs significantly from actual — bulk load may have bypassed tracking"}	{"row_discrepancy_threshold": 10000}	2026-02-23 20:18:31.388966
229	sqlserver	query	Find tables with modification counters exceeding row count	{"sql": "SELECT OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name, sp.last_updated,\\n  sp.rows, sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(100.0 * sp.modification_counter / sp.rows AS decimal(10,1))\\n    ELSE 0 END AS pct_modified\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > sp.rows\\n  AND sp.rows > 1000\\nORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0", "description": "Tables modified more than 100% since last stats update — extremely volatile"}	null	2026-02-23 20:18:31.388967
230	sqlserver	query	Check for long-running transactions with version store impact	{"sql": "SELECT t.transaction_id, t.name AS transaction_name,\\n  s.session_id, s.login_name, s.program_name,\\n  DATEDIFF(minute, t.transaction_begin_time, GETDATE()) AS duration_minutes,\\n  t.transaction_type, t.transaction_state\\nFROM sys.dm_tran_active_transactions t\\nJOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_sessions s ON st.session_id = s.session_id\\nWHERE DATEDIFF(minute, t.transaction_begin_time, GETDATE()) > :min_duration_minutes\\nORDER BY t.transaction_begin_time ASC"}	{"condition": "row_count > 0", "description": "Long-running transactions prevent version store cleanup in tempdb"}	{"min_duration_minutes": 30}	2026-02-23 20:18:31.388967
6125	postgresql	query	Check for active replication connections	{"sql": "SELECT client_addr, application_name, state, sent_lsn FROM pg_stat_replication WHERE client_addr IS NOT NULL"}	{"condition": "row_count > 0", "description": "Active replication to external servers — outbound data flow"}	\N	2026-02-25 00:28:52.405273
232	sqlserver	query	Check for heavily modified tables with high fragmentation	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.avg_page_space_used_in_percent,\\n  ios.leaf_update_count + ios.leaf_delete_count AS modifications\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON ips.object_id = ios.object_id AND ips.index_id = ios.index_id\\nWHERE ips.avg_fragmentation_in_percent > :frag_threshold\\n  AND ips.page_count > 1000\\n  AND (ios.leaf_update_count + ios.leaf_delete_count) > :mod_threshold\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "row_count > 0", "description": "Tables with high fragmentation and high modification counts — bloat from UPDATE/DELETE"}	{"mod_threshold": 100000, "frag_threshold": 30}	2026-02-23 20:18:31.388968
241	sqlserver	query	Check page split counts across indexes	{"sql": "SELECT OBJECT_SCHEMA_NAME(ios.object_id) AS schema_name,\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_insert_count AS inserts,\\n  CASE WHEN ios.leaf_insert_count > 0\\n    THEN CAST(100.0 * ios.leaf_allocation_count / ios.leaf_insert_count AS decimal(5,1))\\n    ELSE 0 END AS split_pct,\\n  i.fill_factor\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nWHERE ios.leaf_allocation_count > :min_splits\\n  AND i.type_desc IN ('CLUSTERED', 'NONCLUSTERED')\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "split_pct > 10", "description": "More than 10% of inserts causing page splits — fillfactor may need adjustment"}	{"min_splits": 5000}	2026-02-23 20:18:31.388974
6321	oracle	query	ora_check_datafile_corruption_v_database_block_corruption	{"sql": "SELECT file#, block#, blocks, corruption_change#, corruption_type FROM v$database_block_corruption ORDER BY file#, block#"}	{"condition": "row_count > 0", "description": "Entries in v$database_block_corruption indicate known block corruption"}	\N	2026-02-28 12:19:19.580455
233	sqlserver	query	Check for tables with high insert+delete but low net row count	{"sql": "SELECT OBJECT_SCHEMA_NAME(ios.object_id) AS schema_name,\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  ios.leaf_insert_count, ios.leaf_delete_count,\\n  p.rows AS current_rows,\\n  ips.avg_fragmentation_in_percent, ips.page_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.partitions p ON ios.object_id = p.object_id AND ios.index_id = p.index_id\\nJOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\n  ON ios.object_id = ips.object_id AND ios.index_id = ips.index_id\\nWHERE ios.leaf_insert_count > :min_inserts\\n  AND ios.leaf_delete_count > :min_deletes\\n  AND p.rows < ios.leaf_insert_count * 0.1\\n  AND ips.page_count > 100\\nORDER BY ios.leaf_insert_count DESC"}	{"condition": "row_count > 0", "description": "Tables with massive insert+delete but few rows — queue/staging pattern causing fragmentation"}	{"min_deletes": 100000, "min_inserts": 100000}	2026-02-23 20:18:31.388969
4240	postgresql	query	Check job failure messages for connection errors	{"sql": "SELECT jobid, status, return_message FROM cron.job_run_details WHERE status = 'failed' AND return_message ~* '(connection refused|too many clients|FATAL|could not connect)' ORDER BY start_time DESC LIMIT 5"}	{"condition": "row_count > 0", "description": "Job failures from connection issues"}	\N	2026-02-25 00:28:52.405273
234	sqlserver	query	Check for indexes with low fillfactor and low page density	{"sql": "SELECT OBJECT_SCHEMA_NAME(i.object_id) AS schema_name,\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.fill_factor,\\n  ips.avg_page_space_used_in_percent, ips.page_count,\\n  ips.avg_fragmentation_in_percent\\nFROM sys.indexes i\\nJOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'DETAILED') ips\\n  ON i.object_id = ips.object_id AND i.index_id = ips.index_id\\nWHERE i.fill_factor > 0 AND i.fill_factor < :low_fillfactor\\n  AND ips.page_count > 100\\n  AND ips.index_level = 0\\nORDER BY i.fill_factor ASC"}	{"condition": "row_count > 0", "description": "Indexes with low fillfactor using more pages than needed"}	{"low_fillfactor": 70}	2026-02-23 20:18:31.38897
235	sqlserver	query	Check for high page split counts on non-sequential indexes	{"sql": "SELECT OBJECT_SCHEMA_NAME(ios.object_id) AS schema_name,\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.nonleaf_allocation_count AS nonleaf_splits,\\n  ios.leaf_insert_count,\\n  CASE WHEN ios.leaf_insert_count > 0\\n    THEN CAST(100.0 * ios.leaf_allocation_count / ios.leaf_insert_count AS decimal(5,1))\\n    ELSE 0 END AS split_pct,\\n  c.system_type_id\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nWHERE ios.leaf_allocation_count > :min_splits\\n  AND c.system_type_id = 36"}	{"condition": "row_count > 0", "description": "Indexes on UNIQUEIDENTIFIER columns with high page split rates"}	{"min_splits": 1000}	2026-02-23 20:18:31.38897
236	sqlserver	query	Check for indexes with high ghost record counts	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.ghost_record_count, ips.record_count,\\n  CASE WHEN ips.record_count > 0\\n    THEN CAST(100.0 * ips.ghost_record_count / (ips.record_count + ips.ghost_record_count) AS decimal(5,1))\\n    ELSE 0 END AS ghost_pct,\\n  ips.page_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'DETAILED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.ghost_record_count > :min_ghost_records\\n  AND ips.index_level = 0\\nORDER BY ips.ghost_record_count DESC"}	{"condition": "row_count > 0", "description": "Indexes with many ghost records — cleanup backlog causing bloat"}	{"min_ghost_records": 10000}	2026-02-23 20:18:31.388971
239	sqlserver	query	Check for recently altered tables with high fragmentation	{"sql": "SELECT OBJECT_SCHEMA_NAME(o.object_id) AS schema_name,\\n  o.name AS table_name, o.modify_date,\\n  ips.avg_fragmentation_in_percent, ips.page_count\\nFROM sys.objects o\\nJOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\n  ON o.object_id = ips.object_id AND ips.index_id IN (0, 1)\\nWHERE o.type = 'U'\\n  AND o.modify_date > DATEADD(day, -30, GETDATE())\\n  AND ips.avg_fragmentation_in_percent > :frag_threshold\\n  AND ips.page_count > 1000\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "row_count > 0", "description": "Recently modified tables with high fragmentation — schema changes likely caused fragmentation"}	{"frag_threshold": 30}	2026-02-23 20:18:31.388973
240	sqlserver	query	Check index fragmentation levels across all user tables	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count, ips.avg_page_space_used_in_percent,\\n  ips.fragment_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.avg_fragmentation_in_percent > :frag_threshold\\n  AND ips.page_count > :min_pages\\n  AND i.type_desc IN ('CLUSTERED', 'NONCLUSTERED')\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "row_count > 0", "description": "Indexes with fragmentation above threshold — DML operations causing page disorder"}	{"min_pages": 1000, "frag_threshold": 30}	2026-02-23 20:18:31.388973
259	sqlserver	query	Check maintenance job schedules for peak-hour conflicts	{"sql": "SELECT j.name, s.name AS schedule_name,\\n  s.active_start_time, s.active_end_time,\\n  s.freq_type, s.freq_interval\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules js ON j.job_id = js.job_id\\nJOIN msdb.dbo.sysschedules s ON js.schedule_id = s.schedule_id\\nWHERE (j.name LIKE '%maintenance%' OR j.name LIKE '%index%' OR j.name LIKE '%rebuild%'\\n  OR j.name LIKE '%integrity%' OR j.name LIKE '%DBCC%')\\n  AND j.enabled = 1 AND s.enabled = 1\\n  AND s.active_start_time BETWEEN :peak_start AND :peak_end"}	{"condition": "row_count > 0", "description": "Maintenance jobs scheduled during business hours"}	{"peak_end": 180000, "peak_start": 80000}	2026-02-23 20:18:31.388986
242	sqlserver	query	Check for 100% fillfactor indexes with high split rates	{"sql": "SELECT OBJECT_SCHEMA_NAME(i.object_id) AS schema_name,\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.fill_factor,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_insert_count + ios.leaf_update_count AS modifications\\nFROM sys.indexes i\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE (i.fill_factor = 0 OR i.fill_factor = 100)\\n  AND ios.leaf_allocation_count > :min_splits\\n  AND (ios.leaf_insert_count + ios.leaf_update_count) > 10000\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "row_count > 0", "description": "Indexes with 100% fillfactor and high split counts — need fillfactor reduction"}	{"min_splits": 5000}	2026-02-23 20:18:31.388975
243	sqlserver	query	Check for high update counts with page splits on variable-length columns	{"sql": "SELECT OBJECT_SCHEMA_NAME(ios.object_id) AS schema_name,\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name,\\n  ios.leaf_update_count AS updates,\\n  ios.leaf_allocation_count AS splits_from_updates,\\n  COUNT(c.column_id) AS varchar_column_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nJOIN sys.columns c ON ios.object_id = c.object_id\\nWHERE ios.leaf_update_count > :min_updates\\n  AND ios.leaf_allocation_count > :min_splits\\n  AND c.system_type_id IN (167, 231, 165)\\n  AND i.index_id IN (0, 1)\\nGROUP BY ios.object_id, i.name, ios.leaf_update_count, ios.leaf_allocation_count\\nHAVING COUNT(c.column_id) > 0\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "row_count > 0", "description": "Tables with VARCHAR columns, high update counts, and high split rates"}	{"min_splits": 5000, "min_updates": 50000}	2026-02-23 20:18:31.388975
244	sqlserver	query	Check for index maintenance jobs in SQL Agent	{"sql": "SELECT j.name, j.enabled, j.date_created,\\n  h.run_date AS last_run_date, h.run_status,\\n  CASE h.run_status WHEN 0 THEN 'Failed' WHEN 1 THEN 'Succeeded'\\n    WHEN 2 THEN 'Retry' WHEN 3 THEN 'Cancelled' END AS status_desc\\nFROM msdb.dbo.sysjobs j\\nLEFT JOIN (\\n  SELECT job_id, run_date, run_status,\\n    ROW_NUMBER() OVER (PARTITION BY job_id ORDER BY run_date DESC, run_time DESC) AS rn\\n  FROM msdb.dbo.sysjobhistory WHERE step_id = 0\\n) h ON j.job_id = h.job_id AND h.rn = 1\\nWHERE j.name LIKE '%index%' OR j.name LIKE '%rebuild%'\\n  OR j.name LIKE '%reorganize%' OR j.name LIKE '%maintenance%'\\n  OR j.name LIKE '%defrag%'"}	{"condition": "row_count = 0 OR enabled = 0 OR run_status = 0", "description": "No index maintenance jobs, or they are disabled/failing"}	null	2026-02-23 20:18:31.388976
3265	sqlserver	query	Verify xprocs are accessible and unmonitored	{"sql": "SELECT c.name AS config_name,\\n  CAST(c.value_in_use AS INT) AS is_enabled\\nFROM sys.configurations c\\nWHERE c.name IN ('xp_cmdshell', 'Ole Automation Procedures')\\n  AND CAST(c.value_in_use AS INT) = 1"}	{"condition": "row_count > 0", "description": "Dangerous xproc features enabled with no monitoring — enforcement gap confirmed"}	null	2026-02-23 20:18:31.388977
246	sqlserver	query	Check clustered index fragmentation specifically	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS clustered_index,\\n  ips.avg_fragmentation_in_percent, ips.page_count,\\n  ips.avg_page_space_used_in_percent,\\n  (SELECT COUNT(*) FROM sys.indexes i2\\n   WHERE i2.object_id = ips.object_id AND i2.type_desc = 'NONCLUSTERED') AS nc_index_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE i.type_desc = 'CLUSTERED'\\n  AND ips.avg_fragmentation_in_percent > :frag_threshold\\n  AND ips.page_count > :min_pages\\nORDER BY ips.page_count * ips.avg_fragmentation_in_percent DESC"}	{"condition": "row_count > 0", "description": "Fragmented clustered indexes — all table access and NC index lookups are affected"}	{"min_pages": 1000, "frag_threshold": 30}	2026-02-23 20:18:31.388978
247	sqlserver	query	Check for indexes with low page density	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ips.avg_page_space_used_in_percent, ips.page_count,\\n  ips.avg_fragmentation_in_percent\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'DETAILED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.avg_page_space_used_in_percent < :density_threshold\\n  AND ips.page_count > :min_pages\\n  AND ips.index_level = 0\\nORDER BY ips.page_count DESC"}	{"condition": "row_count > 0", "description": "Indexes with low page density — each page is only partially filled"}	{"min_pages": 1000, "density_threshold": 60}	2026-02-23 20:18:31.388978
248	sqlserver	query	Check for indexes with high fragmentation and high insert counts	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent, ips.page_count,\\n  ios.leaf_insert_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON ips.object_id = ios.object_id AND ips.index_id = ios.index_id\\nWHERE ips.avg_fragmentation_in_percent > :frag_threshold\\n  AND ios.leaf_insert_count > :min_inserts\\n  AND ips.page_count > 1000\\nORDER BY ios.leaf_insert_count DESC"}	{"condition": "row_count > 0", "description": "Indexes with massive insert counts and high fragmentation — bulk load without index rebuild"}	{"min_inserts": 500000, "frag_threshold": 50}	2026-02-23 20:18:31.388979
260	sqlserver	query	Check for databases in restricted access modes	{"sql": "SELECT name, state_desc, user_access_desc, is_read_only\\nFROM sys.databases\\nWHERE database_id > 4\\n  AND (user_access_desc != 'MULTI_USER' OR state_desc != 'ONLINE' OR is_read_only = 1)"}	{"condition": "row_count > 0", "description": "Databases not in normal MULTI_USER/ONLINE mode — maintenance operations may fail"}	null	2026-02-23 20:18:31.388987
250	sqlserver	query	Check index depth and page distribution	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  MAX(ips.index_depth) AS max_depth,\\n  SUM(ips.page_count) AS total_pages,\\n  SUM(CASE WHEN ips.index_level = 0 THEN ips.page_count ELSE 0 END) AS leaf_pages,\\n  MAX(ips.avg_fragmentation_in_percent) AS max_frag\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'DETAILED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.page_count > 100\\nGROUP BY ips.object_id, i.name\\nHAVING MAX(ips.index_depth) > :max_depth\\nORDER BY MAX(ips.index_depth) DESC"}	{"condition": "max_depth > threshold", "description": "Unusually deep B-tree structure suggesting skewed data or poor key choice"}	{"max_depth": 4}	2026-02-23 20:18:31.38898
251	sqlserver	query	Check for indexes with low page density after deletes	{"sql": "SELECT OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_page_space_used_in_percent, ips.page_count,\\n  ios.leaf_delete_count,\\n  ios.leaf_ghost_count AS pending_ghost_cleanup\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'DETAILED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON ips.object_id = ios.object_id AND ips.index_id = ios.index_id\\nWHERE ips.avg_page_space_used_in_percent < :density_threshold\\n  AND ios.leaf_delete_count > :min_deletes\\n  AND ips.page_count > 1000\\n  AND ips.index_level = 0\\nORDER BY ios.leaf_delete_count DESC"}	{"condition": "row_count > 0", "description": "Indexes with low density and high delete counts — empty pages from mass deletions"}	{"min_deletes": 100000, "density_threshold": 50}	2026-02-23 20:18:31.388981
252	sqlserver	query	Check for NC indexes with very high update counts and fragmentation	{"sql": "SELECT OBJECT_SCHEMA_NAME(ios.object_id) AS schema_name,\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ios.leaf_update_count, ios.leaf_insert_count,\\n  ips.avg_fragmentation_in_percent, ips.page_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nJOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\n  ON ios.object_id = ips.object_id AND ios.index_id = ips.index_id\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND ios.leaf_update_count > :min_updates\\n  AND ips.avg_fragmentation_in_percent > :frag_threshold\\n  AND ips.page_count > 100\\nORDER BY ios.leaf_update_count DESC"}	{"condition": "row_count > 0", "description": "NC indexes with extremely high update counts and high fragmentation"}	{"min_updates": 500000, "frag_threshold": 50}	2026-02-23 20:18:31.388981
253	sqlserver	query	Check for maintenance jobs cancelled or failed by timeout	{"sql": "SELECT j.name, h.run_date, h.run_time, h.run_duration, h.run_status, h.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id\\nWHERE (j.name LIKE '%maintenance%' OR j.name LIKE '%index%' OR j.name LIKE '%rebuild%'\\n  OR j.name LIKE '%statistics%' OR j.name LIKE '%integrity%' OR j.name LIKE '%DBCC%')\\n  AND (h.run_status IN (0, 3) OR h.run_duration > :max_duration_hhmmss)\\n  AND h.step_id = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -14, GETDATE()), 112))\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "run_status IN (0, 3) OR run_duration > max_duration", "description": "Maintenance jobs failed, cancelled, or exceeded maximum duration"}	{"max_duration_hhmmss": 80000}	2026-02-23 20:18:31.388982
254	sqlserver	query	Check for permission-related maintenance job failures	{"sql": "SELECT j.name, h.run_date, h.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id\\nWHERE (j.name LIKE '%maintenance%' OR j.name LIKE '%backup%' OR j.name LIKE '%index%')\\n  AND h.run_status = 0\\n  AND (h.message LIKE '%permission%' OR h.message LIKE '%access denied%'\\n    OR h.message LIKE '%not have sufficient%' OR h.message LIKE '%credential%')\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -14, GETDATE()), 112))\\nORDER BY h.run_date DESC"}	{"condition": "row_count > 0", "description": "Maintenance jobs failing with permission errors"}	null	2026-02-23 20:18:31.388983
255	sqlserver	query	Check for file path failures in maintenance jobs	{"sql": "SELECT j.name, h.run_date, h.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id\\nWHERE (j.name LIKE '%maintenance%' OR j.name LIKE '%backup%' OR j.name LIKE '%cleanup%')\\n  AND h.run_status = 0\\n  AND (h.message LIKE '%cannot open%' OR h.message LIKE '%path%not%found%'\\n    OR h.message LIKE '%operating system error 3%' OR h.message LIKE '%network%'\\n    OR h.message LIKE '%UNC%' OR h.message LIKE '%xp_create_subdir%')\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -14, GETDATE()), 112))\\nORDER BY h.run_date DESC"}	{"condition": "row_count > 0", "description": "Maintenance jobs failing with file/network path errors"}	null	2026-02-23 20:18:31.388983
256	sqlserver	query	Check for blocked maintenance operations	{"sql": "SELECT r.session_id, r.command, r.status, r.wait_type, r.wait_time,\\n  r.blocking_session_id, r.percent_complete,\\n  DATEDIFF(minute, r.start_time, GETDATE()) AS running_min\\nFROM sys.dm_exec_requests r\\nWHERE r.command IN ('DBCC', 'ALTER INDEX', 'UPDATE STATISTICS',\\n  'BACKUP DATABASE', 'BACKUP LOG', 'DbccFilesCompact')\\n  AND r.blocking_session_id > 0"}	{"condition": "row_count > 0", "description": "Maintenance operations currently blocked by user sessions"}	null	2026-02-23 20:18:31.388984
258	sqlserver	query	Check for currently running maintenance jobs	{"sql": "SELECT ja.job_id, j.name, ja.start_execution_date,\\n  DATEDIFF(minute, ja.start_execution_date, GETDATE()) AS running_min\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.start_execution_date IS NOT NULL\\n  AND ja.stop_execution_date IS NULL\\n  AND (j.name LIKE '%maintenance%' OR j.name LIKE '%index%' OR j.name LIKE '%backup%'\\n    OR j.name LIKE '%statistics%' OR j.name LIKE '%integrity%' OR j.name LIKE '%rebuild%')\\n  AND ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)"}	{"condition": "row_count > 1", "description": "Multiple maintenance jobs running simultaneously — resource contention"}	null	2026-02-23 20:18:31.388985
262	sqlserver	query	Check job owner account validity	{"sql": "SELECT j.name AS job_name, SUSER_SNAME(j.owner_sid) AS owner_login,\\n  p.is_disabled AS owner_disabled, p.type_desc\\nFROM msdb.dbo.sysjobs j\\nLEFT JOIN sys.server_principals p ON j.owner_sid = p.sid\\nWHERE (j.name LIKE '%maintenance%' OR j.name LIKE '%backup%' OR j.name LIKE '%index%')\\n  AND (p.sid IS NULL OR p.is_disabled = 1)"}	{"condition": "row_count > 0", "description": "Maintenance jobs owned by disabled or deleted accounts"}	null	2026-02-23 20:18:31.388988
263	sqlserver	query	Check for backup device failures in maintenance jobs	{"sql": "SELECT j.name, h.run_date, h.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id\\nWHERE j.name LIKE '%maintenance%'\\n  AND h.run_status = 0\\n  AND (h.message LIKE '%backup device%' OR h.message LIKE '%media%' OR h.message LIKE '%tape%'\\n    OR h.message LIKE '%operating system error%')\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -14, GETDATE()), 112))\\nORDER BY h.run_date DESC"}	{"condition": "row_count > 0", "description": "Maintenance plan backup steps failing with device/media errors"}	null	2026-02-23 20:18:31.388989
265	sqlserver	query	Check AG transport statistics for network performance	{"sql": "SELECT ag.name AS ag_name, ar.replica_server_name,\\n  drs.log_send_queue_size AS pending_send_kb,\\n  drs.log_send_rate AS send_rate_kb_sec,\\n  drs.redo_queue_size AS pending_redo_kb,\\n  drs.redo_rate AS redo_rate_kb_sec,\\n  CASE WHEN drs.log_send_rate > 0\\n    THEN drs.log_send_queue_size / drs.log_send_rate\\n    ELSE 999999 END AS est_send_catchup_sec\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.is_local = 1 AND drs.is_primary_replica = 0\\n  AND drs.log_send_queue_size > :send_queue_threshold_kb"}	{"condition": "est_send_catchup_sec > 60", "description": "Send queue building faster than drain rate — network bottleneck"}	{"send_queue_threshold_kb": 10240}	2026-02-23 20:18:31.38899
266	sqlserver	query	Check AG replica connection errors	{"sql": "SELECT ag.name AS ag_name, ar.replica_server_name,\\n  ars.connected_state_desc, ars.last_connect_error_number,\\n  ars.last_connect_error_description, ars.last_connect_error_timestamp\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE ars.last_connect_error_number IS NOT NULL\\n  AND ars.last_connect_error_timestamp > DATEADD(day, -7, GETDATE())"}	{"condition": "row_count > 0", "description": "Recent AG connection errors — intermittent network issues"}	null	2026-02-23 20:18:31.388991
267	sqlserver	query	Check redo queue growth with I/O correlation	{"sql": "SELECT ag.name AS ag_name, ar.replica_server_name,\\n  drs.redo_queue_size AS redo_queue_kb,\\n  drs.redo_rate AS redo_rate_kb_sec,\\n  drs.log_send_queue_size AS send_queue_kb,\\n  CASE WHEN drs.redo_rate > 0\\n    THEN drs.redo_queue_size / drs.redo_rate\\n    ELSE 999999 END AS est_redo_catchup_sec\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.is_local = 1 AND drs.is_primary_replica = 0\\n  AND drs.redo_queue_size > :redo_queue_threshold_kb\\n  AND drs.log_send_queue_size < :send_queue_threshold_kb"}	{"condition": "redo_queue high but send_queue low", "description": "Data arrives but can't be applied fast enough — secondary I/O bottleneck"}	{"redo_queue_threshold_kb": 51200, "send_queue_threshold_kb": 1024}	2026-02-23 20:18:31.388992
3266	sqlserver	query	Check if dangerous xprocs are enabled	{"sql": "SELECT c.name AS config_name,\\n  CAST(c.value_in_use AS INT) AS is_enabled\\nFROM sys.configurations c\\nWHERE c.name IN ('xp_cmdshell', 'Ole Automation Procedures')\\n  AND CAST(c.value_in_use AS INT) = 1"}	{"condition": "row_count > 0", "description": "Dangerous extended stored procedure features are enabled"}	null	2026-02-23 20:18:31.388993
3267	sqlserver	query	Check for connections from non-RFC1918 IP addresses	{"sql": "SELECT DISTINCT c.client_net_address,\\n  s.login_name, s.program_name,\\n  c.auth_scheme\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND c.client_net_address IS NOT NULL\\n  AND c.client_net_address <> '<local machine>'\\n  AND c.client_net_address NOT LIKE '10.%'\\n  AND c.client_net_address NOT LIKE '172.1[6-9].%'\\n  AND c.client_net_address NOT LIKE '172.2[0-9].%'\\n  AND c.client_net_address NOT LIKE '172.3[0-1].%'\\n  AND c.client_net_address NOT LIKE '192.168.%'\\n  AND c.client_net_address NOT LIKE '127.%'\\n  AND c.client_net_address NOT LIKE 'fe80:%'\\n  AND c.client_net_address NOT LIKE '::1'"}	{"condition": "row_count > 0", "description": "Non-private IP connections detected — instance is network-accessible beyond private network with xprocs enabled"}	null	2026-02-23 20:18:31.388994
3268	sqlserver	query	Check for dangerous xprocs enabled without audit trail	{"sql": "SELECT c.name AS feature,\\n  CAST(c.value_in_use AS INT) AS is_enabled,\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications\\n    WHERE is_state_enabled = 1) AS active_audit_specs\\nFROM sys.configurations c\\nWHERE c.name IN ('xp_cmdshell', 'Ole Automation Procedures')\\n  AND CAST(c.value_in_use AS INT) = 1"}	{"condition": "row_count > 0 AND (active_audits = 0 OR active_audit_specs = 0)", "description": "Dangerous features enabled without active auditing — fails compliance requirements for compensating controls"}	null	2026-02-23 20:18:31.388994
4241	postgresql	query	Check job failures for disk space errors	{"sql": "SELECT jobid, command, return_message FROM cron.job_run_details WHERE status = 'failed' AND return_message ~* '(no space left|disk full|could not write|temporary file)' ORDER BY start_time DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Jobs failing due to disk space exhaustion"}	\N	2026-02-25 00:28:52.405273
3269	sqlserver	query	Check CIS benchmark compliance indicators for xproc hardening	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n    WHERE name = 'xp_cmdshell') AS xp_cmdshell_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n    WHERE name = 'Ole Automation Procedures') AS ole_auto_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n    WHERE name = 'clr enabled') AS clr_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n    WHERE name = 'external scripts enabled') AS external_scripts_enabled,\\n  (SELECT COUNT(*) FROM master.sys.credentials\\n    WHERE name = '##xp_cmdshell_proxy_account##') AS xp_proxy_exists"}	{"condition": "xp_cmdshell_enabled = 1 OR ole_auto_enabled = 1 OR xp_proxy_exists > 0", "description": "CIS benchmark items failed — xp_cmdshell or OLE Automation should be disabled per all major compliance frameworks"}	null	2026-02-23 20:18:31.388995
3270	sqlserver	query	Check SQL Server service account privilege level	{"sql": "SELECT servicename, service_account, startup_type_desc,\\n  status_desc,\\n  CASE\\n    WHEN service_account LIKE '%LocalSystem%' THEN 'CRITICAL_OVERPRIVILEGED'\\n    WHEN service_account LIKE '%NetworkService%' THEN 'ELEVATED'\\n    WHEN service_account LIKE '%SYSTEM%' THEN 'CRITICAL_OVERPRIVILEGED'\\n    WHEN service_account LIKE '%Administrator%' THEN 'CRITICAL_OVERPRIVILEGED'\\n    WHEN service_account LIKE '%admin%' THEN 'HIGH_RISK'\\n    ELSE 'REVIEW_NEEDED'\\n  END AS privilege_assessment\\nFROM sys.dm_server_services"}	{"condition": "any row with privilege_assessment IN ('CRITICAL_OVERPRIVILEGED', 'ELEVATED', 'HIGH_RISK')", "description": "SQL Server service running under overprivileged account — xp_cmdshell commands execute with these elevated OS permissions"}	null	2026-02-23 20:18:31.388996
3271	sqlserver	query	Check if xp_cmdshell is enabled under overprivileged service account	{"sql": "SELECT\\n  (SELECT service_account FROM sys.dm_server_services\\n    WHERE servicename LIKE '%SQL Server%'\\n      AND servicename NOT LIKE '%Agent%'\\n      AND servicename NOT LIKE '%Launchpad%') AS sql_service_account,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n    WHERE name = 'xp_cmdshell') AS xp_cmdshell_enabled"}	{"condition": "xp_cmdshell_enabled = 1", "description": "xp_cmdshell enabled under overprivileged service account — OS commands run with excessive privileges"}	null	2026-02-23 20:18:31.388996
2299	sqlserver	query	Check optimizer-related configuration settings	{"sql": "SELECT name, value, value_in_use, minimum, maximum, description\\nFROM sys.configurations\\nWHERE name IN (\\n  'cost threshold for parallelism',\\n  'max degree of parallelism',\\n  'optimize for ad hoc workloads',\\n  'query governor cost limit'\\n)\\nORDER BY name"}	{"condition": "non-default values that may be suboptimal", "description": "Configuration parameters affecting optimizer cost decisions"}	null	2026-02-23 20:18:31.390289
1026	sqlserver	query	Check Query Store status across all user databases	{"sql": "SELECT d.name AS database_name,\\n  d.is_query_store_on,\\n  CASE WHEN d.is_query_store_on = 1 THEN 'Enabled'\\n    ELSE 'Disabled' END AS query_store_status\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "any database has is_query_store_on = 0", "description": "One or more user databases do not have Query Store enabled"}	null	2026-02-23 20:18:31.389005
3272	sqlserver	query	Check for third-party applications calling xprocs in plan cache	{"sql": "SELECT qt.text AS query_text,\\n  qs.execution_count,\\n  qs.last_execution_time,\\n  SUBSTRING(qt.text, 1, 200) AS query_preview\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) qt\\nWHERE (qt.text LIKE '%xp_cmdshell%' COLLATE Latin1_General_BIN\\n  OR qt.text LIKE '%xp_regread%' COLLATE Latin1_General_BIN\\n  OR qt.text LIKE '%xp_fileexist%' COLLATE Latin1_General_BIN\\n  OR qt.text LIKE '%xp_dirtree%' COLLATE Latin1_General_BIN\\n  OR qt.text LIKE '%xp_subdirs%' COLLATE Latin1_General_BIN\\n  OR qt.text LIKE '%xp_readerrorlog%' COLLATE Latin1_General_BIN\\n  OR qt.text LIKE '%xp_fixeddrives%' COLLATE Latin1_General_BIN)\\nORDER BY qs.execution_count DESC"}	{"condition": "row_count > 0", "description": "xproc calls found in plan cache — queries coming from applications"}	null	2026-02-23 20:18:31.388998
276	sqlserver	query	Check secondary replica read workload and redo queue	{"sql": "SELECT ar.replica_server_name,\\n  drs.redo_queue_size, drs.redo_rate,\\n  drs.log_send_queue_size,\\n  drs.synchronization_health_desc,\\n  drs.last_redone_time,\\n  DATEDIFF(SECOND, drs.last_redone_time, GETDATE()) AS redo_lag_seconds\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nWHERE drs.is_primary_replica = 0\\n  AND (drs.redo_queue_size > 1000 OR drs.redo_rate < 100)\\nORDER BY drs.redo_queue_size DESC"}	{"condition": "redo_queue_size > 1000 OR redo_rate < 100", "description": "Secondary replicas with growing redo queues or low redo rates indicating read workload interference"}	null	2026-02-23 20:18:31.388998
278	sqlserver	query	Check AG transport compression settings and CPU pressure	{"sql": "SELECT ar.replica_server_name,\\n  ar.availability_mode_desc,\\n  dme.endpoint_url,\\n  drs.log_send_queue_size, drs.log_send_rate,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Log Bytes Compressed/sec'\\n   AND instance_name <> '_Total') AS log_bytes_compressed_sec,\\n  (SELECT SUM(signal_wait_time_ms) * 100.0 / NULLIF(SUM(wait_time_ms), 0)\\n   FROM sys.dm_os_wait_stats) AS signal_wait_pct\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nJOIN sys.database_mirroring_endpoints dme ON 1=1\\nWHERE drs.is_primary_replica = 0"}	{"condition": "high signal_wait_pct (> 25%) with compression active", "description": "CPU contention coinciding with AG log compression indicating compression overhead"}	null	2026-02-23 20:18:31.389
