10853	mysql	config_check	Check group commit configuration	{"sql": "SELECT @@binlog_group_commit_sync_delay AS sync_delay_us, @@binlog_group_commit_sync_no_delay_count AS no_delay_count, @@binlog_order_commits AS order_commits"}	{"condition": "sync_delay_us = 0", "description": "Zero sync delay means no waiting to batch commits together"}	\N	2026-03-01 06:30:58.706791
280	sqlserver	query	Check AG health check configuration and recent failures	{"sql": "SELECT ag.name AS ag_name,\\n  ag.failure_condition_level,\\n  ag.health_check_timeout,\\n  ar.replica_server_name,\\n  ags.primary_replica,\\n  ags.synchronization_health_desc\\nFROM sys.availability_groups ag\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nJOIN sys.dm_hadr_availability_group_states ags ON ag.group_id = ags.group_id\\nWHERE ags.synchronization_health_desc <> 'HEALTHY'\\n  OR ag.health_check_timeout < 30000"}	{"condition": "synchronization_health <> HEALTHY or timeout < 30000", "description": "AG groups with unhealthy synchronization or aggressive health check timeouts"}	null	2026-02-23 20:18:31.389001
289	sqlserver	query	Check database file growth and volume space	{"sql": "SELECT vs.volume_mount_point,\\n  vs.total_bytes / 1073741824 AS total_gb,\\n  vs.available_bytes / 1073741824 AS available_gb,\\n  CAST(vs.available_bytes * 100.0 / NULLIF(vs.total_bytes, 0) AS decimal(5,1)) AS pct_free\\nFROM sys.master_files mf\\nCROSS APPLY sys.dm_os_volume_stats(mf.database_id, mf.file_id) vs\\nGROUP BY vs.volume_mount_point, vs.total_bytes, vs.available_bytes\\nHAVING vs.available_bytes * 100.0 / NULLIF(vs.total_bytes, 0) < 10\\nORDER BY pct_free"}	{"condition": "pct_free < 10", "description": "Volumes with less than 10% free space"}	null	2026-02-23 20:18:31.389006
291	sqlserver	query	Check AG endpoint state and replica connectivity	{"sql": "SELECT ep.name, ep.state_desc, ep.port, ep.ip_address,\\n  ep.is_encryption_enabled, ep.encryption_algorithm_desc,\\n  ar.replica_server_name, ar.endpoint_url,\\n  drs.connected_state_desc, drs.synchronization_state_desc\\nFROM sys.database_mirroring_endpoints ep\\nCROSS JOIN sys.availability_replicas ar\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nWHERE drs.connected_state_desc = 'DISCONNECTED'\\n  OR drs.synchronization_state_desc = 'NOT SYNCHRONIZING'\\n  OR ep.state_desc <> 'STARTED'"}	{"condition": "DISCONNECTED replicas or endpoint not STARTED", "description": "AG replicas disconnected or endpoint not running, suggesting firewall/security policy blocking"}	null	2026-02-23 20:18:31.389008
292	sqlserver	query	Check AG listener configuration and replica connectivity	{"sql": "SELECT l.dns_name, l.port, lip.ip_address, lip.state_desc AS ip_state,\\n  ar.replica_server_name, ar.endpoint_url,\\n  drs.connected_state_desc\\nFROM sys.availability_group_listeners l\\nJOIN sys.availability_group_listener_ip_addresses lip ON l.listener_id = lip.listener_id\\nCROSS JOIN sys.availability_replicas ar\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nWHERE lip.state_desc <> 'ONLINE'\\n  OR drs.connected_state_desc = 'DISCONNECTED'"}	{"condition": "listener IP not ONLINE or replicas DISCONNECTED", "description": "AG listener IPs offline or replicas disconnected, possibly due to DNS issues"}	null	2026-02-23 20:18:31.389009
293	sqlserver	query	Check AG endpoint certificates and authentication	{"sql": "SELECT ep.name AS endpoint_name, ep.state_desc,\\n  ep.connection_auth_desc, ep.certificate_id,\\n  c.name AS cert_name, c.expiry_date,\\n  CASE WHEN c.expiry_date < GETDATE() THEN 'EXPIRED'\\n    WHEN c.expiry_date < DATEADD(day, 30, GETDATE()) THEN 'EXPIRING_SOON'\\n    ELSE 'VALID' END AS cert_status,\\n  drs.connected_state_desc, ar.replica_server_name\\nFROM sys.database_mirroring_endpoints ep\\nLEFT JOIN sys.certificates c ON ep.certificate_id = c.certificate_id\\nCROSS JOIN sys.availability_replicas ar\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nWHERE c.expiry_date < DATEADD(day, 30, GETDATE())\\n  OR drs.connected_state_desc = 'DISCONNECTED'\\n  OR ep.state_desc <> 'STARTED'"}	{"condition": "expired certificates or disconnected replicas", "description": "AG endpoint certificates expired or nearing expiration, or replicas disconnected due to auth failure"}	null	2026-02-23 20:18:31.389009
4243	postgresql	query	Check for tables with excessive dead tuples	{"sql": "SELECT schemaname, relname, n_live_tup, n_dead_tup, CASE WHEN n_live_tup > 0 THEN round(n_dead_tup::numeric / n_live_tup * 100, 2) ELSE 0 END AS dead_pct, last_autovacuum, last_vacuum FROM pg_stat_user_tables WHERE n_dead_tup > :dead_threshold ORDER BY n_dead_tup DESC LIMIT 10"}	{"condition": "row_count > 0 AND dead_pct > :dead_pct_threshold", "description": "Tables with high dead tuple ratio causing bloat and slow queries in jobs"}	{"dead_threshold": 100000, "dead_pct_threshold": 20}	2026-02-25 00:28:52.405273
303	sqlserver	query	Check sp_server_diagnostics component states	{"sql": "SELECT ag.name, ag.failure_condition_level,\\n  ags.primary_replica, ags.synchronization_health_desc,\\n  (SELECT state_desc FROM sys.dm_server_services WHERE servicename LIKE '%SQL Server (%') AS sql_service_state,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'User Connections') AS user_connections,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec') AS batch_requests_sec\\nFROM sys.availability_groups ag\\nJOIN sys.dm_hadr_availability_group_states ags ON ag.group_id = ags.group_id"}	{"condition": "SQL service running and AG HEALTHY but batch_requests_sec very low or user_connections very low", "description": "Primary appears healthy to cluster but shows signs of being unresponsive to applications"}	null	2026-02-23 20:18:31.389016
2943	sqlserver	query	Check server-level cross-database ownership chaining	{"sql": "SELECT c.name AS config_name,\\n  c.value_in_use AS server_level_enabled\\nFROM sys.configurations c\\nWHERE c.name = 'cross db ownership chaining'"}	{"condition": "server_level_enabled = 1", "description": "Cross-database ownership chaining enabled at server level — affects ALL databases"}	null	2026-02-23 20:18:31.390684
4244	postgresql	query	Check for abnormal job terminations	{"sql": "SELECT jobid, command, status, return_message, start_time, end_time, (end_time - start_time) AS duration FROM cron.job_run_details WHERE status = 'failed' AND (return_message ~* '(terminated|killed|crash|signal|SIGKILL|SIGTERM|OOM)' OR return_message IS NULL) ORDER BY start_time DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Jobs terminated abnormally by signal or crash"}	\N	2026-02-25 00:28:52.405273
317	sqlserver	query	Check SQL Server listener and service state	{"sql": "SELECT\\n  (SELECT state_desc FROM sys.dm_server_services WHERE servicename LIKE '%SQL Server (%') AS sql_service_state,\\n  ep.state_desc AS endpoint_state, ep.port AS endpoint_port,\\n  l.dns_name, l.port AS listener_port,\\n  ags.synchronization_health_desc\\nFROM sys.database_mirroring_endpoints ep\\nCROSS JOIN sys.availability_group_listeners l\\nJOIN sys.dm_hadr_availability_group_states ags ON 1=1"}	{"condition": "service running but AG not HEALTHY or endpoint issues", "description": "TCP port responds (L4 check passes) but AG is not healthy (L7 check would fail)"}	null	2026-02-23 20:18:31.389026
4245	postgresql	query	Check job failures for external dependency errors	{"sql": "SELECT jobid, command, return_message FROM cron.job_run_details WHERE status = 'failed' AND return_message ~* '(could not connect|unreachable|timeout|file not found|mount|network|foreign|fdw)' ORDER BY start_time DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Job failures referencing external resources"}	\N	2026-02-25 00:28:52.405273
337	sqlserver	query	Check listener DNS and connectivity states	{"sql": "SELECT l.dns_name, l.port,\\n  lip.ip_address, lip.state_desc,\\n  ar.replica_server_name, ar.endpoint_url,\\n  drs.connected_state_desc\\nFROM sys.availability_group_listeners l\\nJOIN sys.availability_group_listener_ip_addresses lip ON l.listener_id = lip.listener_id\\nCROSS JOIN sys.availability_replicas ar\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nWHERE lip.state_desc <> 'ONLINE'\\n  OR drs.connected_state_desc = 'DISCONNECTED'"}	{"condition": "listener IPs not ONLINE or replicas DISCONNECTED", "description": "DNS-related connectivity failures affecting AG components"}	null	2026-02-23 20:18:31.389037
