356	sqlserver	query	Check log shipping restore status and secondary health	{"sql": "SELECT lss.secondary_database, lss.last_restored_file,\\n  lss.last_restored_date,\\n  DATEDIFF(MINUTE, lss.last_restored_date, GETDATE()) AS minutes_since_restore,\\n  lss.restore_threshold,\\n  (SELECT SUM(signal_wait_time_ms) * 100.0 / NULLIF(SUM(wait_time_ms), 0)\\n   FROM sys.dm_os_wait_stats) AS signal_wait_pct,\\n  (SELECT SUM(io_stall_read_ms + io_stall_write_ms) / NULLIF(SUM(num_of_reads + num_of_writes), 0)\\n   FROM sys.dm_io_virtual_file_stats(NULL, NULL)) AS avg_io_stall_ms,\\n  (SELECT process_memory_low_memory_resource_notification\\n   FROM sys.dm_os_process_memory) AS memory_pressure\\nFROM msdb.dbo.log_shipping_secondary_databases lss\\nWHERE DATEDIFF(MINUTE, lss.last_restored_date, GETDATE()) > lss.restore_threshold"}	{"condition": "restore behind threshold AND resource pressure indicators", "description": "Log shipping secondary falling behind due to CPU, I/O, or memory pressure"}	null	2026-02-23 20:18:31.38905
358	sqlserver	query	Check log shipping timestamps and local clock	{"sql": "SELECT lsd.primary_database,\\n  lsd.last_backup_date AS primary_last_backup,\\n  lss.last_restored_date AS secondary_last_restore,\\n  GETDATE() AS local_time,\\n  GETUTCDATE() AS utc_time,\\n  DATEDIFF(MINUTE, lsd.last_backup_date, GETDATE()) AS min_since_backup,\\n  lsd.backup_threshold\\nFROM msdb.dbo.log_shipping_primary_databases lsd\\nLEFT JOIN msdb.dbo.log_shipping_secondary_databases lss\\n  ON lsd.primary_database = lss.secondary_database"}	{"condition": "unexpected timestamp gaps or negative time deltas", "description": "Time discrepancies between primary and secondary suggesting clock skew"}	null	2026-02-23 20:18:31.389051
359	sqlserver	query	Check log shipping monitor configuration and alert history	{"sql": "SELECT lsd.primary_database,\\n  lsd.monitor_server,\\n  lsd.last_backup_date,\\n  lsd.backup_threshold,\\n  DATEDIFF(MINUTE, lsd.last_backup_date, GETDATE()) AS min_since_backup,\\n  CASE WHEN lsd.monitor_server IS NULL THEN 'NO_MONITOR'\\n    ELSE 'CONFIGURED' END AS monitor_status\\nFROM msdb.dbo.log_shipping_primary_databases lsd"}	{"condition": "monitor_server is NULL or alerts not firing despite threshold breach", "description": "Log shipping monitor not configured or unreachable"}	null	2026-02-23 20:18:31.389052
3496	postgresql	config_check	Check wal_level and archive settings	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('wal_level', 'archive_mode', 'archive_command', 'archive_library') ORDER BY name"}	{"condition": "wal_level = 'minimal' OR archive_mode = 'off'", "description": "WAL archiving is disabled — PITR impossible"}	\N	2026-02-25 00:28:52.405273
362	sqlserver	query	Check secondary database state and log shipping config	{"sql": "SELECT d.name, d.state_desc, d.is_in_standby,\\n  lss.restore_mode,\\n  lss.last_restored_file, lss.last_restored_date,\\n  DATEDIFF(MINUTE, lss.last_restored_date, GETDATE()) AS min_since_restore,\\n  lss.restore_threshold\\nFROM msdb.dbo.log_shipping_secondary_databases lss\\nJOIN sys.databases d ON lss.secondary_database = d.name\\nWHERE d.state_desc NOT IN ('ONLINE', 'RESTORING')\\n  OR DATEDIFF(MINUTE, lss.last_restored_date, GETDATE()) > lss.restore_threshold"}	{"condition": "database in unexpected state or restore behind threshold", "description": "Secondary database state or restore mode preventing timely restore"}	null	2026-02-23 20:18:31.389054
364	sqlserver	query	Check recovery model of log shipping primary databases	{"sql": "SELECT d.name, d.recovery_model_desc,\\n  lsd.backup_threshold, lsd.last_backup_date,\\n  DATEDIFF(MINUTE, lsd.last_backup_date, GETDATE()) AS min_since_backup\\nFROM msdb.dbo.log_shipping_primary_databases lsd\\nJOIN sys.databases d ON lsd.primary_database = d.name\\nWHERE d.recovery_model_desc = 'SIMPLE'"}	{"condition": "log shipping primary in SIMPLE recovery model", "description": "Primary database in SIMPLE mode — log backups impossible, log shipping broken"}	null	2026-02-23 20:18:31.389055
629	sqlserver	query	Check linked server connectivity to replication peers	{"sql": "SELECT s.name AS linked_server, s.data_source, s.product, s.provider, s.is_linked FROM sys.servers s WHERE s.is_linked = 1 AND s.name IN (SELECT DISTINCT subscriber_server_name FROM distribution.dbo.MSdistribution_agents UNION SELECT DISTINCT publisher FROM distribution.dbo.MSdistribution_agents)"}	{"condition": "linked servers configured for replication peers", "description": "Peer server connectivity configuration — if linked server connections fail, replication is partitioned"}	null	2026-02-23 20:18:31.389222
373	sqlserver	query	Check transactional replication articles and filters	{"sql": "SELECT p.name AS publication, a.name AS article,\\n  a.source_object, a.type, a.filter_clause,\\n  a.dest_table, a.status\\nFROM distribution.dbo.MSpublications p\\nJOIN distribution.dbo.MSarticles a ON p.publication_id = a.publication_id\\nWHERE a.filter_clause IS NOT NULL\\n  OR a.type <> 1\\nORDER BY p.name, a.name"}	{"condition": "articles with filters or non-standard types", "description": "Replication articles with row/column filters that may cause data conflicts"}	null	2026-02-23 20:18:31.389061
375	sqlserver	query	Check cluster quorum and member isolation state	{"sql": "SELECT c.quorum_state_desc,\\n  cm.member_name, cm.member_state_desc, cm.number_of_quorum_votes,\\n  ars.role_desc, ars.connected_state_desc\\nFROM sys.dm_hadr_cluster c\\nCROSS JOIN sys.dm_hadr_cluster_members cm\\nLEFT JOIN sys.dm_hadr_availability_replica_states ars\\n  ON cm.member_name = ars.replica_server_name\\nORDER BY cm.member_state_desc, cm.member_name"}	{"condition": "nodes not UP but still showing RESOLVING AG role", "description": "Failed node not properly isolated — may still believe it is primary"}	null	2026-02-23 20:18:31.389062
390	sqlserver	query	Check subscriber configurations and agent errors	{"sql": "SELECT s.name AS subscription_name,\\n  s.subscriber_id, s.subscriber_db,\\n  da.name AS agent_name, da.status,\\n  dh.comments AS last_error,\\n  dh.time AS last_activity\\nFROM distribution.dbo.MSsubscriptions s\\nJOIN distribution.dbo.MSdistribution_agents da ON s.agent_id = da.id\\nLEFT JOIN distribution.dbo.MSdistribution_history dh ON da.id = dh.agent_id\\n  AND dh.time = (SELECT MAX(dh2.time) FROM distribution.dbo.MSdistribution_history dh2\\n    WHERE dh2.agent_id = da.id)\\nWHERE da.status <> 1\\n  OR dh.error_id <> 0"}	{"condition": "agents not running or recent errors", "description": "Subscriber configuration issues preventing replication"}	null	2026-02-23 20:18:31.389072
