387	sqlserver	query	Check distribution agent status and subscriber connectivity	{"sql": "SELECT da.subscriber_db, da.publication,\\n  da.status, da.start_time, da.time,\\n  da.comments, da.delivered_commands, da.delivered_transactions,\\n  DATEDIFF(HOUR, da.time, GETDATE()) AS hours_since_activity\\nFROM distribution.dbo.MSdistribution_agents da\\nWHERE da.subscriber_db IS NOT NULL\\nORDER BY da.time"}	{"condition": "agents with status <> running or hours_since_activity > 4", "description": "Distribution agents inactive — subscribers disconnected or agents stopped"}	null	2026-02-23 20:18:31.38907
388	sqlserver	query	Check CDC capture and cleanup status	{"sql": "SELECT d.name AS database_name,\\n  ct.capture_instance, ct.object_id,\\n  ct.start_lsn, ct.create_date,\\n  j_capture.name AS capture_job, j_capture.enabled AS capture_enabled,\\n  j_cleanup.name AS cleanup_job, j_cleanup.enabled AS cleanup_enabled,\\n  (SELECT COUNT(*) FROM cdc.lsn_time_mapping) AS lsn_mappings\\nFROM sys.databases d\\nJOIN sys.change_tracking_tables ct ON 1=1\\nLEFT JOIN msdb.dbo.sysjobs j_capture ON j_capture.name LIKE 'cdc.' + d.name + '_capture'\\nLEFT JOIN msdb.dbo.sysjobs j_cleanup ON j_cleanup.name LIKE 'cdc.' + d.name + '_cleanup'\\nWHERE d.is_cdc_enabled = 1"}	{"condition": "CDC enabled but cleanup not keeping up (growing change tables)", "description": "CDC change tables accumulating because consumers are not reading changes"}	null	2026-02-23 20:18:31.389071
389	sqlserver	query	Check distribution agent errors and delivery status	{"sql": "SELECT da.name AS agent_name, da.subscriber_db,\\n  da.publication, dh.time, dh.comments,\\n  dh.delivered_commands, dh.delivered_transactions,\\n  dh.error_id\\nFROM distribution.dbo.MSdistribution_agents da\\nJOIN distribution.dbo.MSdistribution_history dh ON da.id = dh.agent_id\\nWHERE dh.error_id <> 0\\n  AND dh.time > DATEADD(day, -1, GETDATE())\\nORDER BY dh.time DESC"}	{"condition": "distribution agents with recent errors", "description": "Network or connectivity errors preventing replication delivery"}	null	2026-02-23 20:18:31.389071
3358	postgresql	query	Find idle-in-transaction sessions with duration	{"sql": "SELECT pid, usename, application_name, client_addr, state, xact_start, state_change, now() - state_change AS idle_duration FROM pg_stat_activity WHERE state = 'idle in transaction' AND xact_start IS NOT NULL ORDER BY idle_duration DESC"}	{"condition": "row_count > 0", "description": "Sessions stuck in idle-in-transaction state indicate potential connection leaks"}	\N	2026-02-25 00:28:52.405273
391	sqlserver	query	Check distribution undistributed commands	{"sql": "SELECT da.name AS agent_name, da.subscriber_db,\\n  SUM(CASE WHEN mc.xact_seqno > da.subscriber_seqno THEN 1 ELSE 0 END) AS pending_commands,\\n  da.time AS last_delivery_time,\\n  DATEDIFF(MINUTE, da.time, GETDATE()) AS minutes_behind\\nFROM distribution.dbo.MSdistribution_agents da\\nCROSS APPLY (\\n  SELECT TOP 1 xact_seqno FROM distribution.dbo.MSrepl_commands\\n  WHERE publisher_database_id = da.publisher_database_id\\n  ORDER BY xact_seqno DESC\\n) mc\\nGROUP BY da.name, da.subscriber_db, da.subscriber_seqno, da.time\\nHAVING SUM(CASE WHEN mc.xact_seqno > da.subscriber_seqno THEN 1 ELSE 0 END) > 0\\nORDER BY pending_commands DESC"}	{"condition": "large number of pending commands or significant time behind", "description": "Subscriber falling behind — distribution database accumulating undelivered commands"}	null	2026-02-23 20:18:31.389072
392	sqlserver	query	Check replication and AG role alignment	{"sql": "SELECT ars.role_desc,\\n  p.name AS publication_name, p.status AS pub_status,\\n  da.subscriber_db, da.status AS agent_status,\\n  dh.comments AS last_message\\nFROM sys.dm_hadr_availability_replica_states ars\\nLEFT JOIN distribution.dbo.MSpublications p ON 1=1\\nLEFT JOIN distribution.dbo.MSdistribution_agents da ON p.publication_id = da.publication_id\\nLEFT JOIN distribution.dbo.MSdistribution_history dh ON da.id = dh.agent_id\\n  AND dh.time = (SELECT MAX(dh2.time) FROM distribution.dbo.MSdistribution_history dh2\\n    WHERE dh2.agent_id = da.id)\\nWHERE ars.is_local = 1"}	{"condition": "current replica is PRIMARY but replication agents not running", "description": "Transactional replication not functioning after AG failover to this replica"}	null	2026-02-23 20:18:31.389073
