605	sqlserver	query	Check AG redo queue growth on secondary replicas	{"sql": "SELECT ar.replica_server_name, DB_NAME(drs.database_id) AS database_name, drs.redo_queue_size, drs.redo_rate, drs.log_send_queue_size, drs.synchronization_state_desc, drs.last_redone_time, DATEDIFF(SECOND, drs.last_redone_time, GETDATE()) AS seconds_since_last_redo FROM sys.dm_hadr_database_replica_states drs JOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id WHERE drs.is_primary_replica = 0 AND (drs.redo_queue_size > 500 OR DATEDIFF(SECOND, drs.last_redone_time, GETDATE()) > 60)"}	{"condition": "redo_queue_size > 500 or seconds_since_last_redo > 60", "description": "Redo is stalled or falling behind — long-running queries on secondary may be holding schema stability locks"}	null	2026-02-23 20:18:31.389208
606	sqlserver	query	Check for long-running queries on readable secondary	{"sql": "SELECT r.session_id, r.start_time, DATEDIFF(SECOND, r.start_time, GETDATE()) AS duration_sec, r.command, r.status, r.wait_type, r.blocking_session_id, DB_NAME(r.database_id) AS database_name, SUBSTRING(st.text, (r.statement_start_offset/2)+1, 200) AS query_fragment FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st WHERE r.database_id > 4 AND DATEDIFF(SECOND, r.start_time, GETDATE()) > 300 AND r.command IN ('SELECT', 'BACKUP DATABASE', 'DBCC') ORDER BY duration_sec DESC"}	{"condition": "SELECT queries running for > 300 seconds on AG secondary databases", "description": "Long-running read queries holding Sch-S locks that prevent redo from acquiring Sch-M locks for DDL replay"}	null	2026-02-23 20:18:31.389209
607	sqlserver	query	Check for redo thread blocked by schema locks	{"sql": "SELECT tl.request_session_id, tl.resource_type, tl.resource_database_id, DB_NAME(tl.resource_database_id) AS database_name, tl.request_mode, tl.request_status, tl.request_owner_type FROM sys.dm_tran_locks tl WHERE tl.request_mode IN ('Sch-M', 'Sch-S') AND tl.request_status = 'WAIT' ORDER BY tl.resource_database_id"}	{"condition": "Sch-M lock waits indicating redo blocked by Sch-S holders", "description": "Redo thread waiting for schema modification lock blocked by reader schema stability locks"}	null	2026-02-23 20:18:31.389209
608	sqlserver	query	Check published tables for missing primary keys	{"sql": "SELECT a.name AS article_name, a.dest_table, a.dest_owner, OBJECTPROPERTY(OBJECT_ID(a.dest_owner + '.' + a.dest_table), 'TableHasPrimaryKey') AS has_primary_key, OBJECTPROPERTY(OBJECT_ID(a.dest_owner + '.' + a.dest_table), 'TableHasIdentity') AS has_identity FROM distribution.dbo.MSarticles a JOIN distribution.dbo.MSpublications p ON a.publication_id = p.publication_id WHERE OBJECTPROPERTY(OBJECT_ID(a.dest_owner + '.' + a.dest_table), 'TableHasPrimaryKey') = 0"}	{"condition": "published tables without primary keys", "description": "Tables published for replication that lack primary keys — UPDATE and DELETE cannot be reliably replicated"}	null	2026-02-23 20:18:31.38921
609	sqlserver	query	Check replication errors for identity/key-related failures	{"sql": "SELECT re.id, re.time, re.error_code, re.error_text FROM distribution.dbo.MSrepl_errors re WHERE (re.error_text LIKE '%primary key%' OR re.error_text LIKE '%unique index%' OR re.error_text LIKE '%identity%' OR re.error_text LIKE '%ROWGUIDCOL%' OR re.error_text LIKE '%cannot find the row%') AND re.time > DATEADD(day, -7, GETDATE()) ORDER BY re.time DESC"}	{"condition": "row_count > 0", "description": "Replication errors related to missing identity columns or primary keys"}	null	2026-02-23 20:18:31.389211
610	sqlserver	query	Check for version store pressure in tempdb	{"sql": "SELECT SUM(version_store_reserved_page_count) * 8 / 1024 AS version_store_mb, SUM(version_store_reserved_page_count) AS version_pages, (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE counter_name = 'Version Store Size (KB)' AND instance_name = '') / 1024 AS perf_counter_version_store_mb FROM sys.dm_db_file_space_usage WHERE database_id = 2"}	{"condition": "version_store_mb > 1024", "description": "Large version store in tempdb indicating many snapshot isolation transactions or long-running reads"}	null	2026-02-23 20:18:31.389212
4125	postgresql	query	Check replication topology for anomalies	{"sql": "SELECT client_addr, state, sync_state, pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn) AS lag_bytes FROM pg_stat_replication"}	{"condition": "row_count >= 0", "description": "Review replication state; if this primary has no standbys, the old standby may have been promoted too"}	\N	2026-02-25 00:28:52.405273
4255	postgresql	query	Check for jobs with no recent execution	{"sql": "SELECT j.jobid, j.schedule, j.command, j.active, max(d.start_time) AS last_run FROM cron.job j LEFT JOIN cron.job_run_details d ON j.jobid = d.jobid WHERE j.active = true GROUP BY j.jobid, j.schedule, j.command, j.active HAVING max(d.start_time) < NOW() - interval ':hours hours' OR max(d.start_time) IS NULL"}	{"condition": "row_count > 0", "description": "Active jobs that have not run recently or never ran"}	{"hours": 24}	2026-02-25 00:28:52.405273
612	sqlserver	query	Check AG secondary for long-running snapshot transactions	{"sql": "SELECT s.session_id, s.login_time, s.status, DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS transaction_age_sec, t.transaction_type, t.transaction_state, DB_NAME(dt.database_id) AS database_name FROM sys.dm_tran_active_snapshot_database_transactions ast JOIN sys.dm_tran_active_transactions t ON ast.transaction_id = t.transaction_id JOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id JOIN sys.dm_exec_sessions s ON st.session_id = s.session_id LEFT JOIN sys.dm_tran_database_transactions dt ON t.transaction_id = dt.transaction_id WHERE DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) > 600 ORDER BY transaction_age_sec DESC"}	{"condition": "snapshot transactions older than 600 seconds", "description": "Long-running snapshot isolation transactions preventing version cleanup — version store grows and may eventually cause errors"}	null	2026-02-23 20:18:31.389212
3651	postgresql	query	Find roles with logging disabled	{"sql": "SELECT rolname, rolconfig FROM pg_roles WHERE rolconfig IS NOT NULL AND (array_to_string(rolconfig, ',') LIKE '%log_statement=none%' OR array_to_string(rolconfig, ',') LIKE '%log_min_duration_statement=-1%') ORDER BY rolname"}	{"condition": "row_count > 0", "description": "Roles with logging explicitly disabled — audit exemption"}	\N	2026-02-25 00:28:52.405273
613	sqlserver	query	Check replication errors for constraint violations	{"sql": "SELECT re.id, re.time, re.error_code, re.error_text, re.xact_seqno FROM distribution.dbo.MSrepl_errors re WHERE (re.error_code IN (2601, 2627, 547, 515) OR re.error_text LIKE '%duplicate key%' OR re.error_text LIKE '%UNIQUE KEY constraint%' OR re.error_text LIKE '%PRIMARY KEY constraint%' OR re.error_text LIKE '%FOREIGN KEY constraint%' OR re.error_text LIKE '%CHECK constraint%' OR re.error_text LIKE '%cannot insert the value NULL%') AND re.time > DATEADD(day, -7, GETDATE()) ORDER BY re.time DESC"}	{"condition": "row_count > 0 with error codes 2601/2627/547/515", "description": "Constraint violations at subscriber — error 2627 (PK violation), 2601 (unique index), 547 (FK/CHECK), 515 (NOT NULL)"}	null	2026-02-23 20:18:31.389213
617	sqlserver	query	Check for active triggers on replicated subscriber tables	{"sql": "SELECT OBJECT_NAME(t.parent_id) AS table_name, t.name AS trigger_name, t.is_disabled, t.is_instead_of_trigger, CASE WHEN te.type = 'TA' THEN 'CLR' ELSE 'T-SQL' END AS trigger_type, OBJECTPROPERTY(t.object_id, 'ExecIsNotForRepl') AS is_not_for_repl FROM sys.triggers t LEFT JOIN sys.trigger_events te ON t.object_id = te.object_id WHERE t.parent_id IN (SELECT OBJECT_ID(a.dest_owner + '.' + a.dest_table) FROM distribution.dbo.MSarticles a) AND t.is_disabled = 0"}	{"condition": "triggers without NOT FOR REPLICATION on replicated tables", "description": "Active triggers on subscriber tables that fire during replication — is_not_for_repl = 0 means the trigger fires for replicated transactions"}	null	2026-02-23 20:18:31.389215
618	sqlserver	query	Check replication errors for trigger-related failures	{"sql": "SELECT re.id, re.time, re.error_code, re.error_text FROM distribution.dbo.MSrepl_errors re WHERE (re.error_text LIKE '%trigger%' OR re.error_text LIKE '%INSTEAD OF%' OR re.error_code IN (334, 336, 3609) OR re.error_text LIKE '%fired by replication%') AND re.time > DATEADD(day, -7, GETDATE()) ORDER BY re.time DESC"}	{"condition": "row_count > 0", "description": "Replication errors caused by trigger execution failures on subscriber"}	null	2026-02-23 20:18:31.389216
619	sqlserver	query	Check for DDL replication configuration	{"sql": "SELECT p.name AS publication_name, p.replicate_ddl, p.allow_push, p.allow_pull, p.status FROM distribution.dbo.MSpublications p"}	{"condition": "replicate_ddl = 0 on any publication", "description": "Publications with DDL replication disabled — schema changes on publisher will not propagate to subscribers"}	null	2026-02-23 20:18:31.389217
620	sqlserver	query	Check replication errors for schema mismatch failures	{"sql": "SELECT re.id, re.time, re.error_code, re.error_text FROM distribution.dbo.MSrepl_errors re WHERE (re.error_text LIKE '%invalid column%' OR re.error_text LIKE '%does not match%' OR re.error_text LIKE '%column does not exist%' OR re.error_text LIKE '%invalid object%' OR re.error_code IN (207, 208, 213, 4104)) AND re.time > DATEADD(day, -7, GETDATE()) ORDER BY re.time DESC"}	{"condition": "row_count > 0 with error codes 207/208/213/4104", "description": "Replication errors from schema mismatch — columns or objects on publisher don't exist on subscriber"}	null	2026-02-23 20:18:31.389217
621	sqlserver	query	Check for schema version differences between published articles and subscriber	{"sql": "SELECT a.name AS article_name, a.dest_table, a.schema_option, CASE WHEN a.schema_option & 0x0000000000000001 = 0x0000000000000001 THEN 'YES' ELSE 'NO' END AS schema_create, CASE WHEN a.schema_option & 0x0000000000000004 = 0x0000000000000004 THEN 'YES' ELSE 'NO' END AS schema_pk, CASE WHEN a.schema_option & 0x0000000000000040 = 0x0000000000000040 THEN 'YES' ELSE 'NO' END AS schema_indexes FROM distribution.dbo.MSarticles a"}	{"condition": "articles with limited schema_option settings", "description": "Published articles with restrictive schema options — schema changes may not propagate completely"}	null	2026-02-23 20:18:31.389218
627	sqlserver	query	Check replication error history for ordering and conflict errors	{"sql": "SELECT re.id, re.time, re.error_code, re.error_text FROM distribution.dbo.MSrepl_errors re WHERE (re.error_text LIKE '%conflict%' OR re.error_text LIKE '%peer-to-peer%' OR re.error_text LIKE '%originator%' OR re.error_code IN (22815, 22816, 22827)) AND re.time > DATEADD(day, -7, GETDATE()) ORDER BY re.time DESC"}	{"condition": "row_count > 0 with peer-to-peer conflict errors", "description": "Peer-to-peer replication conflicts caused by transactions applied in different order at different nodes"}	null	2026-02-23 20:18:31.389221
628	sqlserver	query	Check distribution agent connectivity to all peers	{"sql": "SELECT da.name AS agent_name, da.subscriber_db, da.subscriber_server_name, dh.time AS last_activity, dh.runstatus, dh.comments, DATEDIFF(MINUTE, dh.time, GETDATE()) AS minutes_since_activity FROM distribution.dbo.MSdistribution_agents da JOIN (SELECT agent_id, MAX(time) AS time, runstatus, comments FROM distribution.dbo.MSdistribution_history GROUP BY agent_id, runstatus, comments) dh ON da.id = dh.agent_id WHERE DATEDIFF(MINUTE, dh.time, GETDATE()) > 30 OR dh.runstatus IN (5, 6) ORDER BY minutes_since_activity DESC"}	{"condition": "distribution agents inactive for > 30 minutes or in failed state", "description": "Replication agents unable to reach peer nodes — potential network partition"}	null	2026-02-23 20:18:31.389222
