4135	postgresql	query	Check active client connections	{"sql": "SELECT client_addr, count(*) AS connection_count FROM pg_stat_activity WHERE backend_type = 'client backend' GROUP BY client_addr ORDER BY connection_count DESC"}	{"condition": "row_count > 0", "description": "Clients connected to this primary; if another primary exists, VIP didn't migrate"}	\N	2026-02-25 00:28:52.405273
630	sqlserver	query	Check undelivered commands accumulating during partition	{"sql": "SELECT da.name AS agent_name, da.subscriber_server_name, COUNT(*) AS undelivered_commands, MIN(dc.xact_seqno) AS oldest_undelivered, MAX(dc.xact_seqno) AS newest_undelivered FROM distribution.dbo.MSdistribution_agents da JOIN distribution.dbo.MSrepl_commands dc ON da.id = dc.agent_id WHERE dc.xact_seqno > da.subscriber_seqno GROUP BY da.name, da.subscriber_server_name HAVING COUNT(*) > 1000 ORDER BY undelivered_commands DESC"}	{"condition": "undelivered_commands > 1000 for any peer", "description": "Large backlog of undelivered commands to peer nodes — evidence of network partition or peer unavailability"}	null	2026-02-23 20:18:31.389223
633	sqlserver	query	Check recent job history for T-SQL execution failures	{"sql": "SELECT j.name AS job_name, js.step_name, js.step_id,\\n  h.run_date, h.run_time, h.run_status,\\n  h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Incorrect syntax%'\\n    OR h.message LIKE '%Msg 102,%'\\n    OR h.message LIKE '%Msg 156,%'\\n    OR h.message LIKE '%Msg 105,%'\\n    OR h.message LIKE '%Msg 170,%'\\n    OR h.message LIKE '%Msg 207,%'\\n    OR h.message LIKE '%Msg 245,%'\\n    OR h.message LIKE '%Msg 8114,%'\\n    OR h.message LIKE '%conversion failed%'\\n    OR h.message LIKE '%divide by zero%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Agent job steps failed with T-SQL syntax or logical errors"}	null	2026-02-23 20:18:31.389225
837	sqlserver	query	Check transaction log retention due to replication or CDC	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  ls.total_log_size_in_bytes / 1048576 AS log_size_mb,\\n  ls.used_log_space_in_bytes / 1048576 AS log_used_mb,\\n  ls.used_log_space_in_percent AS log_used_pct\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nWHERE d.database_id = DB_ID()\\n  AND d.log_reuse_wait_desc IN ('REPLICATION', 'CDC', 'ACTIVE_BACKUP_OR_RESTORE')"}	{"condition": "log_reuse_wait_desc IN ('REPLICATION', 'CDC') AND log_used_pct > 50", "description": "Transaction log cannot be reused due to replication/CDC backlog"}	null	2026-02-23 20:18:31.389226
635	sqlserver	query	Check job history for object-not-found errors	{"sql": "SELECT j.name AS job_name, js.step_name, js.step_id,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Invalid object name%'\\n    OR h.message LIKE '%Msg 208,%'\\n    OR h.message LIKE '%Could not find stored procedure%'\\n    OR h.message LIKE '%Msg 2812,%'\\n    OR h.message LIKE '%not find the object%'\\n    OR h.message LIKE '%Invalid column name%'\\n    OR h.message LIKE '%Msg 4104,%'\\n    OR h.message LIKE '%Cannot find the object%'\\n    OR h.message LIKE '%Invalid schema%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failing due to missing database objects"}	null	2026-02-23 20:18:31.389227
636	sqlserver	query	Verify the target database and object status	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  js.database_name AS target_db,\\n  js.command,\\n  CASE WHEN DB_ID(js.database_name) IS NULL THEN 'DATABASE MISSING'\\n    ELSE 'DATABASE EXISTS' END AS db_status\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nJOIN msdb.dbo.sysjobhistory h ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Invalid object name%'\\n    OR h.message LIKE '%Could not find stored procedure%'\\n    OR h.message LIKE '%Msg 208,%'\\n    OR h.message LIKE '%Msg 2812,%')\\n  AND js.subsystem = 'TSQL'"}	{"condition": "job steps referencing missing objects or databases", "description": "Confirms job steps target objects that no longer exist or were renamed"}	null	2026-02-23 20:18:31.389227
637	sqlserver	query	Check job history for permission-related errors	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  j.owner_sid,\\n  SUSER_SNAME(j.owner_sid) AS job_owner,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%permission%'\\n    OR h.message LIKE '%Msg 229,%'\\n    OR h.message LIKE '%Msg 230,%'\\n    OR h.message LIKE '%Msg 262,%'\\n    OR h.message LIKE '%not have permission%'\\n    OR h.message LIKE '%denied%'\\n    OR h.message LIKE '%Login failed%'\\n    OR h.message LIKE '%Msg 18456,%'\\n    OR h.message LIKE '%Cannot open database%'\\n    OR h.message LIKE '%Msg 916,%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failing with permission or authentication errors"}	null	2026-02-23 20:18:31.389228
638	sqlserver	query	Check job owner validity and proxy configuration	{"sql": "SELECT j.name AS job_name,\\n  SUSER_SNAME(j.owner_sid) AS job_owner,\\n  CASE WHEN SUSER_SNAME(j.owner_sid) IS NULL THEN 'ORPHANED OWNER'\\n    ELSE 'OWNER EXISTS' END AS owner_status,\\n  js.step_name, js.subsystem,\\n  COALESCE(p.name, 'SQL Agent service account') AS run_as_identity\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nLEFT JOIN msdb.dbo.sysproxies p ON js.proxy_id = p.proxy_id\\nWHERE SUSER_SNAME(j.owner_sid) IS NULL\\n  OR js.proxy_id IS NOT NULL"}	{"condition": "orphaned owners or proxy-based job steps", "description": "Job owner orphaned (login dropped) or proxy credential potentially misconfigured"}	null	2026-02-23 20:18:31.389229
1036	sqlserver	query	Check SQL Server edition	{"sql": "SELECT\\n  SERVERPROPERTY('Edition') AS edition,\\n  SERVERPROPERTY('EngineEdition') AS engine_edition,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  SERVERPROPERTY('LicenseType') AS license_type"}	{"condition": "edition LIKE '%Express%' OR edition LIKE '%Developer%' OR edition LIKE '%Evaluation%'", "description": "Non-production edition detected"}	null	2026-02-23 20:18:31.389405
840	sqlserver	query	Check for failed SQL Agent jobs related to purge/cleanup	{"sql": "SELECT j.name AS job_name,\\n  jh.run_date, jh.run_time,\\n  jh.run_status,\\n  jh.message,\\n  jh.run_duration\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory jh ON j.job_id = jh.job_id\\nWHERE jh.step_id = 0\\n  AND jh.run_status = 0\\n  AND (j.name LIKE '%purge%' OR j.name LIKE '%cleanup%' OR j.name LIKE '%archive%'\\n    OR j.name LIKE '%delete%' OR j.name LIKE '%retention%' OR j.name LIKE '%maintenance%')\\n  AND jh.run_date >= CONVERT(INT, CONVERT(VARCHAR(8), DATEADD(day, -7, GETDATE()), 112))\\nORDER BY jh.run_date DESC, jh.run_time DESC"}	{"condition": "row_count > 0", "description": "Purge/cleanup jobs have failed in the last 7 days"}	null	2026-02-23 20:18:31.389361
641	sqlserver	query	Check job history for resource exhaustion errors	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%insufficient memory%'\\n    OR h.message LIKE '%Msg 701,%'\\n    OR h.message LIKE '%Msg 802,%'\\n    OR h.message LIKE '%tempdb%'\\n    OR h.message LIKE '%disk space%'\\n    OR h.message LIKE '%could not allocate%'\\n    OR h.message LIKE '%timeout expired%'\\n    OR h.message LIKE '%Msg 1105,%'\\n    OR h.message LIKE '%resource pool%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failing with resource exhaustion errors"}	null	2026-02-23 20:18:31.38923
642	sqlserver	query	Check job history for lock-related errors	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%lock request time out%'\\n    OR h.message LIKE '%Msg 1222,%'\\n    OR h.message LIKE '%deadlock victim%'\\n    OR h.message LIKE '%Msg 1205,%'\\n    OR h.message LIKE '%lock timeout%'\\n    OR h.message LIKE '%could not obtain a lock%'\\n    OR h.message LIKE '%lock escalation%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failed due to lock timeout or deadlock"}	null	2026-02-23 20:18:31.389231
643	sqlserver	query	Check current lock contention and deadlock count	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests WHERE blocking_session_id <> 0) AS currently_blocked,\\n  (SELECT COUNT(*) FROM sys.dm_tran_locks WHERE request_status = 'WAIT') AS lock_waits,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Number of Deadlocks/sec' AND instance_name = '_Total') AS total_deadlocks,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Lock Timeouts/sec' AND instance_name = '_Total') AS total_lock_timeouts"}	{"condition": "currently_blocked > 5 OR total_lock_timeouts > 0 OR total_deadlocks > 0", "description": "Active lock contention or accumulated lock timeouts/deadlocks"}	null	2026-02-23 20:18:31.389232
646	sqlserver	query	Check job history for connection and network errors	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%connection was forcibly closed%'\\n    OR h.message LIKE '%network-related%'\\n    OR h.message LIKE '%Msg 10054,%'\\n    OR h.message LIKE '%Msg 10053,%'\\n    OR h.message LIKE '%Msg 53,%'\\n    OR h.message LIKE '%Named Pipes Provider%'\\n    OR h.message LIKE '%TCP Provider%'\\n    OR h.message LIKE '%Communication link failure%'\\n    OR h.message LIKE '%server was not found%'\\n    OR h.message LIKE '%linked server%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failed due to connection or network errors"}	null	2026-02-23 20:18:31.389234
647	sqlserver	query	Check linked server connectivity status	{"sql": "SELECT s.name AS linked_server, s.data_source, s.provider,\\n  s.product, s.is_linked\\nFROM sys.servers s\\nWHERE s.is_linked = 1\\nORDER BY s.name"}	{"condition": "linked servers configured (potential failure points)", "description": "Linked servers exist that may have connectivity issues"}	null	2026-02-23 20:18:31.389234
1338	sqlserver	query	Check for THREADPOOL waits confirming impact of stale config	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms, max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'THREADPOOL'\\nUNION ALL\\nSELECT 'SCHEDULER_QUEUED' AS wait_type,\\n  SUM(work_queue_count) AS waiting_tasks_count,\\n  0 AS wait_time_ms,\\n  0 AS max_wait_time_ms\\nFROM sys.dm_os_schedulers\\nWHERE status = 'VISIBLE ONLINE'\\n  AND work_queue_count > 0"}	{"condition": "THREADPOOL waits present OR work_queue_count > 0", "description": "THREADPOOL waits or queued tasks confirm that the stale max worker threads configuration is actively causing connection/request queuing that the pending restart would resolve"}	null	2026-02-23 20:18:31.389644
648	sqlserver	query	Check job history for disk space errors	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%disk space%'\\n    OR h.message LIKE '%Msg 112,%'\\n    OR h.message LIKE '%Msg 1105,%'\\n    OR h.message LIKE '%operating system error 112%'\\n    OR h.message LIKE '%not enough space%'\\n    OR h.message LIKE '%could not allocate a new page%'\\n    OR h.message LIKE '%is full%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failed due to disk space exhaustion"}	null	2026-02-23 20:18:31.389235
652	sqlserver	query	Check job history for crash or termination indicators	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  h.run_status, h.run_date, h.run_time,\\n  h.run_duration, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.run_status = 3\\n    OR h.message LIKE '%process was killed%'\\n    OR h.message LIKE '%session was killed%'\\n    OR h.message LIKE '%Msg 233,%'\\n    OR h.message LIKE '%A severe error occurred%'\\n    OR h.message LIKE '%The process could not execute%'\\n    OR h.message LIKE '%terminated abnormally%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps canceled (run_status=3) or terminated abnormally"}	null	2026-02-23 20:18:31.389238
654	sqlserver	query	Check job history for external dependency errors	{"sql": "SELECT j.name AS job_name, js.step_name, js.subsystem,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%network path%'\\n    OR h.message LIKE '%The system cannot find the path%'\\n    OR h.message LIKE '%Access is denied%'\\n    OR h.message LIKE '%file not found%'\\n    OR h.message LIKE '%SSIS%'\\n    OR h.message LIKE '%xp_cmdshell%'\\n    OR h.message LIKE '%OLE DB%'\\n    OR h.message LIKE '%The process exit code was%'\\n    OR js.subsystem IN ('CmdExec', 'SSIS', 'PowerShell'))\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps using external subsystems (CmdExec, SSIS, PowerShell) or referencing external paths failed"}	null	2026-02-23 20:18:31.389239
655	sqlserver	query	Identify job steps with external dependencies	{"sql": "SELECT j.name AS job_name, js.step_name, js.subsystem,\\n  CASE WHEN js.subsystem = 'CmdExec' THEN 'OS Command'\\n    WHEN js.subsystem = 'SSIS' THEN 'SSIS Package'\\n    WHEN js.subsystem = 'PowerShell' THEN 'PowerShell Script'\\n    WHEN js.command LIKE '%OPENQUERY%' THEN 'Linked Server Query'\\n    WHEN js.command LIKE '%xp_cmdshell%' THEN 'xp_cmdshell Call'\\n    WHEN js.command LIKE '%\\\\\\\\%' THEN 'UNC Path Reference'\\n    ELSE 'Other External' END AS dependency_type,\\n  LEFT(js.command, 200) AS command_preview\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE js.subsystem IN ('CmdExec', 'SSIS', 'PowerShell')\\n  OR js.command LIKE '%OPENQUERY%'\\n  OR js.command LIKE '%xp_cmdshell%'\\n  OR js.command LIKE '%\\\\\\\\%'"}	{"condition": "job steps with external dependencies identified", "description": "Jobs depend on external systems that may be unavailable"}	null	2026-02-23 20:18:31.38924
656	sqlserver	query	Check job history for data type and parameter errors	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Conversion failed%'\\n    OR h.message LIKE '%Msg 245,%'\\n    OR h.message LIKE '%Msg 8114,%'\\n    OR h.message LIKE '%Msg 8115,%'\\n    OR h.message LIKE '%Msg 257,%'\\n    OR h.message LIKE '%Msg 206,%'\\n    OR h.message LIKE '%implicit conversion%'\\n    OR h.message LIKE '%operand type clash%'\\n    OR h.message LIKE '%expects parameter%'\\n    OR h.message LIKE '%Procedure or function%has too many arguments%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failing with data type conversion or parameter binding errors"}	null	2026-02-23 20:18:31.38924
657	sqlserver	query	Identify job steps using dynamic SQL	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  CASE WHEN js.command LIKE '%sp_executesql%' THEN 'sp_executesql'\\n    WHEN js.command LIKE '%EXEC(%' OR js.command LIKE '%EXECUTE(%' THEN 'EXEC dynamic'\\n    ELSE 'static SQL' END AS sql_type,\\n  LEFT(js.command, 300) AS command_preview\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nJOIN msdb.dbo.sysjobhistory h ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Conversion failed%'\\n    OR h.message LIKE '%operand type clash%'\\n    OR h.message LIKE '%expects parameter%')\\n  AND (js.command LIKE '%sp_executesql%'\\n    OR js.command LIKE '%EXEC(%'\\n    OR js.command LIKE '%EXECUTE(%')"}	{"condition": "dynamic SQL job steps with type mismatch errors", "description": "Confirms dynamic SQL parameter binding is the failure point"}	null	2026-02-23 20:18:31.389241
3429	postgresql	query	Verify critical background processes are running	{"sql": "SELECT backend_type, count(*) FROM pg_stat_activity WHERE backend_type IN ('checkpointer', 'background writer', 'walwriter', 'autovacuum launcher') GROUP BY backend_type ORDER BY backend_type"}	{"condition": "row_count = 4", "description": "All four critical background processes should be running"}	\N	2026-02-25 00:28:52.405273
908	sqlserver	query	Check checkpoint-related wait statistics	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CHECKPOINT_QUEUE', 'CHKPT', 'WRITELOG', 'IO_COMPLETION', 'LAZY_WRITER_SLEEP')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "CHECKPOINT_QUEUE or CHKPT wait_time_ms significantly elevated", "description": "Checkpoint-related waits indicate heavy flush operations impacting I/O"}	null	2026-02-23 20:18:31.389274
658	sqlserver	query	Check job history for transaction log full errors	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%transaction log%is full%'\\n    OR h.message LIKE '%Msg 9002,%'\\n    OR h.message LIKE '%log file is full%'\\n    OR h.message LIKE '%could not allocate space for object%in database%because the%log file is full%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failed because transaction log is full"}	null	2026-02-23 20:18:31.389241
1085	sqlserver	query	Check SQL Server service account details and privileges	{"sql": "SELECT servicename, service_account,\\n  startup_type_desc, status_desc,\\n  instant_file_initialization_enabled,\\n  is_clustered\\nFROM sys.dm_server_services"}	{"condition": "row_count > 0", "description": "Service account information retrieved — verify account has required permissions"}	null	2026-02-23 20:18:31.389243
660	sqlserver	query	Check job history for constraint violation errors	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%FOREIGN KEY constraint%'\\n    OR h.message LIKE '%Msg 547,%'\\n    OR h.message LIKE '%CHECK constraint%'\\n    OR h.message LIKE '%UNIQUE constraint%'\\n    OR h.message LIKE '%Msg 2627,%'\\n    OR h.message LIKE '%Msg 2601,%'\\n    OR h.message LIKE '%Cannot insert duplicate key%'\\n    OR h.message LIKE '%conflicted with the%constraint%'\\n    OR h.message LIKE '%NOT NULL constraint%'\\n    OR h.message LIKE '%Cannot insert the value NULL%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failing due to data constraint violations"}	null	2026-02-23 20:18:31.389243
661	sqlserver	query	Identify the constraint and affected table	{"sql": "SELECT j.name AS job_name,\\n  h.message,\\n  CASE\\n    WHEN h.message LIKE '%Msg 547,%' THEN 'FOREIGN KEY or CHECK'\\n    WHEN h.message LIKE '%Msg 2627,%' THEN 'PRIMARY KEY or UNIQUE'\\n    WHEN h.message LIKE '%Msg 2601,%' THEN 'UNIQUE INDEX'\\n    WHEN h.message LIKE '%Cannot insert the value NULL%' THEN 'NOT NULL'\\n    ELSE 'OTHER CONSTRAINT' END AS constraint_type\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Msg 547,%' OR h.message LIKE '%Msg 2627,%'\\n    OR h.message LIKE '%Msg 2601,%' OR h.message LIKE '%Cannot insert the value NULL%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "constraint type identified from error message", "description": "Confirms the specific constraint type causing the job failure"}	null	2026-02-23 20:18:31.389244
4259	postgresql	query	Review all job schedules for unusual patterns	{"sql": "SELECT jobid, schedule, command, active FROM cron.job ORDER BY jobid"}	{"condition": "row_count > 0", "description": "Review schedule definitions for syntax issues"}	\N	2026-02-25 00:28:52.405273
662	sqlserver	query	Check job history for trigger-related failures	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  h.run_date, h.run_time, h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%trigger%'\\n    OR h.message LIKE '%Maximum stored procedure, function, trigger, or view nesting%'\\n    OR h.message LIKE '%Msg 217,%'\\n    OR h.message LIKE '%instead of%'\\n    OR h.message LIKE '%AFTER trigger%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job steps failed with trigger-related errors"}	null	2026-02-23 20:18:31.389244
663	sqlserver	query	Identify tables with active triggers referenced by failing jobs	{"sql": "SELECT OBJECT_SCHEMA_NAME(t.parent_id) AS schema_name,\\n  OBJECT_NAME(t.parent_id) AS table_name,\\n  t.name AS trigger_name, t.type_desc,\\n  CASE WHEN t.is_disabled = 1 THEN 'DISABLED' ELSE 'ENABLED' END AS trigger_status,\\n  CASE WHEN t.is_instead_of_trigger = 1 THEN 'INSTEAD OF' ELSE 'AFTER' END AS trigger_type\\nFROM sys.triggers t\\nWHERE t.parent_class = 1\\n  AND t.is_disabled = 0\\nORDER BY OBJECT_NAME(t.parent_id)"}	{"condition": "active triggers on tables used by job steps", "description": "Enabled triggers exist that fire during job DML operations"}	null	2026-02-23 20:18:31.389245
666	sqlserver	query	Check for jobs with one-time schedules that already ran	{"sql": "SELECT j.name AS job_name, j.enabled AS job_enabled,\\n  s.name AS schedule_name, s.enabled AS schedule_enabled,\\n  s.freq_type,\\n  CASE s.freq_type\\n    WHEN 1 THEN 'One-time'\\n    WHEN 4 THEN 'Daily'\\n    WHEN 8 THEN 'Weekly'\\n    WHEN 16 THEN 'Monthly'\\n    WHEN 64 THEN 'Agent Start'\\n    WHEN 128 THEN 'Agent Idle'\\n    ELSE CAST(s.freq_type AS varchar(10)) END AS schedule_type,\\n  s.active_start_date, s.active_end_date,\\n  CASE WHEN s.freq_type = 1\\n    AND s.active_start_date < CONVERT(int, CONVERT(varchar(8), GETDATE(), 112))\\n    THEN 'EXPIRED' ELSE 'ACTIVE' END AS schedule_status\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\nWHERE j.enabled = 1\\n  AND s.enabled = 1\\n  AND ((s.freq_type = 1\\n    AND s.active_start_date < CONVERT(int, CONVERT(varchar(8), GETDATE(), 112)))\\n  OR (s.active_end_date <> 99991231\\n    AND s.active_end_date < CONVERT(int, CONVERT(varchar(8), GETDATE(), 112))))"}	{"condition": "row_count > 0", "description": "Enabled jobs with expired one-time schedules or past end dates"}	null	2026-02-23 20:18:31.389247
667	sqlserver	query	Check if these jobs have any recent execution history	{"sql": "SELECT j.name AS job_name,\\n  ja.run_requested_date AS last_run_requested,\\n  DATEDIFF(day, ja.run_requested_date, GETDATE()) AS days_since_last_run\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND j.enabled = 1\\n  AND (ja.run_requested_date IS NULL\\n    OR ja.run_requested_date < DATEADD(day, -7, GETDATE()))\\nORDER BY ja.run_requested_date ASC"}	{"condition": "enabled jobs with no recent execution (> 7 days or never)", "description": "Confirms jobs are enabled but not being scheduled due to expired schedule"}	null	2026-02-23 20:18:31.389248
671	sqlserver	query	Check for disabled jobs with recent retry failures in history	{"sql": "SELECT j.name AS job_name, j.enabled, j.date_modified,\\n  js.step_name, js.retry_attempts, js.retry_interval,\\n  COUNT(h.instance_id) AS recent_failures,\\n  MAX(h.run_date) AS last_failure_date,\\n  MAX(h.run_time) AS last_failure_time\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nJOIN msdb.dbo.sysjobhistory h ON h.job_id = j.job_id AND h.step_id = js.step_id\\nWHERE j.enabled = 0\\n  AND h.run_status = 0\\n  AND js.retry_attempts > 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -14, GETDATE()), 112))\\nGROUP BY j.name, j.enabled, j.date_modified, js.step_name, js.retry_attempts, js.retry_interval\\nHAVING COUNT(h.instance_id) >= js.retry_attempts\\nORDER BY MAX(h.run_date) DESC"}	{"condition": "row_count > 0", "description": "Disabled jobs whose failure count matches or exceeds configured retry attempts"}	null	2026-02-23 20:18:31.38925
672	sqlserver	query	Verify the job was disabled close to the last failure timestamp	{"sql": "SELECT j.name AS job_name, j.enabled, j.date_modified AS job_disabled_date,\\n  h.run_date AS last_fail_date, h.run_time AS last_fail_time,\\n  h.message AS last_error_message,\\n  DATEDIFF(minute,\\n    CAST(CAST(h.run_date AS varchar(8)) AS datetime)\\n      + CAST(STUFF(STUFF(RIGHT('000000' + CAST(h.run_time AS varchar(6)), 6), 3, 0, ':'), 6, 0, ':') AS datetime),\\n    j.date_modified) AS minutes_between_fail_and_disable\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory h ON h.job_id = j.job_id\\nWHERE j.enabled = 0\\n  AND h.run_status = 0\\n  AND h.step_id = 0\\n  AND h.run_date = (\\n    SELECT MAX(h2.run_date) FROM msdb.dbo.sysjobhistory h2\\n    WHERE h2.job_id = j.job_id AND h2.step_id = 0 AND h2.run_status = 0)\\nORDER BY j.date_modified DESC"}	{"condition": "minutes_between_fail_and_disable < 60", "description": "Job was disabled shortly after the last failure — indicates auto-disable after retry exhaustion"}	null	2026-02-23 20:18:31.389251
673	sqlserver	query	Check for schedules with invalid or nonsensical parameter combinations	{"sql": "SELECT j.name AS job_name, s.name AS schedule_name,\\n  s.enabled AS schedule_enabled,\\n  s.freq_type, s.freq_interval, s.freq_subday_type, s.freq_subday_interval,\\n  s.freq_relative_interval, s.freq_recurrence_factor,\\n  s.active_start_date, s.active_start_time,\\n  s.active_end_date, s.active_end_time,\\n  CASE\\n    WHEN s.freq_type = 8 AND s.freq_interval = 0 THEN 'Weekly with no days selected'\\n    WHEN s.freq_type = 16 AND (s.freq_interval < 1 OR s.freq_interval > 31) THEN 'Monthly with invalid day'\\n    WHEN s.freq_type = 32 AND s.freq_relative_interval NOT IN (1,2,4,8,16) THEN 'Monthly-relative with invalid ordinal'\\n    WHEN s.freq_subday_type = 2 AND s.freq_subday_interval = 0 THEN 'Seconds interval = 0'\\n    WHEN s.freq_subday_type = 4 AND s.freq_subday_interval = 0 THEN 'Minutes interval = 0'\\n    WHEN s.freq_subday_type = 8 AND s.freq_subday_interval = 0 THEN 'Hours interval = 0'\\n    WHEN s.freq_recurrence_factor = 0 AND s.freq_type IN (8, 16, 32) THEN 'Recurrence factor = 0'\\n    WHEN s.active_start_date > s.active_end_date AND s.active_end_date <> 99991231 THEN 'Start date after end date'\\n    ELSE NULL END AS schedule_problem\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\nWHERE j.enabled = 1\\n  AND s.enabled = 1\\n  AND (\\n    (s.freq_type = 8 AND s.freq_interval = 0)\\n    OR (s.freq_type = 16 AND (s.freq_interval < 1 OR s.freq_interval > 31))\\n    OR (s.freq_type = 32 AND s.freq_relative_interval NOT IN (1,2,4,8,16))\\n    OR (s.freq_subday_type IN (2,4,8) AND s.freq_subday_interval = 0)\\n    OR (s.freq_recurrence_factor = 0 AND s.freq_type IN (8,16,32))\\n    OR (s.active_start_date > s.active_end_date AND s.active_end_date <> 99991231)\\n  )"}	{"condition": "row_count > 0", "description": "Schedules with invalid parameter combinations that prevent proper scheduling"}	null	2026-02-23 20:18:31.389252
674	sqlserver	query	Verify these jobs have no next scheduled run date	{"sql": "SELECT j.name AS job_name, s.name AS schedule_name,\\n  ja.next_scheduled_run_date,\\n  ja.run_requested_date AS last_run,\\n  CASE WHEN ja.next_scheduled_run_date IS NULL THEN 'NO NEXT RUN'\\n    WHEN ja.next_scheduled_run_date < GETDATE() THEN 'NEXT RUN IN PAST'\\n    ELSE 'SCHEDULED' END AS scheduling_status\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\nLEFT JOIN msdb.dbo.sysjobactivity ja ON j.job_id = ja.job_id\\n  AND ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\nWHERE j.enabled = 1 AND s.enabled = 1\\n  AND (ja.next_scheduled_run_date IS NULL\\n    OR ja.next_scheduled_run_date < GETDATE())\\nORDER BY j.name"}	{"condition": "enabled jobs with no valid next_scheduled_run_date", "description": "Confirms the invalid schedule parameters prevent the Agent from computing a next run time"}	null	2026-02-23 20:18:31.389252
4156	postgresql	query	Check subscription configuration	{"sql": "SELECT subname, subenabled, subslotname, subconninfo FROM pg_subscription"}	{"condition": "row_count > 0", "description": "Subscription exists; verify slot name matches publisher"}	\N	2026-02-25 00:28:52.405273
675	sqlserver	query	Check for currently executing jobs that overlap with their schedule	{"sql": "SELECT j.name AS job_name,\\n  ja.run_requested_date AS started_at,\\n  DATEDIFF(minute, ja.run_requested_date, GETDATE()) AS running_minutes,\\n  ja.last_executed_step_id, ja.last_executed_step_date,\\n  ja.next_scheduled_run_date,\\n  CASE WHEN ja.next_scheduled_run_date IS NOT NULL\\n    AND ja.next_scheduled_run_date < GETDATE() THEN 'OVERDUE'\\n    ELSE 'ON SCHEDULE' END AS schedule_status\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND ja.start_execution_date IS NOT NULL\\n  AND ja.stop_execution_date IS NULL\\nORDER BY ja.run_requested_date ASC"}	{"condition": "row_count > 0 AND schedule_status = 'OVERDUE'", "description": "Jobs currently running past their next scheduled execution time"}	null	2026-02-23 20:18:31.389253
10855	mysql	query	Check for buffer pool wait-free page availability	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME IN ('Innodb_buffer_pool_wait_free', 'Innodb_buffer_pool_pages_flushed', 'Innodb_buffer_pool_pages_dirty')"}	{"condition": "Innodb_buffer_pool_wait_free > 0", "description": "Wait-free counter > 0 indicates pages had to be flushed to make room, suggesting checkpoint pressure"}	\N	2026-03-01 06:30:58.706791
682	sqlserver	query	Check for job failures shortly after startup referencing database availability	{"sql": "SELECT j.name AS job_name, h.run_date, h.run_time, h.message,\\n  CASE\\n    WHEN h.message LIKE '%is not yet available%' THEN 'Database not yet available'\\n    WHEN h.message LIKE '%RECOVERING%' THEN 'Database recovering'\\n    WHEN h.message LIKE '%not accessible%' THEN 'Database not accessible'\\n    WHEN h.message LIKE '%Cannot open database%' THEN 'Cannot open database'\\n    ELSE 'Other startup-related failure' END AS failure_reason\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date = CONVERT(int, CONVERT(varchar(8),\\n    (SELECT sqlserver_start_time FROM sys.dm_os_sys_info), 112))\\n  AND (h.message LIKE '%not yet available%'\\n    OR h.message LIKE '%RECOVERING%'\\n    OR h.message LIKE '%not accessible%'\\n    OR h.message LIKE '%Cannot open database%'\\n    OR h.message LIKE '%Msg 945,%'\\n    OR h.message LIKE '%Msg 942,%')\\nORDER BY h.run_time ASC"}	{"condition": "row_count > 0", "description": "Jobs failed on startup day with database-not-ready errors"}	null	2026-02-23 20:18:31.389258
683	sqlserver	query	Check for enabled jobs with no schedule or all schedules disabled	{"sql": "SELECT j.name AS job_name, j.enabled AS job_enabled,\\n  j.date_modified,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysjobschedules jsc\\n   WHERE jsc.job_id = j.job_id) AS total_schedules,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysjobschedules jsc\\n   JOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\n   WHERE jsc.job_id = j.job_id AND s.enabled = 1) AS active_schedules\\nFROM msdb.dbo.sysjobs j\\nWHERE j.enabled = 1\\n  AND (\\n    NOT EXISTS (SELECT 1 FROM msdb.dbo.sysjobschedules jsc WHERE jsc.job_id = j.job_id)\\n    OR NOT EXISTS (\\n      SELECT 1 FROM msdb.dbo.sysjobschedules jsc\\n      JOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\n      WHERE jsc.job_id = j.job_id AND s.enabled = 1)\\n  )\\nORDER BY j.name"}	{"condition": "row_count > 0", "description": "Enabled jobs with no schedule or all schedules disabled"}	null	2026-02-23 20:18:31.389259
684	sqlserver	query	Verify these jobs have no next scheduled run and recent gap in history	{"sql": "SELECT j.name AS job_name,\\n  ja.next_scheduled_run_date,\\n  ja.run_requested_date AS last_run,\\n  DATEDIFF(day, ja.run_requested_date, GETDATE()) AS days_since_last_run\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND j.enabled = 1\\n  AND ja.next_scheduled_run_date IS NULL\\n  AND (ja.run_requested_date IS NULL\\n    OR ja.run_requested_date < DATEADD(day, -3, GETDATE()))\\nORDER BY ja.run_requested_date ASC"}	{"condition": "enabled jobs with NULL next_scheduled_run_date and no recent execution", "description": "Confirms job has no upcoming run and has been silent for days — schedule was likely deleted"}	null	2026-02-23 20:18:31.38926
685	sqlserver	query	Check for jobs with step-based dependencies or chaining via sp_start_job	{"sql": "SELECT j.name AS job_name, js.step_name, js.step_id,\\n  js.command,\\n  js.on_success_action, js.on_fail_action\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE j.enabled = 1\\n  AND (js.command LIKE '%sp_start_job%'\\n    OR js.command LIKE '%msdb.dbo.sp_start_job%'\\n    OR js.command LIKE '%EXEC @ReturnCode%sp_start_job%')\\nORDER BY j.name, js.step_id"}	{"condition": "row_count > 0", "description": "Jobs that chain to other jobs via sp_start_job — dependency relationships identified"}	null	2026-02-23 20:18:31.389261
686	sqlserver	query	Check if upstream chain jobs have recent failures	{"sql": "SELECT j.name AS upstream_job,\\n  h.run_status, h.run_date, h.run_time, h.message,\\n  CASE h.run_status\\n    WHEN 0 THEN 'FAILED'\\n    WHEN 1 THEN 'SUCCEEDED'\\n    WHEN 2 THEN 'RETRY'\\n    WHEN 3 THEN 'CANCELED'\\n    ELSE 'UNKNOWN' END AS status_desc\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.step_id = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND h.run_status IN (0, 3)\\n  AND EXISTS (\\n    SELECT 1 FROM msdb.dbo.sysjobsteps js2\\n    JOIN msdb.dbo.sysjobs j2 ON js2.job_id = j2.job_id\\n    WHERE j2.enabled = 1\\n      AND js2.command LIKE '%' + j.name + '%'\\n      AND js2.command LIKE '%sp_start_job%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "upstream jobs failed or were canceled recently", "description": "Prerequisite jobs in the chain have failed, preventing downstream job execution"}	null	2026-02-23 20:18:31.389262
838	sqlserver	query	Check for active index operations	{"sql": "SELECT r.session_id, r.command, r.percent_complete,\\n  r.total_elapsed_time / 60000 AS elapsed_minutes,\\n  r.estimated_completion_time / 60000 AS est_remaining_minutes,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  ips.index_id,\\n  ips.page_count * 8 / 1024 AS index_size_mb\\nFROM sys.dm_exec_requests r\\nLEFT JOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\n  ON r.database_id = DB_ID()\\nWHERE r.command IN ('ALTER INDEX', 'CREATE INDEX', 'DbccSpaceReclaim', 'DbccLOBCompact')\\nORDER BY r.total_elapsed_time DESC"}	{"condition": "row_count > 0", "description": "Active index build/rebuild operations consuming space"}	null	2026-02-23 20:18:31.389263
