1024	sqlserver	query	Check database compatibility levels vs engine version	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 AS engine_compat_level,\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 - d.compatibility_level AS compat_gap\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'\\n  AND d.compatibility_level < CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10"}	{"condition": "row_count > 0", "description": "Databases running at lower compatibility level than the engine version"}	null	2026-02-23 20:18:31.389295
689	sqlserver	query	Correlate unavailable databases with enabled job target databases	{"sql": "SELECT j.name AS job_name, js.step_name, js.step_id,\\n  js.database_name AS target_db,\\n  d.state_desc AS db_state, d.user_access_desc,\\n  ja.next_scheduled_run_date\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nJOIN sys.databases d ON js.database_name = d.name\\nLEFT JOIN msdb.dbo.sysjobactivity ja ON j.job_id = ja.job_id\\n  AND ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\nWHERE j.enabled = 1\\n  AND (d.state <> 0 OR d.user_access_desc = 'SINGLE_USER' OR d.is_in_standby = 1)\\nORDER BY j.name, js.step_id"}	{"condition": "enabled jobs target databases in non-ONLINE state", "description": "Confirms scheduled jobs will fail because their target databases are unavailable"}	null	2026-02-23 20:18:31.389264
691	sqlserver	query	Check for overdue scheduled jobs	{"sql": "SELECT j.name AS job_name,\\n  ja.next_scheduled_run_date,\\n  DATEDIFF(minute, ja.next_scheduled_run_date, GETDATE()) AS minutes_overdue,\\n  ja.run_requested_date AS last_run,\\n  ja.start_execution_date, ja.stop_execution_date\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nWHERE ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND j.enabled = 1\\n  AND ja.next_scheduled_run_date IS NOT NULL\\n  AND ja.next_scheduled_run_date < DATEADD(minute, -10, GETDATE())\\n  AND ja.start_execution_date IS NULL\\nORDER BY ja.next_scheduled_run_date ASC"}	{"condition": "row_count > 0 AND minutes_overdue > 10", "description": "Multiple enabled jobs with overdue next_scheduled_run_date not being started — Agent scheduler is hung"}	null	2026-02-23 20:18:31.389265
696	sqlserver	query	Check for stale statistics on tables in user databases	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  STATS_DATE(s.object_id, s.stats_id) AS last_updated,\\n  DATEDIFF(day, STATS_DATE(s.object_id, s.stats_id), GETDATE()) AS days_stale,\\n  sp.rows, sp.modification_counter,\\n  CASE WHEN sp.modification_counter > sp.rows * 0.2 THEN 'HIGH MODIFICATION'\\n    ELSE 'LOW MODIFICATION' END AS mod_status\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > sp.rows * 0.2\\n  AND sp.rows > 1000\\nORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0 AND days_stale > 7", "description": "Statistics with high modification rates relative to row count — optimizer may produce suboptimal plans"}	null	2026-02-23 20:18:31.389268
10857	mysql	query	Check adaptive flushing and I/O capacity settings	{"sql": "SELECT @@innodb_adaptive_flushing AS adaptive_flushing, @@innodb_io_capacity AS io_capacity, @@innodb_io_capacity_max AS io_capacity_max, @@innodb_adaptive_flushing_lwm AS adaptive_flushing_lwm"}	{"condition": "io_capacity_too_low_or_adaptive_off", "description": "Low I/O capacity settings limit how fast dirty pages can be flushed during checkpoint"}	\N	2026-03-01 06:30:58.706791
913	sqlserver	query	Check instant file initialization and trace flag status	{"sql": "SELECT servicename, instant_file_initialization_enabled\\nFROM sys.dm_server_services\\nWHERE servicename LIKE '%SQL Server%'\\nUNION ALL\\nSELECT 'TraceFlag_1117' AS servicename,\\n  CASE WHEN EXISTS (SELECT 1 FROM sys.dm_db_file_space_usage WHERE 1=0) THEN 'check_needed' ELSE 'N/A' END\\nFROM (SELECT 1 AS x) t"}	{"condition": "instant_file_initialization_enabled = 'N'", "description": "Instant file initialization disabled — data file growth zeroes out pages, causing I/O stalls"}	null	2026-02-23 20:18:31.389285
697	sqlserver	query	Check plan cache for regressed query plans on frequently executed queries	{"sql": "SELECT TOP 10\\n  qs.plan_handle,\\n  qs.execution_count,\\n  qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us,\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.creation_time AS plan_created,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.execution_count > 10\\n  AND qs.total_elapsed_time / qs.execution_count > 1000000\\n  AND qs.creation_time > DATEADD(day, -7, GETDATE())\\nORDER BY qs.total_elapsed_time / qs.execution_count DESC"}	{"condition": "recently created plans with high avg elapsed time (> 1 second)", "description": "New query plans with poor performance — indicates plan regression after recompilation with stale statistics"}	null	2026-02-23 20:18:31.389269
700	sqlserver	query	Check currently running Agent job sessions for blocking	{"sql": "SELECT s.session_id, s.program_name,\\n  r.status, r.command, r.wait_type, r.wait_time,\\n  r.blocking_session_id,\\n  r.total_elapsed_time / 1000 AS elapsed_sec,\\n  SUBSTRING(t.text, (r.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_requests r ON s.session_id = r.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE s.program_name LIKE 'SQLAgent - TSQL JobStep%'\\n  AND r.blocking_session_id <> 0\\nORDER BY r.wait_time DESC"}	{"condition": "row_count > 0", "description": "Agent job sessions are currently blocked by other sessions"}	null	2026-02-23 20:18:31.389271
701	sqlserver	query	Check lock wait statistics and blocking chain root	{"sql": "SELECT r.session_id AS blocked_session,\\n  r.blocking_session_id AS blocker,\\n  bs.program_name AS blocker_program,\\n  bs.login_name AS blocker_login,\\n  r.wait_type, r.wait_time / 1000 AS wait_sec,\\n  OBJECT_NAME(l.resource_associated_entity_id) AS locked_object\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions bs ON r.blocking_session_id = bs.session_id\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nLEFT JOIN sys.dm_tran_locks l ON r.session_id = l.request_session_id\\n  AND l.request_status = 'WAIT'\\nWHERE s.program_name LIKE 'SQLAgent - TSQL JobStep%'\\n  AND r.blocking_session_id <> 0\\nORDER BY r.wait_time DESC"}	{"condition": "blocking chains identified with Agent jobs as victims", "description": "Confirms Agent jobs are waiting on locks held by user sessions or other jobs"}	null	2026-02-23 20:18:31.389272
