4363	postgresql	query	Check for active sessions creating large temporary tables	{"sql": "SELECT pid, usename, query, now() - query_start AS duration, temp_blks_read, temp_blks_written FROM pg_stat_activity a LEFT JOIN pg_stat_statements s ON a.query = s.query WHERE a.state = 'active' AND (a.query ILIKE '%temp%' OR a.query ILIKE '%CREATE TEMP%') ORDER BY duration DESC"}	{"condition": "row_count > 0", "description": "Active sessions creating temporary tables found, contributing to disk space consumption"}	\N	2026-02-25 00:28:52.405273
3971	postgresql	query	Check for disconnected replication slots	{"sql": "SELECT slot_name, active, restart_lsn, pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) AS lag_bytes, (pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) / (1024*1024))::bigint AS lag_mb FROM pg_replication_slots WHERE slot_type = 'physical' AND active = false"}	{"condition": "row_count > 0 AND lag_mb > :lag_threshold_mb", "description": "Inactive physical slot with large lag confirms standby was offline"}	{"lag_threshold_mb": 256}	2026-02-25 00:28:52.405273
713	sqlserver	query	Check SQL Server missing index DMVs for high-impact candidates	{"sql": "SELECT TOP 20\\n  d.database_id, DB_NAME(d.database_id) AS database_name,\\n  d.equality_columns, d.inequality_columns, d.included_columns,\\n  OBJECT_NAME(d.object_id, d.database_id) AS table_name,\\n  gs.avg_user_impact,\\n  gs.user_seeks + gs.user_scans AS total_accesses,\\n  gs.avg_user_impact * (gs.user_seeks + gs.user_scans) AS improvement_score\\nFROM sys.dm_db_missing_index_details d\\nJOIN sys.dm_db_missing_index_groups g ON d.index_handle = g.index_handle\\nJOIN sys.dm_db_missing_index_group_stats gs ON g.index_group_handle = gs.group_handle\\nWHERE gs.avg_user_impact > 70\\n  AND (gs.user_seeks + gs.user_scans) > 100\\nORDER BY improvement_score DESC"}	{"condition": "improvement_score > 10000 AND avg_user_impact > 70", "description": "High-impact missing indexes that could dramatically reduce query execution time"}	null	2026-02-23 20:18:31.38928
3798	postgresql	query	Check maintenance user role attributes	{"sql": "SELECT rolname, rolsuper, rolcreatedb, rolcreaterole, rolcanlogin FROM pg_roles WHERE rolname = current_user"}	{"condition": "rolsuper = false", "description": "Non-superuser may lack permissions for some maintenance operations"}	\N	2026-02-25 00:28:52.405273
714	sqlserver	query	Correlate missing indexes with long-running job steps	{"sql": "SELECT j.name AS job_name, js.step_name,\\n  ((h.run_duration / 10000) * 3600 + ((h.run_duration % 10000) / 100) * 60 + (h.run_duration % 100)) AS duration_sec,\\n  js.database_name AS step_database,\\n  js.command\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.step_id > 0\\n  AND h.run_status = 1\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND ((h.run_duration / 10000) * 3600 + ((h.run_duration % 10000) / 100) * 60 + (h.run_duration % 100)) > 600\\n  AND js.database_name IN (\\n    SELECT DB_NAME(d.database_id)\\n    FROM sys.dm_db_missing_index_details d\\n    JOIN sys.dm_db_missing_index_groups g ON d.index_handle = g.index_handle\\n    JOIN sys.dm_db_missing_index_group_stats gs ON g.index_group_handle = gs.group_handle\\n    WHERE gs.avg_user_impact > 70 AND (gs.user_seeks + gs.user_scans) > 100\\n  )\\nORDER BY duration_sec DESC"}	{"condition": "long-running job steps operate on databases with high-impact missing indexes", "description": "Agent job steps target databases where missing indexes would provide 70%+ improvement"}	null	2026-02-23 20:18:31.389281
715	sqlserver	query	Check for Agent job steps using linked servers or remote paths	{"sql": "SELECT j.name AS job_name, js.step_id, js.step_name,\\n  js.subsystem, js.command,\\n  CASE\\n    WHEN js.command LIKE '%OPENQUERY%' OR js.command LIKE '%OPENROWSET%'\\n      OR js.command LIKE '%[[]%.%].%[[]%.%].%' THEN 'linked_server'\\n    WHEN js.command LIKE '%BACKUP%TO%DISK%=%''\\\\\\\\\\\\\\\\%' THEN 'remote_backup'\\n    WHEN js.command LIKE '%RESTORE%FROM%DISK%=%''\\\\\\\\\\\\\\\\%' THEN 'remote_restore'\\n    ELSE 'other_remote'\\n  END AS remote_type\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE js.command LIKE '%OPENQUERY%'\\n  OR js.command LIKE '%OPENROWSET%'\\n  OR js.command LIKE '%[[]%.%].%[[]%.%].%'\\n  OR js.command LIKE '%BACKUP%TO%DISK%=%''\\\\\\\\\\\\\\\\%'\\n  OR js.command LIKE '%RESTORE%FROM%DISK%=%''\\\\\\\\\\\\\\\\%'"}	{"condition": "row_count > 0", "description": "Agent job steps that access remote resources via linked servers or UNC paths"}	null	2026-02-23 20:18:31.389281
716	sqlserver	query	Check linked server query execution time and OLEDB waits	{"sql": "SELECT ls.name AS linked_server,\\n  ls.data_source, ls.provider,\\n  ws.wait_type, ws.wait_time_ms,\\n  ws.waiting_tasks_count,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.servers ls\\nCROSS JOIN sys.dm_os_wait_stats ws\\nWHERE ls.is_linked = 1\\n  AND ws.wait_type IN ('OLEDB', 'NETWORKIO', 'ASYNC_NETWORK_IO', 'PREEMPTIVE_OLEDBOPS')\\n  AND ws.waiting_tasks_count > 0\\nORDER BY ws.wait_time_ms DESC"}	{"condition": "OLEDB or NETWORKIO avg_wait_ms > 50", "description": "High OLEDB or network waits indicating remote access latency impacting job duration"}	null	2026-02-23 20:18:31.389282
717	sqlserver	query	Check for concurrent index rebuild or statistics update jobs	{"sql": "SELECT j.name AS job_name, ja.start_execution_date,\\n  DATEDIFF(minute, ja.start_execution_date, GETDATE()) AS running_minutes,\\n  js.command\\nFROM msdb.dbo.sysjobactivity ja\\nJOIN msdb.dbo.sysjobs j ON ja.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON ja.job_id = js.job_id AND ja.last_executed_step_id = js.step_id\\nWHERE ja.start_execution_date IS NOT NULL\\n  AND ja.stop_execution_date IS NULL\\n  AND ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\n  AND (js.command LIKE '%ALTER INDEX%REBUILD%'\\n    OR js.command LIKE '%UPDATE STATISTICS%'\\n    OR js.command LIKE '%REORGANIZE%'\\n    OR js.command LIKE '%sp_updatestats%'\\n    OR js.command LIKE '%IndexOptimize%'\\n    OR js.command LIKE '%Ola Hallengren%')"}	{"condition": "row_count > 0 while other jobs are running", "description": "Index maintenance or statistics update jobs running concurrently with other Agent jobs"}	null	2026-02-23 20:18:31.389283
725	sqlserver	query	Check for job steps with external call patterns	{"sql": "SELECT j.name AS job_name, js.step_id, js.step_name,\\n  js.subsystem,\\n  CASE\\n    WHEN js.subsystem = 'CmdExec' THEN 'OS command / xp_cmdshell'\\n    WHEN js.subsystem = 'SSIS' THEN 'SSIS package'\\n    WHEN js.subsystem = 'PowerShell' THEN 'PowerShell script'\\n    WHEN js.command LIKE '%OPENQUERY%' OR js.command LIKE '%OPENROWSET%' THEN 'Linked server query'\\n    WHEN js.command LIKE '%xp_cmdshell%' THEN 'xp_cmdshell call'\\n    WHEN js.command LIKE '%CLR%' OR js.command LIKE '%EXTERNAL%' THEN 'CLR / external'\\n    ELSE 'T-SQL with possible external'\\n  END AS external_call_type,\\n  js.command\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE js.subsystem IN ('CmdExec', 'SSIS', 'PowerShell')\\n  OR js.command LIKE '%OPENQUERY%'\\n  OR js.command LIKE '%OPENROWSET%'\\n  OR js.command LIKE '%xp_cmdshell%'\\n  OR js.command LIKE '%sp_OA%'"}	{"condition": "row_count > 0", "description": "Job steps that invoke external services or OS-level commands"}	null	2026-02-23 20:18:31.389288
726	sqlserver	query	Check execution history for external call steps with extended durations or failures	{"sql": "SELECT j.name AS job_name, js.step_name, js.subsystem,\\n  h.run_date, h.run_time, h.run_status,\\n  ((h.run_duration / 10000) * 3600 + ((h.run_duration % 10000) / 100) * 60 + (h.run_duration % 100)) AS duration_sec,\\n  h.message,\\n  h.retries_attempted\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nJOIN msdb.dbo.sysjobsteps js ON h.job_id = js.job_id AND h.step_id = js.step_id\\nWHERE h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (js.subsystem IN ('CmdExec', 'SSIS', 'PowerShell')\\n    OR js.command LIKE '%OPENQUERY%'\\n    OR js.command LIKE '%xp_cmdshell%')\\n  AND (h.run_status = 0\\n    OR h.retries_attempted > 0\\n    OR ((h.run_duration / 10000) * 3600 + ((h.run_duration % 10000) / 100) * 60 + (h.run_duration % 100)) > 600)\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "retries_attempted > 0 OR duration_sec > 600 OR run_status = 0", "description": "External call steps failing, retrying, or taking over 10 minutes suggesting external service delays"}	null	2026-02-23 20:18:31.389289
11513	mysql	config_check	Check for disabled InnoDB adaptive features	{"sql": "SELECT @@innodb_adaptive_hash_index AS ahi, @@innodb_adaptive_flushing AS af, @@innodb_change_buffering AS cb"}	{"condition": "ahi = 0 OR af = 0", "description": "InnoDB adaptive features disabled, possibly for perceived optimization"}	\N	2026-03-01 06:30:58.706791
743	sqlserver	query	Find jobs that start other jobs via sp_start_job in their steps	{"sql": "SELECT j.name AS parent_job,\\n  js.step_id, js.step_name,\\n  js.command,\\n  CASE\\n    WHEN js.command LIKE '%sp_start_job%' THEN\\n      SUBSTRING(js.command,\\n        CHARINDEX('''', js.command, CHARINDEX('sp_start_job', js.command)) + 1,\\n        CHARINDEX('''', js.command, CHARINDEX('''', js.command, CHARINDEX('sp_start_job', js.command)) + 1)\\n        - CHARINDEX('''', js.command, CHARINDEX('sp_start_job', js.command)) - 1\\n      )\\n    ELSE 'unknown'\\n  END AS child_job_name\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE j.enabled = 1\\n  AND js.command LIKE '%sp_start_job%'"}	{"condition": "row_count > 0", "description": "Jobs that trigger downstream jobs via sp_start_job, forming dependency chains"}	null	2026-02-23 20:18:31.3893
763	sqlserver	query	Check job failures with NULL-related error messages	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Cannot insert the value NULL%'\\n    OR h.message LIKE '%column does not allow nulls%'\\n    OR h.message LIKE '%null value%eliminated%'\\n    OR h.message LIKE '%Divide by zero%'\\n    OR h.message LIKE '%NULL%NOT NULL%'\\n    OR h.message LIKE '%NullReferenceException%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing because NULL values from source are not properly handled in transformation or target insert"}	null	2026-02-23 20:18:31.389303
3829	postgresql	query	Check for WAL sender CPU wait patterns	{"sql": "SELECT pid, application_name, state, wait_event_type, wait_event FROM pg_stat_activity WHERE backend_type = 'walsender' AND state = 'active'"}	{"condition": "row_count > 0", "description": "Active WAL senders — check if CPU-bound from compression"}	\N	2026-02-25 00:28:52.405273
841	sqlserver	query	Check for large tables that may need purging	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(ps.object_id) AS schema_name,\\n  OBJECT_NAME(ps.object_id) AS table_name,\\n  SUM(ps.row_count) AS total_rows,\\n  SUM(ps.reserved_page_count) * 8 / 1024 AS reserved_mb\\nFROM sys.dm_db_partition_stats ps\\nWHERE ps.index_id IN (0, 1)\\n  AND OBJECTPROPERTY(ps.object_id, 'IsUserTable') = 1\\nGROUP BY ps.object_id\\nHAVING SUM(ps.row_count) > 1000000\\nORDER BY reserved_mb DESC"}	{"condition": "large tables present alongside failed purge jobs", "description": "Tables with millions of rows likely accumulating due to failed cleanup jobs"}	null	2026-02-23 20:18:31.389361
755	sqlserver	query	Check recent ETL job failures with schema-related error messages	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time, h.run_status,\\n  h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Invalid column name%'\\n    OR h.message LIKE '%Invalid object name%'\\n    OR h.message LIKE '%column does not allow nulls%'\\n    OR h.message LIKE '%cannot be converted%'\\n    OR h.message LIKE '%Conversion failed%'\\n    OR h.message LIKE '%is not a recognized%'\\n    OR h.message LIKE '%Error at Source%'\\n    OR h.message LIKE '%column ordinal%'\\n    OR h.message LIKE '%metadata%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing with schema-related error messages indicating source drift"}	null	2026-02-23 20:18:31.389308
757	sqlserver	query	Check for ETL job failures with file-not-found or empty source errors	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time, h.run_status,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%file not found%'\\n    OR h.message LIKE '%cannot find the path%'\\n    OR h.message LIKE '%Could not find file%'\\n    OR h.message LIKE '%The system cannot find%'\\n    OR h.message LIKE '%does not exist%'\\n    OR h.message LIKE '%no data%'\\n    OR h.message LIKE '%0 rows%affected%'\\n    OR h.message LIKE '%empty%'\\n    OR h.message LIKE '%Access is denied%'\\n    OR h.message LIKE '%network path was not found%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing because source files or data were not available at expected locations"}	null	2026-02-23 20:18:31.389309
758	sqlserver	query	Check for SSIS package executions that failed with data source errors	{"sql": "SELECT e.execution_id, e.package_name, e.project_name,\\n  e.status, e.start_time, e.end_time,\\n  em.message_type, SUBSTRING(em.message, 1, 500) AS error_msg\\nFROM SSISDB.catalog.executions e\\nJOIN SSISDB.catalog.event_messages em ON e.execution_id = em.operation_id\\nWHERE e.status = 4\\n  AND e.start_time > DATEADD(day, -7, GETDATE())\\n  AND em.message_type = 120\\n  AND (em.message LIKE '%file%not found%'\\n    OR em.message LIKE '%source%missing%'\\n    OR em.message LIKE '%cannot open%'\\n    OR em.message LIKE '%does not exist%'\\n    OR em.message LIKE '%No data%'\\n    OR em.message LIKE '%empty result%')\\nORDER BY e.start_time DESC"}	{"condition": "row_count > 0", "description": "SSIS packages failing due to missing source files or empty data sources"}	null	2026-02-23 20:18:31.38931
759	sqlserver	query	Check job failures with connection-related error messages	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Login failed%'\\n    OR h.message LIKE '%Cannot open database%'\\n    OR h.message LIKE '%connection was forcibly closed%'\\n    OR h.message LIKE '%timeout%'\\n    OR h.message LIKE '%TCP Provider%'\\n    OR h.message LIKE '%Named Pipes Provider%'\\n    OR h.message LIKE '%network-related%'\\n    OR h.message LIKE '%linked server%'\\n    OR h.message LIKE '%OLE DB provider%'\\n    OR h.message LIKE '%A transport-level error%'\\n    OR h.message LIKE '%Communication link failure%'\\n    OR h.message LIKE '%General network error%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing with network, authentication, or connection timeout errors"}	null	2026-02-23 20:18:31.389311
760	sqlserver	query	Test linked server connectivity status	{"sql": "SELECT s.name AS linked_server,\\n  s.product, s.provider, s.data_source,\\n  s.is_linked, s.is_remote_login_enabled,\\n  ll.remote_name,\\n  s.modify_date,\\n  CASE WHEN s.is_linked = 1 THEN 'LINKED_SERVER' ELSE 'REMOTE_SERVER' END AS server_type\\nFROM sys.servers s\\nLEFT JOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nWHERE s.is_linked = 1\\nORDER BY s.name"}	{"condition": "linked servers exist that could be the source of connection failures", "description": "Linked servers configured for ETL source connectivity — test with sp_testlinkedserver"}	null	2026-02-23 20:18:31.389311
761	sqlserver	query	Check job failures with data type conversion error messages	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Conversion failed%'\\n    OR h.message LIKE '%cannot be converted%'\\n    OR h.message LIKE '%Arithmetic overflow%'\\n    OR h.message LIKE '%String or binary data would be truncated%'\\n    OR h.message LIKE '%Error converting data type%'\\n    OR h.message LIKE '%implicit conversion%'\\n    OR h.message LIKE '%out of range%'\\n    OR h.message LIKE '%is not a valid value%'\\n    OR h.message LIKE '%truncation%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing due to data type conversion, truncation, or overflow errors"}	null	2026-02-23 20:18:31.389312
762	sqlserver	query	Check SSIS execution logs for data conversion errors	{"sql": "SELECT e.execution_id, e.package_name, e.project_name,\\n  e.start_time, e.end_time,\\n  em.message_type,\\n  SUBSTRING(em.message, 1, 500) AS error_msg\\nFROM SSISDB.catalog.executions e\\nJOIN SSISDB.catalog.event_messages em ON e.execution_id = em.operation_id\\nWHERE e.status = 4\\n  AND e.start_time > DATEADD(day, -7, GETDATE())\\n  AND em.message_type IN (120, 130)\\n  AND (em.message LIKE '%Conversion%'\\n    OR em.message LIKE '%truncat%'\\n    OR em.message LIKE '%overflow%'\\n    OR em.message LIKE '%data type%'\\n    OR em.message LIKE '%type mismatch%')\\nORDER BY e.start_time DESC"}	{"condition": "row_count > 0", "description": "SSIS packages failing with data type mismatch during ETL transformation"}	null	2026-02-23 20:18:31.389312
764	sqlserver	query	Check target tables with NOT NULL constraints that ETL populates	{"sql": "SELECT t.name AS table_name,\\n  c.name AS column_name,\\n  c.is_nullable,\\n  ty.name AS data_type,\\n  dc.definition AS default_value\\nFROM sys.tables t\\nJOIN sys.columns c ON t.object_id = c.object_id\\nJOIN sys.types ty ON c.user_type_id = ty.user_type_id\\nLEFT JOIN sys.default_constraints dc ON c.default_object_id = dc.object_id\\nWHERE c.is_nullable = 0\\n  AND dc.object_id IS NULL\\n  AND c.is_identity = 0\\n  AND c.is_computed = 0\\n  AND t.name IN (\\n    SELECT DISTINCT PARSENAME(REPLACE(REPLACE(js.command, '[', ''), ']', ''), 1)\\n    FROM msdb.dbo.sysjobsteps js\\n    JOIN msdb.dbo.sysjobs j2 ON js.job_id = j2.job_id\\n    WHERE j2.enabled = 1\\n      AND (js.command LIKE '%INSERT%INTO%' OR js.command LIKE '%MERGE%')\\n  )\\nORDER BY t.name, c.column_id"}	{"condition": "NOT NULL columns without defaults in ETL target tables", "description": "Target tables have NOT NULL constraints without defaults that will reject NULL source values"}	null	2026-02-23 20:18:31.389313
765	sqlserver	query	Check job failures with transformation logic error messages	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Divide by zero%'\\n    OR h.message LIKE '%Subquery returned more than 1 value%'\\n    OR h.message LIKE '%ambiguous column%'\\n    OR h.message LIKE '%Incorrect syntax%'\\n    OR h.message LIKE '%String or binary data would be truncated%'\\n    OR h.message LIKE '%Arithmetic overflow%'\\n    OR h.message LIKE '%multi-part identifier%could not be bound%'\\n    OR h.message LIKE '%Msg 8134%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing due to transformation logic errors in SQL or SSIS expressions"}	null	2026-02-23 20:18:31.389314
767	sqlserver	query	Check job failures with constraint violation error messages	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message,\\n  CASE\\n    WHEN h.message LIKE '%PRIMARY KEY%' THEN 'PK_VIOLATION'\\n    WHEN h.message LIKE '%UNIQUE%' THEN 'UNIQUE_VIOLATION'\\n    WHEN h.message LIKE '%FOREIGN KEY%' THEN 'FK_VIOLATION'\\n    WHEN h.message LIKE '%CHECK constraint%' THEN 'CHECK_VIOLATION'\\n    WHEN h.message LIKE '%Cannot insert the value NULL%' THEN 'NOT_NULL_VIOLATION'\\n    ELSE 'OTHER_CONSTRAINT'\\n  END AS violation_type\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Violation of PRIMARY KEY%'\\n    OR h.message LIKE '%Violation of UNIQUE KEY%'\\n    OR h.message LIKE '%FOREIGN KEY constraint%'\\n    OR h.message LIKE '%CHECK constraint%'\\n    OR h.message LIKE '%Cannot insert duplicate key%'\\n    OR h.message LIKE '%Cannot insert the value NULL%'\\n    OR h.message LIKE '%conflicted with the%constraint%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL load steps failing due to constraint violations on target tables"}	null	2026-02-23 20:18:31.389315
768	sqlserver	query	Identify target tables and their constraint configuration	{"sql": "SELECT t.name AS table_name,\\n  i.name AS constraint_name,\\n  i.type_desc AS constraint_type,\\n  i.is_unique,\\n  i.is_primary_key,\\n  i.is_unique_constraint,\\n  STRING_AGG(c.name, ', ') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_columns,\\n  (SELECT COUNT(*) FROM sys.foreign_keys fk WHERE fk.referenced_object_id = t.object_id) AS incoming_fk_count\\nFROM sys.tables t\\nJOIN sys.indexes i ON t.object_id = i.object_id\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nWHERE (i.is_primary_key = 1 OR i.is_unique_constraint = 1 OR i.is_unique = 1)\\n  AND t.is_ms_shipped = 0\\nGROUP BY t.name, i.name, i.type_desc, i.is_unique, i.is_primary_key, i.is_unique_constraint, t.object_id\\nORDER BY t.name, i.name"}	{"condition": "tables with PK/unique/FK constraints that ETL targets", "description": "Target tables with constraints that will reject duplicate or invalid data from ETL"}	null	2026-02-23 20:18:31.389316
769	sqlserver	query	Check for ETL job failures with lock/deadlock error messages	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%deadlock%'\\n    OR h.message LIKE '%lock request time out%'\\n    OR h.message LIKE '%Could not obtain a lock%'\\n    OR h.message LIKE '%Msg 1205%'\\n    OR h.message LIKE '%Msg 1222%'\\n    OR h.message LIKE '%Lock Wait%'\\n    OR h.message LIKE '%was deadlocked on lock resources%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing due to lock timeouts or deadlocks on target tables"}	null	2026-02-23 20:18:31.389316
4837	postgresql	config_check	Check deadlock detection interval	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name = 'deadlock_timeout'"}	{"condition": "deadlock_timeout < 1000", "description": "Low deadlock_timeout causes more frequent deadlock detection scans"}	\N	2026-02-25 00:28:52.405273
770	sqlserver	query	Check current blocking chains and lock waits	{"sql": "SELECT\\n  r.session_id AS blocked_session,\\n  r.blocking_session_id AS blocker_session,\\n  r.wait_type, r.wait_time / 1000 AS wait_sec,\\n  r.status,\\n  DB_NAME(r.database_id) AS database_name,\\n  SUBSTRING(t.text, (r.statement_start_offset / 2) + 1, 100) AS blocked_query,\\n  s.program_name AS blocked_program,\\n  bs.program_name AS blocker_program,\\n  bs.login_name AS blocker_login\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nLEFT JOIN sys.dm_exec_sessions bs ON r.blocking_session_id = bs.session_id\\nWHERE r.blocking_session_id <> 0\\nORDER BY r.wait_time DESC"}	{"condition": "Agent job sessions blocked by other processes", "description": "Active blocking chains where SQL Agent sessions are waiting on locks held by concurrent processes"}	null	2026-02-23 20:18:31.389317
771	sqlserver	query	Check for ETL job failures with timeout or resource throttling errors	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Timeout expired%'\\n    OR h.message LIKE '%Execution Timeout%'\\n    OR h.message LIKE '%query wait%exceeded%'\\n    OR h.message LIKE '%resource pool%'\\n    OR h.message LIKE '%insufficient system memory%'\\n    OR h.message LIKE '%Msg 845%'\\n    OR h.message LIKE '%BULK INSERT%'\\n    OR h.message LIKE '%bcp%error%'\\n    OR h.message LIKE '%The transaction log%is full%'\\n    OR h.message LIKE '%not enough memory%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing from timeouts, memory pressure, or log-full conditions during bulk writes"}	null	2026-02-23 20:18:31.389318
775	sqlserver	query	Check job failures with HTTP error or rate limit patterns in messages	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%429%'\\n    OR h.message LIKE '%Too Many Requests%'\\n    OR h.message LIKE '%rate limit%'\\n    OR h.message LIKE '%throttl%'\\n    OR h.message LIKE '%503%'\\n    OR h.message LIKE '%Service Unavailable%'\\n    OR h.message LIKE '%Retry-After%'\\n    OR h.message LIKE '%quota%exceeded%'\\n    OR h.message LIKE '%HTTP%error%'\\n    OR h.message LIKE '%API%limit%'\\n    OR h.message LIKE '%request limit%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Job failures with HTTP 429/503 or rate-limit error patterns in job history messages"}	null	2026-02-23 20:18:31.389321
906	sqlserver	query	Check page verification option for all databases	{"sql": "SELECT name, page_verify_option_desc, state_desc FROM sys.databases WHERE page_verify_option_desc <> 'CHECKSUM' AND database_id > 4 AND state = 0"}	{"condition": "row_count > 0", "description": "Databases not using CHECKSUM page verification — TORN_PAGE_DETECTION or NONE provides weaker protection"}	null	2026-02-23 20:18:31.389322
776	sqlserver	query	Check for job steps that invoke external APIs via CLR, xp_cmdshell, or SSIS	{"sql": "SELECT j.name AS job_name, js.step_id, js.step_name,\\n  js.subsystem,\\n  CASE\\n    WHEN js.subsystem = 'CmdExec' THEN 'xp_cmdshell/CmdExec'\\n    WHEN js.subsystem = 'SSIS' THEN 'SSIS Package'\\n    WHEN js.subsystem = 'PowerShell' THEN 'PowerShell'\\n    WHEN js.command LIKE '%http%' OR js.command LIKE '%WebRequest%'\\n      OR js.command LIKE '%Invoke-RestMethod%' OR js.command LIKE '%curl%'\\n      THEN 'HTTP call in command'\\n    ELSE js.subsystem\\n  END AS api_call_type,\\n  SUBSTRING(js.command, 1, 300) AS command_preview\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE j.enabled = 1\\n  AND (js.subsystem IN ('CmdExec', 'PowerShell')\\n    OR js.command LIKE '%http%'\\n    OR js.command LIKE '%WebRequest%'\\n    OR js.command LIKE '%Invoke-RestMethod%'\\n    OR js.command LIKE '%curl%'\\n    OR js.command LIKE '%WebServiceTask%'\\n    OR js.command LIKE '%HttpConnection%'\\n    OR js.command LIKE '%REST%'\\n    OR js.command LIKE '%API%')\\nORDER BY j.name, js.step_id"}	{"condition": "job steps that invoke external HTTP/REST APIs", "description": "Agent jobs contain steps calling external APIs that are subject to rate limiting"}	null	2026-02-23 20:18:31.389322
779	sqlserver	query	Check job failures with constraint or validation error messages	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%CHECK constraint%'\\n    OR h.message LIKE '%conflicted with the CHECK%'\\n    OR h.message LIKE '%validation%fail%'\\n    OR h.message LIKE '%RAISERROR%'\\n    OR h.message LIKE '%is not valid%'\\n    OR h.message LIKE '%rejected%'\\n    OR h.message LIKE '%data validation%'\\n    OR h.message LIKE '%business rule%'\\n    OR h.message LIKE '%trigger%'\\n    OR h.message LIKE '%INSTEAD OF%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing because data validation rules rejected source records"}	null	2026-02-23 20:18:31.389324
1594	sqlserver	query	Check for statistics update waits blocking queries	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('WAIT_ON_SYNC_STATISTICS_REFRESH',\\n  'AUTO_STATS', 'ASYNC_STATS_UPDATE_WAIT')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "WAIT_ON_SYNC_STATISTICS_REFRESH or AUTO_STATS waits present", "description": "Queries blocking on synchronous statistics refresh operations"}	null	2026-02-23 20:18:31.389837
780	sqlserver	query	Check CHECK constraints and validation triggers on target tables	{"sql": "SELECT t.name AS table_name,\\n  cc.name AS check_constraint,\\n  cc.definition AS check_expression,\\n  cc.is_not_trusted,\\n  (SELECT COUNT(*) FROM sys.triggers tr WHERE tr.parent_id = t.object_id AND tr.is_disabled = 0) AS active_trigger_count\\nFROM sys.tables t\\nJOIN sys.check_constraints cc ON t.object_id = cc.parent_object_id\\nWHERE cc.is_disabled = 0\\n  AND t.is_ms_shipped = 0\\nUNION ALL\\nSELECT OBJECT_NAME(tr.parent_id) AS table_name,\\n  tr.name AS trigger_name,\\n  'TRIGGER: ' + SUBSTRING(sm.definition, 1, 200),\\n  0, 0\\nFROM sys.triggers tr\\nJOIN sys.sql_modules sm ON tr.object_id = sm.object_id\\nWHERE tr.is_disabled = 0\\n  AND (sm.definition LIKE '%RAISERROR%' OR sm.definition LIKE '%THROW%'\\n    OR sm.definition LIKE '%ROLLBACK%')\\nORDER BY table_name"}	{"condition": "CHECK constraints or validation triggers on ETL target tables", "description": "Active validation rules on target tables that can reject ETL data"}	null	2026-02-23 20:18:31.389325
3972	postgresql	query	Verify standby not currently connected	{"sql": "SELECT count(*) AS connected_standbys FROM pg_stat_replication WHERE state = 'streaming'"}	{"condition": "connected_standbys < (SELECT count(*) FROM pg_replication_slots WHERE slot_type = 'physical')", "description": "Fewer streaming connections than slots confirms missing standby"}	\N	2026-02-25 00:28:52.405273
1027	sqlserver	query	Count databases without Query Store for severity assessment	{"sql": "SELECT\\n  COUNT(*) AS total_user_dbs,\\n  SUM(CASE WHEN is_query_store_on = 0 THEN 1 ELSE 0 END) AS dbs_without_qs,\\n  SUM(CASE WHEN is_query_store_on = 1 THEN 1 ELSE 0 END) AS dbs_with_qs,\\n  CAST(SUM(CASE WHEN is_query_store_on = 0 THEN 1 ELSE 0 END) AS FLOAT)\\n    / NULLIF(COUNT(*), 0) * 100 AS pct_without_qs\\nFROM sys.databases\\nWHERE database_id > 4\\n  AND state_desc = 'ONLINE'"}	{"condition": "dbs_without_qs > 0", "description": "Databases without Query Store cannot provide query performance baselines for pre/post patch comparison"}	null	2026-02-23 20:18:31.389325
853	sqlserver	query	Check for active index rebuild operations	{"sql": "SELECT r.session_id, r.command, r.percent_complete,\\n  r.total_elapsed_time / 60000 AS elapsed_min,\\n  r.estimated_completion_time / 60000 AS est_remaining_min,\\n  r.wait_type,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE r.command IN ('ALTER INDEX', 'CREATE INDEX')"}	{"condition": "row_count > 0", "description": "Active index rebuild or create operations"}	null	2026-02-23 20:18:31.389369
783	sqlserver	query	Check for ETL job failures with memory-related errors	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%insufficient memory%'\\n    OR h.message LIKE '%memory grant%'\\n    OR h.message LIKE '%Could not allocate%'\\n    OR h.message LIKE '%out of memory%'\\n    OR h.message LIKE '%Msg 701%'\\n    OR h.message LIKE '%Msg 8645%'\\n    OR h.message LIKE '%RESOURCE_SEMAPHORE%'\\n    OR h.message LIKE '%memory pressure%'\\n    OR h.message LIKE '%System.OutOfMemoryException%'\\n    OR h.message LIKE '%buffer%exceeded%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing with memory allocation errors or out-of-memory exceptions"}	null	2026-02-23 20:18:31.389327
784	sqlserver	query	Check memory grant waits and spills to tempdb	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants\\n   WHERE grant_time IS NULL) AS pending_grants,\\n  (SELECT SUM(ideal_memory_kb - granted_memory_kb) / 1024\\n   FROM sys.dm_exec_query_memory_grants\\n   WHERE granted_memory_kb < ideal_memory_kb AND granted_memory_kb > 0) AS memory_deficit_mb,\\n  ws.wait_type, ws.waiting_tasks_count, ws.wait_time_ms,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type IN ('RESOURCE_SEMAPHORE', 'RESOURCE_SEMAPHORE_QUERY_COMPILE',\\n  'RESOURCE_SEMAPHORE_SMALL_QUERY')\\n  AND ws.waiting_tasks_count > 0"}	{"condition": "pending_grants > 0 OR RESOURCE_SEMAPHORE waits present", "description": "Memory grant contention — queries waiting for memory allocation to execute"}	null	2026-02-23 20:18:31.389328
785	sqlserver	query	Check for sort/hash spills to tempdb from memory-starved queries	{"sql": "SELECT TOP 15\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1, 200) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_spills > 0\\n  AND qs.last_execution_time > DATEADD(day, -7, GETDATE())\\nORDER BY avg_spills DESC"}	{"condition": "avg_spills > 100 OR avg_grant_kb << avg_ideal_kb", "description": "ETL queries spilling to tempdb due to insufficient memory grants, degrading performance"}	null	2026-02-23 20:18:31.389329
786	sqlserver	query	Check for ETL job failures with disk space or file growth errors	{"sql": "SELECT j.name AS job_name, h.step_id, h.step_name,\\n  h.run_date, h.run_time,\\n  SUBSTRING(h.message, 1, 500) AS error_message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.run_status = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (h.message LIKE '%Could not allocate space%'\\n    OR h.message LIKE '%disk is full%'\\n    OR h.message LIKE '%filegroup is full%'\\n    OR h.message LIKE '%maximum size%reached%'\\n    OR h.message LIKE '%autogrow%'\\n    OR h.message LIKE '%There is not enough space%'\\n    OR h.message LIKE '%The transaction log%is full%'\\n    OR h.message LIKE '%Msg 1105%'\\n    OR h.message LIKE '%Msg 9002%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "ETL jobs failing due to disk space exhaustion or file growth limits"}	null	2026-02-23 20:18:31.389329
1034	sqlserver	query	Check dangerous surface area configurations	{"sql": "SELECT name, CAST(value_in_use AS INT) AS is_enabled,\\n  description\\nFROM sys.configurations\\nWHERE name IN (\\n  'xp_cmdshell',\\n  'clr enabled',\\n  'clr strict security',\\n  'Ole Automation Procedures',\\n  'external scripts enabled',\\n  'Ad Hoc Distributed Queries',\\n  'Database Mail XPs'\\n)\\n  AND CAST(value_in_use AS INT) <> CASE\\n    WHEN name = 'clr strict security' THEN 1\\n    ELSE 0\\n  END"}	{"condition": "row_count > 0", "description": "External access features enabled — increases attack surface when unpatched"}	null	2026-02-23 20:18:31.389331
7864	oracle	query	ora_check_restricted_session_mode [HLTH-SQL-UP-004-RC21]	{"sql": "SELECT logins FROM v$instance"}	{"condition": "logins = 'RESTRICTED'", "description": "Database should be in restricted session mode during upgrades to prevent user connections"}	\N	2026-02-28 12:19:19.580455
789	sqlserver	query	Check database size growth by comparing current size to allocated space	{"sql": "SELECT d.name AS database_name,\\n  SUM(mf.size * 8.0 / 1024) AS total_size_mb,\\n  SUM(CASE WHEN mf.type = 0 THEN mf.size * 8.0 / 1024 ELSE 0 END) AS data_size_mb,\\n  SUM(CASE WHEN mf.type = 0\\n    THEN FILEPROPERTY(mf.name, 'SpaceUsed') * 8.0 / 1024 ELSE 0 END) AS data_used_mb,\\n  SUM(CASE WHEN mf.type = 0\\n    THEN (mf.size - FILEPROPERTY(mf.name, 'SpaceUsed')) * 8.0 / 1024 ELSE 0 END) AS data_free_mb,\\n  CASE WHEN SUM(CASE WHEN mf.type = 0 THEN mf.size ELSE 0 END) > 0\\n    THEN CAST(SUM(CASE WHEN mf.type = 0 THEN FILEPROPERTY(mf.name, 'SpaceUsed') ELSE 0 END) * 100.0\\n      / SUM(CASE WHEN mf.type = 0 THEN mf.size ELSE 0 END) AS decimal(5,1))\\n    ELSE 0 END AS data_pct_used\\nFROM sys.databases d\\nJOIN sys.master_files mf ON d.database_id = mf.database_id\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'\\nGROUP BY d.name\\nHAVING SUM(CASE WHEN mf.type = 0 THEN mf.size * 8.0 / 1024 ELSE 0 END) > 1024\\nORDER BY data_used_mb DESC"}	{"condition": "data_pct_used > 85 AND data_used_mb > 1024", "description": "Large databases with data files more than 85% full, indicating sustained growth"}	null	2026-02-23 20:18:31.389332
3973	postgresql	log_scan	Check server logs for recovery events	{"sql": "SELECT pg_current_wal_lsn() AS current_lsn, pg_walfile_name(pg_current_wal_lsn()) AS current_wal"}	{"condition": "current_wal IS NOT NULL", "description": "Verify WAL position is accessible to correlate with timeline"}	\N	2026-02-25 00:28:52.405273
791	sqlserver	query	Check volume free space to assess urgency	{"sql": "SELECT DISTINCT\\n  vs.volume_mount_point,\\n  vs.logical_volume_name,\\n  CAST(vs.total_bytes / 1073741824.0 AS decimal(18,2)) AS total_gb,\\n  CAST(vs.available_bytes / 1073741824.0 AS decimal(18,2)) AS available_gb,\\n  CAST((vs.total_bytes - vs.available_bytes) * 100.0 / vs.total_bytes AS decimal(5,1)) AS pct_used\\nFROM sys.master_files mf\\nCROSS APPLY sys.dm_os_volume_stats(mf.database_id, mf.file_id) vs\\nWHERE CAST((vs.total_bytes - vs.available_bytes) * 100.0 / vs.total_bytes AS decimal(5,1)) > 80\\nORDER BY pct_used DESC"}	{"condition": "pct_used > 80", "description": "Volume over 80% used — data growth without archiving is approaching capacity limit"}	null	2026-02-23 20:18:31.389333
834	sqlserver	query	Check tempdb space usage by active tasks for spills	{"sql": "SELECT t.session_id,\\n  t.internal_objects_alloc_page_count * 8 / 1024 AS internal_alloc_mb,\\n  t.internal_objects_dealloc_page_count * 8 / 1024 AS internal_dealloc_mb,\\n  (t.internal_objects_alloc_page_count - t.internal_objects_dealloc_page_count) * 8 / 1024 AS internal_current_mb,\\n  r.command, r.wait_type,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1, 100) AS query_fragment\\nFROM sys.dm_db_task_space_usage t\\nJOIN sys.dm_exec_requests r ON t.session_id = r.session_id AND t.request_id = r.request_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE t.internal_objects_alloc_page_count > 1000\\nORDER BY t.internal_objects_alloc_page_count DESC"}	{"condition": "row_count > 0 AND internal_current_mb > 100", "description": "Active queries spilling significant data to tempdb internal objects"}	null	2026-02-23 20:18:31.389336
4260	postgresql	query	Check for jobs that have never successfully run	{"sql": "SELECT j.jobid, j.schedule, j.command FROM cron.job j LEFT JOIN cron.job_run_details d ON j.jobid = d.jobid AND d.status = 'succeeded' WHERE j.active = true GROUP BY j.jobid, j.schedule, j.command HAVING count(d.runid) = 0"}	{"condition": "row_count > 0", "description": "Active jobs with zero successful runs may have invalid schedule expressions"}	\N	2026-02-25 00:28:52.405273
813	sqlserver	query	Check for databases in unusual states with files still on disk	{"sql": "SELECT d.name AS database_name,\\n  d.state_desc,\\n  d.create_date,\\n  mf.physical_name,\\n  mf.type_desc,\\n  mf.size * 8.0 / 1024 AS file_size_mb\\nFROM sys.databases d\\nJOIN sys.master_files mf ON d.database_id = mf.database_id\\nWHERE d.state_desc IN ('OFFLINE', 'RESTORING', 'RECOVERING', 'SUSPECT')\\n  OR (d.state_desc = 'ONLINE'\\n    AND d.is_read_only = 1\\n    AND d.create_date < DATEADD(year, -1, GETDATE()))\\nORDER BY mf.size DESC"}	{"condition": "row_count > 0", "description": "Databases in OFFLINE/RESTORING/SUSPECT state or very old read-only databases with files still consuming disk"}	null	2026-02-23 20:18:31.389347
803	sqlserver	query	Check for recent backup failures in SQL Agent job history	{"sql": "SELECT j.name AS job_name,\\n  h.run_date, h.run_time,\\n  h.run_status,\\n  CASE h.run_status WHEN 0 THEN 'Failed' WHEN 1 THEN 'Succeeded'\\n    WHEN 2 THEN 'Retry' WHEN 3 THEN 'Canceled' END AS status_desc,\\n  h.message\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.step_id = 0\\n  AND h.run_status IN (0, 3)\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND (j.name LIKE '%backup%' OR j.name LIKE '%Backup%'\\n    OR j.name LIKE '%BACKUP%' OR j.name LIKE '%archive%'\\n    OR j.name LIKE '%maintenance%')\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Backup or maintenance jobs have failed in the last 7 days"}	null	2026-02-23 20:18:31.389341
