807	sqlserver	query	Check for databases where log truncation is blocked by replication	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  d.recovery_model_desc,\\n  ls.total_log_size_in_bytes / 1048576.0 AS log_size_mb,\\n  ls.used_log_space_in_percent AS log_pct_used\\nFROM sys.databases d\\nJOIN sys.dm_db_log_space_usage ls ON d.database_id = ls.database_id\\nWHERE d.log_reuse_wait_desc IN ('REPLICATION', 'AVAILABILITY_REPLICA')\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "log_reuse_wait_desc IN ('REPLICATION', 'AVAILABILITY_REPLICA')", "description": "Transaction log truncation blocked by replication or AG — log cannot be reused"}	null	2026-02-23 20:18:31.389343
4261	postgresql	query	Check for long-running job instances	{"sql": "SELECT jobid, runid, job_pid, status, start_time, NOW() - start_time AS running_duration FROM cron.job_run_details WHERE status = 'running' AND NOW() - start_time > interval ':threshold_minutes minutes'"}	{"condition": "row_count > 0", "description": "Currently running job that may be blocking the next scheduled execution"}	{"threshold_minutes": 30}	2026-02-25 00:28:52.405273
4504	postgresql	process	Check filesystem mount options and scheduler	{"command": "mount | grep -E 'pgdata|postgres|pgsql' && cat /sys/block/sda/queue/scheduler"}	{"condition": "output_contains_info", "description": "Mount options without noatime, wrong I/O scheduler (cfq on SSD), or barrier issues indicate storage misconfiguration"}	\N	2026-02-25 00:28:52.405273
814	sqlserver	query	Check for old backup files referenced in backup history	{"sql": "SELECT bmf.physical_device_name,\\n  bs.database_name,\\n  bs.backup_finish_date,\\n  DATEDIFF(day, bs.backup_finish_date, GETDATE()) AS age_days,\\n  bs.backup_size / 1073741824.0 AS backup_size_gb,\\n  bs.compressed_backup_size / 1073741824.0 AS compressed_size_gb,\\n  bs.type AS backup_type\\nFROM msdb.dbo.backupset bs\\nJOIN msdb.dbo.backupmediafamily bmf ON bs.media_set_id = bmf.media_set_id\\nWHERE bs.backup_finish_date < DATEADD(day, -90, GETDATE())\\n  AND bmf.physical_device_name LIKE '%.bak'\\nORDER BY bs.backup_finish_date ASC"}	{"condition": "age_days > 90", "description": "Backup files older than 90 days still referenced — likely still on disk consuming space"}	null	2026-02-23 20:18:31.389348
815	sqlserver	query	Check for active sessions with high transaction log usage	{"sql": "SELECT s.session_id,\\n  s.login_name,\\n  s.host_name,\\n  s.program_name,\\n  tdt.database_transaction_log_bytes_used / 1048576.0 AS log_used_mb,\\n  tdt.database_transaction_log_bytes_reserved / 1048576.0 AS log_reserved_mb,\\n  tst.open_transaction_count,\\n  t.text AS current_query,\\n  r.command,\\n  r.percent_complete\\nFROM sys.dm_tran_session_transactions tst\\nJOIN sys.dm_tran_database_transactions tdt ON tst.transaction_id = tdt.transaction_id\\nJOIN sys.dm_exec_sessions s ON tst.session_id = s.session_id\\nLEFT JOIN sys.dm_exec_requests r ON s.session_id = r.session_id\\nOUTER APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE tdt.database_transaction_log_bytes_used > 104857600\\nORDER BY tdt.database_transaction_log_bytes_used DESC"}	{"condition": "log_used_mb > 100", "description": "Active transactions using over 100 MB of transaction log — likely bulk operations"}	null	2026-02-23 20:18:31.389348
4137	postgresql	query	Check connected client sources for load balancer IPs	{"sql": "SELECT client_addr, application_name, count(*) AS sessions FROM pg_stat_activity WHERE backend_type = 'client backend' GROUP BY client_addr, application_name ORDER BY sessions DESC"}	{"condition": "row_count > 0", "description": "Review connection sources; load balancer IPs appearing on multiple primaries confirms misconfiguration"}	\N	2026-02-25 00:28:52.405273
816	sqlserver	query	Check for BULK_LOGGED recovery model usage and bulk operation indicators	{"sql": "SELECT d.name AS database_name,\\n  d.recovery_model_desc,\\n  ls.total_log_size_in_bytes / 1048576.0 AS log_size_mb,\\n  ls.used_log_space_in_percent,\\n  d.log_reuse_wait_desc,\\n  r.command,\\n  r.status,\\n  r.percent_complete,\\n  r.estimated_completion_time / 60000 AS est_remaining_min\\nFROM sys.databases d\\nJOIN sys.dm_db_log_space_usage ls ON d.database_id = ls.database_id\\nLEFT JOIN sys.dm_exec_requests r ON d.database_id = r.database_id\\n  AND r.command IN ('BULK INSERT', 'INSERT', 'SELECT INTO', 'BACKUP DATABASE', 'RESTORE DATABASE')\\nWHERE d.database_id > 4\\n  AND (ls.used_log_space_in_percent > 70\\n    OR d.log_reuse_wait_desc = 'ACTIVE_TRANSACTION')\\nORDER BY ls.used_log_space_in_percent DESC"}	{"condition": "log_pct_used > 70 AND active BULK INSERT/SELECT INTO commands", "description": "Large bulk operations consuming transaction log space and blocking log truncation"}	null	2026-02-23 20:18:31.389349
817	sqlserver	query	Check for database snapshots and their sparse file sizes	{"sql": "SELECT snap.name AS snapshot_name,\\n  snap.source_database_id,\\n  src.name AS source_database,\\n  snap.create_date AS snapshot_created,\\n  DATEDIFF(day, snap.create_date, GETDATE()) AS age_days,\\n  mf.physical_name AS sparse_file_path,\\n  mf.size * 8.0 / 1024 AS allocated_size_mb\\nFROM sys.databases snap\\nJOIN sys.databases src ON snap.source_database_id = src.database_id\\nJOIN sys.master_files mf ON snap.database_id = mf.database_id AND mf.type = 0\\nWHERE snap.source_database_id IS NOT NULL\\n  AND snap.source_database_id > 0\\nORDER BY snap.create_date ASC"}	{"condition": "row_count > 3 OR age_days > 30", "description": "Multiple snapshots exist or old snapshots have been abandoned"}	null	2026-02-23 20:18:31.38935
818	sqlserver	query	Check snapshot sparse file growth relative to source database	{"sql": "SELECT snap.name AS snapshot_name,\\n  src.name AS source_database,\\n  DATEDIFF(day, snap.create_date, GETDATE()) AS age_days,\\n  SUM(snap_mf.size * 8.0 / 1024) AS snapshot_allocated_mb,\\n  SUM(src_mf.size * 8.0 / 1024) AS source_data_size_mb,\\n  CASE WHEN SUM(src_mf.size) > 0\\n    THEN CAST(SUM(snap_mf.size) * 100.0 / SUM(src_mf.size) AS decimal(5,1))\\n    ELSE 0 END AS snapshot_pct_of_source\\nFROM sys.databases snap\\nJOIN sys.databases src ON snap.source_database_id = src.database_id\\nJOIN sys.master_files snap_mf ON snap.database_id = snap_mf.database_id AND snap_mf.type = 0\\nJOIN sys.master_files src_mf ON src.database_id = src_mf.database_id AND src_mf.type = 0\\nWHERE snap.source_database_id IS NOT NULL\\n  AND snap.source_database_id > 0\\nGROUP BY snap.name, src.name, snap.create_date\\nHAVING SUM(snap_mf.size * 8.0 / 1024) > 500\\n  OR DATEDIFF(day, snap.create_date, GETDATE()) > 30\\nORDER BY snapshot_allocated_mb DESC"}	{"condition": "snapshot_allocated_mb > 500 OR age_days > 30", "description": "Snapshot sparse files are large or snapshots are old — likely abandoned and consuming significant disk space"}	null	2026-02-23 20:18:31.38935
3611	postgresql	query	Check for password expiration settings	{"sql": "SELECT rolname, rolvaliduntil FROM pg_roles WHERE rolcanlogin = true AND (rolvaliduntil IS NULL OR rolvaliduntil > now() + interval '365 days') AND rolname NOT IN ('postgres') ORDER BY rolname"}	{"condition": "row_count > 0", "description": "Login roles without password expiration — no mandatory rotation"}	\N	2026-02-25 00:28:52.405273
884	sqlserver	query	Check for active DBCC operations	{"sql": "SELECT r.session_id, r.command, r.percent_complete, r.total_elapsed_time / 60000 AS elapsed_minutes, r.estimated_completion_time / 60000 AS est_remaining_minutes, DB_NAME(r.database_id) AS target_database, SUBSTRING(t.text, 1, 200) AS command_text FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE r.command LIKE 'DBCC%'"}	{"condition": "row_count > 0 with DBCC commands active", "description": "Active DBCC CHECKDB or related operations running"}	null	2026-02-23 20:18:31.389389
