3853	postgresql	config_check	Check pg_hba.conf replication entries	{"sql": "SELECT type, database, user_name, address, auth_method FROM pg_hba_file_rules WHERE database::text LIKE '%replication%' ORDER BY line_number"}	{"condition": "row_count > 0", "description": "Replication HBA rules exist — verify they match standby addresses"}	\N	2026-02-25 00:28:52.405273
839	sqlserver	query	Check for ONLINE index rebuilds consuming sort_in_tempdb or extra space	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.type_desc,\\n  ps.reserved_page_count * 8 / 1024 AS reserved_mb,\\n  ps.row_count,\\n  df.size * 8 / 1024 AS db_file_size_mb,\\n  (SELECT SUM(size) * 8 / 1024 FROM tempdb.sys.database_files) AS tempdb_size_mb\\nFROM sys.indexes i\\nJOIN sys.dm_db_partition_stats ps ON i.object_id = ps.object_id AND i.index_id = ps.index_id\\nCROSS JOIN (SELECT SUM(size) AS size FROM sys.database_files WHERE type = 0) df\\nWHERE ps.reserved_page_count * 8 / 1024 > 500\\nORDER BY ps.reserved_page_count DESC"}	{"condition": "large indexes present with active rebuild operations", "description": "ONLINE index rebuild requires space for old + new index simultaneously — doubles space temporarily"}	null	2026-02-23 20:18:31.389356
832	sqlserver	query	Find tables with significant LOB data allocation	{"sql": "SELECT OBJECT_SCHEMA_NAME(p.object_id) AS schema_name,\\n  OBJECT_NAME(p.object_id) AS table_name,\\n  p.index_id, p.rows,\\n  au.type_desc,\\n  au.total_pages * 8 / 1024 AS lob_size_mb,\\n  au.used_pages * 8 / 1024 AS lob_used_mb\\nFROM sys.allocation_units au\\nJOIN sys.partitions p ON au.container_id = p.hobt_id\\nWHERE au.type_desc = 'LOB_DATA'\\n  AND au.total_pages > 1000\\nORDER BY au.total_pages DESC"}	{"condition": "row_count > 0 AND lob_size_mb > 100", "description": "Tables with substantial LOB_DATA allocation units found"}	null	2026-02-23 20:18:31.38936
833	sqlserver	query	Compare LOB vs in-row data proportion	{"sql": "SELECT OBJECT_NAME(p.object_id) AS table_name,\\n  SUM(CASE WHEN au.type_desc = 'IN_ROW_DATA' THEN au.total_pages ELSE 0 END) * 8 / 1024 AS inrow_mb,\\n  SUM(CASE WHEN au.type_desc = 'LOB_DATA' THEN au.total_pages ELSE 0 END) * 8 / 1024 AS lob_mb,\\n  SUM(CASE WHEN au.type_desc = 'ROW_OVERFLOW_DATA' THEN au.total_pages ELSE 0 END) * 8 / 1024 AS overflow_mb,\\n  CAST(SUM(CASE WHEN au.type_desc = 'LOB_DATA' THEN au.total_pages ELSE 0 END) AS FLOAT)\\n    / NULLIF(SUM(au.total_pages), 0) * 100 AS lob_pct\\nFROM sys.allocation_units au\\nJOIN sys.partitions p ON au.container_id = p.hobt_id\\nWHERE OBJECT_NAME(p.object_id) IS NOT NULL\\nGROUP BY p.object_id\\nHAVING SUM(CASE WHEN au.type_desc = 'LOB_DATA' THEN au.total_pages ELSE 0 END) > 1000\\nORDER BY lob_mb DESC"}	{"condition": "lob_pct > 50", "description": "LOB data dominates table storage — LOB growth is the primary driver of volume increase"}	null	2026-02-23 20:18:31.38936
847	sqlserver	query	Find files with percentage-based growth	{"sql": "SELECT DB_NAME(database_id) AS database_name,\\n  name AS file_name,\\n  type_desc,\\n  size * 8 / 1024 AS current_size_mb,\\n  growth AS growth_percent,\\n  CAST(size * 8.0 / 1024 * growth / 100 AS DECIMAL(10,2)) AS next_growth_mb,\\n  is_percent_growth\\nFROM sys.master_files\\nWHERE is_percent_growth = 1\\n  AND growth > 0\\nORDER BY size DESC"}	{"condition": "row_count > 0", "description": "Database files using percentage-based growth"}	null	2026-02-23 20:18:31.389365
848	sqlserver	query	Check if percentage growth would cause large growth events	{"sql": "SELECT DB_NAME(database_id) AS database_name,\\n  name AS file_name,\\n  size * 8 / 1024 AS current_size_mb,\\n  growth AS growth_pct,\\n  CAST(size * 8.0 / 1024 * growth / 100 AS DECIMAL(10,2)) AS next_growth_mb\\nFROM sys.master_files\\nWHERE is_percent_growth = 1\\n  AND growth > 0\\n  AND (size * 8.0 / 1024 * growth / 100) > 500"}	{"condition": "next_growth_mb > 500", "description": "Next percentage-based growth would add 500+ MB — growth events become increasingly large and slow"}	null	2026-02-23 20:18:31.389366
849	sqlserver	query	Find files with small fixed growth increments	{"sql": "SELECT DB_NAME(database_id) AS database_name,\\n  name AS file_name,\\n  type_desc,\\n  size * 8 / 1024 AS current_size_mb,\\n  growth * 8 / 1024 AS growth_increment_mb,\\n  is_percent_growth\\nFROM sys.master_files\\nWHERE is_percent_growth = 0\\n  AND growth > 0\\n  AND growth * 8 / 1024 < 64\\n  AND size * 8 / 1024 > 500"}	{"condition": "row_count > 0", "description": "Large database files with growth increments under 64 MB"}	null	2026-02-23 20:18:31.389366
859	sqlserver	query	Check tempdb space usage by sessions	{"sql": "SELECT TOP 20\\n  su.session_id,\\n  s.program_name, s.host_name,\\n  su.user_objects_alloc_page_count * 8 / 1024 AS user_objects_mb,\\n  su.internal_objects_alloc_page_count * 8 / 1024 AS internal_objects_mb,\\n  (su.user_objects_alloc_page_count - su.user_objects_dealloc_page_count) * 8 / 1024 AS user_current_mb\\nFROM sys.dm_db_session_space_usage su\\nJOIN sys.dm_exec_sessions s ON su.session_id = s.session_id\\nWHERE su.user_objects_alloc_page_count > 1000\\nORDER BY su.user_objects_alloc_page_count DESC"}	{"condition": "row_count > 0 AND user_current_mb > 100", "description": "Sessions consuming significant tempdb space via user objects (temp tables)"}	null	2026-02-23 20:18:31.389367
851	sqlserver	query	Check for active bulk operations	{"sql": "SELECT r.session_id, r.command, r.percent_complete,\\n  r.total_elapsed_time / 60000 AS elapsed_min,\\n  r.wait_type,\\n  s.program_name, s.host_name,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1, 100) AS query_fragment\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE r.command IN ('BULK INSERT', 'INSERT', 'SELECT INTO', 'MERGE')\\n  AND r.total_elapsed_time > 60000"}	{"condition": "row_count > 0", "description": "Active bulk data loading operations detected"}	null	2026-02-23 20:18:31.389368
1035	sqlserver	query	Check for UNSAFE CLR assemblies	{"sql": "SELECT a.name AS assembly_name,\\n  a.permission_set_desc,\\n  a.create_date,\\n  a.clr_name\\nFROM sys.assemblies a\\nWHERE a.permission_set_desc IN ('EXTERNAL_ACCESS', 'UNSAFE')\\n  AND a.is_user_defined = 1"}	{"condition": "row_count > 0 OR step 1 matched", "description": "UNSAFE or EXTERNAL_ACCESS CLR assemblies expand the vulnerability surface beyond the SQL Server process"}	null	2026-02-23 20:18:31.389373
861	sqlserver	query	Check for SQL Agent alerts on file growth events	{"sql": "SELECT a.name AS alert_name,\\n  a.message_id, a.severity, a.enabled,\\n  a.occurrence_count, a.last_occurrence_date\\nFROM msdb.dbo.sysalerts a\\nWHERE a.message_id IN (1105, 1101, 9002)\\n  OR a.name LIKE '%growth%'\\n  OR a.name LIKE '%disk%space%'\\n  OR a.name LIKE '%file%full%'"}	{"condition": "row_count = 0", "description": "No alerts configured for file growth events or disk space"}	null	2026-02-23 20:18:31.389374
1028	sqlserver	query	Check SQL Server uptime for evidence of recent patching	{"sql": "SELECT sqlserver_start_time,\\n  DATEDIFF(day, sqlserver_start_time, GETDATE()) AS days_since_restart,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level\\nFROM sys.dm_os_sys_info"}	{"condition": "days_since_restart > 90", "description": "SQL Server not restarted in 90+ days — CU patching requires restart"}	null	2026-02-23 20:18:31.389375
867	sqlserver	query	Check if Instant File Initialization is enabled	{"sql": "SELECT servicename, instant_file_initialization_enabled\\nFROM sys.dm_server_services\\nWHERE servicename LIKE 'SQL Server%'"}	{"condition": "instant_file_initialization_enabled = 'N'", "description": "Instant File Initialization is disabled — data file growth requires zero-fill"}	null	2026-02-23 20:18:31.389379
869	sqlserver	query	Find files with small or percentage-based auto-growth settings	{"sql": "SELECT db.name AS database_name, mf.name AS file_name, mf.physical_name, mf.type_desc, mf.growth, mf.is_percent_growth, CASE WHEN mf.is_percent_growth = 1 THEN CAST(mf.growth AS VARCHAR) + '%' ELSE CAST(mf.growth * 8 / 1024 AS VARCHAR) + ' MB' END AS growth_setting, CAST(mf.size * 8.0 / 1024 AS DECIMAL(18,2)) AS current_size_mb FROM sys.master_files mf JOIN sys.databases db ON mf.database_id = db.database_id WHERE mf.is_percent_growth = 1 OR (mf.is_percent_growth = 0 AND mf.growth > 0 AND mf.growth * 8 / 1024 < 64)"}	{"condition": "row_count > 0", "description": "Files with percentage growth or growth increments less than 64 MB cause file fragmentation"}	null	2026-02-23 20:18:31.38938
874	sqlserver	query	Check for sort and hash warnings in query stats	{"sql": "SELECT TOP 20 qs.sql_handle, qs.plan_handle, qs.execution_count, qs.total_spills, qs.last_spills, qs.min_spills, qs.max_spills, qs.total_grant_kb, qs.total_used_grant_kb, qs.total_ideal_grant_kb, SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 100) AS query_fragment FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t WHERE qs.total_spills > 0 ORDER BY qs.total_spills DESC"}	{"condition": "row_count > 0", "description": "Queries with spill operations detected — sort/hash operations writing to tempdb"}	null	2026-02-23 20:18:31.389383
878	sqlserver	query	Find high-impact missing indexes correlated with tempdb-heavy queries	{"sql": "SELECT TOP 15 mid.statement AS table_name, mid.equality_columns, mid.inequality_columns, mid.included_columns, migs.avg_user_impact, migs.user_seeks, migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure FROM sys.dm_db_missing_index_details mid JOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle JOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle WHERE migs.avg_user_impact > 50 ORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 with improvement_measure > 10000", "description": "High-impact missing indexes causing full scans that generate large intermediate result sets"}	null	2026-02-23 20:18:31.389386
881	sqlserver	query	Check tempdb internal object space from sort operations	{"sql": "SELECT session_id, SUM(internal_objects_alloc_page_count) * 8 / 1024 AS internal_alloc_mb, SUM(internal_objects_dealloc_page_count) * 8 / 1024 AS internal_dealloc_mb, SUM(internal_objects_alloc_page_count - internal_objects_dealloc_page_count) * 8 / 1024 AS current_internal_mb FROM sys.dm_db_task_space_usage GROUP BY session_id HAVING SUM(internal_objects_alloc_page_count - internal_objects_dealloc_page_count) * 8 / 1024 > 500 ORDER BY current_internal_mb DESC"}	{"condition": "current_internal_mb > 500 MB from rebuild sessions", "description": "Index rebuild sort operations consuming hundreds of MB or more in tempdb"}	null	2026-02-23 20:18:31.389387
4140	postgresql	query	Check if basic replication without HA tooling	{"sql": "SELECT NOT pg_is_in_recovery() AS is_primary, (SELECT count(*) FROM pg_stat_replication) AS replica_count"}	{"condition": "is_primary = true AND replica_count > 0", "description": "Running replication without visible HA management"}	\N	2026-02-25 00:28:52.405273
3776	postgresql	query	Check pg_cron job history for failures	{"sql": "SELECT jobid, command, status, return_message, start_time, end_time FROM cron.job_run_details WHERE status = 'failed' AND command ILIKE '%amcheck%' OR command ILIKE '%verify%' OR command ILIKE '%checksum%' ORDER BY start_time DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Integrity check jobs have been failing"}	\N	2026-02-25 00:28:52.405273
890	sqlserver	query	Check for active cursors consuming tempdb	{"sql": "SELECT c.session_id, c.properties, c.creation_time, c.is_open, c.worker_time / 1000 AS worker_ms, c.reads, c.writes, SUBSTRING(t.text, 1, 200) AS cursor_text FROM sys.dm_exec_cursors(0) c CROSS APPLY sys.dm_exec_sql_text(c.sql_handle) t WHERE c.is_open = 1 ORDER BY c.worker_time DESC"}	{"condition": "row_count > 5 or high worker_time cursors present", "description": "Multiple open cursors or expensive cursors consuming resources"}	null	2026-02-23 20:18:31.389392
1058	sqlserver	query	Check SQL Server service startup configuration and recent restarts	{"sql": "SELECT servicename, startup_type_desc, status_desc,\\n  last_startup_time, service_account,\\n  instant_file_initialization_enabled\\nFROM sys.dm_server_services\\nWHERE servicename LIKE '%SQL Server%'\\n  OR servicename LIKE '%SQL Agent%'"}	{"condition": "row_count > 0", "description": "SQL Server services are present and their startup type can indicate automatic maintenance patterns"}	null	2026-02-23 20:18:31.389487
907	sqlserver	query	Check suspect pages for torn page events	{"sql": "SELECT DB_NAME(sp.database_id) AS database_name, sp.file_id, sp.page_id, sp.event_type, CASE sp.event_type WHEN 3 THEN 'Torn page detected' WHEN 1 THEN '823/824 error' WHEN 2 THEN 'Bad checksum' END AS event_description, sp.error_count, sp.last_update_date, d.page_verify_option_desc FROM msdb.dbo.suspect_pages sp JOIN sys.databases d ON sp.database_id = d.database_id WHERE sp.event_type IN (1, 2, 3) ORDER BY sp.last_update_date DESC"}	{"condition": "torn page events (event_type = 3) or any suspect pages on non-CHECKSUM databases", "description": "Torn page writes detected or databases vulnerable due to weak page verification"}	null	2026-02-23 20:18:31.389395
900	sqlserver	query	Check suspect pages table for I/O errors	{"sql": "SELECT db.name AS database_name, sp.file_id, sp.page_id, sp.event_type, CASE sp.event_type WHEN 1 THEN '823/824 error' WHEN 2 THEN 'Bad checksum' WHEN 3 THEN 'Torn page' WHEN 4 THEN 'Restored (823/824)' WHEN 5 THEN 'Repaired (DBCC)' WHEN 7 THEN 'Deallocated (DBCC)' END AS event_description, sp.error_count, sp.last_update_date FROM msdb.dbo.suspect_pages sp JOIN sys.databases db ON sp.database_id = db.database_id WHERE sp.event_type IN (1, 2, 3) ORDER BY sp.last_update_date DESC"}	{"condition": "row_count > 0 with event_type 1, 2, or 3", "description": "Suspect pages with unresolved I/O errors, bad checksums, or torn pages"}	null	2026-02-23 20:18:31.389399
903	sqlserver	query	Check suspect pages for bad checksums (in-memory corruption symptom)	{"sql": "SELECT sp.database_id, DB_NAME(sp.database_id) AS database_name, sp.file_id, sp.page_id, sp.event_type, sp.error_count, sp.last_update_date FROM msdb.dbo.suspect_pages sp WHERE sp.event_type = 2 ORDER BY sp.last_update_date DESC"}	{"condition": "bad checksum entries in suspect_pages", "description": "Bad checksums indicate page was corrupted in memory before being written to disk"}	null	2026-02-23 20:18:31.389401
4266	postgresql	query	Check for jobs with missing executions around restart time	{"sql": "SELECT j.jobid, j.schedule, j.command, max(d.start_time) AS last_successful FROM cron.job j LEFT JOIN cron.job_run_details d ON j.jobid = d.jobid AND d.status = 'succeeded' WHERE j.active = true GROUP BY j.jobid, j.schedule, j.command HAVING max(d.start_time) < pg_postmaster_start_time() OR max(d.start_time) IS NULL"}	{"condition": "row_count > 0", "description": "Jobs that last ran before the restart and missed their schedule during downtime"}	\N	2026-02-25 00:28:52.405273
909	sqlserver	query	Check recovery interval and checkpoint frequency	{"sql": "SELECT c.name, c.value_in_use AS recovery_interval_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n     AND instance_name = '_Total') AS checkpoint_pages_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Background writer pages/sec'\\n     AND instance_name = '_Total') AS bgwriter_pages_per_sec\\nFROM sys.configurations c\\nWHERE c.name = 'recovery interval (min)'"}	{"condition": "checkpoint_pages_per_sec > 1000 or recovery_interval too low", "description": "Aggressive checkpoint frequency causing I/O saturation during flush"}	null	2026-02-23 20:18:31.389403
910	sqlserver	query	Correlate checkpoint activity with data file write latency	{"sql": "SELECT DB_NAME(vfs.database_id) AS db_name,\\n  mf.physical_name, mf.type_desc,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms,\\n  vfs.num_of_writes, vfs.num_of_bytes_written / 1048576 AS mb_written\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE mf.type = 0\\n  AND vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) > 10\\nORDER BY avg_write_stall_ms DESC"}	{"condition": "avg_write_stall_ms > 10 on data files", "description": "High data file write latency confirms checkpoint flushes are overwhelming storage"}	null	2026-02-23 20:18:31.389403
911	sqlserver	query	Check for elevated I/O latency on database files	{"sql": "SELECT DB_NAME(vfs.database_id) AS db_name,\\n  mf.physical_name, mf.type_desc,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms,\\n  vfs.num_of_reads + vfs.num_of_writes AS total_ios\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.database_id > 4\\nORDER BY (vfs.io_stall_read_ms + vfs.io_stall_write_ms) / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0) DESC"}	{"condition": "avg_read_stall_ms > 20 or avg_write_stall_ms > 20 across multiple files", "description": "Uniformly elevated I/O latency across multiple database files suggests external interference"}	null	2026-02-23 20:18:31.389404
912	sqlserver	query	Check for IO_COMPLETION and ASYNC_IO_COMPLETION waits indicating external delays	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('IO_COMPLETION', 'ASYNC_IO_COMPLETION', 'PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'PAGEIOLATCH_UP')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH average waits > 20ms with high IO_COMPLETION waits", "description": "Pattern of elevated I/O waits across both read and write paths consistent with antivirus file scanning overhead"}	null	2026-02-23 20:18:31.389405
914	sqlserver	query	Check file growth configuration and autogrow events	{"sql": "SELECT DB_NAME(mf.database_id) AS db_name, mf.name, mf.type_desc,\\n  mf.physical_name, mf.growth,\\n  CASE WHEN mf.is_percent_growth = 1 THEN CAST(mf.growth AS VARCHAR) + '%'\\n    ELSE CAST(mf.growth * 8 / 1024 AS VARCHAR) + ' MB' END AS growth_setting,\\n  mf.is_percent_growth,\\n  mf.size * 8 / 1024 AS current_size_mb\\nFROM sys.master_files mf\\nWHERE mf.database_id > 4\\n  AND (mf.is_percent_growth = 1 OR mf.growth < 8192)"}	{"condition": "files using percent growth or growth < 64MB", "description": "Small or percentage-based file growth causes frequent autogrow events and I/O stalls"}	null	2026-02-23 20:18:31.389406
915	sqlserver	query	Check for data and log files on same physical volume	{"sql": "SELECT DB_NAME(mf.database_id) AS db_name,\\n  LEFT(mf.physical_name, 3) AS drive_letter,\\n  mf.type_desc,\\n  COUNT(*) AS file_count,\\n  STRING_AGG(mf.name, ', ') AS files\\nFROM sys.master_files mf\\nWHERE mf.database_id > 4\\nGROUP BY DB_NAME(mf.database_id), LEFT(mf.physical_name, 3), mf.type_desc\\nHAVING COUNT(DISTINCT mf.type) > 1\\nORDER BY db_name"}	{"condition": "data and log files sharing same drive letter", "description": "Data and log files on same volume causes I/O contention between random reads and sequential writes"}	null	2026-02-23 20:18:31.389407
917	sqlserver	query	Check I/O stall patterns on all database files	{"sql": "SELECT DB_NAME(vfs.database_id) AS db_name,\\n  mf.type_desc,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms,\\n  vfs.io_stall_queued_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_queued_read_ms,\\n  vfs.io_stall_queued_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_queued_write_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.database_id > 4\\n  AND (vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) > 15\\n    OR vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) > 15)\\nORDER BY (vfs.io_stall_read_ms + vfs.io_stall_write_ms) DESC"}	{"condition": "avg stall > 15ms with significant queued I/O time", "description": "High I/O latency on a VM with elevated queue times suggests hypervisor storage contention"}	null	2026-02-23 20:18:31.389408
918	sqlserver	query	Check for I/O errors in SQL Server suspect pages and error log	{"sql": "SELECT db.name AS database_name, sp.file_id, sp.page_id,\\n  sp.event_type, sp.error_count, sp.last_update_date\\nFROM msdb.dbo.suspect_pages sp\\nJOIN sys.databases db ON sp.database_id = db.database_id\\nWHERE sp.last_update_date > DATEADD(day, -30, GETDATE())\\nORDER BY sp.last_update_date DESC"}	{"condition": "row_count > 0", "description": "Suspect pages indicate physical I/O errors — possible failing disk in array"}	null	2026-02-23 20:18:31.389409
919	sqlserver	query	Check for elevated I/O latency with error patterns	{"sql": "SELECT DB_NAME(vfs.database_id) AS db_name,\\n  mf.physical_name,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms,\\n  (SELECT COUNT(*) FROM msdb.dbo.suspect_pages sp2\\n   WHERE sp2.database_id = vfs.database_id AND sp2.file_id = vfs.file_id) AS suspect_page_count\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.database_id > 4\\n  AND (vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) > 50\\n    OR vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) > 50)\\nORDER BY avg_read_stall_ms DESC"}	{"condition": "avg stall > 50ms or suspect pages on specific files", "description": "Very high I/O latency combined with suspect pages strongly indicates failing storage hardware"}	null	2026-02-23 20:18:31.389409
920	sqlserver	query	Check for concurrent I/O-heavy operations	{"sql": "SELECT r.session_id, r.command, r.status,\\n  r.percent_complete, r.wait_type, r.wait_time,\\n  r.total_elapsed_time / 1000 AS elapsed_sec,\\n  DB_NAME(r.database_id) AS db_name,\\n  r.reads + r.writes AS total_ios\\nFROM sys.dm_exec_requests r\\nWHERE r.command IN ('BACKUP DATABASE', 'BACKUP LOG', 'RESTORE DATABASE',\\n  'DBCC TABLE CHECK', 'DBCC CHECKDB', 'DBCC CHECKTABLE',\\n  'ALTER INDEX', 'CREATE INDEX', 'UPDATE STATISTICS',\\n  'DbccSpaceReclaim', 'DbccFilesCompact')\\nORDER BY r.total_elapsed_time DESC"}	{"condition": "row_count > 1", "description": "Multiple I/O-heavy operations running concurrently"}	null	2026-02-23 20:18:31.38941
921	sqlserver	query	Check Resource Governor I/O impact and pending I/O	{"sql": "SELECT\\n  (SELECT SUM(pending_disk_io_count) FROM sys.dm_os_schedulers) AS total_pending_ios,\\n  ws.wait_type, ws.wait_time_ms, ws.waiting_tasks_count,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'WRITELOG', 'IO_COMPLETION', 'ASYNC_IO_COMPLETION')\\n  AND ws.waiting_tasks_count > 0\\nORDER BY ws.wait_time_ms DESC"}	{"condition": "total_pending_ios > 50 with elevated PAGEIOLATCH waits", "description": "High pending I/O queue with competing workloads confirms I/O resource contention"}	null	2026-02-23 20:18:31.389411
922	sqlserver	query	Check for periodic write latency spikes on database files	{"sql": "SELECT DB_NAME(vfs.database_id) AS db_name,\\n  mf.physical_name, mf.type_desc,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms,\\n  vfs.num_of_writes, vfs.num_of_reads\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.database_id > 4\\nORDER BY vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) DESC"}	{"condition": "avg_write_stall_ms > 5 with write-heavy workload", "description": "Elevated write latency on SSDs may indicate garbage collection interference"}	null	2026-02-23 20:18:31.389411
923	sqlserver	query	Check for WRITELOG and write-path wait patterns	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('WRITELOG', 'PAGEIOLATCH_EX', 'IO_COMPLETION', 'ASYNC_IO_COMPLETION')\\n  AND waiting_tasks_count > 0\\nORDER BY max_wait_time_ms DESC"}	{"condition": "max_wait_time_ms >> avg_wait_ms (spiky pattern) on write waits", "description": "Large gap between average and maximum write waits suggests periodic latency spikes from SSD GC"}	null	2026-02-23 20:18:31.389412
924	sqlserver	query	Check databases with no recent log backups	{"sql": "SELECT d.name AS database_name,\\n  d.recovery_model_desc,\\n  d.log_reuse_wait_desc,\\n  (SELECT MAX(bs.backup_finish_date)\\n   FROM msdb.dbo.backupset bs\\n   WHERE bs.database_name = d.name AND bs.type = 'L') AS last_log_backup,\\n  DATEDIFF(HOUR, \\n    (SELECT MAX(bs.backup_finish_date)\\n     FROM msdb.dbo.backupset bs\\n     WHERE bs.database_name = d.name AND bs.type = 'L'),\\n    GETDATE()) AS hours_since_last_log_backup\\nFROM sys.databases d\\nWHERE d.recovery_model_desc IN ('FULL', 'BULK_LOGGED')\\n  AND d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "last_log_backup IS NULL or hours_since_last_log_backup > 24", "description": "Databases in FULL recovery with no log backup or stale log backups"}	null	2026-02-23 20:18:31.389412
925	sqlserver	query	Confirm transaction log is consuming excessive space	{"sql": "SELECT DB_NAME(database_id) AS db_name,\\n  CAST(total_log_size_in_bytes / 1048576.0 AS DECIMAL(12,2)) AS total_log_size_mb,\\n  CAST(used_log_space_in_bytes / 1048576.0 AS DECIMAL(12,2)) AS used_log_space_mb,\\n  CAST(used_log_space_in_percent AS DECIMAL(5,2)) AS used_log_pct\\nFROM sys.dm_db_log_space_usage"}	{"condition": "used_log_pct > 70 or total_log_size_mb > 10000", "description": "Transaction log growing without truncation due to missing log backups"}	null	2026-02-23 20:18:31.389413
4141	postgresql	query	Check for HA tool connections	{"sql": "SELECT application_name FROM pg_stat_activity WHERE application_name ~* '(patroni|repmgr|pacemaker|stolon|pg_auto_failover)' GROUP BY application_name"}	{"condition": "row_count = 0", "description": "No HA tool connections detected; cluster lacks distributed consensus"}	\N	2026-02-25 00:28:52.405273
926	sqlserver	query	Check for failed log backup jobs in Agent history	{"sql": "SELECT j.name AS job_name,\\n  jh.run_date, jh.run_time, jh.run_status,\\n  CASE jh.run_status\\n    WHEN 0 THEN 'Failed' WHEN 1 THEN 'Succeeded'\\n    WHEN 2 THEN 'Retry' WHEN 3 THEN 'Canceled' END AS status_desc,\\n  jh.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobhistory jh ON j.job_id = jh.job_id\\nWHERE jh.step_id = 0\\n  AND jh.run_status IN (0, 3)\\n  AND (j.name LIKE '%log%backup%' OR j.name LIKE '%tlog%' OR j.name LIKE '%transaction%log%'\\n    OR EXISTS (SELECT 1 FROM msdb.dbo.sysjobsteps js\\n      WHERE js.job_id = j.job_id AND js.command LIKE '%BACKUP LOG%'))\\n  AND jh.run_date >= CAST(CONVERT(VARCHAR(8), DATEADD(day, -7, GETDATE()), 112) AS INT)\\nORDER BY jh.run_date DESC, jh.run_time DESC"}	{"condition": "row_count > 0", "description": "Log backup jobs failing — log cannot be truncated"}	null	2026-02-23 20:18:31.389414
927	sqlserver	query	Confirm log growth due to failed backups	{"sql": "SELECT d.name AS database_name,\\n  d.recovery_model_desc,\\n  d.log_reuse_wait_desc,\\n  CAST(ls.total_log_size_in_bytes / 1048576.0 AS DECIMAL(12,2)) AS total_log_size_mb,\\n  CAST(ls.used_log_space_in_percent AS DECIMAL(5,2)) AS used_log_pct,\\n  (SELECT MAX(bs.backup_finish_date)\\n   FROM msdb.dbo.backupset bs\\n   WHERE bs.database_name = d.name AND bs.type = 'L') AS last_successful_log_backup\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nWHERE d.database_id = DB_ID()\\n  AND d.recovery_model_desc IN ('FULL', 'BULK_LOGGED')\\n  AND d.log_reuse_wait_desc = 'LOG_BACKUP'"}	{"condition": "log_reuse_wait_desc = 'LOG_BACKUP' with high used_log_pct", "description": "Log retention confirmed due to failed backup jobs"}	null	2026-02-23 20:18:31.389414
928	sqlserver	query	Check for databases with ACTIVE_TRANSACTION log reuse wait	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  CAST(ls.total_log_size_in_bytes / 1048576.0 AS DECIMAL(12,2)) AS total_log_size_mb,\\n  CAST(ls.used_log_space_in_percent AS DECIMAL(5,2)) AS used_log_pct\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nWHERE d.log_reuse_wait_desc = 'ACTIVE_TRANSACTION'\\n  AND d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "row_count > 0", "description": "Log truncation blocked by an active transaction"}	null	2026-02-23 20:18:31.389415
929	sqlserver	query	Identify the oldest open transaction	{"sql": "SELECT tat.transaction_id,\\n  tat.transaction_begin_time,\\n  DATEDIFF(MINUTE, tat.transaction_begin_time, GETDATE()) AS age_minutes,\\n  tat.name AS transaction_name,\\n  es.session_id, es.login_name, es.host_name, es.program_name,\\n  es.status AS session_status,\\n  (SELECT TEXT FROM sys.dm_exec_sql_text(ec.most_recent_sql_handle)) AS last_sql\\nFROM sys.dm_tran_active_transactions tat\\nJOIN sys.dm_tran_session_transactions tst ON tat.transaction_id = tst.transaction_id\\nJOIN sys.dm_exec_sessions es ON tst.session_id = es.session_id\\nLEFT JOIN sys.dm_exec_connections ec ON es.session_id = ec.session_id\\nWHERE tat.transaction_begin_time < DATEADD(MINUTE, -30, GETDATE())\\nORDER BY tat.transaction_begin_time ASC"}	{"condition": "transactions older than 30 minutes", "description": "Long-running open transaction holding log space — blocking truncation"}	null	2026-02-23 20:18:31.389416
4267	postgresql	query	Check for disabled jobs	{"sql": "SELECT jobid, schedule, command, active, username, database FROM cron.job WHERE active = false"}	{"condition": "row_count > 0", "description": "Inactive jobs found that should potentially be running"}	\N	2026-02-25 00:28:52.405273
930	sqlserver	query	Check for databases with REPLICATION log reuse wait	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  d.is_published, d.is_merge_published, d.is_distributor,\\n  CAST(ls.total_log_size_in_bytes / 1048576.0 AS DECIMAL(12,2)) AS total_log_size_mb,\\n  CAST(ls.used_log_space_in_percent AS DECIMAL(5,2)) AS used_log_pct\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nWHERE d.log_reuse_wait_desc = 'REPLICATION'\\n  AND d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "row_count > 0 with log_reuse_wait_desc = 'REPLICATION'", "description": "Log truncation blocked by replication — log reader not advancing"}	null	2026-02-23 20:18:31.389417
931	sqlserver	query	Check log reader agent status and replication latency	{"sql": "SELECT p.name AS publication_name,\\n  la.name AS logreader_agent_name, la.publisher_db,\\n  lh.time AS last_action_time, lh.action_message,\\n  lh.comments, lh.delivery_latency,\\n  DATEDIFF(MINUTE, lh.time, GETDATE()) AS minutes_since_last_action\\nFROM distribution.dbo.MSlogreader_agents la\\nJOIN distribution.dbo.MSlogreader_history lh ON la.id = lh.agent_id\\nLEFT JOIN distribution.dbo.MSpublications p ON la.publisher_db = p.publisher_db\\nWHERE lh.time = (SELECT MAX(time) FROM distribution.dbo.MSlogreader_history lh2 WHERE lh2.agent_id = la.id)\\nORDER BY lh.time DESC"}	{"condition": "minutes_since_last_action > 30 or error in comments", "description": "Log reader agent stalled or failing — not consuming log records"}	null	2026-02-23 20:18:31.389418
3777	postgresql	query	Check tablespace disk usage and availability	{"sql": "SELECT spcname, pg_size_pretty(pg_tablespace_size(oid)) AS used_size FROM pg_tablespace ORDER BY pg_tablespace_size(oid) DESC"}	{"condition": "row_count > 0", "description": "Tablespace size information for disk space assessment"}	\N	2026-02-25 00:28:52.405273
932	sqlserver	query	Check for active bulk operations and log usage	{"sql": "SELECT r.session_id, r.command, r.status,\\n  r.percent_complete,\\n  r.total_elapsed_time / 60000 AS elapsed_minutes,\\n  DB_NAME(r.database_id) AS db_name,\\n  r.writes AS page_writes,\\n  CAST(dt.database_transaction_log_bytes_used / 1048576.0 AS DECIMAL(12,2)) AS log_used_mb,\\n  CAST(dt.database_transaction_log_bytes_reserved / 1048576.0 AS DECIMAL(12,2)) AS log_reserved_mb\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_tran_session_transactions st ON r.session_id = st.session_id\\nJOIN sys.dm_tran_database_transactions dt ON st.transaction_id = dt.transaction_id\\nWHERE r.command IN ('INSERT', 'BULK INSERT', 'SELECT INTO', 'ALTER INDEX', 'CREATE INDEX',\\n  'UPDATE', 'DELETE', 'MERGE')\\n  AND dt.database_transaction_log_bytes_used > 104857600\\nORDER BY dt.database_transaction_log_bytes_used DESC"}	{"condition": "transactions using > 100MB of log space", "description": "Large bulk operations generating significant transaction log volume"}	null	2026-02-23 20:18:31.389419
933	sqlserver	query	Confirm log file growth due to bulk operations	{"sql": "SELECT d.name AS database_name,\\n  d.recovery_model_desc,\\n  d.log_reuse_wait_desc,\\n  CAST(ls.total_log_size_in_bytes / 1048576.0 AS DECIMAL(12,2)) AS total_log_size_mb,\\n  CAST(ls.used_log_space_in_percent AS DECIMAL(5,2)) AS used_log_pct,\\n  (SELECT COUNT(*) FROM sys.dm_tran_database_transactions dt2\\n   WHERE dt2.database_id = d.database_id\\n     AND dt2.database_transaction_log_bytes_used > 104857600) AS large_txn_count\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nWHERE d.database_id > 4\\n  AND ls.used_log_space_in_percent > 70\\n  AND d.state_desc = 'ONLINE'\\nORDER BY ls.used_log_space_in_percent DESC"}	{"condition": "used_log_pct > 70 with active large transactions", "description": "Transaction log filling due to large bulk operation log records"}	null	2026-02-23 20:18:31.38942
4146	postgresql	query	Check replication connections for partial connectivity	{"sql": "SELECT client_addr, state, sent_lsn, write_lsn, pg_wal_lsn_diff(sent_lsn, write_lsn) AS unacked_bytes FROM pg_stat_replication WHERE state != 'streaming'"}	{"condition": "row_count > 0 AND state = 'catchup'", "description": "Standby in catchup state may indicate asymmetric connectivity"}	\N	2026-02-25 00:28:52.405273
934	sqlserver	query	Check for CDC-enabled databases with REPLICATION log reuse wait	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  d.is_cdc_enabled,\\n  CAST(ls.total_log_size_in_bytes / 1048576.0 AS DECIMAL(12,2)) AS total_log_size_mb,\\n  CAST(ls.used_log_space_in_percent AS DECIMAL(5,2)) AS used_log_pct\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nWHERE d.is_cdc_enabled = 1\\n  AND d.log_reuse_wait_desc = 'REPLICATION'\\n  AND d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "CDC-enabled database with log_reuse_wait_desc = 'REPLICATION'", "description": "CDC is preventing log truncation — capture job is behind"}	null	2026-02-23 20:18:31.38942
935	sqlserver	query	Check CDC capture job status and scan latency	{"sql": "SELECT\\n  s.session_id, s.start_time, s.end_time,\\n  s.duration AS scan_duration_ms,\\n  s.scan_phase, s.error_count,\\n  s.tran_count AS transactions_processed,\\n  s.command_count AS commands_processed,\\n  DATEDIFF(MINUTE, s.end_time, GETDATE()) AS minutes_since_last_scan,\\n  s.latency AS capture_latency_sec\\nFROM sys.dm_cdc_log_scan_sessions s\\nORDER BY s.session_id DESC\\nOFFSET 0 ROWS FETCH FIRST 5 ROWS ONLY"}	{"condition": "minutes_since_last_scan > 30 or error_count > 0 or high latency", "description": "CDC capture job stalled, failing, or lagging behind log generation"}	null	2026-02-23 20:18:31.389421
936	sqlserver	query	Check for databases with DATABASE_MIRRORING log reuse wait	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  dm.mirroring_state_desc,\\n  dm.mirroring_role_desc,\\n  dm.mirroring_safety_level_desc,\\n  dm.mirroring_partner_name,\\n  dm.mirroring_witness_state_desc,\\n  CAST(ls.total_log_size_in_bytes / 1048576.0 AS DECIMAL(12,2)) AS total_log_size_mb,\\n  CAST(ls.used_log_space_in_percent AS DECIMAL(5,2)) AS used_log_pct\\nFROM sys.databases d\\nJOIN sys.database_mirroring dm ON d.database_id = dm.database_id\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nWHERE d.log_reuse_wait_desc = 'DATABASE_MIRRORING'\\n  AND dm.mirroring_guid IS NOT NULL\\n  AND d.database_id > 4"}	{"condition": "row_count > 0 with log_reuse_wait_desc = 'DATABASE_MIRRORING'", "description": "Database mirroring is holding log truncation"}	null	2026-02-23 20:18:31.389421
937	sqlserver	query	Check mirroring state and send queue	{"sql": "SELECT d.name AS database_name,\\n  dm.mirroring_state_desc,\\n  dm.mirroring_role_desc,\\n  dm.mirroring_safety_level_desc,\\n  pc.cntr_value AS send_queue_kb,\\n  pc2.cntr_value AS redo_queue_kb,\\n  pc3.cntr_value AS transaction_delay_ms\\nFROM sys.database_mirroring dm\\nJOIN sys.databases d ON dm.database_id = d.database_id\\nLEFT JOIN sys.dm_os_performance_counters pc\\n  ON pc.counter_name = 'Log Send Queue KB'\\n  AND pc.instance_name = d.name\\nLEFT JOIN sys.dm_os_performance_counters pc2\\n  ON pc2.counter_name = 'Redo Queue KB'\\n  AND pc2.instance_name = d.name\\nLEFT JOIN sys.dm_os_performance_counters pc3\\n  ON pc3.counter_name = 'Transaction Delay'\\n  AND pc3.instance_name = d.name\\nWHERE dm.mirroring_guid IS NOT NULL\\n  AND (dm.mirroring_state_desc <> 'SYNCHRONIZED'\\n    OR dm.mirroring_state_desc = 'DISCONNECTED')"}	{"condition": "mirroring DISCONNECTED or SUSPENDED with send_queue_kb > 0", "description": "Mirroring session broken or suspended — log records accumulating unsent"}	null	2026-02-23 20:18:31.389422
2807	sqlserver	query	Check registry audit level for success-only mode	{"sql": "DECLARE @AuditLevel INT;\\nEXEC xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'Software\\\\Microsoft\\\\MSSQLServer\\\\MSSQLServer',\\n  N'AuditLevel',\\n  @AuditLevel OUTPUT;\\nSELECT @AuditLevel AS audit_level,\\n  CASE WHEN @AuditLevel = 1 THEN 'SUCCESSFUL_LOGINS_ONLY' ELSE 'OTHER' END AS status"}	{"condition": "audit_level = 1", "description": "Registry-level auditing captures only successful logins — failures are suppressed"}	null	2026-02-23 20:18:31.389428
938	sqlserver	query	Check for suspect pages indicating possible write-back cache corruption	{"sql": "SELECT sp.database_id, d.name AS database_name,\\n  sp.file_id, sp.page_id,\\n  sp.event_type,\\n  CASE sp.event_type\\n    WHEN 1 THEN '823 error (OS CRC or torn page)'\\n    WHEN 2 THEN 'Bad checksum'\\n    WHEN 3 THEN 'Torn page'\\n    WHEN 4 THEN 'Restored (after repair)'\\n    WHEN 5 THEN 'Repaired (DBCC)'\\n    WHEN 7 THEN 'Deallocated (DBCC)'\\n  END AS event_description,\\n  sp.error_count,\\n  sp.last_update_date\\nFROM msdb.dbo.suspect_pages sp\\nJOIN sys.databases d ON sp.database_id = d.database_id\\nWHERE sp.event_type IN (1, 2, 3)\\n  AND sp.last_update_date >= DATEADD(day, -30, GETDATE())\\nORDER BY sp.last_update_date DESC"}	{"condition": "row_count > 0", "description": "Recent suspect pages found — 823 errors, bad checksums, or torn pages suggest storage-level write corruption consistent with RAID cache failure"}	null	2026-02-23 20:18:31.389423
1075	sqlserver	query	Check current build version and age indicators	{"sql": "SELECT SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  sqlserver_start_time,\\n  DATEDIFF(day, sqlserver_start_time, GETDATE()) AS days_since_restart\\nFROM sys.dm_os_sys_info"}	{"condition": "days_since_restart > 180", "description": "Instance has been running for over 6 months without a restart, suggesting no CU has been applied"}	null	2026-02-23 20:18:31.389504
944	sqlserver	query	Check if SQL Server is running in a virtual environment and detect clock skew	{"sql": "SELECT @@VERSION AS sql_version,\\n  si.cpu_count AS logical_cpus,\\n  si.hyperthread_ratio,\\n  si.virtual_machine_type_desc,\\n  si.sqlserver_start_time,\\n  DATEDIFF(minute, si.sqlserver_start_time, GETDATE()) AS uptime_minutes,\\n  os.ms_ticks AS os_ticks_ms\\nFROM sys.dm_os_sys_info si\\nCROSS JOIN (SELECT ms_ticks FROM sys.dm_os_sys_info) os\\nWHERE si.virtual_machine_type_desc <> 'NONE'"}	{"condition": "virtual_machine_type_desc <> 'NONE'", "description": "SQL Server is running in a virtualized environment — prerequisite for virtualization-layer corruption"}	null	2026-02-23 20:18:31.389426
945	sqlserver	query	Check for suspect pages and I/O anomalies in virtualized environment	{"sql": "SELECT sp.database_id, d.name AS database_name,\\n  sp.event_type, sp.error_count, sp.last_update_date,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms\\nFROM msdb.dbo.suspect_pages sp\\nJOIN sys.databases d ON sp.database_id = d.database_id\\nJOIN sys.master_files mf ON sp.database_id = mf.database_id AND sp.file_id = mf.file_id\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\n  ON sp.database_id = vfs.database_id AND sp.file_id = vfs.file_id\\nWHERE sp.event_type IN (1, 2, 3)\\nORDER BY sp.last_update_date DESC"}	{"condition": "suspect pages exist in virtualized environment", "description": "Data corruption in a virtualized environment — may be caused by hypervisor snapshot operations, virtual disk thin provisioning, or vSphere memory overcommit"}	null	2026-02-23 20:18:31.389426
1084	sqlserver	query	Verify instance is still at the pre-patch version	{"sql": "SELECT SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  sqlserver_start_time,\\n  DATEDIFF(hour, sqlserver_start_time, GETDATE()) AS hours_since_restart\\nFROM sys.dm_os_sys_info"}	{"condition": "CU level unchanged despite recent restart or error log entries showing patch attempt", "description": "Instance remains at the old CU level after a failed patch attempt, suggesting the download or transfer was interrupted"}	null	2026-02-23 20:18:31.389435
4268	postgresql	query	Check total job count vs expected	{"sql": "SELECT count(*) AS total_jobs, count(*) FILTER (WHERE active) AS active_jobs, count(*) FILTER (WHERE NOT active) AS inactive_jobs FROM cron.job"}	{"condition": "total_jobs < :expected_count OR inactive_jobs > 0", "description": "Fewer jobs than expected or disabled jobs present"}	{"expected_count": 5}	2026-02-25 00:28:52.405273
1048	sqlserver	query	Check last known good DBCC CHECKDB date for each database	{"sql": "SELECT d.name AS database_name,\\n  d.state_desc,\\n  DATABASEPROPERTYEX(d.name, 'LastGoodCheckDbTime') AS last_checkdb_time,\\n  DATEDIFF(day,\\n    CAST(DATABASEPROPERTYEX(d.name, 'LastGoodCheckDbTime') AS DATETIME),\\n    GETDATE()) AS days_since_checkdb\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "days_since_checkdb > 14 OR last_checkdb_time = '1900-01-01'", "description": "DBCC CHECKDB not run in 14+ days or never run (1900-01-01 default)"}	null	2026-02-23 20:18:31.389486
963	sqlserver	query	Check volume sector sizes for all database file locations	{"sql": "SELECT DISTINCT\\n  d.name AS database_name,\\n  mf.physical_name,\\n  mf.type_desc,\\n  vs.logical_volume_name,\\n  vs.file_system_type,\\n  vs.supports_compression,\\n  vs.supports_alternate_streams,\\n  vs.supports_sparse_files\\nFROM sys.master_files mf\\nJOIN sys.databases d ON mf.database_id = d.database_id\\nCROSS APPLY sys.dm_os_volume_stats(mf.database_id, mf.file_id) vs\\nWHERE d.database_id > 4\\nORDER BY d.name, mf.type_desc"}	{"condition": "row_count > 0", "description": "Retrieves volume metadata for all database files — sector size must be checked against SQL Server's page write alignment requirements"}	null	2026-02-23 20:18:31.389439
964	sqlserver	query	Check for torn page errors that indicate sector alignment problems	{"sql": "SELECT sp.database_id, d.name AS database_name,\\n  sp.file_id, sp.page_id,\\n  sp.event_type,\\n  sp.error_count,\\n  sp.last_update_date,\\n  d.page_verify_option_desc,\\n  mf.physical_name\\nFROM msdb.dbo.suspect_pages sp\\nJOIN sys.databases d ON sp.database_id = d.database_id\\nJOIN sys.master_files mf ON sp.database_id = mf.database_id AND sp.file_id = mf.file_id\\nWHERE sp.event_type = 3\\nORDER BY sp.last_update_date DESC"}	{"condition": "event_type = 3 (torn pages)", "description": "Torn page errors are the primary symptom of sector size mismatch — when the physical sector is 4KB but the OS reports 512B, an 8KB SQL Server page write becomes two non-atomic sector writes"}	null	2026-02-23 20:18:31.38944
1427	sqlserver	query	Verify compilation spike correlating with index changes	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'SQL Compilations/sec') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'SQL Re-Compilations/sec') AS recompilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'Batch Requests/sec') AS batch_requests_sec,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_stats WHERE plan_generation_num > 3\\n    AND creation_time > DATEADD(HOUR, -1, GETDATE())) AS recently_recompiled_plans"}	{"condition": "recompilations_sec elevated and recently_recompiled_plans > 50", "description": "Spike in recompilation rate with many recently-recompiled plans confirms index DDL triggered mass plan invalidation"}	null	2026-02-23 20:18:31.389736
1286	sqlserver	query	Find connection accumulation across middleware instances	{"sql": "SELECT s.program_name, s.host_name,\\n  COUNT(*) AS sleeping_count,\\n  SUM(CASE WHEN DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30 THEN 1 ELSE 0 END) AS idle_over_30min,\\n  AVG(c.num_reads + c.num_writes) AS avg_io_ops,\\n  MAX(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS max_idle_min\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 10\\n  AND SUM(CASE WHEN DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30 THEN 1 ELSE 0 END)\\n      > COUNT(*) * 0.5\\nORDER BY sleeping_count DESC"}	{"condition": "multiple host_name entries for same program_name, each showing > 50% idle sessions over 30 min", "description": "Uniform leak pattern across multiple middleware instances (same program, different hosts) indicates middleware layer buffering connections"}	null	2026-02-23 20:18:31.389642
1038	sqlserver	query	Check for SQL Agent alerts on critical error severities	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM msdb.dbo.sysalerts WHERE severity >= 17) AS high_severity_alerts,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysalerts WHERE severity >= 19) AS critical_severity_alerts,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysalerts WHERE message_id IN (823, 824, 825)) AS io_error_alerts,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysoperators WHERE enabled = 1) AS enabled_operators"}	{"condition": "high_severity_alerts = 0 OR enabled_operators = 0", "description": "No alerts configured for high-severity errors or no operators to receive notifications"}	null	2026-02-23 20:18:31.389445
4269	postgresql	query	Check for sequential job failure chains	{"sql": "SELECT jobid, command, status, return_message, start_time FROM cron.job_run_details WHERE status = 'failed' AND start_time > NOW() - interval '24 hours' ORDER BY start_time DESC"}	{"condition": "row_count > 1", "description": "Multiple job failures may indicate a dependency chain failure"}	\N	2026-02-25 00:28:52.405273
980	sqlserver	query	Identify lagging AG replicas and queue sizes	{"sql": "SELECT ag.name AS ag_name,\\n  ar.replica_server_name,\\n  drs.database_id,\\n  DB_NAME(drs.database_id) AS database_name,\\n  drs.synchronization_state_desc,\\n  drs.log_send_queue_size AS log_send_queue_kb,\\n  drs.redo_queue_size AS redo_queue_kb,\\n  drs.last_hardened_lsn,\\n  drs.last_sent_lsn,\\n  drs.last_received_lsn,\\n  DATEDIFF(SECOND, drs.last_commit_time, GETUTCDATE()) AS seconds_behind\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.is_primary_replica = 0\\n  AND (drs.log_send_queue_size > 1024 OR drs.synchronization_state_desc <> 'SYNCHRONIZED')\\nORDER BY drs.log_send_queue_size DESC"}	{"condition": "log_send_queue_kb > 1024 or synchronization_state_desc NOT SYNCHRONIZED", "description": "Secondary replicas with send queue backlog preventing log truncation on primary"}	null	2026-02-23 20:18:31.38945
981	sqlserver	query	Check log file auto-growth settings	{"sql": "SELECT DB_NAME(database_id) AS database_name,\\n  name AS logical_name,\\n  type_desc,\\n  size * 8 / 1024 AS current_size_mb,\\n  CASE WHEN is_percent_growth = 1\\n    THEN CAST(growth AS VARCHAR) + '%'\\n    ELSE CAST(growth * 8 / 1024 AS VARCHAR) + ' MB'\\n  END AS growth_increment,\\n  is_percent_growth,\\n  growth,\\n  max_size\\nFROM sys.master_files\\nWHERE type_desc = 'LOG'\\n  AND (is_percent_growth = 1\\n    OR (is_percent_growth = 0 AND growth > 0 AND growth * 8 / 1024 < 64))\\n  AND growth > 0\\n  AND database_id > 4"}	{"condition": "row_count > 0", "description": "Log files using percentage growth or fixed growth under 64 MB"}	null	2026-02-23 20:18:31.38945
4147	postgresql	query	Check HA tool connections and primary state	{"sql": "SELECT application_name, client_addr, backend_start FROM pg_stat_activity WHERE application_name ~* '(patroni|repmgr|stolon|pg_auto_failover)'"}	{"condition": "row_count > 0", "description": "HA tool is connected; check for misconfiguration or version-specific bugs"}	\N	2026-02-25 00:28:52.405273
982	sqlserver	query	Check recent auto-growth events from default trace	{"sql": "SELECT DB_NAME(te.DatabaseId) AS database_name,\\n  te.FileName,\\n  te.StartTime,\\n  te.Duration / 1000 AS duration_ms,\\n  (te.IntegerData * 8) / 1024 AS growth_mb\\nFROM (\\n  SELECT path FROM sys.traces WHERE is_default = 1\\n) t\\nCROSS APPLY sys.fn_trace_gettable(t.path, DEFAULT) te\\nWHERE te.EventClass IN (92, 93)\\n  AND te.StartTime > DATEADD(DAY, -7, GETDATE())\\nORDER BY te.StartTime DESC"}	{"condition": "row_count > 0 with frequent growth events", "description": "Multiple auto-growth events in the past week indicate undersized growth increments"}	null	2026-02-23 20:18:31.389451
1020	sqlserver	query	Get current build version and CU level	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  SERVERPROPERTY('ProductMinorVersion') AS minor_version,\\n  SERVERPROPERTY('ProductBuild') AS build_number,\\n  SERVERPROPERTY('Edition') AS edition,\\n  @@VERSION AS full_version"}	{"condition": "cu_level IS NULL OR cu_level < latest_available_cu", "description": "CU level is NULL (pre-2017) or behind latest available cumulative update"}	null	2026-02-23 20:18:31.389477
4271	postgresql	query	Check database operational state	{"sql": "SELECT pg_is_in_recovery() AS in_recovery, current_setting('default_transaction_read_only') AS read_only"}	{"condition": "in_recovery = true OR read_only = 'on'", "description": "Database in recovery or read-only mode; write jobs will fail"}	\N	2026-02-25 00:28:52.405273
6002	postgresql	config_check	Check for encryption key management settings	{"sql": "SELECT name, setting FROM pg_settings WHERE name ~* '(encrypt|key|kms|vault)'"}	{"condition": "row_count = 0", "description": "No key management configuration — encryption blocked by missing infrastructure"}	\N	2026-02-25 00:28:52.405273
1287	sqlserver	query	Check total connection pressure from middleware pattern	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%General Statistics%'\\n     AND counter_name = 'User Connections') AS total_connections,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'user connections') AS max_connections,\\n  mw.program_name AS middleware_app,\\n  mw.host_count,\\n  mw.total_leaked\\nFROM (\\n  SELECT program_name,\\n    COUNT(DISTINCT host_name) AS host_count,\\n    COUNT(*) AS total_leaked\\n  FROM sys.dm_exec_sessions\\n  WHERE status = 'sleeping' AND is_user_process = 1\\n    AND DATEDIFF(MINUTE, last_request_end_time, GETDATE()) > 30\\n  GROUP BY program_name\\n  HAVING COUNT(DISTINCT host_name) > 1 AND COUNT(*) > 15\\n) mw"}	{"condition": "total_leaked > 15 across multiple hosts from same middleware application", "description": "Middleware holding connections across multiple instances creates multiplicative leak — N instances x M leaked connections each"}	null	2026-02-23 20:18:31.389643
984	sqlserver	query	Identify top log-generating sessions and their queries	{"sql": "SELECT TOP 10\\n  s.session_id,\\n  s.login_name,\\n  s.program_name,\\n  s.host_name,\\n  dt.database_transaction_log_bytes_used / 1048576 AS log_used_mb,\\n  dt.database_transaction_log_record_count AS log_records,\\n  SUBSTRING(st.text, (r.statement_start_offset / 2) + 1,\\n    CASE WHEN r.statement_end_offset = -1 THEN LEN(st.text)\\n    ELSE (r.statement_end_offset - r.statement_start_offset) / 2 + 1 END) AS current_statement\\nFROM sys.dm_tran_database_transactions dt\\nJOIN sys.dm_tran_session_transactions st2 ON dt.transaction_id = st2.transaction_id\\nJOIN sys.dm_exec_sessions s ON st2.session_id = s.session_id\\nLEFT JOIN sys.dm_exec_requests r ON s.session_id = r.session_id\\nOUTER APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE dt.database_transaction_log_bytes_used > 10485760\\nORDER BY dt.database_transaction_log_bytes_used DESC"}	{"condition": "sessions with log_used_mb > 10 from application connections", "description": "Application sessions generating excessive transaction log records"}	null	2026-02-23 20:18:31.389452
1021	sqlserver	query	Check SQL Server service start time for patch recency	{"sql": "SELECT sqlserver_start_time,\\n  DATEDIFF(day, sqlserver_start_time, GETDATE()) AS days_since_restart,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level\\nFROM sys.dm_os_sys_info\\nWHERE DATEDIFF(day, sqlserver_start_time, GETDATE()) > 180"}	{"condition": "days_since_restart > 180", "description": "SQL Server not restarted in 6+ months — CU patching requires restart, so long uptime suggests no recent patching"}	null	2026-02-23 20:18:31.389478
9885	mysql	config_check	Check if binary logging is enabled	{"sql": "SELECT @@log_bin AS log_bin, @@binlog_format AS binlog_format"}	{"condition": "log_bin = 'OFF'", "description": "Binary logging disabled means no transaction log archiving for PITR"}	\N	2026-03-01 06:30:58.706791
992	sqlserver	query	Check distribution database transaction retention and agent status	{"sql": "SELECT p.publication AS publication_name,\\n  a.name AS agent_name,\\n  a.publisher_db,\\n  h.start_time AS last_run_time,\\n  h.duration AS last_run_duration_sec,\\n  h.comments,\\n  h.delivered_transactions,\\n  h.delivered_commands,\\n  CASE h.runstatus\\n    WHEN 1 THEN 'Started' WHEN 2 THEN 'Succeeded'\\n    WHEN 3 THEN 'InProgress' WHEN 4 THEN 'Idle'\\n    WHEN 5 THEN 'Retrying' WHEN 6 THEN 'Failed'\\n  END AS run_status\\nFROM distribution.dbo.MSlogreader_agents a\\nJOIN distribution.dbo.MSlogreader_history h ON a.id = h.agent_id\\nJOIN distribution.dbo.MSpublications p ON a.publisher_db = p.publisher_db\\nWHERE h.timestamp = (\\n  SELECT MAX(h2.timestamp) FROM distribution.dbo.MSlogreader_history h2\\n  WHERE h2.agent_id = a.id\\n)\\nORDER BY h.start_time DESC"}	{"condition": "run_status = 'Failed' or 'Retrying' or delivered_transactions = 0", "description": "Log reader agent failing or stalled, not processing log records for distribution"}	null	2026-02-23 20:18:31.389457
997	sqlserver	query	Collect current SQL Server version and build information	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  SERVERPROPERTY('ProductMinorVersion') AS minor_version,\\n  SERVERPROPERTY('ProductBuild') AS build_number,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cumulative_update,\\n  SERVERPROPERTY('ProductUpdateReference') AS update_kb,\\n  SERVERPROPERTY('Edition') AS edition,\\n  @@VERSION AS full_version_string"}	{"condition": "returns version information", "description": "Baseline version data collected for lifecycle assessment"}	null	2026-02-23 20:18:31.38946
1258	sqlserver	query	Check network-related wait statistics	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms / 1000 AS total_wait_seconds,\\n  wait_time_ms * 1.0 / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'ASYNC_NETWORK_IO', 'NETWORK_IO',\\n  'PREEMPTIVE_OS_GETPROCADDRESS',\\n  'DTC_STATE', 'DTCNEW_ENLIST', 'DTCNEW_PREPARE'\\n)\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "ASYNC_NETWORK_IO total_wait_seconds > 300 or avg_wait_ms > 50", "description": "High ASYNC_NETWORK_IO waits indicate SQL Server is waiting for the client to consume result sets, consistent with network latency or slow client processing"}	null	2026-02-23 20:18:31.389608
998	sqlserver	query	Check if version is in extended support or end-of-life	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS major_version,\\n  SERVERPROPERTY('ProductLevel') AS service_pack,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) <= 11 THEN 'END_OF_LIFE'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 12 THEN 'END_OF_LIFE'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 13 THEN 'EXTENDED_SUPPORT_ENDING'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 14 THEN 'EXTENDED_SUPPORT'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 15 THEN 'MAINSTREAM'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 16 THEN 'CURRENT'\\n    ELSE 'UNKNOWN'\\n  END AS lifecycle_status,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) <= 11 THEN 'SQL Server 2012 or earlier — past end of all support'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 12 THEN 'SQL Server 2014 — extended support ended July 2024'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 13 THEN 'SQL Server 2016 — extended support ends July 2026'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 14 THEN 'SQL Server 2017 — extended support ends October 2027'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 15 THEN 'SQL Server 2019 — mainstream support until February 2025, extended until January 2030'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 16 THEN 'SQL Server 2022 — current release, mainstream support active'\\n    ELSE 'Unknown version'\\n  END AS lifecycle_detail"}	{"condition": "lifecycle_status IN ('END_OF_LIFE', 'EXTENDED_SUPPORT_ENDING', 'EXTENDED_SUPPORT')", "description": "SQL Server version is nearing or past end of lifecycle without documented tracking"}	null	2026-02-23 20:18:31.389461
1022	sqlserver	query	Get detailed SQL Server version and build number	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  CAST(SERVERPROPERTY('ProductBuild') AS INT) AS build_number,\\n  SERVERPROPERTY('Edition') AS edition"}	{"condition": "build_number retrievable for comparison against known vulnerable builds", "description": "Build number retrieved for CVE vulnerability cross-reference"}	null	2026-02-23 20:18:31.389478
999	sqlserver	query	Check SQL Server version age and CU currency	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS major_version,\\n  SERVERPROPERTY('ProductVersion') AS full_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  SERVERPROPERTY('Edition') AS edition,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) <= 13 THEN 'UPGRADE_OVERDUE'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 14 THEN 'UPGRADE_RECOMMENDED'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 15 THEN 'CURRENT'\\n    ELSE 'UNKNOWN'\\n  END AS upgrade_urgency,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) <= 13 THEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT)\\n    ELSE 0\\n  END AS versions_behind"}	{"condition": "upgrade_urgency IN ('UPGRADE_OVERDUE', 'UPGRADE_RECOMMENDED')", "description": "SQL Server is 1+ major versions behind current release, upgrade planning deferred"}	null	2026-02-23 20:18:31.389462
10142	mysql	config_check	Check event scheduler status	{"sql": "SELECT @@global.event_scheduler AS event_scheduler"}	{"condition": "row_count > 0", "description": "Event scheduler is OFF or DISABLED, preventing all scheduled maintenance jobs"}	\N	2026-03-01 06:30:58.706791
1000	sqlserver	query	Check for features requiring newer version	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS major_version,\\n  CASE WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) < 14\\n    THEN 'Missing: Automatic tuning, Graph DB, Resumable index rebuild'\\n    ELSE '' END AS missing_v14_features,\\n  CASE WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) < 15\\n    THEN 'Missing: Intelligent Query Processing, Accelerated Database Recovery, UTF-8'\\n    ELSE '' END AS missing_v15_features,\\n  CASE WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) < 16\\n    THEN 'Missing: Ledger, Query Store hints, Parameter Sensitive Plan, Contained AG'\\n    ELSE '' END AS missing_v16_features,\\n  d.total_databases,\\n  d.total_size_gb\\nFROM (\\n  SELECT COUNT(*) AS total_databases,\\n    SUM(CAST(size AS BIGINT)) * 8 / 1024 / 1024 AS total_size_gb\\n  FROM sys.master_files WHERE type = 0 AND database_id > 4\\n) d"}	{"condition": "missing features listed for current major version", "description": "Instance is missing significant features available in newer versions, confirming deferred planning"}	null	2026-02-23 20:18:31.389462
1001	sqlserver	query	Check version against EOL timeline	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS major_version,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('Edition') AS edition,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) <= 10 THEN 'PAST_EOL — SQL 2008/R2 ended July 2019'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 11 THEN 'PAST_EOL — SQL 2012 ended July 2022'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 12 THEN 'PAST_EOL — SQL 2014 ended July 2024'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 13 THEN 'NEAR_EOL — SQL 2016 extended support ends July 2026'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 14 THEN 'SUPPORTED — SQL 2017 extended support ends Oct 2027'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 15 THEN 'SUPPORTED — within active support lifecycle'\\n    ELSE 'UNKNOWN'\\n  END AS eol_status"}	{"condition": "eol_status LIKE 'PAST_EOL%' or eol_status LIKE 'NEAR_EOL%'", "description": "SQL Server version is past EOL or within 12 months of EOL"}	null	2026-02-23 20:18:31.389463
1002	sqlserver	query	Determine version gap and upgrade path requirements	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS current_major,\\n  SERVERPROPERTY('ProductVersion') AS current_version,\\n  16 AS target_major,\\n  '2022' AS target_version_name,\\n  16 - CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS version_gap,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) <= 10 THEN 'Requires intermediate upgrade: 2008(R2) -> 2012/2014 -> 2022'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 11 THEN 'Direct upgrade supported: 2012 -> 2022 (but test compat level jump)'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 12 THEN 'Direct upgrade supported: 2014 -> 2022'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 13 THEN 'Direct upgrade supported: straightforward path'\\n    ELSE 'UNKNOWN'\\n  END AS upgrade_path"}	{"condition": "version_gap >= 4", "description": "Version gap of 4+ major versions requires careful upgrade path planning"}	null	2026-02-23 20:18:31.389463
3981	postgresql	query	Check standby replay lag and last error	{"sql": "SELECT pg_last_wal_receive_lsn() AS received_lsn, pg_last_wal_replay_lsn() AS replayed_lsn, pg_wal_lsn_diff(pg_last_wal_receive_lsn(), pg_last_wal_replay_lsn()) AS replay_pending_bytes, pg_last_xact_replay_timestamp() AS last_replay_time"}	{"condition": "replay_pending_bytes > :pending_threshold AND (NOW() - last_replay_time) > interval ':stale_minutes minutes'", "description": "Large pending WAL with stale replay timestamp indicates replay errors"}	{"stale_minutes": 30, "pending_threshold": 67108864}	2026-02-25 00:28:52.405273
1003	sqlserver	query	Check database compatibility levels for upgrade impact	{"sql": "SELECT name AS database_name,\\n  compatibility_level,\\n  CASE compatibility_level\\n    WHEN 80 THEN 'SQL Server 2000'\\n    WHEN 90 THEN 'SQL Server 2005'\\n    WHEN 100 THEN 'SQL Server 2008'\\n    WHEN 110 THEN 'SQL Server 2012'\\n    WHEN 120 THEN 'SQL Server 2014'\\n    WHEN 130 THEN 'SQL Server 2016'\\n    WHEN 140 THEN 'SQL Server 2017'\\n    WHEN 150 THEN 'SQL Server 2019'\\n    WHEN 160 THEN 'SQL Server 2022'\\n    ELSE 'Unknown'\\n  END AS compat_level_name,\\n  CASE WHEN compatibility_level < CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10\\n    THEN 'LEGACY — running below instance level'\\n    ELSE 'CURRENT'\\n  END AS compat_status\\nFROM sys.databases\\nWHERE database_id > 4\\n  AND compatibility_level < 130\\nORDER BY compatibility_level"}	{"condition": "row_count > 0 with compatibility_level < 130", "description": "Databases with legacy compatibility levels that will require careful upgrade testing"}	null	2026-02-23 20:18:31.389464
1004	sqlserver	query	Check for databases at lower compatibility levels than instance	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 AS instance_compat_level,\\n  CASE\\n    WHEN d.compatibility_level < CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10\\n    THEN 'HELD_BACK — application may depend on legacy behavior'\\n    ELSE 'AT_INSTANCE_LEVEL'\\n  END AS constraint_status,\\n  d.compatibility_level - (CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10) AS compat_gap\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.compatibility_level < CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10\\nORDER BY d.compatibility_level"}	{"condition": "row_count > 0", "description": "Databases held at lower compatibility levels than the instance — signals application constraints"}	null	2026-02-23 20:18:31.389465
1005	sqlserver	query	Check for deprecated feature usage	{"sql": "SELECT object_name AS deprecated_feature,\\n  instance_name AS feature_detail,\\n  cntr_value AS usage_count\\nFROM sys.dm_os_performance_counters\\nWHERE object_name LIKE '%Deprecated Features%'\\n  AND cntr_value > 0\\nORDER BY cntr_value DESC"}	{"condition": "row_count > 0 with high usage_count", "description": "Active usage of deprecated features that would break on newer SQL Server versions"}	null	2026-02-23 20:18:31.389465
1428	sqlserver	query	Find procedures with high recompilation counts	{"sql": "SELECT TOP 20\\n  DB_NAME(st.dbid) AS database_name,\\n  OBJECT_NAME(st.objectid, st.dbid) AS procedure_name,\\n  qs.plan_generation_num,\\n  qs.execution_count,\\n  qs.total_worker_time / 1000 AS total_cpu_ms,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  st.text AS proc_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE st.objectid IS NOT NULL\\n  AND qs.plan_generation_num > 3\\nORDER BY qs.plan_generation_num DESC"}	{"condition": "procedures with plan_generation_num > 3 and proc_text containing CREATE TABLE #temp patterns", "description": "Stored procedures creating temp tables that recompile frequently suggest temp table creation inside control flow"}	null	2026-02-23 20:18:31.389737
1008	sqlserver	query	Check SQL Server edition and resource limits	{"sql": "SELECT\\n  SERVERPROPERTY('Edition') AS edition,\\n  SERVERPROPERTY('ProductVersion') AS version,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  SERVERPROPERTY('LicenseType') AS license_type,\\n  SERVERPROPERTY('NumLicenses') AS num_licenses,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Express%'\\n    THEN 'EXPRESS — 1 GB RAM, 10 GB database size, 4 cores'\\n    WHEN CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Web%'\\n    THEN 'WEB — limited to internet-facing workloads by license'\\n    WHEN CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Standard%'\\n    THEN 'STANDARD — 128 GB RAM, limited to 24 cores'\\n    WHEN CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Developer%'\\n    THEN 'DEVELOPER — non-production only'\\n    WHEN CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Enterprise%'\\n    THEN 'ENTERPRISE — full features'\\n    ELSE 'OTHER'\\n  END AS edition_constraints"}	{"condition": "edition is Express or Developer or Web", "description": "Running a limited edition that may indicate budget constraints for proper licensing"}	null	2026-02-23 20:18:31.389467
1037	sqlserver	query	Check Express edition resource limits impacting operations	{"sql": "SELECT\\n  SERVERPROPERTY('Edition') AS edition,\\n  (SELECT physical_memory_kb / 1024 FROM sys.dm_os_sys_info) AS total_memory_mb,\\n  (SELECT COUNT(*) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS cpu_count,\\n  (SELECT SUM(CAST(size AS BIGINT) * 8 / 1024) FROM sys.master_files\\n   WHERE database_id > 4 AND type = 0) AS total_data_size_mb"}	{"condition": "Express edition with total_data_size_mb approaching 10240 (10 GB limit)", "description": "Express edition has 10GB database size limit, 1GB RAM limit, 4 CPU core limit — no Premier support available for patch issues"}	null	2026-02-23 20:18:31.38947
1014	sqlserver	query	Check edition and license status	{"sql": "SELECT\\n  SERVERPROPERTY('Edition') AS edition,\\n  SERVERPROPERTY('ProductVersion') AS version,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  SERVERPROPERTY('LicenseType') AS license_type,\\n  SERVERPROPERTY('NumLicenses') AS num_licenses,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Express%'\\n    THEN 'FREE_EDITION — no license cost but severe limitations'\\n    WHEN CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Evaluation%'\\n    THEN 'EVALUATION — will expire, requires license purchase'\\n    WHEN CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Developer%'\\n    THEN 'DEVELOPER — non-production license only'\\n    ELSE 'LICENSED'\\n  END AS license_concern"}	{"condition": "license_concern IN ('FREE_EDITION', 'EVALUATION', 'DEVELOPER')", "description": "Running on a non-production or free edition indicating license procurement issues"}	null	2026-02-23 20:18:31.389472
1025	sqlserver	query	Check if the compatibility gap is large enough to cause concern	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 AS engine_compat_level,\\n  CASE\\n    WHEN d.compatibility_level <= 110 THEN 'SQL 2012 or older compat - high risk'\\n    WHEN d.compatibility_level = 120 THEN 'SQL 2014 compat - moderate risk'\\n    WHEN d.compatibility_level = 130 THEN 'SQL 2016 compat - low-moderate risk'\\n    ELSE 'Recent compat level'\\n  END AS risk_assessment\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'\\n  AND d.compatibility_level < CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 - 10"}	{"condition": "row_count > 0 with compat_level 2+ generations behind", "description": "Databases 2+ major versions behind in compatibility — legacy cardinality estimator, no adaptive query processing"}	null	2026-02-23 20:18:31.389473
3982	postgresql	query	Measure current WAL generation rate	{"sql": "SELECT pg_current_wal_lsn() AS current_lsn, pg_walfile_name(pg_current_wal_lsn()) AS current_wal_file, (SELECT count(*) FROM pg_ls_waldir()) AS wal_files_on_disk"}	{"condition": "wal_files_on_disk > :max_wal_files", "description": "Excessive WAL files indicate generation outpacing consumption"}	{"max_wal_files": 64}	2026-02-25 00:28:52.405273
1016	sqlserver	query	Check SQL Server Agent alert configuration	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM msdb.dbo.sysalerts WHERE enabled = 1) AS active_alerts,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysalerts WHERE enabled = 1 AND severity >= 17) AS severity_alerts,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysalerts WHERE enabled = 1 AND performance_condition IS NOT NULL) AS perf_alerts,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysoperators WHERE enabled = 1) AS active_operators,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysjobs WHERE enabled = 1) AS active_jobs,\\n  CASE\\n    WHEN (SELECT COUNT(*) FROM msdb.dbo.sysalerts WHERE enabled = 1 AND severity >= 17) = 0\\n    THEN 'NO_SEVERITY_ALERTS — critical errors not monitored'\\n    WHEN (SELECT COUNT(*) FROM msdb.dbo.sysoperators WHERE enabled = 1) = 0\\n    THEN 'NO_OPERATORS — alerts have no notification target'\\n    WHEN (SELECT COUNT(*) FROM msdb.dbo.sysalerts WHERE enabled = 1) < 5\\n    THEN 'MINIMAL_ALERTS — insufficient monitoring coverage'\\n    ELSE 'BASIC_MONITORING'\\n  END AS monitoring_assessment"}	{"condition": "monitoring_assessment LIKE 'NO_%' or monitoring_assessment = 'MINIMAL_ALERTS'", "description": "Critical health alerts not configured — problems go undetected, creating false stability perception"}	null	2026-02-23 20:18:31.389474
1039	sqlserver	query	Check SQL Agent service status and job monitoring	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM msdb.dbo.sysalerts) AS total_alerts,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysjobs WHERE enabled = 1) AS enabled_jobs,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysjobhistory\\n   WHERE run_status = 0\\n   AND CONVERT(datetime, STUFF(STUFF(CAST(run_date AS CHAR(8)),5,0,'-'),8,0,'-'))\\n     > DATEADD(day, -7, GETDATE())) AS failed_jobs_7days"}	{"condition": "total_alerts = 0 OR (failed_jobs_7days > 0 AND high_severity_alerts = 0)", "description": "No alerting infrastructure or failed jobs going unnoticed"}	null	2026-02-23 20:18:31.389475
1018	sqlserver	query	Check for server-level audits	{"sql": "SELECT COUNT(*) AS audit_count,\\n  SUM(CASE WHEN is_state_enabled = 1 THEN 1 ELSE 0 END) AS enabled_audits\\nFROM sys.server_audits"}	{"condition": "audit_count = 0 OR enabled_audits = 0", "description": "No server audits configured or none are enabled"}	null	2026-02-23 20:18:31.389476
1019	sqlserver	query	Check for database audit specifications	{"sql": "SELECT d.name AS database_name,\\n  (SELECT COUNT(*) FROM sys.database_audit_specifications das\\n   WHERE das.is_state_enabled = 1) AS enabled_db_audit_specs,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   WHERE sas.is_state_enabled = 1) AS enabled_server_audit_specs\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "enabled_db_audit_specs = 0 AND enabled_server_audit_specs = 0", "description": "No active audit specifications at either server or database level"}	null	2026-02-23 20:18:31.389476
11525	mysql	config_check	Check if require_secure_transport is enabled	{"sql": "SHOW GLOBAL VARIABLES LIKE 'require_secure_transport'"}	{"condition": "value = 'OFF'", "description": "Secure transport is not required, allowing unencrypted connections"}	\N	2026-03-01 06:30:58.706791
4272	postgresql	query	Check pg_cron launcher and worker status	{"sql": "SELECT pid, backend_type, state, wait_event_type, wait_event, query_start, NOW() - query_start AS idle_duration FROM pg_stat_activity WHERE backend_type LIKE '%cron%'"}	{"condition": "row_count > 0 AND idle_duration > interval ':threshold_hours hours'", "description": "pg_cron process has been idle for an extended period, possibly hung"}	{"threshold_hours": 2}	2026-02-25 00:28:52.405273
6043	postgresql	query	Check PostgreSQL version for weak key generation risk	{"sql": "SELECT version(), current_setting('server_version_num')::int AS version_num"}	{"condition": "version_num < 100000", "description": "PostgreSQL version < 10 — older SSL key generation methods"}	\N	2026-02-25 00:28:52.405273
1023	sqlserver	query	Check if running a version that is likely unpatched for recent GDR fixes	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 13\\n      AND CAST(SERVERPROPERTY('ProductBuild') AS INT) < 6441 THEN 'SQL 2016 - below latest GDR'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 14\\n      AND CAST(SERVERPROPERTY('ProductBuild') AS INT) < 3465 THEN 'SQL 2017 - below latest GDR'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 15\\n      AND CAST(SERVERPROPERTY('ProductBuild') AS INT) < 4385 THEN 'SQL 2019 - below latest GDR'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 16\\n      AND CAST(SERVERPROPERTY('ProductBuild') AS INT) < 4145 THEN 'SQL 2022 - below latest GDR'\\n    ELSE 'At or above recent GDR level'\\n  END AS vulnerability_status"}	{"condition": "vulnerability_status contains 'below latest GDR'", "description": "SQL Server build is below the latest GDR (General Distribution Release) security fix level"}	null	2026-02-23 20:18:31.389479
1030	sqlserver	query	Check for databases with no recent full backup	{"sql": "SELECT d.name AS database_name,\\n  d.recovery_model_desc,\\n  MAX(b.backup_finish_date) AS last_full_backup,\\n  DATEDIFF(day, MAX(b.backup_finish_date), GETDATE()) AS days_since_backup\\nFROM sys.databases d\\nLEFT JOIN msdb.dbo.backupset b\\n  ON d.name = b.database_name AND b.type = 'D'\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'\\nGROUP BY d.name, d.recovery_model_desc\\nHAVING MAX(b.backup_finish_date) IS NULL\\n  OR DATEDIFF(day, MAX(b.backup_finish_date), GETDATE()) > 7"}	{"condition": "row_count > 0", "description": "Databases with no full backup or backup older than 7 days"}	null	2026-02-23 20:18:31.38948
1031	sqlserver	query	Check system databases backup status	{"sql": "SELECT d.name AS database_name,\\n  MAX(b.backup_finish_date) AS last_full_backup,\\n  DATEDIFF(day, MAX(b.backup_finish_date), GETDATE()) AS days_since_backup\\nFROM sys.databases d\\nLEFT JOIN msdb.dbo.backupset b\\n  ON d.name = b.database_name AND b.type = 'D'\\nWHERE d.name IN ('master', 'msdb', 'model')\\nGROUP BY d.name\\nHAVING MAX(b.backup_finish_date) IS NULL\\n  OR DATEDIFF(day, MAX(b.backup_finish_date), GETDATE()) > 7"}	{"condition": "row_count > 0", "description": "System databases without recent backup — critical for rollback since CU patches modify system objects"}	null	2026-02-23 20:18:31.38948
1032	sqlserver	query	Check for multiple instances on this host	{"sql": "SELECT\\n  SERVERPROPERTY('ComputerNamePhysicalNetBIOS') AS host_name,\\n  SERVERPROPERTY('InstanceName') AS instance_name,\\n  SERVERPROPERTY('IsClustered') AS is_clustered,\\n  SERVERPROPERTY('ProductVersion') AS product_version"}	{"condition": "instance_name IS NOT NULL (named instance implies multiple possible instances)", "description": "Named instance detected — host may have additional instances"}	null	2026-02-23 20:18:31.389481
2278	sqlserver	query	Check if I/O waits are consuming worker threads under memory pressure	{"sql": "SELECT\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS queued_requests,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests WHERE wait_type LIKE 'PAGEIOLATCH%') AS threads_waiting_on_io,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS total_workers,\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_workers,\\n  (SELECT wait_time_ms / NULLIF(waiting_tasks_count, 0)\\n   FROM sys.dm_os_wait_stats WHERE wait_type = 'PAGEIOLATCH_SH') AS avg_io_wait_ms"}	{"condition": "threads_waiting_on_io > total_workers * 0.3 AND avg_io_wait_ms > 20", "description": "Large fraction of workers stuck on I/O waits due to buffer pool shrinkage confirms memory-induced thread starvation"}	null	2026-02-23 20:18:31.390276
1040	sqlserver	query	Check SQL Server major version against support lifecycle	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS major_version,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('Edition') AS edition,\\n  CASE CAST(SERVERPROPERTY('ProductMajorVersion') AS INT)\\n    WHEN 10 THEN 'SQL 2008/R2 - END OF LIFE (extended support ended Jul 2019)'\\n    WHEN 11 THEN 'SQL 2012 - END OF LIFE (extended support ended Jul 2022)'\\n    WHEN 12 THEN 'SQL 2014 - END OF LIFE (extended support ended Jul 2024)'\\n    WHEN 13 THEN 'SQL 2016 - Extended support ends Jul 2026'\\n    WHEN 14 THEN 'SQL 2017 - Extended support ends Oct 2027'\\n    WHEN 15 THEN 'SQL 2019 - Extended support ends Jan 2030'\\n    WHEN 16 THEN 'SQL 2022 - Mainstream support until Jan 2028'\\n    ELSE 'Unknown version'\\n  END AS support_status"}	{"condition": "major_version <= 12 (SQL 2014 or older)", "description": "Running a version past end of extended support — no security patches available"}	null	2026-02-23 20:18:31.389481
1041	sqlserver	query	Check if approaching end of support	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS major_version,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 13 THEN 'SQL 2016 - extended support ends Jul 2026 - PLAN MIGRATION'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 14 THEN 'SQL 2017 - extended support ends Oct 2027'\\n    ELSE 'Currently supported'\\n  END AS upcoming_eol"}	{"condition": "major_version = 13", "description": "SQL Server 2016 approaching end of extended support — migration planning needed"}	null	2026-02-23 20:18:31.389482
1044	sqlserver	query	Check AG replica versions from primary	{"sql": "SELECT ar.replica_server_name,\\n  ar.availability_mode_desc,\\n  ar.failover_mode_desc,\\n  ars.connected_state_desc,\\n  ars.role_desc,\\n  ars.operational_state_desc\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars\\n  ON ar.replica_id = ars.replica_id"}	{"condition": "row_count > 1 (AG exists with multiple replicas)", "description": "AG with multiple replicas — need to compare build numbers"}	null	2026-02-23 20:18:31.389484
1045	sqlserver	query	Compare build versions across replicas via linked server or DMV	{"sql": "SELECT ar.replica_server_name,\\n  ars.role_desc,\\n  hrc.replica_server_name AS connected_replica,\\n  hrc.join_state_desc,\\n  SERVERPROPERTY('ProductVersion') AS local_version,\\n  SERVERPROPERTY('ProductUpdateLevel') AS local_cu\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars\\n  ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_availability_replica_cluster_states hrc\\n  ON ar.replica_id = hrc.replica_id\\nWHERE ars.connected_state_desc = 'CONNECTED'"}	{"condition": "multiple connected replicas detected — version comparison requires connecting to each replica", "description": "AG replicas are connected but version comparison requires querying each replica individually or via linked servers"}	null	2026-02-23 20:18:31.389485
1046	sqlserver	query	Check for AG replicas with health anomalies suggesting version mismatch	{"sql": "SELECT ar.replica_server_name,\\n  ars.role_desc,\\n  ars.connected_state_desc,\\n  ars.synchronization_health_desc,\\n  ars.operational_state_desc,\\n  drs.synchronization_state_desc,\\n  drs.is_suspended,\\n  drs.suspend_reason_desc\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars\\n  ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs\\n  ON ar.replica_id = drs.replica_id\\nWHERE ars.synchronization_health_desc <> 'HEALTHY'\\n  OR drs.is_suspended = 1"}	{"condition": "row_count > 0", "description": "AG replicas with unhealthy sync state or suspended databases — may indicate post-patch issues from uncoordinated patching"}	null	2026-02-23 20:18:31.389485
1047	sqlserver	query	Check local version and AG replica count for coordination assessment	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS local_version,\\n  SERVERPROPERTY('ProductUpdateLevel') AS local_cu,\\n  (SELECT COUNT(*) FROM sys.availability_replicas) AS total_replicas,\\n  (SELECT COUNT(*) FROM sys.dm_hadr_availability_replica_states\\n   WHERE connected_state_desc = 'CONNECTED') AS connected_replicas,\\n  (SELECT COUNT(*) FROM sys.dm_hadr_availability_replica_states\\n   WHERE synchronization_health_desc <> 'HEALTHY') AS unhealthy_replicas"}	{"condition": "unhealthy_replicas > 0", "description": "Unhealthy replicas alongside version information — strong indicator of uncoordinated patching when combined with step 1"}	null	2026-02-23 20:18:31.389486
1049	sqlserver	query	Check system databases DBCC status	{"sql": "SELECT d.name AS database_name,\\n  DATABASEPROPERTYEX(d.name, 'LastGoodCheckDbTime') AS last_checkdb_time,\\n  DATEDIFF(day,\\n    CAST(DATABASEPROPERTYEX(d.name, 'LastGoodCheckDbTime') AS DATETIME),\\n    GETDATE()) AS days_since_checkdb\\nFROM sys.databases d\\nWHERE d.name IN ('master', 'msdb', 'model')\\n  AND (DATABASEPROPERTYEX(d.name, 'LastGoodCheckDbTime') = '1900-01-01'\\n    OR DATEDIFF(day,\\n      CAST(DATABASEPROPERTYEX(d.name, 'LastGoodCheckDbTime') AS DATETIME),\\n      GETDATE()) > 14)"}	{"condition": "row_count > 0", "description": "System databases also lack recent DBCC CHECKDB — critical after patching since CUs modify system objects"}	null	2026-02-23 20:18:31.389488
1050	sqlserver	query	Check for disconnected AG replicas	{"sql": "SELECT ar.replica_server_name,\\n  ar.availability_mode_desc,\\n  ar.failover_mode_desc,\\n  ars.connected_state_desc,\\n  ars.role_desc,\\n  ars.operational_state_desc,\\n  ars.recovery_health_desc,\\n  ars.synchronization_health_desc\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars\\n  ON ar.replica_id = ars.replica_id\\nWHERE ars.connected_state_desc = 'DISCONNECTED'"}	{"condition": "row_count > 0", "description": "One or more AG replicas are disconnected"}	null	2026-02-23 20:18:31.389488
1051	sqlserver	query	Check impact of disconnected replicas on AG health and failover readiness	{"sql": "SELECT ag.name AS ag_name,\\n  ags.synchronization_health_desc AS ag_health,\\n  (SELECT COUNT(*) FROM sys.availability_replicas ar2\\n   WHERE ar2.group_id = ag.group_id) AS total_replicas,\\n  (SELECT COUNT(*) FROM sys.dm_hadr_availability_replica_states ars2\\n   JOIN sys.availability_replicas ar3 ON ars2.replica_id = ar3.replica_id\\n   WHERE ar3.group_id = ag.group_id\\n     AND ars2.connected_state_desc = 'CONNECTED') AS connected_replicas,\\n  (SELECT COUNT(*) FROM sys.dm_hadr_availability_replica_states ars3\\n   JOIN sys.availability_replicas ar4 ON ars3.replica_id = ar4.replica_id\\n   WHERE ar4.group_id = ag.group_id\\n     AND ars3.connected_state_desc = 'DISCONNECTED') AS disconnected_replicas,\\n  (SELECT COUNT(*) FROM sys.availability_replicas ar5\\n   WHERE ar5.group_id = ag.group_id\\n     AND ar5.failover_mode_desc = 'AUTOMATIC') AS auto_failover_replicas\\nFROM sys.availability_groups ag\\nJOIN sys.dm_hadr_availability_group_states ags\\n  ON ag.group_id = ags.group_id"}	{"condition": "disconnected_replicas > 0 AND ag_health <> 'HEALTHY'", "description": "AG is unhealthy due to disconnected replicas — failover capability reduced, potential quorum risk"}	null	2026-02-23 20:18:31.389489
2598	sqlserver	query	Check if sa has active sessions or recent usage	{"sql": "SELECT COUNT(*) AS active_sa_sessions,\\n  MAX(login_time) AS most_recent_sa_login\\nFROM sys.dm_exec_sessions\\nWHERE original_login_name = 'sa'\\n  OR (original_login_name = (SELECT name FROM sys.server_principals WHERE sid = 0x01))"}	{"condition": "active_sa_sessions > 0", "description": "Active sa sessions found — the recovery account is being used for routine operations"}	null	2026-02-23 20:18:31.39049
1052	sqlserver	query	Check AG replica connection health and state	{"sql": "SELECT ag.name AS ag_name,\\n  ar.replica_server_name,\\n  ars.connected_state_desc,\\n  ars.role_desc,\\n  ars.operational_state_desc,\\n  ars.recovery_health_desc,\\n  ars.synchronization_health_desc,\\n  ars.last_connect_error_number,\\n  ars.last_connect_error_description,\\n  ars.last_connect_error_timestamp\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE ars.connected_state_desc = 'DISCONNECTED'\\n  OR ars.synchronization_health_desc != 'HEALTHY'\\n  OR ars.last_connect_error_number != 0"}	{"condition": "row_count > 0", "description": "One or more AG replicas are disconnected or have recent connection errors"}	null	2026-02-23 20:18:31.389489
1053	sqlserver	query	Check if disconnected replicas have different build numbers	{"sql": "SELECT ar.replica_server_name,\\n  ars.connected_state_desc,\\n  ars.synchronization_health_desc,\\n  ars.last_connect_error_timestamp,\\n  drs.is_suspended,\\n  drs.suspend_reason_desc\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ars.replica_id = drs.replica_id\\nWHERE ars.connected_state_desc = 'DISCONNECTED'\\n  OR drs.is_suspended = 1"}	{"condition": "row_count > 0 with suspended databases or disconnected replicas", "description": "Disconnected or suspended replicas during a maintenance window indicate a network partition interrupted the patching process"}	null	2026-02-23 20:18:31.38949
1054	sqlserver	query	Check instance uptime and current build version	{"sql": "SELECT SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS product_update_level,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  sqlserver_start_time,\\n  DATEDIFF(hour, sqlserver_start_time, GETDATE()) AS uptime_hours\\nFROM sys.dm_os_sys_info"}	{"condition": "uptime_hours < 72", "description": "Instance was recently restarted, consistent with a patch attempt"}	null	2026-02-23 20:18:31.389491
1055	sqlserver	query	Check error log for setup or patch-related failure messages	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'patch';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'setup';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'update';\\nSELECT DISTINCT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -7, GETDATE())\\n  AND (Text LIKE '%fail%' OR Text LIKE '%error%' OR Text LIKE '%could not%' OR Text LIKE '%rollback%')\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "Recent setup/patch-related error messages in the error log indicate a failed patch that was not retried"}	null	2026-02-23 20:18:31.389491
1056	sqlserver	query	Check local instance version details	{"sql": "SELECT SERVERPROPERTY('ServerName') AS server_name,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS product_update_level,\\n  SERVERPROPERTY('Edition') AS edition,\\n  ar.replica_server_name,\\n  ars.role_desc,\\n  ars.connected_state_desc\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id"}	{"condition": "row_count > 1", "description": "Multiple AG replicas exist that could have different patch sources"}	null	2026-02-23 20:18:31.389492
1109	sqlserver	query	Check WSFC cluster health and quorum status	{"sql": "SELECT cluster_name, quorum_type_desc,\\n  quorum_state_desc\\nFROM sys.dm_hadr_cluster;\\nSELECT member_name, member_type_desc,\\n  member_state_desc, number_of_quorum_votes\\nFROM sys.dm_hadr_cluster_members\\nWHERE member_state_desc != 'UP'\\n  OR number_of_quorum_votes = 0"}	{"condition": "quorum_state_desc != 'NORMAL_QUORUM' OR row_count > 0 for non-UP members", "description": "Cluster quorum is not normal or one or more cluster members are not in UP state, indicating disabled or failed cluster services"}	null	2026-02-23 20:18:31.389526
1373	sqlserver	query	Check CXPACKET and CXCONSUMER wait accumulation	{"sql": "SELECT wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  signal_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT')\\nORDER BY wait_time_ms DESC"}	{"condition": "CXPACKET wait_time_ms is high (top 5 overall waits)", "description": "Significant CXPACKET waits indicating parallel thread synchronization delays"}	null	2026-02-23 20:18:31.389702
1057	sqlserver	query	Check for AG replicas with version mismatch indicators	{"sql": "SELECT ar.replica_server_name,\\n  ars.role_desc,\\n  ars.connected_state_desc,\\n  ars.operational_state_desc,\\n  arcs.join_state_desc,\\n  drs.synchronization_state_desc,\\n  drs.synchronization_health_desc,\\n  drs.last_hardened_lsn,\\n  drs.end_of_log_lsn\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.dm_hadr_availability_replica_cluster_states arcs ON ar.replica_id = arcs.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ars.replica_id = drs.replica_id AND drs.is_local = 0\\nWHERE ars.connected_state_desc = 'CONNECTED'"}	{"condition": "row_count > 0 with connected replicas to compare", "description": "Connected replicas from different patch repositories may show version mismatches — verify each replica's ProductVersion via linked server or direct connection"}	null	2026-02-23 20:18:31.389493
3830	postgresql	query	Check for cascading replication topology	{"sql": "SELECT client_addr, application_name, state, sync_state, sent_lsn, replay_lsn, pg_size_pretty(pg_wal_lsn_diff(sent_lsn, replay_lsn)) AS lag, replay_lag FROM pg_stat_replication ORDER BY client_addr"}	{"condition": "row_count > 1", "description": "Multiple replication connections — check if any are cascading standbys"}	\N	2026-02-25 00:28:52.405273
1059	sqlserver	query	Check for unexpected recent service restarts suggesting automatic patching	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'SQL Server is starting';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'Service Broker manager has started';\\nSELECT LogDate, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -30, GETDATE())\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "multiple startup events in last 30 days outside planned maintenance windows", "description": "Unexpected restarts suggest automatic Windows Update is applying patches and restarting SQL Server without coordination"}	null	2026-02-23 20:18:31.389493
1060	sqlserver	query	Verify AG replicas exist and check synchronization state	{"sql": "SELECT ag.name AS ag_name,\\n  ar.replica_server_name,\\n  ars.role_desc,\\n  ars.synchronization_health_desc,\\n  SERVERPROPERTY('ProductVersion') AS local_version,\\n  SERVERPROPERTY('ProductUpdateLevel') AS local_cu_level\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id"}	{"condition": "row_count > 1 with multiple replicas in the AG", "description": "Multiple AG replicas present where inconsistent automatic patching could cause version drift"}	null	2026-02-23 20:18:31.389494
1061	sqlserver	query	Check for AG databases not synchronizing	{"sql": "SELECT ag.name AS ag_name,\\n  ar.replica_server_name,\\n  DB_NAME(drs.database_id) AS database_name,\\n  drs.synchronization_state_desc,\\n  drs.synchronization_health_desc,\\n  drs.is_suspended,\\n  drs.suspend_reason_desc,\\n  drs.last_hardened_lsn,\\n  drs.last_redone_lsn,\\n  drs.log_send_queue_size,\\n  drs.redo_queue_size\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.synchronization_state_desc IN ('NOT SYNCHRONIZING', 'INITIALIZING')\\n  OR drs.is_suspended = 1"}	{"condition": "row_count > 0", "description": "AG databases are not synchronizing or have been suspended, indicating resync issues"}	null	2026-02-23 20:18:31.389494
1062	sqlserver	query	Check error log for AG resync or redo errors	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'Always On';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'availability';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'redo';\\nSELECT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -7, GETDATE())\\n  AND (Text LIKE '%error%' OR Text LIKE '%fail%' OR Text LIKE '%suspend%' OR Text LIKE '%not synchronizing%')\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "AG-related errors in error log confirm healing or resync failures after a node patch or restart"}	null	2026-02-23 20:18:31.389496
1063	sqlserver	query	Check local instance version and AG membership	{"sql": "SELECT SERVERPROPERTY('ServerName') AS server_name,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS product_update_level,\\n  ag.name AS ag_name,\\n  ar.replica_server_name,\\n  ars.role_desc\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id"}	{"condition": "row_count > 1", "description": "Multiple AG replicas exist where version rollback on one node could cause inconsistency"}	null	2026-02-23 20:18:31.389496
1064	sqlserver	query	Check error log for CU uninstall or rollback indicators	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'build';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'version';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'downgrade';\\nSELECT LogDate, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -30, GETDATE())\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "entries showing version change or build downgrade", "description": "Error log entries showing version changes indicate a CU was uninstalled or rolled back"}	null	2026-02-23 20:18:31.389497
1065	sqlserver	query	Check if AG databases show compatibility issues from version mismatch	{"sql": "SELECT ag.name AS ag_name,\\n  drs.synchronization_state_desc,\\n  drs.synchronization_health_desc,\\n  drs.is_suspended,\\n  drs.suspend_reason_desc,\\n  DB_NAME(drs.database_id) AS database_name,\\n  drs.log_send_queue_size,\\n  drs.redo_queue_size\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.synchronization_health_desc != 'HEALTHY'\\n  OR drs.is_suspended = 1"}	{"condition": "row_count > 0 with unhealthy or suspended databases", "description": "Unhealthy AG databases confirm that a version rollback on one replica has caused synchronization issues"}	null	2026-02-23 20:18:31.389497
1066	sqlserver	query	Get local version and list all AG replicas	{"sql": "SELECT SERVERPROPERTY('ServerName') AS local_server,\\n  CAST(SERVERPROPERTY('ProductVersion') AS NVARCHAR(128)) AS local_version,\\n  CAST(SERVERPROPERTY('ProductUpdateLevel') AS NVARCHAR(128)) AS local_cu,\\n  ag.name AS ag_name,\\n  ar.replica_server_name,\\n  ars.role_desc,\\n  ars.connected_state_desc,\\n  ars.synchronization_health_desc\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id"}	{"condition": "row_count > 1 with multiple replicas", "description": "AG contains multiple replicas where build versions should be compared"}	null	2026-02-23 20:18:31.389498
1078	sqlserver	query	Check tempdb and system database volume space specifically	{"sql": "SELECT\\n  DB_NAME(mf.database_id) AS db_name,\\n  mf.physical_name,\\n  vs.volume_mount_point,\\n  vs.available_bytes / 1073741824 AS available_gb,\\n  mf.size * 8 / 1024 AS file_size_mb,\\n  mf.max_size,\\n  mf.growth\\nFROM sys.master_files mf\\nCROSS APPLY sys.dm_os_volume_stats(mf.database_id, mf.file_id) vs\\nWHERE mf.database_id IN (1, 2, 3, 4)\\nORDER BY vs.available_bytes ASC"}	{"condition": "available_gb < 2 on any system database volume", "description": "SQL Server CU installers use tempdb and require space on the system drive for extraction — low space causes installation failure"}	null	2026-02-23 20:18:31.389499
1067	sqlserver	query	Check for signs of version inconsistency via synchronization health	{"sql": "SELECT ar.replica_server_name,\\n  ars.role_desc,\\n  ars.synchronization_health_desc,\\n  drs.synchronization_state_desc,\\n  drs.is_suspended,\\n  drs.suspend_reason_desc,\\n  DB_NAME(drs.database_id) AS database_name\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ars.replica_id = drs.replica_id\\nWHERE ars.synchronization_health_desc != 'HEALTHY'\\n  OR drs.synchronization_state_desc NOT IN ('SYNCHRONIZED', 'SYNCHRONIZING')\\n  OR drs.is_suspended = 1"}	{"condition": "row_count > 0", "description": "Unhealthy synchronization or suspended databases suggest build mismatch from mixed update strategies"}	null	2026-02-23 20:18:31.389499
1068	sqlserver	query	Check available disk space on all volumes hosting SQL Server files	{"sql": "SELECT DISTINCT\\n  vs.volume_mount_point,\\n  vs.logical_volume_name,\\n  vs.total_bytes / 1073741824 AS total_gb,\\n  vs.available_bytes / 1073741824 AS available_gb,\\n  CAST(100.0 * vs.available_bytes / NULLIF(vs.total_bytes, 0) AS DECIMAL(5,1)) AS pct_free\\nFROM sys.master_files mf\\nCROSS APPLY sys.dm_os_volume_stats(mf.database_id, mf.file_id) vs\\nWHERE vs.available_bytes / 1073741824 < 5\\nORDER BY pct_free ASC"}	{"condition": "row_count > 0", "description": "One or more volumes have less than 5 GB free, which may be insufficient for CU installation"}	null	2026-02-23 20:18:31.3895
1070	sqlserver	query	Check SQL Server engine version and component details	{"sql": "SELECT SERVERPROPERTY('ProductVersion') AS engine_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  SERVERPROPERTY('ProductBuildType') AS build_type,\\n  SERVERPROPERTY('Edition') AS edition,\\n  SERVERPROPERTY('EngineEdition') AS engine_edition,\\n  @@VERSION AS full_version_string"}	{"condition": "row_count > 0", "description": "Engine version information retrieved for comparison"}	null	2026-02-23 20:18:31.389501
6448	oracle	query	ora-check-resetlogs-scn-gap	{"sql": "SELECT resetlogs_change#, resetlogs_time, prior_resetlogs_change#, prior_resetlogs_time FROM v$database WHERE resetlogs_time > SYSDATE - :recent_days"}	{"condition": "row_count > 0", "description": "A recent RESETLOGS operation confirms the database was opened with a new incarnation, invalidating previous backup chains"}	{"recent_days": 7}	2026-02-28 12:19:19.580455
1071	sqlserver	query	Check for version discrepancies in installed components via registry	{"sql": "SELECT value_name, value_data\\nFROM sys.dm_server_registry\\nWHERE registry_key LIKE '%CurrentVersion%'\\n  OR registry_key LIKE '%Setup%'\\nORDER BY registry_key"}	{"condition": "version numbers in registry differ from SERVERPROPERTY ProductVersion", "description": "Registry component versions not matching engine version indicates patch metadata inconsistency"}	null	2026-02-23 20:18:31.389502
1072	sqlserver	query	Check for CLR and database internal version mismatches	{"sql": "SELECT name, compatibility_level,\\n  CASE\\n    WHEN compatibility_level < CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10\\n    THEN 'Below current version'\\n    ELSE 'Current'\\n  END AS compat_status,\\n  state_desc, is_read_only\\nFROM sys.databases\\nWHERE database_id > 4\\n  AND state = 0"}	{"condition": "databases with compatibility_level below current major version", "description": "Databases left at older compatibility levels after patching may miss internal metadata updates that require database upgrade"}	null	2026-02-23 20:18:31.389502
1073	sqlserver	query	Check AG configuration and replica count	{"sql": "SELECT ag.name AS ag_name,\\n  ag.automated_backup_preference_desc,\\n  ag.failure_condition_level,\\n  ag.health_check_timeout,\\n  COUNT(ar.replica_id) AS replica_count,\\n  SUM(CASE WHEN ars.connected_state_desc = 'CONNECTED' THEN 1 ELSE 0 END) AS connected_replicas\\nFROM sys.availability_groups ag\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nLEFT JOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nGROUP BY ag.name, ag.automated_backup_preference_desc,\\n  ag.failure_condition_level, ag.health_check_timeout"}	{"condition": "replica_count > 1", "description": "Multi-replica AG exists where coordinated patching is required"}	null	2026-02-23 20:18:31.389503
1074	sqlserver	query	Check if SQL Server Agent alerts are configured for AG health	{"sql": "SELECT a.name AS alert_name, a.enabled, a.message_id,\\n  a.severity, a.category_id,\\n  a.occurrence_count, a.last_occurrence_date\\nFROM msdb.dbo.sysalerts a\\nWHERE a.message_id IN (35264, 35265, 35206, 35254, 35255, 35256, 35257, 35258, 35259, 35260, 35261, 35262, 35263)\\n  OR a.name LIKE '%availability%'\\n  OR a.name LIKE '%AG%'\\n  OR a.name LIKE '%AlwaysOn%'"}	{"condition": "row_count = 0", "description": "No AG-specific alerts configured — indicates lack of monitoring infrastructure for patch coordination"}	null	2026-02-23 20:18:31.389504
1076	sqlserver	query	Check error log history for any past CU installations	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'SQL Server is starting at';\\nSELECT LogDate, Text\\nFROM #errorlog\\nORDER BY LogDate ASC;\\nDROP TABLE #errorlog"}	{"condition": "only one startup entry or long gap between startups", "description": "Minimal restart history confirms the instance has been running continuously without maintenance-related restarts"}	null	2026-02-23 20:18:31.389505
1077	sqlserver	query	Check disk space on all volumes hosting SQL Server files	{"sql": "SELECT DISTINCT\\n  vs.volume_mount_point,\\n  vs.logical_volume_name,\\n  vs.total_bytes / 1073741824 AS total_gb,\\n  vs.available_bytes / 1073741824 AS available_gb,\\n  CAST(100.0 * vs.available_bytes / NULLIF(vs.total_bytes, 0) AS DECIMAL(5,1)) AS pct_free,\\n  CASE WHEN vs.available_bytes / 1073741824 < 2 THEN 'CRITICAL'\\n    WHEN vs.available_bytes / 1073741824 < 5 THEN 'WARNING'\\n    ELSE 'OK' END AS space_status\\nFROM sys.master_files mf\\nCROSS APPLY sys.dm_os_volume_stats(mf.database_id, mf.file_id) vs\\nORDER BY pct_free ASC"}	{"condition": "any volume with available_gb < 5 or pct_free < 10", "description": "Volumes with insufficient free space will prevent CU/SP extraction and installation"}	null	2026-02-23 20:18:31.389506
1079	sqlserver	query	Check system memory availability	{"sql": "SELECT\\n  total_physical_memory_kb / 1024 AS total_physical_mb,\\n  available_physical_memory_kb / 1024 AS available_physical_mb,\\n  total_page_file_kb / 1024 AS total_page_file_mb,\\n  available_page_file_kb / 1024 AS available_page_file_mb,\\n  system_memory_state_desc\\nFROM sys.dm_os_sys_memory"}	{"condition": "available_physical_mb < 1024 or system_memory_state_desc LIKE '%low%'", "description": "Less than 1 GB available physical memory or low memory state could prevent patch installation"}	null	2026-02-23 20:18:31.389507
1080	sqlserver	query	Check SQL Server memory consumption and configuration	{"sql": "SELECT\\n  physical_memory_in_use_kb / 1024 AS sql_memory_used_mb,\\n  locked_page_allocations_kb / 1024 AS locked_pages_mb,\\n  virtual_address_space_committed_kb / 1024 AS virtual_committed_mb,\\n  memory_utilization_percentage,\\n  process_physical_memory_low,\\n  process_virtual_memory_low,\\n  c.value_in_use AS max_server_memory_mb\\nFROM sys.dm_os_process_memory\\nCROSS JOIN sys.configurations c\\nWHERE c.name = 'max server memory (MB)'"}	{"condition": "process_physical_memory_low = 1 or memory_utilization_percentage > 95", "description": "SQL Server is consuming nearly all available memory, leaving insufficient resources for patch installer processes"}	null	2026-02-23 20:18:31.389507
5940	postgresql	config_check	Check for ALTER SYSTEM parameters specifically	{"sql": "SELECT name, setting, source, sourcefile FROM pg_settings WHERE sourcefile LIKE '%postgresql.auto.conf%'"}	{"condition": "row_count > 0", "description": "ALTER SYSTEM overrides exist — may be undocumented changes"}	\N	2026-02-25 00:28:52.405273
1081	sqlserver	query	Check error log for setup and installation failure messages	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'Setup';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'install';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'upgrade';\\nSELECT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -30, GETDATE())\\n  AND (Text LIKE '%fail%' OR Text LIKE '%error%' OR Text LIKE '%corrupt%'\\n    OR Text LIKE '%could not%' OR Text LIKE '%unable%' OR Text LIKE '%abort%')\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "Setup or installation error messages in the error log indicate a failed patch attempt"}	null	2026-02-23 20:18:31.389508
1082	sqlserver	query	Check if current version suggests incomplete upgrade	{"sql": "SELECT SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  SERVERPROPERTY('IsSingleUser') AS is_single_user,\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS integrated_sec_only,\\n  d.state_desc AS master_state,\\n  d.is_read_only AS master_readonly\\nFROM sys.databases d\\nWHERE d.name = 'master'"}	{"condition": "error log shows setup failures and CU level does not reflect expected patch", "description": "Failed setup entries combined with an older-than-expected CU level confirms a corrupted or failed patch binary"}	null	2026-02-23 20:18:31.389508
3983	postgresql	query	Check active transaction volume	{"sql": "SELECT count(*) AS active_transactions, count(*) FILTER (WHERE state = 'active') AS active_queries, count(*) FILTER (WHERE xact_start IS NOT NULL) AS in_transaction FROM pg_stat_activity WHERE backend_type = 'client backend'"}	{"condition": "active_transactions > :threshold", "description": "High concurrent transaction count correlates with WAL generation spike"}	{"threshold": 50}	2026-02-25 00:28:52.405273
1083	sqlserver	query	Check error log for network or download-related failures during setup	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'Setup';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'network';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'download';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'transfer';\\nSELECT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -14, GETDATE())\\n  AND (Text LIKE '%fail%' OR Text LIKE '%error%' OR Text LIKE '%timeout%'\\n    OR Text LIKE '%disconnect%' OR Text LIKE '%abort%' OR Text LIKE '%incomplete%')\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "Network or transfer-related error messages around patch installation time"}	null	2026-02-23 20:18:31.389509
1086	sqlserver	query	Check for file access errors and locked file indicators in error log	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'access';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'permission';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'locked';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'denied';\\nSELECT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -14, GETDATE())\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0 with permission or lock-related errors", "description": "File access, permission denied, or file locked errors indicate the service account or installer cannot access required files"}	null	2026-02-23 20:18:31.38951
1087	sqlserver	query	Check current version details for inconsistencies	{"sql": "SELECT SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cu_level,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  SERVERPROPERTY('ProductMinorVersion') AS minor_version,\\n  SERVERPROPERTY('ProductBuildType') AS build_type,\\n  SERVERPROPERTY('Edition') AS edition,\\n  @@VERSION AS full_version"}	{"condition": "row_count > 0", "description": "Version details retrieved for conflict analysis"}	null	2026-02-23 20:18:31.38951
1088	sqlserver	query	Check error log for version conflict or compatibility messages	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'version';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'compatible';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'prerequisite';\\nSELECT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -30, GETDATE())\\n  AND (Text LIKE '%conflict%' OR Text LIKE '%incompatible%' OR Text LIKE '%prerequisite%'\\n    OR Text LIKE '%cannot be applied%' OR Text LIKE '%requires%')\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "Version conflict or prerequisite messages confirm incompatible patches were attempted"}	null	2026-02-23 20:18:31.389511
1089	sqlserver	query	Check database internal versions for post-patch consistency	{"sql": "SELECT name, compatibility_level,\\n  DATABASEPROPERTYEX(name, 'Version') AS internal_version,\\n  state_desc, is_read_only, is_in_standby\\nFROM sys.databases\\nWHERE state = 0\\nORDER BY database_id"}	{"condition": "databases with different internal versions or unexpected compatibility levels", "description": "Mixed internal database versions after a patch conflict indicate the upgrade script did not complete uniformly"}	null	2026-02-23 20:18:31.389512
1148	sqlserver	query	Quantify wasted plan cache memory from duplicate text variants	{"sql": "SELECT\\n  SUM(wasted_plans) AS total_wasted_plans,\\n  SUM(wasted_kb) AS total_wasted_kb,\\n  COUNT(*) AS affected_query_patterns\\nFROM (\\n  SELECT\\n    qs.query_hash,\\n    COUNT(DISTINCT qs.sql_handle) - 1 AS wasted_plans,\\n    (SUM(cp.size_in_bytes) - MIN(cp.size_in_bytes)) / 1024 AS wasted_kb\\n  FROM sys.dm_exec_query_stats qs\\n  JOIN sys.dm_exec_cached_plans cp ON qs.plan_handle = cp.plan_handle\\n  GROUP BY qs.query_hash\\n  HAVING COUNT(DISTINCT qs.sql_handle) > 1\\n) dup"}	{"condition": "total_wasted_plans > 100 OR total_wasted_kb > 10240", "description": "Significant plan cache memory (>10 MB) is wasted on duplicate plans for logically identical queries that differ only in text formatting"}	null	2026-02-23 20:18:31.389512
1090	sqlserver	query	Check for active user sessions and long-running transactions	{"sql": "SELECT s.session_id, s.login_name, s.host_name,\\n  s.program_name, s.status, s.cpu_time, s.memory_usage,\\n  s.total_scheduled_time, s.total_elapsed_time,\\n  s.last_request_start_time, s.last_request_end_time,\\n  DB_NAME(s.database_id) AS database_name,\\n  t.transaction_id, t.name AS tran_name,\\n  DATEDIFF(minute, t.transaction_begin_time, GETDATE()) AS tran_duration_minutes\\nFROM sys.dm_exec_sessions s\\nLEFT JOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nLEFT JOIN sys.dm_tran_active_transactions t ON st.transaction_id = t.transaction_id\\nWHERE s.is_user_process = 1\\n  AND s.status != 'sleeping'\\nORDER BY t.transaction_begin_time ASC"}	{"condition": "row_count > 0 with active sessions or open transactions", "description": "Active user sessions with open transactions will block clean service shutdown during patching"}	null	2026-02-23 20:18:31.389513
6308	oracle	query	ora_check_block_corruption	{"sql": "SELECT file#, block#, blocks, corruption_change#, corruption_type FROM v$database_block_corruption ORDER BY file#, block#"}	{"condition": "row_count > 0", "description": "Block corruption indicates potential disk/storage hardware failure"}	\N	2026-02-28 12:19:19.580455
1101	sqlserver	query	Check error log for permission denied and access errors during setup	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'permission';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'denied';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'insufficient';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'privilege';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'access is denied';\\nSELECT DISTINCT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -14, GETDATE())\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "Permission denied or insufficient privilege messages indicate the service account or installer user lacks required permissions for CU installation"}	null	2026-02-23 20:18:31.38952
1091	sqlserver	query	Check for long-running queries and blocked processes	{"sql": "SELECT r.session_id, r.status, r.command,\\n  r.wait_type, r.wait_time, r.blocking_session_id,\\n  DATEDIFF(minute, r.start_time, GETDATE()) AS running_minutes,\\n  DB_NAME(r.database_id) AS database_name,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1,\\n    ((CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE r.statement_end_offset END - r.statement_start_offset)/2)+1) AS current_statement\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE r.session_id > 50\\n  AND r.status != 'background'\\nORDER BY r.start_time ASC"}	{"condition": "queries running > 30 minutes or blocking chains present", "description": "Long-running queries or blocking chains will prevent the SQL Server service from stopping gracefully within the shutdown timeout, causing patch installation to fail or timeout"}	null	2026-02-23 20:18:31.389513
1092	sqlserver	query	Check for databases with suspect or emergency status	{"sql": "SELECT name, database_id, state_desc,\\n  is_read_only, is_in_standby,\\n  is_cleanly_shutdown,\\n  DATABASEPROPERTYEX(name, 'Status') AS db_status,\\n  DATABASEPROPERTYEX(name, 'Updateability') AS updateability\\nFROM sys.databases\\nWHERE state_desc IN ('SUSPECT', 'EMERGENCY', 'RECOVERY_PENDING')\\n  OR DATABASEPROPERTYEX(name, 'Status') = 'SUSPECT'"}	{"condition": "row_count > 0", "description": "Databases in SUSPECT, EMERGENCY, or RECOVERY_PENDING state indicate possible system catalog corruption"}	null	2026-02-23 20:18:31.389514
1093	sqlserver	query	Check suspect_pages and DBCC history for corruption indicators	{"sql": "SELECT db.name AS database_name,\\n  sp.file_id, sp.page_id,\\n  sp.event_type, sp.error_count,\\n  sp.last_update_date\\nFROM msdb.dbo.suspect_pages sp\\nJOIN sys.databases db ON sp.database_id = db.database_id\\nWHERE sp.event_type IN (1, 2, 3)\\nORDER BY sp.last_update_date DESC"}	{"condition": "row_count > 0", "description": "Suspect pages with I/O errors or bad checksums indicate physical corruption that can affect system catalog pages"}	null	2026-02-23 20:18:31.389515
1094	sqlserver	query	Check DBCC CHECKDB last known good date for system databases	{"sql": "SELECT name,\\n  DATABASEPROPERTYEX(name, 'LastGoodCheckDbTime') AS last_checkdb_time,\\n  DATEDIFF(day, CAST(DATABASEPROPERTYEX(name, 'LastGoodCheckDbTime') AS DATETIME), GETDATE()) AS days_since_checkdb\\nFROM sys.databases\\nWHERE database_id IN (1, 2, 3, 4)\\n  AND DATABASEPROPERTYEX(name, 'LastGoodCheckDbTime') IS NOT NULL"}	{"condition": "days_since_checkdb > 30 or last_checkdb_time is NULL for any system database", "description": "System databases without recent DBCC CHECKDB may have undetected catalog corruption that will cause CU upgrade scripts to fail"}	null	2026-02-23 20:18:31.389515
1095	sqlserver	query	Check OS version and hardware compatibility	{"sql": "SELECT\\n  host_platform, host_distribution,\\n  host_release, host_service_pack_level,\\n  host_sku, os_language_version\\nFROM sys.dm_os_host_info;\\nSELECT\\n  cpu_count, hyperthread_ratio,\\n  physical_memory_kb / 1024 AS physical_memory_mb,\\n  virtual_machine_type_desc,\\n  softnuma_configuration_desc,\\n  sql_memory_model_desc,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  SERVERPROPERTY('Edition') AS edition\\nFROM sys.dm_os_sys_info"}	{"condition": "host information retrieved for prerequisite validation", "description": "OS version and hardware details retrieved to verify CU/SP prerequisites are met"}	null	2026-02-23 20:18:31.389516
1096	sqlserver	query	Check CLR version and .NET assemblies loaded	{"sql": "SELECT TOP 20\\n  name, clr_name, permission_set_desc, is_visible\\nFROM sys.assemblies\\nWHERE is_user_defined = 0\\nORDER BY name;\\nSELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS integrated_sec_only,\\n  SERVERPROPERTY('IsHadrEnabled') AS hadr_enabled,\\n  SERVERPROPERTY('IsFullTextInstalled') AS fulltext_installed,\\n  SERVERPROPERTY('IsPolyBaseInstalled') AS polybase_installed,\\n  SERVERPROPERTY('FilestreamConfiguredLevel') AS filestream_level"}	{"condition": "system assemblies are present and component features retrievable", "description": "CLR assemblies and optional component status help identify missing prerequisites that certain CU patches require"}	null	2026-02-23 20:18:31.389517
1097	sqlserver	query	Check for error log entries about prerequisite failures	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'prerequisite';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'.NET';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'CLR version';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'requirement';\\nSELECT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -30, GETDATE())\\n  AND (Text LIKE '%fail%' OR Text LIKE '%not supported%' OR Text LIKE '%required%'\\n    OR Text LIKE '%minimum%' OR Text LIKE '%incompatible%')\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "Prerequisite failure messages in the error log confirm that CU installation was blocked by missing requirements"}	null	2026-02-23 20:18:31.389517
1098	sqlserver	query	Check for recent suspect pages indicating I/O failures	{"sql": "SELECT db.name AS database_name,\\n  sp.file_id, sp.page_id,\\n  sp.event_type,\\n  CASE sp.event_type\\n    WHEN 1 THEN '823 error (OS CRC)'\\n    WHEN 2 THEN 'Bad checksum'\\n    WHEN 3 THEN 'Torn page'\\n    WHEN 4 THEN 'Restored (after error)'\\n    WHEN 5 THEN 'Repaired (DBCC)'\\n    WHEN 7 THEN 'Deallocated (DBCC)'\\n  END AS event_description,\\n  sp.error_count,\\n  sp.last_update_date\\nFROM msdb.dbo.suspect_pages sp\\nJOIN sys.databases db ON sp.database_id = db.database_id\\nWHERE sp.event_type IN (1, 2, 3)\\n  AND sp.last_update_date > DATEADD(day, -14, GETDATE())\\nORDER BY sp.last_update_date DESC"}	{"condition": "row_count > 0", "description": "Recent suspect pages with I/O errors, bad checksums, or torn pages indicate hardware failure during the upgrade window"}	null	2026-02-23 20:18:31.389518
1099	sqlserver	query	Check error log for hardware and I/O failure messages	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'I/O error';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'823';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'824';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'825';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'operating system error';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'Fatal hardware';\\nSELECT DISTINCT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -14, GETDATE())\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "I/O error messages (823/824/825) or fatal hardware errors in the error log confirm hardware failure during or near the upgrade window"}	null	2026-02-23 20:18:31.389519
1100	sqlserver	query	Check SQL Server service account and its privileges	{"sql": "SELECT servicename, service_account,\\n  startup_type_desc, status_desc,\\n  instant_file_initialization_enabled,\\n  is_clustered,\\n  CASE\\n    WHEN service_account LIKE '%LocalSystem%' THEN 'LocalSystem (over-privileged)'\\n    WHEN service_account LIKE '%NT Service%' THEN 'Virtual service account (recommended)'\\n    WHEN service_account LIKE '%NT AUTHORITY%' THEN 'Built-in account'\\n    ELSE 'Domain/local account'\\n  END AS account_type\\nFROM sys.dm_server_services"}	{"condition": "row_count > 0", "description": "Service account details retrieved for permission analysis"}	null	2026-02-23 20:18:31.389519
1102	sqlserver	query	Check host OS version and platform details	{"sql": "SELECT\\n  host_platform, host_distribution,\\n  host_release, host_service_pack_level,\\n  host_sku, os_language_version\\nFROM sys.dm_os_host_info;\\nSELECT\\n  cpu_count, hyperthread_ratio,\\n  physical_memory_kb / 1024 AS physical_memory_mb,\\n  max_workers_count,\\n  virtual_machine_type_desc,\\n  socket_count, cores_per_socket,\\n  numa_node_count,\\n  SERVERPROPERTY('ProductMajorVersion') AS sql_major_version,\\n  SERVERPROPERTY('Edition') AS edition\\nFROM sys.dm_os_sys_info"}	{"condition": "host_release or cpu_count retrievable for compatibility check", "description": "OS and hardware details retrieved to validate platform support for the target CU/SP"}	null	2026-02-23 20:18:31.389521
4004	postgresql	query	Check for intermittent archive success/failure pattern	{"sql": "SELECT failed_count, archived_count, last_failed_time, last_archived_time FROM pg_stat_archiver"}	{"condition": "failed_count > 0 AND archived_count > 0", "description": "Mixed success/failure pattern may indicate exit code inconsistency in script"}	\N	2026-02-25 00:28:52.405273
1103	sqlserver	query	Check for platform compatibility indicators and end-of-life warnings	{"sql": "SELECT\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 13\\n      AND (SELECT host_release FROM sys.dm_os_host_info) < '6.2'\\n      THEN 'SQL 2016 on pre-Windows Server 2012 - unsupported'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 14\\n      AND (SELECT host_release FROM sys.dm_os_host_info) < '6.3'\\n      THEN 'SQL 2017 on pre-Windows Server 2012 R2 - unsupported'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 15\\n      AND (SELECT host_release FROM sys.dm_os_host_info) < '10.0'\\n      THEN 'SQL 2019 on pre-Windows Server 2016 - unsupported'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) = 16\\n      AND (SELECT host_release FROM sys.dm_os_host_info) < '10.0'\\n      THEN 'SQL 2022 on pre-Windows Server 2016 - unsupported'\\n    ELSE 'Platform appears supported'\\n  END AS platform_status,\\n  (SELECT host_platform FROM sys.dm_os_host_info) AS host_platform,\\n  (SELECT host_distribution FROM sys.dm_os_host_info) AS host_os,\\n  (SELECT physical_memory_kb / 1024 FROM sys.dm_os_sys_info) AS memory_mb,\\n  CASE\\n    WHEN (SELECT physical_memory_kb / 1024 FROM sys.dm_os_sys_info) < 2048\\n      THEN 'Below minimum 2 GB RAM'\\n    ELSE 'Memory meets minimum'\\n  END AS memory_status"}	{"condition": "platform_status contains 'unsupported' OR memory_status contains 'Below minimum'", "description": "Instance is running on an unsupported OS version or below minimum hardware requirements for the target SQL Server CU"}	null	2026-02-23 20:18:31.389521
1104	sqlserver	query	Check for non-SQL Server processes connected or causing waits	{"sql": "SELECT s.session_id, s.login_name, s.host_name,\\n  s.program_name, s.client_interface_name,\\n  s.status, s.last_request_start_time\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND (s.program_name LIKE '%backup%'\\n    OR s.program_name LIKE '%Veeam%'\\n    OR s.program_name LIKE '%Commvault%'\\n    OR s.program_name LIKE '%NetBackup%'\\n    OR s.program_name LIKE '%Avamar%'\\n    OR s.program_name LIKE '%Acronis%'\\n    OR s.program_name LIKE '%Quest%'\\n    OR s.program_name LIKE '%SentinelOne%'\\n    OR s.program_name LIKE '%CrowdStrike%'\\n    OR s.program_name LIKE '%Symantec%'\\n    OR s.program_name LIKE '%McAfee%'\\n    OR s.program_name LIKE '%Trend%'\\n    OR s.program_name LIKE '%monitoring%'\\n    OR s.program_name LIKE '%SolarWinds%'\\n    OR s.program_name LIKE '%Zabbix%')\\nORDER BY s.program_name"}	{"condition": "row_count > 0", "description": "Third-party backup, antivirus, or monitoring agents have active connections to SQL Server that could lock files during patching"}	null	2026-02-23 20:18:31.389522
1105	sqlserver	query	Check error log for file locking and access denied errors from external processes	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'locked';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'access denied';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'in use by another process';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'cannot open';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'sharing violation';\\nSELECT DISTINCT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -14, GETDATE())\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "File locking, access denied, or sharing violation errors indicate third-party software is interfering with SQL Server file access during patching"}	null	2026-02-23 20:18:31.389523
1106	sqlserver	query	Check AG replica states and cluster health	{"sql": "SELECT ag.name AS ag_name,\\n  ar.replica_server_name,\\n  ars.role_desc,\\n  ars.connected_state_desc,\\n  ars.operational_state_desc,\\n  ars.synchronization_health_desc,\\n  ars.last_connect_error_number,\\n  ars.last_connect_error_description,\\n  ars.last_connect_error_timestamp,\\n  ar.failover_mode_desc,\\n  ar.availability_mode_desc,\\n  ar.session_timeout\\nFROM sys.dm_hadr_availability_replica_states ars\\nJOIN sys.availability_replicas ar ON ars.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE ars.connected_state_desc = 'DISCONNECTED'\\n  OR ars.synchronization_health_desc != 'HEALTHY'\\n  OR ars.operational_state_desc != 'ONLINE'\\n  OR ars.last_connect_error_number != 0"}	{"condition": "row_count > 0", "description": "One or more AG replicas show disconnection, unhealthy sync, or connection errors indicating timeout during rolling upgrade"}	null	2026-02-23 20:18:31.389524
1107	sqlserver	query	Check cluster node status and HADR error log entries	{"sql": "SELECT node_name, status, status_description,\\n  is_current_owner\\nFROM sys.dm_os_cluster_nodes;\\nSELECT member_name, member_type_desc,\\n  member_state_desc, number_of_quorum_votes\\nFROM sys.dm_hadr_cluster_members"}	{"condition": "any node with status != 0 or member_state_desc != 'UP'", "description": "Cluster nodes that are down or in a non-UP state during patching indicate timeout or synchronization failure during the rolling upgrade"}	null	2026-02-23 20:18:31.389525
1108	sqlserver	query	Check error log for timeout and failover events during upgrade window	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'timeout';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'failover';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'lease';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'cluster';\\nSELECT DISTINCT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -7, GETDATE())\\n  AND (Text LIKE '%timeout%' OR Text LIKE '%lease expired%'\\n    OR Text LIKE '%failover%' OR Text LIKE '%lost quorum%'\\n    OR Text LIKE '%not responding%')\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "Timeout, lease expiry, or unplanned failover events in the error log confirm synchronization issues during the cluster rolling upgrade"}	null	2026-02-23 20:18:31.389525
1110	sqlserver	query	Check cluster node statuses and AG health	{"sql": "SELECT node_name, status, status_description,\\n  is_current_owner\\nFROM sys.dm_os_cluster_nodes\\nWHERE status != 0;\\nSELECT ag.name AS ag_name,\\n  ag.failure_condition_level,\\n  ag.health_check_timeout,\\n  ars.synchronization_health_desc,\\n  ar.replica_server_name,\\n  ars.connected_state_desc\\nFROM sys.availability_groups ag\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nWHERE ars.connected_state_desc = 'DISCONNECTED'\\n  OR ars.synchronization_health_desc != 'HEALTHY'"}	{"condition": "row_count > 0 with non-zero node status or disconnected/unhealthy AG replicas", "description": "Cluster nodes are down or AG replicas are disconnected, confirming cluster service failure that blocks coordinated patching"}	null	2026-02-23 20:18:31.389526
4318	postgresql	query	Check for jobs with progressively later start times over recent days	{"sql": "SELECT jobid, command, date_trunc('day', start_time) AS run_date, MIN(start_time) AS first_start, MAX(end_time) AS last_end, MAX(end_time) - MIN(start_time) AS total_span FROM cron.job_run_details WHERE start_time > now() - interval '7 days' GROUP BY jobid, command, date_trunc('day', start_time) HAVING MAX(end_time) - MIN(start_time) > interval '1 hour' ORDER BY run_date, first_start"}	{"condition": "row_count > 0", "description": "Jobs showing extended execution spans suggest cascading delays from dependent job chains"}	\N	2026-02-25 00:28:52.405273
1111	sqlserver	query	Check database compatibility levels against current SQL Server version	{"sql": "SELECT name, database_id, compatibility_level,\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 AS current_compat_level,\\n  CASE\\n    WHEN compatibility_level < 100 THEN 'Pre-SQL 2008 compat (very old)'\\n    WHEN compatibility_level = 100 THEN 'SQL Server 2008'\\n    WHEN compatibility_level = 110 THEN 'SQL Server 2012'\\n    WHEN compatibility_level = 120 THEN 'SQL Server 2014'\\n    WHEN compatibility_level = 130 THEN 'SQL Server 2016'\\n    WHEN compatibility_level = 140 THEN 'SQL Server 2017'\\n    WHEN compatibility_level = 150 THEN 'SQL Server 2019'\\n    WHEN compatibility_level = 160 THEN 'SQL Server 2022'\\n    ELSE 'Unknown'\\n  END AS compat_description,\\n  state_desc, is_read_only\\nFROM sys.databases\\nWHERE database_id > 4\\n  AND state = 0\\n  AND compatibility_level < CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10\\nORDER BY compatibility_level ASC"}	{"condition": "row_count > 0", "description": "One or more databases are running at a compatibility level below the current SQL Server version"}	null	2026-02-23 20:18:31.389527
1112	sqlserver	query	Check for databases with severely outdated compatibility levels	{"sql": "SELECT name, compatibility_level,\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 AS server_compat,\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 - compatibility_level AS compat_gap,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 - compatibility_level > 30\\n      THEN 'CRITICAL: 3+ major versions behind'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 - compatibility_level > 20\\n      THEN 'WARNING: 2+ major versions behind'\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 - compatibility_level > 10\\n      THEN 'INFO: 1 major version behind'\\n    ELSE 'Current'\\n  END AS severity,\\n  create_date, collation_name\\nFROM sys.databases\\nWHERE database_id > 4\\n  AND state = 0\\n  AND compatibility_level < CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10 - 20\\nORDER BY compatibility_level ASC"}	{"condition": "row_count > 0 with databases 2+ major versions behind", "description": "Databases at severely outdated compatibility levels (2+ versions behind) risk upgrade script failures and may use deprecated features that are removed in newer CUs"}	null	2026-02-23 20:18:31.389528
1113	sqlserver	query	Check for databases stuck in upgrade or recovery states	{"sql": "SELECT name, database_id, state_desc,\\n  is_read_only, is_in_standby,\\n  is_cleanly_shutdown,\\n  user_access_desc,\\n  DATABASEPROPERTYEX(name, 'Status') AS db_status,\\n  DATABASEPROPERTYEX(name, 'Updateability') AS updateability,\\n  DATABASEPROPERTYEX(name, 'Version') AS internal_version\\nFROM sys.databases\\nWHERE state_desc IN ('RECOVERY_PENDING', 'SUSPECT', 'EMERGENCY')\\n  OR DATABASEPROPERTYEX(name, 'Status') = 'SUSPECT'\\n  OR user_access_desc = 'SINGLE_USER'"}	{"condition": "row_count > 0", "description": "Databases in RECOVERY_PENDING, SUSPECT, or EMERGENCY state, or stuck in SINGLE_USER mode, indicate post-patch upgrade script failure"}	null	2026-02-23 20:18:31.389528
1114	sqlserver	query	Check error log for post-upgrade script failures	{"sql": "CREATE TABLE #errorlog (LogDate DATETIME, ProcessInfo VARCHAR(64), Text NVARCHAR(MAX));\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'upgrade';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'script';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'sp_vupgrade';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'database upgrade';\\nINSERT INTO #errorlog EXEC xp_readerrorlog 0, 1, N'msdb110_upgrade';\\nSELECT DISTINCT LogDate, ProcessInfo, Text\\nFROM #errorlog\\nWHERE LogDate > DATEADD(day, -14, GETDATE())\\n  AND (Text LIKE '%fail%' OR Text LIKE '%error%' OR Text LIKE '%could not%'\\n    OR Text LIKE '%upgrade step%' OR Text LIKE '%Cannot open database%')\\nORDER BY LogDate DESC;\\nDROP TABLE #errorlog"}	{"condition": "row_count > 0", "description": "Post-upgrade script failure messages confirm that CU installation succeeded at the binary level but internal database upgrade scripts failed to complete"}	null	2026-02-23 20:18:31.389529
1115	sqlserver	query	Check for active sessions and open transactions	{"sql": "SELECT\\n  COUNT(*) AS active_sessions,\\n  SUM(CASE WHEN s.status = 'running' THEN 1 ELSE 0 END) AS running_sessions,\\n  SUM(CASE WHEN t.transaction_id IS NOT NULL THEN 1 ELSE 0 END) AS sessions_with_transactions,\\n  MAX(DATEDIFF(minute, t.transaction_begin_time, GETDATE())) AS longest_tran_minutes\\nFROM sys.dm_exec_sessions s\\nLEFT JOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nLEFT JOIN sys.dm_tran_active_transactions t ON st.transaction_id = t.transaction_id\\nWHERE s.is_user_process = 1\\n  AND s.session_id != @@SPID"}	{"condition": "active_sessions > 10 OR sessions_with_transactions > 0 OR longest_tran_minutes > 5", "description": "Significant active user sessions or open transactions exist that would block clean service shutdown for patching"}	null	2026-02-23 20:18:31.38953
1116	sqlserver	query	Check for blocking chains and lock contention	{"sql": "SELECT\\n  l.resource_type, l.resource_database_id,\\n  DB_NAME(l.resource_database_id) AS database_name,\\n  l.request_mode, l.request_status,\\n  l.request_session_id,\\n  wt.blocking_session_id,\\n  wt.wait_type, wt.wait_duration_ms / 1000 AS wait_seconds,\\n  s.program_name, s.host_name, s.login_name,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1,\\n    ((CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE r.statement_end_offset END - r.statement_start_offset)/2)+1) AS current_statement\\nFROM sys.dm_tran_locks l\\nJOIN sys.dm_exec_sessions s ON l.request_session_id = s.session_id\\nLEFT JOIN sys.dm_os_waiting_tasks wt ON l.request_session_id = wt.session_id\\nLEFT JOIN sys.dm_exec_requests r ON l.request_session_id = r.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE l.request_status = 'WAIT'\\n  OR wt.blocking_session_id IS NOT NULL\\nORDER BY wt.wait_duration_ms DESC"}	{"condition": "row_count > 0 with active blocking or waiting locks", "description": "Active blocking chains and lock contention will prevent SQL Server service from stopping within the shutdown timeout, causing CU installation to fail"}	null	2026-02-23 20:18:31.38953
3854	postgresql	query	Check replication connections for hostname issues	{"sql": "SELECT client_addr, client_hostname, application_name, state FROM pg_stat_replication ORDER BY client_addr"}	{"condition": "client_hostname IS NULL", "description": "Missing client_hostname may indicate DNS resolution issues (requires log_hostname=on to populate)"}	\N	2026-02-25 00:28:52.405273
1117	sqlserver	query	Check for recent full backups of all databases	{"sql": "SELECT d.name AS database_name,\\n  d.database_id,\\n  d.recovery_model_desc,\\n  MAX(bs.backup_finish_date) AS last_full_backup,\\n  DATEDIFF(day, MAX(bs.backup_finish_date), GETDATE()) AS days_since_backup,\\n  CASE\\n    WHEN MAX(bs.backup_finish_date) IS NULL THEN 'NEVER BACKED UP'\\n    WHEN DATEDIFF(day, MAX(bs.backup_finish_date), GETDATE()) > 7 THEN 'STALE (>7 days)'\\n    WHEN DATEDIFF(day, MAX(bs.backup_finish_date), GETDATE()) > 1 THEN 'RECENT'\\n    ELSE 'CURRENT'\\n  END AS backup_status\\nFROM sys.databases d\\nLEFT JOIN msdb.dbo.backupset bs ON d.name = bs.database_name\\n  AND bs.type = 'D'\\nWHERE d.state = 0\\nGROUP BY d.name, d.database_id, d.recovery_model_desc\\nORDER BY last_full_backup ASC"}	{"condition": "any database with backup_status = 'NEVER BACKED UP' or 'STALE'", "description": "One or more databases have no recent full backup, meaning there is no rollback option if the CU installation fails or corrupts the database"}	null	2026-02-23 20:18:31.389531
1118	sqlserver	query	Check system database backup status specifically	{"sql": "SELECT d.name AS database_name,\\n  MAX(bs.backup_finish_date) AS last_full_backup,\\n  DATEDIFF(hour, MAX(bs.backup_finish_date), GETDATE()) AS hours_since_backup,\\n  CASE\\n    WHEN MAX(bs.backup_finish_date) IS NULL THEN 'CRITICAL: No backup exists'\\n    WHEN DATEDIFF(hour, MAX(bs.backup_finish_date), GETDATE()) > 24 THEN 'WARNING: No backup in last 24 hours'\\n    ELSE 'OK: Recent backup exists'\\n  END AS pre_upgrade_readiness\\nFROM sys.databases d\\nLEFT JOIN msdb.dbo.backupset bs ON d.name = bs.database_name\\n  AND bs.type = 'D'\\nWHERE d.database_id IN (1, 2, 3, 4)\\nGROUP BY d.name\\nORDER BY d.name"}	{"condition": "any system database with 'CRITICAL' or 'WARNING' pre_upgrade_readiness", "description": "System databases (master, msdb, model, tempdb) without recent backups mean there is no recovery path if CU upgrade scripts fail and corrupt the system catalog"}	null	2026-02-23 20:18:31.389532
1120	sqlserver	query	Check PAGEIOLATCH waits indicating physical I/O pressure from buffer misses	{"sql": "SELECT wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  signal_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'PAGEIOLATCH_UP')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "total PAGEIOLATCH wait_time_ms is significant (top wait type) or avg_wait_ms > 10", "description": "High PAGEIOLATCH waits confirm the buffer pool cannot satisfy read requests from cache, forcing frequent physical disk reads due to insufficient allocation"}	null	2026-02-23 20:18:31.389533
1165	sqlserver	query	Check for active cursor usage and cursor-related waits	{"sql": "SELECT\\n  (SELECT SUM(cntr_value) FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Cursor Requests/sec') AS cursor_requests,\\n  (SELECT SUM(cntr_value) FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Active cursors') AS active_cursors,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cursors(0)\\n   WHERE is_open = 1) AS open_cursors_all_sessions,\\n  (SELECT SUM(CAST(size_in_bytes AS BIGINT)) / 1048576\\n   FROM sys.dm_exec_cached_plans\\n   WHERE objtype = 'Prepared') AS prepared_plan_cache_mb"}	{"condition": "open_cursors_all_sessions > 10 OR active_cursors > 50", "description": "Significant cursor activity indicating row-by-row processing patterns"}	null	2026-02-23 20:18:31.389562
1135	sqlserver	query	Find tables with stale statistics (high modification counter relative to rows)	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(sp.object_id) + '.' + OBJECT_NAME(sp.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows AS stat_rows,\\n  sp.rows_sampled,\\n  sp.modification_counter,\\n  CASE WHEN sp.rows = 0 THEN 0\\n    ELSE CAST(sp.modification_counter AS FLOAT) / sp.rows * 100\\n  END AS pct_modified,\\n  DATEDIFF(day, sp.last_updated, GETDATE()) AS days_since_update,\\n  sp.steps AS histogram_steps\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\n  AND sp.modification_counter > 0\\n  AND sp.rows > 1000\\nORDER BY pct_modified DESC"}	{"condition": "row_count > 0 with pct_modified > 20 or days_since_update > 7", "description": "Tables with statistics modified more than 20% since last update or not updated in 7+ days are likely causing incorrect cardinality estimates"}	null	2026-02-23 20:18:31.389533
1121	sqlserver	query	Compare buffer pool usage to total database sizes	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Database pages') * 8 / 1024 AS buffer_pool_data_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Page life expectancy') AS ple_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Page reads/sec') AS page_reads_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Lazy writes/sec') AS lazy_writes_per_sec,\\n  (SELECT SUM(size) * 8 / 1024 FROM sys.master_files WHERE type = 0) AS total_data_files_mb"}	{"condition": "total_data_files_mb > buffer_pool_data_mb * 3 AND ple_seconds < 300", "description": "Total data file size far exceeds buffer pool capacity and PLE is low, indicating the working set cannot fit in the cache"}	null	2026-02-23 20:18:31.389534
1122	sqlserver	query	Check per-database buffer usage and identify hot databases	{"sql": "SELECT TOP 15\\n  DB_NAME(database_id) AS database_name,\\n  COUNT(*) * 8 / 1024 AS buffer_mb,\\n  SUM(CAST(is_modified AS INT)) * 8 / 1024 AS dirty_mb,\\n  COUNT(*) AS total_pages,\\n  SUM(CAST(is_modified AS INT)) AS dirty_pages\\nFROM sys.dm_os_buffer_descriptors\\nWHERE database_id > 0\\nGROUP BY database_id\\nORDER BY buffer_mb DESC"}	{"condition": "top database consumes > 70% of buffer pool OR multiple databases competing for limited buffer", "description": "Buffer pool is dominated by one database or spread thin across many, confirming the working set exceeds available cache and pages are being evicted constantly"}	null	2026-02-23 20:18:31.389535
6044	postgresql	config_check	Check if ssl_ciphers is at default value	{"sql": "SELECT name, setting, boot_val, source FROM pg_settings WHERE name = 'ssl_ciphers'"}	{"condition": "setting = boot_val OR source = 'default'", "description": "SSL ciphers at default — inherits OS-level OpenSSL configuration"}	\N	2026-02-25 00:28:52.405273
1125	sqlserver	query	Find tables with high scan counts and low seek counts	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.user_scans,\\n  s.user_seeks,\\n  s.user_lookups,\\n  s.user_updates,\\n  CASE WHEN s.user_seeks + s.user_scans = 0 THEN 0\\n    ELSE CAST(s.user_scans AS FLOAT) / (s.user_seeks + s.user_scans) * 100\\n  END AS scan_pct,\\n  p.rows AS row_count,\\n  (SELECT SUM(a.total_pages) * 8 / 1024\\n   FROM sys.allocation_units a\\n   JOIN sys.partitions p2 ON a.container_id = p2.hobt_id\\n   WHERE p2.object_id = s.object_id AND p2.index_id IN (0, 1)) AS table_size_mb\\nFROM sys.dm_db_index_usage_stats s\\nJOIN sys.partitions p ON s.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE s.database_id = DB_ID()\\n  AND OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\n  AND s.user_scans > 100\\n  AND p.rows > 100000\\nORDER BY s.user_scans DESC"}	{"condition": "row_count > 0 with scan_pct > 80 and table_size_mb > 100", "description": "Large tables (>100 MB) with more than 80% scans versus seeks are being fully read into the buffer pool repeatedly"}	null	2026-02-23 20:18:31.389537
1133	sqlserver	query	Check missing index recommendations with high improvement measure	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(mid.object_id) + '.' + OBJECT_NAME(mid.object_id) AS table_name,\\n  migs.avg_user_impact AS pct_improvement,\\n  migs.user_seeks + migs.user_scans AS potential_uses,\\n  migs.avg_total_user_cost AS avg_query_cost,\\n  mid.equality_columns,\\n  mid.inequality_columns,\\n  mid.included_columns,\\n  migs.avg_user_impact * (migs.user_seeks + migs.user_scans) *\\n    migs.avg_total_user_cost AS improvement_measure\\nFROM sys.dm_db_missing_index_group_stats migs\\nJOIN sys.dm_db_missing_index_groups mig ON migs.group_handle = mig.index_group_handle\\nJOIN sys.dm_db_missing_index_details mid ON mig.index_handle = mid.index_handle\\nWHERE mid.database_id = DB_ID()\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 with improvement_measure > 100000", "description": "High-impact missing indexes exist that would significantly reduce logical reads and buffer pool pressure"}	null	2026-02-23 20:18:31.389542
1126	sqlserver	query	Confirm scans are causing PAGEIOLATCH waits and buffer pressure	{"sql": "SELECT wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX')\\n  AND waiting_tasks_count > 0;\\nSELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Page life expectancy') AS ple_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Page reads/sec') AS page_reads_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Readahead pages/sec') AS readahead_per_sec"}	{"condition": "PAGEIOLATCH waits are high AND (ple_seconds < 300 OR readahead_per_sec is high)", "description": "High PAGEIOLATCH waits combined with low PLE and high read-ahead activity confirm that full table scans are flushing the buffer pool"}	null	2026-02-23 20:18:31.389537
3594	postgresql	query	Find parameters overridden at role/database level	{"sql": "SELECT r.rolname, unnest(r.rolconfig) AS role_setting FROM pg_roles r WHERE r.rolconfig IS NOT NULL AND array_length(r.rolconfig, 1) > 0 UNION ALL SELECT d.datname, unnest(setconfig) FROM pg_db_role_setting s JOIN pg_database d ON d.oid = s.setdatabase WHERE s.setrole = 0 ORDER BY 1"}	{"condition": "row_count > 0", "description": "Role or database level overrides exist — may break intended inheritance"}	\N	2026-02-25 00:28:52.405273
1127	sqlserver	query	Find queries with high grant consumption and memory spills	{"sql": "SELECT TOP 15\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_grant_kb,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_spills > 0\\n  OR qs.total_grant_kb / NULLIF(qs.execution_count, 0) > 102400\\nORDER BY qs.total_spills DESC"}	{"condition": "row_count > 0 with avg_spills > 0 or avg_grant_kb > 102400", "description": "Queries with tempdb spills or excessive memory grants indicate suboptimal plans that waste buffer pool resources"}	null	2026-02-23 20:18:31.389538
1128	sqlserver	query	Check for queries with plan quality warnings in cached plans	{"sql": "SELECT TOP 10\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.execution_count,\\n  qp.query_plan.exist('//Warnings') AS has_warnings,\\n  qp.query_plan.exist('//Warnings/SpillToTempDb') AS has_spill_warning,\\n  qp.query_plan.exist('//Warnings/NoJoinPredicate') AS has_no_join_predicate,\\n  qp.query_plan.exist('//MissingIndexes') AS has_missing_index_hint,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 50000\\n  AND qs.execution_count > 5\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "has_warnings = 1 OR has_spill_warning = 1 OR has_no_join_predicate = 1 OR has_missing_index_hint = 1", "description": "Cached execution plans contain warnings (spills, missing join predicates, missing index hints) confirming poor optimization is driving excessive buffer pool consumption"}	null	2026-02-23 20:18:31.389538
1129	sqlserver	query	Check for PAGELATCH and buffer latch contention	{"sql": "SELECT wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  signal_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'PAGELATCH_SH', 'PAGELATCH_EX', 'PAGELATCH_UP',\\n  'PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'PAGEIOLATCH_UP',\\n  'WRITELOG', 'LATCH_EX', 'LATCH_SH'\\n)\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGELATCH_EX or PAGELATCH_SH in top wait types with significant wait_time_ms", "description": "High PAGELATCH waits indicate concurrent sessions are contending for in-memory buffer pages"}	null	2026-02-23 20:18:31.389539
1130	sqlserver	query	Check for active concurrent sessions causing buffer contention	{"sql": "SELECT\\n  COUNT(*) AS total_active_requests,\\n  SUM(CASE WHEN r.wait_type LIKE 'PAGELATCH%' THEN 1 ELSE 0 END) AS page_latch_waiters,\\n  SUM(CASE WHEN r.wait_type LIKE 'PAGEIOLATCH%' THEN 1 ELSE 0 END) AS page_io_latch_waiters,\\n  MAX(r.total_elapsed_time) / 1000 AS longest_request_ms,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Page life expectancy') AS ple_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Free list stalls/sec') AS free_list_stalls_per_sec\\nFROM sys.dm_exec_requests r\\nWHERE r.session_id > 50\\n  AND r.status IN ('running', 'runnable', 'suspended')"}	{"condition": "page_latch_waiters > 3 OR free_list_stalls_per_sec > 0", "description": "Multiple sessions waiting on page latches or free list stalls confirm concurrent workload contention is exhausting the buffer pool"}	null	2026-02-23 20:18:31.38954
4274	postgresql	query	Check for job failures with connection errors	{"sql": "SELECT jobid, database, command, return_message FROM cron.job_run_details WHERE status = 'failed' AND return_message ~* '(could not connect|connection refused|timeout|host|network)' ORDER BY start_time DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Jobs failing with connection or network errors"}	\N	2026-02-25 00:28:52.405273
6076	postgresql	query	Count roles with superuser privilege	{"sql": "SELECT rolname FROM pg_roles WHERE rolsuper = true"}	{"condition": "row_count > 1", "description": "Multiple superusers can re-enable untrusted functions after removal"}	\N	2026-02-25 00:28:52.405273
1131	sqlserver	query	Identify hot pages from current latch waiters	{"sql": "SELECT\\n  wt.session_id,\\n  wt.wait_type,\\n  wt.wait_duration_ms,\\n  wt.resource_description,\\n  CASE\\n    WHEN wt.resource_description LIKE '%:%:%'\\n      THEN PARSENAME(REPLACE(wt.resource_description, ':', '.'), 3)\\n    ELSE NULL\\n  END AS database_id_str,\\n  r.command,\\n  r.status\\nFROM sys.dm_os_waiting_tasks wt\\nJOIN sys.dm_exec_requests r ON wt.session_id = r.session_id\\nWHERE wt.wait_type LIKE 'PAGELATCH%'\\nORDER BY wt.wait_duration_ms DESC"}	{"condition": "row_count > 0 with multiple sessions waiting on same resource_description pattern", "description": "Multiple sessions waiting on PAGELATCH for the same page or narrow range of pages indicates hot page concentration"}	null	2026-02-23 20:18:31.389541
4143	postgresql	query	Check for HA monitoring connections	{"sql": "SELECT application_name, count(*) AS conn_count FROM pg_stat_activity WHERE application_name ~* '(patroni|repmgr|pg_auto_failover|haproxy|pgpool)' GROUP BY application_name"}	{"condition": "row_count = 0", "description": "No monitoring tool connections; primary role not being tracked externally"}	\N	2026-02-25 00:28:52.405273
1134	sqlserver	query	Cross-reference with tables that have high scan-to-seek ratios	{"sql": "SELECT TOP 15\\n  OBJECT_SCHEMA_NAME(ius.object_id) + '.' + OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.type_desc,\\n  ius.user_scans,\\n  ius.user_seeks,\\n  ius.user_lookups,\\n  CASE WHEN ius.user_seeks + ius.user_scans = 0 THEN 0\\n    ELSE CAST(ius.user_scans AS FLOAT) / (ius.user_seeks + ius.user_scans) * 100\\n  END AS scan_pct,\\n  p.rows AS row_count\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND i.index_id <= 1\\n  AND ius.user_scans > 100\\n  AND p.rows > 10000\\n  AND OBJECTPROPERTY(ius.object_id, 'IsUserTable') = 1\\nORDER BY ius.user_scans DESC"}	{"condition": "tables from missing index list also appear with scan_pct > 50", "description": "Tables with missing indexes are also showing high scan rates on heaps or clustered indexes, confirming that missing indexes are directly causing excessive buffer pool reads"}	null	2026-02-23 20:18:31.389543
1151	sqlserver	query	Find EXEC-based dynamic SQL patterns in plan cache	{"sql": "SELECT TOP 20\\n  cp.objtype,\\n  cp.usecounts,\\n  cp.size_in_bytes / 1024 AS plan_kb,\\n  SUBSTRING(st.text, 1, 300) AS query_text\\nFROM sys.dm_exec_cached_plans cp\\nCROSS APPLY sys.dm_exec_sql_text(cp.plan_handle) st\\nWHERE cp.objtype = 'Adhoc'\\n  AND cp.usecounts = 1\\n  AND (\\n    st.text LIKE '%EXEC(%' OR st.text LIKE '%EXECUTE(%'\\n    OR st.text LIKE '%+ @%' OR st.text LIKE '%+ ''%'\\n  )\\nORDER BY cp.size_in_bytes DESC"}	{"condition": "row_count > 0", "description": "Single-use ad-hoc plans containing EXEC() or string concatenation patterns indicate dynamic SQL without parameterization"}	null	2026-02-23 20:18:31.389543
1137	sqlserver	query	Find queries with large estimated vs actual row discrepancies from Query Store	{"sql": "SELECT TOP 15\\n  qsq.query_id,\\n  qsp.plan_id,\\n  qsrs.avg_logical_io_reads,\\n  qsrs.avg_physical_io_reads,\\n  qsrs.count_executions,\\n  qsrs.avg_rowcount AS avg_actual_rows,\\n  qsp.compatibility_level,\\n  qsp.engine_version,\\n  CAST(qsp.query_plan AS XML).exist('//Warnings/PlanAffectingConvert') AS has_implicit_conversion,\\n  qst.query_sql_text\\nFROM sys.query_store_runtime_stats qsrs\\nJOIN sys.query_store_plan qsp ON qsrs.plan_id = qsp.plan_id\\nJOIN sys.query_store_query qsq ON qsp.query_id = qsq.query_id\\nJOIN sys.query_store_query_text qst ON qsq.query_text_id = qst.query_text_id\\nWHERE qsrs.avg_logical_io_reads > 10000\\n  AND qsrs.count_executions > 5\\n  AND qsrs.last_execution_time > DATEADD(day, -7, GETUTCDATE())\\nORDER BY qsrs.avg_logical_io_reads DESC"}	{"condition": "row_count > 0 with avg_logical_io_reads > 10000", "description": "High logical I/O queries found in Query Store indicate potential cardinality estimation issues driving excessive buffer usage"}	null	2026-02-23 20:18:31.389545
1139	sqlserver	query	Check index fragmentation on large tables	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.type_desc,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.avg_page_space_used_in_percent,\\n  ips.ghost_record_count,\\n  ips.version_ghost_record_count,\\n  ips.record_count,\\n  ips.forwarded_record_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.page_count > 1000\\n  AND (ips.avg_fragmentation_in_percent > 30\\n    OR ips.ghost_record_count > 1000\\n    OR ips.avg_page_space_used_in_percent < 60)\\nORDER BY ips.page_count * (100 - ips.avg_page_space_used_in_percent) DESC"}	{"condition": "row_count > 0 with fragmentation > 30% or ghost_record_count > 1000", "description": "Large indexes with high fragmentation, many ghost records, or low page density are wasting buffer pool space"}	null	2026-02-23 20:18:31.389546
4275	postgresql	query	Check if pg_cron extension is available	{"sql": "SELECT extname, extversion FROM pg_extension WHERE extname = 'pg_cron'"}	{"condition": "row_count = 0", "description": "pg_cron not installed; jobs likely rely on OS cron + psql"}	\N	2026-02-25 00:28:52.405273
1147	sqlserver	query	Find query_hash groups with multiple sql_handle variants	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  COUNT(DISTINCT qs.sql_handle) AS distinct_sql_handles,\\n  COUNT(DISTINCT qs.plan_handle) AS distinct_plans,\\n  SUM(qs.execution_count) AS total_executions,\\n  SUM(cp.size_in_bytes) / 1024 AS total_plan_kb,\\n  MIN(SUBSTRING(st.text, 1, 150)) AS sample_1,\\n  MAX(SUBSTRING(st.text, 1, 150)) AS sample_2\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nJOIN sys.dm_exec_cached_plans cp ON qs.plan_handle = cp.plan_handle\\nGROUP BY qs.query_hash\\nHAVING COUNT(DISTINCT qs.sql_handle) > 3\\nORDER BY distinct_sql_handles DESC"}	{"condition": "row_count > 0 with distinct_sql_handles > 3 for same query_hash", "description": "Multiple distinct sql_handle values for the same query_hash means logically identical queries are cached separately due to text differences (whitespace, casing)"}	null	2026-02-23 20:18:31.389546
1603	sqlserver	query	Check if AUTO_CREATE_STATISTICS is enabled	{"sql": "SELECT name AS database_name,\\n  is_auto_create_stats_on,\\n  is_auto_update_stats_on\\nFROM sys.databases\\nWHERE database_id = DB_ID()"}	{"condition": "is_auto_create_stats_on = 0", "description": "AUTO_CREATE_STATISTICS is disabled — new columns will not get statistics automatically"}	null	2026-02-23 20:18:31.389837
1140	sqlserver	query	Check ghost cleanup performance counter and forwarded records	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Access Methods%'\\n     AND counter_name = 'Ghost Cleanup Rate') AS ghost_cleanup_rate,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Access Methods%'\\n     AND counter_name = 'Forwarded Records/sec') AS forwarded_records_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Access Methods%'\\n     AND counter_name = 'Full Scans/sec') AS full_scans_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Page life expectancy') AS ple_seconds"}	{"condition": "forwarded_records_per_sec > 100 OR (ghost_cleanup_rate is active AND ple_seconds < 300)", "description": "High forwarded records rate on heap tables or active ghost cleanup combined with low PLE confirm that bloated indexes and ghost records are degrading buffer pool efficiency"}	null	2026-02-23 20:18:31.389547
1141	sqlserver	query	Check recovery interval setting and checkpoint wait stats	{"sql": "SELECT name, value_in_use AS recovery_interval_seconds,\\n  CASE\\n    WHEN value_in_use = 0 THEN 'Auto (approximately 1 minute)'\\n    WHEN value_in_use < 60 THEN 'Aggressive (under 60 seconds)'\\n    ELSE CAST(value_in_use AS VARCHAR) + ' seconds'\\n  END AS checkpoint_description\\nFROM sys.configurations\\nWHERE name = 'recovery interval (min)';\\nSELECT wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CHECKPOINT_QUEUE', 'CHKPT', 'WRITELOG')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "recovery_interval_seconds < 60 AND CHECKPOINT_QUEUE wait_time_ms is significant", "description": "Recovery interval is set aggressively low and checkpoint queue waits are measurable, indicating frequent checkpoint activity"}	null	2026-02-23 20:18:31.389548
1142	sqlserver	query	Check checkpoint I/O volume and page writes rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Checkpoint pages/sec') AS checkpoint_pages_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Background writer pages/sec') AS bg_writer_pages_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Lazy writes/sec') AS lazy_writes_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Page life expectancy') AS ple_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Page writes/sec') AS page_writes_per_sec"}	{"condition": "checkpoint_pages_per_sec is high relative to page_writes_per_sec AND ple_seconds drops after checkpoints", "description": "High checkpoint page write rate relative to total writes confirms checkpoints are dominating I/O and disrupting the buffer pool working set"}	null	2026-02-23 20:18:31.389548
1143	sqlserver	query	Check OS memory state and SQL Server memory notifications	{"sql": "SELECT\\n  pm.physical_memory_in_use_kb / 1024 AS sql_physical_memory_mb,\\n  pm.locked_page_allocations_kb / 1024 AS locked_pages_mb,\\n  pm.virtual_address_space_committed_kb / 1024 AS committed_mb,\\n  pm.memory_utilization_percentage,\\n  pm.page_fault_count,\\n  pm.process_physical_memory_low AS memory_low_notification,\\n  pm.process_virtual_memory_low AS virtual_memory_low,\\n  sm.total_physical_memory_kb / 1024 AS os_total_memory_mb,\\n  sm.available_physical_memory_kb / 1024 AS os_available_memory_mb,\\n  sm.system_memory_state_desc\\nFROM sys.dm_os_process_memory pm\\nCROSS JOIN sys.dm_os_sys_memory sm"}	{"condition": "system_memory_state_desc LIKE '%low%' OR os_available_memory_mb < 512 OR memory_low_notification = 1", "description": "OS reports low memory state or SQL Server has received a low memory notification, indicating the system is under memory pressure"}	null	2026-02-23 20:18:31.389549
1144	sqlserver	query	Check for active paging and memory clerk pressure	{"sql": "SELECT TOP 10\\n  type AS clerk_type,\\n  name AS clerk_name,\\n  pages_kb / 1024 AS memory_mb\\nFROM sys.dm_os_memory_clerks\\nORDER BY pages_kb DESC;\\nSELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Page life expectancy') AS ple_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n     AND counter_name = 'Memory Grants Pending') AS grants_pending,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n     AND counter_name = 'Target Server Memory (KB)') / 1024 AS target_memory_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n     AND counter_name = 'Total Server Memory (KB)') / 1024 AS total_memory_mb"}	{"condition": "total_memory_mb < target_memory_mb * 0.9 OR grants_pending > 0", "description": "SQL Server's current memory is below its target allocation or memory grants are pending, confirming the OS is reclaiming memory from SQL Server (swapping) and the buffer pool is being compressed"}	null	2026-02-23 20:18:31.38955
1145	sqlserver	query	Check plan cache for single-use ad-hoc plan ratio	{"sql": "SELECT\\n  objtype,\\n  COUNT(*) AS plan_count,\\n  SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) AS single_use_count,\\n  CAST(SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) AS FLOAT) / NULLIF(COUNT(*), 0) * 100 AS single_use_pct,\\n  SUM(size_in_bytes) / 1024 / 1024 AS total_size_mb,\\n  SUM(CASE WHEN usecounts = 1 THEN size_in_bytes ELSE 0 END) / 1024 / 1024 AS single_use_size_mb\\nFROM sys.dm_exec_cached_plans\\nGROUP BY objtype\\nORDER BY total_size_mb DESC"}	{"condition": "single_use_pct > 50 for Adhoc objtype AND single_use_size_mb > 100", "description": "More than 50% of ad-hoc plans are single-use and consuming significant memory, indicating plan cache bloat from literal values"}	null	2026-02-23 20:18:31.38955
1146	sqlserver	query	Find specific examples of similar queries differing only by literal values	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  COUNT(*) AS variant_count,\\n  SUM(qs.execution_count) AS total_executions,\\n  AVG(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS avg_logical_reads,\\n  MIN(SUBSTRING(st.text, 1, 200)) AS sample_query\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.execution_count = 1\\nGROUP BY qs.query_hash\\nHAVING COUNT(*) > 10\\nORDER BY variant_count DESC"}	{"condition": "row_count > 0 with variant_count > 10", "description": "Multiple cached plans sharing the same query_hash but with different sql_handle values confirm identical query patterns with different literal values creating separate plan cache entries"}	null	2026-02-23 20:18:31.389551
1667	sqlserver	query	Check SQL Server version and TF 1118 applicability	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS major_version,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 13\\n    THEN 'SQL 2016+ - uniform extents default for tempdb'\\n    ELSE 'Pre-2016 - TF 1118 needed'\\n  END AS tf1118_recommendation"}	{"condition": "major_version < 13", "description": "Pre-SQL Server 2016 instance where TF 1118 is needed to prevent mixed extent allocation"}	null	2026-02-23 20:18:31.389883
1149	sqlserver	query	Check plan cache for plans with different schema-bound attributes	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  COUNT(DISTINCT qs.plan_handle) AS distinct_plans,\\n  COUNT(DISTINCT pa_schema.value) AS distinct_schemas,\\n  COUNT(DISTINCT pa_user.value) AS distinct_users,\\n  SUM(cp.size_in_bytes) / 1024 AS total_plan_kb,\\n  MIN(SUBSTRING(st.text, 1, 200)) AS sample_query\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nJOIN sys.dm_exec_cached_plans cp ON qs.plan_handle = cp.plan_handle\\nOUTER APPLY sys.dm_exec_plan_attributes(qs.plan_handle) pa_schema\\nOUTER APPLY sys.dm_exec_plan_attributes(qs.plan_handle) pa_user\\nWHERE pa_schema.attribute = 'set_options'\\n  AND pa_user.attribute = 'user_id'\\nGROUP BY qs.query_hash\\nHAVING COUNT(DISTINCT qs.plan_handle) > 3\\n  AND COUNT(DISTINCT pa_user.value) > 1\\nORDER BY distinct_plans DESC"}	{"condition": "row_count > 0 with distinct_plans > 3 and distinct_users > 1", "description": "Same query hash has multiple cached plans created by different users, indicating unqualified object references cause schema-context-dependent caching"}	null	2026-02-23 20:18:31.389551
1157	sqlserver	query	Check databases with forced parameterization enabled	{"sql": "SELECT d.name AS database_name,\\n  d.is_parameterization_forced,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Forced Parameterizations/sec'\\n     AND instance_name = d.name) AS forced_param_count,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Failed Forced Parameterizations/sec'\\n     AND instance_name = d.name) AS failed_forced_param_count\\nFROM sys.databases d\\nWHERE d.is_parameterization_forced = 1\\n  AND d.database_id > 4"}	{"condition": "is_parameterization_forced = 1 with failed_forced_param_count > 0", "description": "Databases with forced parameterization enabled, especially with failed parameterization attempts"}	null	2026-02-23 20:18:31.389556
1150	sqlserver	query	Check for users with non-dbo default schemas and plan attribute differences	{"sql": "SELECT dp.name AS user_name,\\n  dp.default_schema_name,\\n  COUNT(*) AS user_count\\nFROM sys.database_principals dp\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND dp.default_schema_name IS NOT NULL\\n  AND dp.default_schema_name != 'dbo'\\n  AND dp.name NOT IN ('guest', 'INFORMATION_SCHEMA', 'sys')\\nGROUP BY dp.name, dp.default_schema_name;\\nSELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans WHERE objtype = 'Adhoc') AS total_adhoc_plans,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans WHERE objtype = 'Prepared') AS total_prepared_plans,\\n  (SELECT SUM(size_in_bytes) / 1024 / 1024 FROM sys.dm_exec_cached_plans) AS total_plan_cache_mb"}	{"condition": "users with non-dbo default schemas exist AND total_adhoc_plans is high", "description": "Users with different default schemas combined with a high ad-hoc plan count confirm that unqualified object references are generating schema-specific plan cache entries"}	null	2026-02-23 20:18:31.389552
1152	sqlserver	query	Compare EXEC vs sp_executesql usage and quantify plan cache impact	{"sql": "SELECT\\n  SUM(CASE WHEN st.text LIKE '%sp_executesql%' THEN 1 ELSE 0 END) AS parameterized_plans,\\n  SUM(CASE WHEN st.text LIKE '%EXEC(%' OR st.text LIKE '%EXECUTE(%' THEN 1 ELSE 0 END) AS exec_plans,\\n  SUM(CASE WHEN cp.usecounts = 1 AND cp.objtype = 'Adhoc' THEN 1 ELSE 0 END) AS single_use_adhoc,\\n  SUM(CASE WHEN cp.usecounts = 1 AND cp.objtype = 'Adhoc' THEN cp.size_in_bytes ELSE 0 END) / 1024 / 1024 AS single_use_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Plan Cache%'\\n     AND counter_name = 'Cache Object Counts'\\n     AND instance_name = 'SQL Plans') AS sql_plan_count,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Plan Cache%'\\n     AND counter_name = 'Cache Object Counts'\\n     AND instance_name = '_Total') AS total_cache_objects\\nFROM sys.dm_exec_cached_plans cp\\nCROSS APPLY sys.dm_exec_sql_text(cp.plan_handle) st"}	{"condition": "exec_plans > parameterized_plans AND single_use_mb > 50", "description": "More EXEC-based dynamic SQL than parameterized sp_executesql calls, combined with significant single-use plan cache consumption, confirms dynamic SQL without parameterization is bloating the plan cache"}	null	2026-02-23 20:18:31.389553
1154	sqlserver	query	Identify distinct client applications and their plan cache footprint	{"sql": "SELECT\\n  s.program_name,\\n  s.client_interface_name,\\n  COUNT(DISTINCT s.session_id) AS active_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_stats qs2\\n   CROSS APPLY sys.dm_exec_sql_text(qs2.sql_handle) st2\\n   JOIN sys.dm_exec_cached_plans cp2 ON qs2.plan_handle = cp2.plan_handle\\n   WHERE cp2.objtype = 'Adhoc' AND cp2.usecounts = 1) AS total_single_use_plans,\\n  (SELECT SUM(size_in_bytes) / 1024 / 1024 FROM sys.dm_exec_cached_plans\\n   WHERE objtype = 'Adhoc' AND usecounts = 1) AS single_use_cache_mb,\\n  (SELECT SUM(size_in_bytes) / 1024 / 1024 FROM sys.dm_exec_cached_plans) AS total_cache_mb\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.program_name IS NOT NULL\\n  AND s.program_name != ''\\nGROUP BY s.program_name, s.client_interface_name\\nORDER BY active_sessions DESC"}	{"condition": "multiple distinct program_name values AND single_use_cache_mb > total_cache_mb * 0.3", "description": "Multiple client applications are connected and single-use plans constitute more than 30% of the total plan cache, confirming that different applications are generating similar-but-distinct query text"}	null	2026-02-23 20:18:31.389554
1155	sqlserver	query	Check parameterization mode and single-use plan statistics	{"sql": "SELECT\\n  d.name AS database_name,\\n  d.is_parameterization_forced,\\n  DATABASEPROPERTYEX(d.name, 'IsParameterizationForced') AS forced_param,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans WHERE objtype = 'Adhoc' AND usecounts = 1) AS single_use_adhoc,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans WHERE objtype = 'Adhoc') AS total_adhoc,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans WHERE objtype = 'Prepared') AS total_prepared,\\n  (SELECT SUM(size_in_bytes) / 1024 / 1024 FROM sys.dm_exec_cached_plans WHERE objtype = 'Adhoc' AND usecounts = 1) AS single_use_mb,\\n  (SELECT value_in_use FROM sys.configurations WHERE name = 'optimize for ad hoc workloads') AS optimize_adhoc\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "is_parameterization_forced = 0 AND single_use_adhoc > total_adhoc * 0.5", "description": "Simple parameterization is in effect (not forced) and more than half of ad-hoc plans are single-use, indicating auto-parameterization is failing for many queries"}	null	2026-02-23 20:18:31.389554
4276	postgresql	process	Verify database is healthy for external job connections	{"sql": "SELECT count(*) AS connections, pg_postmaster_start_time() AS uptime_since FROM pg_stat_activity"}	{"condition": "connections > 0", "description": "Database is accepting connections; issue is with OS cron service, not PostgreSQL"}	\N	2026-02-25 00:28:52.405273
1189	sqlserver	query	Check spinlock contention on plan cache structures	{"sql": "SELECT name AS spinlock_name,\\n  collisions, spins, spins_per_collision,\\n  sleep_time, backoffs\\nFROM sys.dm_os_spinlock_stats\\nWHERE name IN ('CACHESTORE_SQLCP', 'CACHESTORE_OBJCP', 'CACHESTORE_PHDR',\\n  'SOS_CACHESTORE', 'LOCK_HASH')\\n  AND collisions > 0\\nORDER BY collisions DESC"}	{"condition": "CACHESTORE_SQLCP collisions > 100000 OR spins_per_collision > 1000", "description": "High spinlock collisions on plan cache stores indicate serialization contention when multiple sessions simultaneously access or insert plans"}	null	2026-02-23 20:18:31.389555
1668	sqlserver	query	Check trace flag 1118 status	{"sql": "DBCC TRACESTATUS(1118, -1)"}	{"condition": "TF 1118 not enabled (Status = 0 or no rows)", "description": "TF 1118 not active — tempdb using mixed extent allocations"}	null	2026-02-23 20:18:31.389883
1156	sqlserver	query	Find queries that failed simple parameterization by examining query_hash groups	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  COUNT(*) AS plan_count,\\n  SUM(CASE WHEN cp.usecounts = 1 THEN 1 ELSE 0 END) AS single_use_count,\\n  SUM(cp.size_in_bytes) / 1024 AS total_plan_kb,\\n  MIN(SUBSTRING(st.text, 1, 200)) AS sample_query,\\n  CASE\\n    WHEN MIN(st.text) LIKE '%JOIN%JOIN%' THEN 'Multiple JOINs (too complex for simple param)'\\n    WHEN MIN(st.text) LIKE '%IN (%' THEN 'IN clause (variable length list)'\\n    WHEN MIN(st.text) LIKE '%LIKE%' THEN 'LIKE predicate'\\n    WHEN MIN(st.text) LIKE '%CASE%' THEN 'CASE expression'\\n    WHEN MIN(st.text) LIKE '%OR%' THEN 'OR predicate'\\n    ELSE 'Other complex pattern'\\n  END AS likely_failure_reason\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nJOIN sys.dm_exec_cached_plans cp ON qs.plan_handle = cp.plan_handle\\nWHERE cp.objtype = 'Adhoc'\\n  AND cp.usecounts = 1\\nGROUP BY qs.query_hash\\nHAVING COUNT(*) > 10\\nORDER BY plan_count DESC"}	{"condition": "row_count > 0 with plan_count > 10 and identified failure patterns", "description": "Multiple single-use plans with the same query_hash confirm simple parameterization is failing to auto-parameterize these queries, each literal combination creating a new cache entry"}	null	2026-02-23 20:18:31.389556
1646	sqlserver	query	Check target recovery time settings across databases	{"sql": "SELECT d.name, d.target_recovery_time_in_seconds,\\n  d.recovery_model_desc,\\n  d.log_reuse_wait_desc\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.target_recovery_time_in_seconds > 0\\nORDER BY d.target_recovery_time_in_seconds ASC"}	{"condition": "target_recovery_time_in_seconds < 20", "description": "Target recovery time under 20 seconds is aggressive for most workloads"}	null	2026-02-23 20:18:31.38987
1158	sqlserver	query	Check for suboptimal plans caused by forced parameterization	{"sql": "SELECT TOP 20\\n  qs.plan_handle,\\n  qs.execution_count,\\n  qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.min_elapsed_time,\\n  qs.max_elapsed_time,\\n  CASE WHEN qs.max_elapsed_time > qs.min_elapsed_time * 10\\n    THEN 'HIGH_VARIANCE' ELSE 'STABLE' END AS plan_stability,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.execution_count > 10\\n  AND qs.max_elapsed_time > qs.min_elapsed_time * 10\\nORDER BY (qs.max_elapsed_time - qs.min_elapsed_time) DESC"}	{"condition": "queries with HIGH_VARIANCE where max_elapsed > 10x min_elapsed", "description": "High variance in execution times indicates parameter-sensitive plans being forced into one-size-fits-all parameterized form"}	null	2026-02-23 20:18:31.389557
1159	sqlserver	query	Measure single-use plan ratio in cache	{"sql": "SELECT\\n  COUNT(*) AS total_plans,\\n  SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) AS single_use_plans,\\n  CAST(SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0) AS DECIMAL(5,1)) AS single_use_pct,\\n  SUM(CASE WHEN usecounts = 1 THEN CAST(size_in_bytes AS BIGINT) ELSE 0 END) / 1048576 AS single_use_mb,\\n  SUM(CAST(size_in_bytes AS BIGINT)) / 1048576 AS total_cache_mb\\nFROM sys.dm_exec_cached_plans\\nWHERE objtype = 'Adhoc'"}	{"condition": "single_use_pct > 50 OR single_use_mb > 256", "description": "More than half of ad-hoc plans are single-use, or single-use plans consume over 256 MB"}	null	2026-02-23 20:18:31.389558
1160	sqlserver	query	Check if optimize for ad hoc workloads is enabled	{"sql": "SELECT name,\\n  CAST(value_in_use AS INT) AS value_in_use\\nFROM sys.configurations\\nWHERE name = 'optimize for ad hoc workloads'"}	{"condition": "value_in_use = 0", "description": "Optimize for ad hoc workloads is disabled — full plans cached on first execution instead of compiled plan stubs"}	null	2026-02-23 20:18:31.389558
1161	sqlserver	query	Count cached plans for temporary procedures	{"sql": "SELECT\\n  COUNT(*) AS temp_proc_plans,\\n  SUM(CAST(size_in_bytes AS BIGINT)) / 1048576 AS temp_proc_cache_mb,\\n  SUM(usecounts) AS total_executions\\nFROM sys.dm_exec_cached_plans cp\\nCROSS APPLY sys.dm_exec_sql_text(cp.plan_handle) t\\nWHERE cp.objtype = 'Proc'\\n  AND t.text LIKE '%#%'\\n  AND t.objectid IS NOT NULL"}	{"condition": "temp_proc_plans > 100 OR temp_proc_cache_mb > 50", "description": "Significant number of temporary procedure plans in cache"}	null	2026-02-23 20:18:31.389559
1163	sqlserver	query	Find applications with high single-use plan counts	{"sql": "SELECT TOP 15\\n  s.program_name,\\n  s.host_name,\\n  COUNT(DISTINCT qs.plan_handle) AS unique_plans,\\n  SUM(CASE WHEN qs.execution_count = 1 THEN 1 ELSE 0 END) AS single_use_plans,\\n  SUM(CAST(qs.total_elapsed_time AS BIGINT)) / 1000000 AS total_elapsed_sec\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nJOIN sys.dm_exec_sessions s ON t.dbid = DB_ID()\\nWHERE s.is_user_process = 1\\n  AND s.program_name IS NOT NULL\\n  AND s.program_name <> ''\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(DISTINCT qs.plan_handle) > 50\\nORDER BY single_use_plans DESC"}	{"condition": "applications with single_use_plans > 50", "description": "Applications generating many unique, single-execution plans"}	null	2026-02-23 20:18:31.38956
3595	postgresql	query	Check replication slot and sender configuration	{"sql": "SELECT slot_name, slot_type, active, database, plugin FROM pg_replication_slots ORDER BY slot_name"}	{"condition": "row_count > 0", "description": "Replication slots configured — verify they match standby expectations"}	\N	2026-02-25 00:28:52.405273
1169	sqlserver	query	Check ghost record and cleanup counters	{"sql": "SELECT\\n  object_name, counter_name, cntr_value\\nFROM sys.dm_os_performance_counters\\nWHERE counter_name IN (\\n  'Ghost Records/sec', 'Ghost Cleanup/sec',\\n  'Version Generation rate (KB/s)', 'Version Store Size (KB)'\\n)\\n  AND cntr_value > 0\\nORDER BY counter_name"}	{"condition": "Ghost Records/sec significantly exceeds Ghost Cleanup/sec", "description": "Ghost records are being created faster than the ghost cleanup task can process them"}	null	2026-02-23 20:18:31.389564
10183	mysql	query	Check SSL status and certificate validity	{"sql": "SHOW STATUS LIKE 'Ssl_server_not_after'"}	{"condition": "Ssl_server_not_after < CURRENT_DATE + INTERVAL 30 DAY", "description": "SSL certificate expiring within 30 days or already expired"}	\N	2026-03-01 06:30:58.706791
1170	sqlserver	query	Check ghost cleanup rate vs ghost record creation rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Ghost Records/sec'\\n     AND instance_name = '_Total') AS ghost_records_created,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Ghost Cleanup/sec'\\n     AND instance_name = '_Total') AS ghost_records_cleaned,\\n  (SELECT SUM(ghost_record_count)\\n   FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'SAMPLED')\\n   WHERE page_count > 100) AS current_ghost_records"}	{"condition": "ghost_records_created > ghost_records_cleaned AND current_ghost_records > 1000", "description": "Ghost creation rate exceeds cleanup rate with significant accumulation"}	null	2026-02-23 20:18:31.389566
1171	sqlserver	query	Check for ghost cleanup throttling or blocking	{"sql": "SELECT\\n  CASE WHEN EXISTS (SELECT 1 FROM sys.dm_os_waiting_tasks\\n    WHERE wait_type LIKE 'GHOST%') THEN 1 ELSE 0 END AS ghost_cleanup_waiting,\\n  (SELECT COUNT(*) FROM sys.dm_tran_active_snapshot_database_transactions) AS active_snapshot_txns,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Version Store Size (KB)') AS version_store_kb,\\n  (SELECT DATEDIFF(SECOND, MIN(transaction_begin_time), GETDATE())\\n   FROM sys.dm_tran_active_transactions\\n   WHERE transaction_type = 1 AND transaction_state = 2) AS oldest_active_txn_sec"}	{"condition": "ghost_cleanup_waiting = 1 OR active_snapshot_txns > 0 with large version_store_kb", "description": "Ghost cleanup is being blocked or throttled by active snapshot transactions or version store pressure"}	null	2026-02-23 20:18:31.389566
1172	sqlserver	query	Check for long-running snapshot transactions and version store size	{"sql": "SELECT\\n  ast.transaction_id,\\n  ast.elapsed_time_seconds,\\n  ast.session_id,\\n  s.program_name,\\n  s.host_name,\\n  s.login_name,\\n  CASE s.status\\n    WHEN 'sleeping' THEN 'IDLE'\\n    ELSE s.status END AS session_status,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Version Store Size (KB)') AS version_store_kb\\nFROM sys.dm_tran_active_snapshot_database_transactions ast\\nJOIN sys.dm_exec_sessions s ON ast.session_id = s.session_id\\nWHERE ast.elapsed_time_seconds > 300\\nORDER BY ast.elapsed_time_seconds DESC"}	{"condition": "snapshot transactions older than 300 seconds with growing version_store_kb", "description": "Long-running snapshot transactions preventing version store cleanup"}	null	2026-02-23 20:18:31.389567
1202	sqlserver	query	Check for async stats update configuration	{"sql": "SELECT name AS database_name,\\n  is_auto_update_stats_on,\\n  is_auto_update_stats_async_on,\\n  is_auto_create_stats_on\\nFROM sys.databases\\nWHERE database_id > 4\\n  AND state_desc = 'ONLINE'\\nORDER BY name"}	{"condition": "is_auto_update_stats_on = 1 AND is_auto_update_stats_async_on = 0", "description": "Synchronous auto-update statistics is enabled, meaning stats updates block query execution and immediately invalidate cached plans, amplifying the recompilation impact of frequently changing tables"}	null	2026-02-23 20:18:31.389585
1173	sqlserver	query	Check tempdb version store space usage and ghost record accumulation	{"sql": "SELECT\\n  SUM(version_store_reserved_page_count) * 8 / 1024 AS version_store_mb,\\n  SUM(user_object_reserved_page_count) * 8 / 1024 AS user_objects_mb,\\n  SUM(internal_object_reserved_page_count) * 8 / 1024 AS internal_objects_mb\\nFROM sys.dm_db_file_space_usage\\nWHERE database_id = 2;\\nSELECT TOP 10\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  SUM(ips.ghost_record_count) AS total_ghost_records,\\n  SUM(ips.version_ghost_record_count) AS version_ghost_records\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'SAMPLED') ips\\nWHERE ips.page_count > 500\\nGROUP BY ips.object_id\\nHAVING SUM(ips.version_ghost_record_count) > 0\\nORDER BY version_ghost_records DESC"}	{"condition": "version_store_mb > 500 OR version_ghost_records accumulating", "description": "Version store consuming significant tempdb space and version ghost records accumulating on tables"}	null	2026-02-23 20:18:31.389569
1174	sqlserver	query	Check modification rates on tables	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  SUM(ios.leaf_delete_count) AS total_deletes,\\n  SUM(ios.leaf_update_count) AS total_updates,\\n  SUM(ios.leaf_ghost_count) AS current_ghost_rows,\\n  SUM(ios.leaf_delete_count + ios.leaf_update_count) AS total_modifications\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nWHERE ios.leaf_delete_count + ios.leaf_update_count > 0\\nGROUP BY ios.object_id\\nHAVING SUM(ios.leaf_ghost_count) > 100\\nORDER BY total_modifications DESC"}	{"condition": "tables with leaf_ghost_count > 100 and high modification counts", "description": "Tables with high DELETE/UPDATE activity accumulating ghost records"}	null	2026-02-23 20:18:31.389569
1175	sqlserver	query	Compare ghost records against total rows to assess bloat severity	{"sql": "SELECT TOP 10\\n  OBJECT_NAME(p.object_id) AS table_name,\\n  p.rows AS live_rows,\\n  SUM(ips.ghost_record_count) AS ghost_records,\\n  CASE WHEN p.rows > 0\\n    THEN CAST(SUM(ips.ghost_record_count) * 100.0 / p.rows AS DECIMAL(5,1))\\n    ELSE 0 END AS ghost_pct_of_live_rows,\\n  SUM(ips.page_count) AS total_pages\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'SAMPLED') ips\\nJOIN sys.partitions p ON ips.object_id = p.object_id AND ips.index_id = p.index_id\\nWHERE ips.ghost_record_count > 0\\n  AND p.rows > 0\\nGROUP BY p.object_id, p.rows\\nHAVING SUM(ips.ghost_record_count) > 100\\nORDER BY ghost_pct_of_live_rows DESC"}	{"condition": "ghost_pct_of_live_rows > 10%", "description": "Ghost records exceed 10% of live rows — significant bloat affecting scan performance"}	null	2026-02-23 20:18:31.38957
1176	sqlserver	query	Check indexes with fill factor 100% and page split activity	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.fill_factor,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.nonleaf_allocation_count AS nonleaf_splits,\\n  ios.leaf_insert_count,\\n  ios.leaf_update_count,\\n  ips.page_count,\\n  ips.avg_fragmentation_in_percent\\nFROM sys.indexes i\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nJOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\n  ON i.object_id = ips.object_id AND i.index_id = ips.index_id\\nWHERE i.fill_factor IN (0, 100)\\n  AND ios.leaf_allocation_count > 100\\n  AND ips.page_count > 500\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "indexes with fill_factor 0/100 and high leaf_allocation_count (page splits)", "description": "Indexes at 100% fill factor experiencing frequent page splits due to INSERT/UPDATE activity"}	null	2026-02-23 20:18:31.38957
1177	sqlserver	query	Correlate page splits with fragmentation growth	{"sql": "SELECT TOP 10\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.avg_page_space_used_in_percent,\\n  ips.page_count,\\n  ips.fragment_count,\\n  CASE WHEN ips.avg_page_space_used_in_percent < 70\\n    THEN 'LOW_DENSITY' ELSE 'OK' END AS page_density\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'DETAILED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.page_count > 500\\n  AND ips.avg_fragmentation_in_percent > 30\\n  AND i.fill_factor IN (0, 100)\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation > 30% with avg_page_space_used < 70%", "description": "High fragmentation with low page density confirms page splits from 100% fill factor"}	null	2026-02-23 20:18:31.389571
4277	postgresql	query	Check for increasing job execution times	{"sql": "SELECT jobid, command, start_time, end_time, (end_time - start_time) AS duration FROM cron.job_run_details WHERE status = 'succeeded' ORDER BY start_time DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Review recent job durations for trending upward"}	\N	2026-02-25 00:28:52.405273
6174	postgresql	query	Check pgaudit configuration	{"sql": "SELECT extname FROM pg_extension WHERE extname = 'pgaudit'"}	{"condition": "row_count > 0", "description": "pgaudit installed"}	\N	2026-02-25 00:28:52.405273
1198	sqlserver	query	Check plan cache hit ratio and single-use plan bloat	{"sql": "SELECT\\n  objtype AS plan_type,\\n  COUNT(*) AS plan_count,\\n  SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) AS single_use_plans,\\n  SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0) AS single_use_pct,\\n  SUM(size_in_bytes) / 1048576 AS total_size_mb,\\n  SUM(CASE WHEN usecounts = 1 THEN size_in_bytes ELSE 0 END) / 1048576 AS single_use_mb\\nFROM sys.dm_exec_cached_plans\\nGROUP BY objtype\\nORDER BY single_use_plans DESC"}	{"condition": "single_use_pct > 50 for Adhoc plan type", "description": "More than 50% of ad-hoc plans used only once indicates applications are not parameterizing queries, causing plan cache bloat with heterogeneous plans"}	null	2026-02-23 20:18:31.389572
1178	sqlserver	query	Check AG replica synchronization state and queue sizes	{"sql": "SELECT\\n  ag.name AS ag_name,\\n  ar.replica_server_name,\\n  ar.availability_mode_desc,\\n  drs.synchronization_state_desc,\\n  drs.synchronization_health_desc,\\n  drs.log_send_queue_size,\\n  drs.log_send_rate,\\n  drs.redo_queue_size,\\n  drs.redo_rate,\\n  CASE WHEN drs.redo_rate > 0\\n    THEN drs.redo_queue_size / drs.redo_rate ELSE -1 END AS est_redo_catchup_sec,\\n  CASE WHEN drs.log_send_rate > 0\\n    THEN drs.log_send_queue_size / drs.log_send_rate ELSE -1 END AS est_send_catchup_sec,\\n  drs.last_commit_time\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nJOIN sys.availability_groups ag ON ar.group_id = ag.group_id\\nWHERE drs.is_primary_replica = 0"}	{"condition": "log_send_queue_size > 500 OR redo_queue_size > 500 OR synchronization_state_desc NOT IN ('SYNCHRONIZED', 'SYNCHRONIZING')", "description": "Secondary replicas with growing queues or not in synchronized state"}	null	2026-02-23 20:18:31.389572
1179	sqlserver	query	Check for sustained lag by examining commit time delta	{"sql": "SELECT\\n  ar.replica_server_name,\\n  drs.last_commit_time,\\n  drs.last_hardened_time,\\n  DATEDIFF(SECOND, drs.last_commit_time, GETDATE()) AS commit_lag_seconds,\\n  drs.log_send_queue_size,\\n  drs.redo_queue_size\\nFROM sys.dm_hadr_database_replica_states drs\\nJOIN sys.availability_replicas ar ON drs.replica_id = ar.replica_id\\nWHERE drs.is_primary_replica = 0\\n  AND (drs.log_send_queue_size > 500 OR drs.redo_queue_size > 500\\n    OR DATEDIFF(SECOND, drs.last_commit_time, GETDATE()) > 60)"}	{"condition": "commit_lag_seconds > 60 or queues > 500 KB", "description": "Sustained replication lag — secondary is significantly behind primary"}	null	2026-02-23 20:18:31.389573
1181	sqlserver	query	Check for tables with NORECOMPUTE stats or stale statistics	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(sp.object_id) AS table_name,\\n  sp.stats_id,\\n  s.name AS stats_name,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.rows_sampled,\\n  sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(sp.modification_counter * 100.0 / sp.rows AS DECIMAL(5,1))\\n    ELSE 0 END AS modification_pct,\\n  s.no_recompute\\nFROM sys.dm_db_stats_properties(OBJECT_ID(NULL), NULL) sp\\nCROSS APPLY (\\n  SELECT s2.name, s2.no_recompute\\n  FROM sys.stats s2\\n  WHERE s2.object_id = sp.object_id AND s2.stats_id = sp.stats_id\\n) s\\nWHERE sp.modification_counter > sp.rows * 0.20\\n  OR s.no_recompute = 1\\nORDER BY sp.modification_counter DESC"}	{"condition": "no_recompute = 1 OR modification_pct > 20%", "description": "Statistics with NORECOMPUTE flag or heavily modified without update"}	null	2026-02-23 20:18:31.389574
1182	sqlserver	query	Check indexes needing maintenance and estimate rebuild time	{"sql": "SELECT\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.page_count * 8 / 1024 AS index_size_mb,\\n  CASE\\n    WHEN ips.avg_fragmentation_in_percent > 30 THEN 'REBUILD'\\n    WHEN ips.avg_fragmentation_in_percent > 10 THEN 'REORGANIZE'\\n    ELSE 'OK' END AS maintenance_action\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.page_count > 1000\\n  AND ips.avg_fragmentation_in_percent > 10\\nORDER BY ips.page_count DESC"}	{"condition": "many large indexes requiring REBUILD or REORGANIZE", "description": "Significant number of fragmented indexes requiring maintenance"}	null	2026-02-23 20:18:31.389574
1669	sqlserver	query	Check SGAM contention confirming impact	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGELATCH_UP', 'PAGELATCH_EX')\\n  AND waiting_tasks_count > 100"}	{"condition": "PAGELATCH_UP waits significant (waiting_tasks_count > 5000)", "description": "High PAGELATCH contention confirms mixed extent allocation impact on tempdb"}	null	2026-02-23 20:18:31.389884
1183	sqlserver	query	Check stale statistics suggesting maintenance did not complete	{"sql": "SELECT\\n  COUNT(*) AS total_stats,\\n  SUM(CASE WHEN sp.last_updated < DATEADD(day, -7, GETDATE()) THEN 1 ELSE 0 END) AS stale_stats_7d,\\n  SUM(CASE WHEN sp.last_updated < DATEADD(day, -30, GETDATE()) THEN 1 ELSE 0 END) AS stale_stats_30d,\\n  SUM(CASE WHEN sp.modification_counter > sp.rows * 0.20 THEN 1 ELSE 0 END) AS highly_modified_stats,\\n  MAX(sp.last_updated) AS most_recent_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.object_id > 100\\n  AND sp.rows > 100"}	{"condition": "stale_stats_30d > 0 OR highly_modified_stats > 10", "description": "Many statistics not updated in over 30 days or heavily modified — maintenance window not covering all objects"}	null	2026-02-23 20:18:31.389575
1184	sqlserver	query	Check heaps for forwarded record counts	{"sql": "SELECT\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  ips.forwarded_record_count,\\n  ips.page_count,\\n  p.rows AS row_count,\\n  CASE WHEN p.rows > 0\\n    THEN CAST(ips.forwarded_record_count * 100.0 / p.rows AS DECIMAL(5,1))\\n    ELSE 0 END AS forwarded_pct\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, 0, NULL, 'DETAILED') ips\\nJOIN sys.partitions p ON ips.object_id = p.object_id AND ips.index_id = p.index_id\\nWHERE ips.index_id = 0\\n  AND ips.forwarded_record_count > 0\\n  AND p.rows > 100\\nORDER BY ips.forwarded_record_count DESC"}	{"condition": "forwarded_record_count > 0 with forwarded_pct > 10%", "description": "Heap tables with significant forwarding pointers from row-expanding UPDATEs"}	null	2026-02-23 20:18:31.389575
1186	sqlserver	query	Check for highly fragmented indexes across the database	{"sql": "SELECT\\n  COUNT(*) AS total_indexes_checked,\\n  SUM(CASE WHEN ips.avg_fragmentation_in_percent > 30 THEN 1 ELSE 0 END) AS indexes_over_30pct,\\n  SUM(CASE WHEN ips.avg_fragmentation_in_percent > 50 THEN 1 ELSE 0 END) AS indexes_over_50pct,\\n  SUM(CASE WHEN ips.avg_fragmentation_in_percent > 80 THEN 1 ELSE 0 END) AS indexes_over_80pct,\\n  AVG(ips.avg_fragmentation_in_percent) AS avg_fragmentation\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nWHERE ips.page_count > 1000\\n  AND ips.index_id > 0"}	{"condition": "indexes_over_30pct > total_indexes_checked * 0.25 OR indexes_over_80pct > 0", "description": "Over 25% of large indexes fragmented above 30%, or any index above 80% — strongly suggests no maintenance plan"}	null	2026-02-23 20:18:31.389577
4278	postgresql	query	Check table sizes for growth	{"sql": "SELECT schemaname, relname, n_live_tup, pg_size_pretty(pg_total_relation_size(relid)) AS total_size FROM pg_stat_user_tables ORDER BY pg_total_relation_size(relid) DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Review largest tables for unexpected growth that impacts job performance"}	\N	2026-02-25 00:28:52.405273
1187	sqlserver	query	Check for SQL Agent maintenance jobs and recent index rebuild activity	{"sql": "SELECT\\n  j.name AS job_name,\\n  j.enabled,\\n  ja.run_date,\\n  ja.run_status,\\n  ja.run_duration\\nFROM msdb.dbo.sysjobs j\\nLEFT JOIN (\\n  SELECT job_id, run_date, run_status, run_duration,\\n    ROW_NUMBER() OVER (PARTITION BY job_id ORDER BY run_date DESC, run_time DESC) AS rn\\n  FROM msdb.dbo.sysjobhistory\\n  WHERE step_id = 0\\n) ja ON j.job_id = ja.job_id AND ja.rn = 1\\nWHERE j.name LIKE '%index%' OR j.name LIKE '%maint%'\\n  OR j.name LIKE '%rebuild%' OR j.name LIKE '%reorgan%'\\n  OR j.name LIKE '%defrag%' OR j.name LIKE '%Ola%'\\nORDER BY j.name"}	{"condition": "no maintenance jobs found OR jobs disabled OR last run > 7 days ago", "description": "No active index maintenance jobs — indexes are not being maintained"}	null	2026-02-23 20:18:31.389577
1188	sqlserver	query	Check worst fragmented indexes with usage stats	{"sql": "SELECT TOP 15\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.page_count * 8 / 1024 AS index_size_mb,\\n  ius.user_seeks + ius.user_scans + ius.user_lookups AS total_reads,\\n  ius.user_updates AS total_writes,\\n  sp.last_updated AS stats_last_updated,\\n  sp.modification_counter\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON ips.object_id = ius.object_id AND ips.index_id = ius.index_id AND ius.database_id = DB_ID()\\nLEFT JOIN sys.dm_db_stats_properties(NULL, NULL) sp\\n  ON ips.object_id = sp.object_id AND ips.index_id = sp.stats_id\\nWHERE ips.page_count > 1000\\n  AND ips.avg_fragmentation_in_percent > 30\\n  AND i.index_id > 0\\nORDER BY (ius.user_seeks + ius.user_scans + ius.user_lookups) DESC"}	{"condition": "highly fragmented indexes with significant read activity", "description": "Actively-used indexes that are heavily fragmented — every read pays the fragmentation penalty"}	null	2026-02-23 20:18:31.389578
1534	sqlserver	query	Check target recovery time settings	{"sql": "SELECT d.name, d.target_recovery_time_in_seconds,\\n  d.recovery_model_desc\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.target_recovery_time_in_seconds > 0\\n  AND d.target_recovery_time_in_seconds < 30\\nORDER BY d.target_recovery_time_in_seconds ASC"}	{"condition": "target_recovery_time_in_seconds < 30", "description": "Very aggressive recovery target (< 30s) forces continuous high-rate background flushing"}	null	2026-02-23 20:18:31.389579
1190	sqlserver	query	Check for RESOURCE_SEMAPHORE_QUERY_COMPILE waits	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms, max_wait_time_ms,\\n  signal_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('RESOURCE_SEMAPHORE_QUERY_COMPILE',\\n  'RESOURCE_SEMAPHORE', 'CMEMTHREAD')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "RESOURCE_SEMAPHORE_QUERY_COMPILE waiting_tasks_count > 100", "description": "Query compile semaphore waits confirm that sessions are queuing to compile plans, indicating plan cache contention under high concurrency"}	null	2026-02-23 20:18:31.389579
1192	sqlserver	query	Check SQL recompilation rate vs batch request rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Re-Compilations/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS recompilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Compilations/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS batch_requests_sec"}	{"condition": "recompilations_sec > compilations_sec * 0.1 OR recompilations_sec > 100", "description": "Recompilation rate exceeding 10% of total compilations or absolute count above 100/sec indicates excessive plan invalidation"}	null	2026-02-23 20:18:31.38958
1193	sqlserver	query	Identify top queries with highest recompilation counts	{"sql": "SELECT TOP 20\\n  qs.plan_generation_num,\\n  qs.execution_count,\\n  qs.plan_generation_num * 1.0 / NULLIF(qs.execution_count, 0) AS recompile_ratio,\\n  qs.total_elapsed_time / 1000 AS total_elapsed_ms,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    ((CASE qs.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END\\n      - qs.statement_start_offset) / 2) + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.plan_generation_num > 5\\nORDER BY qs.plan_generation_num DESC"}	{"condition": "queries with plan_generation_num > 10 or recompile_ratio > 0.5", "description": "Queries with high plan generation numbers are being recompiled repeatedly, wasting CPU cycles on plan compilation instead of execution"}	null	2026-02-23 20:18:31.389581
1194	sqlserver	query	Check auto-stats update frequency as recompilation trigger	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.last_updated,\\n  sp.rows, sp.rows_sampled,\\n  sp.modification_counter,\\n  sp.modification_counter * 100.0 / NULLIF(sp.rows, 0) AS modification_pct\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > 1000\\n  AND sp.last_updated > DATEADD(hour, -24, GETDATE())\\nORDER BY sp.modification_counter DESC"}	{"condition": "tables with modification_pct > 20 and recent last_updated", "description": "High modification counters with recent stats updates confirm that statistics changes are triggering frequent plan invalidation and recompilation"}	null	2026-02-23 20:18:31.389582
1195	sqlserver	query	Check plan cache memory clerk allocation and pressure	{"sql": "SELECT type AS clerk_type,\\n  pages_kb / 1024 AS size_mb,\\n  pages_kb * 100.0 / NULLIF(SUM(pages_kb) OVER (), 0) AS pct_of_total_clerks\\nFROM sys.dm_os_memory_clerks\\nWHERE type IN ('CACHESTORE_SQLCP', 'CACHESTORE_OBJCP', 'CACHESTORE_PHDR',\\n  'MEMORYCLERK_SQLBUFFERPOOL', 'MEMORYCLERK_SQLOPTIMIZER')\\nORDER BY pages_kb DESC"}	{"condition": "CACHESTORE_SQLCP size_mb < 256 OR CACHESTORE_SQLCP pct_of_total_clerks < 2", "description": "Plan cache memory clerk consuming very little memory relative to total allocation indicates memory pressure forcing plan eviction"}	null	2026-02-23 20:18:31.389582
1196	sqlserver	query	Check plan cache eviction indicators	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Cache Hit Ratio'\\n     AND object_name LIKE '%Plan Cache%'\\n     AND instance_name = '_Total') AS cache_hit_ratio_base,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Cache Hit Ratio Base'\\n     AND object_name LIKE '%Plan Cache%'\\n     AND instance_name = '_Total') AS cache_hit_ratio_divisor,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Cache Object Counts'\\n     AND object_name LIKE '%Plan Cache%'\\n     AND instance_name = '_Total') AS cached_plans_count,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Cache Pages'\\n     AND object_name LIKE '%Plan Cache%'\\n     AND instance_name = '_Total') AS cache_pages"}	{"condition": "cache_hit_ratio_base / NULLIF(cache_hit_ratio_divisor, 0) < 0.80 OR cached_plans_count < 1000", "description": "Low plan cache hit ratio or unexpectedly small plan count indicates plans are being evicted due to memory pressure"}	null	2026-02-23 20:18:31.389583
1199	sqlserver	query	Identify top query patterns with many single-use variants	{"sql": "SELECT TOP 20\\n  qh.query_hash,\\n  COUNT(DISTINCT qh.query_plan_hash) AS distinct_plans,\\n  COUNT(*) AS execution_variants,\\n  SUM(qh.total_elapsed_time) / 1000 AS total_elapsed_ms,\\n  MIN(SUBSTRING(st.text, 1, 200)) AS sample_query\\nFROM sys.dm_exec_query_stats qh\\nCROSS APPLY sys.dm_exec_sql_text(qh.sql_handle) st\\nGROUP BY qh.query_hash\\nHAVING COUNT(*) > 10\\nORDER BY COUNT(*) DESC"}	{"condition": "query_hash groups with execution_variants > 50", "description": "Query hash groups with many execution variants confirm the same logical query is generating multiple plans due to varying literal values"}	null	2026-02-23 20:18:31.389583
1200	sqlserver	query	Check tables with high modification counters triggering stats updates	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name, s.auto_created, s.user_created,\\n  sp.last_updated, sp.rows, sp.rows_sampled,\\n  sp.modification_counter,\\n  sp.modification_counter * 100.0 / NULLIF(sp.rows, 0) AS modification_pct\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > 500\\nORDER BY sp.modification_counter DESC"}	{"condition": "tables with modification_pct > 20 or modification_counter > 10000", "description": "Tables with high modification counters relative to row count are triggering frequent statistics updates"}	null	2026-02-23 20:18:31.389584
1201	sqlserver	query	Correlate with recompilation rate and compile waits	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Re-Compilations/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS recompilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Compilations/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Auto-Param Attempts/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS auto_param_attempts_sec"}	{"condition": "recompilations_sec > 50", "description": "Sustained recompilation rate above 50/sec indicates frequently changing tables are driving excessive plan invalidation"}	null	2026-02-23 20:18:31.389585
3596	postgresql	query	Check active replication connections	{"sql": "SELECT application_name, client_addr, state, sync_state, reply_time FROM pg_stat_replication ORDER BY application_name"}	{"condition": "state != 'streaming'", "description": "Replication not streaming — possible configuration mismatch"}	\N	2026-02-25 00:28:52.405273
1204	sqlserver	query	Check compilation time vs total execution time for frequent queries	{"sql": "SELECT TOP 15\\n  qs.execution_count,\\n  qs.total_elapsed_time / 1000 AS total_elapsed_ms,\\n  qs.total_worker_time / 1000 AS total_cpu_ms,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.plan_generation_num,\\n  cp.size_in_bytes / 1024 AS plan_size_kb,\\n  cp.usecounts,\\n  SUBSTRING(st.text, 1, 150) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nJOIN sys.dm_exec_cached_plans cp ON qs.plan_handle = cp.plan_handle\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_elapsed_time / NULLIF(qs.execution_count, 0) < 1000\\n  AND qs.execution_count > 1000\\nORDER BY qs.execution_count DESC"}	{"condition": "many high-frequency queries with avg_elapsed_ms < 1 and large plan cache", "description": "Many sub-millisecond high-frequency queries combined with a bloated plan cache means lookup overhead can rival or exceed actual execution time"}	null	2026-02-23 20:18:31.389587
1205	sqlserver	query	Check ad-hoc plan cache bloat ratio	{"sql": "SELECT\\n  objtype AS plan_type,\\n  COUNT(*) AS plan_count,\\n  SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) AS single_use,\\n  SUM(size_in_bytes) / 1048576 AS total_mb,\\n  SUM(CASE WHEN usecounts = 1 THEN size_in_bytes ELSE 0 END) / 1048576 AS wasted_mb\\nFROM sys.dm_exec_cached_plans\\nGROUP BY objtype\\nORDER BY SUM(size_in_bytes) DESC"}	{"condition": "Adhoc single_use > 5000 OR wasted_mb > 256", "description": "Thousands of single-use ad-hoc plans or hundreds of MB wasted on never-reused plans confirms applications are not sending identical parameterized queries"}	null	2026-02-23 20:18:31.389587
1206	sqlserver	query	Find duplicate query patterns differing only by literals	{"sql": "SELECT TOP 20\\n  qh.query_hash,\\n  COUNT(*) AS variant_count,\\n  SUM(qs.execution_count) AS total_executions,\\n  SUM(qs.total_worker_time) / 1000 AS total_cpu_ms,\\n  MIN(SUBSTRING(st.text, 1, 200)) AS sample_query_1,\\n  MAX(SUBSTRING(st.text, 1, 200)) AS sample_query_2\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY (SELECT qs.query_hash) qh(query_hash)\\nWHERE qs.query_hash <> 0x0\\nGROUP BY qh.query_hash\\nHAVING COUNT(*) > 20\\nORDER BY COUNT(*) DESC"}	{"condition": "query_hash groups with variant_count > 50", "description": "Same query_hash with many statement variants confirms applications are embedding literals instead of using parameters"}	null	2026-02-23 20:18:31.389588
1207	sqlserver	query	Check if optimize for ad hoc workloads is disabled	{"sql": "SELECT name, value_in_use,\\n  CASE WHEN value_in_use = 0\\n    THEN 'DISABLED - full plans cached on first use'\\n    ELSE 'ENABLED - stubs cached on first use'\\n  END AS status\\nFROM sys.configurations\\nWHERE name = 'optimize for ad hoc workloads';\\nSELECT\\n  d.name AS database_name,\\n  d.is_parameterization_forced\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'\\nORDER BY d.name"}	{"condition": "optimize for ad hoc workloads value_in_use = 0 AND is_parameterization_forced = 0", "description": "Neither ad-hoc optimization nor forced parameterization is enabled, allowing every unique query text to consume a full plan cache slot"}	null	2026-02-23 20:18:31.389588
1208	sqlserver	query	Check for parameterized plans with high variance in execution time	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.query_plan_hash,\\n  qs.execution_count,\\n  qs.min_elapsed_time / 1000 AS min_elapsed_ms,\\n  qs.max_elapsed_time / 1000 AS max_elapsed_ms,\\n  qs.max_elapsed_time * 1.0 / NULLIF(qs.min_elapsed_time, 0) AS variance_ratio,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.min_logical_reads, qs.max_logical_reads,\\n  SUBSTRING(st.text, 1, 200) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.execution_count > 100\\n  AND qs.max_elapsed_time > qs.min_elapsed_time * 10\\nORDER BY (qs.max_elapsed_time - qs.min_elapsed_time) DESC"}	{"condition": "variance_ratio > 100 or max_logical_reads > min_logical_reads * 50", "description": "Extreme variance between min and max execution metrics for the same plan indicates parameter sniffing — the cached plan is optimal for some values but catastrophic for others"}	null	2026-02-23 20:18:31.389589
1223	sqlserver	query	Identify sessions waiting on specific page latches right now	{"sql": "SELECT\\n  r.session_id, r.wait_type, r.wait_time,\\n  r.wait_resource,\\n  r.blocking_session_id,\\n  SUBSTRING(st.text, (r.statement_start_offset / 2) + 1,\\n    ((CASE r.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE r.statement_end_offset END\\n      - r.statement_start_offset) / 2) + 1) AS current_statement\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE r.wait_type LIKE 'PAGELATCH%'\\nORDER BY r.wait_time DESC"}	{"condition": "multiple sessions waiting on PAGELATCH_EX for same page resource pattern", "description": "Multiple concurrent sessions waiting on PAGELATCH_EX for the same or adjacent page IDs confirms last-page insert hot spot contention"}	null	2026-02-23 20:18:31.38959
1209	sqlserver	query	Check parameterization settings and sniffed parameter values	{"sql": "SELECT TOP 10\\n  cp.objtype, cp.usecounts, cp.size_in_bytes / 1024 AS plan_kb,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  TRY_CAST(qp.query_plan AS XML).value(\\n    '(//ParameterList/ColumnReference/@ParameterCompiledValue)[1]', 'NVARCHAR(100)'\\n  ) AS sniffed_value_1,\\n  SUBSTRING(st.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nJOIN sys.dm_exec_cached_plans cp ON qs.plan_handle = cp.plan_handle\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_text_query_plan(qs.plan_handle, 0, -1) qp\\nWHERE cp.objtype IN ('Prepared', 'Proc')\\n  AND qs.execution_count > 50\\n  AND qs.max_elapsed_time > qs.min_elapsed_time * 10\\nORDER BY (qs.max_elapsed_time - qs.min_elapsed_time) DESC"}	{"condition": "parameterized plans (Prepared/Proc) with sniffed values and high execution variance", "description": "Prepared or stored procedure plans with sniffed parameter values that show high performance variance confirm parameter sniffing is producing suboptimal plans for some executions"}	null	2026-02-23 20:18:31.38959
1210	sqlserver	query	Check SQL Server uptime and recent restart indicators	{"sql": "SELECT\\n  sqlserver_start_time,\\n  DATEDIFF(minute, sqlserver_start_time, GETDATE()) AS uptime_minutes,\\n  DATEDIFF(hour, sqlserver_start_time, GETDATE()) AS uptime_hours,\\n  cpu_count, physical_memory_kb / 1024 AS physical_memory_mb\\nFROM sys.dm_os_sys_info;\\nSELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Compilations/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS batch_requests_sec"}	{"condition": "uptime_hours < 4 AND compilations_sec > batch_requests_sec * 0.5", "description": "Server recently restarted and compilations represent a large fraction of batch requests, indicating cold plan cache impact"}	null	2026-02-23 20:18:31.389591
1670	sqlserver	query	Check tempdb data file size uniformity	{"sql": "SELECT file_id, name, physical_name,\\n  size * 8 / 1024 AS size_mb,\\n  growth, is_percent_growth,\\n  max_size\\nFROM sys.master_files\\nWHERE database_id = 2 AND type_desc = 'ROWS'\\nORDER BY file_id"}	{"condition": "MAX(size_mb) > MIN(size_mb) * 1.1", "description": "Tempdb data files have unequal sizes (>10% variance) — proportional fill will skew allocations"}	null	2026-02-23 20:18:31.389885
1211	sqlserver	query	Check plan cache population progress and compile waits	{"sql": "SELECT objtype,\\n  COUNT(*) AS cached_plans,\\n  SUM(size_in_bytes) / 1048576 AS cache_mb,\\n  AVG(usecounts) AS avg_reuse\\nFROM sys.dm_exec_cached_plans\\nGROUP BY objtype\\nORDER BY COUNT(*) DESC;\\nSELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('RESOURCE_SEMAPHORE_QUERY_COMPILE', 'CMEMTHREAD')\\n  AND waiting_tasks_count > 0"}	{"condition": "avg_reuse < 3 AND RESOURCE_SEMAPHORE_QUERY_COMPILE waiting_tasks_count > 0", "description": "Low average plan reuse counts and compile semaphore waits confirm the plan cache is still warming up after a cold start"}	null	2026-02-23 20:18:31.389592
1212	sqlserver	query	Find clustered indexes on uniqueidentifier columns	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  c.name AS column_name, t.name AS data_type,\\n  dc.definition AS default_value\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.types t ON c.user_type_id = t.user_type_id\\nLEFT JOIN sys.default_constraints dc ON c.default_object_id = dc.object_id\\nWHERE i.type_desc = 'CLUSTERED'\\n  AND t.name = 'uniqueidentifier'\\n  AND ic.key_ordinal = 1\\nORDER BY OBJECT_NAME(i.object_id)"}	{"condition": "clustered indexes on uniqueidentifier columns found, especially with NEWID() defaults", "description": "Clustered indexes on uniqueidentifier (UUID) columns with NEWID() default insert rows at random positions, causing page splits on every insert"}	null	2026-02-23 20:18:31.389592
1213	sqlserver	query	Check fragmentation on identified UUID-keyed indexes	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.index_type_desc,\\n  ips.avg_fragmentation_in_percent,\\n  ips.avg_page_space_used_in_percent,\\n  ips.page_count,\\n  ips.fragment_count,\\n  ips.avg_fragment_size_in_pages\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.types t ON c.user_type_id = t.user_type_id\\nWHERE t.name = 'uniqueidentifier'\\n  AND i.type_desc = 'CLUSTERED'\\n  AND ips.page_count > 100\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > 30 AND avg_page_space_used_in_percent < 75", "description": "High fragmentation with low page density on UUID-keyed clustered indexes confirms random inserts are causing pervasive page splits"}	null	2026-02-23 20:18:31.389593
1214	sqlserver	query	Find non-clustered indexes with high split activity on low-cardinality columns	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(ios.object_id) + '.' + OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ios.leaf_insert_count, ios.leaf_update_count,\\n  ios.leaf_allocation_count AS leaf_page_splits,\\n  ios.nonleaf_allocation_count AS nonleaf_page_splits,\\n  ios.leaf_allocation_count * 100.0 /\\n    NULLIF(ios.leaf_insert_count, 0) AS split_per_insert_pct,\\n  c.name AS leading_column\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND ios.leaf_allocation_count > 100\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "leaf_page_splits > 1000 AND split_per_insert_pct > 5", "description": "Non-clustered indexes with high page split rates relative to inserts indicate hot-spot contention on low-cardinality leading columns"}	null	2026-02-23 20:18:31.389593
1215	sqlserver	query	Check fragmentation and page density on affected indexes	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.avg_page_space_used_in_percent,\\n  ips.page_count,\\n  ips.ghost_record_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND ips.page_count > 100\\n  AND ips.avg_fragmentation_in_percent > 30\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > 40 AND avg_page_space_used_in_percent < 70", "description": "High fragmentation with poor page density on non-clustered indexes confirms page splits from concentrated inserts on low-cardinality key values"}	null	2026-02-23 20:18:31.389594
1216	sqlserver	query	Check indexes with high fragmentation and ghost records from delete activity	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ips.avg_fragmentation_in_percent,\\n  ips.avg_page_space_used_in_percent,\\n  ips.page_count,\\n  ips.ghost_record_count,\\n  ips.version_ghost_record_count,\\n  ips.record_count,\\n  ips.ghost_record_count * 100.0 / NULLIF(ips.record_count, 0) AS ghost_pct\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'DETAILED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.page_count > 500\\n  AND ips.index_level = 0\\n  AND ips.avg_page_space_used_in_percent < 65\\nORDER BY ips.avg_page_space_used_in_percent ASC"}	{"condition": "avg_page_space_used_in_percent < 60 AND ghost_pct > 10", "description": "Low page density with high ghost record percentage indicates B-tree is riddled with gaps from random deletes that have not been cleaned up"}	null	2026-02-23 20:18:31.389595
1217	sqlserver	query	Correlate with operational stats showing split and delete activity	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(ios.object_id) + '.' + OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name,\\n  ios.leaf_insert_count, ios.leaf_delete_count, ios.leaf_update_count,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_ghost_count,\\n  ios.nonleaf_insert_count, ios.nonleaf_delete_count,\\n  ios.nonleaf_allocation_count AS nonleaf_splits\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nWHERE ios.leaf_delete_count > 1000\\n  AND ios.leaf_allocation_count > 100\\nORDER BY ios.leaf_delete_count DESC"}	{"condition": "leaf_delete_count > leaf_insert_count * 0.3 AND page_splits > 500", "description": "High delete-to-insert ratio combined with page splits confirms the B-tree is suffering from insert/delete churn that fragments the tree structure"}	null	2026-02-23 20:18:31.389595
3250	sqlserver	query	Check for recent external script executions	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests\\n   WHERE command = 'ExternalScript') AS active_external_scripts,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Total Executions'\\n     AND object_name LIKE '%External Scripts%') AS total_executions"}	{"condition": "total_executions > 0 OR active_external_scripts > 0", "description": "External scripts are actively being executed — R/Python runtime is in use and may need package repository access"}	null	2026-02-23 20:18:31.390098
1218	sqlserver	query	Find indexes with fill factor 100% that have page split activity	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  i.fill_factor,\\n  CASE WHEN i.fill_factor = 0 THEN 100 ELSE i.fill_factor END AS effective_fill_factor,\\n  ios.leaf_insert_count, ios.leaf_update_count,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) AS split_rate_pct\\nFROM sys.indexes i\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE (i.fill_factor = 0 OR i.fill_factor = 100)\\n  AND ios.leaf_allocation_count > 50\\n  AND ios.leaf_insert_count > 100\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "indexes with fill_factor IN (0, 100) and split_rate_pct > 1", "description": "Indexes at 100% fill factor with measurable page split activity — pages are completely full, so any non-sequential insert forces a page split"}	null	2026-02-23 20:18:31.389596
1219	sqlserver	query	Check page density to confirm full pages with no headroom	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.fill_factor,\\n  ips.avg_page_space_used_in_percent,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE (i.fill_factor = 0 OR i.fill_factor = 100)\\n  AND ips.page_count > 100\\n  AND ips.avg_fragmentation_in_percent > 20\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > 30", "description": "High fragmentation on indexes with 100% fill factor confirms that page splits are occurring because there is no free space reserved on pages for new rows"}	null	2026-02-23 20:18:31.389597
1220	sqlserver	query	Compare fill factor settings against actual page split behavior	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  CASE WHEN i.fill_factor = 0 THEN 100 ELSE i.fill_factor END AS effective_fill_factor,\\n  ios.leaf_insert_count, ios.leaf_update_count, ios.leaf_delete_count,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) AS split_rate_pct,\\n  CASE\\n    WHEN ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) > 5\\n      AND (i.fill_factor = 0 OR i.fill_factor > 90)\\n    THEN 'FILL_FACTOR_TOO_HIGH'\\n    WHEN ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) < 0.1\\n      AND i.fill_factor > 0 AND i.fill_factor < 80\\n    THEN 'FILL_FACTOR_TOO_LOW_WASTING_SPACE'\\n    ELSE 'ACCEPTABLE'\\n  END AS assessment\\nFROM sys.indexes i\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE ios.leaf_insert_count > 1000\\n  AND i.type IN (1, 2)\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "assessment = 'FILL_FACTOR_TOO_HIGH' for multiple indexes", "description": "Indexes with high split rates but high fill factors indicate the fill factor does not account for the actual random/mid-page insert pattern"}	null	2026-02-23 20:18:31.389597
4279	postgresql	query	Check table statistics freshness	{"sql": "SELECT schemaname, relname, last_analyze, last_autoanalyze, n_live_tup, n_dead_tup FROM pg_stat_user_tables WHERE last_analyze IS NULL AND last_autoanalyze IS NULL AND n_live_tup > :min_rows ORDER BY n_live_tup DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Tables with no ANALYZE ever; planner using default statistics"}	{"min_rows": 10000}	2026-02-25 00:28:52.405273
4280	postgresql	query	Check for recent index changes	{"sql": "SELECT count(*) AS invalid_indexes FROM pg_index WHERE NOT indisvalid"}	{"condition": "invalid_indexes > 0", "description": "Invalid indexes may cause planner to use suboptimal plans"}	\N	2026-02-25 00:28:52.405273
1221	sqlserver	query	Check page density confirms fill factor mismatch	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  CASE WHEN i.fill_factor = 0 THEN 100 ELSE i.fill_factor END AS effective_fill_factor,\\n  ips.avg_page_space_used_in_percent AS actual_density,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ABS(CASE WHEN i.fill_factor = 0 THEN 100 ELSE i.fill_factor END\\n    - ips.avg_page_space_used_in_percent) AS density_vs_fillfactor_gap\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.page_count > 100\\n  AND ips.avg_fragmentation_in_percent > 20\\n  AND i.type IN (1, 2)\\nORDER BY ABS(CASE WHEN i.fill_factor = 0 THEN 100 ELSE i.fill_factor END\\n  - ips.avg_page_space_used_in_percent) DESC"}	{"condition": "density_vs_fillfactor_gap > 20 AND avg_fragmentation_in_percent > 30", "description": "Large gap between configured fill factor and actual page density, combined with high fragmentation, confirms the fill factor setting is inappropriate for the workload's insert pattern"}	null	2026-02-23 20:18:31.389598
1222	sqlserver	query	Check for PAGELATCH_EX waits indicating page-level contention	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms * 1.0 / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  signal_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGELATCH_EX', 'PAGELATCH_SH', 'PAGELATCH_UP')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGELATCH_EX wait_time_ms > 10000 AND waiting_tasks_count > 1000", "description": "Significant PAGELATCH_EX waits indicate contention on data/index pages, typically the last page of a hot insert table"}	null	2026-02-23 20:18:31.389598
1388	sqlserver	query	Check parallel queries consuming disproportionate memory	{"sql": "SELECT TOP 15\\n  mg.session_id, mg.dop,\\n  mg.granted_memory_kb / 1024 AS granted_mb,\\n  mg.used_memory_kb / 1024 AS used_mb,\\n  mg.ideal_memory_kb / 1024 AS ideal_mb,\\n  mg.max_used_memory_kb / 1024 AS max_used_mb,\\n  SUBSTRING(st.text, 1, 200) AS query_text\\nFROM sys.dm_exec_query_memory_grants mg\\nCROSS APPLY sys.dm_exec_sql_text(mg.sql_handle) st\\nWHERE mg.dop > 1\\nORDER BY mg.granted_memory_kb DESC"}	{"condition": "parallel queries holding large grants while others wait", "description": "Parallel queries with high DOP consuming bulk of available memory grants"}	null	2026-02-23 20:18:31.389599
1224	sqlserver	query	Confirm hot tables have IDENTITY or sequential clustered keys	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  c.name AS key_column, c.is_identity,\\n  t.name AS data_type,\\n  ios.leaf_insert_count,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.page_latch_wait_count,\\n  ios.page_latch_wait_in_ms\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.types t ON c.user_type_id = t.user_type_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE i.type_desc = 'CLUSTERED'\\n  AND ios.page_latch_wait_count > 100\\nORDER BY ios.page_latch_wait_in_ms DESC"}	{"condition": "clustered indexes with is_identity = 1 and high page_latch_wait_count", "description": "Clustered index on IDENTITY column with high page latch waits confirms classic last-page insert contention from high-concurrency sequential inserts"}	null	2026-02-23 20:18:31.3896
1225	sqlserver	query	Check for non-leaf page split activity in index operational stats	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(ios.object_id) + '.' + OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ios.leaf_allocation_count AS leaf_splits,\\n  ios.nonleaf_allocation_count AS nonleaf_splits,\\n  ios.nonleaf_insert_count,\\n  ios.nonleaf_allocation_count * 100.0 /\\n    NULLIF(ios.leaf_allocation_count, 0) AS cascade_ratio_pct,\\n  ios.leaf_insert_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nWHERE ios.nonleaf_allocation_count > 10\\nORDER BY ios.nonleaf_allocation_count DESC"}	{"condition": "nonleaf_splits > 50 AND cascade_ratio_pct > 5", "description": "Non-leaf page splits exceeding 5% of leaf splits indicate cascading splits propagating up the B-tree when intermediate pages are also full"}	null	2026-02-23 20:18:31.3896
1226	sqlserver	query	Examine B-tree depth and non-leaf fragmentation	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.index_depth, ips.index_level,\\n  ips.page_count,\\n  ips.avg_fragmentation_in_percent,\\n  ips.avg_page_space_used_in_percent,\\n  ips.record_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'DETAILED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.index_level > 0\\n  AND ips.avg_fragmentation_in_percent > 20\\n  AND ips.page_count > 10\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "non-leaf levels (index_level > 0) with avg_fragmentation_in_percent > 30", "description": "Fragmentation at non-leaf levels of the B-tree confirms cascading splits have disrupted the intermediate page structure, not just leaf pages"}	null	2026-02-23 20:18:31.389601
1227	sqlserver	query	Calculate rows per page and identify wide-row indexes	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  p.rows AS row_count,\\n  SUM(au.used_pages) AS used_pages,\\n  CASE WHEN SUM(au.used_pages) > 0\\n    THEN p.rows * 1.0 / SUM(au.used_pages)\\n    ELSE 0 END AS avg_rows_per_page,\\n  CASE WHEN p.rows > 0\\n    THEN SUM(au.used_pages) * 8096.0 / p.rows\\n    ELSE 0 END AS avg_row_bytes\\nFROM sys.indexes i\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nJOIN sys.allocation_units au ON p.partition_id = au.container_id\\nWHERE i.type IN (1, 2)\\n  AND p.rows > 1000\\n  AND au.type = 1\\nGROUP BY i.object_id, i.name, i.type_desc, p.rows\\nHAVING CASE WHEN p.rows > 0\\n  THEN p.rows * 1.0 / NULLIF(SUM(au.used_pages), 0)\\n  ELSE 0 END < 20\\nORDER BY CASE WHEN p.rows > 0\\n  THEN p.rows * 1.0 / NULLIF(SUM(au.used_pages), 0)\\n  ELSE 999 END ASC"}	{"condition": "avg_rows_per_page < 10", "description": "Indexes with fewer than 10 rows per 8KB page indicate wide rows that waste page space and amplify the impact of every page split"}	null	2026-02-23 20:18:31.389601
1228	sqlserver	query	Check page split impact on wide-row indexes	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ios.object_id) + '.' + OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name,\\n  ios.leaf_insert_count, ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) AS split_rate_pct,\\n  ips.avg_page_space_used_in_percent,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nJOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\n  ON ios.object_id = ips.object_id AND ios.index_id = ips.index_id\\nWHERE i.type IN (1, 2)\\n  AND ios.leaf_allocation_count > 50\\n  AND ips.page_count > 100\\nORDER BY ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) DESC"}	{"condition": "split_rate_pct > 10 AND avg_page_space_used_in_percent < 60", "description": "High page split rate with low page density on indexes with few rows per page confirms that wide rows amplify fragmentation — each split creates pages with very few rows"}	null	2026-02-23 20:18:31.389602
1229	sqlserver	query	Find clustered indexes on GUID columns with high page split rates	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  c.name AS key_column, t.name AS data_type,\\n  dc.definition AS default_expr,\\n  ios.leaf_insert_count,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) AS split_per_insert_pct,\\n  ios.page_latch_wait_count,\\n  ios.page_latch_wait_in_ms\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.types t ON c.user_type_id = t.user_type_id\\nLEFT JOIN sys.default_constraints dc ON c.default_object_id = dc.object_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE i.type_desc = 'CLUSTERED'\\n  AND t.name = 'uniqueidentifier'\\n  AND ios.leaf_insert_count > 1000\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "split_per_insert_pct > 10 AND page_latch_wait_count > 500", "description": "GUID-keyed clustered indexes with high page split rates and latch waits indicate random inserts are causing mid-page splits under concurrent load"}	null	2026-02-23 20:18:31.389603
1230	sqlserver	query	Check PAGELATCH contention confirming concurrency amplification	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms * 1.0 / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGELATCH_EX', 'PAGELATCH_UP', 'PAGELATCH_SH')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGELATCH_EX wait_time_ms > 5000 AND waiting_tasks_count > 500", "description": "Significant PAGELATCH waits confirm that concurrent inserts into random GUID positions are serializing on page latches during splits"}	null	2026-02-23 20:18:31.389603
1389	sqlserver	query	Check buffer latch waits	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGELATCH_SH', 'PAGELATCH_EX', 'PAGELATCH_UP',\\n  'PAGEIOLATCH_SH', 'PAGEIOLATCH_EX')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGELATCH_SH or PAGELATCH_EX have high wait counts", "description": "Buffer pool page latch contention — threads competing for same pages"}	null	2026-02-23 20:18:31.389604
1390	sqlserver	query	Check for parallel queries combined with latch waits	{"sql": "SELECT r.session_id, r.dop, r.wait_type, r.wait_time,\\n  r.last_wait_type, r.granted_query_memory,\\n  SUBSTRING(st.text, 1, 200) AS query_text\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE r.dop > 1\\n  AND r.wait_type LIKE 'PAGELATCH%'"}	{"condition": "parallel queries currently blocked on PAGELATCH waits", "description": "Active parallel queries experiencing latch contention on buffer pool pages"}	null	2026-02-23 20:18:31.389623
3597	postgresql	query	List tablespace configuration	{"sql": "SELECT spcname, pg_tablespace_location(oid) AS location, spcowner::regrole AS owner FROM pg_tablespace ORDER BY spcname"}	{"condition": "row_count > 2", "description": "Custom tablespaces exist — must have matching paths on all cluster members"}	\N	2026-02-25 00:28:52.405273
1231	sqlserver	query	Verify fragmentation and low page density from random GUID splits	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.avg_page_space_used_in_percent,\\n  ips.page_count,\\n  ips.fragment_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.types t ON c.user_type_id = t.user_type_id\\nWHERE t.name = 'uniqueidentifier'\\n  AND i.type_desc = 'CLUSTERED'\\n  AND ips.page_count > 100\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > 50 AND avg_page_space_used_in_percent < 70", "description": "Extreme fragmentation with poor page density on GUID-keyed clustered indexes confirms that high-concurrency random inserts are destroying page locality"}	null	2026-02-23 20:18:31.389605
1232	sqlserver	query	Find indexes that re-fragment rapidly after rebuild	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  CASE WHEN i.fill_factor = 0 THEN 100 ELSE i.fill_factor END AS fill_factor,\\n  ips.avg_fragmentation_in_percent,\\n  ips.avg_page_space_used_in_percent,\\n  ips.page_count,\\n  ios.leaf_insert_count, ios.leaf_update_count,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) AS split_rate_pct,\\n  STATS_DATE(i.object_id, i.index_id) AS last_stats_update\\nFROM sys.indexes i\\nJOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\n  ON i.object_id = ips.object_id AND i.index_id = ips.index_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE i.type IN (1, 2)\\n  AND ips.page_count > 500\\n  AND ips.avg_fragmentation_in_percent > 30\\n  AND (i.fill_factor = 0 OR i.fill_factor >= 95)\\n  AND ios.leaf_allocation_count > 100\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "indexes with fill_factor >= 95 and avg_fragmentation > 30% and split_rate_pct > 5", "description": "Indexes rebuilt with near-100% fill factor that are already highly fragmented with active page splits indicate the rebuild did not account for the non-sequential insert pattern"}	null	2026-02-23 20:18:31.389605
4364	postgresql	config_check	Check PostgreSQL logging configuration for rotation settings	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('log_rotation_age', 'log_rotation_size', 'log_directory', 'log_filename', 'logging_collector', 'log_truncate_on_rotation') ORDER BY name"}	{"condition": "log_rotation_age = 0 AND log_rotation_size = 0", "description": "Log rotation is disabled, causing log files to grow indefinitely"}	\N	2026-02-25 00:28:52.405273
1233	sqlserver	query	Check insert pattern to confirm non-uniform distribution	{"sql": "SELECT TOP 15\\n  OBJECT_SCHEMA_NAME(ios.object_id) + '.' + OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name,\\n  ios.range_scan_count, ios.singleton_lookup_count,\\n  ios.leaf_insert_count, ios.leaf_delete_count,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.nonleaf_allocation_count AS nonleaf_splits,\\n  CASE\\n    WHEN ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) > 20\\n      THEN 'RANDOM_INSERT_PATTERN'\\n    WHEN ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) BETWEEN 1 AND 20\\n      THEN 'MIXED_INSERT_PATTERN'\\n    ELSE 'APPEND_ONLY' END AS insert_pattern\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nWHERE i.type IN (1, 2)\\n  AND ios.leaf_insert_count > 1000\\n  AND ios.leaf_allocation_count > 50\\nORDER BY ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) DESC"}	{"condition": "insert_pattern = 'RANDOM_INSERT_PATTERN' for indexes rebuilt at high fill factor", "description": "Random or mixed insert patterns on indexes rebuilt with high fill factor confirms the rebuild strategy does not match actual data distribution"}	null	2026-02-23 20:18:31.389606
1234	sqlserver	query	Find non-clustered indexes with high fragmentation on append-only tables	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  ci.name AS clustered_index_name,\\n  i.name AS nc_index_name,\\n  nc_col.name AS nc_leading_column,\\n  ci_col.name AS ci_leading_column,\\n  ci_col.is_identity AS ci_is_identity,\\n  ips.avg_fragmentation_in_percent AS nc_fragmentation,\\n  ips.avg_page_space_used_in_percent AS nc_page_density,\\n  ips.page_count AS nc_page_count,\\n  ios.leaf_allocation_count AS nc_page_splits,\\n  ios.leaf_insert_count AS nc_inserts\\nFROM sys.indexes i\\nJOIN sys.indexes ci ON i.object_id = ci.object_id AND ci.type_desc = 'CLUSTERED'\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns nc_col ON ic.object_id = nc_col.object_id AND ic.column_id = nc_col.column_id\\nJOIN sys.index_columns cic ON ci.object_id = cic.object_id AND ci.index_id = cic.index_id AND cic.key_ordinal = 1\\nJOIN sys.columns ci_col ON cic.object_id = ci_col.object_id AND cic.column_id = ci_col.column_id\\nJOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\n  ON i.object_id = ips.object_id AND i.index_id = ips.index_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND ci_col.is_identity = 1\\n  AND ips.page_count > 200\\n  AND ips.avg_fragmentation_in_percent > 30\\n  AND ios.leaf_allocation_count > 50\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "non-clustered indexes with fragmentation > 30% on tables with IDENTITY clustered keys", "description": "Non-clustered indexes are fragmenting on tables where the clustered key is append-only (IDENTITY), indicating the NC index key column does not follow monotonic order"}	null	2026-02-23 20:18:31.389606
1585	sqlserver	query	Check exchange-related wait stats	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT',\\n  'CXSYNC_CONSUMER', 'EXCHANGE')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "CXSYNC_PORT or EXCHANGE waits elevated alongside high CXPACKET", "description": "Exchange synchronization waits confirm overhead from data reshuffling between threads"}	null	2026-02-23 20:18:31.389607
1764	sqlserver	query	Check delete-heavy operational stats	{"sql": "SELECT OBJECT_NAME(os.object_id) AS table_name, i.name AS index_name, os.leaf_delete_count, os.leaf_insert_count, os.leaf_update_count, CASE WHEN (os.leaf_insert_count + os.leaf_update_count + os.leaf_delete_count) > 0 THEN CAST(os.leaf_delete_count AS FLOAT) / (os.leaf_insert_count + os.leaf_update_count + os.leaf_delete_count) * 100 ELSE 0 END AS delete_pct, os.leaf_ghost_count FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os JOIN sys.indexes i ON os.object_id = i.object_id AND os.index_id = i.index_id WHERE i.type > 0 AND os.leaf_delete_count > :min_deletes ORDER BY delete_pct DESC"}	{"condition": "delete_pct > :delete_threshold_pct", "description": "Deletes dominate the write workload — fragmentation is delete-driven"}	{"min_deletes": 10000, "delete_threshold_pct": 40}	2026-02-23 20:18:31.389946
1235	sqlserver	query	Confirm NC index split rate is disproportionate to clustered index	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ios.object_id) + '.' + OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ios.leaf_insert_count, ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count, 0) AS split_rate_pct\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nWHERE ios.leaf_insert_count > 1000\\n  AND i.object_id IN (\\n    SELECT ci.object_id FROM sys.indexes ci\\n    JOIN sys.index_columns cic ON ci.object_id = cic.object_id AND ci.index_id = cic.index_id AND cic.key_ordinal = 1\\n    JOIN sys.columns c ON cic.object_id = c.object_id AND cic.column_id = c.column_id\\n    WHERE ci.type_desc = 'CLUSTERED' AND c.is_identity = 1\\n  )\\nORDER BY ios.object_id, i.type_desc"}	{"condition": "NC index split_rate_pct >> clustered index split_rate_pct on same table", "description": "Non-clustered indexes on append-only tables have significantly higher page split rates than the clustered index, confirming that the NC key order diverges from insert order"}	null	2026-02-23 20:18:31.389608
1236	sqlserver	query	Find FK indexes with high page split activity	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(fk.parent_object_id) + '.' + OBJECT_NAME(fk.parent_object_id) AS child_table,\\n  OBJECT_SCHEMA_NAME(fk.referenced_object_id) + '.' + OBJECT_NAME(fk.referenced_object_id) AS parent_table,\\n  fk.name AS fk_name,\\n  fk.delete_referential_action_desc AS on_delete,\\n  fk.update_referential_action_desc AS on_update,\\n  i.name AS supporting_index,\\n  ios.leaf_insert_count, ios.leaf_update_count, ios.leaf_delete_count,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.leaf_allocation_count * 100.0 / NULLIF(ios.leaf_insert_count + ios.leaf_update_count + ios.leaf_delete_count, 0) AS split_per_dml_pct\\nFROM sys.foreign_keys fk\\nJOIN sys.foreign_key_columns fkc ON fk.object_id = fkc.constraint_object_id\\nJOIN sys.indexes i ON fkc.parent_object_id = i.object_id\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\n  AND fkc.parent_column_id = ic.column_id AND ic.key_ordinal = 1\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND ios.leaf_allocation_count > 100\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "FK supporting indexes with page_splits > 500 and split_per_dml_pct > 5", "description": "Indexes supporting foreign key constraints have high page split rates from cascaded DML operations on parent tables"}	null	2026-02-23 20:18:31.389609
1237	sqlserver	query	Check fragmentation on FK supporting indexes	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.avg_page_space_used_in_percent,\\n  ips.page_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE i.object_id IN (\\n  SELECT fkc.parent_object_id FROM sys.foreign_key_columns fkc\\n)\\n  AND i.type_desc = 'NONCLUSTERED'\\n  AND ips.page_count > 100\\n  AND ips.avg_fragmentation_in_percent > 30\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > 40 on FK supporting indexes", "description": "High fragmentation on foreign key supporting indexes confirms cascaded DML operations are causing pervasive page splits in child table indexes"}	null	2026-02-23 20:18:31.389609
6325	oracle	query	ora_check_startup_recovery_mode	{"sql": "SELECT instance_name, startup_time, status, database_status, instance_role FROM v$instance"}	{"condition": "row_count > 0", "description": "Instance startup time and status reveals if instance was recently restarted after forced shutdown"}	\N	2026-02-28 12:19:19.580455
1238	sqlserver	query	Find indexes with high latch waits and page splits on low-cardinality columns	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  c.name AS leading_column,\\n  ios.leaf_insert_count,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.page_latch_wait_count,\\n  ios.page_latch_wait_in_ms,\\n  ios.page_latch_wait_in_ms * 1.0 / NULLIF(ios.page_latch_wait_count, 0) AS avg_latch_wait_ms,\\n  ios.page_io_latch_wait_count\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND ios.page_latch_wait_count > 100\\n  AND ios.leaf_allocation_count > 50\\nORDER BY ios.page_latch_wait_in_ms DESC"}	{"condition": "page_latch_wait_count > 500 AND page_splits > 200", "description": "Indexes with both high page latch waits and page splits indicate concurrent insert hot spots on the index's leading column"}	null	2026-02-23 20:18:31.38961
1239	sqlserver	query	Estimate cardinality of leading column on affected indexes	{"sql": "SELECT TOP 15\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  i.name AS index_name,\\n  c.name AS leading_column,\\n  sp.rows AS total_rows,\\n  CASE WHEN sh.range_rows IS NOT NULL\\n    THEN sh.distinct_range_rows + 1\\n    ELSE NULL END AS estimated_distinct_values,\\n  sp.rows * 1.0 / NULLIF(\\n    CASE WHEN sh.range_rows IS NOT NULL THEN sh.distinct_range_rows + 1 ELSE 1 END, 0\\n  ) AS avg_rows_per_value\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.stats s ON i.object_id = s.object_id AND i.index_id = s.stats_id\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nOUTER APPLY sys.dm_db_stats_histogram(s.object_id, s.stats_id) sh\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND ios.page_latch_wait_count > 100\\n  AND sh.step_number = 1\\nORDER BY avg_rows_per_value DESC"}	{"condition": "avg_rows_per_value > 10000 or estimated_distinct_values < 20", "description": "Low cardinality on the leading column (few distinct values, many rows per value) confirms that inserts concentrate on a small number of leaf page ranges, creating hot spots"}	null	2026-02-23 20:18:31.389611
1240	sqlserver	query	Check total connections vs configured maximum	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS user_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections) AS total_connections,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'user connections') AS max_user_connections,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1 AND status = 'sleeping') AS sleeping_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1 AND status = 'running') AS running_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1 AND status = 'suspended') AS suspended_sessions"}	{"condition": "user_sessions > max_user_connections * 0.8 OR (max_user_connections = 0 AND user_sessions > 500)", "description": "Connection count approaching configured maximum (0 means 32,767 default). High session count with many sleeping sessions suggests pool exhaustion."}	null	2026-02-23 20:18:31.389611
1241	sqlserver	query	Check sleeping-to-active ratio indicating pooled connections waiting	{"sql": "SELECT\\n  s.program_name,\\n  COUNT(*) AS total_sessions,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping,\\n  SUM(CASE WHEN s.status = 'running' THEN 1 ELSE 0 END) AS running,\\n  SUM(CASE WHEN s.status = 'suspended' THEN 1 ELSE 0 END) AS suspended,\\n  MIN(s.last_request_start_time) AS oldest_request,\\n  DATEDIFF(second, MIN(s.last_request_start_time), GETDATE()) AS oldest_idle_seconds\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING COUNT(*) > 10\\nORDER BY COUNT(*) DESC"}	{"condition": "applications with sleeping > running * 5 AND total_sessions > 50", "description": "Applications holding many sleeping connections relative to active ones indicates the pool is oversized for actual workload or too many application instances are competing"}	null	2026-02-23 20:18:31.389612
1242	sqlserver	query	Check for connection timeout errors in recent SQL Server logs	{"sql": "SELECT TOP 20\\n  wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms * 1.0 / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PREEMPTIVE_OS_AUTHENTICATIONOPS', 'PREEMPTIVE_OS_AUTHORIZATIONOPS',\\n  'LOGON_TRIGGER_FIRED', 'BROKER_EVENTHANDLER')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PREEMPTIVE_OS_AUTHENTICATIONOPS with high wait counts indicating many connection attempts", "description": "High authentication wait counts confirm a surge of connection attempts, consistent with applications unable to acquire pooled connections and attempting new ones"}	null	2026-02-23 20:18:31.389613
1243	sqlserver	query	Find sessions with long-running open transactions	{"sql": "SELECT\\n  s.session_id, s.login_name, s.program_name, s.host_name,\\n  s.status, s.login_time,\\n  t.transaction_begin_time,\\n  DATEDIFF(second, t.transaction_begin_time, GETDATE()) AS transaction_age_seconds,\\n  t.transaction_type, t.transaction_state,\\n  CASE t.transaction_state\\n    WHEN 0 THEN 'Initializing'\\n    WHEN 1 THEN 'Initialized'\\n    WHEN 2 THEN 'Active'\\n    WHEN 3 THEN 'Ended (read-only)'\\n    WHEN 4 THEN 'Commit started (distributed)'\\n    WHEN 5 THEN 'Prepared (distributed)'\\n    WHEN 6 THEN 'Committed'\\n    WHEN 7 THEN 'Rolling back'\\n    WHEN 8 THEN 'Rolled back'\\n    END AS state_desc\\nFROM sys.dm_tran_active_transactions t\\nJOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_sessions s ON st.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND DATEDIFF(second, t.transaction_begin_time, GETDATE()) > 300\\nORDER BY t.transaction_begin_time ASC"}	{"condition": "transactions older than 300 seconds (5 minutes)", "description": "Open transactions running for more than 5 minutes are holding their connections, preventing return to the pool"}	null	2026-02-23 20:18:31.389613
1244	sqlserver	query	Check if long-running transactions are sleeping (idle in transaction)	{"sql": "SELECT\\n  s.session_id, s.program_name, s.status,\\n  s.last_request_start_time, s.last_request_end_time,\\n  DATEDIFF(second, s.last_request_end_time, GETDATE()) AS idle_since_seconds,\\n  t.transaction_begin_time,\\n  DATEDIFF(second, t.transaction_begin_time, GETDATE()) AS txn_age_seconds,\\n  (SELECT text FROM sys.dm_exec_sql_text(c.most_recent_sql_handle)) AS last_sql\\nFROM sys.dm_tran_active_transactions t\\nJOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_sessions s ON st.session_id = s.session_id\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(second, t.transaction_begin_time, GETDATE()) > 60\\nORDER BY t.transaction_begin_time ASC"}	{"condition": "sleeping sessions with open transactions older than 60 seconds and high idle_since_seconds", "description": "Sessions that are sleeping (no active request) but hold open transactions confirm the application opened a transaction and then became idle, holding the connection hostage"}	null	2026-02-23 20:18:31.389614
1245	sqlserver	query	Find long-idle sleeping sessions indicating leaked connections	{"sql": "SELECT\\n  s.session_id, s.login_name, s.program_name, s.host_name,\\n  s.status, s.login_time,\\n  s.last_request_start_time, s.last_request_end_time,\\n  DATEDIFF(minute, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  DATEDIFF(minute, s.login_time, GETDATE()) AS session_age_minutes,\\n  c.num_reads, c.num_writes,\\n  c.connect_time\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > 30\\nORDER BY s.last_request_end_time ASC"}	{"condition": "sessions idle for > 30 minutes with no open transaction", "description": "Sleeping sessions idle for extended periods without recent activity suggest the application acquired a connection from the pool but never returned it"}	null	2026-02-23 20:18:31.389614
1246	sqlserver	query	Group leaked connections by application to identify offending source	{"sql": "SELECT\\n  s.program_name, s.host_name,\\n  COUNT(*) AS idle_sessions,\\n  MIN(DATEDIFF(minute, s.last_request_end_time, GETDATE())) AS min_idle_minutes,\\n  MAX(DATEDIFF(minute, s.last_request_end_time, GETDATE())) AS max_idle_minutes,\\n  AVG(DATEDIFF(minute, s.last_request_end_time, GETDATE())) AS avg_idle_minutes\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > 30\\n  AND s.session_id NOT IN (\\n    SELECT st.session_id FROM sys.dm_tran_session_transactions st\\n  )\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 3\\nORDER BY COUNT(*) DESC"}	{"condition": "application with > 5 idle sessions averaging > 60 minutes idle", "description": "Specific application consistently holding many idle connections confirms a systematic connection leak pattern"}	null	2026-02-23 20:18:31.389615
1247	sqlserver	query	Find active sessions running queries for extended time	{"sql": "SELECT\\n  r.session_id, r.status, r.command,\\n  r.start_time,\\n  DATEDIFF(second, r.start_time, GETDATE()) AS running_seconds,\\n  r.wait_type, r.wait_time, r.wait_resource,\\n  r.total_elapsed_time / 1000 AS elapsed_ms,\\n  r.cpu_time, r.logical_reads, r.writes,\\n  s.program_name, s.host_name,\\n  SUBSTRING(st.text, (r.statement_start_offset / 2) + 1,\\n    ((CASE r.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE r.statement_end_offset END\\n      - r.statement_start_offset) / 2) + 1) AS current_statement\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE s.is_user_process = 1\\n  AND r.total_elapsed_time > 30000\\nORDER BY r.total_elapsed_time DESC"}	{"condition": "queries running for > 30 seconds with significant logical reads or waits", "description": "Long-running active queries consuming connections that could otherwise be returned to the pool"}	null	2026-02-23 20:18:31.389616
1385	sqlserver	query	Check for scheduler contention symptoms	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('SOS_SCHEDULER_YIELD', 'CXPACKET', 'CXCONSUMER')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "SOS_SCHEDULER_YIELD is elevated with high CXPACKET", "description": "Scheduler yields combined with parallelism waits — HT contention under parallel workload"}	null	2026-02-23 20:18:31.389657
1248	sqlserver	query	Check historically expensive queries consuming connection time	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_elapsed_time / 1000 AS total_elapsed_ms,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.max_elapsed_time / 1000 AS max_elapsed_ms,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    ((CASE qs.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END\\n      - qs.statement_start_offset) / 2) + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_elapsed_time / NULLIF(qs.execution_count, 0) > 10000000\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "queries with avg_elapsed_ms > 10000 (10 seconds average)", "description": "Queries averaging over 10 seconds hold connections far longer than typical OLTP operations, contributing to pool exhaustion under load"}	null	2026-02-23 20:18:31.389617
1249	sqlserver	query	Find active blocking chains with blocked session count	{"sql": "SELECT\\n  r.session_id AS blocked_session,\\n  r.blocking_session_id AS blocking_session,\\n  r.wait_type, r.wait_time / 1000 AS wait_seconds,\\n  r.wait_resource,\\n  s.program_name AS blocked_program,\\n  bs.program_name AS blocker_program,\\n  bs.status AS blocker_status,\\n  SUBSTRING(st.text, (r.statement_start_offset / 2) + 1,\\n    ((CASE r.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE r.statement_end_offset END\\n      - r.statement_start_offset) / 2) + 1) AS blocked_query\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nLEFT JOIN sys.dm_exec_sessions bs ON r.blocking_session_id = bs.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE r.blocking_session_id > 0\\nORDER BY r.wait_time DESC"}	{"condition": "blocked sessions with wait_seconds > 30", "description": "Sessions blocked for more than 30 seconds are holding their connections while waiting for locks, consuming pool capacity"}	null	2026-02-23 20:18:31.389617
4954	postgresql	process	Check if pg_wal is a symlink to separate device	{"command": "readlink -f $(psql -t -c \\"SHOW data_directory\\")/pg_wal"}	{"condition": "path_on_same_device_as_data_dir", "description": "If pg_wal resolves to same mount point as data_directory, WAL competes with data I/O"}	\N	2026-02-25 00:28:52.405273
1250	sqlserver	query	Identify head blockers and the extent of the blocking chain	{"sql": "WITH BlockingChain AS (\\n  SELECT\\n    r.session_id,\\n    r.blocking_session_id,\\n    CAST(r.blocking_session_id AS VARCHAR(MAX)) AS chain,\\n    1 AS chain_depth\\n  FROM sys.dm_exec_requests r\\n  WHERE r.blocking_session_id > 0\\n  UNION ALL\\n  SELECT\\n    bc.session_id,\\n    r2.blocking_session_id,\\n    CAST(bc.chain + ' -> ' + CAST(r2.blocking_session_id AS VARCHAR(10)) AS VARCHAR(MAX)),\\n    bc.chain_depth + 1\\n  FROM BlockingChain bc\\n  JOIN sys.dm_exec_requests r2 ON bc.blocking_session_id = r2.session_id\\n  WHERE r2.blocking_session_id > 0\\n    AND bc.chain_depth < 10\\n)\\nSELECT TOP 10\\n  head.session_id AS head_blocker,\\n  head.status AS blocker_status,\\n  head.program_name,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests r3 WHERE r3.blocking_session_id = head.session_id) AS directly_blocked,\\n  (SELECT text FROM sys.dm_exec_sql_text(c.most_recent_sql_handle)) AS blocker_last_sql\\nFROM sys.dm_exec_sessions head\\nJOIN sys.dm_exec_connections c ON head.session_id = c.session_id\\nWHERE head.session_id IN (\\n  SELECT blocking_session_id FROM sys.dm_exec_requests\\n  WHERE blocking_session_id > 0\\n)\\n  AND head.session_id NOT IN (\\n  SELECT session_id FROM sys.dm_exec_requests WHERE blocking_session_id > 0\\n)\\nORDER BY directly_blocked DESC"}	{"condition": "head blockers with directly_blocked > 3 or blocker_status = 'sleeping'", "description": "A sleeping head blocker with multiple sessions queued behind it confirms a blocking chain is consuming connections that cannot complete and return to the pool"}	null	2026-02-23 20:18:31.389618
4281	postgresql	query	Check for bloated tables	{"sql": "SELECT schemaname, relname, n_live_tup, n_dead_tup, CASE WHEN n_live_tup > 0 THEN round(n_dead_tup::numeric / n_live_tup * 100, 2) ELSE 0 END AS dead_pct, pg_size_pretty(pg_total_relation_size(relid)) AS total_size, last_autovacuum FROM pg_stat_user_tables WHERE n_dead_tup > :dead_threshold ORDER BY n_dead_tup DESC LIMIT 10"}	{"condition": "row_count > 0 AND dead_pct > :dead_pct_threshold", "description": "Significant table bloat from dead tuples impacting job performance"}	{"dead_threshold": 50000, "dead_pct_threshold": 20}	2026-02-25 00:28:52.405273
1251	sqlserver	query	Find suspended sessions waiting for resources	{"sql": "SELECT\\n  r.session_id, r.status, r.wait_type,\\n  r.wait_time / 1000 AS wait_seconds,\\n  r.wait_resource,\\n  r.total_elapsed_time / 1000 AS elapsed_ms,\\n  r.cpu_time, r.logical_reads,\\n  r.granted_query_memory * 8 / 1024 AS granted_memory_mb,\\n  s.program_name, s.host_name\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND r.status = 'suspended'\\n  AND r.wait_time > 5000\\nORDER BY r.wait_time DESC"}	{"condition": "suspended sessions with wait_seconds > 10 across multiple applications", "description": "Multiple sessions suspended on waits for extended periods means application threads are blocked waiting for SQL Server responses while holding connections"}	null	2026-02-23 20:18:31.389618
1252	sqlserver	query	Categorize wait types contributing to slow responses	{"sql": "SELECT\\n  r.wait_type,\\n  COUNT(*) AS waiting_sessions,\\n  SUM(r.wait_time) / 1000 AS total_wait_seconds,\\n  AVG(r.wait_time) / 1000 AS avg_wait_seconds\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND r.status = 'suspended'\\n  AND r.wait_time > 1000\\nGROUP BY r.wait_type\\nHAVING COUNT(*) > 2\\nORDER BY SUM(r.wait_time) DESC"}	{"condition": "I/O waits (PAGEIOLATCH_*), lock waits (LCK_M_*), or memory grant waits (RESOURCE_SEMAPHORE) with multiple waiting sessions", "description": "Systemic wait types across multiple sessions confirm SQL Server is bottlenecked on a resource, causing application threads to hold connections while waiting for responses"}	null	2026-02-23 20:18:31.389619
1253	sqlserver	query	Count connections grouped by application and host	{"sql": "SELECT\\n  s.program_name, s.host_name,\\n  COUNT(*) AS session_count,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping,\\n  SUM(CASE WHEN s.status = 'running' THEN 1 ELSE 0 END) AS running,\\n  SUM(CASE WHEN s.status = 'suspended' THEN 1 ELSE 0 END) AS suspended,\\n  MIN(s.login_time) AS earliest_login,\\n  MAX(s.last_request_start_time) AS latest_request\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name\\nORDER BY COUNT(*) DESC"}	{"condition": "same program_name from multiple host_names each with > 20 sessions, totaling > 200", "description": "Multiple application instances from different hosts each maintain their own pool, and the combined total exceeds what the server or a single pool would allow"}	null	2026-02-23 20:18:31.38962
1524	sqlserver	query	Check for synchronous mirroring or AG sync commit waits	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('DBMIRROR_SEND', 'DBMIRROR_DBM_MUTEX',\\n  'HADR_SYNC_COMMIT', 'HADR_LOGCAPTURE_SYNC')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "HADR_SYNC_COMMIT or DBMIRROR_SEND waits with avg_wait_ms > 1", "description": "Synchronous replication adding measurable commit latency"}	null	2026-02-23 20:18:31.389691
1254	sqlserver	query	Calculate per-host vs total connection pressure	{"sql": "SELECT\\n  s.program_name,\\n  COUNT(DISTINCT s.host_name) AS distinct_hosts,\\n  COUNT(*) AS total_sessions,\\n  COUNT(*) * 1.0 / NULLIF(COUNT(DISTINCT s.host_name), 0) AS avg_sessions_per_host,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS server_total_sessions,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'user connections') AS max_connections\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING COUNT(DISTINCT s.host_name) > 1\\nORDER BY COUNT(*) DESC"}	{"condition": "distinct_hosts > 3 AND total_sessions > 100 for same program_name", "description": "Multiple application instances collectively consuming a large fraction of available connections confirms connection pool competition"}	null	2026-02-23 20:18:31.38962
1255	sqlserver	query	Check current lock waits and blocking	{"sql": "SELECT\\n  wt.session_id AS waiting_session,\\n  wt.wait_type, wt.wait_duration_ms / 1000 AS wait_seconds,\\n  wt.resource_description,\\n  wt.blocking_session_id,\\n  tl.resource_type, tl.request_mode, tl.request_status,\\n  OBJECT_NAME(tl.resource_associated_entity_id) AS locked_object\\nFROM sys.dm_os_waiting_tasks wt\\nJOIN sys.dm_tran_locks tl ON wt.resource_address = tl.lock_owner_address\\nWHERE wt.wait_type LIKE 'LCK_M_%'\\n  AND wt.wait_duration_ms > 5000\\nORDER BY wt.wait_duration_ms DESC"}	{"condition": "LCK_M_* waits > 5 seconds across multiple sessions", "description": "Multiple sessions waiting on lock grants for extended periods indicates lock contention preventing work completion and connection release"}	null	2026-02-23 20:18:31.389621
1256	sqlserver	query	Identify lock escalation and table lock holders	{"sql": "SELECT\\n  tl.resource_type, tl.request_mode, tl.request_status,\\n  tl.request_session_id AS session_id,\\n  OBJECT_NAME(tl.resource_associated_entity_id) AS object_name,\\n  COUNT(*) AS lock_count,\\n  s.program_name, s.status\\nFROM sys.dm_tran_locks tl\\nJOIN sys.dm_exec_sessions s ON tl.request_session_id = s.session_id\\nWHERE tl.resource_type IN ('OBJECT', 'PAGE', 'KEY', 'RID')\\n  AND tl.request_status = 'GRANT'\\nGROUP BY tl.resource_type, tl.request_mode, tl.request_status,\\n  tl.request_session_id, tl.resource_associated_entity_id,\\n  s.program_name, s.status\\nHAVING COUNT(*) > 100\\nORDER BY COUNT(*) DESC"}	{"condition": "sessions holding > 1000 locks or OBJECT-level exclusive locks", "description": "Sessions holding large numbers of locks or table-level exclusive locks are preventing concurrent access, blocking other sessions and their connections"}	null	2026-02-23 20:18:31.389622
1257	sqlserver	query	Check cumulative lock wait statistics	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms / 1000 AS total_wait_seconds,\\n  wait_time_ms * 1.0 / NULLIF(waiting_tasks_count, 0) / 1000 AS avg_wait_seconds,\\n  max_wait_time_ms / 1000 AS max_wait_seconds\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type LIKE 'LCK_M_%'\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "LCK_M_S or LCK_M_X total_wait_seconds > 60 with avg_wait_seconds > 1", "description": "Significant cumulative lock wait time confirms lock contention is a systemic issue consuming connection hold time"}	null	2026-02-23 20:18:31.389622
3598	postgresql	query	Check monitoring extensions and configuration	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('shared_preload_libraries', 'track_activities', 'track_counts', 'track_io_timing', 'track_wal_io_timing', 'track_functions') ORDER BY name"}	{"condition": "settings_retrieved", "description": "Monitoring configuration identified — compare with other cluster nodes"}	\N	2026-02-25 00:28:52.405273
1259	sqlserver	query	Identify sessions currently experiencing network waits	{"sql": "SELECT\\n  r.session_id, r.wait_type, r.wait_time / 1000 AS wait_seconds,\\n  s.program_name, s.host_name,\\n  c.client_net_address, c.net_transport, c.protocol_type,\\n  c.num_reads, c.num_writes,\\n  c.net_packet_size,\\n  s.last_request_start_time,\\n  DATEDIFF(second, s.last_request_start_time, GETDATE()) AS request_age_seconds\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE r.wait_type = 'ASYNC_NETWORK_IO'\\n  AND r.wait_time > 5000\\nORDER BY r.wait_time DESC"}	{"condition": "sessions waiting on ASYNC_NETWORK_IO > 5 seconds, especially from remote client addresses", "description": "Active sessions blocked on network I/O to remote clients confirm network latency is extending connection hold time"}	null	2026-02-23 20:18:31.389623
4282	postgresql	query	Check autovacuum activity	{"sql": "SELECT schemaname, relname, last_vacuum, last_autovacuum, vacuum_count, autovacuum_count FROM pg_stat_user_tables WHERE n_dead_tup > :dead_threshold AND (last_autovacuum IS NULL OR last_autovacuum < NOW() - interval ':hours hours')"}	{"condition": "row_count > 0", "description": "Autovacuum not running frequently enough to prevent bloat"}	{"hours": 24, "dead_threshold": 50000}	2026-02-25 00:28:52.405273
1260	sqlserver	query	Find sessions with large gap between connect time and first/last request	{"sql": "SELECT\\n  s.session_id, s.program_name, s.host_name,\\n  s.login_time,\\n  c.connect_time,\\n  s.last_request_start_time, s.last_request_end_time,\\n  DATEDIFF(minute, s.login_time, GETDATE()) AS session_age_minutes,\\n  DATEDIFF(minute, s.last_request_end_time, GETDATE()) AS idle_since_minutes,\\n  c.num_reads, c.num_writes,\\n  s.status\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND DATEDIFF(minute, s.login_time, GETDATE()) > 60\\n  AND s.status = 'sleeping'\\nORDER BY DATEDIFF(minute, s.login_time, GETDATE()) DESC"}	{"condition": "sessions older than 60 minutes that are sleeping with low num_reads/num_writes relative to age", "description": "Long-lived sleeping sessions with minimal activity indicate connections opened at application startup and held indefinitely"}	null	2026-02-23 20:18:31.389624
1261	sqlserver	query	Calculate utilization ratio for long-lived sessions	{"sql": "SELECT\\n  s.program_name,\\n  COUNT(*) AS sessions,\\n  AVG(DATEDIFF(minute, s.login_time, GETDATE())) AS avg_session_age_min,\\n  AVG(DATEDIFF(minute, s.last_request_end_time, GETDATE())) AS avg_idle_min,\\n  AVG(c.num_reads + c.num_writes) AS avg_total_io,\\n  AVG((c.num_reads + c.num_writes) * 1.0 / NULLIF(DATEDIFF(minute, s.login_time, GETDATE()), 0)) AS io_per_minute\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND DATEDIFF(minute, s.login_time, GETDATE()) > 30\\nGROUP BY s.program_name\\nHAVING COUNT(*) > 3\\n  AND AVG(DATEDIFF(minute, s.last_request_end_time, GETDATE())) > 15\\nORDER BY AVG(DATEDIFF(minute, s.login_time, GETDATE())) DESC"}	{"condition": "applications with avg_session_age_min > 120 and io_per_minute < 1", "description": "Applications maintaining long-lived sessions with very low I/O activity per minute confirms the connect-early close-late anti-pattern"}	null	2026-02-23 20:18:31.389625
1472	sqlserver	query	Check parallelism configuration settings	{"sql": "SELECT\\n  name, value_in_use\\nFROM sys.configurations\\nWHERE name IN ('cost threshold for parallelism',\\n  'max degree of parallelism')\\nUNION ALL\\nSELECT\\n  'scheduler_count' AS name,\\n  CAST(COUNT(*) AS sql_variant) AS value_in_use\\nFROM sys.dm_os_schedulers\\nWHERE status = 'VISIBLE ONLINE'"}	{"condition": "cost threshold for parallelism = 5 (default) or max degree of parallelism = 0 (unlimited)", "description": "Default settings (cost threshold 5, MAXDOP 0) allow parallelism for trivial queries on all cores — a common cause of excessive parallelism overhead"}	null	2026-02-23 20:18:31.389625
1262	sqlserver	query	Identify top connection consumers by application	{"sql": "SELECT\\n  s.program_name,\\n  COUNT(*) AS session_count,\\n  COUNT(*) * 100.0 / NULLIF((SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1), 0) AS pct_of_total,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping,\\n  SUM(CASE WHEN s.status = 'running' THEN 1 ELSE 0 END) AS running,\\n  COUNT(DISTINCT s.host_name) AS distinct_hosts\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING COUNT(*) > 10\\nORDER BY COUNT(*) DESC"}	{"condition": "a single program_name consuming > 30% of total sessions", "description": "One application or middleware tool consuming a disproportionate share of all connections"}	null	2026-02-23 20:18:31.389626
1263	sqlserver	query	Check if dominant connection consumer is a known middleware or monitoring tool	{"sql": "SELECT\\n  s.program_name,\\n  COUNT(*) AS session_count,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping,\\n  AVG(DATEDIFF(minute, s.last_request_end_time, GETDATE())) AS avg_idle_minutes,\\n  CASE\\n    WHEN s.program_name LIKE '%SolarWinds%' OR s.program_name LIKE '%DPA%' THEN 'MONITORING'\\n    WHEN s.program_name LIKE '%Idera%' OR s.program_name LIKE '%Diagnostic%' THEN 'MONITORING'\\n    WHEN s.program_name LIKE '%Quest%' OR s.program_name LIKE '%Spotlight%' THEN 'MONITORING'\\n    WHEN s.program_name LIKE '%Redgate%' THEN 'MONITORING'\\n    WHEN s.program_name LIKE '%EntityFramework%' OR s.program_name LIKE '.Net%' THEN 'ORM'\\n    WHEN s.program_name LIKE '%Hibernate%' OR s.program_name LIKE '%HikariCP%' THEN 'ORM/POOL'\\n    WHEN s.program_name LIKE '%SQLAlchemy%' THEN 'ORM'\\n    WHEN s.program_name LIKE '%Report%' THEN 'REPORTING'\\n    ELSE 'APPLICATION' END AS tool_category\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING COUNT(*) > 10\\nORDER BY COUNT(*) DESC"}	{"condition": "MONITORING or ORM/POOL category consuming > 20% of sessions with high sleeping ratio", "description": "Third-party middleware or monitoring tool holding many idle connections confirms it is consuming pool capacity that should be available to the primary application"}	null	2026-02-23 20:18:31.389626
1264	sqlserver	query	Find extremely long-idle connections	{"sql": "SELECT\\n  s.session_id, s.program_name, s.host_name,\\n  s.status, s.login_time,\\n  s.last_request_start_time, s.last_request_end_time,\\n  DATEDIFF(hour, s.last_request_end_time, GETDATE()) AS idle_hours,\\n  DATEDIFF(hour, s.login_time, GETDATE()) AS session_age_hours,\\n  c.num_reads, c.num_writes\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(hour, s.last_request_end_time, GETDATE()) > 4\\nORDER BY s.last_request_end_time ASC"}	{"condition": "sleeping sessions idle for > 4 hours", "description": "Sessions idle for hours indicate the connection pool is not evicting unused connections, suggesting timeout is set too high or eviction is disabled"}	null	2026-02-23 20:18:31.389627
1265	sqlserver	query	Group stale connections by application to quantify waste	{"sql": "SELECT\\n  s.program_name,\\n  COUNT(*) AS stale_sessions,\\n  MIN(DATEDIFF(hour, s.last_request_end_time, GETDATE())) AS min_idle_hours,\\n  MAX(DATEDIFF(hour, s.last_request_end_time, GETDATE())) AS max_idle_hours,\\n  AVG(c.num_reads + c.num_writes) AS avg_total_io,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS total_user_sessions\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(hour, s.last_request_end_time, GETDATE()) > 2\\nGROUP BY s.program_name\\nHAVING COUNT(*) > 2\\nORDER BY COUNT(*) DESC"}	{"condition": "stale_sessions > 5 for an application with max_idle_hours > 8", "description": "Applications persistently holding connections idle for many hours confirms connection timeout is too high, wasting pool capacity"}	null	2026-02-23 20:18:31.389628
1266	sqlserver	query	Check session count trend indicators and idle ratio	{"sql": "SELECT\\n  s.program_name,\\n  COUNT(*) AS total_sessions,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping,\\n  SUM(CASE WHEN s.status IN ('running', 'suspended') THEN 1 ELSE 0 END) AS active,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) * 100.0 /\\n    NULLIF(COUNT(*), 0) AS sleeping_pct,\\n  MIN(s.login_time) AS oldest_session_login,\\n  MAX(s.login_time) AS newest_session_login,\\n  DATEDIFF(minute, MIN(s.login_time), MAX(s.login_time)) AS session_span_minutes\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING COUNT(*) > 20\\n  AND SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0) > 80\\nORDER BY COUNT(*) DESC"}	{"condition": "sleeping_pct > 90 AND total_sessions > 50", "description": "Applications with > 90% sleeping sessions out of a large session count indicates connections are being acquired but never properly returned to the pool"}	null	2026-02-23 20:18:31.389628
1267	sqlserver	query	Check for orphaned connections with no recent activity and no open transaction	{"sql": "SELECT\\n  s.session_id, s.program_name, s.host_name,\\n  s.login_time, s.last_request_start_time, s.last_request_end_time,\\n  DATEDIFF(minute, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  c.num_reads, c.num_writes,\\n  CASE WHEN st.session_id IS NOT NULL THEN 'HAS_OPEN_TXN' ELSE 'NO_TXN' END AS txn_status\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nLEFT JOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > 30\\n  AND st.session_id IS NULL\\nORDER BY s.last_request_end_time ASC"}	{"condition": "many sessions idle > 30 minutes with no open transaction, clustered by same program_name", "description": "Sleeping sessions with no open transaction and no recent activity are orphaned connections that the application acquired but failed to close"}	null	2026-02-23 20:18:31.389629
1275	sqlserver	query	Verify burst sessions executed similar queries	{"sql": "SELECT s.session_id, s.login_time,\\n  c.most_recent_sql_handle,\\n  t.text AS last_query,\\n  s.open_transaction_count\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nCROSS APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) t\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 10\\n  AND s.program_name IN (\\n    SELECT TOP 1 program_name\\n    FROM sys.dm_exec_sessions\\n    WHERE status = 'sleeping' AND is_user_process = 1\\n      AND DATEDIFF(MINUTE, last_request_end_time, GETDATE()) > 10\\n    GROUP BY program_name\\n    HAVING COUNT(*) > 20\\n    ORDER BY COUNT(*) DESC\\n  )\\nORDER BY s.login_time"}	{"condition": "multiple sessions executed similar or identical queries suggesting same recursive code path", "description": "Identical last_query across burst sessions confirms a single code path repeatedly acquiring connections"}	null	2026-02-23 20:18:31.38963
1656	sqlserver	query	Confirm I/O bottleneck via wait statistics	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'PAGEIOLATCH_UP',\\n  'IO_COMPLETION', 'ASYNC_IO_COMPLETION', 'WRITELOG'\\n)\\nAND waiting_tasks_count > 100\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH avg_wait_ms > 20 OR IO_COMPLETION avg_wait_ms > 30", "description": "I/O wait types with high average waits confirm storage subsystem is the bottleneck"}	null	2026-02-23 20:18:31.389877
1268	sqlserver	query	Find sessions with abandoned transactions (exception during execution)	{"sql": "SELECT\\n  s.session_id, s.program_name, s.host_name,\\n  s.status, s.login_time,\\n  s.last_request_start_time, s.last_request_end_time,\\n  DATEDIFF(minute, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  t.transaction_begin_time,\\n  DATEDIFF(minute, t.transaction_begin_time, GETDATE()) AS txn_age_minutes,\\n  t.transaction_state,\\n  CASE t.transaction_state\\n    WHEN 1 THEN 'Initialized'\\n    WHEN 2 THEN 'Active'\\n    WHEN 7 THEN 'Rolling_back'\\n    WHEN 8 THEN 'Rolled_back'\\n    ELSE CAST(t.transaction_state AS VARCHAR) END AS state_desc,\\n  (SELECT text FROM sys.dm_exec_sql_text(c.most_recent_sql_handle)) AS last_sql\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nJOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nJOIN sys.dm_tran_active_transactions t ON st.transaction_id = t.transaction_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > 10\\nORDER BY t.transaction_begin_time ASC"}	{"condition": "sleeping sessions with open transactions idle > 10 minutes, especially in rolled_back or initialized state", "description": "Sessions left sleeping with an open transaction after the last request completed suggest an exception occurred and the application neither committed/rolled back nor closed the connection"}	null	2026-02-23 20:18:31.38963
1269	sqlserver	query	Check for error indicators correlated with orphaned sessions	{"sql": "SELECT\\n  s.program_name,\\n  COUNT(*) AS orphaned_txn_sessions,\\n  AVG(DATEDIFF(minute, s.last_request_end_time, GETDATE())) AS avg_idle_minutes,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s2\\n   WHERE s2.program_name = s.program_name AND s2.is_user_process = 1) AS total_app_sessions,\\n  COUNT(*) * 100.0 / NULLIF(\\n    (SELECT COUNT(*) FROM sys.dm_exec_sessions s2\\n     WHERE s2.program_name = s.program_name AND s2.is_user_process = 1), 0\\n  ) AS orphaned_pct\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > 5\\nGROUP BY s.program_name\\nHAVING COUNT(*) > 2\\nORDER BY COUNT(*) DESC"}	{"condition": "orphaned_pct > 10 for an application with orphaned_txn_sessions > 3", "description": "A significant percentage of an application's connections are orphaned with open transactions, confirming exceptions are bypassing connection cleanup"}	null	2026-02-23 20:18:31.389631
1270	sqlserver	query	Find very long-lived sleeping sessions with no recent activity	{"sql": "SELECT s.session_id, s.login_time, s.last_request_end_time,\\n  DATEDIFF(HOUR, s.login_time, GETDATE()) AS session_age_hours,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  s.program_name, s.host_name, s.open_transaction_count,\\n  c.num_reads, c.num_writes,\\n  c.connect_time\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(HOUR, s.login_time, GETDATE()) > 24\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 60\\nORDER BY s.login_time ASC"}	{"condition": "row_count > 0 with session_age_hours >> idle_minutes indicating long-lived connection with sporadic or no use", "description": "Sessions alive for days but idle for hours suggest static variable holding a connection reference across app restarts/redeployments"}	null	2026-02-23 20:18:31.389631
1271	sqlserver	query	Check if long-lived sessions correlate with rising connection count	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%General Statistics%'\\n     AND counter_name = 'User Connections') AS current_user_connections,\\n  COUNT(*) AS stale_sessions_24h,\\n  SUM(CASE WHEN DATEDIFF(HOUR, s.login_time, GETDATE()) > 72 THEN 1 ELSE 0 END) AS stale_sessions_72h\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(HOUR, s.login_time, GETDATE()) > 24\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 60"}	{"condition": "stale_sessions_72h > 5 or stale_sessions_24h represents > 10% of current_user_connections", "description": "Accumulation of ancient sleeping sessions confirms connections persisting in static/singleton scope beyond request lifecycle"}	null	2026-02-23 20:18:31.389632
1272	sqlserver	query	Find accumulating sleeping sessions grouped by application	{"sql": "SELECT s.program_name, s.host_name,\\n  COUNT(*) AS sleeping_session_count,\\n  MIN(s.login_time) AS oldest_session,\\n  MAX(s.login_time) AS newest_session,\\n  AVG(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS avg_idle_minutes,\\n  SUM(s.open_transaction_count) AS total_open_transactions\\nFROM sys.dm_exec_sessions s\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 10\\nORDER BY sleeping_session_count DESC"}	{"condition": "sleeping_session_count > 10 from same program_name with wide spread between oldest and newest session", "description": "Multiple idle sessions from same app accumulating over time suggests event listeners registering new connections without releasing old ones"}	null	2026-02-23 20:18:31.389633
1273	sqlserver	query	Verify leaked sessions have minimal recent activity	{"sql": "SELECT s.session_id, s.program_name,\\n  s.login_time,\\n  s.last_request_end_time,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  c.num_reads, c.num_writes,\\n  s.open_transaction_count\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30\\n  AND s.program_name IN (\\n    SELECT TOP 3 program_name\\n    FROM sys.dm_exec_sessions\\n    WHERE status = 'sleeping' AND is_user_process = 1\\n      AND DATEDIFF(MINUTE, last_request_end_time, GETDATE()) > 30\\n    GROUP BY program_name\\n    ORDER BY COUNT(*) DESC\\n  )\\nORDER BY s.login_time ASC"}	{"condition": "pattern of sessions created at different times, all now idle, from same application", "description": "Staircase pattern of login_times with uniform idleness confirms connections acquired per event subscription and never released"}	null	2026-02-23 20:18:31.389633
1274	sqlserver	query	Find rapid connection acquisition bursts from same application	{"sql": "SELECT s.program_name, s.host_name,\\n  COUNT(*) AS session_count,\\n  MIN(s.login_time) AS burst_start,\\n  MAX(s.login_time) AS burst_end,\\n  DATEDIFF(SECOND, MIN(s.login_time), MAX(s.login_time)) AS burst_duration_sec,\\n  AVG(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS avg_idle_minutes\\nFROM sys.dm_exec_sessions s\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 10\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 20\\n  AND DATEDIFF(SECOND, MIN(s.login_time), MAX(s.login_time)) < 300\\nORDER BY session_count DESC"}	{"condition": "session_count > 20 within burst_duration_sec < 300 seconds, all now idle", "description": "Many connections opened in a short burst then all abandoned is characteristic of recursive functions each acquiring a connection without closing"}	null	2026-02-23 20:18:31.389634
1276	sqlserver	query	Find long-idle sessions with library-pattern SQL	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.login_time, s.last_request_end_time,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  t.text AS last_query,\\n  s.open_transaction_count\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nCROSS APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) t\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30\\n  AND s.open_transaction_count >= 0\\nORDER BY idle_minutes DESC"}	{"condition": "sessions with last_query containing framework/library patterns (e.g., sp_reset_connection, internal metadata queries, ORM-style SQL) idle > 30 min", "description": "Idle sessions whose last SQL indicates library-level operations rather than direct app queries suggest an external library retained the connection"}	null	2026-02-23 20:18:31.389635
1277	sqlserver	query	Check if leaked sessions share program_name but different query patterns	{"sql": "SELECT s.program_name,\\n  COUNT(*) AS idle_sessions,\\n  COUNT(DISTINCT CHECKSUM(t.text)) AS distinct_query_patterns,\\n  SUM(s.open_transaction_count) AS open_txns,\\n  MIN(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS min_idle_min,\\n  MAX(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS max_idle_min\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nCROSS APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) t\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30\\nGROUP BY s.program_name\\nHAVING COUNT(*) > 5"}	{"condition": "idle_sessions > 5 with multiple distinct_query_patterns from same program_name", "description": "Multiple leaked sessions from same application with varied query patterns suggests different library components each leaking connections independently"}	null	2026-02-23 20:18:31.389635
1278	sqlserver	query	Find sessions with open transactions that went idle after partial work	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.login_time, s.last_request_end_time,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  s.open_transaction_count,\\n  t.text AS last_query,\\n  dt.database_transaction_begin_time,\\n  dt.database_transaction_log_bytes_used\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nCROSS APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) t\\nJOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nJOIN sys.dm_tran_database_transactions dt ON st.transaction_id = dt.transaction_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 15\\nORDER BY idle_minutes DESC"}	{"condition": "sessions with open transactions idle > 15 minutes with log_bytes_used > 0 indicating partial work was done", "description": "Sessions that did partial transactional work then went idle suggest async operations that started transactions but had no completion handler to commit and release the connection"}	null	2026-02-23 20:18:31.389636
1279	sqlserver	query	Verify pattern recurs from same application	{"sql": "SELECT s.program_name, s.host_name,\\n  COUNT(*) AS abandoned_async_sessions,\\n  SUM(s.open_transaction_count) AS total_open_txns,\\n  AVG(dt.database_transaction_log_bytes_used) AS avg_log_bytes,\\n  MIN(s.last_request_end_time) AS oldest_idle_since\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nJOIN sys.dm_tran_database_transactions dt ON st.transaction_id = dt.transaction_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 15\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 3"}	{"condition": "abandoned_async_sessions > 3 from same program_name", "description": "Recurring pattern of abandoned transactions from same application confirms systemic async completion handler issue"}	null	2026-02-23 20:18:31.389636
1690	sqlserver	query	Check tempdb I/O stall during index build	{"sql": "SELECT\\n  mf.physical_name,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms,\\n  vfs.num_of_reads, vfs.num_of_writes,\\n  vfs.num_of_bytes_written / 1048576 AS written_mb\\nFROM sys.dm_io_virtual_file_stats(2, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE mf.database_id = 2"}	{"condition": "avg_write_stall_ms > 5 OR avg_read_stall_ms > 10", "description": "Elevated tempdb I/O latency during index rebuild with SORT_IN_TEMPDB"}	null	2026-02-23 20:18:31.389897
1955	sqlserver	query	Identify the head blocker causing the chain of lock waits	{"sql": "WITH BlockerChain AS (SELECT blocking_session_id AS head_blocker, COUNT(*) AS victims FROM sys.dm_exec_requests WHERE blocking_session_id <> 0 AND wait_type LIKE 'LCK%' GROUP BY blocking_session_id) SELECT bc.head_blocker, bc.victims, s.login_name, s.host_name, s.program_name, r.command, r.wait_type, r.wait_time / 1000 AS wait_seconds, t.text AS sql_text FROM BlockerChain bc JOIN sys.dm_exec_sessions s ON bc.head_blocker = s.session_id LEFT JOIN sys.dm_exec_requests r ON bc.head_blocker = r.session_id OUTER APPLY sys.dm_exec_sql_text(r.sql_handle) t ORDER BY bc.victims DESC"}	{"condition": "row_count > 0 AND victims > 5", "description": "A head blocker is holding locks that are cascading to multiple victim sessions, exhausting the connection pool"}	null	2026-02-23 20:18:31.390073
1280	sqlserver	query	Find sleeping sessions with open transactions and recent errors	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.login_time, s.last_request_end_time,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  s.open_transaction_count,\\n  c.most_recent_sql_handle,\\n  t.text AS last_query\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nCROSS APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) t\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 15\\n  AND (\\n    t.text LIKE '%INSERT%' OR t.text LIKE '%UPDATE%' OR t.text LIKE '%DELETE%'\\n    OR t.text LIKE '%MERGE%'\\n  )\\nORDER BY idle_minutes DESC"}	{"condition": "sleeping sessions with open DML transactions idle > 15 min", "description": "DML statements in open transactions on sleeping sessions suggest an ORM started a write operation, hit an error, and failed to rollback/close in the exception handler"}	null	2026-02-23 20:18:31.389637
1363	sqlserver	query	Check plan cache eviction counters	{"sql": "SELECT pc.type, pc.pages_kb, pc.pages_in_use_kb,\\n  pc.entries_count, pc.entries_in_use_count,\\n  pc.entries_count - pc.entries_in_use_count AS unused_entries,\\n  perf.cntr_value AS cache_hit_ratio\\nFROM sys.dm_os_memory_cache_counters pc\\nLEFT JOIN sys.dm_os_performance_counters perf\\n  ON perf.counter_name = 'Cache Hit Ratio'\\n  AND perf.object_name LIKE '%Plan Cache%'\\nWHERE pc.type IN ('CACHESTORE_SQLCP', 'CACHESTORE_OBJCP', 'CACHESTORE_PHDR')\\nORDER BY pc.pages_kb DESC"}	{"condition": "large unused_entries count or low cache hit ratio", "description": "Plan cache stores show high turnover indicating frequent evictions"}	null	2026-02-23 20:18:31.389638
14798	mariadb	config_check	Check secure_file_priv restriction	{"sql": "SHOW GLOBAL VARIABLES LIKE 'secure_file_priv'"}	{"condition": "value = '' OR value IS NULL", "description": "secure_file_priv is empty or NULL, meaning FILE operations are unrestricted"}	\N	2026-05-11 22:17:39.229791
1281	sqlserver	query	Correlate with error log ring buffer for session errors	{"sql": "SELECT s.session_id, s.program_name,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  s.open_transaction_count,\\n  dt.database_transaction_state,\\n  dt.database_transaction_log_bytes_used,\\n  dt.database_transaction_log_bytes_reserved\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nJOIN sys.dm_tran_database_transactions dt ON st.transaction_id = dt.transaction_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 15\\n  AND dt.database_transaction_state IN (4, 6)\\nORDER BY s.last_request_end_time"}	{"condition": "database_transaction_state = 4 (uncommittable) or 6 (read-only/aborted marker) indicates error condition", "description": "Transaction in uncommittable state (XACT_STATE=-1 equivalent) confirms an error occurred and the ORM did not roll back or release the connection"}	null	2026-02-23 20:18:31.389638
1505	sqlserver	query	Check LOGBUFFER wait statistics	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'LOGBUFFER'"}	{"condition": "waiting_tasks_count > 100 AND avg_wait_ms > 1", "description": "LOGBUFFER waits indicate sessions waiting for space in the in-memory log buffer"}	null	2026-02-23 20:18:31.389639
1282	sqlserver	query	Profile idle session age distribution	{"sql": "SELECT\\n  CASE\\n    WHEN DATEDIFF(MINUTE, last_request_end_time, GETDATE()) < 5 THEN '0-5min'\\n    WHEN DATEDIFF(MINUTE, last_request_end_time, GETDATE()) < 30 THEN '5-30min'\\n    WHEN DATEDIFF(MINUTE, last_request_end_time, GETDATE()) < 120 THEN '30min-2hr'\\n    WHEN DATEDIFF(MINUTE, last_request_end_time, GETDATE()) < 480 THEN '2-8hr'\\n    ELSE '8hr+'\\n  END AS idle_bucket,\\n  COUNT(*) AS session_count\\nFROM sys.dm_exec_sessions\\nWHERE status = 'sleeping'\\n  AND is_user_process = 1\\nGROUP BY\\n  CASE\\n    WHEN DATEDIFF(MINUTE, last_request_end_time, GETDATE()) < 5 THEN '0-5min'\\n    WHEN DATEDIFF(MINUTE, last_request_end_time, GETDATE()) < 30 THEN '5-30min'\\n    WHEN DATEDIFF(MINUTE, last_request_end_time, GETDATE()) < 120 THEN '30min-2hr'\\n    WHEN DATEDIFF(MINUTE, last_request_end_time, GETDATE()) < 480 THEN '2-8hr'\\n    ELSE '8hr+'\\n  END\\nORDER BY MIN(DATEDIFF(MINUTE, last_request_end_time, GETDATE()))"}	{"condition": "significant count in 2-8hr or 8hr+ buckets", "description": "A healthy pool with idle timeout should have few sessions beyond the timeout threshold — heavy-tail distribution indicates no eviction"}	null	2026-02-23 20:18:31.38964
1283	sqlserver	query	Verify no cleanup trend across applications	{"sql": "SELECT s.program_name,\\n  COUNT(*) AS total_sleeping,\\n  SUM(CASE WHEN DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 120 THEN 1 ELSE 0 END) AS idle_over_2hr,\\n  MAX(DATEDIFF(HOUR, s.last_request_end_time, GETDATE())) AS max_idle_hours,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%General Statistics%'\\n     AND counter_name = 'User Connections') AS total_connections\\nFROM sys.dm_exec_sessions s\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING SUM(CASE WHEN DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 120 THEN 1 ELSE 0 END) > 5\\nORDER BY idle_over_2hr DESC"}	{"condition": "idle_over_2hr > 5 per application with max_idle_hours > 8", "description": "Applications with many sessions idle for hours and no eviction boundary confirm missing idle timeout configuration"}	null	2026-02-23 20:18:31.38964
1284	sqlserver	query	Find orphaned sleeping sessions without open transactions	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.login_time, s.last_request_end_time,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  s.open_transaction_count,\\n  c.num_reads, c.num_writes,\\n  c.net_transport, c.client_net_address\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND s.open_transaction_count = 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 60\\nORDER BY idle_minutes DESC"}	{"condition": "row_count > 10 with sessions idle > 60 min and no open transactions", "description": "Many sleeping sessions with no transactions but long idle time indicates connections were dereferenced (set to null) without calling close/dispose"}	null	2026-02-23 20:18:31.389641
1285	sqlserver	query	Check connection accumulation rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%General Statistics%'\\n     AND counter_name = 'User Connections') AS current_connections,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%General Statistics%'\\n     AND counter_name = 'Logins/sec') AS logins_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%General Statistics%'\\n     AND counter_name = 'Logouts/sec') AS logouts_per_sec,\\n  COUNT(*) AS orphaned_sessions\\nFROM sys.dm_exec_sessions\\nWHERE status = 'sleeping'\\n  AND is_user_process = 1\\n  AND open_transaction_count = 0\\n  AND DATEDIFF(MINUTE, last_request_end_time, GETDATE()) > 60"}	{"condition": "logins_per_sec significantly exceeds logouts_per_sec and orphaned_sessions growing", "description": "Login rate exceeding logout rate with growing orphaned session count confirms connections opened but never formally closed"}	null	2026-02-23 20:18:31.389642
1288	sqlserver	query	Find sleeping sessions with long-running open transactions	{"sql": "SELECT s.session_id, s.program_name, s.host_name, s.login_name,\\n  s.last_request_end_time,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  at.transaction_id, at.name AS transaction_name,\\n  at.transaction_begin_time,\\n  DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) AS txn_age_minutes,\\n  dt.database_transaction_log_bytes_used,\\n  dt.database_transaction_log_bytes_reserved\\nFROM sys.dm_tran_active_transactions at\\nJOIN sys.dm_tran_session_transactions st ON at.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_sessions s ON st.session_id = s.session_id\\nLEFT JOIN sys.dm_tran_database_transactions dt ON at.transaction_id = dt.transaction_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) > 30\\nORDER BY at.transaction_begin_time"}	{"condition": "row_count > 0 with txn_age_minutes > 30 on sleeping sessions", "description": "Open transactions on sleeping sessions older than 30 minutes are abandoned — they will never be committed or rolled back without intervention"}	null	2026-02-23 20:18:31.389645
1657	sqlserver	query	Check tempdb file count vs CPU cores	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.master_files\\n   WHERE database_id = 2 AND type_desc = 'ROWS') AS tempdb_data_files,\\n  (SELECT cpu_count FROM sys.dm_os_sys_info) AS logical_cpus,\\n  (SELECT COUNT(*) FROM sys.master_files\\n   WHERE database_id = 2 AND type_desc = 'ROWS') * 1.0 /\\n  (SELECT cpu_count FROM sys.dm_os_sys_info) AS files_per_cpu"}	{"condition": "tempdb_data_files < logical_cpus AND tempdb_data_files < 8", "description": "Fewer tempdb data files than CPU cores (up to 8) — primary cause of allocation contention"}	null	2026-02-23 20:18:31.389877
1289	sqlserver	query	Check blocking and log impact of abandoned transactions	{"sql": "SELECT s.session_id,\\n  DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) AS txn_age_minutes,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests r\\n   WHERE r.blocking_session_id = s.session_id) AS blocked_session_count,\\n  dt.database_transaction_log_bytes_used / 1048576.0 AS log_used_mb,\\n  lsu.log_space_in_bytes_since_last_backup / 1048576.0 AS log_since_backup_mb,\\n  d.log_reuse_wait_desc\\nFROM sys.dm_tran_active_transactions at\\nJOIN sys.dm_tran_session_transactions st ON at.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_sessions s ON st.session_id = s.session_id\\nLEFT JOIN sys.dm_tran_database_transactions dt ON at.transaction_id = dt.transaction_id\\nLEFT JOIN sys.dm_db_log_space_usage lsu ON dt.database_id = lsu.database_id\\nLEFT JOIN sys.databases d ON dt.database_id = d.database_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) > 30\\nORDER BY txn_age_minutes DESC"}	{"condition": "abandoned transactions causing blocking (blocked_session_count > 0) or preventing log truncation (log_reuse_wait_desc = 'ACTIVE_TRANSACTION')", "description": "Abandoned transactions actively degrading performance through lock contention or transaction log growth"}	null	2026-02-23 20:18:31.389645
1290	sqlserver	query	Find sessions with request-scope timing anomalies	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.login_time, s.last_request_start_time, s.last_request_end_time,\\n  DATEDIFF(SECOND, s.last_request_start_time, s.last_request_end_time) AS last_request_duration_sec,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_since_min,\\n  DATEDIFF(MINUTE, s.login_time, s.last_request_end_time) AS active_duration_min,\\n  c.num_reads, c.num_writes,\\n  s.open_transaction_count\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30\\n  AND (c.num_reads + c.num_writes) > 0\\n  AND DATEDIFF(SECOND, s.last_request_start_time, s.last_request_end_time) < 5\\nORDER BY idle_since_min DESC"}	{"condition": "sessions with very short last_request_duration but long idle time, suggesting request completed quickly but connection was not returned to pool scope", "description": "Short request duration followed by indefinite idle indicates connection acquired in request scope but never released when that scope ended"}	null	2026-02-23 20:18:31.389646
1691	sqlserver	query	Check tempdb file locations vs user database files	{"sql": "SELECT\\n  'tempdb' AS source,\\n  mf.physical_name AS file_path,\\n  LEFT(mf.physical_name, 3) AS drive_letter,\\n  mf.type_desc\\nFROM sys.master_files mf\\nWHERE mf.database_id = 2\\nUNION ALL\\nSELECT\\n  d.name AS source,\\n  mf.physical_name AS file_path,\\n  LEFT(mf.physical_name, 3) AS drive_letter,\\n  mf.type_desc\\nFROM sys.master_files mf\\nJOIN sys.databases d ON mf.database_id = d.database_id\\nWHERE mf.database_id > 4\\nORDER BY drive_letter, source"}	{"condition": "tempdb drive_letter matches any user database drive_letter", "description": "Tempdb co-located on same drive as user database files"}	null	2026-02-23 20:18:31.389898
1291	sqlserver	query	Verify scope-leaked sessions are accumulating per application	{"sql": "SELECT s.program_name,\\n  COUNT(*) AS scope_leaked_sessions,\\n  AVG(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS avg_idle_min,\\n  AVG(DATEDIFF(SECOND, s.last_request_start_time, s.last_request_end_time)) AS avg_request_sec\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30\\n  AND DATEDIFF(SECOND, s.last_request_start_time, s.last_request_end_time) < 5\\nGROUP BY s.program_name\\nHAVING COUNT(*) > 5\\nORDER BY scope_leaked_sessions DESC"}	{"condition": "scope_leaked_sessions > 5 with avg_request_sec < 5 but avg_idle_min >> 30", "description": "Application accumulating many sessions that did quick work then went indefinitely idle confirms request-scope acquisition with different-scope (or no) release"}	null	2026-02-23 20:18:31.389647
1292	sqlserver	query	Find clusters of sleeping sessions from batch job patterns	{"sql": "SELECT s.program_name, s.host_name,\\n  COUNT(*) AS batch_session_count,\\n  MIN(s.login_time) AS batch_start,\\n  MAX(s.login_time) AS batch_end,\\n  DATEDIFF(MINUTE, MIN(s.login_time), MAX(s.login_time)) AS batch_window_min,\\n  SUM(s.open_transaction_count) AS open_txns,\\n  MIN(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS min_idle_min,\\n  MAX(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS max_idle_min\\nFROM sys.dm_exec_sessions s\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 15\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 10\\n  AND MAX(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()))\\n    - MIN(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) < 30\\nORDER BY batch_session_count DESC"}	{"condition": "batch_session_count > 10 with similar idle times (max_idle - min_idle < 30 min), indicating all sessions abandoned around the same time", "description": "Cluster of sessions that all went idle within a short window suggests a batch job that acquired many connections in parallel and failed to clean them up"}	null	2026-02-23 20:18:31.389647
4365	postgresql	query	Check replication slot status for WAL retention	{"sql": "SELECT slot_name, slot_type, active, restart_lsn, confirmed_flush_lsn, pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS retained_wal FROM pg_replication_slots ORDER BY pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) DESC"}	{"condition": "row_count > 0", "description": "Replication slots retaining WAL segments, potentially accumulating significant log data"}	\N	2026-02-25 00:28:52.405273
1384	sqlserver	query	Check MAXDOP exceeds physical core count per NUMA	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS int) FROM sys.configurations\\n   WHERE name = 'max degree of parallelism') AS maxdop,\\n  si.cpu_count / si.hyperthread_ratio AS physical_cores,\\n  si.cpu_count / si.hyperthread_ratio / NULLIF(si.numa_node_count, 0) AS cores_per_numa,\\n  si.cpu_count AS logical_cpus\\nFROM sys.dm_os_sys_info si"}	{"condition": "maxdop > cores_per_numa or maxdop = 0", "description": "MAXDOP allows scheduling on HT siblings — parallel threads share physical cores"}	null	2026-02-23 20:18:31.389711
1293	sqlserver	query	Check for partial work pattern in batch sessions	{"sql": "SELECT s.session_id, s.program_name,\\n  c.num_reads, c.num_writes,\\n  s.open_transaction_count,\\n  t.text AS last_query,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_min\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nCROSS APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) t\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 15\\n  AND s.program_name IN (\\n    SELECT TOP 1 program_name\\n    FROM sys.dm_exec_sessions\\n    WHERE status = 'sleeping' AND is_user_process = 1\\n      AND DATEDIFF(MINUTE, last_request_end_time, GETDATE()) > 15\\n    GROUP BY program_name\\n    HAVING COUNT(*) > 10\\n    ORDER BY COUNT(*) DESC\\n  )\\nORDER BY c.num_writes DESC"}	{"condition": "some sessions have num_writes > 0 (completed work) while others have num_writes = 0 (acquired but never used) — partial failure pattern", "description": "Mix of used and unused connections from same batch confirms partial failure: some tasks completed, others were abandoned along with their connections"}	null	2026-02-23 20:18:31.389648
1294	sqlserver	query	Check connection churn rate via performance counters	{"sql": "SELECT\\n  pc1.cntr_value AS logins_total,\\n  pc2.cntr_value AS logouts_total,\\n  pc3.cntr_value AS user_connections,\\n  pc4.cntr_value AS connection_resets_total,\\n  CASE WHEN pc4.cntr_value > 0 AND pc1.cntr_value > 0\\n    THEN CAST(pc4.cntr_value AS FLOAT) / pc1.cntr_value\\n    ELSE 0 END AS reset_to_login_ratio\\nFROM sys.dm_os_performance_counters pc1\\nCROSS JOIN sys.dm_os_performance_counters pc2\\nCROSS JOIN sys.dm_os_performance_counters pc3\\nCROSS JOIN sys.dm_os_performance_counters pc4\\nWHERE pc1.object_name LIKE '%General Statistics%' AND pc1.counter_name = 'Logins/sec'\\n  AND pc2.object_name LIKE '%General Statistics%' AND pc2.counter_name = 'Logouts/sec'\\n  AND pc3.object_name LIKE '%General Statistics%' AND pc3.counter_name = 'User Connections'\\n  AND pc4.object_name LIKE '%General Statistics%' AND pc4.counter_name = 'Connection Resets/sec'"}	{"condition": "reset_to_login_ratio < 0.5 (most logins are physical, not pool resets) and logins_total is high relative to user_connections", "description": "Low reset-to-login ratio means the app is making physical connections rather than reusing pooled ones — Connection Reset/sec tracks pool reuse while Logins/sec tracks new physical connections"}	null	2026-02-23 20:18:31.389649
1295	sqlserver	query	Verify short session lifetimes indicating no pooling	{"sql": "SELECT s.program_name,\\n  COUNT(*) AS active_sessions,\\n  AVG(DATEDIFF(SECOND, s.login_time, GETDATE())) AS avg_session_age_sec,\\n  MIN(DATEDIFF(SECOND, s.login_time, GETDATE())) AS min_session_age_sec,\\n  MAX(DATEDIFF(SECOND, s.login_time, GETDATE())) AS max_session_age_sec\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING AVG(DATEDIFF(SECOND, s.login_time, GETDATE())) < 60\\nORDER BY active_sessions DESC"}	{"condition": "avg_session_age_sec < 60 indicating very short-lived connections that are created and destroyed per request", "description": "Average session age under 60 seconds confirms connection-per-request pattern with no pooling — pooled connections would show longer login_time ages"}	null	2026-02-23 20:18:31.38965
1296	sqlserver	query	Measure connection turnover rate	{"sql": "SELECT\\n  pc1.cntr_value AS logins_total,\\n  pc2.cntr_value AS logouts_total,\\n  pc3.cntr_value AS user_connections,\\n  pc4.cntr_value AS connection_resets_total,\\n  CASE WHEN pc3.cntr_value > 0\\n    THEN CAST(pc1.cntr_value AS FLOAT) / pc3.cntr_value\\n    ELSE 0 END AS login_to_connection_ratio\\nFROM sys.dm_os_performance_counters pc1\\nCROSS JOIN sys.dm_os_performance_counters pc2\\nCROSS JOIN sys.dm_os_performance_counters pc3\\nCROSS JOIN sys.dm_os_performance_counters pc4\\nWHERE pc1.object_name LIKE '%General Statistics%' AND pc1.counter_name = 'Logins/sec'\\n  AND pc2.object_name LIKE '%General Statistics%' AND pc2.counter_name = 'Logouts/sec'\\n  AND pc3.object_name LIKE '%General Statistics%' AND pc3.counter_name = 'User Connections'\\n  AND pc4.object_name LIKE '%General Statistics%' AND pc4.counter_name = 'Connection Resets/sec'"}	{"condition": "logins_total approximately equals logouts_total (balanced churn) AND login_to_connection_ratio is high (many physical connections created per existing connection) AND connection_resets_total is also high (pool IS being used, but connections keep getting replaced)", "description": "High logins AND high resets together indicate pooling is active but connections are being physically replaced too often — maxLifetime is forcing premature connection recycling"}	null	2026-02-23 20:18:31.38965
1297	sqlserver	query	Check session age distribution for premature eviction pattern	{"sql": "SELECT\\n  CASE\\n    WHEN DATEDIFF(MINUTE, login_time, GETDATE()) < 5 THEN '0-5min'\\n    WHEN DATEDIFF(MINUTE, login_time, GETDATE()) < 15 THEN '5-15min'\\n    WHEN DATEDIFF(MINUTE, login_time, GETDATE()) < 30 THEN '15-30min'\\n    WHEN DATEDIFF(MINUTE, login_time, GETDATE()) < 60 THEN '30-60min'\\n    ELSE '60min+'\\n  END AS session_age_bucket,\\n  COUNT(*) AS session_count\\nFROM sys.dm_exec_sessions\\nWHERE is_user_process = 1\\nGROUP BY\\n  CASE\\n    WHEN DATEDIFF(MINUTE, login_time, GETDATE()) < 5 THEN '0-5min'\\n    WHEN DATEDIFF(MINUTE, login_time, GETDATE()) < 15 THEN '5-15min'\\n    WHEN DATEDIFF(MINUTE, login_time, GETDATE()) < 30 THEN '15-30min'\\n    WHEN DATEDIFF(MINUTE, login_time, GETDATE()) < 60 THEN '30-60min'\\n    ELSE '60min+'\\n  END\\nORDER BY MIN(DATEDIFF(MINUTE, login_time, GETDATE()))"}	{"condition": "sharp cutoff in session age distribution — very few sessions beyond a threshold (e.g., no sessions > 30min) indicating forced recycling", "description": "A hard ceiling on session age confirms pool maxLifetime/Connection Lifetime is forcing connection replacement — healthy pools show a gradual tail, not a cliff"}	null	2026-02-23 20:18:31.389651
1298	sqlserver	query	Check for high physical login rate with minimal reuse	{"sql": "SELECT\\n  pc1.cntr_value AS logins_total,\\n  pc4.cntr_value AS connection_resets_total,\\n  pc3.cntr_value AS user_connections,\\n  CASE WHEN pc1.cntr_value > 0\\n    THEN CAST(pc4.cntr_value AS FLOAT) / pc1.cntr_value * 100\\n    ELSE 0 END AS reuse_pct\\nFROM sys.dm_os_performance_counters pc1\\nCROSS JOIN sys.dm_os_performance_counters pc3\\nCROSS JOIN sys.dm_os_performance_counters pc4\\nWHERE pc1.object_name LIKE '%General Statistics%' AND pc1.counter_name = 'Logins/sec'\\n  AND pc3.object_name LIKE '%General Statistics%' AND pc3.counter_name = 'User Connections'\\n  AND pc4.object_name LIKE '%General Statistics%' AND pc4.counter_name = 'Connection Resets/sec'"}	{"condition": "reuse_pct < 10 (very few connections are being reused) with logins_total high relative to uptime", "description": "Near-zero pool reuse with high login rate indicates every invocation creates a fresh physical connection — classic serverless pattern"}	null	2026-02-23 20:18:31.389652
1299	sqlserver	query	Profile session duration for serverless short-lived pattern	{"sql": "SELECT s.program_name,\\n  COUNT(*) AS current_sessions,\\n  AVG(DATEDIFF(SECOND, s.login_time, GETDATE())) AS avg_age_sec,\\n  AVG(c.num_reads + c.num_writes) AS avg_io_per_session,\\n  COUNT(DISTINCT s.host_name) AS distinct_hosts\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING AVG(DATEDIFF(SECOND, s.login_time, GETDATE())) < 30\\n  AND AVG(c.num_reads + c.num_writes) < 20\\nORDER BY current_sessions DESC"}	{"condition": "avg_age_sec < 30 with avg_io_per_session < 20 and potentially many distinct_hosts (different Lambda/Function instances)", "description": "Very short sessions with minimal I/O from many different hosts is the serverless fingerprint — each function invocation connects, does minimal work, disconnects"}	null	2026-02-23 20:18:31.389652
14877	mariadb	query	Check SSL certificate details	{"sql": "SHOW GLOBAL STATUS WHERE Variable_name LIKE 'Ssl_server%'"}	{"condition": "issuer_equals_subject", "description": "SSL certificate is self-signed (issuer equals subject)"}	\N	2026-05-11 22:17:39.229791
1300	sqlserver	query	Find distinct connection profiles from same application	{"sql": "SELECT s.program_name, s.host_name,\\n  s.login_name, c.auth_scheme,\\n  DB_NAME(s.database_id) AS current_database,\\n  c.encrypt_option,\\n  COUNT(*) AS session_count\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name, s.login_name,\\n  c.auth_scheme, DB_NAME(s.database_id), c.encrypt_option\\nHAVING COUNT(*) >= 1\\nORDER BY s.program_name, session_count DESC"}	{"condition": "same program_name with multiple distinct login_name or database combinations", "description": "Same application using different logins, databases, or auth schemes per request creates separate connection pools for each combination, defeating reuse"}	null	2026-02-23 20:18:31.389653
1301	sqlserver	query	Verify churn correlates with pool fragmentation	{"sql": "SELECT s.program_name,\\n  COUNT(DISTINCT s.login_name) AS distinct_logins,\\n  COUNT(DISTINCT DB_NAME(s.database_id)) AS distinct_databases,\\n  COUNT(*) AS total_sessions,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%General Statistics%'\\n     AND counter_name = 'Logins/sec') AS logins_total,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%General Statistics%'\\n     AND counter_name = 'Connection Resets/sec') AS resets_total\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING COUNT(DISTINCT s.login_name) > 3\\n  OR COUNT(DISTINCT DB_NAME(s.database_id)) > 3\\nORDER BY total_sessions DESC"}	{"condition": "distinct_logins > 3 or distinct_databases > 3 from same program_name with high login rate", "description": "Many distinct connection profiles from same application with high physical login rate confirms connection string variation is fragmenting the pool and preventing reuse"}	null	2026-02-23 20:18:31.389654
1302	sqlserver	query	Profile connections per client host	{"sql": "SELECT s.program_name,\\n  COUNT(DISTINCT c.client_net_address) AS distinct_clients,\\n  COUNT(*) AS total_sessions,\\n  COUNT(*) * 1.0 / NULLIF(COUNT(DISTINCT c.client_net_address), 0) AS avg_sessions_per_client,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%General Statistics%'\\n     AND counter_name = 'User Connections') AS total_user_connections\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name\\nHAVING COUNT(DISTINCT c.client_net_address) > 5\\nORDER BY distinct_clients DESC"}	{"condition": "distinct_clients > 5 with avg_sessions_per_client < 10", "description": "Many client hosts each holding few connections means each backend instance runs its own small pool — aggregate connection count = N_instances x pool_size"}	null	2026-02-23 20:18:31.389654
1303	sqlserver	query	Verify aggregate connection pressure from distributed pools	{"sql": "SELECT c.client_net_address, s.program_name,\\n  COUNT(*) AS sessions_from_host,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping_sessions,\\n  SUM(CASE WHEN s.status = 'running' THEN 1 ELSE 0 END) AS active_sessions\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY c.client_net_address, s.program_name\\nHAVING COUNT(*) > 1\\nORDER BY sleeping_sessions DESC"}	{"condition": "most hosts show more sleeping than active sessions, indicating each small pool's minimum idle connections are wasted across N instances", "description": "Each backend instance keeping minimum pool size of idle connections multiplied across many instances creates excessive aggregate connection consumption"}	null	2026-02-23 20:18:31.389655
1311	sqlserver	query	Verify high connection creation overhead from churn	{"sql": "SELECT\\n  wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PREEMPTIVE_OS_AUTHENTICATIONOPS',\\n  'PREEMPTIVE_OS_ACCEPTSECURITYCONTEXT',\\n  'LOGMGR', 'WRITELOG')\\n  AND waiting_tasks_count > 100\\nORDER BY wait_time_ms DESC"}	{"condition": "PREEMPTIVE_OS_AUTHENTICATIONOPS waiting_tasks_count > 1000 with high cumulative wait_time_ms", "description": "High authentication operation counts confirm that the server is spending significant time authenticating new connections that could have been reused if the client driver timeout were longer"}	null	2026-02-23 20:18:31.38966
1304	sqlserver	query	Check connection reset and validation query frequency	{"sql": "SELECT\\n  pc1.cntr_value AS connection_resets_total,\\n  pc2.cntr_value AS user_connections,\\n  pc3.cntr_value AS logins_total,\\n  CASE WHEN pc2.cntr_value > 0\\n    THEN CAST(pc1.cntr_value AS FLOAT) / pc2.cntr_value\\n    ELSE 0 END AS resets_per_connection\\nFROM sys.dm_os_performance_counters pc1\\nCROSS JOIN sys.dm_os_performance_counters pc2\\nCROSS JOIN sys.dm_os_performance_counters pc3\\nWHERE pc1.object_name LIKE '%General Statistics%' AND pc1.counter_name = 'Connection Resets/sec'\\n  AND pc2.object_name LIKE '%General Statistics%' AND pc2.counter_name = 'User Connections'\\n  AND pc3.object_name LIKE '%General Statistics%' AND pc3.counter_name = 'Logins/sec'"}	{"condition": "resets_per_connection very high (>> 100) indicating connections are being validated/reset far more often than expected for normal pool reuse", "description": "Very high reset-per-connection ratio suggests the pool is running health checks (sp_reset_connection + SELECT 1) on every borrow, return, or on a very short validation interval"}	null	2026-02-23 20:18:31.389655
1305	sqlserver	query	Identify health check queries dominating workload	{"sql": "SELECT TOP 10\\n  qs.execution_count,\\n  qs.total_worker_time / 1000 AS total_cpu_ms,\\n  qs.total_elapsed_time / 1000 AS total_elapsed_ms,\\n  SUBSTRING(qt.text, 1, 200) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) qt\\nWHERE qt.text LIKE '%SELECT 1%'\\n  OR qt.text LIKE '%SELECT @@VERSION%'\\n  OR qt.text LIKE '%sp_reset_connection%'\\n  OR qt.text LIKE '%SELECT GETDATE()%'\\n  OR qt.text LIKE '%SELECT DB_NAME()%'\\nORDER BY qs.execution_count DESC"}	{"condition": "validation queries (SELECT 1, SELECT @@VERSION, etc.) with very high execution_count relative to actual workload queries", "description": "Health check queries dominating execution count confirms overly aggressive validation interval — these lightweight queries individually cost little but at high frequency consume CPU and increase latency"}	null	2026-02-23 20:18:31.389656
1306	sqlserver	query	Check for high login/logout rate indicating connection churn	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec'\\n     AND object_name LIKE '%General Statistics%') AS logins_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logouts/sec'\\n     AND object_name LIKE '%General Statistics%') AS logouts_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Connection Resets/sec'\\n     AND object_name LIKE '%General Statistics%') AS connection_resets_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'User Connections'\\n     AND object_name LIKE '%General Statistics%') AS current_connections"}	{"condition": "logins_sec > 50 AND logouts_sec > 50 AND logins_sec approximately equals logouts_sec", "description": "High login/logout rates that are roughly equal indicate connections are being established and torn down rapidly rather than being pooled and reused"}	null	2026-02-23 20:18:31.389657
1307	sqlserver	query	Check for connections with short lifetimes suggesting timeout-driven drops	{"sql": "SELECT\\n  c.client_net_address,\\n  COUNT(*) AS connection_count,\\n  AVG(DATEDIFF(SECOND, c.connect_time, GETDATE())) AS avg_age_seconds,\\n  MAX(DATEDIFF(SECOND, c.connect_time, GETDATE())) AS max_age_seconds,\\n  MIN(DATEDIFF(SECOND, c.connect_time, GETDATE())) AS min_age_seconds\\nFROM sys.dm_exec_connections c\\nGROUP BY c.client_net_address\\nHAVING MAX(DATEDIFF(SECOND, c.connect_time, GETDATE())) < 1800\\n  AND COUNT(*) > 5\\nORDER BY connection_count DESC"}	{"condition": "client addresses where max_age_seconds clusters around a common timeout value (e.g., 300, 600, 900)", "description": "When all connections from a client are younger than a common firewall timeout interval, it suggests network infrastructure is killing idle connections at that threshold"}	null	2026-02-23 20:18:31.389658
1308	sqlserver	query	Check for connection errors and network-related wait types	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms, max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PREEMPTIVE_OS_ACCEPTSECURITYCONTEXT',\\n  'PREEMPTIVE_OS_AUTHENTICATIONOPS',\\n  'ASYNC_NETWORK_IO', 'NETWORK_IO')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "high PREEMPTIVE_OS_ACCEPTSECURITYCONTEXT or PREEMPTIVE_OS_AUTHENTICATIONOPS waits", "description": "Elevated authentication-related waits confirm frequent re-authentication cycles consistent with connections being dropped and re-established due to network timeouts"}	null	2026-02-23 20:18:31.389659
1309	sqlserver	query	Check login/logout rate vs connection reset rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec'\\n     AND object_name LIKE '%General Statistics%') AS logins_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logouts/sec'\\n     AND object_name LIKE '%General Statistics%') AS logouts_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Connection Resets/sec'\\n     AND object_name LIKE '%General Statistics%') AS connection_resets_sec"}	{"condition": "logins_sec > logouts_sec * 0.8 AND connection_resets_sec < logins_sec * 0.3", "description": "High login rate close to logout rate with low connection resets indicates connections are being fully closed and reopened rather than being reset and reused in a pool"}	null	2026-02-23 20:18:31.389659
1310	sqlserver	query	Check for short-lived connections with rapid turnover	{"sql": "SELECT\\n  s.program_name,\\n  s.host_name,\\n  COUNT(*) AS session_count,\\n  AVG(DATEDIFF(SECOND, c.connect_time, GETDATE())) AS avg_connection_age_sec,\\n  MIN(DATEDIFF(SECOND, c.connect_time, GETDATE())) AS min_connection_age_sec,\\n  MAX(DATEDIFF(SECOND, c.connect_time, GETDATE())) AS max_connection_age_sec\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name\\nHAVING AVG(DATEDIFF(SECOND, c.connect_time, GETDATE())) < 120\\nORDER BY session_count DESC"}	{"condition": "programs with avg_connection_age_sec < 60 and multiple active sessions", "description": "Client applications maintaining very short-lived connections suggest the driver idle timeout is aggressively closing connections before they can be reused"}	null	2026-02-23 20:18:31.38966
1312	sqlserver	query	Check SQL Server start time for recent restart or failover	{"sql": "SELECT\\n  sqlserver_start_time,\\n  DATEDIFF(MINUTE, sqlserver_start_time, GETDATE()) AS uptime_minutes,\\n  CASE\\n    WHEN DATEDIFF(MINUTE, sqlserver_start_time, GETDATE()) < 60 THEN 'RECENT_RESTART'\\n    WHEN DATEDIFF(MINUTE, sqlserver_start_time, GETDATE()) < 1440 THEN 'RESTARTED_TODAY'\\n    ELSE 'STABLE'\\n  END AS restart_status\\nFROM sys.dm_os_sys_info"}	{"condition": "uptime_minutes < 60 OR RECENT_RESTART status", "description": "A recent SQL Server restart or failover means all existing pooled connections were forcibly closed and clients must establish new connections"}	null	2026-02-23 20:18:31.389661
1313	sqlserver	query	Check for connection storm pattern — many connections created near start time	{"sql": "SELECT\\n  DATEPART(MINUTE, c.connect_time) AS connect_minute,\\n  COUNT(*) AS connections_created,\\n  MIN(c.connect_time) AS earliest_connection,\\n  MAX(c.connect_time) AS latest_connection\\nFROM sys.dm_exec_connections c\\nWHERE c.connect_time > (SELECT sqlserver_start_time FROM sys.dm_os_sys_info)\\nGROUP BY DATEPART(MINUTE, c.connect_time)\\nORDER BY connect_minute"}	{"condition": "large spike of connections_created in the first few minutes after start time", "description": "A burst of connection creation immediately after server start indicates all clients simultaneously reconnecting after the failover or restart event"}	null	2026-02-23 20:18:31.389662
1506	sqlserver	query	Check WRITELOG waits as downstream confirmation	{"sql": "SELECT\\n  lb.waiting_tasks_count AS logbuffer_waits,\\n  lb.wait_time_ms AS logbuffer_wait_ms,\\n  wl.waiting_tasks_count AS writelog_waits,\\n  wl.wait_time_ms AS writelog_wait_ms,\\n  wl.wait_time_ms / NULLIF(wl.waiting_tasks_count, 0) AS avg_writelog_ms\\nFROM sys.dm_os_wait_stats lb\\nCROSS JOIN sys.dm_os_wait_stats wl\\nWHERE lb.wait_type = 'LOGBUFFER'\\n  AND wl.wait_type = 'WRITELOG'"}	{"condition": "logbuffer_waits > 0 AND avg_writelog_ms > 2", "description": "LOGBUFFER waits combined with slow WRITELOG — log buffer fills up because log writes are slow"}	null	2026-02-23 20:18:31.389663
3436	postgresql	log_scan	Scan for storage I/O errors	{"pattern": "could not open file|could not read file|could not write file|No such file or directory|Input/output error|read-only file system|could not fsync", "description": "I/O errors indicating storage subsystem problems"}	{"condition": "pattern_found", "description": "Storage subsystem I/O errors detected"}	\N	2026-02-25 00:28:52.405273
1315	sqlserver	query	Compare login rate to batch request rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec'\\n     AND object_name LIKE '%General Statistics%') AS logins_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logouts/sec'\\n     AND object_name LIKE '%General Statistics%') AS logouts_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS batch_requests_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Connection Resets/sec'\\n     AND object_name LIKE '%General Statistics%') AS connection_resets_sec"}	{"condition": "logins_sec > batch_requests_sec * 0.5", "description": "When the login rate is more than half the batch request rate, it strongly suggests connections are being created per query rather than pooled and reused across multiple queries"}	null	2026-02-23 20:18:31.389663
1316	sqlserver	query	Check for extremely short-lived connections	{"sql": "SELECT\\n  s.program_name,\\n  s.host_name,\\n  COUNT(*) AS active_sessions,\\n  AVG(DATEDIFF(SECOND, c.connect_time, GETDATE())) AS avg_age_sec,\\n  MIN(DATEDIFF(SECOND, c.connect_time, GETDATE())) AS min_age_sec\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name\\nORDER BY active_sessions DESC"}	{"condition": "programs with low active_sessions but high login rate from step 1, AND avg_age_sec < 5", "description": "Very short average connection age combined with few active sessions but high throughput indicates open-use-close pattern per query"}	null	2026-02-23 20:18:31.389664
1317	sqlserver	query	Confirm connection churn overhead in authentication waits	{"sql": "SELECT\\n  wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PREEMPTIVE_OS_AUTHENTICATIONOPS',\\n  'PREEMPTIVE_OS_ACCEPTSECURITYCONTEXT',\\n  'PREEMPTIVE_OS_LOOKUPACCOUNTSID')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PREEMPTIVE_OS_AUTHENTICATIONOPS wait_time_ms > 10000 with count proportional to login rate", "description": "High cumulative authentication wait time proportional to login rate confirms the server is spending significant resources authenticating per-query connections"}	null	2026-02-23 20:18:31.389665
1318	sqlserver	query	Check compilation rate vs batch request rate for plan reuse efficiency	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Compilations/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS batch_requests_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Re-Compilations/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS recompilations_sec,\\n  CASE\\n    WHEN (SELECT cntr_value FROM sys.dm_os_performance_counters\\n          WHERE counter_name = 'Batch Requests/sec'\\n            AND object_name LIKE '%SQL Statistics%') > 0\\n    THEN (SELECT cntr_value FROM sys.dm_os_performance_counters\\n          WHERE counter_name = 'SQL Compilations/sec'\\n            AND object_name LIKE '%SQL Statistics%') * 100.0 /\\n         (SELECT cntr_value FROM sys.dm_os_performance_counters\\n          WHERE counter_name = 'Batch Requests/sec'\\n            AND object_name LIKE '%SQL Statistics%')\\n    ELSE 0\\n  END AS compilation_pct_of_batches"}	{"condition": "compilation_pct_of_batches > 25", "description": "When compilations exceed 25% of batch requests, it indicates most queries are being compiled fresh rather than reusing cached plans from prepared statements"}	null	2026-02-23 20:18:31.389665
1319	sqlserver	query	Check for ad-hoc queries dominating plan cache instead of prepared statements	{"sql": "SELECT\\n  objtype AS plan_type,\\n  COUNT(*) AS plan_count,\\n  SUM(usecounts) AS total_uses,\\n  AVG(usecounts) AS avg_uses,\\n  SUM(size_in_bytes) / 1024 / 1024 AS total_size_mb\\nFROM sys.dm_exec_cached_plans\\nGROUP BY objtype\\nORDER BY plan_count DESC"}	{"condition": "Adhoc plan_count >> Prepared plan_count AND Adhoc avg_uses close to 1", "description": "A plan cache dominated by ad-hoc plans with single use counts confirms that prepared statement caching is not being used, as each query generates a unique ad-hoc plan"}	null	2026-02-23 20:18:31.389666
1328	sqlserver	query	Check for worker thread exhaustion waits	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms, max_wait_time_ms,\\n  signal_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'THREADPOOL',\\n  'RESOURCE_SEMAPHORE',\\n  'LOGON_TRIGGER_WAIT'\\n)\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "THREADPOOL waiting_tasks_count > 0 OR max_wait_time_ms > 5000", "description": "THREADPOOL waits mean tasks are queuing because all worker threads are busy. This is the primary indicator that connection demand has exceeded the server's ability to service them."}	null	2026-02-23 20:18:31.389672
1320	sqlserver	query	Check for single-use ad-hoc plans wasting cache space	{"sql": "SELECT\\n  COUNT(*) AS single_use_plans,\\n  SUM(size_in_bytes) / 1024 / 1024 AS wasted_mb,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans) AS total_plans,\\n  COUNT(*) * 100.0 / NULLIF((SELECT COUNT(*) FROM sys.dm_exec_cached_plans), 0) AS single_use_pct,\\n  (SELECT value_in_use FROM sys.configurations WHERE name = 'optimize for ad hoc workloads') AS optimize_adhoc_enabled\\nFROM sys.dm_exec_cached_plans\\nWHERE usecounts = 1 AND objtype = 'Adhoc'"}	{"condition": "single_use_pct > 50 AND optimize_adhoc_enabled = 0", "description": "Over 50% single-use ad-hoc plans with 'optimize for ad hoc workloads' disabled confirms prepared statement caching is not being leveraged and the plan cache is bloated with throwaway plans"}	null	2026-02-23 20:18:31.389667
1321	sqlserver	query	Check for high batch request rate with rapid connection resets	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec'\\n     AND object_name LIKE '%SQL Statistics%') AS batch_requests_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Connection Resets/sec'\\n     AND object_name LIKE '%General Statistics%') AS connection_resets_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec'\\n     AND object_name LIKE '%General Statistics%') AS logins_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'User Connections'\\n     AND object_name LIKE '%General Statistics%') AS user_connections"}	{"condition": "connection_resets_sec > batch_requests_sec * 0.3 AND batch_requests_sec > 100", "description": "High connection reset rate relative to batch requests indicates connections are being acquired and released very frequently, consistent with ORM per-query connection acquisition"}	null	2026-02-23 20:18:31.389667
3437	postgresql	query	Check tablespace accessibility	{"sql": "SELECT spcname, pg_tablespace_location(oid) AS location FROM pg_tablespace WHERE spcname NOT IN ('pg_default', 'pg_global')"}	{"condition": "location_accessible", "description": "All tablespace locations are accessible"}	\N	2026-02-25 00:28:52.405273
3622	postgresql	query	Check for masking-related extensions or views	{"sql": "SELECT extname, extversion FROM pg_extension WHERE extname IN ('anon', 'postgresql_anonymizer', 'pg_masking')"}	{"condition": "row_count = 0", "description": "No data masking extension installed"}	\N	2026-02-25 00:28:52.405273
1322	sqlserver	query	Check for N+1 query patterns — many similar single-row lookups from same program	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  SUBSTRING(st.text, 1, 200) AS query_prefix\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.execution_count > 100\\n  AND qs.total_rows / NULLIF(qs.execution_count, 0) <= 1\\n  AND st.text LIKE '%SELECT%WHERE%'\\nORDER BY qs.execution_count DESC"}	{"condition": "queries with execution_count > 1000 AND avg_rows <= 1", "description": "Highly executed queries returning exactly one row are the hallmark of ORM lazy-loading N+1 patterns, where each related entity is fetched individually"}	null	2026-02-23 20:18:31.389668
3126	sqlserver	query	Check if ForceEncryption is disabled	{"sql": "DECLARE @force_encryption INT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SOFTWARE\\\\Microsoft\\\\Microsoft SQL Server\\\\MSSQLServer\\\\SuperSocketNetLib',\\n  N'ForceEncryption', @force_encryption OUTPUT;\\nSELECT @force_encryption AS force_encryption;"}	{"condition": "force_encryption = 0 or NULL", "description": "ForceEncryption not enabled — server accepts unencrypted connections"}	null	2026-02-23 20:18:31.390771
1323	sqlserver	query	Verify ORM-characteristic program names and query patterns	{"sql": "SELECT\\n  s.program_name,\\n  s.host_name,\\n  COUNT(DISTINCT s.session_id) AS session_count,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests r\\n   WHERE r.session_id = s.session_id) AS active_requests\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND (s.program_name LIKE '%EntityFramework%'\\n    OR s.program_name LIKE '%.Net%'\\n    OR s.program_name LIKE '%Core%'\\n    OR s.program_name LIKE '%Hibernate%'\\n    OR s.program_name LIKE '%nHibernate%')\\nGROUP BY s.program_name, s.host_name, s.session_id\\nORDER BY session_count DESC"}	{"condition": "ORM-related program names with multiple sessions showing frequent connection cycling", "description": "Presence of ORM framework program names with connection churn patterns confirms lazy-loading is driving excessive connection acquisition and release"}	null	2026-02-23 20:18:31.389668
1324	sqlserver	query	Check for elevated login rate with connection resets indicating pool validation failures	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec'\\n     AND object_name LIKE '%General Statistics%') AS logins_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logouts/sec'\\n     AND object_name LIKE '%General Statistics%') AS logouts_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Connection Resets/sec'\\n     AND object_name LIKE '%General Statistics%') AS connection_resets_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Errors/sec' AND instance_name = '_Total'\\n     AND object_name LIKE '%SQL Errors%') AS errors_sec"}	{"condition": "logins_sec significantly > connection_resets_sec AND errors_sec > 0", "description": "When login rate far exceeds connection reset rate, it means connections are being fully closed and recreated rather than pooled (reset). Combined with errors, this indicates validation is detecting broken connections."}	null	2026-02-23 20:18:31.389669
1325	sqlserver	query	Check for recent connection errors and broken pipe indicators	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms, max_wait_time_ms,\\n  signal_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'PREEMPTIVE_OS_AUTHENTICATIONOPS',\\n  'PREEMPTIVE_OS_ACCEPTSECURITYCONTEXT',\\n  'PREEMPTIVE_OS_NETVALIDATEPASSWORDPOLICY',\\n  'PREEMPTIVE_OS_AUTHORIZATIONOPS'\\n)\\n  AND waiting_tasks_count > 0\\nORDER BY waiting_tasks_count DESC"}	{"condition": "multiple authentication wait types with high task counts relative to current session count", "description": "Disproportionately high authentication wait counts compared to active sessions indicate repeated authentication cycles from connections that pass validation failure and get replaced"}	null	2026-02-23 20:18:31.38967
1326	sqlserver	query	Check for short-lived connections concentrated from specific programs	{"sql": "SELECT\\n  s.program_name,\\n  c.client_net_address,\\n  COUNT(*) AS connection_count,\\n  AVG(DATEDIFF(SECOND, c.connect_time, GETDATE())) AS avg_age_sec,\\n  SUM(CASE WHEN DATEDIFF(SECOND, c.connect_time, GETDATE()) < 10 THEN 1 ELSE 0 END) AS very_new_count\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, c.client_net_address\\nHAVING SUM(CASE WHEN DATEDIFF(SECOND, c.connect_time, GETDATE()) < 10 THEN 1 ELSE 0 END) > 3\\nORDER BY very_new_count DESC"}	{"condition": "programs with high very_new_count indicating constant connection recreation", "description": "Programs with many connections younger than 10 seconds confirm continuous connection replacement, consistent with validation queries detecting stale/broken connections and forcing pool to recreate them"}	null	2026-02-23 20:18:31.38967
1327	sqlserver	query	Check current connections vs configured maximum	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS current_user_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections) AS current_connections,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'user connections') AS configured_max_connections,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS configured_max_workers,\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS active_workers,\\n  (SELECT MAX(active_workers_count) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS max_workers_any_scheduler"}	{"condition": "current_user_sessions > configured_max_connections * 0.85 (when configured_max_connections > 0) OR active_workers > configured_max_workers * 0.80", "description": "Current connections exceeding 85% of the configured limit, or active workers exceeding 80% of max worker threads, indicates the server is approaching connection capacity"}	null	2026-02-23 20:18:31.389671
7109	oracle	query	ora_check_transport_lag_trend	{"sql": "SELECT name, value, time_computed FROM v$dataguard_stats WHERE name IN ('transport lag', 'apply lag')"}	{"condition": "transport lag is growing", "description": "Growing transport lag confirms the network cannot keep up with redo generation rate"}	\N	2026-02-28 12:19:19.580455
1329	sqlserver	query	Identify top connection consumers by program and host	{"sql": "SELECT TOP 15\\n  s.program_name,\\n  s.host_name,\\n  s.login_name,\\n  COUNT(*) AS session_count,\\n  SUM(CASE WHEN r.session_id IS NOT NULL THEN 1 ELSE 0 END) AS active_requests,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping_sessions\\nFROM sys.dm_exec_sessions s\\nLEFT JOIN sys.dm_exec_requests r ON s.session_id = r.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name, s.login_name\\nORDER BY session_count DESC"}	{"condition": "single program or host consuming > 30% of total sessions", "description": "A disproportionate share of connections from one application or host confirms that aggregate pool demand from multiple consumers is driving the server toward its connection limit"}	null	2026-02-23 20:18:31.389672
1330	sqlserver	query	Check for THREADPOOL waits indicating worker thread exhaustion	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms, max_wait_time_ms,\\n  signal_wait_time_ms,\\n  CASE\\n    WHEN max_wait_time_ms > 30000 THEN 'CRITICAL - tasks queued > 30s'\\n    WHEN max_wait_time_ms > 10000 THEN 'WARNING - tasks queued > 10s'\\n    ELSE 'MODERATE'\\n  END AS severity\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'THREADPOOL'\\n  AND waiting_tasks_count > 0"}	{"condition": "THREADPOOL max_wait_time_ms > 10000 AND waiting_tasks_count > 10", "description": "Long THREADPOOL waits with multiple queued tasks indicate the server entered a state where it could not service connection requests, triggering retry storms"}	null	2026-02-23 20:18:31.389673
3438	postgresql	log_scan	Scan for network connectivity errors	{"pattern": "could not connect to|connection.*reset by peer|connection.*refused|no route to host|network is unreachable|unexpected EOF|could not receive data", "description": "Network connectivity failure messages in PostgreSQL logs"}	{"condition": "pattern_found", "description": "Network connectivity errors detected"}	\N	2026-02-25 00:28:52.405273
1331	sqlserver	query	Check for burst of recent connections indicating storm pattern	{"sql": "SELECT\\n  DATEPART(MINUTE, c.connect_time) AS connect_minute,\\n  COUNT(*) AS connections_per_minute,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec'\\n     AND object_name LIKE '%General Statistics%') AS current_login_rate,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'User Connections'\\n     AND object_name LIKE '%General Statistics%') AS current_total_connections\\nFROM sys.dm_exec_connections c\\nWHERE c.connect_time > DATEADD(MINUTE, -10, GETDATE())\\nGROUP BY DATEPART(MINUTE, c.connect_time)\\nORDER BY connect_minute DESC"}	{"condition": "connections_per_minute shows a spike > 3x the average across minutes", "description": "A sudden spike in connection creation rate within a short window indicates a connection storm where multiple clients simultaneously retry after experiencing pool exhaustion"}	null	2026-02-23 20:18:31.389673
6449	oracle	query	ora-check-incarnation-history	{"sql": "SELECT incarnation#, resetlogs_change#, resetlogs_time, prior_resetlogs_change#, prior_incarnation#, status FROM v$database_incarnation ORDER BY incarnation# DESC FETCH FIRST 5 ROWS ONLY"}	{"condition": "row_count > 1", "description": "Multiple incarnations confirm the database has been re-initialized, creating a new redo chain"}	\N	2026-02-28 12:19:19.580455
1332	sqlserver	query	Check for login failures indicating rejected connections during storm	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Errors/sec' AND instance_name = 'User Errors'\\n     AND object_name LIKE '%SQL Errors%') AS user_errors_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec'\\n     AND object_name LIKE '%General Statistics%') AS logins_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logouts/sec'\\n     AND object_name LIKE '%General Statistics%') AS logouts_sec,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS current_sessions,\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers\\n   WHERE status = 'VISIBLE ONLINE') AS active_workers"}	{"condition": "user_errors_sec > 0 AND logins_sec > 50 AND active_workers near max worker threads", "description": "User errors combined with high login rate and near-maximum worker utilization confirm a connection storm scenario where failed connections trigger immediate retries, compounding the overload"}	null	2026-02-23 20:18:31.389674
1333	sqlserver	query	Count distinct connection pools by program name and host	{"sql": "SELECT\\n  s.program_name,\\n  s.host_name,\\n  s.login_name,\\n  COUNT(*) AS session_count,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping_count,\\n  SUM(CASE WHEN s.status = 'running' THEN 1 ELSE 0 END) AS running_count\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name, s.login_name\\nORDER BY session_count DESC"}	{"condition": "more than 10 distinct program_name+host_name combinations, each holding 10+ sessions", "description": "Many distinct application identities each maintaining their own connection pool multiplies the total connection footprint on the server"}	null	2026-02-23 20:18:31.389675
1365	sqlserver	query	Check SQL compilations vs re-compilations rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Compilations/sec'\\n   AND object_name LIKE '%SQL Statistics%') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Re-Compilations/sec'\\n   AND object_name LIKE '%SQL Statistics%') AS recompilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec'\\n   AND object_name LIKE '%SQL Statistics%') AS batch_requests_sec"}	{"condition": "compilations_sec > batch_requests_sec * 0.10", "description": "Compilations exceeding 10% of batch requests — plans being evicted and recompiled"}	null	2026-02-23 20:18:31.389675
1334	sqlserver	query	Check total connections vs active utilization	{"sql": "SELECT\\n  COUNT(*) AS total_user_sessions,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping_sessions,\\n  SUM(CASE WHEN s.status = 'running' THEN 1 ELSE 0 END) AS running_sessions,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0) AS sleeping_pct,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'user connections') AS configured_max,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS max_workers\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1"}	{"condition": "sleeping_pct > 80 AND total_user_sessions > 200", "description": "When over 80% of sessions are sleeping and total count is high, it means connection pools are holding many idle connections that collectively consume server resources without doing useful work"}	null	2026-02-23 20:18:31.389676
1335	sqlserver	query	Verify connection pool multiplication pattern from distinct hosts	{"sql": "SELECT\\n  COUNT(DISTINCT c.client_net_address) AS distinct_client_hosts,\\n  COUNT(DISTINCT s.program_name) AS distinct_programs,\\n  COUNT(*) AS total_connections,\\n  COUNT(*) / NULLIF(COUNT(DISTINCT c.client_net_address), 0) AS avg_connections_per_host,\\n  COUNT(*) / NULLIF(COUNT(DISTINCT s.program_name), 0) AS avg_connections_per_program\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1"}	{"condition": "distinct_client_hosts > 10 AND avg_connections_per_host > 15", "description": "Many distinct client hosts each maintaining 15+ connections confirms a microservice architecture where each service instance runs its own pool, and the aggregate far exceeds what the server needs"}	null	2026-02-23 20:18:31.389677
1336	sqlserver	query	Check for discrepancy between configured and running values	{"sql": "SELECT name,\\n  CAST(value AS INT) AS configured_value,\\n  CAST(value_in_use AS INT) AS running_value,\\n  CASE\\n    WHEN CAST(value AS INT) != CAST(value_in_use AS INT) THEN 'RESTART REQUIRED'\\n    ELSE 'IN SYNC'\\n  END AS status\\nFROM sys.configurations\\nWHERE name IN ('max worker threads', 'user connections',\\n  'max degree of parallelism', 'cost threshold for parallelism')\\nORDER BY name"}	{"condition": "any row where configured_value != running_value, especially for 'max worker threads'", "description": "A discrepancy between configured and running values for max worker threads means the change is pending a restart. The server is still running with the old limit."}	null	2026-02-23 20:18:31.389677
1337	sqlserver	query	Check if current worker thread usage is hitting the running limit	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS running_max_workers,\\n  (SELECT CAST(value AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS configured_max_workers,\\n  SUM(active_workers_count) AS total_active_workers,\\n  MAX(active_workers_count) AS max_workers_per_scheduler,\\n  COUNT(*) AS scheduler_count,\\n  SUM(work_queue_count) AS total_queued_tasks\\nFROM sys.dm_os_schedulers\\nWHERE status = 'VISIBLE ONLINE'"}	{"condition": "total_active_workers > running_max_workers * 0.75 AND configured_max_workers > running_max_workers", "description": "Active workers approaching the running (old) limit while the configured (new) limit is higher confirms the pending restart is needed to relieve worker thread pressure"}	null	2026-02-23 20:18:31.389678
1658	sqlserver	query	Check tempdb allocation contention via PAGELATCH waits	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGELATCH_UP', 'PAGELATCH_EX', 'PAGELATCH_SH')\\n  AND waiting_tasks_count > 100\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGELATCH_UP avg_wait_ms > 1 AND waiting_tasks_count > 1000", "description": "Significant PAGELATCH_UP waits indicate tempdb allocation page contention"}	null	2026-02-23 20:18:31.389878
1339	sqlserver	query	Identify admin vs application sessions	{"sql": "SELECT\\n  CASE\\n    WHEN s.program_name LIKE '%Management Studio%' THEN 'SSMS'\\n    WHEN s.program_name LIKE '%SQLAgent%' THEN 'SQL Agent'\\n    WHEN s.program_name LIKE '%DatabaseMail%' THEN 'Database Mail'\\n    WHEN s.program_name LIKE '%Report Server%' THEN 'SSRS'\\n    WHEN s.program_name LIKE '%Monitor%' OR s.program_name LIKE '%SolarWinds%'\\n      OR s.program_name LIKE '%Datadog%' OR s.program_name LIKE '%Zabbix%'\\n      OR s.program_name LIKE '%Nagios%' THEN 'Monitoring'\\n    WHEN s.program_name LIKE '%Backup%' OR s.program_name LIKE '%Veeam%'\\n      OR s.program_name LIKE '%Ola Hallengren%' THEN 'Backup'\\n    WHEN s.login_name LIKE '%sa%' OR IS_SRVROLEMEMBER('sysadmin', s.login_name) = 1\\n      THEN 'Admin Login'\\n    ELSE 'Application'\\n  END AS session_category,\\n  COUNT(*) AS session_count,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping_count\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY\\n  CASE\\n    WHEN s.program_name LIKE '%Management Studio%' THEN 'SSMS'\\n    WHEN s.program_name LIKE '%SQLAgent%' THEN 'SQL Agent'\\n    WHEN s.program_name LIKE '%DatabaseMail%' THEN 'Database Mail'\\n    WHEN s.program_name LIKE '%Report Server%' THEN 'SSRS'\\n    WHEN s.program_name LIKE '%Monitor%' OR s.program_name LIKE '%SolarWinds%'\\n      OR s.program_name LIKE '%Datadog%' OR s.program_name LIKE '%Zabbix%'\\n      OR s.program_name LIKE '%Nagios%' THEN 'Monitoring'\\n    WHEN s.program_name LIKE '%Backup%' OR s.program_name LIKE '%Veeam%'\\n      OR s.program_name LIKE '%Ola Hallengren%' THEN 'Backup'\\n    WHEN s.login_name LIKE '%sa%' OR IS_SRVROLEMEMBER('sysadmin', s.login_name) = 1\\n      THEN 'Admin Login'\\n    ELSE 'Application'\\n  END\\nORDER BY session_count DESC"}	{"condition": "non-Application categories collectively > 20% of total sessions", "description": "When admin, monitoring, backup, and management tool sessions consume more than 20% of total connections, they are significantly reducing available capacity for application workloads"}	null	2026-02-23 20:18:31.389678
1340	sqlserver	query	Check for idle SSMS connections holding resources	{"sql": "SELECT\\n  s.session_id,\\n  s.program_name,\\n  s.login_name,\\n  s.host_name,\\n  s.status,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  s.open_transaction_count\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30\\n  AND (s.program_name LIKE '%Management Studio%'\\n    OR s.program_name LIKE '%Monitor%'\\n    OR s.program_name LIKE '%SQLAgent%'\\n    OR IS_SRVROLEMEMBER('sysadmin', s.login_name) = 1)\\nORDER BY idle_minutes DESC"}	{"condition": "admin sessions idle > 60 minutes, especially with open transactions", "description": "Admin sessions idle for over an hour, particularly those with open transactions from SSMS, consume connection slots and potentially hold locks while providing no useful work"}	null	2026-02-23 20:18:31.389679
1341	sqlserver	query	Verify admin connections are impacting total capacity	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS total_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions\\n   WHERE is_user_process = 1\\n     AND (program_name LIKE '%Management Studio%'\\n       OR program_name LIKE '%SQLAgent%'\\n       OR program_name LIKE '%Monitor%'\\n       OR program_name LIKE '%SolarWinds%'\\n       OR program_name LIKE '%Datadog%')) AS admin_tool_sessions,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS max_workers,\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS active_workers,\\n  (SELECT waiting_tasks_count FROM sys.dm_os_wait_stats WHERE wait_type = 'THREADPOOL') AS threadpool_waits"}	{"condition": "admin_tool_sessions > total_sessions * 0.15 AND (active_workers > max_workers * 0.7 OR threadpool_waits > 0)", "description": "Admin tools consuming 15%+ of sessions while the server is at 70%+ worker capacity (or already experiencing THREADPOOL waits) confirms that administrative connections are materially reducing application connection availability"}	null	2026-02-23 20:18:31.38968
1386	sqlserver	query	Check memory grant waits and queued requests	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('RESOURCE_SEMAPHORE', 'RESOURCE_SEMAPHORE_QUERY_COMPILE')\\n  AND waiting_tasks_count > 0"}	{"condition": "RESOURCE_SEMAPHORE waits present", "description": "Queries waiting for memory grants — memory pressure from parallel execution"}	null	2026-02-23 20:18:31.38968
1342	sqlserver	query	Identify replication agent sessions	{"sql": "SELECT\\n  s.session_id,\\n  s.program_name,\\n  s.login_name,\\n  s.host_name,\\n  s.status,\\n  DATEDIFF(MINUTE, c.connect_time, GETDATE()) AS connection_age_minutes,\\n  s.last_request_end_time\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND (s.program_name LIKE '%Repl%'\\n    OR s.program_name LIKE '%LogReader%'\\n    OR s.program_name LIKE '%Distribution%'\\n    OR s.program_name LIKE '%Merge Agent%'\\n    OR s.program_name LIKE '%SQLREPL%'\\n    OR s.program_name LIKE '%Snapshot%')\\nORDER BY connection_age_minutes DESC"}	{"condition": "replication agent sessions found with long-lived connections", "description": "Replication agents (Log Reader, Distribution, Merge, Snapshot) maintain persistent connections that do not pool or time out — they run continuously as long as replication is active"}	null	2026-02-23 20:18:31.389681
3079	sqlserver	query	Check error log size and cycling frequency for verbose logging impact	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_os_enumerate_fixed_drives) AS drive_count,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Errors/sec' AND instance_name = '_Total') AS errors_per_sec,\\n  (SELECT value_in_use FROM sys.configurations WHERE name = 'number of errorlog files') AS errorlog_file_count,\\n  (SELECT sqlserver_start_time FROM sys.dm_os_sys_info) AS last_restart,\\n  DATEDIFF(DAY, (SELECT sqlserver_start_time FROM sys.dm_os_sys_info), GETDATE()) AS uptime_days"}	{"condition": "verbose logging flags active with potentially excessive errorlog growth", "description": "Verbose trace flags combined with long uptime suggest errorlog may be growing excessively — filling disk or making log analysis difficult"}	null	2026-02-23 20:18:31.390773
1372	sqlserver	query	Check CXPACKET waits as overhead indicator	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT')\\nORDER BY wait_time_ms DESC"}	{"condition": "CXPACKET or CXCONSUMER waits are among top waits", "description": "High parallelism-related waits confirm unnecessary parallel execution overhead"}	null	2026-02-23 20:18:31.389701
1343	sqlserver	query	Count total replication connections vs total user connections	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions\\n   WHERE is_user_process = 1\\n     AND (program_name LIKE '%Repl%' OR program_name LIKE '%LogReader%'\\n       OR program_name LIKE '%Distribution%' OR program_name LIKE '%Merge Agent%'\\n       OR program_name LIKE '%SQLREPL%' OR program_name LIKE '%Snapshot%')) AS replication_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS total_user_sessions,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'user connections') AS max_connections,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS max_workers"}	{"condition": "replication_sessions > 5 AND replication_sessions > total_user_sessions * 0.10", "description": "Replication agents consuming more than 10% of total user sessions indicates a significant overhead, especially on servers with many published databases or publications"}	null	2026-02-23 20:18:31.389681
7097	oracle	query	ora_check_transport_lag	{"sql": "SELECT name, value, time_computed, datum_time FROM v$dataguard_stats WHERE name = 'transport lag'"}	{"condition": "transport lag value is non-zero", "description": "Non-zero transport lag indicates redo is not being shipped to standby in a timely manner"}	\N	2026-02-28 12:19:19.580455
1344	sqlserver	query	Check if replication overhead contributes to capacity pressure	{"sql": "SELECT\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS active_workers,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS max_workers,\\n  (SELECT waiting_tasks_count FROM sys.dm_os_wait_stats WHERE wait_type = 'THREADPOOL') AS threadpool_waits,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions\\n   WHERE is_user_process = 1\\n     AND (program_name LIKE '%Repl%' OR program_name LIKE '%LogReader%'\\n       OR program_name LIKE '%Distribution%' OR program_name LIKE '%SQLREPL%')) AS repl_count"}	{"condition": "active_workers > max_workers * 0.7 AND repl_count > 5", "description": "Worker threads at 70%+ capacity with multiple replication connections confirms that replication overhead is contributing to connection exhaustion on this server"}	null	2026-02-23 20:18:31.389682
6450	oracle	query	ora-check-archiver-stuck-status	{"sql": "SELECT log_mode, DECODE(log_mode, 'ARCHIVELOG', 'YES', 'NO') AS archiving_enabled FROM v$database"}	{"condition": "log_mode = 'ARCHIVELOG'", "description": "Database must be in ARCHIVELOG mode; if NOARCHIVELOG, redo logs are always overwritten without archival"}	\N	2026-02-28 12:19:19.580455
1919	sqlserver	query	Check for active sessions using SERIALIZABLE isolation	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.transaction_isolation_level,\\n  CASE s.transaction_isolation_level\\n    WHEN 0 THEN 'Unspecified'\\n    WHEN 1 THEN 'ReadUncommitted'\\n    WHEN 2 THEN 'ReadCommitted'\\n    WHEN 3 THEN 'RepeatableRead'\\n    WHEN 4 THEN 'Serializable'\\n    WHEN 5 THEN 'Snapshot'\\n  END AS isolation_name,\\n  r.wait_type, r.blocking_session_id\\nFROM sys.dm_exec_sessions s\\nLEFT JOIN sys.dm_exec_requests r ON s.session_id = r.session_id\\nWHERE s.transaction_isolation_level = 4\\n  AND s.is_user_process = 1"}	{"condition": "row_count > 0", "description": "Sessions running under SERIALIZABLE isolation — range locks acquired"}	null	2026-02-23 20:18:31.38998
1345	sqlserver	query	Find long-idle sessions that have not sent a request recently	{"sql": "SELECT\\n  s.session_id,\\n  s.program_name,\\n  s.host_name,\\n  s.login_name,\\n  s.login_time,\\n  s.last_request_end_time,\\n  DATEDIFF(HOUR, s.last_request_end_time, GETDATE()) AS idle_hours,\\n  s.status,\\n  s.open_transaction_count,\\n  c.client_net_address\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(HOUR, s.last_request_end_time, GETDATE()) > 4\\nORDER BY idle_hours DESC"}	{"condition": "sessions idle for > 8 hours from application program names", "description": "Application connections that have been idle for many hours likely belong to previous instance deployments that did not clean up their connection pools"}	null	2026-02-23 20:18:31.389683
1346	sqlserver	query	Check for duplicate host/program combos suggesting old and new instances	{"sql": "SELECT\\n  s.program_name,\\n  s.host_name,\\n  COUNT(*) AS total_sessions,\\n  MIN(c.connect_time) AS oldest_connection,\\n  MAX(c.connect_time) AS newest_connection,\\n  DATEDIFF(HOUR, MIN(c.connect_time), MAX(c.connect_time)) AS connection_age_span_hours,\\n  SUM(CASE WHEN DATEDIFF(HOUR, s.last_request_end_time, GETDATE()) > 4 THEN 1 ELSE 0 END) AS stale_sessions\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 5\\n  AND DATEDIFF(HOUR, MIN(c.connect_time), MAX(c.connect_time)) > 4\\nORDER BY stale_sessions DESC"}	{"condition": "programs with stale_sessions > 0 AND connection_age_span_hours > 8", "description": "A wide spread between oldest and newest connection times with stale sessions indicates multiple deployment generations coexisting — old connections were never cleaned up"}	null	2026-02-23 20:18:31.389684
1347	sqlserver	query	Verify orphaned connections are impacting capacity	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions\\n   WHERE is_user_process = 1\\n     AND status = 'sleeping'\\n     AND DATEDIFF(HOUR, last_request_end_time, GETDATE()) > 4) AS orphaned_estimate,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS total_user_sessions,\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS active_workers,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS max_workers"}	{"condition": "orphaned_estimate > total_user_sessions * 0.15", "description": "When estimated orphaned connections exceed 15% of total sessions, they are materially reducing available connection capacity and should be cleaned up"}	null	2026-02-23 20:18:31.389684
1348	sqlserver	query	Identify non-production databases and their connection counts	{"sql": "SELECT\\n  DB_NAME(s.database_id) AS database_name,\\n  COUNT(*) AS session_count,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping_count,\\n  SUM(CASE WHEN s.status = 'running' THEN 1 ELSE 0 END) AS running_count,\\n  CASE\\n    WHEN DB_NAME(s.database_id) LIKE '%test%' OR DB_NAME(s.database_id) LIKE '%dev%'\\n      OR DB_NAME(s.database_id) LIKE '%staging%' OR DB_NAME(s.database_id) LIKE '%qa%'\\n      OR DB_NAME(s.database_id) LIKE '%sandbox%' OR DB_NAME(s.database_id) LIKE '%uat%'\\n    THEN 'NON-PRODUCTION'\\n    ELSE 'PRODUCTION'\\n  END AS env_classification\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.database_id > 0\\nGROUP BY DB_NAME(s.database_id),\\n  CASE\\n    WHEN DB_NAME(s.database_id) LIKE '%test%' OR DB_NAME(s.database_id) LIKE '%dev%'\\n      OR DB_NAME(s.database_id) LIKE '%staging%' OR DB_NAME(s.database_id) LIKE '%qa%'\\n      OR DB_NAME(s.database_id) LIKE '%sandbox%' OR DB_NAME(s.database_id) LIKE '%uat%'\\n    THEN 'NON-PRODUCTION'\\n    ELSE 'PRODUCTION'\\n  END\\nORDER BY session_count DESC"}	{"condition": "NON-PRODUCTION databases present with session_count > 10", "description": "Presence of test/dev/staging/QA databases with active sessions on the same server indicates shared infrastructure consuming production connection capacity"}	null	2026-02-23 20:18:31.389685
1349	sqlserver	query	Check non-production program names connecting to production server	{"sql": "SELECT\\n  s.program_name,\\n  s.host_name,\\n  DB_NAME(s.database_id) AS database_name,\\n  COUNT(*) AS session_count\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND (s.program_name LIKE '%test%'\\n    OR s.program_name LIKE '%dev%'\\n    OR s.program_name LIKE '%staging%'\\n    OR s.program_name LIKE '%debug%'\\n    OR s.host_name LIKE '%dev%'\\n    OR s.host_name LIKE '%test%'\\n    OR s.host_name LIKE '%staging%')\\nGROUP BY s.program_name, s.host_name, DB_NAME(s.database_id)\\nORDER BY session_count DESC"}	{"condition": "test/dev/staging programs or hosts found with active connections", "description": "Non-production application names or host names connecting to this server confirm that development or testing workloads are sharing production database resources"}	null	2026-02-23 20:18:31.389686
2744	sqlserver	query	Verify no audit specifications are capturing events	{"sql": "SELECT sa.name AS audit_name, sa.is_state_enabled AS audit_enabled,\\n  sas.name AS server_spec_name, sas.is_state_enabled AS spec_enabled\\nFROM sys.server_audits sa\\nLEFT JOIN sys.server_audit_specifications sas\\n  ON sa.audit_guid = sas.audit_guid\\nUNION ALL\\nSELECT sa.name, sa.is_state_enabled,\\n  das.name AS db_spec_name, das.is_state_enabled\\nFROM sys.server_audits sa\\nLEFT JOIN sys.database_audit_specifications das\\n  ON sa.audit_guid = das.audit_guid"}	{"condition": "no enabled audit with enabled specifications", "description": "Confirms no active audit specifications — nothing is being logged"}	null	2026-02-23 20:18:31.389696
1350	sqlserver	query	Quantify non-production impact on total capacity	{"sql": "SELECT\\n  SUM(CASE\\n    WHEN DB_NAME(s.database_id) LIKE '%test%' OR DB_NAME(s.database_id) LIKE '%dev%'\\n      OR DB_NAME(s.database_id) LIKE '%staging%' OR DB_NAME(s.database_id) LIKE '%qa%'\\n      OR s.program_name LIKE '%test%' OR s.program_name LIKE '%dev%'\\n      OR s.host_name LIKE '%dev%' OR s.host_name LIKE '%test%'\\n    THEN 1 ELSE 0\\n  END) AS non_prod_sessions,\\n  COUNT(*) AS total_sessions,\\n  SUM(CASE\\n    WHEN DB_NAME(s.database_id) LIKE '%test%' OR DB_NAME(s.database_id) LIKE '%dev%'\\n      OR DB_NAME(s.database_id) LIKE '%staging%' OR DB_NAME(s.database_id) LIKE '%qa%'\\n      OR s.program_name LIKE '%test%' OR s.program_name LIKE '%dev%'\\n      OR s.host_name LIKE '%dev%' OR s.host_name LIKE '%test%'\\n    THEN 1 ELSE 0\\n  END) * 100.0 / NULLIF(COUNT(*), 0) AS non_prod_pct\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1"}	{"condition": "non_prod_pct > 10", "description": "Non-production workloads consuming more than 10% of total connections on this server confirms that shared infrastructure is reducing available production capacity"}	null	2026-02-23 20:18:31.389686
1351	sqlserver	query	Find long-running sessions with active requests	{"sql": "SELECT\\n  s.session_id,\\n  s.program_name,\\n  s.host_name,\\n  s.login_name,\\n  s.status,\\n  r.command,\\n  r.wait_type,\\n  r.wait_time / 1000 AS wait_seconds,\\n  DATEDIFF(MINUTE, r.start_time, GETDATE()) AS running_minutes,\\n  r.blocking_session_id,\\n  s.open_transaction_count\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_requests r ON s.session_id = r.session_id\\nWHERE s.is_user_process = 1\\n  AND DATEDIFF(MINUTE, r.start_time, GETDATE()) > 60\\nORDER BY running_minutes DESC"}	{"condition": "sessions with running_minutes > 120 or wait_seconds > 3600", "description": "Sessions running or waiting for over 2 hours are likely batch/ETL processes that may be hung or running far longer than expected, holding connections hostage"}	null	2026-02-23 20:18:31.389687
1352	sqlserver	query	Identify batch/ETL program names and their connection holding patterns	{"sql": "SELECT\\n  s.program_name,\\n  s.host_name,\\n  COUNT(*) AS session_count,\\n  SUM(CASE WHEN s.open_transaction_count > 0 THEN 1 ELSE 0 END) AS open_txn_sessions,\\n  MAX(DATEDIFF(MINUTE, c.connect_time, GETDATE())) AS max_connection_age_min,\\n  AVG(DATEDIFF(MINUTE, c.connect_time, GETDATE())) AS avg_connection_age_min\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND (s.program_name LIKE '%SSIS%'\\n    OR s.program_name LIKE '%ETL%'\\n    OR s.program_name LIKE '%bcp%'\\n    OR s.program_name LIKE '%BULK%'\\n    OR s.program_name LIKE '%Import%'\\n    OR s.program_name LIKE '%DTS%'\\n    OR s.program_name LIKE '%SQLAgent%'\\n    OR DATEDIFF(MINUTE, c.connect_time, GETDATE()) > 240)\\nGROUP BY s.program_name, s.host_name\\nORDER BY max_connection_age_min DESC"}	{"condition": "batch/ETL programs with max_connection_age_min > 240 or open_txn_sessions > 0", "description": "ETL or batch programs maintaining connections for over 4 hours, especially with open transactions, indicate processes that may be hung or are holding connections unnecessarily long"}	null	2026-02-23 20:18:31.389688
1353	sqlserver	query	Verify hung connections are contributing to capacity pressure	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions\\n   WHERE is_user_process = 1\\n     AND status = 'sleeping'\\n     AND open_transaction_count > 0\\n     AND DATEDIFF(MINUTE, last_request_end_time, GETDATE()) > 30) AS hung_with_open_txn,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s\\n   JOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\n   WHERE s.is_user_process = 1\\n     AND DATEDIFF(HOUR, c.connect_time, GETDATE()) > 4) AS long_lived_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS total_sessions,\\n  (SELECT waiting_tasks_count FROM sys.dm_os_wait_stats WHERE wait_type = 'THREADPOOL') AS threadpool_waits"}	{"condition": "hung_with_open_txn > 0 OR (long_lived_sessions > total_sessions * 0.20 AND threadpool_waits > 0)", "description": "Sleeping sessions with open transactions or long-lived sessions consuming over 20% of capacity while THREADPOOL waits exist confirms that hung batch processes are contributing to connection exhaustion"}	null	2026-02-23 20:18:31.389688
1354	sqlserver	query	Check for disproportionate connection count from individual hosts	{"sql": "SELECT\\n  c.client_net_address,\\n  s.program_name,\\n  COUNT(*) AS connection_count,\\n  COUNT(DISTINCT c.auth_scheme) AS auth_schemes,\\n  COUNT(DISTINCT s.database_id) AS databases_used,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY c.client_net_address, s.program_name\\nHAVING COUNT(*) > 50\\nORDER BY connection_count DESC"}	{"condition": "single client_net_address + program_name with > 100 connections", "description": "A single application from one host maintaining over 100 connections suggests multiple independent pools are being created instead of sharing a single pool"}	null	2026-02-23 20:18:31.389689
1355	sqlserver	query	Check for varying connection properties suggesting separate pools	{"sql": "SELECT\\n  c.client_net_address,\\n  s.program_name,\\n  c.encrypt_option,\\n  c.auth_scheme,\\n  DB_NAME(s.database_id) AS database_name,\\n  s.login_name,\\n  COUNT(*) AS connection_count\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND c.client_net_address IN (\\n    SELECT TOP 5 c2.client_net_address\\n    FROM sys.dm_exec_connections c2\\n    JOIN sys.dm_exec_sessions s2 ON c2.session_id = s2.session_id\\n    WHERE s2.is_user_process = 1\\n    GROUP BY c2.client_net_address\\n    HAVING COUNT(*) > 50\\n    ORDER BY COUNT(*) DESC\\n  )\\nGROUP BY c.client_net_address, s.program_name, c.encrypt_option,\\n  c.auth_scheme, DB_NAME(s.database_id), s.login_name\\nORDER BY c.client_net_address, connection_count DESC"}	{"condition": "same client_net_address with multiple distinct groupings suggesting separate pool keys", "description": "Multiple connection property combinations from the same host indicate the driver is creating separate pools for each combination of database, login, encryption, and other connection string properties"}	null	2026-02-23 20:18:31.38969
1356	sqlserver	query	Verify excessive per-host connections are impacting server capacity	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS total_sessions,\\n  (SELECT MAX(cnt) FROM (\\n    SELECT COUNT(*) AS cnt\\n    FROM sys.dm_exec_connections c\\n    JOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\n    WHERE s.is_user_process = 1\\n    GROUP BY c.client_net_address, s.program_name\\n  ) sub) AS max_sessions_single_source,\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS active_workers,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS max_workers"}	{"condition": "max_sessions_single_source > total_sessions * 0.25", "description": "A single application source consuming over 25% of all server sessions confirms that per-thread pool creation is generating an outsized connection footprint from one client"}	null	2026-02-23 20:18:31.38969
1357	sqlserver	query	Check user connections configuration and Resource Governor status	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'user connections') AS max_user_connections,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS max_worker_threads,\\n  (SELECT is_enabled FROM sys.resource_governor_configuration) AS resource_governor_enabled,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS current_user_sessions,\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS active_workers"}	{"condition": "max_user_connections = 0 AND (resource_governor_enabled = 0 OR resource_governor_enabled IS NULL)", "description": "User connections set to 0 (unlimited) with Resource Governor disabled means there is no mechanism to prevent connection count from growing until server resources are exhausted"}	null	2026-02-23 20:18:31.389692
3439	postgresql	query	Check replication connection status	{"sql": "SELECT pid, usesysid, usename, application_name, client_addr, state, sent_lsn, write_lsn, flush_lsn, replay_lsn, sync_state FROM pg_stat_replication"}	{"condition": "row_count = 0 OR state != 'streaming'", "description": "No active replication or replication not in streaming state"}	\N	2026-02-25 00:28:52.405273
1358	sqlserver	query	Check if connection growth is approaching resource limits	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS user_sessions,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads') AS max_workers,\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS active_workers,\\n  (SELECT SUM(active_workers_count) * 100.0 / NULLIF((SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max worker threads'), 0)\\n   FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS worker_utilization_pct,\\n  (SELECT physical_memory_in_use_kb / 1024 FROM sys.dm_os_process_memory) AS memory_used_mb,\\n  (SELECT total_physical_memory_kb / 1024 FROM sys.dm_os_sys_memory) AS total_memory_mb"}	{"condition": "worker_utilization_pct > 60 AND user_sessions > 200", "description": "High worker utilization with many active sessions and no connection limit means the server is on a trajectory toward resource exhaustion as connections continue to accumulate"}	null	2026-02-23 20:18:31.389692
1562	sqlserver	query	Check PAGEIOLATCH patterns for random I/O signature	{"sql": "SELECT\\n  wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'PAGEIOLATCH_UP')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH_SH dominant with high avg_wait_ms", "description": "PAGEIOLATCH_SH waits from random data page reads — each key lookup fetches a different data page"}	null	2026-02-23 20:18:31.389693
1360	sqlserver	query	Check OS and SQL Server memory pressure indicators	{"sql": "SELECT\\n  m.total_physical_memory_kb / 1024 AS total_memory_mb,\\n  m.available_physical_memory_kb / 1024 AS available_memory_mb,\\n  m.system_low_memory_signal_state,\\n  m.system_high_memory_signal_state,\\n  p.physical_memory_in_use_kb / 1024 AS sql_memory_used_mb,\\n  p.locked_page_allocations_kb / 1024 AS locked_pages_mb,\\n  p.memory_utilization_percentage,\\n  p.process_physical_memory_low,\\n  p.process_virtual_memory_low\\nFROM sys.dm_os_sys_memory m\\nCROSS JOIN sys.dm_os_process_memory p"}	{"condition": "process_physical_memory_low = 1 OR system_low_memory_signal_state != 'Clear' OR memory_utilization_percentage > 95", "description": "Low memory signals or near-100% utilization indicate the server is under severe memory pressure that would prevent allocating memory for new connection structures"}	null	2026-02-23 20:18:31.389694
1361	sqlserver	query	Check for memory-related wait types and stolen pages pressure	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms, max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'RESOURCE_SEMAPHORE',\\n  'CMEMTHREAD',\\n  'SOS_RESERVEDMEMBLOCKLIST',\\n  'RESOURCE_SEMAPHORE_QUERY_COMPILE',\\n  'THREADPOOL'\\n)\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "RESOURCE_SEMAPHORE waiting_tasks_count > 10 OR CMEMTHREAD waits > 0", "description": "RESOURCE_SEMAPHORE waits mean queries cannot get memory grants, and CMEMTHREAD indicates contention on memory objects — both signal the server is unable to allocate memory for new connection processing"}	null	2026-02-23 20:18:31.389695
1956	sqlserver	query	Find foreign keys without supporting indexes on the child table	{"sql": "SELECT SCHEMA_NAME(fk.schema_id) AS fk_schema, fk.name AS fk_name, OBJECT_NAME(fk.parent_object_id) AS child_table, COL_NAME(fkc.parent_object_id, fkc.parent_column_id) AS child_column, OBJECT_NAME(fk.referenced_object_id) AS parent_table, COL_NAME(fkc.referenced_object_id, fkc.referenced_column_id) AS parent_column FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fkc ON fk.object_id = fkc.constraint_object_id WHERE NOT EXISTS (SELECT 1 FROM sys.index_columns ic JOIN sys.indexes i ON ic.object_id = i.object_id AND ic.index_id = i.index_id WHERE ic.object_id = fk.parent_object_id AND ic.column_id = fkc.parent_column_id AND ic.key_ordinal = fkc.constraint_column_id AND i.type > 0) ORDER BY child_table, fk.name"}	{"condition": "row_count > 0", "description": "Foreign key columns on child tables have no supporting index — constraint checks will cause table scans"}	null	2026-02-23 20:18:31.390074
1362	sqlserver	query	Check buffer pool and stolen page pressure from connection overhead	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page life expectancy'\\n     AND object_name LIKE '%Buffer Manager%') AS page_life_expectancy_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Stolen pages'\\n     AND object_name LIKE '%Buffer Manager%') AS stolen_pages,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Target pages'\\n     AND object_name LIKE '%Buffer Manager%') AS target_pages,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS user_sessions,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Errors/sec' AND instance_name = 'User Errors'\\n     AND object_name LIKE '%SQL Errors%') AS user_errors_sec"}	{"condition": "page_life_expectancy_sec < 300 AND stolen_pages > target_pages * 0.3 AND user_sessions > 100", "description": "Low page life expectancy with high stolen page ratio confirms that connection-related memory structures (each session's ~1.5 MB) are competing with buffer pool for limited memory, preventing new connections from being serviced"}	null	2026-02-23 20:18:31.389695
2745	sqlserver	query	Check for audits without specifications	{"sql": "SELECT sa.name AS audit_name, sa.is_state_enabled,\\n  sa.type_desc AS destination,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   WHERE sas.audit_guid = sa.audit_guid\\n     AND sas.is_state_enabled = 1) AS active_server_specs,\\n  (SELECT COUNT(*) FROM sys.database_audit_specifications das\\n   WHERE das.audit_guid = sa.audit_guid\\n     AND das.is_state_enabled = 1) AS active_db_specs\\nFROM sys.server_audits sa\\nWHERE sa.is_state_enabled = 1"}	{"condition": "active_server_specs = 0 AND active_db_specs = 0", "description": "Audit is running but no specifications capture events — effectively silent"}	null	2026-02-23 20:18:31.389696
2746	sqlserver	query	Confirm no C2 audit trace or login auditing as fallback	{"sql": "SELECT name, CAST(value_in_use AS INT) AS value\\nFROM sys.configurations\\nWHERE name IN ('c2 audit mode', 'common criteria compliance enabled')\\nUNION ALL\\nSELECT 'login_auditing' AS name,\\n  CAST(SERVERPROPERTY('IsIntegratedSecurityOnly') AS INT) AS value"}	{"condition": "c2 audit mode = 0 AND common criteria = 0", "description": "No fallback audit mechanisms active — audit specifications required"}	null	2026-02-23 20:18:31.389697
1765	sqlserver	query	Find indexes with high page splits relative to updates	{"sql": "SELECT OBJECT_NAME(os.object_id) AS table_name, i.name AS index_name, i.type_desc, os.leaf_update_count, os.leaf_allocation_count AS page_splits, os.leaf_insert_count, os.leaf_delete_count, CASE WHEN os.leaf_update_count > 0 THEN CAST(os.leaf_allocation_count AS FLOAT) / os.leaf_update_count * 100 ELSE 0 END AS splits_per_update_pct FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os JOIN sys.indexes i ON os.object_id = i.object_id AND os.index_id = i.index_id WHERE i.type > 0 AND os.leaf_update_count > :min_updates AND os.leaf_allocation_count > :min_splits ORDER BY splits_per_update_pct DESC"}	{"condition": "splits_per_update_pct > :split_threshold_pct", "description": "High page split rate relative to updates — updates causing row expansion beyond page capacity"}	{"min_splits": 500, "min_updates": 5000, "split_threshold_pct": 5}	2026-02-23 20:18:31.389946
1366	sqlserver	query	Find queries where compilation dominates execution	{"sql": "SELECT TOP 50\\n  qs.plan_generation_num,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_exec_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.execution_count,\\n  qs.creation_time,\\n  qs.last_execution_time,\\n  qp.query_plan.value('(//StmtSimple/@StatementOptmEarlyAbortReason)[1]', 'nvarchar(50)') AS early_abort,\\n  qp.query_plan.value('(//StmtSimple/@StatementOptmLevel)[1]', 'nvarchar(50)') AS optim_level,\\n  CAST(qp.query_plan.value('(//StmtSimple/@CompileTime)[1]', 'int') AS int) AS compile_time_ms,\\n  CAST(qp.query_plan.value('(//StmtSimple/@CompileCPU)[1]', 'int') AS int) AS compile_cpu_ms,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.plan_generation_num > 1\\nORDER BY qs.plan_generation_num DESC"}	{"condition": "compile_cpu_ms > avg_exec_cpu_us / 1000 or plan_generation_num > 5", "description": "Queries where compile time exceeds execution time or frequent recompilations"}	null	2026-02-23 20:18:31.389698
1367	sqlserver	query	Check total compilation CPU overhead	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Compilations/sec'\\n   AND object_name LIKE '%SQL Statistics%') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Re-Compilations/sec'\\n   AND object_name LIKE '%SQL Statistics%') AS recompilations_sec,\\n  (SELECT SUM(signal_wait_time_ms) * 100.0 / NULLIF(SUM(wait_time_ms), 0)\\n   FROM sys.dm_os_wait_stats) AS signal_wait_pct,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans WHERE usecounts = 1) AS single_use_plans,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans) AS total_plans"}	{"condition": "single_use_plans > total_plans * 0.50 and recompilations_sec is elevated", "description": "Majority single-use plans with high recompilation rate — compile overhead dominates"}	null	2026-02-23 20:18:31.389698
1370	sqlserver	query	Check cost threshold for parallelism setting	{"sql": "SELECT name, CAST(value_in_use AS int) AS value_in_use,\\n  CAST(value AS int) AS configured_value\\nFROM sys.configurations\\nWHERE name = 'cost threshold for parallelism'"}	{"condition": "value_in_use <= 5", "description": "Cost threshold at default (5) or lower — too many small queries qualify for parallelism"}	null	2026-02-23 20:18:31.3897
1371	sqlserver	query	Find small queries running with parallel plans	{"sql": "SELECT TOP 30\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qp.query_plan.value('(//RelOp/@Parallel)[1]', 'bit') AS is_parallel,\\n  qp.query_plan.value('(//StmtSimple/@StatementSubTreeCost)[1]', 'float') AS estimated_cost,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@Parallel=\\"true\\"]') = 1\\n  AND qs.total_rows / NULLIF(qs.execution_count, 0) < 100\\n  AND qs.execution_count > 100\\nORDER BY qs.execution_count DESC"}	{"condition": "parallel plans found for queries returning < 100 rows with high execution count", "description": "Small queries going parallel — overhead exceeds benefit for these query sizes"}	null	2026-02-23 20:18:31.389701
1387	sqlserver	query	Check current memory grant queue and parallel query memory usage	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NULL) AS waiting_for_grant,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NOT NULL) AS granted,\\n  (SELECT SUM(granted_memory_kb) / 1024 FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NOT NULL) AS total_granted_mb,\\n  (SELECT SUM(required_memory_kb) / 1024 FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NULL) AS waiting_required_mb,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE dop > 1) AS parallel_grants"}	{"condition": "waiting_for_grant > 0 and parallel_grants > granted * 0.5", "description": "Queries queued for memory with majority of grants going to parallel queries"}	null	2026-02-23 20:18:31.389703
1394	sqlserver	query	Find parallel scans on partitioned tables without elimination	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ix.object_id) AS table_name,\\n  ix.name AS index_name,\\n  ps.partition_number, ps.row_count, ps.used_page_count,\\n  os.leaf_allocation_count, os.range_scan_count,\\n  os.singleton_lookup_count\\nFROM sys.dm_db_partition_stats ps\\nJOIN sys.indexes ix ON ps.object_id = ix.object_id AND ps.index_id = ix.index_id\\nLEFT JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os\\n  ON ps.object_id = os.object_id AND ps.index_id = os.index_id\\n  AND ps.partition_number = os.partition_number\\nWHERE ps.row_count > 0\\n  AND EXISTS (SELECT 1 FROM sys.partition_schemes psc\\n    JOIN sys.indexes ix2 ON psc.data_space_id = ix2.data_space_id\\n    WHERE ix2.object_id = ix.object_id)\\nORDER BY os.range_scan_count DESC"}	{"condition": "multiple partitions with high range_scan_count on same table", "description": "All partitions being scanned — no partition elimination happening"}	null	2026-02-23 20:18:31.389711
1392	sqlserver	query	Find queries with sort spills to tempdb	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_spills, qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_grant_kb,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_spills > 0\\n  AND qp.query_plan.exist('//RelOp[@Parallel=\\"true\\"]') = 1\\nORDER BY qs.total_spills DESC"}	{"condition": "parallel queries with total_spills > 0 and avg_used_grant_kb close to avg_grant_kb", "description": "Parallel queries spilling sorts to tempdb — memory grant insufficient for parallel work"}	null	2026-02-23 20:18:31.389703
2873	sqlserver	query	Check if VIEW DEFINITION or sensitive metadata is exposed to rootcause	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  CASE dp.class_desc\\n    WHEN 'DATABASE' THEN DB_NAME()\\n    WHEN 'SCHEMA' THEN SCHEMA_NAME(dp.major_id)\\n    ELSE OBJECT_NAME(dp.major_id) END AS scope,\\n  dp.state_desc\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.permission_name IN ('VIEW DEFINITION', 'VIEW ANY DEFINITION', 'VIEW DATABASE STATE',\\n    'VIEW SERVER STATE', 'ALTER', 'CONTROL')\\n  AND dp.class_desc IN ('DATABASE', 'SCHEMA', 'OBJECT_OR_COLUMN')"}	{"condition": "VIEW DEFINITION or VIEW DATABASE STATE granted to PUBLIC", "description": "PUBLIC has metadata visibility permissions that expose database structure to all users"}	null	2026-02-23 20:18:31.390638
1374	sqlserver	query	Find parallel queries with skewed row distribution	{"sql": "SELECT TOP 20\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  CASE WHEN (qs.total_worker_time / NULLIF(qs.execution_count, 0)) > 0\\n    THEN CAST((qs.total_elapsed_time / NULLIF(qs.execution_count, 0)) AS float) /\\n         (qs.total_worker_time / NULLIF(qs.execution_count, 0))\\n    ELSE 0 END AS elapsed_to_cpu_ratio,\\n  qs.execution_count,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@Parallel=\\"true\\"]') = 1\\n  AND qs.total_elapsed_time / NULLIF(qs.execution_count, 0) >\\n      qs.total_worker_time / NULLIF(qs.execution_count, 0)\\nORDER BY (qs.total_elapsed_time - qs.total_worker_time) DESC"}	{"condition": "elapsed_to_cpu_ratio > 2 for parallel queries (threads waiting, not working)", "description": "Parallel queries where elapsed >> CPU indicates threads idling due to skew"}	null	2026-02-23 20:18:31.389704
1375	sqlserver	query	Check currently executing parallel queries for thread imbalance	{"sql": "SELECT qp.session_id, qp.node_id, qp.thread_id,\\n  qp.row_count, qp.estimate_row_count,\\n  qp.physical_operator_name,\\n  r.dop,\\n  r.wait_type, r.wait_time\\nFROM sys.dm_exec_query_profiles qp\\nJOIN sys.dm_exec_requests r ON qp.session_id = r.session_id\\nWHERE qp.physical_operator_name IN ('Parallelism', 'Hash Match', 'Sort', 'Stream Aggregate')\\nORDER BY qp.session_id, qp.node_id, qp.thread_id"}	{"condition": "within same node_id, max(row_count) > 5 * min(row_count) across threads", "description": "Thread row counts vary by >5x within the same operator — severe work imbalance"}	null	2026-02-23 20:18:31.389705
1376	sqlserver	query	Verify overall parallelism wait overhead	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER')\\n  AND waiting_tasks_count > 0"}	{"condition": "CXPACKET waits elevated with high average wait time", "description": "Idle threads accumulating CXPACKET waits confirm work distribution imbalance"}	null	2026-02-23 20:18:31.389706
1377	sqlserver	query	Check current cost threshold setting	{"sql": "SELECT name, CAST(value_in_use AS int) AS value_in_use,\\n  CAST(value AS int) AS configured_value,\\n  CAST(minimum AS int) AS minimum,\\n  CAST(maximum AS int) AS maximum\\nFROM sys.configurations\\nWHERE name = 'cost threshold for parallelism'"}	{"condition": "value_in_use <= 5", "description": "Cost threshold at default (5) — far too low for most workloads"}	null	2026-02-23 20:18:31.389706
1379	sqlserver	query	Confirm parallelism overhead via wait stats	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  CAST(100.0 * wait_time_ms / NULLIF(SUM(wait_time_ms) OVER(), 0) AS decimal(5,2)) AS pct_of_total\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT')\\nORDER BY wait_time_ms DESC"}	{"condition": "CXPACKET pct_of_total > 5%", "description": "Parallelism waits consuming >5% of total waits — low threshold contributing to overhead"}	null	2026-02-23 20:18:31.389708
1380	sqlserver	query	Check MAXDOP setting vs available schedulers	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS int) FROM sys.configurations\\n   WHERE name = 'max degree of parallelism') AS maxdop,\\n  (SELECT COUNT(*) FROM sys.dm_os_schedulers\\n   WHERE scheduler_id < 255 AND is_online = 1) AS online_schedulers,\\n  (SELECT COUNT(DISTINCT parent_node_id) FROM sys.dm_os_schedulers\\n   WHERE scheduler_id < 255 AND is_online = 1) AS numa_nodes,\\n  (SELECT cpu_count FROM sys.dm_os_sys_info) AS logical_cpus,\\n  (SELECT socket_count FROM sys.dm_os_sys_info) AS sockets"}	{"condition": "maxdop = 0 (unlimited) or maxdop > online_schedulers / numa_nodes", "description": "MAXDOP set to 0 (unlimited) or exceeds cores per NUMA node"}	null	2026-02-23 20:18:31.389708
1382	sqlserver	query	Confirm with CXPACKET waits and SOS_SCHEDULER_YIELD	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'SOS_SCHEDULER_YIELD')\\nORDER BY wait_time_ms DESC"}	{"condition": "both CXPACKET and SOS_SCHEDULER_YIELD are elevated", "description": "Parallelism waits combined with scheduler yields confirm MAXDOP too high"}	null	2026-02-23 20:18:31.389709
1405	sqlserver	query	Check I/O latency on fragmented objects	{"sql": "SELECT TOP 15\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  ips.avg_fragmentation_in_percent,\\n  os.page_io_latch_wait_count,\\n  os.page_io_latch_wait_in_ms,\\n  os.page_io_latch_wait_in_ms / NULLIF(os.page_io_latch_wait_count, 0) AS avg_io_wait_ms,\\n  os.range_scan_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os\\n  ON ips.object_id = os.object_id AND ips.index_id = os.index_id\\nWHERE ips.avg_fragmentation_in_percent > 30\\n  AND ips.page_count > 1000\\n  AND os.range_scan_count > 50\\nORDER BY os.page_io_latch_wait_in_ms DESC"}	{"condition": "high page_io_latch_wait_in_ms on fragmented indexes with many scans", "description": "Fragmented indexes causing physical I/O delays during parallel scans"}	null	2026-02-23 20:18:31.389718
1407	sqlserver	query	Check PAGEIOLATCH waits for parallel queries	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'ASYNC_IO_COMPLETION')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH_SH has high wait time and count", "description": "Parallel scan threads waiting for pages — readahead cannot pre-populate fast enough"}	null	2026-02-23 20:18:31.389719
7148	oracle	query	ora_check_archive_log_mode	{"sql": "SELECT log_mode, force_logging, supplemental_log_data_min FROM v$database"}	{"condition": "log_mode = 'NOARCHIVELOG'", "description": "Database in NOARCHIVELOG mode means archive logs are not being generated"}	\N	2026-02-28 12:19:19.580455
1766	sqlserver	query	Check for variable-length columns in index keys	{"sql": "SELECT OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, c.name AS column_name, tp.name AS data_type, c.max_length FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.is_included_column = 0 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.user_type_id = tp.user_type_id WHERE i.type > 0 AND tp.name IN ('varchar', 'nvarchar', 'varbinary') AND i.object_id IN (SELECT os.object_id FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os WHERE os.leaf_allocation_count > :min_splits AND os.leaf_update_count > :min_updates) ORDER BY c.max_length DESC"}	{"condition": "row_count > 0", "description": "Variable-length key columns in high-split indexes — updates expanding column values cause page splits"}	{"min_splits": 500, "min_updates": 5000}	2026-02-23 20:18:31.389947
1395	sqlserver	query	Check for parallel plans hitting many partitions	{"sql": "SELECT TOP 15\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qp.query_plan.value('(//RelOp[@Parallel=\\"true\\"]/RunTimeInformation/RunTimeCountersPerThread/@ActualRows)[1]', 'bigint') AS thread_rows,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@Parallel=\\"true\\"]') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 100000\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "high logical reads per execution on parallel queries hitting partitioned tables", "description": "Parallel scans reading far more data than necessary — partition elimination not effective"}	null	2026-02-23 20:18:31.389712
1396	sqlserver	query	Find parallel hash join queries with high CPU variance	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.max_worker_time,\\n  qs.min_worker_time,\\n  qs.max_worker_time / NULLIF(qs.min_worker_time, 0) AS cpu_variance_ratio,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\" and @Parallel=\\"true\\"]') = 1\\n  AND qs.total_worker_time / NULLIF(qs.execution_count, 0) > 100000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "parallel hash joins with avg_elapsed_us >> avg_cpu_us / DOP", "description": "Parallel hash joins taking longer than expected — join key skew causing uneven partitioning"}	null	2026-02-23 20:18:31.389713
1397	sqlserver	query	Check live parallel thread distribution for hash joins	{"sql": "SELECT qp.session_id, qp.node_id, qp.thread_id,\\n  qp.row_count, qp.estimate_row_count,\\n  qp.physical_operator_name,\\n  ABS(qp.row_count - qp.estimate_row_count) AS estimation_error\\nFROM sys.dm_exec_query_profiles qp\\nWHERE qp.physical_operator_name = 'Hash Match'\\nORDER BY qp.session_id, qp.node_id, qp.thread_id"}	{"condition": "within same node_id, max(row_count) > 5 * min(row_count)", "description": "Hash join thread row counts severely imbalanced — one partition has most of the data"}	null	2026-02-23 20:18:31.389713
1399	sqlserver	query	Check live thread distribution for aggregate operators	{"sql": "SELECT qp.session_id, qp.node_id, qp.thread_id,\\n  qp.row_count, qp.estimate_row_count,\\n  qp.physical_operator_name\\nFROM sys.dm_exec_query_profiles qp\\nWHERE qp.physical_operator_name IN ('Stream Aggregate', 'Hash Match')\\nORDER BY qp.session_id, qp.node_id, qp.thread_id"}	{"condition": "severe row imbalance across threads within same aggregate operator", "description": "Aggregate threads processing vastly different row counts — distribution key is skewed"}	null	2026-02-23 20:18:31.389715
1401	sqlserver	query	Check exchange spill and wait overhead	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT',\\n  'EXCHANGE', 'EXECSYNC')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "CXSYNC_PORT or EXCHANGE waits elevated alongside CXPACKET", "description": "Exchange synchronization overhead consuming significant time"}	null	2026-02-23 20:18:31.389716
1403	sqlserver	query	Check SOS_SCHEDULER_YIELD waits and parallel query count	{"sql": "SELECT\\n  (SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type = 'SOS_SCHEDULER_YIELD') AS scheduler_yield_ms,\\n  (SELECT waiting_tasks_count FROM sys.dm_os_wait_stats WHERE wait_type = 'SOS_SCHEDULER_YIELD') AS scheduler_yield_count,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests WHERE dop > 1) AS parallel_queries_now,\\n  (SELECT SUM(dop) FROM sys.dm_exec_requests WHERE dop > 1) AS total_parallel_threads,\\n  (SELECT COUNT(*) FROM sys.dm_os_schedulers WHERE scheduler_id < 255 AND is_online = 1) AS cpu_count"}	{"condition": "total_parallel_threads > cpu_count * 2 and SOS_SCHEDULER_YIELD is elevated", "description": "More parallel threads than CPUs with high scheduler yields — severe over-subscription"}	null	2026-02-23 20:18:31.389717
4283	postgresql	query	Check current lock waits involving job processes	{"sql": "SELECT blocked.pid AS blocked_pid, blocked.usename AS blocked_user, blocked.query AS blocked_query, blocking.pid AS blocking_pid, blocking.usename AS blocking_user, blocking.query AS blocking_query FROM pg_stat_activity blocked JOIN pg_locks bl ON blocked.pid = bl.pid JOIN pg_locks lock_blocker ON bl.locktype = lock_blocker.locktype AND bl.database IS NOT DISTINCT FROM lock_blocker.database AND bl.relation IS NOT DISTINCT FROM lock_blocker.relation AND bl.page IS NOT DISTINCT FROM lock_blocker.page AND bl.tuple IS NOT DISTINCT FROM lock_blocker.tuple AND bl.pid != lock_blocker.pid JOIN pg_stat_activity blocking ON lock_blocker.pid = blocking.pid WHERE NOT bl.granted"}	{"condition": "row_count > 0", "description": "Active lock waits detected between processes"}	\N	2026-02-25 00:28:52.405273
1404	sqlserver	query	Find fragmented indexes used by parallel queries	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.index_type_desc,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.fragment_count,\\n  ips.avg_page_space_used_in_percent,\\n  ius.user_scans, ius.user_seeks\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nJOIN sys.dm_db_index_usage_stats ius ON ips.object_id = ius.object_id\\n  AND ips.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE ips.avg_fragmentation_in_percent > 30\\n  AND ips.page_count > 1000\\n  AND ius.user_scans > 100\\nORDER BY ius.user_scans DESC"}	{"condition": "heavily fragmented indexes (>30%) with high scan counts", "description": "Fragmented indexes being frequently scanned — parallel readahead ineffective"}	null	2026-02-23 20:18:31.389717
1406	sqlserver	query	Check readahead and I/O wait statistics	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Readaheads/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS readaheads_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page reads/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS page_reads_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page lookups/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS page_lookups_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Buffer cache hit ratio'\\n   AND object_name LIKE '%Buffer Manager%') AS cache_hit_ratio"}	{"condition": "readaheads_sec is low relative to page_reads_sec or cache_hit_ratio is low", "description": "Readahead not keeping up with page demand — parallel scans stalling on I/O"}	null	2026-02-23 20:18:31.389718
1408	sqlserver	query	Check concurrent parallel scans competing for I/O	{"sql": "SELECT COUNT(*) AS parallel_scan_queries,\\n  SUM(r.dop) AS total_scan_threads\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_query_plan(r.plan_handle) qp\\nWHERE r.dop > 1\\n  AND (qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" and @Parallel=\\"true\\"]') = 1\\n    OR qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Index Scan\\" and @Parallel=\\"true\\"]') = 1\\n    OR qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Table Scan\\" and @Parallel=\\"true\\"]') = 1)"}	{"condition": "multiple parallel scan queries running simultaneously", "description": "Many concurrent parallel scans overwhelming I/O subsystem readahead capacity"}	null	2026-02-23 20:18:31.38972
1409	sqlserver	query	Find parallel nested loop joins with high execution counts	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Nested Loops\\" and @Parallel=\\"true\\"]') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 50000\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "parallel nested loop joins with very high logical reads per execution", "description": "Parallel nested loops iterating heavily — inner side executed millions of times across threads"}	null	2026-02-23 20:18:31.389721
1410	sqlserver	query	Check live thread activity for nested loop operators	{"sql": "SELECT qp.session_id, qp.node_id, qp.thread_id,\\n  qp.row_count, qp.estimate_row_count,\\n  qp.physical_operator_name,\\n  qp.cpu_time_ms, qp.elapsed_time_ms\\nFROM sys.dm_exec_query_profiles qp\\nWHERE qp.physical_operator_name = 'Nested Loops'\\nORDER BY qp.session_id, qp.node_id, qp.row_count DESC"}	{"condition": "nested loop operator with very high row_count or severe imbalance across threads", "description": "Parallel nested loop threads processing excessive iterations — high overhead"}	null	2026-02-23 20:18:31.389722
3876	postgresql	query	Check basic PostgreSQL health	{"sql": "SELECT 1 AS health_check, pg_is_in_recovery() AS is_standby, current_timestamp AS server_time"}	{"condition": "row_count > 0 AND is_standby = false", "description": "PostgreSQL is responsive as primary"}	\N	2026-02-25 00:28:52.405273
1411	sqlserver	query	Check for cardinality misestimate driving wrong join choice	{"sql": "SELECT TOP 10\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.last_rows,\\n  qs.max_logical_reads,\\n  qs.min_logical_reads,\\n  qs.max_logical_reads / NULLIF(qs.min_logical_reads, 0) AS read_variance_ratio\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Nested Loops\\" and @Parallel=\\"true\\"]') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 50000\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "high read_variance_ratio or avg_reads >> expected for the row count", "description": "Cardinality underestimate caused optimizer to choose nested loop instead of hash/merge join"}	null	2026-02-23 20:18:31.389722
2747	sqlserver	query	Check action group coverage in server audit specifications	{"sql": "SELECT sas.name AS spec_name, sas.is_state_enabled,\\n  COUNT(sasd.audit_action_id) AS action_group_count,\\n  STRING_AGG(sasd.audit_action_name, ', ') AS actions\\nFROM sys.server_audit_specifications sas\\nLEFT JOIN sys.server_audit_specification_details sasd\\n  ON sas.server_specification_id = sasd.server_specification_id\\nWHERE sas.is_state_enabled = 1\\nGROUP BY sas.name, sas.is_state_enabled"}	{"condition": "action_group_count < 3 or critical groups missing", "description": "Audit specification captures too few events — compliance gaps likely"}	null	2026-02-23 20:18:31.389723
2748	sqlserver	query	Verify critical action groups are included	{"sql": "SELECT action_name AS required_group,\\n  CASE WHEN EXISTS (\\n    SELECT 1 FROM sys.server_audit_specification_details sasd\\n    JOIN sys.server_audit_specifications sas\\n      ON sasd.server_specification_id = sas.server_specification_id\\n    WHERE sas.is_state_enabled = 1\\n      AND sasd.audit_action_name = da.action_name\\n  ) THEN 'PRESENT' ELSE 'MISSING' END AS status\\nFROM (\\n  VALUES ('FAILED_LOGIN_GROUP'), ('SUCCESSFUL_LOGIN_GROUP'),\\n         ('SERVER_ROLE_MEMBER_CHANGE_GROUP'),\\n         ('DATABASE_PERMISSION_CHANGE_GROUP'),\\n         ('SCHEMA_OBJECT_ACCESS_GROUP')\\n) da(action_name)"}	{"condition": "any critical group status = MISSING", "description": "Critical audit action groups not being captured"}	null	2026-02-23 20:18:31.389723
2749	sqlserver	query	Check SQL Server edition and version for audit support	{"sql": "SELECT SERVERPROPERTY('Edition') AS edition,\\n  SERVERPROPERTY('ProductVersion') AS version,\\n  SERVERPROPERTY('ProductLevel') AS service_pack,\\n  SERVERPROPERTY('EngineEdition') AS engine_edition,\\n  CASE\\n    WHEN SERVERPROPERTY('EngineEdition') = 1 THEN 'Personal/Desktop - NO AUDIT'\\n    WHEN SERVERPROPERTY('EngineEdition') = 2 THEN 'Standard - Limited Audit (server-level only pre-2016 SP1)'\\n    WHEN SERVERPROPERTY('EngineEdition') = 3 THEN 'Enterprise - Full Audit'\\n    WHEN SERVERPROPERTY('EngineEdition') = 4 THEN 'Express - NO SQL Server Audit'\\n    WHEN SERVERPROPERTY('EngineEdition') = 5 THEN 'Azure SQL - Uses Azure Auditing'\\n    ELSE 'Unknown'\\n  END AS audit_capability"}	{"condition": "engine_edition IN (1, 4) OR (engine_edition = 2 AND version < 13.0.4001)", "description": "Edition does not support SQL Server Audit or has limited capabilities"}	null	2026-02-23 20:18:31.389724
2753	sqlserver	query	Check for disabled audits alongside performance indicators	{"sql": "SELECT sa.name AS audit_name, sa.is_state_enabled,\\n  sa.create_date, sa.modify_date,\\n  sa.type_desc AS destination,\\n  sa.queue_delay AS queue_delay_ms,\\n  (SELECT SUM(signal_wait_time_ms) * 100.0 / NULLIF(SUM(wait_time_ms), 0)\\n   FROM sys.dm_os_wait_stats) AS signal_wait_pct,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec'\\n     AND instance_name = '') AS batch_requests_sec\\nFROM sys.server_audits sa\\nWHERE sa.is_state_enabled = 0"}	{"condition": "disabled audits exist (is_state_enabled = 0)", "description": "Audit objects exist but are disabled — may have been turned off for performance"}	null	2026-02-23 20:18:31.389726
2754	sqlserver	query	Check if audit queue_delay is set to minimize overhead	{"sql": "SELECT sa.name, sa.queue_delay,\\n  sa.type_desc,\\n  CASE\\n    WHEN sa.queue_delay = 0 THEN 'SYNCHRONOUS (highest impact)'\\n    WHEN sa.queue_delay = 1000 THEN 'DEFAULT (1 second buffer)'\\n    WHEN sa.queue_delay > 1000 THEN 'RELAXED (reduced accuracy for performance)'\\n    ELSE 'CUSTOM'\\n  END AS delay_assessment\\nFROM sys.server_audits sa"}	{"condition": "disabled audit with queue_delay = 0 (synchronous mode was too expensive)", "description": "Synchronous audit mode likely caused performance degradation leading to disablement"}	null	2026-02-23 20:18:31.389727
1413	sqlserver	query	Check SOS_SCHEDULER_YIELD waits indicating CPU pressure	{"sql": "SELECT wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  CASE WHEN waiting_tasks_count > 0\\n    THEN wait_time_ms / waiting_tasks_count ELSE 0 END AS avg_wait_ms,\\n  signal_wait_time_ms,\\n  CASE WHEN wait_time_ms > 0\\n    THEN CAST(signal_wait_time_ms AS FLOAT) / wait_time_ms * 100 ELSE 0 END AS signal_pct\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('SOS_SCHEDULER_YIELD', 'CXPACKET', 'CXCONSUMER', 'THREADPOOL')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "SOS_SCHEDULER_YIELD dominant with signal_pct > 20% across all wait types", "description": "High SOS_SCHEDULER_YIELD waits confirm CPU-bound workload with excessive context switching; high signal waits across all types confirm CPU saturation"}	null	2026-02-23 20:18:31.389728
1414	sqlserver	query	Identify queries with highest CPU time contributing to switching	{"sql": "SELECT TOP 10\\n  qs.total_worker_time / 1000 AS total_cpu_ms,\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.plan_generation_num,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.execution_count > 100\\nORDER BY qs.total_worker_time DESC"}	{"condition": "top queries have very high total_worker_time with high execution_count", "description": "High-frequency queries consuming large CPU totals drive scheduler context switches"}	null	2026-02-23 20:18:31.389728
1415	sqlserver	query	Check overall CPU utilization from SQL Server ring buffer	{"sql": "SELECT TOP 10\\n  record_id,\\n  EventTime,\\n  SQLProcessUtilization,\\n  SystemIdle,\\n  100 - SystemIdle - SQLProcessUtilization AS OtherProcessCPU\\nFROM (\\n  SELECT\\n    record.value('(./Record/@id)[1]', 'int') AS record_id,\\n    record.value('(./Record/SchedulerMonitorEvent/SystemHealth/ProcessUtilization)[1]', 'int') AS SQLProcessUtilization,\\n    record.value('(./Record/SchedulerMonitorEvent/SystemHealth/SystemIdle)[1]', 'int') AS SystemIdle,\\n    DATEADD(ms, -1 * (si.cpu_ticks / (si.cpu_ticks / si.ms_ticks) - record.value('(./Record/@time)[1]', 'bigint')), GETDATE()) AS EventTime\\n  FROM (\\n    SELECT CAST(record AS XML) AS record\\n    FROM sys.dm_os_ring_buffers\\n    WHERE ring_buffer_type = N'RING_BUFFER_SCHEDULER_MONITOR'\\n      AND record LIKE N'%<SystemHealth>%'\\n  ) AS x\\n  CROSS JOIN sys.dm_os_sys_info si\\n) AS y\\nORDER BY record_id DESC"}	{"condition": "SQLProcessUtilization > 80 or SystemIdle < 10 sustained over multiple samples", "description": "SQL Server consuming most CPU capacity with little idle headroom"}	null	2026-02-23 20:18:31.389729
1416	sqlserver	query	Check scheduler pressure and signal wait ratio	{"sql": "SELECT\\n  SUM(signal_wait_time_ms) AS total_signal_wait_ms,\\n  SUM(wait_time_ms) AS total_wait_ms,\\n  CASE WHEN SUM(wait_time_ms) > 0\\n    THEN CAST(SUM(signal_wait_time_ms) AS FLOAT) / SUM(wait_time_ms) * 100 ELSE 0 END AS signal_wait_pct,\\n  (SELECT SUM(runnable_tasks_count) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS total_runnable_tasks,\\n  (SELECT COUNT(*) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS scheduler_count,\\n  (SELECT cpu_count FROM sys.dm_os_sys_info) AS logical_cpus,\\n  (SELECT hyperthread_ratio FROM sys.dm_os_sys_info) AS hyperthread_ratio\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type NOT IN ('WAITFOR', 'LAZYWRITER_SLEEP', 'SQLTRACE_BUFFER_FLUSH',\\n  'REQUEST_FOR_DEADLOCK_SEARCH', 'SLEEP_TASK', 'BROKER_TO_FLUSH',\\n  'CHECKPOINT_QUEUE', 'CLR_AUTO_EVENT', 'CLR_MANUAL_EVENT')"}	{"condition": "signal_wait_pct > 15 and total_runnable_tasks > scheduler_count", "description": "High signal wait percentage confirms tasks are ready to run but waiting for CPU time; runnable queue exceeds available schedulers"}	null	2026-02-23 20:18:31.38973
1417	sqlserver	query	Check plan cache composition for ad-hoc vs prepared ratio	{"sql": "SELECT cacheobjtype, objtype,\\n  COUNT(*) AS plan_count,\\n  SUM(CAST(size_in_bytes AS BIGINT)) / 1024 / 1024 AS total_size_mb,\\n  AVG(usecounts) AS avg_use_count,\\n  SUM(CASE WHEN usecounts = 1 THEN 1 ELSE 0 END) AS single_use_plans\\nFROM sys.dm_exec_cached_plans\\nGROUP BY cacheobjtype, objtype\\nORDER BY plan_count DESC"}	{"condition": "objtype = 'Adhoc' has high plan_count with avg_use_count near 1 and single_use_plans > 50% of total Adhoc plans", "description": "Massive number of single-use ad-hoc plans confirms non-parameterized queries flooding the plan cache"}	null	2026-02-23 20:18:31.38973
3947	postgresql	query	Check WAL archiver failure count	{"sql": "SELECT archived_count, failed_count, last_failed_wal, last_failed_time FROM pg_stat_archiver WHERE failed_count > 0"}	{"condition": "row_count > 0", "description": "WAL archive failures prevent WAL segment recycling and cause disk space growth"}	\N	2026-02-25 00:28:52.405273
1420	sqlserver	query	Find cached plans from EXEC() dynamic SQL patterns	{"sql": "SELECT TOP 20\\n  cp.objtype, cp.usecounts, cp.size_in_bytes / 1024 AS size_kb,\\n  st.text AS sql_text\\nFROM sys.dm_exec_cached_plans cp\\nCROSS APPLY sys.dm_exec_sql_text(cp.plan_handle) st\\nWHERE cp.objtype = 'Adhoc'\\n  AND cp.usecounts = 1\\n  AND (st.text LIKE '%EXEC(%' OR st.text LIKE '%EXECUTE(%')\\n  AND st.text NOT LIKE '%sp_executesql%'\\nORDER BY cp.size_in_bytes DESC"}	{"condition": "row_count > 5 showing EXEC() calls with embedded literal values", "description": "Dynamic SQL using EXEC() with concatenated values creates unique non-parameterized plans"}	null	2026-02-23 20:18:31.389731
1522	sqlserver	query	Check log-related spinlock contention across NUMA nodes	{"sql": "SELECT name, collisions, spins, spins_per_collision,\\n  sleep_time, backoffs\\nFROM sys.dm_os_spinlock_stats\\nWHERE name IN ('LOGCACHE_ACCESS', 'LOGFLUSHQ', 'LOGPOOL_HASHBUCKET',\\n  'LOGPOOL_FREEPOOLLIST', 'LOGPOOL_SHAREDCACHEBUFFER')\\n  AND collisions > 1000\\nORDER BY collisions DESC"}	{"condition": "collisions > 10000 or backoffs > 1000 on log-related spinlocks", "description": "High spinlock contention on log cache structures — typical of NUMA cache line bouncing"}	null	2026-02-23 20:18:31.389753
1421	sqlserver	query	Check recompilation rate from SQL Re-Compilations/sec counter	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'SQL Compilations/sec') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'SQL Re-Compilations/sec') AS recompilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'Batch Requests/sec') AS batch_requests_sec"}	{"condition": "compilations_sec / batch_requests_sec > 0.10 indicating > 10% of batches require compilation", "description": "High compilation-to-batch ratio confirms excessive plan generation from non-parameterized dynamic SQL"}	null	2026-02-23 20:18:31.389732
3082	sqlserver	query	Check for lazy optimization trace flags	{"sql": "DBCC TRACESTATUS(-1) WITH NO_INFOMSGS"}	{"condition": "trace flags include optimization shortcuts: 4136 (disable parameter sniffing globally), 8649 (force parallel plans for all queries), 2312 or 9481 (force CE model globally instead of per-query), 610 (minimal logging blanket), 652 (disable read-ahead), 8015 (ignore physical affinity)", "description": "Trace flags used as global optimization shortcuts instead of addressing root cause per-query"}	null	2026-02-23 20:18:31.390774
1517	sqlserver	query	Check log reuse wait description per database	{"sql": "SELECT d.name,\\n  d.recovery_model_desc,\\n  d.log_reuse_wait_desc,\\n  ls.total_log_size_in_bytes / 1048576 AS total_log_mb,\\n  ls.used_log_space_in_bytes / 1048576 AS used_log_mb,\\n  ls.used_log_space_in_percent AS log_used_pct\\nFROM sys.databases d\\nJOIN sys.dm_db_log_space_usage ls ON d.database_id = ls.database_id\\nWHERE d.database_id > 4\\n  AND d.log_reuse_wait_desc <> 'NOTHING'\\nORDER BY ls.used_log_space_in_percent DESC"}	{"condition": "log_reuse_wait_desc != 'NOTHING' AND log_used_pct > 50", "description": "Log cannot be truncated — something is preventing log space reuse"}	null	2026-02-23 20:18:31.389733
1422	sqlserver	query	Check for recent auto-stats update events	{"sql": "SELECT\\n  o.name AS table_name,\\n  s.name AS stat_name,\\n  s.auto_created,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.rows_sampled,\\n  sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(sp.modification_counter AS FLOAT) / sp.rows * 100 ELSE 0 END AS modification_pct\\nFROM sys.stats s\\nJOIN sys.objects o ON s.object_id = o.object_id\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE o.type = 'U'\\n  AND sp.modification_counter > 0\\n  AND sp.last_updated > DATEADD(HOUR, -1, GETDATE())\\nORDER BY sp.modification_counter DESC"}	{"condition": "statistics updated within the last hour with high modification_counter values", "description": "Recent auto-stats updates indicate statistics are being refreshed during query execution windows"}	null	2026-02-23 20:18:31.389733
1423	sqlserver	query	Check auto-stats configuration and recompilation correlation	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'Auto-Param Attempts/sec') AS auto_param_attempts,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'SQL Re-Compilations/sec') AS recompilations_sec,\\n  (SELECT is_auto_update_stats_on FROM sys.databases WHERE database_id = DB_ID()) AS auto_update_stats,\\n  (SELECT is_auto_update_stats_async_on FROM sys.databases WHERE database_id = DB_ID()) AS auto_update_stats_async"}	{"condition": "auto_update_stats = 1 AND auto_update_stats_async = 0 AND recompilations_sec elevated", "description": "Synchronous auto-stats updates (async disabled) block query execution during statistics refresh and force recompilation"}	null	2026-02-23 20:18:31.389734
1424	sqlserver	query	Check plan cache for high plan_generation_num indicating schema-driven recompilation	{"sql": "SELECT TOP 20\\n  qs.plan_generation_num,\\n  qs.execution_count,\\n  qs.total_worker_time / 1000 AS total_cpu_ms,\\n  qs.creation_time AS last_compile_time,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.plan_generation_num > 5\\nORDER BY qs.plan_generation_num DESC"}	{"condition": "plan_generation_num > 5 for multiple queries, especially those referencing user tables", "description": "High plan generation numbers indicate queries have been recompiled many times, consistent with schema changes invalidating plans"}	null	2026-02-23 20:18:31.389735
1425	sqlserver	query	Check for recent schema changes via sys.objects modify_date	{"sql": "SELECT o.name, o.type_desc, o.modify_date,\\n  DATEDIFF(MINUTE, o.modify_date, GETDATE()) AS minutes_ago\\nFROM sys.objects o\\nWHERE o.type IN ('U', 'V', 'P', 'FN', 'IF', 'TF')\\n  AND o.modify_date > DATEADD(HOUR, -24, GETDATE())\\n  AND o.is_ms_shipped = 0\\nORDER BY o.modify_date DESC"}	{"condition": "objects modified within last 24 hours, especially tables referenced by high plan_generation_num queries", "description": "Recent schema modifications on tables correlating with recompiled queries confirms schema changes as the recompilation trigger"}	null	2026-02-23 20:18:31.389735
1426	sqlserver	query	Check for recent index modifications and missing index requests	{"sql": "SELECT\\n  i.name AS index_name, o.name AS table_name,\\n  i.type_desc, i.is_disabled, i.is_hypothetical,\\n  STATS_DATE(i.object_id, i.index_id) AS last_stats_update,\\n  ius.last_user_seek, ius.last_user_scan, ius.last_user_lookup,\\n  ius.user_seeks + ius.user_scans + ius.user_lookups AS total_reads,\\n  ius.user_updates,\\n  o.modify_date AS table_modify_date\\nFROM sys.indexes i\\nJOIN sys.objects o ON i.object_id = o.object_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id\\n  AND ius.database_id = DB_ID()\\nWHERE o.type = 'U'\\n  AND o.is_ms_shipped = 0\\n  AND o.modify_date > DATEADD(HOUR, -24, GETDATE())\\nORDER BY o.modify_date DESC"}	{"condition": "tables with recent modify_date having indexes with no usage stats (newly created) or missing expected indexes (recently dropped)", "description": "Recent index DDL on tables correlates with plan cache invalidation for all queries on those tables"}	null	2026-02-23 20:18:31.389736
1435	sqlserver	query	Correlate stats volatility with plan recompilation frequency	{"sql": "SELECT\\n  OBJECT_NAME(st.objectid, st.dbid) AS object_name,\\n  qs.plan_generation_num,\\n  qs.execution_count,\\n  qs.creation_time AS last_compile_time,\\n  DATEDIFF(MINUTE, qs.creation_time, GETDATE()) AS minutes_since_compile,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.plan_generation_num > 5\\n  AND qs.creation_time > DATEADD(HOUR, -4, GETDATE())\\nORDER BY qs.plan_generation_num DESC"}	{"condition": "plan_generation_num > 5 with recent creation_time and queries referencing the volatile tables from step 1", "description": "Frequent recompilation of queries on tables with rapidly changing statistics confirms the stats-to-recompile feedback loop"}	null	2026-02-23 20:18:31.389741
1501	sqlserver	query	Check log file placement and sharing	{"sql": "SELECT d.name AS database_name,\\n  mf_log.physical_name AS log_file_path,\\n  LEFT(mf_log.physical_name, 3) AS log_drive,\\n  mf_data.physical_name AS data_file_path,\\n  LEFT(mf_data.physical_name, 3) AS data_drive\\nFROM sys.databases d\\nJOIN sys.master_files mf_log ON d.database_id = mf_log.database_id AND mf_log.type = 1\\nJOIN sys.master_files mf_data ON d.database_id = mf_data.database_id AND mf_data.type = 0\\nWHERE d.database_id > 4\\n  AND LEFT(mf_log.physical_name, 3) = LEFT(mf_data.physical_name, 3)"}	{"condition": "row_count > 0", "description": "Log and data files on the same drive letter — I/O contention between sequential log writes and random data reads"}	null	2026-02-23 20:18:31.389747
1444	sqlserver	query	Verify compilation overhead from parameter proliferation	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'SQL Compilations/sec') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'Batch Requests/sec') AS batch_requests_sec,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans WHERE objtype = 'Prepared'\\n    AND usecounts < 3) AS low_reuse_prepared_plans,\\n  (SELECT SUM(CAST(size_in_bytes AS BIGINT)) / 1024 / 1024\\n   FROM sys.dm_exec_cached_plans WHERE objtype = 'Prepared'\\n    AND usecounts < 3) AS low_reuse_prepared_mb"}	{"condition": "compilations_sec / batch_requests_sec > 0.05 and low_reuse_prepared_plans is significant", "description": "High compilation rate with many low-reuse prepared plans confirms parameter combination explosion preventing effective caching"}	null	2026-02-23 20:18:31.389748
1429	sqlserver	query	Check recompilation events via extended events or trace	{"sql": "SELECT\\n  qs.sql_handle,\\n  qs.plan_generation_num,\\n  qs.creation_time,\\n  qp.query_plan,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS statement_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE st.objectid IS NOT NULL\\n  AND qs.plan_generation_num > 3\\n  AND (CAST(qp.query_plan AS NVARCHAR(MAX)) LIKE '%StatementOptmEarlyAbortReason=\\"GoodEnoughPlanFound\\"%'\\n    OR qs.creation_time > DATEADD(MINUTE, -30, GETDATE()))\\nORDER BY qs.plan_generation_num DESC"}	{"condition": "recently compiled plans for statements referencing temp tables in procedures that recompile frequently", "description": "Statements following temp table creation inside control flow are recompiled because the optimizer cannot determine temp table schema at initial compilation time"}	null	2026-02-23 20:18:31.389738
1430	sqlserver	query	Find procedures with multiple plans for the same query	{"sql": "SELECT\\n  st.dbid, OBJECT_NAME(st.objectid, st.dbid) AS procedure_name,\\n  COUNT(DISTINCT qs.plan_handle) AS plan_count,\\n  SUM(qs.execution_count) AS total_executions,\\n  MIN(qs.total_worker_time / NULLIF(qs.execution_count, 0)) / 1000 AS min_avg_cpu_ms,\\n  MAX(qs.total_worker_time / NULLIF(qs.execution_count, 0)) / 1000 AS max_avg_cpu_ms,\\n  MAX(qs.plan_generation_num) AS max_plan_gen\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE st.objectid IS NOT NULL\\nGROUP BY st.dbid, st.objectid\\nHAVING COUNT(DISTINCT qs.plan_handle) > 1\\nORDER BY COUNT(DISTINCT qs.plan_handle) DESC"}	{"condition": "plan_count > 1 with large variance between min_avg_cpu_ms and max_avg_cpu_ms", "description": "Multiple distinct plans for the same procedure with wide CPU variance indicates parameter sniffing is creating different plans for different parameter values"}	null	2026-02-23 20:18:31.389738
1438	sqlserver	query	Find tables with large modification counters relative to row counts	{"sql": "SELECT\\n  OBJECT_NAME(p.object_id) AS table_name,\\n  p.rows AS current_rows,\\n  SUM(sp.modification_counter) AS total_modifications,\\n  MAX(sp.last_updated) AS most_recent_stats_update,\\n  COUNT(DISTINCT s.stats_id) AS stats_count,\\n  CASE WHEN p.rows > 500\\n    THEN SQRT(1000.0 * p.rows) ELSE 500.0 END AS recomp_threshold\\nFROM sys.partitions p\\nJOIN sys.stats s ON p.object_id = s.object_id\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE p.index_id IN (0, 1)\\n  AND OBJECTPROPERTY(p.object_id, 'IsUserTable') = 1\\n  AND sp.modification_counter > 0\\nGROUP BY p.object_id, p.rows\\nHAVING SUM(sp.modification_counter) >\\n  CASE WHEN p.rows > 500 THEN SQRT(1000.0 * p.rows) ELSE 500.0 END\\nORDER BY total_modifications DESC"}	{"condition": "total_modifications exceeds the auto-stats recompilation threshold for the table's row count", "description": "Tables where modifications exceed the recompilation threshold will trigger auto-stats updates and subsequent plan recompilation"}	null	2026-02-23 20:18:31.389743
1431	sqlserver	query	Examine sniffed parameters in cached plans	{"sql": "SELECT TOP 10\\n  OBJECT_NAME(st.objectid, st.dbid) AS procedure_name,\\n  qs.plan_handle,\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.plan_generation_num,\\n  TRY_CAST(qp.query_plan AS XML).value('(//ParameterList/ColumnReference/@ParameterCompiledValue)[1]', 'NVARCHAR(256)') AS sniffed_param_1\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE st.objectid IS NOT NULL\\n  AND st.objectid IN (\\n    SELECT st2.objectid\\n    FROM sys.dm_exec_query_stats qs2\\n    CROSS APPLY sys.dm_exec_sql_text(qs2.sql_handle) st2\\n    WHERE st2.objectid IS NOT NULL\\n    GROUP BY st2.dbid, st2.objectid\\n    HAVING COUNT(DISTINCT qs2.plan_handle) > 1\\n  )\\nORDER BY qs.total_worker_time DESC"}	{"condition": "same procedure with different sniffed parameter values producing plans with widely different avg_logical_reads and avg_cpu_ms", "description": "Confirms parameter sniffing: optimizer compiled plan for one parameter value but performance degrades for other values with different data distributions"}	null	2026-02-23 20:18:31.389739
1432	sqlserver	query	Find cached plans with RECOMPILE hints	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(st.objectid, st.dbid) AS procedure_name,\\n  qs.execution_count,\\n  qs.total_worker_time / 1000 AS total_cpu_ms,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.plan_generation_num,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS statement_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE st.text LIKE '%RECOMPILE%'\\n  AND qs.execution_count > 100\\nORDER BY qs.total_worker_time DESC"}	{"condition": "queries with RECOMPILE in text having high execution_count (> 100), each execution paying full compilation cost", "description": "High-frequency queries with RECOMPILE hints force compilation CPU overhead on every execution"}	null	2026-02-23 20:18:31.38974
1433	sqlserver	query	Quantify compilation CPU overhead from recompile hints	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'SQL Re-Compilations/sec') AS recompilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'Batch Requests/sec') AS batch_requests_sec,\\n  (SELECT SUM(qs.total_worker_time) / 1000\\n   FROM sys.dm_exec_query_stats qs\\n   CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\n   WHERE st.text LIKE '%RECOMPILE%'\\n     AND qs.execution_count > 100) AS total_recompile_cpu_ms"}	{"condition": "recompilations_sec / batch_requests_sec > 0.05 and total_recompile_cpu_ms is significant portion of server CPU", "description": "Recompile hints contributing measurable CPU overhead relative to batch request volume"}	null	2026-02-23 20:18:31.38974
1434	sqlserver	query	Find statistics with high modification counters relative to row count	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  s.auto_created,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(sp.modification_counter AS FLOAT) / sp.rows * 100 ELSE 0 END AS modification_pct,\\n  sp.steps AS histogram_steps\\nFROM sys.stats s\\nJOIN sys.objects o ON s.object_id = o.object_id\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE o.type = 'U' AND o.is_ms_shipped = 0\\n  AND sp.modification_counter > 500\\nORDER BY modification_pct DESC"}	{"condition": "modification_pct > 20% on tables with auto-created statistics, indicating data is changing faster than stats can stabilize", "description": "High modification percentages relative to row count cause auto-stats to repeatedly trigger, each update forcing recompilation of referencing queries"}	null	2026-02-23 20:18:31.389741
3967	postgresql	query	Check wal_keep_size configuration	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('wal_keep_size', 'wal_keep_segments')"}	{"condition": "setting = '0' OR setting IS NULL", "description": "Zero or unset wal_keep_size means no WAL retention guarantee beyond checkpoint"}	\N	2026-02-25 00:28:52.405273
1436	sqlserver	query	Analyze density vectors for join columns on volatile tables	{"sql": "SELECT\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.rows,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter AS FLOAT) / NULLIF(sp.rows, 0) * 100 AS mod_pct,\\n  sp.last_updated,\\n  (SELECT TOP 1 range_rows FROM sys.dm_db_stats_histogram(s.object_id, s.stats_id)\\n   ORDER BY range_rows DESC) AS max_range_rows,\\n  (SELECT AVG(range_rows) FROM sys.dm_db_stats_histogram(s.object_id, s.stats_id)) AS avg_range_rows,\\n  (SELECT MAX(range_rows) - MIN(range_rows) FROM sys.dm_db_stats_histogram(s.object_id, s.stats_id)) AS range_spread\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.stats_columns sc ON s.object_id = sc.object_id AND s.stats_id = sc.stats_id\\nJOIN sys.index_columns ic ON sc.object_id = ic.object_id AND sc.column_id = ic.column_id\\nWHERE sp.modification_counter > 1000\\n  AND sp.rows > 10000\\nORDER BY mod_pct DESC"}	{"condition": "range_spread is large relative to avg_range_rows, indicating highly uneven data distribution that changes with DML", "description": "Skewed and shifting density in join columns means the optimizer may choose hash join for one parameter set and nested loops for another"}	null	2026-02-23 20:18:31.389742
1437	sqlserver	query	Find queries with multiple plans showing different join types	{"sql": "SELECT\\n  qs.sql_handle,\\n  COUNT(DISTINCT qs.plan_handle) AS plan_variants,\\n  MIN(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS min_avg_reads,\\n  MAX(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS max_avg_reads,\\n  MAX(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) /\\n    NULLIF(MIN(qs.total_logical_reads / NULLIF(qs.execution_count, 0)), 0) AS read_ratio,\\n  SUM(qs.plan_generation_num) AS total_regens\\nFROM sys.dm_exec_query_stats qs\\nGROUP BY qs.sql_handle\\nHAVING COUNT(DISTINCT qs.plan_handle) > 1\\n  AND MAX(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) /\\n    NULLIF(MIN(qs.total_logical_reads / NULLIF(qs.execution_count, 0)), 0) > 10\\nORDER BY read_ratio DESC"}	{"condition": "read_ratio > 10 indicating same query has plans with vastly different I/O patterns (different join strategies)", "description": "A 10x+ difference in avg reads between plan variants for the same query confirms the optimizer is choosing different join orders based on density changes"}	null	2026-02-23 20:18:31.389743
5325	postgresql	config_check	Check plan_cache_mode setting for generic plan behavior	{"sql": "SELECT name, setting FROM pg_settings WHERE name = 'plan_cache_mode'"}	{"condition": "setting = 'auto'", "description": "Auto plan caching may lock in suboptimal generic plans for skewed parameter distributions"}	\N	2026-02-25 00:28:52.405273
1439	sqlserver	query	Check for cardinality estimation warnings in recent plans	{"sql": "SELECT TOP 15\\n  qs.plan_generation_num,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.creation_time,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset\\n      WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.plan_generation_num > 3\\n  AND qs.creation_time > DATEADD(HOUR, -2, GETDATE())\\nORDER BY qs.plan_generation_num DESC"}	{"condition": "multiple queries recompiled within last 2 hours with high plan_generation_num referencing tables from step 1", "description": "Frequent recompilation of queries on tables exceeding cardinality thresholds confirms row count changes are driving recompilation"}	null	2026-02-23 20:18:31.389744
1441	sqlserver	query	Check plan cache hit ratio and memory pressure	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Plan Cache%'\\n     AND counter_name = 'Cache Hit Ratio'\\n     AND instance_name = '_Total') AS cache_hit_ratio_raw,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Plan Cache%'\\n     AND counter_name = 'Cache Hit Ratio Base'\\n     AND instance_name = '_Total') AS cache_hit_ratio_base,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Plan Cache%'\\n     AND counter_name = 'Cache Pages'\\n     AND instance_name = '_Total') AS cache_pages,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n     AND counter_name = 'Stolen Server Memory (KB)') AS stolen_memory_kb"}	{"condition": "cache_hit_ratio_raw / cache_hit_ratio_base < 0.90 indicating less than 90% plan cache hit rate", "description": "Low plan cache hit ratio confirms plans are being evicted under memory pressure and must be recompiled"}	null	2026-02-23 20:18:31.389745
1442	sqlserver	query	Check for plan cache eviction notifications	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Plan Cache%'\\n     AND counter_name = 'Cache Object Counts'\\n     AND instance_name = '_Total') AS total_cache_objects,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'SQL Compilations/sec') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n     AND counter_name = 'SQL Re-Compilations/sec') AS recompilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n     AND counter_name = 'Lazy writes/sec') AS lazy_writes_sec"}	{"condition": "compilations_sec consistently high relative to recompilations_sec indicating fresh compilations (not just recompiles) from evicted plans", "description": "High compilation rate with low recompile rate means plans are being fully evicted (aged out) and compiled from scratch rather than recompiled in place"}	null	2026-02-23 20:18:31.389746
4284	postgresql	query	Check lock wait event statistics	{"sql": "SELECT count(*) AS lock_waiters, count(*) FILTER (WHERE wait_event_type = 'Lock') AS lock_events FROM pg_stat_activity WHERE wait_event_type = 'Lock'"}	{"condition": "lock_waiters > :threshold", "description": "Multiple sessions waiting for locks confirms contention"}	{"threshold": 2}	2026-02-25 00:28:52.405273
1443	sqlserver	query	Find queries with many distinct plans from parameter combinations	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  COUNT(DISTINCT qs.query_plan_hash) AS distinct_plan_shapes,\\n  COUNT(DISTINCT qs.plan_handle) AS total_plan_variants,\\n  SUM(qs.execution_count) AS total_executions,\\n  SUM(qs.total_worker_time) / 1000 AS total_cpu_ms,\\n  MIN(SUBSTRING(st.text, 1, 120)) AS query_sample\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nGROUP BY qs.query_hash\\nHAVING COUNT(DISTINCT qs.query_plan_hash) > 3\\nORDER BY COUNT(DISTINCT qs.query_plan_hash) DESC"}	{"condition": "distinct_plan_shapes > 3 for the same query_hash indicating the same logical query produces many different execution plans", "description": "Multiple distinct plan shapes for the same query hash confirms parameter combinations are causing the optimizer to generate different plans"}	null	2026-02-23 20:18:31.389746
8217	oracle	query	ora_check_dynamic_sampling_level	{"sql": "SELECT name, value FROM v$parameter WHERE name = 'optimizer_dynamic_sampling'"}	{"condition": "value returned", "description": "Dynamic sampling level determines how much effort Oracle spends estimating when statistics are missing"}	\N	2026-02-28 12:19:19.580455
1445	sqlserver	query	Check for SET option mismatches in cached plans	{"sql": "SELECT\\n  pa.attribute, pa.value,\\n  COUNT(*) AS plan_count,\\n  SUM(cp.usecounts) AS total_uses\\nFROM sys.dm_exec_cached_plans cp\\nCROSS APPLY sys.dm_exec_plan_attributes(cp.plan_handle) pa\\nWHERE pa.attribute = 'set_options'\\n  AND cp.objtype IN ('Adhoc', 'Prepared', 'Proc')\\nGROUP BY pa.attribute, pa.value\\nORDER BY plan_count DESC"}	{"condition": "multiple different set_options values with significant plan counts, indicating different sessions compile plans with different SET environments", "description": "Different SET option combinations create separate plan cache entries for identical queries — each unique set_options value is a separate cache bucket"}	null	2026-02-23 20:18:31.389748
9408	oracle	query	ora_check_trace_file_accessibility	{"sql": "SELECT name, value FROM v$parameter WHERE name = 'diagnostic_dest'"}	{"condition": "row_count > 0", "description": "Diagnostic destination contains trace files that may contain sensitive data"}	\N	2026-02-28 12:19:19.580455
1446	sqlserver	query	Check database compatibility level and recent configuration changes	{"sql": "SELECT d.name, d.compatibility_level,\\n  d.is_query_store_on,\\n  d.is_parameterization_forced,\\n  d.snapshot_isolation_state_desc,\\n  d.is_read_committed_snapshot_on,\\n  c.name AS config_name, c.value_in_use, c.value AS config_value\\nFROM sys.databases d\\nCROSS JOIN sys.configurations c\\nWHERE d.database_id = DB_ID()\\n  AND c.name IN ('cost threshold for parallelism', 'max degree of parallelism',\\n    'optimize for ad hoc workloads', 'query governor cost limit')\\nORDER BY c.name"}	{"condition": "value != value_in_use for any config (pending restart), or compatibility_level mismatch with server version", "description": "Configuration changes pending or recent compatibility level changes indicate environmental changes that can invalidate the plan cache"}	null	2026-02-23 20:18:31.389749
1447	sqlserver	query	Find queries with disproportionately high compilation time	{"sql": "SELECT TOP 15\\n  qs.total_worker_time / 1000 AS total_cpu_ms,\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.plan_generation_num,\\n  LEN(st.text) AS query_length_chars,\\n  (LEN(st.text) - LEN(REPLACE(st.text, 'JOIN', ''))) / 4 AS approx_join_count,\\n  SUBSTRING(st.text, 1, 200) AS query_prefix\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.plan_generation_num > 1\\n  AND LEN(st.text) > 2000\\nORDER BY qs.total_worker_time / NULLIF(qs.execution_count, 0) DESC"}	{"condition": "queries with query_length > 2000 chars, approx_join_count > 5, and avg_cpu_ms disproportionately high relative to rows returned", "description": "Long, complex queries with many joins spending significant CPU on compilation rather than execution"}	null	2026-02-23 20:18:31.389749
1448	sqlserver	query	Check for timeout or early abort in query optimization	{"sql": "SELECT TOP 10\\n  qs.plan_handle,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qp.query_plan.value('(//StmtSimple/@StatementOptmLevel)[1]', 'NVARCHAR(50)') AS optimization_level,\\n  qp.query_plan.value('(//StmtSimple/@StatementOptmEarlyAbortReason)[1]', 'NVARCHAR(50)') AS early_abort_reason,\\n  qp.query_plan.value('count(//RelOp)', 'INT') AS operator_count\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.plan_generation_num > 1\\n  AND qs.total_worker_time / NULLIF(qs.execution_count, 0) > 100000\\nORDER BY qs.total_worker_time / NULLIF(qs.execution_count, 0) DESC"}	{"condition": "early_abort_reason = 'TimeOut' or optimization_level = 'FULL' with high operator_count (> 30)", "description": "Optimizer timeout indicates the query is too complex to fully optimize within SQL Server's cost-based search limits, settling for a suboptimal plan"}	null	2026-02-23 20:18:31.38975
1449	sqlserver	query	Check for sessions using non-default isolation levels	{"sql": "SELECT\\n  s.session_id, s.login_name, s.program_name,\\n  CASE s.transaction_isolation_level\\n    WHEN 0 THEN 'Unspecified'\\n    WHEN 1 THEN 'ReadUncommitted'\\n    WHEN 2 THEN 'ReadCommitted'\\n    WHEN 3 THEN 'RepeatableRead'\\n    WHEN 4 THEN 'Serializable'\\n    WHEN 5 THEN 'Snapshot'\\n  END AS isolation_level,\\n  COUNT(*) OVER (PARTITION BY s.transaction_isolation_level) AS sessions_at_level,\\n  r.wait_type, r.blocking_session_id\\nFROM sys.dm_exec_sessions s\\nLEFT JOIN sys.dm_exec_requests r ON s.session_id = r.session_id\\nWHERE s.is_user_process = 1\\n  AND s.transaction_isolation_level NOT IN (2)\\nORDER BY s.transaction_isolation_level DESC"}	{"condition": "sessions running at Serializable (4) or Snapshot (5) isolation level", "description": "Non-default isolation levels require different locking strategies and may produce different execution plans"}	null	2026-02-23 20:18:31.389751
1450	sqlserver	query	Check for plan cache fragmentation from isolation level variation	{"sql": "SELECT\\n  pa_set.value AS set_options_value,\\n  COUNT(*) AS plans_with_setting,\\n  SUM(cp.usecounts) AS total_uses,\\n  SUM(CAST(cp.size_in_bytes AS BIGINT)) / 1024 / 1024 AS size_mb\\nFROM sys.dm_exec_cached_plans cp\\nCROSS APPLY sys.dm_exec_plan_attributes(cp.plan_handle) pa_set\\nWHERE pa_set.attribute = 'set_options'\\n  AND cp.objtype IN ('Proc', 'Prepared')\\nGROUP BY pa_set.value\\nHAVING COUNT(*) > 10\\nORDER BY plans_with_setting DESC"}	{"condition": "multiple set_options groups with > 10 plans each, indicating different session environments producing separate cached plan entries", "description": "Isolation level changes encoded in SET options create separate cache buckets, preventing plan reuse across sessions with different isolation levels"}	null	2026-02-23 20:18:31.389751
1451	sqlserver	query	Find non-deterministic scalar UDFs in the database	{"sql": "SELECT\\n  OBJECT_NAME(o.object_id) AS function_name,\\n  o.type_desc,\\n  sm.is_inlineable,\\n  OBJECTPROPERTY(o.object_id, 'IsDeterministic') AS is_deterministic,\\n  OBJECTPROPERTY(o.object_id, 'IsSystemVerified') AS is_system_verified,\\n  sm.definition\\nFROM sys.objects o\\nJOIN sys.sql_modules sm ON o.object_id = sm.object_id\\nWHERE o.type IN ('FN', 'IF')\\n  AND o.is_ms_shipped = 0\\n  AND OBJECTPROPERTY(o.object_id, 'IsDeterministic') = 0"}	{"condition": "non-deterministic scalar UDFs exist in the database, especially those calling GETDATE(), NEWID(), RAND(), or accessing tables", "description": "Non-deterministic UDFs cannot be inlined by the optimizer and force per-row execution in queries"}	null	2026-02-23 20:18:31.389752
1452	sqlserver	query	Find queries calling non-deterministic UDFs with high execution counts	{"sql": "SELECT TOP 15\\n  qs.execution_count,\\n  qs.total_worker_time / 1000 AS total_cpu_ms,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.plan_generation_num,\\n  SUBSTRING(st.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.execution_count > 50\\n  AND EXISTS (\\n    SELECT 1 FROM sys.objects o\\n    WHERE o.type = 'FN'\\n      AND o.is_ms_shipped = 0\\n      AND OBJECTPROPERTY(o.object_id, 'IsDeterministic') = 0\\n      AND st.text LIKE '%' + OBJECT_NAME(o.object_id) + '%'\\n  )\\nORDER BY qs.total_worker_time DESC"}	{"condition": "queries referencing non-deterministic UDFs with high total_worker_time and avg_cpu_ms", "description": "High CPU consumption in queries calling non-deterministic UDFs confirms per-row scalar function evaluation overhead"}	null	2026-02-23 20:18:31.389753
1453	sqlserver	query	Check if scalar UDF inlining is available and being used	{"sql": "SELECT\\n  d.compatibility_level,\\n  CASE WHEN d.compatibility_level >= 150 THEN 'Scalar UDF Inlining available (SQL 2019+)'\\n       ELSE 'Scalar UDF Inlining NOT available (requires compat 150+)' END AS inlining_status,\\n  (SELECT COUNT(*) FROM sys.sql_modules sm\\n   JOIN sys.objects o ON sm.object_id = o.object_id\\n   WHERE o.type = 'FN' AND o.is_ms_shipped = 0\\n     AND sm.is_inlineable = 1) AS inlineable_udfs,\\n  (SELECT COUNT(*) FROM sys.sql_modules sm\\n   JOIN sys.objects o ON sm.object_id = o.object_id\\n   WHERE o.type = 'FN' AND o.is_ms_shipped = 0\\n     AND (sm.is_inlineable = 0 OR sm.is_inlineable IS NULL)) AS non_inlineable_udfs\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "compatibility_level < 150 or non_inlineable_udfs > 0", "description": "Scalar UDF inlining is unavailable (pre-SQL 2019) or non-deterministic UDFs are not inlineable, forcing per-row evaluation and preventing plan optimization"}	null	2026-02-23 20:18:31.389754
1454	sqlserver	query	Check for high login failure rate and connection timeouts	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec'\\n     AND object_name LIKE '%General Statistics%') AS logins_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logouts/sec'\\n     AND object_name LIKE '%General Statistics%') AS logouts_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Connection Resets/sec'\\n     AND object_name LIKE '%General Statistics%') AS connection_resets_sec,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections\\n   WHERE net_transport = 'TCP') AS tcp_connections,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests\\n   WHERE wait_type LIKE 'PREEMPTIVE_OS_AUTHENTICATIONOPS'\\n     OR wait_type = 'PREEMPTIVE_OS_ACCEPTSECURITYCONTEXT') AS auth_waiting"}	{"condition": "logins_sec significantly higher than logouts_sec, or auth_waiting > 0 indicating authentication attempts stacking up", "description": "Login rate exceeding logout rate suggests connection attempts that never complete, consistent with silent firewall drops forcing retries"}	null	2026-02-23 20:18:31.389754
1455	sqlserver	query	Check for failed login attempts from specific client addresses	{"sql": "SELECT\\n  client_net_address,\\n  COUNT(*) AS connection_count,\\n  MIN(connect_time) AS earliest_connection,\\n  MAX(connect_time) AS latest_connection,\\n  AVG(DATEDIFF(SECOND, connect_time, GETDATE())) AS avg_connection_age_sec\\nFROM sys.dm_exec_connections\\nGROUP BY client_net_address\\nORDER BY connection_count DESC"}	{"condition": "client addresses with many very young connections (avg_connection_age_sec < 60) and high count", "description": "Clusters of new connections from specific clients indicate retry storms from blocked network paths"}	null	2026-02-23 20:18:31.389755
1456	sqlserver	query	Check SQL Server error log for login-related errors	{"sql": "EXEC sp_readerrorlog 0, 1, N'Login failed';\\nSELECT * FROM sys.dm_os_ring_buffers\\nWHERE ring_buffer_type = 'RING_BUFFER_CONNECTIVITY'\\n  AND record LIKE '%LoginTimers%'\\nORDER BY timestamp DESC"}	{"condition": "clusters of login failures from specific client IPs, or connectivity ring buffer entries showing connection timeouts", "description": "Login failures and connectivity ring buffer records confirm that some connection attempts are failing, likely due to network-level blocking"}	null	2026-02-23 20:18:31.389756
1483	sqlserver	query	Check system_health XEvent session for recent deadlock graphs	{"sql": "SELECT TOP 20\\n  xed.value('@timestamp', 'datetime2') AS deadlock_time,\\n  xed.query('.') AS deadlock_graph\\nFROM (\\n  SELECT CAST(target_data AS XML) AS target_data\\n  FROM sys.dm_xe_session_targets st\\n  JOIN sys.dm_xe_sessions s ON s.address = st.event_session_address\\n  WHERE s.name = 'system_health'\\n    AND st.target_name = 'ring_buffer'\\n) AS data\\nCROSS APPLY target_data.nodes('RingBufferTarget/event[@name=\\"xml_deadlock_report\\"]') AS xed(xed)\\nORDER BY xed.value('@timestamp', 'datetime2') DESC"}	{"condition": "multiple deadlock events within the last hour", "description": "Frequent deadlocks captured in system_health confirm the lock monitor is running at elevated frequency (from default 5s down to sub-second intervals), consuming additional CPU"}	null	2026-02-23 20:18:31.389772
1457	sqlserver	query	Find top CPU-consuming queries with plan details	{"sql": "SELECT TOP 20\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.total_worker_time AS total_cpu_us,\\n  qs.execution_count,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text,\\n  qp.query_plan\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nORDER BY qs.total_worker_time DESC"}	{"condition": "queries with avg_cpu_us > 1000000 (1 second) or avg_logical_reads > 100000", "description": "High average CPU time or logical reads per execution indicates suboptimal query plans"}	null	2026-02-23 20:18:31.389756
3361	postgresql	query	Find long-running active queries	{"sql": "SELECT pid, usename, application_name, client_addr, state, query_start, now() - query_start AS query_duration, left(query, 200) AS query_text FROM pg_stat_activity WHERE state = 'active' AND backend_type = 'client backend' AND now() - query_start > :threshold_interval::interval ORDER BY query_duration DESC"}	{"condition": "row_count > 0", "description": "Active queries running longer than threshold"}	{"threshold_interval": "60 seconds"}	2026-02-25 00:28:52.405273
2144	sqlserver	query	Check tempdb buffer pool consumption	{"sql": "SELECT\\n  COUNT(*) AS tempdb_pages_in_buffer,\\n  COUNT(*) * 8 / 1024 AS tempdb_buffer_mb,\\n  (SELECT COUNT(*) FROM sys.dm_os_buffer_descriptors) AS total_buffer_pages,\\n  CAST(COUNT(*) * 100.0 / NULLIF((SELECT COUNT(*) FROM sys.dm_os_buffer_descriptors), 0) AS DECIMAL(5,2)) AS tempdb_buffer_pct\\nFROM sys.dm_os_buffer_descriptors\\nWHERE database_id = 2"}	{"condition": "tempdb_buffer_pct > 20", "description": "tempdb consuming more than 20% of buffer pool indicates excessive temp table usage"}	null	2026-02-23 20:18:31.389757
1465	sqlserver	query	Check statistics freshness and modification counters	{"sql": "SELECT TOP 30\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  s.auto_created,\\n  sp.last_updated,\\n  sp.rows AS stat_rows,\\n  sp.rows_sampled,\\n  sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(sp.modification_counter AS FLOAT) / sp.rows * 100\\n    ELSE 0 END AS pct_modified,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > 0\\n  AND OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\nORDER BY sp.modification_counter DESC"}	{"condition": "pct_modified > 20 OR days_since_update > 7 with modification_counter > 1000", "description": "Statistics with >20% row modifications or not updated in over 7 days with significant modifications are likely stale"}	null	2026-02-23 20:18:31.389762
6451	oracle	query	ora-check-unarchived-redo-logs	{"sql": "SELECT group#, thread#, sequence#, bytes/1024/1024 AS size_mb, status, archived FROM v$log WHERE archived = 'NO' AND status != 'CURRENT' ORDER BY sequence#"}	{"condition": "row_count > 0", "description": "Redo log groups that are not archived and not current indicate potential overwrite risk or archiver lag"}	\N	2026-02-28 12:19:19.580455
1458	sqlserver	query	Check for plans with warnings and expensive operators	{"sql": "SELECT TOP 20\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.execution_count,\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\"])', 'int') AS table_scan_count,\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') AS ci_scan_count,\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Key Lookup\\"])', 'int') AS key_lookup_count,\\n  qp.query_plan.value('count(//Warnings)', 'int') AS warning_count,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_worker_time / qs.execution_count > 100000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "table_scan_count > 0 OR key_lookup_count > 0 OR warning_count > 0", "description": "Plans containing table scans, key lookups, or optimizer warnings indicate suboptimal plan choices"}	null	2026-02-23 20:18:31.389758
1459	sqlserver	query	Find high-frequency expensive queries	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_worker_time / 1000 AS total_cpu_ms,\\n  qs.total_worker_time / qs.execution_count / 1000 AS avg_cpu_ms,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.creation_time,\\n  DATEDIFF(MINUTE, qs.creation_time, GETDATE()) AS plan_age_min,\\n  qs.execution_count / NULLIF(DATEDIFF(MINUTE, qs.creation_time, GETDATE()), 0) AS exec_per_min,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.execution_count > 1000\\n  AND qs.total_worker_time / qs.execution_count > 10000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "exec_per_min > 10 AND avg_cpu_ms > 10", "description": "Queries executing more than 10 times per minute with >10ms CPU each are significant CPU consumers"}	null	2026-02-23 20:18:31.389758
1461	sqlserver	query	Find queries with highest logical reads per execution	{"sql": "SELECT TOP 20\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.total_logical_reads,\\n  qs.execution_count,\\n  qs.total_worker_time / qs.execution_count / 1000 AS avg_cpu_ms,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text,\\n  qp.query_plan\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_logical_reads / qs.execution_count > 10000\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "avg_logical_reads > 10000 per execution", "description": "Queries with >10K logical reads per execution are likely scanning large portions of tables"}	null	2026-02-23 20:18:31.389759
1462	sqlserver	query	Check for scan-heavy operations in top queries	{"sql": "SELECT\\n  DB_NAME(st.dbid) AS database_name,\\n  OBJECT_NAME(st.objectid, st.dbid) AS object_name,\\n  qs.total_logical_reads / qs.execution_count AS avg_reads,\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\"])', 'int') AS table_scans,\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') AS ci_scans,\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Index Scan\\"])', 'int') AS nc_scans\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_logical_reads / qs.execution_count > 10000\\n  AND qs.execution_count > 10\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "table_scans > 0 OR ci_scans > 0 on tables with avg_reads > 10000", "description": "Table scans or clustered index scans on large tables confirm full-scan behavior causing excessive logical reads"}	null	2026-02-23 20:18:31.38976
1463	sqlserver	query	Check missing index recommendations with impact scores	{"sql": "SELECT TOP 20\\n  mid.statement AS table_name,\\n  mid.equality_columns,\\n  mid.inequality_columns,\\n  mid.included_columns,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure,\\n  migs.user_seeks,\\n  migs.user_scans,\\n  migs.avg_total_user_cost,\\n  migs.avg_user_impact\\nFROM sys.dm_db_missing_index_groups mig\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nJOIN sys.dm_db_missing_index_details mid ON mig.index_handle = mid.index_handle\\nWHERE migs.avg_user_impact > 50\\nORDER BY improvement_measure DESC"}	{"condition": "improvement_measure > 100000 AND avg_user_impact > 50", "description": "High-impact missing index recommendations indicate queries that would benefit significantly from new indexes"}	null	2026-02-23 20:18:31.389761
1464	sqlserver	query	Cross-reference with actual table scan activity on those tables	{"sql": "SELECT\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  ios.index_id,\\n  i.name AS index_name,\\n  i.type_desc,\\n  ius.user_scans,\\n  ius.user_seeks,\\n  ius.user_lookups,\\n  ios.leaf_insert_count,\\n  ios.leaf_update_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius ON ios.object_id = ius.object_id\\n  AND ios.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.index_id IN (0, 1)\\n  AND ius.user_scans > 100\\nORDER BY ius.user_scans DESC"}	{"condition": "user_scans >> user_seeks on the clustered index or heap, confirming scans dominate access patterns", "description": "Tables with high scan counts relative to seeks confirm that queries are scanning because appropriate indexes do not exist"}	null	2026-02-23 20:18:31.389761
1494	sqlserver	query	Check background task wait types	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CHECKPOINT_QUEUE', 'CHKPT', 'WRITELOG',\\n  'LOGBUFFER', 'GHOST_CLEANUP', 'LAZY_WRITER_SLEEP',\\n  'SLEEP_BPOOL_FLUSH', 'IO_COMPLETION', 'PAGEIOLATCH_SH',\\n  'PAGEIOLATCH_EX')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "CHKPT or CHECKPOINT_QUEUE with high wait_time_ms, or WRITELOG with high avg_wait_ms", "description": "Elevated checkpoint and log flush waits confirm that background maintenance activities are creating significant I/O pressure"}	null	2026-02-23 20:18:31.389779
2283	sqlserver	query	Check for threads in preemptive or non-yielding states	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_os_workers WHERE is_preemptive = 1) AS preemptive_workers,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers WHERE state = 'SUSPENDED') AS suspended_workers,\\n  (SELECT COUNT(*) FROM sys.dm_os_schedulers\\n   WHERE scheduler_id < 255 AND is_online = 1\\n     AND active_workers_count > current_tasks_count) AS overallocated_schedulers,\\n  (SELECT SUM(yield_count) FROM sys.dm_os_schedulers\\n   WHERE scheduler_id < 255) AS total_yields,\\n  (SELECT SUM(context_switches_count) FROM sys.dm_os_schedulers\\n   WHERE scheduler_id < 255) AS total_context_switches"}	{"condition": "preemptive_workers > 10 OR overallocated_schedulers > 0", "description": "Elevated preemptive workers or scheduler overallocation indicates threads not being released back to the pool efficiently"}	null	2026-02-23 20:18:31.390279
1466	sqlserver	query	Check for cardinality estimation errors in cached plans	{"sql": "SELECT TOP 15\\n  qs.total_worker_time / qs.execution_count / 1000 AS avg_cpu_ms,\\n  qs.total_logical_reads / qs.execution_count AS avg_reads,\\n  qs.execution_count,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text,\\n  qp.query_plan.value('(//RelOp/@EstimateRows)[1]', 'float') AS estimated_rows,\\n  qp.query_plan.value('(//RelOp/@ActualRows)[1]', 'float') AS actual_rows\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_worker_time / qs.execution_count > 100000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "estimated_rows differs from actual_rows by more than 10x (either direction)", "description": "Large discrepancies between estimated and actual rows confirm the optimizer is using stale statistics, leading to plan choices based on wrong cardinality"}	null	2026-02-23 20:18:31.389763
1467	sqlserver	query	Find procedures with high variance in execution times	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ps.object_id) AS procedure_name,\\n  ps.execution_count,\\n  ps.min_worker_time / 1000 AS min_cpu_ms,\\n  ps.max_worker_time / 1000 AS max_cpu_ms,\\n  ps.total_worker_time / ps.execution_count / 1000 AS avg_cpu_ms,\\n  ps.min_logical_reads AS min_reads,\\n  ps.max_logical_reads AS max_reads,\\n  ps.total_logical_reads / ps.execution_count AS avg_reads,\\n  CASE WHEN ps.min_worker_time > 0\\n    THEN ps.max_worker_time / ps.min_worker_time\\n    ELSE 0 END AS cpu_variance_ratio\\nFROM sys.dm_exec_procedure_stats ps\\nWHERE ps.execution_count > 10\\n  AND ps.max_worker_time > ps.min_worker_time * 10\\nORDER BY (ps.max_worker_time - ps.min_worker_time) DESC"}	{"condition": "cpu_variance_ratio > 100 (max CPU is 100x+ the minimum)", "description": "Extreme variance between best and worst execution times for the same procedure strongly suggests parameter sniffing"}	null	2026-02-23 20:18:31.389763
1468	sqlserver	query	Check Query Store for plan regression on specific queries	{"sql": "SELECT TOP 20\\n  q.query_id,\\n  qt.query_sql_text,\\n  p.plan_id,\\n  rs.avg_duration / 1000 AS avg_duration_ms,\\n  rs.avg_cpu_time / 1000 AS avg_cpu_ms,\\n  rs.avg_logical_io_reads AS avg_reads,\\n  rs.count_executions,\\n  p.is_forced_plan,\\n  p.force_failure_count\\nFROM sys.query_store_query q\\nJOIN sys.query_store_query_text qt ON q.query_text_id = qt.query_text_id\\nJOIN sys.query_store_plan p ON q.query_id = p.query_id\\nJOIN sys.query_store_runtime_stats rs ON p.plan_id = rs.plan_id\\nWHERE q.query_id IN (\\n  SELECT q2.query_id FROM sys.query_store_plan p2\\n  JOIN sys.query_store_query q2 ON p2.query_id = q2.query_id\\n  GROUP BY q2.query_id HAVING COUNT(DISTINCT p2.plan_id) > 1\\n)\\nORDER BY rs.avg_cpu_time DESC"}	{"condition": "multiple plan_ids for the same query_id with vastly different avg_cpu_ms or avg_reads", "description": "Multiple plans for the same query with different performance profiles confirms parameter sniffing — the optimizer chose different plans based on different parameter values"}	null	2026-02-23 20:18:31.389764
1470	sqlserver	query	Check for key lookups adding excessive I/O to seek operations	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name,\\n  ios.singleton_lookup_count AS key_lookups,\\n  ios.range_scan_count AS range_scans,\\n  ios.row_lock_count + ios.page_lock_count AS total_locks,\\n  ius.user_seeks,\\n  ius.user_lookups\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nJOIN sys.dm_db_index_usage_stats ius ON ios.object_id = ius.object_id\\n  AND ios.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.index_id > 1\\n  AND ius.user_lookups > 10000\\nORDER BY ius.user_lookups DESC"}	{"condition": "user_lookups > 10000 indicating frequent key lookups back to the clustered index", "description": "High key lookup counts mean the non-clustered index is being used but not covering the query, requiring expensive bookmark lookups back to the base table"}	null	2026-02-23 20:18:31.389765
1471	sqlserver	query	Check CXPACKET and CXCONSUMER wait statistics	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  signal_wait_time_ms,\\n  100.0 * wait_time_ms / SUM(wait_time_ms) OVER () AS pct_of_total_waits\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT', 'CXSYNC_CONSUMER',\\n  'EXECSYNC', 'EXCHANGE', 'THREADPOOL')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "CXPACKET or CXCONSUMER is in the top 3 waits by time, or pct_of_total_waits > 20", "description": "CXPACKET/CXCONSUMER dominating wait stats indicates excessive parallelism overhead — threads are waiting for other parallel threads to complete"}	null	2026-02-23 20:18:31.389766
1484	sqlserver	query	Check for recent sort and hash spills via query stats	{"sql": "SELECT TOP 20\\n  qs.total_spills,\\n  qs.total_spills / qs.execution_count AS avg_spills_per_exec,\\n  qs.total_worker_time / qs.execution_count / 1000 AS avg_cpu_ms,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.total_grant_kb / qs.execution_count AS avg_grant_kb,\\n  qs.execution_count,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_spills > 0\\nORDER BY qs.total_spills DESC"}	{"condition": "total_spills > 1000 or avg_spills_per_exec > 1", "description": "Queries with frequent spills are writing intermediate results to tempdb instead of processing in memory"}	null	2026-02-23 20:18:31.389773
1495	sqlserver	query	Check recovery interval and indirect checkpoint settings	{"sql": "SELECT\\n  name AS database_name,\\n  target_recovery_time_in_seconds,\\n  log_reuse_wait_desc,\\n  is_auto_update_stats_on,\\n  is_auto_update_stats_async_on\\nFROM sys.databases\\nWHERE database_id > 4\\nUNION ALL\\nSELECT\\n  'Server: recovery interval' AS database_name,\\n  CAST(value_in_use AS INT) AS target_recovery_time_in_seconds,\\n  NULL, NULL, NULL\\nFROM sys.configurations\\nWHERE name = 'recovery interval (min)'"}	{"condition": "target_recovery_time_in_seconds = 0 (automatic checkpoint) with high page writes, or very low target causing aggressive checkpoint", "description": "Default automatic checkpoint or aggressive indirect checkpoint settings can cause frequent flushing that impacts workload performance"}	null	2026-02-23 20:18:31.38978
2279	sqlserver	query	Find long-running queries consuming worker threads	{"sql": "SELECT\\n  r.session_id,\\n  r.start_time,\\n  DATEDIFF(MINUTE, r.start_time, GETDATE()) AS running_minutes,\\n  r.status, r.command,\\n  r.wait_type, r.wait_time,\\n  r.cpu_time / 1000 AS cpu_sec,\\n  r.total_elapsed_time / 1000 AS elapsed_sec,\\n  r.reads, r.writes,\\n  s.program_name, s.host_name, s.login_name,\\n  SUBSTRING(st.text, (r.statement_start_offset / 2) + 1,\\n    (CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE r.statement_end_offset END - r.statement_start_offset) / 2 + 1) AS current_statement\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE r.session_id > 50\\n  AND DATEDIFF(MINUTE, r.start_time, GETDATE()) > 30\\nORDER BY r.start_time ASC"}	{"condition": "row_count > 0 with running_minutes > 30", "description": "Queries running for over 30 minutes are potential orphans consuming worker threads"}	null	2026-02-23 20:18:31.390277
1474	sqlserver	query	Check for CONVERT_IMPLICIT in plan XML causing scans	{"sql": "SELECT TOP 15\\n  qs.total_worker_time / qs.execution_count / 1000 AS avg_cpu_ms,\\n  qs.total_logical_reads / qs.execution_count AS avg_reads,\\n  qp.query_plan.value('(//ScalarOperator[contains(@ScalarString,\\"CONVERT_IMPLICIT\\")]/@ScalarString)[1]', 'nvarchar(500)') AS implicit_convert_expr,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//ScalarOperator[contains(@ScalarString,\\"CONVERT_IMPLICIT\\")]') = 1\\n  AND qs.total_worker_time / qs.execution_count > 50000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "CONVERT_IMPLICIT expressions present in high-CPU queries, especially on indexed columns", "description": "CONVERT_IMPLICIT on indexed columns forces the optimizer to scan instead of seek, dramatically increasing logical reads and CPU"}	null	2026-02-23 20:18:31.389767
1475	sqlserver	query	Find high-cost queries that reference scalar or MSTVF functions	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(o.object_id) AS function_name,\\n  o.type_desc,\\n  fs.execution_count,\\n  fs.total_worker_time / 1000 AS total_cpu_ms,\\n  fs.total_worker_time / fs.execution_count / 1000 AS avg_cpu_ms,\\n  fs.total_logical_reads / fs.execution_count AS avg_reads,\\n  fs.total_elapsed_time / fs.execution_count / 1000 AS avg_elapsed_ms\\nFROM sys.dm_exec_function_stats fs\\nJOIN sys.objects o ON fs.object_id = o.object_id\\nWHERE o.type IN ('FN', 'IF', 'TF')\\n  AND fs.execution_count > 100\\nORDER BY fs.total_worker_time DESC"}	{"condition": "scalar functions (FN) or table-valued functions (TF) with high total_cpu_ms and high execution_count", "description": "Scalar UDFs and MSTVFs with high CPU usage indicate row-by-row execution patterns"}	null	2026-02-23 20:18:31.389767
3481	postgresql	query	Find long-running backup sessions	{"sql": "SELECT pid, usename, application_name, backend_start, state, now() - backend_start AS duration FROM pg_stat_activity WHERE backend_type = 'walsender' AND application_name LIKE '%backup%' AND now() - backend_start > :threshold_interval::interval"}	{"condition": "row_count > 0", "description": "Backup session running longer than expected"}	{"threshold_interval": "4 hours"}	2026-02-25 00:28:52.405273
1476	sqlserver	query	Check for UDF references in top CPU-consuming queries	{"sql": "SELECT TOP 15\\n  qs.total_worker_time / qs.execution_count / 1000 AS avg_cpu_ms,\\n  qs.execution_count,\\n  qp.query_plan.value('count(//RelOp[contains(@LogicalOp,\\"UDX\\") or @PhysicalOp=\\"Table-valued function\\"])', 'int') AS udf_operator_count,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_worker_time / qs.execution_count > 100000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "udf_operator_count > 0 in high-CPU queries, or query_text contains dbo.fn_ patterns", "description": "UDF operators in expensive query plans confirm that scalar/MSTVF functions are contributing to CPU overhead"}	null	2026-02-23 20:18:31.389768
1477	sqlserver	query	Check for active cursors and cursor usage patterns	{"sql": "SELECT\\n  c.name AS cursor_name,\\n  c.properties AS cursor_properties,\\n  c.creation_time,\\n  c.is_open,\\n  c.fetch_status,\\n  c.worker_time / 1000 AS cursor_cpu_ms,\\n  c.reads AS cursor_reads,\\n  c.writes AS cursor_writes,\\n  s.login_name,\\n  s.host_name,\\n  st.text AS cursor_sql\\nFROM sys.dm_exec_cursors(0) c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nCROSS APPLY sys.dm_exec_sql_text(c.sql_handle) st\\nWHERE c.is_open = 1\\nORDER BY c.worker_time DESC"}	{"condition": "active open cursors with high worker_time or reads", "description": "Open cursors with significant CPU time or reads indicate row-by-row processing patterns"}	null	2026-02-23 20:18:31.389769
1478	sqlserver	query	Check for cursor-related wait types and high fetch counts	{"sql": "SELECT\\n  pc.counter_name,\\n  pc.cntr_value\\nFROM sys.dm_os_performance_counters pc\\nWHERE pc.object_name LIKE '%Cursor Manager%'\\n  AND pc.cntr_value > 0\\nUNION ALL\\nSELECT\\n  'Active cursor count' AS counter_name,\\n  COUNT(*) AS cntr_value\\nFROM sys.dm_exec_cursors(0)\\nWHERE is_open = 1\\nUNION ALL\\nSELECT\\n  'SP with CURSOR keyword' AS counter_name,\\n  COUNT(*) AS cntr_value\\nFROM sys.sql_modules m\\nWHERE m.definition LIKE '%DECLARE%CURSOR%'\\n  AND m.definition LIKE '%FETCH%NEXT%'"}	{"condition": "high cursor counts or stored procedures containing DECLARE CURSOR / FETCH NEXT patterns", "description": "Active cursors and cursor-heavy stored procedure code confirm row-by-row processing patterns that should be converted to set-based operations"}	null	2026-02-23 20:18:31.389769
1480	sqlserver	query	Check lock-related wait statistics	{"sql": "SELECT wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  100.0 * wait_time_ms / SUM(wait_time_ms) OVER () AS pct_of_total\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type LIKE 'LCK_%'\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "LCK_M_X, LCK_M_U, or LCK_M_S waits with high total time or pct_of_total > 10", "description": "Lock wait types dominating wait statistics confirms systemic lock contention across the workload"}	null	2026-02-23 20:18:31.389771
1481	sqlserver	query	Check lock escalation events and contention hotspots	{"sql": "SELECT\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  ios.index_id,\\n  ios.row_lock_count,\\n  ios.row_lock_wait_count,\\n  ios.row_lock_wait_in_ms,\\n  ios.page_lock_count,\\n  ios.page_lock_wait_count,\\n  ios.page_lock_wait_in_ms,\\n  ios.index_lock_promotion_attempt_count AS lock_escalation_attempts,\\n  ios.index_lock_promotion_count AS lock_escalations\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nWHERE ios.row_lock_wait_count > 100\\n  OR ios.page_lock_wait_count > 100\\n  OR ios.index_lock_promotion_count > 0\\nORDER BY ios.row_lock_wait_in_ms + ios.page_lock_wait_in_ms DESC"}	{"condition": "high row_lock_wait_count or lock_escalation_attempts on specific tables", "description": "Tables with high lock wait counts and lock escalation events are contention hotspots driving CPU overhead"}	null	2026-02-23 20:18:31.389771
1482	sqlserver	query	Check deadlock frequency via performance counters	{"sql": "SELECT\\n  pc.counter_name,\\n  pc.cntr_value\\nFROM sys.dm_os_performance_counters pc\\nWHERE pc.counter_name IN ('Number of Deadlocks/sec', 'Lock Timeouts/sec',\\n  'Lock Wait Time (ms)', 'Lock Waits/sec')\\n  AND pc.object_name LIKE '%Locks%'\\nUNION ALL\\nSELECT\\n  'Total deadlocks since startup' AS counter_name,\\n  cntr_value\\nFROM sys.dm_os_performance_counters\\nWHERE counter_name = 'Number of Deadlocks/sec'\\n  AND instance_name = '_Total'"}	{"condition": "Number of Deadlocks/sec > 0 (cumulative counter) indicating regular deadlock occurrences", "description": "Non-zero deadlock counters indicate the lock monitor is actively detecting and resolving deadlocks"}	null	2026-02-23 20:18:31.389772
6353	oracle	query	ora_check_service_registration	{"sql": "SELECT name, network_name, creation_date, pdb FROM dba_services WHERE name NOT LIKE 'SYS$%' ORDER BY name"}	{"condition": "row_count > 0", "description": "Verify database services are registered and available for RMAN connections"}	\N	2026-02-28 12:19:19.580455
1485	sqlserver	query	Check memory grants and pending memory grant requests	{"sql": "SELECT\\n  mg.session_id,\\n  mg.requested_memory_kb,\\n  mg.granted_memory_kb,\\n  mg.required_memory_kb,\\n  mg.used_memory_kb,\\n  mg.max_used_memory_kb,\\n  mg.ideal_memory_kb,\\n  mg.is_small,\\n  mg.timeout_sec,\\n  mg.grant_time,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1,\\n    ((CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE r.statement_end_offset END - r.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_memory_grants mg\\nJOIN sys.dm_exec_requests r ON mg.session_id = r.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE mg.granted_memory_kb < mg.ideal_memory_kb\\n  OR mg.grant_time IS NULL\\nORDER BY mg.ideal_memory_kb DESC"}	{"condition": "granted_memory_kb < ideal_memory_kb, or grant_time IS NULL (waiting for memory grant)", "description": "Queries receiving less memory than ideal, or waiting for memory grants, will spill sort/hash operations to tempdb"}	null	2026-02-23 20:18:31.389774
1486	sqlserver	query	Check buffer pool and memory clerk pressure indicators	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page life expectancy'\\n     AND object_name LIKE '%Buffer Manager%') AS page_life_expectancy_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Buffer cache hit ratio'\\n     AND object_name LIKE '%Buffer Manager%') AS buffer_cache_hit_ratio,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Lazy writes/sec'\\n     AND object_name LIKE '%Buffer Manager%') AS lazy_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Free list stalls/sec'\\n     AND object_name LIKE '%Buffer Manager%') AS free_list_stalls_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Memory Grants Pending'\\n     AND object_name LIKE '%Memory Manager%') AS memory_grants_pending"}	{"condition": "page_life_expectancy_sec < 300 OR lazy_writes_sec > 0 OR free_list_stalls_sec > 0 OR memory_grants_pending > 0", "description": "Low PLE (<300s), active lazy writes, free list stalls, or pending memory grants indicate buffer pool pressure"}	null	2026-02-23 20:18:31.389774
1488	sqlserver	query	Check RESOURCE_SEMAPHORE and memory-related waits	{"sql": "SELECT wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('RESOURCE_SEMAPHORE', 'RESOURCE_SEMAPHORE_QUERY_COMPILE',\\n  'CMEMTHREAD', 'SOS_RESERVEDMEMBLOCKLIST')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "RESOURCE_SEMAPHORE waits present with waiting_tasks_count > 0", "description": "RESOURCE_SEMAPHORE waits mean queries are queuing for memory grants — a definitive indicator of memory starvation causing performance degradation"}	null	2026-02-23 20:18:31.389776
1489	sqlserver	query	Check index fragmentation levels for user tables	{"sql": "SELECT TOP 30\\n  DB_NAME() AS database_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.type_desc,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.avg_page_space_used_in_percent,\\n  ips.fragment_count,\\n  ips.avg_fragment_size_in_pages\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.avg_fragmentation_in_percent > 30\\n  AND ips.page_count > 1000\\n  AND OBJECTPROPERTY(ips.object_id, 'IsUserTable') = 1\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > 30 on indexes with > 1000 pages", "description": "Indexes with >30% fragmentation on substantial tables (>1000 pages / ~8MB) are causing excessive I/O for range scans and wasting buffer pool memory"}	null	2026-02-23 20:18:31.389776
1490	sqlserver	query	Cross-reference fragmented indexes with usage patterns	{"sql": "SELECT\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ius.user_seeks + ius.user_scans + ius.user_lookups AS total_reads,\\n  ius.user_updates AS total_writes,\\n  ius.user_scans AS scan_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius ON ips.object_id = ius.object_id\\n  AND ips.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE ips.avg_fragmentation_in_percent > 30\\n  AND ips.page_count > 1000\\n  AND ius.user_scans > 100\\nORDER BY ius.user_scans DESC"}	{"condition": "fragmented indexes with scan_count > 100 — high scan activity amplifies fragmentation impact", "description": "Fragmented indexes that are frequently scanned have the highest performance impact — each scan reads pages out of order, negating read-ahead benefits"}	null	2026-02-23 20:18:31.389777
1492	sqlserver	query	Check ghost cleanup process status and forwarded records in heaps	{"sql": "SELECT\\n  wait_type, waiting_tasks_count, wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('GHOST_CLEANUP', 'GHOST_CLEANUP_WAIT')\\nUNION ALL\\nSELECT\\n  'Forwarded Records/sec' AS wait_type,\\n  0 AS waiting_tasks_count,\\n  cntr_value AS wait_time_ms\\nFROM sys.dm_os_performance_counters\\nWHERE counter_name = 'Forwarded Records/sec'\\n  AND object_name LIKE '%Access Methods%'"}	{"condition": "GHOST_CLEANUP waits present, or Forwarded Records/sec > 0", "description": "Active ghost cleanup waits indicate the background task is busy cleaning deleted rows. Forwarded Records/sec > 0 confirms heap rows are being followed through forwarding pointers, adding I/O overhead."}	null	2026-02-23 20:18:31.389778
1514	sqlserver	query	Check log file usage percentage and growth rate	{"sql": "SELECT d.name,\\n  ls.total_log_size_in_bytes / 1048576 AS total_log_mb,\\n  ls.used_log_space_in_bytes / 1048576 AS used_log_mb,\\n  ls.used_log_space_in_percent AS log_used_pct,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_log_write_ms\\nFROM sys.dm_db_log_space_usage ls\\nJOIN sys.databases d ON ls.database_id = d.database_id\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\n  ON d.database_id = vfs.database_id\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE mf.type = 1\\n  AND d.database_id > 4"}	{"condition": "log_used_pct > 70 AND avg_log_write_ms > 2", "description": "High log utilization combined with slow writes — large transactions saturating the log"}	null	2026-02-23 20:18:31.38979
1493	sqlserver	query	Check checkpoint and lazy writer activity	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n     AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Lazy writes/sec'\\n     AND object_name LIKE '%Buffer Manager%') AS lazy_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Background writer pages/sec'\\n     AND object_name LIKE '%Buffer Manager%') AS bg_writer_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page writes/sec'\\n     AND object_name LIKE '%Buffer Manager%') AS page_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Log Flushes/sec'\\n     AND object_name LIKE '%Databases%'\\n     AND instance_name = '_Total') AS log_flushes_sec"}	{"condition": "checkpoint_pages_sec > 1000 OR lazy_writes_sec > 100 OR page_writes_sec > 5000", "description": "High checkpoint page flushing, active lazy writes, or excessive page writes indicate background maintenance consuming significant I/O and CPU"}	null	2026-02-23 20:18:31.389779
1644	sqlserver	query	Check PAGEIOLATCH and PAGELATCH waits during checkpoint activity	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  signal_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'PAGEIOLATCH_SH', 'PAGEIOLATCH_UP', 'PAGEIOLATCH_EX',\\n  'PAGELATCH_SH', 'PAGELATCH_UP', 'PAGELATCH_EX',\\n  'WRITELOG', 'CHKPT'\\n)\\nAND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH_EX avg_wait_ms > 15 OR PAGELATCH_UP avg_wait_ms > 5", "description": "Elevated exclusive page I/O latches or update page latches indicate checkpoint write contention"}	null	2026-02-23 20:18:31.389781
1496	sqlserver	query	Check transaction rate and log flush overhead	{"sql": "SELECT\\n  d.name AS database_name,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Transactions/sec'\\n     AND instance_name = d.name\\n     AND object_name LIKE '%Databases%') AS transactions_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Log Flushes/sec'\\n     AND instance_name = d.name\\n     AND object_name LIKE '%Databases%') AS log_flushes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Log Flush Wait Time'\\n     AND instance_name = d.name\\n     AND object_name LIKE '%Databases%') AS log_flush_wait_ms,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Log Bytes Flushed/sec'\\n     AND instance_name = d.name\\n     AND object_name LIKE '%Databases%') AS log_bytes_flushed_sec\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state = 0"}	{"condition": "log_flushes_sec approximately equals transactions_sec (indicating auto-commit, one flush per transaction)", "description": "When log flushes match transaction rate 1:1, each statement is auto-committed separately, causing unnecessary log flush overhead"}	null	2026-02-23 20:18:31.389781
1497	sqlserver	query	Check WRITELOG waits and long-running transactions	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('WRITELOG', 'LOGBUFFER', 'LOG_RATE_GOVERNOR')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "WRITELOG with high avg_wait_ms (> 2ms) or high total wait_time_ms", "description": "Elevated WRITELOG waits confirm that log flushing is a bottleneck, often caused by too many small transactions each requiring their own log flush"}	null	2026-02-23 20:18:31.389782
1499	sqlserver	query	Check log flush rate and WRITELOG waits	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Log Flushes/sec'\\n   AND object_name LIKE '%Databases%'\\n   AND instance_name = '_Total') AS log_flushes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Log Flush Wait Time'\\n   AND object_name LIKE '%Databases%'\\n   AND instance_name = '_Total') AS log_flush_wait_time_ms,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec'\\n   AND object_name LIKE '%SQL Statistics%') AS batch_requests_sec,\\n  ws.waiting_tasks_count AS writelog_waits,\\n  ws.wait_time_ms AS writelog_wait_time_ms,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_writelog_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'WRITELOG'"}	{"condition": "avg_writelog_ms > 2 AND log_flushes_sec > batch_requests_sec * 0.8", "description": "High log flush rate approaching batch request rate with elevated WRITELOG waits"}	null	2026-02-23 20:18:31.389783
1500	sqlserver	query	Check per-database log flush density	{"sql": "SELECT d.name,\\n  pc1.cntr_value AS log_flushes,\\n  pc2.cntr_value AS log_flush_waits_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_log_write_ms,\\n  vfs.num_of_writes AS log_writes\\nFROM sys.dm_os_performance_counters pc1\\nJOIN sys.dm_os_performance_counters pc2\\n  ON pc1.instance_name = pc2.instance_name\\nJOIN sys.databases d ON pc1.instance_name = d.name\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\n  ON vfs.database_id = d.database_id\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE pc1.counter_name = 'Log Flushes/sec'\\n  AND pc1.object_name LIKE '%Databases%'\\n  AND pc2.counter_name = 'Log Flush Wait Time'\\n  AND pc2.object_name LIKE '%Databases%'\\n  AND mf.type = 1\\n  AND d.database_id > 4\\nORDER BY pc1.cntr_value DESC"}	{"condition": "avg_log_write_ms > 2 on high-flush databases", "description": "Specific databases with high commit rates and slow log writes confirm flush bottleneck"}	null	2026-02-23 20:18:31.389784
1502	sqlserver	query	Confirm I/O contention on shared volume	{"sql": "SELECT d.name,\\n  vfs_log.io_stall_write_ms / NULLIF(vfs_log.num_of_writes, 0) AS avg_log_write_stall_ms,\\n  vfs_data.io_stall_read_ms / NULLIF(vfs_data.num_of_reads, 0) AS avg_data_read_stall_ms,\\n  vfs_data.io_stall_write_ms / NULLIF(vfs_data.num_of_writes, 0) AS avg_data_write_stall_ms\\nFROM sys.databases d\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs_log\\n  ON d.database_id = vfs_log.database_id\\nJOIN sys.master_files mf_log\\n  ON vfs_log.database_id = mf_log.database_id AND vfs_log.file_id = mf_log.file_id AND mf_log.type = 1\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs_data\\n  ON d.database_id = vfs_data.database_id\\nJOIN sys.master_files mf_data\\n  ON vfs_data.database_id = mf_data.database_id AND vfs_data.file_id = mf_data.file_id AND mf_data.type = 0\\nWHERE d.database_id > 4\\n  AND LEFT(mf_log.physical_name, 3) = LEFT(mf_data.physical_name, 3)\\n  AND vfs_log.io_stall_write_ms / NULLIF(vfs_log.num_of_writes, 0) > 5\\nORDER BY avg_log_write_stall_ms DESC"}	{"condition": "avg_log_write_stall_ms > 5", "description": "Elevated log write stalls on shared storage confirm I/O contention"}	null	2026-02-23 20:18:31.389784
3803	postgresql	config_check	Check maintenance resource allocation settings	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('maintenance_work_mem', 'autovacuum_work_mem', 'shared_buffers', 'max_parallel_maintenance_workers', 'temp_file_limit') ORDER BY name"}	{"condition": "row_count > 0", "description": "Review maintenance resource settings"}	\N	2026-02-25 00:28:52.405273
1503	sqlserver	query	Check log file write latency per database	{"sql": "SELECT d.name,\\n  mf.physical_name,\\n  vfs.num_of_writes AS log_writes,\\n  vfs.num_of_bytes_written / 1048576 AS log_mb_written,\\n  vfs.io_stall_write_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_log_write_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nJOIN sys.databases d ON vfs.database_id = d.database_id\\nWHERE mf.type = 1\\n  AND d.database_id > 4\\n  AND vfs.num_of_writes > 0\\nORDER BY avg_log_write_ms DESC"}	{"condition": "avg_log_write_ms > 5", "description": "Log write latency exceeding 5ms — target is < 1ms for OLTP workloads"}	null	2026-02-23 20:18:31.389785
1504	sqlserver	query	Check WRITELOG wait statistics	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'WRITELOG'"}	{"condition": "avg_wait_ms > 2 AND waiting_tasks_count > 1000", "description": "WRITELOG waits confirm log write bottleneck is impacting transactions"}	null	2026-02-23 20:18:31.389785
7149	oracle	query	ora_check_archive_processes_running	{"sql": "SELECT name, description, paddr FROM v$bgprocess WHERE name LIKE 'ARC%' AND paddr != '00'"}	{"condition": "row_count = 0", "description": "No running ARCn processes confirms archiving is not enabled"}	\N	2026-02-28 12:19:19.580455
1507	sqlserver	query	Check delayed durability settings and WRITELOG waits	{"sql": "SELECT d.name, d.delayed_durability_desc,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_log_write_ms,\\n  vfs.num_of_writes AS log_writes,\\n  pc.cntr_value AS log_flushes\\nFROM sys.databases d\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\n  ON d.database_id = vfs.database_id\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nLEFT JOIN sys.dm_os_performance_counters pc\\n  ON pc.instance_name = d.name\\n  AND pc.counter_name = 'Log Flushes/sec'\\n  AND pc.object_name LIKE '%Databases%'\\nWHERE mf.type = 1\\n  AND d.database_id > 4\\n  AND d.delayed_durability_desc = 'Disabled'\\nORDER BY vfs.num_of_writes DESC"}	{"condition": "delayed_durability_desc = 'Disabled' AND avg_log_write_ms > 2", "description": "All databases using synchronous flush with elevated log write latency"}	null	2026-02-23 20:18:31.389786
1508	sqlserver	query	Check WRITELOG as a top wait type	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  100.0 * wait_time_ms / NULLIF(SUM(wait_time_ms) OVER(), 0) AS pct_of_total_waits\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type NOT IN ('WAITFOR', 'LAZYWRITER_SLEEP', 'SQLTRACE_BUFFER_FLUSH',\\n  'CLR_AUTO_EVENT', 'CLR_MANUAL_EVENT', 'REQUEST_FOR_DEADLOCK_SEARCH',\\n  'SLEEP_TASK', 'SLEEP_SYSTEMTASK', 'BROKER_TO_FLUSH', 'CHECKPOINT_QUEUE',\\n  'XE_TIMER_EVENT', 'HADR_FILESTREAM_IOMGR_IOCOMPLETION',\\n  'SP_SERVER_DIAGNOSTICS_SLEEP', 'QDS_PERSIST_TASK_MAIN_LOOP_SLEEP',\\n  'QDS_CLEANUP_STALE_QUERIES_TASK_MAIN_LOOP_SLEEP',\\n  'DIRTY_PAGE_POLL', 'HADR_WORK_QUEUE')\\nORDER BY wait_time_ms DESC"}	{"condition": "WRITELOG in top 5 wait types by total wait time", "description": "WRITELOG is a dominant wait — synchronous flush is the bottleneck"}	null	2026-02-23 20:18:31.389787
1509	sqlserver	query	Check log manager latch contention	{"sql": "SELECT latch_class, waiting_requests_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_requests_count, 0) AS avg_wait_ms,\\n  max_wait_time_ms\\nFROM sys.dm_os_latch_stats\\nWHERE latch_class IN ('LOG_MANAGER', 'LOGFLUSHQ', 'FGCB_ADD_REMOVE',\\n  'LOGCACHE_ACCESS', 'LOG_BEGIN_IO')\\n  AND waiting_requests_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "waiting_requests_count > 1000 on LOG_MANAGER or related latches", "description": "Log allocation latch contention — multiple threads competing for log buffer slots"}	null	2026-02-23 20:18:31.389787
1510	sqlserver	query	Check spinlock contention on log structures	{"sql": "SELECT name, collisions, spins, spins_per_collision,\\n  sleep_time, backoffs\\nFROM sys.dm_os_spinlock_stats\\nWHERE name IN ('LOGCACHE_ACCESS', 'LOGFLUSHQ', 'SOS_SUSPEND_QUEUE')\\n  AND collisions > 0\\nORDER BY collisions DESC"}	{"condition": "collisions > 10000 or backoffs > 1000", "description": "High spinlock contention on log cache structures"}	null	2026-02-23 20:18:31.389788
1511	sqlserver	query	Check LOGBUFFER wait frequency and trend	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'LOGBUFFER'"}	{"condition": "waiting_tasks_count > 500", "description": "Significant number of LOGBUFFER waits — threads retrying to allocate log buffer space"}	null	2026-02-23 20:18:31.389789
1512	sqlserver	query	Correlate with log I/O throughput	{"sql": "SELECT d.name,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_log_write_ms,\\n  vfs.num_of_bytes_written / NULLIF(vfs.num_of_writes, 0) AS avg_write_size_bytes,\\n  vfs.num_of_writes AS total_log_writes\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nJOIN sys.databases d ON vfs.database_id = d.database_id\\nWHERE mf.type = 1\\n  AND d.database_id > 4\\n  AND vfs.num_of_writes > 0\\nORDER BY vfs.io_stall_write_ms DESC"}	{"condition": "avg_log_write_ms > 3 on databases with high write volume", "description": "Slow log writes causing buffer to fill up, forcing allocation retries"}	null	2026-02-23 20:18:31.389789
1513	sqlserver	query	Find active transactions with high log usage	{"sql": "SELECT t.transaction_id,\\n  t.name AS transaction_name,\\n  t.transaction_begin_time,\\n  DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS duration_sec,\\n  dt.database_transaction_log_bytes_used / 1048576 AS log_mb_used,\\n  dt.database_transaction_log_bytes_reserved / 1048576 AS log_mb_reserved,\\n  dt.database_transaction_log_record_count AS log_records,\\n  s.program_name, s.host_name,\\n  s.session_id\\nFROM sys.dm_tran_active_transactions t\\nJOIN sys.dm_tran_database_transactions dt ON t.transaction_id = dt.transaction_id\\nJOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_sessions s ON st.session_id = s.session_id\\nWHERE dt.database_transaction_log_bytes_used > :threshold_bytes\\n  AND s.is_user_process = 1\\nORDER BY dt.database_transaction_log_bytes_used DESC"}	{"condition": "log_mb_used > 100", "description": "Active transactions consuming > 100MB of log space"}	{"threshold_bytes": 104857600}	2026-02-23 20:18:31.38979
1515	sqlserver	query	Check log file size, growth settings, and autogrowth events	{"sql": "SELECT d.name,\\n  mf.physical_name,\\n  mf.size * 8 / 1024 AS log_size_mb,\\n  mf.max_size,\\n  CASE mf.is_percent_growth\\n    WHEN 1 THEN CAST(mf.growth AS VARCHAR) + '%'\\n    ELSE CAST(mf.growth * 8 / 1024 AS VARCHAR) + ' MB'\\n  END AS growth_setting,\\n  mf.is_percent_growth\\nFROM sys.databases d\\nJOIN sys.master_files mf\\n  ON d.database_id = mf.database_id\\nWHERE mf.type = 1\\n  AND d.database_id > 4\\nORDER BY mf.size ASC"}	{"condition": "log_size_mb < 512 or is_percent_growth = 1", "description": "Small log files or percentage-based growth — likely to autogrow frequently under load"}	null	2026-02-23 20:18:31.389791
1544	sqlserver	query	Check AUTO_CREATE_STATISTICS setting across databases	{"sql": "SELECT\\n  d.name AS database_name,\\n  d.is_auto_create_stats_on,\\n  d.is_auto_update_stats_on,\\n  d.is_auto_update_stats_async_on,\\n  d.is_auto_create_stats_incremental_on\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state = 0\\n  AND (d.is_auto_create_stats_on = 0 OR d.is_auto_update_stats_on = 0)"}	{"condition": "is_auto_create_stats_on = 0 on any user database", "description": "AUTO_CREATE_STATISTICS disabled — optimizer cannot create statistics on unindexed columns used in predicates"}	null	2026-02-23 20:18:31.389807
1516	sqlserver	query	Check for log file autogrowth events	{"sql": "SELECT d.name,\\n  ls.used_log_space_in_percent AS log_used_pct,\\n  ls.total_log_size_in_bytes / 1048576 AS total_log_mb,\\n  ls.used_log_space_in_bytes / 1048576 AS used_log_mb,\\n  mf.growth * 8 / 1024 AS growth_mb\\nFROM sys.dm_db_log_space_usage ls\\nJOIN sys.databases d ON ls.database_id = d.database_id\\nJOIN sys.master_files mf\\n  ON d.database_id = mf.database_id AND mf.type = 1\\nWHERE d.database_id > 4\\n  AND ls.used_log_space_in_percent > 70\\nORDER BY ls.used_log_space_in_percent DESC"}	{"condition": "log_used_pct > 70", "description": "Log files heavily utilized — autogrowth imminent or occurring"}	null	2026-02-23 20:18:31.389792
3984	postgresql	query	Check replay lag trend on primary	{"sql": "SELECT client_addr, replay_lsn, pg_wal_lsn_diff(sent_lsn, replay_lsn) AS replay_lag_bytes, pg_wal_lsn_diff(write_lsn, replay_lsn) AS written_not_replayed FROM pg_stat_replication"}	{"condition": "replay_lag_bytes > :lag_threshold AND written_not_replayed > :written_threshold", "description": "WAL written to standby but not replayed indicates CPU bottleneck on standby"}	{"lag_threshold": 134217728, "written_threshold": 67108864}	2026-02-25 00:28:52.405273
1518	sqlserver	query	Identify the specific blocker of log truncation	{"sql": "SELECT d.name, d.log_reuse_wait_desc,\\n  CASE d.log_reuse_wait_desc\\n    WHEN 'LOG_BACKUP' THEN 'Transaction log backup needed (FULL/BULK_LOGGED recovery)'\\n    WHEN 'ACTIVE_TRANSACTION' THEN 'Long-running transaction holding log space'\\n    WHEN 'REPLICATION' THEN 'Uncommitted transactions not yet delivered to subscriber'\\n    WHEN 'DATABASE_MIRRORING' THEN 'Mirroring/AG send queue not drained'\\n    WHEN 'CHECKPOINT' THEN 'Checkpoint has not run since last log truncation'\\n    WHEN 'ACTIVE_BACKUP_OR_RESTORE' THEN 'Backup or restore in progress'\\n    WHEN 'DATABASE_SNAPSHOT_CREATION' THEN 'Snapshot creation in progress'\\n    WHEN 'AVAILABILITY_REPLICA' THEN 'AG secondary has not hardened log'\\n    ELSE d.log_reuse_wait_desc\\n  END AS explanation,\\n  ls.used_log_space_in_percent AS log_used_pct\\nFROM sys.databases d\\nJOIN sys.dm_db_log_space_usage ls ON d.database_id = ls.database_id\\nWHERE d.database_id > 4\\n  AND d.log_reuse_wait_desc <> 'NOTHING'\\nORDER BY ls.used_log_space_in_percent DESC"}	{"condition": "any log reuse waiter present with high log usage", "description": "Log reuse blocked — specific cause identified for remediation"}	null	2026-02-23 20:18:31.389792
1519	sqlserver	query	Check WRITELOG as a dominant wait type	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  max_wait_time_ms,\\n  100.0 * wait_time_ms / NULLIF(\\n    (SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats\\n     WHERE wait_type NOT IN ('WAITFOR', 'LAZYWRITER_SLEEP',\\n       'SQLTRACE_BUFFER_FLUSH', 'CLR_AUTO_EVENT', 'CLR_MANUAL_EVENT',\\n       'REQUEST_FOR_DEADLOCK_SEARCH', 'SLEEP_TASK', 'SLEEP_SYSTEMTASK',\\n       'BROKER_TO_FLUSH', 'CHECKPOINT_QUEUE', 'XE_TIMER_EVENT',\\n       'SP_SERVER_DIAGNOSTICS_SLEEP', 'DIRTY_PAGE_POLL', 'HADR_WORK_QUEUE',\\n       'QDS_PERSIST_TASK_MAIN_LOOP_SLEEP',\\n       'QDS_CLEANUP_STALE_QUERIES_TASK_MAIN_LOOP_SLEEP')), 0) AS pct_of_waits\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'WRITELOG'"}	{"condition": "pct_of_waits > 10 OR avg_wait_ms > 5", "description": "WRITELOG is a significant contributor to total waits — log writer is the bottleneck"}	null	2026-02-23 20:18:31.389793
1520	sqlserver	query	Check log file I/O performance	{"sql": "SELECT d.name,\\n  mf.physical_name,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_log_write_ms,\\n  vfs.num_of_writes AS log_writes,\\n  vfs.num_of_bytes_written / NULLIF(vfs.num_of_writes, 0) AS avg_write_bytes\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nJOIN sys.databases d ON vfs.database_id = d.database_id\\nWHERE mf.type = 1 AND d.database_id > 4\\nORDER BY avg_log_write_ms DESC"}	{"condition": "avg_log_write_ms > 3", "description": "Log file I/O latency confirms the log writer is being throttled by storage"}	null	2026-02-23 20:18:31.389794
1521	sqlserver	query	Check NUMA node configuration and scheduler distribution	{"sql": "SELECT parent_node_id AS numa_node,\\n  COUNT(*) AS scheduler_count,\\n  SUM(current_tasks_count) AS total_tasks,\\n  SUM(runnable_tasks_count) AS runnable_tasks,\\n  SUM(current_workers_count) AS workers\\nFROM sys.dm_os_schedulers\\nWHERE status = 'VISIBLE ONLINE'\\nGROUP BY parent_node_id\\nORDER BY parent_node_id"}	{"condition": "more than 1 NUMA node with significant task distribution", "description": "Multi-NUMA system where cross-node log structure access causes cache bouncing"}	null	2026-02-23 20:18:31.389794
1659	sqlserver	query	Confirm contention on tempdb allocation pages	{"sql": "SELECT session_id, wait_type, wait_resource,\\n  wait_time, blocking_session_id\\nFROM sys.dm_exec_requests\\nWHERE wait_type LIKE 'PAGELATCH%'\\n  AND wait_resource LIKE '2:%'\\nORDER BY wait_time DESC"}	{"condition": "wait_resource starts with '2:' (tempdb database_id)", "description": "Active PAGELATCH waits on tempdb pages (database_id = 2) confirm tempdb allocation contention"}	null	2026-02-23 20:18:31.389795
3599	postgresql	query	Check installed monitoring extensions	{"sql": "SELECT extname, extversion FROM pg_extension WHERE extname IN ('pg_stat_statements', 'auto_explain', 'pg_stat_kcache', 'pg_wait_sampling', 'pg_buffercache', 'pgstattuple') ORDER BY extname"}	{"condition": "extensions_identified", "description": "Monitoring extensions identified — verify same set on all nodes"}	\N	2026-02-25 00:28:52.405273
1526	sqlserver	query	Check log write size vs flush frequency	{"sql": "SELECT d.name,\\n  vfs.num_of_writes AS log_writes,\\n  vfs.num_of_bytes_written / 1048576 AS log_mb_written,\\n  vfs.num_of_bytes_written / NULLIF(vfs.num_of_writes, 0) AS avg_write_bytes,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_ms,\\n  pc.cntr_value AS log_flushes\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nJOIN sys.databases d ON vfs.database_id = d.database_id\\nLEFT JOIN sys.dm_os_performance_counters pc\\n  ON pc.instance_name = d.name\\n  AND pc.counter_name = 'Log Flushes/sec'\\n  AND pc.object_name LIKE '%Databases%'\\nWHERE mf.type = 1\\n  AND d.database_id > 4\\n  AND vfs.num_of_writes > 0\\nORDER BY avg_write_bytes ASC"}	{"condition": "avg_write_bytes < 4096", "description": "Average log write size below 4KB — group commit not coalescing effectively"}	null	2026-02-23 20:18:31.389796
1527	sqlserver	query	Check WRITELOG wait frequency relative to batch rate	{"sql": "SELECT\\n  ws.waiting_tasks_count AS writelog_waits,\\n  ws.wait_time_ms AS writelog_total_ms,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_writelog_ms,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Batch Requests/sec'\\n   AND object_name LIKE '%SQL Statistics%') AS batch_requests_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Transactions/sec'\\n   AND object_name LIKE '%Databases%'\\n   AND instance_name = '_Total') AS transactions_sec\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'WRITELOG'"}	{"condition": "writelog_waits approaching transactions_sec (low coalescing ratio)", "description": "Nearly 1:1 ratio of log writes to transactions — each commit triggers its own flush"}	null	2026-02-23 20:18:31.389797
1528	sqlserver	query	Check for active checkpoint and concurrent log write stalls	{"sql": "SELECT r.session_id, r.command, r.status,\\n  r.percent_complete,\\n  r.total_elapsed_time / 1000 AS elapsed_sec,\\n  r.wait_type, r.wait_time / 1000 AS wait_sec,\\n  r.database_id, d.name AS database_name\\nFROM sys.dm_exec_requests r\\nJOIN sys.databases d ON r.database_id = d.database_id\\nWHERE r.command IN ('CHECKPOINT', 'RECOVERY', 'DB STARTUP')"}	{"condition": "row_count > 0", "description": "Checkpoint or recovery process is currently active"}	null	2026-02-23 20:18:31.389797
1545	sqlserver	query	Check for missing column statistics	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(c.object_id) + '.' + OBJECT_NAME(c.object_id) AS table_name,\\n  c.name AS column_name,\\n  tp.name AS data_type,\\n  p.rows AS table_rows\\nFROM sys.columns c\\nJOIN sys.types tp ON c.system_type_id = tp.system_type_id\\nJOIN sys.partitions p ON c.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE c.object_id IN (\\n  SELECT object_id FROM sys.tables WHERE is_ms_shipped = 0\\n)\\nAND NOT EXISTS (\\n  SELECT 1 FROM sys.stats_columns sc\\n  WHERE sc.object_id = c.object_id AND sc.column_id = c.column_id\\n)\\nAND p.rows > 1000\\nORDER BY p.rows DESC"}	{"condition": "columns on large tables with no statistics coverage", "description": "Unindexed columns with no auto-created statistics — optimizer uses hard-coded density assumptions"}	null	2026-02-23 20:18:31.389807
1529	sqlserver	query	Check I/O contention between checkpoint and log writes	{"sql": "SELECT d.name,\\n  vfs_log.io_stall_write_ms / NULLIF(vfs_log.num_of_writes, 0) AS avg_log_write_ms,\\n  vfs_data.io_stall_write_ms / NULLIF(vfs_data.num_of_writes, 0) AS avg_data_write_ms,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_writelog_ms\\nFROM sys.databases d\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs_log\\n  ON d.database_id = vfs_log.database_id\\nJOIN sys.master_files mf_log\\n  ON vfs_log.database_id = mf_log.database_id AND vfs_log.file_id = mf_log.file_id AND mf_log.type = 1\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs_data\\n  ON d.database_id = vfs_data.database_id\\nJOIN sys.master_files mf_data\\n  ON vfs_data.database_id = mf_data.database_id AND vfs_data.file_id = mf_data.file_id AND mf_data.type = 0\\nCROSS JOIN sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'WRITELOG'\\n  AND d.database_id > 4\\n  AND vfs_log.io_stall_write_ms / NULLIF(vfs_log.num_of_writes, 0) > 3\\nORDER BY avg_log_write_ms DESC"}	{"condition": "avg_log_write_ms elevated during checkpoint with high checkpoint_pages_sec", "description": "Checkpoint flushing dirty pages saturates I/O bandwidth, starving log writes"}	null	2026-02-23 20:18:31.389798
1530	sqlserver	query	Check recovery interval and checkpoint configuration	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'recovery interval (min)') AS recovery_interval_min,\\n  d.name, d.target_recovery_time_in_seconds,\\n  d.recovery_model_desc\\nFROM sys.databases d\\nWHERE d.database_id > 4\\nORDER BY d.target_recovery_time_in_seconds DESC"}	{"condition": "recovery_interval_min > 5 OR target_recovery_time_in_seconds = 0", "description": "Recovery interval is long or indirect checkpoint not configured — checkpoints may be infrequent"}	null	2026-02-23 20:18:31.389798
1531	sqlserver	query	Check dirty page count and checkpoint frequency	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page life expectancy'\\n   AND object_name LIKE '%Buffer Manager%') AS page_life_expectancy,\\n  (SELECT COUNT(*) FROM sys.dm_os_buffer_descriptors\\n   WHERE is_modified = 1) AS dirty_pages,\\n  (SELECT COUNT(*) FROM sys.dm_os_buffer_descriptors) AS total_pages"}	{"condition": "dirty_pages > total_pages * 0.30", "description": "More than 30% of buffer pool is dirty — checkpoint is not running frequently enough"}	null	2026-02-23 20:18:31.389799
1532	sqlserver	query	Check current dirty page count and ratio	{"sql": "SELECT\\n  COUNT(*) AS total_buffer_pages,\\n  SUM(CASE WHEN is_modified = 1 THEN 1 ELSE 0 END) AS dirty_pages,\\n  CAST(SUM(CASE WHEN is_modified = 1 THEN 1 ELSE 0 END) AS FLOAT)\\n    / NULLIF(COUNT(*), 0) AS dirty_ratio,\\n  SUM(CASE WHEN is_modified = 1 THEN 1 ELSE 0 END) * 8 / 1024 AS dirty_mb\\nFROM sys.dm_os_buffer_descriptors"}	{"condition": "dirty_ratio > 0.25", "description": "More than 25% of buffer pool pages are dirty — large checkpoint write burst expected"}	null	2026-02-23 20:18:31.3898
1533	sqlserver	query	Check checkpoint I/O impact and page write rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Background writer pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS bg_writer_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Lazy writes/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS lazy_writes_sec,\\n  ws.waiting_tasks_count AS pageiolatch_waits,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_pageiolatch_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'PAGEIOLATCH_SH'"}	{"condition": "checkpoint_pages_sec > 100 AND avg_pageiolatch_ms > 10", "description": "High checkpoint I/O rate coinciding with elevated page latch waits — checkpoint storm"}	null	2026-02-23 20:18:31.3898
1535	sqlserver	query	Check background writer I/O pressure from aggressive target	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Background writer pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS bg_writer_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Recovery Log Checkpoint pages/sec'\\n   AND object_name LIKE '%Databases%'\\n   AND instance_name = '_Total') AS indirect_checkpoint_pages_sec,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_pageiolatch_write_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'PAGEIOLATCH_EX'"}	{"condition": "bg_writer_pages_sec elevated or avg_pageiolatch_write_ms > 10", "description": "Background writer continuously flushing pages, competing with foreground I/O"}	null	2026-02-23 20:18:31.389801
4292	postgresql	query	Check for tables with high sequential scan ratio	{"sql": "SELECT schemaname, relname, seq_scan, idx_scan, CASE WHEN seq_scan + idx_scan > 0 THEN round(seq_scan::numeric / (seq_scan + idx_scan) * 100, 2) ELSE 0 END AS seq_scan_pct, seq_tup_read, n_live_tup FROM pg_stat_user_tables WHERE seq_scan > :min_scans AND n_live_tup > :min_rows ORDER BY seq_tup_read DESC LIMIT 10"}	{"condition": "row_count > 0 AND seq_scan_pct > :threshold_pct", "description": "Large tables predominantly using sequential scans; missing or unused indexes"}	{"min_rows": 10000, "min_scans": 100, "threshold_pct": 90}	2026-02-25 00:28:52.405273
1543	sqlserver	query	Check staleness severity of locked statistics	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.modification_counter,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update,\\n  CASE\\n    WHEN sp.modification_counter > sp.rows * 0.20 THEN 'CRITICAL'\\n    WHEN sp.modification_counter > sp.rows * 0.05 THEN 'WARNING'\\n    ELSE 'LOW'\\n  END AS staleness_severity\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.no_recompute = 1\\n  AND sp.modification_counter > sp.rows * 0.05\\nORDER BY CAST(sp.modification_counter AS FLOAT) / NULLIF(sp.rows, 0) DESC"}	{"condition": "any statistics with staleness_severity = 'CRITICAL' (>20% modified)", "description": "Locked statistics with critical staleness — data distribution has changed significantly since last manual update"}	null	2026-02-23 20:18:31.389806
1561	sqlserver	query	Check for key lookups and RID lookups driving random I/O	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(ius.object_id) + '.' + OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.type_desc,\\n  ius.user_lookups,\\n  ius.user_seeks,\\n  ius.user_scans,\\n  ius.user_lookups * 100.0 / NULLIF(ius.user_seeks + ius.user_scans + ius.user_lookups, 0) AS lookup_pct\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.user_lookups > 10000\\nORDER BY ius.user_lookups DESC"}	{"condition": "tables with user_lookups > 10000 and lookup_pct > 50%", "description": "High key/RID lookup counts — each lookup is a random I/O to the clustered index or heap"}	null	2026-02-23 20:18:31.389812
1536	sqlserver	query	Find plans with estimated vs actual row count mismatches from default assumptions	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.total_logical_reads / qs.execution_count AS avg_reads,\\n  qs.last_rows AS actual_rows,\\n  TRY_CAST(qp.query_plan AS XML).value('(//RelOp/@EstimateRows)[1]', 'float') AS estimated_rows,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_text_query_plan(qs.plan_handle, 0, -1) qp\\nWHERE qs.execution_count > 10\\n  AND qs.last_rows > 0\\n  AND qs.total_worker_time / qs.execution_count > 100000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "estimated_rows differs from actual_rows by factor > 10x on high-CPU queries", "description": "Large estimation errors suggest optimizer using default assumptions (30% for inequality, 10% for equality on unknown values)"}	null	2026-02-23 20:18:31.389802
1537	sqlserver	query	Check for statistics with high density indicating uniform assumptions	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.rows_sampled,\\n  sp.steps AS histogram_steps,\\n  sp.modification_counter,\\n  CASE WHEN sp.steps < 10 AND sp.rows > 10000 THEN 'LOW_RESOLUTION' ELSE 'OK' END AS histogram_quality\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 10000\\n  AND sp.steps < 50\\nORDER BY sp.rows DESC"}	{"condition": "tables with high row counts but few histogram steps (< 50)", "description": "Low histogram resolution forces optimizer to use default density assumptions for values between steps"}	null	2026-02-23 20:18:31.389802
1538	sqlserver	query	Find statistics on datetime columns with stale histograms	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  COL_NAME(s.object_id, sc.column_id) AS column_name,\\n  tp.name AS data_type,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter * 100.0 / NULLIF(sp.rows, 0) AS DECIMAL(5,2)) AS pct_modified,\\n  DATEDIFF(HOUR, sp.last_updated, GETDATE()) AS hours_since_update\\nFROM sys.stats s\\nJOIN sys.stats_columns sc ON s.object_id = sc.object_id AND s.stats_id = sc.stats_id AND sc.stats_column_id = 1\\nJOIN sys.columns c ON sc.object_id = c.object_id AND sc.column_id = c.column_id\\nJOIN sys.types tp ON c.system_type_id = tp.system_type_id\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE tp.name IN ('datetime', 'datetime2', 'date', 'smalldatetime', 'datetimeoffset')\\n  AND sp.modification_counter > 1000\\n  AND sp.rows > 10000\\nORDER BY sp.modification_counter DESC"}	{"condition": "datetime columns with modification_counter > 1000 or pct_modified > 5%", "description": "Time-series columns with significant modifications since last statistics update — new values outside histogram range"}	null	2026-02-23 20:18:31.389803
1539	sqlserver	query	Check for ascending key problem in query plans	{"sql": "SELECT\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.last_rows AS actual_rows,\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.total_logical_reads / qs.execution_count AS avg_reads,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE st.text LIKE '%WHERE%>%' OR st.text LIKE '%WHERE%>=%'\\n  OR st.text LIKE '%BETWEEN%' OR st.text LIKE '%ORDER BY%DESC%'\\nAND qs.execution_count > 5\\n  AND qs.last_rows > 100\\n  AND qs.total_worker_time / qs.execution_count > 50000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "high-CPU queries filtering on datetime columns with poor row estimates", "description": "Queries on time-series data using stale histograms — optimizer underestimates rows for recent date ranges"}	null	2026-02-23 20:18:31.389803
1540	sqlserver	query	Find filtered indexes and check for matching statistics	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.filter_definition,\\n  i.is_disabled,\\n  sp.last_updated AS stat_last_updated,\\n  sp.rows AS stat_rows,\\n  sp.rows_sampled,\\n  ius.user_seeks + ius.user_scans AS index_usage,\\n  ius.user_updates AS index_updates\\nFROM sys.indexes i\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nCROSS APPLY sys.dm_db_stats_properties(i.object_id, i.index_id) sp\\nWHERE i.has_filter = 1\\n  AND i.is_disabled = 0\\nORDER BY ius.user_seeks + ius.user_scans DESC"}	{"condition": "filtered indexes exist", "description": "Identify filtered indexes to check if they have adequate statistics coverage"}	null	2026-02-23 20:18:31.389804
1541	sqlserver	query	Check for plans not using filtered indexes due to missing stats	{"sql": "SELECT\\n  i.name AS filtered_index_name,\\n  OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name,\\n  i.filter_definition,\\n  s.name AS stat_name,\\n  s.has_filter AS stat_has_filter,\\n  s.filter_definition AS stat_filter,\\n  sp.last_updated,\\n  sp.modification_counter\\nFROM sys.indexes i\\nLEFT JOIN sys.stats s ON i.object_id = s.object_id\\n  AND s.has_filter = 1\\n  AND s.filter_definition = i.filter_definition\\nCROSS APPLY sys.dm_db_stats_properties(i.object_id, i.index_id) sp\\nWHERE i.has_filter = 1\\n  AND i.is_disabled = 0\\n  AND s.stats_id IS NULL"}	{"condition": "filtered indexes without matching filtered statistics", "description": "No filtered statistics matching the index filter — optimizer cannot accurately estimate rows for filtered subset"}	null	2026-02-23 20:18:31.389805
1581	sqlserver	query	Check NUMA topology and scheduler distribution	{"sql": "SELECT\\n  si.socket_count,\\n  si.numa_node_count,\\n  si.cpu_count AS logical_cpus,\\n  si.cpu_count / si.hyperthread_ratio AS physical_cores,\\n  si.hyperthread_ratio,\\n  (SELECT CAST(value_in_use AS int) FROM sys.configurations\\n   WHERE name = 'max degree of parallelism') AS maxdop,\\n  (SELECT CAST(value_in_use AS int) FROM sys.configurations\\n   WHERE name = 'cost threshold for parallelism') AS cost_threshold\\nFROM sys.dm_os_sys_info si"}	{"condition": "socket_count = 1 and numa_node_count = 1 and maxdop > physical_cores / 2", "description": "Single-socket single-NUMA system with MAXDOP set too high for shared memory bus"}	null	2026-02-23 20:18:31.389829
1542	sqlserver	query	Find statistics with NORECOMPUTE set	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  s.no_recompute,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter * 100.0 / NULLIF(sp.rows, 0) AS DECIMAL(5,2)) AS pct_modified,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.no_recompute = 1\\n  AND sp.modification_counter > 0\\nORDER BY sp.modification_counter DESC"}	{"condition": "statistics with no_recompute = 1 and modification_counter > 0", "description": "Statistics explicitly locked from auto-update while underlying data has changed"}	null	2026-02-23 20:18:31.389805
1546	sqlserver	query	Find high-cost procedures with table variable patterns	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.total_logical_reads / qs.execution_count AS avg_reads,\\n  qs.last_rows AS actual_rows,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE st.text LIKE '%@%TABLE%' OR st.text LIKE '%DECLARE%@%table%'\\nAND qs.execution_count > 5\\n  AND qs.total_worker_time / qs.execution_count > 100000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "high-CPU queries using table variables with actual_rows >> 1", "description": "Procedures using table variables where actual rows far exceed estimated 1 row"}	null	2026-02-23 20:18:31.389808
1547	sqlserver	query	Check database compatibility level for deferred compilation	{"sql": "SELECT\\n  d.name AS database_name,\\n  d.compatibility_level,\\n  CASE\\n    WHEN d.compatibility_level >= 150 THEN 'TABLE_VARIABLE_DEFERRED_COMPILE_AVAILABLE'\\n    ELSE 'TABLE_VARIABLE_FIXED_1_ROW'\\n  END AS tv_estimation_behavior,\\n  CAST(dsc.value AS INT) AS deferred_compilation_disabled\\nFROM sys.databases d\\nLEFT JOIN sys.database_scoped_configurations dsc\\n  ON dsc.name = 'DEFERRED_COMPILATION_TV'\\nWHERE d.database_id > 4 AND d.state = 0\\n  AND (d.compatibility_level < 150\\n    OR (dsc.value IS NOT NULL AND CAST(dsc.value AS INT) = 1))"}	{"condition": "compatibility_level < 150 or deferred_compilation_disabled = 1", "description": "Table variable deferred compilation not available or disabled — statistics fixed at 1 row"}	null	2026-02-23 20:18:31.389808
1548	sqlserver	query	Find temporal tables and check history table statistics	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(t.object_id) + '.' + t.name AS current_table,\\n  OBJECT_SCHEMA_NAME(ht.object_id) + '.' + ht.name AS history_table,\\n  t.temporal_type_desc,\\n  p_curr.rows AS current_rows,\\n  p_hist.rows AS history_rows,\\n  sp_hist.last_updated AS history_stats_updated,\\n  sp_hist.modification_counter AS history_modifications,\\n  DATEDIFF(DAY, sp_hist.last_updated, GETDATE()) AS hist_stats_age_days\\nFROM sys.tables t\\nJOIN sys.tables ht ON t.history_table_id = ht.object_id\\nJOIN sys.partitions p_curr ON t.object_id = p_curr.object_id AND p_curr.index_id IN (0, 1)\\nJOIN sys.partitions p_hist ON ht.object_id = p_hist.object_id AND p_hist.index_id IN (0, 1)\\nCROSS APPLY (\\n  SELECT TOP 1 sp2.last_updated, sp2.modification_counter\\n  FROM sys.stats s2\\n  CROSS APPLY sys.dm_db_stats_properties(s2.object_id, s2.stats_id) sp2\\n  WHERE s2.object_id = ht.object_id\\n  ORDER BY sp2.last_updated ASC\\n) sp_hist\\nWHERE t.temporal_type = 2"}	{"condition": "history_modifications > 1000 or hist_stats_age_days > 7", "description": "Temporal history table with stale statistics — every update/delete on current table inserts into history"}	null	2026-02-23 20:18:31.389809
1550	sqlserver	query	Check I/O stall times per database file	{"sql": "SELECT\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.name AS file_name,\\n  mf.type_desc AS file_type,\\n  mf.physical_name,\\n  vfs.num_of_reads,\\n  vfs.num_of_writes,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms,\\n  vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0) AS avg_total_stall_ms,\\n  vfs.num_of_bytes_read / NULLIF(vfs.num_of_reads, 0) / 1024 AS avg_read_kb,\\n  vfs.num_of_bytes_written / NULLIF(vfs.num_of_writes, 0) / 1024 AS avg_write_kb\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_reads + vfs.num_of_writes > 1000\\nORDER BY vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0) DESC"}	{"condition": "avg_read_stall_ms > 20 or avg_write_stall_ms > 20", "description": "Average I/O latency exceeding 20ms indicates storage cannot keep up with demand"}	null	2026-02-23 20:18:31.38981
1551	sqlserver	query	Check PAGEIOLATCH waits confirming I/O bottleneck	{"sql": "SELECT\\n  wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  signal_wait_time_ms,\\n  (wait_time_ms - signal_wait_time_ms) / NULLIF(waiting_tasks_count, 0) AS avg_resource_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'PAGEIOLATCH_UP',\\n  'WRITELOG', 'ASYNC_IO_COMPLETION', 'IO_COMPLETION'\\n)\\nAND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH waits in top wait types with avg_resource_wait_ms > 10", "description": "PAGEIOLATCH waits confirm SQL Server waiting on storage to complete I/O operations"}	null	2026-02-23 20:18:31.389811
1552	sqlserver	query	Check Buffer Manager performance counters for I/O pressure	{"sql": "SELECT\\n  object_name,\\n  counter_name,\\n  cntr_value\\nFROM sys.dm_os_performance_counters\\nWHERE object_name LIKE '%Buffer Manager%'\\n  AND counter_name IN (\\n    'Page reads/sec', 'Page writes/sec',\\n    'Readahead pages/sec', 'Lazy writes/sec',\\n    'Checkpoint pages/sec', 'Page life expectancy'\\n  )"}	{"condition": "Page life expectancy < 300 or high page reads/sec relative to buffer pool size", "description": "Low PLE combined with high physical I/O indicates memory pressure forcing excessive disk access"}	null	2026-02-23 20:18:31.389812
4005	postgresql	config_check	Check archive_command for atomic copy pattern	{"sql": "SELECT setting FROM pg_settings WHERE name = 'archive_command'"}	{"condition": "setting NOT LIKE '%tmp%' AND setting NOT LIKE '%mv %'", "description": "Archive command lacks temp-file-then-rename pattern for atomicity"}	\N	2026-02-25 00:28:52.405273
2765	sqlserver	query	Check for audits that should be enabled but are not	{"sql": "SELECT sa.name, sa.is_state_enabled,\\n  sa.on_failure_desc,\\n  sa.modify_date,\\n  (SELECT sqlserver_start_time FROM sys.dm_os_sys_info) AS last_restart,\\n  CASE WHEN sa.modify_date >\\n    (SELECT sqlserver_start_time FROM sys.dm_os_sys_info)\\n    THEN 'Modified after restart'\\n    ELSE 'Not modified since restart'\\n  END AS state_change_timing\\nFROM sys.server_audits sa\\nWHERE sa.is_state_enabled = 0"}	{"condition": "disabled audit with modify_date close to an error event", "description": "Audit was disabled by the system, not by an administrator"}	null	2026-02-23 20:18:31.39007
1645	sqlserver	query	Check concurrent checkpoint activity with latch waits	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests\\n   WHERE wait_type LIKE 'PAGEIOLATCH%'\\n   OR wait_type LIKE 'PAGELATCH%') AS sessions_waiting_on_latches,\\n  (SELECT SUM(waiting_tasks_count) FROM sys.dm_os_wait_stats\\n   WHERE wait_type IN ('PAGEIOLATCH_EX', 'PAGELATCH_UP')) AS total_latch_waits"}	{"condition": "checkpoint_pages_sec > 50 AND sessions_waiting_on_latches > 5", "description": "Active checkpoint flushing with multiple sessions blocked on page latches — checkpoint I/O causing contention"}	null	2026-02-23 20:18:31.389869
3985	postgresql	query	Check standby data directory disk usage	{"sql": "SELECT pg_size_pretty(sum(size)) AS total_wal_size, count(*) AS wal_file_count FROM pg_ls_waldir()"}	{"condition": "wal_file_count > :max_files", "description": "Excessive WAL files may indicate disk pressure preventing cleanup"}	{"max_files": 200}	2026-02-25 00:28:52.405273
1553	sqlserver	query	Check write latency vs read latency asymmetry indicating RAID write penalty	{"sql": "SELECT\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.name AS file_name,\\n  mf.type_desc,\\n  mf.physical_name,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_ms,\\n  CASE WHEN vfs.num_of_reads > 0 AND vfs.num_of_writes > 0\\n    THEN CAST(vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS FLOAT) /\\n         NULLIF(CAST(vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS FLOAT), 0)\\n    ELSE 0 END AS write_read_ratio\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_writes > 1000\\n  AND vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) > 10\\nORDER BY write_read_ratio DESC"}	{"condition": "write_read_ratio > 3 (writes 3x slower than reads)", "description": "Write latency significantly higher than read latency — consistent with RAID 5/6 write penalty or degraded RAID"}	null	2026-02-23 20:18:31.389813
1554	sqlserver	query	Check WRITELOG waits for log file RAID impact	{"sql": "SELECT\\n  ws.wait_type,\\n  ws.wait_time_ms,\\n  ws.waiting_tasks_count,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_wait_ms,\\n  vfs.physical_name AS log_file_path,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS log_avg_write_ms\\nFROM sys.dm_os_wait_stats ws\\nCROSS APPLY (\\n  SELECT TOP 1 mf.physical_name,\\n    dvfs.io_stall_write_ms, dvfs.num_of_writes\\n  FROM sys.dm_io_virtual_file_stats(NULL, NULL) dvfs\\n  JOIN sys.master_files mf ON dvfs.database_id = mf.database_id AND dvfs.file_id = mf.file_id\\n  WHERE mf.type = 1\\n  ORDER BY dvfs.io_stall_write_ms DESC\\n) vfs\\nWHERE ws.wait_type = 'WRITELOG'"}	{"condition": "WRITELOG avg_wait_ms > 5 with high log write latency", "description": "Transaction log writes slow — RAID 5 write penalty on log volume severely impacts commit throughput"}	null	2026-02-23 20:18:31.389813
1555	sqlserver	query	Check for elevated write latency with low write size indicating no write cache	{"sql": "SELECT\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.type_desc,\\n  mf.physical_name,\\n  vfs.num_of_writes,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_ms,\\n  vfs.num_of_bytes_written / NULLIF(vfs.num_of_writes, 0) / 1024 AS avg_write_kb,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_writes > 1000\\nORDER BY vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) DESC"}	{"condition": "avg_write_ms > 5 with small avg_write_kb (< 64 KB) across all volumes", "description": "Uniformly high write latency on small writes — consistent with write-through mode (no BBU cache)"}	null	2026-02-23 20:18:31.389814
1556	sqlserver	query	Check WRITELOG and checkpoint write impact	{"sql": "SELECT\\n  wl.wait_time_ms / NULLIF(wl.waiting_tasks_count, 0) AS avg_writelog_ms,\\n  wl.waiting_tasks_count AS writelog_waits,\\n  pc_cp.cntr_value AS checkpoint_pages_sec,\\n  pc_lw.cntr_value AS lazy_writes_sec\\nFROM sys.dm_os_wait_stats wl\\nCROSS JOIN (\\n  SELECT cntr_value FROM sys.dm_os_performance_counters\\n  WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Checkpoint pages/sec'\\n) pc_cp\\nCROSS JOIN (\\n  SELECT cntr_value FROM sys.dm_os_performance_counters\\n  WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Lazy writes/sec'\\n) pc_lw\\nWHERE wl.wait_type = 'WRITELOG'"}	{"condition": "avg_writelog_ms > 5 and checkpoint_pages_sec > 0", "description": "Slow log writes combined with active checkpointing — without BBU, all writes hit physical media"}	null	2026-02-23 20:18:31.389815
1557	sqlserver	query	Check I/O latency distribution across all files for controller bottleneck	{"sql": "SELECT\\n  LEFT(mf.physical_name, 3) AS drive_letter,\\n  COUNT(*) AS file_count,\\n  SUM(vfs.num_of_reads + vfs.num_of_writes) AS total_ios,\\n  AVG(vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0)) AS avg_stall_ms,\\n  MAX(vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0)) AS max_stall_ms,\\n  MIN(vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0)) AS min_stall_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_reads + vfs.num_of_writes > 100\\nGROUP BY LEFT(mf.physical_name, 3)\\nHAVING AVG(vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0)) > 15"}	{"condition": "all drive letters showing avg_stall_ms > 15 with similar latency patterns", "description": "Uniformly high I/O latency across all volumes suggests shared controller bottleneck rather than individual disk issues"}	null	2026-02-23 20:18:31.389815
1558	sqlserver	query	Check pending I/O requests for controller queue saturation	{"sql": "SELECT\\n  vfs.database_id,\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.physical_name,\\n  pior.io_pending_ms_ticks,\\n  pior.io_type,\\n  pior.scheduler_address\\nFROM sys.dm_io_pending_io_requests pior\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\n  ON pior.io_handle = vfs.file_handle\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nORDER BY pior.io_pending_ms_ticks DESC"}	{"condition": "multiple pending I/O requests with io_pending_ms_ticks > 1000", "description": "Long-pending I/O requests across files indicate controller queue depth exceeded"}	null	2026-02-23 20:18:31.389816
4293	postgresql	query	Find tables with high sequential scan volume	{"sql": "SELECT schemaname, relname, seq_scan, seq_tup_read, idx_scan, n_live_tup, pg_size_pretty(pg_total_relation_size(relid)) AS total_size FROM pg_stat_user_tables WHERE seq_scan > idx_scan AND n_live_tup > :min_rows AND seq_tup_read > :min_tuples_read ORDER BY seq_tup_read DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Large tables with more sequential scans than index scans need index analysis"}	{"min_rows": 50000, "min_tuples_read": 1000000}	2026-02-25 00:28:52.405273
1597	sqlserver	query	Check if dynamic threshold (TF 2371) behavior is active	{"sql": "SELECT\\n  d.name AS database_name,\\n  d.compatibility_level,\\n  CASE WHEN d.compatibility_level >= 130 THEN 'Dynamic threshold (default)'\\n    ELSE 'Legacy threshold (500+20%)' END AS threshold_mode,\\n  (SELECT COUNT(*) FROM sys.stats s\\n   CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\n   WHERE s.object_id > 100 AND sp.rows > 1000000\\n     AND sp.modification_counter > 0) AS large_tables_with_mods\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "compatibility_level < 130 (legacy threshold) or large_tables_with_mods > 5", "description": "Legacy threshold mode or many large tables accumulating modifications"}	null	2026-02-23 20:18:31.389839
1614	sqlserver	query	Check for partitioned tables without incremental statistics	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  s.name AS stats_name,\\n  s.is_incremental,\\n  COUNT(DISTINCT p.partition_number) AS partition_count,\\n  SUM(p.rows) AS total_rows\\nFROM sys.indexes i\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nJOIN sys.stats s ON i.object_id = s.object_id\\nJOIN sys.partition_schemes ps ON i.data_space_id = ps.data_space_id\\nWHERE i.object_id > 100\\n  AND p.rows > 0\\nGROUP BY i.object_id, i.name, s.name, s.is_incremental\\nHAVING COUNT(DISTINCT p.partition_number) > 1\\nORDER BY SUM(p.rows) DESC"}	{"condition": "partitioned tables where is_incremental = 0", "description": "Partitioned tables without incremental statistics — stats updates require scanning all partitions"}	null	2026-02-23 20:18:31.38985
1559	sqlserver	query	Check read latency and read-ahead efficiency	{"sql": "SELECT\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.name AS file_name,\\n  mf.type_desc,\\n  mf.physical_name,\\n  mf.size * 8 / 1024 AS size_mb,\\n  mf.growth,\\n  mf.is_percent_growth,\\n  vfs.num_of_reads,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_ms,\\n  vfs.num_of_bytes_read / NULLIF(vfs.num_of_reads, 0) / 1024 AS avg_read_kb\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_reads > 1000\\n  AND vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) > 15\\nORDER BY vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) DESC"}	{"condition": "avg_read_ms > 15 with small avg_read_kb and percentage-based file growth", "description": "High read latency with small reads and auto-grow percentage — file likely fragmented on disk"}	null	2026-02-23 20:18:31.389817
1560	sqlserver	query	Check read-ahead performance counters	{"sql": "SELECT\\n  counter_name,\\n  cntr_value\\nFROM sys.dm_os_performance_counters\\nWHERE object_name LIKE '%Buffer Manager%'\\n  AND counter_name IN (\\n    'Readahead pages/sec',\\n    'Page reads/sec',\\n    'Page lookups/sec'\\n  )\\nUNION ALL\\nSELECT\\n  'PAGEIOLATCH_SH avg wait ms' AS counter_name,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS cntr_value\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'PAGEIOLATCH_SH'"}	{"condition": "high page reads/sec relative to readahead with elevated PAGEIOLATCH_SH waits", "description": "Read-ahead ineffective (fragmented files cause sequential reads to become random) with high physical read waits"}	null	2026-02-23 20:18:31.389817
1563	sqlserver	query	Check missing index suggestions for lookup elimination	{"sql": "SELECT TOP 10\\n  mid.statement AS table_name,\\n  mid.equality_columns,\\n  mid.inequality_columns,\\n  mid.included_columns,\\n  migs.user_seeks,\\n  migs.avg_user_impact,\\n  migs.user_seeks * migs.avg_total_user_cost * migs.avg_user_impact / 100.0 AS improvement_measure\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE migs.user_seeks > 100\\nORDER BY improvement_measure DESC"}	{"condition": "missing indexes with high improvement_measure and included_columns", "description": "Missing covering indexes forcing key lookups — adding included columns would eliminate random I/O"}	null	2026-02-23 20:18:31.389818
1564	sqlserver	query	Check I/O latency patterns characteristic of HDDs	{"sql": "SELECT\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.type_desc,\\n  mf.physical_name,\\n  vfs.num_of_reads,\\n  vfs.num_of_writes,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_ms,\\n  vfs.num_of_bytes_read / NULLIF(vfs.num_of_reads, 0) AS avg_bytes_per_read,\\n  CASE\\n    WHEN vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) > 10\\n      AND vfs.num_of_bytes_read / NULLIF(vfs.num_of_reads, 0) < 65536\\n    THEN 'HDD_RANDOM_IO_SUSPECT'\\n    WHEN vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) > 30\\n    THEN 'HDD_UNDER_HEAVY_LOAD'\\n    ELSE 'ACCEPTABLE'\\n  END AS io_assessment\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_reads + vfs.num_of_writes > 1000\\nORDER BY vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) DESC"}	{"condition": "io_assessment = 'HDD_RANDOM_IO_SUSPECT' or 'HDD_UNDER_HEAVY_LOAD'", "description": "I/O latency pattern consistent with spinning disks — high latency on small random reads (> 10ms for < 64KB)"}	null	2026-02-23 20:18:31.389818
1565	sqlserver	query	Check wait stats for I/O-bound workload on slow storage	{"sql": "SELECT\\n  wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  CAST(wait_time_ms * 100.0 / NULLIF(SUM(wait_time_ms) OVER (), 0) AS DECIMAL(5,2)) AS pct_of_total_waits\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'WRITELOG',\\n  'IO_COMPLETION', 'ASYNC_IO_COMPLETION'\\n)\\nAND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH waits > 30% of total wait time with avg_wait_ms > 15", "description": "I/O waits dominating server wait profile with latencies characteristic of spinning disks"}	null	2026-02-23 20:18:31.389819
1566	sqlserver	query	Check pending I/O requests and queue depth	{"sql": "SELECT\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.physical_name,\\n  mf.type_desc,\\n  pior.io_type,\\n  COUNT(*) AS pending_io_count,\\n  AVG(pior.io_pending_ms_ticks) AS avg_pending_ms\\nFROM sys.dm_io_pending_io_requests pior\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\n  ON pior.io_handle = vfs.file_handle\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nGROUP BY DB_NAME(vfs.database_id), mf.physical_name, mf.type_desc, pior.io_type\\nHAVING COUNT(*) > 5 OR AVG(pior.io_pending_ms_ticks) > 500\\nORDER BY COUNT(*) DESC"}	{"condition": "pending_io_count > 5 per file or avg_pending_ms > 500", "description": "High pending I/O count indicates storage queue saturation — requests waiting longer than storage can process"}	null	2026-02-23 20:18:31.38982
1583	sqlserver	query	Confirm overhead via parallelism and scheduler waits	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'SOS_SCHEDULER_YIELD',\\n  'CMEMTHREAD')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "CMEMTHREAD or SOS_SCHEDULER_YIELD elevated alongside CXPACKET", "description": "Memory allocator contention (CMEMTHREAD) and scheduler yields on single-NUMA node — shared resources saturated"}	null	2026-02-23 20:18:31.389831
1567	sqlserver	query	Check I/O completion rates and stall correlation	{"sql": "SELECT\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.physical_name,\\n  vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0) AS avg_stall_ms,\\n  vfs.num_of_reads + vfs.num_of_writes AS total_ios,\\n  CASE\\n    WHEN vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0) > 50 THEN 'SEVERE_QUEUING'\\n    WHEN vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0) > 20 THEN 'MODERATE_QUEUING'\\n    ELSE 'ACCEPTABLE'\\n  END AS queue_assessment\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_reads + vfs.num_of_writes > 1000\\n  AND vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0) > 20\\nORDER BY avg_stall_ms DESC"}	{"condition": "queue_assessment = 'SEVERE_QUEUING' or 'MODERATE_QUEUING'", "description": "High I/O stalls with multiple pending requests — disk queue depth insufficient for workload demand"}	null	2026-02-23 20:18:31.38982
4294	postgresql	query	Check existing indexes on high-scan tables	{"sql": "SELECT schemaname, relname, indexrelname, idx_scan, idx_tup_read, idx_tup_fetch FROM pg_stat_user_indexes WHERE relname IN (SELECT relname FROM pg_stat_user_tables WHERE seq_scan > idx_scan AND n_live_tup > :min_rows ORDER BY seq_tup_read DESC LIMIT 5) ORDER BY idx_scan ASC"}	{"condition": "row_count = 0", "description": "No indexes on frequently scanned tables; indexes needed for filter/join columns"}	{"min_rows": 50000}	2026-02-25 00:28:52.405273
1568	sqlserver	query	Check I/O latency variance indicating shared storage contention	{"sql": "SELECT\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.physical_name,\\n  mf.type_desc,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_ms,\\n  vfs.io_stall_queued_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_queued_read_ms,\\n  vfs.io_stall_queued_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_queued_write_ms,\\n  CASE\\n    WHEN vfs.io_stall_queued_read_ms > vfs.io_stall_read_ms * 0.5 THEN 'HIGH_QUEUE_CONTENTION'\\n    ELSE 'NORMAL'\\n  END AS contention_indicator\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_reads + vfs.num_of_writes > 1000\\nORDER BY vfs.io_stall_queued_read_ms DESC"}	{"condition": "avg_queued_read_ms or avg_queued_write_ms > 50% of total stall time", "description": "High proportion of I/O time spent in queue rather than actual I/O — indicates contention from other consumers on shared storage"}	null	2026-02-23 20:18:31.389821
1576	sqlserver	query	Check memory grants and RESOURCE_SEMAPHORE waits	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NULL) AS pending_memory_grants,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NOT NULL) AS active_memory_grants,\\n  (SELECT SUM(used_memory_kb) FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NOT NULL) / 1024 AS active_grants_mb,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_resource_semaphore_ms,\\n  ws.waiting_tasks_count AS resource_semaphore_waits\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'RESOURCE_SEMAPHORE'"}	{"condition": "pending_memory_grants > 0 or resource_semaphore_waits > 100", "description": "Queries waiting for memory grants — memory pressure cascading to storage as buffer pool shrinks"}	null	2026-02-23 20:18:31.389822
1570	sqlserver	query	Check for elevated I/O latency on write-heavy operations	{"sql": "SELECT\\n  DB_NAME(vfs.database_id) AS database_name,\\n  mf.type_desc,\\n  mf.physical_name,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_ms,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_ms,\\n  CASE\\n    WHEN vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) > 30\\n      AND vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) > 20\\n    THEN 'BOTH_DEGRADED'\\n    WHEN vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) > 30\\n    THEN 'WRITE_DEGRADED'\\n    ELSE 'READ_ONLY_DEGRADED'\\n  END AS degradation_pattern\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_reads + vfs.num_of_writes > 1000\\n  AND (vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) > 30\\n    OR vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) > 20)\\nORDER BY vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) DESC"}	{"condition": "degradation_pattern = 'BOTH_DEGRADED' across multiple files on same volume", "description": "Both read and write latency elevated uniformly — consistent with RAID rebuild consuming I/O bandwidth"}	null	2026-02-23 20:18:31.389823
1571	sqlserver	query	Check for recent I/O latency increase via error log	{"sql": "SELECT\\n  wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'WRITELOG',\\n  'IO_COMPLETION', 'ASYNC_IO_COMPLETION'\\n)\\nAND wait_time_ms / NULLIF(waiting_tasks_count, 0) > 25\\nORDER BY wait_time_ms DESC"}	{"condition": "all I/O wait types showing avg_wait_ms > 25", "description": "Uniformly elevated I/O waits across all types — characteristic of RAID rebuild background I/O competition"}	null	2026-02-23 20:18:31.389823
1572	sqlserver	query	Check for full scans that should benefit from read-ahead	{"sql": "SELECT TOP 15\\n  OBJECT_SCHEMA_NAME(ius.object_id) + '.' + OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.type_desc,\\n  ius.user_scans,\\n  ius.user_seeks,\\n  p.rows AS table_rows,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS file_avg_read_ms\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nCROSS APPLY (\\n  SELECT TOP 1 dvfs.io_stall_read_ms, dvfs.num_of_reads\\n  FROM sys.dm_io_virtual_file_stats(DB_ID(), NULL) dvfs\\n  JOIN sys.master_files mf ON dvfs.file_id = mf.file_id AND dvfs.database_id = mf.database_id\\n  WHERE mf.type = 0\\n) vfs\\nWHERE ius.database_id = DB_ID()\\n  AND ius.user_scans > 100\\n  AND p.rows > 10000\\nORDER BY ius.user_scans DESC"}	{"condition": "large tables with frequent scans and elevated file_avg_read_ms", "description": "Frequent table scans on large tables with slow read completion — read-ahead should be helping but isn't"}	null	2026-02-23 20:18:31.389824
1573	sqlserver	query	Check for uniform latency across all files suggesting network bottleneck	{"sql": "SELECT\\n  LEFT(mf.physical_name, 3) AS volume,\\n  COUNT(*) AS file_count,\\n  AVG(vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0)) AS avg_read_ms,\\n  AVG(vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0)) AS avg_write_ms,\\n  STDEV(vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0)) AS stall_stddev,\\n  SUM(vfs.num_of_bytes_read + vfs.num_of_bytes_written) / 1048576 AS total_io_mb\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE vfs.num_of_reads + vfs.num_of_writes > 100\\nGROUP BY LEFT(mf.physical_name, 3)\\nHAVING AVG(vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0)) > 15"}	{"condition": "low stall_stddev (uniform latency) with high avg latency across volumes — all affected equally", "description": "Uniform I/O degradation across different volumes on same fabric suggests storage network saturation"}	null	2026-02-23 20:18:31.389825
1574	sqlserver	query	Check total I/O throughput approaching fabric limits	{"sql": "SELECT\\n  SUM(vfs.num_of_bytes_read) / 1048576 AS total_read_mb,\\n  SUM(vfs.num_of_bytes_written) / 1048576 AS total_write_mb,\\n  (SUM(vfs.num_of_bytes_read) + SUM(vfs.num_of_bytes_written)) / 1048576 AS total_io_mb,\\n  SUM(vfs.num_of_reads) + SUM(vfs.num_of_writes) AS total_io_ops,\\n  AVG(vfs.io_stall / NULLIF(vfs.num_of_reads + vfs.num_of_writes, 0)) AS overall_avg_stall_ms,\\n  (SELECT wait_time_ms / NULLIF(waiting_tasks_count, 0)\\n   FROM sys.dm_os_wait_stats WHERE wait_type = 'ASYNC_NETWORK_IO') AS network_io_avg_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs"}	{"condition": "high total_io_mb with elevated overall_avg_stall_ms across all I/O", "description": "Large total I/O throughput with uniformly elevated stalls — storage fabric bandwidth saturated"}	null	2026-02-23 20:18:31.389825
4295	postgresql	query	Check for foreign data wrapper usage	{"sql": "SELECT ft.foreign_table_name, fs.srvname, fs.srvoptions FROM information_schema.foreign_tables ft JOIN pg_foreign_server fs ON ft.foreign_server_name = fs.srvname"}	{"condition": "row_count > 0", "description": "Foreign tables in use; network latency affects query performance"}	\N	2026-02-25 00:28:52.405273
3986	postgresql	query	Check tablespace disk usage	{"sql": "SELECT spcname, pg_size_pretty(pg_tablespace_size(oid)) AS size FROM pg_tablespace"}	{"condition": "size IS NOT NULL", "description": "Review tablespace sizes to identify disk space consumption patterns"}	\N	2026-02-25 00:28:52.405273
1575	sqlserver	query	Check buffer pool memory pressure indicators	{"sql": "SELECT\\n  pc_ple.cntr_value AS page_life_expectancy,\\n  pc_lw.cntr_value AS lazy_writes_sec,\\n  pc_cp.cntr_value AS checkpoint_pages_sec,\\n  pc_fh.cntr_value AS free_list_stalls_sec,\\n  pc_pr.cntr_value AS page_reads_sec,\\n  pc_pw.cntr_value AS page_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%' AND counter_name = 'Target Server Memory (KB)') AS target_memory_kb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%' AND counter_name = 'Total Server Memory (KB)') AS total_memory_kb\\nFROM\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Page life expectancy') pc_ple,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Lazy writes/sec') pc_lw,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Checkpoint pages/sec') pc_cp,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Free list stalls/sec') pc_fh,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Page reads/sec') pc_pr,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Page writes/sec') pc_pw"}	{"condition": "page_life_expectancy < 300 or lazy_writes_sec > 0 or free_list_stalls_sec > 0", "description": "Memory pressure forcing buffer pool to evict pages — causing excessive physical I/O to storage"}	null	2026-02-23 20:18:31.389826
1577	sqlserver	query	Check I/O impact from memory pressure	{"sql": "SELECT\\n  wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'WRITELOG')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH waits elevated alongside memory pressure indicators", "description": "Physical I/O waits confirm memory pressure forcing data to disk — storage subsystem overloaded by demand that should be served from memory"}	null	2026-02-23 20:18:31.389826
1578	sqlserver	query	Find parallel DML statements with high overhead	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  CASE WHEN (qs.total_worker_time / NULLIF(qs.execution_count, 0)) > 0\\n    THEN CAST((qs.total_elapsed_time / NULLIF(qs.execution_count, 0)) AS float) /\\n         (qs.total_worker_time / NULLIF(qs.execution_count, 0))\\n    ELSE 0 END AS elapsed_to_cpu_ratio,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@Parallel=\\"true\\"]') = 1\\n  AND (st.text LIKE '%INSERT%' OR st.text LIKE '%UPDATE%' OR st.text LIKE '%DELETE%')\\n  AND qs.total_worker_time / NULLIF(qs.execution_count, 0) > 50000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "parallel DML statements with elapsed_to_cpu_ratio > 1.5", "description": "DML statements going parallel where elapsed time exceeds CPU time — threads idle on synchronization"}	null	2026-02-23 20:18:31.389827
1579	sqlserver	query	Check lock and latch contention from parallel DML	{"sql": "SELECT wait_type, wait_time_ms, waiting_tasks_count,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'LCK_M_IX', 'LCK_M_X',\\n  'PAGELATCH_EX', 'PAGELATCH_UP', 'WRITELOG')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "CXPACKET combined with lock or latch waits on write operations", "description": "Parallel DML threads contending on page locks, latches, and log writes"}	null	2026-02-23 20:18:31.389828
1580	sqlserver	query	Check for parallel INSERT with index maintenance overhead	{"sql": "SELECT TOP 10\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name,\\n  ios.leaf_insert_count, ios.leaf_update_count, ios.leaf_delete_count,\\n  ios.row_lock_count, ios.row_lock_wait_count,\\n  ios.page_lock_count, ios.page_lock_wait_count,\\n  ios.page_lock_wait_in_ms\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nWHERE ios.leaf_insert_count + ios.leaf_update_count + ios.leaf_delete_count > 10000\\n  AND ios.page_lock_wait_count > 100\\nORDER BY ios.page_lock_wait_in_ms DESC"}	{"condition": "tables with high DML and elevated page lock waits", "description": "Parallel DML on tables with multiple indexes causes lock contention during concurrent index maintenance"}	null	2026-02-23 20:18:31.389829
1593	sqlserver	query	Check AUTO_UPDATE_STATISTICS settings per database	{"sql": "SELECT name AS database_name,\\n  is_auto_update_stats_on,\\n  is_auto_update_stats_async_on,\\n  is_auto_create_stats_on,\\n  is_auto_create_stats_incremental_on\\nFROM sys.databases\\nWHERE database_id > 4\\n  AND state_desc = 'ONLINE'"}	{"condition": "is_auto_update_stats_on = 0 or is_auto_update_stats_async_on = 0", "description": "AUTO_UPDATE_STATISTICS disabled or synchronous mode — queries block during stats update"}	null	2026-02-23 20:18:31.389836
1586	sqlserver	query	Compare parallel plan CPU cost to serial alternative	{"sql": "SELECT TOP 10\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_worker_time AS total_cpu_all_threads,\\n  CAST((qs.total_worker_time * 1.0 / NULLIF(qs.total_elapsed_time, 0)) AS decimal(5,2)) AS parallelism_efficiency,\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Parallelism\\"])', 'int') AS exchange_count\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Parallelism\\"])', 'int') > 3\\n  AND qs.total_worker_time / NULLIF(qs.execution_count, 0) > 100000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "parallelism_efficiency < 2.0 despite high DOP — threads spending time in exchanges not computation", "description": "Low parallelism efficiency where total CPU time barely exceeds elapsed — exchange overhead dominates"}	null	2026-02-23 20:18:31.389832
4296	postgresql	query	Check for slow FDW queries in active sessions	{"sql": "SELECT pid, usename, query_start, NOW() - query_start AS duration, query FROM pg_stat_activity WHERE state = 'active' AND query ~* 'foreign|dblink|fdw' AND NOW() - query_start > interval ':threshold_seconds seconds'"}	{"condition": "row_count > 0", "description": "Long-running FDW queries confirm network latency impact"}	{"threshold_seconds": 60}	2026-02-25 00:28:52.405273
4041	postgresql	config_check	Check wal_level setting	{"sql": "SELECT name, setting FROM pg_settings WHERE name = 'wal_level'"}	{"condition": "setting = 'minimal'", "description": "wal_level=minimal does not log enough information for PITR"}	\N	2026-02-25 00:28:52.405273
1587	sqlserver	query	Find short parallel queries where startup overhead dominates	{"sql": "SELECT TOP 30\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  CASE WHEN qs.total_worker_time / NULLIF(qs.execution_count, 0) > 0\\n    THEN CAST(qs.total_elapsed_time AS float) / NULLIF(qs.total_worker_time, 0)\\n    ELSE 0 END AS elapsed_to_cpu_ratio,\\n  qp.query_plan.exist('//RelOp[@Parallel=\\"true\\"]') AS is_parallel,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@Parallel=\\"true\\"]') = 1\\n  AND qs.total_worker_time / NULLIF(qs.execution_count, 0) < 50000\\n  AND qs.execution_count > 500\\nORDER BY qs.execution_count DESC"}	{"condition": "parallel queries with avg_cpu < 50ms but high execution count — startup cost amortized poorly", "description": "Frequently executed short queries going parallel where thread startup overhead is significant"}	null	2026-02-23 20:18:31.389832
1588	sqlserver	query	Check worker thread availability and creation overhead	{"sql": "SELECT\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_worker_threads,\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers\\n   WHERE scheduler_id < 255 AND is_online = 1) AS active_workers,\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers\\n   WHERE scheduler_id < 255 AND is_online = 1) AS queued_requests,\\n  (SELECT wait_time_ms FROM sys.dm_os_wait_stats\\n   WHERE wait_type = 'THREADPOOL') AS threadpool_wait_ms,\\n  (SELECT waiting_tasks_count FROM sys.dm_os_wait_stats\\n   WHERE wait_type = 'THREADPOOL') AS threadpool_waits"}	{"condition": "active_workers > max_worker_threads * 0.7 or threadpool_waits > 0", "description": "Worker thread pool under pressure from parallel query thread demand"}	null	2026-02-23 20:18:31.389833
1589	sqlserver	query	Check cost threshold allowing small queries to go parallel	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS int) FROM sys.configurations\\n   WHERE name = 'cost threshold for parallelism') AS cost_threshold,\\n  (SELECT CAST(value_in_use AS int) FROM sys.configurations\\n   WHERE name = 'max degree of parallelism') AS maxdop,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans cp\\n   CROSS APPLY sys.dm_exec_query_plan(cp.plan_handle) qp\\n   WHERE qp.query_plan.exist('//RelOp[@Parallel=\\"true\\"]') = 1\\n     AND cp.usecounts > 100) AS frequent_parallel_plans"}	{"condition": "cost_threshold <= 5 and frequent_parallel_plans > 50", "description": "Low cost threshold pushing many short queries into parallel mode — startup overhead wasted"}	null	2026-02-23 20:18:31.389834
1590	sqlserver	query	Check for high MAXDOP on cache-sensitive workloads	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS int) FROM sys.configurations\\n   WHERE name = 'max degree of parallelism') AS maxdop,\\n  si.cpu_count AS logical_cpus,\\n  si.cpu_count / si.hyperthread_ratio AS physical_cores,\\n  si.numa_node_count,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Buffer cache hit ratio'\\n   AND object_name LIKE '%Buffer Manager%') AS buffer_cache_hit_ratio,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page lookups/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS page_lookups_sec\\nFROM sys.dm_os_sys_info si"}	{"condition": "maxdop > 4 with moderate buffer cache hit ratio (< 99%)", "description": "High DOP combined with buffer cache pressure — parallel threads evicting each other from CPU caches"}	null	2026-02-23 20:18:31.389834
1591	sqlserver	query	Find parallel queries with high logical reads relative to rows	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  CASE WHEN qs.total_rows > 0\\n    THEN qs.total_logical_reads / NULLIF(qs.total_rows, 0)\\n    ELSE 0 END AS reads_per_row,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@Parallel=\\"true\\"]') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.execution_count > 50\\nORDER BY reads_per_row DESC"}	{"condition": "reads_per_row > 50 on parallel queries — many page accesses per row returned", "description": "Parallel queries with high reads-per-row indicating poor data locality across threads"}	null	2026-02-23 20:18:31.389835
4482	postgresql	config_check	Check PostgreSQL block size configuration	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('block_size', 'wal_block_size')"}	{"condition": "row_count > 0", "description": "PostgreSQL block_size (default 8192) and wal_block_size should be aligned with underlying sector size"}	\N	2026-02-25 00:28:52.405273
1595	sqlserver	query	Check recent auto-stats operations and their duration	{"sql": "SELECT TOP 20\\n  object_name, index_name, stats_name,\\n  last_updated,\\n  modification_counter,\\n  rows AS total_rows,\\n  rows_sampled,\\n  CAST(rows_sampled * 100.0 / NULLIF(rows, 0) AS decimal(5,2)) AS sample_pct\\nFROM (\\n  SELECT\\n    OBJECT_NAME(s.object_id) AS object_name,\\n    i.name AS index_name,\\n    s.name AS stats_name,\\n    sp.last_updated,\\n    sp.modification_counter,\\n    sp.rows, sp.rows_sampled\\n  FROM sys.stats s\\n  CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\n  LEFT JOIN sys.indexes i ON s.object_id = i.object_id AND s.name = i.name\\n  WHERE s.object_id > 100\\n    AND sp.modification_counter > 0\\n) sub\\nORDER BY modification_counter DESC"}	{"condition": "tables with high modification_counter values pending statistics updates", "description": "Many modifications accumulated without auto-update — stale statistics affect query plans"}	null	2026-02-23 20:18:31.389838
1596	sqlserver	query	Find large tables with high modification counts below threshold	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.last_updated,\\n  sp.rows AS total_rows,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,4)) AS pct_modified,\\n  CASE WHEN sp.rows > 25000\\n    THEN CAST(SQRT(1000 * sp.rows) AS bigint)\\n    ELSE 500 + CAST(sp.rows * 0.20 AS bigint)\\n  END AS dynamic_threshold,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.object_id > 100\\n  AND sp.rows > 100000\\n  AND sp.modification_counter > SQRT(1000 * sp.rows) * 0.5\\nORDER BY sp.modification_counter DESC"}	{"condition": "large tables with modification_counter approaching or exceeding sqrt(1000 * rows) but auto-update not yet triggered", "description": "Tables with substantial modifications but below auto-update threshold — statistics becoming stale"}	null	2026-02-23 20:18:31.389839
1598	sqlserver	query	Check query plan quality on tables with stale statistics	{"sql": "SELECT TOP 10\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.modification_counter,\\n  sp.rows,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.max_worker_time / NULLIF(qs.min_worker_time, 0) AS cpu_variance\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nCROSS APPLY (\\n  SELECT TOP 1 qs.*\\n  FROM sys.dm_exec_query_stats qs\\n  CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\n  WHERE st.text LIKE '%' + OBJECT_NAME(s.object_id) + '%'\\n  ORDER BY qs.total_worker_time DESC\\n) qs\\nWHERE s.object_id > 100\\n  AND sp.modification_counter > SQRT(1000 * sp.rows) * 0.3\\nORDER BY sp.modification_counter DESC"}	{"condition": "high cpu_variance (>5x) on tables with high modification_counter", "description": "Plan quality degradation on tables with stale statistics — optimizer using outdated cardinality estimates"}	null	2026-02-23 20:18:31.38984
1599	sqlserver	query	Find tables with high modification count relative to sampled rows	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.last_updated,\\n  sp.rows AS total_rows,\\n  sp.rows_sampled,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,2)) AS pct_modified,\\n  DATEDIFF(HOUR, sp.last_updated, GETDATE()) AS hours_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.object_id > 100\\n  AND sp.modification_counter > sp.rows * 0.3\\nORDER BY sp.modification_counter DESC"}	{"condition": "tables with modification_counter > 30% of total rows", "description": "Tables received massive data changes (bulk load) — statistics no longer representative"}	null	2026-02-23 20:18:31.389841
1600	sqlserver	query	Check for recent bulk operations via minimal logging indicators	{"sql": "SELECT TOP 15\\n  OBJECT_NAME(p.object_id) AS table_name,\\n  p.rows AS current_rows,\\n  sp.rows AS stats_rows,\\n  ABS(p.rows - sp.rows) AS row_difference,\\n  CAST(ABS(p.rows - sp.rows) * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,2)) AS pct_growth,\\n  sp.last_updated,\\n  sp.modification_counter\\nFROM sys.partitions p\\nJOIN sys.stats s ON p.object_id = s.object_id\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE p.index_id IN (0, 1)\\n  AND p.rows > 10000\\n  AND ABS(p.rows - sp.rows) > sp.rows * 0.2\\nORDER BY ABS(p.rows - sp.rows) DESC"}	{"condition": "stats_rows differs significantly from current partition rows (>20% growth/shrinkage)", "description": "Row count changed dramatically since last stats update — bulk load or delete occurred"}	null	2026-02-23 20:18:31.389841
1601	sqlserver	query	Find filtered statistics with high modification counts	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  s.has_filter,\\n  s.filter_definition,\\n  sp.last_updated,\\n  sp.rows, sp.rows_sampled, sp.unfiltered_rows,\\n  sp.modification_counter,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.has_filter = 1\\n  AND sp.modification_counter > 0\\nORDER BY sp.modification_counter DESC"}	{"condition": "filtered statistics with high modification_counter relative to rows", "description": "Filtered statistics with accumulated modifications — histogram no longer matches filtered subset"}	null	2026-02-23 20:18:31.389842
1602	sqlserver	query	Check if filtered indexes are being used despite stale stats	{"sql": "SELECT TOP 15\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.has_filter,\\n  i.filter_definition,\\n  ius.user_seeks, ius.user_scans,\\n  ius.last_user_seek, ius.last_user_scan,\\n  sp.modification_counter,\\n  sp.last_updated\\nFROM sys.indexes i\\nJOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id\\n  AND ius.database_id = DB_ID()\\nJOIN sys.stats s ON i.object_id = s.object_id AND i.name = s.name\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE i.has_filter = 1\\n  AND (ius.user_seeks > 100 OR ius.user_scans > 100)\\n  AND sp.modification_counter > sp.rows * 0.1\\nORDER BY sp.modification_counter DESC"}	{"condition": "actively used filtered indexes with stale statistics (>10% modifications)", "description": "Filtered indexes being used for queries but underlying statistics are stale"}	null	2026-02-23 20:18:31.389842
1604	sqlserver	query	Find columns used in predicates without statistics	{"sql": "SELECT\\n  OBJECT_NAME(c.object_id) AS table_name,\\n  c.name AS column_name,\\n  t.name AS data_type,\\n  c.column_id,\\n  p.rows AS table_rows\\nFROM sys.columns c\\nJOIN sys.types t ON c.user_type_id = t.user_type_id\\nJOIN sys.partitions p ON c.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE c.object_id > 100\\n  AND p.rows > 1000\\n  AND NOT EXISTS (\\n    SELECT 1 FROM sys.stats_columns sc\\n    JOIN sys.stats s ON sc.object_id = s.object_id AND sc.stats_id = s.stats_id\\n    WHERE sc.object_id = c.object_id AND sc.column_id = c.column_id\\n  )\\nORDER BY p.rows DESC"}	{"condition": "columns on large tables with no statistics whatsoever", "description": "Columns without any statistics — optimizer uses 30% default selectivity estimates"}	null	2026-02-23 20:18:31.389843
1606	sqlserver	query	Find statistics with low sample rates on large tables	{"sql": "SELECT TOP 25\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.rows AS total_rows,\\n  sp.rows_sampled,\\n  CAST(sp.rows_sampled * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,2)) AS sample_pct,\\n  sp.steps AS histogram_steps,\\n  sp.last_updated,\\n  sp.modification_counter\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.object_id > 100\\n  AND sp.rows > 100000\\n  AND sp.rows_sampled < sp.rows * 0.10\\nORDER BY sp.rows DESC"}	{"condition": "large tables with sample percentage < 10%", "description": "Statistics based on very small sample — may miss data skew and outlier distributions"}	null	2026-02-23 20:18:31.389844
1607	sqlserver	query	Check for cardinality estimation errors on low-sample statistics	{"sql": "SELECT TOP 15\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.rows_sampled,\\n  CAST(sp.rows_sampled * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,2)) AS sample_pct,\\n  sp.steps AS histogram_steps,\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.max_worker_time / NULLIF(qs.min_worker_time, 0) AS cpu_variance\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nCROSS APPLY (\\n  SELECT TOP 1 qs.*\\n  FROM sys.dm_exec_query_stats qs\\n  CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\n  WHERE st.text LIKE '%' + OBJECT_NAME(s.object_id) + '%'\\n  ORDER BY qs.total_worker_time DESC\\n) qs\\nWHERE s.object_id > 100\\n  AND sp.rows > 100000\\n  AND sp.rows_sampled < sp.rows * 0.10\\nORDER BY qs.total_worker_time DESC"}	{"condition": "high cpu_variance (>5x) on queries touching low-sample tables", "description": "Query performance instability on tables with insufficient statistics sampling"}	null	2026-02-23 20:18:31.389845
3987	postgresql	query	Check for gaps in WAL archive sequence	{"sql": "SELECT last_archived_wal, last_failed_wal, failed_count, last_archived_time FROM pg_stat_archiver"}	{"condition": "last_failed_wal IS NOT NULL AND last_failed_wal < last_archived_wal", "description": "Failed WAL earlier than last archived indicates sequence gap from manual intervention"}	\N	2026-02-25 00:28:52.405273
1608	sqlserver	query	Find stale multi-column statistics	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  s.auto_created,\\n  s.user_created,\\n  (\\n    SELECT STRING_AGG(COL_NAME(sc.object_id, sc.column_id), ', ')\\n    WITHIN GROUP (ORDER BY sc.stats_column_id)\\n    FROM sys.stats_columns sc\\n    WHERE sc.object_id = s.object_id AND sc.stats_id = s.stats_id\\n  ) AS column_list,\\n  sp.last_updated,\\n  sp.rows, sp.rows_sampled,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,2)) AS pct_modified,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.object_id > 100\\n  AND (SELECT COUNT(*) FROM sys.stats_columns sc\\n       WHERE sc.object_id = s.object_id AND sc.stats_id = s.stats_id) > 1\\n  AND sp.modification_counter > 0\\nORDER BY sp.modification_counter DESC"}	{"condition": "multi-column statistics with high modification_counter or days_since_update > 7", "description": "Multi-column statistics outdated — correlation information no longer accurate"}	null	2026-02-23 20:18:31.389845
1609	sqlserver	query	Check queries that rely on multi-column statistics	{"sql": "SELECT TOP 15\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.max_worker_time / NULLIF(qs.min_worker_time, 0) AS cpu_variance,\\n  qp.query_plan.value('count(//ColumnReference[@Database])', 'int') AS column_refs,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.max_worker_time / NULLIF(qs.min_worker_time, 0) > 10\\n  AND qs.execution_count > 50\\nORDER BY qs.total_worker_time DESC"}	{"condition": "queries with high cpu_variance > 10x — unstable plans from stale correlation data", "description": "Plan instability from optimizer using outdated multi-column correlation estimates"}	null	2026-02-23 20:18:31.389846
1610	sqlserver	query	Find statistics with old histograms on tables with significant deletes	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.last_updated,\\n  sp.rows AS stats_rows,\\n  p.rows AS actual_rows,\\n  CASE WHEN sp.rows > p.rows\\n    THEN sp.rows - p.rows ELSE 0 END AS deleted_rows_estimate,\\n  sp.modification_counter,\\n  sp.steps AS histogram_steps,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.partitions p ON s.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE s.object_id > 100\\n  AND sp.rows > p.rows * 1.2\\nORDER BY (sp.rows - p.rows) DESC"}	{"condition": "stats_rows > actual_rows * 1.2 — statistics think table is larger than it is", "description": "Statistics contain stale row counts from before bulk deletes — histogram includes deleted value ranges"}	null	2026-02-23 20:18:31.389847
1635	sqlserver	query	Check page verification setting per database	{"sql": "SELECT d.name, d.page_verify_option_desc,\\n  d.target_recovery_time_in_seconds,\\n  d.recovery_model_desc\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.page_verify_option_desc <> 'CHECKSUM'\\nORDER BY d.name"}	{"condition": "row_count > 0 AND page_verify_option_desc IN ('TORN_PAGE_DETECTION', 'NONE')", "description": "Databases not using CHECKSUM page verification — suboptimal data integrity protection"}	null	2026-02-23 20:18:31.389847
5758	postgresql	config_check	Check for pgAudit extension with remote logging	{"sql": "SELECT extname, extversion FROM pg_extension WHERE extname = 'pgaudit'"}	{"condition": "row_count = 0", "description": "pgAudit not installed — no structured audit trail that could be shipped remotely"}	\N	2026-02-25 00:28:52.405273
1611	sqlserver	query	Check queries affected by overestimation from ghost ranges	{"sql": "SELECT TOP 15\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  CAST(qs.total_used_grant_kb * 100.0 / NULLIF(qs.total_grant_kb, 0) AS decimal(5,2)) AS grant_utilization_pct\\nFROM sys.dm_exec_query_stats qs\\nWHERE qs.total_grant_kb > 0\\n  AND qs.total_used_grant_kb * 100.0 / NULLIF(qs.total_grant_kb, 0) < 20\\n  AND qs.execution_count > 50\\nORDER BY (qs.total_grant_kb - qs.total_used_grant_kb) DESC"}	{"condition": "grant_utilization_pct < 20% — large memory grants with low utilization", "description": "Queries over-requesting memory grants due to overestimated cardinality from stale histograms"}	null	2026-02-23 20:18:31.389848
1612	sqlserver	query	Find index key columns without dedicated statistics	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.type_desc,\\n  ic.key_ordinal,\\n  COL_NAME(ic.object_id, ic.column_id) AS column_name,\\n  p.rows AS table_rows\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\nJOIN sys.partitions p ON i.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE i.object_id > 100\\n  AND ic.key_ordinal > 1\\n  AND p.rows > 10000\\n  AND NOT EXISTS (\\n    SELECT 1 FROM sys.stats_columns sc\\n    JOIN sys.stats s ON sc.object_id = s.object_id AND sc.stats_id = s.stats_id\\n    WHERE sc.object_id = ic.object_id\\n      AND sc.column_id = ic.column_id\\n      AND sc.stats_column_id = 1\\n  )\\nORDER BY p.rows DESC"}	{"condition": "non-leading index columns on large tables without dedicated leading-column statistics", "description": "Index columns used in predicates lack histogram — optimizer uses density vector (average) instead"}	null	2026-02-23 20:18:31.389849
4297	postgresql	query	Check for active autovacuum workers	{"sql": "SELECT pid, query, query_start, NOW() - query_start AS duration, wait_event_type, wait_event FROM pg_stat_activity WHERE backend_type = 'autovacuum worker' AND state = 'active'"}	{"condition": "row_count > 0", "description": "Autovacuum workers active; may compete with scheduled jobs for resources"}	\N	2026-02-25 00:28:52.405273
1613	sqlserver	query	Check for suboptimal index usage patterns indicating stats gaps	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  ius.user_seeks, ius.user_scans, ius.user_lookups,\\n  ius.user_scans * 1.0 / NULLIF(ius.user_seeks + ius.user_scans, 0) AS scan_ratio,\\n  ius.last_user_scan\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND i.type_desc <> 'HEAP'\\n  AND ius.user_scans > ius.user_seeks\\n  AND ius.user_scans > 100\\nORDER BY ius.user_scans DESC"}	{"condition": "scan_ratio > 0.5 on non-clustered indexes — scans where seeks should be possible", "description": "Indexes being scanned instead of seeked — optimizer cannot estimate selectivity without column statistics"}	null	2026-02-23 20:18:31.389849
11383	mysql	config_check	Check log file locations	{"sql": "SELECT @@datadir AS datadir, @@log_error AS error_log, @@general_log_file AS general_log_file"}	{"condition": "paths are identified", "description": "Log file locations identified for disk space check"}	\N	2026-03-01 06:30:58.706791
1616	sqlserver	query	Find tables with high update modification counts	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,2)) AS pct_modified,\\n  p.rows AS actual_rows,\\n  DATEDIFF(HOUR, sp.last_updated, GETDATE()) AS hours_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.partitions p ON s.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE s.object_id > 100\\n  AND sp.modification_counter > sp.rows * 0.2\\n  AND ABS(sp.rows - p.rows) < p.rows * 0.05\\nORDER BY sp.modification_counter DESC"}	{"condition": "high modification_counter (>20% of rows) but stable row count (rows haven't changed) — in-place UPDATE pattern", "description": "Tables with many modifications but stable row count — data cleansing updated values without adding/removing rows"}	null	2026-02-23 20:18:31.389851
1617	sqlserver	query	Check for index operational stats showing heavy updates	{"sql": "SELECT TOP 15\\n  OBJECT_NAME(os.object_id) AS table_name,\\n  i.name AS index_name,\\n  os.leaf_update_count,\\n  os.leaf_insert_count,\\n  os.leaf_delete_count,\\n  CAST(os.leaf_update_count * 100.0 /\\n    NULLIF(os.leaf_insert_count + os.leaf_update_count + os.leaf_delete_count, 0)\\n    AS decimal(5,2)) AS update_pct\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os\\nJOIN sys.indexes i ON os.object_id = i.object_id AND os.index_id = i.index_id\\nWHERE os.object_id > 100\\n  AND os.leaf_update_count > os.leaf_insert_count\\n  AND os.leaf_update_count > 10000\\nORDER BY os.leaf_update_count DESC"}	{"condition": "tables where updates dominate over inserts/deletes — characteristic of data cleansing", "description": "Update-heavy pattern confirms data cleansing — value distributions changed in place"}	null	2026-02-23 20:18:31.389852
1618	sqlserver	query	Check for query plan instability on cleansed tables	{"sql": "SELECT TOP 10\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.max_worker_time / NULLIF(qs.min_worker_time, 0) AS cpu_variance,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.max_logical_reads / NULLIF(qs.min_logical_reads, 0) AS read_variance,\\n  qs.plan_generation_num\\nFROM sys.dm_exec_query_stats qs\\nWHERE qs.max_worker_time / NULLIF(qs.min_worker_time, 0) > 10\\n  AND qs.plan_generation_num > 1\\n  AND qs.execution_count > 20\\nORDER BY qs.plan_generation_num DESC"}	{"condition": "high cpu_variance > 10x and multiple plan regenerations", "description": "Queries with extreme performance variance and recompilation — stale stats from data cleansing"}	null	2026-02-23 20:18:31.389852
1619	sqlserver	query	Find partitioned tables without incremental statistics	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  s.name AS stats_name,\\n  s.is_incremental,\\n  COUNT(DISTINCT p.partition_number) AS partition_count,\\n  SUM(p.rows) AS total_rows,\\n  MAX(sp.last_updated) AS last_stats_update,\\n  MAX(sp.modification_counter) AS max_modifications\\nFROM sys.indexes i\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nJOIN sys.stats s ON i.object_id = s.object_id\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.partition_schemes ps ON i.data_space_id = ps.data_space_id\\nWHERE i.object_id > 100\\n  AND s.is_incremental = 0\\n  AND p.rows > 0\\nGROUP BY i.object_id, i.name, s.name, s.is_incremental\\nHAVING COUNT(DISTINCT p.partition_number) > 3\\nORDER BY SUM(p.rows) DESC"}	{"condition": "partitioned tables with > 3 partitions where is_incremental = 0", "description": "Large partitioned tables without incremental statistics — full scans required for every stats update"}	null	2026-02-23 20:18:31.389853
1620	sqlserver	query	Check database-level incremental statistics setting	{"sql": "SELECT name AS database_name,\\n  is_auto_create_stats_incremental_on,\\n  is_auto_create_stats_on,\\n  is_auto_update_stats_on,\\n  compatibility_level\\nFROM sys.databases\\nWHERE database_id = DB_ID()"}	{"condition": "is_auto_create_stats_incremental_on = 0", "description": "Auto-create incremental statistics disabled — new stats won't be partition-aware"}	null	2026-02-23 20:18:31.389854
1621	sqlserver	query	Check stats update duration impact via recent operations	{"sql": "SELECT TOP 15\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.rows,\\n  sp.rows_sampled,\\n  CAST(sp.rows_sampled * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,2)) AS sample_pct,\\n  sp.last_updated,\\n  sp.modification_counter,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.partition_schemes ps ON EXISTS (\\n  SELECT 1 FROM sys.indexes i\\n  WHERE i.object_id = s.object_id AND i.data_space_id = ps.data_space_id\\n)\\nWHERE s.object_id > 100\\n  AND sp.rows > 1000000\\n  AND s.is_incremental = 0\\nORDER BY sp.rows DESC"}	{"condition": "large partitioned tables with infrequent stats updates (days_since_update > 3)", "description": "Large tables with stale stats — full-scan cost prevents frequent updates"}	null	2026-02-23 20:18:31.389854
1631	sqlserver	query	Check lazy writer activity and free list stalls	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Lazy writes/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS lazy_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Free list stalls/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS free_list_stalls_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page life expectancy'\\n   AND object_name LIKE '%Buffer Manager%') AS ple_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec"}	{"condition": "free_list_stalls_sec > 0 OR (lazy_writes_sec > 20 AND ple_seconds < 300)", "description": "Free list stalls indicate lazy writer cannot free pages fast enough; low PLE with high lazy writes confirms memory pressure causing dirty page backlog"}	null	2026-02-23 20:18:31.389861
1632	sqlserver	query	Check dirty page accumulation in buffer pool	{"sql": "SELECT\\n  SUM(CASE WHEN is_modified = 1 THEN 1 ELSE 0 END) AS dirty_pages,\\n  COUNT(*) AS total_pages,\\n  CAST(SUM(CASE WHEN is_modified = 1 THEN 1 ELSE 0 END) AS FLOAT)\\n    / NULLIF(COUNT(*), 0) AS dirty_ratio,\\n  SUM(CASE WHEN is_modified = 1 THEN 1 ELSE 0 END) * 8 / 1024 AS dirty_mb\\nFROM sys.dm_os_buffer_descriptors\\nWHERE database_id > 4"}	{"condition": "dirty_ratio > 0.30", "description": "Over 30% dirty pages in user database buffer space — lazy writer is falling behind, leading to large checkpoint flushes"}	null	2026-02-23 20:18:31.389861
2284	sqlserver	query	Check for PREEMPTIVE waits holding threads outside SQL Server scheduling	{"sql": "SELECT TOP 15\\n  wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  CASE WHEN waiting_tasks_count > 0\\n    THEN wait_time_ms / waiting_tasks_count ELSE 0 END AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type LIKE 'PREEMPTIVE_%'\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PREEMPTIVE wait types with avg_wait_ms > 100", "description": "Worker threads spending extended time in preemptive mode (outside SQL OS scheduling) are effectively unavailable for other requests"}	null	2026-02-23 20:18:31.39028
1622	sqlserver	query	Find queries with large actual-vs-estimated row differences	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_actual_rows,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_spills > 0\\n  AND qs.execution_count > 10\\nORDER BY qs.total_spills DESC"}	{"condition": "queries with frequent spills — optimizer underestimated rows due to assuming column independence", "description": "Sort/hash spills from underestimated cardinality caused by correlated column predicates"}	null	2026-02-23 20:18:31.389855
1624	sqlserver	query	Check CE model and estimation issues	{"sql": "SELECT\\n  d.name AS database_name,\\n  d.compatibility_level,\\n  CASE\\n    WHEN d.compatibility_level >= 120 THEN 'New CE (2014+) — base containment'\\n    ELSE 'Legacy CE — independence assumption'\\n  END AS cardinality_estimator,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_stats qs\\n   WHERE qs.total_spills > 0 AND qs.execution_count > 5) AS queries_with_spills\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "legacy CE (compat < 120) or many queries_with_spills despite new CE", "description": "Cardinality estimator struggling with correlated columns — multi-column statistics needed"}	null	2026-02-23 20:18:31.389856
1626	sqlserver	query	Check if computed columns are used in queries without statistics	{"sql": "SELECT\\n  OBJECT_NAME(cc.object_id) AS table_name,\\n  cc.name AS computed_column,\\n  cc.definition,\\n  cc.is_persisted,\\n  p.rows AS table_rows,\\n  CASE WHEN EXISTS (\\n    SELECT 1 FROM sys.stats_columns sc\\n    WHERE sc.object_id = cc.object_id AND sc.column_id = cc.column_id\\n  ) THEN 'Yes' ELSE 'No' END AS has_statistics,\\n  CASE WHEN EXISTS (\\n    SELECT 1 FROM sys.index_columns ic\\n    WHERE ic.object_id = cc.object_id AND ic.column_id = cc.column_id\\n  ) THEN 'Yes' ELSE 'No' END AS in_index\\nFROM sys.computed_columns cc\\nJOIN sys.partitions p ON cc.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE cc.object_id > 100\\n  AND NOT EXISTS (\\n    SELECT 1 FROM sys.stats_columns sc\\n    WHERE sc.object_id = cc.object_id AND sc.column_id = cc.column_id\\n  )\\n  AND p.rows > 10000\\nORDER BY p.rows DESC"}	{"condition": "computed columns on large tables without any statistics", "description": "Computed columns used in queries but optimizer has no distribution information"}	null	2026-02-23 20:18:31.389857
3483	postgresql	query	Check replication lag on standby	{"sql": "SELECT CASE WHEN pg_is_in_recovery() THEN pg_last_wal_replay_lsn() ELSE NULL END AS replay_lsn, CASE WHEN pg_is_in_recovery() THEN pg_last_wal_receive_lsn() ELSE NULL END AS receive_lsn, CASE WHEN pg_is_in_recovery() THEN now() - pg_last_xact_replay_timestamp() ELSE NULL END AS replay_lag"}	{"condition": "replay_lag > :lag_threshold::interval", "description": "Standby is significantly behind primary — backups from standby are stale"}	{"lag_threshold": "5 minutes"}	2026-02-25 00:28:52.405273
1627	sqlserver	query	Check for non-persisted computed columns preventing auto-stats	{"sql": "SELECT\\n  OBJECT_NAME(cc.object_id) AS table_name,\\n  cc.name AS computed_column,\\n  cc.definition,\\n  cc.is_persisted,\\n  cc.is_nullable,\\n  t.name AS data_type,\\n  CASE WHEN cc.is_persisted = 0 AND t.name IN ('float', 'real', 'decimal', 'numeric')\\n    THEN 'Imprecise non-persisted — stats may be unreliable'\\n    ELSE 'OK' END AS stats_reliability\\nFROM sys.computed_columns cc\\nJOIN sys.types t ON cc.system_type_id = t.system_type_id\\nWHERE cc.object_id > 100\\nORDER BY cc.is_persisted, OBJECT_NAME(cc.object_id)"}	{"condition": "non-persisted computed columns — statistics require computing expression for every sampled row", "description": "Non-persisted computed columns make statistics updates expensive and may prevent auto-creation"}	null	2026-02-23 20:18:31.389858
1628	sqlserver	query	Find statistics with high modification count on tables used for aggregations	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,2)) AS pct_modified,\\n  sp.steps AS histogram_steps,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update,\\n  (\\n    SELECT COUNT(DISTINCT sc.column_id)\\n    FROM sys.stats_columns sc\\n    WHERE sc.object_id = s.object_id AND sc.stats_id = s.stats_id\\n  ) AS columns_in_stats\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE s.object_id > 100\\n  AND sp.modification_counter > sp.rows * 0.05\\n  AND sp.rows > 10000\\nORDER BY sp.modification_counter DESC"}	{"condition": "statistics with > 5% modifications on tables used in queries", "description": "Statistics with stale density information — distinct value count has likely changed"}	null	2026-02-23 20:18:31.389859
1629	sqlserver	query	Check for GROUP BY and DISTINCT queries with estimation errors	{"sql": "SELECT TOP 15\\n  qs.execution_count,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  CASE WHEN qs.total_grant_kb > 0\\n    THEN CAST(qs.total_used_grant_kb * 100.0 / NULLIF(qs.total_grant_kb, 0) AS decimal(5,2))\\n    ELSE 0 END AS grant_utilization_pct,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE (st.text LIKE '%GROUP BY%' OR st.text LIKE '%DISTINCT%')\\n  AND qs.execution_count > 10\\n  AND (qs.total_spills > 0\\n    OR qs.total_used_grant_kb * 100.0 / NULLIF(qs.total_grant_kb, 0) < 20\\n    OR qs.total_used_grant_kb * 100.0 / NULLIF(qs.total_grant_kb, 0) > 200)\\nORDER BY qs.total_worker_time DESC"}	{"condition": "GROUP BY/DISTINCT queries with spills (underestimate) or low grant utilization (overestimate)", "description": "Aggregation queries with poor estimates from outdated density — distinct count has shifted"}	null	2026-02-23 20:18:31.389859
1630	sqlserver	query	Verify density staleness by comparing stats rows to current data	{"sql": "SELECT TOP 10\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name,\\n  sp.rows AS stats_rows,\\n  p.rows AS actual_rows,\\n  sp.rows_sampled,\\n  CAST(sp.rows_sampled * 100.0 / NULLIF(sp.rows, 0) AS decimal(10,2)) AS sample_pct,\\n  sp.modification_counter,\\n  sp.steps\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.partitions p ON s.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE s.object_id > 100\\n  AND sp.modification_counter > sp.rows * 0.05\\n  AND sp.rows > 10000\\nORDER BY sp.modification_counter DESC"}	{"condition": "significant gap between stats_rows and actual_rows or high modification_counter", "description": "Density vector based on outdated row count and distinct value estimates"}	null	2026-02-23 20:18:31.38986
1633	sqlserver	query	Check background writer and lazy writer counters	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Lazy writes/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS lazy_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Background writer pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS bg_writer_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page life expectancy'\\n   AND object_name LIKE '%Buffer Manager%') AS ple_seconds"}	{"condition": "lazy_writes_sec = 0 AND bg_writer_pages_sec = 0 AND checkpoint_pages_sec = 0", "description": "All background flush processes showing zero activity — no proactive dirty page management"}	null	2026-02-23 20:18:31.389862
1634	sqlserver	query	Check dirty page accumulation without background flushing	{"sql": "SELECT\\n  SUM(CASE WHEN is_modified = 1 THEN 1 ELSE 0 END) AS dirty_pages,\\n  COUNT(*) AS total_pages,\\n  CAST(SUM(CASE WHEN is_modified = 1 THEN 1 ELSE 0 END) AS FLOAT)\\n    / NULLIF(COUNT(*), 0) AS dirty_ratio\\nFROM sys.dm_os_buffer_descriptors\\nWHERE database_id > 4"}	{"condition": "dirty_pages > 10000 AND dirty_ratio > 0.20", "description": "Significant dirty page buildup with no background flushing — next checkpoint will be an I/O storm"}	null	2026-02-23 20:18:31.389863
3613	postgresql	query	Check for pgAudit extension	{"sql": "SELECT extname, extversion FROM pg_extension WHERE extname = 'pgaudit'"}	{"condition": "row_count = 0", "description": "pgAudit extension not installed — no detailed SQL auditing"}	\N	2026-02-25 00:28:52.405273
1636	sqlserver	query	Check if non-CHECKSUM databases have significant write I/O	{"sql": "SELECT DB_NAME(vfs.database_id) AS db_name,\\n  d.page_verify_option_desc,\\n  SUM(vfs.num_of_writes) AS total_writes,\\n  SUM(vfs.io_stall_write_ms) AS total_write_stall_ms,\\n  SUM(vfs.io_stall_write_ms) / NULLIF(SUM(vfs.num_of_writes), 0) AS avg_write_latency_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.databases d ON d.database_id = vfs.database_id\\nWHERE d.database_id > 4\\n  AND d.page_verify_option_desc <> 'CHECKSUM'\\nGROUP BY vfs.database_id, d.page_verify_option_desc\\nHAVING SUM(vfs.num_of_writes) > 10000\\nORDER BY SUM(vfs.num_of_writes) DESC"}	{"condition": "total_writes > 10000 AND avg_write_latency_ms > 5", "description": "High-write databases using suboptimal page verification with elevated write latency"}	null	2026-02-23 20:18:31.389863
1637	sqlserver	query	Check filegroup distribution per database	{"sql": "SELECT DB_NAME(database_id) AS db_name,\\n  file_id, type_desc, physical_name,\\n  size * 8 / 1024 AS size_mb,\\n  (SELECT COUNT(DISTINCT data_space_id) FROM sys.filegroups) AS filegroup_count\\nFROM sys.master_files\\nWHERE database_id > 4\\n  AND type_desc = 'ROWS'\\nORDER BY database_id, file_id"}	{"condition": "filegroup_count = 1 AND size_mb > 10240", "description": "Large database (>10 GB) with only PRIMARY filegroup — all data on single set of files"}	null	2026-02-23 20:18:31.389864
1639	sqlserver	query	Check Page Life Expectancy and buffer pool pressure	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page life expectancy'\\n   AND object_name LIKE '%Buffer Manager%') AS ple_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Buffer cache hit ratio'\\n   AND object_name LIKE '%Buffer Manager%') AS cache_hit_ratio,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page reads/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS page_reads_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Lazy writes/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS lazy_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Free list stalls/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS free_list_stalls_sec"}	{"condition": "ple_seconds < 300 OR free_list_stalls_sec > 0", "description": "Low PLE (<300s) or free list stalls indicate buffer pool is too small for the working set"}	null	2026-02-23 20:18:31.389866
1640	sqlserver	query	Compare database sizes to buffer pool allocation	{"sql": "SELECT\\n  (SELECT COUNT(*) * 8 / 1024 FROM sys.dm_os_buffer_descriptors) AS buffer_pool_mb,\\n  (SELECT SUM(size * 8 / 1024) FROM sys.master_files\\n   WHERE type_desc = 'ROWS' AND database_id > 4) AS total_data_mb,\\n  (SELECT value_in_use FROM sys.configurations\\n   WHERE name = 'max server memory (MB)') AS max_server_memory_mb"}	{"condition": "total_data_mb > buffer_pool_mb * 3", "description": "Total data size significantly exceeds buffer pool — working set cannot fit in memory"}	null	2026-02-23 20:18:31.389866
1642	sqlserver	query	Check checkpoint wait types and durations	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'CHECKPOINT_QUEUE', 'CHKPT', 'WRITELOG',\\n  'IO_COMPLETION', 'PAGEIOLATCH_EX', 'PAGEIOLATCH_UP'\\n)\\nAND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "CHKPT avg_wait_ms > 1000 OR CHECKPOINT_QUEUE waiting_tasks_count > 0", "description": "Extended checkpoint waits or queued checkpoint requests indicate checkpoint coordinator bottleneck"}	null	2026-02-23 20:18:31.389868
1643	sqlserver	query	Check indirect checkpoint progress and dirty page rate	{"sql": "SELECT d.name,\\n  d.target_recovery_time_in_seconds,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Background writer pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS bg_writer_pages_sec,\\n  SUM(CASE WHEN bd.is_modified = 1 THEN 1 ELSE 0 END) AS dirty_pages\\nFROM sys.databases d\\nLEFT JOIN sys.dm_os_buffer_descriptors bd ON bd.database_id = d.database_id\\nWHERE d.database_id > 4\\nGROUP BY d.name, d.target_recovery_time_in_seconds\\nHAVING SUM(CASE WHEN bd.is_modified = 1 THEN 1 ELSE 0 END) > 5000\\nORDER BY dirty_pages DESC"}	{"condition": "dirty_pages > 5000 AND checkpoint_pages_sec > 200", "description": "High dirty page count despite active checkpoint — coordinator cannot keep up with write rate"}	null	2026-02-23 20:18:31.389868
3487	postgresql	query	Check pg_cron or scheduled backup jobs	{"sql": "SELECT jobid, schedule, command, nodename, active, jobname FROM cron.job WHERE command LIKE '%backup%' OR command LIKE '%pg_dump%' OR command LIKE '%pg_basebackup%' ORDER BY jobid"}	{"condition": "row_count > 0 AND active = true", "description": "Backup cron jobs exist and are active"}	\N	2026-02-25 00:28:52.405273
2211	sqlserver	query	Identify top parallel thread consumers	{"sql": "SELECT TOP 10\\n  r.session_id,\\n  r.dop,\\n  r.parallel_worker_count,\\n  r.status,\\n  r.total_elapsed_time / 1000 AS elapsed_sec,\\n  r.wait_type,\\n  r.wait_time,\\n  t.text AS query_text\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE r.parallel_worker_count > 0\\nORDER BY r.parallel_worker_count DESC"}	{"condition": "SUM(parallel_worker_count) > max_workers_count * 0.50", "description": "Parallel queries consuming >50% of available worker threads"}	null	2026-02-23 20:18:31.389869
1647	sqlserver	query	Check background writer I/O rate confirming aggressive flushing	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Background writer pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS bg_writer_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Recovery Log Checkpoint pages/sec'\\n   AND object_name LIKE '%Databases%'\\n   AND instance_name = '_Total') AS indirect_cp_pages_sec,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_write_latch_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'PAGEIOLATCH_EX'"}	{"condition": "bg_writer_pages_sec > 100 OR avg_write_latch_ms > 15", "description": "High background writer rate or elevated write latches confirm aggressive RTO is causing continuous I/O contention"}	null	2026-02-23 20:18:31.389871
1648	sqlserver	query	Check databases without indirect checkpoint enabled	{"sql": "SELECT d.name, d.target_recovery_time_in_seconds,\\n  d.recovery_model_desc, d.log_reuse_wait_desc,\\n  mf.size * 8 / 1024 AS data_size_mb\\nFROM sys.databases d\\nJOIN sys.master_files mf ON d.database_id = mf.database_id\\nWHERE d.database_id > 4\\n  AND d.target_recovery_time_in_seconds = 0\\n  AND mf.type_desc = 'ROWS'\\nORDER BY mf.size DESC"}	{"condition": "target_recovery_time_in_seconds = 0 AND data_size_mb > 1024", "description": "Large databases using automatic checkpoint (target_recovery_time = 0) — checkpoint executes as batch operation"}	null	2026-02-23 20:18:31.389871
1649	sqlserver	query	Check CHKPT waits confirming checkpoint blocking	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CHKPT', 'CHECKPOINT_QUEUE', 'WRITELOG')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "CHKPT wait_time_ms > 10000", "description": "Significant time spent waiting on checkpoint operations confirms synchronous checkpoint impact"}	null	2026-02-23 20:18:31.389872
1650	sqlserver	query	Check multiple databases with active checkpoint indicators	{"sql": "SELECT d.name, d.target_recovery_time_in_seconds,\\n  d.log_reuse_wait_desc,\\n  SUM(CASE WHEN bd.is_modified = 1 THEN 1 ELSE 0 END) AS dirty_pages,\\n  SUM(CASE WHEN bd.is_modified = 1 THEN 1 ELSE 0 END) * 8 / 1024 AS dirty_mb\\nFROM sys.databases d\\nJOIN sys.dm_os_buffer_descriptors bd ON bd.database_id = d.database_id\\nWHERE d.database_id > 4\\nGROUP BY d.name, d.target_recovery_time_in_seconds, d.log_reuse_wait_desc\\nHAVING SUM(CASE WHEN bd.is_modified = 1 THEN 1 ELSE 0 END) > 1000\\nORDER BY dirty_pages DESC"}	{"condition": "multiple databases with dirty_pages > 1000", "description": "Multiple databases with significant dirty page counts — concurrent checkpoints will compete for I/O"}	null	2026-02-23 20:18:31.389873
1652	sqlserver	query	Check data file count per database relative to I/O load	{"sql": "SELECT DB_NAME(mf.database_id) AS db_name,\\n  COUNT(*) AS data_file_count,\\n  SUM(mf.size * 8 / 1024) AS total_data_mb,\\n  MAX(vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0)) AS max_write_latency_ms\\nFROM sys.master_files mf\\nLEFT JOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\n  ON mf.database_id = vfs.database_id AND mf.file_id = vfs.file_id\\nWHERE mf.database_id > 4\\n  AND mf.type_desc = 'ROWS'\\nGROUP BY mf.database_id\\nHAVING SUM(mf.size * 8 / 1024) > 5120 AND COUNT(*) <= 2\\nORDER BY total_data_mb DESC"}	{"condition": "data_file_count <= 2 AND total_data_mb > 5120", "description": "Large database (>5 GB) with only 1-2 data files — checkpoint I/O cannot be parallelized effectively"}	null	2026-02-23 20:18:31.389874
4298	postgresql	query	Check for lock contention between autovacuum and user queries	{"sql": "SELECT a.pid AS autovac_pid, a.query AS autovac_query, b.pid AS blocked_pid, b.query AS blocked_query FROM pg_stat_activity a JOIN pg_locks la ON a.pid = la.pid JOIN pg_locks lb ON la.relation = lb.relation AND la.pid != lb.pid AND NOT lb.granted JOIN pg_stat_activity b ON lb.pid = b.pid WHERE a.backend_type = 'autovacuum worker'"}	{"condition": "row_count > 0", "description": "Lock contention between autovacuum and other processes confirmed"}	\N	2026-02-25 00:28:52.405273
1653	sqlserver	query	Check write I/O stalls confirming serialized checkpoint writes	{"sql": "SELECT DB_NAME(vfs.database_id) AS db_name,\\n  vfs.file_id, mf.physical_name,\\n  vfs.num_of_writes, vfs.io_stall_write_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_latency_ms,\\n  vfs.num_of_bytes_written / 1048576 AS writes_mb\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON mf.database_id = vfs.database_id AND mf.file_id = vfs.file_id\\nWHERE vfs.database_id > 4\\n  AND mf.type_desc = 'ROWS'\\n  AND vfs.num_of_writes > 10000\\nORDER BY vfs.io_stall_write_ms DESC"}	{"condition": "avg_write_latency_ms > 10 AND writes_mb > 1024", "description": "High write volume with elevated latency on limited data files — I/O serialization during checkpoint"}	null	2026-02-23 20:18:31.389875
11384	mysql	query	Check binary log count and size as disk pressure indicator	{"sql": "SHOW BINARY LOGS"}	{"condition": "very few binary log files remain", "description": "Very few binary log files may indicate forced cleanup due to disk pressure"}	\N	2026-03-01 06:30:58.706791
1654	sqlserver	query	Check overall I/O latency across data files	{"sql": "SELECT DB_NAME(vfs.database_id) AS db_name,\\n  mf.physical_name, mf.type_desc,\\n  vfs.num_of_reads, vfs.num_of_writes,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_latency_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_latency_ms,\\n  vfs.io_stall_read_ms + vfs.io_stall_write_ms AS total_io_stall_ms\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON mf.database_id = vfs.database_id AND mf.file_id = vfs.file_id\\nWHERE vfs.database_id > 4\\nORDER BY vfs.io_stall_write_ms DESC"}	{"condition": "avg_write_latency_ms > 20 OR avg_read_latency_ms > 20", "description": "Average I/O latency above 20ms indicates storage subsystem saturation"}	null	2026-02-23 20:18:31.389875
1655	sqlserver	query	Check pending I/O operations and checkpoint activity	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_io_pending_io_requests) AS pending_io_requests,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Checkpoint pages/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page writes/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS page_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page reads/sec'\\n   AND object_name LIKE '%Buffer Manager%') AS page_reads_sec"}	{"condition": "pending_io_requests > 50 OR (checkpoint_pages_sec > 100 AND page_writes_sec > 200)", "description": "High pending I/O queue or saturated write throughput during checkpoint — storage cannot keep up"}	null	2026-02-23 20:18:31.389876
1741	sqlserver	query	Verify server uptime is sufficient for meaningful conclusion	{"sql": "SELECT sqlserver_start_time, DATEDIFF(DAY, sqlserver_start_time, GETDATE()) AS uptime_days FROM sys.dm_os_sys_info"}	{"condition": "uptime_days >= :min_uptime_days", "description": "Sufficient uptime to conclude the index was genuinely never needed"}	{"min_uptime_days": 14}	2026-02-23 20:18:31.389933
1661	sqlserver	query	Check tempdb file count and PFS distribution	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.master_files\\n   WHERE database_id = 2 AND type_desc = 'ROWS') AS tempdb_files,\\n  (SELECT cpu_count FROM sys.dm_os_sys_info) AS cpu_cores,\\n  ws.waiting_tasks_count AS pagelatch_up_waits,\\n  ws.wait_time_ms AS pagelatch_up_total_ms,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_pagelatch_up_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'PAGELATCH_UP'"}	{"condition": "tempdb_files < cpu_cores AND pagelatch_up_waits > 10000", "description": "Insufficient tempdb files with high PAGELATCH_UP waits — PFS contention from too few allocation points"}	null	2026-02-23 20:18:31.389879
1663	sqlserver	query	Check extent allocation rate and tempdb file configuration	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.master_files\\n   WHERE database_id = 2 AND type_desc = 'ROWS') AS tempdb_files,\\n  (SELECT SUM(unallocated_extent_page_count) * 8 / 1024\\n   FROM sys.dm_db_file_space_usage\\n   WHERE database_id = 2) AS free_space_mb,\\n  (SELECT SUM(user_object_reserved_page_count + internal_object_reserved_page_count\\n    + version_store_reserved_page_count) * 8 / 1024\\n   FROM sys.dm_db_file_space_usage\\n   WHERE database_id = 2) AS used_space_mb,\\n  ws.waiting_tasks_count AS pagelatch_waits,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type = 'PAGELATCH_UP'"}	{"condition": "tempdb_files < 4 AND pagelatch_waits > 5000", "description": "Few tempdb files with high PAGELATCH waits confirm GAM contention from concentrated extent allocations"}	null	2026-02-23 20:18:31.38988
3502	postgresql	log_scan	Scan for timeline-related recovery errors	{"pattern": "requested timeline.*not.*containing|new timeline.*ID.*does not|could not find.*timeline|timeline.*does not contain|WAL file.*timeline.*unexpected", "description": "Timeline divergence errors during recovery"}	{"condition": "pattern_found", "description": "Timeline divergence prevents WAL replay"}	\N	2026-02-25 00:28:52.405273
1665	sqlserver	query	Check if TF 1118 is enabled and tempdb configuration	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.master_files\\n   WHERE database_id = 2 AND type_desc = 'ROWS') AS tempdb_files,\\n  SERVERPROPERTY('ProductMajorVersion') AS sql_version_major,\\n  (SELECT CASE WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 13\\n    THEN 'Uniform extents default (SQL 2016+)'\\n    ELSE 'Check TF 1118' END) AS extent_allocation_mode"}	{"condition": "sql_version_major < 13 (pre-SQL 2016)", "description": "Pre-SQL 2016 instances use mixed extent allocation by default, causing SGAM contention"}	null	2026-02-23 20:18:31.389882
1666	sqlserver	query	Verify trace flag 1118 status on older versions	{"sql": "DBCC TRACESTATUS(1118, -1)"}	{"condition": "TF 1118 not enabled globally (Status = 0 or not present)", "description": "TF 1118 not active — mixed extent allocations causing SGAM page contention"}	null	2026-02-23 20:18:31.389882
1671	sqlserver	query	Check file-level space usage for allocation skew	{"sql": "SELECT mf.file_id, mf.name,\\n  mf.size * 8 / 1024 AS file_size_mb,\\n  fsu.unallocated_extent_page_count * 8 / 1024 AS free_mb,\\n  (fsu.user_object_reserved_page_count +\\n   fsu.internal_object_reserved_page_count) * 8 / 1024 AS used_mb,\\n  CAST((fsu.user_object_reserved_page_count +\\n   fsu.internal_object_reserved_page_count) AS FLOAT) /\\n   NULLIF(mf.size, 0) AS utilization_ratio\\nFROM sys.dm_db_file_space_usage fsu\\nJOIN sys.master_files mf ON mf.database_id = 2 AND mf.file_id = fsu.file_id\\nWHERE mf.database_id = 2 AND mf.type_desc = 'ROWS'\\nORDER BY mf.file_id"}	{"condition": "MAX(utilization_ratio) - MIN(utilization_ratio) > 0.20", "description": "Significant utilization skew across tempdb files confirms uneven allocation distribution"}	null	2026-02-23 20:18:31.389885
1672	sqlserver	query	Check tempdb object allocation churn	{"sql": "SELECT\\n  SUM(tsu.user_objects_alloc_page_count) AS user_obj_alloc_pages,\\n  SUM(tsu.user_objects_dealloc_page_count) AS user_obj_dealloc_pages,\\n  SUM(tsu.internal_objects_alloc_page_count) AS internal_obj_alloc_pages,\\n  SUM(tsu.internal_objects_dealloc_page_count) AS internal_obj_dealloc_pages,\\n  COUNT(DISTINCT tsu.session_id) AS active_sessions\\nFROM sys.dm_db_task_space_usage tsu\\nWHERE tsu.database_id = 2"}	{"condition": "user_obj_alloc_pages > 10000 AND active_sessions > 20", "description": "High temp object allocation across many sessions indicates temp table creation storm"}	null	2026-02-23 20:18:31.389886
1673	sqlserver	query	Check sessions creating temp tables and their activity	{"sql": "SELECT TOP 20\\n  tsu.session_id,\\n  tsu.user_objects_alloc_page_count AS alloc_pages,\\n  tsu.user_objects_dealloc_page_count AS dealloc_pages,\\n  s.program_name, s.host_name, s.login_name,\\n  r.wait_type, r.wait_resource\\nFROM sys.dm_db_session_space_usage tsu\\nJOIN sys.dm_exec_sessions s ON s.session_id = tsu.session_id\\nLEFT JOIN sys.dm_exec_requests r ON r.session_id = tsu.session_id\\nWHERE tsu.user_objects_alloc_page_count > 100\\nORDER BY tsu.user_objects_alloc_page_count DESC"}	{"condition": "multiple sessions with high alloc_pages AND wait_type LIKE 'PAGELATCH%'", "description": "Many sessions creating temp objects while waiting on page latches — temp table storm causing contention"}	null	2026-02-23 20:18:31.389887
1674	sqlserver	query	Check metadata contention from temp table DDL	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN (\\n  'PAGELATCH_UP', 'PAGELATCH_EX',\\n  'LATCH_EX', 'LATCH_SH'\\n)\\nAND waiting_tasks_count > 500\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGELATCH_UP or LATCH_EX with avg_wait_ms > 2", "description": "Page latch and system latch contention from rapid temp table creation/drop cycles"}	null	2026-02-23 20:18:31.389887
1675	sqlserver	query	Check for active global temporary tables in tempdb	{"sql": "SELECT o.name, o.type_desc, o.create_date,\\n  p.rows AS row_count,\\n  SUM(a.total_pages) * 8 / 1024 AS size_mb\\nFROM tempdb.sys.objects o\\nJOIN tempdb.sys.partitions p ON o.object_id = p.object_id\\nJOIN tempdb.sys.allocation_units a ON p.partition_id = a.container_id\\nWHERE o.name LIKE '##%'\\n  AND o.type_desc = 'USER_TABLE'\\nGROUP BY o.name, o.type_desc, o.create_date, p.rows\\nORDER BY SUM(a.total_pages) DESC"}	{"condition": "row_count > 0 AND (multiple ##tables OR size_mb > 100)", "description": "Active global temp tables found — these persist across sessions and consume tempdb space"}	null	2026-02-23 20:18:31.389888
1676	sqlserver	query	Check lock contention on global temp tables	{"sql": "SELECT resource_type, resource_description,\\n  request_mode, request_status,\\n  COUNT(*) AS lock_count,\\n  SUM(CASE WHEN request_status = 'WAIT' THEN 1 ELSE 0 END) AS waiting_count\\nFROM sys.dm_tran_locks\\nWHERE resource_database_id = 2\\n  AND resource_type IN ('OBJECT', 'PAGE', 'KEY', 'RID')\\nGROUP BY resource_type, resource_description, request_mode, request_status\\nHAVING COUNT(*) > 5\\nORDER BY COUNT(*) DESC"}	{"condition": "waiting_count > 0 AND resource_database_id = 2", "description": "Lock contention in tempdb on objects (likely global temp tables) — multiple sessions competing"}	null	2026-02-23 20:18:31.389888
3975	postgresql	query	Check WAL generation rate from statistics	{"sql": "SELECT pg_wal_lsn_diff(pg_current_wal_lsn(), '0/0') AS total_wal_generated, (SELECT count(*) FROM pg_ls_waldir()) AS wal_files_on_disk FROM pg_stat_archiver"}	{"condition": "wal_files_on_disk > :max_wal_files", "description": "Accumulating WAL files on disk confirm generation outpacing transfer"}	{"max_wal_files": 50}	2026-02-25 00:28:52.405273
1677	sqlserver	query	Check tempdb space pressure from global temp tables	{"sql": "SELECT\\n  SUM(user_object_reserved_page_count) * 8 / 1024 AS user_objects_mb,\\n  SUM(internal_object_reserved_page_count) * 8 / 1024 AS internal_objects_mb,\\n  SUM(version_store_reserved_page_count) * 8 / 1024 AS version_store_mb,\\n  SUM(unallocated_extent_page_count) * 8 / 1024 AS free_space_mb\\nFROM sys.dm_db_file_space_usage\\nWHERE database_id = 2"}	{"condition": "user_objects_mb > 500 AND free_space_mb < user_objects_mb * 0.2", "description": "Global temp tables consuming significant tempdb space with limited free space remaining"}	null	2026-02-23 20:18:31.389889
3504	postgresql	config_check	Check WAL retention configuration	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('wal_keep_size', 'max_wal_size', 'min_wal_size', 'archive_mode', 'archive_command') ORDER BY name"}	{"condition": "wal_keep_size = '0' AND (archive_mode = 'off' OR archive_command = '')", "description": "No WAL retention configured — old WAL segments are immediately recycled"}	\N	2026-02-25 00:28:52.405273
1678	sqlserver	query	Check for tempdb spills from sort and hash operations	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_spills > 0\\n  AND st.text LIKE '%DECLARE%@%TABLE%'\\nORDER BY qs.total_spills DESC"}	{"condition": "row_count > 0 AND avg_spills > 10", "description": "Queries using table variables with significant spill counts"}	null	2026-02-23 20:18:31.38989
2300	sqlserver	query	Check database-scoped optimizer configurations	{"sql": "SELECT\\n  configuration_id, name, value, value_for_secondary\\nFROM sys.database_scoped_configurations\\nWHERE name IN (\\n  'LEGACY_CARDINALITY_ESTIMATION',\\n  'PARAMETER_SNIFFING',\\n  'QUERY_OPTIMIZER_HOTFIXES',\\n  'MAXDOP',\\n  'LAST_QUERY_PLAN_STATS',\\n  'LIGHTWEIGHT_QUERY_PROFILING'\\n)"}	{"condition": "LEGACY_CARDINALITY_ESTIMATION = ON or unusual MAXDOP override", "description": "Database-scoped overrides affecting optimizer behavior"}	null	2026-02-23 20:18:31.39029
1679	sqlserver	query	Check tempdb allocation growth from table variable spills	{"sql": "SELECT\\n  SUM(user_object_reserved_page_count) * 8 AS user_obj_kb,\\n  SUM(internal_object_reserved_page_count) * 8 AS internal_obj_kb,\\n  SUM(version_store_reserved_page_count) * 8 AS version_store_kb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Temp Tables Creation Rate'\\n   AND object_name LIKE '%General Statistics%') AS temp_table_creation_rate\\nFROM sys.dm_db_file_space_usage\\nWHERE database_id = 2"}	{"condition": "internal_obj_kb > 1048576", "description": "Internal objects exceeding 1 GB in tempdb suggests heavy spill activity from table variables or other operations"}	null	2026-02-23 20:18:31.38989
1680	sqlserver	query	Verify table variable deferred compilation is available	{"sql": "SELECT\\n  d.compatibility_level,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  CASE WHEN d.compatibility_level >= 150 THEN 'Table variable deferred compilation ACTIVE'\\n       ELSE 'Table variable estimates 1 row — spills likely' END AS tv_behavior\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "compatibility_level < 150", "description": "Database running below compat level 150 — table variables use fixed 1-row estimate causing spills"}	null	2026-02-23 20:18:31.389891
1681	sqlserver	query	Find top queries by spill count	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_spills,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills_per_exec,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_spills > 0\\nORDER BY qs.total_spills DESC"}	{"condition": "row_count > 0 AND avg_spills_per_exec > 5", "description": "Queries consistently spilling sort/hash operations to tempdb"}	null	2026-02-23 20:18:31.389891
1682	sqlserver	query	Check memory grant ratio for spilling queries	{"sql": "SELECT TOP 20\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_kb,\\n  CASE WHEN qs.total_ideal_grant_kb > 0\\n    THEN CAST(qs.total_grant_kb AS float) / qs.total_ideal_grant_kb * 100\\n    ELSE 0 END AS grant_vs_ideal_pct,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_spills > 0\\n  AND qs.total_grant_kb < qs.total_ideal_grant_kb\\nORDER BY (qs.total_ideal_grant_kb - qs.total_grant_kb) DESC"}	{"condition": "grant_vs_ideal_pct < 75", "description": "Queries receiving less than 75% of ideal memory grant — insufficient grant causing spills"}	null	2026-02-23 20:18:31.389892
4466	postgresql	query	Check for checksum failures without hardware explanation	{"sql": "SELECT datname, checksum_failures, checksum_last_failure FROM pg_stat_database WHERE checksum_failures > 0"}	{"condition": "row_count > 0", "description": "Checksum failures with clean hardware diagnostics may point to OS kernel bugs"}	\N	2026-02-25 00:28:52.405273
1683	sqlserver	query	Check tempdb object creation rate vs procedure execution rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Temp Tables Creation Rate'\\n   AND object_name LIKE '%General Statistics%') AS temp_creation_rate,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Temp Tables For Destruction'\\n   AND object_name LIKE '%General Statistics%') AS temp_for_destruction,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Compilations/sec'\\n   AND object_name LIKE '%SQL Statistics%') AS sql_compilations_sec"}	{"condition": "temp_creation_rate > 100 AND temp_for_destruction > temp_creation_rate * 0.8", "description": "High temp table creation rate with most tables being destroyed rather than cached"}	null	2026-02-23 20:18:31.389893
3988	postgresql	query	Check replication slot restart positions	{"sql": "SELECT slot_name, restart_lsn, pg_walfile_name(restart_lsn) AS restart_wal_file FROM pg_replication_slots WHERE slot_type = 'physical'"}	{"condition": "restart_wal_file IS NOT NULL", "description": "Verify replication slots point to valid WAL files"}	\N	2026-02-25 00:28:52.405273
1684	sqlserver	query	Find stored procedures with high temp table creation	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(qs.object_id, qs.database_id) AS proc_name,\\n  DB_NAME(qs.database_id) AS db_name,\\n  qs.execution_count,\\n  qs.total_logical_writes / NULLIF(qs.execution_count, 0) AS avg_logical_writes,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) AS avg_cpu_us\\nFROM sys.dm_exec_procedure_stats qs\\nWHERE qs.execution_count > 100\\n  AND qs.total_logical_writes / NULLIF(qs.execution_count, 0) > 50\\nORDER BY qs.execution_count * (qs.total_logical_writes / NULLIF(qs.execution_count, 0)) DESC"}	{"condition": "row_count > 0 AND avg_logical_writes > 100", "description": "Frequently executed procedures with high write activity indicating repeated temp object creation/destruction"}	null	2026-02-23 20:18:31.389893
1685	sqlserver	query	Check allocation contention from uncached temp objects	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGELATCH_UP', 'PAGELATCH_EX', 'PAGELATCH_SH')\\n  AND waiting_tasks_count > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGELATCH_UP or PAGELATCH_EX with significant wait time", "description": "Allocation page contention from frequent temp object creation/destruction without caching"}	null	2026-02-23 20:18:31.389894
