1686	sqlserver	query	Check memory grant pending and pressure indicators	{"sql": "SELECT\\n  mg.total_memory_kb,\\n  mg.available_memory_kb,\\n  mg.granted_memory_kb,\\n  mg.used_memory_kb,\\n  mg.grantee_count,\\n  mg.waiter_count,\\n  CASE WHEN mg.available_memory_kb > 0\\n    THEN CAST(mg.granted_memory_kb AS float) / mg.total_memory_kb * 100\\n    ELSE 0 END AS memory_utilization_pct\\nFROM sys.dm_exec_query_resource_semaphores mg\\nWHERE mg.resource_semaphore_id = 0"}	{"condition": "waiter_count > 0 OR memory_utilization_pct > 90", "description": "Queries waiting for memory grants or memory pool near exhaustion"}	null	2026-02-23 20:18:31.389895
1687	sqlserver	query	Check currently executing queries with reduced grants and spills	{"sql": "SELECT\\n  mg.session_id,\\n  mg.requested_memory_kb,\\n  mg.granted_memory_kb,\\n  mg.required_memory_kb,\\n  mg.ideal_memory_kb,\\n  mg.used_memory_kb,\\n  CASE WHEN mg.ideal_memory_kb > 0\\n    THEN CAST(mg.granted_memory_kb AS float) / mg.ideal_memory_kb * 100\\n    ELSE 0 END AS grant_vs_ideal_pct,\\n  mg.is_small,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1,\\n    (CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE r.statement_end_offset END - r.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_memory_grants mg\\nJOIN sys.dm_exec_requests r ON mg.session_id = r.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE mg.granted_memory_kb < mg.ideal_memory_kb"}	{"condition": "row_count > 0 AND grant_vs_ideal_pct < 70", "description": "Active queries receiving well below their ideal memory grant — forced to spill to tempdb"}	null	2026-02-23 20:18:31.389895
1688	sqlserver	query	Check tempdb space growth from spill activity	{"sql": "SELECT\\n  SUM(internal_object_reserved_page_count) * 8 AS internal_obj_kb,\\n  SUM(user_object_reserved_page_count) * 8 AS user_obj_kb,\\n  (SELECT SUM(size) * 8 FROM sys.master_files WHERE database_id = 2) AS tempdb_size_kb,\\n  CAST(SUM(internal_object_reserved_page_count) * 8 AS float) /\\n    NULLIF((SELECT SUM(size) * 8 FROM sys.master_files WHERE database_id = 2), 0) * 100 AS internal_obj_pct\\nFROM sys.dm_db_file_space_usage\\nWHERE database_id = 2"}	{"condition": "internal_obj_pct > 30", "description": "Internal objects consuming significant tempdb space — spill activity from memory-constrained queries"}	null	2026-02-23 20:18:31.389896
1689	sqlserver	query	Check tempdb internal object space during index operations	{"sql": "SELECT\\n  t.session_id,\\n  t.internal_objects_alloc_page_count * 8 AS internal_alloc_kb,\\n  t.internal_objects_dealloc_page_count * 8 AS internal_dealloc_kb,\\n  (t.internal_objects_alloc_page_count - t.internal_objects_dealloc_page_count) * 8 AS net_internal_kb,\\n  s.program_name, s.host_name\\nFROM sys.dm_db_session_space_usage t\\nJOIN sys.dm_exec_sessions s ON t.session_id = s.session_id\\nWHERE (t.internal_objects_alloc_page_count - t.internal_objects_dealloc_page_count) > 1000\\nORDER BY net_internal_kb DESC"}	{"condition": "net_internal_kb > 1048576", "description": "Sessions with over 1 GB of internal object allocation in tempdb — index sorts consuming tempdb space"}	null	2026-02-23 20:18:31.389897
1692	sqlserver	query	Check I/O contention on shared tempdb volume	{"sql": "SELECT\\n  d.name AS database_name,\\n  mf.type_desc AS file_type,\\n  LEFT(mf.physical_name, 3) AS drive,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms,\\n  vfs.num_of_reads + vfs.num_of_writes AS total_ios\\nFROM sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nJOIN sys.databases d ON vfs.database_id = d.database_id\\nWHERE LEFT(mf.physical_name, 3) IN (\\n  SELECT LEFT(physical_name, 3) FROM sys.master_files WHERE database_id = 2\\n)\\nORDER BY vfs.io_stall_read_ms + vfs.io_stall_write_ms DESC"}	{"condition": "avg_read_stall_ms > 10 OR avg_write_stall_ms > 5 on shared drive", "description": "Elevated I/O latency on drives shared between tempdb and user databases"}	null	2026-02-23 20:18:31.389899
1913	sqlserver	query	Check for parallel query exchange-related waits	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT', 'CXSYNC_CONSUMER')\\n  AND waiting_tasks_count > 100\\nORDER BY wait_time_ms DESC"}	{"condition": "high CXPACKET/CXCONSUMER waits indicating heavy parallelism", "description": "Significant parallel execution waits suggesting exchange operator contention"}	null	2026-02-23 20:18:31.390045
1694	sqlserver	query	Check for contention on tempdb system catalog pages specifically	{"sql": "SELECT r.session_id, r.wait_type, r.wait_resource,\\n  r.wait_time AS current_wait_ms,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1,\\n    (CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE r.statement_end_offset END - r.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nWHERE r.wait_type LIKE 'PAGELATCH%'\\n  AND r.wait_resource LIKE '2:%'\\n  AND r.session_id > 50"}	{"condition": "row_count > 0 AND wait_resource references database_id 2 (tempdb)", "description": "Active sessions waiting on page latches in tempdb — metadata contention on system catalog pages"}	null	2026-02-23 20:18:31.389899
3989	postgresql	query	Check WAL archiver performance during backup	{"sql": "SELECT archived_count, failed_count, last_archived_time, (NOW() - last_archived_time) AS time_since_last_archive FROM pg_stat_archiver"}	{"condition": "time_since_last_archive > interval ':stale_minutes minutes'", "description": "Stale archiving during active backup confirms interference"}	{"stale_minutes": 15}	2026-02-25 00:28:52.405273
1695	sqlserver	query	Check temp table creation rate and memory-optimized tempdb setting	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Temp Tables Creation Rate'\\n   AND object_name LIKE '%General Statistics%') AS temp_creation_rate,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  (SELECT CASE WHEN is_memory_optimized_enabled = 1 THEN 'YES' ELSE 'NO' END\\n   FROM sys.databases WHERE database_id = 2) AS tempdb_memory_optimized"}	{"condition": "temp_creation_rate > 500 AND tempdb_memory_optimized = 'NO'", "description": "High temp table creation rate without memory-optimized tempdb metadata — vulnerable to metadata contention"}	null	2026-02-23 20:18:31.3899
1697	sqlserver	query	Check version store size and generation rate	{"sql": "SELECT\\n  SUM(version_store_reserved_page_count) * 8 AS version_store_kb,\\n  SUM(version_store_reserved_page_count) * 8 / 1024 AS version_store_mb,\\n  (SELECT SUM(size) * 8 FROM sys.master_files WHERE database_id = 2) AS tempdb_total_kb,\\n  CAST(SUM(version_store_reserved_page_count) * 8 AS float) /\\n    NULLIF((SELECT SUM(size) * 8 FROM sys.master_files WHERE database_id = 2), 0) * 100 AS version_store_pct,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Version Store Size (KB)'\\n   AND object_name LIKE '%Transactions%') AS perf_counter_version_kb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Version Generation rate (KB/s)'\\n   AND object_name LIKE '%Transactions%') AS version_gen_rate_kb_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Version Cleanup rate (KB/s)'\\n   AND object_name LIKE '%Transactions%') AS version_cleanup_rate_kb_sec\\nFROM sys.dm_db_file_space_usage\\nWHERE database_id = 2"}	{"condition": "version_store_pct > 20 OR version_gen_rate_kb_sec > version_cleanup_rate_kb_sec", "description": "Version store consuming significant tempdb space or growing faster than cleanup"}	null	2026-02-23 20:18:31.389901
1699	sqlserver	query	Check tempdb file count and size uniformity	{"sql": "SELECT\\n  mf.file_id,\\n  mf.physical_name,\\n  mf.size * 8 AS size_kb,\\n  mf.growth,\\n  mf.max_size,\\n  mf.is_percent_growth,\\n  (SELECT COUNT(*) FROM sys.master_files WHERE database_id = 2 AND type = 0) AS total_data_files,\\n  (SELECT MIN(size) * 8 FROM sys.master_files WHERE database_id = 2 AND type = 0) AS min_file_kb,\\n  (SELECT MAX(size) * 8 FROM sys.master_files WHERE database_id = 2 AND type = 0) AS max_file_kb\\nFROM sys.master_files mf\\nWHERE mf.database_id = 2 AND mf.type = 0\\nORDER BY mf.file_id"}	{"condition": "max_file_kb > min_file_kb * 1.2 OR total_data_files = 1", "description": "Tempdb files are not uniformly sized (>20% variance) or only a single data file exists"}	null	2026-02-23 20:18:31.389902
1700	sqlserver	query	Check I/O distribution across tempdb files	{"sql": "SELECT\\n  mf.file_id,\\n  mf.physical_name,\\n  mf.size * 8 AS size_kb,\\n  vfs.num_of_reads,\\n  vfs.num_of_writes,\\n  vfs.num_of_reads + vfs.num_of_writes AS total_ios,\\n  vfs.io_stall_read_ms / NULLIF(vfs.num_of_reads, 0) AS avg_read_stall_ms,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_write_stall_ms\\nFROM sys.dm_io_virtual_file_stats(2, NULL) vfs\\nJOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE mf.type = 0\\nORDER BY mf.file_id"}	{"condition": "MAX(total_ios) > MIN(total_ios) * 2 across files", "description": "Highly uneven I/O distribution — some tempdb files serving disproportionate workload"}	null	2026-02-23 20:18:31.389903
1701	sqlserver	query	Check for PFS/GAM/SGAM page contention in tempdb	{"sql": "SELECT r.session_id, r.wait_type, r.wait_resource, r.wait_time,\\n  CASE\\n    WHEN CHARINDEX(':', r.wait_resource, CHARINDEX(':', r.wait_resource)+1) > 0\\n    THEN CAST(SUBSTRING(r.wait_resource,\\n      CHARINDEX(':', r.wait_resource, CHARINDEX(':', r.wait_resource)+1)+1,\\n      LEN(r.wait_resource)) AS bigint)\\n    ELSE -1\\n  END AS page_id,\\n  CASE\\n    WHEN r.wait_resource LIKE '2:%' AND\\n      CAST(SUBSTRING(r.wait_resource,\\n        CHARINDEX(':', r.wait_resource, CHARINDEX(':', r.wait_resource)+1)+1,\\n        LEN(r.wait_resource)) AS bigint) % 8088 = 0 THEN 'PFS'\\n    WHEN r.wait_resource LIKE '2:%' AND\\n      CAST(SUBSTRING(r.wait_resource,\\n        CHARINDEX(':', r.wait_resource, CHARINDEX(':', r.wait_resource)+1)+1,\\n        LEN(r.wait_resource)) AS bigint) % 511232 = 0 THEN 'GAM'\\n    WHEN r.wait_resource LIKE '2:%' AND\\n      CAST(SUBSTRING(r.wait_resource,\\n        CHARINDEX(':', r.wait_resource, CHARINDEX(':', r.wait_resource)+1)+1,\\n        LEN(r.wait_resource)) AS bigint) % 511232 = 1 THEN 'SGAM'\\n    ELSE 'OTHER'\\n  END AS page_type\\nFROM sys.dm_exec_requests r\\nWHERE r.wait_type LIKE 'PAGELATCH%'\\n  AND r.wait_resource LIKE '2:%'"}	{"condition": "row_count > 0 AND page_type IN ('PFS', 'GAM', 'SGAM')", "description": "Active sessions waiting on PFS/GAM/SGAM allocation bitmap pages in tempdb"}	null	2026-02-23 20:18:31.389904
1702	sqlserver	query	Check tempdb file count and allocation contention indicators	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.master_files WHERE database_id = 2 AND type = 0) AS tempdb_data_files,\\n  (SELECT cpu_count FROM sys.dm_os_sys_info) AS logical_cpus,\\n  ws.wait_type, ws.waiting_tasks_count, ws.wait_time_ms,\\n  ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type IN ('PAGELATCH_UP', 'PAGELATCH_EX')\\n  AND ws.waiting_tasks_count > 0"}	{"condition": "tempdb_data_files < logical_cpus / 2 AND avg_wait_ms > 2", "description": "Too few tempdb files relative to CPU count with elevated allocation page latch waits"}	null	2026-02-23 20:18:31.389904
1703	sqlserver	query	Check missing index recommendations with impact analysis	{"sql": "SELECT TOP 25\\n  d.database_id, DB_NAME(d.database_id) AS db_name,\\n  d.object_id, OBJECT_NAME(d.object_id, d.database_id) AS table_name,\\n  gs.unique_compiles, gs.user_seeks, gs.user_scans,\\n  gs.avg_total_user_cost, gs.avg_user_impact,\\n  gs.user_seeks * gs.avg_total_user_cost * (gs.avg_user_impact / 100.0) AS improvement_measure,\\n  d.equality_columns, d.inequality_columns, d.included_columns,\\n  gs.last_user_seek\\nFROM sys.dm_db_missing_index_details d\\nJOIN sys.dm_db_missing_index_groups g ON d.index_handle = g.index_handle\\nJOIN sys.dm_db_missing_index_group_stats gs ON g.index_group_handle = gs.group_handle\\nWHERE d.database_id = DB_ID()\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND improvement_measure > 10000", "description": "Significant missing index recommendations with high estimated improvement"}	null	2026-02-23 20:18:31.389905
3976	postgresql	query	Check archive failure count and timing	{"sql": "SELECT failed_count, last_failed_wal, last_failed_time, last_archived_wal, last_archived_time FROM pg_stat_archiver WHERE failed_count > 0"}	{"condition": "row_count > 0 AND last_failed_time > NOW() - interval ':hours hours'", "description": "Recent archive failures suggest destination issues"}	{"hours": 1}	2026-02-25 00:28:52.405273
