1711	sqlserver	query	Check for table scans on tables that have indexes	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ius.user_scans, ius.user_seeks, ius.user_lookups,\\n  CASE WHEN (ius.user_scans + ius.user_seeks) > 0\\n    THEN CAST(ius.user_scans AS float) / (ius.user_scans + ius.user_seeks) * 100\\n    ELSE 0 END AS scan_pct\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND i.type_desc IN ('CLUSTERED', 'HEAP')\\n  AND ius.user_scans > 1000\\n  AND EXISTS (SELECT 1 FROM sys.indexes i2\\n    WHERE i2.object_id = ius.object_id AND i2.type_desc = 'NONCLUSTERED')\\nORDER BY ius.user_scans DESC"}	{"condition": "row_count > 0 AND scan_pct > 80", "description": "Tables with nonclustered indexes but predominantly scanned — predicates likely non-sargable preventing index seek"}	null	2026-02-23 20:18:31.389906
1705	sqlserver	query	Check missing index recommendations with included columns	{"sql": "SELECT TOP 25\\n  DB_NAME(d.database_id) AS db_name,\\n  OBJECT_NAME(d.object_id, d.database_id) AS table_name,\\n  d.equality_columns, d.inequality_columns,\\n  d.included_columns,\\n  gs.user_seeks, gs.user_scans,\\n  gs.avg_total_user_cost, gs.avg_user_impact,\\n  gs.user_seeks * gs.avg_total_user_cost * (gs.avg_user_impact / 100.0) AS improvement_measure\\nFROM sys.dm_db_missing_index_details d\\nJOIN sys.dm_db_missing_index_groups g ON d.index_handle = g.index_handle\\nJOIN sys.dm_db_missing_index_group_stats gs ON g.index_group_handle = gs.group_handle\\nWHERE d.database_id = DB_ID()\\n  AND d.included_columns IS NOT NULL\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND improvement_measure > 5000", "description": "Missing index recommendations specifically requesting INCLUDE columns for coverage"}	null	2026-02-23 20:18:31.389907
1706	sqlserver	query	Find queries with high key lookup counts	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ios.singleton_lookup_count AS key_lookups,\\n  ios.range_scan_count, ios.singleton_lookup_count,\\n  ius.user_seeks, ius.user_lookups,\\n  ius.user_lookups AS bookmark_lookups\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nJOIN sys.dm_db_index_usage_stats ius\\n  ON ios.object_id = ius.object_id AND ios.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND ius.user_lookups > 1000\\nORDER BY ius.user_lookups DESC"}	{"condition": "row_count > 0 AND user_lookups > 10000", "description": "Nonclustered indexes with high key lookup counts — each lookup requires a separate I/O to the clustered index"}	null	2026-02-23 20:18:31.389907
1707	sqlserver	query	Find statistics with high modification count relative to rows	{"sql": "SELECT TOP 25\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  s.auto_created, s.user_created,\\n  sp.rows AS stat_rows,\\n  sp.rows_sampled, sp.modification_counter,\\n  sp.last_updated,\\n  DATEDIFF(HOUR, sp.last_updated, GETDATE()) AS hours_since_update,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(sp.modification_counter AS float) / sp.rows * 100\\n    ELSE 0 END AS modification_pct\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > 0\\n  AND OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\nORDER BY modification_pct DESC"}	{"condition": "modification_pct > 20 OR hours_since_update > 168", "description": "Statistics with more than 20% modification rate or not updated in over a week"}	null	2026-02-23 20:18:31.389908
1708	sqlserver	query	Check auto-statistics settings and stale stats impact	{"sql": "SELECT\\n  d.name AS db_name,\\n  d.is_auto_update_stats_on,\\n  d.is_auto_create_stats_on,\\n  d.is_auto_update_stats_async_on,\\n  (SELECT COUNT(*) FROM sys.stats s\\n   CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\n   WHERE OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\n     AND sp.modification_counter > sp.rows * 0.2\\n     AND sp.rows > 500) AS stale_stat_count\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "stale_stat_count > 5 OR is_auto_update_stats_on = 0", "description": "Multiple stale statistics or auto-update disabled — optimizer may choose wrong indexes"}	null	2026-02-23 20:18:31.389909
1709	sqlserver	query	Find queries with cardinality estimation warnings	{"sql": "SELECT TOP 15\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//Warnings[@CardinalityEstimationModelVersion]') = 1\\n  OR (qs.total_rows / NULLIF(qs.execution_count, 0)) >\\n     (qs.total_logical_reads / NULLIF(qs.execution_count, 0)) * 10\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0", "description": "Queries with cardinality estimation issues from stale statistics leading to suboptimal plans"}	null	2026-02-23 20:18:31.389909
1710	sqlserver	query	Find queries with high logical reads and scan-dominant access	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) AS avg_elapsed_us,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  CASE WHEN (qs.total_logical_reads / NULLIF(qs.execution_count, 0)) > 0\\n    THEN CAST(qs.total_rows / NULLIF(qs.execution_count, 0) AS float) /\\n         (qs.total_logical_reads / NULLIF(qs.execution_count, 0)) * 100\\n    ELSE 0 END AS selectivity_pct,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset)/2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.total_rows / NULLIF(qs.execution_count, 0) < 100\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND selectivity_pct < 1", "description": "Queries reading many pages but returning few rows — suggests index not being used despite selective predicates"}	null	2026-02-23 20:18:31.38991
1753	sqlserver	query	Find full-text indexes and their activity	{"sql": "SELECT t.name AS table_name, fi.unique_index_id, fic.column_id, COL_NAME(fic.object_id, fic.column_id) AS ft_column, fc.name AS catalog_name, fi.is_enabled, fi.change_tracking_state_desc, fi.has_crawl_completed FROM sys.fulltext_indexes fi JOIN sys.tables t ON fi.object_id = t.object_id JOIN sys.fulltext_index_columns fic ON fi.object_id = fic.object_id JOIN sys.fulltext_catalogs fc ON fi.fulltext_catalog_id = fc.fulltext_catalog_id ORDER BY t.name"}	{"condition": "row_count > 0", "description": "Full-text indexes exist in the database"}	null	2026-02-23 20:18:31.389911
