1712	sqlserver	query	Check missing index recommendations for join columns	{"sql": "SELECT TOP 25\\n  DB_NAME(d.database_id) AS db_name,\\n  OBJECT_NAME(d.object_id, d.database_id) AS table_name,\\n  d.equality_columns,\\n  d.inequality_columns,\\n  d.included_columns,\\n  gs.user_seeks, gs.user_scans,\\n  gs.avg_total_user_cost, gs.avg_user_impact,\\n  gs.user_seeks * gs.avg_total_user_cost * (gs.avg_user_impact / 100.0) AS improvement_measure\\nFROM sys.dm_db_missing_index_details d\\nJOIN sys.dm_db_missing_index_groups g ON d.index_handle = g.index_handle\\nJOIN sys.dm_db_missing_index_group_stats gs ON g.index_group_handle = gs.group_handle\\nWHERE d.database_id = DB_ID()\\n  AND gs.user_seeks > 100\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND improvement_measure > 10000", "description": "Missing index recommendations driven by frequent seek operations — typical for join column access patterns"}	null	2026-02-23 20:18:31.389912
1714	sqlserver	query	Check missing index recommendations with multiple equality columns	{"sql": "SELECT TOP 25\\n  DB_NAME(d.database_id) AS db_name,\\n  OBJECT_NAME(d.object_id, d.database_id) AS table_name,\\n  d.equality_columns,\\n  d.inequality_columns,\\n  d.included_columns,\\n  LEN(d.equality_columns) - LEN(REPLACE(d.equality_columns, ',', '')) + 1 AS equality_col_count,\\n  gs.user_seeks, gs.avg_total_user_cost, gs.avg_user_impact,\\n  gs.user_seeks * gs.avg_total_user_cost * (gs.avg_user_impact / 100.0) AS improvement_measure\\nFROM sys.dm_db_missing_index_details d\\nJOIN sys.dm_db_missing_index_groups g ON d.index_handle = g.index_handle\\nJOIN sys.dm_db_missing_index_group_stats gs ON g.index_group_handle = gs.group_handle\\nWHERE d.database_id = DB_ID()\\n  AND d.equality_columns LIKE '%,%'\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND equality_col_count >= 2 AND improvement_measure > 5000", "description": "Missing index recommendations for multi-column equality predicates — composite index needed"}	null	2026-02-23 20:18:31.389913
1715	sqlserver	query	Check for single-column indexes on frequently multi-filtered tables	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  COUNT(ic.column_id) AS key_column_count,\\n  (SELECT STRING_AGG(c.name, ', ') FROM sys.index_columns ic2\\n   JOIN sys.columns c ON ic2.object_id = c.object_id AND ic2.column_id = c.column_id\\n   WHERE ic2.object_id = i.object_id AND ic2.index_id = i.index_id\\n     AND ic2.is_included_column = 0) AS key_columns,\\n  ius.user_seeks, ius.user_scans\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\n  AND ic.is_included_column = 0\\nJOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND OBJECTPROPERTY(i.object_id, 'IsUserTable') = 1\\nGROUP BY i.object_id, i.name, i.index_id, ius.user_seeks, ius.user_scans\\nHAVING COUNT(ic.column_id) = 1 AND ius.user_scans > ius.user_seeks\\nORDER BY ius.user_scans DESC"}	{"condition": "row_count > 0 AND single-column indexes with more scans than seeks", "description": "Single-column nonclustered indexes being scanned more than seeked — queries need multi-column composite access"}	null	2026-02-23 20:18:31.389913
1717	sqlserver	query	Correlate type conversion with table scan behavior	{"sql": "SELECT TOP 15\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ius.user_scans, ius.user_seeks,\\n  CASE WHEN (ius.user_scans + ius.user_seeks) > 0\\n    THEN CAST(ius.user_scans AS float) / (ius.user_scans + ius.user_seeks) * 100\\n    ELSE 0 END AS scan_pct,\\n  p.rows AS table_rows\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND i.type_desc IN ('CLUSTERED', 'HEAP')\\n  AND ius.user_scans > 500\\n  AND p.rows > 100000\\nORDER BY ius.user_scans DESC"}	{"condition": "scan_pct > 70 on large tables", "description": "Large tables predominantly scanned despite having indexes — implicit conversions may be forcing scans"}	null	2026-02-23 20:18:31.389915
