1917	sqlserver	query	Check index fragmentation indicating page split history	{"sql": "SELECT OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.avg_page_space_used_in_percent\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.avg_fragmentation_in_percent > 30\\n  AND ips.page_count > 1000\\n  AND i.index_id > 0\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation > 30% on large indexes", "description": "High fragmentation from page splits — increases lock surface area"}	null	2026-02-23 20:18:31.389915
1718	sqlserver	query	Find small tables with missing index recommendations	{"sql": "SELECT\\n  OBJECT_NAME(d.object_id, d.database_id) AS table_name,\\n  p.rows AS table_rows,\\n  SUM(a.total_pages) * 8 AS total_size_kb,\\n  d.equality_columns, d.inequality_columns,\\n  gs.user_seeks, gs.avg_user_impact\\nFROM sys.dm_db_missing_index_details d\\nJOIN sys.dm_db_missing_index_groups g ON d.index_handle = g.index_handle\\nJOIN sys.dm_db_missing_index_group_stats gs ON g.index_group_handle = gs.group_handle\\nJOIN sys.partitions p ON d.object_id = p.object_id AND p.index_id IN (0, 1)\\nJOIN sys.allocation_units a ON p.partition_id = a.container_id\\nWHERE d.database_id = DB_ID()\\n  AND p.rows < 1000\\nGROUP BY d.object_id, d.database_id, d.equality_columns, d.inequality_columns,\\n  p.rows, gs.user_seeks, gs.avg_user_impact\\nORDER BY p.rows ASC"}	{"condition": "row_count > 0 AND table_rows < 1000 AND total_size_kb < 80", "description": "Missing index recommendations on tables small enough to fit in a few pages — scans are already fast"}	null	2026-02-23 20:18:31.389916
1719	sqlserver	query	Check scan performance on small tables	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  p.rows,\\n  SUM(a.total_pages) * 8 AS total_size_kb,\\n  ius.user_scans, ius.user_seeks,\\n  ius.last_user_scan, ius.last_user_seek\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.partitions p ON ius.object_id = p.object_id AND ius.index_id = p.index_id\\nJOIN sys.allocation_units a ON p.partition_id = a.container_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.index_id IN (0, 1)\\n  AND p.rows < 1000\\n  AND ius.user_scans > 100\\nGROUP BY ius.object_id, p.rows, ius.user_scans, ius.user_seeks,\\n  ius.last_user_scan, ius.last_user_seek\\nHAVING SUM(a.total_pages) * 8 < 80\\nORDER BY ius.user_scans DESC"}	{"condition": "row_count > 0 AND total_size_kb < 80", "description": "Small tables fitting in under 10 data pages — table scan reads entire table in a single I/O and is faster than index seek + lookup"}	null	2026-02-23 20:18:31.389917
3977	postgresql	query	Check WAL directory size accumulation	{"sql": "SELECT count(*) AS wal_file_count, pg_size_pretty(sum(size)) AS total_wal_size FROM pg_ls_waldir()"}	{"condition": "wal_file_count > :max_files", "description": "Growing WAL directory indicates archiving is stalled"}	{"max_files": 100}	2026-02-25 00:28:52.405273
1721	sqlserver	query	Check index usage pattern for scan-heavy access on low-cardinality indexes	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  c.name AS leading_key_column,\\n  p.rows AS table_rows,\\n  ius.user_seeks, ius.user_scans, ius.user_lookups, ius.user_updates,\\n  CASE WHEN (ius.user_seeks + ius.user_scans) > 0\\n    THEN CAST(ius.user_scans AS float) / (ius.user_seeks + ius.user_scans) * 100\\n    ELSE 0 END AS scan_pct\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\n  AND ic.key_ordinal = 1 AND ic.is_included_column = 0\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND i.type_desc = 'NONCLUSTERED'\\n  AND p.rows > 10000\\n  AND ius.user_scans > ius.user_seeks\\n  AND ius.user_updates > ius.user_seeks + ius.user_scans\\nORDER BY ius.user_updates DESC"}	{"condition": "user_updates > user_seeks + user_scans AND scan_pct > 50", "description": "Low-cardinality indexes updated more than read — maintenance cost exceeds benefit"}	null	2026-02-23 20:18:31.389918
3360	postgresql	query	Check connection pool utilization pressure	{"sql": "SELECT count(*) AS current_connections, (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') AS max_connections, round(count(*)::numeric / (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') * 100, 1) AS utilization_pct FROM pg_stat_activity WHERE backend_type = 'client backend'"}	{"condition": "utilization_pct > :threshold_pct", "description": "Pool nearing capacity confirms leaked connections are causing pressure"}	{"threshold_pct": 80}	2026-02-25 00:28:52.405273
1722	sqlserver	query	Find nonclustered indexes on nullable columns with usage stats	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  c.name AS leading_key_column,\\n  c.is_nullable,\\n  p.rows AS table_rows,\\n  ius.user_seeks, ius.user_scans, ius.user_updates,\\n  ios.leaf_insert_count + ios.leaf_update_count + ios.leaf_delete_count AS leaf_modifications\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\n  AND ic.key_ordinal = 1 AND ic.is_included_column = 0\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nLEFT JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON i.object_id = ios.object_id AND i.index_id = ios.index_id\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND c.is_nullable = 1\\n  AND p.rows > 10000\\n  AND OBJECTPROPERTY(i.object_id, 'IsUserTable') = 1\\nORDER BY p.rows DESC"}	{"condition": "row_count > 0", "description": "Nonclustered indexes with nullable leading key columns on large tables"}	null	2026-02-23 20:18:31.389918
3081	sqlserver	query	Verify SQL Server version confirms deprecation	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS major_version,\\n  CAST(SERVERPROPERTY('ProductVersion') AS NVARCHAR(128)) AS full_version,\\n  CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) AS edition,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 13 THEN 'TF 1117, 1118, 2371 are default behavior'\\n    ELSE 'Pre-2016: flags may still be needed'\\n  END AS tf_1117_1118_2371_status,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 13 THEN 'Use ALTER DATABASE SCOPED CONFIGURATION'\\n    ELSE 'Database scoped config not available'\\n  END AS dbsc_availability"}	{"condition": "major_version >= 13 (SQL Server 2016+) with deprecated trace flags still enabled", "description": "SQL Server version confirms these trace flags are superseded — they should be replaced with database scoped configurations or removed"}	null	2026-02-23 20:18:31.390774
1729	sqlserver	query	Check if hinted queries have high cost relative to non-hinted	{"sql": "SELECT qs.query_hash, qs.total_logical_reads / qs.execution_count AS avg_reads, qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us, qs.total_worker_time / qs.execution_count AS avg_cpu_us, SUBSTRING(t.text, (qs.statement_start_offset/2)+1, ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t WHERE (t.text LIKE '%WITH (INDEX%' OR t.text LIKE '%WITH (FORCESEEK%' OR t.text LIKE '%WITH (FORCESCAN%') AND qs.execution_count > :min_executions AND qs.total_logical_reads / qs.execution_count > :read_threshold ORDER BY avg_reads DESC"}	{"condition": "row_count > 0", "description": "Hinted queries consuming excessive reads — hint may be forcing a suboptimal index"}	{"min_executions": 5, "read_threshold": 10000}	2026-02-23 20:18:31.389924
1723	sqlserver	query	Check NULL density in statistics for these columns	{"sql": "SELECT\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.rows, sp.rows_sampled, sp.modification_counter,\\n  (SELECT TOP 1 equal_rows FROM sys.dm_db_stats_histogram(s.object_id, s.stats_id)\\n   ORDER BY step_number ASC) AS null_or_min_equal_rows,\\n  sp.rows AS total_rows\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.indexes i ON s.object_id = i.object_id AND s.name = i.name\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\n  AND ic.key_ordinal = 1 AND ic.is_included_column = 0\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND c.is_nullable = 1\\n  AND sp.rows > 10000\\n  AND OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\nORDER BY sp.rows DESC"}	{"condition": "null_or_min_equal_rows > total_rows * 0.5", "description": "More than 50% of indexed column values are NULL — index stores many NULL entries providing no seek value"}	null	2026-02-23 20:18:31.389919
1943	sqlserver	query	Check total lock count and lock memory pressure	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_tran_locks) AS current_lock_count,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Lock Memory (KB)'\\n     AND instance_name = '') AS lock_memory_kb,\\n  (SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats\\n   WHERE wait_type LIKE 'LCK_M_%') AS total_lock_wait_ms"}	{"condition": "current_lock_count > 50000 or lock_memory_kb > 50000", "description": "Very high lock count causes the deadlock detection algorithm to consume more CPU per scan"}	null	2026-02-23 20:18:31.38992
1732	sqlserver	query	Find indexes with zero usage since last restart	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, i.index_id, ius.user_seeks, ius.user_scans, ius.user_lookups, ius.user_updates, ius.last_user_seek, ius.last_user_scan FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.type > 0 AND i.is_primary_key = 0 AND i.is_unique_constraint = 0 AND i.is_disabled = 0 AND (ius.user_seeks IS NULL OR ius.user_seeks = 0) AND (ius.user_scans IS NULL OR ius.user_scans = 0) AND (ius.user_lookups IS NULL OR ius.user_lookups = 0) ORDER BY t.name, i.name"}	{"condition": "row_count > 0", "description": "Indexes with zero reads found"}	null	2026-02-23 20:18:31.38992
1724	sqlserver	query	Check if filtered index would be beneficial	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  i.has_filter, i.filter_definition,\\n  ius.user_seeks, ius.user_scans, ius.user_updates,\\n  CASE WHEN i.has_filter = 0 AND ius.user_updates > (ius.user_seeks + ius.user_scans) * 2\\n    THEN 'Candidate for filtered index (WHERE col IS NOT NULL)'\\n    ELSE 'Review usage pattern' END AS recommendation\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\n  AND ic.key_ordinal = 1 AND ic.is_included_column = 0\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND c.is_nullable = 1\\n  AND OBJECTPROPERTY(i.object_id, 'IsUserTable') = 1"}	{"condition": "has_filter = 0 AND user_updates > user_seeks * 2", "description": "Unfiltered index on nullable column with disproportionate update cost — filtered index would reduce size and maintenance"}	null	2026-02-23 20:18:31.389921
1728	sqlserver	query	Find cached plans with index hints	{"sql": "SELECT TOP 30 qs.query_hash, qs.execution_count, qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us, qs.total_logical_reads / qs.execution_count AS avg_reads, SUBSTRING(t.text, (qs.statement_start_offset/2)+1, ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t WHERE (t.text LIKE '%WITH (INDEX%' OR t.text LIKE '%WITH (FORCESEEK%' OR t.text LIKE '%WITH (FORCESCAN%' OR t.text LIKE '%OPTION (TABLE HINT%') AND qs.execution_count > :min_executions ORDER BY avg_elapsed_us DESC"}	{"condition": "row_count > 0", "description": "Queries with index hints found in plan cache"}	{"min_executions": 5}	2026-02-23 20:18:31.389923
