1737	sqlserver	query	Calculate write overhead of redundant indexes	{"sql": "WITH IndexKeyColumns AS (SELECT i.object_id, i.index_id, i.name AS index_name, (SELECT STRING_AGG(CAST(ic.column_id AS VARCHAR), ',') WITHIN GROUP (ORDER BY ic.key_ordinal) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 0) AS key_columns FROM sys.indexes i WHERE i.type > 0 AND i.is_disabled = 0) SELECT OBJECT_NAME(a.object_id) AS table_name, a.index_name AS redundant_index, ISNULL(ius.user_updates, 0) AS write_overhead, ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0) AS reads, (SELECT SUM(ps.used_page_count) * 8 / 1024 FROM sys.dm_db_partition_stats ps WHERE ps.object_id = a.object_id AND ps.index_id = a.index_id) AS size_mb FROM IndexKeyColumns a JOIN IndexKeyColumns b ON a.object_id = b.object_id AND a.index_id <> b.index_id AND b.key_columns LIKE a.key_columns + '%' AND LEN(b.key_columns) > LEN(a.key_columns) LEFT JOIN sys.dm_db_index_usage_stats ius ON a.object_id = ius.object_id AND a.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0) = 0 ORDER BY write_overhead DESC"}	{"condition": "row_count > 0 AND write_overhead > :min_writes", "description": "Redundant indexes incurring write overhead without any read benefit"}	{"min_writes": 500}	2026-02-23 20:18:31.389929
1782	sqlserver	query	Verify index is not providing meaningful seek benefit	{"sql": "SELECT OBJECT_NAME(us.object_id) AS table_name, i.name AS index_name, us.user_seeks, us.user_scans, us.user_lookups, us.user_updates FROM sys.dm_db_index_usage_stats us JOIN sys.indexes i ON us.object_id = i.object_id AND us.index_id = i.index_id WHERE us.database_id = DB_ID() AND i.type = 2 AND us.user_updates > (us.user_seeks + us.user_scans) * :overhead_multiplier ORDER BY us.user_updates DESC"}	{"condition": "row_count > 0", "description": "Write maintenance cost exceeds read benefit by the specified multiplier"}	{"overhead_multiplier": 3}	2026-02-23 20:18:31.38993
1738	sqlserver	query	Find tables with high index-to-column ratio	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, (SELECT COUNT(*) FROM sys.columns c WHERE c.object_id = t.object_id) AS column_count, (SELECT COUNT(*) FROM sys.indexes i WHERE i.object_id = t.object_id AND i.type > 0) AS index_count, (SELECT SUM(ISNULL(ius.user_updates, 0)) FROM sys.indexes i LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.object_id = t.object_id AND i.type > 0) AS total_updates FROM sys.tables t WHERE (SELECT COUNT(*) FROM sys.indexes i WHERE i.object_id = t.object_id AND i.type > 0) > :min_index_count ORDER BY index_count DESC"}	{"condition": "index_count > column_count OR index_count > :over_index_threshold", "description": "Tables with more indexes than columns or exceeding threshold"}	{"min_index_count": 5, "over_index_threshold": 10}	2026-02-23 20:18:31.38993
1747	sqlserver	query	Find partition-aligned indexes with per-partition usage	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, p.partition_number, p.rows, os.range_scan_count, os.singleton_lookup_count, os.leaf_insert_count + os.leaf_update_count + os.leaf_delete_count AS writes FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id JOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id CROSS APPLY sys.dm_db_index_operational_stats(DB_ID(), i.object_id, i.index_id, p.partition_number) os WHERE i.type > 0 AND i.is_primary_key = 0 AND (SELECT COUNT(*) FROM sys.partitions p2 WHERE p2.object_id = i.object_id AND p2.index_id = i.index_id) > 1 ORDER BY t.name, i.name, p.partition_number"}	{"condition": "row_count > 0", "description": "Partition-aligned indexes exist with per-partition stats"}	null	2026-02-23 20:18:31.389931
1739	sqlserver	query	Calculate unused index ratio on over-indexed tables	{"sql": "SELECT OBJECT_NAME(i.object_id) AS table_name, COUNT(*) AS total_indexes, SUM(CASE WHEN ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0) + ISNULL(ius.user_lookups, 0) = 0 THEN 1 ELSE 0 END) AS unused_indexes, SUM(ISNULL(ius.user_updates, 0)) AS total_write_overhead, SUM(ps.used_page_count) * 8 / 1024 AS total_index_size_mb FROM sys.indexes i LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() LEFT JOIN sys.dm_db_partition_stats ps ON i.object_id = ps.object_id AND i.index_id = ps.index_id WHERE i.type > 0 AND i.object_id IN (SELECT t.object_id FROM sys.tables t WHERE (SELECT COUNT(*) FROM sys.indexes ix WHERE ix.object_id = t.object_id AND ix.type > 0) > :min_index_count) GROUP BY i.object_id HAVING SUM(CASE WHEN ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0) = 0 THEN 1 ELSE 0 END) > :min_unused ORDER BY unused_indexes DESC"}	{"condition": "unused_indexes > total_indexes * 0.5", "description": "More than half the indexes on these over-indexed tables are unused"}	{"min_unused": 3, "min_index_count": 5}	2026-02-23 20:18:31.389931
1740	sqlserver	query	Find indexes with zero reads and zero writes	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, i.index_id FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.type > 0 AND i.is_primary_key = 0 AND i.is_unique_constraint = 0 AND i.is_disabled = 0 AND ius.object_id IS NULL ORDER BY t.name, i.name"}	{"condition": "row_count > 0", "description": "Indexes with absolutely no usage stats — never touched since last restart"}	null	2026-02-23 20:18:31.389932
5783	postgresql	config_check	Check log_temp_files and temp object patterns	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('log_temp_files', 'log_statement') ORDER BY name"}	{"condition": "log_statement != 'all'", "description": "If log_statement is not 'all', temp table DDL exclusion may spill over to real tables"}	\N	2026-02-25 00:28:52.405273
1742	sqlserver	query	Check index creation date relative to uptime	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, o.create_date AS index_create_date, DATEDIFF(DAY, o.create_date, GETDATE()) AS age_days FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id JOIN sys.objects o ON i.object_id = o.object_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.type > 0 AND i.is_primary_key = 0 AND i.is_unique_constraint = 0 AND ius.object_id IS NULL AND DATEDIFF(DAY, o.create_date, GETDATE()) > :min_age_days ORDER BY age_days DESC"}	{"condition": "row_count > 0", "description": "Old indexes that have never been used — queries they were designed for never materialized"}	{"min_age_days": 30}	2026-02-23 20:18:31.389933
3184	sqlserver	query	Check SQL Server instance encryption configuration	{"sql": "SELECT SERVERPROPERTY('IsClustered') AS is_clustered,\\n  CONNECTIONPROPERTY('protocol_type') AS current_protocol,\\n  CONNECTIONPROPERTY('encrypt_option') AS current_encrypt,\\n  (SELECT value_in_use FROM sys.configurations WHERE name = 'force encryption') AS force_encryption_config"}	{"condition": "force_encryption_config = 0 or current_encrypt = FALSE", "description": "Encryption not forced — legacy cipher suites may be accepted on unencrypted connections"}	null	2026-02-23 20:18:31.390833
1743	sqlserver	query	Find indexes with zero seeks but high operational overhead	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, ius.user_seeks, ius.user_scans, ius.user_updates, os.leaf_insert_count, os.leaf_update_count, os.leaf_delete_count, os.leaf_allocation_count AS page_splits, os.nonleaf_allocation_count FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() CROSS APPLY sys.dm_db_index_operational_stats(DB_ID(), i.object_id, i.index_id, NULL) os WHERE i.type > 0 AND i.is_primary_key = 0 AND i.is_unique_constraint = 0 AND (ISNULL(ius.user_seeks, 0) = 0 AND ISNULL(ius.user_scans, 0) = 0) AND os.leaf_allocation_count > :min_page_splits ORDER BY os.leaf_allocation_count DESC"}	{"condition": "row_count > 0", "description": "Indexes with zero reads but high page split activity — optimizer is avoiding them"}	{"min_page_splits": 1000}	2026-02-23 20:18:31.389934
1744	sqlserver	query	Check fragmentation level of avoided indexes	{"sql": "SELECT OBJECT_NAME(ips.object_id) AS table_name, i.name AS index_name, ips.avg_fragmentation_in_percent, ips.page_count, ips.avg_page_space_used_in_percent FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id WHERE i.type > 0 AND i.is_primary_key = 0 AND ips.avg_fragmentation_in_percent > :frag_threshold AND ips.page_count > :min_pages AND ISNULL((SELECT ius.user_seeks + ius.user_scans FROM sys.dm_db_index_usage_stats ius WHERE ius.object_id = i.object_id AND ius.index_id = i.index_id AND ius.database_id = DB_ID()), 0) = 0 ORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > :frag_threshold", "description": "Unused indexes are also highly fragmented — optimizer cost model penalizes them"}	{"min_pages": 1000, "frag_threshold": 50}	2026-02-23 20:18:31.389935
1745	sqlserver	query	Find filtered indexes and their usage	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.has_filter, i.filter_definition, ISNULL(ius.user_seeks, 0) AS user_seeks, ISNULL(ius.user_scans, 0) AS user_scans, ISNULL(ius.user_updates, 0) AS user_updates, (SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = i.object_id AND p.index_id = i.index_id) AS filtered_rows, (SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = i.object_id AND p.index_id <= 1) AS total_rows FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.has_filter = 1 ORDER BY user_seeks + user_scans ASC"}	{"condition": "row_count > 0", "description": "Filtered indexes exist in the database"}	null	2026-02-23 20:18:31.389935
1746	sqlserver	query	Identify filtered indexes with zero usage and tiny row coverage	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.filter_definition, ISNULL(ius.user_seeks, 0) AS user_seeks, ISNULL(ius.user_scans, 0) AS user_scans, (SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = i.object_id AND p.index_id = i.index_id) AS filtered_rows, (SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = i.object_id AND p.index_id <= 1) AS total_rows, CASE WHEN (SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = i.object_id AND p.index_id <= 1) > 0 THEN CAST((SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = i.object_id AND p.index_id = i.index_id) AS FLOAT) / (SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = i.object_id AND p.index_id <= 1) * 100 ELSE 0 END AS coverage_pct FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.has_filter = 1 AND (ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0)) = 0 ORDER BY coverage_pct ASC"}	{"condition": "row_count > 0 AND coverage_pct < :max_coverage_pct", "description": "Filtered indexes with zero usage and very low row coverage — filter is too restrictive"}	{"max_coverage_pct": 1.0}	2026-02-23 20:18:31.389936
1748	sqlserver	query	Check for partitioned indexes with zero reads across all partitions	{"sql": "SELECT OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, i.type_desc, SUM(os.range_scan_count + os.singleton_lookup_count) AS total_reads, SUM(os.leaf_insert_count + os.leaf_update_count + os.leaf_delete_count) AS total_writes, COUNT(DISTINCT p.partition_number) AS partition_count FROM sys.indexes i JOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id CROSS APPLY sys.dm_db_index_operational_stats(DB_ID(), i.object_id, i.index_id, p.partition_number) os WHERE i.type > 0 AND i.is_primary_key = 0 AND i.is_unique_constraint = 0 AND (SELECT COUNT(*) FROM sys.partitions p2 WHERE p2.object_id = i.object_id AND p2.index_id = i.index_id) > 1 GROUP BY i.object_id, i.name, i.type_desc HAVING SUM(os.range_scan_count + os.singleton_lookup_count) = 0 AND SUM(os.leaf_insert_count + os.leaf_update_count + os.leaf_delete_count) > :min_writes ORDER BY total_writes DESC"}	{"condition": "row_count > 0", "description": "Partitioned indexes with zero reads across ALL partitions but active writes"}	{"min_writes": 500}	2026-02-23 20:18:31.389936
