1916	sqlserver	query	Check page split rates from index operational stats	{"sql": "SELECT OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ios.leaf_allocation_count AS page_splits,\\n  ios.nonleaf_allocation_count AS nonleaf_splits,\\n  ios.row_lock_wait_count, ios.page_lock_wait_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nWHERE ios.leaf_allocation_count > 1000\\n  AND (ios.row_lock_wait_count > 100 OR ios.page_lock_wait_count > 100)\\nORDER BY ios.leaf_allocation_count DESC"}	{"condition": "high page split count with concurrent lock waits", "description": "Indexes with excessive page splits and lock contention"}	null	2026-02-23 20:18:31.389961
