1791	sqlserver	query	Find queries with CONVERT_IMPLICIT warnings in cached plans	{"sql": "SELECT TOP 20 qs.query_hash, qs.execution_count, qs.total_logical_reads / qs.execution_count AS avg_reads, SUBSTRING(t.text, (qs.statement_start_offset/2)+1, ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text, qp.query_plan FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t CROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp WHERE qp.query_plan.exist('//Warnings/PlanAffectingConvert') = 1 AND qs.execution_count > :min_executions ORDER BY avg_reads DESC"}	{"condition": "row_count > 0", "description": "Cached query plans contain implicit conversion warnings"}	{"min_executions": 10}	2026-02-23 20:18:31.389963
1792	sqlserver	query	Identify indexes on columns involved in implicit conversions that also have low selectivity	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, COL_NAME(ic.object_id, ic.column_id) AS column_name, TYPE_NAME(c.system_type_id) AS column_type, c.max_length, (SELECT COUNT(*) FROM sys.dm_db_stats_histogram(i.object_id, i.index_id)) AS distinct_values, sp.total_rows, CAST((SELECT COUNT(*) FROM sys.dm_db_stats_histogram(i.object_id, i.index_id)) AS FLOAT) / NULLIF(sp.total_rows, 0) AS selectivity FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.tables t ON i.object_id = t.object_id CROSS APPLY (SELECT SUM(rows) AS total_rows FROM sys.partitions WHERE object_id = i.object_id AND index_id IN (0, 1)) sp WHERE i.type = 2 AND i.is_disabled = 0 AND c.system_type_id IN (167, 175, 231, 239) AND sp.total_rows > :min_rows AND CAST((SELECT COUNT(*) FROM sys.dm_db_stats_histogram(i.object_id, i.index_id)) AS FLOAT) / NULLIF(sp.total_rows, 0) < :selectivity_threshold ORDER BY selectivity ASC"}	{"condition": "row_count > 0", "description": "String-type indexed columns with low selectivity that are likely targets of implicit conversion (varchar/nvarchar mismatch, int-to-varchar comparison)"}	{"min_rows": 10000, "selectivity_threshold": 0.01}	2026-02-23 20:18:31.389964
1828	sqlserver	query	Check for recent index maintenance via stats update dates	{"sql": "SELECT OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, STATS_DATE(i.object_id, i.index_id) AS last_stats_update, DATEDIFF(DAY, STATS_DATE(i.object_id, i.index_id), GETDATE()) AS days_since_update, ips.avg_fragmentation_in_percent, ips.page_count FROM sys.indexes i CROSS APPLY sys.dm_db_index_physical_stats(DB_ID(), i.object_id, i.index_id, NULL, 'LIMITED') ips WHERE i.type > 0 AND ips.page_count > :min_pages AND ips.avg_fragmentation_in_percent > :frag_threshold ORDER BY days_since_update DESC"}	{"condition": "days_since_update > :stale_days", "description": "Index statistics have not been updated recently — indicates no maintenance plan is running"}	{"min_pages": 1000, "stale_days": 30, "frag_threshold": 30}	2026-02-23 20:18:31.389964
1833	sqlserver	query	Check available space in data files and tempdb for rebuild	{"sql": "SELECT db.name AS database_name, mf.name AS file_name, mf.type_desc, (mf.size * 8.0 / 1024) AS total_mb, (FILEPROPERTY(mf.name, 'SpaceUsed') * 8.0 / 1024) AS used_mb, ((mf.size - FILEPROPERTY(mf.name, 'SpaceUsed')) * 8.0 / 1024) AS free_mb, mf.max_size, mf.growth FROM sys.master_files mf JOIN sys.databases db ON mf.database_id = db.database_id WHERE mf.database_id IN (DB_ID(), 2) ORDER BY mf.database_id, mf.file_id"}	{"condition": "free_mb is insufficient for largest compressed index rebuild", "description": "Insufficient free space for rebuilding compressed indexes — tempdb or data file space too low"}	null	2026-02-23 20:18:31.389992
1793	sqlserver	query	Find indexed string columns with case-insensitive collation	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, c.name AS column_name, c.collation_name, TYPE_NAME(c.system_type_id) AS data_type, sp.total_rows, (SELECT COUNT(*) FROM sys.dm_db_stats_histogram(i.object_id, i.index_id)) AS histogram_steps FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.tables t ON i.object_id = t.object_id CROSS APPLY (SELECT SUM(rows) AS total_rows FROM sys.partitions WHERE object_id = i.object_id AND index_id IN (0, 1)) sp WHERE i.type = 2 AND i.is_disabled = 0 AND c.collation_name LIKE '%_CI_%' AND c.system_type_id IN (167, 175, 231, 239) AND sp.total_rows > :min_rows ORDER BY sp.total_rows DESC"}	{"condition": "row_count > 0", "description": "Indexed string columns using case-insensitive collation"}	{"min_rows": 10000}	2026-02-23 20:18:31.389965
2280	sqlserver	query	Check if orphaned queries are contributing to worker thread pressure	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests\\n   WHERE session_id > 50 AND DATEDIFF(MINUTE, start_time, GETDATE()) > 30) AS long_running_queries,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS total_workers,\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_workers,\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS queued_requests,\\n  CAST((SELECT COUNT(*) FROM sys.dm_exec_requests\\n    WHERE session_id > 50 AND DATEDIFF(MINUTE, start_time, GETDATE()) > 30) AS FLOAT)\\n    / NULLIF((SELECT max_workers_count FROM sys.dm_os_sys_info), 0) * 100 AS pct_workers_orphaned"}	{"condition": "pct_workers_orphaned > 10 OR (long_running_queries > 10 AND queued_requests > 0)", "description": "Orphaned queries consuming over 10% of worker threads, or causing request queuing"}	null	2026-02-23 20:18:31.390278
1794	sqlserver	query	Check selectivity of CI-collated indexed columns	{"sql": "SELECT OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, c.name AS column_name, c.collation_name, (SELECT COUNT(*) FROM sys.dm_db_stats_histogram(i.object_id, i.index_id)) AS distinct_values, sp.total_rows, CAST((SELECT COUNT(*) FROM sys.dm_db_stats_histogram(i.object_id, i.index_id)) AS FLOAT) / NULLIF(sp.total_rows, 0) AS selectivity FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id CROSS APPLY (SELECT SUM(rows) AS total_rows FROM sys.partitions WHERE object_id = i.object_id AND index_id IN (0, 1)) sp WHERE i.type = 2 AND c.collation_name LIKE '%_CI_%' AND c.system_type_id IN (167, 175, 231, 239) AND sp.total_rows > :min_rows AND CAST((SELECT COUNT(*) FROM sys.dm_db_stats_histogram(i.object_id, i.index_id)) AS FLOAT) / NULLIF(sp.total_rows, 0) < :selectivity_threshold ORDER BY selectivity ASC"}	{"condition": "row_count > 0", "description": "CI-collated columns with low selectivity — case folding reduces effective distinct values"}	{"min_rows": 10000, "selectivity_threshold": 0.01}	2026-02-23 20:18:31.389966
