1795	sqlserver	query	Find indexed columns with high NULL ratio from statistics	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, COL_NAME(ic.object_id, ic.column_id) AS leading_column, c.is_nullable, sp.total_rows, (SELECT TOP 1 h.equal_rows FROM sys.dm_db_stats_histogram(i.object_id, i.index_id) h ORDER BY h.range_high_key ASC) AS first_step_rows, CASE WHEN sp.total_rows > 0 THEN sp.total_rows - ISNULL((SELECT SUM(h.equal_rows + h.range_rows) FROM sys.dm_db_stats_histogram(i.object_id, i.index_id) h), 0) ELSE 0 END AS estimated_nulls FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.tables t ON i.object_id = t.object_id CROSS APPLY (SELECT SUM(rows) AS total_rows FROM sys.partitions WHERE object_id = i.object_id AND index_id IN (0, 1)) sp WHERE i.type = 2 AND i.is_disabled = 0 AND c.is_nullable = 1 AND sp.total_rows > :min_rows ORDER BY estimated_nulls DESC"}	{"condition": "estimated_nulls > total_rows * :null_ratio_threshold", "description": "NULL values constitute more than the threshold ratio of total rows"}	{"min_rows": 10000, "null_ratio_threshold": 0.7}	2026-02-23 20:18:31.389966
1796	sqlserver	query	Check if the index is a full (non-filtered) index including all NULLs	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.has_filter, i.filter_definition, ps.page_count, ps.record_count, ps.avg_record_size_in_bytes, ps.page_count * 8 AS index_size_kb FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id CROSS APPLY sys.dm_db_index_physical_stats(DB_ID(), i.object_id, i.index_id, NULL, 'LIMITED') ps WHERE i.type = 2 AND i.has_filter = 0 AND i.object_id IN (SELECT ic.object_id FROM sys.index_columns ic JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id WHERE ic.key_ordinal = 1 AND c.is_nullable = 1) AND ps.page_count > :min_pages ORDER BY ps.page_count DESC"}	{"condition": "row_count > 0", "description": "Unfiltered indexes including NULL-heavy columns — index is bloated with NULL entries that are rarely queried"}	{"min_pages": 100}	2026-02-23 20:18:31.389967
1797	sqlserver	query	Find tables with high index count	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, COUNT(i.index_id) AS index_count, SUM(CASE WHEN i.type = 2 THEN 1 ELSE 0 END) AS nonclustered_count, (SELECT SUM(rows) FROM sys.partitions WHERE object_id = t.object_id AND index_id IN (0, 1)) AS row_count FROM sys.tables t JOIN sys.indexes i ON t.object_id = i.object_id WHERE i.type > 0 GROUP BY t.schema_id, t.name, t.object_id HAVING COUNT(i.index_id) > :index_threshold ORDER BY index_count DESC"}	{"condition": "row_count > 0", "description": "Tables with more nonclustered indexes than the threshold"}	{"index_threshold": 8}	2026-02-23 20:18:31.389968
1798	sqlserver	query	Check write-to-read ratio on heavily indexed tables	{"sql": "SELECT OBJECT_NAME(us.object_id) AS table_name, SUM(us.user_updates) AS total_writes, SUM(us.user_seeks + us.user_scans + us.user_lookups) AS total_reads, CASE WHEN SUM(us.user_seeks + us.user_scans + us.user_lookups) > 0 THEN CAST(SUM(us.user_updates) AS FLOAT) / SUM(us.user_seeks + us.user_scans + us.user_lookups) ELSE SUM(us.user_updates) END AS write_to_read_ratio, COUNT(DISTINCT us.index_id) AS used_index_count FROM sys.dm_db_index_usage_stats us WHERE us.database_id = DB_ID() AND us.object_id IN (SELECT t.object_id FROM sys.tables t JOIN sys.indexes i ON t.object_id = i.object_id WHERE i.type > 0 GROUP BY t.object_id HAVING COUNT(i.index_id) > :index_threshold) GROUP BY us.object_id HAVING SUM(us.user_updates) > :min_writes ORDER BY write_to_read_ratio DESC"}	{"condition": "write_to_read_ratio > :ratio_threshold", "description": "Write operations far exceed reads — indexes are causing net performance degradation on write-heavy table"}	{"min_writes": 1000, "index_threshold": 8, "ratio_threshold": 5.0}	2026-02-23 20:18:31.389968
