1830	sqlserver	query	Find indexes with high fill factor and page splits	{"sql": "SELECT OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, i.type_desc, i.fill_factor, os.leaf_allocation_count AS page_splits, os.leaf_insert_count + os.leaf_update_count AS write_ops, CASE WHEN (os.leaf_insert_count + os.leaf_update_count) > 0 THEN CAST(os.leaf_allocation_count AS FLOAT) / (os.leaf_insert_count + os.leaf_update_count) * 100 ELSE 0 END AS split_per_write_pct FROM sys.indexes i JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os ON i.object_id = os.object_id AND i.index_id = os.index_id WHERE i.type > 0 AND i.fill_factor > :min_fill_factor AND i.fill_factor NOT IN (0, 100) AND os.leaf_allocation_count > :min_splits AND (os.leaf_insert_count + os.leaf_update_count) > :min_writes ORDER BY split_per_write_pct DESC"}	{"condition": "row_count > 0 AND split_per_write_pct > :split_threshold", "description": "Indexes with non-default but still-high fill factor experiencing excessive page splits"}	{"min_splits": 300, "min_writes": 5000, "min_fill_factor": 85, "split_threshold": 5}	2026-02-23 20:18:31.389985
1960	sqlserver	query	Identify tables with high modification counts triggering frequent stats updates	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, s.name AS stat_name, sp.modification_counter, sp.rows, sp.last_updated, CAST(sp.modification_counter AS FLOAT) / NULLIF(sp.rows, 0) * 100 AS pct_modified FROM sys.tables t JOIN sys.stats s ON t.object_id = s.object_id CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE sp.modification_counter > 1000 AND sp.rows > 0 ORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0 AND modification_counter > 1000", "description": "Tables with high modification counts that will trigger synchronous statistics recalculation, blocking concurrent queries"}	null	2026-02-23 20:18:31.390076
