1831	sqlserver	query	Check fragmentation accumulation rate on high fill factor indexes	{"sql": "SELECT OBJECT_NAME(ips.object_id) AS table_name, i.name AS index_name, i.fill_factor, ips.avg_fragmentation_in_percent, ips.avg_page_space_used_in_percent, ips.page_count, DATEDIFF(DAY, STATS_DATE(i.object_id, i.index_id), GETDATE()) AS days_since_rebuild FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id WHERE i.type > 0 AND i.fill_factor > :min_fill_factor AND i.fill_factor NOT IN (0, 100) AND ips.page_count > :min_pages AND ips.avg_fragmentation_in_percent > :frag_threshold ORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > :frag_threshold AND days_since_rebuild < :recent_rebuild_days", "description": "High fragmentation even shortly after rebuild — fill factor is too high for the write workload"}	{"min_pages": 1000, "frag_threshold": 25, "min_fill_factor": 85, "recent_rebuild_days": 14}	2026-02-23 20:18:31.38999
1821	sqlserver	query	Find indexes with variable-length key or included columns and high split rates	{"sql": "SELECT OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, i.type_desc, STRING_AGG(c.name + ' (' + tp.name + '(' + CAST(c.max_length AS VARCHAR) + '))', ', ') AS variable_columns, os.leaf_update_count, os.leaf_allocation_count AS page_splits, CASE WHEN os.leaf_update_count > 0 THEN CAST(os.leaf_allocation_count AS FLOAT) / os.leaf_update_count * 100 ELSE 0 END AS split_per_update_pct FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.user_type_id = tp.user_type_id JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os ON i.object_id = os.object_id AND i.index_id = os.index_id WHERE i.type > 0 AND tp.name IN ('varchar', 'nvarchar', 'varbinary') AND c.max_length > :min_col_length AND os.leaf_update_count > :min_updates AND os.leaf_allocation_count > :min_splits GROUP BY i.object_id, i.name, i.type_desc, os.leaf_update_count, os.leaf_allocation_count ORDER BY split_per_update_pct DESC"}	{"condition": "row_count > 0 AND split_per_update_pct > :split_threshold", "description": "Indexes with variable-length columns showing high page split rates relative to updates"}	{"min_splits": 300, "min_updates": 5000, "min_col_length": 50, "split_threshold": 5}	2026-02-23 20:18:31.389986
1843	sqlserver	query	Check if smaller included set is subset of larger	{"sql": "WITH IndexIncl AS (SELECT i.object_id, i.index_id, i.name AS index_name, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type = 2 GROUP BY i.object_id, i.index_id, i.name), InclCols AS (SELECT i.object_id, i.index_id, ic.column_id FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE ic.is_included_column = 1 AND i.type = 2), Pairs AS (SELECT a.object_id, a.index_id AS id_a, b.index_id AS id_b, a.index_name AS name_a, b.index_name AS name_b FROM IndexIncl a JOIN IndexIncl b ON a.object_id = b.object_id AND a.index_id < b.index_id AND a.key_cols = b.key_cols) SELECT OBJECT_NAME(p.object_id) AS table_name, p.name_a, p.name_b, (SELECT COUNT(*) FROM InclCols ca WHERE ca.object_id = p.object_id AND ca.index_id = p.id_a) AS incl_a_count, (SELECT COUNT(*) FROM InclCols cb WHERE cb.object_id = p.object_id AND cb.index_id = p.id_b) AS incl_b_count, (SELECT COUNT(*) FROM InclCols ca WHERE ca.object_id = p.object_id AND ca.index_id = p.id_a AND ca.column_id NOT IN (SELECT cb.column_id FROM InclCols cb WHERE cb.object_id = p.object_id AND cb.index_id = p.id_b)) AS a_only_cols FROM Pairs p WHERE (SELECT COUNT(*) FROM InclCols ca WHERE ca.object_id = p.object_id AND ca.index_id = p.id_a AND ca.column_id NOT IN (SELECT cb.column_id FROM InclCols cb WHERE cb.object_id = p.object_id AND cb.index_id = p.id_b)) = 0 OR (SELECT COUNT(*) FROM InclCols cb WHERE cb.object_id = p.object_id AND cb.index_id = p.id_b AND cb.column_id NOT IN (SELECT ca.column_id FROM InclCols ca WHERE ca.object_id = p.object_id AND ca.index_id = p.id_a)) = 0 ORDER BY table_name"}	{"condition": "row_count > 0 AND a_only_cols = 0", "description": "One index's included columns are a complete subset of the other's — the narrower index is redundant"}	null	2026-02-23 20:18:31.389999
1823	sqlserver	query	Check fragmentation and page density on candidate indexes	{"sql": "SELECT OBJECT_NAME(ips.object_id) AS table_name, i.name AS index_name, ips.avg_fragmentation_in_percent, ips.avg_page_space_used_in_percent, ips.page_count, i.fill_factor FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id WHERE i.type > 0 AND ips.page_count > :min_pages AND ips.avg_fragmentation_in_percent > :frag_threshold AND i.object_id IN (SELECT os.object_id FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os WHERE os.leaf_allocation_count > :min_splits AND os.leaf_update_count > :min_updates) ORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > :frag_threshold", "description": "High fragmentation confirms varchar growth is causing page splits and index degradation"}	{"min_pages": 1000, "min_splits": 300, "min_updates": 5000, "frag_threshold": 25}	2026-02-23 20:18:31.389987
3999	postgresql	query	Check archiver failure timing pattern	{"sql": "SELECT failed_count, last_failed_wal, last_failed_time, last_archived_time, (last_failed_time - last_archived_time) AS gap_since_last_success FROM pg_stat_archiver WHERE failed_count > 0"}	{"condition": "row_count > 0 AND gap_since_last_success > interval ':gap_minutes minutes'", "description": "Extended gap between last success and recent failure suggests storage became unreachable"}	{"gap_minutes": 30}	2026-02-25 00:28:52.405273
1824	sqlserver	query	Find clustered indexes on non-sequential key columns	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, c.name AS key_column, tp.name AS data_type, c.is_identity, CASE WHEN tp.name = 'uniqueidentifier' THEN 'GUID' WHEN tp.name IN ('varchar', 'nvarchar', 'char', 'nchar') THEN 'String' WHEN tp.name IN ('datetime', 'datetime2', 'date') AND c.is_identity = 0 THEN 'Date (may be non-monotonic)' WHEN c.is_identity = 0 AND tp.name IN ('int', 'bigint', 'smallint') THEN 'Integer (non-IDENTITY)' ELSE 'Other' END AS key_type_assessment FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.user_type_id = tp.user_type_id WHERE i.type = 1 AND c.is_identity = 0 AND tp.name NOT IN ('int', 'bigint', 'smallint', 'tinyint') ORDER BY t.name"}	{"condition": "row_count > 0", "description": "Clustered indexes found on non-sequential, non-IDENTITY columns"}	null	2026-02-23 20:18:31.389988
1825	sqlserver	query	Check page split rate on non-sequential clustered indexes	{"sql": "SELECT OBJECT_NAME(os.object_id) AS table_name, i.name AS index_name, c.name AS key_column, tp.name AS data_type, os.leaf_allocation_count AS page_splits, os.leaf_insert_count AS inserts, CASE WHEN os.leaf_insert_count > 0 THEN CAST(os.leaf_allocation_count AS FLOAT) / os.leaf_insert_count * 100 ELSE 0 END AS split_pct FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) os JOIN sys.indexes i ON os.object_id = i.object_id AND os.index_id = i.index_id JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.user_type_id = tp.user_type_id WHERE i.type = 1 AND c.is_identity = 0 AND os.leaf_insert_count > :min_inserts AND os.leaf_allocation_count > :min_splits ORDER BY split_pct DESC"}	{"condition": "split_pct > :split_threshold_pct", "description": "High page split rate on non-sequential clustered indexes confirms random insert pattern"}	{"min_splits": 500, "min_inserts": 5000, "split_threshold_pct": 10}	2026-02-23 20:18:31.389989
1924	sqlserver	query	Check plan cache for SELECT-then-UPDATE patterns	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE t.text LIKE '%SELECT%UPDATE%'\\n  AND t.text NOT LIKE '%sys.%'\\n  AND qs.execution_count > 10\\nORDER BY qs.execution_count DESC"}	{"condition": "stored procedures or batches containing SELECT followed by UPDATE on same table", "description": "Read-then-update pattern found in frequently executed queries"}	null	2026-02-23 20:18:31.390049
1826	sqlserver	query	Check fragmentation level on non-sequential clustered indexes	{"sql": "SELECT OBJECT_NAME(ips.object_id) AS table_name, i.name AS index_name, ips.avg_fragmentation_in_percent, ips.page_count, ips.avg_page_space_used_in_percent FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id WHERE i.type = 1 AND c.is_identity = 0 AND ips.page_count > :min_pages ORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > :frag_threshold", "description": "High fragmentation on non-sequential clustered indexes confirms suboptimal key choice"}	{"min_pages": 1000, "frag_threshold": 30}	2026-02-23 20:18:31.389989
1827	sqlserver	query	Find indexes with high fragmentation across the database	{"sql": "SELECT COUNT(*) AS fragmented_index_count, AVG(ips.avg_fragmentation_in_percent) AS avg_frag_pct, MAX(ips.avg_fragmentation_in_percent) AS max_frag_pct, SUM(CASE WHEN ips.avg_fragmentation_in_percent > 30 THEN 1 ELSE 0 END) AS severely_fragmented, SUM(CASE WHEN ips.avg_fragmentation_in_percent BETWEEN 10 AND 30 THEN 1 ELSE 0 END) AS moderately_fragmented FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id WHERE i.type > 0 AND ips.page_count > :min_pages"}	{"condition": "severely_fragmented > :severity_count OR avg_frag_pct > :avg_frag_threshold", "description": "Widespread fragmentation across the database — many indexes need maintenance"}	{"min_pages": 1000, "severity_count": 10, "avg_frag_threshold": 25}	2026-02-23 20:18:31.38999
