1834	sqlserver	query	Estimate rebuild space requirement for largest compressed indexes	{"sql": "SELECT TOP 10 OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, p.data_compression_desc, (SUM(au.total_pages) * 8.0 / 1024) AS current_size_mb, (SUM(au.total_pages) * 8.0 / 1024) * 1.5 AS estimated_rebuild_mb, (SELECT ((mf.size - FILEPROPERTY(mf.name, 'SpaceUsed')) * 8.0 / 1024) FROM sys.master_files mf WHERE mf.database_id = DB_ID() AND mf.type = 0 ORDER BY mf.file_id OFFSET 0 ROWS FETCH NEXT 1 ROW ONLY) AS data_free_mb FROM sys.indexes i JOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id JOIN sys.allocation_units au ON p.partition_id = au.container_id WHERE p.data_compression > 0 AND i.type > 0 GROUP BY i.object_id, i.name, p.data_compression_desc ORDER BY SUM(au.total_pages) DESC"}	{"condition": "estimated_rebuild_mb > data_free_mb", "description": "Largest compressed indexes require more space for rebuild than is available — maintenance blocked"}	null	2026-02-23 20:18:31.389992
1835	sqlserver	query	Check for active index rebuild or reorganize operations	{"sql": "SELECT r.session_id, r.command, r.status, r.wait_type, r.wait_time, r.blocking_session_id, r.percent_complete, DATEDIFF(MINUTE, r.start_time, GETDATE()) AS elapsed_minutes, OBJECT_NAME(p.object_id) AS table_name, i.name AS index_name, t.text AS sql_text FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t LEFT JOIN sys.partitions p ON r.command LIKE 'ALTER INDEX%' LEFT JOIN sys.indexes i ON p.object_id = i.object_id AND p.index_id = i.index_id WHERE r.command IN ('ALTER INDEX', 'DbccFilesCompact', 'DbccSpaceReclaim') OR t.text LIKE '%ALTER INDEX%REBUILD%' OR t.text LIKE '%ALTER INDEX%REORGANIZE%'"}	{"condition": "row_count > 0", "description": "Active index maintenance operations currently running"}	null	2026-02-23 20:18:31.389993
1921	sqlserver	query	Correlate with deadlock events	{"sql": "SELECT cntr_value AS total_deadlocks\\nFROM sys.dm_os_performance_counters\\nWHERE counter_name = 'Number of Deadlocks/sec'\\n  AND instance_name = '_Total'"}	{"condition": "total_deadlocks > 0", "description": "Deadlocks occurring while SERIALIZABLE sessions are active"}	null	2026-02-23 20:18:31.389994
1936	sqlserver	query	Find active large DML operations	{"sql": "SELECT r.session_id, r.command, r.status,\\n  r.total_elapsed_time / 1000 AS elapsed_sec,\\n  r.row_count AS rows_affected,\\n  r.logical_reads, r.writes,\\n  SUBSTRING(t.text, (r.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE r.command IN ('INSERT', 'UPDATE', 'DELETE', 'BULK INSERT')\\n  AND r.row_count > 5000\\n  AND r.session_id > 50\\nORDER BY r.row_count DESC"}	{"condition": "DML operations affecting > 5000 rows in a single statement", "description": "Large batch operations that acquire many locks and risk escalation"}	null	2026-02-23 20:18:31.390055
1836	sqlserver	query	Check for blocking caused by or affecting index operations	{"sql": "SELECT blocked.session_id AS blocked_session, blocked.wait_type, blocked.wait_time / 1000 AS wait_seconds, blocked.blocking_session_id AS blocker_session, blocker_text.text AS blocker_sql, blocked_text.text AS blocked_sql, blocked.command AS blocked_command FROM sys.dm_exec_requests blocked JOIN sys.dm_exec_requests blocker ON blocked.blocking_session_id = blocker.session_id CROSS APPLY sys.dm_exec_sql_text(blocked.sql_handle) blocked_text CROSS APPLY sys.dm_exec_sql_text(blocker.sql_handle) blocker_text WHERE (blocker.command IN ('ALTER INDEX', 'DbccFilesCompact') OR blocked.command IN ('ALTER INDEX', 'DbccFilesCompact') OR blocker_text.text LIKE '%ALTER INDEX%REBUILD%' OR blocker_text.text LIKE '%ALTER INDEX%REORGANIZE%' OR blocked_text.text LIKE '%ALTER INDEX%REBUILD%')"}	{"condition": "row_count > 0", "description": "Active blocking between index operations and DML queries"}	null	2026-02-23 20:18:31.389994
1837	sqlserver	query	Check if ONLINE rebuild option is not being used	{"sql": "SELECT r.session_id, t.text AS sql_text, CASE WHEN t.text LIKE '%ONLINE%=%ON%' THEN 'ONLINE' WHEN t.text LIKE '%ONLINE%=%OFF%' THEN 'OFFLINE' ELSE 'OFFLINE (default)' END AS rebuild_mode, r.percent_complete, DATEDIFF(MINUTE, r.start_time, GETDATE()) AS elapsed_minutes FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE t.text LIKE '%ALTER INDEX%REBUILD%' OR t.text LIKE '%ALTER INDEX%REORGANIZE%'"}	{"condition": "rebuild_mode != 'ONLINE'", "description": "Index rebuild is running in OFFLINE mode, blocking all DML on the table during the operation"}	null	2026-02-23 20:18:31.389995
1840	sqlserver	query	Find composite indexes with overlapping left-prefixes	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.type_desc, i.is_unique, COUNT(*) AS key_col_count, STRING_AGG(CAST(ic.column_id AS VARCHAR), ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.is_included_column = 0 WHERE i.type IN (1, 2) GROUP BY i.object_id, i.index_id, i.name, i.type_desc, i.is_unique) SELECT OBJECT_NAME(a.object_id) AS table_name, a.index_name AS shorter_index, a.key_col_count AS shorter_key_count, b.index_name AS wider_index, b.key_col_count AS wider_key_count, a.key_cols AS shorter_keys, b.key_cols AS wider_keys FROM IndexKeys a JOIN IndexKeys b ON a.object_id = b.object_id AND a.index_id != b.index_id AND a.key_col_count < b.key_col_count AND b.key_cols LIKE a.key_cols + ',%' WHERE a.key_col_count >= 1 ORDER BY OBJECT_NAME(a.object_id), a.index_name"}	{"condition": "row_count > 0", "description": "Composite indexes found where the shorter is a left-prefix of the wider index"}	null	2026-02-23 20:18:31.389997
1841	sqlserver	query	Check usage stats to confirm shorter index is redundant	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.is_unique, i.is_primary_key, COUNT(*) AS key_col_count, STRING_AGG(CAST(ic.column_id AS VARCHAR), ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.is_included_column = 0 WHERE i.type IN (1, 2) GROUP BY i.object_id, i.index_id, i.name, i.is_unique, i.is_primary_key), Overlapping AS (SELECT a.object_id, a.index_id AS short_id, b.index_id AS wide_id, a.index_name AS short_name, b.index_name AS wide_name, a.is_unique AS short_unique, a.is_primary_key AS short_pk FROM IndexKeys a JOIN IndexKeys b ON a.object_id = b.object_id AND a.index_id != b.index_id AND a.key_col_count < b.key_col_count AND b.key_cols LIKE a.key_cols + ',%') SELECT OBJECT_NAME(o.object_id) AS table_name, o.short_name, o.wide_name, o.short_unique, o.short_pk, ISNULL(us.user_seeks, 0) AS short_seeks, ISNULL(us.user_scans, 0) AS short_scans, ISNULL(us.user_updates, 0) AS short_writes, ISNULL(uw.user_seeks, 0) AS wide_seeks, ISNULL(uw.user_scans, 0) AS wide_scans FROM Overlapping o LEFT JOIN sys.dm_db_index_usage_stats us ON o.object_id = us.object_id AND o.short_id = us.index_id AND us.database_id = DB_ID() LEFT JOIN sys.dm_db_index_usage_stats uw ON o.object_id = uw.object_id AND o.wide_id = uw.index_id AND uw.database_id = DB_ID() WHERE o.short_pk = 0 AND o.short_unique = 0 ORDER BY short_writes DESC"}	{"condition": "row_count > 0", "description": "Overlapping non-PK, non-unique indexes — the shorter index is likely redundant since the wider index can satisfy the same seeks"}	null	2026-02-23 20:18:31.389997
1850	sqlserver	query	Check usage efficiency of overlapping filtered indexes	{"sql": "SELECT OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, i.filter_definition, ISNULL(ius.user_seeks, 0) AS seeks, ISNULL(ius.user_scans, 0) AS scans, ISNULL(ius.user_updates, 0) AS writes, CASE WHEN ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0) = 0 THEN 'UNUSED' WHEN ISNULL(ius.user_updates, 0) > (ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0)) * 10 THEN 'WRITE-HEAVY' ELSE 'ACTIVE' END AS status FROM sys.indexes i LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.has_filter = 1 AND i.type = 2 AND i.object_id IN (SELECT a.object_id FROM sys.indexes a JOIN sys.indexes b ON a.object_id = b.object_id AND a.index_id < b.index_id WHERE a.has_filter = 1 AND b.has_filter = 1) ORDER BY OBJECT_NAME(i.object_id), i.name"}	{"condition": "row_count > 0 AND any status = 'UNUSED' OR 'WRITE-HEAVY'", "description": "Overlapping filtered indexes where at least one is unused or write-heavy — confirms redundancy"}	null	2026-02-23 20:18:31.389999
1844	sqlserver	query	Find single-column indexes covered by multi-column indexes	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.is_unique, i.is_primary_key, i.is_unique_constraint, COUNT(CASE WHEN ic.is_included_column = 0 THEN 1 END) AS key_count, COUNT(CASE WHEN ic.is_included_column = 1 THEN 1 END) AS incl_count, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols, MIN(CASE WHEN ic.is_included_column = 0 AND ic.key_ordinal = 1 THEN ic.column_id END) AS first_key_col FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type = 2 GROUP BY i.object_id, i.index_id, i.name, i.is_unique, i.is_primary_key, i.is_unique_constraint) SELECT OBJECT_NAME(narrow.object_id) AS table_name, narrow.index_name AS narrow_index, narrow.key_count AS narrow_keys, wide.index_name AS wider_index, wide.key_count AS wider_keys, narrow.is_unique AS narrow_unique, narrow.is_primary_key AS narrow_pk FROM IndexKeys narrow JOIN IndexKeys wide ON narrow.object_id = wide.object_id AND narrow.index_id != wide.index_id AND narrow.key_count < wide.key_count AND wide.key_cols LIKE narrow.key_cols + ',%' WHERE narrow.incl_count = 0 AND narrow.is_primary_key = 0 AND narrow.is_unique_constraint = 0 ORDER BY OBJECT_NAME(narrow.object_id)"}	{"condition": "row_count > 0", "description": "Narrow indexes found that are strict left-prefix subsets of wider indexes"}	null	2026-02-23 20:18:31.39
1845	sqlserver	query	Check usage and write overhead of narrow subset indexes	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.is_unique, i.is_primary_key, i.is_unique_constraint, COUNT(CASE WHEN ic.is_included_column = 0 THEN 1 END) AS key_count, COUNT(CASE WHEN ic.is_included_column = 1 THEN 1 END) AS incl_count, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type = 2 GROUP BY i.object_id, i.index_id, i.name, i.is_unique, i.is_primary_key, i.is_unique_constraint), Subsets AS (SELECT narrow.object_id, narrow.index_id AS narrow_id, wide.index_id AS wide_id, narrow.index_name AS narrow_name, wide.index_name AS wide_name FROM IndexKeys narrow JOIN IndexKeys wide ON narrow.object_id = wide.object_id AND narrow.index_id != wide.index_id AND narrow.key_count < wide.key_count AND wide.key_cols LIKE narrow.key_cols + ',%' WHERE narrow.incl_count = 0 AND narrow.is_primary_key = 0 AND narrow.is_unique_constraint = 0) SELECT OBJECT_NAME(s.object_id) AS table_name, s.narrow_name, s.wide_name, ISNULL(un.user_seeks, 0) AS narrow_seeks, ISNULL(un.user_scans, 0) AS narrow_scans, ISNULL(un.user_updates, 0) AS narrow_writes, ISNULL(uw.user_seeks, 0) AS wide_seeks, ISNULL(uw.user_scans, 0) AS wide_scans, (SELECT SUM(au.used_pages) * 8 / 1024 FROM sys.partitions p JOIN sys.allocation_units au ON p.partition_id = au.container_id WHERE p.object_id = s.object_id AND p.index_id = s.narrow_id) AS narrow_size_mb FROM Subsets s LEFT JOIN sys.dm_db_index_usage_stats un ON s.object_id = un.object_id AND s.narrow_id = un.index_id AND un.database_id = DB_ID() LEFT JOIN sys.dm_db_index_usage_stats uw ON s.object_id = uw.object_id AND s.wide_id = uw.index_id AND uw.database_id = DB_ID() ORDER BY narrow_writes DESC"}	{"condition": "row_count > 0", "description": "Narrow subset indexes confirmed with write overhead — the wider index can replace them"}	null	2026-02-23 20:18:31.39
1846	sqlserver	query	Find duplicate indexes with different naming patterns	{"sql": "WITH IndexFingerprint AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.type_desc, STRING_AGG(CAST(ic.column_id AS VARCHAR) + CASE WHEN ic.is_included_column = 1 THEN 'i' ELSE 'k' + CAST(ic.key_ordinal AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.is_included_column, ic.key_ordinal, ic.column_id) AS fingerprint FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type = 2 GROUP BY i.object_id, i.index_id, i.name, i.type_desc) SELECT OBJECT_NAME(a.object_id) AS table_name, a.index_name AS index_a, b.index_name AS index_b, a.fingerprint, CASE WHEN a.index_name LIKE 'IX_%' AND b.index_name LIKE 'idx_%' THEN 'Different naming convention' WHEN a.index_name LIKE 'IX_%' AND b.index_name LIKE 'nci_%' THEN 'Different naming convention' WHEN a.index_name LIKE '%_idx' AND b.index_name LIKE 'IX_%' THEN 'Different naming convention' WHEN LEFT(a.index_name, 3) != LEFT(b.index_name, 3) THEN 'Different prefix pattern' ELSE 'Same prefix — likely intentional' END AS naming_analysis FROM IndexFingerprint a JOIN IndexFingerprint b ON a.object_id = b.object_id AND a.index_id < b.index_id AND a.fingerprint = b.fingerprint WHERE a.index_name != b.index_name ORDER BY OBJECT_NAME(a.object_id)"}	{"condition": "row_count > 0", "description": "Structurally identical indexes with different names found — likely independent creation"}	null	2026-02-23 20:18:31.390001
1849	sqlserver	query	Compare filter predicates and key columns of filtered indexes	{"sql": "SELECT OBJECT_NAME(a.object_id) AS table_name, a.name AS index_a, a.filter_definition AS filter_a, b.name AS index_b, b.filter_definition AS filter_b, (SELECT STRING_AGG(CAST(ic.column_id AS VARCHAR), ',') WITHIN GROUP (ORDER BY ic.key_ordinal) FROM sys.index_columns ic WHERE ic.object_id = a.object_id AND ic.index_id = a.index_id AND ic.is_included_column = 0) AS keys_a, (SELECT STRING_AGG(CAST(ic.column_id AS VARCHAR), ',') WITHIN GROUP (ORDER BY ic.key_ordinal) FROM sys.index_columns ic WHERE ic.object_id = b.object_id AND ic.index_id = b.index_id AND ic.is_included_column = 0) AS keys_b FROM sys.indexes a JOIN sys.indexes b ON a.object_id = b.object_id AND a.index_id < b.index_id WHERE a.has_filter = 1 AND b.has_filter = 1 AND a.type = 2 AND b.type = 2 ORDER BY OBJECT_NAME(a.object_id)"}	{"condition": "row_count > 0 AND (keys_a = keys_b OR filter_a contains subset of filter_b)", "description": "Filtered indexes with same key columns and overlapping or similar filter predicates"}	null	2026-02-23 20:18:31.390003
