2281	sqlserver	query	Check deadlock frequency from system health XE session	{"sql": "SELECT\\n  COUNT(*) AS deadlock_count,\\n  MIN(event_timestamp) AS earliest_deadlock,\\n  MAX(event_timestamp) AS latest_deadlock\\nFROM (\\n  SELECT\\n    xed.value('@timestamp', 'datetime2') AS event_timestamp\\n  FROM (\\n    SELECT CAST(target_data AS XML) AS target_xml\\n    FROM sys.dm_xe_session_targets st\\n    JOIN sys.dm_xe_sessions s ON s.address = st.event_session_address\\n    WHERE s.name = 'system_health'\\n      AND st.target_name = 'ring_buffer'\\n  ) AS data\\n  CROSS APPLY target_xml.nodes('RingBufferTarget/event[@name=\\"xml_deadlock_report\\"]') AS xed(xed)\\n) dl\\nWHERE event_timestamp > DATEADD(HOUR, -1, GETDATE())"}	{"condition": "deadlock_count > 5 in the last hour", "description": "Frequent deadlocks indicate lock contention patterns that hold and recycle worker threads"}	null	2026-02-23 20:18:31.390278
1851	sqlserver	query	Find indexes with high write overhead and low or no reads	{"sql": "SELECT OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, i.type_desc, ISNULL(ius.user_seeks, 0) AS seeks, ISNULL(ius.user_scans, 0) AS scans, ISNULL(ius.user_lookups, 0) AS lookups, ISNULL(ius.user_updates, 0) AS writes, CASE WHEN (ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0)) = 0 THEN 0.0 ELSE CAST(ISNULL(ius.user_updates, 0) AS FLOAT) / (ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0)) END AS write_to_read_ratio, (SELECT COUNT(*) FROM sys.indexes i2 WHERE i2.object_id = i.object_id AND i2.type > 0) AS total_indexes_on_table FROM sys.indexes i LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.type = 2 AND i.is_primary_key = 0 AND i.is_unique_constraint = 0 AND ISNULL(ius.user_updates, 0) > :min_writes AND (ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0)) < :max_reads ORDER BY write_to_read_ratio DESC"}	{"condition": "row_count > 0 AND write_to_read_ratio > :ratio_threshold", "description": "Indexes with high write overhead but negligible reads — created but never effectively used"}	{"max_reads": 10, "min_writes": 1000, "ratio_threshold": 100}	2026-02-23 20:18:31.390004
1852	sqlserver	query	Check if unused indexes overlap with active indexes on same table	{"sql": "WITH UnusedIdx AS (SELECT i.object_id, i.index_id, i.name AS index_name, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.type = 2 AND i.is_primary_key = 0 AND i.is_unique_constraint = 0 AND ISNULL(ius.user_updates, 0) > :min_writes AND (ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0)) < :max_reads GROUP BY i.object_id, i.index_id, i.name), ActiveIdx AS (SELECT i.object_id, i.index_id, i.name AS index_name, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.type IN (1, 2) AND (ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0)) > :active_min_reads GROUP BY i.object_id, i.index_id, i.name) SELECT OBJECT_NAME(u.object_id) AS table_name, u.index_name AS unused_index, a.index_name AS active_index, u.key_cols AS unused_keys, a.key_cols AS active_keys FROM UnusedIdx u JOIN ActiveIdx a ON u.object_id = a.object_id AND u.index_id != a.index_id WHERE a.key_cols LIKE u.key_cols + '%' OR u.key_cols LIKE a.key_cols + '%' ORDER BY OBJECT_NAME(u.object_id)"}	{"condition": "row_count > 0", "description": "Unused indexes overlap with active indexes on same table — premature optimization that duplicates existing coverage"}	{"max_reads": 10, "min_writes": 1000, "active_min_reads": 100}	2026-02-23 20:18:31.390005
1857	sqlserver	query	Find foreign key columns and their supporting indexes	{"sql": "SELECT OBJECT_NAME(fk.parent_object_id) AS child_table, fk.name AS fk_name, STRING_AGG(COL_NAME(fkc.parent_object_id, fkc.parent_column_id), ', ') WITHIN GROUP (ORDER BY fkc.constraint_column_id) AS fk_columns, (SELECT COUNT(*) FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.object_id = fk.parent_object_id AND i.type > 0 AND ic.column_id IN (SELECT fkc2.parent_column_id FROM sys.foreign_key_columns fkc2 WHERE fkc2.constraint_object_id = fk.object_id) AND ic.key_ordinal = 1) AS supporting_index_count FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fkc ON fk.object_id = fkc.constraint_object_id GROUP BY fk.parent_object_id, fk.object_id, fk.name HAVING (SELECT COUNT(*) FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.object_id = fk.parent_object_id AND i.type > 0 AND ic.column_id IN (SELECT fkc2.parent_column_id FROM sys.foreign_key_columns fkc2 WHERE fkc2.constraint_object_id = fk.object_id) AND ic.key_ordinal = 1) > 1 ORDER BY supporting_index_count DESC"}	{"condition": "row_count > 0", "description": "Foreign keys with multiple supporting indexes — at least one is likely redundant"}	null	2026-02-23 20:18:31.390006
1853	sqlserver	query	Find duplicate indexes with tool-generated naming patterns	{"sql": "WITH IndexFingerprint AS (SELECT i.object_id, i.index_id, i.name AS index_name, STRING_AGG(CAST(ic.column_id AS VARCHAR) + CASE WHEN ic.is_included_column = 1 THEN 'i' ELSE 'k' + CAST(ic.key_ordinal AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.is_included_column, ic.key_ordinal, ic.column_id) AS fingerprint FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type = 2 GROUP BY i.object_id, i.index_id, i.name) SELECT OBJECT_NAME(a.object_id) AS table_name, a.index_name AS index_a, b.index_name AS index_b, a.fingerprint, CASE WHEN a.index_name LIKE '%__repl%' OR b.index_name LIKE '%__repl%' THEN 'Replication-generated' WHEN a.index_name LIKE 'UQ_%' OR b.index_name LIKE 'UQ_%' THEN 'Possibly EF/ORM-generated' WHEN a.index_name LIKE '%_migration%' OR b.index_name LIKE '%_migration%' THEN 'Migration-generated' WHEN a.index_name LIKE '%[_][0-9]%' OR b.index_name LIKE '%[_][0-9]%' THEN 'Auto-numbered (tool-generated)' WHEN a.index_name LIKE 'IX[_]%[_]%[_]%' AND b.index_name LIKE 'IX[_]%[_]%[_]%' THEN 'Both follow tool convention' ELSE 'Manual' END AS origin_assessment FROM IndexFingerprint a JOIN IndexFingerprint b ON a.object_id = b.object_id AND a.index_id < b.index_id AND a.fingerprint = b.fingerprint ORDER BY OBJECT_NAME(a.object_id)"}	{"condition": "row_count > 0", "description": "Structurally duplicate indexes with tool-generated or migration-related naming patterns"}	null	2026-02-23 20:18:31.390006
1854	sqlserver	query	Check if replication or change tracking is active on affected tables	{"sql": "SELECT OBJECT_NAME(t.object_id) AS table_name, CASE WHEN EXISTS (SELECT 1 FROM sys.change_tracking_tables ct WHERE ct.object_id = t.object_id) THEN 1 ELSE 0 END AS has_change_tracking, t.is_replicated, t.is_merge_published, t.is_tracked_by_cdc, (SELECT COUNT(*) FROM sys.indexes i WHERE i.object_id = t.object_id AND i.type > 0) AS index_count FROM sys.tables t WHERE t.object_id IN (SELECT i.object_id FROM sys.indexes i WHERE i.type = 2 GROUP BY i.object_id HAVING COUNT(*) > :max_index_count) ORDER BY index_count DESC"}	{"condition": "row_count > 0 AND (is_replicated = 1 OR is_merge_published = 1 OR is_tracked_by_cdc = 1 OR has_change_tracking = 1)", "description": "Tables with duplicate indexes are involved in replication, CDC, or change tracking — tools likely created extra indexes"}	{"max_index_count": 5}	2026-02-23 20:18:31.390007
1855	sqlserver	query	Find non-unique indexes that are prefixes of unique indexes	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.is_unique, i.is_primary_key, i.is_unique_constraint, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols, COUNT(CASE WHEN ic.is_included_column = 0 THEN 1 END) AS key_count FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type IN (1, 2) GROUP BY i.object_id, i.index_id, i.name, i.is_unique, i.is_primary_key, i.is_unique_constraint) SELECT OBJECT_NAME(plain.object_id) AS table_name, plain.index_name AS redundant_index, plain.key_cols AS redundant_keys, plain.key_count AS redundant_key_count, uniq.index_name AS unique_index, uniq.key_cols AS unique_keys, uniq.key_count AS unique_key_count, CASE WHEN uniq.is_primary_key = 1 THEN 'Primary Key' WHEN uniq.is_unique_constraint = 1 THEN 'Unique Constraint' ELSE 'Unique Index' END AS unique_type FROM IndexKeys plain JOIN IndexKeys uniq ON plain.object_id = uniq.object_id AND plain.index_id != uniq.index_id AND uniq.is_unique = 1 AND plain.is_unique = 0 AND plain.key_count <= uniq.key_count AND uniq.key_cols LIKE plain.key_cols + '%' ORDER BY OBJECT_NAME(plain.object_id)"}	{"condition": "row_count > 0", "description": "Non-unique indexes found that are left-prefixes of unique indexes — redundant for seek operations"}	null	2026-02-23 20:18:31.390007
1856	sqlserver	query	Check usage of redundant prefix indexes vs unique indexes	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.is_unique, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols, COUNT(CASE WHEN ic.is_included_column = 0 THEN 1 END) AS key_count FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type IN (1, 2) GROUP BY i.object_id, i.index_id, i.name, i.is_unique), Redundant AS (SELECT plain.object_id, plain.index_id AS plain_id, uniq.index_id AS uniq_id, plain.index_name AS plain_name, uniq.index_name AS uniq_name FROM IndexKeys plain JOIN IndexKeys uniq ON plain.object_id = uniq.object_id AND plain.index_id != uniq.index_id AND uniq.is_unique = 1 AND plain.is_unique = 0 AND plain.key_count <= uniq.key_count AND uniq.key_cols LIKE plain.key_cols + '%') SELECT OBJECT_NAME(r.object_id) AS table_name, r.plain_name AS redundant_index, r.uniq_name AS unique_index, ISNULL(up.user_seeks, 0) + ISNULL(up.user_scans, 0) AS redundant_reads, ISNULL(up.user_updates, 0) AS redundant_writes, ISNULL(uu.user_seeks, 0) + ISNULL(uu.user_scans, 0) AS unique_reads FROM Redundant r LEFT JOIN sys.dm_db_index_usage_stats up ON r.object_id = up.object_id AND r.plain_id = up.index_id AND up.database_id = DB_ID() LEFT JOIN sys.dm_db_index_usage_stats uu ON r.object_id = uu.object_id AND r.uniq_id = uu.index_id AND uu.database_id = DB_ID() ORDER BY redundant_writes DESC"}	{"condition": "row_count > 0", "description": "Redundant prefix indexes confirmed with write overhead — the unique index already serves the same seek patterns"}	null	2026-02-23 20:18:31.390009
1868	sqlserver	query	Check SQL Agent job history for index maintenance jobs	{"sql": "SELECT j.name AS job_name, j.enabled, jh.run_date, jh.run_status, js.step_name FROM msdb.dbo.sysjobs j LEFT JOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id LEFT JOIN (SELECT job_id, MAX(run_date) AS run_date, run_status FROM msdb.dbo.sysjobhistory WHERE step_id = 0 GROUP BY job_id, run_status) jh ON j.job_id = jh.job_id WHERE (j.name LIKE '%index%' OR j.name LIKE '%maintenance%' OR j.name LIKE '%reindex%' OR j.name LIKE '%rebuild%' OR j.name LIKE '%reorganize%' OR js.command LIKE '%ALTER INDEX%' OR js.command LIKE '%REORGANIZE%' OR js.command LIKE '%REBUILD%' OR js.command LIKE '%UPDATE STATISTICS%')"}	{"condition": "row_count = 0 OR enabled = 0 OR run_date < CONVERT(INT, CONVERT(VARCHAR(8), DATEADD(DAY, -30, GETDATE()), 112))", "description": "No index maintenance jobs found, or they are disabled, or have not run in 30+ days"}	null	2026-02-23 20:18:31.390009
3488	postgresql	query	Check archive mode and command	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('archive_mode', 'archive_command') ORDER BY name"}	{"condition": "archive_mode = 'off' OR archive_command = '' OR archive_command = '/bin/true'", "description": "WAL archiving is disabled or using dummy command"}	\N	2026-02-25 00:28:52.405273
1858	sqlserver	query	List specific redundant indexes on foreign key columns	{"sql": "WITH FKCols AS (SELECT fk.parent_object_id AS table_id, fk.name AS fk_name, fkc.parent_column_id AS col_id, fkc.constraint_column_id AS ordinal FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fkc ON fk.object_id = fkc.constraint_object_id), FKIndexes AS (SELECT fk.table_id, fk.fk_name, i.index_id, i.name AS index_name, i.is_primary_key, i.is_unique_constraint, i.is_unique FROM FKCols fk JOIN sys.index_columns ic ON fk.table_id = ic.object_id AND fk.col_id = ic.column_id AND ic.key_ordinal = 1 JOIN sys.indexes i ON ic.object_id = i.object_id AND ic.index_id = i.index_id WHERE i.type > 0) SELECT OBJECT_NAME(fi.table_id) AS table_name, fi.fk_name, fi.index_name, fi.is_primary_key, fi.is_unique, ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0) AS reads, ISNULL(ius.user_updates, 0) AS writes, (SELECT COUNT(*) FROM FKIndexes fi2 WHERE fi2.table_id = fi.table_id AND fi2.fk_name = fi.fk_name) AS competing_indexes FROM FKIndexes fi LEFT JOIN sys.dm_db_index_usage_stats ius ON fi.table_id = ius.object_id AND fi.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE fi.table_id IN (SELECT fi3.table_id FROM FKIndexes fi3 GROUP BY fi3.table_id, fi3.fk_name HAVING COUNT(*) > 1) ORDER BY OBJECT_NAME(fi.table_id), fi.fk_name, reads DESC"}	{"condition": "row_count > 0 AND competing_indexes > 1", "description": "Multiple indexes serving the same foreign key — the lower-usage one is redundant"}	null	2026-02-23 20:18:31.39001
1871	sqlserver	query	Find tables with wide clustered index keys	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS clustered_index, SUM(c.max_length) AS clustered_key_width_bytes, COUNT(ic.column_id) AS key_column_count, STRING_AGG(c.name + ' (' + tp.name + ',' + CAST(c.max_length AS VARCHAR) + ')', ', ') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_columns FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.is_included_column = 0 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.system_type_id = tp.system_type_id JOIN sys.tables t ON i.object_id = t.object_id WHERE i.type = 1 GROUP BY t.schema_id, t.name, i.name HAVING SUM(c.max_length) > 16 ORDER BY clustered_key_width_bytes DESC"}	{"condition": "row_count > 0 AND clustered_key_width_bytes > 16", "description": "Tables with clustered index keys wider than 16 bytes — this width propagates to every nonclustered index"}	null	2026-02-23 20:18:31.390017
1859	sqlserver	query	Find constraint-created indexes that overlap with manual indexes	{"sql": "WITH IndexDetail AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.is_primary_key, i.is_unique_constraint, i.is_unique, i.type_desc, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type IN (1, 2) GROUP BY i.object_id, i.index_id, i.name, i.is_primary_key, i.is_unique_constraint, i.is_unique, i.type_desc) SELECT OBJECT_NAME(c.object_id) AS table_name, c.index_name AS constraint_index, c.type_desc AS constraint_type, CASE WHEN c.is_primary_key = 1 THEN 'PRIMARY KEY' ELSE 'UNIQUE CONSTRAINT' END AS constraint_kind, m.index_name AS manual_index, m.type_desc AS manual_type, c.key_cols FROM IndexDetail c JOIN IndexDetail m ON c.object_id = m.object_id AND c.index_id != m.index_id AND c.key_cols = m.key_cols WHERE (c.is_primary_key = 1 OR c.is_unique_constraint = 1) AND m.is_primary_key = 0 AND m.is_unique_constraint = 0 ORDER BY OBJECT_NAME(c.object_id)"}	{"condition": "row_count > 0", "description": "Manual indexes found that duplicate constraint-created indexes on same key columns"}	null	2026-02-23 20:18:31.390011
1930	sqlserver	query	Find head blockers and their impact	{"sql": "SELECT blocking.session_id AS blocker_session,\\n  blocking.status AS blocker_status,\\n  blocking.open_transaction_count,\\n  blocking.program_name, blocking.host_name,\\n  COUNT(blocked.session_id) AS blocked_session_count,\\n  MAX(blocked.wait_time) / 1000 AS max_wait_seconds\\nFROM sys.dm_exec_requests blocked\\nJOIN sys.dm_exec_sessions blocking\\n  ON blocked.blocking_session_id = blocking.session_id\\nWHERE blocked.blocking_session_id <> 0\\nGROUP BY blocking.session_id, blocking.status,\\n  blocking.open_transaction_count, blocking.program_name, blocking.host_name\\nORDER BY blocked_session_count DESC"}	{"condition": "row_count > 0 with blocked_session_count >= 1", "description": "One or more sessions are actively blocking others"}	null	2026-02-23 20:18:31.390053
1860	sqlserver	query	Check if manual duplicates have included columns justifying their existence	{"sql": "WITH IndexDetail AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.is_primary_key, i.is_unique_constraint, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols, COUNT(CASE WHEN ic.is_included_column = 1 THEN 1 END) AS incl_count FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type IN (1, 2) GROUP BY i.object_id, i.index_id, i.name, i.is_primary_key, i.is_unique_constraint), Overlap AS (SELECT c.object_id, c.index_id AS constr_id, m.index_id AS manual_id, c.index_name AS constr_name, m.index_name AS manual_name, m.incl_count AS manual_includes FROM IndexDetail c JOIN IndexDetail m ON c.object_id = m.object_id AND c.index_id != m.index_id AND c.key_cols = m.key_cols WHERE (c.is_primary_key = 1 OR c.is_unique_constraint = 1) AND m.is_primary_key = 0 AND m.is_unique_constraint = 0) SELECT OBJECT_NAME(o.object_id) AS table_name, o.constr_name, o.manual_name, o.manual_includes, ISNULL(um.user_seeks, 0) + ISNULL(um.user_scans, 0) AS manual_reads, ISNULL(um.user_updates, 0) AS manual_writes, ISNULL(uc.user_seeks, 0) + ISNULL(uc.user_scans, 0) AS constraint_reads FROM Overlap o LEFT JOIN sys.dm_db_index_usage_stats um ON o.object_id = um.object_id AND o.manual_id = um.index_id AND um.database_id = DB_ID() LEFT JOIN sys.dm_db_index_usage_stats uc ON o.object_id = uc.object_id AND o.constr_id = uc.index_id AND uc.database_id = DB_ID() ORDER BY manual_writes DESC"}	{"condition": "row_count > 0 AND manual_includes = 0", "description": "Manual indexes with no included columns duplicating constraint indexes — purely redundant"}	null	2026-02-23 20:18:31.390011
1861	sqlserver	query	Find nonclustered indexes duplicating the clustered index key columns	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.type, i.type_desc, i.is_unique, i.is_primary_key, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols, COUNT(CASE WHEN ic.is_included_column = 1 THEN 1 END) AS incl_count FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type IN (1, 2) GROUP BY i.object_id, i.index_id, i.name, i.type, i.type_desc, i.is_unique, i.is_primary_key) SELECT OBJECT_NAME(ci.object_id) AS table_name, ci.index_name AS clustered_index, ci.key_cols AS clustered_keys, ci.is_primary_key AS ci_is_pk, nci.index_name AS nonclustered_index, nci.key_cols AS nonclustered_keys, nci.is_unique AS nci_is_unique, nci.incl_count AS nci_includes FROM IndexKeys ci JOIN IndexKeys nci ON ci.object_id = nci.object_id AND ci.type = 1 AND nci.type = 2 AND ci.key_cols = nci.key_cols ORDER BY OBJECT_NAME(ci.object_id)"}	{"condition": "row_count > 0", "description": "Nonclustered indexes found that duplicate the clustered index key columns"}	null	2026-02-23 20:18:31.390012
1869	sqlserver	query	Find large indexes without compression enabled	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, p.data_compression_desc, SUM(ps.used_page_count) * 8 / 1024 AS size_mb, SUM(ps.row_count) AS row_count FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id JOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id JOIN sys.dm_db_partition_stats ps ON p.partition_id = ps.partition_id WHERE i.type > 0 AND p.data_compression_desc = 'NONE' GROUP BY t.schema_id, t.name, i.name, i.type_desc, p.data_compression_desc HAVING SUM(ps.used_page_count) * 8 / 1024 > 100 ORDER BY size_mb DESC"}	{"condition": "row_count > 0 AND size_mb > 100", "description": "Large indexes (>100 MB) with no compression — wasting storage and buffer pool memory"}	null	2026-02-23 20:18:31.390012
1922	sqlserver	query	Check for lock conversion waits (S to X upgrade conflicts)	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('LCK_M_U', 'LCK_M_X', 'LCK_M_IX')\\n  AND waiting_tasks_count > 100\\nORDER BY wait_time_ms DESC"}	{"condition": "high LCK_M_U or LCK_M_X waits indicating lock conversion contention", "description": "Elevated update/exclusive lock waits suggest read-then-update patterns blocking each other"}	null	2026-02-23 20:18:31.390013
3489	postgresql	query	Check last successful archive time	{"sql": "SELECT last_archived_time, now() - last_archived_time AS time_since_last_archive FROM pg_stat_archiver"}	{"condition": "time_since_last_archive > :stale_threshold::interval", "description": "No recent WAL archives — backup schedule may be disabled"}	{"stale_threshold": "24 hours"}	2026-02-25 00:28:52.405273
1870	sqlserver	query	Estimate compression savings for uncompressed indexes	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, SUM(ps.used_page_count) * 8 / 1024 AS current_size_mb, i.type_desc, (SELECT COUNT(*) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id) AS total_columns, (SELECT COUNT(*) FROM sys.index_columns ic JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.system_type_id = tp.system_type_id WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND tp.name IN ('varchar', 'nvarchar', 'char', 'nchar', 'varbinary')) AS compressible_cols FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id JOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id JOIN sys.dm_db_partition_stats ps ON p.partition_id = ps.partition_id WHERE i.type > 0 AND p.data_compression_desc = 'NONE' GROUP BY t.schema_id, t.name, i.name, i.type_desc, i.object_id, i.index_id HAVING SUM(ps.used_page_count) * 8 / 1024 > 100 ORDER BY current_size_mb DESC"}	{"condition": "compressible_cols > 0", "description": "Uncompressed indexes contain string/binary columns that benefit significantly from PAGE or ROW compression"}	null	2026-02-23 20:18:31.390017
1873	sqlserver	query	Find indexes with VARCHAR/NVARCHAR key columns	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, c.name AS column_name, tp.name AS data_type, c.max_length, ic.key_ordinal, ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0) AS reads, ISNULL(ius.user_updates, 0) AS writes FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.is_included_column = 0 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.system_type_id = tp.system_type_id JOIN sys.tables t ON i.object_id = t.object_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE tp.name IN ('varchar', 'nvarchar') AND c.max_length > 50 AND i.type > 0 ORDER BY c.max_length DESC, t.name"}	{"condition": "row_count > 0", "description": "Index key columns using VARCHAR/NVARCHAR with max_length > 50 bytes"}	null	2026-02-23 20:18:31.390019
3898	postgresql	log_scan	Check for authentication failure log entries	{"pattern": "password authentication failed|FATAL.*authentication|no pg_hba.conf entry"}	{"condition": "match_found", "description": "Authentication failures in logs confirm health check credential issues"}	\N	2026-02-25 00:28:52.405273
1862	sqlserver	query	Check usage and size overhead of duplicate nonclustered indexes	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.type, STRING_AGG(CASE WHEN ic.is_included_column = 0 THEN CAST(ic.column_id AS VARCHAR) END, ',') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_cols, COUNT(CASE WHEN ic.is_included_column = 1 THEN 1 END) AS incl_count FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id WHERE i.type IN (1, 2) GROUP BY i.object_id, i.index_id, i.name, i.type), DupNCI AS (SELECT ci.object_id, nci.index_id AS nci_id, ci.index_id AS ci_id, nci.index_name AS nci_name, ci.index_name AS ci_name, nci.incl_count FROM IndexKeys ci JOIN IndexKeys nci ON ci.object_id = nci.object_id AND ci.type = 1 AND nci.type = 2 AND ci.key_cols = nci.key_cols) SELECT OBJECT_NAME(d.object_id) AS table_name, d.ci_name AS clustered_index, d.nci_name AS nonclustered_index, d.incl_count AS nci_includes, ISNULL(un.user_seeks, 0) + ISNULL(un.user_scans, 0) AS nci_reads, ISNULL(un.user_updates, 0) AS nci_writes, ISNULL(uc.user_seeks, 0) + ISNULL(uc.user_scans, 0) AS ci_reads, (SELECT SUM(au.used_pages) * 8 / 1024 FROM sys.partitions p JOIN sys.allocation_units au ON p.partition_id = au.container_id WHERE p.object_id = d.object_id AND p.index_id = d.nci_id) AS nci_size_mb FROM DupNCI d LEFT JOIN sys.dm_db_index_usage_stats un ON d.object_id = un.object_id AND d.nci_id = un.index_id AND un.database_id = DB_ID() LEFT JOIN sys.dm_db_index_usage_stats uc ON d.object_id = uc.object_id AND d.ci_id = uc.index_id AND uc.database_id = DB_ID() ORDER BY nci_writes DESC"}	{"condition": "row_count > 0", "description": "Duplicate nonclustered indexes with measurable size and write overhead — confirmed redundancy"}	null	2026-02-23 20:18:31.390014
1863	sqlserver	query	Find indexes whose key columns are a prefix of another index on the same table	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, i.type_desc, i.is_unique, (SELECT STRING_AGG(CAST(ic.column_id AS VARCHAR), ',') WITHIN GROUP (ORDER BY ic.key_ordinal) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 0) AS key_cols, (SELECT COUNT(*) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 0) AS key_count, (SELECT COUNT(*) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 1) AS include_count FROM sys.indexes i WHERE i.type > 0 AND i.is_disabled = 0) SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, narrow.index_name AS narrow_index, narrow.key_cols AS narrow_keys, narrow.key_count AS narrow_key_count, wide.index_name AS covering_index, wide.key_cols AS covering_keys, wide.key_count AS covering_key_count FROM IndexKeys narrow JOIN IndexKeys wide ON narrow.object_id = wide.object_id AND narrow.index_id <> wide.index_id AND wide.key_cols LIKE narrow.key_cols + ',%' AND wide.key_count > narrow.key_count JOIN sys.tables t ON narrow.object_id = t.object_id WHERE narrow.is_unique = 0 ORDER BY t.name, narrow.index_name"}	{"condition": "row_count > 0", "description": "Indexes found where a narrower index is a strict prefix of a wider index on the same table"}	null	2026-02-23 20:18:31.390014
1864	sqlserver	query	Verify the narrower index has low or zero usage relative to the covering index	{"sql": "WITH IndexKeys AS (SELECT i.object_id, i.index_id, i.name AS index_name, (SELECT STRING_AGG(CAST(ic.column_id AS VARCHAR), ',') WITHIN GROUP (ORDER BY ic.key_ordinal) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 0) AS key_cols FROM sys.indexes i WHERE i.type > 0 AND i.is_disabled = 0 AND i.is_unique = 0) SELECT OBJECT_NAME(narrow.object_id) AS table_name, narrow.index_name AS duplicate_index, ISNULL(nius.user_seeks, 0) + ISNULL(nius.user_scans, 0) AS narrow_reads, ISNULL(nius.user_updates, 0) AS narrow_writes, wide.index_name AS covering_index, ISNULL(wius.user_seeks, 0) + ISNULL(wius.user_scans, 0) AS covering_reads, (SELECT SUM(ps.used_page_count) * 8 / 1024 FROM sys.dm_db_partition_stats ps WHERE ps.object_id = narrow.object_id AND ps.index_id = narrow.index_id) AS duplicate_size_mb FROM IndexKeys narrow JOIN IndexKeys wide ON narrow.object_id = wide.object_id AND narrow.index_id <> wide.index_id AND wide.key_cols LIKE narrow.key_cols + ',%' LEFT JOIN sys.dm_db_index_usage_stats nius ON narrow.object_id = nius.object_id AND narrow.index_id = nius.index_id AND nius.database_id = DB_ID() LEFT JOIN sys.dm_db_index_usage_stats wius ON wide.object_id = wius.object_id AND wide.index_id = wius.index_id AND wius.database_id = DB_ID() WHERE ISNULL(nius.user_seeks, 0) + ISNULL(nius.user_scans, 0) < ISNULL(wius.user_seeks, 0) + ISNULL(wius.user_scans, 0) ORDER BY narrow_writes DESC"}	{"condition": "row_count > 0 AND narrow_reads < covering_reads", "description": "Narrower index has fewer reads than the covering index and incurs write overhead — it is redundant"}	null	2026-02-23 20:18:31.390015
1865	sqlserver	query	Find indexes with high write-to-read ratio indicating low usage ignored	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, ISNULL(ius.user_seeks, 0) AS seeks, ISNULL(ius.user_scans, 0) AS scans, ISNULL(ius.user_lookups, 0) AS lookups, ISNULL(ius.user_updates, 0) AS updates, CASE WHEN ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0) > 0 THEN CAST(ISNULL(ius.user_updates, 0) AS FLOAT) / (ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0)) ELSE 999999 END AS write_to_read_ratio, (SELECT SUM(ps.used_page_count) * 8 / 1024 FROM sys.dm_db_partition_stats ps WHERE ps.object_id = i.object_id AND ps.index_id = i.index_id) AS size_mb FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id LEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID() WHERE i.type > 0 AND i.is_primary_key = 0 AND i.is_unique_constraint = 0 AND i.is_disabled = 0 AND ISNULL(ius.user_updates, 0) > 1000 AND (ISNULL(ius.user_seeks, 0) + ISNULL(ius.user_scans, 0)) < ISNULL(ius.user_updates, 0) * 0.01 ORDER BY write_to_read_ratio DESC"}	{"condition": "row_count > 0", "description": "Indexes with writes exceeding reads by 100:1 or more — low usage statistics being ignored"}	null	2026-02-23 20:18:31.390015
1867	sqlserver	query	Check for stale statistics on fragmented indexes	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, s.name AS stats_name, sp.last_updated, sp.rows, sp.rows_sampled, sp.modification_counter, CASE WHEN sp.rows > 0 THEN CAST(sp.modification_counter AS FLOAT) / sp.rows * 100 ELSE 0 END AS pct_modified FROM sys.stats s JOIN sys.tables t ON s.object_id = t.object_id CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE sp.modification_counter > 0 AND (sp.last_updated < DATEADD(DAY, -7, GETDATE()) OR (sp.rows > 0 AND CAST(sp.modification_counter AS FLOAT) / sp.rows > 0.2)) ORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0", "description": "Statistics not updated in over 7 days or with more than 20% row modifications — no maintenance policy in effect"}	null	2026-02-23 20:18:31.390016
3434	postgresql	log_scan	Scan for forced shutdown signals	{"pattern": "received.*shutdown request|received.*signal.*SIGTERM|received.*signal.*SIGQUIT|received.*signal.*SIGKILL|fast shutdown|immediate shutdown|smart shutdown", "description": "PostgreSQL receiving shutdown signals from external sources"}	{"condition": "pattern_found", "description": "Forced shutdown from external signal detected"}	\N	2026-02-25 00:28:52.405273
1874	sqlserver	query	Check fragmentation on indexes with variable-length keys	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, ips.avg_fragmentation_in_percent, ips.page_count, ips.avg_page_space_used_in_percent, ips.record_count FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'SAMPLED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id JOIN sys.tables t ON i.object_id = t.object_id WHERE i.type > 0 AND ips.page_count > 100 AND ips.avg_fragmentation_in_percent > 20 AND EXISTS (SELECT 1 FROM sys.index_columns ic JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.system_type_id = tp.system_type_id WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 0 AND tp.name IN ('varchar', 'nvarchar') AND c.max_length > 50) ORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "avg_fragmentation_in_percent > 20", "description": "Indexes with variable-length keys showing elevated fragmentation from page splits"}	null	2026-02-23 20:18:31.390019
1875	sqlserver	query	Find composite indexes with total key width exceeding threshold	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, COUNT(ic.column_id) AS key_column_count, SUM(c.max_length) AS total_key_width_bytes, STRING_AGG(c.name + ' (' + tp.name + ',' + CAST(c.max_length AS VARCHAR) + ')', ', ') WITHIN GROUP (ORDER BY ic.key_ordinal) AS key_columns, (SELECT SUM(ps.used_page_count) * 8 / 1024 FROM sys.dm_db_partition_stats ps WHERE ps.object_id = i.object_id AND ps.index_id = i.index_id) AS size_mb FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.is_included_column = 0 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.system_type_id = tp.system_type_id JOIN sys.tables t ON i.object_id = t.object_id WHERE i.type > 0 GROUP BY t.schema_id, t.name, i.name, i.type_desc, i.object_id, i.index_id HAVING COUNT(ic.column_id) >= 3 AND SUM(c.max_length) > 200 ORDER BY total_key_width_bytes DESC"}	{"condition": "row_count > 0 AND total_key_width_bytes > 200", "description": "Composite indexes with 3+ key columns and total key width exceeding 200 bytes"}	null	2026-02-23 20:18:31.39002
3362	postgresql	query	Group long queries by application	{"sql": "SELECT application_name, client_addr, count(*) AS long_query_count FROM pg_stat_activity WHERE state = 'active' AND backend_type = 'client backend' AND now() - query_start > :threshold_interval::interval GROUP BY application_name, client_addr HAVING count(*) > :min_count ORDER BY long_query_count DESC"}	{"condition": "row_count > 0", "description": "Multiple long queries from same application confirms systematic issue"}	{"min_count": 3, "threshold_interval": "60 seconds"}	2026-02-25 00:28:52.405273
2170	sqlserver	query	Check for multi-column equality predicates without multi-column statistics	{"sql": "SELECT\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.max_grant_kb,\\n  qs.last_grant_kb,\\n  qs.max_used_grant_kb,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.max_grant_kb > 51200\\n  AND qs.max_used_grant_kb < qs.max_grant_kb * 0.10\\n  AND t.text LIKE '%WHERE%AND%=%AND%=%'\\nORDER BY qs.max_grant_kb DESC"}	{"condition": "row_count > 0", "description": "Queries with multiple equality predicates and large unused grants suggest correlated predicate overestimation"}	null	2026-02-23 20:18:31.39021
1876	sqlserver	query	Check if wide composite indexes are approaching the 900-byte key limit	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, SUM(c.max_length) AS total_key_width_bytes, CAST(SUM(c.max_length) AS FLOAT) / 900 * 100 AS pct_of_900_limit, COUNT(ic.column_id) AS key_count, ips.avg_fragmentation_in_percent, ips.page_count FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.is_included_column = 0 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.tables t ON i.object_id = t.object_id LEFT JOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips ON i.object_id = ips.object_id AND i.index_id = ips.index_id WHERE i.type > 0 GROUP BY t.schema_id, t.name, i.name, i.object_id, i.index_id, ips.avg_fragmentation_in_percent, ips.page_count HAVING SUM(c.max_length) > 200 AND COUNT(ic.column_id) >= 3 ORDER BY total_key_width_bytes DESC"}	{"condition": "pct_of_900_limit > 30", "description": "Wide composite indexes consuming significant portion of the 900-byte key limit — I/O overhead is high"}	null	2026-02-23 20:18:31.39002
1877	sqlserver	query	Find indexes with excessive INCLUDE columns	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, (SELECT COUNT(*) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 0) AS key_column_count, (SELECT COUNT(*) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 1) AS include_column_count, (SELECT SUM(c.max_length) FROM sys.index_columns ic JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 1) AS include_width_bytes, (SELECT SUM(ps.used_page_count) * 8 / 1024 FROM sys.dm_db_partition_stats ps WHERE ps.object_id = i.object_id AND ps.index_id = i.index_id) AS index_size_mb FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id WHERE i.type = 2 AND (SELECT COUNT(*) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 1) > 5 ORDER BY include_column_count DESC"}	{"condition": "include_column_count > 5", "description": "Nonclustered indexes with more than 5 INCLUDE columns — approaching table-width coverage"}	null	2026-02-23 20:18:31.390021
1419	sqlserver	query	Check if Optimize for Ad Hoc Workloads is disabled	{"sql": "SELECT name, value_in_use,\\n  CASE WHEN value_in_use = 0 THEN 'DISABLED - full plans cached for every ad-hoc query'\\n       ELSE 'ENABLED - only plan stubs cached on first execution' END AS status\\nFROM sys.configurations\\nWHERE name = 'optimize for ad hoc workloads'"}	{"condition": "value_in_use = 0", "description": "Optimize for Ad Hoc Workloads is disabled, meaning every unique ad-hoc query stores a full compiled plan in cache"}	null	2026-02-23 20:18:31.390937
1884	sqlserver	query	Find indexes with nullable key columns	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, c.name AS nullable_key_column, tp.name AS data_type, c.max_length, ic.key_ordinal, (SELECT COUNT(*) FROM sys.index_columns ic2 WHERE ic2.object_id = i.object_id AND ic2.index_id = i.index_id AND ic2.is_included_column = 0) AS total_key_columns, (SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = i.object_id AND p.index_id <= 1) AS table_rows FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.is_included_column = 0 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.system_type_id = tp.system_type_id JOIN sys.tables t ON i.object_id = t.object_id WHERE i.type > 0 AND c.is_nullable = 1 ORDER BY t.name, i.name, ic.key_ordinal"}	{"condition": "row_count > 0", "description": "Indexes with nullable key columns found"}	null	2026-02-23 20:18:31.390026
1878	sqlserver	query	Compare covering index size to the clustered index to check if it approaches a full table copy	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS nc_index_name, nc_stats.nc_size_mb, ci_stats.ci_size_mb, CASE WHEN ci_stats.ci_size_mb > 0 THEN CAST(nc_stats.nc_size_mb AS FLOAT) / ci_stats.ci_size_mb * 100 ELSE 0 END AS pct_of_table_size, (SELECT COUNT(*) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 1) AS include_cols, (SELECT COUNT(*) FROM sys.columns c WHERE c.object_id = i.object_id) AS total_table_cols FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id CROSS APPLY (SELECT SUM(ps.used_page_count) * 8 / 1024 AS nc_size_mb FROM sys.dm_db_partition_stats ps WHERE ps.object_id = i.object_id AND ps.index_id = i.index_id) nc_stats CROSS APPLY (SELECT SUM(ps.used_page_count) * 8 / 1024 AS ci_size_mb FROM sys.dm_db_partition_stats ps WHERE ps.object_id = i.object_id AND ps.index_id <= 1) ci_stats WHERE i.type = 2 AND (SELECT COUNT(*) FROM sys.index_columns ic WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 1) > 5 ORDER BY pct_of_table_size DESC"}	{"condition": "pct_of_table_size > 50", "description": "Covering index is more than 50% the size of the table — excessive INCLUDE columns creating near-duplicate storage"}	null	2026-02-23 20:18:31.390022
1879	sqlserver	query	Find indexes with wide, low-selectivity leading columns	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, c.name AS leading_column, tp.name AS data_type, c.max_length, (SELECT TOP 1 sp.rows FROM sys.stats s CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE s.object_id = i.object_id AND s.name = i.name) AS total_rows, (SELECT TOP 1 sh.range_high_key FROM sys.stats s CROSS APPLY sys.dm_db_stats_histogram(s.object_id, s.stats_id) sh WHERE s.object_id = i.object_id AND s.name = i.name ORDER BY sh.step_number DESC) AS max_histogram_key FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 AND ic.is_included_column = 0 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.types tp ON c.system_type_id = tp.system_type_id JOIN sys.tables t ON i.object_id = t.object_id WHERE i.type > 0 AND c.max_length > 50 AND tp.name IN ('varchar', 'nvarchar', 'char', 'nchar') ORDER BY c.max_length DESC"}	{"condition": "row_count > 0", "description": "Indexes with wide string columns (>50 bytes) in leading key position"}	null	2026-02-23 20:18:31.390022
1906	sqlserver	query	Check plan cache for queries using lock hints	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE t.text LIKE '%UPDLOCK%'\\n  OR t.text LIKE '%XLOCK%'\\n  OR t.text LIKE '%HOLDLOCK%'\\n  OR t.text LIKE '%TABLOCK%'\\nORDER BY qs.execution_count DESC"}	{"condition": "row_count > 0", "description": "Active queries in plan cache using explicit lock hints — potential deadlock contributors"}	null	2026-02-23 20:18:31.390023
1881	sqlserver	query	Check if computed column index keys are excessively wide	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, c.name AS computed_column, cc.definition AS expression, c.max_length AS result_width_bytes, tp.name AS result_type, (SELECT SUM(ps.used_page_count) * 8 / 1024 FROM sys.dm_db_partition_stats ps WHERE ps.object_id = i.object_id AND ps.index_id = i.index_id) AS index_size_mb FROM sys.indexes i JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.is_included_column = 0 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.computed_columns cc ON c.object_id = cc.object_id AND c.column_id = cc.column_id JOIN sys.types tp ON c.system_type_id = tp.system_type_id JOIN sys.tables t ON i.object_id = t.object_id WHERE i.type > 0 AND c.max_length > 100 ORDER BY c.max_length DESC"}	{"condition": "result_width_bytes > 100", "description": "Computed column indexes with result type wider than 100 bytes — expression outputs long values that inflate index size"}	null	2026-02-23 20:18:31.390024
