1900	sqlserver	query	Check current table-level locks and blocked sessions from escalation	{"sql": "SELECT l.resource_type, OBJECT_NAME(l.resource_associated_entity_id) AS locked_table, l.request_mode, l.request_status, l.request_session_id, s.login_name, s.program_name, (SELECT COUNT(*) FROM sys.dm_exec_requests er WHERE er.blocking_session_id = l.request_session_id) AS sessions_blocked, (SELECT TOP 1 SUBSTRING(st.text, 1, 200) FROM sys.dm_exec_connections c CROSS APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) st WHERE c.session_id = l.request_session_id) AS last_sql FROM sys.dm_tran_locks l JOIN sys.dm_exec_sessions s ON l.request_session_id = s.session_id WHERE l.resource_type = 'OBJECT' AND l.request_mode IN ('X', 'IX', 'SIX', 'Sch-M') AND l.request_status = 'GRANT' AND l.resource_database_id = DB_ID() ORDER BY sessions_blocked DESC"}	{"condition": "row_count > 0 AND sessions_blocked > 0", "description": "Table-level exclusive or intent-exclusive locks currently blocking other sessions — lock escalation impact"}	null	2026-02-23 20:18:31.390037
1893	sqlserver	query	Check page split rates on wide-key indexes with full fill factor	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.fill_factor, ios.leaf_allocation_count AS page_splits, ios.leaf_insert_count AS inserts, CASE WHEN ios.leaf_insert_count > 0 THEN CAST(ios.leaf_allocation_count AS FLOAT) / ios.leaf_insert_count * 100 ELSE 0 END AS split_pct, ips.avg_fragmentation_in_percent, ips.page_count FROM sys.indexes i JOIN sys.tables t ON i.object_id = t.object_id JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios ON i.object_id = ios.object_id AND i.index_id = ios.index_id LEFT JOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips ON i.object_id = ips.object_id AND i.index_id = ips.index_id WHERE i.type > 0 AND (i.fill_factor = 0 OR i.fill_factor = 100) AND ios.leaf_allocation_count > 100 AND EXISTS (SELECT 1 FROM sys.index_columns ic JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id WHERE ic.object_id = i.object_id AND ic.index_id = i.index_id AND ic.is_included_column = 0 GROUP BY ic.object_id, ic.index_id HAVING SUM(c.max_length) > 100) ORDER BY ios.leaf_allocation_count DESC"}	{"condition": "page_splits > 100 AND split_pct > 1", "description": "Wide-key indexes experiencing significant page splits due to 100% fill factor — reducing fill factor would leave room for inserts"}	null	2026-02-23 20:18:31.390033
1894	sqlserver	query	Extract recent deadlock events from system_health extended event session	{"sql": "SELECT TOP 20 xdr.value('@timestamp', 'datetime2') AS deadlock_time, xdr.query('(data/value/deadlock)') AS deadlock_graph FROM (SELECT CAST(target_data AS XML) AS target_data FROM sys.dm_xe_session_targets st JOIN sys.dm_xe_sessions s ON s.address = st.event_session_address WHERE s.name = 'system_health' AND st.target_name = 'ring_buffer') AS data CROSS APPLY target_data.nodes('RingBufferTarget/event[@name=\\"xml_deadlock_report\\"]') AS xed(xdr) ORDER BY xdr.value('@timestamp', 'datetime2') DESC"}	{"condition": "row_count > 0", "description": "Deadlock events found in system_health ring buffer"}	null	2026-02-23 20:18:31.390033
1895	sqlserver	query	Analyze deadlock wait resource patterns for lock ordering issues	{"sql": "SELECT TOP 30 xdr.value('@timestamp', 'datetime2') AS deadlock_time, process.value('(@id)', 'varchar(50)') AS process_id, process.value('(inputbuf)[1]', 'varchar(max)') AS input_buffer, resource.value('(@objectname)', 'varchar(256)') AS locked_object, resource.value('(@lockMode)', 'varchar(10)') AS lock_mode, resource.value('(@dbid)', 'int') AS database_id FROM (SELECT CAST(target_data AS XML) AS target_data FROM sys.dm_xe_session_targets st JOIN sys.dm_xe_sessions s ON s.address = st.event_session_address WHERE s.name = 'system_health' AND st.target_name = 'ring_buffer') AS data CROSS APPLY target_data.nodes('RingBufferTarget/event[@name=\\"xml_deadlock_report\\"]') AS xed(xdr) CROSS APPLY xdr.nodes('data/value/deadlock/process-list/process') AS procs(process) CROSS APPLY xdr.nodes('data/value/deadlock/resource-list/*') AS resources(resource) ORDER BY deadlock_time DESC"}	{"condition": "multiple processes accessing same objects in different order", "description": "Deadlock graph shows processes acquiring locks on the same objects in different orders — classic lock ordering violation"}	null	2026-02-23 20:18:31.390034
1896	sqlserver	query	Check deadlock frequency and recurring object patterns	{"sql": "SELECT DB_NAME(er.database_id) AS database_name, COUNT(*) AS deadlock_count_recent, ws.wait_time_ms AS total_lock_wait_ms, ws.waiting_tasks_count AS lock_waits FROM sys.dm_exec_requests er CROSS JOIN (SELECT wait_time_ms, waiting_tasks_count FROM sys.dm_os_wait_stats WHERE wait_type = 'LCK_M_X') ws WHERE er.wait_type LIKE 'LCK_M_%' GROUP BY er.database_id, ws.wait_time_ms, ws.waiting_tasks_count UNION ALL SELECT 'SYSTEM' AS database_name, (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE counter_name = 'Number of Deadlocks/sec' AND instance_name = '_Total') AS deadlock_count_recent, (SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type = 'LCK_M_X') AS total_lock_wait_ms, (SELECT waiting_tasks_count FROM sys.dm_os_wait_stats WHERE wait_type = 'LCK_M_X') AS lock_waits"}	{"condition": "deadlock_count_recent > 0", "description": "Active deadlock occurrences and lock wait statistics confirm ongoing lock ordering issues"}	null	2026-02-23 20:18:31.390035
1897	sqlserver	query	Find long-running open transactions with locks held	{"sql": "SELECT s.session_id, s.login_name, s.host_name, s.program_name, t.transaction_id, t.name AS transaction_name, tat.transaction_begin_time, DATEDIFF(SECOND, tat.transaction_begin_time, GETDATE()) AS duration_seconds, (SELECT COUNT(*) FROM sys.dm_tran_locks l WHERE l.request_session_id = s.session_id AND l.request_status = 'GRANT') AS locks_held, (SELECT COUNT(DISTINCT l.resource_associated_entity_id) FROM sys.dm_tran_locks l WHERE l.request_session_id = s.session_id AND l.request_status = 'GRANT' AND l.resource_type IN ('KEY', 'RID', 'PAGE', 'OBJECT')) AS objects_locked, (SELECT TOP 1 SUBSTRING(st.text, (er.statement_start_offset/2)+1, ((CASE er.statement_end_offset WHEN -1 THEN DATALENGTH(st.text) ELSE er.statement_end_offset END - er.statement_start_offset)/2)+1) FROM sys.dm_exec_requests er CROSS APPLY sys.dm_exec_sql_text(er.sql_handle) st WHERE er.session_id = s.session_id) AS current_statement FROM sys.dm_exec_sessions s JOIN sys.dm_tran_session_transactions tst ON s.session_id = tst.session_id JOIN sys.dm_tran_active_transactions tat ON tst.transaction_id = tat.transaction_id JOIN sys.dm_tran_active_transactions t ON tst.transaction_id = t.transaction_id WHERE DATEDIFF(SECOND, tat.transaction_begin_time, GETDATE()) > 60 AND tat.transaction_type = 1 ORDER BY duration_seconds DESC"}	{"condition": "row_count > 0 AND duration_seconds > 60", "description": "Transactions open for more than 60 seconds holding locks"}	null	2026-02-23 20:18:31.390035
1898	sqlserver	query	Check if long-running transactions are blocking other sessions	{"sql": "SELECT blocking.session_id AS blocking_session_id, blocking.login_name AS blocking_login, DATEDIFF(SECOND, tat.transaction_begin_time, GETDATE()) AS blocking_txn_duration_sec, COUNT(DISTINCT blocked.session_id) AS blocked_session_count, MAX(DATEDIFF(SECOND, blocked.wait_time / 1000, GETDATE())) AS max_blocked_wait_sec, STRING_AGG(CAST(blocked.session_id AS VARCHAR), ', ') AS blocked_sessions FROM sys.dm_exec_requests blocked JOIN sys.dm_exec_sessions blocking ON blocked.blocking_session_id = blocking.session_id JOIN sys.dm_tran_session_transactions tst ON blocking.session_id = tst.session_id JOIN sys.dm_tran_active_transactions tat ON tst.transaction_id = tat.transaction_id WHERE blocked.blocking_session_id > 0 AND DATEDIFF(SECOND, tat.transaction_begin_time, GETDATE()) > 60 GROUP BY blocking.session_id, blocking.login_name, tat.transaction_begin_time ORDER BY blocked_session_count DESC"}	{"condition": "blocked_session_count > 0", "description": "Long-running transactions are actively blocking other sessions — holding locks too long"}	null	2026-02-23 20:18:31.390036
4304	postgresql	query	Check pg_stat_statements for slow job queries	{"sql": "SELECT queryid, calls, mean_exec_time, stddev_exec_time, rows, shared_blks_hit, shared_blks_read, temp_blks_read, temp_blks_written FROM pg_stat_statements WHERE mean_exec_time > :threshold_ms ORDER BY mean_exec_time DESC LIMIT 10"}	{"condition": "row_count > 0 AND mean_exec_time > :threshold_ms", "description": "Slow queries identified; likely from poor join order or cardinality estimates"}	{"threshold_ms": 10000}	2026-02-25 00:28:52.405273
1902	sqlserver	query	Check for lock waits on tables involved in FK relationships	{"sql": "SELECT OBJECT_NAME(ios.object_id) AS table_name, ios.row_lock_wait_count, ios.row_lock_wait_in_ms, ios.page_lock_wait_count, ios.page_lock_wait_in_ms, CASE WHEN ios.row_lock_wait_count > 0 THEN ios.row_lock_wait_in_ms / ios.row_lock_wait_count ELSE 0 END AS avg_row_lock_wait_ms FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios WHERE ios.index_id <= 1 AND (ios.row_lock_wait_count > 100 OR ios.page_lock_wait_count > 100) AND ios.object_id IN (SELECT fk.parent_object_id FROM sys.foreign_keys fk UNION SELECT fk.referenced_object_id FROM sys.foreign_keys fk) ORDER BY ios.row_lock_wait_in_ms DESC"}	{"condition": "row_lock_wait_count > 100 OR page_lock_wait_count > 100", "description": "Significant lock wait activity on FK-related tables — constraint validation causing blocking"}	null	2026-02-23 20:18:31.390038
