1939	sqlserver	query	Check for active table-level locks and their blocking impact	{"sql": "SELECT OBJECT_NAME(l.resource_associated_entity_id) AS table_name,\\n  l.request_mode, l.request_session_id,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests r\\n   WHERE r.blocking_session_id = l.request_session_id) AS blocked_count\\nFROM sys.dm_tran_locks l\\nWHERE l.resource_type = 'OBJECT'\\n  AND l.request_mode IN ('X', 'SIX', 'IX')\\n  AND l.request_status = 'GRANT'\\n  AND l.resource_database_id = DB_ID()\\nORDER BY blocked_count DESC"}	{"condition": "table-level exclusive locks with blocked sessions", "description": "Escalated table locks actively blocking concurrent operations"}	null	2026-02-23 20:18:31.390058
1940	sqlserver	query	Find sleeping sessions with open transactions and held locks	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.login_time, s.last_request_end_time,\\n  DATEDIFF(SECOND, s.last_request_end_time, GETDATE()) AS idle_seconds,\\n  s.open_transaction_count,\\n  (SELECT COUNT(*) FROM sys.dm_tran_locks l\\n   WHERE l.request_session_id = s.session_id\\n     AND l.request_status = 'GRANT') AS held_lock_count\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(SECOND, s.last_request_end_time, GETDATE()) > 30\\nORDER BY idle_seconds DESC"}	{"condition": "sleeping sessions with open transactions idle > 30 seconds holding locks", "description": "Idle-in-transaction sessions holding locks that could block others"}	null	2026-02-23 20:18:31.390058
