1945	sqlserver	query	Identify tables with identity columns and high insert rates	{"sql": "SELECT OBJECT_NAME(ios.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ios.leaf_insert_count,\\n  ios.page_latch_wait_count,\\n  ios.page_latch_wait_in_ms,\\n  ic.name AS identity_column\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nLEFT JOIN sys.identity_columns ic ON ios.object_id = ic.object_id\\nWHERE ios.page_latch_wait_count > 100\\n  AND ios.leaf_insert_count > 10000\\n  AND i.index_id <= 1\\nORDER BY ios.page_latch_wait_count DESC"}	{"condition": "tables with identity columns showing high insert counts and page latch waits", "description": "Sequential insert pattern on identity-based clustered index causing last-page hot spot"}	null	2026-02-23 20:18:31.390061
1946	sqlserver	query	Check active page latch waits on specific resources	{"sql": "SELECT wt.session_id, wt.wait_type,\\n  wt.wait_duration_ms, wt.resource_description,\\n  r.command,\\n  SUBSTRING(t.text, (r.statement_start_offset/2)+1, 100) AS query_fragment\\nFROM sys.dm_os_waiting_tasks wt\\nJOIN sys.dm_exec_requests r ON wt.session_id = r.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE wt.wait_type LIKE 'PAGELATCH%'\\nORDER BY wt.wait_duration_ms DESC"}	{"condition": "multiple sessions waiting on PAGELATCH for the same page resource", "description": "Active last-page insert contention — multiple INSERT sessions waiting on the same page"}	null	2026-02-23 20:18:31.390061
1947	sqlserver	query	Check for schema lock waits	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('LCK_M_SCH_S', 'LCK_M_SCH_M')\\n  AND waiting_tasks_count > 10\\nORDER BY wait_time_ms DESC"}	{"condition": "elevated LCK_M_SCH_S or LCK_M_SCH_M waits", "description": "Schema lock contention — DDL vs DML or DDL vs DDL conflicts"}	null	2026-02-23 20:18:31.390062
