4307	postgresql	query	Check pg_cron job schedule definitions for business-hour overlap	{"sql": "SELECT jobid, schedule, command, nodename, active FROM cron.job WHERE active = true AND (schedule LIKE '%8 %' OR schedule LIKE '%9 %' OR schedule LIKE '%10 %' OR schedule LIKE '%11 %' OR schedule LIKE '%12 %' OR schedule LIKE '%13 %' OR schedule LIKE '%14 %' OR schedule LIKE '%15 %' OR schedule LIKE '%16 %' OR schedule LIKE '%17 %')"}	{"condition": "row_count > 0", "description": "Jobs are scheduled to start during typical business hours (8-17)"}	\N	2026-02-25 00:28:52.405273
1948	sqlserver	query	Find active schema lock conflicts	{"sql": "SELECT l.request_session_id, l.resource_type,\\n  l.request_mode, l.request_status,\\n  OBJECT_NAME(l.resource_associated_entity_id) AS object_name,\\n  r.command, r.wait_type,\\n  SUBSTRING(t.text, (r.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_tran_locks l\\nJOIN sys.dm_exec_requests r ON l.request_session_id = r.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE l.request_mode IN ('Sch-S', 'Sch-M')\\n  AND (l.request_status = 'WAIT' OR EXISTS (\\n    SELECT 1 FROM sys.dm_tran_locks l2\\n    WHERE l2.resource_associated_entity_id = l.resource_associated_entity_id\\n      AND l2.request_session_id <> l.request_session_id\\n      AND l2.request_mode IN ('Sch-S', 'Sch-M')\\n      AND l2.request_status = 'WAIT'\\n  ))\\nORDER BY l.request_status DESC"}	{"condition": "Sch-M lock waiting or blocking Sch-S holders", "description": "Schema modification lock (DDL) blocked by or blocking schema stability locks (DML)"}	null	2026-02-23 20:18:31.390062
1949	sqlserver	query	Check for online index operations or statistics updates	{"sql": "SELECT r.session_id, r.command, r.status,\\n  r.total_elapsed_time / 1000 AS elapsed_sec,\\n  r.percent_complete,\\n  SUBSTRING(t.text, (r.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE r.command IN ('ALTER INDEX', 'CREATE INDEX', 'ALTER TABLE',\\n  'UPDATE STATISTICS', 'DBCC')\\nORDER BY r.total_elapsed_time DESC"}	{"condition": "active DDL operations that acquire Sch-M locks", "description": "Index rebuilds, ALTER TABLE, or statistics updates causing schema lock contention"}	null	2026-02-23 20:18:31.390063
1950	sqlserver	query	Find long-running transactions with high lock counts	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  t.transaction_id,\\n  DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS txn_duration_sec,\\n  (SELECT COUNT(*) FROM sys.dm_tran_locks l\\n   WHERE l.request_session_id = s.session_id\\n     AND l.request_status = 'GRANT') AS held_locks,\\n  s.cpu_time, s.logical_reads, s.total_elapsed_time / 1000 AS session_elapsed_sec\\nFROM sys.dm_tran_active_transactions t\\nJOIN sys.dm_tran_session_transactions st ON st.transaction_id = t.transaction_id\\nJOIN sys.dm_exec_sessions s ON s.session_id = st.session_id\\nWHERE s.is_user_process = 1\\n  AND DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) > 30\\nORDER BY held_locks DESC"}	{"condition": "transactions running > 30 seconds with many held locks", "description": "Long-duration transactions holding locks — expensive operations extend lock window"}	null	2026-02-23 20:18:31.390064
1951	sqlserver	query	Check if these transactions are causing blocking	{"sql": "SELECT r.blocking_session_id AS long_txn_session,\\n  COUNT(r.session_id) AS blocked_count,\\n  MAX(r.wait_time) / 1000 AS max_wait_seconds,\\n  STRING_AGG(CAST(r.session_id AS VARCHAR), ', ') AS blocked_sessions\\nFROM sys.dm_exec_requests r\\nWHERE r.blocking_session_id IN (\\n  SELECT s.session_id\\n  FROM sys.dm_tran_active_transactions t\\n  JOIN sys.dm_tran_session_transactions st ON st.transaction_id = t.transaction_id\\n  JOIN sys.dm_exec_sessions s ON s.session_id = st.session_id\\n  WHERE DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) > 30\\n    AND s.is_user_process = 1\\n)\\nGROUP BY r.blocking_session_id\\nORDER BY blocked_count DESC"}	{"condition": "long transactions are blocking multiple other sessions", "description": "Expensive operations within transaction are holding locks and causing cascading blocking"}	null	2026-02-23 20:18:31.390065
3238	sqlserver	query	Check default port with SQL authentication enabled	{"sql": "SELECT\\n  (SELECT DISTINCT local_tcp_port FROM sys.dm_exec_connections\\n   WHERE local_tcp_port IS NOT NULL AND net_transport = 'TCP') AS listening_port,\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.sql_logins WHERE is_disabled = 0) AS enabled_sql_logins"}	{"condition": "listening_port = 1433 AND windows_auth_only = 0 AND enabled_sql_logins > 0", "description": "SQL Server on default port 1433 with SQL authentication — prime target for brute force"}	null	2026-02-23 20:18:31.390066
2656	sqlserver	query	Check active connections for unencrypted Windows auth sessions	{"sql": "SELECT\\n  c.auth_scheme,\\n  c.encrypt_option,\\n  COUNT(*) AS session_count,\\n  COUNT(DISTINCT s.login_name) AS distinct_logins\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE c.auth_scheme IN ('KERBEROS', 'NTLM')\\nGROUP BY c.auth_scheme, c.encrypt_option\\nORDER BY c.auth_scheme, c.encrypt_option"}	{"condition": "rows where encrypt_option = 'FALSE' with auth_scheme KERBEROS or NTLM", "description": "Kerberos/NTLM sessions running without TLS — authentication tokens exposed on the wire"}	null	2026-02-23 20:18:31.390519
2760	sqlserver	query	Check for disabled specs pointing to enabled audits or vice versa	{"sql": "SELECT 'Server Spec' AS spec_type,\\n  sas.name AS spec_name, sas.is_state_enabled AS spec_enabled,\\n  sa.name AS audit_name, sa.is_state_enabled AS audit_enabled\\nFROM sys.server_audit_specifications sas\\nJOIN sys.server_audits sa ON sas.audit_guid = sa.audit_guid\\nWHERE sas.is_state_enabled <> sa.is_state_enabled\\nUNION ALL\\nSELECT 'Database Spec',\\n  das.name, das.is_state_enabled,\\n  sa.name, sa.is_state_enabled\\nFROM sys.database_audit_specifications das\\nJOIN sys.server_audits sa ON das.audit_guid = sa.audit_guid\\nWHERE das.is_state_enabled <> sa.is_state_enabled"}	{"condition": "specs enabled but audit disabled, or audit enabled but specs disabled", "description": "Mismatched enable states between audit and its specifications — events not captured"}	null	2026-02-23 20:18:31.390067
