1961	sqlserver	query	Find active transactions running longer than 5 minutes	{"sql": "SELECT t.transaction_id, s.session_id, s.login_name, s.host_name, s.program_name, DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS duration_seconds, t.transaction_begin_time, CASE t.transaction_type WHEN 1 THEN 'Read/Write' WHEN 2 THEN 'Read-Only' WHEN 3 THEN 'System' WHEN 4 THEN 'Distributed' END AS transaction_type, CASE t.transaction_state WHEN 0 THEN 'Not initialized' WHEN 1 THEN 'Initialized not started' WHEN 2 THEN 'Active' WHEN 3 THEN 'Ended (read-only)' WHEN 4 THEN 'DTC commit initiated' WHEN 5 THEN 'Awaiting resolution' WHEN 6 THEN 'Committed' WHEN 7 THEN 'Rolling back' WHEN 8 THEN 'Rolled back' END AS transaction_state FROM sys.dm_tran_active_transactions t JOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id JOIN sys.dm_exec_sessions s ON st.session_id = s.session_id WHERE t.transaction_type = 1 AND t.transaction_state = 2 AND DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) > 300 ORDER BY duration_seconds DESC"}	{"condition": "row_count > 0", "description": "Active read/write transactions running for more than 5 minutes — potential uncommitted queries holding locks"}	null	2026-02-23 20:18:31.390077
1971	sqlserver	query	Check for table-level locks with blocked waiters from hint usage	{"sql": "SELECT l.request_session_id AS holder_session, OBJECT_NAME(l.resource_associated_entity_id) AS table_name, l.request_mode AS lock_mode, (SELECT COUNT(*) FROM sys.dm_exec_requests r WHERE r.blocking_session_id = l.request_session_id) AS blocked_count, t.text AS holder_sql FROM sys.dm_tran_locks l LEFT JOIN sys.dm_exec_connections c ON l.request_session_id = c.session_id OUTER APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) t WHERE l.resource_type = 'OBJECT' AND l.request_mode IN ('S', 'X', 'SIX', 'Sch-M') AND l.request_status = 'GRANT' AND l.resource_database_id = DB_ID() AND EXISTS (SELECT 1 FROM sys.dm_exec_requests r WHERE r.blocking_session_id = l.request_session_id) ORDER BY blocked_count DESC"}	{"condition": "row_count > 0 AND blocked_count > 0", "description": "Table-level locks from explicit hints are blocking other sessions"}	null	2026-02-23 20:18:31.390077
1962	sqlserver	query	Check if long-running transactions are holding locks that block others	{"sql": "SELECT t.transaction_id, st.session_id, DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS txn_duration_seconds, (SELECT COUNT(*) FROM sys.dm_exec_requests r WHERE r.blocking_session_id = st.session_id) AS blocked_sessions, (SELECT COUNT(*) FROM sys.dm_tran_locks l WHERE l.request_session_id = st.session_id AND l.request_status = 'GRANT') AS held_locks, txt.text AS last_sql_text FROM sys.dm_tran_active_transactions t JOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id LEFT JOIN sys.dm_exec_connections c ON st.session_id = c.session_id OUTER APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) txt WHERE t.transaction_type = 1 AND t.transaction_state = 2 AND DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) > 300 ORDER BY blocked_sessions DESC"}	{"condition": "row_count > 0 AND blocked_sessions > 0", "description": "Long-running uncommitted transactions are actively blocking other sessions"}	null	2026-02-23 20:18:31.390078
1963	sqlserver	query	Find active transactions with large log usage	{"sql": "SELECT t.transaction_id, s.session_id, s.login_name, s.program_name, t.transaction_begin_time, DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS duration_seconds, dt.database_transaction_log_bytes_used / 1048576 AS log_used_mb, dt.database_transaction_log_bytes_reserved / 1048576 AS log_reserved_mb, dt.database_transaction_log_record_count AS log_records FROM sys.dm_tran_active_transactions t JOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id JOIN sys.dm_tran_database_transactions dt ON t.transaction_id = dt.transaction_id JOIN sys.dm_exec_sessions s ON st.session_id = s.session_id WHERE dt.database_transaction_log_bytes_used > 10485760 ORDER BY dt.database_transaction_log_bytes_used DESC"}	{"condition": "row_count > 0 AND log_used_mb > 10", "description": "Active transactions consuming more than 10 MB of transaction log — indicates large transaction scope"}	null	2026-02-23 20:18:31.390079
3529	postgresql	log_scan	Scan for WAL format incompatibility after upgrade	{"pattern": "WAL file.*incompatible|database files are incompatible with server|pg_controldata.*version mismatch|could not.*WAL.*version", "description": "WAL format incompatibility from version upgrade"}	{"condition": "pattern_found", "description": "WAL format changed after version upgrade"}	\N	2026-02-25 00:28:52.405273
1964	sqlserver	query	Check lock count held by large transactions	{"sql": "SELECT l.request_session_id AS session_id, COUNT(*) AS total_locks, SUM(CASE WHEN l.resource_type = 'KEY' THEN 1 ELSE 0 END) AS key_locks, SUM(CASE WHEN l.resource_type = 'PAGE' THEN 1 ELSE 0 END) AS page_locks, SUM(CASE WHEN l.resource_type = 'OBJECT' THEN 1 ELSE 0 END) AS table_locks, SUM(CASE WHEN l.request_mode IN ('X', 'IX') THEN 1 ELSE 0 END) AS exclusive_locks FROM sys.dm_tran_locks l WHERE l.request_status = 'GRANT' AND l.request_session_id IN (SELECT st.session_id FROM sys.dm_tran_active_transactions t JOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id JOIN sys.dm_tran_database_transactions dt ON t.transaction_id = dt.transaction_id WHERE dt.database_transaction_log_bytes_used > 10485760) GROUP BY l.request_session_id ORDER BY total_locks DESC"}	{"condition": "row_count > 0 AND total_locks > 5000", "description": "Large transactions holding thousands of locks — high contention risk with concurrent DML"}	null	2026-02-23 20:18:31.390079
1965	sqlserver	query	Find currently executing UPDATE/DELETE queries using scans	{"sql": "SELECT r.session_id, r.blocking_session_id, r.wait_type, r.wait_time / 1000 AS wait_seconds, t.text AS sql_text, p.query_plan FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t CROSS APPLY sys.dm_exec_query_plan(r.plan_handle) p WHERE r.command IN ('UPDATE', 'DELETE') AND CAST(p.query_plan AS NVARCHAR(MAX)) LIKE '%Scan%' AND r.blocking_session_id <> 0"}	{"condition": "row_count > 0", "description": "Blocked UPDATE/DELETE queries using scan operators — missing indexes force broader lock acquisition"}	null	2026-02-23 20:18:31.39008
1966	sqlserver	query	Check missing index DMV suggestions for tables involved in lock waits	{"sql": "SELECT TOP 20 OBJECT_NAME(mid.object_id) AS table_name, mid.equality_columns, mid.inequality_columns, mid.included_columns, migs.user_seeks, migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure FROM sys.dm_db_missing_index_details mid JOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle JOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle WHERE mid.database_id = DB_ID() AND migs.user_seeks > 100 ORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND improvement_measure > 10000", "description": "SQL Server recommends missing indexes on frequently accessed tables — these missing indexes are likely causing scan-based locks on modification queries"}	null	2026-02-23 20:18:31.39008
