1967	sqlserver	query	Check lock escalation counters from index operational stats	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, ios.index_lock_promotion_attempt_count AS escalation_attempts, ios.index_lock_promotion_count AS escalation_successes, CAST(ios.index_lock_promotion_count AS FLOAT) / NULLIF(ios.index_lock_promotion_attempt_count, 0) * 100 AS success_pct FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios JOIN sys.tables t ON ios.object_id = t.object_id JOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id WHERE ios.index_lock_promotion_attempt_count > 0 ORDER BY ios.index_lock_promotion_count DESC"}	{"condition": "row_count > 0 AND escalation_successes > 0", "description": "Lock escalation has occurred — row/page locks were promoted to table locks"}	null	2026-02-23 20:18:31.390081
1968	sqlserver	query	Check current table-level exclusive locks indicating active escalation	{"sql": "SELECT l.request_session_id AS session_id, OBJECT_NAME(l.resource_associated_entity_id) AS table_name, l.request_mode, l.request_status, r.command, r.wait_type, t.text AS sql_text FROM sys.dm_tran_locks l LEFT JOIN sys.dm_exec_requests r ON l.request_session_id = r.session_id OUTER APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE l.resource_type = 'OBJECT' AND l.request_mode IN ('X', 'SIX') AND l.request_status = 'GRANT' AND l.resource_database_id = DB_ID()"}	{"condition": "row_count > 0", "description": "Active table-level exclusive locks — all concurrent access to these tables is blocked"}	null	2026-02-23 20:18:31.390082
1969	sqlserver	query	Check table lock escalation settings for affected tables	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, t.lock_escalation, t.lock_escalation_desc FROM sys.tables t WHERE t.lock_escalation <> 2 AND t.object_id IN (SELECT ios.object_id FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios WHERE ios.index_lock_promotion_count > 0) ORDER BY t.name"}	{"condition": "row_count > 0 AND lock_escalation_desc = 'TABLE'", "description": "Tables with TABLE-level escalation (not DISABLE or AUTO) that have experienced lock promotions — candidates for ALTER TABLE SET LOCK_ESCALATION = DISABLE or AUTO"}	null	2026-02-23 20:18:31.390082
1972	sqlserver	query	Check active sessions using restrictive isolation levels	{"sql": "SELECT s.session_id, s.login_name, s.program_name, CASE s.transaction_isolation_level WHEN 0 THEN 'Unspecified' WHEN 1 THEN 'ReadUncommitted' WHEN 2 THEN 'ReadCommitted' WHEN 3 THEN 'RepeatableRead' WHEN 4 THEN 'Serializable' WHEN 5 THEN 'Snapshot' END AS isolation_level, (SELECT COUNT(*) FROM sys.dm_tran_locks l WHERE l.request_session_id = s.session_id AND l.request_status = 'GRANT') AS held_locks, (SELECT COUNT(*) FROM sys.dm_exec_requests r WHERE r.blocking_session_id = s.session_id) AS blocking_count FROM sys.dm_exec_sessions s WHERE s.is_user_process = 1 AND s.transaction_isolation_level IN (3, 4) ORDER BY held_locks DESC"}	{"condition": "row_count > 0", "description": "Sessions running under REPEATABLE READ or SERIALIZABLE — these isolation levels hold shared locks until transaction end, causing broader blocking"}	null	2026-02-23 20:18:31.390083
1973	sqlserver	query	Confirm restrictive isolation sessions are causing blocking chains	{"sql": "SELECT blocker.session_id AS blocker_session, CASE blocker.transaction_isolation_level WHEN 3 THEN 'RepeatableRead' WHEN 4 THEN 'Serializable' END AS blocker_isolation, COUNT(r.session_id) AS victim_count, MAX(r.wait_time / 1000) AS max_wait_seconds FROM sys.dm_exec_sessions blocker JOIN sys.dm_exec_requests r ON r.blocking_session_id = blocker.session_id WHERE blocker.transaction_isolation_level IN (3, 4) AND r.wait_type LIKE 'LCK%' GROUP BY blocker.session_id, blocker.transaction_isolation_level HAVING COUNT(r.session_id) > 0 ORDER BY victim_count DESC"}	{"condition": "row_count > 0 AND victim_count > 1", "description": "Sessions with restrictive isolation are head blockers for multiple victims — isolation level is too restrictive for the workload"}	null	2026-02-23 20:18:31.390084
