1974	sqlserver	query	Check page split counts from index operational stats	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, ios.leaf_insert_count, ios.leaf_update_count, ios.leaf_allocation_count AS page_splits, ios.nonleaf_allocation_count AS nonleaf_splits, CAST(ios.leaf_allocation_count AS FLOAT) / NULLIF(ios.leaf_insert_count + ios.leaf_update_count, 0) * 100 AS split_pct FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios JOIN sys.tables t ON ios.object_id = t.object_id JOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id WHERE ios.leaf_allocation_count > 100 ORDER BY ios.leaf_allocation_count DESC"}	{"condition": "row_count > 0 AND page_splits > 100", "description": "Indexes with significant page split activity — each split causes latch contention on the affected pages"}	null	2026-02-23 20:18:31.390084
1975	sqlserver	query	Check page latch wait stats correlated with page splits	{"sql": "SELECT ios.object_id, OBJECT_NAME(ios.object_id) AS table_name, i.name AS index_name, ios.page_latch_wait_count, ios.page_latch_wait_in_ms, ios.page_latch_wait_in_ms / NULLIF(ios.page_latch_wait_count, 0) AS avg_latch_wait_ms, ios.leaf_allocation_count AS page_splits FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios JOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id WHERE ios.page_latch_wait_count > 100 AND ios.leaf_allocation_count > 50 ORDER BY ios.page_latch_wait_in_ms DESC"}	{"condition": "row_count > 0 AND page_latch_wait_count > 100", "description": "Indexes with both page splits and page latch waits — splits are causing latch contention"}	null	2026-02-23 20:18:31.390085
1976	sqlserver	query	Check for PAGELATCH_EX waits concentrated on specific pages	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms, wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms FROM sys.dm_os_wait_stats WHERE wait_type IN ('PAGELATCH_EX', 'PAGELATCH_SH', 'PAGELATCH_UP') AND waiting_tasks_count > 0 ORDER BY wait_time_ms DESC"}	{"condition": "row_count > 0 AND waiting_tasks_count > 1000", "description": "Significant PAGELATCH waits detected — potential last-page contention from sequential inserts"}	null	2026-02-23 20:18:31.390085
1977	sqlserver	query	Identify tables with identity/sequence clustered keys and high insert rates	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, c.name AS key_column, c.is_identity, TYPE_NAME(c.system_type_id) AS data_type, ios.leaf_insert_count, ios.page_latch_wait_count, ios.page_latch_wait_in_ms FROM sys.tables t JOIN sys.indexes i ON t.object_id = i.object_id AND i.type = 1 JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios ON t.object_id = ios.object_id AND i.index_id = ios.index_id WHERE c.is_identity = 1 AND ios.leaf_insert_count > 10000 AND ios.page_latch_wait_count > 100 ORDER BY ios.page_latch_wait_count DESC"}	{"condition": "row_count > 0", "description": "Tables with identity-based clustered indexes experiencing high insert rates and page latch waits — classic last-page insert contention"}	null	2026-02-23 20:18:31.390086
1987	sqlserver	query	Check if statistics operations are blocking other sessions	{"sql": "SELECT r.session_id AS stats_session, r.command, t.text AS stats_sql, (SELECT COUNT(*) FROM sys.dm_exec_requests r2 WHERE r2.blocking_session_id = r.session_id) AS blocked_count, (SELECT MAX(r2.wait_time / 1000) FROM sys.dm_exec_requests r2 WHERE r2.blocking_session_id = r.session_id) AS max_blocked_wait_seconds FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE (r.command LIKE '%STATISTICS%' OR t.text LIKE '%UPDATE STATISTICS%') AND EXISTS (SELECT 1 FROM sys.dm_exec_requests r2 WHERE r2.blocking_session_id = r.session_id)"}	{"condition": "row_count > 0 AND blocked_count > 0", "description": "Statistics updates are actively blocking other sessions — consider scheduling stats updates during off-peak hours or using WITH SAMPLE instead of FULLSCAN"}	null	2026-02-23 20:18:31.390092
1978	sqlserver	query	Check if OPTIMIZE_FOR_SEQUENTIAL_KEY is enabled on affected indexes	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, CASE WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 15 THEN (SELECT TOP 1 CAST(ISNULL(i2.optimize_for_sequential_key, 0) AS INT) FROM sys.indexes i2 WHERE i2.object_id = i.object_id AND i2.index_id = i.index_id) ELSE -1 END AS optimize_for_sequential_key FROM sys.tables t JOIN sys.indexes i ON t.object_id = i.object_id AND i.type = 1 JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios ON t.object_id = ios.object_id AND i.index_id = ios.index_id WHERE c.is_identity = 1 AND ios.page_latch_wait_count > 100 ORDER BY t.name"}	{"condition": "row_count > 0 AND optimize_for_sequential_key = 0", "description": "Affected indexes do not have OPTIMIZE_FOR_SEQUENTIAL_KEY enabled (SQL Server 2019+) — enabling this reduces last-page contention"}	null	2026-02-23 20:18:31.390087
1979	sqlserver	query	Check RCSI and snapshot isolation settings on user databases	{"sql": "SELECT name AS database_name, is_read_committed_snapshot_on AS rcsi_enabled, snapshot_isolation_state, snapshot_isolation_state_desc FROM sys.databases WHERE database_id > 4 ORDER BY name"}	{"condition": "row_count > 0 AND rcsi_enabled = 0", "description": "User databases without RCSI enabled — readers will acquire shared locks that block concurrent writers"}	null	2026-02-23 20:18:31.390087
1980	sqlserver	query	Verify reader-writer blocking is occurring due to shared lock conflicts	{"sql": "SELECT r.session_id AS blocked_session, r.blocking_session_id AS blocker_session, r.wait_type, r.wait_time / 1000 AS wait_seconds, r.command AS blocked_command, br.command AS blocker_command, CASE WHEN r.command IN ('SELECT', 'FETCH') AND br.command IN ('UPDATE', 'DELETE', 'INSERT') THEN 'Reader blocked by writer' WHEN r.command IN ('UPDATE', 'DELETE', 'INSERT') AND br.command IN ('SELECT', 'FETCH') THEN 'Writer blocked by reader' ELSE 'Other' END AS blocking_pattern FROM sys.dm_exec_requests r JOIN sys.dm_exec_requests br ON r.blocking_session_id = br.session_id WHERE r.wait_type LIKE 'LCK%' AND ((r.command IN ('SELECT', 'FETCH') AND br.command IN ('UPDATE', 'DELETE', 'INSERT')) OR (r.command IN ('UPDATE', 'DELETE', 'INSERT') AND br.command IN ('SELECT', 'FETCH')))"}	{"condition": "row_count > 0", "description": "Reader-writer blocking detected — enabling RCSI would eliminate these conflicts by providing readers with a versioned snapshot instead of acquiring shared locks"}	null	2026-02-23 20:18:31.390088
2120	sqlserver	query	Check PAGEIOLATCH waits confirming physical I/O from insufficient cache	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms, wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms, signal_wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'PAGEIOLATCH_UP') AND waiting_tasks_count > 0 ORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH is among top 5 wait types by total wait_time_ms", "description": "High PAGEIOLATCH waits confirm that the low buffer hit ratio is forcing physical reads — pages are being evicted from the buffer pool before they can be reused, generating constant disk I/O"}	null	2026-02-23 20:18:31.390124
1981	sqlserver	query	Check deadlock frequency from system health extended event	{"sql": "SELECT COUNT(*) AS deadlock_count, MIN(event_time) AS first_deadlock, MAX(event_time) AS last_deadlock, DATEDIFF(MINUTE, MIN(event_time), MAX(event_time)) AS time_span_minutes FROM (SELECT CAST(xet.target_data AS XML).value('(RingBufferTarget/@eventCount)[1]', 'int') AS total_events, xe.event_time FROM (SELECT CAST(target_data AS XML) AS target_data FROM sys.dm_xe_session_targets t JOIN sys.dm_xe_sessions s ON t.event_session_address = s.address WHERE s.name = 'system_health' AND t.target_name = 'ring_buffer') xet CROSS APPLY (SELECT n.value('(@timestamp)[1]', 'datetime2') AS event_time FROM xet.target_data.nodes('RingBufferTarget/event[@name=\\"xml_deadlock_report\\"]') AS x(n)) xe) dl WHERE event_time > DATEADD(HOUR, -1, GETDATE())"}	{"condition": "deadlock_count > 5", "description": "More than 5 deadlocks in the last hour — potential retry storms without backoff"}	null	2026-02-23 20:18:31.390089
1982	sqlserver	query	Check deadlock frequency using performance counter	{"sql": "SELECT cntr_value AS total_deadlocks FROM sys.dm_os_performance_counters WHERE counter_name = 'Number of Deadlocks/sec' AND instance_name = '_Total'"}	{"condition": "total_deadlocks > 0", "description": "Deadlocks have occurred since server restart — combined with high frequency from step 1, indicates applications may be retrying without backoff"}	null	2026-02-23 20:18:31.390089
1983	sqlserver	query	Identify repeated deadlock victims on the same resources	{"sql": "SELECT DB_NAME(l.resource_database_id) AS database_name, l.resource_type, l.resource_description, l.request_session_id, s.login_name, s.program_name, COUNT(*) OVER (PARTITION BY l.resource_type, l.resource_description) AS contention_count FROM sys.dm_tran_locks l JOIN sys.dm_exec_sessions s ON l.request_session_id = s.session_id WHERE l.request_status = 'WAIT' AND l.request_mode IN ('X', 'U') AND l.resource_database_id = DB_ID() ORDER BY contention_count DESC"}	{"condition": "row_count > 0 AND contention_count > 3", "description": "Multiple sessions contending for the same lock resources — repeated deadlock cycles from immediate retries without exponential backoff"}	null	2026-02-23 20:18:31.39009
1984	sqlserver	query	Check for active Sch-M lock requests blocking other sessions	{"sql": "SELECT l.request_session_id AS ddl_session, OBJECT_NAME(l.resource_associated_entity_id) AS table_name, l.request_mode, l.request_status, r.command, r.percent_complete, r.estimated_completion_time / 1000 AS est_remaining_seconds, t.text AS ddl_text FROM sys.dm_tran_locks l JOIN sys.dm_exec_requests r ON l.request_session_id = r.session_id OUTER APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE l.resource_type = 'OBJECT' AND l.request_mode = 'Sch-M' AND l.request_status = 'GRANT'"}	{"condition": "row_count > 0", "description": "Active schema modification locks held — all concurrent access to the table is blocked"}	null	2026-02-23 20:18:31.39009
1985	sqlserver	query	Count sessions blocked by Sch-M locks	{"sql": "SELECT blocker.session_id AS ddl_session, OBJECT_NAME(bl.resource_associated_entity_id) AS table_name, COUNT(r.session_id) AS blocked_count, MAX(r.wait_time / 1000) AS max_wait_seconds, bt.text AS ddl_statement FROM sys.dm_tran_locks bl JOIN sys.dm_exec_requests r ON r.blocking_session_id = bl.request_session_id JOIN sys.dm_exec_sessions blocker ON bl.request_session_id = blocker.session_id LEFT JOIN sys.dm_exec_connections c ON bl.request_session_id = c.session_id OUTER APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) bt WHERE bl.request_mode = 'Sch-M' AND bl.request_status = 'GRANT' AND bl.resource_type = 'OBJECT' GROUP BY blocker.session_id, bl.resource_associated_entity_id, bt.text ORDER BY blocked_count DESC"}	{"condition": "row_count > 0 AND blocked_count > 0", "description": "DDL operations without ONLINE option are blocking concurrent sessions — use ALTER INDEX ... REBUILD WITH (ONLINE = ON) or ALTER TABLE ... WITH (ONLINE = ON) where supported"}	null	2026-02-23 20:18:31.390091
1986	sqlserver	query	Check for active statistics update operations	{"sql": "SELECT r.session_id, r.command, r.status, r.wait_type, r.wait_time / 1000 AS wait_seconds, r.percent_complete, t.text AS sql_text FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE r.command LIKE '%STATISTICS%' OR t.text LIKE '%UPDATE STATISTICS%' OR t.text LIKE '%CREATE STATISTICS%' OR t.text LIKE '%sp_updatestats%'"}	{"condition": "row_count > 0", "description": "Active statistics update operations that may be holding locks and blocking queries"}	null	2026-02-23 20:18:31.390092
4579	postgresql	query	Check for monitoring extensions installed	{"sql": "SELECT extname FROM pg_extension WHERE extname IN ('pg_stat_statements', 'auto_explain', 'pg_audit', 'pgaudit')"}	{"condition": "row_count = 0", "description": "No monitoring extensions installed indicates a gap in observability for detecting exploitation attempts"}	\N	2026-02-25 00:28:52.405273
1988	sqlserver	query	Check for synchronous auto-stats on databases with high modification counts	{"sql": "SELECT d.name AS database_name, d.is_auto_update_stats_on, d.is_auto_update_stats_async_on, (SELECT SUM(sp.modification_counter) FROM sys.stats s CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE sp.modification_counter > 500) AS total_pending_modifications FROM sys.databases d WHERE d.database_id = DB_ID() AND d.is_auto_update_stats_on = 1 AND d.is_auto_update_stats_async_on = 0"}	{"condition": "row_count > 0 AND is_auto_update_stats_async_on = 0", "description": "Database has synchronous auto-stats with pending modifications — statistics updates will block queries during recompilation"}	null	2026-02-23 20:18:31.390093
2009	sqlserver	query	Check pending I/O requests to confirm I/O subsystem saturation	{"sql": "SELECT vfs.database_id, DB_NAME(vfs.database_id) AS database_name, mf.physical_name, pio.io_pending_ms_ticks, pio.io_type, pio.scheduler_address FROM sys.dm_io_pending_io_requests pio JOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs ON pio.io_handle = vfs.file_handle JOIN sys.master_files mf ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id ORDER BY pio.io_pending_ms_ticks DESC"}	{"condition": "row_count > 5 OR any io_pending_ms_ticks > 50", "description": "Multiple pending I/O requests or long-pending requests confirm the I/O subsystem is saturated, causing extended latch holds as threads wait for pages to be read from or written to disk"}	null	2026-02-23 20:18:31.390106
1989	sqlserver	query	Identify tables most likely to trigger synchronous stats updates	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, s.name AS stat_name, sp.rows AS table_rows, sp.modification_counter, sp.last_updated, DATEDIFF(HOUR, sp.last_updated, GETDATE()) AS hours_since_update, CASE WHEN sp.rows < 500 AND sp.modification_counter >= 500 THEN 'Will trigger' WHEN sp.rows >= 500 AND sp.modification_counter >= (500 + CAST(sp.rows * 0.20 AS BIGINT)) THEN 'Will trigger' ELSE 'Below threshold' END AS auto_update_status FROM sys.tables t JOIN sys.stats s ON t.object_id = s.object_id CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE sp.modification_counter > 0 AND CASE WHEN sp.rows < 500 AND sp.modification_counter >= 500 THEN 1 WHEN sp.rows >= 500 AND sp.modification_counter >= (500 + CAST(sp.rows * 0.20 AS BIGINT)) THEN 1 ELSE 0 END = 1 ORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0", "description": "Tables have crossed the automatic statistics update threshold — next query referencing these tables will trigger a synchronous stats update that blocks the query and potentially others"}	null	2026-02-23 20:18:31.390094
1991	sqlserver	query	Identify tables with identity-based clustered indexes and high insert latch contention	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, c.name AS leading_key, c.is_identity, ios.leaf_insert_count, ios.page_latch_wait_count, ios.page_latch_wait_in_ms, ios.page_latch_wait_in_ms / NULLIF(ios.page_latch_wait_count, 0) AS avg_latch_wait_ms, p.rows AS row_count FROM sys.tables t JOIN sys.indexes i ON t.object_id = i.object_id AND i.type = 1 JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1 JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios ON t.object_id = ios.object_id AND i.index_id = ios.index_id JOIN sys.partitions p ON t.object_id = p.object_id AND i.index_id = p.index_id WHERE (c.is_identity = 1 OR TYPE_NAME(c.system_type_id) IN ('datetime', 'datetime2', 'datetimeoffset')) AND ios.page_latch_wait_count > 500 ORDER BY ios.page_latch_wait_count DESC"}	{"condition": "row_count > 0 AND page_latch_wait_count > 500", "description": "Tables with monotonically increasing clustered keys and significant page latch waits — classic last-page contention pattern"}	null	2026-02-23 20:18:31.390094
1992	sqlserver	query	Check if OPTIMIZE_FOR_SEQUENTIAL_KEY or partitioning can mitigate	{"sql": "SELECT SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, CASE WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 15 THEN (SELECT TOP 1 CAST(ISNULL(i2.optimize_for_sequential_key, 0) AS INT) FROM sys.indexes i2 WHERE i2.object_id = i.object_id AND i2.index_id = i.index_id) ELSE -1 END AS optimize_for_sequential_key, CASE WHEN p.partition_number > 1 THEN 'Partitioned' ELSE 'Not partitioned' END AS partition_status, p.rows FROM sys.tables t JOIN sys.indexes i ON t.object_id = i.object_id AND i.type = 1 JOIN sys.partitions p ON t.object_id = p.object_id AND i.index_id = p.index_id JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios ON t.object_id = ios.object_id AND i.index_id = ios.index_id WHERE ios.page_latch_wait_count > 500 ORDER BY ios.page_latch_wait_count DESC"}	{"condition": "row_count > 0 AND optimize_for_sequential_key = 0", "description": "High-contention tables without OPTIMIZE_FOR_SEQUENTIAL_KEY or hash partitioning — remediation available"}	null	2026-02-23 20:18:31.390095
1993	sqlserver	query	Check overall PAGELATCH wait statistics by type	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms, wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms, CAST(100.0 * wait_time_ms / NULLIF(SUM(wait_time_ms) OVER(), 0) AS DECIMAL(5,2)) AS pct_of_pagelatch_waits FROM sys.dm_os_wait_stats WHERE wait_type LIKE 'PAGELATCH%' AND waiting_tasks_count > 0 ORDER BY wait_time_ms DESC"}	{"condition": "row_count > 0 AND wait_time_ms > 10000", "description": "Significant PAGELATCH waits detected — indicates hot page contention in the buffer pool"}	null	2026-02-23 20:18:31.390095
1994	sqlserver	query	Identify specific pages with current latch contention	{"sql": "SELECT r.wait_type, r.wait_resource, DB_NAME(CAST(PARSENAME(REPLACE(r.wait_resource, ':', '.'), 3) AS INT)) AS database_name, r.session_id, r.blocking_session_id, r.wait_time / 1000 AS wait_seconds, t.text AS sql_text FROM sys.dm_exec_requests r CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE r.wait_type LIKE 'PAGELATCH%' AND r.wait_resource <> '' ORDER BY r.wait_time DESC"}	{"condition": "row_count > 0", "description": "Active sessions waiting on specific page latches — the wait_resource identifies the hot page (database_id:file_id:page_id)"}	null	2026-02-23 20:18:31.390096
1995	sqlserver	query	Identify tables and indexes with the highest page latch contention	{"sql": "SELECT TOP 10 SCHEMA_NAME(t.schema_id) AS schema_name, t.name AS table_name, i.name AS index_name, i.type_desc, ios.page_latch_wait_count, ios.page_latch_wait_in_ms, ios.page_latch_wait_in_ms / NULLIF(ios.page_latch_wait_count, 0) AS avg_latch_wait_ms, ios.page_io_latch_wait_count, ios.page_io_latch_wait_in_ms FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios JOIN sys.tables t ON ios.object_id = t.object_id JOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id WHERE ios.page_latch_wait_count > 0 ORDER BY ios.page_latch_wait_in_ms DESC"}	{"condition": "row_count > 0 AND page_latch_wait_count > 1000", "description": "Indexes with significant page latch waits — these contain the hot pages causing buffer pool contention"}	null	2026-02-23 20:18:31.390097
1996	sqlserver	query	Check PAGELATCH wait statistics and page life expectancy	{"sql": "SELECT ws.wait_type, ws.waiting_tasks_count, ws.wait_time_ms, ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_wait_ms, (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Page life expectancy') AS ple_seconds, (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Page reads/sec') AS page_reads_per_sec FROM sys.dm_os_wait_stats ws WHERE ws.wait_type IN ('PAGELATCH_SH', 'PAGELATCH_EX', 'PAGELATCH_UP') AND ws.waiting_tasks_count > 0 ORDER BY ws.wait_time_ms DESC"}	{"condition": "ple_seconds < 300 AND total PAGELATCH wait_time_ms is among top wait types", "description": "Low page life expectancy combined with high PAGELATCH waits indicates buffer pool memory pressure is causing latch contention as threads wait for pages being read from disk"}	null	2026-02-23 20:18:31.390097
2010	sqlserver	query	Check parallelism-related wait types and CXPACKET/CXCONSUMER waits	{"sql": "SELECT wait_type, waiting_tasks_count, wait_time_ms, wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms FROM sys.dm_os_wait_stats WHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'CXSYNC_PORT', 'CXSYNC_CONSUMER', 'PAGELATCH_SH', 'PAGELATCH_EX', 'PAGELATCH_UP') AND waiting_tasks_count > 0 ORDER BY wait_time_ms DESC"}	{"condition": "CXPACKET or CXCONSUMER is a top-3 wait type AND PAGELATCH waits are also significant", "description": "High CXPACKET/CXCONSUMER combined with significant PAGELATCH waits indicates parallel query execution is generating latch contention as multiple parallel threads scan and update the same pages"}	null	2026-02-23 20:18:31.390106
1997	sqlserver	query	Check buffer pool allocation versus physical memory	{"sql": "SELECT c.value_in_use AS max_server_memory_mb, si.physical_memory_kb / 1024 AS physical_memory_mb, CAST(c.value_in_use AS FLOAT) / (si.physical_memory_kb / 1024.0) * 100 AS pct_allocated, pm.memory_utilization_percentage, (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Lazy writes/sec') AS lazy_writes_per_sec, (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE object_name LIKE '%Buffer Manager%' AND counter_name = 'Free list stalls/sec') AS free_list_stalls_per_sec FROM sys.configurations c CROSS JOIN sys.dm_os_sys_info si CROSS JOIN sys.dm_os_process_memory pm WHERE c.name = 'max server memory (MB)'"}	{"condition": "memory_utilization_percentage > 95 OR free_list_stalls_per_sec > 0 OR lazy_writes_per_sec > 20", "description": "Memory utilization near 100%, free list stalls, or high lazy writes confirm the buffer pool is undersized, forcing constant page eviction and re-reads that generate latch waits"}	null	2026-02-23 20:18:31.390099
6601	oracle	query	Oracle check TDE wallet status	{"sql": "SELECT wrl_type, status, wallet_type FROM v$encryption_wallet"}	{"condition": "status NOT IN ('OPEN', 'OPEN_NO_MASTER_KEY')", "description": "TDE wallet is not open — encryption infrastructure is inactive"}	\N	2026-02-28 12:19:19.580455
1998	sqlserver	query	Find indexes with high fill factor and high page split rates	{"sql": "SELECT OBJECT_NAME(ips.object_id) AS table_name, i.name AS index_name, i.fill_factor, ips.avg_fragmentation_in_percent, ips.page_count, ios.leaf_insert_count, ios.leaf_update_count, ios.leaf_allocation_count AS page_splits FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips JOIN sys.indexes i ON i.object_id = ips.object_id AND i.index_id = ips.index_id JOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios ON ios.object_id = ips.object_id AND ios.index_id = ips.index_id WHERE i.fill_factor IN (0, 100) AND ios.leaf_allocation_count > 1000 AND ips.page_count > 1000 ORDER BY ios.leaf_allocation_count DESC"}	{"condition": "row_count > 0 AND leaf_allocation_count is high relative to leaf_insert_count", "description": "Indexes with fill factor 0 (defaults to 100%) or 100% experiencing frequent page splits generate latch contention on the pages being split"}	null	2026-02-23 20:18:31.390099
2000	sqlserver	query	Identify specific hot page contention from page splits	{"sql": "SELECT ios.object_id, OBJECT_NAME(ios.object_id) AS table_name, i.name AS index_name, ios.page_latch_wait_count, ios.page_latch_wait_in_ms, ios.page_latch_wait_in_ms / NULLIF(ios.page_latch_wait_count, 0) AS avg_page_latch_wait_ms, ios.leaf_allocation_count AS page_splits, ios.nonleaf_allocation_count AS nonleaf_page_splits FROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios JOIN sys.indexes i ON i.object_id = ios.object_id AND i.index_id = ios.index_id WHERE ios.page_latch_wait_count > 1000 ORDER BY ios.page_latch_wait_count DESC"}	{"condition": "row_count > 0 AND indexes with high page_latch_wait_count correlate with high leaf_allocation_count", "description": "Indexes with correlated high page latch waits and page split counts confirm fill factor is too high for the DML workload on those indexes"}	null	2026-02-23 20:18:31.3901
2001	sqlserver	query	Check NUMA node configuration and processor count	{"sql": "SELECT si.cpu_count AS logical_processors, si.scheduler_count, si.max_workers_count, si.numa_node_count, (SELECT COUNT(*) FROM sys.dm_os_schedulers WHERE status = 'VISIBLE ONLINE') AS online_schedulers, (SELECT value_in_use FROM sys.configurations WHERE name = 'affinity mask') AS affinity_mask, (SELECT value_in_use FROM sys.configurations WHERE name = 'affinity64 mask') AS affinity64_mask FROM sys.dm_os_sys_info si"}	{"condition": "logical_processors > 16 AND numa_node_count > 1 AND affinity_mask = 0 AND affinity64_mask = 0", "description": "Large processor count with multiple NUMA nodes and no affinity mask configured means SQL Server uses all processors without NUMA-aware memory partitioning, causing cross-NUMA latch contention"}	null	2026-02-23 20:18:31.3901
2002	sqlserver	query	Check per-NUMA node memory distribution and foreign page access	{"sql": "SELECT memory_node_id, virtual_address_space_committed_kb / 1024 AS committed_mb, pages_kb / 1024 AS pages_mb, foreign_committed_kb / 1024 AS foreign_committed_mb, CASE WHEN pages_kb > 0 THEN CAST(foreign_committed_kb AS FLOAT) / pages_kb * 100 ELSE 0 END AS foreign_pct FROM sys.dm_os_memory_nodes WHERE memory_node_id != 64"}	{"condition": "foreign_pct > 20 for any NUMA node OR large imbalance in committed_mb across nodes", "description": "High foreign memory percentage indicates threads are accessing memory allocated on remote NUMA nodes, causing additional latency and latch contention"}	null	2026-02-23 20:18:31.390101
