2053	sqlserver	query	Check buffer pool hit ratio and page life expectancy	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Buffer cache hit ratio') AS cache_hit_ratio,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Buffer cache hit ratio base') AS cache_hit_ratio_base,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Page life expectancy') AS page_life_expectancy,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Page reads/sec') AS page_reads_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Lazy writes/sec') AS lazy_writes_sec"}	{"condition": "page_life_expectancy < 300 or lazy_writes_sec > 20 or page_reads_sec > 100", "description": "Short PLE, high lazy writes, or excessive page reads indicate buffer pool thrashing"}	null	2026-02-23 20:18:31.390135
3051	sqlserver	query	Check for UNSAFE assemblies with CLR modules	{"sql": "SELECT a.name AS assembly_name,\\n  a.permission_set_desc,\\n  OBJECT_NAME(am.object_id) AS module_name,\\n  o.type_desc AS module_type,\\n  a.clr_name\\nFROM sys.assemblies a\\nJOIN sys.assembly_modules am ON a.assembly_id = am.assembly_id\\nJOIN sys.objects o ON am.object_id = o.object_id\\nWHERE a.is_user_defined = 1\\n  AND a.permission_set_desc = 'UNSAFE_ACCESS'"}	{"condition": "UNSAFE assemblies with executable CLR modules", "description": "UNSAFE CLR assemblies expose executable modules — unrestricted .NET code execution capability"}	null	2026-02-23 20:18:31.390755
2054	sqlserver	query	Check buffer pool size vs database sizes	{"sql": "SELECT\\n  (SELECT cntr_value / 1024 FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Database pages') AS buffer_pool_data_mb,\\n  (SELECT SUM(size * 8 / 1024) FROM sys.master_files\\n   WHERE type = 0 AND database_id > 4) AS total_data_file_mb,\\n  (SELECT CAST(value_in_use AS BIGINT) FROM sys.configurations\\n   WHERE name = 'max server memory (MB)') AS max_memory_mb"}	{"condition": "buffer_pool_data_mb < total_data_file_mb * 0.20", "description": "Buffer pool holds less than 20% of total data — severely undersized for caching"}	null	2026-02-23 20:18:31.390135
2055	sqlserver	query	Check connection count and per-connection memory	{"sql": "SELECT\\n  COUNT(*) AS total_sessions,\\n  SUM(s.memory_usage * 8) AS total_session_memory_kb,\\n  AVG(s.memory_usage * 8) AS avg_session_memory_kb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'User Connections' AND instance_name = '') AS user_connections,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n   AND counter_name = 'Connection Memory (KB)') AS connection_memory_kb\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1"}	{"condition": "total_sessions > 500 or connection_memory_kb > 500000", "description": "High session count or excessive memory consumed by connections"}	null	2026-02-23 20:18:31.390136
2056	sqlserver	query	Check memory pressure from connection overhead	{"sql": "SELECT\\n  mc.type AS clerk_type,\\n  mc.pages_kb / 1024 AS clerk_memory_mb\\nFROM sys.dm_os_memory_clerks mc\\nWHERE mc.type IN ('MEMORYCLERK_SQLCONNECTIONPOOL',\\n  'MEMORYCLERK_SOSNODE', 'USERSTORE_TOKENPERM')\\nORDER BY mc.pages_kb DESC"}	{"condition": "clerk_memory_mb for connection-related clerks > 500 MB combined", "description": "Significant memory consumed by connection infrastructure"}	null	2026-02-23 20:18:31.390137
2058	sqlserver	query	Check aggregate workspace memory consumption	{"sql": "SELECT\\n  (SELECT SUM(granted_memory_kb) / 1024 FROM sys.dm_exec_query_memory_grants\\n   WHERE grant_time IS NOT NULL) AS total_granted_mb,\\n  (SELECT SUM(used_memory_kb) / 1024 FROM sys.dm_exec_query_memory_grants\\n   WHERE grant_time IS NOT NULL) AS total_used_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n   AND counter_name = 'Total Server Memory (KB)') / 1024 AS total_server_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n   AND counter_name = 'Memory Grants Pending') AS grants_pending"}	{"condition": "total_granted_mb > total_server_mb * 0.25 or grants_pending > 0", "description": "Workspace memory grants consuming large share of server memory or causing queuing"}	null	2026-02-23 20:18:31.390138
2059	sqlserver	query	Check for abnormally large memory clerks	{"sql": "SELECT TOP 20\\n  mc.type AS clerk_type,\\n  mc.name AS clerk_name,\\n  mc.pages_kb / 1024 AS clerk_mb,\\n  mc.pages_kb * 100.0 / NULLIF(\\n    (SELECT SUM(pages_kb) FROM sys.dm_os_memory_clerks), 0\\n  ) AS pct_of_total\\nFROM sys.dm_os_memory_clerks mc\\nORDER BY mc.pages_kb DESC"}	{"condition": "non-buffer-pool clerk consuming > 10% of total memory", "description": "Memory clerk consuming disproportionate share — potential leak source"}	null	2026-02-23 20:18:31.390139
2060	sqlserver	query	Check process memory and virtual address space	{"sql": "SELECT\\n  pm.physical_memory_in_use_kb / 1024 AS physical_in_use_mb,\\n  pm.virtual_address_space_committed_kb / 1024 AS committed_vas_mb,\\n  pm.locked_page_allocations_kb / 1024 AS locked_pages_mb,\\n  pm.memory_utilization_percentage,\\n  pm.process_physical_memory_low AS low_memory_signal,\\n  pm.process_virtual_memory_low AS low_vas_signal\\nFROM sys.dm_os_process_memory pm"}	{"condition": "low_memory_signal = 1 or low_vas_signal = 1 or committed_vas_mb > physical_in_use_mb * 1.5", "description": "Low memory signals or VAS significantly exceeding physical use indicates leak"}	null	2026-02-23 20:18:31.390139
2061	sqlserver	query	Find large batch operations with high memory grants	{"sql": "SELECT r.session_id, r.command, r.status,\\n  r.wait_type,\\n  mg.granted_memory_kb / 1024 AS granted_mb,\\n  mg.used_memory_kb / 1024 AS used_mb,\\n  r.row_count AS rows_processed,\\n  DATEDIFF(SECOND, r.start_time, GETDATE()) AS duration_sec,\\n  SUBSTRING(t.text, 1, 200) AS query_text\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_query_memory_grants mg ON r.session_id = mg.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE mg.granted_memory_kb > 262144\\nORDER BY mg.granted_memory_kb DESC"}	{"condition": "operations with granted_mb > 256", "description": "Large batch operations holding significant memory grants"}	null	2026-02-23 20:18:31.39014
2606	sqlserver	query	Check if server audit captures login changes	{"sql": "SELECT COUNT(*) AS change_audit_specs\\nFROM sys.server_audit_specification_details sasd\\nJOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\nWHERE sasd.audit_action_name IN (\\n  'SERVER_PRINCIPAL_CHANGE_GROUP',\\n  'LOGIN_CHANGE_PASSWORD_GROUP',\\n  'SERVER_ROLE_MEMBER_CHANGE_GROUP',\\n  'DATABASE_ROLE_MEMBER_CHANGE_GROUP'\\n)\\n  AND sas.is_state_enabled = 1"}	{"condition": "change_audit_specs = 0", "description": "No audit specifications for login/role changes — changes are happening without audit trail"}	null	2026-02-23 20:18:31.39014
9424	oracle	query	ora-check-rootcause-database-links	{"sql": "SELECT owner, db_link, username, host, created FROM dba_db_links WHERE owner = 'PUBLIC' ORDER BY created"}	{"condition": "row_count > 0", "description": "Public database links accessible to all users — potential scope confusion risk"}	\N	2026-02-28 12:19:19.580455
2115	sqlserver	query	Check Resource Governor workload group memory grant settings	{"sql": "SELECT wg.name AS workload_group, wg.request_max_memory_grant_percent, wg.request_max_cpu_time_sec, wg.max_dop, wg.request_memory_grant_timeout_sec, rp.name AS resource_pool, rp.max_memory_percent, rp.min_memory_percent FROM sys.dm_resource_governor_workload_groups wg JOIN sys.dm_resource_governor_resource_pools rp ON wg.pool_id = rp.pool_id WHERE wg.name != 'internal'"}	{"condition": "request_max_memory_grant_percent < 10 OR request_max_memory_grant_percent > 50", "description": "Memory grant percent below 10% can starve sort-heavy queries (causing spills), while above 50% allows single queries to consume half the pool's workspace memory, blocking others"}	null	2026-02-23 20:18:31.390175
2062	sqlserver	query	Check impact on buffer pool and pending grants	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Page life expectancy') AS ple,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n   AND counter_name = 'Memory Grants Pending') AS grants_pending,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n   AND counter_name = 'Memory Grants Outstanding') AS grants_outstanding,\\n  (SELECT SUM(granted_memory_kb) / 1024 FROM sys.dm_exec_query_memory_grants) AS total_granted_mb"}	{"condition": "ple < 300 or grants_pending > 0", "description": "Batch operations causing buffer pool pressure or memory grant queuing"}	null	2026-02-23 20:18:31.390141
8878	oracle	query	ora_check_optimizer_search_limit	{"sql": "SELECT name, value FROM v$parameter WHERE name = '_optimizer_max_permutations'"}	{"condition": "row_count > 0", "description": "Optimizer permutation limit may prevent exhaustive join order search for queries with many tables"}	\N	2026-02-28 12:19:19.580455
2064	sqlserver	query	Check plan cache bloat from stored procedure recompilations	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans\\n   WHERE objtype = 'Proc') AS cached_proc_plans,\\n  (SELECT SUM(size_in_bytes) / 1024 / 1024 FROM sys.dm_exec_cached_plans\\n   WHERE objtype = 'Proc') AS proc_cache_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%SQL Statistics%'\\n   AND counter_name = 'SQL Re-Compilations/sec') AS recompiles_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Plan Cache%'\\n   AND counter_name = 'Cache Hit Ratio'\\n   AND instance_name = 'SQL Plans') AS plan_cache_hit_ratio"}	{"condition": "proc_cache_mb > 1024 or recompiles_sec > 50", "description": "Excessive procedure plan cache or frequent recompilations"}	null	2026-02-23 20:18:31.390142
4006	postgresql	query	Check archive timing pattern	{"sql": "SELECT failed_count, archived_count, last_archived_time, last_failed_time, CASE WHEN last_archived_time IS NOT NULL AND archived_count > 0 THEN (NOW() - last_archived_time) ELSE NULL END AS time_since_success FROM pg_stat_archiver"}	{"condition": "failed_count > archived_count", "description": "More failures than successes suggests timeout-related issues"}	\N	2026-02-25 00:28:52.405273
2065	sqlserver	query	Check background process memory and activity	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Checkpoint pages/sec') AS checkpoint_pages_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Lazy writes/sec') AS lazy_writes_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Free list stalls/sec') AS free_list_stalls_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Ghost Cleanup/sec'\\n   AND instance_name = '') AS ghost_cleanup_sec"}	{"condition": "lazy_writes_sec > 20 or free_list_stalls_sec > 2 or checkpoint_pages_sec > 300", "description": "High background process activity indicating memory pressure"}	null	2026-02-23 20:18:31.390143
2066	sqlserver	query	Check memory clerks for background process overhead	{"sql": "SELECT mc.type, mc.pages_kb / 1024 AS clerk_mb\\nFROM sys.dm_os_memory_clerks mc\\nWHERE mc.type IN (\\n  'MEMORYCLERK_SQLBUFFERPOOL',\\n  'MEMORYCLERK_SQLLOGPOOL',\\n  'MEMORYCLERK_SQLSTORENG',\\n  'CACHESTORE_SQLCP',\\n  'CACHESTORE_OBJCP'\\n)\\nORDER BY mc.pages_kb DESC"}	{"condition": "non-buffer-pool clerks consuming > 2 GB combined", "description": "Background infrastructure memory clerks consuming significant memory"}	null	2026-02-23 20:18:31.390144
2067	sqlserver	query	Check system-level memory and SQL Server allocation	{"sql": "SELECT\\n  sm.total_physical_memory_kb / 1024 AS total_physical_mb,\\n  sm.available_physical_memory_kb / 1024 AS available_mb,\\n  pm.physical_memory_in_use_kb / 1024 AS sql_using_mb,\\n  (sm.total_physical_memory_kb - sm.available_physical_memory_kb - pm.physical_memory_in_use_kb) / 1024 AS other_processes_mb,\\n  sm.system_memory_state_desc,\\n  pm.process_physical_memory_low AS sql_low_memory\\nFROM sys.dm_os_sys_memory sm\\nCROSS JOIN sys.dm_os_process_memory pm"}	{"condition": "other_processes_mb > total_physical_mb * 0.30 or system_memory_state_desc LIKE '%Low%'", "description": "Non-SQL processes consuming > 30% of physical memory or system memory state is low"}	null	2026-02-23 20:18:31.390144
2068	sqlserver	query	Check if SQL Server has been shrunk due to external pressure	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS BIGINT) FROM sys.configurations\\n   WHERE name = 'max server memory (MB)') AS max_configured_mb,\\n  pm.physical_memory_in_use_kb / 1024 AS current_using_mb,\\n  (SELECT cntr_value / 1024 FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n   AND counter_name = 'Target Server Memory (KB)') AS target_mb,\\n  (SELECT cntr_value / 1024 FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Memory Manager%'\\n   AND counter_name = 'Total Server Memory (KB)') AS total_server_mb\\nFROM sys.dm_os_process_memory pm"}	{"condition": "total_server_mb < target_mb * 0.90 or total_server_mb < max_configured_mb * 0.80", "description": "SQL Server using significantly less than its target — external memory pressure forcing shrinkage"}	null	2026-02-23 20:18:31.390145
2069	sqlserver	query	Analyze connection distribution and idle patterns	{"sql": "SELECT s.program_name, s.host_name,\\n  COUNT(*) AS total_connections,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS idle_connections,\\n  SUM(s.memory_usage * 8) AS total_session_memory_kb,\\n  AVG(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS avg_idle_minutes\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 10\\nORDER BY total_connections DESC"}	{"condition": "idle_connections > total_connections * 0.80 or total_connections > 50 per host", "description": "Most connections idle or excessive connections per application — pool oversized"}	null	2026-02-23 20:18:31.390145
3127	sqlserver	query	Confirm unencrypted connections exist	{"sql": "SELECT COUNT(*) AS unencrypted_connections,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections) AS total_connections\\nFROM sys.dm_exec_connections\\nWHERE encrypt_option = 'FALSE'"}	{"condition": "unencrypted_connections > 0", "description": "Active unencrypted connections confirm missing encryption requirements"}	null	2026-02-23 20:18:31.390783
2071	sqlserver	query	Find long-running transactions with version store impact	{"sql": "SELECT t.transaction_id,\\n  DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS duration_sec,\\n  t.transaction_type, s.session_id, s.program_name,\\n  s.status AS session_status, s.open_transaction_count,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Version Store Size (KB)'\\n   AND instance_name = '_Total') / 1024 AS version_store_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Version Generation rate (KB/s)'\\n   AND instance_name = '_Total') AS version_gen_rate_kb_sec\\nFROM sys.dm_tran_active_transactions t\\nJOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_sessions s ON st.session_id = s.session_id\\nWHERE DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) > 300\\n  AND s.is_user_process = 1\\nORDER BY duration_sec DESC"}	{"condition": "transactions older than 5 minutes with version_store_mb > 1024", "description": "Long transactions preventing version store cleanup"}	null	2026-02-23 20:18:31.390147
2072	sqlserver	query	Check version store growth and tempdb pressure	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Version Store Size (KB)'\\n   AND instance_name = '_Total') / 1024 AS version_store_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Longest Transaction Running Time'\\n   AND instance_name = '_Total') AS longest_txn_sec,\\n  (SELECT SUM(unallocated_extent_page_count) * 8 / 1024\\n   FROM sys.dm_db_file_space_usage\\n   WHERE database_id = 2) AS tempdb_free_mb,\\n  (SELECT SUM(version_store_reserved_page_count) * 8 / 1024\\n   FROM sys.dm_db_file_space_usage\\n   WHERE database_id = 2) AS version_store_reserved_mb"}	{"condition": "version_store_reserved_mb > 2048 or tempdb_free_mb < 1024", "description": "Version store consuming significant tempdb space or tempdb running low"}	null	2026-02-23 20:18:31.390147
2073	sqlserver	query	Check for heaps with forwarded records	{"sql": "SELECT OBJECT_SCHEMA_NAME(i.object_id) AS schema_name,\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  ios.forwarded_fetch_count,\\n  ios.leaf_insert_count, ios.leaf_update_count,\\n  ios.leaf_delete_count, ios.leaf_ghost_count,\\n  p.rows AS row_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, 0) ios\\nJOIN sys.indexes i ON ios.object_id = i.object_id AND ios.index_id = i.index_id\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nWHERE i.type = 0\\n  AND ios.forwarded_fetch_count > 1000\\nORDER BY ios.forwarded_fetch_count DESC"}	{"condition": "tables with forwarded_fetch_count > 1000", "description": "Heap tables with significant forwarded records causing extra I/O and buffer pool waste"}	null	2026-02-23 20:18:31.390148
4007	postgresql	config_check	Check archive_timeout setting	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name = 'archive_timeout'"}	{"condition": "setting::int > 0", "description": "archive_timeout is set, forcing periodic WAL switches that may compound timeout issues"}	\N	2026-02-25 00:28:52.405273
2074	sqlserver	query	Check ghost record accumulation and cleanup rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Ghost Cleanup/sec'\\n   AND instance_name = '') AS ghost_cleanup_sec,\\n  (SELECT SUM(leaf_ghost_count) FROM sys.dm_db_index_operational_stats(\\n   DB_ID(), NULL, NULL, NULL)) AS total_ghost_records,\\n  (SELECT SUM(forwarded_fetch_count) FROM sys.dm_db_index_operational_stats(\\n   DB_ID(), NULL, NULL, 0)) AS total_forwarded_fetches,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE object_name LIKE '%Buffer Manager%'\\n   AND counter_name = 'Page life expectancy') AS ple"}	{"condition": "total_ghost_records > 100000 or total_forwarded_fetches > 1000000", "description": "High ghost record or forwarded fetch counts indicating table bloat and memory waste"}	null	2026-02-23 20:18:31.390148
2076	sqlserver	query	Check high-impact missing indexes for memory-heavy queries	{"sql": "SELECT TOP 20\\n  mid.statement AS table_name,\\n  mid.equality_columns, mid.inequality_columns,\\n  mid.included_columns,\\n  migs.avg_user_impact AS impact_pct,\\n  migs.user_seeks, migs.user_scans,\\n  migs.avg_total_user_cost AS avg_cost,\\n  migs.avg_user_impact * migs.user_seeks AS improvement_score\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE migs.avg_user_impact > 70\\nORDER BY migs.avg_user_impact * migs.user_seeks DESC"}	{"condition": "high-impact missing indexes (improvement_score > 10000)", "description": "Missing indexes that would eliminate sorts/scans and reduce memory grants"}	null	2026-02-23 20:18:31.39015
2077	sqlserver	query	Find queries with large memory grants and high DOP	{"sql": "SELECT session_id, dop, requested_memory_kb, granted_memory_kb, required_memory_kb, used_memory_kb, max_used_memory_kb, ideal_memory_kb, CASE WHEN dop > 0 THEN granted_memory_kb / dop ELSE granted_memory_kb END AS grant_per_thread_kb, query_cost, plan_handle FROM sys.dm_exec_query_memory_grants WHERE granted_memory_kb IS NOT NULL AND dop > 1 ORDER BY granted_memory_kb DESC"}	{"condition": "row_count > 0 AND granted_memory_kb > 500000 AND dop > 4", "description": "Queries with memory grants exceeding 500 MB and DOP above 4 indicate parallelism is multiplying memory consumption — each parallel thread gets its own hash/sort workspace"}	null	2026-02-23 20:18:31.39015
2078	sqlserver	query	Check MAXDOP configuration and resource semaphore waits	{"sql": "SELECT (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max degree of parallelism') AS server_maxdop, (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'cost threshold for parallelism') AS cost_threshold, (SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type = 'RESOURCE_SEMAPHORE') AS resource_semaphore_wait_ms, (SELECT waiting_tasks_count FROM sys.dm_os_wait_stats WHERE wait_type = 'RESOURCE_SEMAPHORE') AS resource_semaphore_waiters, (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE granted_memory_kb IS NULL) AS queries_waiting_for_grant"}	{"condition": "server_maxdop = 0 OR server_maxdop > 8 OR resource_semaphore_waiters > 0 OR queries_waiting_for_grant > 0", "description": "Unrestricted MAXDOP (0 = all cores) or MAXDOP above 8 combined with RESOURCE_SEMAPHORE waits confirms that high-DOP queries are consuming disproportionate workspace memory, forcing other queries to wait for grants"}	null	2026-02-23 20:18:31.390151
2596	sqlserver	query	Check for sysadmin-level accounts beyond minimum required	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  sp.create_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals r ON srm.role_principal_id = r.principal_id\\nWHERE r.name = 'sysadmin'\\n  AND sp.name NOT LIKE 'NT SERVICE\\\\%'\\n  AND sp.name NOT LIKE '##%##'\\n  AND sp.is_disabled = 0"}	{"condition": "row_count > 2", "description": "More than 2 enabled sysadmin accounts — potential migration leftovers"}	null	2026-02-23 20:18:31.390488
4311	postgresql	query	Check pg_cron for failed jobs that were retried during business hours	{"sql": "SELECT a.jobid, a.command, a.start_time AS failed_run, a.status AS failed_status, b.start_time AS retry_run, b.status AS retry_status FROM cron.job_run_details a JOIN cron.job_run_details b ON a.jobid = b.jobid AND b.start_time > a.start_time AND b.start_time < a.start_time + interval '4 hours' WHERE a.status = 'failed' AND EXTRACT(HOUR FROM b.start_time) BETWEEN 8 AND 17 AND a.start_time > now() - interval '7 days' ORDER BY a.start_time DESC"}	{"condition": "row_count > 0", "description": "Failed jobs were retried during peak business hours"}	\N	2026-02-25 00:28:52.405273
2087	sqlserver	query	Find tables missing statistics on columns used in predicates	{"sql": "SELECT OBJECT_NAME(mid.object_id) AS table_name, mid.equality_columns, mid.inequality_columns, migs.avg_user_impact, migs.user_seeks FROM sys.dm_db_missing_index_details mid JOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle JOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle WHERE mid.database_id = DB_ID() AND migs.avg_user_impact > 70 ORDER BY migs.user_seeks * migs.avg_user_impact DESC"}	{"condition": "row_count > 0", "description": "Missing indexes imply missing statistics on the join and filter columns — without statistics, the optimizer uses fixed guesses (30% for inequality, 10% for equality) that produce wildly inaccurate memory grants"}	null	2026-02-23 20:18:31.390152
2117	sqlserver	query	Check for RESOURCE_SEMAPHORE waits confirming grant contention	{"sql": "SELECT ws.wait_type, ws.waiting_tasks_count, ws.wait_time_ms, ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_wait_ms FROM sys.dm_os_wait_stats ws WHERE ws.wait_type IN ('RESOURCE_SEMAPHORE', 'RESOURCE_SEMAPHORE_QUERY_COMPILE') AND ws.waiting_tasks_count > 0"}	{"condition": "waiting_tasks_count > 0 AND avg_wait_ms > 1000", "description": "RESOURCE_SEMAPHORE waits averaging over 1 second confirm memory grant configuration is causing queries to queue — either individual grants are too large (crowding others out) or the total workspace pool is too small"}	null	2026-02-23 20:18:31.390176
2080	sqlserver	query	Find large memory grants associated with LOB or XML processing	{"sql": "SELECT mg.session_id, mg.granted_memory_kb, mg.max_used_memory_kb, mg.ideal_memory_kb, mg.dop, r.total_elapsed_time / 1000 AS elapsed_sec, SUBSTRING(t.text, (r.statement_start_offset / 2) + 1, (CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE r.statement_end_offset END - r.statement_start_offset) / 2 + 1) AS current_statement FROM sys.dm_exec_query_memory_grants mg JOIN sys.dm_exec_requests r ON mg.session_id = r.session_id CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE mg.granted_memory_kb > 200000 ORDER BY mg.granted_memory_kb DESC"}	{"condition": "row_count > 0 AND granted_memory_kb > 200000", "description": "Queries with memory grants exceeding 200 MB are candidates for LOB/XML-related memory inflation — large grants are required when SQL Server must sort or hash-join on variable-length data"}	null	2026-02-23 20:18:31.390153
13635	mariadb	query	Check for lock waits involving replication threads	{"sql": "SELECT waiting_trx_id, waiting_pid AS waiting_thread, blocking_trx_id, blocking_pid AS blocking_thread, blocking_query FROM sys.innodb_lock_waits"}	{"condition": "row_count > 0", "description": "Lock waits involving replication threads confirm lock contention"}	\N	2026-05-11 22:17:39.229791
2081	sqlserver	query	Check for tables with LOB and XML columns used in high-memory queries	{"sql": "SELECT OBJECT_NAME(c.object_id) AS table_name, c.name AS column_name, TYPE_NAME(c.system_type_id) AS data_type, c.max_length, t.lob_data_space_id, (SELECT SUM(au.used_pages) * 8 FROM sys.allocation_units au JOIN sys.partitions p ON au.container_id = p.hobt_id WHERE p.object_id = t.object_id AND au.type = 2) AS lob_used_kb FROM sys.columns c JOIN sys.tables t ON c.object_id = t.object_id WHERE TYPE_NAME(c.system_type_id) IN ('varchar', 'nvarchar', 'varbinary', 'xml', 'text', 'ntext', 'image') AND (c.max_length = -1 OR TYPE_NAME(c.system_type_id) IN ('xml', 'text', 'ntext', 'image')) ORDER BY lob_used_kb DESC"}	{"condition": "row_count > 0 AND lob_used_kb > 100000", "description": "Tables with significant LOB/XML storage confirm that queries touching these columns require large memory grants for in-memory materialization during sorts, hash joins, and XML processing"}	null	2026-02-23 20:18:31.390153
2083	sqlserver	query	Find queries with significant spills indicating underestimated grants	{"sql": "SELECT TOP 20 qs.plan_handle, qs.execution_count, qs.total_spills, qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills_per_exec, qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb, qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb, qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_grant_kb, SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1, (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t WHERE qs.total_spills > 0 ORDER BY qs.total_spills DESC"}	{"condition": "row_count > 0 AND avg_spills_per_exec > 100", "description": "Queries with frequent tempdb spills indicate the cardinality estimator underestimated row counts, resulting in memory grants too small to hold intermediate results in memory"}	null	2026-02-23 20:18:31.390155
2084	sqlserver	query	Find queries with excessive memory grants but low usage (overestimate)	{"sql": "SELECT mg.session_id, mg.granted_memory_kb, mg.max_used_memory_kb, mg.ideal_memory_kb, CASE WHEN mg.granted_memory_kb > 0 THEN CAST(mg.max_used_memory_kb AS FLOAT) / mg.granted_memory_kb * 100 ELSE 0 END AS used_pct, r.total_elapsed_time / 1000 AS elapsed_sec, SUBSTRING(t.text, (r.statement_start_offset / 2) + 1, (CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE r.statement_end_offset END - r.statement_start_offset) / 2 + 1) AS current_statement FROM sys.dm_exec_query_memory_grants mg JOIN sys.dm_exec_requests r ON mg.session_id = r.session_id CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t WHERE mg.granted_memory_kb IS NOT NULL AND mg.granted_memory_kb > 100000 AND CASE WHEN mg.granted_memory_kb > 0 THEN CAST(mg.max_used_memory_kb AS FLOAT) / mg.granted_memory_kb * 100 ELSE 100 END < 20 ORDER BY mg.granted_memory_kb DESC"}	{"condition": "row_count > 0 AND used_pct < 20", "description": "Queries using less than 20% of their granted memory have overestimated cardinality — the optimizer expected far more rows than actually processed, reserving excessive workspace memory"}	null	2026-02-23 20:18:31.390155
2099	sqlserver	query	Find parallel queries with high memory grants and RESOURCE_SEMAPHORE impact	{"sql": "SELECT mg.session_id, mg.dop, mg.requested_memory_kb, mg.granted_memory_kb, mg.used_memory_kb, mg.max_used_memory_kb, CASE WHEN mg.dop > 0 THEN mg.granted_memory_kb / mg.dop ELSE mg.granted_memory_kb END AS per_thread_grant_kb, mg.wait_time_ms AS grant_wait_ms, mg.query_cost FROM sys.dm_exec_query_memory_grants mg WHERE mg.dop > 1 AND mg.granted_memory_kb > 200000 ORDER BY mg.granted_memory_kb DESC"}	{"condition": "row_count > 0 AND granted_memory_kb > 200000 AND dop > 4", "description": "Parallel queries consuming over 200 MB with DOP > 4 indicate parallelism is multiplying per-thread sort/hash workspace, inflating the total memory reservation"}	null	2026-02-23 20:18:31.390165
2085	sqlserver	query	Check cardinality estimator model and warnings in cached plans	{"sql": "SELECT qs.plan_handle, qs.total_spills, qs.total_grant_kb, qs.total_used_grant_kb, qp.query_plan.value('(//StmtSimple/@CardinalityEstimationModelVersion)[1]', 'int') AS ce_model_version, qp.query_plan.exist('//Warnings/SpillToTempDb') AS has_spill_warning, qp.query_plan.exist('//Warnings/ColumnsWithNoStatistics') AS has_no_stats_warning FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp WHERE qs.total_spills > 1000 OR qs.total_grant_kb / NULLIF(qs.execution_count, 0) > 500000 ORDER BY qs.total_spills DESC"}	{"condition": "has_spill_warning = 1 OR has_no_stats_warning = 1", "description": "Execution plan warnings for spills or missing statistics confirm the cardinality estimator is producing inaccurate row estimates that directly cause incorrect memory grants"}	null	2026-02-23 20:18:31.390156
2086	sqlserver	query	Find tables with stale statistics	{"sql": "SELECT OBJECT_NAME(s.object_id) AS table_name, s.name AS stat_name, s.auto_created, STATS_DATE(s.object_id, s.stats_id) AS last_updated, sp.rows AS table_rows, sp.modification_counter AS rows_modified, CASE WHEN sp.rows > 0 THEN CAST(sp.modification_counter AS FLOAT) / sp.rows * 100 ELSE 0 END AS modified_pct FROM sys.stats s CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE sp.modification_counter > 0 AND sp.rows > 1000 ORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0 AND modified_pct > 20", "description": "Statistics with more than 20% modification since last update are stale — the optimizer is using row distribution data that no longer reflects the actual data, causing incorrect cardinality estimates and memory grants"}	null	2026-02-23 20:18:31.390157
2088	sqlserver	query	Correlate stale statistics with memory grant spills	{"sql": "SELECT TOP 10 qs.plan_handle, qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills, qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb, qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_kb, SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1, (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t WHERE qs.total_spills > 0 AND qs.execution_count > 10 ORDER BY qs.total_spills / NULLIF(qs.execution_count, 0) DESC"}	{"condition": "avg_spills > 50", "description": "Queries with consistent per-execution spills across many executions confirm systematically wrong estimates from stale or missing statistics, not one-off parameter variation"}	null	2026-02-23 20:18:31.390157
2282	sqlserver	query	Check lock waits and worker thread pressure from lock contention	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests WHERE wait_type LIKE 'LCK_%') AS threads_waiting_on_locks,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS total_workers,\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_workers,\\n  (SELECT wait_time_ms / NULLIF(waiting_tasks_count, 0)\\n   FROM sys.dm_os_wait_stats WHERE wait_type = 'LCK_M_X') AS avg_exclusive_lock_wait_ms,\\n  (SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type = 'LCK_M_X') AS total_x_lock_wait_ms,\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS queued_requests"}	{"condition": "threads_waiting_on_locks > total_workers * 0.15 OR (avg_exclusive_lock_wait_ms > 5000 AND queued_requests > 0)", "description": "Many workers stuck on lock waits with potential request queuing indicates deadlock patterns consuming the thread pool"}	null	2026-02-23 20:18:31.390279
2089	sqlserver	query	Find parameterized queries with high variance in memory usage	{"sql": "SELECT qs.plan_handle, qs.execution_count, qs.min_grant_kb, qs.max_grant_kb, qs.max_grant_kb - qs.min_grant_kb AS grant_variance_kb, qs.total_spills, qs.min_spills, qs.max_spills, qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb, qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_kb, SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1, (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t WHERE qs.execution_count > 100 AND qs.total_spills > 0 AND qs.max_grant_kb > qs.min_grant_kb * 5 ORDER BY grant_variance_kb DESC"}	{"condition": "row_count > 0 AND grant_variance_kb > 100000", "description": "Queries with high grant variance (max 5x or more than min) across executions and spills indicate the cached plan's memory grant was optimized for a specific parameter that does not match the broader parameter distribution"}	null	2026-02-23 20:18:31.390158
2090	sqlserver	query	Check for sniffed parameter values in cached plans	{"sql": "SELECT qs.plan_handle, qs.execution_count, qs.total_spills, qp.query_plan.value('(//StmtSimple/QueryPlan/ParameterList/ColumnReference/@ParameterCompiledValue)[1]', 'nvarchar(256)') AS sniffed_param_1, qp.query_plan.value('(//StmtSimple/QueryPlan/ParameterList/ColumnReference/@ParameterRuntimeValue)[1]', 'nvarchar(256)') AS runtime_param_1, qp.query_plan.value('(//StmtSimple/@StatementEstRows)[1]', 'float') AS estimated_rows FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp WHERE qs.total_spills > 1000 AND qp.query_plan.exist('//StmtSimple/QueryPlan/ParameterList/ColumnReference') = 1 ORDER BY qs.total_spills DESC"}	{"condition": "sniffed_param_1 != runtime_param_1 OR row_count > 0", "description": "Different compiled vs runtime parameter values in the execution plan confirm the plan was compiled for one parameter value and is being reused for a different value, causing memory grant mismatch"}	null	2026-02-23 20:18:31.390158
2092	sqlserver	query	Check for mismatched column types in joins and filters	{"sql": "SELECT qp.query_plan.value('(//Warnings/PlanAffectingConvert/@Expression)[1]', 'nvarchar(500)') AS convert_expression, qp.query_plan.value('(//Warnings/PlanAffectingConvert/@ConvertIssue)[1]', 'nvarchar(100)') AS convert_issue, qs.total_spills, qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb, qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_kb FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp WHERE qp.query_plan.exist('//Warnings/PlanAffectingConvert') = 1 AND (qs.total_spills > 0 OR qs.total_grant_kb / NULLIF(qs.execution_count, 0) > 100000) ORDER BY qs.total_spills DESC"}	{"condition": "row_count > 0 AND convert_issue = 'Seek Plan' OR convert_issue = 'Cardinality Estimate'", "description": "Implicit conversions flagged as affecting cardinality estimates or preventing seek plans confirm the optimizer cannot use column statistics, defaulting to fixed estimate ratios that produce wrong memory grants"}	null	2026-02-23 20:18:31.39016
2831	sqlserver	query	Check tempdb activity level to assess audit gap impact	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Temp Tables Creation Rate' AND instance_name = '') AS temp_table_rate,\\n  (SELECT COUNT(*) FROM tempdb.sys.objects WHERE type IN ('U', 'TT') AND is_ms_shipped = 0) AS current_temp_objects,\\n  (SELECT SUM(user_object_reserved_page_count) * 8 / 1024 FROM sys.dm_db_file_space_usage) AS user_objects_mb_in_tempdb"}	{"condition": "current_temp_objects > 0 or user_objects_mb_in_tempdb > 100", "description": "Active tempdb usage with unmonitored DDL — significant audit blind spot"}	null	2026-02-23 20:18:31.39061
2093	sqlserver	query	Find queries with many joins and high spill rates	{"sql": "SELECT TOP 20 qs.plan_handle, qs.execution_count, qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills, qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb, qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_kb, qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\"])', 'int') AS hash_join_count, qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Sort\\"])', 'int') AS sort_count, qp.query_plan.value('count(//RelOp)', 'int') AS total_operators FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp WHERE qs.total_spills > 0 AND qs.execution_count > 10 ORDER BY qs.total_spills / NULLIF(qs.execution_count, 0) DESC"}	{"condition": "row_count > 0 AND (hash_join_count > 2 OR total_operators > 30)", "description": "Queries with multiple hash joins or complex plans (>30 operators) with consistent spills indicate the optimizer is miscalculating intermediate row counts at the join boundaries, causing cascading estimation errors that affect memory grants"}	null	2026-02-23 20:18:31.39016
2094	sqlserver	query	Check for large estimation errors in query plan operators	{"sql": "SELECT qs.plan_handle, qs.total_spills, qp.query_plan.value('(//RelOp[@PhysicalOp=\\"Hash Match\\"]/@EstimateRows)[1]', 'float') AS hash_estimated_rows, qp.query_plan.value('(//RelOp[@PhysicalOp=\\"Hash Match\\"]/@ActualRows)[1]', 'float') AS hash_actual_rows, qp.query_plan.value('(//RelOp[@PhysicalOp=\\"Sort\\"]/@EstimateRows)[1]', 'float') AS sort_estimated_rows, qp.query_plan.value('(//RelOp[@PhysicalOp=\\"Sort\\"]/@ActualRows)[1]', 'float') AS sort_actual_rows FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp WHERE qs.total_spills > 1000 AND (qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\"]') = 1 OR qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Sort\\"]') = 1) ORDER BY qs.total_spills DESC"}	{"condition": "hash_actual_rows > hash_estimated_rows * 10 OR sort_actual_rows > sort_estimated_rows * 10", "description": "Actual row counts exceeding estimates by 10x or more at hash join or sort operators confirm complex join predicates are causing the optimizer to grossly underestimate cardinality, resulting in insufficient memory grants and tempdb spills"}	null	2026-02-23 20:18:31.390161
4312	postgresql	query	Check pg_cron run details for unscheduled executions during business hours	{"sql": "SELECT jobid, command, start_time, end_time, status FROM cron.job_run_details WHERE EXTRACT(HOUR FROM start_time) BETWEEN 8 AND 17 AND start_time > now() - interval '7 days' ORDER BY start_time DESC"}	{"condition": "row_count > 0", "description": "Job executions found during business hours that may include manual triggers"}	\N	2026-02-25 00:28:52.405273
2116	sqlserver	query	Check for queries hitting memory grant limits or timing out	{"sql": "SELECT mg.session_id, mg.requested_memory_kb, mg.granted_memory_kb, mg.required_memory_kb, mg.ideal_memory_kb, mg.wait_time_ms AS grant_wait_ms, mg.is_small, CASE WHEN mg.ideal_memory_kb > mg.granted_memory_kb THEN 'CAPPED_BELOW_IDEAL' WHEN mg.granted_memory_kb IS NULL THEN 'WAITING_FOR_GRANT' ELSE 'GRANTED' END AS grant_status FROM sys.dm_exec_query_memory_grants mg ORDER BY mg.wait_time_ms DESC"}	{"condition": "grant_status = 'CAPPED_BELOW_IDEAL' OR grant_status = 'WAITING_FOR_GRANT'", "description": "Queries capped below their ideal memory or waiting for grants indicate the memory grant boundaries are too restrictive, forcing sorts and hash joins to spill to tempdb"}	null	2026-02-23 20:18:31.390176
2095	sqlserver	query	Find queries with hash spools or lazy spools indicating correlated subquery materialization	{"sql": "SELECT TOP 20 qs.plan_handle, qs.execution_count, qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb, qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills, qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Spool\\" or @PhysicalOp=\\"Index Spool\\" or @PhysicalOp=\\"Row Count Spool\\"])', 'int') AS spool_count, qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\"])', 'int') AS hash_count, SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1, (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t WHERE qs.total_grant_kb / NULLIF(qs.execution_count, 0) > 200000 AND qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Spool\\" or @PhysicalOp=\\"Index Spool\\"])', 'int') > 0 ORDER BY qs.total_grant_kb / NULLIF(qs.execution_count, 0) DESC"}	{"condition": "row_count > 0 AND spool_count > 0 AND avg_grant_kb > 200000", "description": "Queries with spool operators and large memory grants indicate the optimizer is materializing correlated subquery results — each spool builds a temporary structure in workspace memory to avoid re-evaluating the subquery for every outer row"}	null	2026-02-23 20:18:31.390162
2096	sqlserver	query	Check for RESOURCE_SEMAPHORE waits from high-memory subquery plans	{"sql": "SELECT (SELECT wait_time_ms FROM sys.dm_os_wait_stats WHERE wait_type = 'RESOURCE_SEMAPHORE') AS resource_semaphore_wait_ms, (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE granted_memory_kb IS NULL) AS pending_grants, (SELECT SUM(granted_memory_kb) FROM sys.dm_exec_query_memory_grants WHERE granted_memory_kb IS NOT NULL) AS total_granted_kb, (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE granted_memory_kb > 200000) AS large_grant_count"}	{"condition": "resource_semaphore_wait_ms > 0 OR pending_grants > 0 OR large_grant_count > 3", "description": "Memory pressure from correlated subquery plans is confirmed by RESOURCE_SEMAPHORE waits or multiple concurrent large grants consuming the workspace memory pool"}	null	2026-02-23 20:18:31.390162
2097	sqlserver	query	Find statistics with high density variance indicating skewed data	{"sql": "SELECT OBJECT_NAME(s.object_id) AS table_name, s.name AS stat_name, COL_NAME(s.object_id, sc.column_id) AS column_name, sp.rows, sp.rows_sampled, sp.unfiltered_rows, sp.modification_counter, CASE WHEN sp.rows > 0 THEN CAST(sp.modification_counter AS FLOAT) / sp.rows * 100 ELSE 0 END AS modified_pct FROM sys.stats s JOIN sys.stats_columns sc ON s.object_id = sc.object_id AND s.stats_id = sc.stats_id AND sc.stats_column_id = 1 CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE sp.rows > 10000 ORDER BY sp.rows DESC"}	{"condition": "row_count > 0", "description": "Large tables with statistics are candidates for data skew analysis — the histogram covers at most 200 steps, so tables with more than 200 distinct values may have unrepresented skew"}	null	2026-02-23 20:18:31.390163
2098	sqlserver	query	Check for queries with spills on tables likely to have skewed distributions	{"sql": "SELECT TOP 10 qs.plan_handle, qs.execution_count, qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills, qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb, qs.last_grant_kb, qs.last_used_grant_kb, ABS(qs.last_grant_kb - qs.last_used_grant_kb) AS last_grant_diff_kb, SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1, (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text) ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t WHERE qs.total_spills > 0 AND qs.execution_count > 50 AND ABS(qs.max_grant_kb - qs.min_grant_kb) > 50000 ORDER BY ABS(qs.max_grant_kb - qs.min_grant_kb) DESC"}	{"condition": "row_count > 0 AND last_grant_diff_kb > 50000", "description": "High variance between granted and used memory across executions confirms data skew — some parameter values hit dense regions of the distribution (many rows), while others hit sparse regions (few rows), causing wildly different actual memory needs"}	null	2026-02-23 20:18:31.390163
2143	sqlserver	query	Identify top scan-heavy queries from plan cache	{"sql": "SELECT TOP 10\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.execution_count,\\n  qs.total_logical_reads,\\n  qs.total_physical_reads,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_logical_reads / qs.execution_count > 10000\\n  AND qs.execution_count > 10\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "queries with avg_logical_reads > 10000 executing frequently", "description": "Frequently executed queries reading thousands of pages per execution indicate scan-heavy workload"}	null	2026-02-23 20:18:31.390164
2100	sqlserver	query	Check server MAXDOP and cost threshold configuration	{"sql": "SELECT (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max degree of parallelism') AS maxdop, (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'cost threshold for parallelism') AS cost_threshold, (SELECT cpu_count FROM sys.dm_os_sys_info) AS logical_cpus, (SELECT numa_node_count FROM sys.dm_os_sys_info) AS numa_nodes, CASE WHEN (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max degree of parallelism') = 0 THEN (SELECT cpu_count FROM sys.dm_os_sys_info) ELSE (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'max degree of parallelism') END AS effective_maxdop"}	{"condition": "maxdop = 0 OR maxdop > 8 OR cost_threshold <= 5", "description": "MAXDOP=0 (unlimited) or >8 with low cost threshold allows too many queries to go parallel at high DOP, each multiplying their memory grant by DOP"}	null	2026-02-23 20:18:31.390165
2101	sqlserver	query	Check RESOURCE_SEMAPHORE waits and memory grant queue	{"sql": "SELECT ws.wait_type, ws.waiting_tasks_count, ws.wait_time_ms, ws.wait_time_ms / NULLIF(ws.waiting_tasks_count, 0) AS avg_wait_ms FROM sys.dm_os_wait_stats ws WHERE ws.wait_type IN ('RESOURCE_SEMAPHORE', 'RESOURCE_SEMAPHORE_QUERY_COMPILE', 'RESOURCE_SEMAPHORE_MUTEX') AND ws.waiting_tasks_count > 0"}	{"condition": "RESOURCE_SEMAPHORE waiting_tasks_count > 0", "description": "Active RESOURCE_SEMAPHORE waits confirm workspace memory is exhausted — high-DOP queries have consumed the available grant pool, forcing subsequent queries to queue"}	null	2026-02-23 20:18:31.390166
