2248	sqlserver	query	Check critical server configuration settings	{"sql": "SELECT\\n  c.name, c.value_in_use, c.minimum, c.maximum,\\n  CASE\\n    WHEN c.name = 'max degree of parallelism' AND c.value_in_use = 0 THEN 'SUBOPTIMAL: MAXDOP=0 allows unlimited parallelism'\\n    WHEN c.name = 'cost threshold for parallelism' AND c.value_in_use = 5 THEN 'SUBOPTIMAL: default threshold too low for modern hardware'\\n    WHEN c.name = 'max server memory (MB)' AND c.value_in_use = 2147483647 THEN 'SUBOPTIMAL: unlimited memory may cause OS pressure'\\n    WHEN c.name = 'optimize for ad hoc workloads' AND c.value_in_use = 0 THEN 'SUBOPTIMAL: plan cache may bloat with single-use plans'\\n    ELSE 'OK'\\n  END AS assessment\\nFROM sys.configurations c\\nWHERE c.name IN (\\n  'max degree of parallelism', 'cost threshold for parallelism',\\n  'max server memory (MB)', 'optimize for ad hoc workloads',\\n  'max worker threads', 'min memory per query (KB)'\\n)"}	{"condition": "any assessment = 'SUBOPTIMAL'", "description": "Suboptimal server configuration settings detected that affect query execution"}	null	2026-02-23 20:18:31.390255
2249	sqlserver	query	Check database-level configuration settings	{"sql": "SELECT\\n  d.name AS database_name,\\n  d.compatibility_level,\\n  d.is_auto_update_stats_on,\\n  d.is_auto_create_stats_on,\\n  d.is_auto_update_stats_async_on,\\n  d.is_read_committed_snapshot_on,\\n  d.is_parameterization_forced,\\n  d.page_verify_option_desc,\\n  CASE\\n    WHEN d.is_auto_update_stats_on = 0 THEN 'CRITICAL: auto update stats disabled'\\n    WHEN d.is_auto_create_stats_on = 0 THEN 'CRITICAL: auto create stats disabled'\\n    WHEN d.compatibility_level < 130 THEN 'SUBOPTIMAL: old compatibility level misses optimizer improvements'\\n    WHEN d.page_verify_option_desc <> 'CHECKSUM' THEN 'SUBOPTIMAL: page verify should be CHECKSUM'\\n    ELSE 'OK'\\n  END AS assessment\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "any assessment contains 'CRITICAL' or 'SUBOPTIMAL'", "description": "Database-level misconfigurations affecting query optimization and statistics maintenance"}	null	2026-02-23 20:18:31.390256
2330	sqlserver	query	Check database compatibility level and IQP feature availability	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  CASE\\n    WHEN d.compatibility_level < 140 THEN 'No IQP features'\\n    WHEN d.compatibility_level = 140 THEN 'Batch mode adaptive joins + batch MGF'\\n    WHEN d.compatibility_level = 150 THEN 'Full IQP: adaptive joins, row+batch MGF, interleaved exec, table variable deferred compile'\\n    WHEN d.compatibility_level >= 160 THEN 'Full IQP + CE feedback + DOP feedback + optimized plan forcing'\\n    ELSE 'Unknown'\\n  END AS iqp_features,\\n  d.is_query_store_on\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "compatibility_level < 140", "description": "Database running at compatibility level below 140 — no adaptive query execution features available"}	null	2026-02-23 20:18:31.390256
9921	mysql	query	Check replication status and configuration	{"sql": "SELECT CHANNEL_NAME, SERVICE_STATE, SOURCE_UUID, RECEIVED_TRANSACTION_SET FROM performance_schema.replication_connection_status UNION ALL SELECT '', 'applier', '', '' FROM performance_schema.replication_applier_status WHERE SERVICE_STATE = 'ON' LIMIT 5"}	{"condition": "row_count > 0", "description": "This is a replica, configuration sync should be checked"}	\N	2026-03-01 06:30:58.706791
2251	sqlserver	query	Check for table scans with corresponding missing index recommendations	{"sql": "SELECT TOP 20\\n  mid.statement AS table_name,\\n  mid.equality_columns, mid.inequality_columns, mid.included_columns,\\n  migs.user_seeks, migs.user_scans,\\n  migs.avg_total_user_cost, migs.avg_user_impact,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure,\\n  migs.last_user_seek, migs.last_user_scan\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE mid.database_id = DB_ID()\\n  AND migs.user_seeks + migs.user_scans > 100\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND improvement_measure > 5000", "description": "High-impact missing index recommendations with frequent seeks/scans confirm queries scanning without proper indexes"}	null	2026-02-23 20:18:31.390258
2252	sqlserver	query	Correlate table scan activity with missing index tables	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.type_desc AS current_index_type,\\n  ius.user_scans AS heap_or_ci_scans,\\n  ius.user_seeks,\\n  p.rows AS table_rows,\\n  CASE WHEN (ius.user_scans + ius.user_seeks) > 0\\n    THEN CAST(ius.user_scans AS FLOAT) / (ius.user_scans + ius.user_seeks) * 100\\n    ELSE 0 END AS scan_pct\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.partitions p ON ius.object_id = p.object_id AND ius.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.index_id IN (0, 1)\\n  AND ius.user_scans > 100\\n  AND p.rows > 10000\\nORDER BY ius.user_scans DESC"}	{"condition": "scan_pct > 60 AND table_rows > 10000", "description": "Tables with 10K+ rows where over 60% of access is scans confirm missing indexes forcing full table reads"}	null	2026-02-23 20:18:31.390258
2382	sqlserver	query	Check for excessive single-use ad-hoc plans indicating EXEC-based dynamic SQL	{"sql": "SELECT\\n  cp.objtype,\\n  COUNT(*) AS plan_count,\\n  SUM(cp.usecounts) AS total_uses,\\n  SUM(cp.size_in_bytes) / 1024 / 1024 AS total_mb,\\n  SUM(CASE WHEN cp.usecounts = 1 THEN 1 ELSE 0 END) AS single_use_count,\\n  CAST(SUM(CASE WHEN cp.usecounts = 1 THEN 1 ELSE 0 END) AS FLOAT) / NULLIF(COUNT(*), 0) * 100 AS single_use_pct\\nFROM sys.dm_exec_cached_plans cp\\nWHERE cp.cacheobjtype = 'Compiled Plan'\\nGROUP BY cp.objtype\\nORDER BY plan_count DESC"}	{"condition": "single_use_pct > 60 for objtype = 'Adhoc'", "description": "High single-use ad-hoc plan percentage suggests dynamic SQL via EXEC concatenating values instead of parameterizing"}	null	2026-02-23 20:18:31.390259
