2253	sqlserver	query	Find parallel queries with high CXPACKET/CXCONSUMER waits	{"sql": "SELECT TOP 20\\n  qs.query_hash, qs.query_plan_hash,\\n  qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us,\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.execution_count,\\n  CAST(qs.total_elapsed_time - qs.total_worker_time AS FLOAT) / NULLIF(qs.execution_count, 0) AS avg_wait_us,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_worker_time / NULLIF(qs.execution_count, 0) > 0\\n  AND (qs.total_elapsed_time - qs.total_worker_time) > qs.total_worker_time * 0.5\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "avg_wait_us > avg_cpu_us * 0.5 for parallel queries", "description": "Parallel queries where elapsed time far exceeds CPU time indicate thread imbalance — some threads finish early and wait"}	null	2026-02-23 20:18:31.39026
2254	sqlserver	query	Check for skewed statistics on columns in parallel query plans	{"sql": "SELECT\\n  s.name AS stat_name,\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  sp.last_updated,\\n  sp.rows, sp.rows_sampled,\\n  sp.steps AS histogram_steps,\\n  sp.unfiltered_rows,\\n  CASE WHEN sp.rows_sampled < sp.rows * 0.5 THEN 'LOW_SAMPLE' ELSE 'OK' END AS sample_quality\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 100000\\n  AND sp.modification_counter > sp.rows * 0.1\\nORDER BY sp.modification_counter DESC"}	{"condition": "modification_counter > rows * 0.1 on large tables", "description": "Stale statistics on large tables cause the optimizer to distribute parallel work based on inaccurate row estimates, amplifying skew"}	null	2026-02-23 20:18:31.39026
2255	sqlserver	query	Check CXPACKET and CXCONSUMER cumulative waits	{"sql": "SELECT\\n  wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  CASE WHEN waiting_tasks_count > 0\\n    THEN wait_time_ms / waiting_tasks_count ELSE 0 END AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER')\\nORDER BY wait_time_ms DESC"}	{"condition": "CXPACKET wait_time_ms is among top 5 waits and avg_wait_ms > 50", "description": "High CXPACKET waits with significant average wait time confirm parallel thread imbalance from data skew"}	null	2026-02-23 20:18:31.390261
2256	sqlserver	query	Check partition row distribution for skew	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(p.object_id) + '.' + OBJECT_NAME(p.object_id) AS table_name,\\n  ps.name AS partition_scheme,\\n  p.partition_number,\\n  p.rows,\\n  SUM(p.rows) OVER (PARTITION BY p.object_id) AS total_rows,\\n  CAST(p.rows AS FLOAT) / NULLIF(SUM(p.rows) OVER (PARTITION BY p.object_id), 0) * 100 AS pct_of_total,\\n  COUNT(*) OVER (PARTITION BY p.object_id) AS partition_count\\nFROM sys.partitions p\\nJOIN sys.indexes i ON p.object_id = i.object_id AND p.index_id = i.index_id\\nLEFT JOIN sys.partition_schemes ps ON i.data_space_id = ps.data_space_id\\nWHERE p.index_id IN (0, 1)\\n  AND p.rows > 0\\nORDER BY p.object_id, p.partition_number"}	{"condition": "MAX(pct_of_total) > 50 when partition_count >= 4", "description": "One partition holding more than 50% of rows when 4+ partitions exist indicates severe partition skew"}	null	2026-02-23 20:18:31.390261
3274	sqlserver	query	Check for user-defined extended stored procedures with their DLL paths	{"sql": "SELECT o.name AS xproc_name,\\n  o.type_desc, o.create_date,\\n  OBJECT_DEFINITION(o.object_id) AS definition,\\n  SCHEMA_NAME(o.schema_id) AS schema_name\\nFROM sys.objects o\\nWHERE o.type = 'X'\\n  AND o.is_ms_shipped = 0"}	{"condition": "row_count > 0", "description": "User-defined extended stored procedures found — custom DLLs loaded into SQL Server process space"}	null	2026-02-23 20:18:31.390883
2257	sqlserver	query	Check if partitioned tables are used in parallel queries with high waits	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us,\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.execution_count,\\n  qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') AS has_parallelism,\\n  qp.query_plan.exist('//RelOp[contains(@PhysicalOp,\\"Scan\\")]/*/Object[@Partitioned=\\"1\\"]') AS scans_partitioned_table\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') = 1\\n  AND (qs.total_elapsed_time - qs.total_worker_time) > qs.total_worker_time * 0.3\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "scans_partitioned_table = 1 on queries with high elapsed-to-cpu ratio", "description": "Parallel queries scanning partitioned tables with high wait time confirms partition skew causing thread imbalance"}	null	2026-02-23 20:18:31.390262
2258	sqlserver	query	Find parallel hash join/aggregate queries with high CXPACKET waits	{"sql": "SELECT TOP 15\\n  qs.query_hash, qs.query_plan_hash,\\n  qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us,\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.execution_count,\\n  qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\"]') AS has_hash_match,\\n  qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') AS has_parallelism\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\"]') = 1\\n  AND qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') = 1\\n  AND (qs.total_elapsed_time - qs.total_worker_time) > qs.total_worker_time * 0.5\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "row_count > 0 with has_hash_match = 1 AND avg_elapsed_us >> avg_cpu_us", "description": "Parallel hash match queries with disproportionate elapsed vs CPU time suggest hash distribution skew"}	null	2026-02-23 20:18:31.390263
2259	sqlserver	query	Check for low-cardinality join columns driving hash collisions	{"sql": "SELECT TOP 10\\n  OBJECT_SCHEMA_NAME(ic.object_id) + '.' + OBJECT_NAME(ic.object_id) AS table_name,\\n  c.name AS column_name,\\n  s.name AS stat_name,\\n  sp.rows AS total_rows,\\n  sp.steps AS histogram_steps,\\n  CASE WHEN sp.steps > 0\\n    THEN sp.rows / sp.steps ELSE sp.rows END AS est_rows_per_bucket\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.stats_columns ic ON s.object_id = ic.object_id AND s.stats_id = ic.stats_id\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nWHERE sp.rows > 100000\\n  AND sp.steps < 20\\nORDER BY sp.rows DESC"}	{"condition": "histogram_steps < 20 on tables with > 100K rows", "description": "Low cardinality (few distinct values) on large tables means hash distribution across parallel threads will be uneven"}	null	2026-02-23 20:18:31.390263
2260	sqlserver	query	Find parallel scan queries with high wait-to-cpu ratio	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  qs.total_elapsed_time / qs.execution_count AS avg_elapsed_us,\\n  qs.total_worker_time / qs.execution_count AS avg_cpu_us,\\n  qs.execution_count,\\n  qp.query_plan.exist('//RelOp[contains(@PhysicalOp,\\"Scan\\")]') AS has_scan,\\n  qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\" and @PhysicalOp=\\"Distribute Streams\\"]') AS has_distribute_streams,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[contains(@PhysicalOp,\\"Scan\\")]') = 1\\n  AND qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') = 1\\n  AND (qs.total_elapsed_time - qs.total_worker_time) > qs.total_worker_time * 0.4\\n  AND qs.execution_count > 5\\nORDER BY (qs.total_elapsed_time - qs.total_worker_time) / NULLIF(qs.execution_count, 0) DESC"}	{"condition": "row_count > 0 with avg_elapsed_us > avg_cpu_us * 1.5", "description": "Parallel scans with consistently high elapsed vs CPU time suggest uneven range splitting"}	null	2026-02-23 20:18:31.390264
4018	postgresql	query	Check archive success-to-failure ratio	{"sql": "SELECT archived_count, failed_count, CASE WHEN (archived_count + failed_count) > 0 THEN round(failed_count::numeric / (archived_count + failed_count) * 100, 2) ELSE 0 END AS failure_pct FROM pg_stat_archiver"}	{"condition": "failure_pct > :min_pct AND failure_pct < :max_pct AND archived_count > 0", "description": "Low but non-zero failure rate indicates intermittent storage issues"}	{"max_pct": 20, "min_pct": 1}	2026-02-25 00:28:52.405273
2261	sqlserver	query	Check stale statistics that would cause inaccurate range estimation	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows, sp.rows_sampled, sp.modification_counter,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update,\\n  CAST(sp.modification_counter AS FLOAT) / NULLIF(sp.rows, 0) * 100 AS pct_modified\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 50000\\n  AND (sp.modification_counter > sp.rows * 0.2\\n    OR DATEDIFF(DAY, sp.last_updated, GETDATE()) > 7)\\nORDER BY sp.modification_counter DESC"}	{"condition": "modification_counter > 20% of rows or stats older than 7 days", "description": "Outdated statistics cause the optimizer to split parallel ranges based on stale histograms, resulting in uneven work distribution"}	null	2026-02-23 20:18:31.390265
2262	sqlserver	query	Check for parallel queries with threads waiting on external resources	{"sql": "SELECT\\n  er.session_id, er.request_id,\\n  ot.exec_context_id AS thread_id,\\n  ot.scheduler_id,\\n  er.parallel_worker_count,\\n  ot.task_state,\\n  owt.wait_type,\\n  owt.wait_duration_ms,\\n  owt.resource_description\\nFROM sys.dm_exec_requests er\\nJOIN sys.dm_os_tasks ot ON er.session_id = ot.session_id AND er.request_id = ot.request_id\\nLEFT JOIN sys.dm_os_waiting_tasks owt ON ot.task_address = owt.waiting_task_address\\nWHERE er.parallel_worker_count > 0\\n  AND owt.wait_type IN ('ASYNC_NETWORK_IO', 'OLEDB', 'PAGEIOLATCH_SH', 'PAGEIOLATCH_EX',\\n    'IO_COMPLETION', 'WRITELOG', 'NETWORKIO', 'PREEMPTIVE_OS_WAITFORSINGLEOBJECT',\\n    'PREEMPTIVE_OLEDBOPS')\\nORDER BY owt.wait_duration_ms DESC"}	{"condition": "parallel threads with external wait_type and wait_duration_ms > 1000", "description": "Parallel threads blocked on I/O, network, or linked server calls while other threads in the same query are idle"}	null	2026-02-23 20:18:31.390265
2263	sqlserver	query	Check cumulative PAGEIOLATCH and external wait stats	{"sql": "SELECT\\n  wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  CASE WHEN waiting_tasks_count > 0\\n    THEN wait_time_ms / waiting_tasks_count ELSE 0 END AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'IO_COMPLETION',\\n  'ASYNC_NETWORK_IO', 'OLEDB', 'PREEMPTIVE_OLEDBOPS', 'CXPACKET')\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH or OLEDB avg_wait_ms > 20 combined with high CXPACKET waits", "description": "External resource latency combined with CXPACKET confirms some parallel threads are stalled on I/O or remote calls"}	null	2026-02-23 20:18:31.390266
2597	sqlserver	query	Check sa account status and last usage	{"sql": "SELECT sp.name, sp.is_disabled,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY('sa', 'PasswordLastSetTime') AS password_last_set,\\n  LOGINPROPERTY('sa', 'BadPasswordCount') AS bad_password_count,\\n  LOGINPROPERTY('sa', 'LockoutTime') AS lockout_time,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions\\n   WHERE original_login_name = 'sa') AS last_sa_session\\nFROM sys.server_principals sp\\nLEFT JOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sp.sid = 0x01\\n  AND sp.is_disabled = 0"}	{"condition": "row_count > 0", "description": "The sa account is enabled — potentially kept as a recovery backdoor"}	null	2026-02-23 20:18:31.390489
2264	sqlserver	query	Find queries with high plan-to-actual row variance in parallel plans	{"sql": "SELECT TOP 15\\n  qs.query_hash, qs.query_plan_hash,\\n  qs.execution_count,\\n  qs.min_elapsed_time / 1000 AS min_elapsed_ms,\\n  qs.max_elapsed_time / 1000 AS max_elapsed_ms,\\n  (qs.max_elapsed_time - qs.min_elapsed_time) / 1000 AS elapsed_range_ms,\\n  qs.min_worker_time / 1000 AS min_cpu_ms,\\n  qs.max_worker_time / 1000 AS max_cpu_ms,\\n  CAST(qs.max_elapsed_time AS FLOAT) / NULLIF(qs.min_elapsed_time, 0) AS elapsed_variance_ratio\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') = 1\\n  AND qs.execution_count > 10\\n  AND qs.max_elapsed_time > qs.min_elapsed_time * 5\\nORDER BY elapsed_variance_ratio DESC"}	{"condition": "elapsed_variance_ratio > 5 on queries with execution_count > 10", "description": "Wide performance variance in a parallel plan suggests the cached plan is optimal for some parameter values but causes skew for others"}	null	2026-02-23 20:18:31.390266
2265	sqlserver	query	Check for parameter-sensitive plans in plan cache	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.query_plan_hash,\\n  qs.execution_count,\\n  qp.query_plan.value('(//ParameterList/ColumnReference/@ParameterCompiledValue)[1]', 'nvarchar(100)') AS sniffed_param_1,\\n  qp.query_plan.value('(//ParameterList/ColumnReference/@ParameterRuntimeValue)[1]', 'nvarchar(100)') AS runtime_param_1,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.max_elapsed_time > qs.min_elapsed_time * 5\\n  AND qs.execution_count > 10\\n  AND qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') = 1\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "sniffed_param_1 <> runtime_param_1 on high-variance queries", "description": "Parameter values differ between compile time and runtime, confirming the plan was optimized for a different data distribution"}	null	2026-02-23 20:18:31.390267
2266	sqlserver	query	Check for parallel query thread creation delays	{"sql": "SELECT\\n  wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  CASE WHEN waiting_tasks_count > 0\\n    THEN wait_time_ms / waiting_tasks_count ELSE 0 END AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('CXPACKET', 'CXCONSUMER', 'EXECSYNC',\\n  'EXCHANGE', 'CXROWSET_SYNC')\\nORDER BY wait_time_ms DESC"}	{"condition": "EXECSYNC or CXROWSET_SYNC avg_wait_ms > 10", "description": "Elevated EXECSYNC/CXROWSET_SYNC waits indicate delays in synchronizing parallel thread startup"}	null	2026-02-23 20:18:31.390268
2267	sqlserver	query	Check scheduler pressure that could delay thread allocation	{"sql": "SELECT\\n  scheduler_id, cpu_id,\\n  current_tasks_count, runnable_tasks_count,\\n  active_workers_count, work_queue_count,\\n  pending_disk_io_count,\\n  CASE WHEN runnable_tasks_count > 0 THEN 'PRESSURE' ELSE 'OK' END AS scheduler_state\\nFROM sys.dm_os_schedulers\\nWHERE scheduler_id < 255\\n  AND is_online = 1\\nORDER BY runnable_tasks_count DESC"}	{"condition": "runnable_tasks_count > 0 on multiple schedulers", "description": "Runnable queue backup on schedulers delays parallel thread startup, causing staggered execution"}	null	2026-02-23 20:18:31.390268
2268	sqlserver	query	Check current vs max worker threads	{"sql": "SELECT\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_worker_threads,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS current_workers,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers WHERE is_preemptive = 1) AS preemptive_workers,\\n  (SELECT SUM(active_workers_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS active_workers,\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS queued_requests,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Processes blocked' AND object_name LIKE '%General Statistics%') AS processes_blocked"}	{"condition": "current_workers > max_worker_threads * 0.9 OR queued_requests > 0", "description": "Worker thread pool at or near capacity, with requests queuing on schedulers"}	null	2026-02-23 20:18:31.390269
2269	sqlserver	query	Check THREADPOOL waits and worker allocation rate	{"sql": "SELECT\\n  wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  CASE WHEN waiting_tasks_count > 0\\n    THEN wait_time_ms / waiting_tasks_count ELSE 0 END AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type = 'THREADPOOL'\\n\\nUNION ALL\\n\\nSELECT\\n  'CURRENT_STATE' AS wait_type,\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS wait_time_ms,\\n  (SELECT SUM(runnable_tasks_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS waiting_tasks_count,\\n  0 AS avg_wait_ms"}	{"condition": "THREADPOOL waiting_tasks_count > 0 OR work_queue_count > 0", "description": "THREADPOOL waits confirm requests are queuing because no worker threads are available"}	null	2026-02-23 20:18:31.390269
2270	sqlserver	query	Check worker thread capacity vs OS-level indicators	{"sql": "SELECT\\n  si.max_workers_count,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS current_workers,\\n  si.physical_memory_kb / 1024 AS physical_memory_mb,\\n  si.committed_kb / 1024 AS committed_mb,\\n  si.committed_target_kb / 1024 AS committed_target_mb,\\n  si.virtual_memory_kb / 1024 AS virtual_memory_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Total Server Memory (KB)' AND object_name LIKE '%Memory Manager%') / 1024 AS server_memory_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Target Server Memory (KB)' AND object_name LIKE '%Memory Manager%') / 1024 AS target_memory_mb\\nFROM sys.dm_os_sys_info si"}	{"condition": "current_workers < max_workers_count * 0.5 AND committed_mb close to virtual_memory_mb", "description": "SQL Server unable to create workers up to max despite demand, suggesting OS memory or thread limits"}	null	2026-02-23 20:18:31.39027
2272	sqlserver	query	Find head blockers and chain depth	{"sql": "WITH BlockingChain AS (\\n  SELECT\\n    session_id,\\n    blocking_session_id,\\n    wait_type,\\n    wait_time,\\n    1 AS chain_depth\\n  FROM sys.dm_exec_requests\\n  WHERE blocking_session_id <> 0\\n\\n  UNION ALL\\n\\n  SELECT\\n    r.session_id,\\n    r.blocking_session_id,\\n    r.wait_type,\\n    r.wait_time,\\n    bc.chain_depth + 1\\n  FROM sys.dm_exec_requests r\\n  JOIN BlockingChain bc ON r.blocking_session_id = bc.session_id\\n  WHERE r.blocking_session_id <> 0 AND bc.chain_depth < 10\\n)\\nSELECT\\n  blocking_session_id AS head_blocker,\\n  COUNT(DISTINCT session_id) AS blocked_sessions,\\n  MAX(chain_depth) AS max_chain_depth,\\n  MAX(wait_time) / 1000 AS max_wait_sec\\nFROM BlockingChain\\nWHERE blocking_session_id NOT IN (\\n  SELECT session_id FROM sys.dm_exec_requests WHERE blocking_session_id <> 0\\n)\\nGROUP BY blocking_session_id\\nHAVING COUNT(DISTINCT session_id) > 5"}	{"condition": "head blocker with blocked_sessions > 5 OR max_chain_depth > 3", "description": "A single head blocker holding many sessions indicates worker thread consumption from blocking chains"}	null	2026-02-23 20:18:31.390272
2273	sqlserver	query	Check worker thread consumption from blocked sessions	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests WHERE blocking_session_id <> 0) AS blocked_request_count,\\n  (SELECT COUNT(*) FROM sys.dm_os_workers) AS total_workers,\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_workers,\\n  (SELECT SUM(work_queue_count) FROM sys.dm_os_schedulers WHERE scheduler_id < 255) AS queued_requests,\\n  CAST((SELECT COUNT(*) FROM sys.dm_exec_requests WHERE blocking_session_id <> 0) AS FLOAT)\\n    / NULLIF((SELECT max_workers_count FROM sys.dm_os_sys_info), 0) * 100 AS pct_workers_blocked"}	{"condition": "pct_workers_blocked > 20 OR queued_requests > 0", "description": "Significant percentage of workers consumed by blocked sessions, with potential request queuing"}	null	2026-02-23 20:18:31.390273
11598	mysql	query	Check SSL certificate age	{"sql": "SHOW STATUS LIKE 'Ssl_server_not_before';"}	{"condition": "DATEDIFF(NOW(), STR_TO_DATE(value, '%b %d %H:%i:%s %Y')) > 365", "description": "SSL certificate is older than one year without rotation"}	{"max_cert_age_days": 365}	2026-03-01 06:30:58.706791
2274	sqlserver	query	Check current connection count and login rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'User Connections' AND object_name LIKE '%General Statistics%') AS user_connections,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec' AND object_name LIKE '%General Statistics%') AS logins_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logouts/sec' AND object_name LIKE '%General Statistics%') AS logouts_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Connection Reset/sec' AND object_name LIKE '%General Statistics%') AS connection_resets_per_sec,\\n  (SELECT max_workers_count FROM sys.dm_os_sys_info) AS max_workers,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS active_user_sessions"}	{"condition": "user_connections > max_workers * 0.8 OR logins_per_sec > 50", "description": "High connection count approaching worker limit or abnormally high login rate indicates connection storm"}	null	2026-02-23 20:18:31.390273
2275	sqlserver	query	Check for connection storm patterns by application and host	{"sql": "SELECT TOP 20\\n  s.program_name,\\n  s.host_name,\\n  COUNT(*) AS session_count,\\n  SUM(CASE WHEN s.status = 'sleeping' THEN 1 ELSE 0 END) AS sleeping_count,\\n  SUM(CASE WHEN s.status = 'running' THEN 1 ELSE 0 END) AS running_count,\\n  MIN(s.login_time) AS earliest_login,\\n  MAX(s.login_time) AS latest_login,\\n  DATEDIFF(SECOND, MIN(s.login_time), MAX(s.login_time)) AS login_window_sec\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 20\\nORDER BY session_count DESC"}	{"condition": "session_count > 20 from a single program/host with narrow login_window_sec", "description": "Large burst of connections from a single application in a short window confirms connection storm"}	null	2026-02-23 20:18:31.390274
2276	sqlserver	query	Check THREADPOOL waits confirming worker exhaustion from connection surge	{"sql": "SELECT\\n  wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  CASE WHEN waiting_tasks_count > 0\\n    THEN wait_time_ms / waiting_tasks_count ELSE 0 END AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('THREADPOOL', 'LOGON_TRIGGER_WAIT')\\n  AND waiting_tasks_count > 0"}	{"condition": "THREADPOOL waiting_tasks_count > 0", "description": "Active THREADPOOL waits during connection surge confirm worker thread starvation from connection storm"}	null	2026-02-23 20:18:31.390274
2277	sqlserver	query	Check memory pressure indicators	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Total Server Memory (KB)' AND object_name LIKE '%Memory Manager%') / 1024 AS server_memory_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Target Server Memory (KB)' AND object_name LIKE '%Memory Manager%') / 1024 AS target_memory_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Memory Grants Pending' AND object_name LIKE '%Memory Manager%') AS grants_pending,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Page life expectancy'\\n     AND object_name LIKE '%Buffer Manager%') AS ple_seconds,\\n  (SELECT SUM(pages_kb) / 1024 FROM sys.dm_os_memory_clerks\\n   WHERE type = 'MEMORYCLERK_SQLBUFFERPOOL') AS buffer_pool_mb"}	{"condition": "server_memory_mb < target_memory_mb * 0.9 OR grants_pending > 0 OR ple_seconds < 60", "description": "Memory pressure forces buffer pool shrinkage, increasing physical I/O that holds worker threads"}	null	2026-02-23 20:18:31.390275
2285	sqlserver	query	Check for queries with memory grant spills	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_grant_kb,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.execution_count,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_spills > 0\\nORDER BY qs.total_spills DESC"}	{"condition": "avg_spills > 0 AND avg_grant_kb < avg_ideal_grant_kb * 0.8", "description": "Queries receiving significantly less memory than ideal and spilling to tempdb"}	null	2026-02-23 20:18:31.390281
2286	sqlserver	query	Check memory grant queue and pending grants	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Memory Grants Pending' AND object_name LIKE '%Memory Manager%') AS grants_pending,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Memory Grants Outstanding' AND object_name LIKE '%Memory Manager%') AS grants_outstanding,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Total Server Memory (KB)' AND object_name LIKE '%Memory Manager%') / 1024 AS server_memory_mb,\\n  (SELECT SUM(requested_memory_kb) / 1024 FROM sys.dm_exec_query_memory_grants) AS total_requested_mb,\\n  (SELECT SUM(granted_memory_kb) / 1024 FROM sys.dm_exec_query_memory_grants) AS total_granted_mb,\\n  (SELECT SUM(ideal_memory_kb) / 1024 FROM sys.dm_exec_query_memory_grants) AS total_ideal_mb,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_memory_grants WHERE grant_time IS NULL) AS waiting_for_grant"}	{"condition": "grants_pending > 0 OR waiting_for_grant > 0 OR total_granted_mb < total_ideal_mb * 0.7", "description": "Active memory grant queue or significant gap between granted and ideal memory confirms insufficient grants for parallel operations"}	null	2026-02-23 20:18:31.390282
2288	sqlserver	query	Find tables with stale statistics used in spilling queries	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows, sp.rows_sampled,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter AS FLOAT) / NULLIF(sp.rows, 0) * 100 AS pct_modified,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update,\\n  sp.steps AS histogram_steps\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 10000\\n  AND (sp.modification_counter > sp.rows * 0.1\\n    OR DATEDIFF(DAY, sp.last_updated, GETDATE()) > 3)\\nORDER BY sp.modification_counter DESC"}	{"condition": "pct_modified > 10 on tables with > 10K rows", "description": "Statistics with > 10% modifications relative to row count will have inaccurate cardinality estimates"}	null	2026-02-23 20:18:31.390283
2289	sqlserver	query	Check for spilling queries that touch tables with stale stats	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_grant_kb,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_actual_rows,\\n  qs.execution_count,\\n  qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') AS has_parallelism,\\n  qs.last_elapsed_time / 1000 AS last_elapsed_ms\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_spills > 0\\n  AND qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') = 1\\n  AND qs.total_grant_kb < qs.total_ideal_grant_kb * 0.6\\nORDER BY qs.total_spills DESC"}	{"condition": "avg_spills > 0 AND avg_grant_kb < avg_ideal_grant_kb * 0.6 on parallel plans", "description": "Parallel queries spilling with grants well below ideal — cardinality underestimation from stale statistics is the likely cause"}	null	2026-02-23 20:18:31.390284
2290	sqlserver	query	Find parallel queries with spills despite adequate total memory grants	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_grant_kb,\\n  CAST(qs.total_used_grant_kb AS FLOAT) / NULLIF(qs.total_grant_kb, 0) * 100 AS pct_grant_used,\\n  qs.execution_count,\\n  qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\"]') AS has_hash_match,\\n  qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') AS has_parallelism\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_spills > 0\\n  AND qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Parallelism\\"]') = 1\\n  AND qs.total_grant_kb >= qs.total_ideal_grant_kb * 0.8\\nORDER BY qs.total_spills DESC"}	{"condition": "avg_spills > 0 AND avg_grant_kb >= avg_ideal_grant_kb * 0.8", "description": "Queries that spill despite receiving adequate (or near-ideal) memory grants suggest per-thread memory imbalance from data skew"}	null	2026-02-23 20:18:31.390284
2291	sqlserver	query	Check for skewed columns driving hash distribution in spilling queries	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.rows,\\n  sp.steps AS histogram_steps,\\n  CASE WHEN sp.steps > 0 THEN sp.rows / sp.steps ELSE sp.rows END AS avg_rows_per_step\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 100000\\n  AND sp.steps < 30\\nORDER BY sp.rows / NULLIF(sp.steps, 0) DESC"}	{"condition": "avg_rows_per_step highly variable (low histogram steps on large tables)", "description": "Low-cardinality or highly skewed columns on large tables cause uneven row distribution across parallel hash buckets"}	null	2026-02-23 20:18:31.390285
2292	sqlserver	query	Verify CXPACKET waits co-occurring with spills	{"sql": "SELECT\\n  ws_cx.wait_time_ms AS cxpacket_wait_ms,\\n  ws_cx.waiting_tasks_count AS cxpacket_count,\\n  CASE WHEN ws_cx.waiting_tasks_count > 0\\n    THEN ws_cx.wait_time_ms / ws_cx.waiting_tasks_count ELSE 0 END AS avg_cxpacket_ms,\\n  (SELECT SUM(internal_objects_alloc_page_count) * 8 / 1024\\n   FROM sys.dm_db_task_space_usage\\n   WHERE internal_objects_alloc_page_count > 128) AS tempdb_spill_mb\\nFROM sys.dm_os_wait_stats ws_cx\\nWHERE ws_cx.wait_type = 'CXPACKET'"}	{"condition": "high cxpacket_wait_ms co-occurring with tempdb_spill_mb > 50", "description": "CXPACKET waits alongside tempdb spills confirm that one thread is doing disproportionate work and spilling while others wait"}	null	2026-02-23 20:18:31.390286
4019	postgresql	query	Measure WAL directory size	{"sql": "SELECT count(*) AS wal_file_count, pg_size_pretty(sum(size)) AS total_wal_size FROM pg_ls_waldir()"}	{"condition": "wal_file_count > :threshold", "description": "Excessive WAL files confirmed; archiving failure is the root cause"}	{"threshold": 100}	2026-02-25 00:28:52.405273
2293	sqlserver	query	Check for scan-heavy queries on fragmented indexes	{"sql": "SELECT OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  ius.user_scans,\\n  ius.user_seeks,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\n  ON ius.object_id = ips.object_id AND ius.index_id = ips.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.user_scans > 100\\n  AND ips.avg_fragmentation_in_percent > 30\\n  AND ips.page_count > 1000\\nORDER BY ius.user_scans DESC"}	{"condition": "fragmented indexes with high scan counts (user_scans > 100)", "description": "Heavily fragmented indexes being scanned frequently — optimizer underestimates I/O cost because it assumes contiguous pages"}	null	2026-02-23 20:18:31.390286
2294	sqlserver	query	Find tables with outdated statistics	{"sql": "SELECT OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  s.auto_created,\\n  sp.last_updated,\\n  sp.rows AS stat_rows,\\n  sp.rows_sampled,\\n  sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN sp.modification_counter * 100.0 / sp.rows ELSE 0 END AS pct_modified\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > 0\\n  AND (\\n    sp.modification_counter > SQRT(sp.rows) * 10\\n    OR sp.last_updated < DATEADD(day, -7, GETDATE())\\n    OR sp.rows_sampled < sp.rows * 0.5\\n  )\\n  AND OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\nORDER BY sp.modification_counter DESC"}	{"condition": "statistics with high modification_counter or last_updated > 7 days ago", "description": "Stale statistics that may cause cardinality misestimation"}	null	2026-02-23 20:18:31.390287
2296	sqlserver	query	Check for tables with no statistics at all	{"sql": "SELECT t.object_id,\\n  OBJECT_SCHEMA_NAME(t.object_id) AS schema_name,\\n  t.name AS table_name,\\n  (SELECT COUNT(*) FROM sys.stats s WHERE s.object_id = t.object_id) AS stat_count,\\n  (SELECT SUM(row_count) FROM sys.dm_db_partition_stats ps\\n   WHERE ps.object_id = t.object_id AND ps.index_id IN (0,1)) AS row_count\\nFROM sys.tables t\\nWHERE (SELECT COUNT(*) FROM sys.stats s WHERE s.object_id = t.object_id) = 0\\n  AND (SELECT SUM(row_count) FROM sys.dm_db_partition_stats ps\\n   WHERE ps.object_id = t.object_id AND ps.index_id IN (0,1)) > 1000"}	{"condition": "tables with > 1000 rows and zero statistics", "description": "Tables with no statistics at all — optimizer uses hard-coded assumptions"}	null	2026-02-23 20:18:31.390288
2297	sqlserver	query	Check database compatibility level vs engine version	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  SERVERPROPERTY('ProductMajorVersion') AS engine_major_version,\\n  CASE\\n    WHEN d.compatibility_level < 130 THEN 'Legacy CE (pre-2016)'\\n    WHEN d.compatibility_level = 130 THEN 'SQL 2016 CE'\\n    WHEN d.compatibility_level = 140 THEN 'SQL 2017 CE'\\n    WHEN d.compatibility_level = 150 THEN 'SQL 2019 CE'\\n    WHEN d.compatibility_level = 160 THEN 'SQL 2022 CE'\\n    ELSE 'Unknown'\\n  END AS ce_model,\\n  d.is_query_store_on\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.compatibility_level <> (CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10)"}	{"condition": "compatibility_level does not match engine version", "description": "Database running at different compatibility level — cardinality estimator model differs from current engine"}	null	2026-02-23 20:18:31.390288
11768	mysql	query	Check Galera provider port options	{"sql": "SHOW VARIABLES LIKE 'wsrep_provider_options';"}	{"condition": "contains gmcast.listen_addr with explicit port", "description": "The Galera provider is configured with explicit listen port"}	\N	2026-03-01 06:30:58.706791
2298	sqlserver	query	Check for regressed queries in Query Store	{"sql": "SELECT TOP 20\\n  qsq.query_id,\\n  qsp.plan_id,\\n  qsrs.avg_duration / 1000.0 AS avg_duration_ms,\\n  qsrs.avg_cpu_time / 1000.0 AS avg_cpu_ms,\\n  qsrs.avg_logical_io_reads,\\n  qsrs.count_executions,\\n  qsp.compatibility_level AS plan_compat_level,\\n  qsp.is_forced_plan\\nFROM sys.query_store_query qsq\\nJOIN sys.query_store_plan qsp ON qsq.query_id = qsp.query_id\\nJOIN sys.query_store_runtime_stats qsrs ON qsp.plan_id = qsrs.plan_id\\nWHERE qsrs.avg_duration > 1000000\\n  AND qsrs.count_executions > 10\\nORDER BY qsrs.avg_duration DESC"}	{"condition": "slow queries with plans compiled at non-current compatibility level", "description": "Queries showing performance issues potentially related to CE model mismatch"}	null	2026-02-23 20:18:31.390289
2302	sqlserver	query	Check cost threshold for parallelism and MAXDOP settings	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'cost threshold for parallelism') AS cost_threshold,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'max degree of parallelism') AS maxdop,\\n  (SELECT COUNT(*) FROM sys.dm_os_schedulers\\n   WHERE status = 'VISIBLE ONLINE' AND is_online = 1) AS online_schedulers"}	{"condition": "cost_threshold = 5 (default) or cost_threshold < 25", "description": "Cost threshold too low — trivial queries going parallel, wasting threads and causing CXPACKET waits"}	null	2026-02-23 20:18:31.390291
3167	sqlserver	query	Check for backup encryption prerequisites	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM master.sys.symmetric_keys\\n   WHERE name = '##MS_DatabaseMasterKey##') AS master_dmk_exists,\\n  (SELECT COUNT(*) FROM master.sys.certificates\\n   WHERE expiry_date > GETDATE()) AS valid_cert_count,\\n  (SELECT COUNT(*) FROM master.sys.asymmetric_keys) AS asym_key_count,\\n  (SELECT COUNT(*) FROM sys.cryptographic_providers) AS ekm_provider_count"}	{"condition": "master_dmk_exists = 0 OR (valid_cert_count = 0 AND asym_key_count = 0 AND ekm_provider_count = 0)", "description": "No usable certificate, asymmetric key, or EKM provider for backup encryption"}	null	2026-02-23 20:18:31.390292
3482	postgresql	query	Check if backup-in-progress flag is set	{"sql": "SELECT CASE WHEN current_setting('server_version_num')::int < 150000 THEN 'check_exclusive_backup' ELSE 'exclusive_backup_not_supported' END AS backup_check_method, CASE WHEN current_setting('server_version_num')::int < 150000 THEN 'Run pg_is_in_backup() to check' ELSE 'Exclusive backups removed in PG15+; use pg_stat_activity to check for non-exclusive backup processes' END AS recommendation, (SELECT count(*) FROM pg_stat_activity WHERE backend_type = 'walreceiver' OR query LIKE '%pg_backup_start%' OR query LIKE '%pg_start_backup%') AS backup_related_processes"}	{"condition": "backup_active = true", "description": "Exclusive backup mode still active — blocking new backups"}	\N	2026-02-25 00:28:52.405273
2304	sqlserver	query	Find queries with high logical reads per execution suggesting bad join choices	{"sql": "SELECT TOP 20\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  qs.total_worker_time / qs.execution_count / 1000 AS avg_cpu_ms,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text,\\n  qs.plan_handle\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.execution_count > 5\\n  AND qs.total_logical_reads / qs.execution_count > 100000\\nORDER BY avg_logical_reads DESC"}	{"condition": "queries averaging > 100K logical reads per execution", "description": "High logical reads suggest nested loop on large datasets or missing join indexes"}	null	2026-02-23 20:18:31.390293
2305	sqlserver	query	Check execution plans for nested loop joins with large row estimates	{"sql": "SELECT TOP 10\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"])', 'int') AS nested_loop_count,\\n  qp.query_plan.value('(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/@EstimateRows)[1]', 'float') AS nl_estimated_rows,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_logical_reads / qs.execution_count > 100000\\n  AND qs.execution_count > 5\\n  AND qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Nested Loops\\"]') = 1\\nORDER BY avg_logical_reads DESC"}	{"condition": "nested loop joins with estimated rows > 1000 on the outer input", "description": "Optimizer chose nested loop despite large outer input — likely cardinality underestimation or missing join index"}	null	2026-02-23 20:18:31.390294
2306	sqlserver	query	Check for sort warnings (spills) in recent query executions	{"sql": "SELECT TOP 20\\n  qs.total_spills AS total_spills,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills_per_exec,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_grant_kb,\\n  qs.execution_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_spills > 0\\n  AND qs.execution_count > 1\\nORDER BY qs.total_spills DESC"}	{"condition": "queries with avg_spills_per_exec > 0", "description": "Sort or hash operations spilling to tempdb due to insufficient memory grant"}	null	2026-02-23 20:18:31.390294
2308	sqlserver	query	Find queries with large estimated-vs-actual row discrepancies via Query Store	{"sql": "SELECT TOP 20\\n  qsq.query_id,\\n  qsp.plan_id,\\n  qsrs.avg_duration / 1000.0 AS avg_duration_ms,\\n  qsrs.avg_logical_io_reads,\\n  qsrs.count_executions,\\n  qsrs.avg_rowcount AS avg_actual_rows,\\n  CAST(qsp.query_plan AS XML).value(\\n    '(//RelOp/@EstimateRows)[1]', 'float') AS top_estimated_rows,\\n  qt.query_sql_text\\nFROM sys.query_store_query qsq\\nJOIN sys.query_store_plan qsp ON qsq.query_id = qsp.query_id\\nJOIN sys.query_store_runtime_stats qsrs ON qsp.plan_id = qsrs.plan_id\\nJOIN sys.query_store_query_text qt ON qsq.query_text_id = qt.query_text_id\\nWHERE qsrs.avg_duration > 500000\\n  AND qsrs.count_executions > 5\\nORDER BY qsrs.avg_duration DESC"}	{"condition": "queries where estimated rows differ from actual rows by > 10x", "description": "Significant cardinality misestimation causing suboptimal plan choices"}	null	2026-02-23 20:18:31.390296
2309	sqlserver	query	Check for multi-column statistics that could improve estimates	{"sql": "SELECT OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  s.auto_created,\\n  STRING_AGG(COL_NAME(sc.object_id, sc.column_id), ', ')\\n    WITHIN GROUP (ORDER BY sc.stats_column_id) AS columns,\\n  COUNT(*) AS column_count\\nFROM sys.stats s\\nJOIN sys.stats_columns sc ON s.stats_id = sc.stats_id AND s.object_id = sc.object_id\\nWHERE OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\nGROUP BY s.object_id, s.name, s.auto_created, s.stats_id\\nHAVING COUNT(*) = 1\\nORDER BY table_name"}	{"condition": "tables with only single-column statistics on columns used in compound predicates", "description": "Missing multi-column statistics — optimizer assumes independence between predicates, multiplying selectivities"}	null	2026-02-23 20:18:31.390296
2874	sqlserver	query	Find schema-level grants to rootcause	{"sql": "SELECT SCHEMA_NAME(dp.major_id) AS schema_name,\\n  dp.permission_name, dp.state_desc,\\n  dp.class_desc\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.class_desc = 'SCHEMA'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.permission_name IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE', 'EXECUTE', 'ALTER', 'CONTROL',\\n    'VIEW DEFINITION', 'REFERENCES', 'CREATE SEQUENCE', 'TAKE OWNERSHIP')"}	{"condition": "row_count > 0", "description": "PUBLIC has schema-level grants — all current and future objects in that schema are accessible to every user"}	null	2026-02-23 20:18:31.390533
2310	sqlserver	query	Find tables with large modification counters relative to row count	{"sql": "SELECT OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows AS stat_rows,\\n  sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(sp.modification_counter * 100.0 / sp.rows AS DECIMAL(10,2))\\n    ELSE 100.0 END AS pct_modified,\\n  p.rows AS current_rows\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.partitions p ON s.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE sp.modification_counter > sp.rows * 0.2\\n  AND sp.rows > 0\\n  AND OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\nORDER BY sp.modification_counter DESC"}	{"condition": "pct_modified > 20% with modification_counter > 10000", "description": "Tables with massive modifications since last stats update — likely from bulk load"}	null	2026-02-23 20:18:31.390297
2311	sqlserver	query	Check if BULK INSERT or BCP operations occurred recently	{"sql": "SELECT d.name AS database_name,\\n  d.is_auto_update_stats_on,\\n  (SELECT TOP 1 last_user_update FROM sys.dm_db_index_usage_stats ius\\n   JOIN sys.stats s2 ON ius.object_id = s2.object_id\\n   CROSS APPLY sys.dm_db_stats_properties(s2.object_id, s2.stats_id) sp2\\n   WHERE sp2.modification_counter > sp2.rows * 0.2\\n     AND ius.database_id = DB_ID()\\n   ORDER BY ius.last_user_update DESC) AS most_recent_write,\\n  (SELECT MIN(sp3.last_updated)\\n   FROM sys.stats s3\\n   CROSS APPLY sys.dm_db_stats_properties(s3.object_id, s3.stats_id) sp3\\n   WHERE sp3.modification_counter > sp3.rows * 0.2\\n     AND OBJECTPROPERTY(s3.object_id, 'IsUserTable') = 1) AS oldest_stale_stat\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "most_recent_write is recent but oldest_stale_stat is old", "description": "Recent bulk writes but statistics not yet updated — queries using stale cardinality estimates"}	null	2026-02-23 20:18:31.390298
2312	sqlserver	query	Check missing index DMV for indexes with filter predicates	{"sql": "SELECT TOP 20\\n  mid.statement AS table_name,\\n  mid.equality_columns,\\n  mid.inequality_columns,\\n  mid.included_columns,\\n  migs.avg_user_impact,\\n  migs.user_seeks,\\n  migs.avg_total_user_cost,\\n  migs.user_seeks * migs.avg_total_user_cost * migs.avg_user_impact / 100.0 AS improvement_measure\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE migs.avg_user_impact > 70\\n  AND migs.user_seeks > 100\\nORDER BY improvement_measure DESC"}	{"condition": "high-impact missing indexes with improvement_measure > 10000", "description": "Missing indexes that could significantly improve query plans"}	null	2026-02-23 20:18:31.390298
2313	sqlserver	query	Check for tables where a filtered index could help status-based queries	{"sql": "SELECT t.name AS table_name,\\n  i.name AS index_name,\\n  i.has_filter,\\n  i.filter_definition,\\n  (SELECT SUM(row_count) FROM sys.dm_db_partition_stats ps\\n   WHERE ps.object_id = t.object_id AND ps.index_id IN (0,1)) AS total_rows,\\n  ius.user_seeks, ius.user_scans\\nFROM sys.tables t\\nJOIN sys.indexes i ON t.object_id = i.object_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius ON i.object_id = ius.object_id\\n  AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.index_id > 0\\n  AND (SELECT SUM(row_count) FROM sys.dm_db_partition_stats ps\\n   WHERE ps.object_id = t.object_id AND ps.index_id IN (0,1)) > 100000\\n  AND i.has_filter = 0\\n  AND ius.user_scans > ius.user_seeks * 2\\nORDER BY ius.user_scans DESC"}	{"condition": "large tables with non-filtered indexes heavily scanned", "description": "Tables with scan-heavy access on large row counts — filtered indexes could target active subsets"}	null	2026-02-23 20:18:31.390299
2314	sqlserver	query	Find queries with IN clauses and high cardinality misestimation	{"sql": "SELECT TOP 20\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.execution_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 300) AS query_text,\\n  qs.plan_handle\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 4000) LIKE '%IN (%'\\n  AND qs.total_elapsed_time / qs.execution_count > 500000\\n  AND qs.execution_count > 5\\nORDER BY avg_elapsed_ms DESC"}	{"condition": "slow queries containing IN clauses", "description": "Queries with IN predicates and high average execution time"}	null	2026-02-23 20:18:31.390299
2315	sqlserver	query	Check histogram step density for columns used in queries	{"sql": "SELECT OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.steps AS histogram_steps,\\n  CASE WHEN sp.rows > 0\\n    THEN sp.rows / NULLIF(sp.steps, 0) ELSE 0 END AS avg_rows_per_step,\\n  sp.unfiltered_rows,\\n  sp.rows_sampled\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\n  AND sp.rows > 10000\\n  AND sp.steps < 50\\n  AND sp.rows / NULLIF(sp.steps, 0) > 1000\\nORDER BY avg_rows_per_step DESC"}	{"condition": "statistics with avg_rows_per_step > 1000 and few histogram steps", "description": "Sparse histograms with large gaps between steps — IN clause values likely fall into RANGE_ROWS estimates"}	null	2026-02-23 20:18:31.3903
3591	postgresql	query	Check for stale replication configuration	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('primary_conninfo', 'primary_slot_name', 'recovery_target_timeline') AND setting != '' ORDER BY name"}	{"condition": "row_count > 0 AND NOT pg_is_in_recovery()", "description": "Replication configuration present on a primary server — leftover from clone/restore"}	\N	2026-02-25 00:28:52.405273
2317	sqlserver	query	Check the sniffed parameter values in the cached plan	{"sql": "SELECT\\n  OBJECT_NAME(qp.objectid) AS proc_name,\\n  qp.query_plan.value('(//ParameterList/ColumnReference/@ParameterCompiledValue)[1]', 'nvarchar(256)') AS sniffed_param_1,\\n  qp.query_plan.value('(//ParameterList/ColumnReference/@ParameterCompiledValue)[2]', 'nvarchar(256)') AS sniffed_param_2,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  qs.creation_time AS plan_compiled_at\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qp.objectid IS NOT NULL\\n  AND qp.objectid > 0\\n  AND OBJECT_NAME(qp.objectid) IS NOT NULL\\n  AND qs.execution_count > 10\\nORDER BY qs.total_elapsed_time / qs.execution_count DESC"}	{"condition": "ParameterCompiledValue visible with high avg_elapsed_ms", "description": "Sniffed parameter values captured in the plan — compare with typical runtime values"}	null	2026-02-23 20:18:31.390301
2318	sqlserver	query	Find parameterized queries with high runtime variance	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  MIN(qs.total_elapsed_time / qs.execution_count) AS min_avg_elapsed_us,\\n  MAX(qs.total_elapsed_time / qs.execution_count) AS max_avg_elapsed_us,\\n  MAX(qs.total_elapsed_time / qs.execution_count) /\\n    NULLIF(MIN(qs.total_elapsed_time / qs.execution_count), 0) AS elapsed_ratio,\\n  SUM(qs.execution_count) AS total_execs,\\n  COUNT(DISTINCT qs.plan_handle) AS plan_count,\\n  MIN(SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200)) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.execution_count > 5\\nGROUP BY qs.query_hash\\nHAVING COUNT(DISTINCT qs.plan_handle) = 1\\n  AND MAX(qs.total_elapsed_time / qs.execution_count) /\\n    NULLIF(MIN(qs.total_elapsed_time / qs.execution_count), 0) > 10\\nORDER BY elapsed_ratio DESC"}	{"condition": "query_hash entries with plan_count=1 and elapsed_ratio > 10", "description": "Single cached plan serving diverse parameter ranges — 10x+ performance variance"}	null	2026-02-23 20:18:31.390302
2320	sqlserver	query	Find procedures with multiple plan shapes in Query Store	{"sql": "SELECT\\n  OBJECT_NAME(qsq.object_id) AS proc_name,\\n  COUNT(DISTINCT qsp.plan_id) AS plan_count,\\n  MIN(qsrs.avg_duration) / 1000.0 AS best_avg_ms,\\n  MAX(qsrs.avg_duration) / 1000.0 AS worst_avg_ms,\\n  MAX(qsrs.avg_duration) / NULLIF(MIN(qsrs.avg_duration), 0) AS plan_ratio,\\n  SUM(qsrs.count_executions) AS total_execs\\nFROM sys.query_store_query qsq\\nJOIN sys.query_store_plan qsp ON qsq.query_id = qsp.query_id\\nJOIN sys.query_store_runtime_stats qsrs ON qsp.plan_id = qsrs.plan_id\\nWHERE qsq.object_id > 0\\n  AND qsrs.count_executions > 5\\nGROUP BY qsq.object_id\\nHAVING COUNT(DISTINCT qsp.plan_id) > 1\\n  AND MAX(qsrs.avg_duration) / NULLIF(MIN(qsrs.avg_duration), 0) > 5\\nORDER BY plan_ratio DESC"}	{"condition": "procedures with multiple plans and plan_ratio > 5", "description": "Procedure has multiple plan shapes with >5x performance difference — join strategy varies with parameters"}	null	2026-02-23 20:18:31.390303
2321	sqlserver	query	Check plan XML for different join operators across plan variations	{"sql": "SELECT\\n  OBJECT_NAME(qsq.object_id) AS proc_name,\\n  qsp.plan_id,\\n  qsrs.avg_duration / 1000.0 AS avg_duration_ms,\\n  qsrs.count_executions,\\n  CAST(qsp.query_plan AS XML).value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"])', 'int') AS nested_loops,\\n  CAST(qsp.query_plan AS XML).value('count(//RelOp[@PhysicalOp=\\"Hash Match\\"])', 'int') AS hash_joins,\\n  CAST(qsp.query_plan AS XML).value('count(//RelOp[@PhysicalOp=\\"Merge Join\\"])', 'int') AS merge_joins,\\n  qsp.is_forced_plan\\nFROM sys.query_store_query qsq\\nJOIN sys.query_store_plan qsp ON qsq.query_id = qsp.query_id\\nJOIN sys.query_store_runtime_stats qsrs ON qsp.plan_id = qsrs.plan_id\\nWHERE qsq.object_id > 0\\n  AND qsrs.count_executions > 5\\n  AND qsq.object_id IN (\\n    SELECT qsq2.object_id FROM sys.query_store_query qsq2\\n    JOIN sys.query_store_plan qsp2 ON qsq2.query_id = qsp2.query_id\\n    GROUP BY qsq2.object_id HAVING COUNT(DISTINCT qsp2.plan_id) > 1\\n  )\\nORDER BY OBJECT_NAME(qsq.object_id), qsrs.avg_duration"}	{"condition": "different join types across plans for the same procedure", "description": "Same procedure produces plans with different join strategies — nested loops vs hash/merge depending on sniffed parameter"}	null	2026-02-23 20:18:31.390304
2322	sqlserver	query	Find queries with high logical reads variance suggesting seek-vs-scan mismatch	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.min_logical_reads,\\n  qs.max_logical_reads,\\n  qs.max_logical_reads / NULLIF(qs.min_logical_reads, 0) AS reads_ratio,\\n  qs.execution_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.execution_count > 10\\n  AND qs.max_logical_reads / NULLIF(qs.min_logical_reads, 0) > 100\\n  AND qs.min_logical_reads > 0\\nORDER BY reads_ratio DESC"}	{"condition": "queries with reads_ratio > 100 (max_reads 100x+ min_reads)", "description": "Extreme I/O variance — likely index seek for selective values producing key lookups at scale for non-selective values"}	null	2026-02-23 20:18:31.390304
2323	sqlserver	query	Check for key lookups in cached plans	{"sql": "SELECT TOP 10\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment,\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"Key Lookup\\"])', 'int') AS key_lookup_count,\\n  qp.query_plan.value('count(//RelOp[@PhysicalOp=\\"RID Lookup\\"])', 'int') AS rid_lookup_count,\\n  qp.query_plan.value('(//RelOp[@PhysicalOp=\\"Key Lookup\\"]/@EstimateRows)[1]', 'float') AS est_lookup_rows,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.max_logical_reads\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.max_logical_reads / NULLIF(qs.min_logical_reads, 0) > 100\\n  AND qs.execution_count > 10\\n  AND (qp.query_plan.exist('//RelOp[@PhysicalOp=\\"Key Lookup\\"]') = 1\\n    OR qp.query_plan.exist('//RelOp[@PhysicalOp=\\"RID Lookup\\"]') = 1)\\nORDER BY qs.max_logical_reads DESC"}	{"condition": "key lookups present with large estimated rows", "description": "Index seek + key lookup plan cached — efficient for few rows but catastrophic at scale when parameters are non-selective"}	null	2026-02-23 20:18:31.390305
2331	sqlserver	query	Check if specific IQP features are disabled via database-scoped configurations	{"sql": "SELECT name, value, value_for_secondary\\nFROM sys.database_scoped_configurations\\nWHERE name IN (\\n  'BATCH_MODE_ADAPTIVE_JOINS',\\n  'BATCH_MODE_MEMORY_GRANT_FEEDBACK',\\n  'ROW_MODE_MEMORY_GRANT_FEEDBACK',\\n  'INTERLEAVED_EXECUTION_TVF',\\n  'BATCH_MODE_ON_ROWSTORE',\\n  'DEFERRED_COMPILATION_TV',\\n  'ACCELERATED_PLAN_FORCING',\\n  'CE_FEEDBACK',\\n  'DOP_FEEDBACK',\\n  'PARAMETER_SENSITIVE_PLAN_OPTIMIZATION'\\n)\\n  AND value = 0"}	{"condition": "any IQP features explicitly disabled (value = 0)", "description": "Adaptive query features disabled — optimizer cannot self-correct for parameter sniffing issues"}	null	2026-02-23 20:18:31.390306
2324	sqlserver	query	Find queries with memory grant and spill issues	{"sql": "SELECT TOP 20\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.min_spills, qs.max_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.min_grant_kb, qs.max_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.execution_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_spills > 0\\n  AND qs.max_grant_kb > 0\\n  AND qs.execution_count > 10\\nORDER BY qs.total_spills DESC"}	{"condition": "queries with spills and avg_grant_kb << avg_ideal_grant_kb", "description": "Memory grant insufficient — spilling to tempdb because grant was sized for sniffed parameter, not actual data volume"}	null	2026-02-23 20:18:31.390306
3378	postgresql	query	Group connections by source host and application	{"sql": "SELECT client_addr, application_name, count(*) AS connections FROM pg_stat_activity WHERE backend_type = 'client backend' AND client_addr IS NOT NULL GROUP BY client_addr, application_name HAVING count(*) > :per_host_threshold ORDER BY connections DESC"}	{"condition": "row_count > 1", "description": "Multiple hosts with high connection counts"}	{"per_host_threshold": 20}	2026-02-25 00:28:52.405273
2325	sqlserver	query	Check if memory grant feedback is active	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  CASE WHEN d.compatibility_level >= 140 THEN 'Batch mode MGF available'\\n    WHEN d.compatibility_level >= 150 THEN 'Row + Batch mode MGF available'\\n    ELSE 'No memory grant feedback' END AS mgf_status,\\n  (SELECT value FROM sys.database_scoped_configurations\\n   WHERE name = 'BATCH_MODE_MEMORY_GRANT_FEEDBACK') AS batch_mgf,\\n  (SELECT value FROM sys.database_scoped_configurations\\n   WHERE name = 'ROW_MODE_MEMORY_GRANT_FEEDBACK') AS row_mgf\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "compatibility_level < 150 or memory grant feedback disabled", "description": "Memory grant feedback not available or disabled — grants cannot self-correct"}	null	2026-02-23 20:18:31.390307
2326	sqlserver	query	Find queries with high execution time and multi-predicate WHERE clauses	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.execution_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_elapsed_time / qs.execution_count > 1000000\\n  AND qs.execution_count > 10\\n  AND SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 4000) LIKE '%AND%AND%'\\nORDER BY avg_elapsed_ms DESC"}	{"condition": "slow queries with multiple AND predicates", "description": "Multi-predicate queries where parameter correlation may cause CE errors"}	null	2026-02-23 20:18:31.390307
2346	sqlserver	query	Check for tables with highly skewed statistics histograms	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.rows AS total_rows,\\n  sp.rows_sampled,\\n  sp.modification_counter,\\n  h.range_high_key, h.equal_rows, h.range_rows,\\n  CAST(h.equal_rows AS FLOAT) / NULLIF(sp.rows, 0) * 100 AS pct_of_table\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nCROSS APPLY sys.dm_db_stats_histogram(s.object_id, s.stats_id) h\\nWHERE sp.rows > 10000\\n  AND CAST(h.equal_rows AS FLOAT) / NULLIF(sp.rows, 0) * 100 > 15\\nORDER BY pct_of_table DESC"}	{"condition": "row_count > 0 AND pct_of_table > 15", "description": "Histogram buckets containing >15% of table rows indicate data distribution skew where specific values dominate"}	null	2026-02-23 20:18:31.390308
2875	sqlserver	query	Count objects exposed by schema-level rootcause grants	{"sql": "SELECT s.name AS schema_name,\\n  dp.permission_name,\\n  COUNT(o.object_id) AS objects_exposed,\\n  SUM(CASE WHEN o.type IN ('U', 'V') THEN 1 ELSE 0 END) AS tables_views,\\n  SUM(CASE WHEN o.type IN ('P', 'FN', 'IF', 'TF') THEN 1 ELSE 0 END) AS procs_functions\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.schemas s ON dp.major_id = s.schema_id\\nJOIN sys.objects o ON s.schema_id = o.schema_id AND o.is_ms_shipped = 0\\nWHERE pr.name = 'public'\\n  AND dp.class_desc = 'SCHEMA'\\n  AND dp.state_desc = 'GRANT'\\nGROUP BY s.name, dp.permission_name\\nORDER BY objects_exposed DESC"}	{"condition": "objects_exposed > 0", "description": "Schema-level PUBLIC grants expose user-created objects — often done when administrator confused schema-scope with object-scope grants"}	null	2026-02-23 20:18:31.390638
2327	sqlserver	query	Check for missing multi-column statistics on commonly queried column pairs	{"sql": "SELECT t.name AS table_name,\\n  (SELECT COUNT(*) FROM sys.stats s\\n   JOIN sys.stats_columns sc ON s.stats_id = sc.stats_id AND s.object_id = sc.object_id\\n   WHERE s.object_id = t.object_id\\n   GROUP BY s.stats_id HAVING COUNT(*) > 1) AS multi_col_stat_count,\\n  (SELECT COUNT(DISTINCT ic.column_id)\\n   FROM sys.index_columns ic WHERE ic.object_id = t.object_id) AS indexed_columns,\\n  (SELECT COUNT(*) FROM sys.columns c WHERE c.object_id = t.object_id) AS total_columns\\nFROM sys.tables t\\nWHERE (SELECT SUM(row_count) FROM sys.dm_db_partition_stats ps\\n  WHERE ps.object_id = t.object_id AND ps.index_id IN (0,1)) > 100000\\n  AND (SELECT COUNT(*) FROM sys.stats s\\n   JOIN sys.stats_columns sc ON s.stats_id = sc.stats_id AND s.object_id = sc.object_id\\n   WHERE s.object_id = t.object_id\\n   GROUP BY s.stats_id HAVING COUNT(*) > 1) IS NULL\\nORDER BY total_columns DESC"}	{"condition": "large tables with zero multi-column statistics", "description": "No multi-column statistics — optimizer assumes independence between correlated predicates"}	null	2026-02-23 20:18:31.390309
2328	sqlserver	query	Find serial queries with high CPU time that might benefit from parallelism	{"sql": "SELECT TOP 20\\n  qs.total_worker_time / qs.execution_count / 1000 AS avg_cpu_ms,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.execution_count,\\n  qp.query_plan.value('(//QueryPlan/@DegreeOfParallelism)[1]', 'int') AS plan_dop,\\n  qp.query_plan.value('(//StmtSimple/@StatementEstRows)[1]', 'float') AS est_rows,\\n  qp.query_plan.value('(//StmtSimple/@StatementSubTreeCost)[1]', 'float') AS subtree_cost,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_worker_time / qs.execution_count > 5000000\\n  AND qs.execution_count > 5\\nORDER BY avg_cpu_ms DESC"}	{"condition": "queries with plan_dop = 1 (serial) and avg_cpu_ms > 5000", "description": "Serial plans consuming high CPU — sniffed parameter made cost appear below parallelism threshold"}	null	2026-02-23 20:18:31.390309
4319	postgresql	query	Check for active pg_cron jobs with no hour restriction in schedule	{"sql": "SELECT jobid, schedule, command, active FROM cron.job WHERE active = true AND schedule LIKE '% * %'"}	{"condition": "row_count > 0", "description": "Active jobs using wildcard hour schedules run at all times without blackout restriction"}	\N	2026-02-25 00:28:52.405273
2351	sqlserver	query	Check missing index recommendations requesting INCLUDE columns	{"sql": "SELECT TOP 15\\n  mid.statement AS table_name,\\n  mid.equality_columns, mid.inequality_columns,\\n  mid.included_columns,\\n  migs.user_seeks, migs.user_scans,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE mid.database_id = DB_ID()\\n  AND mid.included_columns IS NOT NULL\\n  AND migs.user_seeks > 100\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND included_columns IS NOT NULL AND improvement_measure > 5000", "description": "Missing index recommendations with INCLUDE columns confirm existing indexes lack coverage for query output columns"}	null	2026-02-23 20:18:31.390324
2329	sqlserver	query	Check cost threshold vs actual query subtree costs	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'cost threshold for parallelism') AS cost_threshold,\\n  qp.query_plan.value('(//StmtSimple/@StatementSubTreeCost)[1]', 'float') AS subtree_cost,\\n  qp.query_plan.value('(//QueryPlan/@DegreeOfParallelism)[1]', 'int') AS plan_dop,\\n  qs.total_worker_time / qs.execution_count / 1000 AS avg_cpu_ms,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 150) AS query_fragment\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_worker_time / qs.execution_count > 5000000\\n  AND qp.query_plan.value('(//QueryPlan/@DegreeOfParallelism)[1]', 'int') IS NOT NULL\\n  AND qp.query_plan.value('(//QueryPlan/@DegreeOfParallelism)[1]', 'int') <= 1\\nORDER BY avg_cpu_ms DESC"}	{"condition": "subtree_cost < cost_threshold with avg_cpu_ms > 5000", "description": "Estimated cost below parallelism threshold but actual execution is expensive — sniffed parameter produced a low-cost estimate"}	null	2026-02-23 20:18:31.39031
3133	sqlserver	query	Check for unencrypted connections currently active	{"sql": "SELECT COUNT(*) AS unencrypted_connections\\nFROM sys.dm_exec_connections\\nWHERE encrypt_option = 'FALSE'"}	{"condition": "unencrypted_connections > 0", "description": "Unencrypted connections exist and are not being audited"}	null	2026-02-23 20:18:31.390311
3505	postgresql	query	Check replication slots for WAL retention	{"sql": "SELECT slot_name, active, restart_lsn, pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) AS retained_bytes, pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS retained_size FROM pg_replication_slots ORDER BY retained_bytes DESC"}	{"condition": "row_count = 0", "description": "No replication slots holding back WAL — segments may be recycled too aggressively"}	\N	2026-02-25 00:28:52.405273
2332	sqlserver	query	Find old cached plans with high execution counts	{"sql": "SELECT TOP 20\\n  qs.creation_time AS plan_created,\\n  DATEDIFF(hour, qs.creation_time, GETDATE()) AS plan_age_hours,\\n  qs.execution_count,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  OBJECT_NAME(qp.objectid) AS proc_name,\\n  SUBSTRING(t.text, (qs.statement_start_offset/2)+1, 200) AS query_fragment,\\n  cp.cacheobjtype, cp.objtype, cp.usecounts, cp.size_in_bytes\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nJOIN sys.dm_exec_cached_plans cp ON qs.plan_handle = cp.plan_handle\\nWHERE DATEDIFF(hour, qs.creation_time, GETDATE()) > 72\\n  AND qs.execution_count > 100\\n  AND qs.total_elapsed_time / qs.execution_count > 500000\\nORDER BY plan_age_hours DESC"}	{"condition": "cached plans older than 72 hours with avg_elapsed_ms > 500", "description": "Old cached plans still executing slowly — never invalidated despite potential data changes"}	null	2026-02-23 20:18:31.390311
4020	postgresql	query	Find inactive replication slots with WAL retention	{"sql": "SELECT slot_name, slot_type, active, restart_lsn, pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) AS retained_bytes, (pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) / (1024*1024))::bigint AS retained_mb FROM pg_replication_slots WHERE active = false ORDER BY retained_bytes DESC"}	{"condition": "row_count > 0 AND retained_mb > :threshold_mb", "description": "Inactive slots retaining significant WAL confirms the root cause"}	{"threshold_mb": 1024}	2026-02-25 00:28:52.405273
4021	postgresql	query	Check replication lag against wal_keep_size	{"sql": "SELECT r.client_addr, r.state, pg_wal_lsn_diff(pg_current_wal_lsn(), r.replay_lsn) AS lag_bytes, (pg_wal_lsn_diff(pg_current_wal_lsn(), r.replay_lsn) / (1024*1024))::bigint AS lag_mb, s.setting AS wal_keep_size_mb FROM pg_stat_replication r, pg_settings s WHERE s.name = 'wal_keep_size'"}	{"condition": "lag_mb > wal_keep_size_mb::int", "description": "Replication lag exceeds wal_keep_size, forcing extra WAL retention"}	\N	2026-02-25 00:28:52.405273
2333	sqlserver	query	Check if statistics were updated since plan creation	{"sql": "SELECT OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated AS stats_updated,\\n  sp.modification_counter,\\n  cp.creation_time AS plan_created,\\n  CASE WHEN sp.last_updated > cp.creation_time\\n    THEN 'Stats updated AFTER plan compiled' ELSE 'Stats NOT updated since plan compiled' END AS status\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nCROSS JOIN (\\n  SELECT TOP 1 qs.creation_time\\n  FROM sys.dm_exec_query_stats qs\\n  WHERE DATEDIFF(hour, qs.creation_time, GETDATE()) > 72\\n    AND qs.execution_count > 100\\n    AND qs.total_elapsed_time / qs.execution_count > 500000\\n  ORDER BY DATEDIFF(hour, qs.creation_time, GETDATE()) DESC\\n) cp\\nWHERE OBJECTPROPERTY(s.object_id, 'IsUserTable') = 1\\n  AND sp.modification_counter > 1000\\n  AND sp.last_updated < cp.creation_time\\nORDER BY sp.modification_counter DESC"}	{"condition": "statistics not updated since plan was compiled, with high modification counters", "description": "Plan cache entry compiled against old statistics — stats changed but plan was never recompiled"}	null	2026-02-23 20:18:31.390312
3131	sqlserver	query	Check if server is using self-signed certificate	{"sql": "DECLARE @cert_hash NVARCHAR(256);\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SOFTWARE\\\\Microsoft\\\\Microsoft SQL Server\\\\MSSQLServer\\\\SuperSocketNetLib',\\n  N'Certificate', @cert_hash OUTPUT;\\nSELECT CASE WHEN @cert_hash IS NULL OR @cert_hash = ''\\n  THEN 'self-signed' ELSE 'custom-certificate' END AS cert_status,\\n  @cert_hash AS certificate_hash;"}	{"condition": "cert_status = 'self-signed'", "description": "No custom certificate configured — using SQL Server self-signed cert, typical of dev/test carryover"}	null	2026-02-23 20:18:31.390313
2334	sqlserver	query	Check index selectivity via density and duplicate ratios	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  s.name AS stat_name,\\n  p.rows AS table_rows,\\n  ius.user_scans, ius.user_seeks,\\n  CASE WHEN (ius.user_scans + ius.user_seeks) > 0\\n    THEN CAST(ius.user_scans AS FLOAT) / (ius.user_scans + ius.user_seeks) * 100\\n    ELSE 0 END AS scan_pct\\nFROM sys.indexes i\\nJOIN sys.stats s ON i.object_id = s.object_id AND i.name = s.name\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.index_id > 0 AND i.type_desc = 'NONCLUSTERED'\\n  AND p.rows > 10000\\n  AND ius.user_scans > ius.user_seeks\\nORDER BY ius.user_scans DESC"}	{"condition": "row_count > 0 AND scan_pct > 60", "description": "Nonclustered indexes being scanned more than seeked on large tables suggest low selectivity"}	null	2026-02-23 20:18:31.390313
2335	sqlserver	query	Check density vectors for suspected low-selectivity indexes	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name,\\n  COL_NAME(ic.object_id, ic.column_id) AS column_name,\\n  ic.key_ordinal,\\n  p.rows AS table_rows,\\n  (SELECT TOP 1 CAST(sh.equal_rows AS FLOAT)\\n   FROM sys.dm_db_stats_histogram(i.object_id, i.index_id) sh\\n   ORDER BY sh.equal_rows DESC) AS max_equal_rows,\\n  (SELECT AVG(CAST(sh.equal_rows AS FLOAT))\\n   FROM sys.dm_db_stats_histogram(i.object_id, i.index_id) sh) AS avg_equal_rows\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.index_id > 0\\n  AND p.rows > 10000\\n  AND ius.user_scans > ius.user_seeks\\nORDER BY avg_equal_rows DESC"}	{"condition": "avg_equal_rows > table_rows * 0.05 OR max_equal_rows > table_rows * 0.10", "description": "Index leading column with average bucket containing >5% of rows or max bucket >10% confirms low selectivity — optimizer prefers scan over seek"}	null	2026-02-23 20:18:31.390314
2338	sqlserver	query	Check for plans with PlanAffectingConvert warnings and scans	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  p.query_plan.value('count(//Warnings/PlanAffectingConvert)', 'int') AS convert_warnings,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') AS scan_count,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//Warnings/PlanAffectingConvert') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND convert_warnings > 0 AND scan_count > 0", "description": "Plans with implicit conversion warnings AND scan operators confirm type mismatches preventing seeks"}	null	2026-02-23 20:18:31.390316
2347	sqlserver	query	Verify skewed tables show scan-dominant access patterns	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ius.user_scans, ius.user_seeks, ius.user_lookups,\\n  CASE WHEN (ius.user_scans + ius.user_seeks) > 0\\n    THEN CAST(ius.user_scans AS FLOAT) / (ius.user_scans + ius.user_seeks) * 100\\n    ELSE 0 END AS scan_pct,\\n  p.rows AS table_rows\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.partitions p ON ius.object_id = p.object_id AND ius.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.index_id IN (0, 1)\\n  AND p.rows > 10000\\n  AND ius.user_scans > 50\\nORDER BY ius.user_scans DESC"}	{"condition": "scan_pct > 50 AND table_rows > 10000", "description": "Tables with skewed distribution showing >50% scan access confirm optimizer correctly choosing scans for high-frequency values"}	null	2026-02-23 20:18:31.390317
2340	sqlserver	query	Check for expensive queries with NOT/inequality predicates and scans	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') AS scan_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') > 0\\n  AND (t.text LIKE '%NOT IN%' OR t.text LIKE '%NOT EXISTS%'\\n    OR t.text LIKE '%<>%' OR t.text LIKE '%!=%')\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND scan_count > 0", "description": "Queries with NOT/inequality predicates that produce scan operators indicate negation preventing index seeks"}	null	2026-02-23 20:18:31.390318
2341	sqlserver	query	Verify the scanned tables have indexes that could be used with positive predicates	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ius.user_scans, ius.user_seeks,\\n  p.rows AS table_rows,\\n  CASE WHEN (ius.user_scans + ius.user_seeks) > 0\\n    THEN CAST(ius.user_scans AS FLOAT) / (ius.user_scans + ius.user_seeks) * 100\\n    ELSE 0 END AS scan_pct\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.partitions p ON ius.object_id = p.object_id AND ius.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.user_scans > 100\\n  AND p.rows > 10000\\n  AND i.index_id > 0\\nORDER BY scan_pct DESC"}	{"condition": "scan_pct > 70 AND table_rows > 10000", "description": "Indexes being scanned >70% of the time on large tables confirm NOT operators are overriding the optimizer's ability to seek"}	null	2026-02-23 20:18:31.390318
3095	sqlserver	query	Check for permissions granted on linked server objects	{"sql": "SELECT s.name AS linked_server_name,\\n  s.data_source,\\n  perm.permission_name,\\n  perm.state_desc,\\n  dp.name AS grantee_name,\\n  dp.type_desc AS grantee_type,\\n  CASE\\n    WHEN dp.name = 'public' THEN 'CRITICAL: public role has linked server access'\\n    WHEN dp.type = 'R' THEN 'ROLE_GRANT: ' + dp.name\\n    ELSE 'LOGIN_GRANT: ' + dp.name\\n  END AS access_assessment\\nFROM sys.servers s\\nLEFT JOIN sys.server_permissions perm ON perm.major_id = s.server_id\\nLEFT JOIN sys.server_principals dp ON perm.grantee_principal_id = dp.principal_id\\nWHERE s.is_linked = 1\\n  AND perm.permission_name IN ('CONNECT', 'ALTER', 'ALTER ANY LINKED SERVER')\\n  AND perm.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')"}	{"condition": "public role or broad server roles have CONNECT permission on linked servers", "description": "Linked server access is granted to public or broad roles — any authenticated user can use the linked server"}	null	2026-02-23 20:18:31.390785
2350	sqlserver	query	Check for indexes with high key lookup ratios	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ius.user_seeks, ius.user_lookups, ius.user_scans,\\n  CASE WHEN ius.user_seeks > 0\\n    THEN CAST(ius.user_lookups AS FLOAT) / ius.user_seeks\\n    ELSE 0 END AS lookups_per_seek,\\n  ios.singleton_lookup_count,\\n  ios.range_scan_count\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\n  ON ius.object_id = ios.object_id AND ius.index_id = ios.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND i.type_desc = 'NONCLUSTERED'\\n  AND ius.user_lookups > ius.user_seeks * 0.5\\n  AND ius.user_seeks > 100\\nORDER BY ius.user_lookups DESC"}	{"condition": "row_count > 0 AND lookups_per_seek > 0.5", "description": "Nonclustered indexes with >50% lookup-to-seek ratio indicate the index is not covering query columns"}	null	2026-02-23 20:18:31.390324
2342	sqlserver	query	Check for queries with scalar operators on columns in scan predicates	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') AS scan_count,\\n  p.query_plan.value('count(//ScalarOperator[contains(@ScalarString,\\"CONVERT\\") or contains(@ScalarString,\\"datepart\\") or contains(@ScalarString,\\"isnull\\") or contains(@ScalarString,\\"upper\\") or contains(@ScalarString,\\"lower\\")])', 'int') AS function_on_column_count,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') > 0\\n  AND (t.text LIKE '%CONVERT(%' OR t.text LIKE '%DATEPART(%'\\n    OR t.text LIKE '%YEAR(%' OR t.text LIKE '%MONTH(%'\\n    OR t.text LIKE '%ISNULL(%' OR t.text LIKE '%UPPER(%'\\n    OR t.text LIKE '%LOWER(%' OR t.text LIKE '%SUBSTRING(%'\\n    OR t.text LIKE '%CAST(%')\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND scan_count > 0 AND function_on_column_count > 0", "description": "Queries with function calls on columns that also produce scan operators indicate non-SARGable predicates"}	null	2026-02-23 20:18:31.390319
3506	postgresql	config_check	Check settings that affect WAL compatibility	{"sql": "SELECT name, setting, pending_restart FROM pg_settings WHERE name IN ('max_connections', 'max_prepared_transactions', 'max_locks_per_transaction', 'max_wal_senders', 'max_worker_processes', 'wal_level') AND pending_restart = true"}	{"condition": "row_count > 0", "description": "Configuration changes pending restart that affect WAL replay"}	\N	2026-02-25 00:28:52.405273
2343	sqlserver	query	Correlate scanned tables with existing indexes that should be seekable	{"sql": "SELECT TOP 10\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  COL_NAME(ic.object_id, ic.column_id) AS leading_column,\\n  TYPE_NAME(c.user_type_id) AS column_type,\\n  ius.user_scans, ius.user_seeks,\\n  p.rows AS table_rows\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.partitions p ON ius.object_id = p.object_id AND ius.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.user_scans > ius.user_seeks * 2\\n  AND p.rows > 10000\\n  AND i.index_id > 0\\n  AND c.user_type_id IN (40, 42, 43, 61, 167, 175, 231, 239)\\nORDER BY ius.user_scans DESC"}	{"condition": "row_count > 0 AND user_scans > user_seeks * 2", "description": "Indexes on date/string columns being scanned rather than seeked confirms functions are wrapping the indexed column"}	null	2026-02-23 20:18:31.39032
2344	sqlserver	query	Check for expensive queries with OR predicates producing scans	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') AS scan_count,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Concatenation\\"])', 'int') AS concat_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') > 0\\n  AND t.text LIKE '% OR %'\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND scan_count > 0", "description": "Queries with OR conditions producing scan operators instead of index union (Concatenation) confirm non-indexed OR branches"}	null	2026-02-23 20:18:31.39032
2345	sqlserver	query	Check for missing indexes on columns involved in OR predicates	{"sql": "SELECT TOP 15\\n  mid.statement AS table_name,\\n  mid.equality_columns, mid.inequality_columns,\\n  migs.user_seeks, migs.user_scans,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE mid.database_id = DB_ID()\\n  AND (mid.equality_columns IS NOT NULL\\n    AND CHARINDEX(',', mid.equality_columns) = 0)\\n  AND migs.user_seeks > 50\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND improvement_measure > 5000", "description": "Missing single-column index recommendations on tables with OR queries confirm non-indexed OR branches"}	null	2026-02-23 20:18:31.390321
3329	sqlserver	query	Check linked servers pointing to data warehouse targets	{"sql": "SELECT s.name AS linked_server, s.product,\\n  s.provider, s.data_source, s.catalog,\\n  ll.uses_self_credential, ll.remote_name\\nFROM sys.servers s\\nLEFT JOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nWHERE s.is_linked = 1\\nORDER BY s.name"}	{"condition": "linked servers to DW/analytics targets", "description": "Linked servers provide direct data paths to warehouses — PII may flow unmasked through cross-server queries"}	null	2026-02-23 20:18:31.390321
2349	sqlserver	query	Check auto-create and auto-update statistics database settings	{"sql": "SELECT\\n  d.name AS database_name,\\n  d.is_auto_create_stats_on,\\n  d.is_auto_update_stats_on,\\n  d.is_auto_update_stats_async_on,\\n  (SELECT COUNT(*) FROM sys.stats s\\n   JOIN sys.partitions p ON s.object_id = p.object_id\\n   WHERE p.rows > 1000 AND s.auto_created = 0 AND s.user_created = 0) AS index_stats_only,\\n  (SELECT COUNT(*) FROM sys.stats WHERE auto_created = 1) AS auto_created_stats,\\n  (SELECT COUNT(*) FROM sys.stats WHERE user_created = 1) AS user_created_stats\\nFROM sys.databases d\\nWHERE d.database_id = DB_ID()"}	{"condition": "is_auto_create_stats_on = 0 OR is_auto_update_stats_on = 0 OR auto_created_stats = 0", "description": "Auto-create/update statistics disabled or no auto-created statistics confirm the optimizer lacks data distribution info"}	null	2026-02-23 20:18:31.390323
11616	mysql	query	Check for UDFs that enable OS command execution	{"sql": "SELECT name, type, dl FROM mysql.func WHERE dl LIKE '%lib_mysqludf_sys%' OR name IN ('sys_exec', 'sys_eval', 'sys_get', 'sys_set');"}	{"condition": "row_count > 0", "description": "OS command execution UDFs are installed"}	\N	2026-03-01 06:30:58.706791
2352	sqlserver	query	Check for queries with available indexes but optimizer choosing scans	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_output_rows,\\n  qs.execution_count,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') AS ci_scan_count,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Index Seek\\"])', 'int') AS seek_count,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"]/@EstimateRows)[1]', 'float') AS estimated_scan_rows,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"]/@TableCardinality)[1]', 'float') AS table_cardinality,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') > 0\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\n  AND qs.execution_count > 10\\nORDER BY avg_reads DESC"}	{"condition": "row_count > 0 AND estimated_scan_rows > table_cardinality * 0.15", "description": "Clustered index scans where estimated rows exceed 15% of table cardinality indicate the optimizer correctly chose scan over seek"}	null	2026-02-23 20:18:31.390325
14713	mariadb	query	Verify no audit plugin providing alternative logging	{"sql": "SELECT PLUGIN_NAME, PLUGIN_STATUS FROM information_schema.PLUGINS WHERE PLUGIN_NAME LIKE '%audit%'"}	{"condition": "row_count = 0 OR PLUGIN_STATUS != 'ACTIVE'", "description": "No active audit plugin confirms all SQL logging is disabled"}	\N	2026-05-11 22:17:39.229791
2353	sqlserver	query	Verify no missing index suggestions for these scans (optimizer's choice is informed)	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  ius.user_scans, ius.user_seeks,\\n  p.rows AS table_rows,\\n  (SELECT COUNT(*) FROM sys.dm_db_missing_index_details mid\\n   WHERE mid.database_id = DB_ID()\\n     AND mid.statement LIKE '%' + OBJECT_NAME(ius.object_id) + '%') AS missing_index_count\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.partitions p ON ius.object_id = p.object_id AND ius.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.index_id = 1\\n  AND ius.user_scans > 100\\n  AND p.rows > 10000\\nORDER BY ius.user_scans DESC"}	{"condition": "missing_index_count = 0 AND user_scans > 100", "description": "Frequent scans with no missing index recommendations confirm the optimizer deliberately chose scan as the cheapest option"}	null	2026-02-23 20:18:31.390326
2354	sqlserver	query	Check for small tables being scanned with available indexes	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ius.user_scans, ius.user_seeks,\\n  p.rows AS table_rows,\\n  SUM(a.total_pages) * 8 AS table_kb,\\n  (SELECT COUNT(*) FROM sys.indexes i2\\n   WHERE i2.object_id = ius.object_id AND i2.index_id > 1) AS nonclustered_index_count\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.partitions p ON ius.object_id = p.object_id AND ius.index_id = p.index_id\\nJOIN sys.allocation_units a ON p.partition_id = a.container_id\\nWHERE ius.database_id = DB_ID()\\n  AND ius.index_id IN (0, 1)\\n  AND p.rows < 5000\\n  AND ius.user_scans > 100\\nGROUP BY ius.object_id, i.name, i.type_desc, ius.user_scans, ius.user_seeks, p.rows\\nHAVING SUM(a.total_pages) * 8 < 1024\\nORDER BY ius.user_scans DESC"}	{"condition": "row_count > 0 AND table_rows < 5000 AND table_kb < 1024", "description": "Tables with <5K rows and <1MB that are frequently scanned despite having indexes"}	null	2026-02-23 20:18:31.390326
2355	sqlserver	query	Verify these small tables have nonclustered indexes that are being ignored	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  ius.user_seeks, ius.user_scans,\\n  p.rows AS table_rows,\\n  CASE WHEN ius.user_seeks = 0 AND ius.user_scans = 0 AND ius.user_lookups = 0\\n    THEN 'UNUSED'\\n    ELSE 'IN USE' END AS index_status\\nFROM sys.indexes i\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.index_id > 1\\n  AND p.rows < 5000\\n  AND (ius.user_seeks IS NULL OR ius.user_seeks = 0)\\nORDER BY p.rows DESC"}	{"condition": "row_count > 0 AND index_status = 'UNUSED'", "description": "Unused nonclustered indexes on small tables confirm the optimizer always prefers scanning the small table directly"}	null	2026-02-23 20:18:31.390327
2449	sqlserver	query	Find join queries with PlanAffectingConvert warnings indicating implicit conversion	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.exist('//Warnings/PlanAffectingConvert') AS has_convert_warning,\\n  p.query_plan.value('count(//ScalarOperator[contains(@ScalarString,\\"CONVERT_IMPLICIT\\")])', 'int') AS implicit_converts,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') AS total_scans,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE t.text LIKE '%JOIN%'\\n  AND p.query_plan.exist('//Warnings/PlanAffectingConvert') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\n  AND qs.execution_count > 5\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "has_convert_warning = 1 AND implicit_converts > 0 AND total_scans > 0", "description": "JOIN queries with PlanAffectingConvert warnings and CONVERT_IMPLICIT operations — implicit type conversion preventing index usage"}	null	2026-02-23 20:18:31.390393
2367	sqlserver	query	Check for auto-create statistics and multi-column statistics gaps	{"sql": "SELECT\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  COUNT(CASE WHEN s.auto_created = 1 THEN 1 END) AS auto_stats,\\n  COUNT(CASE WHEN s.user_created = 1 THEN 1 END) AS user_stats,\\n  COUNT(CASE WHEN s.auto_created = 0 AND s.user_created = 0 THEN 1 END) AS index_stats,\\n  (SELECT COUNT(*) FROM sys.columns c2 WHERE c2.object_id = s.object_id) AS total_columns,\\n  COUNT(DISTINCT s.stats_id) AS total_stats,\\n  p.rows AS table_rows\\nFROM sys.stats s\\nJOIN sys.partitions p ON s.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE p.rows > 10000\\nGROUP BY s.object_id, p.rows\\nHAVING COUNT(DISTINCT s.stats_id) < (SELECT COUNT(*) FROM sys.columns c2 WHERE c2.object_id = s.object_id) * 0.3\\nORDER BY p.rows DESC"}	{"condition": "row_count > 0 AND total_stats < total_columns * 0.3", "description": "Large tables with statistics on fewer than 30% of columns indicate many predicate columns lack histogram data"}	null	2026-02-23 20:18:31.390336
2539	sqlserver	query	Check log reuse wait for CDC or other archiving dependency	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  d.is_cdc_enabled,\\n  lu.cntr_value / 1024 AS log_used_mb,\\n  CAST(lu.cntr_value AS FLOAT) / NULLIF(ls.cntr_value, 0) * 100 AS log_used_pct\\nFROM sys.databases d\\nJOIN sys.dm_os_performance_counters ls\\n  ON ls.counter_name = 'Log File(s) Size (KB)' AND ls.instance_name = d.name\\nJOIN sys.dm_os_performance_counters lu\\n  ON lu.counter_name = 'Log File(s) Used Size (KB)' AND lu.instance_name = d.name\\nWHERE d.database_id > 4\\n  AND (d.log_reuse_wait_desc IN ('REPLICATION', 'LOG_SCAN')\\n    OR (d.is_cdc_enabled = 1 AND d.log_reuse_wait_desc <> 'NOTHING'))"}	{"condition": "CDC-enabled databases with log reuse blocked or LOG_SCAN wait", "description": "CDC capture job not reading log fast enough — log cannot be truncated past CDC's position"}	null	2026-02-23 20:18:31.390337
2356	sqlserver	query	Check for scans on composite indexes where seeks would indicate leading column use	{"sql": "SELECT\\n  OBJECT_NAME(i.object_id) AS table_name,\\n  i.name AS index_name, i.type_desc,\\n  (SELECT STRING_AGG(COL_NAME(ic2.object_id, ic2.column_id), ', ')\\n     WITHIN GROUP (ORDER BY ic2.key_ordinal)\\n   FROM sys.index_columns ic2\\n   WHERE ic2.object_id = i.object_id AND ic2.index_id = i.index_id AND ic2.is_included_column = 0\\n  ) AS key_columns,\\n  ius.user_scans, ius.user_seeks,\\n  CASE WHEN (ius.user_scans + ius.user_seeks) > 0\\n    THEN CAST(ius.user_scans AS FLOAT) / (ius.user_scans + ius.user_seeks) * 100\\n    ELSE 0 END AS scan_pct,\\n  p.rows AS table_rows\\nFROM sys.indexes i\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id\\nJOIN sys.partitions p ON i.object_id = p.object_id AND i.index_id = p.index_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius\\n  ON i.object_id = ius.object_id AND i.index_id = ius.index_id AND ius.database_id = DB_ID()\\nWHERE i.type_desc = 'NONCLUSTERED'\\n  AND ic.is_included_column = 0\\nGROUP BY i.object_id, i.name, i.type_desc, i.index_id, ius.user_scans, ius.user_seeks, p.rows\\nHAVING COUNT(ic.column_id) >= 2\\n  AND ius.user_scans > ius.user_seeks\\n  AND p.rows > 10000\\nORDER BY ius.user_scans DESC"}	{"condition": "row_count > 0 AND scan_pct > 60 AND table_rows > 10000", "description": "Multi-column indexes being scanned rather than seeked on large tables suggest queries skip the leading key column"}	null	2026-02-23 20:18:31.390328
2357	sqlserver	query	Check for missing index recommendations suggesting different column order	{"sql": "SELECT TOP 15\\n  mid.statement AS table_name,\\n  mid.equality_columns AS suggested_key,\\n  mid.inequality_columns AS suggested_inequality,\\n  mid.included_columns,\\n  migs.user_seeks, migs.user_scans,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE mid.database_id = DB_ID()\\n  AND mid.equality_columns IS NOT NULL\\n  AND migs.user_seeks > 50\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND improvement_measure > 5000", "description": "Missing index recommendations with different leading columns confirm queries need the composite index in a different key order"}	null	2026-02-23 20:18:31.390329
2358	sqlserver	query	Check for queries with NULL predicates producing scans	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') AS scan_count,\\n  SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\" or @PhysicalOp=\\"Index Scan\\"])', 'int') > 0\\n  AND (t.text LIKE '%IS NULL%' OR t.text LIKE '%IS NOT NULL%')\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND scan_count > 0", "description": "Queries with IS NULL/IS NOT NULL predicates causing scans on large tables"}	null	2026-02-23 20:18:31.390329
4023	postgresql	query	Verify WAL directory matches expected retention	{"sql": "SELECT count(*) AS wal_file_count, pg_size_pretty(sum(size)) AS total_wal_size, (sum(size) / (1024*1024))::bigint AS total_mb FROM pg_ls_waldir()"}	{"condition": "total_mb > :threshold_mb", "description": "WAL directory size matches or exceeds wal_keep_size setting, confirming over-retention"}	{"threshold_mb": 10240}	2026-02-25 00:28:52.405273
2359	sqlserver	query	Check NULL density in column statistics for affected tables	{"sql": "SELECT\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  COL_NAME(s.object_id, sc.column_id) AS column_name,\\n  sp.rows AS total_rows,\\n  (SELECT TOP 1 h.equal_rows\\n   FROM sys.dm_db_stats_histogram(s.object_id, s.stats_id) h\\n   WHERE h.range_high_key IS NULL) AS null_count,\\n  CASE WHEN sp.rows > 0 THEN\\n    CAST((SELECT TOP 1 h.equal_rows\\n          FROM sys.dm_db_stats_histogram(s.object_id, s.stats_id) h\\n          WHERE h.range_high_key IS NULL) AS FLOAT) / sp.rows * 100\\n    ELSE 0 END AS null_pct\\nFROM sys.stats s\\nJOIN sys.stats_columns sc ON s.object_id = sc.object_id AND s.stats_id = sc.stats_id\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 10000\\nORDER BY null_pct DESC"}	{"condition": "null_pct > 20 OR null_pct < 1", "description": "Very high NULL percentage (IS NOT NULL returns most rows — scan is cheaper) or very low NULL percentage but still scanning indicates optimizer limitation or missing filtered index"}	null	2026-02-23 20:18:31.39033
2360	sqlserver	query	Check for queries with range predicates producing large scans	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_output_rows,\\n  qs.execution_count,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Index Scan\\" or @PhysicalOp=\\"Clustered Index Scan\\"]/@EstimateRows)[1]', 'float') AS estimated_scan_rows,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Index Scan\\" or @PhysicalOp=\\"Clustered Index Scan\\"]/@TableCardinality)[1]', 'float') AS table_cardinality,\\n  SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND (t.text LIKE '%>%' OR t.text LIKE '%>=%' OR t.text LIKE '%BETWEEN%')\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Index Scan\\" or @PhysicalOp=\\"Clustered Index Scan\\"])', 'int') > 0\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND estimated_scan_rows > table_cardinality * 0.30", "description": "Scans where estimated rows exceed 30% of table cardinality with range predicates suggest open-ended ranges"}	null	2026-02-23 20:18:31.39033
2374	sqlserver	query	Check for high single-use ad-hoc plan cache bloat	{"sql": "SELECT\\n  COUNT(*) AS total_adhoc_plans,\\n  SUM(CASE WHEN cp.usecounts = 1 THEN 1 ELSE 0 END) AS single_use_plans,\\n  CAST(SUM(CASE WHEN cp.usecounts = 1 THEN 1 ELSE 0 END) AS FLOAT) / NULLIF(COUNT(*), 0) * 100 AS single_use_pct,\\n  SUM(CASE WHEN cp.usecounts = 1 THEN cp.size_in_bytes ELSE 0 END) / 1024 / 1024 AS single_use_mb,\\n  SUM(cp.size_in_bytes) / 1024 / 1024 AS total_adhoc_mb\\nFROM sys.dm_exec_cached_plans cp\\nWHERE cp.cacheobjtype = 'Compiled Plan'\\n  AND cp.objtype = 'Adhoc'"}	{"condition": "single_use_pct > 50 AND single_use_plans > 1000", "description": "Over 50% single-use ad-hoc plans indicate literal values causing unique compilations instead of plan reuse"}	null	2026-02-23 20:18:31.390331
3515	postgresql	log_scan	Scan for storage API errors	{"pattern": "S3.*error|HTTP.*4[0-9][0-9].*delete|storage.*API.*error|rate limit.*exceeded|throttl|could not delete.*remote", "description": "Storage API errors during backup cleanup"}	{"condition": "pattern_found", "description": "Storage API failures preventing backup deletion"}	\N	2026-02-25 00:28:52.405273
2361	sqlserver	query	Check if bounded range would enable index seek on same columns	{"sql": "SELECT\\n  OBJECT_NAME(ius.object_id) AS table_name,\\n  i.name AS index_name,\\n  COL_NAME(ic.object_id, ic.column_id) AS leading_column,\\n  TYPE_NAME(c.user_type_id) AS column_type,\\n  ius.user_scans, ius.user_seeks,\\n  p.rows AS table_rows,\\n  CASE WHEN (ius.user_scans + ius.user_seeks) > 0\\n    THEN CAST(ius.user_scans AS FLOAT) / (ius.user_scans + ius.user_seeks) * 100\\n    ELSE 0 END AS scan_pct\\nFROM sys.dm_db_index_usage_stats ius\\nJOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id\\nJOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id AND ic.key_ordinal = 1\\nJOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id\\nJOIN sys.partitions p ON ius.object_id = p.object_id AND ius.index_id = p.index_id\\nWHERE ius.database_id = DB_ID()\\n  AND c.user_type_id IN (40, 42, 43, 61, 56, 127)\\n  AND ius.user_scans > ius.user_seeks\\n  AND p.rows > 10000\\nORDER BY ius.user_scans DESC"}	{"condition": "scan_pct > 50 AND table_rows > 10000", "description": "Indexes on date/integer leading columns being scanned more than seeked confirm unbounded range queries"}	null	2026-02-23 20:18:31.390332
