2362	sqlserver	query	Check for statistics with high modification counts relative to row counts	{"sql": "SELECT TOP 20\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  s.auto_created, s.user_created,\\n  sp.last_updated,\\n  DATEDIFF(DAY, sp.last_updated, GETDATE()) AS days_since_update,\\n  sp.rows AS stat_rows,\\n  sp.rows_sampled,\\n  CAST(sp.rows_sampled AS FLOAT) / NULLIF(sp.rows, 0) * 100 AS sample_pct,\\n  sp.modification_counter,\\n  CAST(sp.modification_counter AS FLOAT) / NULLIF(sp.rows, 0) * 100 AS mod_pct\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.rows > 1000\\n  AND (sp.modification_counter > sp.rows * 0.20\\n    OR DATEDIFF(DAY, sp.last_updated, GETDATE()) > 7)\\nORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0 AND (mod_pct > 20 OR days_since_update > 7)", "description": "Statistics with >20% modifications since last update or not updated in 7+ days are stale"}	null	2026-02-23 20:18:31.390333
4027	postgresql	query	Find inactive physical replication slots with significant WAL retention	{"sql": "SELECT slot_name, slot_type, active, restart_lsn, pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) AS retained_bytes, (pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) / (1024*1024))::bigint AS retained_mb FROM pg_replication_slots WHERE slot_type = 'physical' AND active = false"}	{"condition": "row_count > 0 AND retained_mb > :threshold_mb", "description": "Inactive physical slot with large WAL retention confirms disconnected standby"}	{"threshold_mb": 512}	2026-02-25 00:28:52.405273
2363	sqlserver	query	Correlate stale statistics with expensive query plans on those tables	{"sql": "SELECT TOP 15\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.last_rows AS last_actual_rows,\\n  p.query_plan.exist('//StmtSimple[@StatementOptmLevel=\\"FULL\\"]') AS fully_optimized,\\n  p.query_plan.value('count(//Warnings)', 'int') AS warning_count,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.execution_count > 5\\nORDER BY avg_elapsed_ms DESC"}	{"condition": "row_count > 0 AND warning_count > 0", "description": "Expensive queries with plan warnings on tables with stale statistics confirm outdated stats driving bad plans"}	null	2026-02-23 20:18:31.390334
2364	sqlserver	query	Check for plans with PlanAffectingConvert warnings affecting cardinality	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//Warnings/PlanAffectingConvert[@ConvertIssue=\\"Cardinality Estimate\\"])', 'int') AS ce_convert_warnings,\\n  p.query_plan.value('count(//Warnings/PlanAffectingConvert[@ConvertIssue=\\"Seek Plan\\"])', 'int') AS seek_convert_warnings,\\n  p.query_plan.value('count(//Warnings/PlanAffectingConvert)', 'int') AS total_convert_warnings,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//Warnings/PlanAffectingConvert') = 1\\n  AND qs.total_elapsed_time / NULLIF(qs.execution_count, 0) > 1000000\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "row_count > 0 AND (ce_convert_warnings > 0 OR seek_convert_warnings > 0)", "description": "Plans with Cardinality Estimate or Seek Plan conversion warnings confirm type mismatches affecting plan quality"}	null	2026-02-23 20:18:31.390334
2365	sqlserver	query	Identify specific columns and types involved in the conversion	{"sql": "SELECT TOP 10\\n  qs.sql_handle,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  p.query_plan.value('(//Warnings/PlanAffectingConvert/@Expression)[1]', 'nvarchar(500)') AS convert_expr_1,\\n  p.query_plan.value('(//Warnings/PlanAffectingConvert/@ConvertIssue)[1]', 'nvarchar(200)') AS convert_issue_1,\\n  p.query_plan.value('(//Warnings/PlanAffectingConvert/@Expression)[2]', 'nvarchar(500)') AS convert_expr_2,\\n  p.query_plan.value('(//Warnings/PlanAffectingConvert/@ConvertIssue)[2]', 'nvarchar(200)') AS convert_issue_2,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//Warnings/PlanAffectingConvert') = 1\\n  AND qs.total_elapsed_time / NULLIF(qs.execution_count, 0) > 1000000\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "convert_expr_1 IS NOT NULL", "description": "Specific conversion expressions identify the exact columns and type mismatches causing the suboptimal plan"}	null	2026-02-23 20:18:31.390335
2366	sqlserver	query	Check for columns used in predicates that lack statistics	{"sql": "SELECT TOP 20\\n  mid.statement AS table_name,\\n  mid.equality_columns, mid.inequality_columns,\\n  migs.user_seeks, migs.user_scans,\\n  migs.avg_total_user_cost,\\n  migs.avg_user_impact,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure\\nFROM sys.dm_db_missing_index_details mid\\nJOIN sys.dm_db_missing_index_groups mig ON mid.index_handle = mig.index_handle\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nWHERE mid.database_id = DB_ID()\\n  AND migs.avg_user_impact > 80\\n  AND migs.user_seeks > 100\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND avg_user_impact > 80", "description": "Missing indexes with >80% estimated impact and frequent seeks indicate columns critically lacking statistics"}	null	2026-02-23 20:18:31.390335
2368	sqlserver	query	Check for queries with large estimated vs actual row discrepancies	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_actual_rows,\\n  qs.last_rows AS last_actual_rows,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  p.query_plan.value('(//RelOp/@EstimateRows)[1]', 'float') AS first_op_estimate,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.execution_count > 5\\n  AND qs.total_elapsed_time / NULLIF(qs.execution_count, 0) > 1000000\\n  AND (qs.total_spills > 0\\n    OR qs.total_grant_kb / NULLIF(qs.execution_count, 0) > qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) * 3)\\nORDER BY avg_elapsed_ms DESC"}	{"condition": "row_count > 0 AND (avg_spills > 0 OR avg_grant_kb > avg_ideal_kb * 3)", "description": "Queries with spills or grossly over/under-estimated memory grants indicate CE estimation errors"}	null	2026-02-23 20:18:31.390337
2370	sqlserver	query	Check for expensive multi-join queries with optimizer timeout or high cost	{"sql": "SELECT TOP 15\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.exist('//StmtSimple[@StatementOptmEarlyAbortReason=\\"TimeOut\\"]') AS optimizer_timeout,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\" or @PhysicalOp=\\"Merge Join\\" or @PhysicalOp=\\"Nested Loops\\"])', 'int') AS join_count,\\n  p.query_plan.value('count(//RelOp)', 'int') AS total_operators,\\n  p.query_plan.value('(//StmtSimple/@StatementSubTreeCost)[1]', 'float') AS estimated_cost,\\n  t.text AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 50000\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\" or @PhysicalOp=\\"Merge Join\\" or @PhysicalOp=\\"Nested Loops\\"])', 'int') >= 3\\nORDER BY avg_elapsed_ms DESC"}	{"condition": "row_count > 0 AND (optimizer_timeout = 1 OR (join_count >= 3 AND avg_reads > 50000))", "description": "Multi-join queries with optimizer timeout or very high cost indicate join ordering problems"}	null	2026-02-23 20:18:31.390339
