2416	sqlserver	query	Find expensive queries with WHERE-clause subquery patterns	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"])', 'int') AS nested_loop_count,\\n  p.query_plan.exist('//Predicate//ScalarOperator/Subquery') AS has_predicate_subquery,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\n  AND qs.execution_count > 5\\n  AND (t.text LIKE '%WHERE%EXISTS%(%SELECT%'\\n    OR t.text LIKE '%WHERE%IN%(%SELECT%'\\n    OR t.text LIKE '%WHERE%>%(%SELECT%'\\n    OR t.text LIKE '%WHERE%<%(%SELECT%')\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND avg_reads > 5000", "description": "Queries with subqueries in WHERE clause and high logical reads indicate correlated evaluation"}	null	2026-02-23 20:18:31.39037
2417	sqlserver	query	Confirm correlated WHERE subquery via plan with nested loops and outer references	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') AS correlated_nested_loops,\\n  p.query_plan.exist('//SeekPredicates//ColumnReference[@Table]') AS seeks_on_inner,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND qs.execution_count > 5\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "correlated_nested_loops > 0 AND avg_elapsed_ms > 500", "description": "Execution plan confirms correlated subquery in WHERE with outer references driving nested loops per outer row"}	null	2026-02-23 20:18:31.390371
2418	sqlserver	query	Find queries with scalar subquery operators in execution plan	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.exist('//ScalarOperator/Subquery') AS has_scalar_subquery,\\n  p.query_plan.value('count(//ScalarOperator/Subquery)', 'int') AS scalar_subquery_count,\\n  SUBSTRING(t.text, 1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//ScalarOperator/Subquery') = 1\\n  AND qs.total_elapsed_time / NULLIF(qs.execution_count, 0) > 500000\\n  AND qs.execution_count > 3\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "has_scalar_subquery = 1 AND avg_elapsed_ms > 500", "description": "Queries with scalar subquery operators in the plan indicate non-optimized per-row execution"}	null	2026-02-23 20:18:31.390372
2419	sqlserver	query	Confirm per-row execution via actual execution stats showing high inner executions	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.last_rows AS last_outer_rows,\\n  qs.last_logical_reads,\\n  qs.last_elapsed_time / 1000 AS last_elapsed_ms,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/@EstimateRows)[1]', 'float') AS est_rows,\\n  p.query_plan.value('count(//ScalarOperator/Subquery)', 'int') AS scalar_subqueries,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//ScalarOperator/Subquery') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.execution_count > 3\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "avg_reads > 10000 AND scalar_subqueries >= 1", "description": "High logical reads with scalar subquery confirms optimizer could not flatten the subquery into a join — per-row evaluation"}	null	2026-02-23 20:18:31.390372
