2428	sqlserver	query	Find queries with nested loops where inner side does table/index scan instead of seek	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') AS outer_ref_loops,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\"])', 'int') AS table_scans,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') AS ci_scans,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Index Scan\\"])', 'int') AS ix_scans,\\n  SUBSTRING(t.text, 1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND (p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\"])', 'int') > 0\\n    OR p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') > 0)\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 50000\\n  AND qs.execution_count > 3\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "outer_ref_loops > 0 AND (table_scans > 0 OR ci_scans > 0) AND avg_reads > 50000", "description": "Correlated subquery with full scans on inner side — outer predicates not pushed down to narrow the subquery"}	null	2026-02-23 20:18:31.390379
2429	sqlserver	query	Check for missing index recommendations on subquery inner tables	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//MissingIndexGroup)', 'int') AS missing_index_suggestions,\\n  p.query_plan.value('(//MissingIndexGroup/@Impact)[1]', 'float') AS top_index_impact,\\n  p.query_plan.value('(//MissingIndex/@Table)[1]', 'nvarchar(256)') AS suggested_table,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND p.query_plan.exist('//MissingIndexGroup') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 50000\\nORDER BY p.query_plan.value('(//MissingIndexGroup/@Impact)[1]', 'float') DESC"}	{"condition": "missing_index_suggestions > 0 AND top_index_impact > 50", "description": "Missing index on inner table of correlated subquery confirms predicates cannot be pushed down efficiently — index would enable seek instead of scan"}	null	2026-02-23 20:18:31.39038
2430	sqlserver	query	Find correlated nested loops with table scans or clustered index scans on inner side	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') AS outer_ref_loops,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\"])', 'int') +\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') AS full_scans,\\n  p.query_plan.value('count(//MissingIndexGroup)', 'int') AS missing_indexes,\\n  SUBSTRING(t.text, 1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND (p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\"])', 'int') > 0\\n    OR p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') > 0\\n    OR p.query_plan.exist('//MissingIndexGroup') = 1)\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 20000\\n  AND qs.execution_count > 3\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "outer_ref_loops > 0 AND full_scans > 0 AND avg_reads > 20000", "description": "Correlated nested loops with full scans on inner side — missing indexes on correlation columns"}	null	2026-02-23 20:18:31.39038
2431	sqlserver	query	Cross-reference with missing index DMVs for affected tables	{"sql": "SELECT TOP 15\\n  mid.statement AS table_name,\\n  migs.avg_user_impact,\\n  migs.user_seeks + migs.user_scans AS total_accesses,\\n  mid.equality_columns, mid.inequality_columns, mid.included_columns,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure\\nFROM sys.dm_db_missing_index_groups mig\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nJOIN sys.dm_db_missing_index_details mid ON mig.index_handle = mid.index_handle\\nWHERE migs.avg_user_impact > 50\\n  AND (migs.user_seeks + migs.user_scans) > 100\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND avg_user_impact > 50", "description": "Missing index DMVs confirm high-impact missing indexes on tables used in correlated subqueries"}	null	2026-02-23 20:18:31.390381
2432	sqlserver	query	Find queries where optimizer kept subquery instead of transforming to join	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.exist('//ScalarOperator/Subquery') AS has_scalar_subquery,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') AS outer_ref_loops,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\" and @LogicalOp=\\"Inner Join\\"])', 'int') AS hash_joins,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Merge Join\\"])', 'int') AS merge_joins,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//ScalarOperator/Subquery') = 1\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.execution_count > 5\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "has_scalar_subquery = 1 AND outer_ref_loops > 0 AND hash_joins = 0 AND merge_joins = 0", "description": "Optimizer kept correlated subquery as nested loops with outer references instead of transforming to hash/merge join — decorrelation failed"}	null	2026-02-23 20:18:31.390382
2674	sqlserver	query	Check SQL logins with no recent activity suggesting abandoned migration	{"sql": "SELECT sp.name AS sql_login, sp.create_date, sp.modify_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\nORDER BY sp.modify_date ASC"}	{"condition": "SQL logins not modified in > 180 days or with no recent sessions", "description": "Stale SQL logins suggest migration to Windows Auth was abandoned mid-process"}	null	2026-02-23 20:18:31.390382
