2434	sqlserver	query	Find queries with table variable references and nested loops with outer references	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.min_rows, qs.max_rows,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') AS outer_ref_loops,\\n  p.query_plan.exist('//Object[@Table=\\"@\\"]') AS has_table_var_ref,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE (t.text LIKE '%@%' AND t.text LIKE '%SELECT%(%SELECT%')\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\n  AND qs.execution_count > 3\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "outer_ref_loops > 0 AND avg_reads > 5000", "description": "Queries with table variable patterns in correlated subqueries and nested loops — optimizer estimates 1 row for table variables"}	null	2026-02-23 20:18:31.390384
2435	sqlserver	query	Check for cardinality estimation errors on table variable operations	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.last_rows AS last_actual_rows,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Table Scan\\"]/@EstimateRows)[1]', 'float') AS est_rows_scan,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/@EstimateRows)[1]', 'float') AS est_rows_nl,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_actual_rows,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND (t.text LIKE '%@%' AND t.text LIKE '%SELECT%(%SELECT%')\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "est_rows_scan <= 1 AND avg_actual_rows > 100", "description": "Table variable estimated at 1 row but actual rows much higher — confirms table variable causing massive cardinality underestimation in correlated subquery"}	null	2026-02-23 20:18:31.390384
2436	sqlserver	query	Find queries with DISTINCT subquery pattern and sort/hash distinct in plan	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//RelOp[@LogicalOp=\\"Aggregate\\" or @LogicalOp=\\"Distinct Sort\\"])', 'int') AS distinct_ops,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') AS outer_ref_loops,\\n  p.query_plan.exist('//ScalarOperator/Subquery') AS has_scalar_subquery,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE t.text LIKE '%DISTINCT%(%SELECT%'\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 5000\\n  AND qs.execution_count > 3\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "distinct_ops > 0 AND outer_ref_loops > 0 AND avg_reads > 5000", "description": "Correlated subquery with DISTINCT forcing per-row sort/hash aggregate operations inside the nested loops"}	null	2026-02-23 20:18:31.390385
2437	sqlserver	query	Find queries with aggregate subquery patterns and stream/hash aggregate in nested loops	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Stream Aggregate\\" or @PhysicalOp=\\"Hash Match\\"][@LogicalOp=\\"Aggregate\\"])', 'int') AS agg_ops,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') AS outer_ref_loops,\\n  p.query_plan.exist('//ScalarOperator/Subquery') AS has_scalar_subquery,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//ScalarOperator/Subquery') = 1\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND (t.text LIKE '%SUM(%' OR t.text LIKE '%COUNT(%' OR t.text LIKE '%AVG(%'\\n    OR t.text LIKE '%MAX(%' OR t.text LIKE '%MIN(%')\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.execution_count > 3\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "has_scalar_subquery = 1 AND outer_ref_loops > 0 AND agg_ops > 0 AND avg_reads > 10000", "description": "Correlated subquery with aggregate function being computed per outer row inside nested loops"}	null	2026-02-23 20:18:31.390385
