2438	sqlserver	query	Assess per-row aggregation cost	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  CASE WHEN qs.total_rows > 0\\n    THEN qs.total_logical_reads / qs.total_rows ELSE 0 END AS reads_per_row,\\n  p.query_plan.value('count(//ScalarOperator/Subquery)', 'int') AS scalar_subqueries,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//ScalarOperator/Subquery') = 1\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\nORDER BY reads_per_row DESC"}	{"condition": "reads_per_row > 100", "description": "Extremely high reads per output row confirms aggregate subquery executing per-row instead of as a single grouped join"}	null	2026-02-23 20:18:31.390387
2439	sqlserver	query	Check for correlated subqueries with large cardinality estimation errors	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.last_rows AS last_actual_rows,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/@EstimateRows)[1]', 'float') AS est_rows,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') AS outer_ref_loops,\\n  SUBSTRING(t.text, 1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/OuterReferences)', 'int') > 0\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.execution_count > 5\\n  AND qs.last_rows > p.query_plan.value('(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/@EstimateRows)[1]', 'float') * 10\\nORDER BY qs.last_rows / NULLIF(p.query_plan.value('(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/@EstimateRows)[1]', 'float'), 0) DESC"}	{"condition": "outer_ref_loops > 0 AND last_actual_rows > est_rows * 10", "description": "Cardinality estimation off by 10x+ on correlated nested loops — statistics on correlation columns likely outdated or missing"}	null	2026-02-23 20:18:31.390387
2441	sqlserver	query	Find expensive join queries with full scans on join columns	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\" and @LogicalOp=\\"Inner Join\\"])', 'int') +\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\" and @LogicalOp=\\"Left Outer Join\\"])', 'int') +\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\" and @LogicalOp=\\"Right Outer Join\\"])', 'int') AS hash_joins,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\"])', 'int') +\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') AS full_scans,\\n  p.query_plan.value('count(//MissingIndexGroup)', 'int') AS missing_indexes,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE t.text LIKE '%JOIN%'\\n  AND (p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\"])', 'int') > 0\\n    OR p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') > 0)\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.execution_count > 5\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "full_scans > 0 AND avg_reads > 10000 AND (hash_joins > 0 OR missing_indexes > 0)", "description": "JOIN queries with full scans and hash matches indicate missing indexes on join key columns"}	null	2026-02-23 20:18:31.390388
2442	sqlserver	query	Check missing index recommendations specifically for join columns	{"sql": "SELECT TOP 15\\n  mid.statement AS table_name,\\n  mid.equality_columns,\\n  mid.inequality_columns,\\n  mid.included_columns,\\n  migs.avg_user_impact,\\n  migs.user_seeks,\\n  migs.avg_total_user_cost * migs.avg_user_impact * (migs.user_seeks + migs.user_scans) AS improvement_measure,\\n  migs.last_user_seek\\nFROM sys.dm_db_missing_index_groups mig\\nJOIN sys.dm_db_missing_index_group_stats migs ON mig.index_group_handle = migs.group_handle\\nJOIN sys.dm_db_missing_index_details mid ON mig.index_handle = mid.index_handle\\nWHERE migs.avg_user_impact > 70\\n  AND migs.user_seeks > 500\\nORDER BY improvement_measure DESC"}	{"condition": "row_count > 0 AND avg_user_impact > 70", "description": "Missing index DMVs confirm high-impact indexes needed on join key columns — improvement measure indicates cost savings"}	null	2026-02-23 20:18:31.390389
2443	sqlserver	query	Find queries with extremely high row counts relative to input tables	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.last_rows,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Nested Loops\\" and @LogicalOp=\\"Inner Join\\" and not(OuterReferences) and not(Predicate)]') AS has_cross_join,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Nested Loops\\" and @LogicalOp=\\"Cross Join\\"]') AS explicit_cross_join,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_rows / NULLIF(qs.execution_count, 0) > 1000000\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 100000\\n  AND qs.execution_count >= 1\\nORDER BY qs.total_rows DESC"}	{"condition": "avg_rows > 1000000 AND avg_reads > 100000", "description": "Queries returning millions of rows with massive reads — potential Cartesian product from missing join condition"}	null	2026-02-23 20:18:31.390389
2444	sqlserver	query	Confirm Cartesian product via plan and tempdb spill indicators	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  p.query_plan.value('count(//RelOp[@LogicalOp=\\"Cross Join\\" or @LogicalOp=\\"Inner Join\\"])', 'int') AS join_count,\\n  SUBSTRING(t.text, 1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_rows / NULLIF(qs.execution_count, 0) > 1000000\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 100000\\nORDER BY qs.total_rows DESC"}	{"condition": "avg_rows > 1000000 AND avg_spills > 0", "description": "Confirmed Cartesian product — massive row counts with tempdb spills indicate cross join from missing/incomplete join condition"}	null	2026-02-23 20:18:31.39039
3514	postgresql	log_scan	Scan for retention override messages	{"pattern": "backup.*pinned|backup.*annotated|backup.*retained.*manual|skip.*delete.*annotated|backup.*keep.*override", "description": "Manual retention override on specific backup sets"}	{"condition": "pattern_found", "description": "Manual retention override preventing automated cleanup"}	\N	2026-02-25 00:28:52.405273
2445	sqlserver	query	Find queries with large estimated vs actual row discrepancies at join operators	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.last_rows AS last_actual_rows,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Hash Match\\"]/@EstimateRows)[1]', 'float') AS hash_est_rows,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/@EstimateRows)[1]', 'float') AS nl_est_rows,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  SUBSTRING(t.text, 1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE t.text LIKE '%JOIN%'\\n  AND qs.total_elapsed_time / NULLIF(qs.execution_count, 0) > 1000000\\n  AND qs.execution_count > 5\\n  AND (qs.last_rows > p.query_plan.value('(//RelOp/@EstimateRows)[1]', 'float') * 10\\n    OR qs.total_spills > 0)\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "avg_elapsed_ms > 1000 AND (avg_spills > 0 OR last_actual_rows > hash_est_rows * 10)", "description": "JOIN queries with cardinality misestimation causing wrong physical operator selection — hash join spilling or nested loops scanning too many rows"}	null	2026-02-23 20:18:31.39039
2446	sqlserver	query	Identify specific join type mismatch via wait stats and plan characteristics	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\"])', 'int') AS hash_ops,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"])', 'int') AS nl_ops,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Merge Join\\"])', 'int') AS merge_ops,\\n  p.query_plan.value('(//RelOp/@EstimatedTotalSubtreeCost)[1]', 'float') AS est_cost,\\n  p.query_plan.value('count(//SpillToTempDb)', 'int') AS tempdb_spills_in_plan,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE t.text LIKE '%JOIN%'\\n  AND qs.total_elapsed_time / NULLIF(qs.execution_count, 0) > 1000000\\n  AND (qs.total_spills > 0\\n    OR qs.last_rows > p.query_plan.value('(//RelOp/@EstimateRows)[1]', 'float') * 10)\\nORDER BY qs.total_elapsed_time DESC"}	{"condition": "(hash_ops > 0 AND avg_spills > 0) OR (nl_ops > 0 AND avg_reads > 100000)", "description": "Confirmed wrong join type: hash join spilling to tempdb (should be nested loops) or nested loops doing excessive reads (should be hash/merge)"}	null	2026-02-23 20:18:31.390391
2447	sqlserver	query	Find expensive join queries with compute scalar operations on join predicates	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Compute Scalar\\"])', 'int') AS compute_scalars,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Table Scan\\"])', 'int') +\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\"])', 'int') +\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Index Scan\\"])', 'int') AS total_scans,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\"])', 'int') AS hash_joins,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE t.text LIKE '%JOIN%'\\n  AND (t.text LIKE '%UPPER(%' OR t.text LIKE '%LOWER(%' OR t.text LIKE '%CAST(%'\\n    OR t.text LIKE '%CONVERT(%' OR t.text LIKE '%ISNULL(%' OR t.text LIKE '%COALESCE(%'\\n    OR t.text LIKE '%LTRIM(%' OR t.text LIKE '%RTRIM(%' OR t.text LIKE '%SUBSTRING(%'\\n    OR t.text LIKE '%DATEPART(%' OR t.text LIKE '%YEAR(%' OR t.text LIKE '%MONTH(%')\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.execution_count > 5\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "total_scans > 0 AND avg_reads > 10000 AND compute_scalars > 0", "description": "JOIN queries with function-wrapped columns showing scans instead of seeks — function prevents index usage"}	null	2026-02-23 20:18:31.390392
2448	sqlserver	query	Confirm non-SARGable join via plan warnings and residual predicates	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.exist('//Warnings/PlanAffectingConvert') AS has_convert_warning,\\n  p.query_plan.value('count(//ScalarOperator[contains(@ScalarString,\\"CONVERT\\") or contains(@ScalarString,\\"isnull\\") or contains(@ScalarString,\\"upper\\") or contains(@ScalarString,\\"lower\\")])', 'int') AS function_in_predicate,\\n  p.query_plan.value('count(//MissingIndexGroup)', 'int') AS missing_indexes,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE t.text LIKE '%JOIN%'\\n  AND (t.text LIKE '%UPPER(%' OR t.text LIKE '%LOWER(%' OR t.text LIKE '%CAST(%'\\n    OR t.text LIKE '%CONVERT(%' OR t.text LIKE '%ISNULL(%')\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "function_in_predicate > 0 OR has_convert_warning = 1", "description": "Confirmed: function-wrapped column in JOIN predicate prevents index seek — PlanAffectingConvert warning or function in scalar operator"}	null	2026-02-23 20:18:31.390392
