2453	sqlserver	query	Check Query Store for plans with large estimated-to-actual row ratio on joins	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_grant_kb,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  p.query_plan.value('(//RelOp[contains(@PhysicalOp,\\"Join\\")]/@EstimateRows)[1]', 'float') AS est_join_rows,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_actual_rows,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//RelOp[contains(@PhysicalOp,\\"Join\\")]') = 1\\n  AND qs.total_spills > 0\\n  AND qs.execution_count > 5\\nORDER BY qs.total_spills DESC"}	{"condition": "avg_spills > 0 AND avg_actual_rows > est_join_rows * 10", "description": "Actual rows vastly exceeding estimated join rows indicates cardinality underestimation at the join operator"}	null	2026-02-23 20:18:31.390395
2454	sqlserver	query	Check statistics freshness on tables involved in underestimated joins	{"sql": "SELECT\\n  s.name AS stats_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  sp.last_updated,\\n  sp.rows,\\n  sp.rows_sampled,\\n  sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(sp.modification_counter AS FLOAT) / sp.rows * 100 ELSE 0 END AS mod_pct\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > 0\\n  AND (CAST(sp.modification_counter AS FLOAT) / NULLIF(sp.rows, 0) * 100) > 20\\nORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0 AND mod_pct > 20", "description": "Statistics with more than 20% modifications since last update confirm stale statistics contributing to cardinality underestimation"}	null	2026-02-23 20:18:31.390396
2455	sqlserver	query	Find queries with hash joins that spill to tempdb	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_used_grant_kb / NULLIF(qs.execution_count, 0) AS avg_used_kb,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\"]') AS has_hash_join,\\n  p.query_plan.exist('//SpillToTempDb') AS has_spill_warning,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\"]') = 1\\n  AND qs.total_spills > 0\\n  AND qs.execution_count > 1\\nORDER BY qs.total_spills DESC"}	{"condition": "row_count > 0 AND has_hash_join = 1 AND has_spill_warning = 1", "description": "Hash join queries with SpillToTempDb warnings indicate insufficient memory grants"}	null	2026-02-23 20:18:31.390397
2550	sqlserver	query	Find sessions with open transactions and network-related issues	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.open_transaction_count, s.status,\\n  c.net_transport, c.client_net_address,\\n  c.connect_time,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  r.wait_type, r.wait_time / 1000 AS wait_seconds\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON c.session_id = s.session_id\\nLEFT JOIN sys.dm_exec_requests r ON r.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND s.open_transaction_count > 0\\n  AND (r.wait_type = 'ASYNC_NETWORK_IO'\\n    OR (s.status = 'sleeping' AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 15))"}	{"condition": "sessions waiting on ASYNC_NETWORK_IO or idle with open transactions", "description": "Client unreachable — SQL Server waiting to send results but network severed"}	null	2026-02-23 20:18:31.390397
2456	sqlserver	query	Check if granted memory is significantly less than ideal memory	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  CASE WHEN qs.total_ideal_grant_kb > 0\\n    THEN CAST(qs.total_grant_kb AS FLOAT) / qs.total_ideal_grant_kb * 100 ELSE 0 END AS grant_pct_of_ideal,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  mg.granted_memory_kb, mg.ideal_memory_kb, mg.required_memory_kb,\\n  mg.queue_id, mg.wait_time_ms\\nFROM sys.dm_exec_query_stats qs\\nLEFT JOIN sys.dm_exec_query_memory_grants mg ON qs.plan_handle = mg.plan_handle\\nWHERE qs.total_spills > 0\\n  AND qs.total_ideal_grant_kb > qs.total_grant_kb\\nORDER BY (qs.total_ideal_grant_kb - qs.total_grant_kb) DESC"}	{"condition": "grant_pct_of_ideal < 80", "description": "Granted memory significantly below ideal confirms the memory grant was insufficient for hash join build input"}	null	2026-02-23 20:18:31.390398
3098	sqlserver	query	Check cached plans for OPENQUERY/OPENROWSET/EXEC AT usage	{"sql": "SELECT TOP 50\\n  qs.execution_count,\\n  qs.last_execution_time,\\n  SUBSTRING(st.text, 1, 500) AS query_text,\\n  CASE\\n    WHEN st.text LIKE '%OPENQUERY%' THEN 'OPENQUERY'\\n    WHEN st.text LIKE '%OPENROWSET%' THEN 'OPENROWSET'\\n    WHEN st.text LIKE '%EXEC%AT%[[]%' THEN 'EXEC_AT_LINKED'\\n    ELSE 'OTHER'\\n  END AS linked_query_type,\\n  DB_NAME(st.dbid) AS source_database\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE st.text LIKE '%OPENQUERY%'\\n  OR st.text LIKE '%OPENROWSET%'\\n  OR (st.text LIKE '%EXEC%' AND st.text LIKE '%AT %[[]%')\\nORDER BY qs.execution_count DESC"}	{"condition": "cached plans with OPENQUERY, OPENROWSET, or EXEC AT linked_server calls", "description": "Dynamic queries are being executed through linked servers — potential SQL injection risk if inputs are not parameterized"}	null	2026-02-23 20:18:31.390787
2457	sqlserver	query	Find queries with nested loop joins having high logical reads per execution	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Nested Loops\\"]') AS has_nested_loop,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/RelOp[2]/@PhysicalOp)[1]', 'nvarchar(100)') AS inner_op,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Nested Loops\\"]/RelOp[2]/@EstimateRows)[1]', 'float') AS inner_est_rows,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//RelOp[@PhysicalOp=\\"Nested Loops\\"]') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 100000\\n  AND qs.execution_count > 1\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND avg_reads > 100000 AND (inner_op = 'Clustered Index Scan' OR inner_op = 'Table Scan')", "description": "Nested loop joins with table/clustered index scans on inner side produce massive I/O proportional to outer input size"}	null	2026-02-23 20:18:31.390399
