2484	sqlserver	query	Check for queries with grants significantly below ideal	{"sql": "SELECT TOP 15\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  CASE WHEN qs.total_ideal_grant_kb > 0\\n    THEN CAST(qs.total_grant_kb AS FLOAT) / qs.total_ideal_grant_kb * 100 ELSE 0 END AS grant_pct_of_ideal,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  SUBSTRING(t.text, 1, 200) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_spills > 0\\n  AND qs.total_ideal_grant_kb > qs.total_grant_kb\\nORDER BY (qs.total_ideal_grant_kb - qs.total_grant_kb) DESC"}	{"condition": "grant_pct_of_ideal < 70 AND avg_spills > 0", "description": "Queries receiving less than 70% of their ideal memory grant with spills confirm systematic memory grant undersizing"}	null	2026-02-23 20:18:31.390415
3100	sqlserver	query	Check linked servers with RPC and RPC Out enabled	{"sql": "SELECT s.name AS linked_server,\\n  s.provider,\\n  s.data_source,\\n  s.product,\\n  s.is_rpc_out_enabled,\\n  s.is_remote_login_enabled,\\n  s.is_data_access_enabled,\\n  ll.uses_self_credential,\\n  ll.remote_name,\\n  CASE WHEN s.is_rpc_out_enabled = 1 AND s.is_remote_login_enabled = 1\\n    THEN 'HIGH_RISK: full remote execution'\\n    WHEN s.is_rpc_out_enabled = 1\\n    THEN 'MEDIUM_RISK: RPC Out enabled'\\n    ELSE 'LOW_RISK' END AS risk_level\\nFROM sys.servers s\\nJOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nWHERE s.is_linked = 1\\n  AND s.is_rpc_out_enabled = 1"}	{"condition": "linked servers with is_rpc_out_enabled = 1", "description": "Linked servers allow remote procedure calls — remote exploitation path via EXEC procedure AT linked_server"}	null	2026-02-23 20:18:31.390789
