2479	sqlserver	query	Find queries with hash aggregate spills	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\" and contains(@LogicalOp,\\"Aggregate\\")]') AS has_hash_agg,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Hash Match\\" and contains(@LogicalOp,\\"Aggregate\\")]/@EstimateRows)[1]', 'float') AS est_groups,\\n  p.query_plan.exist('//SpillToTempDb') AS has_spill,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\" and contains(@LogicalOp,\\"Aggregate\\")]') = 1\\n  AND qs.total_spills > 0\\n  AND qs.execution_count > 1\\nORDER BY qs.total_spills DESC"}	{"condition": "row_count > 0 AND has_hash_agg = 1 AND avg_spills > 0", "description": "Hash aggregate operators with spills indicate the hash table exceeded memory grant due to more distinct groups than estimated"}	null	2026-02-23 20:18:31.390416
2480	sqlserver	query	Check actual vs estimated distinct group counts via statistics	{"sql": "SELECT TOP 10\\n  qs.query_hash,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_output_rows,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Hash Match\\" and contains(@LogicalOp,\\"Aggregate\\")]/@EstimateRows)[1]', 'float') AS est_groups,\\n  CASE WHEN p.query_plan.value('(//RelOp[@PhysicalOp=\\"Hash Match\\" and contains(@LogicalOp,\\"Aggregate\\")]/@EstimateRows)[1]', 'float') > 0\\n    THEN (qs.total_rows / NULLIF(qs.execution_count, 0)) /\\n         p.query_plan.value('(//RelOp[@PhysicalOp=\\"Hash Match\\" and contains(@LogicalOp,\\"Aggregate\\")]/@EstimateRows)[1]', 'float')\\n    ELSE 0 END AS underestimate_ratio,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\" and contains(@LogicalOp,\\"Aggregate\\")]') = 1\\n  AND qs.total_spills > 0\\nORDER BY qs.total_spills DESC"}	{"condition": "underestimate_ratio > 3", "description": "Actual distinct groups 3x+ more than estimated confirms GROUP BY cardinality underestimation causing hash aggregate spills"}	null	2026-02-23 20:18:31.390417
2481	sqlserver	query	Find queries with distinct sort or hash distinct operations that spill	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Sort\\" and contains(@LogicalOp,\\"Distinct\\")]') AS has_distinct_sort,\\n  p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\" and contains(@LogicalOp,\\"Aggregate\\")]') AS has_hash_distinct,\\n  p.query_plan.exist('//SpillToTempDb') AS has_spill,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE (p.query_plan.exist('//RelOp[@PhysicalOp=\\"Sort\\" and contains(@LogicalOp,\\"Distinct\\")]') = 1\\n    OR (p.query_plan.exist('//RelOp[@PhysicalOp=\\"Hash Match\\" and contains(@LogicalOp,\\"Aggregate\\")]') = 1\\n        AND t.text LIKE '%DISTINCT%'))\\n  AND qs.total_spills > 0\\n  AND qs.execution_count > 1\\nORDER BY qs.total_spills DESC"}	{"condition": "row_count > 0 AND avg_spills > 0 AND (has_distinct_sort = 1 OR has_hash_distinct = 1)", "description": "DISTINCT operations (sort distinct or hash aggregate) with spills indicate large dataset deduplication exceeding memory"}	null	2026-02-23 20:18:31.390417
2494	sqlserver	query	Check if grant was insufficient relative to ideal for multi-sort plans	{"sql": "SELECT TOP 15\\n  qs.sql_handle,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  qs.total_ideal_grant_kb / NULLIF(qs.execution_count, 0) AS avg_ideal_kb,\\n  CASE WHEN qs.total_ideal_grant_kb > 0\\n    THEN CAST(qs.total_grant_kb AS FLOAT) / qs.total_ideal_grant_kb * 100\\n    ELSE 100 END AS grant_pct_of_ideal,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Sort\\"])', 'int') AS sort_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_spills > 0\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Sort\\"])', 'int') >= 2\\n  AND qs.total_grant_kb < qs.total_ideal_grant_kb\\nORDER BY (qs.total_ideal_grant_kb - qs.total_grant_kb) DESC"}	{"condition": "grant_pct_of_ideal < 80 AND sort_count >= 2", "description": "Memory grant significantly below ideal for multi-sort plans confirms nested sorts competing for insufficient memory"}	null	2026-02-23 20:18:31.390418
