2506	sqlserver	query	Verify high per-execution read count from correlated pattern	{"sql": "SELECT TOP 15\\n  qs.sql_handle,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  CASE WHEN qs.total_rows > 0\\n    THEN qs.total_logical_reads / NULLIF(qs.total_rows, 0)\\n    ELSE 0 END AS reads_per_row,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  SUBSTRING(t.text, 1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_spills > 0\\n  AND p.query_plan.exist('//ScalarOperator[Subquery]') = 1\\n  AND qs.total_logical_reads / NULLIF(qs.total_rows, 0) > 100\\nORDER BY reads_per_row DESC"}	{"condition": "reads_per_row > 100 AND avg_spills > 0", "description": "Very high reads-per-row ratio with spills confirms correlated subquery in sort key causing per-row evaluation and sort input inflation"}	null	2026-02-23 20:18:31.390435
2507	sqlserver	query	Check for queries with spills where estimated vs actual rows diverge significantly	{"sql": "SELECT TOP 20\\n  qs.sql_handle, qs.plan_handle,\\n  qs.total_spills / NULLIF(qs.execution_count, 0) AS avg_spills,\\n  qs.total_grant_kb / NULLIF(qs.execution_count, 0) AS avg_grant_kb,\\n  p.query_plan.value('(//RelOp[@PhysicalOp=\\"Sort\\" or @PhysicalOp=\\"Hash Match\\"]/@EstimateRows)[1]', 'float') AS estimated_rows,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_actual_rows,\\n  CASE WHEN p.query_plan.value('(//RelOp[@PhysicalOp=\\"Sort\\" or @PhysicalOp=\\"Hash Match\\"]/@EstimateRows)[1]', 'float') > 0\\n    THEN (qs.total_rows / NULLIF(qs.execution_count, 0)) /\\n      p.query_plan.value('(//RelOp[@PhysicalOp=\\"Sort\\" or @PhysicalOp=\\"Hash Match\\"]/@EstimateRows)[1]', 'float')\\n    ELSE 0 END AS actual_to_estimated_ratio,\\n  qs.execution_count,\\n  SUBSTRING(t.text, 1, 300) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_spills > 0\\n  AND p.query_plan.value('(//RelOp[@PhysicalOp=\\"Sort\\" or @PhysicalOp=\\"Hash Match\\"]/@EstimateRows)[1]', 'float') > 0\\nORDER BY actual_to_estimated_ratio DESC"}	{"condition": "actual_to_estimated_ratio > 5 AND avg_spills > 0", "description": "Actual rows exceeding estimated by 5x or more with spills indicates stale statistics causing severe cardinality underestimation"}	null	2026-02-23 20:18:31.390435
2508	sqlserver	query	Check statistics freshness for tables referenced by spilling queries	{"sql": "SELECT\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stat_name,\\n  sp.last_updated,\\n  sp.rows AS stat_rows,\\n  sp.rows_sampled,\\n  sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(sp.modification_counter AS FLOAT) / sp.rows * 100\\n    ELSE 0 END AS modification_pct,\\n  DATEDIFF(day, sp.last_updated, GETDATE()) AS days_since_update,\\n  p.rows AS current_rows\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nJOIN sys.partitions p ON s.object_id = p.object_id AND p.index_id IN (0, 1)\\nWHERE sp.modification_counter > sp.rows * 0.20\\n  OR DATEDIFF(day, sp.last_updated, GETDATE()) > 7\\nORDER BY modification_pct DESC"}	{"condition": "modification_pct > 20 OR days_since_update > 7", "description": "Statistics with >20% row modifications since last update or not updated for over 7 days confirm stale histograms causing cardinality misestimation"}	null	2026-02-23 20:18:31.390436
2510	sqlserver	query	Verify the idle transaction is holding locks and blocking others	{"sql": "SELECT\\n  tl.request_session_id AS blocking_session_id,\\n  s.program_name, s.host_name,\\n  DATEDIFF(second, tat.transaction_begin_time, GETDATE()) AS txn_open_sec,\\n  COUNT(DISTINCT tl.resource_associated_entity_id) AS locked_resources,\\n  SUM(CASE WHEN tl.request_mode LIKE '%X%' THEN 1 ELSE 0 END) AS exclusive_locks,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests r WHERE r.blocking_session_id = tl.request_session_id) AS blocked_sessions\\nFROM sys.dm_tran_locks tl\\nJOIN sys.dm_exec_sessions s ON tl.request_session_id = s.session_id\\nJOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nJOIN sys.dm_tran_active_transactions tat ON st.transaction_id = tat.transaction_id\\nWHERE s.status = 'sleeping'\\n  AND s.is_user_process = 1\\n  AND DATEDIFF(second, tat.transaction_begin_time, GETDATE()) > 60\\nGROUP BY tl.request_session_id, s.program_name, s.host_name, tat.transaction_begin_time\\nHAVING COUNT(DISTINCT tl.resource_associated_entity_id) > 0\\nORDER BY blocked_sessions DESC"}	{"condition": "locked_resources > 0 AND txn_open_sec > 60", "description": "Idle transactions holding locks confirm user interaction pattern — application opened a transaction and is waiting for the user before continuing"}	null	2026-02-23 20:18:31.390437
3525	postgresql	query	Check current timeline on standby	{"sql": "SELECT pg_is_in_recovery() AS is_standby, CASE WHEN pg_is_in_recovery() THEN pg_last_wal_receive_lsn() ELSE NULL END AS last_received_lsn"}	{"condition": "is_standby = true", "description": "Server is a standby — check if recently re-initialized"}	\N	2026-02-25 00:28:52.405273
2513	sqlserver	query	Check for active long-running transactions with currently executing slow queries	{"sql": "SELECT\\n  r.session_id, r.status, r.command,\\n  r.wait_type, r.wait_time, r.wait_resource,\\n  tat.transaction_begin_time,\\n  DATEDIFF(second, tat.transaction_begin_time, GETDATE()) AS txn_open_sec,\\n  DATEDIFF(second, r.start_time, GETDATE()) AS query_running_sec,\\n  r.cpu_time / 1000 AS query_cpu_sec,\\n  r.logical_reads,\\n  r.total_elapsed_time / 1000 AS query_elapsed_sec,\\n  r.estimated_completion_time / 1000 AS est_remaining_sec,\\n  r.granted_query_memory * 8 AS granted_memory_kb,\\n  SUBSTRING(t.text, (r.statement_start_offset / 2) + 1,\\n    (CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE r.statement_end_offset END - r.statement_start_offset) / 2 + 1) AS current_query\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_tran_session_transactions st ON r.session_id = st.session_id\\nJOIN sys.dm_tran_active_transactions tat ON st.transaction_id = tat.transaction_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE r.status = 'running'\\n  AND DATEDIFF(second, tat.transaction_begin_time, GETDATE()) > 30\\n  AND r.total_elapsed_time > 30000\\nORDER BY txn_open_sec DESC"}	{"condition": "txn_open_sec > 30 AND query_running_sec > 30", "description": "Transaction open because a currently executing query has been running for over 30 seconds"}	null	2026-02-23 20:18:31.390439
4326	postgresql	query	Check for historical concurrent job start clusters within 60-second windows	{"sql": "SELECT date_trunc('minute', start_time) AS minute_bucket, count(*) AS concurrent_starts FROM cron.job_run_details WHERE start_time > now() - interval '7 days' GROUP BY date_trunc('minute', start_time) HAVING count(*) >= 3 ORDER BY concurrent_starts DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Clusters of 3+ jobs starting within the same minute confirm thundering herd pattern"}	\N	2026-02-25 00:28:52.405273
4327	postgresql	query	Check for recent DDL changes on ETL source tables	{"sql": "SELECT schemaname, relname, last_analyze, last_autoanalyze, n_live_tup, n_mod_since_analyze FROM pg_stat_user_tables WHERE n_mod_since_analyze > 0 ORDER BY last_autoanalyze DESC NULLS LAST LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with recent modifications detected; schema drift may have occurred"}	\N	2026-02-25 00:28:52.405273
2514	sqlserver	query	Check execution plan of the slow query for inefficiency indicators	{"sql": "SELECT TOP 10\\n  r.session_id,\\n  DATEDIFF(second, r.start_time, GETDATE()) AS query_running_sec,\\n  r.logical_reads, r.cpu_time / 1000 AS cpu_sec,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Clustered Index Scan\\" or @PhysicalOp=\\"Table Scan\\"])', 'int') AS scan_ops,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Nested Loops\\"])', 'int') AS nested_loops,\\n  p.query_plan.value('count(//Warnings)', 'int') AS plan_warnings,\\n  p.query_plan.exist('//MissingIndexes') AS has_missing_indexes,\\n  r.total_elapsed_time / 1000 AS elapsed_sec\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_query_plan(r.plan_handle) p\\nJOIN sys.dm_tran_session_transactions st ON r.session_id = st.session_id\\nJOIN sys.dm_tran_active_transactions tat ON st.transaction_id = tat.transaction_id\\nWHERE r.status IN ('running', 'runnable', 'suspended')\\n  AND DATEDIFF(second, tat.transaction_begin_time, GETDATE()) > 30\\n  AND r.total_elapsed_time > 30000\\nORDER BY r.total_elapsed_time DESC"}	{"condition": "scan_ops > 0 OR has_missing_indexes = 1 OR plan_warnings > 0", "description": "Slow query with table scans, missing index suggestions, or plan warnings confirms inefficient execution extending the transaction"}	null	2026-02-23 20:18:31.39044
2532	sqlserver	query	Check for active bulk operations and log throughput	{"sql": "SELECT r.session_id, r.command, r.percent_complete,\\n  r.total_elapsed_time / 60000 AS elapsed_minutes,\\n  t.text AS query_text,\\n  d.name AS database_name,\\n  lu.cntr_value / 1024 AS log_used_mb,\\n  CAST(lu.cntr_value AS FLOAT) / NULLIF(ls.cntr_value, 0) * 100 AS log_used_pct\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nJOIN sys.databases d ON r.database_id = d.database_id\\nJOIN sys.dm_os_performance_counters ls\\n  ON ls.counter_name = 'Log File(s) Size (KB)' AND ls.instance_name = d.name\\nJOIN sys.dm_os_performance_counters lu\\n  ON lu.counter_name = 'Log File(s) Used Size (KB)' AND lu.instance_name = d.name\\nWHERE r.command IN ('BULK INSERT', 'INSERT', 'UPDATE', 'DELETE', 'SELECT INTO',\\n  'CREATE INDEX', 'ALTER INDEX', 'DBCC')\\n  AND r.total_elapsed_time > 60000\\nORDER BY r.total_elapsed_time DESC"}	{"condition": "long-running bulk/DML operations with log_used_pct > 70", "description": "Active bulk operations filling the transaction log"}	null	2026-02-23 20:18:31.390442
2516	sqlserver	query	Identify the lock types and resources causing the blocking chain	{"sql": "SELECT\\n  tl_waiter.request_session_id AS waiting_session,\\n  tl_waiter.resource_type, tl_waiter.request_mode AS waiting_mode,\\n  tl_waiter.request_status,\\n  tl_holder.request_session_id AS holding_session,\\n  tl_holder.request_mode AS holding_mode,\\n  OBJECT_NAME(tl_waiter.resource_associated_entity_id) AS locked_object,\\n  wt.blocking_session_id,\\n  wt.wait_duration_ms / 1000 AS wait_duration_sec,\\n  wt.wait_type,\\n  wt.resource_description\\nFROM sys.dm_tran_locks tl_waiter\\nJOIN sys.dm_tran_locks tl_holder\\n  ON tl_waiter.resource_associated_entity_id = tl_holder.resource_associated_entity_id\\n  AND tl_waiter.resource_type = tl_holder.resource_type\\n  AND tl_waiter.request_session_id <> tl_holder.request_session_id\\nLEFT JOIN sys.dm_os_waiting_tasks wt ON tl_waiter.request_session_id = wt.session_id\\nWHERE tl_waiter.request_status = 'WAIT'\\n  AND tl_holder.request_status = 'GRANT'\\nORDER BY wt.wait_duration_ms DESC"}	{"condition": "wait_duration_sec > 5 AND request_status = 'WAIT'", "description": "Lock conflicts with specific resource and mode details confirm blocking as the cause of the long-running transaction"}	null	2026-02-23 20:18:31.390442
2517	sqlserver	query	Check for recent deadlocks via system health extended events	{"sql": "SELECT\\n  xed.value('(event/@timestamp)[1]', 'datetime2') AS deadlock_time,\\n  xed.value('(event/data[@name=\\"xml_report\\"]/value)[1]', 'nvarchar(max)') AS deadlock_report\\nFROM (\\n  SELECT CAST(target_data AS XML) AS target_data\\n  FROM sys.dm_xe_session_targets st\\n  JOIN sys.dm_xe_sessions s ON s.address = st.event_session_address\\n  WHERE s.name = 'system_health'\\n    AND st.target_name = 'ring_buffer'\\n) AS data\\nCROSS APPLY target_data.nodes('RingBufferTarget/event[@name=\\"xml_deadlock_report\\"]') AS xed(xed)\\nWHERE xed.value('(event/@timestamp)[1]', 'datetime2') > DATEADD(hour, -1, GETDATE())\\nORDER BY deadlock_time DESC"}	{"condition": "row_count > 0", "description": "Recent deadlock events detected within the last hour"}	null	2026-02-23 20:18:31.390443
2518	sqlserver	query	Check deadlock-related performance counters and lock waits	{"sql": "SELECT\\n  pc.counter_name, pc.cntr_value,\\n  ws.wait_type, ws.waiting_tasks_count,\\n  ws.wait_time_ms,\\n  CASE WHEN ws.waiting_tasks_count > 0\\n    THEN ws.wait_time_ms / ws.waiting_tasks_count ELSE 0 END AS avg_wait_ms\\nFROM sys.dm_os_performance_counters pc\\nCROSS JOIN sys.dm_os_wait_stats ws\\nWHERE pc.counter_name IN ('Number of Deadlocks/sec', 'Lock Timeouts/sec', 'Lock Wait Time (ms)')\\n  AND pc.instance_name = '_Total'\\n  AND ws.wait_type IN ('LCK_M_S', 'LCK_M_X', 'LCK_M_U', 'LCK_M_IX', 'LCK_M_IS')\\n  AND ws.waiting_tasks_count > 0\\nORDER BY ws.wait_time_ms DESC"}	{"condition": "Number of Deadlocks/sec cntr_value > 0 OR LCK wait_time_ms elevated", "description": "Active deadlock counters and significant lock wait times confirm deadlock contention causing transaction retries and extended duration"}	null	2026-02-23 20:18:31.390444
2520	sqlserver	query	Check if bulk operation is causing log growth and tempdb pressure	{"sql": "SELECT\\n  d.name AS database_name,\\n  lsu.cntr_value / 1024 AS log_file_used_kb,\\n  d.log_reuse_wait_desc,\\n  dt.database_transaction_log_bytes_reserved / 1024 / 1024 AS log_reserved_mb,\\n  dt.database_transaction_log_bytes_used / 1024 / 1024 AS log_used_mb,\\n  dt.database_transaction_log_record_count AS log_records,\\n  mf.size * 8 / 1024 AS log_file_size_mb,\\n  mf.growth * 8 / 1024 AS log_growth_mb\\nFROM sys.dm_tran_database_transactions dt\\nJOIN sys.databases d ON dt.database_id = d.database_id\\nJOIN sys.dm_os_performance_counters lsu ON lsu.instance_name = d.name\\n  AND lsu.counter_name = 'Log File(s) Used Size (KB)'\\nJOIN sys.master_files mf ON d.database_id = mf.database_id AND mf.type = 1\\nWHERE dt.database_transaction_log_bytes_used > 104857600\\n  AND d.log_reuse_wait_desc <> 'NOTHING'\\nORDER BY dt.database_transaction_log_bytes_used DESC"}	{"condition": "log_used_mb > 100 AND log_reuse_wait_desc = 'ACTIVE_TRANSACTION'", "description": "Log reuse blocked by active transaction with large log usage confirms bulk operation holding the log open"}	null	2026-02-23 20:18:31.390445
2534	sqlserver	query	Check log reuse wait and last log backup time	{"sql": "SELECT d.name AS database_name,\\n  d.recovery_model_desc,\\n  d.log_reuse_wait_desc,\\n  bs.last_log_backup,\\n  DATEDIFF(MINUTE, bs.last_log_backup, GETDATE()) AS minutes_since_log_backup,\\n  lu.cntr_value / 1024 AS log_used_mb,\\n  CAST(lu.cntr_value AS FLOAT) / NULLIF(ls.cntr_value, 0) * 100 AS log_used_pct\\nFROM sys.databases d\\nLEFT JOIN (\\n  SELECT database_name, MAX(backup_finish_date) AS last_log_backup\\n  FROM msdb.dbo.backupset WHERE type = 'L'\\n  GROUP BY database_name\\n) bs ON bs.database_name = d.name\\nJOIN sys.dm_os_performance_counters ls\\n  ON ls.counter_name = 'Log File(s) Size (KB)' AND ls.instance_name = d.name\\nJOIN sys.dm_os_performance_counters lu\\n  ON lu.counter_name = 'Log File(s) Used Size (KB)' AND lu.instance_name = d.name\\nWHERE d.recovery_model_desc = 'FULL'\\n  AND d.database_id > 4\\n  AND (bs.last_log_backup IS NULL\\n    OR DATEDIFF(MINUTE, bs.last_log_backup, GETDATE()) > 60)"}	{"condition": "FULL recovery databases with no log backup or last backup > 60 minutes ago", "description": "Transaction log cannot be truncated without log backups in FULL recovery model"}	null	2026-02-23 20:18:31.390445
2533	sqlserver	query	Check log flush rate and write latency	{"sql": "SELECT d.name AS database_name,\\n  pc.cntr_value AS log_flushes_sec,\\n  vfs.io_stall_write_ms / NULLIF(vfs.num_of_writes, 0) AS avg_log_write_ms,\\n  vfs.num_of_bytes_written / 1048576 AS total_log_written_mb\\nFROM sys.databases d\\nJOIN sys.dm_os_performance_counters pc\\n  ON pc.counter_name = 'Log Flushes/sec' AND pc.instance_name = d.name\\nJOIN sys.dm_io_virtual_file_stats(NULL, NULL) vfs\\n  ON vfs.database_id = d.database_id\\nJOIN sys.master_files mf\\n  ON vfs.database_id = mf.database_id AND vfs.file_id = mf.file_id\\nWHERE mf.type = 1\\n  AND d.database_id > 4\\nORDER BY vfs.num_of_bytes_written DESC"}	{"condition": "high log flush rate or total_log_written_mb significantly larger than log file size", "description": "Sustained high log write throughput confirms bulk data load pressure"}	null	2026-02-23 20:18:31.390446
4045	postgresql	config_check	Check wal_level for cloud defaults	{"sql": "SELECT name, setting FROM pg_settings WHERE name = 'wal_level'"}	{"condition": "setting = 'minimal'", "description": "Minimal WAL level in cloud suggests PITR explicitly disabled"}	\N	2026-02-25 00:28:52.405273
2522	sqlserver	query	Verify the orphaned transaction is blocking log reuse or other sessions	{"sql": "SELECT\\n  s.session_id,\\n  DATEDIFF(minute, tat.transaction_begin_time, GETDATE()) AS open_minutes,\\n  d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  (SELECT COUNT(*) FROM sys.dm_tran_locks tl WHERE tl.request_session_id = s.session_id) AS held_locks,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests r WHERE r.blocking_session_id = s.session_id) AS blocked_sessions,\\n  dt.database_transaction_log_bytes_used / 1024 AS log_used_kb\\nFROM sys.dm_tran_session_transactions st\\nJOIN sys.dm_tran_active_transactions tat ON st.transaction_id = tat.transaction_id\\nJOIN sys.dm_tran_database_transactions dt ON tat.transaction_id = dt.transaction_id\\nJOIN sys.databases d ON dt.database_id = d.database_id\\nJOIN sys.dm_exec_sessions s ON st.session_id = s.session_id\\nWHERE s.status = 'sleeping'\\n  AND DATEDIFF(minute, tat.transaction_begin_time, GETDATE()) > 10\\n  AND s.open_transaction_count > 0\\nORDER BY open_minutes DESC"}	{"condition": "open_minutes > 10 AND (held_locks > 0 OR log_reuse_wait_desc = 'ACTIVE_TRANSACTION' OR blocked_sessions > 0)", "description": "Orphaned transaction holding locks, blocking log reuse, or blocking other sessions confirms forgotten COMMIT"}	null	2026-02-23 20:18:31.390447
2524	sqlserver	query	Check network-related wait types for the session	{"sql": "SELECT\\n  ws.wait_type,\\n  ws.waiting_tasks_count,\\n  ws.wait_time_ms,\\n  CASE WHEN ws.waiting_tasks_count > 0\\n    THEN ws.wait_time_ms / ws.waiting_tasks_count ELSE 0 END AS avg_wait_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type IN (\\n  'ASYNC_NETWORK_IO', 'NETWORK_IO',\\n  'PREEMPTIVE_OS_GETPROCADDRESS', 'PREEMPTIVE_OS_AUTHORIZATIONOPS'\\n)\\n  AND ws.waiting_tasks_count > 0\\nORDER BY ws.wait_time_ms DESC"}	{"condition": "ASYNC_NETWORK_IO wait_time_ms elevated AND avg_wait_ms > 5", "description": "High ASYNC_NETWORK_IO waits confirm SQL Server is waiting for the client to consume results, indicating network latency or slow client processing"}	null	2026-02-23 20:18:31.390448
2525	sqlserver	query	Check for user transactions blocked by maintenance operations	{"sql": "SELECT\\n  r.session_id AS blocked_session,\\n  r.blocking_session_id AS maintenance_session,\\n  r.wait_type, r.wait_time / 1000 AS wait_sec,\\n  r.wait_resource,\\n  tat.transaction_begin_time,\\n  DATEDIFF(second, tat.transaction_begin_time, GETDATE()) AS txn_open_sec,\\n  s_maint.program_name AS maint_program,\\n  s_maint.login_name AS maint_login,\\n  r_maint.command AS maint_command,\\n  r_maint.percent_complete AS maint_pct_complete,\\n  SUBSTRING(t.text, 1, 300) AS blocked_query,\\n  (SELECT text FROM sys.dm_exec_sql_text(r_maint.sql_handle)) AS maint_query\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_tran_session_transactions st ON r.session_id = st.session_id\\nJOIN sys.dm_tran_active_transactions tat ON st.transaction_id = tat.transaction_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nJOIN sys.dm_exec_sessions s_maint ON r.blocking_session_id = s_maint.session_id\\nLEFT JOIN sys.dm_exec_requests r_maint ON s_maint.session_id = r_maint.session_id\\nWHERE r.blocking_session_id <> 0\\n  AND r_maint.command IN ('ALTER INDEX', 'DBCC', 'CREATE INDEX', 'UPDATE STATISTICS',\\n    'ALTER TABLE', 'DbccFilesCompact', 'DbccCheckDb', 'DbccCheckTable')\\nORDER BY r.wait_time DESC"}	{"condition": "row_count > 0 AND maint_command IN ('ALTER INDEX', 'DBCC', 'CREATE INDEX', 'UPDATE STATISTICS')", "description": "User transactions blocked by maintenance commands confirm database maintenance causing long-running transactions"}	null	2026-02-23 20:18:31.390449
2535	sqlserver	query	Confirm log_reuse_wait is LOG_BACKUP	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  lu.cntr_value / 1024 AS log_used_mb\\nFROM sys.databases d\\nJOIN sys.dm_os_performance_counters lu\\n  ON lu.counter_name = 'Log File(s) Used Size (KB)' AND lu.instance_name = d.name\\nWHERE d.log_reuse_wait_desc = 'LOG_BACKUP'\\n  AND d.database_id > 4"}	{"condition": "databases with log_reuse_wait_desc = LOG_BACKUP", "description": "SQL Server explicitly reports log waiting for backup — definitive confirmation"}	null	2026-02-23 20:18:31.39045
2579	sqlserver	query	Check for active triggers on tables with high error rates	{"sql": "SELECT\\n  OBJECT_NAME(tr.parent_id) AS table_name,\\n  tr.name AS trigger_name,\\n  tr.type_desc,\\n  tr.is_instead_of_trigger,\\n  tr.is_disabled,\\n  OBJECT_DEFINITION(tr.object_id) AS trigger_definition,\\n  qs.execution_count AS trigger_executions,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads\\nFROM sys.triggers tr\\nLEFT JOIN sys.dm_exec_trigger_stats qs ON tr.object_id = qs.object_id\\nWHERE tr.is_disabled = 0\\n  AND tr.parent_class = 1\\n  AND qs.execution_count > 0\\nORDER BY qs.execution_count DESC"}	{"condition": "row_count > 0 AND active triggers with high execution counts", "description": "Active triggers on frequently modified tables that could be sources of transaction failures"}	null	2026-02-23 20:18:31.390477
4328	postgresql	query	Check pg_attribute for recently modified columns on source tables	{"sql": "SELECT c.relname AS table_name, a.attname AS column_name, a.atttypid::regtype AS data_type, a.attnum AS column_position FROM pg_attribute a JOIN pg_class c ON a.attrelid = c.oid JOIN pg_namespace n ON c.relnamespace = n.oid WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND a.attnum > 0 AND NOT a.attisdropped AND c.relkind = 'r' ORDER BY c.relname, a.attnum"}	{"condition": "row_count > 0", "description": "Column definitions available for comparison against ETL expectations"}	\N	2026-02-25 00:28:52.405273
2546	sqlserver	query	Check for deferred transactions blocking log reuse	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  lu.cntr_value / 1024 AS log_used_mb,\\n  CAST(lu.cntr_value AS FLOAT) / NULLIF(ls.cntr_value, 0) * 100 AS log_used_pct\\nFROM sys.databases d\\nJOIN sys.dm_os_performance_counters ls\\n  ON ls.counter_name = 'Log File(s) Size (KB)' AND ls.instance_name = d.name\\nJOIN sys.dm_os_performance_counters lu\\n  ON lu.counter_name = 'Log File(s) Used Size (KB)' AND lu.instance_name = d.name\\nWHERE d.log_reuse_wait_desc = 'ACTIVE_TRANSACTION'\\n  AND d.database_id > 4"}	{"condition": "databases with log_reuse_wait = ACTIVE_TRANSACTION", "description": "Potential deferred transaction holding log open"}	null	2026-02-23 20:18:31.390456
3380	postgresql	query	Find very old idle sessions	{"sql": "SELECT pid, client_addr, application_name, backend_start, state_change, state, extract(epoch FROM now() - state_change) / 3600 AS idle_hours FROM pg_stat_activity WHERE backend_type = 'client backend' AND state = 'idle' AND now() - state_change > :threshold_interval::interval ORDER BY idle_hours DESC"}	{"condition": "row_count > 0", "description": "Sessions idle for hours are likely orphaned from dead app instances"}	{"threshold_interval": "2 hours"}	2026-02-25 00:28:52.405273
2590	sqlserver	query	Check for remote connections and listening endpoints	{"sql": "SELECT e.name, e.protocol_desc, e.state_desc,\\n  te.port, te.is_dynamic_port,\\n  e.is_admin_endpoint\\nFROM sys.endpoints e\\nLEFT JOIN sys.tcp_endpoints te ON e.endpoint_id = te.endpoint_id\\nWHERE e.protocol_desc = 'TCP'\\n  AND e.state_desc = 'STARTED'"}	{"condition": "row_count > 0", "description": "TCP endpoints are active and listening for remote connections"}	null	2026-02-23 20:18:31.390485
3843	postgresql	config_check	Check WAL timeout settings	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('wal_sender_timeout', 'wal_receiver_timeout', 'tcp_keepalives_idle', 'tcp_keepalives_interval', 'tcp_keepalives_count') ORDER BY name"}	{"condition": "row_count > 0", "description": "Timeout settings that control heartbeat detection"}	\N	2026-02-25 00:28:52.405273
2527	sqlserver	query	Check network connectivity state and impact of the idle transaction	{"sql": "SELECT\\n  s.session_id,\\n  DATEDIFF(minute, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  ec.net_transport, ec.auth_scheme,\\n  ec.connect_time,\\n  DATEDIFF(minute, ec.last_read, GETDATE()) AS min_since_last_network_read,\\n  DATEDIFF(minute, ec.last_write, GETDATE()) AS min_since_last_network_write,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests r WHERE r.blocking_session_id = s.session_id) AS blocked_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_tran_locks tl WHERE tl.request_session_id = s.session_id) AS held_locks,\\n  d.name AS database_name,\\n  d.log_reuse_wait_desc\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections ec ON s.session_id = ec.session_id\\nJOIN sys.dm_tran_session_transactions st ON s.session_id = st.session_id\\nJOIN sys.dm_tran_database_transactions dt ON st.transaction_id = dt.transaction_id\\nJOIN sys.databases d ON dt.database_id = d.database_id\\nWHERE s.status = 'sleeping'\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(minute, s.last_request_end_time, GETDATE()) > 5\\nORDER BY idle_minutes DESC"}	{"condition": "min_since_last_network_read > 5 AND (held_locks > 0 OR blocked_sessions > 0)", "description": "No network activity for over 5 minutes with active locks confirms client application is halted — not just slow, but completely stopped"}	null	2026-02-23 20:18:31.390451
2528	sqlserver	query	Find sleeping sessions with open transactions and ORM/driver patterns	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.open_transaction_count,\\n  DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS txn_duration_sec,\\n  s.status AS session_status,\\n  c.client_net_address, c.protocol_type,\\n  (SELECT text FROM sys.dm_exec_sql_text(c.most_recent_sql_handle)) AS last_sql\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON st.session_id = s.session_id\\nJOIN sys.dm_tran_active_transactions t ON t.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_connections c ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND s.open_transaction_count > 0\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) > 120"}	{"condition": "sleeping sessions with open transactions idle > 120 seconds", "description": "Sessions holding transactions while idle suggest driver/ORM not committing or rolling back properly"}	null	2026-02-23 20:18:31.390452
2529	sqlserver	query	Check for implicit transaction mode on suspect sessions	{"sql": "SELECT s.session_id, s.program_name,\\n  CASE WHEN (@@OPTIONS & 2) = 2 THEN 'ON' ELSE 'OFF' END AS implicit_transactions,\\n  s.transaction_isolation_level,\\n  t.name AS transaction_name,\\n  t.transaction_type\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON st.session_id = s.session_id\\nJOIN sys.dm_tran_active_transactions t ON t.transaction_id = st.transaction_id\\nWHERE s.is_user_process = 1\\n  AND s.open_transaction_count > 0\\n  AND s.status = 'sleeping'\\n  AND DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) > 120"}	{"condition": "implicit_transactions = ON or transaction_name = 'implicit_transaction' or transaction_type = 4", "description": "Implicit transaction mode or user transaction pattern confirms driver/ORM misconfiguration"}	null	2026-02-23 20:18:31.390452
2530	sqlserver	query	Check databases where log reuse is blocked by active transaction	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  ls.cntr_value / 1024 AS log_size_mb,\\n  lu.cntr_value / 1024 AS log_used_mb,\\n  CAST(lu.cntr_value AS FLOAT) / NULLIF(ls.cntr_value, 0) * 100 AS log_used_pct\\nFROM sys.databases d\\nJOIN sys.dm_os_performance_counters ls\\n  ON ls.counter_name = 'Log File(s) Size (KB)'\\n  AND ls.instance_name = d.name\\nJOIN sys.dm_os_performance_counters lu\\n  ON lu.counter_name = 'Log File(s) Used Size (KB)'\\n  AND lu.instance_name = d.name\\nWHERE d.log_reuse_wait_desc = 'ACTIVE_TRANSACTION'\\n  AND d.database_id > 4"}	{"condition": "databases with log_reuse_wait_desc = ACTIVE_TRANSACTION", "description": "Transaction log cannot be truncated because an active transaction holds the oldest LSN"}	null	2026-02-23 20:18:31.390453
2531	sqlserver	query	Identify the oldest active transaction blocking log truncation	{"sql": "SELECT dat.transaction_id,\\n  dat.name AS transaction_name,\\n  dat.transaction_begin_time,\\n  DATEDIFF(MINUTE, dat.transaction_begin_time, GETDATE()) AS age_minutes,\\n  dst.session_id,\\n  s.program_name, s.host_name, s.login_name,\\n  s.status AS session_status,\\n  (SELECT text FROM sys.dm_exec_sql_text(c.most_recent_sql_handle)) AS last_sql\\nFROM sys.dm_tran_active_transactions dat\\nJOIN sys.dm_tran_session_transactions dst ON dst.transaction_id = dat.transaction_id\\nJOIN sys.dm_exec_sessions s ON s.session_id = dst.session_id\\nLEFT JOIN sys.dm_exec_connections c ON c.session_id = s.session_id\\nWHERE dat.transaction_begin_time = (\\n  SELECT MIN(transaction_begin_time)\\n  FROM sys.dm_tran_active_transactions\\n  WHERE transaction_id IN (\\n    SELECT transaction_id FROM sys.dm_tran_session_transactions\\n  )\\n)"}	{"condition": "age_minutes > 30", "description": "The oldest active transaction is long-running, preventing log reuse"}	null	2026-02-23 20:18:31.390453
2544	sqlserver	query	Check log growth events and current log utilization	{"sql": "SELECT d.name AS database_name,\\n  lu.cntr_value / 1024 AS log_used_mb,\\n  ls.cntr_value / 1024 AS log_size_mb,\\n  CAST(lu.cntr_value AS FLOAT) / NULLIF(ls.cntr_value, 0) * 100 AS log_used_pct,\\n  mf.growth,\\n  CASE WHEN mf.is_percent_growth = 1\\n    THEN CAST(mf.growth AS VARCHAR) + '%'\\n    ELSE CAST(mf.growth * 8 / 1024 AS VARCHAR) + ' MB'\\n  END AS growth_increment\\nFROM sys.databases d\\nJOIN sys.master_files mf ON d.database_id = mf.database_id AND mf.type = 1\\nJOIN sys.dm_os_performance_counters ls\\n  ON ls.counter_name = 'Log File(s) Size (KB)' AND ls.instance_name = d.name\\nJOIN sys.dm_os_performance_counters lu\\n  ON lu.counter_name = 'Log File(s) Used Size (KB)' AND lu.instance_name = d.name\\nWHERE d.database_id > 4\\n  AND CAST(lu.cntr_value AS FLOAT) / NULLIF(ls.cntr_value, 0) * 100 > 80"}	{"condition": "log_used_pct > 80 with slow I/O from step 1", "description": "High log utilization combined with I/O bottleneck — log writes backing up"}	null	2026-02-23 20:18:31.390455
2545	sqlserver	query	Check log file auto-growth configuration	{"sql": "SELECT d.name AS database_name,\\n  mf.physical_name,\\n  mf.size * 8 / 1024 AS current_size_mb,\\n  mf.max_size,\\n  CASE mf.max_size\\n    WHEN 0 THEN 'GROWTH DISABLED'\\n    WHEN -1 THEN 'UNLIMITED'\\n    WHEN 268435456 THEN 'UNLIMITED (2TB)'\\n    ELSE CAST(mf.max_size * 8 / 1024 AS VARCHAR) + ' MB'\\n  END AS max_size_desc,\\n  mf.is_percent_growth,\\n  mf.growth,\\n  CASE\\n    WHEN mf.growth = 0 THEN 'AUTO-GROWTH DISABLED'\\n    WHEN mf.is_percent_growth = 1 THEN CAST(mf.growth AS VARCHAR) + '% growth'\\n    WHEN mf.growth * 8 / 1024 < 64 THEN 'SMALL: ' + CAST(mf.growth * 8 / 1024 AS VARCHAR) + ' MB'\\n    ELSE CAST(mf.growth * 8 / 1024 AS VARCHAR) + ' MB'\\n  END AS growth_desc\\nFROM sys.databases d\\nJOIN sys.master_files mf ON d.database_id = mf.database_id\\nWHERE mf.type = 1\\n  AND d.database_id > 4\\n  AND (mf.growth = 0 OR mf.is_percent_growth = 1 OR mf.growth * 8 / 1024 < 64)"}	{"condition": "log files with disabled growth, percentage growth, or small fixed increments (< 64 MB)", "description": "Misconfigured auto-growth: disabled (fill risk), percentage (unpredictable large growths), or too-small increments (frequent pauses)"}	null	2026-02-23 20:18:31.390455
11486	mysql	config_check	Check MySQL version and local_infile status	{"sql": "SELECT @@version AS mysql_version, @@local_infile AS local_infile_status"}	{"condition": "mysql_version >= '8.0' AND local_infile_status = 1", "description": "MySQL 8.0+ defaults to local_infile OFF, but it is ON — manually enabled"}	\N	2026-03-01 06:30:58.706791
2556	sqlserver	query	Count sleeping sessions with open transactions by application	{"sql": "SELECT s.program_name, s.host_name,\\n  COUNT(*) AS orphaned_txn_count,\\n  AVG(DATEDIFF(MINUTE, t.transaction_begin_time, GETDATE())) AS avg_txn_age_minutes,\\n  MAX(DATEDIFF(MINUTE, t.transaction_begin_time, GETDATE())) AS max_txn_age_minutes,\\n  SUM(s.open_transaction_count) AS total_open_txns\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON st.session_id = s.session_id\\nJOIN sys.dm_tran_active_transactions t ON t.transaction_id = st.transaction_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 5\\nGROUP BY s.program_name, s.host_name\\nHAVING COUNT(*) > 2\\nORDER BY orphaned_txn_count DESC"}	{"condition": "multiple sleeping sessions with open transactions from the same application (> 2)", "description": "Pattern of connection pool leak — same app accumulating orphaned transactions"}	null	2026-02-23 20:18:31.390457
2547	sqlserver	query	Check for deferred transactions in database transaction log	{"sql": "SELECT d.name AS database_name,\\n  dt.database_transaction_state,\\n  CASE dt.database_transaction_state\\n    WHEN 1 THEN 'Not initialized'\\n    WHEN 3 THEN 'Initialized, no log records'\\n    WHEN 4 THEN 'Has log records'\\n    WHEN 5 THEN 'Prepared'\\n    WHEN 10 THEN 'Committed'\\n    WHEN 11 THEN 'Rolled back'\\n    WHEN 12 THEN 'Being committed'\\n  END AS state_desc,\\n  dt.database_transaction_log_bytes_reserved,\\n  at.transaction_begin_time,\\n  DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) AS age_minutes,\\n  at.name AS transaction_name,\\n  at.transaction_state\\nFROM sys.dm_tran_database_transactions dt\\nJOIN sys.dm_tran_active_transactions at ON dt.transaction_id = at.transaction_id\\nJOIN sys.databases d ON dt.database_id = d.database_id\\nLEFT JOIN sys.dm_tran_session_transactions st ON st.transaction_id = at.transaction_id\\nWHERE st.session_id IS NULL\\n  AND d.database_id > 4\\n  AND at.transaction_state NOT IN (2)"}	{"condition": "active transactions with no session (orphaned/deferred)", "description": "Deferred transactions with no owning session — these cannot be resolved by killing a session"}	null	2026-02-23 20:18:31.390457
2548	sqlserver	query	Find sleeping sessions with open transactions and long idle time	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.login_name, s.status AS session_status,\\n  s.open_transaction_count,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  t.transaction_begin_time,\\n  DATEDIFF(MINUTE, t.transaction_begin_time, GETDATE()) AS txn_age_minutes,\\n  t.name AS transaction_name\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON st.session_id = s.session_id\\nJOIN sys.dm_tran_active_transactions t ON t.transaction_id = st.transaction_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 10"}	{"condition": "sleeping sessions idle > 10 minutes with open transactions", "description": "Application likely crashed without closing transaction — session persists via connection pool"}	null	2026-02-23 20:18:31.390458
2549	sqlserver	query	Check if orphaned transaction is blocking other sessions	{"sql": "SELECT blocked.session_id AS blocked_session,\\n  blocked.wait_type, blocked.wait_time / 1000 AS wait_seconds,\\n  blocked.blocking_session_id AS blocking_session,\\n  bs.status AS blocker_status,\\n  bs.open_transaction_count AS blocker_open_txns,\\n  DATEDIFF(MINUTE, bs.last_request_end_time, GETDATE()) AS blocker_idle_minutes\\nFROM sys.dm_exec_requests blocked\\nJOIN sys.dm_exec_sessions bs ON blocked.blocking_session_id = bs.session_id\\nWHERE bs.status = 'sleeping'\\n  AND bs.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, bs.last_request_end_time, GETDATE()) > 10"}	{"condition": "orphaned transactions blocking other sessions", "description": "Orphaned transaction causing blocking chain — confirms impact"}	null	2026-02-23 20:18:31.390458
2552	sqlserver	query	Check for in-doubt DTC transactions	{"sql": "SELECT at.transaction_id, at.name AS transaction_name,\\n  at.transaction_begin_time,\\n  DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) AS age_minutes,\\n  at.dtc_state,\\n  CASE at.dtc_state\\n    WHEN 1 THEN 'Active'\\n    WHEN 2 THEN 'Prepared'\\n    WHEN 3 THEN 'Committed'\\n    WHEN 4 THEN 'Aborted'\\n    WHEN 5 THEN 'Recovered'\\n  END AS dtc_state_desc,\\n  at.transaction_state,\\n  dt.database_transaction_log_bytes_reserved,\\n  d.name AS database_name\\nFROM sys.dm_tran_active_transactions at\\nJOIN sys.dm_tran_database_transactions dt ON at.transaction_id = dt.transaction_id\\nJOIN sys.databases d ON dt.database_id = d.database_id\\nWHERE at.transaction_type = 4\\n  AND at.dtc_state IN (2, 3, 4, 5)"}	{"condition": "DTC transactions in Prepared/Committed/Aborted/Recovered state", "description": "In-doubt distributed transactions — DTC coordinator failed before resolving outcome"}	null	2026-02-23 20:18:31.390459
2553	sqlserver	query	Check for locks held by DTC transactions	{"sql": "SELECT l.resource_type,\\n  l.resource_description,\\n  l.request_mode, l.request_status,\\n  l.request_owner_type,\\n  at.transaction_id,\\n  at.name AS transaction_name,\\n  DATEDIFF(MINUTE, at.transaction_begin_time, GETDATE()) AS age_minutes\\nFROM sys.dm_tran_locks l\\nJOIN sys.dm_tran_active_transactions at ON l.request_owner_id = at.transaction_id\\nWHERE at.transaction_type = 4\\n  AND at.dtc_state IN (2, 3, 4, 5)\\n  AND l.request_status = 'GRANT'"}	{"condition": "DTC transactions holding granted locks", "description": "In-doubt DTC transactions actively holding locks — blocking other work"}	null	2026-02-23 20:18:31.39046
2554	sqlserver	query	Find sessions in killed/rollback state	{"sql": "SELECT s.session_id, s.status,\\n  r.command, r.status AS request_status,\\n  r.wait_type, r.wait_time / 1000 AS wait_seconds,\\n  r.total_elapsed_time / 60000 AS elapsed_minutes,\\n  s.open_transaction_count,\\n  t.transaction_begin_time,\\n  DATEDIFF(MINUTE, t.transaction_begin_time, GETDATE()) AS txn_age_minutes\\nFROM sys.dm_exec_sessions s\\nLEFT JOIN sys.dm_exec_requests r ON r.session_id = s.session_id\\nLEFT JOIN sys.dm_tran_session_transactions st ON st.session_id = s.session_id\\nLEFT JOIN sys.dm_tran_active_transactions t ON t.transaction_id = st.transaction_id\\nWHERE (r.command = 'KILLED/ROLLBACK'\\n  OR (s.status = 'sleeping' AND s.open_transaction_count > 0\\n    AND s.session_id IN (\\n      SELECT DISTINCT blocking_session_id FROM sys.dm_exec_requests\\n      WHERE blocking_session_id <> 0\\n    )))"}	{"condition": "sessions in KILLED/ROLLBACK state or zombie-like blocking", "description": "Worker threads stuck in rollback — cannot complete transaction undo"}	null	2026-02-23 20:18:31.39046
2557	sqlserver	query	Check total connection count from leaking application	{"sql": "SELECT s.program_name, s.host_name,\\n  COUNT(*) AS total_connections,\\n  SUM(CASE WHEN s.status = 'sleeping' AND s.open_transaction_count > 0 THEN 1 ELSE 0 END) AS orphaned_txn_sessions,\\n  SUM(CASE WHEN s.status IN ('running', 'runnable', 'suspended') THEN 1 ELSE 0 END) AS active_sessions,\\n  CAST(SUM(CASE WHEN s.status = 'sleeping' AND s.open_transaction_count > 0 THEN 1 ELSE 0 END) AS FLOAT) /\\n    NULLIF(COUNT(*), 0) * 100 AS orphan_pct\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.program_name IN (\\n    SELECT s2.program_name FROM sys.dm_exec_sessions s2\\n    JOIN sys.dm_tran_session_transactions st2 ON st2.session_id = s2.session_id\\n    WHERE s2.status = 'sleeping' AND s2.open_transaction_count > 0\\n    GROUP BY s2.program_name HAVING COUNT(*) > 2\\n  )\\nGROUP BY s.program_name, s.host_name"}	{"condition": "orphan_pct > 30 or total_connections growing abnormally", "description": "High ratio of orphaned transaction sessions confirms systematic pool leak"}	null	2026-02-23 20:18:31.390462
2558	sqlserver	query	Find sessions with implicit transactions left open	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.open_transaction_count, s.status,\\n  c.client_net_address, c.net_transport,\\n  c.protocol_version,\\n  t.name AS transaction_name,\\n  t.transaction_begin_time,\\n  DATEDIFF(MINUTE, t.transaction_begin_time, GETDATE()) AS txn_age_minutes,\\n  (SELECT text FROM sys.dm_exec_sql_text(c.most_recent_sql_handle)) AS last_sql\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON st.session_id = s.session_id\\nJOIN sys.dm_tran_active_transactions t ON t.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_connections c ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 5"}	{"condition": "sleeping sessions with open implicit transactions and driver-indicative last SQL", "description": "Driver left transaction open without explicit BEGIN TRANSACTION from application"}	null	2026-02-23 20:18:31.390462
2559	sqlserver	query	Find sessions stuck in KILLED/ROLLBACK state	{"sql": "SELECT r.session_id, r.command, r.status,\\n  r.percent_complete,\\n  r.estimated_completion_time / 60000 AS est_completion_minutes,\\n  r.total_elapsed_time / 60000 AS elapsed_minutes,\\n  r.wait_type, r.wait_time / 1000 AS wait_seconds,\\n  r.wait_resource,\\n  s.open_transaction_count,\\n  s.program_name, s.host_name\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nWHERE r.command = 'KILLED/ROLLBACK'"}	{"condition": "sessions in KILLED/ROLLBACK state", "description": "KILL command issued but rollback is in progress or stuck"}	null	2026-02-23 20:18:31.390463
2560	sqlserver	query	Check if KILLED/ROLLBACK session is blocking others	{"sql": "SELECT r.session_id AS blocked_session,\\n  r.blocking_session_id,\\n  r.wait_type, r.wait_time / 1000 AS wait_seconds,\\n  kr.command AS blocker_command,\\n  kr.percent_complete AS rollback_pct,\\n  kr.total_elapsed_time / 60000 AS rollback_elapsed_minutes\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_requests kr ON r.blocking_session_id = kr.session_id\\nWHERE kr.command = 'KILLED/ROLLBACK'"}	{"condition": "other sessions blocked by KILLED/ROLLBACK session", "description": "Stuck kill is causing a blocking chain — critical impact"}	null	2026-02-23 20:18:31.390463
2561	sqlserver	query	Find idle sessions with open transactions matching LB timeout pattern	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.open_transaction_count, s.status,\\n  c.client_net_address,\\n  s.last_request_end_time,\\n  DATEDIFF(SECOND, s.last_request_end_time, GETDATE()) AS idle_seconds,\\n  t.transaction_begin_time,\\n  DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS txn_age_seconds,\\n  (SELECT text FROM sys.dm_exec_sql_text(c.most_recent_sql_handle)) AS last_sql\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON st.session_id = s.session_id\\nJOIN sys.dm_tran_active_transactions t ON t.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_connections c ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(SECOND, s.last_request_end_time, GETDATE()) > 120"}	{"condition": "multiple idle sessions from similar client addresses with open transactions", "description": "Pattern consistent with load balancer severing connections — sessions idle past LB timeout"}	null	2026-02-23 20:18:31.390465
2562	sqlserver	query	Check for concentration of orphaned sessions from same network segment	{"sql": "SELECT c.client_net_address,\\n  COUNT(*) AS orphaned_count,\\n  AVG(DATEDIFF(MINUTE, s.last_request_end_time, GETDATE())) AS avg_idle_minutes\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON st.session_id = s.session_id\\nJOIN sys.dm_exec_connections c ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 5\\nGROUP BY c.client_net_address\\nHAVING COUNT(*) > 1\\nORDER BY orphaned_count DESC"}	{"condition": "multiple orphaned transactions from same client IP (load balancer IP)", "description": "Concentration from same IP confirms load balancer is the intermediary severing connections"}	null	2026-02-23 20:18:31.390465
2563	sqlserver	query	Find sleeping debug-like sessions with open transactions	{"sql": "SELECT s.session_id, s.program_name, s.host_name,\\n  s.login_name, s.status,\\n  s.open_transaction_count,\\n  t.transaction_begin_time,\\n  DATEDIFF(MINUTE, t.transaction_begin_time, GETDATE()) AS txn_age_minutes,\\n  DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) AS idle_minutes,\\n  (SELECT text FROM sys.dm_exec_sql_text(c.most_recent_sql_handle)) AS last_sql\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_tran_session_transactions st ON st.session_id = s.session_id\\nJOIN sys.dm_tran_active_transactions t ON t.transaction_id = st.transaction_id\\nJOIN sys.dm_exec_connections c ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND s.status = 'sleeping'\\n  AND s.open_transaction_count > 0\\n  AND DATEDIFF(MINUTE, s.last_request_end_time, GETDATE()) > 30\\n  AND (s.program_name LIKE '%Management Studio%'\\n    OR s.program_name LIKE '%Visual Studio%'\\n    OR s.program_name LIKE '%sqlcmd%'\\n    OR s.program_name LIKE '%Azure Data Studio%'\\n    OR s.program_name LIKE '%DBeaver%'\\n    OR s.program_name LIKE '%DataGrip%')"}	{"condition": "debug/IDE tool sessions with open transactions idle > 30 minutes", "description": "Developer tool left transaction open — likely forgot to COMMIT/ROLLBACK after debugging"}	null	2026-02-23 20:18:31.390466
2564	sqlserver	query	Check if debug session transactions are causing blocking	{"sql": "SELECT r.session_id AS blocked_session,\\n  r.blocking_session_id,\\n  r.wait_type, r.wait_time / 1000 AS wait_seconds,\\n  bs.program_name AS blocker_app,\\n  bs.host_name AS blocker_host,\\n  DATEDIFF(MINUTE, bs.last_request_end_time, GETDATE()) AS blocker_idle_minutes\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions bs ON r.blocking_session_id = bs.session_id\\nWHERE bs.status = 'sleeping'\\n  AND bs.open_transaction_count > 0\\n  AND (bs.program_name LIKE '%Management Studio%'\\n    OR bs.program_name LIKE '%Visual Studio%'\\n    OR bs.program_name LIKE '%sqlcmd%'\\n    OR bs.program_name LIKE '%Azure Data Studio%'\\n    OR bs.program_name LIKE '%DBeaver%'\\n    OR bs.program_name LIKE '%DataGrip%')"}	{"condition": "debug sessions blocking production queries", "description": "Developer debug session is blocking production workload — critical impact"}	null	2026-02-23 20:18:31.390467
2565	sqlserver	query	Check deadlock counters and recent deadlock victim sessions	{"sql": "SELECT\\n  pc.cntr_value AS total_deadlocks,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Transactions/sec' AND instance_name = '_Total') AS txn_per_sec,\\n  CASE WHEN (SELECT cntr_value FROM sys.dm_os_performance_counters\\n    WHERE counter_name = 'Transactions/sec' AND instance_name = '_Total') > 0\\n    THEN CAST(pc.cntr_value AS FLOAT) /\\n      NULLIF((SELECT cntr_value FROM sys.dm_os_performance_counters\\n        WHERE counter_name = 'Transactions/sec' AND instance_name = '_Total'), 0) * 100\\n    ELSE 0 END AS deadlock_pct_of_txn\\nFROM sys.dm_os_performance_counters pc\\nWHERE pc.object_name LIKE '%Locks%'\\n  AND pc.counter_name = 'Number of Deadlocks/sec'\\n  AND pc.instance_name = '_Total'"}	{"condition": "total_deadlocks > 0", "description": "Deadlock counter shows deadlocks have occurred since instance restart"}	null	2026-02-23 20:18:31.390467
2566	sqlserver	query	Check system_health session for recent deadlock graphs	{"sql": "SELECT TOP 20\\n  xed.value('(event/@timestamp)[1]', 'datetime2') AS deadlock_time,\\n  xed.value('(event/data[@name=\\"resource_owner_type\\"]/text)[1]', 'varchar(50)') AS resource_type,\\n  xed.query('(event/data[@name=\\"xml_report\\"]/value/deadlock)[1]') AS deadlock_graph\\nFROM (\\n  SELECT CAST(target_data AS XML) AS target_xml\\n  FROM sys.dm_xe_session_targets st\\n  JOIN sys.dm_xe_sessions s ON st.event_session_address = s.address\\n  WHERE s.name = 'system_health'\\n    AND st.target_name = 'ring_buffer'\\n) AS data\\nCROSS APPLY target_xml.nodes('RingBufferTarget/event[@name=\\"xml_deadlock_report\\"]') AS xed(xed)\\nORDER BY deadlock_time DESC"}	{"condition": "row_count > 0 AND recent deadlock graphs within last 24 hours", "description": "Recent deadlock reports in system_health session confirm active deadlock-induced rollbacks"}	null	2026-02-23 20:18:31.390468
2567	sqlserver	query	Check for lock timeout counters and blocked sessions approaching timeout	{"sql": "SELECT\\n  pc.cntr_value AS total_lock_timeouts,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Lock Waits/sec' AND instance_name = '_Total'\\n     AND object_name LIKE '%Locks%') AS lock_waits_per_sec,\\n  pc2.cntr_value AS lock_wait_time_ms\\nFROM sys.dm_os_performance_counters pc\\nJOIN sys.dm_os_performance_counters pc2\\n  ON pc2.object_name LIKE '%Locks%'\\n  AND pc2.counter_name = 'Lock Wait Time (ms)'\\n  AND pc2.instance_name = '_Total'\\nWHERE pc.object_name LIKE '%Locks%'\\n  AND pc.counter_name = 'Lock Timeouts/sec'\\n  AND pc.instance_name = '_Total'"}	{"condition": "total_lock_timeouts > 0", "description": "Lock timeout counter shows transactions have timed out waiting for locks"}	null	2026-02-23 20:18:31.390468
2691	sqlserver	query	Check for Mixed Mode and absence of SQL Vulnerability Assessment	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  SERVERPROPERTY('ProductVersion') AS sql_version,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%') AS active_sql_logins,\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications WHERE is_state_enabled = 1) AS active_audit_specs"}	{"condition": "windows_auth_only = 0 AND active_audits = 0", "description": "Mixed Mode enabled with no server audits — no compliance scanning would detect this misconfiguration"}	null	2026-02-23 20:18:31.390542
2568	sqlserver	query	Check for sessions with LOCK_TIMEOUT set and currently blocked requests	{"sql": "SELECT\\n  r.session_id, r.blocking_session_id,\\n  r.wait_type, r.wait_time AS wait_time_ms,\\n  r.lock_timeout AS lock_timeout_ms,\\n  s.program_name, s.host_name,\\n  DATEDIFF(second, r.start_time, GETDATE()) AS request_duration_sec,\\n  SUBSTRING(t.text, (r.statement_start_offset / 2) + 1,\\n    (CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE r.statement_end_offset END - r.statement_start_offset) / 2 + 1) AS current_sql\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE r.blocking_session_id <> 0\\n  AND r.wait_type LIKE 'LCK_%'\\n  AND r.lock_timeout > 0\\n  AND r.wait_time > r.lock_timeout * 0.8\\nORDER BY r.wait_time DESC"}	{"condition": "row_count > 0 AND wait_time approaching lock_timeout", "description": "Blocked sessions with wait times approaching LOCK_TIMEOUT confirm lock wait timeout-induced rollbacks"}	null	2026-02-23 20:18:31.390469
2569	sqlserver	query	Check if snapshot isolation is enabled and version store is active	{"sql": "SELECT\\n  d.name AS database_name,\\n  d.snapshot_isolation_state_desc,\\n  d.is_read_committed_snapshot_on,\\n  vs.reserved_page_count * 8 AS version_store_kb,\\n  vs.reserved_page_count * 8 / 1024 AS version_store_mb,\\n  pc.cntr_value AS snapshot_txn_count,\\n  pc2.cntr_value AS update_conflict_ratio\\nFROM sys.databases d\\nLEFT JOIN sys.dm_tran_version_store_space_usage vs ON d.database_id = vs.database_id\\nLEFT JOIN sys.dm_os_performance_counters pc\\n  ON pc.counter_name = 'Snapshot Transactions'\\n  AND pc.instance_name = d.name\\n  AND pc.object_name LIKE '%Transactions%'\\nLEFT JOIN sys.dm_os_performance_counters pc2\\n  ON pc2.counter_name = 'Update conflict ratio'\\n  AND pc2.instance_name = d.name\\n  AND pc2.object_name LIKE '%Transactions%'\\nWHERE d.database_id > 4\\n  AND (d.snapshot_isolation_state = 1 OR d.is_read_committed_snapshot_on = 1)"}	{"condition": "snapshot or RCSI enabled AND (update_conflict_ratio > 0 OR version_store_kb > 0)", "description": "Databases using snapshot isolation with active version store and update conflicts"}	null	2026-02-23 20:18:31.39047
4329	postgresql	query	Check staging or source tables for zero rows or stale data	{"sql": "SELECT schemaname, relname, n_live_tup, last_analyze, last_autoanalyze FROM pg_stat_user_tables WHERE (relname ILIKE '%staging%' OR relname ILIKE '%source%' OR relname ILIKE '%import%' OR relname ILIKE '%landing%') AND (n_live_tup = 0 OR last_autoanalyze < now() - interval '24 hours' OR last_autoanalyze IS NULL) ORDER BY relname"}	{"condition": "row_count > 0", "description": "Staging or source tables found with zero rows or stale data, indicating missing data delivery"}	\N	2026-02-25 00:28:52.405273
