2587	sqlserver	query	Check if sa account is enabled and has default name	{"sql": "SELECT sp.name, sp.is_disabled, sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  LOGINPROPERTY(sp.name, 'DaysUntilExpiration') AS days_until_expiration\\nFROM sys.server_principals sp\\nLEFT JOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sp.sid = 0x01\\n  AND sp.is_disabled = 0"}	{"condition": "row_count > 0", "description": "The sa account (SID 0x01) is still enabled — installation default not hardened"}	null	2026-02-23 20:18:31.390483
3852	postgresql	query	Check replication connections for missing standbys	{"sql": "SELECT slot_name, slot_type, active, database FROM pg_replication_slots"}	{"condition": "row_count > 0 AND active = false", "description": "Inactive replication slots indicate standbys that cannot connect — may be blocked by firewall"}	\N	2026-02-25 00:28:52.405273
2588	sqlserver	query	Check for additional default settings not changed	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'xp_cmdshell') AS xp_cmdshell_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'remote admin connections') AS dac_remote_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'cross db ownership chaining') AS cross_db_chaining,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE name = 'sa' AND sid = 0x01) AS sa_not_renamed,\\n  (SELECT is_disabled FROM sys.server_principals WHERE name = 'BUILTIN\\\\Administrators') AS builtin_admin_enabled"}	{"condition": "sa_not_renamed = 1 OR xp_cmdshell_enabled = 1 OR cross_db_chaining = 1", "description": "Default security-sensitive settings remain from installation — sa not renamed, dangerous features enabled"}	null	2026-02-23 20:18:31.390484
2571	sqlserver	query	Check for recent constraint violation errors in query stats and ring buffer	{"sql": "SELECT\\n  xed.value('(event/@timestamp)[1]', 'datetime2') AS error_time,\\n  xed.value('(event/data[@name=\\"error_number\\"]/value)[1]', 'int') AS error_number,\\n  xed.value('(event/data[@name=\\"severity\\"]/value)[1]', 'int') AS severity,\\n  xed.value('(event/data[@name=\\"message\\"]/value)[1]', 'varchar(500)') AS error_message\\nFROM (\\n  SELECT CAST(target_data AS XML) AS target_xml\\n  FROM sys.dm_xe_session_targets st\\n  JOIN sys.dm_xe_sessions s ON st.event_session_address = s.address\\n  WHERE s.name = 'system_health'\\n    AND st.target_name = 'ring_buffer'\\n) AS data\\nCROSS APPLY target_xml.nodes('RingBufferTarget/event[@name=\\"error_reported\\"]') AS xed(xed)\\nWHERE xed.value('(event/data[@name=\\"error_number\\"]/value)[1]', 'int')\\n  IN (2627, 2601, 547, 548)\\nORDER BY error_time DESC"}	{"condition": "row_count > 5 with recent constraint violation errors", "description": "Frequent constraint violation errors (2627=PK/unique duplicate, 2601=unique index duplicate, 547=FK violation, 548=CHECK violation) indicate data integrity issues causing rollbacks"}	null	2026-02-23 20:18:31.390471
2572	sqlserver	query	Check transaction rollback counters vs commit counters	{"sql": "SELECT\\n  db.name AS database_name,\\n  pc_write.cntr_value AS write_txn,\\n  pc_active.cntr_value AS active_txn,\\n  (SELECT SUM(cntr_value) FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Transactions/sec' AND object_name LIKE '%Databases%'\\n     AND instance_name = db.name) AS total_txn_per_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Errors/sec' AND instance_name = 'User Errors'\\n     AND object_name LIKE '%SQL Errors%') AS user_errors_per_sec\\nFROM sys.databases db\\nLEFT JOIN sys.dm_os_performance_counters pc_write\\n  ON pc_write.counter_name = 'Write Transactions/sec'\\n  AND pc_write.instance_name = db.name\\n  AND pc_write.object_name LIKE '%Databases%'\\nLEFT JOIN sys.dm_os_performance_counters pc_active\\n  ON pc_active.counter_name = 'Active Transactions'\\n  AND pc_active.instance_name = db.name\\n  AND pc_active.object_name LIKE '%Databases%'\\nWHERE db.database_id > 4\\n  AND pc_write.cntr_value > 0\\nORDER BY user_errors_per_sec DESC"}	{"condition": "user_errors_per_sec > 0 AND elevated relative to total_txn_per_sec", "description": "High user error rate alongside write transactions confirms constraint violations driving rollbacks"}	null	2026-02-23 20:18:31.390471
2573	sqlserver	query	Check for high rollback ratio vs commits	{"sql": "SELECT\\n  qs.sql_handle,\\n  qs.execution_count,\\n  SUM(CASE WHEN qs.total_rows = 0 THEN 1 ELSE 0 END) OVER (PARTITION BY qs.sql_handle) AS zero_row_executions,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  s.program_name,\\n  SUBSTRING(t.text, 1, 500) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nLEFT JOIN sys.dm_exec_sessions s ON qs.plan_handle IS NOT NULL\\nWHERE (t.text LIKE '%ROLLBACK%' OR t.text LIKE '%RAISERROR%' OR t.text LIKE '%THROW%')\\n  AND (t.text LIKE '%BEGIN TRAN%' OR t.text LIKE '%BEGIN TRANSACTION%')\\n  AND qs.execution_count > 10\\nORDER BY qs.execution_count DESC"}	{"condition": "row_count > 0 AND queries with both BEGIN TRAN and ROLLBACK/THROW that execute frequently", "description": "Frequently executed stored procedures or batches that contain both BEGIN TRAN and ROLLBACK/THROW patterns suggest validation-driven rollbacks"}	null	2026-02-23 20:18:31.390472
2575	sqlserver	query	Check for data type conversion errors in system_health ring buffer	{"sql": "SELECT TOP 30\\n  xed.value('(event/@timestamp)[1]', 'datetime2') AS error_time,\\n  xed.value('(event/data[@name=\\"error_number\\"]/value)[1]', 'int') AS error_number,\\n  xed.value('(event/data[@name=\\"message\\"]/value)[1]', 'varchar(500)') AS error_message\\nFROM (\\n  SELECT CAST(target_data AS XML) AS target_xml\\n  FROM sys.dm_xe_session_targets st\\n  JOIN sys.dm_xe_sessions s ON st.event_session_address = s.address\\n  WHERE s.name = 'system_health'\\n    AND st.target_name = 'ring_buffer'\\n) AS data\\nCROSS APPLY target_xml.nodes('RingBufferTarget/event[@name=\\"error_reported\\"]') AS xed(xed)\\nWHERE xed.value('(event/data[@name=\\"error_number\\"]/value)[1]', 'int')\\n  IN (245, 8114, 8115, 529, 206, 257)\\nORDER BY error_time DESC"}	{"condition": "row_count > 5 with recent data conversion errors", "description": "Frequent data type conversion errors: 245 (conversion failed varchar to int), 8114 (error converting data type), 8115 (arithmetic overflow), 529 (explicit conversion not allowed)"}	null	2026-02-23 20:18:31.390473
2576	sqlserver	query	Check for queries with implicit conversion warnings in cached plans	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  p.query_plan.exist('//Warnings/PlanAffectingConvert') AS has_implicit_convert,\\n  p.query_plan.value('count(//Warnings/PlanAffectingConvert)', 'int') AS convert_warnings,\\n  SUBSTRING(t.text, 1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.exist('//Warnings/PlanAffectingConvert') = 1\\n  AND qs.execution_count > 10\\nORDER BY qs.execution_count DESC"}	{"condition": "has_implicit_convert = 1 AND convert_warnings > 0 AND execution_count > 10", "description": "Frequently executed queries with implicit conversion warnings confirm systematic data type mismatch issues"}	null	2026-02-23 20:18:31.390474
2604	sqlserver	query	Check for non-DBA accounts with sysadmin	{"sql": "SELECT sp.name, sp.type_desc,\\n  sp.create_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  (SELECT COUNT(*) FROM sys.server_role_members srm2\\n   JOIN sys.server_principals r2 ON srm2.role_principal_id = r2.principal_id\\n   WHERE srm2.member_principal_id = sp.principal_id) AS total_server_roles\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals r ON srm.role_principal_id = r.principal_id\\nWHERE r.name = 'sysadmin'\\n  AND sp.is_disabled = 0\\n  AND sp.type IN ('S', 'U')\\n  AND sp.name NOT LIKE 'NT SERVICE\\\\%'\\n  AND sp.name NOT LIKE '##%##'\\n  AND sp.sid <> 0x01"}	{"condition": "row_count > 2", "description": "More than 2 non-service accounts have sysadmin — excessive privilege accumulation"}	null	2026-02-23 20:18:31.390475
2578	sqlserver	query	Check for resource-related errors in ring buffer	{"sql": "SELECT TOP 20\\n  xed.value('(event/@timestamp)[1]', 'datetime2') AS error_time,\\n  xed.value('(event/data[@name=\\"error_number\\"]/value)[1]', 'int') AS error_number,\\n  xed.value('(event/data[@name=\\"message\\"]/value)[1]', 'varchar(500)') AS error_message\\nFROM (\\n  SELECT CAST(target_data AS XML) AS target_xml\\n  FROM sys.dm_xe_session_targets st\\n  JOIN sys.dm_xe_sessions s ON st.event_session_address = s.address\\n  WHERE s.name = 'system_health'\\n    AND st.target_name = 'ring_buffer'\\n) AS data\\nCROSS APPLY target_xml.nodes('RingBufferTarget/event[@name=\\"error_reported\\"]') AS xed(xed)\\nWHERE xed.value('(event/data[@name=\\"error_number\\"]/value)[1]', 'int')\\n  IN (1105, 9002, 701, 8628, 8645, 17889)\\nORDER BY error_time DESC"}	{"condition": "row_count > 0 with resource exhaustion errors", "description": "Resource errors confirm exhaustion: 1105 (filegroup full), 9002 (log full), 701 (insufficient memory), 8628/8645 (query timeout waiting for memory grant), 17889 (max worker threads)"}	null	2026-02-23 20:18:31.390476
15053	mariadb	query	Check for loaded shared library UDFs	{"sql": "SELECT name, type, dl FROM mysql.func WHERE dl IS NOT NULL AND dl != '';"}	{"condition": "row_count > 0", "description": "Shared library UDFs loaded that execute in MySQL server process without sandboxing"}	\N	2026-05-11 22:17:39.229791
2580	sqlserver	query	Check for trigger-related errors and ROLLBACK within trigger definitions	{"sql": "SELECT\\n  OBJECT_NAME(tr.parent_id) AS table_name,\\n  tr.name AS trigger_name,\\n  CASE\\n    WHEN OBJECT_DEFINITION(tr.object_id) LIKE '%ROLLBACK%' THEN 'explicit_rollback'\\n    WHEN OBJECT_DEFINITION(tr.object_id) LIKE '%RAISERROR%' THEN 'raiserror'\\n    WHEN OBJECT_DEFINITION(tr.object_id) LIKE '%THROW%' THEN 'throw'\\n    ELSE 'other'\\n  END AS abort_mechanism,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_ms,\\n  LEN(OBJECT_DEFINITION(tr.object_id)) AS trigger_code_length\\nFROM sys.triggers tr\\nJOIN sys.dm_exec_trigger_stats qs ON tr.object_id = qs.object_id\\nWHERE tr.is_disabled = 0\\n  AND (OBJECT_DEFINITION(tr.object_id) LIKE '%ROLLBACK%'\\n    OR OBJECT_DEFINITION(tr.object_id) LIKE '%RAISERROR%WITH%16%'\\n    OR OBJECT_DEFINITION(tr.object_id) LIKE '%THROW%')\\n  AND qs.execution_count > 100\\nORDER BY qs.execution_count DESC"}	{"condition": "row_count > 0 AND triggers containing ROLLBACK, RAISERROR severity 16+, or THROW", "description": "Triggers with explicit rollback or error-raising code that execute frequently confirm trigger-induced transaction aborts"}	null	2026-02-23 20:18:31.390478
2583	sqlserver	query	Check for lock contention on specific resources with blocking	{"sql": "SELECT TOP 20\\n  tl.resource_type,\\n  tl.resource_description,\\n  tl.resource_associated_entity_id,\\n  OBJECT_NAME(p.object_id) AS table_name,\\n  tl.request_mode,\\n  COUNT(*) AS lock_requests,\\n  SUM(CASE WHEN tl.request_status = 'WAIT' THEN 1 ELSE 0 END) AS waiting_requests,\\n  SUM(CASE WHEN tl.request_status = 'GRANT' THEN 1 ELSE 0 END) AS granted_requests,\\n  MAX(r.wait_time) AS max_wait_time_ms\\nFROM sys.dm_tran_locks tl\\nLEFT JOIN sys.partitions p ON tl.resource_associated_entity_id = p.hobt_id\\nLEFT JOIN sys.dm_exec_requests r ON tl.request_session_id = r.session_id\\n  AND r.blocking_session_id <> 0\\nWHERE tl.resource_type IN ('KEY', 'RID', 'PAGE')\\n  AND tl.request_status IN ('WAIT', 'GRANT')\\nGROUP BY tl.resource_type, tl.resource_description,\\n  tl.resource_associated_entity_id, OBJECT_NAME(p.object_id),\\n  tl.request_mode\\nHAVING SUM(CASE WHEN tl.request_status = 'WAIT' THEN 1 ELSE 0 END) > 2\\nORDER BY waiting_requests DESC"}	{"condition": "waiting_requests > 2 on same resource (KEY/RID/PAGE)", "description": "Multiple sessions waiting for the same row or page lock confirm hot row contention"}	null	2026-02-23 20:18:31.39048
2584	sqlserver	query	Check wait statistics for lock contention patterns	{"sql": "SELECT\\n  ws.wait_type,\\n  ws.waiting_tasks_count,\\n  ws.wait_time_ms,\\n  ws.max_wait_time_ms,\\n  CASE WHEN ws.waiting_tasks_count > 0\\n    THEN ws.wait_time_ms / ws.waiting_tasks_count\\n    ELSE 0 END AS avg_wait_ms\\nFROM sys.dm_os_wait_stats ws\\nWHERE ws.wait_type IN (\\n  'LCK_M_X', 'LCK_M_U', 'LCK_M_S',\\n  'LCK_M_IX', 'LCK_M_IU', 'LCK_M_IS',\\n  'LCK_M_SCH_M', 'LCK_M_SCH_S'\\n)\\n  AND ws.waiting_tasks_count > 100\\nORDER BY ws.wait_time_ms DESC"}	{"condition": "LCK_M_X or LCK_M_U wait_time_ms high AND waiting_tasks_count > 100", "description": "High exclusive (X) and update (U) lock waits confirm write-write contention on hot rows causing transaction failures"}	null	2026-02-23 20:18:31.39048
2605	sqlserver	query	Check for recently modified logins and role memberships	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date, sp.modify_date,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  (SELECT COUNT(*) FROM sys.server_role_members srm\\n   WHERE srm.member_principal_id = sp.principal_id) AS server_role_count\\nFROM sys.server_principals sp\\nWHERE sp.modify_date > DATEADD(DAY, -30, GETDATE())\\n  AND sp.name NOT LIKE '##%##'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.type IN ('S', 'U', 'G')\\nORDER BY sp.modify_date DESC"}	{"condition": "row_count > 0", "description": "Login principals modified in the last 30 days"}	null	2026-02-23 20:18:31.390481
2594	sqlserver	query	Check built-in and default accounts status	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  sp.create_date, sp.modify_date,\\n  CASE\\n    WHEN sp.sid = 0x01 THEN 'sa (default sysadmin)'\\n    WHEN sp.name = 'BUILTIN\\\\Administrators' THEN 'Local Admins group'\\n    WHEN sp.name = 'NT AUTHORITY\\\\SYSTEM' THEN 'OS System account'\\n    WHEN sp.name = 'NT SERVICE\\\\MSSQLSERVER' THEN 'SQL Service account'\\n    WHEN sp.name = 'NT SERVICE\\\\SQLSERVERAGENT' THEN 'Agent Service account'\\n    WHEN sp.name LIKE '##%##' THEN 'Internal system certificate'\\n    ELSE 'Custom or unknown'\\n  END AS account_purpose\\nFROM sys.server_principals sp\\nWHERE (sp.sid = 0x01\\n  OR sp.name IN ('BUILTIN\\\\Administrators', 'NT AUTHORITY\\\\SYSTEM')\\n  OR sp.name LIKE '##%##'\\n  OR sp.type = 'S')\\n  AND sp.is_disabled = 0\\nORDER BY sp.type_desc, sp.name"}	{"condition": "row_count > 3", "description": "Multiple default/built-in accounts remain enabled beyond minimum service requirements"}	null	2026-02-23 20:18:31.390487
2585	sqlserver	query	Check for connection reset indicators and orphaned transactions	{"sql": "SELECT\\n  pc_resets.cntr_value AS connection_resets_per_sec,\\n  pc_logins.cntr_value AS logins_per_sec,\\n  pc_logouts.cntr_value AS logouts_per_sec,\\n  pc_user_conn.cntr_value AS current_user_connections,\\n  CASE WHEN pc_logins.cntr_value > 0\\n    THEN CAST(pc_resets.cntr_value AS FLOAT) / pc_logins.cntr_value * 100\\n    ELSE 0 END AS reset_pct_of_logins\\nFROM sys.dm_os_performance_counters pc_resets\\nJOIN sys.dm_os_performance_counters pc_logins\\n  ON pc_logins.counter_name = 'Logins/sec'\\n  AND pc_logins.object_name LIKE '%General Statistics%'\\nJOIN sys.dm_os_performance_counters pc_logouts\\n  ON pc_logouts.counter_name = 'Logouts/sec'\\n  AND pc_logouts.object_name LIKE '%General Statistics%'\\nJOIN sys.dm_os_performance_counters pc_user_conn\\n  ON pc_user_conn.counter_name = 'User Connections'\\n  AND pc_user_conn.object_name LIKE '%General Statistics%'\\nWHERE pc_resets.counter_name = 'Connection Reset/sec'\\n  AND pc_resets.object_name LIKE '%General Statistics%'"}	{"condition": "reset_pct_of_logins > 5 OR connection_resets_per_sec significantly elevated", "description": "High connection reset rate relative to logins indicates unstable connections"}	null	2026-02-23 20:18:31.390482
2586	sqlserver	query	Check error log for connection-related errors and transaction rollback recovery	{"sql": "SELECT TOP 30\\n  xed.value('(event/@timestamp)[1]', 'datetime2') AS event_time,\\n  xed.value('(event/data[@name=\\"error_number\\"]/value)[1]', 'int') AS error_number,\\n  xed.value('(event/data[@name=\\"message\\"]/value)[1]', 'varchar(500)') AS error_message\\nFROM (\\n  SELECT CAST(target_data AS XML) AS target_xml\\n  FROM sys.dm_xe_session_targets st\\n  JOIN sys.dm_xe_sessions s ON st.event_session_address = s.address\\n  WHERE s.name = 'system_health'\\n    AND st.target_name = 'ring_buffer'\\n) AS data\\nCROSS APPLY target_xml.nodes('RingBufferTarget/event[@name=\\"error_reported\\"]') AS xed(xed)\\nWHERE xed.value('(event/data[@name=\\"error_number\\"]/value)[1]', 'int')\\n  IN (233, 10054, 10053, 64, 121, 4014)\\nORDER BY event_time DESC"}	{"condition": "row_count > 5 with connection errors", "description": "Connection errors (233=pipe broken, 10054/10053=TCP reset/abort, 64=connection forcibly closed, 121=semaphore timeout, 4014=fatal transport error) confirm network flakiness causing transaction aborts"}	null	2026-02-23 20:18:31.390483
4331	postgresql	log_scan	Scan PostgreSQL logs for FDW or dblink connection errors	{"source": "postgresql log", "pattern": "could not connect|connection refused|timeout expired|authentication failed|SSL error.*fdw|dblink.*error"}	{"condition": "matches_found > 0", "description": "Connection failures to external data sources found in logs"}	\N	2026-02-25 00:28:52.405273
2592	sqlserver	query	Check multiple hardening indicators	{"sql": "SELECT\\n  (SELECT is_disabled FROM sys.server_principals WHERE sid = 0x01) AS sa_disabled,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE name = 'sa' AND sid = 0x01) AS sa_not_renamed,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'xp_cmdshell') AS xp_cmdshell,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'Ole Automation Procedures') AS ole_automation,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'clr enabled') AS clr_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'cross db ownership chaining') AS cross_db_chaining,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'Database Mail XPs') AS db_mail_xps,\\n  (SELECT is_disabled FROM sys.server_principals WHERE name = 'BUILTIN\\\\Administrators') AS builtin_admin_disabled"}	{"condition": "sa_disabled = 0 OR sa_not_renamed = 1 OR xp_cmdshell = 1 OR ole_automation = 1 OR cross_db_chaining = 1", "description": "Multiple default security settings not hardened — indicates no post-deployment checklist was followed"}	null	2026-02-23 20:18:31.390486
2599	sqlserver	query	Check for mixed authentication patterns	{"sql": "SELECT\\n  SUM(CASE WHEN sp.type = 'S' AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS enabled_sql_logins,\\n  SUM(CASE WHEN sp.type = 'U' AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS enabled_windows_logins,\\n  SUM(CASE WHEN sp.type = 'G' AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS enabled_windows_groups,\\n  SUM(CASE WHEN sp.type = 'E' AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS enabled_external_logins,\\n  (SELECT is_disabled FROM sys.server_principals WHERE sid = 0x01) AS sa_disabled\\nFROM sys.server_principals sp\\nWHERE sp.name NOT LIKE '##%##'\\n  AND sp.name NOT LIKE 'NT %'"}	{"condition": "enabled_sql_logins > 5 AND (enabled_windows_logins > 0 OR enabled_windows_groups > 0)", "description": "Many SQL logins alongside Windows logins — mixed authentication suggests multi-vendor app landscape"}	null	2026-02-23 20:18:31.39049
2600	sqlserver	query	Check for SQL logins without password policy enforcement	{"sql": "SELECT sp.name, sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), GETDATE()) AS password_age_days\\nFROM sys.server_principals sp\\nJOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sp.type = 'S'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%##'\\n  AND sp.sid <> 0x01\\n  AND (sl.is_policy_checked = 0 OR sl.is_expiration_checked = 0)"}	{"condition": "row_count > 0", "description": "SQL logins without password policies — typical in multi-vendor environments where each app manages its own credentials"}	null	2026-02-23 20:18:31.390491
2601	sqlserver	query	Check for stale SQL logins with old passwords	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), GETDATE()) AS password_age_days,\\n  sl.is_policy_checked, sl.is_expiration_checked\\nFROM sys.server_principals sp\\nJOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sp.type = 'S'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%##'\\n  AND sp.sid <> 0x01\\n  AND DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), GETDATE()) > 90"}	{"condition": "row_count > 0", "description": "SQL logins with passwords older than 90 days — no automated rotation from identity provisioning"}	null	2026-02-23 20:18:31.390491
2602	sqlserver	query	Check for absence of server audit on login events	{"sql": "SELECT COUNT(*) AS login_audit_specs\\nFROM sys.server_audit_specification_details sasd\\nJOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\nWHERE sasd.audit_action_name IN ('SUCCESSFUL_LOGIN_GROUP', 'FAILED_LOGIN_GROUP', 'LOGIN_CHANGE_PASSWORD_GROUP')\\n  AND sas.is_state_enabled = 1"}	{"condition": "login_audit_specs = 0", "description": "No login audit configured — no centralized tracking of account lifecycle events"}	null	2026-02-23 20:18:31.390492
2662	sqlserver	query	Check for connections from diverse client networks	{"sql": "SELECT\\n  c.client_net_address,\\n  c.auth_scheme,\\n  c.encrypt_option,\\n  COUNT(*) AS session_count,\\n  COUNT(DISTINCT s.login_name) AS distinct_logins\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\nGROUP BY c.client_net_address, c.auth_scheme, c.encrypt_option\\nORDER BY session_count DESC"}	{"condition": "connections from 3+ distinct client_net_address subnets", "description": "Connections arriving from diverse networks confirms firewall is not effectively limiting access — SQL Server is exposed"}	null	2026-02-23 20:18:31.390523
2614	sqlserver	query	Check all blank-password logins for any non-essential accounts	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  sp.create_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_login,\\n  (SELECT COUNT(*) FROM sys.database_principals dp\\n   JOIN sys.databases d ON dp.name = sp.name\\n   WHERE dp.type = 'S') AS db_user_mappings\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE PWDCOMPARE('', sl.password_hash) = 1\\n  AND sp.type_desc = 'SQL_LOGIN'"}	{"condition": "row_count > 0", "description": "Any SQL login with a blank password is a security risk regardless of naming"}	null	2026-02-23 20:18:31.390494
2615	sqlserver	query	Check for logins with blank passwords where password was never changed	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  sp.create_date, sp.modify_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  CASE WHEN CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime)\\n    = sp.create_date THEN 'NEVER_CHANGED' ELSE 'CHANGED' END AS password_status\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE PWDCOMPARE('', sl.password_hash) = 1\\n  AND sp.type_desc = 'SQL_LOGIN'"}	{"condition": "row_count > 0 with password_status = NEVER_CHANGED", "description": "SQL logins with blank passwords that have never been changed since creation"}	null	2026-02-23 20:18:31.390495
3371	postgresql	query	Find long-idle zero-activity sessions	{"sql": "SELECT pid, usename, application_name, client_addr, backend_start, state, state_change, now() - state_change AS idle_duration FROM pg_stat_activity WHERE state = 'idle' AND backend_type = 'client backend' AND now() - state_change > :threshold_interval::interval ORDER BY idle_duration DESC"}	{"condition": "row_count > :idle_threshold", "description": "Many sessions idle for extended periods are potentially stale"}	{"idle_threshold": 10, "threshold_interval": "60 minutes"}	2026-02-25 00:28:52.405273
2623	sqlserver	query	Check for SQL logins with blank passwords alongside Windows logins for same users	{"sql": "SELECT\\n  sql_sp.name AS sql_login, sql_sp.create_date AS sql_created,\\n  sql_sp.is_disabled AS sql_disabled,\\n  LOGINPROPERTY(sql_sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  (SELECT COUNT(*) FROM sys.server_principals win_sp\\n   WHERE win_sp.type IN ('U', 'G')\\n     AND win_sp.name LIKE '%' + REPLACE(sql_sp.name, '_', '%') + '%') AS possible_windows_matches\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sql_sp ON sl.principal_id = sql_sp.principal_id\\nWHERE PWDCOMPARE('', sl.password_hash) = 1\\n  AND sql_sp.type_desc = 'SQL_LOGIN'"}	{"condition": "SQL logins with blank passwords, especially where Windows logins also exist", "description": "Blank-password SQL logins coexisting with Windows logins — incomplete directory integration"}	null	2026-02-23 20:18:31.390499
2624	sqlserver	query	Confirm mixed authentication with both Windows and SQL logins active	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_only_mode,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type IN ('U', 'G')) AS windows_logins,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE PWDCOMPARE('', sl.password_hash) = 1) AS blank_sql_logins,\\n  (SELECT COUNT(*) FROM sys.sql_logins) AS total_sql_logins"}	{"condition": "windows_only_mode = 0 AND blank_sql_logins > 0 AND windows_logins > 0", "description": "Mixed mode with both Windows and blank-password SQL logins — LDAP integration incomplete"}	null	2026-02-23 20:18:31.390499
3526	postgresql	query	Check archive failure and WAL retention	{"sql": "SELECT (SELECT failed_count FROM pg_stat_archiver) AS archive_failures, (SELECT count(*) FROM pg_ls_waldir()) AS wal_on_disk, (SELECT setting FROM pg_settings WHERE name = 'wal_keep_size') AS wal_keep_size"}	{"condition": "archive_failures > 0", "description": "Archive failures combined with potential WAL recycling"}	\N	2026-02-25 00:28:52.405273
2805	sqlserver	query	Check instance login auditing level via registry	{"sql": "DECLARE @AuditLevel INT;\\nEXEC xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'Software\\\\Microsoft\\\\MSSQLServer\\\\MSSQLServer',\\n  N'AuditLevel',\\n  @AuditLevel OUTPUT;\\nSELECT @AuditLevel AS audit_level,\\n  CASE @AuditLevel\\n    WHEN 0 THEN 'NONE'\\n    WHEN 1 THEN 'SUCCESSFUL_LOGINS_ONLY'\\n    WHEN 2 THEN 'FAILED_LOGINS_ONLY'\\n    WHEN 3 THEN 'BOTH_SUCCESS_AND_FAILURE'\\n    ELSE 'UNKNOWN'\\n  END AS audit_level_desc"}	{"condition": "audit_level = 0 OR audit_level = 1", "description": "Login auditing set to NONE or SUCCESS_ONLY — failed login attempts are not logged"}	null	2026-02-23 20:18:31.390595
2645	sqlserver	query	Check for SQL Server Audit or login auditing configuration	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audits sa ON sas.audit_guid = sa.audit_guid\\n   WHERE sa.is_state_enabled = 1 AND sas.is_state_enabled = 1) AS active_audit_specs,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   JOIN sys.server_audits sa ON sas.audit_guid = sa.audit_guid\\n   WHERE sa.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('FAILED_LOGIN_GROUP', 'SUCCESSFUL_LOGIN_GROUP',\\n       'LOGIN_CHANGE_PASSWORD_GROUP', 'SERVER_PRINCIPAL_CHANGE_GROUP')) AS login_audit_actions,\\n  CAST(SERVERPROPERTY('IsIntegratedSecurityOnly') AS INT) AS windows_auth_only"}	{"condition": "active_audits = 0 OR login_audit_actions = 0", "description": "No active audit or no login-related audit actions configured — password policy violations go undetected"}	null	2026-02-23 20:18:31.390512
3527	postgresql	log_scan	Scan for WAL recycling before archive	{"pattern": "requested WAL segment.*has already been removed|WAL file.*recycled|archive.*command.*file not found", "description": "WAL segment recycled before archive could capture it"}	{"condition": "pattern_found", "description": "WAL segments lost to recycling before archiving"}	\N	2026-02-25 00:28:52.405273
2648	sqlserver	query	Check for wide variance in password ages indicating no rotation standard	{"sql": "SELECT\\n  MIN(DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), GETDATE())) AS min_password_age_days,\\n  MAX(DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), GETDATE())) AS max_password_age_days,\\n  AVG(DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), GETDATE())) AS avg_password_age_days,\\n  STDEV(DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), GETDATE())) AS stdev_password_age_days,\\n  COUNT(*) AS total_logins\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND LOGINPROPERTY(sp.name, 'PasswordLastSetTime') IS NOT NULL"}	{"condition": "max_password_age_days - min_password_age_days > 180 OR stdev_password_age_days > 90", "description": "Wide variance in password ages confirms no documented rotation policy — passwords changed ad-hoc"}	null	2026-02-23 20:18:31.390514
2651	sqlserver	query	Identify SQL Server service account and its database privileges	{"sql": "SELECT servicename, service_account, startup_type_desc, status_desc\\nFROM sys.dm_server_services\\nWHERE servicename LIKE '%SQL%'"}	{"condition": "service_account is a domain account or LocalSystem/NetworkService", "description": "SQL Server service account identified — check if it is overly privileged"}	null	2026-02-23 20:18:31.390516
2653	sqlserver	query	Check for Windows logins from external or trusted domains	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled, sp.create_date,\\n  sp.default_database_name,\\n  LEFT(sp.name, CHARINDEX('\\\\', sp.name) - 1) AS domain_name,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin\\nFROM sys.server_principals sp\\nWHERE sp.type_desc IN ('WINDOWS_LOGIN', 'WINDOWS_GROUP')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name NOT LIKE '##%'\\nORDER BY LEFT(sp.name, CHARINDEX('\\\\', sp.name) - 1), sp.name"}	{"condition": "multiple distinct domain_name values found", "description": "Logins from multiple Windows domains — trusted domain users may have unintended access"}	null	2026-02-23 20:18:31.390517
2655	sqlserver	query	Check if Force Encryption is enabled on the SQL Server instance	{"sql": "SELECT\\n  CONNECTIONPROPERTY('net_transport') AS current_transport,\\n  CONNECTIONPROPERTY('protocol_type') AS current_protocol,\\n  CONNECTIONPROPERTY('auth_scheme') AS current_auth,\\n  CONNECTIONPROPERTY('encrypt_option') AS current_encrypt,\\n  (SELECT value_in_use FROM sys.configurations WHERE name = 'remote admin connections') AS remote_dac,\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only"}	{"condition": "current_auth IN ('KERBEROS', 'NTLM')", "description": "Windows authentication is active — check if connection encryption protects the auth exchange"}	null	2026-02-23 20:18:31.390518
4046	postgresql	config_check	Check archive command and library settings	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('archive_mode', 'archive_command', 'archive_library')"}	{"condition": "archive_mode = 'on' AND (archive_command = '' OR archive_command = '/bin/true') AND (archive_library = '' OR archive_library IS NULL)", "description": "Archive mode on but command is empty or a no-op; WAL not actually archived"}	\N	2026-02-25 00:28:52.405273
2657	sqlserver	query	Enumerate all Windows logins and group by domain	{"sql": "SELECT\\n  LEFT(sp.name, CHARINDEX('\\\\', sp.name + '\\\\') - 1) AS domain_name,\\n  sp.type_desc,\\n  COUNT(*) AS login_count,\\n  SUM(CASE WHEN IS_SRVROLEMEMBER('sysadmin', sp.name) = 1 THEN 1 ELSE 0 END) AS sysadmin_count,\\n  SUM(CASE WHEN sp.is_disabled = 0 THEN 1 ELSE 0 END) AS enabled_count\\nFROM sys.server_principals sp\\nWHERE sp.type_desc IN ('WINDOWS_LOGIN', 'WINDOWS_GROUP')\\n  AND sp.name LIKE '%\\\\%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name NOT LIKE '##%'\\nGROUP BY LEFT(sp.name, CHARINDEX('\\\\', sp.name + '\\\\') - 1), sp.type_desc\\nHAVING COUNT(*) > 0\\nORDER BY domain_name"}	{"condition": "more than one distinct domain_name with enabled logins", "description": "Logins from multiple AD domains — cross-domain trust extends authentication boundary"}	null	2026-02-23 20:18:31.390519
3528	postgresql	query	Check PostgreSQL version	{"sql": "SELECT current_setting('server_version') AS version, current_setting('server_version_num')::int AS version_num"}	{"condition": "version_retrieved", "description": "Current version identified"}	\N	2026-02-25 00:28:52.405273
2658	sqlserver	query	Check cross-domain logins for high-privilege access	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  LEFT(sp.name, CHARINDEX('\\\\', sp.name + '\\\\') - 1) AS domain_name,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin,\\n  IS_SRVROLEMEMBER('securityadmin', sp.name) AS is_securityadmin,\\n  (SELECT MAX(s.login_time) FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name) AS last_session\\nFROM sys.server_principals sp\\nWHERE sp.type_desc IN ('WINDOWS_LOGIN', 'WINDOWS_GROUP')\\n  AND sp.name LIKE '%\\\\%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.is_disabled = 0\\n  AND LEFT(sp.name, CHARINDEX('\\\\', sp.name + '\\\\') - 1) <>\\n    CAST(SERVERPROPERTY('ComputerNamePhysicalNetBIOS') AS NVARCHAR(128))\\nORDER BY domain_name, sp.name"}	{"condition": "row_count > 0 — external domain logins with active sessions or elevated roles", "description": "Cross-domain logins actively accessing SQL Server — broader trust boundary than expected"}	null	2026-02-23 20:18:31.39052
2668	sqlserver	query	Check if SQL logins are used by application connections	{"sql": "SELECT s.login_name, s.program_name, s.host_name,\\n  sp.type_desc,\\n  COUNT(*) AS session_count,\\n  MAX(s.login_time) AS last_login\\nFROM sys.dm_exec_sessions s\\nJOIN sys.server_principals sp ON s.security_id = sp.sid\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND s.is_user_process = 1\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\nGROUP BY s.login_name, s.program_name, s.host_name, sp.type_desc\\nORDER BY session_count DESC"}	{"condition": "row_count > 0 with application program_name values", "description": "Applications actively connecting via SQL Authentication — mixed mode enabled for application compatibility"}	null	2026-02-23 20:18:31.390521
2659	sqlserver	query	Check for Windows auth logins without additional validation layers	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type_desc IN ('WINDOWS_LOGIN', 'WINDOWS_GROUP')\\n   AND is_disabled = 0 AND name NOT LIKE 'NT %') AS active_windows_logins,\\n  (SELECT COUNT(*) FROM sys.server_triggers\\n   WHERE parent_class_desc = 'SERVER' AND is_disabled = 0\\n   AND name LIKE '%logon%') AS active_logon_triggers,\\n  (SELECT COUNT(*) FROM sys.endpoints\\n   WHERE state_desc = 'STARTED' AND type_desc = 'TSQL'\\n   AND principal_id <> 1) AS restricted_endpoints"}	{"condition": "active_windows_logins > 5 AND active_logon_triggers = 0 AND restricted_endpoints = 0", "description": "Many Windows logins accepted with no login trigger or endpoint restriction — OS token is the only gate"}	null	2026-02-23 20:18:31.390521
2660	sqlserver	query	Check for Windows group logins with no individual auditing	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audits sa ON sas.audit_guid = sa.audit_guid\\n   WHERE sa.is_state_enabled = 1 AND sas.is_state_enabled = 1) AS active_audit_specs\\nFROM sys.server_principals sp\\nWHERE sp.type_desc = 'WINDOWS_GROUP'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name NOT LIKE 'BUILTIN\\\\%'"}	{"condition": "WINDOWS_GROUP logins exist with is_sysadmin = 1 and no active audit specifications", "description": "Windows group with sysadmin and no audit — any AD group member gets full access with no individual validation"}	null	2026-02-23 20:18:31.390522
2661	sqlserver	query	Check for absence of IP-based login restrictions	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE is_disabled = 0\\n   AND type_desc IN ('SQL_LOGIN', 'WINDOWS_LOGIN', 'WINDOWS_GROUP')\\n   AND name NOT LIKE 'NT %' AND name NOT LIKE '##%') AS active_logins,\\n  (SELECT COUNT(*) FROM sys.server_triggers\\n   WHERE parent_class_desc = 'SERVER' AND is_disabled = 0) AS server_triggers,\\n  (SELECT COUNT(*) FROM sys.endpoints\\n   WHERE state_desc = 'STARTED' AND type_desc = 'TSQL'\\n   AND is_admin_endpoint = 0) AS tsql_endpoints,\\n  (SELECT value_in_use FROM sys.configurations WHERE name = 'remote access') AS remote_access_enabled,\\n  (SELECT value_in_use FROM sys.configurations WHERE name = 'remote admin connections') AS remote_dac_enabled"}	{"condition": "active_logins > 0 AND server_triggers = 0 AND remote_access_enabled = 1", "description": "SQL Server accepts connections from any source with no logon trigger IP filtering — relying on network layer only"}	null	2026-02-23 20:18:31.390522
2663	sqlserver	query	Check for LDAP linked servers with unencrypted connections	{"sql": "SELECT ls.name, ls.product, ls.provider, ls.data_source,\\n  ls.provider_string, ls.catalog,\\n  CASE WHEN ls.data_source LIKE 'LDAP://%' THEN 'LDAP_UNENCRYPTED'\\n       WHEN ls.data_source LIKE 'LDAPS://%' THEN 'LDAPS_ENCRYPTED'\\n       WHEN ls.provider LIKE '%ADsDSOObject%' THEN 'ADSI_PROVIDER'\\n       ELSE 'OTHER' END AS ldap_security\\nFROM sys.servers ls\\nWHERE ls.is_linked = 1\\n  AND (ls.provider LIKE '%ADsDSOObject%'\\n    OR ls.data_source LIKE '%LDAP%'\\n    OR ls.product LIKE '%Active Directory%')"}	{"condition": "ldap_security = 'LDAP_UNENCRYPTED' or ADSI_PROVIDER without LDAPS", "description": "LDAP linked server using unencrypted LDAP:// — credentials and directory data sent in cleartext"}	null	2026-02-23 20:18:31.390524
2664	sqlserver	query	Check for linked server logins using stored credentials	{"sql": "SELECT ls.name AS linked_server, ls.provider, ls.data_source,\\n  ll.uses_self_credential, ll.remote_name,\\n  CASE WHEN ll.remote_name IS NOT NULL THEN 'STORED_CREDENTIAL'\\n       WHEN ll.uses_self_credential = 1 THEN 'PASSTHROUGH'\\n       ELSE 'NO_CREDENTIAL' END AS auth_mode\\nFROM sys.servers ls\\nJOIN sys.linked_logins ll ON ls.server_id = ll.server_id\\nWHERE ls.is_linked = 1\\n  AND (ls.provider LIKE '%ADsDSOObject%'\\n    OR ls.data_source LIKE '%LDAP%'\\n    OR ls.provider LIKE '%MSDASQL%')\\n  AND (ll.remote_name IS NOT NULL OR ll.uses_self_credential = 1)"}	{"condition": "auth_mode = 'STORED_CREDENTIAL' or 'PASSTHROUGH' on LDAP linked server", "description": "LDAP linked server with stored or passthrough credentials — credentials may be transmitted without encryption"}	null	2026-02-23 20:18:31.390524
2809	sqlserver	query	Check for pre-login errors in error log	{"sql": "EXEC xp_readerrorlog 0, 1, N'pre-login';\\nEXEC xp_readerrorlog 0, 1, N'SSPI';\\nEXEC xp_readerrorlog 0, 1, N'Login failed for user'"}	{"condition": "pre-login or SSPI handshake errors present but not appearing in audit", "description": "Pre-authentication failures may not reach SQL Server Audit — connection string or TLS errors fail before login event fires"}	null	2026-02-23 20:18:31.390525
2665	sqlserver	query	Check if SQL Server Audit captures Windows auth login events	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type_desc IN ('WINDOWS_LOGIN', 'WINDOWS_GROUP')\\n   AND is_disabled = 0 AND name NOT LIKE 'NT %') AS windows_logins,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   JOIN sys.server_audits sa ON sas.audit_guid = sa.audit_guid\\n   WHERE sa.is_state_enabled = 1 AND sas.is_state_enabled = 1\\n   AND sasd.audit_action_name IN (\\n     'SUCCESSFUL_LOGIN_GROUP', 'FAILED_LOGIN_GROUP',\\n     'LOGIN_CHANGE_PASSWORD_GROUP', 'SERVER_PRINCIPAL_CHANGE_GROUP'\\n   )) AS login_audit_actions"}	{"condition": "windows_logins > 0 AND login_audit_actions = 0", "description": "Windows logins exist but no SQL Server Audit captures login events"}	null	2026-02-23 20:18:31.390526
2666	sqlserver	query	Check basic login auditing configuration	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n   WHERE name = 'default trace enabled') AS default_trace_on,\\n  CASE\\n    WHEN EXISTS (SELECT 1 FROM sys.traces WHERE is_default = 1 AND status = 1) THEN 'RUNNING'\\n    ELSE 'STOPPED'\\n  END AS default_trace_status,\\n  (SELECT COUNT(*) FROM sys.dm_xe_sessions WHERE name LIKE '%login%' OR name LIKE '%audit%') AS xe_login_sessions"}	{"condition": "default_trace_on = 0 OR xe_login_sessions = 0", "description": "No login auditing via default trace or Extended Events — OS authentication events are invisible"}	null	2026-02-23 20:18:31.390526
2667	sqlserver	query	Check if Mixed Mode authentication is enabled	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  CASE WHEN CAST(SERVERPROPERTY('IsIntegratedSecurityOnly') AS INT) = 0\\n    THEN 'MIXED_MODE' ELSE 'WINDOWS_ONLY' END AS auth_mode,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.type_desc = 'SQL_LOGIN' AND sp.is_disabled = 0\\n   AND sp.name NOT LIKE '##%' AND sp.name <> 'sa') AS active_sql_logins"}	{"condition": "auth_mode = 'MIXED_MODE' AND active_sql_logins > 0", "description": "Mixed Mode authentication enabled with active SQL logins"}	null	2026-02-23 20:18:31.390527
2716	sqlserver	query	Check if SQL Agent has dormancy detection jobs	{"sql": "SELECT j.name, j.enabled, j.date_created,\\n  js.step_name, js.command\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nWHERE j.enabled = 1\\n  AND (js.command LIKE '%dormant%' OR js.command LIKE '%inactive%login%'\\n    OR js.command LIKE '%last_login%' OR js.command LIKE '%unused%account%'\\n    OR js.command LIKE '%stale%login%')"}	{"condition": "row_count = 0", "description": "No SQL Agent jobs implementing automated dormancy detection"}	null	2026-02-23 20:18:31.390527
2669	sqlserver	query	Check for Mixed Mode with multiple SQL logins mapped to separate databases	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.type_desc = 'SQL_LOGIN' AND sp.is_disabled = 0\\n   AND sp.name NOT LIKE '##%' AND sp.name <> 'sa') AS active_sql_logins,\\n  (SELECT COUNT(DISTINCT sp.default_database_name)\\n   FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.type_desc = 'SQL_LOGIN' AND sp.is_disabled = 0\\n   AND sp.name NOT LIKE '##%' AND sp.name <> 'sa'\\n   AND sp.default_database_name NOT IN ('master', 'tempdb', 'msdb', 'model')\\n  ) AS distinct_default_dbs"}	{"condition": "active_sql_logins >= 3 AND distinct_default_dbs >= 2", "description": "Multiple SQL logins mapped to different databases — multi-tenancy pattern with per-tenant credentials"}	null	2026-02-23 20:18:31.390528
4334	postgresql	log_scan	Scan logs for NULL-related errors in ETL queries	{"source": "postgresql log", "pattern": "null value in column.*violates not-null|division by zero|ERROR.*null|cannot insert NULL"}	{"condition": "matches_found > 0", "description": "NULL-related errors found indicating missing NULL handling in ETL logic"}	\N	2026-02-25 00:28:52.405273
2687	sqlserver	query	Check for Mixed Mode without Kerberos SPNs registered	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT auth_scheme FROM sys.dm_exec_connections WHERE session_id = @@SPID) AS current_auth_scheme,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections WHERE auth_scheme = 'KERBEROS' AND parent_connection_id IS NULL) AS kerberos_connections,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections WHERE auth_scheme = 'NTLM' AND parent_connection_id IS NULL) AS ntlm_connections,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections WHERE auth_scheme = 'SQL' AND parent_connection_id IS NULL) AS sql_auth_connections"}	{"condition": "windows_auth_only = 0 AND sql_auth_connections > 0 AND kerberos_connections = 0", "description": "Mixed Mode with SQL Auth and no Kerberos connections — SPNs likely not configured"}	null	2026-02-23 20:18:31.39054
2688	sqlserver	query	Check if Windows connections fall back to NTLM instead of Kerberos	{"sql": "SELECT\\n  auth_scheme,\\n  COUNT(*) AS connection_count,\\n  COUNT(DISTINCT login_name) AS distinct_logins\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND c.parent_connection_id IS NULL\\nGROUP BY auth_scheme\\nORDER BY connection_count DESC"}	{"condition": "NTLM connections present but no Kerberos — SPN misconfiguration causing NTLM fallback", "description": "Windows Auth falling back to NTLM instead of Kerberos, SQL Auth used to avoid delegation issues"}	null	2026-02-23 20:18:31.39054
2672	sqlserver	query	Check if SQL logins duplicate existing Windows logins or groups	{"sql": "SELECT sp_sql.name AS sql_login,\\n  sp_sql.create_date AS sql_created,\\n  sp_sql.is_disabled AS sql_disabled,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE login_name = sp_sql.name AND is_user_process = 1) AS active_sessions,\\n  (SELECT TOP 1 sp_win.name FROM sys.server_principals sp_win\\n   WHERE sp_win.type IN ('U', 'G')\\n     AND (sp_win.name LIKE '%' + sp_sql.name + '%' OR sp_sql.name LIKE '%' + REPLACE(PARSENAME(sp_win.name, 1), ' ', '') + '%')\\n  ) AS possible_windows_equivalent\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp_sql ON sl.principal_id = sp_sql.principal_id\\nWHERE sp_sql.is_disabled = 0\\n  AND sp_sql.name NOT LIKE '##%'\\n  AND sp_sql.name <> 'sa'"}	{"condition": "SQL logins exist that could be replaced by Windows Authentication", "description": "SQL logins in use where Windows logins could serve the same purpose — Mixed Mode unnecessary for many connections"}	null	2026-02-23 20:18:31.39053
2673	sqlserver	query	Check for Mixed Mode with stale SQL logins alongside active Windows logins	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type IN ('U', 'G') AND is_disabled = 0) AS active_windows_logins,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name <> 'sa') AS active_sql_logins"}	{"condition": "windows_auth_only = 0 AND active_windows_logins > active_sql_logins AND active_sql_logins > 0", "description": "Mixed Mode with more Windows than SQL logins — migration was started but SQL logins remain"}	null	2026-02-23 20:18:31.39053
