2682	sqlserver	query	Check for SQL logins with persistent sessions from application hosts	{"sql": "SELECT sp.name, sp.create_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE()) AS password_age_days,\\n  s.program_name, s.host_name, COUNT(*) AS session_count\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nLEFT JOIN sys.dm_exec_sessions s ON s.login_name = sp.name AND s.is_user_process = 1\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\n  AND SERVERPROPERTY('IsIntegratedSecurityOnly') = 0\\nGROUP BY sp.name, sp.create_date, sp.principal_id, sl.password_hash,\\n  s.program_name, s.host_name\\nHAVING COUNT(*) > 1 OR DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE()) > 180"}	{"condition": "SQL logins with multiple pooled sessions or very old passwords", "description": "Application connection pooling via SQL Auth with long-unchanged passwords — password in connection string"}	null	2026-02-23 20:18:31.390537
2683	sqlserver	query	Check Mixed Mode status and SQL login usage	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%') AS active_sql_logins,\\n  (SELECT COUNT(DISTINCT login_name) FROM sys.dm_exec_sessions\\n   WHERE is_user_process = 1\\n     AND login_name IN (SELECT sp.name FROM sys.sql_logins sl JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id)) AS sql_logins_with_sessions,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type IN ('U', 'G') AND is_disabled = 0) AS active_windows_logins"}	{"condition": "windows_auth_only = 0 AND sql_logins_with_sessions > 0", "description": "Mixed Mode with actively used SQL logins — no policy enforcing Windows Auth Only"}	null	2026-02-23 20:18:31.390537
4335	postgresql	query	Check source tables for high NULL ratio in key columns	{"sql": "SELECT schemaname, tablename, attname AS column_name, null_frac AS null_fraction, n_distinct FROM pg_stats WHERE null_frac > 0.1 AND schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY null_frac DESC LIMIT 30"}	{"condition": "row_count > 0", "description": "Columns with significant NULL fractions found that may break ETL transformations lacking NULL handling"}	\N	2026-02-25 00:28:52.405273
2689	sqlserver	query	Check for SQL Auth sessions from application connections	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  s.login_name, s.program_name, s.host_name,\\n  c.auth_scheme,\\n  COUNT(*) AS session_count\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND c.auth_scheme = 'SQL'\\n  AND c.parent_connection_id IS NULL\\n  AND SERVERPROPERTY('IsIntegratedSecurityOnly') = 0\\nGROUP BY s.login_name, s.program_name, s.host_name, c.auth_scheme\\nORDER BY session_count DESC"}	{"condition": "row_count > 0 with application program_names using SQL auth", "description": "Applications actively using SQL Authentication — connection strings default to SQL Auth"}	null	2026-02-23 20:18:31.390541
2916	sqlserver	query	Check if xp_cmdshell is enabled	{"sql": "SELECT name, CAST(value_in_use AS INT) AS is_enabled,\\n  description\\nFROM sys.configurations\\nWHERE name IN ('xp_cmdshell', 'Ole Automation Procedures', 'show advanced options')"}	{"condition": "xp_cmdshell or Ole Automation Procedures enabled (value_in_use = 1)", "description": "File system access features are enabled at the server level"}	null	2026-02-23 20:18:31.390541
2692	sqlserver	query	Check for SQL login creation events without audit trail	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('SERVER_PRINCIPAL_CHANGE_GROUP', 'LOGIN_CHANGE_PASSWORD_GROUP')) AS login_audit_actions,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name <> 'sa'\\n     AND DATEDIFF(DAY, sp.create_date, GETDATE()) < 90) AS recent_sql_logins"}	{"condition": "login_audit_actions = 0", "description": "No audit coverage for login creation or password changes — compliance scanning absent"}	null	2026-02-23 20:18:31.390543
3416	postgresql	query	List loaded extensions	{"sql": "SELECT e.extname, e.extversion, n.nspname AS schema FROM pg_extension e JOIN pg_namespace n ON e.extnamespace = n.oid ORDER BY e.extname"}	{"condition": "row_count > 0", "description": "Extensions are loaded — check for known leaky versions"}	\N	2026-02-25 00:28:52.405273
4053	postgresql	query	Check for backup-related connections	{"sql": "SELECT pid, usename, application_name, backend_type, state FROM pg_stat_activity WHERE application_name ~* '(barman|pgbackrest|wal-g|pg_probackup|backup)' OR backend_type = 'walsender'"}	{"condition": "row_count > 0", "description": "Third-party backup tool connections detected"}	\N	2026-02-25 00:28:52.405273
4056	postgresql	config_check	Check archive and WAL configuration	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('archive_mode', 'wal_level', 'archive_command')"}	{"condition": "archive_mode = 'off' AND wal_level = 'replica'", "description": "WAL level supports archiving but archive mode disabled — intentional cost saving"}	\N	2026-02-25 00:28:52.405273
2693	sqlserver	query	Check for logins with no recent sessions and no audit trail	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date, sp.modify_date,\\n  sp.is_disabled,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session_time,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  CASE WHEN sp.type_desc = 'SQL_LOGIN'\\n    THEN CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime)\\n    ELSE NULL END AS password_last_set\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT IN ('sa', 'BUILTIN\\\\Administrators', 'NT AUTHORITY\\\\SYSTEM', 'NT SERVICE\\\\%')\\n  AND sp.name NOT LIKE 'NT %'\\nORDER BY sp.modify_date ASC"}	{"condition": "logins with no current sessions and modify_date older than 90 days", "description": "Enabled logins with no recent activity detected — no monitoring caught these dormant accounts"}	null	2026-02-23 20:18:31.390543
2694	sqlserver	query	Check if login audit is enabled to track activity	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('SUCCESSFUL_LOGIN_GROUP', 'FAILED_LOGIN_GROUP', 'LOGIN_CHANGE_PASSWORD_GROUP')) AS login_tracking_actions,\\n  CAST(SERVERPROPERTY('IsIntegratedSecurityOnly') AS int) AS windows_auth_only"}	{"condition": "login_tracking_actions = 0", "description": "No audit specifications tracking login activity — dormant accounts cannot be detected automatically"}	null	2026-02-23 20:18:31.390544
2695	sqlserver	query	Check for enabled logins with no recent sessions and old creation dates	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date, sp.modify_date,\\n  sp.is_disabled,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session_time,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS account_age_days,\\n  CASE WHEN sp.type = 'S'\\n    THEN DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE())\\n    ELSE NULL END AS password_age_days\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name NOT IN ('sa')\\n  AND sp.name NOT LIKE '%svc%'\\n  AND sp.name NOT LIKE '%service%'\\n  AND sp.name NOT LIKE '%app%'"}	{"condition": "logins older than 365 days with no current sessions", "description": "Old user logins still enabled with no current activity — potential offboarding gaps"}	null	2026-02-23 20:18:31.390545
4337	postgresql	query	Check pg_stat_statements for failed ETL-pattern queries	{"sql": "SELECT queryid, calls, mean_exec_time, query FROM pg_stat_statements WHERE query ILIKE '%INSERT%INTO%SELECT%' OR query ILIKE '%MERGE%' OR query ILIKE '%UPDATE%FROM%' ORDER BY calls DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "ETL-pattern queries found; review for logic correctness"}	\N	2026-02-25 00:28:52.405273
2696	sqlserver	query	Check for Windows logins referencing potentially disabled AD accounts	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date, sp.modify_date,\\n  sp.is_disabled AS sql_disabled,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\n  AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\n  AND DATEDIFF(DAY, sp.modify_date, GETDATE()) > 180"}	{"condition": "enabled logins with no sessions and unmodified for > 180 days", "description": "Stale logins not cleaned up during offboarding — accounts remain enabled indefinitely"}	null	2026-02-23 20:18:31.390545
2780	sqlserver	query	Check audit on_failure behavior when space exhausted	{"sql": "SELECT sa.name, sa.on_failure_desc,\\n  CASE sa.on_failure_desc\\n    WHEN 'CONTINUE' THEN 'RISK: Audit silently stops — security gap'\\n    WHEN 'SHUTDOWN' THEN 'RISK: Server shuts down — availability impact'\\n    WHEN 'FAIL_OPERATION' THEN 'RISK: Audited operations fail — application impact'\\n  END AS risk_assessment\\nFROM sys.server_audits sa\\nWHERE sa.type_desc = 'FILE'\\n  AND sa.is_state_enabled = 1"}	{"condition": "any on_failure mode with low disk space", "description": "File system constraint will trigger on_failure behavior — all options have impact"}	null	2026-02-23 20:18:31.390579
2697	sqlserver	query	Check for service-pattern logins with stale passwords and no documentation indicators	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date, sp.modify_date,\\n  sp.is_disabled,\\n  CASE WHEN sp.type = 'S'\\n    THEN DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE())\\n    ELSE NULL END AS password_age_days,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS account_age_days\\nFROM sys.server_principals sp\\nLEFT JOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\n  AND (sp.name LIKE '%svc%' OR sp.name LIKE '%service%' OR sp.name LIKE '%app%'\\n    OR sp.name LIKE '%job%' OR sp.name LIKE '%batch%' OR sp.name LIKE '%etl%'\\n    OR sp.name LIKE '%agent%' OR sp.name LIKE '%daemon%' OR sp.name LIKE '%sys%')\\nORDER BY sp.create_date ASC"}	{"condition": "service accounts older than 365 days with passwords older than 365 days", "description": "Long-lived service accounts with stale passwords — lifecycle unknown"}	null	2026-02-23 20:18:31.390546
2698	sqlserver	query	Check if service accounts have any active connections or are orphaned	{"sql": "SELECT sp.name, sp.create_date,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS account_age_days,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE login_name = sp.name AND is_user_process = 1) AS active_sessions,\\n  (SELECT COUNT(dp.principal_id) FROM sys.database_principals dp\\n   WHERE dp.sid = sp.sid AND dp.type = 'S') AS db_user_count\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\n  AND (sp.name LIKE '%svc%' OR sp.name LIKE '%service%' OR sp.name LIKE '%app%'\\n    OR sp.name LIKE '%job%' OR sp.name LIKE '%batch%' OR sp.name LIKE '%etl%'\\n    OR sp.name LIKE '%agent%' OR sp.name LIKE '%daemon%')\\n  AND DATEDIFF(DAY, sp.create_date, GETDATE()) > 365"}	{"condition": "old service accounts with no active sessions", "description": "Service accounts with no active connections and unknown lifecycle — nobody manages these accounts"}	null	2026-02-23 20:18:31.390547
