2699	sqlserver	query	Check for contractor-pattern logins that may be stale	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date, sp.modify_date,\\n  sp.is_disabled,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS account_age_days,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  CASE WHEN sp.type = 'S'\\n    THEN DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE())\\n    ELSE NULL END AS password_age_days\\nFROM sys.server_principals sp\\nLEFT JOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND (sp.name LIKE '%contractor%' OR sp.name LIKE '%vendor%' OR sp.name LIKE '%extern%'\\n    OR sp.name LIKE '%consult%' OR sp.name LIKE '%partner%' OR sp.name LIKE '%3rd%'\\n    OR sp.name LIKE '%third%' OR sp.name LIKE '%guest%' OR sp.name LIKE '%temp_%'\\n    OR sp.name LIKE '%outsource%')"}	{"condition": "contractor-pattern accounts with account_age_days > 180 and no current sessions", "description": "Contractor accounts still enabled long after likely engagement end"}	null	2026-02-23 20:18:31.390548
2700	sqlserver	query	Check for any non-employee logins with stale access patterns	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin,\\n  (SELECT STRING_AGG(dp.name + ':' + r.name, ', ')\\n   FROM sys.database_principals dp\\n   CROSS APPLY (SELECT r.name FROM sys.database_role_members rm\\n     JOIN sys.database_principals r ON rm.role_principal_id = r.principal_id\\n     WHERE rm.member_principal_id = dp.principal_id) r\\n   WHERE dp.sid = sp.sid) AS db_roles\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\n  AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\n  AND DATEDIFF(DAY, sp.modify_date, GETDATE()) > 180"}	{"condition": "logins with no sessions and no modifications in > 180 days with database roles", "description": "Inactive logins retaining database access — potential abandoned contractor accounts without naming convention"}	null	2026-02-23 20:18:31.390548
2713	sqlserver	query	Find logins without extended properties or descriptions	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  sp.create_date, sp.modify_date, sp.is_disabled,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  CASE WHEN sp.name LIKE 'svc_%' OR sp.name LIKE 'app_%' THEN 'service_pattern'\\n       WHEN sp.name LIKE 'sa' OR sp.name LIKE '##%' THEN 'system_account'\\n       WHEN sp.type_desc = 'WINDOWS_LOGIN' THEN 'windows_login'\\n       ELSE 'unknown_ownership' END AS ownership_classification\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.principal_id > 10\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "logins classified as unknown_ownership", "description": "Active logins with no naming convention or metadata to identify the responsible owner"}	null	2026-02-23 20:18:31.390556
2706	sqlserver	query	Check for login naming inconsistency indicating ad-hoc creation	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date,\\n  sp.is_disabled,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  CASE\\n    WHEN sp.name LIKE '%svc%' OR sp.name LIKE '%service%' THEN 'service_account'\\n    WHEN sp.name LIKE '%app%' OR sp.name LIKE '%api%' OR sp.name LIKE '%web%' THEN 'application'\\n    WHEN sp.name LIKE '%test%' OR sp.name LIKE '%dev%' OR sp.name LIKE '%qa%' THEN 'dev_test'\\n    WHEN sp.name LIKE '%admin%' OR sp.name LIKE '%dba%' THEN 'admin'\\n    WHEN sp.type IN ('U', 'G') THEN 'windows_auth'\\n    ELSE 'uncategorized'\\n  END AS account_category\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\nORDER BY account_category, sp.create_date"}	{"condition": "multiple 'uncategorized' accounts or mixed naming conventions", "description": "Inconsistent login naming and uncategorizable accounts — no naming standard or inventory in place"}	null	2026-02-23 20:18:31.390552
2731	sqlserver	query	Check if security-sensitive settings differ from hardened values	{"sql": "SELECT name, CAST(value_in_use AS INT) AS current_value,\\n  CASE name\\n    WHEN 'xp_cmdshell' THEN 0\\n    WHEN 'Ole Automation Procedures' THEN 0\\n    WHEN 'clr enabled' THEN 0\\n    WHEN 'cross db ownership chaining' THEN 0\\n    WHEN 'remote admin connections' THEN 0\\n    WHEN 'remote access' THEN 0\\n    WHEN 'scan for startup procs' THEN 0\\n  END AS hardened_value\\nFROM sys.configurations\\nWHERE name IN ('xp_cmdshell', 'Ole Automation Procedures', 'clr enabled',\\n  'cross db ownership chaining', 'remote admin connections', 'remote access',\\n  'scan for startup procs')\\n  AND CAST(value_in_use AS INT) <> 0"}	{"condition": "security-sensitive settings at non-hardened values", "description": "Configuration management has left or reverted security settings to insecure state"}	null	2026-02-23 20:18:31.390566
2707	sqlserver	query	Check for SQL logins alongside Windows logins indicating mixed identity management	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type = 'S' AND is_disabled = 0 AND name NOT LIKE '##%' AND name <> 'sa') AS active_sql_logins,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type IN ('U', 'G') AND is_disabled = 0 AND name NOT LIKE 'NT %') AS active_windows_logins,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type = 'S' AND is_disabled = 0 AND name NOT LIKE '##%' AND name <> 'sa'\\n    AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sys.server_principals.name) IS NULL) AS sql_logins_no_session,\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only"}	{"condition": "active_sql_logins > 0 AND sql_logins_no_session > 0", "description": "SQL logins not tied to AD exist with some having no active sessions — no identity integration"}	null	2026-02-23 20:18:31.390553
2708	sqlserver	query	Check for potential orphaned Windows logins (AD account may be deleted)	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date, sp.modify_date,\\n  sp.is_disabled,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name NOT LIKE 'BUILTIN\\\\%'\\n  AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\n  AND DATEDIFF(DAY, sp.modify_date, GETDATE()) > 180"}	{"condition": "Windows logins with no sessions and unmodified > 180 days", "description": "Stale Windows logins may reference deleted AD accounts — no automated sync removes them"}	null	2026-02-23 20:18:31.390553
3078	sqlserver	query	Check for verbose logging trace flags	{"sql": "DBCC TRACESTATUS(-1) WITH NO_INFOMSGS"}	{"condition": "trace flags include verbose logging flags: 1204 (deadlock graph to errorlog), 1222 (deadlock info XML to errorlog), 3605 (DBCC output to errorlog), 3226 is NOT present (backup success messages NOT suppressed), 4616 (server-level metadata visibility — logging related), 7412 (lightweight query profiling infrastructure)", "description": "Verbose logging trace flags enabled — creating excessive log output under the assumption it provides security visibility"}	null	2026-02-23 20:18:31.390773
2709	sqlserver	query	Check account creation rate vs dormancy detection window	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type IN ('S', 'U', 'G') AND is_disabled = 0\\n     AND name NOT LIKE '##%' AND name NOT LIKE 'NT %') AS total_active_logins,\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type IN ('S', 'U', 'G') AND is_disabled = 0\\n     AND name NOT LIKE '##%' AND name NOT LIKE 'NT %'\\n     AND DATEDIFF(DAY, create_date, GETDATE()) < 90) AS created_last_quarter,\\n  (SELECT COUNT(*) FROM sys.server_principals sp\\n   WHERE sp.type IN ('S', 'U', 'G') AND sp.is_disabled = 0\\n     AND sp.name NOT LIKE '##%' AND sp.name NOT LIKE 'NT %'\\n     AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\n     AND DATEDIFF(DAY, sp.modify_date, GETDATE()) > 90) AS dormant_over_90_days"}	{"condition": "dormant_over_90_days > 3 or created_last_quarter > 5 with dormant accounts", "description": "Accounts going dormant between quarterly reviews — review cadence too slow for creation rate"}	null	2026-02-23 20:18:31.390554
2710	sqlserver	query	Check for accounts that were dormant before they would be caught in a quarterly review	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  CASE\\n    WHEN DATEDIFF(DAY, sp.modify_date, GETDATE()) > 180 THEN 'DORMANT_6M+'\\n    WHEN DATEDIFF(DAY, sp.modify_date, GETDATE()) > 90 THEN 'DORMANT_3-6M'\\n    WHEN DATEDIFF(DAY, sp.modify_date, GETDATE()) > 30 THEN 'DORMANT_1-3M'\\n    ELSE 'RECENT'\\n  END AS dormancy_tier\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name <> 'sa'\\n  AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\nORDER BY sp.modify_date ASC"}	{"condition": "accounts in DORMANT_3-6M or DORMANT_6M+ tiers", "description": "Accounts dormant for multiple quarters — quarterly reviews insufficient or not enforced"}	null	2026-02-23 20:18:31.390554
2712	sqlserver	query	Check if shared accounts have elevated privileges	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  (SELECT COUNT(DISTINCT s.host_name) FROM sys.dm_exec_sessions s\\n   WHERE s.login_name = sp.name AND s.is_user_process = 1) AS distinct_hosts,\\n  STRING_AGG(srm.role_principal_id, ',') AS server_role_ids,\\n  (SELECT COUNT(*) FROM sys.server_role_members rm2\\n   JOIN sys.server_principals sr ON rm2.role_principal_id = sr.principal_id\\n   WHERE rm2.member_principal_id = sp.principal_id\\n     AND sr.name IN ('sysadmin','securityadmin','serveradmin','dbcreator')) AS privileged_roles\\nFROM sys.server_principals sp\\nLEFT JOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND (SELECT COUNT(DISTINCT s.host_name) FROM sys.dm_exec_sessions s\\n       WHERE s.login_name = sp.name AND s.is_user_process = 1) > 1\\nGROUP BY sp.name, sp.type_desc, sp.principal_id"}	{"condition": "shared accounts with privileged_roles > 0", "description": "Shared service accounts hold elevated server roles — individual usage tracking impossible"}	null	2026-02-23 20:18:31.390555
3530	postgresql	log_scan	Scan for recovery after unclean shutdown	{"pattern": "database system was not properly shut down|redo starts at|incomplete startup packet|could not.*consistent recovery", "description": "Crash recovery indicators that may follow VM snapshot restore"}	{"condition": "pattern_found", "description": "Instance recovered from unclean shutdown — possible VM snapshot restore"}	\N	2026-02-25 00:28:52.405273
2715	sqlserver	query	Check for login audit trace or extended events capturing login activity	{"sql": "SELECT\\n  CASE WHEN (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n    WHERE name = 'login auditing') >= 2 THEN 1 ELSE 0 END AS login_audit_enabled,\\n  (SELECT COUNT(*) FROM sys.server_event_sessions ses\\n   JOIN sys.server_event_session_events sese ON ses.event_session_id = sese.event_session_id\\n   WHERE sese.name IN ('audit_login', 'login') AND ses.startup_state = 1) AS xe_login_sessions,\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('SUCCESSFUL_LOGIN_GROUP', 'FAILED_LOGIN_GROUP')) AS login_audit_specs"}	{"condition": "login_audit_enabled = 0 AND xe_login_sessions = 0 AND login_audit_specs = 0", "description": "No login tracking mechanism — cannot detect dormant accounts without login history"}	null	2026-02-23 20:18:31.390557
2717	sqlserver	query	Find logins with multiple server-level role memberships	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  sp.create_date, sp.is_disabled,\\n  COUNT(srm.role_principal_id) AS server_role_count,\\n  STRING_AGG(sr.name, ', ') AS server_roles\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals sr ON srm.role_principal_id = sr.principal_id\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.principal_id > 10\\nGROUP BY sp.name, sp.type_desc, sp.create_date, sp.is_disabled\\nHAVING COUNT(srm.role_principal_id) > 2\\nORDER BY server_role_count DESC"}	{"condition": "logins with more than 2 server roles", "description": "Logins with excessive server-level role accumulation"}	null	2026-02-23 20:18:31.390558
11665	mysql	query	Check for deprecated authentication plugins	{"sql": "SELECT user, host, plugin FROM mysql.user WHERE plugin = 'mysql_native_password' AND user NOT LIKE 'mysql.%';"}	{"condition": "row_count > 0", "description": "Users with deprecated mysql_native_password plugin that blocks upgrade path"}	\N	2026-03-01 06:30:58.706791
2718	sqlserver	query	Check database-level role accumulation across databases	{"sql": "DECLARE @sql NVARCHAR(MAX) = '';\\nSELECT @sql = @sql +\\n  'SELECT ''' + name + ''' AS db_name, dp.name AS user_name, dp.type_desc,\\n    COUNT(drm.role_principal_id) AS db_role_count,\\n    STRING_AGG(r.name, '','') AS db_roles\\n  FROM [' + name + '].sys.database_principals dp\\n  JOIN [' + name + '].sys.database_role_members drm ON dp.principal_id = drm.member_principal_id\\n  JOIN [' + name + '].sys.database_principals r ON drm.role_principal_id = r.principal_id\\n  WHERE dp.type IN (''S'',''U'',''G'') AND dp.principal_id > 4\\n  GROUP BY dp.name, dp.type_desc\\n  HAVING COUNT(drm.role_principal_id) > 3\\n  UNION ALL '\\nFROM sys.databases WHERE state = 0 AND database_id > 4;\\nSET @sql = LEFT(@sql, LEN(@sql) - 10) + ' ORDER BY db_role_count DESC';\\nEXEC sp_executesql @sql;"}	{"condition": "users with more than 3 database roles in any database", "description": "Users have accumulated excessive database roles — indicates privilege creep without periodic review"}	null	2026-02-23 20:18:31.390558
2798	sqlserver	query	Check for SQL Agent jobs that might ship logs externally	{"sql": "SELECT j.name AS job_name,\\n  j.enabled,\\n  js.step_name,\\n  js.command\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nWHERE j.enabled = 1\\n  AND (js.command LIKE '%audit%' OR js.command LIKE '%fn_get_audit_file%'\\n    OR js.command LIKE '%syslog%' OR js.command LIKE '%SIEM%'\\n    OR js.command LIKE '%EventLog%' OR js.command LIKE '%.sqlaudit%')"}	{"condition": "no jobs found shipping audit files remotely", "description": "No SQL Agent jobs detected for audit log shipping — logs are stranded locally"}	null	2026-02-23 20:18:31.39059
2719	sqlserver	query	Check audit configuration completeness for login tracking	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'login auditing') AS login_audit_level,\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name = 'SUCCESSFUL_LOGIN_GROUP') AS success_login_audit,\\n  (SELECT COUNT(*) FROM sys.server_event_sessions ses\\n   JOIN sys.server_event_session_events sese ON ses.event_session_id = sese.event_session_id\\n   WHERE ses.startup_state = 1\\n     AND sese.name IN ('audit_login', 'login')) AS xe_login_tracking,\\n  (SELECT COUNT(*) FROM sys.dm_xe_sessions) AS active_xe_sessions"}	{"condition": "success_login_audit = 0 AND xe_login_tracking = 0", "description": "No persistent successful login auditing — cannot build login history for dormancy analysis"}	null	2026-02-23 20:18:31.390559
2721	sqlserver	query	Count active logins with no current sessions and old password dates	{"sql": "SELECT\\n  COUNT(*) AS total_active_logins,\\n  SUM(CASE WHEN s.login_name IS NULL THEN 1 ELSE 0 END) AS logins_no_current_session,\\n  SUM(CASE WHEN DATEDIFF(DAY,\\n    COALESCE(CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS DATETIME), sp.modify_date),\\n    GETDATE()) > 180 THEN 1 ELSE 0 END) AS logins_stale_password,\\n  SUM(CASE WHEN sp.create_date < DATEADD(YEAR, -1, GETDATE()) THEN 1 ELSE 0 END) AS logins_older_than_1yr\\nFROM sys.server_principals sp\\nLEFT JOIN (SELECT DISTINCT login_name FROM sys.dm_exec_sessions WHERE is_user_process = 1) s\\n  ON s.login_name = sp.name\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.principal_id > 10\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "logins_no_current_session > total_active_logins * 0.5 or logins_stale_password > 20", "description": "Large number of potentially dormant accounts requiring review"}	null	2026-02-23 20:18:31.39056
3531	postgresql	query	Check for timeline advance indicating recovery	{"sql": "SELECT timeline_id, checkpoint_lsn FROM pg_control_checkpoint()"}	{"condition": "timeline_id > 1", "description": "Timeline advanced — server has been through recovery, possibly from VM snapshot"}	\N	2026-02-25 00:28:52.405273
2726	sqlserver	query	Check for weak passwords on SQL logins using common patterns	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  PWDCOMPARE('', sl.password_hash) AS empty_password,\\n  PWDCOMPARE(sp.name, sl.password_hash) AS password_equals_login,\\n  PWDCOMPARE('password', sl.password_hash) AS common_password_1,\\n  PWDCOMPARE('Password1', sl.password_hash) AS common_password_2,\\n  PWDCOMPARE('sqlserver', sl.password_hash) AS common_password_3\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND (PWDCOMPARE('', sl.password_hash) = 1\\n    OR PWDCOMPARE(sp.name, sl.password_hash) = 1\\n    OR PWDCOMPARE('password', sl.password_hash) = 1\\n    OR PWDCOMPARE('Password1', sl.password_hash) = 1\\n    OR PWDCOMPARE('sqlserver', sl.password_hash) = 1)"}	{"condition": "any login matching weak passwords", "description": "SQL logins with development-grade passwords in production"}	null	2026-02-23 20:18:31.390563
2727	sqlserver	query	Check remote access configuration and linked server auth	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'remote access') AS remote_access,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'remote admin connections') AS remote_dac,\\n  (SELECT COUNT(*) FROM sys.servers WHERE is_linked = 1) AS linked_server_count,\\n  (SELECT COUNT(*) FROM sys.linked_logins WHERE uses_self_credential = 1) AS self_credential_links,\\n  (SELECT COUNT(*) FROM sys.linked_logins ll\\n   JOIN sys.servers s ON ll.server_id = s.server_id\\n   WHERE ll.remote_name IS NOT NULL) AS explicit_remote_logins"}	{"condition": "linked_server_count > 0 with self_credential_links or remote_dac enabled", "description": "Remote access configured with credential passthrough or remote DAC — authentication not hardened for remote exposure"}	null	2026-02-23 20:18:31.390563
2728	sqlserver	query	Check if remote connections use encrypted channels	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'remote access') AS remote_access,\\n  CONNECTIONPROPERTY('encrypt_option') AS current_encrypt_option,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections WHERE encrypt_option = 'FALSE') AS unencrypted_connections,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections WHERE encrypt_option = 'TRUE') AS encrypted_connections,\\n  (SELECT COUNT(*) FROM sys.endpoints WHERE protocol_desc = 'TCP'\\n    AND type_desc <> 'TSQL') AS tcp_endpoints_non_default"}	{"condition": "unencrypted_connections > 0 or remote_access = 1 with no encryption", "description": "Remote connections without encryption — authentication tokens transmitted in clear text"}	null	2026-02-23 20:18:31.390565
2730	sqlserver	query	Check for recent configuration changes and agent automation	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.configurations\\n   WHERE value <> value_in_use) AS pending_config_changes,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysjobs j\\n   JOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\n   WHERE j.enabled = 1\\n     AND (js.command LIKE '%sp_configure%'\\n       OR js.command LIKE '%RECONFIGURE%'\\n       OR js.command LIKE '%ALTER LOGIN%'\\n       OR js.command LIKE '%ALTER SERVER CONFIGURATION%')) AS config_modifying_jobs,\\n  (SELECT TOP 1 t.text FROM sys.dm_exec_connections c\\n   CROSS APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) t\\n   WHERE t.text LIKE '%sp_configure%' OR t.text LIKE '%RECONFIGURE%'\\n   ORDER BY c.connect_time DESC) AS recent_config_sql"}	{"condition": "config_modifying_jobs > 0 or recent_config_sql is not null", "description": "Automated configuration management detected — may be overriding manual security hardening"}	null	2026-02-23 20:18:31.390566
4338	postgresql	log_scan	Scan PostgreSQL logs for constraint violation errors	{"source": "postgresql log", "pattern": "duplicate key value violates unique constraint|violates foreign key constraint|violates not-null constraint|violates check constraint"}	{"condition": "matches_found > 0", "description": "Constraint violation errors found during ETL target writes"}	\N	2026-02-25 00:28:52.405273
2732	sqlserver	query	Check for signs of recovery mode access or sa account manipulation	{"sql": "SELECT\\n  (SELECT is_disabled FROM sys.server_principals WHERE name = 'sa') AS sa_disabled,\\n  (SELECT LOGINPROPERTY('sa', 'PasswordLastSetTime')) AS sa_password_last_set,\\n  (SELECT modify_date FROM sys.server_principals WHERE name = 'sa') AS sa_last_modified,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'remote admin connections') AS remote_dac_enabled,\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type_desc = 'SQL_LOGIN' AND is_disabled = 0\\n     AND create_date > DATEADD(DAY, -30, GETDATE())\\n     AND name NOT LIKE '##%') AS recent_sql_logins_created"}	{"condition": "sa_disabled = 0 with recent password change, or remote_dac_enabled = 1, or recent_sql_logins_created > 0", "description": "Signs of recovery procedure usage — sa re-enabled, DAC left on, or emergency logins created"}	null	2026-02-23 20:18:31.390567
2733	sqlserver	query	Check sysadmin role membership for emergency accounts	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date,\\n  sp.modify_date, sp.is_disabled,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals sr ON srm.role_principal_id = sr.principal_id\\nWHERE sr.name = 'sysadmin'\\n  AND sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.create_date > DATEADD(YEAR, -1, GETDATE())\\nORDER BY sp.create_date DESC"}	{"condition": "recently created SQL logins with sysadmin", "description": "Emergency sysadmin accounts created during recovery and not cleaned up"}	null	2026-02-23 20:18:31.390568
2742	sqlserver	query	Check for Policy-Based Management evaluating security policies	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM msdb.dbo.syspolicy_policies WHERE is_enabled = 1) AS active_policies,\\n  (SELECT COUNT(*) FROM msdb.dbo.syspolicy_policies p\\n   JOIN msdb.dbo.syspolicy_policy_categories pc ON p.policy_category_id = pc.policy_category_id\\n   WHERE p.is_enabled = 1\\n     AND (pc.name LIKE '%security%' OR pc.name LIKE '%Surface Area%'\\n       OR p.name LIKE '%security%' OR p.name LIKE '%password%')) AS security_policies,\\n  (SELECT COUNT(*) FROM msdb.dbo.syspolicy_system_health_state\\n   WHERE result = 0) AS policy_violations"}	{"condition": "security_policies = 0", "description": "No Policy-Based Management rules enforcing security configuration — no automated drift detection"}	null	2026-02-23 20:18:31.390569
2736	sqlserver	query	Check for network exposure and multi-instance indicators	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.servers WHERE is_linked = 1) AS linked_server_count,\\n  (SELECT COUNT(*) FROM sys.endpoints WHERE protocol_desc = 'TCP'\\n    AND state_desc = 'STARTED') AS tcp_endpoints,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections WHERE net_transport = 'TCP') AS tcp_connections,\\n  (SELECT COUNT(DISTINCT c.client_net_address)\\n   FROM sys.dm_exec_connections c WHERE c.client_net_address <> '<local machine>') AS remote_clients,\\n  (SELECT COUNT(*) FROM sys.availability_replicas) AS ag_replicas,\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_only_auth"}	{"condition": "remote_clients > 0 or linked_server_count > 0 or ag_replicas > 0", "description": "Instance is networked with remote connections but may have single-node security assumptions"}	null	2026-02-23 20:18:31.39057
2737	sqlserver	query	Check if security settings match single-node assumptions	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_only_auth,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'remote admin connections') AS remote_dac,\\n  (SELECT COUNT(*) FROM sys.dm_exec_connections WHERE encrypt_option = 'FALSE'\\n    AND client_net_address <> '<local machine>') AS unencrypted_remote_connections,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type_desc = 'SQL_LOGIN'\\n    AND is_disabled = 0 AND name NOT LIKE '##%') AS active_sql_logins,\\n  (SELECT is_disabled FROM sys.server_principals WHERE name = 'sa') AS sa_disabled"}	{"condition": "unencrypted_remote_connections > 0 or (windows_only_auth = 0 AND sa_disabled = 0)", "description": "Networked instance with single-node security posture — unencrypted remote connections or lax auth for a multi-node environment"}	null	2026-02-23 20:18:31.390571
2738	sqlserver	query	Check sa account state and recent sysadmin changes	{"sql": "SELECT\\n  (SELECT name FROM sys.server_principals WHERE name = 'sa') AS sa_exists,\\n  (SELECT is_disabled FROM sys.server_principals WHERE name = 'sa') AS sa_disabled,\\n  (SELECT LOGINPROPERTY('sa', 'PasswordLastSetTime')) AS sa_password_last_set,\\n  (SELECT modify_date FROM sys.server_principals WHERE name = 'sa') AS sa_modified,\\n  (SELECT COUNT(*) FROM sys.server_principals sp\\n   JOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\n   JOIN sys.server_principals sr ON srm.role_principal_id = sr.principal_id\\n   WHERE sr.name = 'sysadmin' AND sp.type_desc = 'SQL_LOGIN'\\n     AND sp.is_disabled = 0 AND sp.name NOT LIKE '##%') AS active_sysadmin_sql_logins"}	{"condition": "sa password recently changed or multiple sysadmin SQL logins", "description": "Signs of password recovery — sa password reset or emergency sysadmin logins created"}	null	2026-02-23 20:18:31.390571
2775	sqlserver	query	Check for event log-only audit destination	{"sql": "SELECT sa.name, sa.type_desc AS destination,\\n  sa.is_state_enabled, sa.on_failure_desc,\\n  CASE\\n    WHEN sa.type_desc = 'APPLICATION_LOG' THEN 'Windows Application Log — limited retention'\\n    WHEN sa.type_desc = 'SECURITY_LOG' THEN 'Windows Security Log — requires privilege'\\n    ELSE sa.type_desc\\n  END AS retention_risk\\nFROM sys.server_audits sa\\nWHERE sa.type_desc IN ('APPLICATION_LOG', 'SECURITY_LOG')\\n  AND sa.is_state_enabled = 1"}	{"condition": "audit using APPLICATION_LOG or SECURITY_LOG destination", "description": "Audit writing to Windows Event Log — subject to event log retention policies"}	null	2026-02-23 20:18:31.390576
2776	sqlserver	query	Confirm no file-based audit as backup	{"sql": "SELECT COUNT(*) AS file_audit_count\\nFROM sys.server_audits\\nWHERE type_desc = 'FILE'\\n  AND is_state_enabled = 1"}	{"condition": "file_audit_count = 0", "description": "No file-based audit backup — event log is the only audit destination"}	null	2026-02-23 20:18:31.390577
2806	sqlserver	query	Check if SQL Server Audit captures failed logins independently	{"sql": "SELECT sas.name AS spec_name,\\n  sasd.audit_action_name\\nFROM sys.server_audit_specification_details sasd\\nJOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\nWHERE sas.is_state_enabled = 1\\n  AND sasd.audit_action_name = 'FAILED_LOGIN_GROUP'"}	{"condition": "no rows — FAILED_LOGIN_GROUP not in any active audit specification", "description": "Neither registry-level auditing nor SQL Server Audit captures failed logins — brute force attacks invisible"}	null	2026-02-23 20:18:31.390595
9967	mysql	query	Check wsrep cluster size and status	{"sql": "SHOW STATUS LIKE 'wsrep_cluster_size'"}	{"condition": "Value < expected_node_count", "description": "Cluster size smaller than expected may indicate address list divergence"}	\N	2026-03-01 06:30:58.706791
2799	sqlserver	query	Check if audit captures login events for non-repudiation	{"sql": "SELECT sas.name AS spec_name,\\n  sasd.audit_action_name,\\n  sasd.class_desc,\\n  sas.is_state_enabled\\nFROM sys.server_audit_specification_details sasd\\nJOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\nWHERE sas.is_state_enabled = 1\\n  AND sasd.audit_action_name IN (\\n    'SUCCESSFUL_LOGIN_GROUP', 'FAILED_LOGIN_GROUP',\\n    'LOGIN_CHANGE_PASSWORD_GROUP', 'AUDIT_CHANGE_GROUP',\\n    'SERVER_PRINCIPAL_IMPERSONATION_GROUP'\\n  )"}	{"condition": "missing SUCCESSFUL_LOGIN_GROUP or SERVER_PRINCIPAL_IMPERSONATION_GROUP", "description": "Non-repudiation requires tracking all logins and impersonation — gaps mean actions cannot be attributed"}	null	2026-02-23 20:18:31.390591
3389	postgresql	query	Check if deadlocks are occurring	{"sql": "SELECT datname, deadlocks FROM pg_stat_database WHERE deadlocks > 0 AND datname = current_database()"}	{"condition": "row_count > 0", "description": "Deadlocks occurring alongside long transactions"}	\N	2026-02-25 00:28:52.405273
2785	sqlserver	query	Check who can alter or disable server audits	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  perm.permission_name, perm.state_desc,\\n  (SELECT COUNT(*) FROM sys.server_role_members rm\\n   JOIN sys.server_principals sr ON rm.role_principal_id = sr.principal_id\\n   WHERE rm.member_principal_id = sp.principal_id\\n     AND sr.name = 'sysadmin') AS is_sysadmin,\\n  (SELECT COUNT(*) FROM sys.server_permissions p2\\n   WHERE p2.grantee_principal_id = sp.principal_id\\n     AND p2.permission_name IN ('ALTER ANY SERVER AUDIT', 'CONTROL SERVER')) AS audit_control_perms\\nFROM sys.server_principals sp\\nLEFT JOIN sys.server_permissions perm ON sp.principal_id = perm.grantee_principal_id\\n  AND perm.permission_name IN ('ALTER ANY SERVER AUDIT', 'CONTROL SERVER')\\nWHERE sp.is_disabled = 0\\n  AND sp.type IN ('S', 'U', 'G')\\n  AND sp.name NOT LIKE '##%'\\n  AND (\\n    EXISTS (SELECT 1 FROM sys.server_role_members rm\\n      JOIN sys.server_principals sr ON rm.role_principal_id = sr.principal_id\\n      WHERE rm.member_principal_id = sp.principal_id AND sr.name = 'sysadmin')\\n    OR EXISTS (SELECT 1 FROM sys.server_permissions p2\\n      WHERE p2.grantee_principal_id = sp.principal_id\\n        AND p2.permission_name IN ('ALTER ANY SERVER AUDIT', 'CONTROL SERVER')\\n        AND p2.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION'))\\n  )"}	{"condition": "multiple logins with ALTER ANY SERVER AUDIT or sysadmin", "description": "Multiple accounts can disable or alter auditing — any of these could manually delete audit evidence"}	null	2026-02-23 20:18:31.390582
2788	sqlserver	query	Check if non-sysadmin logins can read audit files via fn_get_audit_file	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  (SELECT COUNT(*) FROM sys.server_role_members rm\\n   JOIN sys.server_principals sr ON rm.role_principal_id = sr.principal_id\\n   WHERE rm.member_principal_id = sp.principal_id\\n     AND sr.name = 'sysadmin') AS is_sysadmin,\\n  (SELECT COUNT(*) FROM sys.server_permissions p\\n   WHERE p.grantee_principal_id = sp.principal_id\\n     AND p.permission_name = 'CONTROL SERVER'\\n     AND p.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')) AS has_control_server\\nFROM sys.server_principals sp\\nWHERE sp.is_disabled = 0\\n  AND sp.type IN ('S', 'U', 'G')\\n  AND sp.name NOT LIKE '##%'\\n  AND (\\n    EXISTS (SELECT 1 FROM sys.server_role_members rm\\n      JOIN sys.server_principals sr ON rm.role_principal_id = sr.principal_id\\n      WHERE rm.member_principal_id = sp.principal_id AND sr.name = 'sysadmin')\\n    OR EXISTS (SELECT 1 FROM sys.server_permissions p\\n      WHERE p.grantee_principal_id = sp.principal_id\\n        AND p.permission_name = 'CONTROL SERVER'\\n        AND p.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION'))\\n  )"}	{"condition": "multiple accounts with sysadmin or CONTROL SERVER can access/modify audit files", "description": "Multiple privileged accounts can access audit file paths and potentially tamper with contents"}	null	2026-02-23 20:18:31.390584
2902	sqlserver	query	Find orphaned database users across all databases	{"sql": "SELECT DB_NAME() AS database_name,\\n  dp.name AS user_name, dp.type_desc, dp.create_date,\\n  dp.sid, dp.authentication_type_desc\\nFROM sys.database_principals dp\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND dp.sid IS NOT NULL\\n  AND dp.sid <> 0x00\\n  AND LEN(dp.sid) > 0\\n  AND sp.sid IS NULL\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser')"}	{"condition": "row_count > 0", "description": "Database users exist without corresponding server logins — orphaned due to cross-database account complexity"}	null	2026-02-23 20:18:31.390585
2790	sqlserver	query	Check if sysadmin can modify audit records via fn_get_audit_file	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE type_desc = 'FILE') AS file_based_audits,\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE type_desc IN ('APPLICATION LOG', 'SECURITY LOG')) AS event_log_audits,\\n  (SELECT COUNT(DISTINCT rm.member_principal_id)\\n   FROM sys.server_role_members rm\\n   JOIN sys.server_principals sr ON rm.role_principal_id = sr.principal_id\\n   WHERE sr.name = 'sysadmin') AS sysadmin_count,\\n  CASE\\n    WHEN (SELECT COUNT(*) FROM sys.server_audits WHERE type_desc = 'FILE') > 0\\n      AND (SELECT COUNT(*) FROM sys.server_audits WHERE type_desc IN ('APPLICATION LOG', 'SECURITY LOG')) = 0\\n    THEN 'FILE_ONLY_MUTABLE'\\n    WHEN (SELECT COUNT(*) FROM sys.server_audits WHERE type_desc IN ('APPLICATION LOG', 'SECURITY LOG')) > 0\\n    THEN 'EVENT_LOG_LESS_MUTABLE'\\n    ELSE 'NO_AUDIT'\\n  END AS mutability_risk"}	{"condition": "FILE_ONLY_MUTABLE with sysadmin_count > 1", "description": "Audit records stored only in mutable files with multiple sysadmins who could tamper with them"}	null	2026-02-23 20:18:31.390585
2793	sqlserver	query	Check audit ownership and service account identity	{"sql": "SELECT a.name AS audit_name,\\n  SUSER_SNAME(a.principal_id) AS audit_owner,\\n  a.create_date, a.modify_date,\\n  (SELECT service_account FROM sys.dm_server_services\\n   WHERE servicename LIKE '%SQL Server (%' AND servicename NOT LIKE '%Agent%') AS sql_service_account,\\n  (SELECT service_account FROM sys.dm_server_services\\n   WHERE servicename LIKE '%Agent%') AS agent_service_account\\nFROM sys.server_audits a"}	{"condition": "audit owner matches or is related to SQL service account", "description": "Audit owned by the service account it is supposed to audit — conflict of interest"}	null	2026-02-23 20:18:31.390587
2854	sqlserver	query	Check for objects created by application accounts in dbo schema	{"sql": "SELECT o.type_desc, COUNT(*) AS object_count,\\n  MIN(o.create_date) AS earliest_object,\\n  MAX(o.modify_date) AS latest_modified\\nFROM sys.objects o\\nWHERE o.schema_id = SCHEMA_ID('dbo')\\n  AND o.is_ms_shipped = 0\\n  AND o.type IN ('U', 'P', 'V', 'FN', 'IF', 'TF')\\nGROUP BY o.type_desc\\nORDER BY object_count DESC"}	{"condition": "many application objects in dbo schema", "description": "Application objects in dbo schema — application was built assuming dbo ownership, cannot be easily restricted"}	null	2026-02-23 20:18:31.390625
2794	sqlserver	query	Check if service account has ALTER audit permissions	{"sql": "SELECT dss.servicename, dss.service_account,\\n  sp.principal_id,\\n  (SELECT COUNT(*) FROM sys.server_role_members rm\\n   JOIN sys.server_principals sr ON rm.role_principal_id = sr.principal_id\\n   WHERE rm.member_principal_id = sp.principal_id AND sr.name = 'sysadmin') AS is_sysadmin,\\n  (SELECT COUNT(*) FROM sys.server_permissions p\\n   WHERE p.grantee_principal_id = sp.principal_id\\n     AND p.permission_name = 'ALTER ANY SERVER AUDIT') AS has_alter_audit\\nFROM sys.dm_server_services dss\\nLEFT JOIN sys.server_principals sp ON dss.service_account = sp.name\\nWHERE dss.servicename LIKE '%SQL Server%'"}	{"condition": "service account is sysadmin or has ALTER ANY SERVER AUDIT", "description": "SQL Server service account can modify its own audit configuration — no separation of duties"}	null	2026-02-23 20:18:31.390588
