2800	sqlserver	query	Check for EXECUTE AS usage and impersonation without audit	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name = 'SERVER_PRINCIPAL_IMPERSONATION_GROUP') AS impersonation_audited,\\n  (SELECT COUNT(*) FROM sys.server_permissions\\n   WHERE permission_name = 'IMPERSONATE'\\n     AND state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')) AS impersonate_grants,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('SUCCESSFUL_LOGIN_GROUP', 'FAILED_LOGIN_GROUP')) AS login_events_audited"}	{"condition": "impersonation_audited = 0 with impersonate_grants > 0 OR login_events_audited = 0", "description": "Impersonation permitted but not audited, or login events not tracked — non-repudiation broken"}	null	2026-02-23 20:18:31.390592
2801	sqlserver	query	Find shared admin accounts with concurrent multi-host sessions	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  (SELECT COUNT(*) FROM sys.server_role_members rm\\n   JOIN sys.server_principals sr ON rm.role_principal_id = sr.principal_id\\n   WHERE rm.member_principal_id = sp.principal_id\\n     AND sr.name IN ('sysadmin', 'securityadmin', 'serveradmin')) AS privileged_roles,\\n  (SELECT COUNT(DISTINCT s.host_name) FROM sys.dm_exec_sessions s\\n   WHERE s.login_name = sp.name AND s.is_user_process = 1) AS distinct_hosts,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s\\n   WHERE s.login_name = sp.name AND s.is_user_process = 1) AS total_sessions\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members rm ON sp.principal_id = rm.member_principal_id\\nJOIN sys.server_principals sr ON rm.role_principal_id = sr.principal_id\\nWHERE sr.name IN ('sysadmin', 'securityadmin', 'serveradmin')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'"}	{"condition": "privileged logins connecting from multiple distinct hosts", "description": "Admin accounts used from multiple hosts — likely shared credentials, individual actions unattributable"}	null	2026-02-23 20:18:31.390592
2803	sqlserver	query	Check if AUDIT_CHANGE_GROUP is being monitored	{"sql": "SELECT sas.name AS spec_name,\\n  sasd.audit_action_name,\\n  sas.is_state_enabled\\nFROM sys.server_audit_specification_details sasd\\nJOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\nWHERE sasd.audit_action_name = 'AUDIT_CHANGE_GROUP'\\n  AND sas.is_state_enabled = 1"}	{"condition": "no rows — AUDIT_CHANGE_GROUP not being audited", "description": "Audit state changes are not tracked — disabling audit leaves no trace"}	null	2026-02-23 20:18:31.390593
