2808	sqlserver	query	Verify no SQL Server Audit compensating for failed login capture	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.is_state_enabled = 1 AND sasd.audit_action_name = 'FAILED_LOGIN_GROUP') AS failed_login_audited,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.is_state_enabled = 1 AND sasd.audit_action_name = 'SUCCESSFUL_LOGIN_GROUP') AS success_login_audited"}	{"condition": "failed_login_audited = 0", "description": "Failed logins not captured by either mechanism — only successes are recorded"}	null	2026-02-23 20:18:31.390596
2812	sqlserver	query	Check if registry-level auditing compensates	{"sql": "DECLARE @AuditLevel INT;\\nEXEC xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'Software\\\\Microsoft\\\\MSSQLServer\\\\MSSQLServer',\\n  N'AuditLevel',\\n  @AuditLevel OUTPUT;\\nSELECT @AuditLevel AS audit_level,\\n  CASE\\n    WHEN @AuditLevel IN (2, 3) THEN 'FAILURES_CAPTURED_VIA_REGISTRY'\\n    WHEN @AuditLevel = 1 THEN 'SUCCESS_ONLY_VIA_REGISTRY'\\n    WHEN @AuditLevel = 0 THEN 'NO_LOGIN_AUDITING'\\n    ELSE 'UNKNOWN'\\n  END AS registry_compensation"}	{"condition": "audit_level = 0 OR audit_level = 1", "description": "Neither SQL Server Audit nor registry-level auditing captures failed logins"}	null	2026-02-23 20:18:31.390598
3445	postgresql	query	Check for unexpected long I/O waits	{"sql": "SELECT wait_event_type, wait_event, count(*) AS waiting FROM pg_stat_activity WHERE wait_event_type = 'IO' AND state = 'active' GROUP BY wait_event_type, wait_event HAVING count(*) > :threshold ORDER BY waiting DESC"}	{"condition": "row_count > 0", "description": "Unexpected I/O waits may indicate external process holding file locks"}	{"threshold": 10}	2026-02-25 00:28:52.405273
2820	sqlserver	query	Check server audit specification for DDL action groups	{"sql": "SELECT sas.name AS spec_name,\\n  sasd.audit_action_name,\\n  sasd.class_desc,\\n  CASE\\n    WHEN sasd.audit_action_name LIKE '%DDL%' THEN 'DDL'\\n    WHEN sasd.audit_action_name LIKE '%LOGIN%' THEN 'LOGIN'\\n    WHEN sasd.audit_action_name LIKE '%SCHEMA%' THEN 'SCHEMA'\\n    WHEN sasd.audit_action_name LIKE '%PRINCIPAL%' THEN 'PRINCIPAL'\\n    WHEN sasd.audit_action_name LIKE '%PERMISSION%' THEN 'PERMISSION'\\n    WHEN sasd.audit_action_name LIKE '%AUDIT%' THEN 'AUDIT_META'\\n    ELSE 'OTHER'\\n  END AS action_category\\nFROM sys.server_audit_specification_details sasd\\nJOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\nWHERE sas.is_state_enabled = 1"}	{"condition": "no DDL or SCHEMA category actions present", "description": "Server audit specification has no DDL-related action groups"}	null	2026-02-23 20:18:31.390603
2822	sqlserver	query	Check server and database audit specification DDL action groups	{"sql": "SELECT sa.name AS audit_name,\\n  sas.name AS server_spec_name, sas.is_state_enabled AS server_spec_enabled,\\n  sasd.audit_action_name, sasd.class_desc\\nFROM sys.server_audits sa\\nLEFT JOIN sys.server_audit_specifications sas ON sa.audit_guid = sas.audit_guid\\nLEFT JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\nWHERE sa.is_state_enabled = 1\\n  AND sas.is_state_enabled = 1\\n  AND sasd.audit_action_name IN (\\n    'SCHEMA_OBJECT_CHANGE_GROUP', 'DATABASE_OBJECT_CHANGE_GROUP',\\n    'DATABASE_CHANGE_GROUP', 'SCHEMA_OBJECT_ACCESS_GROUP')"}	{"condition": "SCHEMA_OBJECT_CHANGE_GROUP or DATABASE_OBJECT_CHANGE_GROUP missing", "description": "DDL audit is active but missing key granular action groups for object-level DDL tracking"}	null	2026-02-23 20:18:31.390604
4353	postgresql	query	Check temporary file usage indicating memory spills	{"sql": "SELECT datname, temp_files, temp_bytes, pg_size_pretty(temp_bytes) AS temp_size, stats_reset FROM pg_stat_database WHERE datname = current_database()"}	{"condition": "temp_files > :threshold", "description": "High temp file count indicates work_mem exhaustion causing disk spills during transformations"}	{"threshold": 100}	2026-02-25 00:28:52.405273
2814	sqlserver	query	Check error log for different categories of login failures	{"sql": "CREATE TABLE #LoginErrors (LogDate DATETIME, ProcessInfo VARCHAR(50), Text NVARCHAR(MAX));\\nINSERT INTO #LoginErrors EXEC xp_readerrorlog 0, 1, N'Login failed';\\nSELECT\\n  CASE\\n    WHEN Text LIKE '%Reason: Password did not match%' THEN 'WRONG_PASSWORD'\\n    WHEN Text LIKE '%Reason: Could not find a login%' THEN 'INVALID_USER'\\n    WHEN Text LIKE '%Reason: Token-based server access validation failed%' THEN 'PERMISSIONS_ERROR'\\n    WHEN Text LIKE '%Reason: The account is disabled%' THEN 'DISABLED_ACCOUNT'\\n    WHEN Text LIKE '%Reason: Password expired%' THEN 'EXPIRED_PASSWORD'\\n    WHEN Text LIKE '%Reason: The account is locked%' THEN 'LOCKED_ACCOUNT'\\n    WHEN Text LIKE '%Reason: An error occurred%' THEN 'SYSTEM_ERROR'\\n    ELSE 'OTHER'\\n  END AS failure_category,\\n  COUNT(*) AS failure_count\\nFROM #LoginErrors\\nWHERE LogDate > DATEADD(day, -7, GETDATE())\\nGROUP BY\\n  CASE\\n    WHEN Text LIKE '%Reason: Password did not match%' THEN 'WRONG_PASSWORD'\\n    WHEN Text LIKE '%Reason: Could not find a login%' THEN 'INVALID_USER'\\n    WHEN Text LIKE '%Reason: Token-based server access validation failed%' THEN 'PERMISSIONS_ERROR'\\n    WHEN Text LIKE '%Reason: The account is disabled%' THEN 'DISABLED_ACCOUNT'\\n    WHEN Text LIKE '%Reason: Password expired%' THEN 'EXPIRED_PASSWORD'\\n    WHEN Text LIKE '%Reason: The account is locked%' THEN 'LOCKED_ACCOUNT'\\n    WHEN Text LIKE '%Reason: An error occurred%' THEN 'SYSTEM_ERROR'\\n    ELSE 'OTHER'\\n  END\\nORDER BY failure_count DESC;\\nDROP TABLE #LoginErrors"}	{"condition": "multiple failure categories present with high OTHER or SYSTEM_ERROR counts", "description": "Mixed login error types — SYSTEM_ERROR and OTHER categories may hide actual brute force attempts among configuration noise"}	null	2026-02-23 20:18:31.390599
2815	sqlserver	query	Check if audit specifications differentiate error types	{"sql": "SELECT sasd.audit_action_name,\\n  sasd.class_desc,\\n  sas.name AS spec_name\\nFROM sys.server_audit_specification_details sasd\\nJOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\nWHERE sas.is_state_enabled = 1\\n  AND sasd.audit_action_name LIKE '%LOGIN%'"}	{"condition": "only FAILED_LOGIN_GROUP present without additional granularity", "description": "Audit captures all failures as one category — no differentiation between brute force and misconfiguration"}	null	2026-02-23 20:18:31.3906
2816	sqlserver	query	Check authentication mode and audit coverage	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%') AS active_sql_logins,\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type IN ('U', 'G') AND is_disabled = 0) AS active_windows_logins,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name = 'FAILED_LOGIN_GROUP') AS failed_login_audited"}	{"condition": "windows_auth_only = 0 AND active_sql_logins > 0 AND active_windows_logins > 0", "description": "Mixed Mode with both login types active — audit must cover both authentication paths"}	null	2026-02-23 20:18:31.3906
3615	postgresql	query	Check for default and well-known accounts	{"sql": "SELECT rolname, rolsuper, rolcanlogin, rolvaliduntil, rolpassword IS NOT NULL AS has_password FROM pg_authid WHERE rolcanlogin = true AND rolname IN ('postgres', 'admin', 'root', 'dbadmin', 'replication', 'pgadmin') ORDER BY rolname"}	{"condition": "row_count > 0", "description": "Well-known account names exist — verify passwords are not defaults"}	\N	2026-02-25 00:28:52.405273
2817	sqlserver	query	Check if Windows auth failures reach SQL Server audit	{"sql": "DECLARE @AuditLevel INT;\\nEXEC xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'Software\\\\Microsoft\\\\MSSQLServer\\\\MSSQLServer',\\n  N'AuditLevel',\\n  @AuditLevel OUTPUT;\\nSELECT @AuditLevel AS audit_level,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name = 'FAILED_LOGIN_GROUP') AS sql_audit_captures_failures,\\n  CASE\\n    WHEN @AuditLevel IN (2, 3) THEN 1 ELSE 0\\n  END AS registry_captures_failures"}	{"condition": "sql_audit_captures_failures = 0 AND registry_captures_failures = 0", "description": "Neither SQL Server Audit nor registry captures Windows auth failures — Kerberos/NTLM failures invisible to SQL Server"}	null	2026-02-23 20:18:31.390601
2818	sqlserver	query	Check for rapid login failure patterns from same source	{"sql": "CREATE TABLE #RecentLogins (LogDate DATETIME, ProcessInfo VARCHAR(50), Text NVARCHAR(MAX));\\nINSERT INTO #RecentLogins EXEC xp_readerrorlog 0, 1, N'Login failed';\\nSELECT\\n  SUBSTRING(Text, CHARINDEX('[CLIENT:', Text) + 8,\\n    CHARINDEX(']', Text, CHARINDEX('[CLIENT:', Text)) - CHARINDEX('[CLIENT:', Text) - 8) AS client_ip,\\n  COUNT(*) AS failure_count,\\n  MIN(LogDate) AS first_failure,\\n  MAX(LogDate) AS last_failure,\\n  DATEDIFF(SECOND, MIN(LogDate), MAX(LogDate)) AS span_seconds\\nFROM #RecentLogins\\nWHERE LogDate > DATEADD(hour, -24, GETDATE())\\n  AND Text LIKE '%[CLIENT:%'\\nGROUP BY\\n  SUBSTRING(Text, CHARINDEX('[CLIENT:', Text) + 8,\\n    CHARINDEX(']', Text, CHARINDEX('[CLIENT:', Text)) - CHARINDEX('[CLIENT:', Text) - 8)\\nHAVING COUNT(*) > 5\\nORDER BY failure_count DESC;\\nDROP TABLE #RecentLogins"}	{"condition": "client IPs with high failure counts in short spans, or unexpectedly low failure counts from known busy app servers", "description": "Pattern analysis of login failures — app-side suppression would show fewer failures than expected for the connection volume"}	null	2026-02-23 20:18:31.390602
2819	sqlserver	query	Compare connection attempts with login failure rate	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Connection Reset/sec' AND instance_name = '') AS connection_resets,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec' AND instance_name = '') AS total_logins,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logouts/sec' AND instance_name = '') AS total_logouts,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'User Connections' AND instance_name = '') AS current_user_connections"}	{"condition": "high connection_resets relative to total_logins — apps failing and retrying internally", "description": "Connection reset pattern suggests applications catching and retrying login failures internally before SQL Server logs them"}	null	2026-02-23 20:18:31.390602
4339	postgresql	query	Check target table constraints that may be violated	{"sql": "SELECT tc.table_schema, tc.table_name, tc.constraint_name, tc.constraint_type, kcu.column_name FROM information_schema.table_constraints tc JOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name AND tc.table_schema = kcu.table_schema WHERE tc.table_schema NOT IN ('pg_catalog', 'information_schema') AND tc.constraint_type IN ('PRIMARY KEY', 'FOREIGN KEY', 'UNIQUE') ORDER BY tc.table_name, tc.constraint_type"}	{"condition": "row_count > 0", "description": "Active constraints on target tables that may reject incoming ETL data"}	\N	2026-02-25 00:28:52.405273
2823	sqlserver	query	Check database-level audit specifications for DDL coverage	{"sql": "SELECT d.name AS database_name,\\n  das.name AS db_spec_name, das.is_state_enabled,\\n  dasd.audit_action_name, dasd.class_desc,\\n  dasd.audited_result\\nFROM sys.databases d\\nCROSS APPLY (\\n  SELECT das2.name, das2.is_state_enabled, das2.database_specification_id\\n  FROM sys.database_audit_specifications das2\\n  WHERE das2.is_state_enabled = 1) das\\nCROSS APPLY (\\n  SELECT dasd2.audit_action_name, dasd2.class_desc, dasd2.audited_result\\n  FROM sys.database_audit_specification_details dasd2\\n  WHERE dasd2.database_specification_id = das.database_specification_id\\n    AND dasd2.audit_action_name IN (\\n      'SCHEMA_OBJECT_CHANGE_GROUP', 'DATABASE_OBJECT_CHANGE_GROUP',\\n      'DATABASE_ROLE_MEMBER_CHANGE_GROUP', 'SCHEMA_OBJECT_ACCESS_GROUP')) dasd\\nWHERE d.state = 0 AND d.database_id > 4"}	{"condition": "user databases without SCHEMA_OBJECT_CHANGE_GROUP in database audit specs", "description": "Database-level DDL audit specifications do not cover object-level DDL changes at sufficient granularity"}	null	2026-02-23 20:18:31.390605
3535	postgresql	query	Check for stale replication slots holding WAL	{"sql": "SELECT slot_name, active, restart_lsn, pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) AS retained_bytes, pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS retained_size FROM pg_replication_slots WHERE NOT active ORDER BY retained_bytes DESC"}	{"condition": "row_count > 0 AND retained_bytes > :threshold", "description": "Inactive replication slots holding back WAL recycling"}	{"threshold": 1073741824}	2026-02-25 00:28:52.405273
2890	sqlserver	query	Find orphaned users with old modification dates	{"sql": "SELECT dp.name AS user_name, dp.type_desc,\\n  dp.create_date, dp.modify_date,\\n  DATEDIFF(DAY, dp.modify_date, GETDATE()) AS days_orphaned_estimate,\\n  DB_NAME() AS database_name\\nFROM sys.database_principals dp\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND sp.sid IS NULL\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser')\\n  AND dp.name NOT LIKE '##%'\\n  AND dp.authentication_type <> 0\\n  AND DATEDIFF(DAY, dp.modify_date, GETDATE()) > 90"}	{"condition": "row_count > 0", "description": "Orphaned users found that have been stale for over 90 days"}	null	2026-02-23 20:18:31.390605
2824	sqlserver	query	Check if sysadmin members can bypass audit via AUDIT_CHANGE_GROUP	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name = 'AUDIT_CHANGE_GROUP') AS audit_change_monitored\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals sr ON srm.role_principal_id = sr.principal_id\\nWHERE sr.name = 'sysadmin'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "sysadmin members exist and AUDIT_CHANGE_GROUP not monitored", "description": "Sysadmin users can disable or modify audits without the change being logged"}	null	2026-02-23 20:18:31.390606
2825	sqlserver	query	Check audit on_failure configuration for sysadmin tampering resistance	{"sql": "SELECT sa.name AS audit_name,\\n  sa.on_failure_desc,\\n  sa.is_state_enabled,\\n  sa.queue_delay,\\n  (SELECT COUNT(*) FROM sys.server_audit_specification_details sasd\\n   JOIN sys.server_audit_specifications sas ON sasd.server_specification_id = sas.server_specification_id\\n   WHERE sas.audit_guid = sa.audit_guid AND sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('SCHEMA_OBJECT_CHANGE_GROUP', 'DATABASE_OBJECT_CHANGE_GROUP')) AS ddl_action_count\\nFROM sys.server_audits sa\\nWHERE sa.is_state_enabled = 1"}	{"condition": "on_failure_desc = 'CONTINUE' (not SHUTDOWN) and no AUDIT_CHANGE_GROUP tracking", "description": "Audit configured to continue on failure — sysadmin can disable audit, perform DDL, then re-enable without detection"}	null	2026-02-23 20:18:31.390607
2826	sqlserver	query	Compare DML vs DDL audit action group coverage	{"sql": "SELECT\\n  SUM(CASE WHEN sasd.audit_action_name IN ('DATABASE_OBJECT_ACCESS_GROUP', 'SCHEMA_OBJECT_ACCESS_GROUP') THEN 1 ELSE 0 END) AS dml_access_groups,\\n  SUM(CASE WHEN sasd.audit_action_name IN ('SCHEMA_OBJECT_CHANGE_GROUP', 'DATABASE_OBJECT_CHANGE_GROUP', 'DATABASE_CHANGE_GROUP') THEN 1 ELSE 0 END) AS ddl_change_groups,\\n  SUM(CASE WHEN sasd.audit_action_name IN ('SERVER_OBJECT_CHANGE_GROUP', 'SERVER_PRINCIPAL_CHANGE_GROUP') THEN 1 ELSE 0 END) AS server_change_groups\\nFROM sys.server_audit_specifications sas\\nJOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\nWHERE sas.is_state_enabled = 1"}	{"condition": "dml_access_groups > 0 AND ddl_change_groups = 0", "description": "Audit tracks data access (DML) but not schema changes (DDL) — DDL changes go unlogged"}	null	2026-02-23 20:18:31.390607
4340	postgresql	query	Check for lock waits on tables commonly used as ETL targets	{"sql": "SELECT blocked.pid AS blocked_pid, blocked.usename AS blocked_user, blocked.query AS blocked_query, blocking.pid AS blocking_pid, blocking.usename AS blocking_user, blocking.query AS blocking_query, l.relation::regclass AS locked_table FROM pg_locks l JOIN pg_stat_activity blocked ON l.pid = blocked.pid JOIN pg_locks bl ON l.relation = bl.relation AND l.pid != bl.pid JOIN pg_stat_activity blocking ON bl.pid = blocking.pid WHERE NOT l.granted"}	{"condition": "row_count > 0", "description": "Blocked processes detected waiting for locks on tables, potentially blocking ETL writes"}	\N	2026-02-25 00:28:52.405273
2839	sqlserver	query	Check for db_owner membership across databases	{"sql": "DECLARE @sql NVARCHAR(MAX) = '';\\nSELECT @sql = @sql +\\n  'SELECT ''' + name + ''' AS db_name, dp.name AS user_name, dp.type_desc\\n  FROM [' + name + '].sys.database_role_members drm\\n  JOIN [' + name + '].sys.database_principals dp ON drm.member_principal_id = dp.principal_id\\n  JOIN [' + name + '].sys.database_principals r ON drm.role_principal_id = r.principal_id\\n  WHERE r.name = ''db_owner'' AND dp.principal_id > 4 AND dp.name <> ''dbo''\\n  UNION ALL '\\nFROM sys.databases WHERE state = 0 AND database_id > 4;\\nSET @sql = LEFT(@sql, LEN(@sql) - 10) + ' ORDER BY db_name';\\nEXEC sp_executesql @sql;"}	{"condition": "non-DBA users in db_owner across multiple databases", "description": "Application users or service accounts have db_owner — full database control beyond what is needed"}	null	2026-02-23 20:18:31.390615
2827	sqlserver	query	Check database-level audit for DDL vs DML coverage gap	{"sql": "SELECT d.name AS database_name,\\n  SUM(CASE WHEN dasd.audit_action_name LIKE '%ACCESS%' THEN 1 ELSE 0 END) AS access_actions,\\n  SUM(CASE WHEN dasd.audit_action_name LIKE '%CHANGE%' THEN 1 ELSE 0 END) AS change_actions,\\n  SUM(CASE WHEN dasd.audit_action_name LIKE '%PERMISSION%' THEN 1 ELSE 0 END) AS permission_actions\\nFROM sys.databases d\\nCROSS APPLY (\\n  SELECT das2.database_specification_id\\n  FROM sys.database_audit_specifications das2\\n  WHERE das2.is_state_enabled = 1) das\\nCROSS APPLY (\\n  SELECT dasd2.audit_action_name\\n  FROM sys.database_audit_specification_details dasd2\\n  WHERE dasd2.database_specification_id = das.database_specification_id) dasd\\nWHERE d.state = 0 AND d.database_id > 4\\nGROUP BY d.name\\nHAVING SUM(CASE WHEN dasd.audit_action_name LIKE '%CHANGE%' THEN 1 ELSE 0 END) = 0"}	{"condition": "databases with access audit but no change audit actions", "description": "Database-level audit covers data access but not DDL — schema changes invisible to compliance"}	null	2026-02-23 20:18:31.390608
2829	sqlserver	query	Check if audit covers all principals including deployment service accounts	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('SCHEMA_OBJECT_CHANGE_GROUP', 'DATABASE_OBJECT_CHANGE_GROUP')\\n     AND sasd.class_desc = 'SERVER') AS server_wide_ddl_audit,\\n  (SELECT COUNT(DISTINCT dasd.audited_principal_id)\\n   FROM sys.database_audit_specifications das\\n   JOIN sys.database_audit_specification_details dasd ON das.database_specification_id = dasd.database_specification_id\\n   WHERE das.is_state_enabled = 1\\n     AND dasd.audit_action_name IN ('SCHEMA_OBJECT_CHANGE_GROUP', 'DATABASE_OBJECT_CHANGE_GROUP')\\n     AND dasd.audited_principal_id <> 0) AS principal_scoped_ddl_audit"}	{"condition": "server_wide_ddl_audit = 0 or principal_scoped_ddl_audit > 0", "description": "DDL audit is scoped to specific principals — deployment service accounts may be excluded"}	null	2026-02-23 20:18:31.390609
2830	sqlserver	query	Check if tempdb has a database audit specification for DDL	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM tempdb.sys.database_audit_specifications das\\n   WHERE das.is_state_enabled = 1) AS tempdb_audit_specs,\\n  (SELECT COUNT(*) FROM tempdb.sys.database_audit_specification_details dasd\\n   JOIN tempdb.sys.database_audit_specifications das ON dasd.database_specification_id = das.database_specification_id\\n   WHERE das.is_state_enabled = 1\\n     AND dasd.audit_action_name IN ('SCHEMA_OBJECT_CHANGE_GROUP', 'DATABASE_OBJECT_CHANGE_GROUP')) AS tempdb_ddl_audit,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name = 'SCHEMA_OBJECT_CHANGE_GROUP') AS server_ddl_audit"}	{"condition": "tempdb_ddl_audit = 0", "description": "No DDL audit on tempdb — all temporary table DDL is unlogged"}	null	2026-02-23 20:18:31.39061
2832	sqlserver	query	Check if CLR is enabled and CLR-related DDL is audited	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'clr enabled') AS clr_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'clr strict security') AS clr_strict_security,\\n  (SELECT COUNT(*) FROM sys.assemblies WHERE is_user_defined = 1) AS user_clr_assemblies,\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN ('SCHEMA_OBJECT_CHANGE_GROUP', 'DATABASE_OBJECT_CHANGE_GROUP')) AS ddl_audit_enabled"}	{"condition": "clr_enabled = 1 AND ddl_audit_enabled = 0", "description": "CLR is enabled but DDL audit does not cover assembly creation/modification"}	null	2026-02-23 20:18:31.390611
2833	sqlserver	query	Check for extended stored procedures and OLE automation	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'xp_cmdshell') AS xp_cmdshell_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'Ole Automation Procedures') AS ole_automation_enabled,\\n  (SELECT COUNT(*) FROM master.sys.extended_procedures) AS extended_procs,\\n  (SELECT COUNT(*) FROM sys.assemblies WHERE is_user_defined = 1\\n    AND permission_set_desc IN ('EXTERNAL_ACCESS', 'UNSAFE')) AS unsafe_assemblies"}	{"condition": "xp_cmdshell_enabled = 1 or ole_automation_enabled = 1 or unsafe_assemblies > 0", "description": "Extension mechanisms enabled (CLR UNSAFE, xp_cmdshell, OLE) without DDL audit — high-risk code can be deployed unlogged"}	null	2026-02-23 20:18:31.390612
2836	sqlserver	query	Check for direct permission grants to individual users vs roles	{"sql": "SELECT\\n  SUM(CASE WHEN dp.type_desc IN ('SQL_USER', 'WINDOWS_USER', 'EXTERNAL_USER') THEN 1 ELSE 0 END) AS direct_user_grants,\\n  SUM(CASE WHEN dp.type_desc = 'DATABASE_ROLE' THEN 1 ELSE 0 END) AS role_grants,\\n  COUNT(*) AS total_grants\\nFROM sys.database_permissions p\\nJOIN sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\nWHERE p.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n  AND p.class_desc <> 'DATABASE'\\n  AND dp.principal_id > 4"}	{"condition": "direct_user_grants > role_grants or direct_user_grants > 10", "description": "More permissions granted directly to users than through roles — no RBAC pattern"}	null	2026-02-23 20:18:31.390613
2837	sqlserver	query	Check for custom database roles defined for RBAC	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.database_principals\\n   WHERE type_desc = 'DATABASE_ROLE' AND is_fixed_role = 0\\n     AND principal_id > 4 AND name <> 'public') AS custom_roles,\\n  (SELECT COUNT(DISTINCT dp.name) FROM sys.database_permissions p\\n   JOIN sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\n   WHERE dp.type_desc IN ('SQL_USER', 'WINDOWS_USER', 'EXTERNAL_USER')\\n     AND p.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n     AND dp.principal_id > 4) AS users_with_direct_grants"}	{"condition": "custom_roles = 0 or users_with_direct_grants > custom_roles * 2", "description": "No custom roles defined or users overwhelmingly bypassing roles — RBAC not implemented"}	null	2026-02-23 20:18:31.390614
2838	sqlserver	query	Check for non-DBA users in sysadmin and high-privilege server roles	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  STRING_AGG(sr.name, ', ') AS server_roles,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s\\n   WHERE s.login_name = sp.name AND s.is_user_process = 1) AS active_sessions,\\n  sp.create_date\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals sr ON srm.role_principal_id = sr.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.principal_id > 10\\n  AND sr.name IN ('sysadmin', 'securityadmin', 'serveradmin', 'dbcreator')\\nGROUP BY sp.name, sp.type_desc, sp.create_date"}	{"condition": "more than 3 active logins in high-privilege server roles", "description": "Multiple logins with elevated server roles — principle of least privilege not enforced"}	null	2026-02-23 20:18:31.390615
5574	postgresql	query	Check lock_timeout configuration	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name = 'lock_timeout'"}	{"condition": "setting != '0'", "description": "Non-zero lock_timeout means transactions will be aborted after waiting too long for locks"}	\N	2026-02-25 00:28:52.405273
3080	sqlserver	query	Check for deprecated trace flags on SQL Server 2016+	{"sql": "DBCC TRACESTATUS(-1) WITH NO_INFOMSGS"}	{"condition": "trace flags include deprecated/superseded flags: 1117 (uniform auto-grow — default in 2016+), 1118 (uniform extents — default in 2016+), 2371 (auto stats threshold — default in 2016+), 4199 (QO hotfixes — use ALTER DATABASE SCOPED CONFIGURATION SET QUERY_OPTIMIZER_HOTFIXES = ON), 9481 (legacy CE — use ALTER DATABASE SCOPED CONFIGURATION SET LEGACY_CARDINALITY_ESTIMATION = ON), 2312 (new CE — default CE in 2014+), 6498 (allow big plans — enabled by default in 2019+)", "description": "Deprecated trace flags still active on a version where they are no longer needed"}	null	2026-02-23 20:18:31.390616
3536	postgresql	log_scan	Scan for incomplete backup cleanup	{"pattern": "pg_basebackup.*cancelled|backup.*aborted|backup.*interrupted|could not.*cleanup.*backup", "description": "Failed or aborted backup operations that may leave orphaned files"}	{"condition": "pattern_found", "description": "Backup operations failed without cleanup"}	\N	2026-02-25 00:28:52.405273
2840	sqlserver	query	Check for development-typical privilege patterns	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin,\\n  (SELECT COUNT(*) FROM sys.server_permissions p\\n   WHERE p.grantee_principal_id = sp.principal_id\\n     AND p.state_desc = 'GRANT'\\n     AND p.permission_name = 'CONTROL SERVER') AS has_control_server,\\n  s.program_name, s.host_name\\nFROM sys.server_principals sp\\nLEFT JOIN sys.dm_exec_sessions s ON s.login_name = sp.name AND s.is_user_process = 1\\nWHERE sp.is_disabled = 0\\n  AND sp.principal_id > 10\\n  AND sp.name NOT LIKE '##%'\\n  AND (IS_SRVROLEMEMBER('sysadmin', sp.name) = 1\\n    OR EXISTS (SELECT 1 FROM sys.server_permissions p\\n      WHERE p.grantee_principal_id = sp.principal_id\\n        AND p.permission_name = 'CONTROL SERVER'))\\n  AND s.program_name IS NOT NULL\\n  AND s.program_name NOT LIKE '%Management Studio%'\\n  AND s.program_name NOT LIKE '%SQLAgent%'"}	{"condition": "application/service connections with sysadmin or CONTROL SERVER", "description": "Non-management application sessions running with sysadmin — development privilege pattern in production"}	null	2026-02-23 20:18:31.390616
2841	sqlserver	query	Check sysadmin login activity patterns	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s\\n   WHERE s.login_name = sp.name AND s.is_user_process = 1) AS current_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests r\\n   JOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\n   WHERE s.login_name = sp.name\\n     AND r.command NOT IN ('BACKUP DATABASE', 'BACKUP LOG', 'DBCC', 'ALTER INDEX')) AS non_admin_requests\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals sr ON srm.role_principal_id = sr.principal_id\\nWHERE sr.name = 'sysadmin'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.principal_id > 10"}	{"condition": "sysadmin logins with active non-administrative requests", "description": "Sysadmin accounts being used for routine (non-admin) work — convenience override of least privilege"}	null	2026-02-23 20:18:31.390617
2842	sqlserver	query	Check for application queries running under sysadmin context	{"sql": "SELECT s.login_name, s.program_name, s.host_name,\\n  COUNT(*) AS request_count,\\n  r.command\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND IS_SRVROLEMEMBER('sysadmin', s.login_name) = 1\\n  AND r.command IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE')\\nGROUP BY s.login_name, s.program_name, s.host_name, r.command"}	{"condition": "DML commands (SELECT, INSERT, UPDATE, DELETE) running under sysadmin", "description": "Routine DML operations executed with sysadmin privileges — elevated access used for convenience"}	null	2026-02-23 20:18:31.390618
2843	sqlserver	query	Check application accounts in broad fixed database roles	{"sql": "SELECT dp.name AS user_name, dp.type_desc,\\n  STRING_AGG(r.name, ', ') AS database_roles,\\n  DB_NAME() AS database_name\\nFROM sys.database_role_members drm\\nJOIN sys.database_principals dp ON drm.member_principal_id = dp.principal_id\\nJOIN sys.database_principals r ON drm.role_principal_id = r.principal_id\\nWHERE dp.principal_id > 4\\n  AND dp.name <> 'dbo'\\n  AND r.name IN ('db_owner', 'db_ddladmin', 'db_securityadmin')\\nGROUP BY dp.name, dp.type_desc"}	{"condition": "non-DBA users in db_owner, db_ddladmin, or db_securityadmin", "description": "Application accounts have broad fixed roles instead of granular permissions"}	null	2026-02-23 20:18:31.390618
2844	sqlserver	query	Check for WITH GRANT OPTION permissions on application accounts	{"sql": "SELECT dp.name AS user_name, dp.type_desc,\\n  p.permission_name, p.state_desc,\\n  CASE p.class\\n    WHEN 0 THEN 'DATABASE'\\n    WHEN 1 THEN OBJECT_NAME(p.major_id)\\n    WHEN 3 THEN SCHEMA_NAME(p.major_id)\\n    ELSE CAST(p.class AS VARCHAR) END AS secured_object\\nFROM sys.database_permissions p\\nJOIN sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\nWHERE p.state_desc = 'GRANT_WITH_GRANT_OPTION'\\n  AND dp.principal_id > 4\\n  AND dp.name <> 'dbo'\\n  AND dp.type_desc IN ('SQL_USER', 'WINDOWS_USER', 'EXTERNAL_USER')"}	{"condition": "application users with WITH GRANT OPTION", "description": "Application accounts can delegate permissions — indicates over-provisioning without analysis"}	null	2026-02-23 20:18:31.390619
2845	sqlserver	query	Check for cross-database ownership chaining and broad schema access	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'cross db ownership chaining') AS cross_db_chaining_enabled,\\n  (SELECT COUNT(DISTINCT dp.name) FROM sys.database_permissions p\\n   JOIN sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\n   WHERE p.class = 3 AND p.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n     AND dp.principal_id > 4 AND dp.name <> 'dbo') AS users_with_schema_grants,\\n  (SELECT COUNT(DISTINCT SCHEMA_NAME(p.major_id)) FROM sys.database_permissions p\\n   JOIN sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\n   WHERE p.class = 3 AND p.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n     AND dp.principal_id > 4 AND dp.name <> 'dbo') AS schemas_granted"}	{"condition": "cross_db_chaining_enabled = 1 or schemas_granted > 3", "description": "Cross-database chaining enabled or users with access to many schemas"}	null	2026-02-23 20:18:31.39062
2846	sqlserver	query	Check for logins mapped to users in many databases	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  COUNT(DISTINCT d.name) AS database_count\\nFROM sys.server_principals sp\\nCROSS APPLY (\\n  SELECT d2.name FROM sys.databases d2\\n  WHERE d2.state = 0 AND d2.database_id > 4\\n    AND EXISTS (\\n      SELECT 1 FROM sys.server_principals sp2\\n      WHERE sp2.sid = sp.sid)) d\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.principal_id > 10\\n  AND sp.name NOT LIKE '##%'\\nGROUP BY sp.name, sp.type_desc\\nHAVING COUNT(DISTINCT d.name) > 3\\nORDER BY database_count DESC"}	{"condition": "logins mapped to more than 3 databases", "description": "Logins with cross-database presence — privileges granted to satisfy multi-database application requirements"}	null	2026-02-23 20:18:31.39062
3616	postgresql	query	Check pg_hba.conf for trust auth on default accounts	{"sql": "SELECT line_number, type, database, user_name, address, auth_method FROM pg_hba_file_rules WHERE auth_method = 'trust' AND (user_name @> ARRAY['postgres'] OR user_name @> ARRAY['all'])"}	{"condition": "row_count > 0", "description": "Default superuser accessible without password via trust authentication"}	\N	2026-02-25 00:28:52.405273
2847	sqlserver	query	Check for vendor application accounts with sysadmin or db_owner	{"sql": "SELECT s.login_name, s.program_name, s.host_name,\\n  IS_SRVROLEMEMBER('sysadmin', s.login_name) AS is_sysadmin,\\n  COUNT(*) AS session_count\\nFROM sys.dm_exec_sessions s\\nWHERE s.is_user_process = 1\\n  AND s.program_name IS NOT NULL\\n  AND s.program_name <> ''\\n  AND s.program_name NOT LIKE '%Management Studio%'\\n  AND s.program_name NOT LIKE '%SQLAgent%'\\n  AND s.program_name NOT LIKE '%Report Server%'\\n  AND IS_SRVROLEMEMBER('sysadmin', s.login_name) = 1\\nGROUP BY s.login_name, s.program_name, s.host_name"}	{"condition": "non-Microsoft application sessions with sysadmin", "description": "Third-party application accounts running with sysadmin — vendor-required over-provisioning"}	null	2026-02-23 20:18:31.390621
2849	sqlserver	query	Check for indicators of access review absence	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type IN ('S','U','G') AND is_disabled = 0 AND principal_id > 10\\n     AND name NOT LIKE '##%') AS total_active_logins,\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type IN ('S','U','G') AND is_disabled = 0 AND principal_id > 10\\n     AND name NOT LIKE '##%'\\n     AND modify_date < DATEADD(YEAR, -1, GETDATE())) AS logins_unmodified_1yr,\\n  (SELECT COUNT(*) FROM sys.server_principals sp\\n   WHERE sp.type IN ('S','U','G') AND sp.is_disabled = 0 AND sp.principal_id > 10\\n     AND sp.name NOT LIKE '##%'\\n     AND NOT EXISTS (SELECT 1 FROM sys.dm_exec_sessions s\\n       WHERE s.login_name = sp.name AND s.is_user_process = 1)) AS logins_no_current_session,\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type IN ('S','U','G') AND is_disabled = 1) AS disabled_logins"}	{"condition": "logins_unmodified_1yr > total_active_logins * 0.5 or disabled_logins = 0", "description": "Majority of logins unmodified for over a year and no disabled logins — no evidence of access reviews"}	null	2026-02-23 20:18:31.390622
2850	sqlserver	query	Check for permission change audit trail	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_audit_specifications sas\\n   JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\n   WHERE sas.is_state_enabled = 1\\n     AND sasd.audit_action_name IN (\\n       'SERVER_ROLE_MEMBER_CHANGE_GROUP', 'DATABASE_ROLE_MEMBER_CHANGE_GROUP',\\n       'SERVER_PERMISSION_CHANGE_GROUP', 'DATABASE_PERMISSION_CHANGE_GROUP',\\n       'SERVER_PRINCIPAL_CHANGE_GROUP')) AS permission_audit_specs,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysjobs j\\n   JOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\n   WHERE j.enabled = 1\\n     AND (js.command LIKE '%access review%' OR js.command LIKE '%permission%report%'\\n       OR js.command LIKE '%role member%audit%')) AS access_review_jobs"}	{"condition": "permission_audit_specs = 0 AND access_review_jobs = 0", "description": "No permission change auditing and no automated access review jobs — reviews are not being conducted"}	null	2026-02-23 20:18:31.390623
2851	sqlserver	query	Find logins with conflicting privilege combinations	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  sp.create_date, sp.modify_date,\\n  STRING_AGG(sr.name, ', ') AS server_roles,\\n  COUNT(srm.role_principal_id) AS role_count\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals sr ON srm.role_principal_id = sr.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.principal_id > 10\\n  AND sp.name NOT LIKE '##%'\\nGROUP BY sp.name, sp.type_desc, sp.create_date, sp.modify_date\\nHAVING COUNT(srm.role_principal_id) >= 2\\nORDER BY role_count DESC"}	{"condition": "logins with 2 or more server roles", "description": "Logins in multiple server roles — indicates privilege accumulation from role transitions"}	null	2026-02-23 20:18:31.390623
2852	sqlserver	query	Check for database-level privilege accumulation across multiple databases	{"sql": "DECLARE @sql NVARCHAR(MAX) = '';\\nSELECT @sql = @sql +\\n  'SELECT ''' + name + ''' AS db_name, dp.name AS user_name,\\n    STRING_AGG(r.name, '','') AS db_roles,\\n    COUNT(drm.role_principal_id) AS role_count\\n  FROM [' + name + '].sys.database_role_members drm\\n  JOIN [' + name + '].sys.database_principals dp ON drm.member_principal_id = dp.principal_id\\n  JOIN [' + name + '].sys.database_principals r ON drm.role_principal_id = r.principal_id\\n  WHERE dp.principal_id > 4 AND dp.name <> ''dbo''\\n  GROUP BY dp.name\\n  HAVING COUNT(drm.role_principal_id) >= 3\\n  UNION ALL '\\nFROM sys.databases WHERE state = 0 AND database_id > 4;\\nSET @sql = LEFT(@sql, LEN(@sql) - 10) + ' ORDER BY role_count DESC';\\nEXEC sp_executesql @sql;"}	{"condition": "users with 3+ database roles in any single database", "description": "Users accumulated multiple database roles — past role assignments not revoked after transitions"}	null	2026-02-23 20:18:31.390624
2853	sqlserver	query	Check for application users with dbo schema ownership or db_owner	{"sql": "SELECT dp.name AS user_name, dp.type_desc,\\n  dp.default_schema_name,\\n  (SELECT COUNT(*) FROM sys.database_role_members drm\\n   JOIN sys.database_principals r ON drm.role_principal_id = r.principal_id\\n   WHERE drm.member_principal_id = dp.principal_id AND r.name = 'db_owner') AS is_db_owner,\\n  (SELECT COUNT(*) FROM sys.schemas s WHERE s.principal_id = dp.principal_id) AS owned_schemas,\\n  dp.create_date\\nFROM sys.database_principals dp\\nWHERE dp.principal_id > 4\\n  AND dp.name <> 'dbo'\\n  AND dp.type_desc IN ('SQL_USER', 'WINDOWS_USER', 'EXTERNAL_USER')\\n  AND (dp.default_schema_name = 'dbo'\\n    OR EXISTS (SELECT 1 FROM sys.database_role_members drm\\n      JOIN sys.database_principals r ON drm.role_principal_id = r.principal_id\\n      WHERE drm.member_principal_id = dp.principal_id AND r.name = 'db_owner'))"}	{"condition": "application users with dbo default schema or db_owner membership", "description": "Application accounts assume dbo access — legacy privilege pattern"}	null	2026-02-23 20:18:31.390625
2869	sqlserver	query	Check rootcause grants in legacy-compat databases	{"sql": "SELECT DB_NAME() AS database_name,\\n  dp.permission_name, dp.class_desc,\\n  COALESCE(OBJECT_NAME(dp.major_id), SCHEMA_NAME(dp.major_id), '') AS object_name,\\n  COUNT(*) AS grant_count\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc IN ('OBJECT_OR_COLUMN', 'SCHEMA', 'DATABASE')\\n  AND dp.major_id > 0\\n  AND OBJECTPROPERTY(dp.major_id, 'IsMSShipped') = 0\\nGROUP BY dp.permission_name, dp.class_desc,\\n  COALESCE(OBJECT_NAME(dp.major_id), SCHEMA_NAME(dp.major_id), '')"}	{"condition": "row_count > 0", "description": "Legacy-compatibility databases have explicit PUBLIC grants on user objects — inherited from older security practices"}	null	2026-02-23 20:18:31.390626
2855	sqlserver	query	Check for common permission misconfiguration patterns	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.database_principals dp\\n   WHERE dp.type IN ('S','U','G') AND dp.sid <> 0x00\\n     AND dp.principal_id > 4\\n     AND NOT EXISTS (SELECT 1 FROM sys.server_principals sp WHERE sp.sid = dp.sid)) AS orphaned_users,\\n  (SELECT COUNT(*) FROM sys.database_permissions p\\n   WHERE p.state_desc = 'DENY'\\n     AND EXISTS (SELECT 1 FROM sys.database_permissions p2\\n       WHERE p2.grantee_principal_id = p.grantee_principal_id\\n         AND p2.major_id = p.major_id AND p2.minor_id = p.minor_id\\n         AND p2.state_desc = 'GRANT')) AS conflicting_grant_deny,\\n  (SELECT COUNT(*) FROM sys.database_principals dp\\n   JOIN sys.database_role_members drm ON dp.principal_id = drm.member_principal_id\\n   JOIN sys.database_principals r ON drm.role_principal_id = r.principal_id\\n   WHERE r.name = 'db_owner'\\n     AND EXISTS (SELECT 1 FROM sys.database_permissions p\\n       WHERE p.grantee_principal_id = dp.principal_id AND p.state_desc = 'DENY')) AS db_owner_with_deny"}	{"condition": "orphaned_users > 0 or conflicting_grant_deny > 0 or db_owner_with_deny > 0", "description": "Permission misconfigurations found — orphaned users, conflicting grants/denies, or DENY on db_owner members"}	null	2026-02-23 20:18:31.390626
4208	postgresql	query	Check snapshot conflicts on standby	{"sql": "SELECT datname, confl_snapshot FROM pg_stat_database_conflicts WHERE confl_snapshot > 0"}	{"condition": "row_count > 0 AND confl_snapshot > :threshold", "description": "Significant snapshot conflicts from VACUUM operations"}	{"threshold": 10}	2026-02-25 00:28:52.405273
2856	sqlserver	query	Check for redundant permissions indicating misunderstanding of role inheritance	{"sql": "SELECT dp.name AS user_name,\\n  r.name AS role_name,\\n  p.permission_name AS direct_grant,\\n  OBJECT_NAME(p.major_id) AS object_name\\nFROM sys.database_permissions p\\nJOIN sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\nJOIN sys.database_role_members drm ON dp.principal_id = drm.member_principal_id\\nJOIN sys.database_principals r ON drm.role_principal_id = r.principal_id\\nWHERE p.state_desc = 'GRANT'\\n  AND dp.principal_id > 4\\n  AND r.name IN ('db_datareader', 'db_datawriter', 'db_owner')\\n  AND p.permission_name IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE')\\n  AND p.class = 1"}	{"condition": "users with both role membership AND direct object grants for the same permission", "description": "Redundant permissions — user has SELECT via db_datareader AND direct SELECT on tables — indicates misunderstanding"}	null	2026-02-23 20:18:31.390627
2858	sqlserver	query	Check for default security-sensitive sp_configure settings	{"sql": "SELECT name, CAST(value_in_use AS INT) AS current_value,\\n  CASE name\\n    WHEN 'xp_cmdshell' THEN 0\\n    WHEN 'Ole Automation Procedures' THEN 0\\n    WHEN 'cross db ownership chaining' THEN 0\\n    WHEN 'clr enabled' THEN 0\\n    WHEN 'remote admin connections' THEN 0\\n    WHEN 'remote access' THEN 0\\n    WHEN 'Ad Hoc Distributed Queries' THEN 0\\n    WHEN 'scan for startup procs' THEN 0\\n  END AS hardened_value,\\n  CASE WHEN CAST(value_in_use AS INT) <> 0 THEN 'NOT_HARDENED' ELSE 'OK' END AS status\\nFROM sys.configurations\\nWHERE name IN ('xp_cmdshell', 'Ole Automation Procedures', 'cross db ownership chaining',\\n  'clr enabled', 'remote admin connections', 'remote access',\\n  'Ad Hoc Distributed Queries', 'scan for startup procs')\\n  AND CAST(value_in_use AS INT) <> 0"}	{"condition": "any security-sensitive setting at non-hardened value", "description": "Security-sensitive configurations left at defaults or intentionally enabled without documentation"}	null	2026-02-23 20:18:31.390628
2859	sqlserver	query	Check authentication method distribution and centralization	{"sql": "SELECT\\n  SUM(CASE WHEN sp.type_desc = 'SQL_LOGIN' AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS sql_logins,\\n  SUM(CASE WHEN sp.type_desc = 'WINDOWS_LOGIN' AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS windows_logins,\\n  SUM(CASE WHEN sp.type_desc = 'WINDOWS_GROUP' AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS windows_groups,\\n  SUM(CASE WHEN sp.type_desc IN ('EXTERNAL_USER', 'EXTERNAL_GROUP') AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS azure_ad_principals,\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_only_auth\\nFROM sys.server_principals sp\\nWHERE sp.principal_id > 10\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "sql_logins > windows_logins + windows_groups + azure_ad_principals", "description": "More SQL logins than Windows/Azure AD principals — authentication is not centrally governed"}	null	2026-02-23 20:18:31.390629
2860	sqlserver	query	Check for AD group-based access vs individual login-based access	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type_desc = 'WINDOWS_GROUP'\\n    AND is_disabled = 0) AS ad_groups,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type_desc = 'WINDOWS_LOGIN'\\n    AND is_disabled = 0 AND principal_id > 10) AS individual_windows_logins,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type_desc = 'SQL_LOGIN'\\n    AND is_disabled = 0 AND principal_id > 10 AND name NOT LIKE '##%') AS sql_logins,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type IN ('S','U','G')\\n    AND is_disabled = 0 AND principal_id > 10 AND name NOT LIKE '##%') AS total_principals,\\n  CASE WHEN (SELECT COUNT(*) FROM sys.server_principals WHERE type_desc = 'WINDOWS_GROUP'\\n    AND is_disabled = 0) = 0 THEN 'NO_GROUP_GOVERNANCE'\\n    ELSE 'PARTIAL_GOVERNANCE' END AS governance_status"}	{"condition": "ad_groups = 0 or sql_logins > ad_groups * 5", "description": "No AD group-based governance or SQL logins vastly outnumber governed principals"}	null	2026-02-23 20:18:31.390629
4341	postgresql	query	Check for long-running transactions holding AccessExclusive locks	{"sql": "SELECT l.pid, l.locktype, l.relation::regclass AS table_name, l.mode, a.usename, a.query, now() - a.xact_start AS transaction_duration FROM pg_locks l JOIN pg_stat_activity a ON l.pid = a.pid WHERE l.mode IN ('AccessExclusiveLock', 'ExclusiveLock', 'ShareRowExclusiveLock') AND l.granted = true AND now() - a.xact_start > interval '5 minutes'"}	{"condition": "row_count > 0", "description": "Long-running transactions holding exclusive locks on tables that ETL needs to write to"}	\N	2026-02-25 00:28:52.405273
2868	sqlserver	query	Find databases with legacy compatibility levels and rootcause grants	{"sql": "SELECT d.name AS database_name, d.compatibility_level,\\n  CASE d.compatibility_level\\n    WHEN 100 THEN '2008' WHEN 110 THEN '2012' WHEN 120 THEN '2014'\\n    WHEN 130 THEN '2016' WHEN 140 THEN '2017' WHEN 150 THEN '2019'\\n    WHEN 160 THEN '2022' ELSE 'Unknown' END AS compat_version,\\n  d.create_date\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state = 0\\n  AND d.compatibility_level < 130"}	{"condition": "row_count > 0", "description": "Databases found running at legacy compatibility levels (pre-2016)"}	null	2026-02-23 20:18:31.390635
2861	sqlserver	query	Find service/application logins with sysadmin or high-privilege roles	{"sql": "SELECT sp.name AS login_name, sp.type_desc, sp.create_date, sp.modify_date,\\n  sr.name AS role_name,\\n  sp.is_disabled,\\n  (SELECT MAX(s.login_time) FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name) AS last_session_time\\nFROM sys.server_principals sp\\nJOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id\\nJOIN sys.server_principals sr ON srm.role_principal_id = sr.principal_id\\nWHERE sr.name IN ('sysadmin', 'securityadmin', 'serveradmin', 'dbcreator')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT IN ('sa')\\n  AND (\\n    sp.name LIKE '%svc%' OR sp.name LIKE '%app%' OR sp.name LIKE '%service%'\\n    OR sp.name LIKE '%agent%' OR sp.name LIKE '%batch%' OR sp.name LIKE '%job%'\\n    OR sp.name LIKE '%api%' OR sp.name LIKE '%web%' OR sp.name LIKE '%etl%'\\n    OR sp.name LIKE '%scheduler%' OR sp.name LIKE '%daemon%'\\n  )"}	{"condition": "row_count > 0", "description": "Service or application accounts found with high-privilege server role membership"}	null	2026-02-23 20:18:31.39063
2863	sqlserver	query	Find explicit non-default grants to rootcause on user objects	{"sql": "SELECT DB_NAME() AS database_name,\\n  dp.permission_name, dp.state_desc, dp.class_desc,\\n  COALESCE(OBJECT_NAME(dp.major_id), SCHEMA_NAME(dp.major_id), '') AS object_name,\\n  dp.type AS permission_type\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc IN ('OBJECT_OR_COLUMN', 'SCHEMA', 'DATABASE', 'TYPE', 'ASSEMBLY')\\n  AND dp.major_id > 0\\n  AND OBJECTPROPERTY(dp.major_id, 'IsMSShipped') = 0"}	{"condition": "row_count > 0", "description": "Explicit grants to PUBLIC found on user-created objects — every database user inherits these permissions"}	null	2026-02-23 20:18:31.390631
3217	sqlserver	query	Check for logon trigger that validates IP addresses	{"sql": "SELECT t.name AS trigger_name, t.create_date, t.modify_date,\\n  m.definition\\nFROM sys.server_triggers t\\nJOIN sys.server_sql_modules m ON t.object_id = m.object_id\\nWHERE t.type = 'TR'\\n  AND t.parent_class_desc = 'SERVER'\\n  AND (m.definition LIKE '%EVENTDATA%' OR m.definition LIKE '%client_net_address%'\\n    OR m.definition LIKE '%CONNECTIONPROPERTY%')"}	{"condition": "row_count = 0", "description": "No logon trigger implementing IP allowlist — all IP addresses can connect"}	null	2026-02-23 20:18:31.390854
2864	sqlserver	query	Check severity — DML/EXECUTE permissions on rootcause vs read-only	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  COALESCE(OBJECT_NAME(dp.major_id), SCHEMA_NAME(dp.major_id), '') AS object_name,\\n  CASE WHEN dp.permission_name IN ('INSERT', 'UPDATE', 'DELETE', 'EXECUTE', 'ALTER', 'CONTROL')\\n    THEN 'HIGH_RISK' ELSE 'MODERATE_RISK' END AS risk_level,\\n  COUNT(*) AS grant_count\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc IN ('OBJECT_OR_COLUMN', 'SCHEMA', 'DATABASE', 'TYPE')\\n  AND dp.major_id > 0\\n  AND OBJECTPROPERTY(dp.major_id, 'IsMSShipped') = 0\\nGROUP BY dp.permission_name, dp.class_desc,\\n  COALESCE(OBJECT_NAME(dp.major_id), SCHEMA_NAME(dp.major_id), '')\\nORDER BY risk_level, dp.permission_name"}	{"condition": "any HIGH_RISK permissions found on PUBLIC", "description": "PUBLIC has write or execute permissions on user objects — critical security gap due to misunderstanding of PUBLIC scope"}	null	2026-02-23 20:18:31.390632
2937	sqlserver	query	Check xp_cmdshell and OLE Automation configuration state	{"sql": "SELECT c.name AS config_name,\\n  c.value AS config_value,\\n  c.value_in_use AS runtime_value,\\n  CASE WHEN c.value <> c.value_in_use THEN 'CONFIG_DRIFT' ELSE 'CONSISTENT' END AS drift_status\\nFROM sys.configurations c\\nWHERE c.name IN ('xp_cmdshell', 'Ole Automation Procedures', 'show advanced options', 'clr enabled', 'Ad Hoc Distributed Queries')\\nORDER BY c.name"}	{"condition": "any config has CONFIG_DRIFT or xp_cmdshell/OLE Automation enabled", "description": "File system access features enabled or configuration drift detected between stored and runtime values"}	null	2026-02-23 20:18:31.390633
2865	sqlserver	query	Find schema-wide or database-wide grants to rootcause	{"sql": "SELECT dp.permission_name, dp.state_desc, dp.class_desc,\\n  CASE dp.class_desc\\n    WHEN 'SCHEMA' THEN SCHEMA_NAME(dp.major_id)\\n    WHEN 'DATABASE' THEN DB_NAME()\\n    ELSE COALESCE(OBJECT_NAME(dp.major_id), CAST(dp.major_id AS NVARCHAR(20)))\\n  END AS scope_name,\\n  dp.type AS permission_type\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND (\\n    (dp.class_desc = 'SCHEMA' AND dp.permission_name IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE', 'EXECUTE', 'ALTER', 'CONTROL'))\\n    OR (dp.class_desc = 'DATABASE' AND dp.permission_name IN ('CONNECT', 'CREATE TABLE', 'CREATE VIEW', 'CREATE PROCEDURE', 'EXECUTE', 'ALTER ANY SCHEMA'))\\n  )"}	{"condition": "row_count > 0", "description": "Broad schema-wide or database-wide grants to PUBLIC found — typical of quick-fix troubleshooting shortcuts"}	null	2026-02-23 20:18:31.390633
2866	sqlserver	query	Find rootcause grants on user objects with object creation date context	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  OBJECT_NAME(dp.major_id) AS object_name,\\n  o.create_date AS object_created,\\n  o.modify_date AS object_modified,\\n  DATEDIFF(DAY, o.modify_date, GETDATE()) AS days_since_object_modified\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc = 'OBJECT_OR_COLUMN'\\n  AND o.is_ms_shipped = 0\\n  AND dp.permission_name IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE', 'EXECUTE')"}	{"condition": "row_count > 0", "description": "PUBLIC has explicit DML/EXECUTE permissions on user objects"}	null	2026-02-23 20:18:31.390634
2867	sqlserver	query	Check if any granted objects are rarely accessed — stale workaround indicator	{"sql": "SELECT OBJECT_NAME(dp.major_id) AS object_name,\\n  dp.permission_name,\\n  o.create_date,\\n  COALESCE(ius.last_user_seek, ius.last_user_scan, ius.last_user_lookup, '1900-01-01') AS last_accessed,\\n  DATEDIFF(DAY,\\n    COALESCE(ius.last_user_seek, ius.last_user_scan, ius.last_user_lookup, o.create_date),\\n    GETDATE()) AS days_since_last_access\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nLEFT JOIN sys.dm_db_index_usage_stats ius ON o.object_id = ius.object_id AND ius.database_id = DB_ID()\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc = 'OBJECT_OR_COLUMN'\\n  AND o.is_ms_shipped = 0\\n  AND dp.permission_name IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE', 'EXECUTE')\\nORDER BY days_since_last_access DESC"}	{"condition": "rows with days_since_last_access > 90", "description": "PUBLIC-granted objects have not been accessed in over 90 days — strong indicator of temporary workaround that was never cleaned up"}	null	2026-02-23 20:18:31.390634
2870	sqlserver	query	Check if permission change auditing covers rootcause role modifications	{"sql": "SELECT sa.name AS audit_name,\\n  sas.name AS spec_name, sas.is_state_enabled,\\n  sasd.audit_action_name\\nFROM sys.server_audits sa\\nLEFT JOIN sys.server_audit_specifications sas ON sa.audit_guid = sas.audit_guid\\nLEFT JOIN sys.server_audit_specification_details sasd ON sas.server_specification_id = sasd.server_specification_id\\nWHERE sa.is_state_enabled = 1\\n  AND sas.is_state_enabled = 1\\n  AND sasd.audit_action_name IN (\\n    'DATABASE_PERMISSION_CHANGE_GROUP', 'SCHEMA_OBJECT_PERMISSION_CHANGE_GROUP',\\n    'SERVER_PERMISSION_CHANGE_GROUP', 'DATABASE_ROLE_MEMBER_CHANGE_GROUP')"}	{"condition": "row_count = 0 or DATABASE_PERMISSION_CHANGE_GROUP missing", "description": "No audit trail for permission changes — grants to PUBLIC will go undetected"}	null	2026-02-23 20:18:31.390636
2871	sqlserver	query	Check if rootcause already has excessive grants without audit coverage	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  COALESCE(OBJECT_NAME(dp.major_id), SCHEMA_NAME(dp.major_id), '') AS object_name,\\n  COUNT(*) AS grant_count\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc IN ('OBJECT_OR_COLUMN', 'SCHEMA')\\n  AND dp.major_id > 0\\n  AND OBJECTPROPERTY(dp.major_id, 'IsMSShipped') = 0\\nGROUP BY dp.permission_name, dp.class_desc,\\n  COALESCE(OBJECT_NAME(dp.major_id), SCHEMA_NAME(dp.major_id), '')"}	{"condition": "row_count > 0", "description": "PUBLIC already has non-default grants and no audit trail exists to track how they got there"}	null	2026-02-23 20:18:31.390636
2872	sqlserver	query	Check rootcause permissions on system objects beyond standard defaults	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  OBJECT_SCHEMA_NAME(dp.major_id) AS schema_name,\\n  OBJECT_NAME(dp.major_id) AS object_name,\\n  o.type_desc\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND o.is_ms_shipped = 1\\n  AND dp.permission_name IN ('VIEW DEFINITION', 'SELECT', 'EXECUTE')\\n  AND OBJECT_SCHEMA_NAME(dp.major_id) NOT IN ('sys', 'INFORMATION_SCHEMA')"}	{"condition": "row_count > 0", "description": "PUBLIC has view/execute permissions on system objects outside sys/INFORMATION_SCHEMA — potential information disclosure"}	null	2026-02-23 20:18:31.390637
4060	postgresql	query	Check replication lag in time domain	{"sql": "SELECT client_addr, write_lag, flush_lag, replay_lag FROM pg_stat_replication WHERE replay_lag > interval ':lag_seconds seconds'"}	{"condition": "row_count > 0", "description": "Time-based lag exceeding threshold confirms network-related delays"}	{"lag_seconds": 30}	2026-02-25 00:28:52.405273
2876	sqlserver	query	Check for dev/test-style rootcause grants in production databases	{"sql": "SELECT DB_NAME() AS database_name,\\n  dp.permission_name, dp.class_desc,\\n  CASE dp.class_desc\\n    WHEN 'SCHEMA' THEN SCHEMA_NAME(dp.major_id)\\n    WHEN 'OBJECT_OR_COLUMN' THEN OBJECT_NAME(dp.major_id)\\n    WHEN 'DATABASE' THEN DB_NAME()\\n    ELSE '' END AS scope,\\n  COUNT(*) AS grant_count\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc IN ('OBJECT_OR_COLUMN', 'SCHEMA', 'DATABASE')\\n  AND dp.permission_name IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE', 'EXECUTE', 'ALTER', 'CONTROL')\\n  AND (dp.major_id = 0 OR OBJECTPROPERTY(dp.major_id, 'IsMSShipped') = 0)\\nGROUP BY dp.permission_name, dp.class_desc,\\n  CASE dp.class_desc\\n    WHEN 'SCHEMA' THEN SCHEMA_NAME(dp.major_id)\\n    WHEN 'OBJECT_OR_COLUMN' THEN OBJECT_NAME(dp.major_id)\\n    WHEN 'DATABASE' THEN DB_NAME()\\n    ELSE '' END\\nHAVING COUNT(*) >= 1"}	{"condition": "row_count >= 5", "description": "Large number of PUBLIC grants found — consistent with dev/test configuration pattern"}	null	2026-02-23 20:18:31.390639
2893	sqlserver	query	Assess proportion of SQL-auth logins vs Windows-auth on server	{"sql": "SELECT\\n  SUM(CASE WHEN sp.type = 'S' THEN 1 ELSE 0 END) AS sql_logins,\\n  SUM(CASE WHEN sp.type = 'U' THEN 1 ELSE 0 END) AS windows_logins,\\n  SUM(CASE WHEN sp.type = 'G' THEN 1 ELSE 0 END) AS windows_groups,\\n  COUNT(*) AS total_logins,\\n  CAST(SUM(CASE WHEN sp.type = 'S' THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0) AS DECIMAL(5,1)) AS pct_sql_auth\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT IN ('sa')\\n  AND sp.is_disabled = 0"}	{"condition": "pct_sql_auth > 30", "description": "Over 30% of active logins use SQL authentication — these cannot be automatically deprovisioned via HR-triggered AD changes"}	null	2026-02-23 20:18:31.39064
2884	sqlserver	query	Find recently modified objects with rootcause grants indicating emergency changes	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  OBJECT_SCHEMA_NAME(dp.major_id) AS schema_name,\\n  OBJECT_NAME(dp.major_id) AS object_name,\\n  o.modify_date,\\n  DATEDIFF(DAY, o.modify_date, GETDATE()) AS days_since_modified\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND o.is_ms_shipped = 0\\n  AND dp.permission_name IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE', 'EXECUTE', 'ALTER', 'CONTROL')"}	{"condition": "row_count > 0", "description": "PUBLIC has DML/DDL grants on user objects"}	null	2026-02-23 20:18:31.390646
2878	sqlserver	query	Check for uniform rootcause grants across many objects of same type	{"sql": "SELECT dp.permission_name, o.type_desc,\\n  COUNT(*) AS objects_with_grant,\\n  (SELECT COUNT(*) FROM sys.objects o2 WHERE o2.type = o.type AND o2.is_ms_shipped = 0) AS total_objects_of_type,\\n  CAST(COUNT(*) * 100.0 / NULLIF((SELECT COUNT(*) FROM sys.objects o2 WHERE o2.type = o.type AND o2.is_ms_shipped = 0), 0) AS DECIMAL(5,1)) AS pct_covered\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc = 'OBJECT_OR_COLUMN'\\n  AND o.is_ms_shipped = 0\\n  AND dp.permission_name IN ('SELECT', 'INSERT', 'UPDATE', 'DELETE', 'EXECUTE')\\nGROUP BY dp.permission_name, o.type_desc, o.type\\nHAVING COUNT(*) >= 5"}	{"condition": "pct_covered >= 50 for any permission/type combination", "description": "PUBLIC has the same permission on 50%+ of objects of one type — hallmark of bulk GRANT script"}	null	2026-02-23 20:18:31.390641
2886	sqlserver	query	Find orphaned database users without server logins	{"sql": "SELECT dp.name AS user_name, dp.type_desc, dp.sid,\\n  dp.create_date, dp.modify_date,\\n  dp.authentication_type_desc,\\n  DB_NAME() AS database_name\\nFROM sys.database_principals dp\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND sp.sid IS NULL\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser')\\n  AND dp.name NOT LIKE '##%'\\n  AND dp.authentication_type <> 0"}	{"condition": "row_count > 0", "description": "Orphaned database users found — server login deleted but database user remains"}	null	2026-02-23 20:18:31.390647
2895	sqlserver	query	Check for logins that have never established a session (never used)	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  sp.create_date, sp.modify_date,\\n  sp.is_disabled,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS days_since_created,\\n  (SELECT MAX(s.login_time) FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name) AS last_session_time\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT IN ('sa')\\n  AND sp.is_disabled = 0\\n  AND NOT EXISTS (\\n    SELECT 1 FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name\\n  )\\n  AND DATEDIFF(DAY, sp.create_date, GETDATE()) > 30"}	{"condition": "row_count > 0", "description": "Active logins created over 30 days ago with no current sessions — likely unused accounts that reconciliation would catch"}	null	2026-02-23 20:18:31.390651
2879	sqlserver	query	Check for rootcause grants without custom role alternatives	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.database_permissions dp\\n   JOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\n   WHERE pr.name = 'public' AND dp.state_desc = 'GRANT'\\n   AND dp.class_desc IN ('OBJECT_OR_COLUMN', 'SCHEMA')\\n   AND dp.major_id > 0 AND OBJECTPROPERTY(dp.major_id, 'IsMSShipped') = 0) AS public_user_grants,\\n  (SELECT COUNT(*) FROM sys.database_principals\\n   WHERE type = 'R' AND is_fixed_role = 0\\n   AND name NOT IN ('public', 'dbo', 'guest', 'INFORMATION_SCHEMA', 'sys')) AS custom_roles,\\n  (SELECT COUNT(*) FROM sys.database_permissions dp\\n   JOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\n   WHERE pr.type = 'R' AND pr.is_fixed_role = 0\\n   AND pr.name NOT IN ('public', 'dbo')\\n   AND dp.state_desc = 'GRANT'\\n   AND dp.class_desc IN ('OBJECT_OR_COLUMN', 'SCHEMA')) AS custom_role_grants"}	{"condition": "public_user_grants > 0 AND (custom_roles = 0 OR custom_role_grants = 0)", "description": "PUBLIC has explicit grants but no custom roles exist or custom roles have no grants — no role-based alternative is implemented"}	null	2026-02-23 20:18:31.390642
2880	sqlserver	query	Check for mixed GRANT and DENY on rootcause indicating incomplete revocation	{"sql": "SELECT dp.permission_name, dp.state_desc,\\n  dp.class_desc,\\n  COUNT(*) AS permission_count\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.class_desc IN ('OBJECT_OR_COLUMN', 'SCHEMA', 'DATABASE')\\n  AND dp.state_desc IN ('GRANT', 'DENY')\\n  AND dp.major_id > 0\\nGROUP BY dp.permission_name, dp.state_desc, dp.class_desc\\nORDER BY dp.permission_name, dp.state_desc"}	{"condition": "same permission_name has both GRANT and DENY rows", "description": "Mixed GRANT and DENY for same permission type on PUBLIC — partial revocation in progress or incomplete"}	null	2026-02-23 20:18:31.390643
4210	postgresql	query	Check snapshot and bufferpin conflicts	{"sql": "SELECT datname, confl_snapshot, confl_bufferpin FROM pg_stat_database_conflicts WHERE confl_snapshot > 0 OR confl_bufferpin > 0"}	{"condition": "confl_bufferpin > 0", "description": "Buffer pin conflicts indicate HOT chain pruning issues"}	\N	2026-02-25 00:28:52.405273
2881	sqlserver	query	Identify specific objects still granted to rootcause alongside denied objects	{"sql": "SELECT 'STILL_GRANTED' AS status, dp.permission_name,\\n  OBJECT_SCHEMA_NAME(dp.major_id) + '.' + OBJECT_NAME(dp.major_id) AS object_name,\\n  o.type_desc\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.class_desc = 'OBJECT_OR_COLUMN'\\n  AND o.is_ms_shipped = 0\\n  AND dp.permission_name IN (\\n    SELECT dp2.permission_name FROM sys.database_permissions dp2\\n    JOIN sys.database_principals pr2 ON dp2.grantee_principal_id = pr2.principal_id\\n    WHERE pr2.name = 'public' AND dp2.state_desc = 'DENY'\\n    AND dp2.class_desc = 'OBJECT_OR_COLUMN')\\nORDER BY dp.permission_name, object_name"}	{"condition": "row_count > 0", "description": "Some objects are still granted to PUBLIC while the same permission is denied on other objects — revocation was not completed for all objects"}	null	2026-02-23 20:18:31.390643
2997	sqlserver	query	Check for legacy compatibility indicators	{"sql": "SELECT d.name AS database_name, d.compatibility_level,\\n  d.create_date,\\n  DATEDIFF(YEAR, d.create_date, GETDATE()) AS age_years\\nFROM sys.databases d\\nWHERE d.state = 0\\n  AND d.database_id > 4\\n  AND (d.compatibility_level < 130 OR DATEDIFF(YEAR, d.create_date, GETDATE()) > 5)\\nORDER BY d.compatibility_level ASC"}	{"condition": "row_count > 0", "description": "Legacy databases with old compatibility levels — xp_cmdshell usage likely rooted in legacy application requirements"}	null	2026-02-23 20:18:31.390644
2882	sqlserver	query	Find rootcause EXECUTE grants on stored procedures and functions	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  OBJECT_SCHEMA_NAME(dp.major_id) AS schema_name,\\n  OBJECT_NAME(dp.major_id) AS object_name,\\n  o.type_desc,\\n  CASE\\n    WHEN OBJECT_NAME(dp.major_id) LIKE '%report%' THEN 'reporting-tool'\\n    WHEN OBJECT_NAME(dp.major_id) LIKE '%monitor%' THEN 'monitoring-tool'\\n    WHEN OBJECT_SCHEMA_NAME(dp.major_id) NOT IN ('dbo', 'sys') THEN 'vendor-schema'\\n    ELSE 'application' END AS likely_source\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.permission_name = 'EXECUTE'\\n  AND o.is_ms_shipped = 0\\n  AND o.type IN ('P', 'FN', 'IF', 'TF')"}	{"condition": "row_count > 0", "description": "PUBLIC has EXECUTE grants on stored procedures/functions — often added per vendor/tool installation guides"}	null	2026-02-23 20:18:31.390644
2883	sqlserver	query	Check if granted procedures access sensitive data or system functions	{"sql": "SELECT OBJECT_SCHEMA_NAME(dp.major_id) AS schema_name,\\n  OBJECT_NAME(dp.major_id) AS proc_name,\\n  dp.permission_name,\\n  COALESCE(sm.definition, '') AS proc_definition_preview\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nJOIN sys.objects o ON dp.major_id = o.object_id\\nLEFT JOIN sys.sql_modules sm ON o.object_id = sm.object_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.permission_name = 'EXECUTE'\\n  AND o.is_ms_shipped = 0\\n  AND o.type IN ('P', 'FN', 'IF', 'TF')"}	{"condition": "procedures accessible to PUBLIC that access sensitive objects", "description": "PUBLIC can execute procedures that may access sensitive data — unsafe vendor recommendation implemented without scoping"}	null	2026-02-23 20:18:31.390645
4343	postgresql	query	Check for sessions in idle-in-transaction or waiting on IO	{"sql": "SELECT pid, usename, state, wait_event_type, wait_event, now() - query_start AS duration, query FROM pg_stat_activity WHERE (wait_event_type = 'IO' OR state = 'idle in transaction') AND now() - query_start > interval '5 minutes' ORDER BY duration DESC"}	{"condition": "row_count > 0", "description": "Sessions blocked on I/O or stuck in transaction confirm database throttling under bulk load"}	\N	2026-02-25 00:28:52.405273
3539	postgresql	query	Check for large bulk operations	{"sql": "SELECT datname, tup_inserted, tup_updated, tup_deleted FROM pg_stat_database WHERE datname = current_database()"}	{"condition": "tup_updated + tup_deleted > :change_threshold", "description": "High DML activity causing large WAL generation"}	{"change_threshold": 10000000}	2026-02-25 00:28:52.405273
2885	sqlserver	query	Check for high-privilege rootcause grants that look like emergency overrides	{"sql": "SELECT dp.permission_name, dp.class_desc,\\n  CASE dp.class_desc\\n    WHEN 'DATABASE' THEN DB_NAME()\\n    WHEN 'SCHEMA' THEN SCHEMA_NAME(dp.major_id)\\n    ELSE OBJECT_SCHEMA_NAME(dp.major_id) + '.' + OBJECT_NAME(dp.major_id)\\n  END AS scope,\\n  CASE\\n    WHEN dp.permission_name IN ('ALTER', 'CONTROL', 'ALTER ANY SCHEMA', 'ALTER ANY USER') THEN 'EMERGENCY_LEVEL'\\n    WHEN dp.permission_name IN ('INSERT', 'UPDATE', 'DELETE') AND dp.class_desc = 'SCHEMA' THEN 'EMERGENCY_LEVEL'\\n    WHEN dp.permission_name = 'EXECUTE' AND dp.class_desc = 'SCHEMA' THEN 'HIGH_RISK'\\n    ELSE 'ELEVATED' END AS risk_classification\\nFROM sys.database_permissions dp\\nJOIN sys.database_principals pr ON dp.grantee_principal_id = pr.principal_id\\nWHERE pr.name = 'public'\\n  AND dp.state_desc = 'GRANT'\\n  AND dp.permission_name IN ('ALTER', 'CONTROL', 'ALTER ANY SCHEMA', 'ALTER ANY USER',\\n    'INSERT', 'UPDATE', 'DELETE', 'EXECUTE')\\n  AND (dp.class_desc IN ('DATABASE', 'SCHEMA')\\n    OR (dp.class_desc = 'OBJECT_OR_COLUMN'\\n      AND dp.permission_name IN ('ALTER', 'CONTROL')))"}	{"condition": "any EMERGENCY_LEVEL grants found", "description": "PUBLIC has ALTER, CONTROL, or schema-wide DML grants — characteristic of emergency access that was never rolled back"}	null	2026-02-23 20:18:31.390646
2887	sqlserver	query	Check permissions held by orphaned users	{"sql": "SELECT dp_user.name AS orphaned_user, dp_user.type_desc,\\n  perm.permission_name, perm.state_desc, perm.class_desc,\\n  COALESCE(OBJECT_NAME(perm.major_id), SCHEMA_NAME(perm.major_id), '') AS object_name,\\n  rm.role_name\\nFROM sys.database_principals dp_user\\nLEFT JOIN sys.server_principals sp ON dp_user.sid = sp.sid\\nLEFT JOIN sys.database_permissions perm ON dp_user.principal_id = perm.grantee_principal_id\\nLEFT JOIN (\\n  SELECT drm.member_principal_id,\\n    STRING_AGG(dp_role.name, ', ') AS role_name\\n  FROM sys.database_role_members drm\\n  JOIN sys.database_principals dp_role ON drm.role_principal_id = dp_role.principal_id\\n  GROUP BY drm.member_principal_id\\n) rm ON dp_user.principal_id = rm.member_principal_id\\nWHERE dp_user.type IN ('S', 'U', 'G')\\n  AND sp.sid IS NULL\\n  AND dp_user.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser')\\n  AND dp_user.name NOT LIKE '##%'\\n  AND dp_user.authentication_type <> 0\\n  AND (perm.permission_name IS NOT NULL OR rm.role_name IS NOT NULL)"}	{"condition": "orphaned users with permissions or role memberships", "description": "Orphaned users retain permissions and role memberships — security risk from accounts that should no longer have access"}	null	2026-02-23 20:18:31.390647
2888	sqlserver	query	Count orphaned users across current database	{"sql": "SELECT dp.name AS user_name, dp.type_desc, dp.sid,\\n  dp.create_date, dp.modify_date,\\n  DATEDIFF(DAY, dp.modify_date, GETDATE()) AS days_since_modified,\\n  DB_NAME() AS database_name\\nFROM sys.database_principals dp\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND sp.sid IS NULL\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser')\\n  AND dp.name NOT LIKE '##%'\\n  AND dp.authentication_type <> 0"}	{"condition": "row_count > 0", "description": "Orphaned users found in database"}	null	2026-02-23 20:18:31.390648
2889	sqlserver	query	Check if orphaned users have been inactive for extended periods	{"sql": "SELECT dp.name AS orphaned_user, dp.type_desc,\\n  dp.create_date, dp.modify_date,\\n  DATEDIFF(DAY, dp.modify_date, GETDATE()) AS days_since_modified,\\n  CASE WHEN DATEDIFF(DAY, dp.modify_date, GETDATE()) > 180 THEN 'STALE_6_MONTHS'\\n    WHEN DATEDIFF(DAY, dp.modify_date, GETDATE()) > 90 THEN 'STALE_3_MONTHS'\\n    WHEN DATEDIFF(DAY, dp.modify_date, GETDATE()) > 30 THEN 'STALE_1_MONTH'\\n    ELSE 'RECENT' END AS staleness\\nFROM sys.database_principals dp\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND sp.sid IS NULL\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser')\\n  AND dp.name NOT LIKE '##%'\\n  AND dp.authentication_type <> 0\\nORDER BY days_since_modified DESC"}	{"condition": "rows with staleness = STALE_3_MONTHS or STALE_6_MONTHS", "description": "Orphaned users have been stale for months — manual offboarding missed these database users when login was removed"}	null	2026-02-23 20:18:31.390649
2891	sqlserver	query	Check if orphaned users own schemas or objects	{"sql": "SELECT dp.name AS orphaned_user,\\n  s.name AS owned_schema,\\n  (SELECT COUNT(*) FROM sys.objects o WHERE o.schema_id = s.schema_id AND o.is_ms_shipped = 0) AS objects_in_schema,\\n  DATEDIFF(DAY, dp.modify_date, GETDATE()) AS days_orphaned_estimate\\nFROM sys.database_principals dp\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nJOIN sys.schemas s ON dp.principal_id = s.principal_id\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND sp.sid IS NULL\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser')\\n  AND dp.name NOT LIKE '##%'\\n  AND dp.authentication_type <> 0\\n  AND DATEDIFF(DAY, dp.modify_date, GETDATE()) > 90"}	{"condition": "orphaned users that own schemas with objects", "description": "Long-orphaned users own schemas containing objects — deprovisioning was delayed and now cleanup is complex"}	null	2026-02-23 20:18:31.390649
4344	postgresql	query	Check table row count growth rate for volume spike	{"sql": "SELECT schemaname, relname, n_live_tup, n_dead_tup, n_tup_ins, n_tup_upd, n_tup_del, last_autoanalyze FROM pg_stat_user_tables WHERE n_tup_ins > :volume_threshold ORDER BY n_tup_ins DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with unusually high insert counts indicate a data volume spike"}	{"volume_threshold": 100000}	2026-02-25 00:28:52.405273
2892	sqlserver	query	Find orphaned SQL authentication users vs Windows users	{"sql": "SELECT dp.name AS user_name, dp.type_desc,\\n  dp.authentication_type_desc,\\n  CASE dp.type\\n    WHEN 'S' THEN 'SQL_LOGIN'\\n    WHEN 'U' THEN 'WINDOWS_LOGIN'\\n    WHEN 'G' THEN 'WINDOWS_GROUP'\\n    ELSE dp.type END AS auth_category,\\n  dp.create_date, dp.modify_date,\\n  DB_NAME() AS database_name\\nFROM sys.database_principals dp\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND sp.sid IS NULL\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser')\\n  AND dp.name NOT LIKE '##%'\\n  AND dp.authentication_type <> 0"}	{"condition": "row_count > 0", "description": "Orphaned users found — checking authentication type to assess HR integration gap"}	null	2026-02-23 20:18:31.39065
5606	postgresql	config_check	Check hot_standby_feedback setting on primary	{"sql": "SELECT name, setting FROM pg_settings WHERE name = 'hot_standby_feedback'"}	{"condition": "setting = 'off'", "description": "hot_standby_feedback disabled means replica queries can cause conflicts instead of delaying VACUUM"}	\N	2026-02-25 00:28:52.405273
2903	sqlserver	query	Check for users with cross-database role memberships creating dependency complexity	{"sql": "SELECT dp.name AS user_name, dp.type_desc,\\n  dr.name AS role_name,\\n  dp.create_date, dp.modify_date,\\n  CASE WHEN sp.sid IS NULL THEN 'ORPHANED' ELSE 'MAPPED' END AS mapping_status\\nFROM sys.database_principals dp\\nJOIN sys.database_role_members drm ON dp.principal_id = drm.member_principal_id\\nJOIN sys.database_principals dr ON drm.role_principal_id = dr.principal_id\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys')\\n  AND dp.sid IS NOT NULL AND dp.sid <> 0x00\\nORDER BY dp.name, dr.name"}	{"condition": "orphaned users with role memberships in multiple databases", "description": "Orphaned users retain role memberships creating hidden privilege persistence across databases"}	null	2026-02-23 20:18:31.390655
2894	sqlserver	query	Find orphaned users and disabled logins with database access	{"sql": "SELECT 'ORPHANED' AS issue_type, dp.name AS user_name, dp.type_desc,\\n  DB_NAME() AS database_name, NULL AS login_disabled\\nFROM sys.database_principals dp\\nLEFT JOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U', 'G')\\n  AND sp.sid IS NULL\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys', 'MS_DataCollectorInternalUser')\\n  AND dp.name NOT LIKE '##%'\\n  AND dp.authentication_type <> 0\\nUNION ALL\\nSELECT 'DISABLED_LOGIN' AS issue_type, dp.name AS user_name, dp.type_desc,\\n  DB_NAME() AS database_name, sp.is_disabled AS login_disabled\\nFROM sys.database_principals dp\\nJOIN sys.server_principals sp ON dp.sid = sp.sid\\nWHERE dp.type IN ('S', 'U')\\n  AND sp.is_disabled = 1\\n  AND dp.name NOT IN ('dbo', 'guest', 'INFORMATION_SCHEMA', 'sys')\\n  AND dp.name NOT LIKE '##%'"}	{"condition": "row_count > 0", "description": "Orphaned users or disabled logins with active database users found — no reconciliation is removing stale accounts"}	null	2026-02-23 20:18:31.390651
2896	sqlserver	query	Find service/application logins without ownership metadata	{"sql": "SELECT sp.name AS login_name, sp.type_desc,\\n  sp.create_date, sp.modify_date,\\n  sp.is_disabled,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS days_since_created,\\n  LOGINPROPERTY(sp.name, 'DaysUntilExpiration') AS days_until_expiry,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set\\nFROM sys.server_principals sp\\nWHERE sp.type = 'S'\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT IN ('sa')\\n  AND (\\n    sp.name LIKE '%svc%' OR sp.name LIKE '%app%' OR sp.name LIKE '%service%'\\n    OR sp.name LIKE '%agent%' OR sp.name LIKE '%batch%' OR sp.name LIKE '%job%'\\n    OR sp.name LIKE '%api%' OR sp.name LIKE '%web%' OR sp.name LIKE '%etl%'\\n    OR sp.name LIKE '%scheduler%' OR sp.name LIKE '%daemon%' OR sp.name LIKE '%system%'\\n  )"}	{"condition": "row_count > 0", "description": "Service/application logins found using SQL authentication — checking for ownership documentation"}	null	2026-02-23 20:18:31.390652
4064	postgresql	query	Check sustained replication lag	{"sql": "SELECT client_addr, replay_lag, pg_wal_lsn_diff(pg_current_wal_lsn(), replay_lsn) AS total_lag_bytes FROM pg_stat_replication WHERE replay_lag > interval ':threshold_seconds seconds'"}	{"condition": "row_count > 0", "description": "Persistent replay lag despite normal primary load suggests hardware limitations on replica"}	{"threshold_seconds": 60}	2026-02-25 00:28:52.405273
4069	postgresql	query	Check replay lag vs write lag	{"sql": "SELECT client_addr, pg_wal_lsn_diff(write_lsn, replay_lsn) AS write_replay_gap_bytes, pg_wal_lsn_diff(flush_lsn, replay_lsn) AS flush_replay_gap_bytes, replay_lag FROM pg_stat_replication WHERE pg_wal_lsn_diff(flush_lsn, replay_lsn) > :gap_threshold"}	{"condition": "row_count > 0", "description": "Large gap between flushed and replayed WAL confirms replay is the bottleneck"}	{"gap_threshold": 67108864}	2026-02-25 00:28:52.405273
2897	sqlserver	query	Check if service accounts have been orphaned in any database	{"sql": "SELECT sp.name AS login_name,\\n  sp.create_date AS login_created,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS age_days,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  CASE WHEN LOGINPROPERTY(sp.name, 'IsExpired') = 1 THEN 'EXPIRED'\\n    WHEN LOGINPROPERTY(sp.name, 'IsLocked') = 1 THEN 'LOCKED'\\n    WHEN LOGINPROPERTY(sp.name, 'IsMustChange') = 1 THEN 'MUST_CHANGE'\\n    ELSE 'ACTIVE' END AS password_status,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name) AS current_sessions\\nFROM sys.server_principals sp\\nWHERE sp.type = 'S'\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT IN ('sa')\\n  AND sp.is_disabled = 0\\n  AND (\\n    sp.name LIKE '%svc%' OR sp.name LIKE '%app%' OR sp.name LIKE '%service%'\\n    OR sp.name LIKE '%agent%' OR sp.name LIKE '%batch%' OR sp.name LIKE '%job%'\\n    OR sp.name LIKE '%api%' OR sp.name LIKE '%web%' OR sp.name LIKE '%etl%'\\n    OR sp.name LIKE '%scheduler%' OR sp.name LIKE '%daemon%' OR sp.name LIKE '%system%'\\n  )\\n  AND DATEDIFF(DAY, sp.create_date, GETDATE()) > 180"}	{"condition": "service accounts older than 180 days with no documented ownership", "description": "Long-lived service accounts without ownership tracking — no one knows who is responsible for these accounts"}	null	2026-02-23 20:18:31.390652
2898	sqlserver	query	Find SQL logins without password expiration enforcement	{"sql": "SELECT sp.name AS login_name, sp.type_desc, sp.create_date, sp.modify_date,\\n  sl.is_expiration_checked, sl.is_policy_checked,\\n  LOGINPROPERTY(sp.name, 'DaysUntilExpiration') AS days_until_expiration,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  sp.is_disabled\\nFROM sys.server_principals sp\\nJOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sl.is_expiration_checked = 0\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT IN ('sa')"}	{"condition": "row_count > 0", "description": "Active SQL logins found without password expiration policy — potential contractor/vendor accounts that will never expire"}	null	2026-02-23 20:18:31.390653
2899	sqlserver	query	Check for logins with names suggesting external accounts and no expiration	{"sql": "SELECT sp.name AS login_name, sp.type_desc, sp.create_date,\\n  sl.is_expiration_checked, sl.is_policy_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS account_age_days\\nFROM sys.server_principals sp\\nJOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sl.is_expiration_checked = 0\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND (\\n    sp.name LIKE '%vendor%' OR sp.name LIKE '%contractor%'\\n    OR sp.name LIKE '%consultant%' OR sp.name LIKE '%external%'\\n    OR sp.name LIKE '%partner%' OR sp.name LIKE '%temp%'\\n    OR sp.name LIKE '%3rd%' OR sp.name LIKE '%third%'\\n    OR DATEDIFF(DAY, sp.create_date, GETDATE()) > 365\\n  )"}	{"condition": "row_count > 0", "description": "Logins with external naming conventions or aged over 1 year without expiration — high probability of stale contractor/vendor accounts"}	null	2026-02-23 20:18:31.390654
2900	sqlserver	query	Find logins with generic shared-account naming patterns	{"sql": "SELECT sp.name AS login_name, sp.type_desc, sp.create_date,\\n  sp.is_disabled,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name AND s.is_user_process = 1) AS active_sessions,\\n  (SELECT COUNT(DISTINCT s.host_name) FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name AND s.is_user_process = 1) AS distinct_hosts\\nFROM sys.server_principals sp\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND (\\n    sp.name LIKE '%app%' OR sp.name LIKE '%service%'\\n    OR sp.name LIKE '%admin%' OR sp.name LIKE '%test%'\\n    OR sp.name LIKE '%user%' OR sp.name LIKE '%shared%'\\n    OR sp.name LIKE '%generic%' OR sp.name LIKE '%common%'\\n    OR sp.name LIKE '%default%' OR sp.name LIKE '%dev%'\\n  )\\n  AND sp.name NOT IN ('sa')"}	{"condition": "row_count > 0", "description": "SQL logins with generic names suggesting shared account usage"}	null	2026-02-23 20:18:31.390655
