3177	sqlserver	query	Check if encryption infrastructure exists but is unused	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.certificates WHERE name NOT LIKE '##%') AS user_certificates,\\n  (SELECT COUNT(*) FROM sys.symmetric_keys WHERE name NOT LIKE '##%') AS user_symmetric_keys,\\n  (SELECT COUNT(*) FROM sys.asymmetric_keys) AS asymmetric_keys,\\n  (SELECT is_master_key_encrypted_by_server FROM sys.databases WHERE name = 'master') AS dmk_exists"}	{"condition": "user_certificates = 0 and user_symmetric_keys = 0", "description": "No encryption infrastructure created — team likely deterred by encryption setup complexity"}	null	2026-02-23 20:18:31.390829
3245	sqlserver	query	Check linked server definitions and providers	{"sql": "SELECT s.name AS linked_server_name,\\n  s.data_source,\\n  s.provider,\\n  s.product,\\n  s.catalog,\\n  s.is_remote_login_enabled,\\n  s.is_data_access_enabled,\\n  s.is_rpc_out_enabled,\\n  ll.remote_name AS mapped_remote_login,\\n  ll.uses_self_credential\\nFROM sys.servers s\\nLEFT JOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nWHERE s.is_linked = 1"}	{"condition": "linked servers configured", "description": "Linked servers (SQL Server's FDW equivalent) are configured — each represents a cross-server communication channel"}	null	2026-02-23 20:18:31.39087
3181	sqlserver	query	Find backup jobs without encryption in their command text	{"sql": "SELECT j.name AS job_name, js.step_name, js.command,\\n  j.date_created, j.date_modified\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nWHERE (js.command LIKE '%BACKUP DATABASE%' OR js.command LIKE '%BACKUP LOG%')\\n  AND js.command NOT LIKE '%ENCRYPTION%'\\n  AND j.enabled = 1\\nORDER BY j.date_created ASC"}	{"condition": "row_count > 0", "description": "Enabled backup jobs without ENCRYPTION clause in their BACKUP commands"}	null	2026-02-23 20:18:31.390832
3185	sqlserver	query	Check symmetric keys for short key lengths	{"sql": "SELECT sk.name, sk.algorithm_desc, sk.key_length,\\n  sk.create_date, sk.modify_date,\\n  CASE\\n    WHEN sk.algorithm_desc IN ('DES', 'TRIPLE_DES', 'RC4', 'RC4_128', 'RC2', 'DESX') THEN 'DEPRECATED_ALGORITHM'\\n    WHEN sk.key_length < 128 THEN 'CRITICALLY_SHORT'\\n    WHEN sk.key_length < 256 AND sk.algorithm_desc LIKE 'AES%' THEN 'BELOW_RECOMMENDED'\\n    ELSE 'OK'\\n  END AS key_strength_status\\nFROM sys.symmetric_keys sk\\nWHERE sk.name NOT LIKE '##%'\\nORDER BY sk.key_length ASC"}	{"condition": "any key with key_strength_status IN (CRITICALLY_SHORT, BELOW_RECOMMENDED)", "description": "Symmetric keys with key lengths below recommended minimum (AES-256)"}	null	2026-02-23 20:18:31.390834
3186	sqlserver	query	Check for deprecated algorithms in symmetric keys	{"sql": "SELECT sk.name, sk.algorithm_desc, sk.key_length,\\n  sk.create_date\\nFROM sys.symmetric_keys sk\\nWHERE sk.algorithm_desc IN ('DES', 'TRIPLE_DES', 'TRIPLE_DES_3KEY', 'RC4', 'RC4_128', 'RC2', 'DESX')\\n  AND sk.name NOT LIKE '##%'\\nORDER BY sk.create_date ASC"}	{"condition": "row_count > 0", "description": "Symmetric keys using deprecated algorithms (DES, RC4, RC2, 3DES)"}	null	2026-02-23 20:18:31.390835
3188	sqlserver	query	Check certificate properties for weak signatures	{"sql": "SELECT c.name AS certificate_name,\\n  c.start_date, c.expiry_date,\\n  c.key_length,\\n  c.pvt_key_encryption_type_desc,\\n  c.subject,\\n  CERTPROPERTY(c.certificate_id, 'Sig_Algorithm') AS signature_algorithm,\\n  DATEDIFF(DAY, GETDATE(), c.expiry_date) AS days_until_expiry\\nFROM sys.certificates c\\nWHERE c.name NOT LIKE '##%'\\nORDER BY c.start_date ASC"}	{"condition": "signature_algorithm contains MD5 or SHA1", "description": "Certificate signed with weak hash algorithm (MD5 or SHA-1)"}	null	2026-02-23 20:18:31.390836
3558	postgresql	query	Check for role-level parameter overrides from tools	{"sql": "SELECT r.rolname, unnest(r.rolconfig) AS parameter FROM pg_roles r WHERE r.rolconfig IS NOT NULL ORDER BY r.rolname"}	{"condition": "row_count > 0", "description": "Role-level parameter overrides exist — may have been set by management tools"}	\N	2026-02-25 00:28:52.405273
9887	mysql	query	Check binary log status	{"sql": "SHOW BINARY LOGS"}	{"condition": "row_count > 0", "description": "Binary log files listed for corruption analysis"}	\N	2026-03-01 06:30:58.706791
3201	sqlserver	query	Check if SCHANNEL cipher suite order has been customized	{"sql": "DECLARE @cipher_order NVARCHAR(4000);\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SOFTWARE\\\\Policies\\\\Microsoft\\\\Cryptography\\\\Configuration\\\\SSL\\\\00010002',\\n  N'Functions', @cipher_order OUTPUT;\\nSELECT\\n  CASE WHEN @cipher_order IS NULL THEN 'DEFAULT_NOT_CUSTOMIZED'\\n    ELSE 'CUSTOM_CIPHER_ORDER'\\n  END AS cipher_suite_status,\\n  @cipher_order AS configured_cipher_order;"}	{"condition": "cipher_suite_status = 'DEFAULT_NOT_CUSTOMIZED'", "description": "No custom cipher suite order configured via Group Policy — using Windows defaults without review"}	null	2026-02-23 20:18:31.390837
3191	sqlserver	query	Check if any active connections negotiated CBC-mode ciphers	{"sql": "SELECT COUNT(*) AS encrypted_connections,\\n  COUNT(CASE WHEN c.encrypt_option = 'TRUE' THEN 1 END) AS tls_connections\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND c.encrypt_option = 'TRUE'"}	{"condition": "tls_connections > 0", "description": "Encrypted connections exist — with CBC enabled at OS level, any connection could negotiate a CBC cipher"}	null	2026-02-23 20:18:31.390839
3202	sqlserver	query	Check if any SCHANNEL cipher-level registry customization exists	{"sql": "DECLARE @rc4 INT, @3des INT, @aes128 INT, @aes256 INT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders\\\\SCHANNEL\\\\Ciphers\\\\RC4 128/128',\\n  N'Enabled', @rc4 OUTPUT;\\nEXEC master.dbo.xp_instance_regread\\n  N'HKEY_LOCAL_MACHINE',\\n  N'SYSTEM\\\\CurrentControlSet\\\\Control\\\\SecurityProviders\\\\SCHANNEL\\\\Ciphers\\\\Triple DES 168',\\n  N'Enabled', @3des OUTPUT;\\nSELECT\\n  CASE WHEN @rc4 IS NULL AND @3des IS NULL\\n    THEN 'NO_CIPHER_CUSTOMIZATION'\\n    ELSE 'SOME_CIPHER_CUSTOMIZATION'\\n  END AS customization_status,\\n  @rc4 AS rc4_setting, @3des AS triple_des_setting;"}	{"condition": "customization_status = 'NO_CIPHER_CUSTOMIZATION'", "description": "No individual cipher registry keys set — all at Windows defaults, confirming no security review of cipher suites"}	null	2026-02-23 20:18:31.390844
3194	sqlserver	query	Check certificate age for TDE and other encryption	{"sql": "SELECT name, subject, start_date, expiry_date,\\n  DATEDIFF(DAY, start_date, GETDATE()) AS age_days,\\n  DATEDIFF(DAY, GETDATE(), expiry_date) AS days_until_expiry,\\n  pvt_key_encryption_type_desc,\\n  CASE\\n    WHEN DATEDIFF(DAY, start_date, GETDATE()) > 730 THEN 'OVERDUE_ROTATION'\\n    WHEN DATEDIFF(DAY, start_date, GETDATE()) > 365 THEN 'APPROACHING_ROTATION'\\n    ELSE 'OK'\\n  END AS rotation_status\\nFROM master.sys.certificates\\nWHERE name NOT LIKE '##%'\\nORDER BY start_date ASC"}	{"condition": "any row with rotation_status = 'OVERDUE_ROTATION'", "description": "Certificates older than 2 years without rotation — indicates no key rotation policy"}	null	2026-02-23 20:18:31.39084
13721	mariadb	query	Check for backup-related activity on replica	{"sql": "SELECT id, user, host, command, time AS duration_seconds, state, info FROM information_schema.PROCESSLIST WHERE info LIKE '%BACKUP%' OR info LIKE '%FLUSH TABLES%' OR state LIKE '%Sending to client%' AND time > 60 ORDER BY time DESC"}	{"condition": "row_count > 0", "description": "Active backup operations on the semi-sync replica consuming resources"}	\N	2026-05-11 22:17:39.229791
3222	sqlserver	query	Check login audit for recent authentication attempts	{"sql": "SELECT sp.name AS login_name, sp.create_date,\\n  LOGINPROPERTY(sp.name, 'DaysUntilExpiration') AS days_until_expiration,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  LOGINPROPERTY(sp.name, 'IsExpired') AS is_expired,\\n  LOGINPROPERTY(sp.name, 'IsLocked') AS is_locked,\\n  LOGINPROPERTY(sp.name, 'IsMustChange') AS must_change\\nFROM sys.server_principals sp\\nWHERE sp.type = 'S'\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\n  AND sp.is_disabled = 0\\n  AND DATEDIFF(DAY, sp.create_date, GETDATE()) > 90\\n  AND LOGINPROPERTY(sp.name, 'DaysUntilExpiration') IS NULL"}	{"condition": "row_count > 0", "description": "SQL logins with no password expiration policy — temporary accounts without lifecycle management"}	null	2026-02-23 20:18:31.390858
3196	sqlserver	query	Check TDE database encryption key age	{"sql": "SELECT d.name AS database_name,\\n  dek.encryptor_type, dek.key_algorithm, dek.key_length,\\n  dek.create_date, dek.regenerate_date,\\n  COALESCE(dek.regenerate_date, dek.create_date) AS last_rotation_date,\\n  DATEDIFF(DAY, COALESCE(dek.regenerate_date, dek.create_date), GETDATE()) AS days_since_rotation,\\n  CASE\\n    WHEN DATEDIFF(DAY, COALESCE(dek.regenerate_date, dek.create_date), GETDATE()) > 730 THEN 'OVERDUE'\\n    WHEN DATEDIFF(DAY, COALESCE(dek.regenerate_date, dek.create_date), GETDATE()) > 365 THEN 'APPROACHING'\\n    ELSE 'OK'\\n  END AS rotation_status\\nFROM sys.dm_database_encryption_keys dek\\nJOIN sys.databases d ON dek.database_id = d.database_id\\nWHERE dek.encryption_state = 3"}	{"condition": "any row with rotation_status = 'OVERDUE'", "description": "TDE database encryption keys not rotated in over 2 years — key rotation policy missing or not enforced"}	null	2026-02-23 20:18:31.390842
3197	sqlserver	query	Check asymmetric keys for weak parameters in master	{"sql": "SELECT name, algorithm_desc, key_length,\\n  pvt_key_encryption_type_desc,\\n  CASE\\n    WHEN algorithm_desc = 'RSA_512' THEN 'CRITICAL_WEAK'\\n    WHEN algorithm_desc = 'RSA_1024' THEN 'WEAK'\\n    WHEN algorithm_desc = 'RSA_2048' THEN 'ACCEPTABLE'\\n    WHEN algorithm_desc = 'RSA_3072' THEN 'STRONG'\\n    WHEN algorithm_desc = 'RSA_4096' THEN 'STRONG'\\n    ELSE 'UNKNOWN'\\n  END AS strength_assessment\\nFROM sys.asymmetric_keys\\nWHERE key_length < 2048"}	{"condition": "row_count > 0", "description": "Asymmetric keys found with key length below 2048 bits — cryptographically weak"}	null	2026-02-23 20:18:31.390842
