3203	sqlserver	query	Find procedures with EXEC and string concatenation patterns	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  m.object_id\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type IN ('P', 'FN', 'IF', 'TF')\\n  AND (\\n    m.definition LIKE '%EXEC(%+%@%+%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXECUTE(%+%@%+%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXECUTE (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXECUTE(@%' COLLATE Latin1_General_BIN\\n  )"}	{"condition": "row_count > 0", "description": "Stored procedures found using EXEC with string concatenation — potential SQL injection vectors"}	null	2026-02-23 20:18:31.390845
3204	sqlserver	query	Filter to procedures that concatenate without using sp_executesql parameters	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  LEN(m.definition) AS definition_length\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type IN ('P', 'FN', 'IF', 'TF')\\n  AND (\\n    m.definition LIKE '%EXEC(%+%@%+%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXECUTE(%+%@%+%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@%' COLLATE Latin1_General_BIN\\n  )\\n  AND m.definition NOT LIKE '%sp_executesql%' COLLATE Latin1_General_BIN"}	{"condition": "row_count > 0", "description": "Procedures using EXEC with concatenation AND not using parameterized sp_executesql — highest injection risk"}	null	2026-02-23 20:18:31.390845
3205	sqlserver	query	Find dynamic SQL procedures without QUOTENAME or REPLACE	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  CASE\\n    WHEN m.definition LIKE '%EXEC(%' OR m.definition LIKE '%EXECUTE(%'\\n      THEN 'EXEC_PATTERN'\\n    WHEN m.definition LIKE '%sp_executesql%'\\n      THEN 'SP_EXECUTESQL'\\n    ELSE 'OTHER'\\n  END AS dynamic_sql_type\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type = 'P'\\n  AND (m.definition LIKE '%EXEC(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXECUTE(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@%' COLLATE Latin1_General_BIN)\\n  AND m.definition NOT LIKE '%QUOTENAME%' COLLATE Latin1_General_BIN\\n  AND m.definition NOT LIKE '%REPLACE(%''%'',%''''''''%)%'"}	{"condition": "row_count > 0", "description": "Procedures with dynamic SQL but no QUOTENAME or single-quote escaping — missing input validation"}	null	2026-02-23 20:18:31.390846
3213	sqlserver	query	Check for broad EXECUTE permissions on stored procedures with dynamic SQL	{"sql": "SELECT dp.name AS grantee_name, dp.type_desc AS principal_type,\\n  p.permission_name, p.state_desc,\\n  OBJECT_SCHEMA_NAME(p.major_id) AS schema_name,\\n  OBJECT_NAME(p.major_id) AS object_name\\nFROM sys.database_permissions p\\nJOIN sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\nJOIN sys.sql_modules m ON p.major_id = m.object_id\\nWHERE p.permission_name = 'EXECUTE'\\n  AND p.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n  AND (m.definition LIKE '%EXEC(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@ %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%sp_executesql%')\\n  AND dp.name NOT IN ('dbo', 'db_owner')"}	{"condition": "row_count > 0", "description": "Non-DBO principals have EXECUTE permission on procedures containing dynamic SQL"}	null	2026-02-23 20:18:31.390847
5900	postgresql	config_check	Check data_directory permissions and file access scope	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('data_directory', 'config_file', 'hba_file', 'ident_file')"}	{"condition": "row_count > 0", "description": "Configuration files accessible — COPY FROM can read these as superuser"}	\N	2026-02-25 00:28:52.405273
3206	sqlserver	query	Find old procedures with dynamic SQL and no parameterization	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  o.create_date, o.modify_date,\\n  DATEDIFF(YEAR, o.create_date, GETDATE()) AS age_years,\\n  CASE\\n    WHEN m.definition LIKE '%sp_executesql%' THEN 'HAS_SP_EXECUTESQL'\\n    ELSE 'NO_SP_EXECUTESQL'\\n  END AS parameterization_status\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type = 'P'\\n  AND (m.definition LIKE '%EXEC(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXECUTE(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@%' COLLATE Latin1_General_BIN)\\n  AND m.definition NOT LIKE '%sp_executesql%' COLLATE Latin1_General_BIN\\n  AND DATEDIFF(YEAR, o.create_date, GETDATE()) >= :min_age_years\\nORDER BY o.create_date ASC"}	{"condition": "row_count > 0", "description": "Legacy procedures (created years ago) with unsafe dynamic SQL — technical debt not remediated"}	{"min_age_years": 3}	2026-02-23 20:18:31.390848
3207	sqlserver	query	Find procedures with both static DML and dynamic execution	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  CASE WHEN m.definition LIKE '%EXEC(%+%@%' OR m.definition LIKE '%EXEC(@%'\\n    OR m.definition LIKE '%EXEC (@%' THEN 1 ELSE 0 END AS has_exec_concat,\\n  CASE WHEN m.definition LIKE '%sp_executesql%' THEN 1 ELSE 0 END AS has_sp_executesql\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type = 'P'\\n  AND (m.definition LIKE '%EXEC(%' OR m.definition LIKE '%EXECUTE(%'\\n    OR m.definition LIKE '%sp_executesql%')\\n  AND (m.definition LIKE '%SELECT %FROM %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%INSERT %INTO %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%UPDATE %SET %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%DELETE %FROM %' COLLATE Latin1_General_BIN)"}	{"condition": "row_count > 0", "description": "Procedures with both static SQL and dynamic execution — mixed patterns increase confusion and injection risk"}	null	2026-02-23 20:18:31.390848
3451	postgresql	query	Check total database size relative to available space	{"sql": "SELECT sum(pg_database_size(datname)) AS total_size, pg_size_pretty(sum(pg_database_size(datname))) AS total_human FROM pg_database WHERE datistemplate = false"}	{"condition": "total_size_retrieved", "description": "Database size calculated — compare with available disk on backup destination"}	\N	2026-02-25 00:28:52.405273
3208	sqlserver	query	Count dynamic SQL procedures with mixed patterns	{"sql": "SELECT COUNT(*) AS mixed_pattern_count,\\n  SUM(CASE WHEN m.definition NOT LIKE '%QUOTENAME%'\\n    AND m.definition NOT LIKE '%sp_executesql%N''%@%' THEN 1 ELSE 0 END) AS unprotected_mixed_count\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type = 'P'\\n  AND (m.definition LIKE '%EXEC(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@ %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%sp_executesql%')\\n  AND (m.definition LIKE '%SELECT %FROM %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%INSERT %INTO %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%UPDATE %SET %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%DELETE %FROM %' COLLATE Latin1_General_BIN)"}	{"condition": "unprotected_mixed_count > 0", "description": "Mixed static/dynamic procedures without proper parameterization — highest risk of accidental injection"}	null	2026-02-23 20:18:31.390849
3209	sqlserver	query	Find procedures with extensive dynamic SQL construction	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  LEN(m.definition) AS definition_length,\\n  (LEN(m.definition) - LEN(REPLACE(m.definition, '+ @', ''))) / 3 AS approx_concat_count,\\n  (LEN(m.definition) - LEN(REPLACE(m.definition, 'IF ', ''))) / 3 AS approx_if_count\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type = 'P'\\n  AND (m.definition LIKE '%EXEC(%' OR m.definition LIKE '%sp_executesql%')\\n  AND (LEN(m.definition) - LEN(REPLACE(m.definition, '+ @', ''))) / 3 >= :min_concat_points\\nORDER BY (LEN(m.definition) - LEN(REPLACE(m.definition, '+ @', ''))) DESC"}	{"condition": "row_count > 0", "description": "Procedures with many string concatenation points in dynamic SQL — complex business logic driving unsafe dynamic query building"}	{"min_concat_points": 5}	2026-02-23 20:18:31.390849
3210	sqlserver	query	Find frequently-executed dynamic SQL procedures	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  ps.execution_count,\\n  ps.total_elapsed_time / 1000 AS total_elapsed_ms,\\n  CASE WHEN ps.execution_count > 0\\n    THEN ps.total_elapsed_time / ps.execution_count / 1000\\n    ELSE 0 END AS avg_elapsed_ms,\\n  ps.total_logical_reads,\\n  CASE WHEN m.definition LIKE '%OPTION%RECOMPILE%' THEN 1 ELSE 0 END AS has_recompile_hint\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nLEFT JOIN sys.dm_exec_procedure_stats ps ON m.object_id = ps.object_id\\nWHERE o.type = 'P'\\n  AND (m.definition LIKE '%EXEC(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@ %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%sp_executesql%')\\n  AND ps.execution_count >= :min_executions\\nORDER BY ps.execution_count DESC"}	{"condition": "row_count > 0", "description": "Highly-executed procedures using dynamic SQL — likely built for performance optimization (avoiding parameter sniffing, generating optimal plans per parameter set)"}	{"min_executions": 1000}	2026-02-23 20:18:31.39085
3383	postgresql	query	Check deadlock count from pg_stat_database	{"sql": "SELECT datname, deadlocks FROM pg_stat_database WHERE deadlocks > :baseline_count ORDER BY deadlocks DESC"}	{"condition": "row_count > 0", "description": "Databases with deadlock count above baseline"}	{"baseline_count": 0}	2026-02-25 00:28:52.405273
3211	sqlserver	query	Check for high ad-hoc to prepared query ratio in plan cache	{"sql": "SELECT\\n  SUM(CASE WHEN objtype = 'Adhoc' THEN 1 ELSE 0 END) AS adhoc_plans,\\n  SUM(CASE WHEN objtype = 'Prepared' THEN 1 ELSE 0 END) AS prepared_plans,\\n  SUM(CASE WHEN objtype = 'Proc' THEN 1 ELSE 0 END) AS proc_plans,\\n  COUNT(*) AS total_plans,\\n  CASE WHEN COUNT(*) > 0\\n    THEN CAST(SUM(CASE WHEN objtype = 'Adhoc' THEN 1 ELSE 0 END) AS FLOAT) / COUNT(*) * 100\\n    ELSE 0 END AS adhoc_pct\\nFROM sys.dm_exec_cached_plans"}	{"condition": "adhoc_pct > 70", "description": "Over 70% ad-hoc plans — suggests application or ORM sending non-parameterized queries"}	null	2026-02-23 20:18:31.390851
3212	sqlserver	query	Find similar ad-hoc queries differing only by literal values	{"sql": "SELECT TOP 20\\n  qs.query_hash,\\n  COUNT(*) AS plan_count,\\n  MIN(SUBSTRING(qt.text, 1, 100)) AS sample_query\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) qt\\nWHERE qt.dbid > 4\\nGROUP BY qs.query_hash\\nHAVING COUNT(*) >= :min_duplicates\\nORDER BY COUNT(*) DESC"}	{"condition": "row_count > 0", "description": "Multiple plans for the same query hash — ORM or application sending unparameterized queries with different literal values"}	{"min_duplicates": 10}	2026-02-23 20:18:31.390851
3237	sqlserver	query	Check if version info accessible to low-privilege logins	{"sql": "SELECT\\n  @@VERSION AS version_banner,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS service_pack,\\n  SERVERPROPERTY('Edition') AS edition,\\n  (SELECT DISTINCT local_tcp_port FROM sys.dm_exec_connections\\n   WHERE local_tcp_port IS NOT NULL AND net_transport = 'TCP') AS listening_port"}	{"condition": "listening_port = 1433 AND version_banner accessible", "description": "SQL Server on default port with full version banner accessible — attackers can fingerprint exact version and target CVEs"}	null	2026-02-23 20:18:31.390852
3223	sqlserver	query	Check TCP listener ports	{"sql": "SELECT listener_id, ip_address, port, type_desc, state_desc\\nFROM sys.dm_tcp_listener_states\\nWHERE state_desc = 'STARTED'\\n  AND type_desc = 'TSQL'"}	{"condition": "any row has port = 1433", "description": "SQL Server listening on default port 1433 — default configuration never changed"}	null	2026-02-23 20:18:31.390859
3214	sqlserver	query	Check for procedures with EXECUTE AS or ownership chaining elevating dynamic SQL privileges	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  m.execute_as_principal_id,\\n  dp.name AS execute_as_name,\\n  dp.type_desc AS principal_type\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nLEFT JOIN sys.database_principals dp ON m.execute_as_principal_id = dp.principal_id\\nWHERE o.type = 'P'\\n  AND m.execute_as_principal_id IS NOT NULL\\n  AND m.execute_as_principal_id <> 0\\n  AND (m.definition LIKE '%EXEC(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@ %' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%sp_executesql%')"}	{"condition": "row_count > 0", "description": "Dynamic SQL procedures with EXECUTE AS impersonation — dynamic SQL inside runs with elevated identity, breaking ownership chaining containment"}	null	2026-02-23 20:18:31.390853
3215	sqlserver	query	Check for connections from non-private IP ranges	{"sql": "SELECT c.session_id, c.client_net_address, c.local_net_address,\\n  c.connect_time, s.login_name, s.host_name, s.program_name\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND c.client_net_address NOT LIKE '10.%'\\n  AND c.client_net_address NOT LIKE '172.1[6-9].%'\\n  AND c.client_net_address NOT LIKE '172.2[0-9].%'\\n  AND c.client_net_address NOT LIKE '172.3[0-1].%'\\n  AND c.client_net_address NOT LIKE '192.168.%'\\n  AND c.client_net_address NOT LIKE '127.%'\\n  AND c.client_net_address <> '<local machine>'\\n  AND c.client_net_address <> ''"}	{"condition": "row_count > 0", "description": "Connections from non-private IP addresses indicate the instance may be reachable from the public internet"}	null	2026-02-23 20:18:31.390853
3218	sqlserver	query	Check for connections from diverse IP ranges	{"sql": "SELECT DISTINCT\\n  LEFT(c.client_net_address,\\n    CASE WHEN CHARINDEX('.', c.client_net_address, CHARINDEX('.', c.client_net_address) + 1) > 0\\n      THEN CHARINDEX('.', c.client_net_address, CHARINDEX('.', c.client_net_address) + 1) - 1\\n      ELSE LEN(c.client_net_address) END) AS ip_prefix,\\n  COUNT(*) AS connection_count\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND c.client_net_address <> '<local machine>'\\nGROUP BY LEFT(c.client_net_address,\\n  CASE WHEN CHARINDEX('.', c.client_net_address, CHARINDEX('.', c.client_net_address) + 1) > 0\\n    THEN CHARINDEX('.', c.client_net_address, CHARINDEX('.', c.client_net_address) + 1) - 1\\n    ELSE LEN(c.client_net_address) END)"}	{"condition": "multiple distinct IP prefixes with no logon trigger restriction", "description": "Connections from diverse IP ranges with no SQL-level allowlist enforcement"}	null	2026-02-23 20:18:31.390855
3219	sqlserver	query	Check instance configuration for non-standard or default settings	{"sql": "SELECT\\n  SERVERPROPERTY('MachineName') AS machine_name,\\n  SERVERPROPERTY('InstanceName') AS instance_name,\\n  SERVERPROPERTY('Edition') AS edition,\\n  SERVERPROPERTY('ProductVersion') AS version,\\n  SERVERPROPERTY('ProductLevel') AS service_pack,\\n  SERVERPROPERTY('IsClustered') AS is_clustered,\\n  (SELECT COUNT(*) FROM sys.databases WHERE database_id > 4) AS user_db_count,\\n  (SELECT create_date FROM sys.server_principals WHERE sid = 0x01) AS sa_create_date,\\n  (SELECT is_disabled FROM sys.server_principals WHERE sid = 0x01) AS sa_disabled,\\n  (SELECT COUNT(*) FROM sys.dm_tcp_listener_states WHERE state_desc = 'STARTED') AS active_listeners"}	{"condition": "sa_disabled = 0 and default configuration indicators present", "description": "Instance with sa enabled and minimal hardening suggests unmanaged deployment"}	null	2026-02-23 20:18:31.390856
3220	sqlserver	query	Check for absence of standard management indicators	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.credentials) AS credential_count,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysjobs) AS job_count,\\n  (SELECT COUNT(*) FROM msdb.dbo.sysmail_profile) AS mail_profile_count,\\n  (SELECT COUNT(*) FROM msdb.dbo.log_shipping_primary_databases) AS log_shipping_count,\\n  (SELECT COUNT(*) FROM sys.availability_groups) AS ag_count,\\n  (SELECT COUNT(*) FROM msdb.dbo.backupset\\n   WHERE backup_finish_date > DATEADD(day, -30, GETDATE())) AS recent_backup_count"}	{"condition": "job_count = 0 AND mail_profile_count = 0 AND recent_backup_count = 0", "description": "No jobs, no mail profiles, no recent backups — instance appears unmanaged (potential shadow IT)"}	null	2026-02-23 20:18:31.390857
