3251	sqlserver	query	Check for databases with forced parameterization disabled and high ad-hoc plan counts	{"sql": "SELECT d.name AS database_name,\\n  d.is_parameterization_forced,\\n  COUNT(cp.plan_handle) AS adhoc_plan_count,\\n  SUM(cp.usecounts) AS total_adhoc_executions\\nFROM sys.databases d\\nCROSS APPLY (\\n  SELECT cp2.plan_handle, cp2.usecounts\\n  FROM sys.dm_exec_cached_plans cp2\\n  CROSS APPLY sys.dm_exec_sql_text(cp2.plan_handle) qt\\n  WHERE cp2.objtype = 'Adhoc'\\n    AND qt.dbid = d.database_id\\n) cp\\nWHERE d.database_id > 4\\n  AND d.is_parameterization_forced = 0\\nGROUP BY d.name, d.is_parameterization_forced\\nHAVING COUNT(cp.plan_handle) > :min_adhoc_plans"}	{"condition": "row_count > 0 with adhoc_plan_count > 500", "description": "Databases with simple parameterization (framework default trust) and high ad-hoc plan counts — application frameworks sending unparameterized queries"}	{"min_adhoc_plans": 500}	2026-02-23 20:18:31.390873
3252	sqlserver	query	Check for optimize for ad hoc workloads not enabled as safety net	{"sql": "SELECT name, CAST(value_in_use AS INT) AS value_in_use\\nFROM sys.configurations\\nWHERE name = 'optimize for ad hoc workloads'"}	{"condition": "value_in_use = 0", "description": "Optimize for ad hoc workloads is OFF — no server-side mitigation for framework-generated ad-hoc queries, confirming implicit trust in framework parameterization defaults"}	null	2026-02-23 20:18:31.390874
3253	sqlserver	query	Find procedures using sp_executesql with string concatenation in the query portion	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  m.object_id\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type IN ('P', 'FN', 'IF', 'TF')\\n  AND m.definition LIKE '%sp_executesql%' COLLATE Latin1_General_BIN\\n  AND (\\n    m.definition LIKE '%sp_executesql%+%@%+%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%sp_executesql %N''%'' + @%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%SET @%=%+%@%+%[^,]%sp_executesql%@%' COLLATE Latin1_General_BIN\\n  )"}	{"condition": "row_count > 0", "description": "Procedures using sp_executesql but with string concatenation in the query text — parameter binding is incomplete"}	null	2026-02-23 20:18:31.390874
4103	postgresql	query	Check pg_hba.conf replication rules	{"sql": "SELECT type, database, user_name, address, auth_method FROM pg_hba_file_rules WHERE database::text LIKE '%replication%'"}	{"condition": "row_count = 0", "description": "No replication entries in pg_hba.conf prevents standby authentication"}	\N	2026-02-25 00:28:52.405273
3254	sqlserver	query	Narrow to procedures concatenating variables into sp_executesql SQL string without QUOTENAME protection	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  CASE WHEN m.definition LIKE '%QUOTENAME%' THEN 1 ELSE 0 END AS has_quotename,\\n  LEN(m.definition) AS definition_length\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type IN ('P', 'FN', 'IF', 'TF')\\n  AND m.definition LIKE '%sp_executesql%' COLLATE Latin1_General_BIN\\n  AND (\\n    m.definition LIKE '%sp_executesql%+%@%+%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%SET @%=%+%@%+%[^,]%sp_executesql%@%' COLLATE Latin1_General_BIN\\n  )\\n  AND m.definition NOT LIKE '%QUOTENAME%' COLLATE Latin1_General_BIN"}	{"condition": "row_count > 0", "description": "sp_executesql procedures concatenating variables without QUOTENAME — incomplete parameter binding with no compensating control"}	null	2026-02-23 20:18:31.390875
3256	sqlserver	query	Check for active usage of dangerous system extended stored procedures	{"sql": "SELECT OBJECT_NAME(ps.object_id) AS xproc_name,\\n  ps.execution_count, ps.last_execution_time,\\n  DATEDIFF(DAY, ps.last_execution_time, GETDATE()) AS days_since_last_exec\\nFROM sys.dm_exec_procedure_stats ps\\nWHERE OBJECT_NAME(ps.object_id) IN (\\n  'xp_cmdshell', 'xp_regread', 'xp_regwrite', 'xp_regdeletevalue',\\n  'xp_regdeletekey', 'xp_regenumvalues', 'xp_fileexist',\\n  'xp_subdirs', 'xp_dirtree', 'xp_fixeddrives',\\n  'xp_enumerrorlogs', 'xp_readerrorlog',\\n  'xp_servicecontrol', 'xp_sprintf', 'xp_sscanf'\\n)\\nORDER BY ps.execution_count DESC"}	{"condition": "row_count > 0", "description": "Legacy xprocs actively executed — system depends on extended stored procedure functionality"}	null	2026-02-23 20:18:31.390876
3277	sqlserver	query	Check for dynamic SQL procedures that could be injection entry points	{"sql": "SELECT OBJECT_SCHEMA_NAME(m.object_id) AS schema_name,\\n  OBJECT_NAME(m.object_id) AS proc_name,\\n  CASE\\n    WHEN m.definition LIKE '%EXEC(%+%@%' AND m.definition NOT LIKE '%sp_executesql%'\\n      THEN 'HIGH_RISK_EXEC_CONCAT'\\n    WHEN m.definition LIKE '%sp_executesql%+%@%+%'\\n      THEN 'MEDIUM_RISK_INCOMPLETE_PARAMS'\\n    WHEN m.definition LIKE '%EXEC(%+%@%'\\n      THEN 'MODERATE_RISK_EXEC_PATTERN'\\n    ELSE 'LOW_RISK'\\n  END AS injection_risk_level\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE o.type = 'P'\\n  AND (m.definition LIKE '%EXEC(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXECUTE(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@%' COLLATE Latin1_General_BIN)"}	{"condition": "row_count > 0", "description": "Dynamic SQL procedures found with xp_cmdshell enabled — attack chain: SQL injection → dynamic SQL → xp_cmdshell → OS commands"}	null	2026-02-23 20:18:31.390878
4356	postgresql	query	Identify largest tables by size and row count	{"sql": "SELECT schemaname, relname, n_live_tup, n_dead_tup, pg_size_pretty(pg_total_relation_size(schemaname || '.' || relname)) AS total_size, pg_total_relation_size(schemaname || '.' || relname) AS size_bytes FROM pg_stat_user_tables ORDER BY pg_total_relation_size(schemaname || '.' || relname) DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Large tables identified that may require archival review"}	\N	2026-02-25 00:28:52.405273
3259	sqlserver	query	Count stored procedures referencing extended stored procedures	{"sql": "SELECT xproc_name, COUNT(DISTINCT calling_proc) AS dependent_proc_count\\nFROM (\\n  SELECT OBJECT_NAME(m.object_id) AS calling_proc,\\n    'xp_cmdshell' AS xproc_name\\n  FROM sys.sql_modules m\\n  JOIN sys.objects o ON m.object_id = o.object_id\\n  WHERE o.type = 'P'\\n    AND m.definition LIKE '%xp_cmdshell%' COLLATE Latin1_General_BIN\\n  UNION ALL\\n  SELECT OBJECT_NAME(m.object_id), 'xp_regread'\\n  FROM sys.sql_modules m\\n  JOIN sys.objects o ON m.object_id = o.object_id\\n  WHERE o.type = 'P'\\n    AND m.definition LIKE '%xp_regread%' COLLATE Latin1_General_BIN\\n  UNION ALL\\n  SELECT OBJECT_NAME(m.object_id), 'xp_fileexist'\\n  FROM sys.sql_modules m\\n  JOIN sys.objects o ON m.object_id = o.object_id\\n  WHERE o.type = 'P'\\n    AND m.definition LIKE '%xp_fileexist%' COLLATE Latin1_General_BIN\\n  UNION ALL\\n  SELECT OBJECT_NAME(m.object_id), 'xp_dirtree'\\n  FROM sys.sql_modules m\\n  JOIN sys.objects o ON m.object_id = o.object_id\\n  WHERE o.type = 'P'\\n    AND m.definition LIKE '%xp_dirtree%' COLLATE Latin1_General_BIN\\n  UNION ALL\\n  SELECT OBJECT_NAME(m.object_id), 'xp_subdirs'\\n  FROM sys.sql_modules m\\n  JOIN sys.objects o ON m.object_id = o.object_id\\n  WHERE o.type = 'P'\\n    AND m.definition LIKE '%xp_subdirs%' COLLATE Latin1_General_BIN\\n) refs\\nGROUP BY xproc_name\\nHAVING COUNT(DISTINCT calling_proc) >= :min_dependents"}	{"condition": "row_count > 0", "description": "Extended stored procedures referenced by multiple stored procedures — widespread dependency creates high refactoring barrier"}	{"min_dependents": 3}	2026-02-23 20:18:31.390879
3260	sqlserver	query	Check SQL Agent jobs for xproc usage in job steps	{"sql": "SELECT j.name AS job_name, j.enabled AS job_enabled,\\n  js.step_name, js.subsystem, js.command,\\n  CASE\\n    WHEN js.command LIKE '%xp_cmdshell%' THEN 'xp_cmdshell'\\n    WHEN js.command LIKE '%xp_regread%' THEN 'xp_regread'\\n    WHEN js.command LIKE '%xp_fileexist%' THEN 'xp_fileexist'\\n    WHEN js.command LIKE '%xp_dirtree%' THEN 'xp_dirtree'\\n    WHEN js.command LIKE '%xp_subdirs%' THEN 'xp_subdirs'\\n    WHEN js.command LIKE '%xp_fixeddrives%' THEN 'xp_fixeddrives'\\n    WHEN js.command LIKE '%xp_servicecontrol%' THEN 'xp_servicecontrol'\\n    WHEN js.command LIKE '%xp_readerrorlog%' THEN 'xp_readerrorlog'\\n    ELSE 'other_xproc'\\n  END AS xproc_used\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nWHERE js.subsystem = 'TSQL'\\n  AND (js.command LIKE '%xp_cmdshell%' COLLATE Latin1_General_BIN\\n    OR js.command LIKE '%xp_regread%' COLLATE Latin1_General_BIN\\n    OR js.command LIKE '%xp_fileexist%' COLLATE Latin1_General_BIN\\n    OR js.command LIKE '%xp_dirtree%' COLLATE Latin1_General_BIN\\n    OR js.command LIKE '%xp_subdirs%' COLLATE Latin1_General_BIN\\n    OR js.command LIKE '%xp_fixeddrives%' COLLATE Latin1_General_BIN\\n    OR js.command LIKE '%xp_servicecontrol%' COLLATE Latin1_General_BIN\\n    OR js.command LIKE '%xp_readerrorlog%' COLLATE Latin1_General_BIN)"}	{"condition": "row_count > 0", "description": "SQL Agent jobs using extended stored procedures — operational automation depends on xprocs"}	null	2026-02-23 20:18:31.390879
13722	mariadb	query	Check for long-running queries holding locks	{"sql": "SELECT id, user, host, db, command, time AS duration_seconds, state, LEFT(info, 200) AS query_preview FROM information_schema.PROCESSLIST WHERE COMMAND = 'Query' AND TIME > 60 ORDER BY TIME DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Long-running queries may hold locks blocking replication"}	{"duration_threshold_seconds": 60}	2026-05-11 22:17:39.229791
4104	postgresql	query	Verify replication user has proper role	{"sql": "SELECT rolname, rolreplication, rolcanlogin FROM pg_roles WHERE rolreplication = true"}	{"condition": "row_count = 0", "description": "No roles with replication privilege exist"}	\N	2026-02-25 00:28:52.405273
4106	postgresql	query	Check for write-attempting sessions	{"sql": "SELECT pid, usename, application_name, client_addr, query FROM pg_stat_activity WHERE state = 'active' AND backend_type = 'client backend' AND query ~* '^(INSERT|UPDATE|DELETE|CREATE|ALTER|DROP|TRUNCATE)'"}	{"condition": "row_count > 0", "description": "Write attempts on standby causing errors; application misconfigured"}	\N	2026-02-25 00:28:52.405273
3261	sqlserver	query	Check EXECUTE permissions on dangerous xprocs granted to non-sysadmin users	{"sql": "SELECT dp.name AS grantee_name, dp.type_desc AS principal_type,\\n  p.permission_name, p.state_desc,\\n  OBJECT_NAME(p.major_id) AS xproc_name\\nFROM master.sys.database_permissions p\\nJOIN master.sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\nWHERE p.permission_name = 'EXECUTE'\\n  AND p.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\n  AND OBJECT_NAME(p.major_id) IN (\\n    'xp_cmdshell', 'xp_regread', 'xp_regwrite', 'xp_regdeletevalue',\\n    'xp_regdeletekey', 'xp_fileexist', 'xp_subdirs', 'xp_dirtree',\\n    'xp_fixeddrives', 'xp_servicecontrol', 'xp_enumerrorlogs'\\n  )\\n  AND dp.name NOT IN ('dbo', 'public')"}	{"condition": "row_count > 0", "description": "Non-default principals have explicit EXECUTE on dangerous xprocs — privilege controls insufficient"}	null	2026-02-23 20:18:31.39088
3262	sqlserver	query	Check if xp_cmdshell proxy account is configured (weakens privilege model)	{"sql": "SELECT c.credential_id, c.name AS credential_name,\\n  c.credential_identity, c.create_date\\nFROM master.sys.credentials c\\nWHERE c.name = '##xp_cmdshell_proxy_account##'"}	{"condition": "row_count > 0", "description": "xp_cmdshell proxy account configured — allows non-sysadmin execution of OS commands, weakening privilege controls"}	null	2026-02-23 20:18:31.39088
3331	sqlserver	query	Check column master key store providers and configuration	{"sql": "SELECT cmk.name AS master_key_name, cmk.key_store_provider_name,\\n  cmk.key_path, cmk.create_date, cmk.modify_date,\\n  CASE cmk.key_store_provider_name\\n    WHEN 'MSSQL_CERTIFICATE_STORE' THEN 'Windows Certificate Store'\\n    WHEN 'AZURE_KEY_VAULT' THEN 'Azure Key Vault'\\n    WHEN 'MSSQL_CNG_STORE' THEN 'CNG Provider'\\n    WHEN 'MSSQL_CSP_PROVIDER' THEN 'CSP Provider'\\n    ELSE 'Unknown'\\n  END AS store_description\\nFROM sys.column_master_keys cmk\\nORDER BY cmk.name"}	{"condition": "column master keys using local certificate stores", "description": "Column master keys stored in local Windows Certificate Store lack centralized management, rotation, and access auditing compared to Azure Key Vault"}	null	2026-02-23 20:18:31.390921
3273	sqlserver	query	Identify application names associated with xproc usage	{"sql": "SELECT s.program_name, s.host_name, s.login_name,\\n  COUNT(DISTINCT r.session_id) AS active_sessions,\\n  MAX(s.last_request_start_time) AS last_activity\\nFROM sys.dm_exec_sessions s\\nLEFT JOIN sys.dm_exec_requests r ON s.session_id = r.session_id\\nWHERE s.is_user_process = 1\\n  AND s.program_name IS NOT NULL\\n  AND s.program_name <> ''\\n  AND s.program_name NOT LIKE '%Microsoft SQL Server Management Studio%'\\n  AND s.program_name NOT LIKE '%sqlcmd%'\\n  AND s.program_name NOT LIKE '%SQLCMD%'\\n  AND s.program_name NOT LIKE '%SQLAgent%'\\nGROUP BY s.program_name, s.host_name, s.login_name\\nHAVING COUNT(*) > 0"}	{"condition": "row_count > 0", "description": "Third-party application connections identified — cross-reference with step 1 xproc usage to determine which applications depend on xprocs"}	null	2026-02-23 20:18:31.390882
3278	sqlserver	query	Check for rootcause or broad execute permissions on injection entry points	{"sql": "SELECT dp.name AS grantee_name,\\n  OBJECT_SCHEMA_NAME(p.major_id) AS schema_name,\\n  OBJECT_NAME(p.major_id) AS proc_name,\\n  p.state_desc\\nFROM sys.database_permissions p\\nJOIN sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\nJOIN sys.sql_modules m ON p.major_id = m.object_id\\nWHERE p.permission_name = 'EXECUTE'\\n  AND (m.definition LIKE '%EXEC(%+%@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC (@%' COLLATE Latin1_General_BIN\\n    OR m.definition LIKE '%EXEC(@%' COLLATE Latin1_General_BIN)\\n  AND dp.name IN ('public', 'guest')\\n  AND p.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')"}	{"condition": "row_count > 0", "description": "Public or guest can execute dynamic SQL procedures — maximizes injection chaining attack surface"}	null	2026-02-23 20:18:31.390884
3279	sqlserver	query	Check for partially disabled xproc configuration	{"sql": "SELECT\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n    WHERE name = 'xp_cmdshell') AS xp_cmdshell_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations\\n    WHERE name = 'Ole Automation Procedures') AS ole_auto_enabled,\\n  (SELECT COUNT(*) FROM master.sys.credentials\\n    WHERE name = '##xp_cmdshell_proxy_account##') AS proxy_account_exists,\\n  (SELECT COUNT(*) FROM master.sys.database_permissions p\\n    JOIN master.sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\\n    WHERE p.permission_name = 'EXECUTE'\\n      AND OBJECT_NAME(p.major_id) LIKE 'xp_%'\\n      AND dp.name NOT IN ('dbo', 'public')) AS explicit_xproc_grants"}	{"condition": "(xp_cmdshell_enabled = 0 AND (proxy_account_exists > 0 OR explicit_xproc_grants > 0)) OR (xp_cmdshell_enabled = 0 AND ole_auto_enabled = 1)", "description": "Incomplete removal — xp_cmdshell disabled but proxy account still exists, grants remain, or OLE Automation still enabled"}	null	2026-02-23 20:18:31.390884
3280	sqlserver	query	Check for user-defined extended stored procedures not removed	{"sql": "SELECT o.name AS xproc_name, o.create_date,\\n  SCHEMA_NAME(o.schema_id) AS schema_name,\\n  (SELECT COUNT(*) FROM sys.sql_modules m2\\n    JOIN sys.objects o2 ON m2.object_id = o2.object_id\\n    WHERE o2.type = 'P'\\n      AND m2.definition LIKE '%' + o.name + '%') AS referencing_procs\\nFROM sys.objects o\\nWHERE o.type = 'X'\\n  AND o.is_ms_shipped = 0"}	{"condition": "row_count > 0", "description": "User-defined extended stored procedures still registered — removal was not validated or completed"}	null	2026-02-23 20:18:31.390885
3318	sqlserver	query	Check if any Always Encrypted keys exist	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.column_master_keys) AS cmk_count,\\n  (SELECT COUNT(*) FROM sys.column_encryption_keys) AS cek_count,\\n  (SELECT COUNT(*) FROM sys.columns WHERE encryption_type IS NOT NULL) AS encrypted_column_count"}	{"condition": "cmk_count = 0 AND cek_count = 0 AND encrypted_column_count = 0", "description": "Always Encrypted is available but completely unused — no column master keys, no column encryption keys, no encrypted columns"}	null	2026-02-23 20:18:31.390914
3284	sqlserver	query	Check for connections from non-private (potentially rootcause) IP addresses	{"sql": "SELECT c.client_net_address,\\n  s.login_name, s.program_name, s.host_name,\\n  c.auth_scheme, c.encrypt_option,\\n  s.login_time,\\n  COUNT(*) AS connection_count\\nFROM sys.dm_exec_connections c\\nJOIN sys.dm_exec_sessions s ON c.session_id = s.session_id\\nWHERE s.is_user_process = 1\\n  AND c.client_net_address IS NOT NULL\\n  AND c.client_net_address <> '<local machine>'\\n  AND c.client_net_address NOT LIKE '10.%'\\n  AND c.client_net_address NOT LIKE '172.1[6-9].%'\\n  AND c.client_net_address NOT LIKE '172.2[0-9].%'\\n  AND c.client_net_address NOT LIKE '172.3[0-1].%'\\n  AND c.client_net_address NOT LIKE '192.168.%'\\n  AND c.client_net_address NOT LIKE '127.%'\\n  AND c.client_net_address NOT LIKE 'fe80:%'\\n  AND c.client_net_address NOT LIKE '::1'\\n  AND c.client_net_address NOT LIKE 'fd%'\\n  AND c.client_net_address NOT LIKE 'fc%'\\nGROUP BY c.client_net_address, s.login_name,\\n  s.program_name, s.host_name, c.auth_scheme,\\n  c.encrypt_option, s.login_time\\nORDER BY connection_count DESC"}	{"condition": "row_count > 0", "description": "Connections from non-RFC1918 IP addresses — database accessible from outside private network, firewall/security groups too permissive"}	null	2026-02-23 20:18:31.390888
3286	sqlserver	query	Check listener exposure on default port and non-default ports	{"sql": "SELECT ip_address, port, type_desc, state_desc\\nFROM sys.dm_tcp_listener_states\\nWHERE state_desc = 'ONLINE'\\n  AND (ip_address = '0.0.0.0' OR ip_address = '::')\\n  AND port = 1433"}	{"condition": "row_count > 0", "description": "SQL Server listening on default port 1433 on all interfaces — most commonly targeted by automated scanners"}	null	2026-02-23 20:18:31.39089
3560	postgresql	query	Check role-level parameter overrides	{"sql": "SELECT rolname, rolconfig FROM pg_roles WHERE rolconfig IS NOT NULL AND array_length(rolconfig, 1) > 0 ORDER BY rolname"}	{"condition": "row_count > 0", "description": "Role-level parameter overrides exist — may differ across environments"}	\N	2026-02-25 00:28:52.405273
3287	sqlserver	query	Check linked servers pointing to cloud endpoints	{"sql": "SELECT s.name AS linked_server_name,\\n  s.data_source,\\n  s.provider,\\n  s.product,\\n  s.catalog,\\n  l.remote_name,\\n  s.is_data_access_enabled,\\n  s.is_rpc_out_enabled\\nFROM sys.servers s\\nLEFT JOIN sys.linked_logins l ON s.server_id = l.server_id\\nWHERE s.is_linked = 1\\n  AND (s.data_source LIKE '%.database.windows.net%'\\n    OR s.data_source LIKE '%.database.azure.com%'\\n    OR s.data_source LIKE '%.rds.amazonaws.com%'\\n    OR s.data_source LIKE '%.sql.azuresynapse.net%'\\n    OR s.data_source LIKE '%.cosmos.azure.com%'\\n    OR s.data_source LIKE '%.cloud.google.com%'\\n    OR s.data_source LIKE '%.googleapis.com%')"}	{"condition": "rows returned with cloud endpoint data_source", "description": "Linked servers configured to connect to cloud database services — outbound connections required for replication or distributed queries"}	null	2026-02-23 20:18:31.390891
3288	sqlserver	query	Check availability group listeners for cross-network replicas	{"sql": "SELECT ag.name AS ag_name,\\n  ar.replica_server_name,\\n  ar.endpoint_url,\\n  ar.availability_mode_desc,\\n  agl.dns_name AS listener_dns_name,\\n  agl.port AS listener_port,\\n  ars.connected_state_desc,\\n  ars.role_desc\\nFROM sys.availability_groups ag\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nLEFT JOIN sys.availability_group_listeners agl ON ag.group_id = agl.group_id\\nLEFT JOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nWHERE ar.replica_server_name NOT LIKE '%' + CAST(SERVERPROPERTY('MachineName') AS NVARCHAR(128)) + '%'"}	{"condition": "remote replicas found with external endpoint URLs", "description": "Availability group replicas on remote servers requiring outbound network connections for log shipping and synchronization"}	null	2026-02-23 20:18:31.390892
3289	sqlserver	query	Check for external data source definitions (PolyBase/external tables)	{"sql": "SELECT ds.name AS data_source_name,\\n  ds.type_desc,\\n  ds.location,\\n  ds.credential_id,\\n  c.name AS credential_name\\nFROM sys.external_data_sources ds\\nLEFT JOIN sys.database_scoped_credentials c ON ds.credential_id = c.credential_id\\nWHERE ds.location LIKE 'https://%'\\n  OR ds.location LIKE 'wasbs://%'\\n  OR ds.location LIKE 'abfss://%'\\n  OR ds.location LIKE 'adl://%'\\n  OR ds.location LIKE 's3://%'"}	{"condition": "external data sources pointing to cloud storage or services", "description": "PolyBase or external table configurations requiring outbound connections to cloud storage (Azure Blob, ADLS, S3)"}	null	2026-02-23 20:18:31.390893
3290	sqlserver	query	Check xp_cmdshell enablement	{"sql": "SELECT name, value_in_use\\nFROM sys.configurations\\nWHERE name = 'xp_cmdshell'"}	{"condition": "value_in_use = 1", "description": "xp_cmdshell is enabled — allows arbitrary OS command execution from T-SQL, including network utilities (curl, bcp, sqlcmd to remote, PowerShell Invoke-WebRequest)"}	null	2026-02-23 20:18:31.390893
3291	sqlserver	query	Check CLR assemblies with external access permissions	{"sql": "SELECT a.name AS assembly_name,\\n  a.permission_set_desc,\\n  a.clr_name,\\n  a.create_date,\\n  a.modify_date,\\n  p.name AS owner_name\\nFROM sys.assemblies a\\nJOIN sys.database_principals p ON a.principal_id = p.principal_id\\nWHERE a.permission_set_desc IN ('EXTERNAL_ACCESS', 'UNSAFE')\\n  AND a.is_user_defined = 1"}	{"condition": "user-defined assemblies with EXTERNAL_ACCESS or UNSAFE permission", "description": "CLR assemblies with elevated permissions can make outbound HTTP calls, access file system, or open network sockets"}	null	2026-02-23 20:18:31.390894
3292	sqlserver	query	Check SQL Agent jobs with external command steps or mail profiles	{"sql": "SELECT j.name AS job_name,\\n  j.enabled AS job_enabled,\\n  js.step_name,\\n  js.subsystem,\\n  js.command,\\n  j.date_created,\\n  j.date_modified\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nWHERE js.subsystem IN ('CmdExec', 'PowerShell', 'SSIS')\\n  OR js.command LIKE '%Invoke-WebRequest%'\\n  OR js.command LIKE '%curl%'\\n  OR js.command LIKE '%bcp%out%'\\n  OR js.command LIKE '%sqlcmd%-S%'\\n  OR js.command LIKE '%xp_cmdshell%'\\n  OR js.command LIKE '%sp_send_dbmail%'\\nORDER BY j.enabled DESC, j.date_modified DESC"}	{"condition": "Agent job steps with CmdExec, PowerShell, SSIS subsystems or commands containing external transfer utilities", "description": "SQL Agent jobs capable of executing external commands or transferring data outside the server"}	null	2026-02-23 20:18:31.390895
3293	sqlserver	query	Check Database Mail configuration for external SMTP	{"sql": "SELECT p.name AS profile_name,\\n  a.name AS account_name,\\n  a.email_address,\\n  s.servername AS smtp_server,\\n  s.port AS smtp_port,\\n  s.enable_ssl\\nFROM msdb.dbo.sysmail_profile p\\nJOIN msdb.dbo.sysmail_profileaccount pa ON p.profile_id = pa.profile_id\\nJOIN msdb.dbo.sysmail_account a ON pa.account_id = a.account_id\\nJOIN msdb.dbo.sysmail_server s ON a.account_id = s.account_id"}	{"condition": "Database Mail profiles with external SMTP servers configured", "description": "Database Mail can be used to exfiltrate data via email attachments or message bodies through configured SMTP relays"}	null	2026-02-23 20:18:31.390896
3472	postgresql	log_scan	Scan for missing metadata errors	{"pattern": "backup_manifest.*missing|could not open.*backup_label|missing.*pg_control|backup_label.*not found|tablespace_map.*not found", "description": "Missing backup metadata or control files"}	{"condition": "pattern_found", "description": "Required backup metadata files are missing"}	\N	2026-02-25 00:28:52.405273
3294	sqlserver	query	Retrieve SQL Server version and build information	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  SERVERPROPERTY('ProductMinorVersion') AS minor_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS update_level,\\n  SERVERPROPERTY('Edition') AS edition,\\n  @@VERSION AS full_version_string,\\n  CASE CAST(SERVERPROPERTY('ProductMajorVersion') AS INT)\\n    WHEN 10 THEN 'SQL Server 2008/2008R2 — EXTENDED SUPPORT ENDED 2019-07-09'\\n    WHEN 11 THEN 'SQL Server 2012 — EXTENDED SUPPORT ENDED 2022-07-12'\\n    WHEN 12 THEN 'SQL Server 2014 — EXTENDED SUPPORT ENDED 2024-07-09'\\n    WHEN 13 THEN 'SQL Server 2016 — EXTENDED SUPPORT ENDS 2026-07-14'\\n    WHEN 14 THEN 'SQL Server 2017 — EXTENDED SUPPORT ENDS 2027-10-12'\\n    WHEN 15 THEN 'SQL Server 2019 — MAINSTREAM SUPPORT ENDS 2025-02-28, EXTENDED 2030-01-08'\\n    WHEN 16 THEN 'SQL Server 2022 — MAINSTREAM SUPPORT ENDS 2028-01-11, EXTENDED 2033-01-11'\\n    ELSE 'Unknown version — verify manually'\\n  END AS lifecycle_status"}	{"condition": "major_version <= 12 (EOL) or major_version = 13 (extended support ending 2026)", "description": "SQL Server is running an end-of-life version (2008, 2008R2, 2012, 2014) or nearing end of extended support (2016)"}	null	2026-02-23 20:18:31.390896
3312	sqlserver	query	Check TDE status across databases	{"sql": "SELECT d.name AS database_name,\\n  dek.encryption_state,\\n  CASE dek.encryption_state\\n    WHEN 0 THEN 'No encryption'\\n    WHEN 1 THEN 'Unencrypted'\\n    WHEN 2 THEN 'Encryption in progress'\\n    WHEN 3 THEN 'Encrypted'\\n    WHEN 4 THEN 'Key change in progress'\\n    WHEN 5 THEN 'Decryption in progress'\\n    WHEN 6 THEN 'Protection change in progress'\\n  END AS encryption_state_desc,\\n  dek.key_algorithm, dek.key_length\\nFROM sys.databases d\\nLEFT JOIN sys.dm_database_encryption_keys dek ON d.database_id = dek.database_id\\nWHERE d.database_id > 4"}	{"condition": "encryption_state = 3 (TDE enabled on at least one database)", "description": "TDE is enabled — need to check if column-level encryption also exists"}	null	2026-02-23 20:18:31.390897
3561	postgresql	query	Map parameter source hierarchy	{"sql": "SELECT name, setting, source, sourcefile, sourceline FROM pg_settings WHERE source NOT IN ('default', 'override') ORDER BY source, name"}	{"condition": "row_count > 0", "description": "Non-default parameters from multiple sources — potential inheritance conflicts"}	\N	2026-02-25 00:28:52.405273
3356	sqlserver	query	Check ERRORLOG file location and default trace files	{"sql": "SELECT 'ERRORLOG' AS log_type,\\n  SERVERPROPERTY('ErrorLogFileName') AS file_path\\nUNION ALL\\nSELECT 'DefaultTrace' AS log_type,\\n  path AS file_path\\nFROM sys.traces\\nWHERE is_default = 1 AND status = 1"}	{"condition": "log file paths returned", "description": "ERRORLOG and default trace file locations identified — verify OS-level ACLs restrict read access to authorized administrators only"}	null	2026-02-23 20:18:31.390935
3295	sqlserver	query	Check major version distance from current release	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS current_major,\\n  16 AS latest_major_version,\\n  16 - CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS versions_behind,\\n  CASE CAST(SERVERPROPERTY('ProductMajorVersion') AS INT)\\n    WHEN 10 THEN 'SQL Server 2008/2008R2 — 6 major versions behind'\\n    WHEN 11 THEN 'SQL Server 2012 — 5 major versions behind'\\n    WHEN 12 THEN 'SQL Server 2014 — 4 major versions behind'\\n    WHEN 13 THEN 'SQL Server 2016 — 3 major versions behind'\\n    WHEN 14 THEN 'SQL Server 2017 — 2 major versions behind'\\n    WHEN 15 THEN 'SQL Server 2019 — 1 major version behind'\\n    WHEN 16 THEN 'SQL Server 2022 — current release'\\n    ELSE 'Unknown version'\\n  END AS version_assessment,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level"}	{"condition": "versions_behind >= 2", "description": "SQL Server instance is 2+ major versions behind the current release, indicating deferred upgrades likely due to technical complexity"}	null	2026-02-23 20:18:31.390898
3296	sqlserver	query	Check deprecated feature usage counters	{"sql": "SELECT instance_name AS deprecated_feature,\\n  cntr_value AS usage_count\\nFROM sys.dm_os_performance_counters\\nWHERE object_name LIKE '%Deprecated Features%'\\n  AND cntr_value > 0\\nORDER BY cntr_value DESC"}	{"condition": "rows returned with cntr_value > 0", "description": "Deprecated features are actively being used — these features may be removed in future versions, blocking upgrades"}	null	2026-02-23 20:18:31.390899
3297	sqlserver	query	Check for high-impact deprecated feature categories	{"sql": "SELECT instance_name AS deprecated_feature,\\n  cntr_value AS usage_count,\\n  CASE\\n    WHEN instance_name LIKE '%STRING_ESCAPE%' THEN 'syntax'\\n    WHEN instance_name LIKE '%compatibility%' THEN 'compatibility'\\n    WHEN instance_name LIKE '%DATABASEPROPERTY%' THEN 'metadata-function'\\n    WHEN instance_name LIKE '%SET ROWCOUNT%' THEN 'syntax'\\n    WHEN instance_name LIKE '%RAISERROR%' THEN 'syntax'\\n    WHEN instance_name LIKE '%sp_addtype%' THEN 'system-proc'\\n    WHEN instance_name LIKE '%ntext%' THEN 'data-type'\\n    WHEN instance_name LIKE '%image%' THEN 'data-type'\\n    WHEN instance_name LIKE '%text%' THEN 'data-type'\\n    ELSE 'other'\\n  END AS category\\nFROM sys.dm_os_performance_counters\\nWHERE object_name LIKE '%Deprecated Features%'\\n  AND cntr_value > 1000\\nORDER BY cntr_value DESC"}	{"condition": "deprecated features with usage_count > 1000", "description": "Heavily used deprecated features indicate deep application dependency that would require significant code changes before upgrading"}	null	2026-02-23 20:18:31.3909
3298	sqlserver	query	Check TDS protocol versions of active connections	{"sql": "SELECT\\n  c.protocol_version,\\n  CASE\\n    WHEN c.protocol_version >= 1946157060 THEN 'TDS 7.4 (SQL Server 2012+)'\\n    WHEN c.protocol_version >= 1912602624 THEN 'TDS 7.3B (SQL Server 2008R2)'\\n    WHEN c.protocol_version >= 1879048192 THEN 'TDS 7.3A (SQL Server 2008)'\\n    WHEN c.protocol_version >= 1845493760 THEN 'TDS 7.2 (SQL Server 2005)'\\n    WHEN c.protocol_version >= 1811939328 THEN 'TDS 7.1 (SQL Server 2000)'\\n    ELSE 'TDS 7.0 or older'\\n  END AS tds_version_desc,\\n  COUNT(*) AS connection_count,\\n  COUNT(DISTINCT c.client_net_address) AS distinct_clients\\nFROM sys.dm_exec_connections c\\nWHERE c.protocol_version IS NOT NULL\\nGROUP BY c.protocol_version\\nORDER BY c.protocol_version ASC"}	{"condition": "connections with protocol_version < 1946157060 (pre-TDS 7.4)", "description": "Clients using TDS protocol versions older than 7.4, indicating legacy drivers that may not support newer SQL Server features or versions"}	null	2026-02-23 20:18:31.390901
3299	sqlserver	query	Identify specific legacy client applications and drivers	{"sql": "SELECT\\n  s.program_name,\\n  s.client_interface_name,\\n  c.protocol_version,\\n  c.client_net_address,\\n  COUNT(*) AS sessions\\nFROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE c.protocol_version < 1946157060\\n  AND s.is_user_process = 1\\nGROUP BY s.program_name, s.client_interface_name,\\n  c.protocol_version, c.client_net_address\\nORDER BY sessions DESC"}	{"condition": "specific applications or drivers using old TDS versions", "description": "Legacy applications or drivers identified that would need updating before a SQL Server version upgrade"}	null	2026-02-23 20:18:31.390902
3300	sqlserver	query	Check for deprecated syntax patterns in plan cache	{"sql": "SELECT TOP 20\\n  qs.execution_count,\\n  qs.last_execution_time,\\n  SUBSTRING(qt.text, 1, 200) AS query_fragment,\\n  DB_NAME(qt.dbid) AS database_name\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) qt\\nWHERE (qt.text LIKE '%SET ROWCOUNT%'\\n  OR qt.text LIKE '%RAISERROR %,%,%'\\n  OR qt.text LIKE '%sp_addtype%'\\n  OR qt.text LIKE '%DATABASEPROPERTY(%'\\n  OR qt.text LIKE '%::fn_virtualfilestats%')\\n  AND qt.dbid > 4\\nORDER BY qs.execution_count DESC"}	{"condition": "cached queries using deprecated syntax patterns", "description": "Application queries actively using deprecated T-SQL syntax that would break or behave differently at higher compatibility levels"}	null	2026-02-23 20:18:31.390902
3301	sqlserver	query	Check if instance is 3+ major versions behind	{"sql": "SELECT\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS current_major,\\n  16 AS latest_major_version,\\n  16 - CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS versions_behind,\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS cumulative_update"}	{"condition": "versions_behind >= 3", "description": "Instance is 3+ major versions behind (SQL Server 2016 or older on current timeline), indicating neglect across multiple release cycles"}	null	2026-02-23 20:18:31.390903
3313	sqlserver	query	Check for absence of Always Encrypted column master keys	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.column_master_keys) AS column_master_key_count,\\n  (SELECT COUNT(*) FROM sys.column_encryption_keys) AS column_encryption_key_count,\\n  (SELECT COUNT(*) FROM sys.column_encryption_key_values) AS cek_value_count"}	{"condition": "column_master_key_count = 0 AND column_encryption_key_count = 0", "description": "No Always Encrypted infrastructure exists — TDE is the only encryption, leaving PII exposed in queries, memory, and network traffic"}	null	2026-02-23 20:18:31.390904
3562	postgresql	query	Check for parameters set at multiple levels	{"sql": "SELECT name, setting, source FROM pg_settings WHERE name IN (SELECT name FROM pg_settings WHERE sourcefile LIKE '%auto%') AND source != 'configuration file' ORDER BY name, source"}	{"condition": "row_count > 0", "description": "Same parameter set at multiple inheritance levels — potential confusion"}	\N	2026-02-25 00:28:52.405273
3302	sqlserver	query	Check for evidence of minimal configuration management	{"sql": "SELECT\\n  si.sqlserver_start_time,\\n  DATEDIFF(DAY, si.sqlserver_start_time, GETDATE()) AS days_since_restart,\\n  (SELECT COUNT(*) FROM sys.configurations WHERE value <> value_in_use) AS pending_config_changes,\\n  (SELECT COUNT(*) FROM sys.databases WHERE state_desc <> 'ONLINE' AND database_id > 4) AS non_online_dbs,\\n  (SELECT MAX(backup_finish_date) FROM msdb.dbo.backupset WHERE type = 'D') AS last_full_backup,\\n  DATEDIFF(DAY, (SELECT MAX(backup_finish_date) FROM msdb.dbo.backupset WHERE type = 'D'), GETDATE()) AS days_since_last_backup\\nFROM sys.dm_os_sys_info si"}	{"condition": "days_since_restart > 180 or days_since_last_backup > 30 or non_online_dbs > 0", "description": "Signs of minimal active management: long uptime without patching, stale backups, or neglected databases reinforce incremental neglect pattern"}	null	2026-02-23 20:18:31.390905
3303	sqlserver	query	Check current build version and patch level	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS product_update_level,\\n  SERVERPROPERTY('ProductBuildType') AS product_build_type,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  SERVERPROPERTY('Edition') AS edition"}	{"condition": "product_update_level is NULL or indicates an older CU", "description": "Instance not on latest cumulative update — ProductUpdateLevel shows current CU number"}	null	2026-02-23 20:18:31.390905
3304	sqlserver	query	Check instance uptime since last restart	{"sql": "SELECT\\n  sqlserver_start_time,\\n  DATEDIFF(DAY, sqlserver_start_time, GETDATE()) AS uptime_days,\\n  DATEDIFF(HOUR, sqlserver_start_time, GETDATE()) AS uptime_hours\\nFROM sys.dm_os_sys_info"}	{"condition": "uptime_days > 90", "description": "Instance has not been restarted in over 90 days — patches typically require a restart, so extended uptime suggests missing patches"}	null	2026-02-23 20:18:31.390906
3305	sqlserver	query	Check database compatibility levels across all databases	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  CASE\\n    WHEN d.compatibility_level = 80 THEN 'SQL Server 2000'\\n    WHEN d.compatibility_level = 90 THEN 'SQL Server 2005'\\n    WHEN d.compatibility_level = 100 THEN 'SQL Server 2008'\\n    WHEN d.compatibility_level = 110 THEN 'SQL Server 2012'\\n    WHEN d.compatibility_level = 120 THEN 'SQL Server 2014'\\n    WHEN d.compatibility_level = 130 THEN 'SQL Server 2016'\\n    WHEN d.compatibility_level = 140 THEN 'SQL Server 2017'\\n    WHEN d.compatibility_level = 150 THEN 'SQL Server 2019'\\n    WHEN d.compatibility_level = 160 THEN 'SQL Server 2022'\\n    ELSE 'Unknown'\\n  END AS compat_version,\\n  SERVERPROPERTY('ProductMajorVersion') AS current_major_version\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.compatibility_level < (\\n    SELECT CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) * 10\\n  )"}	{"condition": "databases with compatibility_level significantly below current engine version", "description": "Databases running in legacy compatibility mode — may have dependencies on deprecated features that block major version upgrades"}	null	2026-02-23 20:18:31.390907
3306	sqlserver	query	Check linked servers and their provider versions	{"sql": "SELECT s.name AS linked_server_name,\\n  s.product, s.provider, s.data_source,\\n  s.provider_string,\\n  s.is_linked, s.is_remote_login_enabled\\nFROM sys.servers s\\nWHERE s.is_linked = 1"}	{"condition": "linked servers present", "description": "Linked servers create cross-instance dependencies — patching one instance may break linked server queries if provider versions are incompatible"}	null	2026-02-23 20:18:31.390907
3307	sqlserver	query	Check CLR assemblies and their target frameworks	{"sql": "SELECT a.name AS assembly_name,\\n  a.clr_name,\\n  a.permission_set_desc,\\n  a.create_date, a.modify_date,\\n  af.name AS file_name\\nFROM sys.assemblies a\\nJOIN sys.assembly_files af ON a.assembly_id = af.assembly_id\\nWHERE a.is_user_defined = 1"}	{"condition": "user-defined CLR assemblies present", "description": "CLR assemblies compiled against specific .NET framework versions may fail after patching if the CLR host changes"}	null	2026-02-23 20:18:31.390908
3308	sqlserver	query	Check for long-running transactions and active sessions	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process = 1) AS active_user_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_tran_active_transactions t\\n   JOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id\\n   WHERE DATEDIFF(MINUTE, t.transaction_begin_time, GETDATE()) > 30) AS long_running_transactions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_requests WHERE status IN ('running', 'runnable', 'suspended')\\n   AND session_id > 50) AS active_requests"}	{"condition": "active_user_sessions > 50 or long_running_transactions > 0", "description": "Significant active workload that would be disrupted by a restart for patching"}	null	2026-02-23 20:18:31.390908
3309	sqlserver	query	Check Always On AG status requiring coordination for restart	{"sql": "SELECT ag.name AS ag_name,\\n  ar.replica_server_name,\\n  ar.availability_mode_desc,\\n  ar.failover_mode_desc,\\n  ars.role_desc,\\n  ag.required_synchronized_secondaries_to_commit AS required_sync,\\n  (SELECT COUNT(*) FROM sys.availability_replicas ar2\\n   WHERE ar2.group_id = ag.group_id) AS total_replicas\\nFROM sys.availability_groups ag\\nJOIN sys.availability_replicas ar ON ag.group_id = ar.group_id\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nWHERE ars.role_desc = 'PRIMARY'"}	{"condition": "instance is primary in an AG with synchronous commit replicas", "description": "Instance is AG primary — patching requires planned failover to avoid downtime, which adds complexity and risk"}	null	2026-02-23 20:18:31.390909
3310	sqlserver	query	Check build version staleness and update branch	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS product_version,\\n  SERVERPROPERTY('ProductLevel') AS product_level,\\n  SERVERPROPERTY('ProductUpdateLevel') AS product_update_level,\\n  SERVERPROPERTY('ProductBuildType') AS product_build_type,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  CASE\\n    WHEN SERVERPROPERTY('ProductBuildType') = 'GDR' THEN 'Security-only branch (minimal patches)'\\n    WHEN SERVERPROPERTY('ProductBuildType') = 'OD' THEN 'Cumulative Update branch (full patches)'\\n    ELSE 'Unknown branch'\\n  END AS branch_description"}	{"condition": "ProductUpdateLevel indicates an older CU or ProductBuildType is GDR", "description": "Instance is behind on cumulative updates or on the GDR branch receiving only critical security fixes"}	null	2026-02-23 20:18:31.39091
3311	sqlserver	query	Check uptime as proxy for last patch application	{"sql": "SELECT\\n  sqlserver_start_time,\\n  DATEDIFF(DAY, sqlserver_start_time, GETDATE()) AS days_since_restart,\\n  CASE\\n    WHEN DATEDIFF(DAY, sqlserver_start_time, GETDATE()) > 180 THEN 'CRITICAL: Over 6 months since restart'\\n    WHEN DATEDIFF(DAY, sqlserver_start_time, GETDATE()) > 90 THEN 'WARNING: Over 3 months since restart'\\n    ELSE 'OK: Restarted within last 90 days'\\n  END AS patch_staleness\\nFROM sys.dm_os_sys_info"}	{"condition": "days_since_restart > 90", "description": "Long uptime combined with older CU suggests patches are being skipped for rarely-exploited vulnerabilities"}	null	2026-02-23 20:18:31.39091
5901	postgresql	query	Verify file_fdw extension not adding additional file access	{"sql": "SELECT extname FROM pg_extension WHERE extname = 'file_fdw'"}	{"condition": "row_count > 0", "description": "file_fdw installed — provides additional file read capability without COPY"}	\N	2026-02-25 00:28:52.405273
3314	sqlserver	query	Check for columns with PII-like names that are unprotected	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE\\nFROM INFORMATION_SCHEMA.COLUMNS c\\nJOIN INFORMATION_SCHEMA.TABLES t ON c.TABLE_SCHEMA = t.TABLE_SCHEMA\\n  AND c.TABLE_NAME = t.TABLE_NAME\\nWHERE t.TABLE_TYPE = 'BASE TABLE'\\n  AND (\\n    c.COLUMN_NAME LIKE '%ssn%'\\n    OR c.COLUMN_NAME LIKE '%social_security%'\\n    OR c.COLUMN_NAME LIKE '%credit_card%'\\n    OR c.COLUMN_NAME LIKE '%card_number%'\\n    OR c.COLUMN_NAME LIKE '%tax_id%'\\n    OR c.COLUMN_NAME LIKE '%passport%'\\n    OR c.COLUMN_NAME LIKE '%driver_license%'\\n    OR c.COLUMN_NAME LIKE '%national_id%'\\n    OR c.COLUMN_NAME LIKE '%bank_account%'\\n    OR c.COLUMN_NAME LIKE '%routing_number%'\\n    OR c.COLUMN_NAME LIKE '%date_of_birth%'\\n    OR c.COLUMN_NAME LIKE '%dob%'\\n    OR c.COLUMN_NAME LIKE '%email%'\\n    OR c.COLUMN_NAME LIKE '%phone%'\\n  )"}	{"condition": "PII-named columns found without encryption", "description": "Columns with PII-like names exist in unencrypted form — TDE alone does not protect this data from authorized users or in-memory access"}	null	2026-02-23 20:18:31.390911
3315	sqlserver	query	Find PII-named columns that are indexed	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(ic.object_id) AS schema_name,\\n  OBJECT_NAME(ic.object_id) AS table_name,\\n  COL_NAME(ic.object_id, ic.column_id) AS column_name,\\n  i.name AS index_name,\\n  i.type_desc AS index_type,\\n  ic.key_ordinal\\nFROM sys.index_columns ic\\nJOIN sys.indexes i ON ic.object_id = i.object_id AND ic.index_id = i.index_id\\nWHERE i.type > 0\\n  AND (\\n    COL_NAME(ic.object_id, ic.column_id) LIKE '%ssn%'\\n    OR COL_NAME(ic.object_id, ic.column_id) LIKE '%social_security%'\\n    OR COL_NAME(ic.object_id, ic.column_id) LIKE '%credit_card%'\\n    OR COL_NAME(ic.object_id, ic.column_id) LIKE '%card_number%'\\n    OR COL_NAME(ic.object_id, ic.column_id) LIKE '%tax_id%'\\n    OR COL_NAME(ic.object_id, ic.column_id) LIKE '%passport%'\\n    OR COL_NAME(ic.object_id, ic.column_id) LIKE '%email%'\\n    OR COL_NAME(ic.object_id, ic.column_id) LIKE '%phone%'\\n    OR COL_NAME(ic.object_id, ic.column_id) LIKE '%national_id%'\\n  )"}	{"condition": "PII-named columns found in indexes", "description": "PII columns are indexed for search performance — Always Encrypted deterministic encryption supports equality searches but not range queries, LIKE, or ORDER BY"}	null	2026-02-23 20:18:31.390912
4357	postgresql	query	Check for tables with high insert counts but zero deletes	{"sql": "SELECT schemaname, relname, n_live_tup, n_tup_ins, n_tup_del, CASE WHEN n_tup_del = 0 THEN 'no_deletes' ELSE round(n_tup_ins::numeric / GREATEST(n_tup_del, 1), 2)::text END AS insert_delete_ratio FROM pg_stat_user_tables WHERE n_tup_ins > 10000 AND n_tup_del = 0 ORDER BY n_live_tup DESC"}	{"condition": "row_count > 0", "description": "Tables with high inserts and zero deletes confirm no archival or purge process is running"}	\N	2026-02-25 00:28:52.405273
3316	sqlserver	query	Check if Always Encrypted is configured on these columns	{"sql": "SELECT c.name AS column_name,\\n  OBJECT_SCHEMA_NAME(c.object_id) AS schema_name,\\n  OBJECT_NAME(c.object_id) AS table_name,\\n  c.encryption_type,\\n  c.encryption_type_desc,\\n  c.encryption_algorithm_name\\nFROM sys.columns c\\nWHERE c.encryption_type IS NOT NULL\\n  AND (\\n    c.name LIKE '%ssn%'\\n    OR c.name LIKE '%social_security%'\\n    OR c.name LIKE '%credit_card%'\\n    OR c.name LIKE '%card_number%'\\n    OR c.name LIKE '%tax_id%'\\n    OR c.name LIKE '%passport%'\\n    OR c.name LIKE '%email%'\\n    OR c.name LIKE '%phone%'\\n    OR c.name LIKE '%national_id%'\\n  )"}	{"condition": "no rows returned (PII columns not encrypted)", "description": "PII columns are indexed but not encrypted — searchability requirements likely prevented Always Encrypted adoption"}	null	2026-02-23 20:18:31.390912
3317	sqlserver	query	Check if edition supports Always Encrypted	{"sql": "SELECT\\n  SERVERPROPERTY('Edition') AS edition,\\n  SERVERPROPERTY('ProductMajorVersion') AS major_version,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 13\\n      AND (CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Enterprise%'\\n        OR CAST(SERVERPROPERTY('Edition') AS NVARCHAR(128)) LIKE '%Developer%'\\n        OR CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) >= 15)\\n    THEN 'Always Encrypted available'\\n    ELSE 'Always Encrypted not available'\\n  END AS ae_availability"}	{"condition": "Always Encrypted is available (SQL 2016+ Enterprise/Developer, or SQL 2019+ any edition)", "description": "The edition supports Always Encrypted"}	null	2026-02-23 20:18:31.390913
3426	postgresql	log_scan	Scan PostgreSQL log for assertion failures and PANIC	{"pattern": "PANIC:|FATAL.*internal error|Assert.*failed|server process.*was terminated by signal|could not.*shared memory", "description": "PostgreSQL internal consistency check failures and PANIC-level errors"}	{"condition": "pattern_found", "description": "Internal error or assertion failure detected"}	\N	2026-02-25 00:28:52.405273
3319	sqlserver	query	Verify PII-like columns exist that could benefit from encryption	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE\\nFROM INFORMATION_SCHEMA.COLUMNS c\\nJOIN INFORMATION_SCHEMA.TABLES t ON c.TABLE_SCHEMA = t.TABLE_SCHEMA\\n  AND c.TABLE_NAME = t.TABLE_NAME\\nWHERE t.TABLE_TYPE = 'BASE TABLE'\\n  AND (\\n    c.COLUMN_NAME LIKE '%ssn%'\\n    OR c.COLUMN_NAME LIKE '%social_security%'\\n    OR c.COLUMN_NAME LIKE '%credit_card%'\\n    OR c.COLUMN_NAME LIKE '%card_number%'\\n    OR c.COLUMN_NAME LIKE '%tax_id%'\\n    OR c.COLUMN_NAME LIKE '%passport%'\\n    OR c.COLUMN_NAME LIKE '%driver_license%'\\n    OR c.COLUMN_NAME LIKE '%national_id%'\\n    OR c.COLUMN_NAME LIKE '%bank_account%'\\n  )"}	{"condition": "PII-named columns exist", "description": "PII columns present with no encryption — Always Encrypted is available but not deployed, likely due to performance overhead concerns"}	null	2026-02-23 20:18:31.390914
4108	postgresql	query	Check replication role privileges	{"sql": "SELECT rolname, rolreplication, rolcanlogin, rolconnlimit FROM pg_roles WHERE rolreplication = true"}	{"condition": "row_count = 0", "description": "No roles with REPLICATION privilege; standbys cannot connect"}	\N	2026-02-25 00:28:52.405273
4109	postgresql	query	Verify replication user can login	{"sql": "SELECT rolname, rolcanlogin, rolreplication FROM pg_roles WHERE rolreplication = true AND rolcanlogin = false"}	{"condition": "row_count > 0", "description": "Replication role exists but cannot login; useless for replication"}	\N	2026-02-25 00:28:52.405273
3330	sqlserver	query	Check recent bulk operations and SELECT INTO in query plans	{"sql": "SELECT TOP 50\\n  qs.last_execution_time,\\n  SUBSTRING(st.text, 1, 500) AS query_text,\\n  qs.execution_count,\\n  qp.query_plan.exist('//RelOp[@LogicalOp=\\"Insert\\"]') AS has_insert,\\n  qp.query_plan.exist('//RelOp[@LogicalOp=\\"Clustered Index Insert\\"]') AS has_bulk_insert\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE (st.text LIKE '%SELECT%INTO%' OR st.text LIKE '%BULK INSERT%'\\n  OR st.text LIKE '%INSERT%INTO%SELECT%' OR st.text LIKE '%OPENROWSET%')\\n  AND qs.last_execution_time > DATEADD(DAY, -7, GETDATE())\\nORDER BY qs.last_execution_time DESC"}	{"condition": "bulk copy or SELECT INTO operations found in recent plans", "description": "Recent bulk data movement operations detected — these bypass DDM and may copy PII in clear text"}	null	2026-02-23 20:18:31.390915
3328	sqlserver	query	Check for SSIS packages stored in msdb	{"sql": "SELECT p.name AS package_name, p.description,\\n  f.foldername AS folder_name,\\n  p.createdate, p.packageformat\\nFROM msdb.dbo.sysssispackages p\\nLEFT JOIN msdb.dbo.sysssispackagefolders f ON p.folderid = f.folderid\\nORDER BY p.createdate DESC"}	{"condition": "SSIS packages found", "description": "SSIS packages present — ETL pipelines may extract PII data without applying masking transformations"}	null	2026-02-23 20:18:31.390916
3320	sqlserver	query	Find PII-pattern columns stored as plain text types	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(c.object_id) AS schema_name,\\n  OBJECT_NAME(c.object_id) AS table_name,\\n  c.name AS column_name,\\n  ty.name AS data_type,\\n  c.max_length,\\n  c.encryption_type_desc,\\n  mc.is_masked\\nFROM sys.columns c\\nJOIN sys.types ty ON c.user_type_id = ty.user_type_id\\nJOIN sys.objects o ON c.object_id = o.object_id\\nLEFT JOIN sys.masked_columns mc ON c.object_id = mc.object_id AND c.column_id = mc.column_id\\nWHERE o.type = 'U'\\n  AND ty.name IN ('varchar', 'nvarchar', 'char', 'nchar')\\n  AND c.encryption_type IS NULL\\n  AND (mc.is_masked IS NULL OR mc.is_masked = 0)\\n  AND (\\n    c.name LIKE '%ssn%'\\n    OR c.name LIKE '%social_security%'\\n    OR c.name LIKE '%credit_card%'\\n    OR c.name LIKE '%card_number%'\\n    OR c.name LIKE '%tax_id%'\\n    OR c.name LIKE '%passport%'\\n    OR c.name LIKE '%driver_license%'\\n    OR c.name LIKE '%national_id%'\\n    OR c.name LIKE '%bank_account%'\\n    OR c.name LIKE '%routing_number%'\\n  )"}	{"condition": "PII-named columns in plain text types with no encryption or masking", "description": "PII data stored as plain VARCHAR/NVARCHAR without any protection — incorrect data type usage for sensitive information"}	null	2026-02-23 20:18:31.390916
3321	sqlserver	query	Check for SSN-sized columns suggesting plaintext SSN storage	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(c.object_id) AS schema_name,\\n  OBJECT_NAME(c.object_id) AS table_name,\\n  c.name AS column_name,\\n  ty.name AS data_type,\\n  c.max_length\\nFROM sys.columns c\\nJOIN sys.types ty ON c.user_type_id = ty.user_type_id\\nJOIN sys.objects o ON c.object_id = o.object_id\\nWHERE o.type = 'U'\\n  AND c.encryption_type IS NULL\\n  AND (\\n    (c.name LIKE '%ssn%' AND ty.name IN ('char', 'varchar') AND c.max_length BETWEEN 9 AND 11)\\n    OR (c.name LIKE '%credit_card%' AND ty.name IN ('char', 'varchar') AND c.max_length BETWEEN 15 AND 19)\\n    OR (c.name LIKE '%card_number%' AND ty.name IN ('char', 'varchar') AND c.max_length BETWEEN 15 AND 19)\\n  )"}	{"condition": "columns with exact PII-length char types found", "description": "Char columns sized exactly for SSN (9-11) or credit card numbers (15-19) strongly indicate plaintext PII storage"}	null	2026-02-23 20:18:31.390917
3322	sqlserver	query	Check database compatibility level for legacy schema indicators	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  CASE\\n    WHEN d.compatibility_level < 130 THEN 'Pre-2016: Always Encrypted not available at this compat level'\\n    WHEN d.compatibility_level < 150 THEN 'Pre-2019: Always Encrypted Enterprise-only'\\n    ELSE 'Modern: All Always Encrypted features available'\\n  END AS encryption_capability,\\n  d.create_date AS database_created\\nFROM sys.databases d\\nWHERE d.database_id > 4"}	{"condition": "databases with compatibility_level < 130", "description": "Legacy compatibility level indicates schema may predate modern encryption features"}	null	2026-02-23 20:18:31.390917
3323	sqlserver	query	Find PII columns without any encryption in user databases	{"sql": "SELECT\\n  OBJECT_SCHEMA_NAME(c.object_id) AS schema_name,\\n  OBJECT_NAME(c.object_id) AS table_name,\\n  c.name AS column_name,\\n  ty.name AS data_type,\\n  c.encryption_type_desc\\nFROM sys.columns c\\nJOIN sys.types ty ON c.user_type_id = ty.user_type_id\\nJOIN sys.objects o ON c.object_id = o.object_id\\nWHERE o.type = 'U'\\n  AND c.encryption_type IS NULL\\n  AND (\\n    c.name LIKE '%ssn%'\\n    OR c.name LIKE '%social_security%'\\n    OR c.name LIKE '%credit_card%'\\n    OR c.name LIKE '%card_number%'\\n    OR c.name LIKE '%tax_id%'\\n    OR c.name LIKE '%passport%'\\n    OR c.name LIKE '%driver_license%'\\n    OR c.name LIKE '%national_id%'\\n    OR c.name LIKE '%bank_account%'\\n    OR c.name LIKE '%date_of_birth%'\\n    OR c.name LIKE '%dob%'\\n  )"}	{"condition": "PII-named unencrypted columns found", "description": "Legacy tables contain PII columns without modern encryption"}	null	2026-02-23 20:18:31.390918
3326	sqlserver	query	Check for custom masking UDFs and views referencing masked tables	{"sql": "SELECT o.name AS object_name, o.type_desc,\\n  m.definition\\nFROM sys.sql_modules m\\nJOIN sys.objects o ON m.object_id = o.object_id\\nWHERE (m.definition LIKE '%mask%' OR m.definition LIKE '%redact%'\\n  OR m.definition LIKE '%obfuscat%' OR m.definition LIKE '%anonymi%')\\n  AND o.is_ms_shipped = 0\\nORDER BY o.type_desc, o.name"}	{"condition": "custom masking objects found", "description": "In-house masking logic exists — review for completeness and correctness versus native DDM"}	null	2026-02-23 20:18:31.39092
3370	postgresql	query	Find idle-in-transaction sessions	{"sql": "SELECT pid, usename, application_name, client_addr, state, xact_start, state_change, now() - state_change AS idle_duration FROM pg_stat_activity WHERE state = 'idle in transaction' AND backend_type = 'client backend'"}	{"condition": "row_count > 0", "description": "Idle-in-transaction sessions — same detection as RC01"}	\N	2026-02-25 00:28:52.405273
3327	sqlserver	query	Check for users with UNMASK permission bypassing DDM	{"sql": "SELECT dp.name AS principal_name, dp.type_desc,\\n  perm.permission_name, perm.state_desc,\\n  COALESCE(s.name + '.' + o.name, 'DATABASE-LEVEL') AS scope\\nFROM sys.database_permissions perm\\nJOIN sys.database_principals dp ON perm.grantee_principal_id = dp.principal_id\\nLEFT JOIN sys.objects o ON perm.major_id = o.object_id\\nLEFT JOIN sys.schemas s ON o.schema_id = s.schema_id\\nWHERE perm.permission_name = 'UNMASK'\\n  AND perm.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')\\nORDER BY dp.name"}	{"condition": "users or roles with UNMASK permission", "description": "Principals with UNMASK permission can see clear-text PII, defeating masking controls"}	null	2026-02-23 20:18:31.39092
3332	sqlserver	query	Check for expired or near-expiry certificates used by Always Encrypted	{"sql": "SELECT c.name AS cert_name, c.expiry_date,\\n  c.start_date, c.subject,\\n  DATEDIFF(DAY, GETDATE(), c.expiry_date) AS days_until_expiry,\\n  c.pvt_key_encryption_type_desc\\nFROM sys.certificates c\\nWHERE c.expiry_date < DATEADD(MONTH, 3, GETDATE())\\nORDER BY c.expiry_date ASC"}	{"condition": "certificates expired or expiring within 90 days", "description": "Certificates approaching or past expiration — key rotation urgently needed to maintain encrypted column accessibility"}	null	2026-02-23 20:18:31.390922
3333	sqlserver	query	Check column encryption key to master key relationships	{"sql": "SELECT cek.name AS encryption_key_name,\\n  cmk.name AS master_key_name,\\n  cmk.key_store_provider_name,\\n  cek.create_date AS cek_created,\\n  cek.modify_date AS cek_modified,\\n  DATEDIFF(DAY, cek.create_date, GETDATE()) AS cek_age_days\\nFROM sys.column_encryption_keys cek\\nJOIN sys.column_encryption_key_values cekv ON cek.column_encryption_key_id = cekv.column_encryption_key_id\\nJOIN sys.column_master_keys cmk ON cekv.column_master_key_id = cmk.column_master_key_id\\nORDER BY cek.create_date ASC"}	{"condition": "CEKs older than 365 days or tied to local certificate stores", "description": "Stale column encryption keys or local-store-based master keys indicate key rotation neglect and management complexity"}	null	2026-02-23 20:18:31.390923
3335	sqlserver	query	Check if DDM or Always Encrypted are actually in use on 2016+ instances	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.masked_columns) AS masked_column_count,\\n  (SELECT COUNT(*) FROM sys.column_encryption_keys) AS encryption_key_count,\\n  (SELECT COUNT(*) FROM sys.column_master_keys) AS master_key_count,\\n  CASE\\n    WHEN (SELECT COUNT(*) FROM sys.masked_columns) = 0\\n      AND (SELECT COUNT(*) FROM sys.column_encryption_keys) = 0\\n    THEN 'FEATURES_AVAILABLE_BUT_UNUSED'\\n    ELSE 'FEATURES_IN_USE'\\n  END AS feature_utilization"}	{"condition": "feature_utilization = FEATURES_AVAILABLE_BUT_UNUSED", "description": "SQL Server 2016+ but neither DDM nor Always Encrypted are deployed — native masking features available but not adopted"}	null	2026-02-23 20:18:31.390924
3336	sqlserver	query	Check for unencrypted backups in backup history	{"sql": "SELECT bs.database_name, bs.backup_finish_date,\\n  bs.type AS backup_type,\\n  CASE bs.type WHEN 'D' THEN 'Full' WHEN 'I' THEN 'Differential'\\n    WHEN 'L' THEN 'Log' ELSE bs.type END AS backup_type_desc,\\n  bs.key_algorithm, bs.encryptor_type, bs.encryptor_thumbprint,\\n  bs.is_copy_only, bs.compressed_backup_size / 1048576 AS size_mb,\\n  bmf.physical_device_name\\nFROM msdb.dbo.backupset bs\\nJOIN msdb.dbo.backupmediafamily bmf ON bs.media_set_id = bmf.media_set_id\\nWHERE bs.key_algorithm IS NULL\\n  AND bs.backup_finish_date > DATEADD(DAY, -30, GETDATE())\\nORDER BY bs.backup_finish_date DESC"}	{"condition": "recent backups with key_algorithm IS NULL", "description": "Unencrypted backups found in last 30 days — backup files contain PII in clear text, readable by anyone with file access"}	null	2026-02-23 20:18:31.390925
3343	sqlserver	query	Check trace flags affecting error logging verbosity	{"sql": "DBCC TRACESTATUS(-1) WITH NO_INFOMSGS;\\nSELECT\\n  CASE\\n    WHEN EXISTS (SELECT 1 FROM sys.dm_exec_query_profiles WHERE 1=0) THEN 'lightweight_profiling_available'\\n    ELSE 'not_available'\\n  END AS profiling_check;\\nSELECT name, value_in_use\\nFROM sys.configurations\\nWHERE name IN ('remote login timeout (s)', 'default trace enabled',\\n  'common criteria compliance enabled')"}	{"condition": "verbose trace flags enabled (e.g., 3605, 4032) or common criteria compliance enabled", "description": "Verbose logging flags or compliance mode increases detail captured in ERRORLOG and trace files, including query text and error context"}	null	2026-02-23 20:18:31.390927
3344	sqlserver	query	Check for custom error messages that may include sensitive details	{"sql": "SELECT message_id, severity, text, language_id\\nFROM sys.messages\\nWHERE message_id > 50000\\n  AND language_id = 1033\\nORDER BY message_id"}	{"condition": "custom messages with placeholder patterns that may embed data values", "description": "Custom error messages (ID > 50000) may use format strings that embed sensitive parameter values when raised"}	null	2026-02-23 20:18:31.390928
3346	sqlserver	query	Check database audit for SELECT on all schema objects	{"sql": "SELECT das.name AS db_spec_name,\\n  dasd.audit_action_name,\\n  dasd.class_desc,\\n  CASE dasd.major_id\\n    WHEN 0 THEN 'ALL OBJECTS'\\n    ELSE OBJECT_NAME(dasd.major_id)\\n  END AS audited_scope,\\n  dasd.audited_result\\nFROM sys.database_audit_specifications das\\nJOIN sys.database_audit_specification_details dasd ON das.database_specification_id = dasd.database_specification_id\\nWHERE das.is_state_enabled = 1\\n  AND dasd.audit_action_name = 'SELECT'\\n  AND dasd.major_id = 0\\nORDER BY das.name"}	{"condition": "SELECT audit on ALL OBJECTS (major_id = 0)", "description": "Database audit captures SELECT on every table — every query reading PII is logged with full statement text"}	null	2026-02-23 20:18:31.390929
3348	sqlserver	query	Check Query Store for sensitive function call patterns	{"sql": "SELECT d.name AS database_name,\\n  d.is_query_store_on,\\n  CASE d.is_query_store_on\\n    WHEN 1 THEN 'ENABLED — query text including DECRYPT*/ENCRYPT* calls persisted'\\n    ELSE 'DISABLED'\\n  END AS query_store_risk\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.is_query_store_on = 1\\nORDER BY d.name"}	{"condition": "Query Store enabled on databases using encryption functions", "description": "Query Store persists query text containing DECRYPTBYKEY and similar calls — parameter values in ad-hoc queries are stored long-term"}	null	2026-02-23 20:18:31.390931
3349	sqlserver	query	Check for recent memory dumps and dump configuration	{"sql": "SELECT filename, creation_time,\\n  size_in_bytes / 1048576 AS size_mb\\nFROM sys.dm_server_memory_dumps\\nORDER BY creation_time DESC"}	{"condition": "memory dumps present", "description": "SQL Server memory dumps exist — these contain raw memory pages including query buffers, plan cache, and buffer pool data that may hold sensitive values"}	null	2026-02-23 20:18:31.390931
3350	sqlserver	query	Check default trace and dump-related configuration	{"sql": "SELECT name, CAST(value_in_use AS INT) AS current_value,\\n  CASE name\\n    WHEN 'default trace enabled' THEN\\n      CASE CAST(value_in_use AS INT)\\n        WHEN 1 THEN 'Default trace ON — captures events to trc files'\\n        ELSE 'Default trace OFF'\\n      END\\n  END AS assessment\\nFROM sys.configurations\\nWHERE name IN ('default trace enabled')\\nUNION ALL\\nSELECT 'sqldumper_flags' AS name,\\n  0 AS current_value,\\n  'Check LOG\\\\SQLDUMPER_ERRORLOG.log for dump flags' AS assessment"}	{"condition": "default trace enabled or frequent memory dumps", "description": "Default trace writes to file system; memory dumps contain full process memory — both are file-system accessible data exposure vectors"}	null	2026-02-23 20:18:31.390932
3353	sqlserver	query	Check for active SQL Trace sessions	{"sql": "SELECT id AS trace_id, status,\\n  CASE status WHEN 0 THEN 'Stopped' WHEN 1 THEN 'Running' END AS status_desc,\\n  path AS trace_file_path,\\n  max_size AS max_file_size_mb,\\n  start_time, stop_time,\\n  event_count, is_default,\\n  buffer_count, buffer_size,\\n  CASE is_rowset WHEN 1 THEN 'Rowset trace' ELSE 'File trace' END AS trace_type\\nFROM sys.traces\\nWHERE status = 1\\nORDER BY is_default, id"}	{"condition": "non-default traces with status = 1 (Running)", "description": "Active SQL Trace sessions found — writing query events to .trc files which may contain full statement text with sensitive data"}	null	2026-02-23 20:18:31.390934
4110	postgresql	query	Check replication slot count vs maximum	{"sql": "SELECT count(*) AS current_slots, (SELECT setting::int FROM pg_settings WHERE name = 'max_replication_slots') AS max_slots FROM pg_replication_slots"}	{"condition": "current_slots >= max_slots", "description": "All replication slots are consumed; cannot create new ones"}	\N	2026-02-25 00:28:52.405273
3354	sqlserver	query	Check trace events for statement-level capture	{"sql": "SELECT t.id AS trace_id, t.path,\\n  te.name AS event_name, tc.name AS column_name\\nFROM sys.traces t\\nCROSS APPLY sys.fn_trace_geteventinfo(t.id) ei\\nJOIN sys.trace_events te ON ei.eventid = te.trace_event_id\\nJOIN sys.trace_columns tc ON ei.columnid = tc.trace_column_id\\nWHERE t.status = 1\\n  AND te.name IN ('SQL:BatchCompleted', 'SQL:StmtCompleted',\\n    'RPC:Completed', 'SP:StmtCompleted',\\n    'SQL:BatchStarting', 'RPC:Starting')\\n  AND tc.name = 'TextData'\\nORDER BY t.id, te.name"}	{"condition": "statement-level trace events capturing TextData column", "description": "SQL Trace captures full query text (TextData) for statement events — PII in literal values persists in trace files"}	null	2026-02-23 20:18:31.390934
3355	sqlserver	query	Check ERRORLOG rotation configuration	{"sql": "SELECT name, CAST(value_in_use AS INT) AS value_in_use,\\n  CASE name\\n    WHEN 'number of errorlog files' THEN\\n      CASE\\n        WHEN CAST(value_in_use AS INT) <= 6 THEN 'DEFAULT (6) — may retain too few or too many logs'\\n        WHEN CAST(value_in_use AS INT) > 30 THEN 'HIGH — ' + CAST(value_in_use AS VARCHAR) + ' log files retained'\\n        ELSE 'CUSTOM — ' + CAST(value_in_use AS VARCHAR) + ' log files'\\n      END\\n  END AS assessment\\nFROM sys.configurations\\nWHERE name = 'number of errorlog files'"}	{"condition": "default value (6) or excessive retention (>30)", "description": "ERRORLOG rotation at default or with high retention — sensitive data in error logs persists longer than necessary"}	null	2026-02-23 20:18:31.390935
2198	sqlserver	query	Check IO-related wait statistics	{"sql": "SELECT\\n  wait_type,\\n  wait_time_ms,\\n  waiting_tasks_count,\\n  CAST(wait_time_ms AS FLOAT) / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms,\\n  CAST(wait_time_ms AS FLOAT) / (SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats WHERE wait_time_ms > 0) * 100 AS pct_of_total\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGEIOLATCH_SH', 'PAGEIOLATCH_EX', 'PAGEIOLATCH_UP',\\n  'IO_COMPLETION', 'ASYNC_IO_COMPLETION', 'WRITELOG')\\n  AND wait_time_ms > 0\\nORDER BY wait_time_ms DESC"}	{"condition": "PAGEIOLATCH waits pct_of_total > 20 OR avg_wait_ms > 10", "description": "IO latch waits dominate or show high average latency, indicating storage saturation"}	null	2026-02-23 20:18:31.390937
3364	postgresql	query	Find active blocking chains	{"sql": "SELECT blocked.pid AS blocked_pid, blocked.usename AS blocked_user, blocked.application_name AS blocked_app, blocked.query AS blocked_query, blocking.pid AS blocking_pid, blocking.usename AS blocking_user, blocking.query AS blocking_query, blocked.wait_event_type, blocked.wait_event FROM pg_stat_activity blocked JOIN pg_locks bl ON bl.pid = blocked.pid JOIN pg_locks kl ON kl.locktype = bl.locktype AND kl.database IS NOT DISTINCT FROM bl.database AND kl.relation IS NOT DISTINCT FROM bl.relation AND kl.page IS NOT DISTINCT FROM bl.page AND kl.tuple IS NOT DISTINCT FROM bl.tuple AND kl.transactionid IS NOT DISTINCT FROM bl.transactionid AND kl.classid IS NOT DISTINCT FROM bl.classid AND kl.objid IS NOT DISTINCT FROM bl.objid AND kl.objsubid IS NOT DISTINCT FROM bl.objsubid AND kl.pid <> bl.pid JOIN pg_stat_activity blocking ON blocking.pid = kl.pid WHERE NOT bl.granted AND kl.granted"}	{"condition": "row_count > 0", "description": "Active blocking chains exist"}	\N	2026-02-25 00:28:52.405273
3365	postgresql	query	Check for long-duration lock waits	{"sql": "SELECT pid, usename, wait_event_type, wait_event, now() - query_start AS wait_duration, left(query, 200) AS blocked_query FROM pg_stat_activity WHERE wait_event_type = 'Lock' AND now() - query_start > :threshold_interval::interval"}	{"condition": "row_count > 0", "description": "Sessions waiting on locks for extended periods confirm blocking is causing pool drain"}	{"threshold_interval": "30 seconds"}	2026-02-25 00:28:52.405273
3366	postgresql	query	Find long-running open transactions	{"sql": "SELECT pid, usename, application_name, client_addr, state, xact_start, now() - xact_start AS transaction_age, query_start, left(query, 200) AS last_query FROM pg_stat_activity WHERE xact_start IS NOT NULL AND backend_type = 'client backend' AND now() - xact_start > :threshold_interval::interval ORDER BY transaction_age DESC"}	{"condition": "row_count > 0", "description": "Transactions open longer than threshold"}	{"threshold_interval": "5 minutes"}	2026-02-25 00:28:52.405273
