6598	oracle	query	Oracle check password file users with SYSDBA privilege	{"sql": "SELECT username, sysdba, sysoper FROM v$pwfile_users WHERE sysdba = 'TRUE' OR sysoper = 'TRUE'"}	{"condition": "row_count > 2", "description": "More than expected number of users have SYSDBA/SYSOPER in the password file enabling remote privileged access"}	\N	2026-02-28 12:19:19.580455
3640	postgresql	query	Map role inheritance tree for privileged roles	{"sql": "WITH RECURSIVE role_tree AS (SELECT a.member, a.roleid, 1 AS depth FROM pg_auth_members a UNION ALL SELECT a.member, a.roleid, rt.depth + 1 FROM pg_auth_members a JOIN role_tree rt ON rt.member = a.roleid WHERE rt.depth < 5) SELECT r.rolname AS user_role, m.rolname AS inherited_role, rt.depth FROM role_tree rt JOIN pg_roles r ON r.oid = rt.member JOIN pg_roles m ON m.oid = rt.roleid WHERE m.rolsuper = true OR m.rolcreaterole = true OR m.rolcreatedb = true OR m.rolreplication = true ORDER BY depth, r.rolname"}	{"condition": "row_count > 0 AND depth > 1", "description": "Indirect privilege inheritance through nested role membership"}	\N	2026-02-25 00:28:52.405273
3641	postgresql	query	Find service accounts with elevated privileges	{"sql": "SELECT rolname, rolsuper, rolcreaterole, rolcreatedb, rolreplication, rolbypassrls FROM pg_roles WHERE rolcanlogin = true AND rolname ~* '(backup|monitor|repl|etl|app|service|agent|barman|pgbackrest|zabbix|nagios|datadog|prometheus)' AND (rolsuper = true OR rolcreaterole = true OR rolcreatedb = true OR rolbypassrls = true) ORDER BY rolname"}	{"condition": "row_count > 0", "description": "Service accounts with excessive privileges"}	\N	2026-02-25 00:28:52.405273
3642	postgresql	query	Find non-admin schema and database owners	{"sql": "SELECT n.nspname AS schema_name, r.rolname AS owner, r.rolsuper FROM pg_namespace n JOIN pg_roles r ON r.oid = n.nspowner WHERE n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast') AND n.nspname NOT LIKE 'pg_temp%' AND r.rolname NOT IN ('postgres') ORDER BY n.nspname"}	{"condition": "row_count > 0", "description": "Non-postgres users own schemas — they have full control over objects within"}	\N	2026-02-25 00:28:52.405273
