3655	postgresql	query	Check for file system access functions	{"sql": "SELECT rolname FROM pg_roles WHERE rolname IN (SELECT member::regrole::text FROM pg_auth_members WHERE roleid = (SELECT oid FROM pg_roles WHERE rolname = 'pg_read_server_files') OR roleid = (SELECT oid FROM pg_roles WHERE rolname = 'pg_write_server_files') OR roleid = (SELECT oid FROM pg_roles WHERE rolname = 'pg_execute_server_program'))"}	{"condition": "row_count > 0", "description": "Users with file system access roles — potential for OS-level escalation"}	\N	2026-02-25 00:28:52.405273
3656	postgresql	query	Find users with many role memberships	{"sql": "SELECT r.rolname, count(a.roleid) AS role_count, array_agg(m.rolname ORDER BY m.rolname) AS roles FROM pg_auth_members a JOIN pg_roles r ON r.oid = a.member JOIN pg_roles m ON m.oid = a.roleid WHERE r.rolcanlogin = true GROUP BY r.rolname HAVING count(a.roleid) > :threshold ORDER BY role_count DESC"}	{"condition": "row_count > 0", "description": "Users with excessive role memberships — potential privilege creep"}	{"threshold": 5}	2026-02-25 00:28:52.405273
3657	postgresql	query	Find non-admin users with admin-level privileges	{"sql": "SELECT r.rolname, r.rolsuper, r.rolcreaterole, r.rolcreatedb, r.rolreplication, r.rolbypassrls, array_agg(m.rolname) AS member_of FROM pg_roles r LEFT JOIN pg_auth_members a ON a.member = r.oid LEFT JOIN pg_roles m ON m.oid = a.roleid WHERE r.rolcanlogin = true AND r.rolname NOT IN ('postgres') AND (r.rolsuper = true OR r.rolcreaterole = true OR r.rolcreatedb = true OR r.rolbypassrls = true) GROUP BY r.rolname, r.rolsuper, r.rolcreaterole, r.rolcreatedb, r.rolreplication, r.rolbypassrls ORDER BY r.rolname"}	{"condition": "row_count > 0", "description": "Non-admin users with elevated privileges — check if temporary escalation was not revoked"}	\N	2026-02-25 00:28:52.405273
3658	postgresql	query	Find tool-related accounts with elevated privileges	{"sql": "SELECT rolname, rolsuper, rolcreaterole, rolcreatedb, rolreplication FROM pg_roles WHERE rolcanlogin = true AND rolname ~* '(pgadmin|dbeaver|datagrip|grafana|zabbix|nagios|datadog|prometheus|pgwatch|barman|pgbackrest|patroni|etcd|consul)' AND (rolsuper = true OR rolcreaterole = true) ORDER BY rolname"}	{"condition": "row_count > 0", "description": "Tool accounts with excessive privileges"}	\N	2026-02-25 00:28:52.405273
3660	postgresql	query	Find tables with autovacuum disabled	{"sql": "SELECT c.relname AS table_name, n.nspname AS schema_name, c.reloptions FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.relkind = 'r' AND c.reloptions IS NOT NULL AND array_to_string(c.reloptions, ',') LIKE '%autovacuum_enabled=false%' ORDER BY n.nspname, c.relname"}	{"condition": "row_count > 0", "description": "Tables with autovacuum explicitly disabled"}	\N	2026-02-25 00:28:52.405273
3663	postgresql	config_check	Check autovacuum threshold settings	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('autovacuum_vacuum_threshold', 'autovacuum_vacuum_scale_factor', 'autovacuum_analyze_threshold', 'autovacuum_analyze_scale_factor') ORDER BY name"}	{"condition": "autovacuum_vacuum_scale_factor::float >= 0.2", "description": "Default scale factor 0.2 means 20% of table must be dead before vacuum triggers — too high for large tables"}	\N	2026-02-25 00:28:52.405273
3664	postgresql	query	Find large tables with high dead tuple ratio	{"sql": "SELECT schemaname, relname, n_live_tup, n_dead_tup, round(n_dead_tup::numeric / NULLIF(n_live_tup, 0) * 100, 2) AS dead_pct, last_autovacuum FROM pg_stat_user_tables WHERE n_live_tup > :min_rows AND n_dead_tup > :min_dead ORDER BY n_dead_tup DESC LIMIT 20"}	{"condition": "dead_pct > :dead_threshold", "description": "Large tables with high dead tuple ratio — autovacuum not triggering soon enough"}	{"min_dead": 10000, "min_rows": 100000, "dead_threshold": 10}	2026-02-25 00:28:52.405273
3665	postgresql	config_check	Check vacuum cost-based throttling settings	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('autovacuum_vacuum_cost_delay', 'autovacuum_vacuum_cost_limit', 'vacuum_cost_delay', 'vacuum_cost_limit', 'vacuum_cost_page_hit', 'vacuum_cost_page_miss', 'vacuum_cost_page_dirty') ORDER BY name"}	{"condition": "autovacuum_vacuum_cost_delay::int >= 20 OR autovacuum_vacuum_cost_limit::int <= 200", "description": "Autovacuum throttled aggressively — may not keep up with write rate"}	\N	2026-02-25 00:28:52.405273
3666	postgresql	query	Check if dead tuples are accumulating faster than vacuum	{"sql": "SELECT schemaname, relname, n_dead_tup, last_autovacuum, now() - last_autovacuum AS since_last_vacuum FROM pg_stat_user_tables WHERE n_dead_tup > :dead_threshold AND last_autovacuum IS NOT NULL ORDER BY n_dead_tup DESC LIMIT 10"}	{"condition": "n_dead_tup > :dead_threshold AND since_last_vacuum < interval '1 hour'", "description": "High dead tuples despite recent vacuum — vacuum cannot keep up due to throttling"}	{"dead_threshold": 100000}	2026-02-25 00:28:52.405273
3661	postgresql	config_check	Check autovacuum_max_workers setting	{"sql": "SELECT name, setting FROM pg_settings WHERE name = 'autovacuum_max_workers'"}	{"condition": "row_count > 0", "description": "Only 3 (default) or fewer autovacuum workers — may be insufficient"}	\N	2026-02-25 00:28:52.405273
3669	postgresql	query	Find idle-in-transaction sessions with old snapshots	{"sql": "SELECT pid, usename, application_name, client_addr, state, xact_start, now() - xact_start AS transaction_age, backend_xmin FROM pg_stat_activity WHERE state = 'idle in transaction' AND backend_type = 'client backend' ORDER BY xact_start ASC"}	{"condition": "row_count > 0 AND transaction_age > :threshold_interval::interval", "description": "Idle-in-transaction sessions holding old snapshots"}	{"threshold_interval": "10 minutes"}	2026-02-25 00:28:52.405273
3671	postgresql	query	Find orphaned prepared transactions	{"sql": "SELECT gid, prepared, owner, database, transaction AS xid FROM pg_prepared_xacts ORDER BY prepared ASC"}	{"condition": "row_count > 0", "description": "Prepared transactions exist — each one holds back xmin horizon"}	\N	2026-02-25 00:28:52.405273
3672	postgresql	query	Check age of prepared transactions	{"sql": "SELECT gid, owner, database, prepared, now() - prepared AS age FROM pg_prepared_xacts WHERE now() - prepared > :threshold_interval::interval ORDER BY prepared ASC"}	{"condition": "row_count > 0", "description": "Old prepared transactions blocking vacuum"}	{"threshold_interval": "1 hour"}	2026-02-25 00:28:52.405273
3673	postgresql	query	Find stale or lagging replication slots	{"sql": "SELECT slot_name, slot_type, active, database, restart_lsn, confirmed_flush_lsn, pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) AS retained_bytes, pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS retained_size, xmin, catalog_xmin FROM pg_replication_slots ORDER BY pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) DESC"}	{"condition": "(NOT active AND retained_bytes > :threshold) OR (xmin IS NOT NULL)", "description": "Inactive or lagging replication slots holding back WAL and/or xmin"}	{"threshold": 1073741824}	2026-02-25 00:28:52.405273
3674	postgresql	query	Check dead tuple accumulation	{"sql": "SELECT sum(n_dead_tup) AS total_dead_tuples, count(*) AS tables_with_dead FROM pg_stat_user_tables WHERE n_dead_tup > 0"}	{"condition": "total_dead_tuples > :dead_threshold", "description": "Significant dead tuple accumulation — likely caused by replication slot holding back xmin"}	{"dead_threshold": 1000000}	2026-02-25 00:28:52.405273
3675	postgresql	query	Check replication connections with feedback	{"sql": "SELECT application_name, client_addr, state, sent_lsn, write_lsn, replay_lsn, pg_wal_lsn_diff(sent_lsn, replay_lsn) AS replay_lag_bytes, pg_size_pretty(pg_wal_lsn_diff(sent_lsn, replay_lsn)) AS replay_lag_size, backend_xmin FROM pg_stat_replication WHERE backend_xmin IS NOT NULL ORDER BY replay_lag_bytes DESC"}	{"condition": "backend_xmin IS NOT NULL AND replay_lag_bytes > :lag_threshold", "description": "Standby with hot_standby_feedback is lagging and holding back primary's xmin"}	{"lag_threshold": 268435456}	2026-02-25 00:28:52.405273
3676	postgresql	query	Find AccessExclusiveLock holders	{"sql": "SELECT l.relation::regclass AS table_name, l.mode, a.pid, a.usename, a.state, left(a.query, 200) AS query_text, now() - a.query_start AS duration FROM pg_locks l JOIN pg_stat_activity a ON a.pid = l.pid WHERE l.mode = 'AccessExclusiveLock' AND l.relation IS NOT NULL AND l.granted = true ORDER BY duration DESC"}	{"condition": "row_count > 0", "description": "DDL operations holding AccessExclusiveLock — blocking autovacuum"}	\N	2026-02-25 00:28:52.405273
3677	postgresql	query	Check if autovacuum is waiting on locks	{"sql": "SELECT pid, query, wait_event_type, wait_event FROM pg_stat_activity WHERE backend_type = 'autovacuum worker' AND wait_event_type = 'Lock'"}	{"condition": "row_count > 0", "description": "Autovacuum workers blocked by DDL locks"}	\N	2026-02-25 00:28:52.405273
3678	postgresql	query	Check active autovacuum workers and target tables	{"sql": "SELECT pid, query, now() - xact_start AS running_time FROM pg_stat_activity WHERE backend_type = 'autovacuum worker' AND state = 'active'"}	{"condition": "row_count >= :worker_threshold", "description": "Most or all autovacuum workers are busy"}	{"worker_threshold": 3}	2026-02-25 00:28:52.405273
3679	postgresql	query	Check vacuum progress on large tables	{"sql": "SELECT p.relid::regclass AS table_name, p.phase, p.heap_blks_total, p.heap_blks_scanned, round(p.heap_blks_scanned::numeric / NULLIF(p.heap_blks_total, 0) * 100, 2) AS pct_complete FROM pg_stat_progress_vacuum p"}	{"condition": "row_count > 0 AND pct_complete < :progress_threshold", "description": "Workers stuck processing large tables with low progress"}	{"progress_threshold": 50}	2026-02-25 00:28:52.405273
3680	postgresql	query	Check autovacuum worker wait events	{"sql": "SELECT pid, wait_event_type, wait_event, query FROM pg_stat_activity WHERE backend_type = 'autovacuum worker' AND wait_event_type = 'IO'"}	{"condition": "row_count > 0", "description": "Autovacuum workers waiting on I/O"}	\N	2026-02-25 00:28:52.405273
3681	postgresql	query	Check overall I/O pressure	{"sql": "SELECT count(*) AS io_waiting_sessions FROM pg_stat_activity WHERE wait_event_type = 'IO' AND state = 'active'"}	{"condition": "io_waiting_sessions > :threshold", "description": "High overall I/O wait count — contention between user queries and vacuum"}	{"threshold": 5}	2026-02-25 00:28:52.405273
