3696	postgresql	query	Find tables with modifications below analyze threshold	{"sql": "SELECT s.schemaname, s.relname, s.n_live_tup, s.n_mod_since_analyze, s.last_autoanalyze, COALESCE((SELECT option_value FROM pg_options_to_table(c.reloptions) WHERE option_name = 'autovacuum_analyze_threshold'), current_setting('autovacuum_analyze_threshold'))::int AS threshold, COALESCE((SELECT option_value FROM pg_options_to_table(c.reloptions) WHERE option_name = 'autovacuum_analyze_scale_factor'), current_setting('autovacuum_analyze_scale_factor'))::float AS scale_factor, COALESCE((SELECT option_value FROM pg_options_to_table(c.reloptions) WHERE option_name = 'autovacuum_analyze_threshold'), current_setting('autovacuum_analyze_threshold'))::int + COALESCE((SELECT option_value FROM pg_options_to_table(c.reloptions) WHERE option_name = 'autovacuum_analyze_scale_factor'), current_setting('autovacuum_analyze_scale_factor'))::float * s.n_live_tup AS trigger_threshold FROM pg_stat_user_tables s JOIN pg_class c ON c.relname = s.relname AND c.relnamespace = (SELECT oid FROM pg_namespace WHERE nspname = s.schemaname) WHERE s.n_mod_since_analyze > 0 AND s.n_mod_since_analyze < COALESCE((SELECT option_value FROM pg_options_to_table(c.reloptions) WHERE option_name = 'autovacuum_analyze_threshold'), current_setting('autovacuum_analyze_threshold'))::int + COALESCE((SELECT option_value FROM pg_options_to_table(c.reloptions) WHERE option_name = 'autovacuum_analyze_scale_factor'), current_setting('autovacuum_analyze_scale_factor'))::float * s.n_live_tup ORDER BY s.n_mod_since_analyze DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with modifications that have not yet triggered autoanalyze due to threshold settings"}	\N	2026-02-25 00:28:52.405273
