3814	postgresql	query	Check replication lag from primary perspective	{"sql": "SELECT client_addr, application_name, state, sync_state, sent_lsn, write_lsn, flush_lsn, replay_lsn, pg_size_pretty(pg_wal_lsn_diff(sent_lsn, replay_lsn)) AS replay_lag_bytes, pg_wal_lsn_diff(sent_lsn, replay_lsn) AS replay_lag_bytes_raw, write_lag, flush_lag, replay_lag FROM pg_stat_replication ORDER BY pg_wal_lsn_diff(sent_lsn, replay_lsn) DESC"}	{"condition": "replay_lag_bytes_raw > :max_lag_bytes OR replay_lag > :max_lag_interval", "description": "Replication lag exceeds acceptable thresholds"}	{"max_lag_bytes": 104857600, "max_lag_interval": "00:00:30"}	2026-02-25 00:28:52.405273
