4656	postgresql	query	Compare shared_buffers size against total database size	{"sql": "SELECT pg_size_pretty((SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers')) AS shared_buffers_size, (SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers') AS shared_buffers_bytes, pg_size_pretty(sum(pg_database_size(datname))) AS total_db_size, sum(pg_database_size(datname)) AS total_db_bytes, round((SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers')::numeric / NULLIF(sum(pg_database_size(datname)), 0) * 100, 2) AS buffer_to_db_pct FROM pg_database"}	{"condition": "buffer_to_db_pct < :min_buffer_pct", "description": "Shared buffers covering less than the threshold percentage of total database size suggests insufficient allocation for the working set"}	{"min_buffer_pct": 15}	2026-02-25 00:28:52.405273
4657	postgresql	query	Check buffer cache hit ratio for eviction pressure	{"sql": "SELECT sum(blks_hit) AS blocks_hit, sum(blks_read) AS blocks_read, CASE WHEN sum(blks_hit) + sum(blks_read) > 0 THEN round(sum(blks_hit)::numeric / (sum(blks_hit) + sum(blks_read)) * 100, 2) ELSE 100 END AS cache_hit_ratio FROM pg_stat_database"}	{"condition": "cache_hit_ratio < :hit_ratio_threshold", "description": "Cache hit ratio below threshold confirms shared_buffers is too small; pages are being evicted and re-read from disk"}	{"hit_ratio_threshold": 95.0}	2026-02-25 00:28:52.405273
4658	postgresql	query	Calculate hot table and index sizes versus buffer pool	{"sql": "SELECT pg_size_pretty(sum(pg_total_relation_size(relid))) AS hot_data_size, sum(pg_total_relation_size(relid)) AS hot_data_bytes, pg_size_pretty((SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers')) AS shared_buffers_size, (SELECT setting::bigint * 8192 FROM pg_settings WHERE name = 'shared_buffers') AS shared_buffers_bytes FROM pg_stat_user_tables WHERE seq_scan + idx_scan > :min_access_count"}	{"condition": "hot_data_bytes > shared_buffers_bytes", "description": "Frequently accessed tables and indexes exceed shared_buffers capacity, confirming the working set cannot fit in the buffer pool"}	{"min_access_count": 100}	2026-02-25 00:28:52.405273
4660	postgresql	query	Find queries with high rows-to-calls ratio via pg_stat_statements	{"sql": "SELECT queryid, left(query, 120) AS query_preview, calls, rows, rows / NULLIF(calls, 0) AS avg_rows_per_call, shared_blks_read + shared_blks_hit AS total_blocks, shared_blks_read AS disk_reads FROM pg_stat_statements WHERE calls > :min_calls AND rows / NULLIF(calls, 0) > :rows_threshold ORDER BY rows / NULLIF(calls, 0) DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Queries averaging many rows per execution fetch large result sets that flood the buffer pool with pages that may not be needed"}	{"min_calls": 10, "rows_threshold": 10000}	2026-02-25 00:28:52.405273
