4662	postgresql	query	Measure disk read impact of sequential scans	{"sql": "SELECT schemaname, relname, heap_blks_read, heap_blks_hit, CASE WHEN heap_blks_hit + heap_blks_read > 0 THEN round(heap_blks_read::numeric / (heap_blks_hit + heap_blks_read) * 100, 2) ELSE 0 END AS disk_read_pct FROM pg_statio_user_tables WHERE heap_blks_read > :min_disk_reads ORDER BY heap_blks_read DESC LIMIT 15"}	{"condition": "disk_read_pct > :disk_read_threshold", "description": "High disk read percentage on tables with sequential scans confirms buffer pool eviction from full table scans"}	{"min_disk_reads": 10000, "disk_read_threshold": 30.0}	2026-02-25 00:28:52.405273
4663	postgresql	query	Find queries with high block read to row ratio	{"sql": "SELECT queryid, left(query, 120) AS query_preview, calls, rows, shared_blks_read + shared_blks_hit AS total_blocks, (shared_blks_read + shared_blks_hit) / NULLIF(rows, 0) AS blocks_per_row, mean_exec_time FROM pg_stat_statements WHERE calls > :min_calls AND rows > 0 AND (shared_blks_read + shared_blks_hit) / NULLIF(rows, 0) > :blocks_per_row_threshold ORDER BY (shared_blks_read + shared_blks_hit) / NULLIF(rows, 0) DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Queries reading many blocks per row returned indicate inefficient plans (hash joins on large tables, unnecessary sorts, nested loop over large sets)"}	{"min_calls": 10, "blocks_per_row_threshold": 50}	2026-02-25 00:28:52.405273
4664	postgresql	query	Measure concurrent active session count and buffer pressure	{"sql": "SELECT count(*) AS total_backends, count(*) FILTER (WHERE state = 'active') AS active_queries, count(*) FILTER (WHERE wait_event_type = 'BufferPin' OR wait_event_type = 'LWLock') AS buffer_waiters, (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') AS max_connections, round(count(*)::numeric / (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') * 100, 1) AS utilization_pct FROM pg_stat_activity WHERE backend_type = 'client backend'"}	{"condition": "active_queries > :active_threshold OR buffer_waiters > 0", "description": "Many active queries or sessions waiting on buffer operations indicate concurrent workload contention for buffer pool pages"}	{"active_threshold": 20}	2026-02-25 00:28:52.405273
5003	postgresql	config_check	Check max_wal_size and checkpoint_timeout configuration	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('max_wal_size', 'checkpoint_timeout', 'checkpoint_completion_target')"}	{"condition": "max_wal_size setting is low relative to workload", "description": "Low max_wal_size forces frequent WAL-triggered checkpoints"}	\N	2026-02-25 00:28:52.405273
4665	postgresql	query	Check buffer-related wait events frequency	{"sql": "SELECT wait_event_type, wait_event, count(*) AS session_count FROM pg_stat_activity WHERE wait_event_type IN ('BufferPin', 'LWLock', 'IO') AND state = 'active' GROUP BY wait_event_type, wait_event ORDER BY session_count DESC"}	{"condition": "row_count > 0", "description": "Sessions waiting on BufferPin, buffer-related LWLocks, or IO events confirm concurrent contention for the buffer pool"}	\N	2026-02-25 00:28:52.405273
4666	postgresql	query	Find tables with high access frequency relative to size	{"sql": "SELECT schemaname, relname, pg_size_pretty(pg_relation_size(relid)) AS table_size, n_live_tup, seq_tup_read + idx_tup_fetch AS total_tup_accessed, (seq_tup_read + idx_tup_fetch) / NULLIF(n_live_tup, 0) AS access_amplification, n_tup_hot_upd, n_tup_upd FROM pg_stat_user_tables WHERE n_live_tup > 0 AND (seq_tup_read + idx_tup_fetch) / NULLIF(n_live_tup, 0) > :amplification_threshold ORDER BY (seq_tup_read + idx_tup_fetch) / NULLIF(n_live_tup, 0) DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Tables with very high access amplification (tuples accessed >> tuples stored) indicate hot page concentration where specific pages are accessed repeatedly"}	{"amplification_threshold": 100}	2026-02-25 00:28:52.405273
4667	postgresql	query	Check for HOT update chains indicating concentrated write patterns	{"sql": "SELECT schemaname, relname, n_tup_upd, n_tup_hot_upd, CASE WHEN n_tup_upd > 0 THEN round(n_tup_hot_upd::numeric / n_tup_upd * 100, 2) ELSE 0 END AS hot_update_pct, n_dead_tup, pg_size_pretty(pg_relation_size(relid)) AS table_size FROM pg_stat_user_tables WHERE n_tup_upd > :min_updates ORDER BY n_tup_upd DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "High HOT update percentages on specific tables confirm concentrated write patterns to the same pages, creating memory pressure hotspots"}	{"min_updates": 10000}	2026-02-25 00:28:52.405273
4756	postgresql	query	Check for recent deadlock occurrences	{"sql": "SELECT deadlocks FROM pg_stat_database WHERE datname = current_database()"}	{"condition": "deadlocks > 0", "description": "Non-zero deadlock count indicates periodic deadlocks disrupting connection availability"}	\N	2026-02-25 00:28:52.405273
4668	postgresql	query	Find tables with sequential scans but no index usage	{"sql": "SELECT schemaname, relname, pg_size_pretty(pg_total_relation_size(relid)) AS total_size, seq_scan, idx_scan, n_live_tup, CASE WHEN seq_scan + idx_scan > 0 THEN round(seq_scan::numeric / (seq_scan + idx_scan) * 100, 2) ELSE 0 END AS seq_scan_pct FROM pg_stat_user_tables WHERE seq_scan > :min_seq_scans AND idx_scan < :max_idx_scans AND n_live_tup > :min_rows ORDER BY seq_scan DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Large tables with many sequential scans and virtually no index scans are prime candidates for missing indexes"}	{"min_rows": 10000, "max_idx_scans": 10, "min_seq_scans": 100}	2026-02-25 00:28:52.405273
4669	postgresql	query	Check existing indexes on high-scan tables for gaps	{"sql": "SELECT t.schemaname, t.relname, t.n_live_tup, t.seq_scan, i.indexrelname, i.idx_scan AS index_scans, pg_size_pretty(pg_relation_size(i.indexrelid)) AS index_size FROM pg_stat_user_tables t LEFT JOIN pg_stat_user_indexes i ON t.relid = i.relid WHERE t.seq_scan > :min_seq_scans AND t.n_live_tup > :min_rows ORDER BY t.seq_scan DESC, i.idx_scan ASC LIMIT 20"}	{"condition": "index_scans IS NULL OR index_scans < :min_useful_scans", "description": "Tables with no indexes or only unused indexes confirm missing indexes that are forcing full table scans into the buffer pool"}	{"min_rows": 10000, "min_seq_scans": 100, "min_useful_scans": 10}	2026-02-25 00:28:52.405273
4670	postgresql	query	Find tables with high modification count since last analyze	{"sql": "SELECT schemaname, relname, n_live_tup, n_mod_since_analyze, last_analyze, last_autoanalyze, CASE WHEN n_live_tup > 0 THEN ROUND(n_mod_since_analyze::numeric / n_live_tup * 100, 1) ELSE 0 END AS mod_pct FROM pg_stat_user_tables WHERE n_mod_since_analyze > :mod_threshold ORDER BY n_mod_since_analyze DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with high modification count since last analyze have stale statistics"}	{"mod_threshold": 10000}	2026-02-25 00:28:52.405273
4671	postgresql	query	Check for sequential scans on tables with stale stats	{"sql": "SELECT s.schemaname, s.relname, s.seq_scan, s.seq_tup_read, s.idx_scan, s.n_mod_since_analyze FROM pg_stat_user_tables s WHERE s.n_mod_since_analyze > :mod_threshold AND s.seq_scan > s.idx_scan AND s.seq_tup_read > :seq_tup_threshold ORDER BY s.seq_tup_read DESC"}	{"condition": "row_count > 0", "description": "Tables with stale stats showing more sequential scans than index scans confirms poor selectivity estimates"}	{"mod_threshold": 10000, "seq_tup_threshold": 100000}	2026-02-25 00:28:52.405273
5662	postgresql	query	Check if passwordcheck or credcheck extension is loaded	{"sql": "SELECT name, setting FROM pg_settings WHERE name = 'shared_preload_libraries'"}	{"condition": "setting NOT LIKE '%passwordcheck%' AND setting NOT LIKE '%credcheck%'", "description": "No password complexity extension loaded means default (no enforcement) configuration"}	\N	2026-02-25 00:28:52.405273
4672	postgresql	query	Find indexes with stale statistics on indexed columns	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan, s.idx_tup_read, s.idx_tup_fetch, CASE WHEN s.idx_tup_read > 0 THEN ROUND(s.idx_tup_fetch::numeric / s.idx_tup_read * 100, 1) ELSE 0 END AS fetch_efficiency_pct FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relid = t.relid WHERE t.n_mod_since_analyze > :mod_threshold AND s.idx_scan > 0 ORDER BY s.idx_tup_read DESC LIMIT 20"}	{"condition": "row_count > 0 AND fetch_efficiency_pct < 50", "description": "Low fetch efficiency on indexes with stale stats indicates cardinality misestimation"}	{"mod_threshold": 5000}	2026-02-25 00:28:52.405273
4673	postgresql	query	Verify planner estimates diverge from actual via pg_stat_statements	{"sql": "SELECT query, calls, rows, ROUND(rows::numeric / calls, 1) AS avg_rows_per_call, total_exec_time, ROUND(total_exec_time / calls, 2) AS avg_exec_ms FROM pg_stat_statements WHERE calls > :min_calls AND rows / calls > :row_ratio_threshold ORDER BY total_exec_time DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries returning many more rows than expected per call indicate cardinality misestimation"}	{"min_calls": 100, "row_ratio_threshold": 1000}	2026-02-25 00:28:52.405273
4674	postgresql	query	Find tables with high dead tuple ratio	{"sql": "SELECT schemaname, relname, n_live_tup, n_dead_tup, CASE WHEN n_live_tup + n_dead_tup > 0 THEN ROUND(n_dead_tup::numeric / (n_live_tup + n_dead_tup) * 100, 1) ELSE 0 END AS dead_pct, last_vacuum, last_autovacuum FROM pg_stat_user_tables WHERE n_dead_tup > :dead_threshold ORDER BY n_dead_tup DESC LIMIT 20"}	{"condition": "row_count > 0 AND dead_pct > 10", "description": "Tables with more than 10% dead tuples indicate bloat from insufficient vacuum activity"}	{"dead_threshold": 10000}	2026-02-25 00:28:52.405273
4693	postgresql	query	Check plan_cache_mode setting and prepared statement usage	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('plan_cache_mode', 'pg_stat_statements.track') ORDER BY name"}	{"condition": "plan_cache_mode = 'auto' OR plan_cache_mode = 'force_custom_plan'", "description": "With auto mode, PostgreSQL may choose custom plans repeatedly; force_custom_plan always replans"}	\N	2026-02-25 00:28:52.405273
4676	postgresql	query	Check checkpoint frequency and timing from pg_stat_bgwriter	{"sql": "SELECT checkpoints_timed, checkpoints_req, buffers_checkpoint, buffers_clean, buffers_backend, CASE WHEN checkpoints_timed + checkpoints_req > 0 THEN ROUND(checkpoints_req::numeric / (checkpoints_timed + checkpoints_req) * 100, 1) ELSE 0 END AS req_pct FROM pg_stat_bgwriter"}	{"condition": "req_pct > 20", "description": "High percentage of requested (non-timed) checkpoints indicates checkpoint_completion_target or checkpoint_timeout is too low"}	\N	2026-02-25 00:28:52.405273
4677	postgresql	config_check	Review checkpoint configuration parameters	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('checkpoint_timeout', 'checkpoint_completion_target', 'max_wal_size', 'min_wal_size') ORDER BY name"}	{"condition": "checkpoint_timeout < 600 OR max_wal_size < 1GB", "description": "Low checkpoint_timeout or small max_wal_size forces frequent checkpoints"}	\N	2026-02-25 00:28:52.405273
4678	postgresql	config_check	Check shared_buffers relative to system memory	{"sql": "SELECT name, setting, unit, CASE WHEN name = 'shared_buffers' THEN pg_size_pretty(setting::bigint * 8192) END AS effective_size FROM pg_settings WHERE name IN ('shared_buffers', 'effective_cache_size', 'work_mem', 'maintenance_work_mem') ORDER BY name"}	{"condition": "shared_buffers configured", "description": "Baseline memory configuration for comparison with OS-level swap usage"}	\N	2026-02-25 00:28:52.405273
4680	postgresql	query	Check for backend processes with high memory usage	{"sql": "SELECT pid, state, backend_type, query_start, now() - query_start AS query_duration FROM pg_stat_activity WHERE state = 'active' AND backend_type = 'client backend' ORDER BY query_start ASC LIMIT 10"}	{"condition": "row_count > 0 AND query_duration > interval '5 minutes'", "description": "Long-running queries may be slow due to swapping; correlate with OS swap metrics"}	\N	2026-02-25 00:28:52.405273
4683	postgresql	query	Find query patterns with high call-to-plan ratio	{"sql": "SELECT queryid, LEFT(query, 200) AS query_preview, calls, rows, ROUND(total_exec_time::numeric / calls, 2) AS avg_ms FROM pg_stat_statements WHERE calls < :low_call_threshold AND dbid = (SELECT oid FROM pg_database WHERE datname = current_database()) ORDER BY total_exec_time DESC LIMIT 20"}	{"condition": "row_count > 10", "description": "Many unique queries with few calls each suggests ad-hoc literal queries"}	{"low_call_threshold": 5}	2026-02-25 00:28:52.405273
4684	postgresql	query	Check total unique query count in pg_stat_statements	{"sql": "SELECT count(*) AS total_entries, (SELECT setting::int FROM pg_settings WHERE name = 'pg_stat_statements.max') AS max_entries, ROUND(count(*)::numeric / NULLIF((SELECT setting::int FROM pg_settings WHERE name = 'pg_stat_statements.max'), 0) * 100, 1) AS usage_pct FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())"}	{"condition": "usage_pct > 80", "description": "pg_stat_statements near capacity with mostly low-call queries confirms ad-hoc literal pattern"}	\N	2026-02-25 00:28:52.405273
