4692	postgresql	query	Look for similar query patterns across different applications	{"sql": "SELECT LEFT(query, 100) AS query_prefix, count(DISTINCT queryid) AS variant_count, sum(calls) AS total_calls FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database()) GROUP BY LEFT(query, 100) HAVING count(DISTINCT queryid) > 1 ORDER BY variant_count DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Same query prefix with multiple queryids indicates similar queries from different sources"}	\N	2026-02-25 00:28:52.405273
4694	postgresql	query	Find queries with high planning time relative to execution	{"sql": "SELECT queryid, LEFT(query, 150) AS query_preview, calls, ROUND(total_plan_time::numeric / calls, 2) AS avg_plan_ms, ROUND(total_exec_time::numeric / calls, 2) AS avg_exec_ms, ROUND(total_plan_time::numeric / NULLIF(total_exec_time, 0) * 100, 1) AS plan_pct FROM pg_stat_statements WHERE calls > :min_calls AND total_plan_time > 0 AND dbid = (SELECT oid FROM pg_database WHERE datname = current_database()) ORDER BY total_plan_time DESC LIMIT 15"}	{"condition": "plan_pct > 30", "description": "Planning time exceeding 30% of execution time indicates replanning overhead from parameterization failures"}	{"min_calls": 50}	2026-02-25 00:28:52.405273
4695	postgresql	config_check	Check if plan_cache_mode forces generic plans	{"sql": "SELECT name, setting, source FROM pg_settings WHERE name = 'plan_cache_mode'"}	{"condition": "setting = 'force_generic_plan'", "description": "force_generic_plan means all prepared statements use a generic plan regardless of parameter values"}	\N	2026-02-25 00:28:52.405273
4696	postgresql	query	Find queries with high execution time variance	{"sql": "SELECT queryid, LEFT(query, 150) AS query_preview, calls, ROUND(min_exec_time, 2) AS min_ms, ROUND(max_exec_time, 2) AS max_ms, ROUND(mean_exec_time, 2) AS avg_ms, ROUND(stddev_exec_time, 2) AS stddev_ms FROM pg_stat_statements WHERE calls > :min_calls AND stddev_exec_time > mean_exec_time AND dbid = (SELECT oid FROM pg_database WHERE datname = current_database()) ORDER BY stddev_exec_time DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "High variance in execution time with generic plans indicates some parameter values get suboptimal plans"}	{"min_calls": 100}	2026-02-25 00:28:52.405273
