4697	postgresql	query	Count one-time queries versus reused queries	{"sql": "SELECT count(*) FILTER (WHERE calls = 1) AS single_use, count(*) FILTER (WHERE calls > 1) AS reused, count(*) AS total, ROUND(count(*) FILTER (WHERE calls = 1)::numeric / NULLIF(count(*), 0) * 100, 1) AS single_use_pct FROM pg_stat_statements WHERE dbid = (SELECT oid FROM pg_database WHERE datname = current_database())"}	{"condition": "single_use_pct > :threshold_pct", "description": "High percentage of single-use queries indicates one-time OLAP/reporting workload"}	{"threshold_pct": 60}	2026-02-25 00:28:52.405273
