4704	postgresql	query	Check pg_stat_statements utilization and eviction	{"sql": "SELECT count(*) AS current_entries, (SELECT setting::int FROM pg_settings WHERE name = 'pg_stat_statements.max') AS max_entries, ROUND(count(*)::numeric / NULLIF((SELECT setting::int FROM pg_settings WHERE name = 'pg_stat_statements.max'), 0) * 100, 1) AS usage_pct, (SELECT dealloc FROM pg_stat_statements_info) AS evictions FROM pg_stat_statements"}	{"condition": "usage_pct > 90 OR evictions > :eviction_threshold", "description": "Near-full pg_stat_statements with high eviction count indicates insufficient maintenance"}	{"eviction_threshold": 1000}	2026-02-25 00:28:52.405273
