4710	postgresql	query	Check dead tuple accumulation on large tables	{"sql": "SELECT schemaname, relname, n_dead_tup, n_live_tup, ROUND(n_dead_tup::numeric / NULLIF(n_live_tup, 0) * 100, 1) AS dead_pct FROM pg_stat_user_tables WHERE n_dead_tup > :dead_threshold ORDER BY n_dead_tup DESC LIMIT 10"}	{"condition": "dead_pct > 15", "description": "High dead tuple ratio combined with long-running transactions confirms xmin horizon blocking"}	{"dead_threshold": 10000}	2026-02-25 00:28:52.405273
4711	postgresql	query	Measure dead tuple growth rate against vacuum activity	{"sql": "SELECT schemaname, relname, n_tup_upd + n_tup_del AS total_modifications, n_dead_tup, autovacuum_count, last_autovacuum, ROUND(n_dead_tup::numeric / NULLIF(n_tup_upd + n_tup_del, 0) * 100, 1) AS dead_retention_pct FROM pg_stat_user_tables WHERE n_tup_upd + n_tup_del > :mod_threshold ORDER BY n_dead_tup DESC LIMIT 15"}	{"condition": "dead_retention_pct > 5 AND n_dead_tup > 50000", "description": "Significant dead tuple retention despite active modifications indicates vacuum cannot keep up"}	{"mod_threshold": 100000}	2026-02-25 00:28:52.405273
4712	postgresql	config_check	Check autovacuum worker capacity	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('autovacuum_max_workers', 'autovacuum_naptime', 'autovacuum_vacuum_cost_delay', 'autovacuum_vacuum_cost_limit') ORDER BY name"}	{"condition": "autovacuum_max_workers <= 3", "description": "Default 3 workers may be insufficient for high-write workloads across many tables"}	\N	2026-02-25 00:28:52.405273
4713	postgresql	query	Check transaction ID age relative to wraparound limit	{"sql": "SELECT datname, age(datfrozenxid) AS xid_age, current_setting('autovacuum_freeze_max_age')::bigint AS freeze_max_age, ROUND(age(datfrozenxid)::numeric / current_setting('autovacuum_freeze_max_age')::bigint * 100, 1) AS pct_to_wraparound FROM pg_database WHERE datallowconn ORDER BY xid_age DESC"}	{"condition": "pct_to_wraparound > 50", "description": "Database approaching 50% of autovacuum_freeze_max_age is at risk of emergency anti-wraparound vacuum"}	\N	2026-02-25 00:28:52.405273
4714	postgresql	query	Find tables with oldest frozen transaction IDs	{"sql": "SELECT schemaname, relname, age(relfrozenxid) AS xid_age, pg_size_pretty(pg_total_relation_size(oid)) AS total_size FROM pg_class JOIN pg_stat_user_tables USING (relname) WHERE relkind = 'r' ORDER BY age(relfrozenxid) DESC LIMIT 10"}	{"condition": "xid_age > 100000000", "description": "Tables with very old frozen transaction IDs will trigger emergency anti-wraparound vacuum"}	\N	2026-02-25 00:28:52.405273
4715	postgresql	query	Find heavily updated tables with default fillfactor	{"sql": "SELECT s.schemaname, s.relname, s.n_tup_upd, s.n_tup_hot_upd, CASE WHEN s.n_tup_upd > 0 THEN ROUND(s.n_tup_hot_upd::numeric / s.n_tup_upd * 100, 1) ELSE 0 END AS hot_pct, (SELECT COALESCE((reloptions::text[])[array_position(reloptions::text[], (SELECT x FROM unnest(reloptions) x WHERE x LIKE 'fillfactor=%'))], 'fillfactor=100') FROM pg_class WHERE oid = s.relid) AS fillfactor_setting FROM pg_stat_user_tables s WHERE s.n_tup_upd > :update_threshold ORDER BY s.n_tup_upd DESC LIMIT 15"}	{"condition": "hot_pct < 50", "description": "Low HOT update ratio on heavily updated tables indicates FILLFACTOR is too high to allow in-page updates"}	{"update_threshold": 10000}	2026-02-25 00:28:52.405273
4716	postgresql	query	Check replication lag for connected standbys	{"sql": "SELECT client_addr, application_name, state, sent_lsn, write_lsn, flush_lsn, replay_lsn, pg_wal_lsn_diff(sent_lsn, replay_lsn) AS replay_lag_bytes, pg_size_pretty(pg_wal_lsn_diff(sent_lsn, replay_lsn)) AS replay_lag_pretty FROM pg_stat_replication ORDER BY replay_lag_bytes DESC"}	{"condition": "replay_lag_bytes > :lag_threshold_bytes", "description": "Standbys lagging behind prevent WAL recycling on the primary"}	{"lag_threshold_bytes": 104857600}	2026-02-25 00:28:52.405273
4717	postgresql	query	Check replication slot lag and xmin retention	{"sql": "SELECT slot_name, slot_type, database, active, xmin, catalog_xmin, restart_lsn, confirmed_flush_lsn, age(xmin) AS xmin_age, age(catalog_xmin) AS catalog_xmin_age FROM pg_replication_slots ORDER BY age(COALESCE(xmin, catalog_xmin)) DESC NULLS LAST"}	{"condition": "xmin_age > 1000000 OR catalog_xmin_age > 1000000", "description": "Replication slots with old xmin values hold back vacuum from cleaning old row versions"}	\N	2026-02-25 00:28:52.405273
4718	postgresql	query	Correlate slot retention with table dead tuple accumulation	{"sql": "SELECT schemaname, relname, n_dead_tup, ROUND(n_dead_tup::numeric / NULLIF(n_live_tup, 0) * 100, 1) AS dead_pct FROM pg_stat_user_tables WHERE n_dead_tup > :dead_threshold ORDER BY n_dead_tup DESC LIMIT 10"}	{"condition": "dead_pct > 10", "description": "High dead tuple ratio on multiple tables confirms replication slot is holding back global vacuum progress"}	{"dead_threshold": 10000}	2026-02-25 00:28:52.405273
4719	postgresql	query	Check dead tuple count on autovacuum-disabled tables	{"sql": "SELECT s.schemaname, s.relname, s.n_dead_tup, s.n_live_tup, ROUND(s.n_dead_tup::numeric / NULLIF(s.n_live_tup, 0) * 100, 1) AS dead_pct FROM pg_stat_user_tables s JOIN pg_class c ON s.relid = c.oid WHERE c.reloptions::text LIKE '%autovacuum_enabled=false%' AND s.n_dead_tup > 0 ORDER BY s.n_dead_tup DESC"}	{"condition": "dead_pct > 5", "description": "Dead tuple accumulation on autovacuum-disabled tables confirms bloat from missing maintenance"}	\N	2026-02-25 00:28:52.405273
4720	postgresql	query	Check index-only scan heap fetch ratio	{"sql": "SELECT schemaname, relname, indexrelname, idx_scan, idx_tup_read, idx_tup_fetch, CASE WHEN idx_tup_read > 0 THEN ROUND((idx_tup_read - idx_tup_fetch)::numeric / idx_tup_read * 100, 1) ELSE 0 END AS heap_fetch_avoided_pct FROM pg_stat_user_indexes WHERE idx_scan > :min_scans ORDER BY idx_tup_fetch DESC LIMIT 20"}	{"condition": "heap_fetch_avoided_pct < 50", "description": "Low heap fetch avoidance ratio indicates the visibility map is not up to date"}	{"min_scans": 100}	2026-02-25 00:28:52.405273
4721	postgresql	query	Check last vacuum time on affected tables	{"sql": "SELECT schemaname, relname, last_vacuum, last_autovacuum, n_dead_tup FROM pg_stat_user_tables WHERE relname IN (SELECT relname FROM pg_stat_user_indexes WHERE idx_scan > :min_scans AND CASE WHEN idx_tup_read > 0 THEN (idx_tup_read - idx_tup_fetch)::numeric / idx_tup_read * 100 ELSE 100 END < 50) ORDER BY n_dead_tup DESC"}	{"condition": "last_vacuum IS NULL OR last_vacuum < now() - interval '1 day'", "description": "Tables not recently vacuumed have stale visibility maps, forcing heap fetches on index-only scans"}	{"min_scans": 100}	2026-02-25 00:28:52.405273
4722	postgresql	query	Find large tables with growing dead tuple counts	{"sql": "SELECT schemaname, relname, pg_size_pretty(pg_total_relation_size(relid)) AS total_size, n_dead_tup, n_live_tup, autovacuum_count, last_autovacuum, ROUND(n_dead_tup::numeric / NULLIF(n_live_tup, 0) * 100, 1) AS dead_pct FROM pg_stat_user_tables WHERE pg_total_relation_size(relid) > :size_threshold AND n_dead_tup > :dead_threshold ORDER BY pg_total_relation_size(relid) DESC LIMIT 10"}	{"condition": "dead_pct > 10", "description": "Large tables with growing dead tuples may need more vacuum time than available maintenance windows allow"}	{"dead_threshold": 100000, "size_threshold": 1073741824}	2026-02-25 00:28:52.405273
4723	postgresql	query	Check if vacuum processes are being cancelled or interrupted	{"sql": "SELECT pid, query, state, backend_type, query_start, now() - query_start AS duration FROM pg_stat_activity WHERE query ILIKE '%vacuum%' OR query ILIKE '%VACUUM%' ORDER BY query_start"}	{"condition": "row_count >= 0", "description": "Active vacuum processes and their duration help assess whether maintenance windows are sufficient"}	\N	2026-02-25 00:28:52.405273
4724	postgresql	query	Check tables with high update ratio and low HOT update success	{"sql": "SELECT schemaname, relname, n_tup_upd, n_tup_hot_upd, CASE WHEN n_tup_upd > 0 THEN ROUND(n_tup_hot_upd::numeric / n_tup_upd * 100, 1) ELSE 0 END AS hot_pct, n_dead_tup, pg_size_pretty(pg_total_relation_size(relid)) AS total_size FROM pg_stat_user_tables WHERE n_tup_upd > :update_threshold ORDER BY n_tup_upd DESC LIMIT 15"}	{"condition": "hot_pct < 30 AND n_dead_tup > 10000", "description": "Low HOT update ratio with dead tuple accumulation indicates UPDATE patterns misaligned with table layout"}	{"update_threshold": 50000}	2026-02-25 00:28:52.405273
4725	postgresql	query	Check for tables with vacuum activity but persistent dead tuples	{"sql": "SELECT schemaname, relname, n_dead_tup, autovacuum_count, vacuum_count, last_autovacuum, last_vacuum FROM pg_stat_user_tables WHERE (autovacuum_count > :min_vacuum_count OR vacuum_count > :min_vacuum_count) AND n_dead_tup > :dead_threshold ORDER BY n_dead_tup DESC LIMIT 10"}	{"condition": "n_dead_tup > dead_threshold AND autovacuum_count > min_vacuum_count", "description": "Tables vacuumed multiple times but still retaining dead tuples may have pinned buffer issues"}	{"dead_threshold": 50000, "min_vacuum_count": 5}	2026-02-25 00:28:52.405273
4726	postgresql	query	Check for concurrent long-running queries on affected tables	{"sql": "SELECT pid, state, wait_event_type, wait_event, LEFT(query, 200) AS query_preview, now() - query_start AS duration FROM pg_stat_activity WHERE state = 'active' AND wait_event_type = 'BufferPin' ORDER BY duration DESC"}	{"condition": "row_count > 0", "description": "BufferPin wait events confirm concurrent access preventing vacuum from processing pages"}	\N	2026-02-25 00:28:52.405273
4727	postgresql	query	Estimate index bloat from size vs expected size	{"sql": "SELECT schemaname, relname AS table_name, indexrelname AS index_name, pg_size_pretty(pg_relation_size(indexrelid)) AS index_size, idx_scan, idx_tup_read, idx_tup_fetch FROM pg_stat_user_indexes WHERE pg_relation_size(indexrelid) > :min_index_size ORDER BY pg_relation_size(indexrelid) DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Large indexes relative to table size may be bloated with dead entries"}	{"min_index_size": 104857600}	2026-02-25 00:28:52.405273
4728	postgresql	query	Compare index size to table size for bloat indicators	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, pg_size_pretty(pg_relation_size(s.relid)) AS table_size, ROUND(pg_relation_size(s.indexrelid)::numeric / NULLIF(pg_relation_size(s.relid), 0) * 100, 1) AS idx_to_tbl_pct FROM pg_stat_user_indexes s WHERE pg_relation_size(s.indexrelid) > pg_relation_size(s.relid) * :bloat_ratio ORDER BY pg_relation_size(s.indexrelid) DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Indexes larger than the table they reference are very likely bloated"}	{"bloat_ratio": 0.5}	2026-02-25 00:28:52.405273
4729	postgresql	query	Find tables with UUID primary key columns	{"sql": "SELECT n.nspname, c.relname, a.attname, t.typname FROM pg_index i JOIN pg_class c ON i.indrelid = c.oid JOIN pg_namespace n ON c.relnamespace = n.oid JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = ANY(i.indkey) JOIN pg_type t ON a.atttypid = t.oid WHERE i.indisprimary AND t.typname = 'uuid' AND n.nspname NOT IN ('pg_catalog', 'information_schema')"}	{"condition": "row_count > 0", "description": "Tables with UUID primary keys are candidates for random insert page splits"}	\N	2026-02-25 00:28:52.405273
4730	postgresql	query	Check index bloat ratio on UUID-keyed tables	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, pg_size_pretty(pg_relation_size(s.relid)) AS table_size, ROUND(pg_relation_size(s.indexrelid)::numeric / NULLIF(pg_relation_size(s.relid), 0) * 100, 1) AS idx_to_tbl_pct FROM pg_stat_user_indexes s JOIN pg_index i ON s.indexrelid = i.indexrelid JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey) JOIN pg_type t ON a.atttypid = t.oid WHERE i.indisprimary AND t.typname = 'uuid' ORDER BY pg_relation_size(s.indexrelid) DESC"}	{"condition": "idx_to_tbl_pct > 30", "description": "UUID indexes disproportionately large relative to table size confirms page split fragmentation"}	\N	2026-02-25 00:28:52.405273
4731	postgresql	query	Find non-PK indexes on low-cardinality columns with high insert rates	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, t.n_tup_ins FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relid = t.relid JOIN pg_index i ON s.indexrelid = i.indexrelid WHERE NOT i.indisprimary AND t.n_tup_ins > :insert_threshold ORDER BY t.n_tup_ins DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Non-PK indexes on heavily inserted tables are candidates for localized page splits"}	{"insert_threshold": 100000}	2026-02-25 00:28:52.405273
4732	postgresql	query	Check index size relative to expected row count	{"sql": "SELECT s.indexrelname, pg_relation_size(s.indexrelid) AS index_bytes, t.n_live_tup, CASE WHEN t.n_live_tup > 0 THEN pg_relation_size(s.indexrelid) / t.n_live_tup ELSE 0 END AS bytes_per_row FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relid = t.relid JOIN pg_index i ON s.indexrelid = i.indexrelid WHERE NOT i.indisprimary AND t.n_tup_ins > :insert_threshold ORDER BY bytes_per_row DESC LIMIT 10"}	{"condition": "bytes_per_row > :expected_bytes_per_row", "description": "High bytes per row in index indicates fragmentation from page splits"}	{"insert_threshold": 100000, "expected_bytes_per_row": 100}	2026-02-25 00:28:52.405273
4733	postgresql	query	Find tables with high insert and delete churn	{"sql": "SELECT schemaname, relname, n_tup_ins, n_tup_del, n_tup_upd, n_live_tup, CASE WHEN n_live_tup > 0 THEN ROUND((n_tup_ins + n_tup_del)::numeric / n_live_tup, 1) ELSE 0 END AS churn_ratio FROM pg_stat_user_tables WHERE n_tup_ins > :churn_threshold AND n_tup_del > :churn_threshold ORDER BY churn_ratio DESC LIMIT 10"}	{"condition": "churn_ratio > 2", "description": "Churn ratio above 2x means the table has been fully churned multiple times, causing B-tree imbalance"}	{"churn_threshold": 50000}	2026-02-25 00:28:52.405273
4734	postgresql	query	Check index bloat on high-churn tables	{"sql": "SELECT s.indexrelname, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, pg_size_pretty(pg_relation_size(s.relid)) AS table_size, ROUND(pg_relation_size(s.indexrelid)::numeric / NULLIF(pg_relation_size(s.relid), 0) * 100, 1) AS idx_to_tbl_pct FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relid = t.relid WHERE (t.n_tup_ins + t.n_tup_del)::numeric / NULLIF(t.n_live_tup, 0) > 2 ORDER BY pg_relation_size(s.indexrelid) DESC LIMIT 10"}	{"condition": "idx_to_tbl_pct > 50", "description": "Indexes significantly larger than tables on high-churn tables confirms B-tree fragmentation"}	\N	2026-02-25 00:28:52.405273
4757	postgresql	query	Find active sessions with long wait times	{"sql": "SELECT pid, usename, application_name, state, wait_event_type, wait_event, now() - query_start AS query_duration, LEFT(query, 200) AS query_preview FROM pg_stat_activity WHERE state = 'active' AND wait_event IS NOT NULL AND backend_type = 'client backend' ORDER BY query_start ASC LIMIT 20"}	{"condition": "row_count > 0 AND query_duration > interval '10 seconds'", "description": "Active sessions waiting on events indicate application threads blocked waiting for database response"}	\N	2026-02-25 00:28:52.405273
4735	postgresql	query	Find indexes with fillfactor set to 100 or default	{"sql": "SELECT n.nspname, c.relname AS index_name, c2.relname AS table_name, c.reloptions, COALESCE((SELECT regexp_replace(x, 'fillfactor=', '')::int FROM unnest(c.reloptions) x WHERE x LIKE 'fillfactor=%'), 90) AS fillfactor FROM pg_class c JOIN pg_index i ON c.oid = i.indexrelid JOIN pg_class c2 ON i.indrelid = c2.oid JOIN pg_namespace n ON c.relnamespace = n.oid WHERE c.relkind = 'i' AND n.nspname NOT IN ('pg_catalog', 'information_schema') AND COALESCE((SELECT regexp_replace(x, 'fillfactor=', '')::int FROM unnest(c.reloptions) x WHERE x LIKE 'fillfactor=%'), 90) >= 100"}	{"condition": "row_count > 0", "description": "Indexes with fillfactor 100 have no free space for new entries"}	\N	2026-02-25 00:28:52.405273
4736	postgresql	query	Check if affected tables have significant insert activity	{"sql": "SELECT s.relname, t.n_tup_ins, t.n_tup_upd FROM pg_stat_user_tables t JOIN pg_stat_user_indexes s ON t.relid = s.relid JOIN pg_class c ON s.indexrelid = c.oid WHERE COALESCE((SELECT regexp_replace(x, 'fillfactor=', '')::int FROM unnest(c.reloptions) x WHERE x LIKE 'fillfactor=%'), 90) >= 100 AND t.n_tup_ins > :insert_threshold ORDER BY t.n_tup_ins DESC"}	{"condition": "row_count > 0", "description": "Indexes with fillfactor 100 on actively inserted tables confirm page split problem"}	{"insert_threshold": 10000}	2026-02-25 00:28:52.405273
11494	mysql	query	Check for third-party application databases	{"sql": "SELECT SCHEMA_NAME FROM information_schema.SCHEMATA WHERE SCHEMA_NAME NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY SCHEMA_NAME"}	{"condition": "row_count > 0", "description": "Application databases exist alongside local_infile=ON, suggesting vendor deployment templates"}	\N	2026-03-01 06:30:58.706791
4737	postgresql	query	Analyze index fillfactor settings against table write patterns	{"sql": "SELECT n.nspname, c2.relname AS table_name, c.relname AS index_name, COALESCE((SELECT regexp_replace(x, 'fillfactor=', '')::int FROM unnest(c.reloptions) x WHERE x LIKE 'fillfactor=%'), 90) AS fillfactor, t.n_tup_ins, t.n_tup_upd, pg_size_pretty(pg_relation_size(c.oid)) AS index_size FROM pg_class c JOIN pg_index i ON c.oid = i.indexrelid JOIN pg_class c2 ON i.indrelid = c2.oid JOIN pg_namespace n ON c.relnamespace = n.oid JOIN pg_stat_user_tables t ON i.indrelid = t.relid WHERE c.relkind = 'i' AND n.nspname NOT IN ('pg_catalog', 'information_schema') AND t.n_tup_ins > :insert_threshold ORDER BY t.n_tup_ins DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Review fillfactor settings against insert volume to identify mismatches"}	{"insert_threshold": 50000}	2026-02-25 00:28:52.405273
4738	postgresql	query	Check for buffer content lock waits on index pages	{"sql": "SELECT wait_event_type, wait_event, count(*) AS wait_count FROM pg_stat_activity WHERE state = 'active' AND wait_event_type = 'Lock' AND wait_event IN ('relation', 'extend', 'page') GROUP BY wait_event_type, wait_event ORDER BY wait_count DESC"}	{"condition": "row_count > 0", "description": "Lock waits on relation extend or page operations indicate concurrent insert contention"}	\N	2026-02-25 00:28:52.405273
4739	postgresql	query	Identify tables with concurrent insert activity	{"sql": "SELECT schemaname, relname, n_tup_ins, n_live_tup FROM pg_stat_user_tables WHERE n_tup_ins > :insert_threshold ORDER BY n_tup_ins DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Heavily inserted tables combined with lock contention confirms narrow-range insert issue"}	{"insert_threshold": 100000}	2026-02-25 00:28:52.405273
4740	postgresql	query	Check index depth and page count for bloated indexes	{"sql": "SELECT c.relname AS index_name, c2.relname AS table_name, pg_size_pretty(pg_relation_size(c.oid)) AS index_size, pg_relation_size(c.oid) / 8192 AS page_count, t.n_live_tup FROM pg_class c JOIN pg_index i ON c.oid = i.indexrelid JOIN pg_class c2 ON i.indrelid = c2.oid JOIN pg_stat_user_tables t ON i.indrelid = t.relid WHERE c.relkind = 'i' AND pg_relation_size(c.oid) > :min_index_size ORDER BY pg_relation_size(c.oid) DESC LIMIT 10"}	{"condition": "page_count / n_live_tup > :pages_per_row_threshold", "description": "Excessive pages per row indicates fragmented B-tree from cascading splits"}	{"min_index_size": 104857600, "pages_per_row_threshold": 0.01}	2026-02-25 00:28:52.405273
4741	postgresql	query	Find indexes with wide key columns	{"sql": "SELECT n.nspname, c2.relname AS table_name, c.relname AS index_name, a.attname, CASE WHEN t.typlen > 0 THEN t.typlen WHEN t.typname = 'text' OR t.typname = 'varchar' THEN a.atttypmod - 4 ELSE -1 END AS approx_col_width FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class c2 ON c2.oid = i.indrelid JOIN pg_namespace n ON c.relnamespace = n.oid JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey) JOIN pg_type t ON a.atttypid = t.oid WHERE c.relkind = 'i' AND n.nspname NOT IN ('pg_catalog', 'information_schema') AND (t.typlen > :width_threshold OR (t.typname IN ('text', 'varchar') AND a.atttypmod > :width_threshold)) ORDER BY approx_col_width DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Indexes on wide columns (>200 bytes) fill pages quickly, causing frequent splits"}	{"width_threshold": 200}	2026-02-25 00:28:52.405273
4742	postgresql	query	Find UUID-keyed tables with high concurrent insert activity	{"sql": "SELECT c2.relname AS table_name, a.attname AS pk_column, t.n_tup_ins, (SELECT count(*) FROM pg_stat_activity WHERE state = 'active' AND query ILIKE '%INSERT%' || c2.relname || '%') AS concurrent_inserters FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class c2 ON c2.oid = i.indrelid JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey) JOIN pg_type tp ON a.atttypid = tp.oid JOIN pg_stat_user_tables t ON i.indrelid = t.relid WHERE i.indisprimary AND tp.typname = 'uuid' AND t.n_tup_ins > :insert_threshold ORDER BY t.n_tup_ins DESC"}	{"condition": "row_count > 0 AND concurrent_inserters > 1", "description": "UUID-keyed tables with multiple concurrent insert sessions"}	{"insert_threshold": 50000}	2026-02-25 00:28:52.405273
4743	postgresql	query	Check for extension wait events related to B-tree operations	{"sql": "SELECT wait_event_type, wait_event, count(*) AS wait_count FROM pg_stat_activity WHERE state = 'active' AND wait_event_type IN ('LWLock', 'Lock', 'BufferPin') GROUP BY wait_event_type, wait_event ORDER BY wait_count DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "LWLock or BufferPin waits during concurrent UUID inserts confirms page split contention"}	\N	2026-02-25 00:28:52.405273
4744	postgresql	query	Check recently reindexed tables with growing index size	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, t.n_tup_ins, t.n_tup_upd, COALESCE((SELECT regexp_replace(x, 'fillfactor=', '')::int FROM unnest(c.reloptions) x WHERE x LIKE 'fillfactor=%'), 90) AS fillfactor FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relid = t.relid JOIN pg_class c ON s.indexrelid = c.oid WHERE t.n_tup_ins > :insert_threshold ORDER BY pg_relation_size(s.indexrelid) DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Review fillfactor against insert/update patterns to identify misconfigured rebuilds"}	{"insert_threshold": 50000}	2026-02-25 00:28:52.405273
4758	postgresql	query	Count connections by application and client address	{"sql": "SELECT application_name, client_addr, count(*) AS conn_count FROM pg_stat_activity WHERE backend_type = 'client backend' GROUP BY application_name, client_addr ORDER BY conn_count DESC"}	{"condition": "row_count > :instance_threshold", "description": "Multiple client addresses with same application name indicates multiple instances competing"}	{"instance_threshold": 5}	2026-02-25 00:28:52.405273
4745	postgresql	query	Find non-PK indexes on sequential-like columns with high insert rates	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, t.n_tup_ins FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relid = t.relid JOIN pg_index i ON s.indexrelid = i.indexrelid WHERE NOT i.indisprimary AND t.n_tup_ins > :insert_threshold AND pg_relation_size(s.indexrelid) > :min_index_size ORDER BY pg_relation_size(s.indexrelid) DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Non-PK indexes that grow rapidly may be fragmenting from non-monotonic sequential inserts"}	{"min_index_size": 52428800, "insert_threshold": 100000}	2026-02-25 00:28:52.405273
4746	postgresql	query	Count indexes per table including FK indexes	{"sql": "SELECT c.relname AS table_name, count(i.indexrelid) AS index_count, t.n_tup_ins FROM pg_class c JOIN pg_index i ON c.oid = i.indrelid JOIN pg_stat_user_tables t ON c.oid = t.relid WHERE c.relkind = 'r' AND c.relnamespace NOT IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')) GROUP BY c.relname, t.n_tup_ins HAVING count(i.indexrelid) > :index_threshold ORDER BY count(i.indexrelid) DESC LIMIT 15"}	{"condition": "index_count > 5 AND n_tup_ins > 50000", "description": "Tables with many indexes and high insert rates experience multiplied page split overhead"}	{"index_threshold": 5}	2026-02-25 00:28:52.405273
4747	postgresql	query	Check total index size relative to table size	{"sql": "SELECT c.relname, pg_size_pretty(pg_relation_size(c.oid)) AS table_size, pg_size_pretty(pg_indexes_size(c.oid)) AS total_index_size, ROUND(pg_indexes_size(c.oid)::numeric / NULLIF(pg_relation_size(c.oid), 0) * 100, 1) AS idx_overhead_pct FROM pg_class c JOIN pg_stat_user_tables t ON c.oid = t.relid WHERE t.n_tup_ins > :insert_threshold ORDER BY pg_indexes_size(c.oid) DESC LIMIT 10"}	{"condition": "idx_overhead_pct > 200", "description": "Total index size more than 2x table size indicates heavy index overhead from FK indexes"}	{"insert_threshold": 50000}	2026-02-25 00:28:52.405273
4763	postgresql	query	Find connections idle for extremely long periods	{"sql": "SELECT pid, usename, application_name, state, state_change, now() - state_change AS idle_duration, client_addr FROM pg_stat_activity WHERE state = 'idle' AND now() - state_change > interval ':idle_threshold hours' AND backend_type = 'client backend' ORDER BY state_change ASC"}	{"condition": "row_count > 0", "description": "Connections idle for many hours may be stale and should be validated or recycled"}	{"idle_threshold": 4}	2026-02-25 00:28:52.405273
4748	postgresql	query	Find indexes on low-cardinality columns	{"sql": "SELECT n.nspname, c2.relname AS table_name, c.relname AS index_name, a.attname, s.n_distinct, pg_size_pretty(pg_relation_size(c.oid)) AS index_size FROM pg_stats s JOIN pg_class c2 ON s.tablename = c2.relname JOIN pg_namespace n ON c2.relnamespace = n.oid JOIN pg_index i ON c2.oid = i.indrelid JOIN pg_class c ON i.indexrelid = c.oid JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey) AND a.attname = s.attname WHERE s.n_distinct > 0 AND s.n_distinct < :cardinality_threshold AND n.nspname NOT IN ('pg_catalog', 'information_schema') ORDER BY s.n_distinct ASC LIMIT 15"}	{"condition": "row_count > 0 AND n_distinct < 20", "description": "Indexes on columns with fewer than 20 distinct values concentrate activity on few pages"}	{"cardinality_threshold": 20}	2026-02-25 00:28:52.405273
4749	postgresql	query	Check current connection count versus max_connections	{"sql": "SELECT count(*) AS current_connections, (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') AS max_connections, ROUND(count(*)::numeric / (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') * 100, 1) AS usage_pct FROM pg_stat_activity"}	{"condition": "usage_pct > :threshold_pct", "description": "Connection utilization above threshold indicates pool nearing exhaustion"}	{"threshold_pct": 80}	2026-02-25 00:28:52.405273
4750	postgresql	query	Break down connections by state and application	{"sql": "SELECT application_name, state, count(*) AS conn_count FROM pg_stat_activity WHERE backend_type = 'client backend' GROUP BY application_name, state ORDER BY conn_count DESC"}	{"condition": "row_count > 0", "description": "Distribution of connections by application and state shows where pool pressure originates"}	\N	2026-02-25 00:28:52.405273
4751	postgresql	query	Find sessions with long-running transactions	{"sql": "SELECT pid, usename, application_name, state, xact_start, now() - xact_start AS xact_duration, LEFT(query, 200) AS query_preview FROM pg_stat_activity WHERE xact_start IS NOT NULL AND now() - xact_start > interval ':threshold_minutes minutes' AND backend_type = 'client backend' ORDER BY xact_start ASC"}	{"condition": "row_count > 0", "description": "Sessions with transactions open longer than threshold are holding connections unnecessarily"}	{"threshold_minutes": 10}	2026-02-25 00:28:52.405273
4752	postgresql	query	Find idle sessions with open transactions	{"sql": "SELECT pid, usename, application_name, state, xact_start, state_change, now() - state_change AS idle_duration, LEFT(query, 200) AS last_query FROM pg_stat_activity WHERE state = 'idle in transaction' AND now() - state_change > interval ':idle_threshold minutes' AND backend_type = 'client backend' ORDER BY state_change ASC"}	{"condition": "row_count > 0", "description": "Sessions idle in transaction for extended periods are likely leaked connections"}	{"idle_threshold": 30}	2026-02-25 00:28:52.405273
4753	postgresql	query	Find long-running active queries consuming connections	{"sql": "SELECT pid, usename, application_name, state, query_start, now() - query_start AS query_duration, wait_event_type, wait_event, LEFT(query, 200) AS query_preview FROM pg_stat_activity WHERE state = 'active' AND backend_type = 'client backend' AND now() - query_start > interval ':threshold_seconds seconds' ORDER BY query_start ASC"}	{"condition": "row_count > 0", "description": "Active queries running longer than threshold are holding connections open"}	{"threshold_seconds": 60}	2026-02-25 00:28:52.405273
4754	postgresql	query	Check if slow queries correlate with connection pressure	{"sql": "SELECT count(*) AS total_connections, count(*) FILTER (WHERE state = 'active' AND now() - query_start > interval '60 seconds') AS slow_queries, ROUND(count(*) FILTER (WHERE state = 'active' AND now() - query_start > interval '60 seconds')::numeric / NULLIF(count(*), 0) * 100, 1) AS slow_pct FROM pg_stat_activity WHERE backend_type = 'client backend'"}	{"condition": "slow_pct > 10", "description": "Significant percentage of connections occupied by slow queries confirms connection pool pressure"}	\N	2026-02-25 00:28:52.405273
4755	postgresql	query	Find blocking lock chains between sessions	{"sql": "SELECT blocked.pid AS blocked_pid, blocked.usename AS blocked_user, blocking.pid AS blocking_pid, blocking.usename AS blocking_user, blocked.state AS blocked_state, LEFT(blocked.query, 150) AS blocked_query, LEFT(blocking.query, 150) AS blocking_query, now() - blocked.query_start AS blocked_duration FROM pg_stat_activity blocked JOIN pg_locks bl ON blocked.pid = bl.pid JOIN pg_locks l ON l.locktype = bl.locktype AND l.database IS NOT DISTINCT FROM bl.database AND l.relation IS NOT DISTINCT FROM bl.relation AND l.page IS NOT DISTINCT FROM bl.page AND l.tuple IS NOT DISTINCT FROM bl.tuple AND l.transactionid IS NOT DISTINCT FROM bl.transactionid AND l.virtualxid IS NOT DISTINCT FROM bl.virtualxid AND l.pid != bl.pid JOIN pg_stat_activity blocking ON l.pid = blocking.pid WHERE NOT bl.granted ORDER BY blocked_duration DESC"}	{"condition": "row_count > 0", "description": "Blocked sessions waiting for locks are holding connections that cannot be returned to the pool"}	\N	2026-02-25 00:28:52.405273
4759	postgresql	query	Check total connections relative to max_connections	{"sql": "SELECT count(*) AS total, (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') AS max_conn, ROUND(count(*)::numeric / (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') * 100, 1) AS usage_pct FROM pg_stat_activity"}	{"condition": "usage_pct > 70", "description": "High connection utilization from multiple instances confirms resource contention"}	\N	2026-02-25 00:28:52.405273
4760	postgresql	query	Find sessions holding locks that block others	{"sql": "SELECT l.pid, a.usename, l.locktype, l.mode, l.granted, c.relname, a.state, LEFT(a.query, 200) AS query_preview FROM pg_locks l JOIN pg_stat_activity a ON l.pid = a.pid LEFT JOIN pg_class c ON l.relation = c.oid WHERE NOT l.granted OR l.mode IN ('ExclusiveLock', 'AccessExclusiveLock', 'ShareRowExclusiveLock') ORDER BY l.granted, a.query_start"}	{"condition": "row_count > 0", "description": "Sessions holding exclusive locks or waiting for locks indicate blocking contention"}	\N	2026-02-25 00:28:52.405273
