4765	postgresql	query	Find applications with high connection-to-activity ratio	{"sql": "SELECT application_name, count(*) AS total_connections, count(*) FILTER (WHERE state = 'active') AS active_connections, count(*) FILTER (WHERE state = 'idle') AS idle_connections, ROUND(count(*) FILTER (WHERE state = 'idle')::numeric / NULLIF(count(*), 0) * 100, 1) AS idle_pct FROM pg_stat_activity WHERE backend_type = 'client backend' GROUP BY application_name HAVING count(*) > :conn_threshold ORDER BY total_connections DESC"}	{"condition": "idle_pct > 80", "description": "Applications with over 80% idle connections are holding more connections than needed"}	{"conn_threshold": 5}	2026-02-25 00:28:52.405273
