5064	postgresql	query	Find indexes on UUID columns	{"sql": "SELECT c.relname AS table_name, i.relname AS index_name, a.attname AS column_name, a.atttypid::regtype AS column_type FROM pg_index idx JOIN pg_class c ON c.oid = idx.indrelid JOIN pg_class i ON i.oid = idx.indexrelid JOIN pg_attribute a ON a.attrelid = idx.indrelid AND a.attnum = idx.indkey[0] WHERE a.atttypid::regtype::text = 'uuid' AND c.relnamespace NOT IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema'))"}	{"condition": "row_count > 0", "description": "UUID-indexed columns are susceptible to random insert fragmentation"}	\N	2026-02-25 00:28:52.405273
5065	postgresql	query	Estimate index bloat from page utilization	{"sql": "SELECT nspname, relname, pg_size_pretty(pg_relation_size(c.oid)) AS index_size, pg_size_pretty(pg_relation_size(c.oid) - (c.reltuples * 48)::bigint) AS estimated_bloat FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.relkind = 'i' AND n.nspname NOT IN ('pg_catalog', 'information_schema') AND c.reltuples > :tuple_threshold ORDER BY pg_relation_size(c.oid) - (c.reltuples * 48)::bigint DESC LIMIT 10"}	{"condition": "estimated_bloat is significant portion of index_size", "description": "Large gap between actual index size and estimated size based on tuple count indicates fragmentation/bloat"}	{"tuple_threshold": 10000}	2026-02-25 00:28:52.405273
5066	postgresql	query	Find tables with high dead tuple counts	{"sql": "SELECT schemaname, relname, n_live_tup, n_dead_tup, n_dead_tup::float / GREATEST(n_live_tup + n_dead_tup, 1) AS dead_ratio, last_vacuum, last_autovacuum FROM pg_stat_user_tables WHERE n_dead_tup > :dead_threshold ORDER BY n_dead_tup DESC LIMIT 10"}	{"condition": "dead_ratio > :ratio_threshold", "description": "High dead tuple ratio indicates mass deletes leaving dead space in tables and their indexes"}	{"dead_threshold": 10000, "ratio_threshold": 0.2}	2026-02-25 00:28:52.405273
5067	postgresql	query	Compare index size to estimated live tuple size	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, pg_size_pretty(pg_relation_size(s.relid)) AS table_size FROM pg_stat_user_indexes s WHERE s.relname IN (SELECT relname FROM pg_stat_user_tables WHERE n_dead_tup::float / GREATEST(n_live_tup + n_dead_tup, 1) > :ratio_threshold) ORDER BY pg_relation_size(s.indexrelid) DESC LIMIT 10"}	{"condition": "index_size is disproportionately large", "description": "Oversized indexes relative to live data confirm dead tuple bloat"}	{"ratio_threshold": 0.2}	2026-02-25 00:28:52.405273
5068	postgresql	query	Find tables with high HOT update failure rate	{"sql": "SELECT schemaname, relname, n_tup_upd, n_tup_hot_upd, (n_tup_upd - n_tup_hot_upd)::float / GREATEST(n_tup_upd, 1) AS non_hot_ratio FROM pg_stat_user_tables WHERE n_tup_upd > :update_threshold ORDER BY non_hot_ratio DESC LIMIT 10"}	{"condition": "non_hot_ratio > :ratio_threshold", "description": "High non-HOT update ratio means updates are modifying indexed columns, causing index entry movement"}	{"ratio_threshold": 0.5, "update_threshold": 10000}	2026-02-25 00:28:52.405273
5069	postgresql	query	Check index sizes on high-update tables for bloat	{"sql": "SELECT s.relname, s.indexrelname, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, pg_size_pretty(pg_relation_size(s.relid)) AS table_size, pg_relation_size(s.indexrelid)::float / GREATEST(pg_relation_size(s.relid), 1) AS index_to_table_ratio FROM pg_stat_user_indexes s WHERE s.relname IN (SELECT relname FROM pg_stat_user_tables WHERE (n_tup_upd - n_tup_hot_upd)::float / GREATEST(n_tup_upd, 1) > :ratio_threshold AND n_tup_upd > :update_threshold) ORDER BY pg_relation_size(s.indexrelid) DESC LIMIT 10"}	{"condition": "index_to_table_ratio > :size_ratio_threshold", "description": "Index size disproportionate to table size confirms fragmentation from non-HOT updates"}	{"ratio_threshold": 0.5, "update_threshold": 10000, "size_ratio_threshold": 0.5}	2026-02-25 00:28:52.405273
5092	postgresql	query	Check if these indexes have any scan activity	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan FROM pg_stat_user_indexes s WHERE s.indexrelname ~* '(backup|bak|tmp|temp|test|old|new|copy|v2|_2|_dup)'"}	{"condition": "idx_scan = 0", "description": "Zero scans confirms these are leftover test/backup indexes adding unnecessary write overhead"}	\N	2026-02-25 00:28:52.405273
5070	postgresql	query	Check insert activity on tables with multiple index types	{"sql": "SELECT t.schemaname, t.relname, t.n_tup_ins, t.n_tup_upd, count(DISTINCT i.indexname) AS index_count FROM pg_stat_user_tables t JOIN pg_indexes i ON t.relname = i.tablename AND t.schemaname = i.schemaname WHERE t.n_tup_ins > :insert_threshold GROUP BY t.schemaname, t.relname, t.n_tup_ins, t.n_tup_upd HAVING count(DISTINCT i.indexname) > 1 ORDER BY t.n_tup_ins DESC LIMIT 10"}	{"condition": "n_tup_ins > :insert_threshold AND index_count > 1", "description": "Tables with high inserts and multiple indexes may have mixed sequential/random patterns across different indexes"}	{"insert_threshold": 100000}	2026-02-25 00:28:52.405273
5071	postgresql	query	Estimate index bloat percentage	{"sql": "SELECT c.relname AS index_name, pg_size_pretty(pg_relation_size(c.oid)) AS actual_size, c.reltuples AS estimated_tuples, c.relpages AS actual_pages FROM pg_class c WHERE c.relkind = 'i' AND c.relnamespace NOT IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')) AND c.reltuples > :tuple_threshold ORDER BY pg_relation_size(c.oid) DESC LIMIT 10"}	{"condition": "actual_pages significantly higher than expected for tuple count", "description": "Page count exceeding expected density indicates fragmentation from mixed insert patterns"}	{"tuple_threshold": 10000}	2026-02-25 00:28:52.405273
