5076	postgresql	query	Find varchar/text columns on frequently updated tables with indexes	{"sql": "SELECT t.relname, a.attname, a.atttypid::regtype AS data_type, s.avg_width, pg_stat.n_tup_upd FROM pg_attribute a JOIN pg_class t ON a.attrelid = t.oid JOIN pg_stats s ON s.tablename = t.relname AND s.attname = a.attname JOIN pg_stat_user_tables pg_stat ON pg_stat.relname = t.relname WHERE a.atttypid IN ('text'::regtype, 'varchar'::regtype, 'character varying'::regtype) AND pg_stat.n_tup_upd > :update_threshold AND EXISTS (SELECT 1 FROM pg_index idx WHERE idx.indrelid = t.oid AND a.attnum = ANY(idx.indkey)) ORDER BY pg_stat.n_tup_upd DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Indexed varchar/text columns on write-heavy tables are candidates for expansion-caused fragmentation"}	{"update_threshold": 10000}	2026-02-25 00:28:52.405273
