5089	postgresql	query	Find indexes with identical column structure and different names	{"sql": "SELECT a.indrelid::regclass AS table_name, a.indexrelid::regclass AS index_1, b.indexrelid::regclass AS index_2, a.indkey AS columns_1, b.indkey AS columns_2 FROM pg_index a JOIN pg_index b ON a.indrelid = b.indrelid AND a.indexrelid < b.indexrelid AND a.indkey = b.indkey WHERE a.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Identically-structured indexes with different names suggest independent creation from separate branches"}	\N	2026-02-25 00:28:52.405273
5079	postgresql	query	Check correlation between physical and logical ordering	{"sql": "SELECT tablename, attname, correlation FROM pg_stats WHERE tablename IN (SELECT c.relname FROM pg_index i JOIN pg_class c ON c.oid = i.indrelid JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0] WHERE i.indisprimary AND a.atttypid::regtype::text IN ('uuid', 'text', 'varchar', 'character varying')) AND attname IN (SELECT a.attname FROM pg_index i JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0] WHERE i.indisprimary)"}	{"condition": "abs(correlation) < :correlation_threshold", "description": "Low correlation between physical and logical order confirms scattered/fragmented storage"}	{"correlation_threshold": 0.5}	2026-02-25 00:28:52.405273
5080	postgresql	query	Find potentially bloated indexes by size vs tuple ratio	{"sql": "SELECT schemaname, relname, indexrelname, pg_size_pretty(pg_relation_size(indexrelid)) AS index_size, idx_scan, (SELECT reltuples FROM pg_class WHERE oid = indexrelid) AS est_tuples, pg_relation_size(indexrelid) / GREATEST((SELECT reltuples FROM pg_class WHERE oid = indexrelid)::bigint, 1) AS bytes_per_tuple FROM pg_stat_user_indexes WHERE pg_relation_size(indexrelid) > :size_threshold ORDER BY pg_relation_size(indexrelid) DESC LIMIT 20"}	{"condition": "bytes_per_tuple > :bytes_threshold", "description": "High bytes-per-tuple ratio suggests significant index bloat from lack of maintenance"}	{"size_threshold": 10485760, "bytes_threshold": 200}	2026-02-25 00:28:52.405273
5081	postgresql	query	Check table write activity indicating ongoing fragmentation	{"sql": "SELECT t.schemaname, t.relname, t.n_tup_ins, t.n_tup_upd, t.n_tup_del FROM pg_stat_user_tables t WHERE t.n_tup_ins + t.n_tup_upd + t.n_tup_del > :write_threshold ORDER BY t.n_tup_ins + t.n_tup_upd + t.n_tup_del DESC LIMIT 10"}	{"condition": "high write activity on bloated index tables", "description": "Continuous write activity without REINDEX confirms fragmentation compounding over time"}	{"write_threshold": 100000}	2026-02-25 00:28:52.405273
