5084	postgresql	query	Find indexes with identical column definitions	{"sql": "SELECT a.indrelid::regclass AS table_name, a.indexrelid::regclass AS index_a, b.indexrelid::regclass AS index_b, pg_size_pretty(pg_relation_size(a.indexrelid)) AS size_a, pg_size_pretty(pg_relation_size(b.indexrelid)) AS size_b FROM pg_index a JOIN pg_index b ON a.indrelid = b.indrelid AND a.indexrelid < b.indexrelid AND a.indkey = b.indkey AND a.indisunique = b.indisunique AND a.indisprimary = b.indisprimary WHERE a.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Indexes with identical key columns on the same table are exact duplicates"}	\N	2026-02-25 00:28:52.405273
5172	postgresql	query	Check for sessions blocked by the DDL operation	{"sql": "SELECT count(*) AS blocked_sessions FROM pg_locks WHERE NOT granted AND relation IS NOT NULL"}	{"condition": "blocked_sessions > :threshold", "description": "Blocked sessions confirm DDL metadata lock is causing lock wait timeouts"}	{"threshold": 1}	2026-02-25 00:28:52.405273
5085	postgresql	query	Find indexes where one is a prefix of another	{"sql": "SELECT a.indrelid::regclass AS table_name, a.indexrelid::regclass AS narrow_index, b.indexrelid::regclass AS wider_index, a.indnatts AS narrow_cols, b.indnatts AS wider_cols FROM pg_index a JOIN pg_index b ON a.indrelid = b.indrelid AND a.indexrelid != b.indexrelid AND a.indnatts < b.indnatts AND a.indkey::text = (SELECT string_agg(x::text, ' ') FROM unnest(b.indkey[0:a.indnatts-1]) AS x) WHERE a.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Narrower index whose columns are a leading prefix of wider index is redundant"}	\N	2026-02-25 00:28:52.405273
5086	postgresql	query	Find indexes with INCLUDE columns on tables with multiple indexes	{"sql": "SELECT idx.indrelid::regclass AS table_name, c.relname AS index_name, idx.indnatts AS total_cols, idx.indnkeyatts AS key_cols, (idx.indnatts - idx.indnkeyatts) AS include_cols FROM pg_index idx JOIN pg_class c ON c.oid = idx.indexrelid WHERE idx.indnatts > idx.indnkeyatts AND idx.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Indexes with INCLUDE columns may overlap with other indexes covering the same key + included columns"}	\N	2026-02-25 00:28:52.405273
5087	postgresql	query	Check for other indexes on the same table with matching key columns	{"sql": "SELECT a.indrelid::regclass AS table_name, a.indexrelid::regclass AS include_index, b.indexrelid::regclass AS other_index FROM pg_index a JOIN pg_index b ON a.indrelid = b.indrelid AND a.indexrelid != b.indexrelid WHERE a.indnatts > a.indnkeyatts AND a.indkey[0:a.indnkeyatts-1] = b.indkey[0:a.indnkeyatts-1] AND a.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Indexes with matching key columns where one uses INCLUDE create redundancy"}	\N	2026-02-25 00:28:52.405273
5088	postgresql	query	Find single-column indexes that are leading column of composites	{"sql": "SELECT a.indrelid::regclass AS table_name, a.indexrelid::regclass AS single_col_index, b.indexrelid::regclass AS composite_index, a.indnatts AS single_cols, b.indnatts AS composite_cols FROM pg_index a JOIN pg_index b ON a.indrelid = b.indrelid AND a.indexrelid != b.indexrelid WHERE a.indnatts = 1 AND b.indnatts > 1 AND a.indkey[0] = b.indkey[0] AND NOT a.indisunique AND a.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Single-column indexes whose column is the leading column of a composite index are redundant"}	\N	2026-02-25 00:28:52.405273
5090	postgresql	query	Find multiple partial indexes on the same table and columns	{"sql": "SELECT tablename, indexname, indexdef FROM pg_indexes WHERE indexdef ~* 'WHERE' AND schemaname NOT IN ('pg_catalog', 'information_schema') AND tablename IN (SELECT tablename FROM pg_indexes WHERE indexdef ~* 'WHERE' GROUP BY tablename HAVING count(*) > 1) ORDER BY tablename, indexname"}	{"condition": "multiple partial indexes on same table", "description": "Multiple partial indexes on the same table may have overlapping WHERE predicates"}	\N	2026-02-25 00:28:52.405273
5093	postgresql	query	Find unused indexes that may be migration leftovers	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size FROM pg_stat_user_indexes s WHERE s.idx_scan = 0 AND s.indexrelname NOT IN (SELECT conindid::regclass::text FROM pg_constraint WHERE contype IN ('p', 'u')) ORDER BY pg_relation_size(s.indexrelid) DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Unused indexes not backing constraints are likely migration leftovers"}	\N	2026-02-25 00:28:52.405273
5094	postgresql	query	Find unique indexes on columns that are part of a primary key	{"sql": "SELECT u.indexrelid::regclass AS unique_index, p.indexrelid::regclass AS primary_key, u.indrelid::regclass AS table_name FROM pg_index u JOIN pg_index p ON u.indrelid = p.indrelid WHERE u.indisunique AND NOT u.indisprimary AND p.indisprimary AND u.indkey[0] = ANY(p.indkey) AND u.indnatts = 1 AND u.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Unique index on a column already in the primary key may be redundant depending on constraint requirements"}	\N	2026-02-25 00:28:52.405273
5154	postgresql	query	Find transactions with multiple locks on same relations	{"sql": "SELECT l.pid, l.relation::regclass AS table_name, count(*) AS lock_count, array_agg(DISTINCT l.mode) AS lock_modes FROM pg_locks l JOIN pg_stat_activity a ON l.pid = a.pid WHERE a.state = 'active' AND l.locktype = 'relation' GROUP BY l.pid, l.relation HAVING count(*) > 1 ORDER BY lock_count DESC"}	{"condition": "row_count > 0", "description": "Transactions holding multiple locks on the same table suggest multi-UPDATE patterns"}	\N	2026-02-25 00:28:52.405273
5095	postgresql	query	Find FK columns with multiple indexes	{"sql": "SELECT c.conrelid::regclass AS table_name, c.conname AS fk_name, a.attname AS fk_column, count(DISTINCT i.indexrelid) AS index_count FROM pg_constraint c JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey) JOIN pg_index i ON i.indrelid = c.conrelid AND a.attnum = ANY(i.indkey) WHERE c.contype = 'f' GROUP BY c.conrelid, c.conname, a.attname HAVING count(DISTINCT i.indexrelid) > 1"}	{"condition": "row_count > 0", "description": "Foreign key columns with more than one supporting index have redundant indexes"}	\N	2026-02-25 00:28:52.405273
5096	postgresql	query	Find constraint-backed indexes that have matching manual indexes	{"sql": "SELECT a.indrelid::regclass AS table_name, a.indexrelid::regclass AS constraint_index, b.indexrelid::regclass AS manual_index FROM pg_index a JOIN pg_index b ON a.indrelid = b.indrelid AND a.indexrelid != b.indexrelid AND a.indkey = b.indkey WHERE (a.indisprimary OR a.indisunique) AND NOT (b.indisprimary OR b.indisunique) AND a.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Manual indexes duplicating constraint-backed indexes are purely redundant"}	\N	2026-02-25 00:28:52.405273
5097	postgresql	query	Find indexes on boolean columns with low selectivity	{"sql": "SELECT i.tablename, i.indexname, s.attname, s.n_distinct, s.most_common_vals, s.most_common_freqs FROM pg_indexes i JOIN pg_stats s ON i.tablename = s.tablename JOIN pg_attribute a ON a.attrelid = (SELECT oid FROM pg_class WHERE relname = i.tablename LIMIT 1) AND a.attname = s.attname WHERE (a.atttypid = 'boolean'::regtype OR s.n_distinct BETWEEN 1 AND 3) AND i.indexdef ~* s.attname AND i.schemaname NOT IN ('pg_catalog', 'information_schema')"}	{"condition": "n_distinct <= 3", "description": "Indexes on columns with 2-3 distinct values are non-selective and likely bypassed by the optimizer"}	\N	2026-02-25 00:28:52.405273
5098	postgresql	query	Verify index has low usage	{"sql": "SELECT schemaname, relname, indexrelname, idx_scan, pg_size_pretty(pg_relation_size(indexrelid)) AS index_size FROM pg_stat_user_indexes WHERE idx_scan < :scan_threshold ORDER BY idx_scan ASC LIMIT 20"}	{"condition": "idx_scan < :scan_threshold", "description": "Low scan count confirms optimizer is not using the non-selective index"}	{"scan_threshold": 10}	2026-02-25 00:28:52.405273
5099	postgresql	query	Find indexes on columns with moderate but skewed distinct values	{"sql": "SELECT s.tablename, s.attname, s.n_distinct, s.most_common_vals::text, s.most_common_freqs::text FROM pg_stats s WHERE s.n_distinct BETWEEN 2 AND 300 AND s.most_common_freqs[1] > :freq_threshold AND s.schemaname NOT IN ('pg_catalog', 'information_schema') AND EXISTS (SELECT 1 FROM pg_indexes i WHERE i.tablename = s.tablename AND i.indexdef ~* s.attname) ORDER BY s.most_common_freqs[1] DESC LIMIT 10"}	{"condition": "most_common_freqs[1] > :freq_threshold", "description": "Most common value matching majority of rows makes index non-selective for that value"}	{"freq_threshold": 0.3}	2026-02-25 00:28:52.405273
5100	postgresql	query	Find low-cardinality columns with even distribution and indexes	{"sql": "SELECT s.tablename, s.attname, s.n_distinct, s.most_common_vals::text, s.most_common_freqs::text FROM pg_stats s WHERE s.n_distinct BETWEEN 2 AND 4 AND s.most_common_freqs[1] < :max_freq AND s.most_common_freqs[1] > :min_freq AND s.schemaname NOT IN ('pg_catalog', 'information_schema') AND EXISTS (SELECT 1 FROM pg_indexes i WHERE i.tablename = s.tablename AND i.indexdef ~* s.attname)"}	{"condition": "n_distinct between 2 and 4 with even distribution", "description": "Columns with 2-3 distinct values evenly distributed make index scans return ~50% of table"}	{"max_freq": 0.6, "min_freq": 0.3}	2026-02-25 00:28:52.405273
5101	postgresql	query	Verify optimizer bypasses these indexes	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan FROM pg_stat_user_indexes s WHERE s.idx_scan < :scan_threshold AND s.indexrelname IN (SELECT indexname FROM pg_indexes WHERE schemaname NOT IN ('pg_catalog', 'information_schema')) ORDER BY s.idx_scan ASC"}	{"condition": "idx_scan < :scan_threshold", "description": "Low usage confirms optimizer correctly avoiding non-selective index"}	{"scan_threshold": 10}	2026-02-25 00:28:52.405273
5102	postgresql	query	Find status-like columns with extreme value skew	{"sql": "SELECT s.tablename, s.attname, s.n_distinct, s.most_common_vals::text, s.most_common_freqs[1] AS dominant_freq FROM pg_stats s WHERE s.most_common_freqs[1] > :skew_threshold AND s.n_distinct BETWEEN 2 AND 20 AND s.schemaname NOT IN ('pg_catalog', 'information_schema') AND EXISTS (SELECT 1 FROM pg_indexes i WHERE i.tablename = s.tablename AND i.indexdef ~* s.attname) ORDER BY s.most_common_freqs[1] DESC LIMIT 10"}	{"condition": "dominant_freq > :skew_threshold", "description": "One status value matching >90% of rows makes index non-selective for that value"}	{"skew_threshold": 0.9}	2026-02-25 00:28:52.405273
5112	postgresql	query	Check write activity on over-indexed tables	{"sql": "SELECT schemaname, relname, n_tup_ins, n_tup_upd, n_tup_del, n_tup_ins + n_tup_upd + n_tup_del AS total_writes FROM pg_stat_user_tables WHERE relname IN (SELECT tablename FROM pg_indexes WHERE schemaname NOT IN ('pg_catalog', 'information_schema') GROUP BY tablename HAVING count(*) > :index_threshold) ORDER BY total_writes DESC"}	{"condition": "total_writes > :write_threshold", "description": "High write volume on over-indexed tables confirms performance impact from index maintenance"}	{"index_threshold": 8, "write_threshold": 10000}	2026-02-25 00:28:52.405273
5103	postgresql	query	Find date columns with low distinct-to-row ratio	{"sql": "SELECT s.tablename, s.attname, s.n_distinct, t.n_live_tup, CASE WHEN s.n_distinct > 0 THEN t.n_live_tup / s.n_distinct ELSE t.n_live_tup * abs(s.n_distinct) END AS avg_rows_per_value FROM pg_stats s JOIN pg_stat_user_tables t ON s.tablename = t.relname AND s.schemaname = t.schemaname WHERE (s.attname ~* '(date|created|updated|timestamp)' OR s.attname ~* '_at$|_on$') AND s.schemaname NOT IN ('pg_catalog', 'information_schema') AND EXISTS (SELECT 1 FROM pg_indexes i WHERE i.tablename = s.tablename AND i.indexdef ~* s.attname) ORDER BY avg_rows_per_value DESC LIMIT 10"}	{"condition": "avg_rows_per_value > :row_threshold", "description": "High number of rows per distinct date value makes index non-selective for date equality queries"}	{"row_threshold": 1000}	2026-02-25 00:28:52.405273
5104	postgresql	query	Find categorical columns where dominant value exceeds threshold	{"sql": "SELECT s.tablename, s.attname, s.n_distinct, s.most_common_vals::text AS top_values, s.most_common_freqs[1] AS top_freq, s.most_common_freqs[2] AS second_freq FROM pg_stats s WHERE s.most_common_freqs[1] > :dominant_threshold AND s.n_distinct > 3 AND s.schemaname NOT IN ('pg_catalog', 'information_schema') AND EXISTS (SELECT 1 FROM pg_indexes i WHERE i.tablename = s.tablename AND i.indexdef ~* s.attname) ORDER BY s.most_common_freqs[1] DESC LIMIT 10"}	{"condition": "top_freq > :dominant_threshold", "description": "One category matching >80% of rows makes the index non-selective for the dominant value"}	{"dominant_threshold": 0.8}	2026-02-25 00:28:52.405273
5116	postgresql	query	Find zero-scan indexes on actively queried tables	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan, t.seq_scan + t.idx_scan AS total_table_scans, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relname = t.relname AND s.schemaname = t.schemaname WHERE s.idx_scan = 0 AND (t.seq_scan + t.idx_scan) > :table_activity_threshold ORDER BY pg_relation_size(s.indexrelid) DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Zero-scan indexes on actively used tables are speculative indexes that never became useful"}	{"table_activity_threshold": 1000}	2026-02-25 00:28:52.405273
5115	postgresql	query	Find tables with composite indexes sharing leading columns	{"sql": "SELECT a.indrelid::regclass AS table_name, a.indexrelid::regclass AS index_a, b.indexrelid::regclass AS index_b, a.indkey AS keys_a, b.indkey AS keys_b FROM pg_index a JOIN pg_index b ON a.indrelid = b.indrelid AND a.indexrelid < b.indexrelid WHERE a.indnatts > 1 AND b.indnatts > 1 AND a.indkey[0] = b.indkey[0] AND a.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Multiple composite indexes sharing leading column could potentially be consolidated"}	\N	2026-02-25 00:28:52.405273
5105	postgresql	query	Find composite indexes with low-cardinality leading column	{"sql": "SELECT idx.indrelid::regclass AS table_name, c.relname AS index_name, lead_attr.attname AS leading_col, s.n_distinct AS leading_distinct FROM pg_index idx JOIN pg_class c ON c.oid = idx.indexrelid JOIN pg_attribute lead_attr ON lead_attr.attrelid = idx.indrelid AND lead_attr.attnum = idx.indkey[0] JOIN pg_stats s ON s.tablename = idx.indrelid::regclass::text AND s.attname = lead_attr.attname WHERE idx.indnatts > 1 AND s.n_distinct BETWEEN 1 AND :distinct_threshold AND idx.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "leading_distinct <= :distinct_threshold", "description": "Composite index with very few distinct values in the leading column provides poor selectivity"}	{"distinct_threshold": 10}	2026-02-25 00:28:52.405273
5106	postgresql	query	Check if index is underutilized	{"sql": "SELECT schemaname, relname, indexrelname, idx_scan FROM pg_stat_user_indexes WHERE idx_scan < :scan_threshold ORDER BY idx_scan ASC LIMIT 20"}	{"condition": "idx_scan < :scan_threshold", "description": "Low scan count on composite index with non-selective leader confirms the ordering reduces effectiveness"}	{"scan_threshold": 100}	2026-02-25 00:28:52.405273
5107	postgresql	query	Find indexes with decreasing scan activity over time	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan, t.n_live_tup, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relname = t.relname AND s.schemaname = t.schemaname WHERE s.idx_scan < :scan_threshold AND t.n_live_tup > :row_threshold ORDER BY t.n_live_tup DESC LIMIT 10"}	{"condition": "idx_scan < :scan_threshold AND n_live_tup > :row_threshold", "description": "Low scans on large tables suggest index was originally created for a smaller dataset with different distribution"}	{"row_threshold": 100000, "scan_threshold": 100}	2026-02-25 00:28:52.405273
5108	postgresql	query	Find tables with stale statistics and active indexes	{"sql": "SELECT t.schemaname, t.relname, t.n_mod_since_analyze, t.n_live_tup, t.last_analyze, t.last_autoanalyze, n_mod_since_analyze::float / GREATEST(n_live_tup, 1) AS mod_ratio FROM pg_stat_user_tables t WHERE n_mod_since_analyze > n_live_tup * :mod_ratio AND EXISTS (SELECT 1 FROM pg_stat_user_indexes i WHERE i.relname = t.relname AND i.idx_scan > 0) ORDER BY mod_ratio DESC LIMIT 10"}	{"condition": "mod_ratio > :mod_ratio", "description": "Tables with significant modifications since last analyze may have outdated selectivity estimates"}	{"mod_ratio": 0.2}	2026-02-25 00:28:52.405273
