5110	postgresql	query	Check for CITEXT columns or case-insensitive indexes	{"sql": "SELECT c.relname, a.attname, a.atttypid::regtype AS data_type FROM pg_attribute a JOIN pg_class c ON a.attrelid = c.oid WHERE a.atttypid::regtype::text = 'citext' AND c.relnamespace NOT IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema'))"}	{"condition": "row_count > 0", "description": "CITEXT columns or case-insensitive collation reduces index selectivity by collapsing case variations"}	\N	2026-02-25 00:28:52.405273
5111	postgresql	query	Find indexed columns with high NULL fraction	{"sql": "SELECT s.tablename, s.attname, s.null_frac, s.n_distinct, i.indexname FROM pg_stats s JOIN pg_indexes i ON i.tablename = s.tablename AND i.indexdef ~* s.attname WHERE s.null_frac > :null_threshold AND s.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY s.null_frac DESC LIMIT 10"}	{"condition": "null_frac > :null_threshold", "description": "Columns where majority of values are NULL make IS NULL queries non-selective"}	{"null_threshold": 0.7}	2026-02-25 00:28:52.405273
5141	postgresql	query	Check for SIRead predicate locks from serializable isolation	{"sql": "SELECT locktype, count(*) AS lock_count FROM pg_locks WHERE locktype IN ('relation', 'page', 'tuple', 'advisory') GROUP BY locktype ORDER BY lock_count DESC"}	{"condition": "relation-level locks present with high count", "description": "Relation-level locks under serializable isolation can block unrelated row-level operations"}	\N	2026-02-25 00:28:52.405273
5113	postgresql	query	Find tables with many single-column indexes	{"sql": "SELECT idx.indrelid::regclass AS table_name, count(*) AS single_col_index_count FROM pg_index idx WHERE idx.indnatts = 1 AND NOT idx.indisprimary AND idx.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema'))) GROUP BY idx.indrelid HAVING count(*) > :threshold ORDER BY single_col_index_count DESC"}	{"condition": "single_col_index_count > :threshold", "description": "Many single-column indexes on one table suggests defensive indexing rather than strategic composite indexes"}	{"threshold": 5}	2026-02-25 00:28:52.405273
5294	postgresql	config_check	Check shared_buffers size relative to recommendations	{"sql": "SELECT name, setting, unit, pg_size_pretty(setting::bigint * CASE WHEN unit = '8kB' THEN 8192 WHEN unit = 'kB' THEN 1024 ELSE 1 END) AS human_size FROM pg_settings WHERE name = 'shared_buffers'"}	{"condition": "shared_buffers_bytes < :min_shared_buffers_bytes", "description": "shared_buffers below minimum recommended threshold for the workload"}	{"min_shared_buffers_bytes": 1073741824}	2026-02-25 00:28:52.405273
5114	postgresql	query	Find tables where majority of indexes are unused	{"sql": "SELECT t.schemaname, t.relname, count(s.indexrelid) AS total_indexes, count(CASE WHEN s.idx_scan = 0 THEN 1 END) AS unused_indexes, count(CASE WHEN s.idx_scan = 0 THEN 1 END)::float / count(s.indexrelid) AS unused_ratio FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relname = t.relname AND s.schemaname = t.schemaname GROUP BY t.schemaname, t.relname HAVING count(s.indexrelid) > :index_threshold AND count(CASE WHEN s.idx_scan = 0 THEN 1 END)::float / count(s.indexrelid) > :unused_ratio ORDER BY unused_ratio DESC"}	{"condition": "unused_ratio > :unused_ratio", "description": "Tables where most indexes are unused indicate historical accumulation without periodic cleanup"}	{"unused_ratio": 0.5, "index_threshold": 3}	2026-02-25 00:28:52.405273
5148	postgresql	query	Check for lock waits on unique index enforcement	{"sql": "SELECT l.pid, l.locktype, l.relation::regclass, l.mode, a.query, a.state FROM pg_locks l JOIN pg_stat_activity a ON l.pid = a.pid WHERE l.locktype = 'transactionid' AND NOT l.granted AND a.query ~* 'INSERT' AND a.state = 'active'"}	{"condition": "row_count > 0", "description": "INSERT operations waiting on transaction locks indicate unique key contention"}	\N	2026-02-25 00:28:52.405273
5117	postgresql	query	Find indexes with zero scans over extended observation period	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, (SELECT stats_reset FROM pg_stat_database WHERE datname = current_database()) AS stats_since FROM pg_stat_user_indexes s WHERE s.idx_scan = 0 AND NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conindid = s.indexrelid) ORDER BY pg_relation_size(s.indexrelid) DESC LIMIT 20"}	{"condition": "row_count > 0 AND stats_since is at least 7 days old", "description": "Indexes with zero scans over a meaningful observation period that do not back constraints are likely batch job leftovers"}	\N	2026-02-25 00:28:52.405273
5118	postgresql	query	Find wide composite indexes with scan activity	{"sql": "SELECT idx.indrelid::regclass AS table_name, c.relname AS index_name, idx.indnatts AS num_columns, s.idx_scan, pg_size_pretty(pg_relation_size(idx.indexrelid)) AS index_size FROM pg_index idx JOIN pg_class c ON c.oid = idx.indexrelid JOIN pg_stat_user_indexes s ON s.indexrelid = idx.indexrelid WHERE idx.indnatts >= :width_threshold AND idx.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema'))) ORDER BY idx.indnatts DESC LIMIT 10"}	{"condition": "num_columns >= :width_threshold", "description": "Very wide composite indexes may be overkill if queries only filter on 1-2 leading columns"}	{"width_threshold": 4}	2026-02-25 00:28:52.405273
5120	postgresql	query	Find index pairs where one covers the other completely	{"sql": "SELECT a.indrelid::regclass AS table_name, a.indexrelid::regclass AS covered_index, b.indexrelid::regclass AS covering_index, pg_size_pretty(pg_relation_size(a.indexrelid)) AS covered_size FROM pg_index a JOIN pg_index b ON a.indrelid = b.indrelid AND a.indexrelid != b.indexrelid AND a.indnatts <= b.indnatts AND a.indkey[0:a.indnatts-1] = b.indkey[0:a.indnatts-1] WHERE NOT a.indisunique AND a.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Indexes whose columns are a prefix subset of another index can be dropped to eliminate double write overhead"}	\N	2026-02-25 00:28:52.405273
5121	postgresql	query	Find indexes with zero scans and significant maintenance cost	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, s.idx_scan, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size, t.n_tup_ins + t.n_tup_upd + t.n_tup_del AS total_writes FROM pg_stat_user_indexes s JOIN pg_stat_user_tables t ON s.relname = t.relname AND s.schemaname = t.schemaname WHERE s.idx_scan = 0 AND (t.n_tup_ins + t.n_tup_upd + t.n_tup_del) > :write_threshold AND NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conindid = s.indexrelid) ORDER BY total_writes DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Zero-scan indexes on write-heavy tables with no constraint backing should be removed"}	{"write_threshold": 10000}	2026-02-25 00:28:52.405273
5122	postgresql	query	Count total unused indexes across the database	{"sql": "SELECT count(*) AS total_indexes, count(CASE WHEN idx_scan = 0 THEN 1 END) AS unused_indexes, count(CASE WHEN idx_scan = 0 THEN 1 END)::float / GREATEST(count(*), 1) AS unused_ratio, pg_size_pretty(sum(CASE WHEN idx_scan = 0 THEN pg_relation_size(indexrelid) ELSE 0 END)) AS wasted_space FROM pg_stat_user_indexes"}	{"condition": "unused_ratio > :ratio_threshold", "description": "High proportion of unused indexes across the database indicates no periodic cleanup policy"}	{"ratio_threshold": 0.3}	2026-02-25 00:28:52.405273
5123	postgresql	query	Compare total index size to shared_buffers allocation	{"sql": "SELECT pg_size_pretty(sum(pg_relation_size(indexrelid))) AS total_index_size, pg_size_pretty(sum(pg_relation_size(relid))) AS total_table_size, sum(pg_relation_size(indexrelid))::float / GREATEST(sum(pg_relation_size(relid)), 1) AS index_to_table_ratio, current_setting('shared_buffers') AS shared_buffers FROM pg_stat_user_indexes"}	{"condition": "index_to_table_ratio > :ratio_threshold", "description": "Index space exceeding table space means indexes dominate buffer cache, starving data page caching"}	{"ratio_threshold": 1.0}	2026-02-25 00:28:52.405273
5124	postgresql	query	Check cache hit ratio for evidence of data page eviction	{"sql": "SELECT sum(heap_blks_hit)::float / GREATEST(sum(heap_blks_hit + heap_blks_read), 1) AS table_cache_hit_ratio, sum(idx_blks_hit)::float / GREATEST(sum(idx_blks_hit + idx_blks_read), 1) AS index_cache_hit_ratio FROM pg_statio_user_tables"}	{"condition": "table_cache_hit_ratio < :hit_threshold", "description": "Low table cache hit ratio while index cache is high confirms indexes crowding out data pages"}	{"hit_threshold": 0.95}	2026-02-25 00:28:52.405273
5295	postgresql	query	Measure per-database buffer cache hit ratio	{"sql": "SELECT datname, blks_hit, blks_read, CASE WHEN blks_hit + blks_read > 0 THEN round(blks_hit * 100.0 / (blks_hit + blks_read), 2) ELSE 100 END AS hit_ratio_pct FROM pg_stat_database WHERE datname NOT IN ('template0', 'template1') ORDER BY hit_ratio_pct ASC"}	{"condition": "hit_ratio_pct < :target_ratio", "description": "Cache hit ratio below target indicates buffer pool is too small for the working set"}	{"target_ratio": 95}	2026-02-25 00:28:52.405273
5125	postgresql	query	Find tables with wide primary key columns	{"sql": "SELECT c.relname AS table_name, string_agg(a.attname || '(' || a.atttypid::regtype::text || ')', ', ') AS pk_columns, sum(CASE WHEN a.atttypid::regtype::text = 'uuid' THEN 16 WHEN a.atttypid::regtype::text LIKE 'character%' THEN a.atttypmod - 4 WHEN a.atttypid::regtype::text = 'text' THEN 50 WHEN a.atttypid::regtype::text = 'integer' THEN 4 WHEN a.atttypid::regtype::text = 'bigint' THEN 8 ELSE 20 END) AS estimated_pk_width FROM pg_index idx JOIN pg_class c ON c.oid = idx.indrelid JOIN pg_attribute a ON a.attrelid = idx.indrelid AND a.attnum = ANY(idx.indkey) WHERE idx.indisprimary AND c.relnamespace NOT IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')) GROUP BY c.relname HAVING sum(CASE WHEN a.atttypid::regtype::text = 'uuid' THEN 16 WHEN a.atttypid::regtype::text LIKE 'character%' THEN a.atttypmod - 4 WHEN a.atttypid::regtype::text = 'text' THEN 50 WHEN a.atttypid::regtype::text = 'integer' THEN 4 WHEN a.atttypid::regtype::text = 'bigint' THEN 8 ELSE 20 END) > :width_threshold ORDER BY estimated_pk_width DESC"}	{"condition": "estimated_pk_width > :width_threshold", "description": "Wide primary key adds overhead to FK indexes on child tables that reference this PK"}	{"width_threshold": 16}	2026-02-25 00:28:52.405273
5149	postgresql	query	Verify deadlock count has increased	{"sql": "SELECT deadlocks FROM pg_stat_database WHERE datname = current_database()"}	{"condition": "deadlocks > :threshold", "description": "Non-zero deadlock count confirms deadlocks are occurring from concurrent unique key inserts"}	{"threshold": 0}	2026-02-25 00:28:52.405273
5150	postgresql	query	Check for parallel worker lock waits	{"sql": "SELECT count(*) AS parallel_waiters FROM pg_stat_activity WHERE backend_type = 'parallel worker' AND wait_event_type = 'Lock'"}	{"condition": "parallel_waiters > :threshold", "description": "Parallel workers waiting on locks confirm they contribute to lock contention"}	{"threshold": 0}	2026-02-25 00:28:52.405273
5126	postgresql	query	Find indexes with varchar/text key columns and their average widths	{"sql": "SELECT i.tablename, i.indexname, s.attname, s.avg_width, a.atttypmod AS max_length FROM pg_indexes i JOIN pg_attribute a ON a.attrelid = (SELECT oid FROM pg_class WHERE relname = i.tablename LIMIT 1) JOIN pg_stats s ON s.tablename = i.tablename AND s.attname = a.attname WHERE a.atttypid IN ('text'::regtype, 'varchar'::regtype, 'character varying'::regtype) AND i.indexdef ~* a.attname AND s.avg_width > :width_threshold AND i.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY s.avg_width DESC LIMIT 10"}	{"condition": "avg_width > :width_threshold", "description": "Index entries with wide varchar values reduce the number of entries per page, increasing B-tree depth"}	{"width_threshold": 50}	2026-02-25 00:28:52.405273
5127	postgresql	query	Estimate total key width of composite indexes	{"sql": "SELECT idx.indrelid::regclass AS table_name, c.relname AS index_name, idx.indnatts AS column_count, pg_size_pretty(pg_relation_size(idx.indexrelid)) AS index_size, pg_relation_size(idx.indexrelid) / GREATEST((SELECT reltuples FROM pg_class WHERE oid = idx.indexrelid)::bigint, 1) AS bytes_per_entry FROM pg_index idx JOIN pg_class c ON c.oid = idx.indexrelid WHERE idx.indnatts >= :col_threshold AND idx.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema'))) ORDER BY bytes_per_entry DESC LIMIT 10"}	{"condition": "bytes_per_entry > :bytes_threshold AND column_count >= :col_threshold", "description": "Wide composite index entries reduce entries per page and increase tree depth"}	{"col_threshold": 5, "bytes_threshold": 200}	2026-02-25 00:28:52.405273
5128	postgresql	query	Find indexes with high INCLUDE column count	{"sql": "SELECT idx.indrelid::regclass AS table_name, c.relname AS index_name, idx.indnatts AS total_cols, idx.indnkeyatts AS key_cols, (idx.indnatts - idx.indnkeyatts) AS include_cols, pg_size_pretty(pg_relation_size(idx.indexrelid)) AS index_size FROM pg_index idx JOIN pg_class c ON c.oid = idx.indexrelid WHERE (idx.indnatts - idx.indnkeyatts) > :include_threshold AND idx.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema'))) ORDER BY (idx.indnatts - idx.indnkeyatts) DESC"}	{"condition": "include_cols > :include_threshold", "description": "Many INCLUDE columns widen index entries, consuming more storage and buffer cache"}	{"include_threshold": 5}	2026-02-25 00:28:52.405273
5129	postgresql	query	Find leading columns with wide average width	{"sql": "SELECT idx.indrelid::regclass AS table_name, c.relname AS index_name, a.attname AS leading_col, a.atttypid::regtype AS data_type, s.avg_width FROM pg_index idx JOIN pg_class c ON c.oid = idx.indexrelid JOIN pg_attribute a ON a.attrelid = idx.indrelid AND a.attnum = idx.indkey[0] JOIN pg_stats s ON s.tablename = idx.indrelid::regclass::text AND s.attname = a.attname WHERE s.avg_width > :width_threshold AND idx.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema'))) ORDER BY s.avg_width DESC LIMIT 10"}	{"condition": "avg_width > :width_threshold", "description": "Wide leading column wastes space at every level of the B-tree, not just leaf pages"}	{"width_threshold": 30}	2026-02-25 00:28:52.405273
5130	postgresql	query	Find expression indexes and their sizes	{"sql": "SELECT i.tablename, i.indexname, i.indexdef, pg_size_pretty(pg_relation_size(i.indexname::regclass)) AS index_size, (SELECT reltuples FROM pg_class WHERE relname = i.indexname) AS est_tuples FROM pg_indexes i WHERE i.indexdef ~* '\\\\(.*\\\\(' AND i.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY pg_relation_size(i.indexname::regclass) DESC LIMIT 10"}	{"condition": "index size is large relative to tuple count", "description": "Expression indexes with wide output (e.g., full text concatenation) produce wider keys than expected"}	\N	2026-02-25 00:28:52.405273
5142	postgresql	config_check	Check transaction isolation level configuration	{"sql": "SELECT name, setting FROM pg_settings WHERE name = 'default_transaction_isolation'"}	{"condition": "setting = 'serializable'", "description": "Serializable isolation uses predicate locks that can escalate to broader lock scopes"}	\N	2026-02-25 00:28:52.405273
5143	postgresql	query	Check if parent tables receive DELETE operations	{"sql": "SELECT schemaname, relname, n_tup_del FROM pg_stat_user_tables WHERE relname IN (SELECT confrelid::regclass::text FROM pg_constraint WHERE contype = 'f') AND n_tup_del > :delete_threshold ORDER BY n_tup_del DESC"}	{"condition": "n_tup_del > :delete_threshold", "description": "DELETEs on parent tables with unindexed FK children cause sequential scans and long lock holds"}	{"delete_threshold": 100}	2026-02-25 00:28:52.405273
5131	postgresql	query	Check database encoding and find text columns with wide averages	{"sql": "SELECT pg_encoding_to_char(encoding) AS db_encoding, s.tablename, s.attname, s.avg_width, a.atttypmod AS declared_length FROM pg_database d, pg_stats s JOIN pg_attribute a ON a.attrelid = (SELECT oid FROM pg_class WHERE relname = s.tablename LIMIT 1) AND a.attname = s.attname WHERE d.datname = current_database() AND s.avg_width > :width_threshold AND a.atttypid IN ('text'::regtype, 'varchar'::regtype) AND s.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY s.avg_width DESC LIMIT 10"}	{"condition": "db_encoding = 'UTF8' AND avg_width significantly exceeds character count", "description": "UTF-8 encoding causes multibyte characters to expand index key width beyond expected character count"}	{"width_threshold": 50}	2026-02-25 00:28:52.405273
6331	oracle	query	ora_check_instance_eviction_history	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%evict%' OR message_text LIKE '%node kill%' OR message_text LIKE '%communication failure%' OR message_text LIKE '%CSS%' OR message_text LIKE '%misscount%' AND originating_timestamp > SYSDATE - 7 ORDER BY originating_timestamp DESC"}	{"condition": "row_count > 0", "description": "Eviction or CSS communication failure messages confirm network-related instance termination"}	\N	2026-02-28 12:19:19.580455
5132	postgresql	query	Find indexes with nullable key columns	{"sql": "SELECT idx.indrelid::regclass AS table_name, c.relname AS index_name, a.attname, a.attnotnull, s.null_frac FROM pg_index idx JOIN pg_class c ON c.oid = idx.indexrelid JOIN pg_attribute a ON a.attrelid = idx.indrelid AND a.attnum = ANY(idx.indkey) JOIN pg_stats s ON s.tablename = idx.indrelid::regclass::text AND s.attname = a.attname WHERE NOT a.attnotnull AND idx.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "Nullable columns in index keys add NULL bitmap overhead to every index entry"}	\N	2026-02-25 00:28:52.405273
5133	postgresql	query	Find indexes on binary or geometric data types	{"sql": "SELECT idx.indrelid::regclass AS table_name, c.relname AS index_name, a.attname, a.atttypid::regtype AS data_type, pg_size_pretty(pg_relation_size(idx.indexrelid)) AS index_size FROM pg_index idx JOIN pg_class c ON c.oid = idx.indexrelid JOIN pg_attribute a ON a.attrelid = idx.indrelid AND a.attnum = ANY(idx.indkey) WHERE a.atttypid::regtype::text IN ('bytea', 'geometry', 'geography', 'jsonb', 'json') AND idx.indrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')))"}	{"condition": "row_count > 0", "description": "B-tree indexes on binary/JSON data types produce very wide keys and may exceed page size limits"}	\N	2026-02-25 00:28:52.405273
5134	postgresql	query	Find indexes with expression and plain columns on the same base	{"sql": "SELECT i.tablename, i.indexname, i.indexdef FROM pg_indexes i WHERE i.indexdef ~* '(EXTRACT|date_trunc|DATE_PART|to_char)' AND i.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY i.tablename"}	{"condition": "row_count > 0 AND index includes both expression and source column", "description": "Indexes including both a date expression and the source date column have redundant width"}	\N	2026-02-25 00:28:52.405273
5135	postgresql	query	Find indexed columns where actual width is much smaller than type max	{"sql": "SELECT s.tablename, s.attname, a.atttypid::regtype AS declared_type, s.avg_width, CASE WHEN a.atttypmod > 0 THEN a.atttypmod - 4 ELSE 0 END AS declared_max_width FROM pg_stats s JOIN pg_attribute a ON a.attrelid = (SELECT oid FROM pg_class WHERE relname = s.tablename LIMIT 1) AND a.attname = s.attname WHERE s.avg_width > 0 AND CASE WHEN a.atttypmod > 0 THEN a.atttypmod - 4 ELSE 0 END > s.avg_width * :ratio_threshold AND EXISTS (SELECT 1 FROM pg_indexes i WHERE i.tablename = s.tablename AND i.indexdef ~* s.attname) AND s.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY (CASE WHEN a.atttypmod > 0 THEN a.atttypmod - 4 ELSE 0 END - s.avg_width) DESC LIMIT 10"}	{"condition": "declared_max_width >> avg_width * ratio_threshold", "description": "Column declared as varchar(255) but avg_width is 10 wastes potential allocation in indexes"}	{"ratio_threshold": 5}	2026-02-25 00:28:52.405273
5136	postgresql	query	Find wide indexes without adjusted fillfactor	{"sql": "SELECT c.relname AS index_name, c.reloptions, pg_relation_size(c.oid) / GREATEST((SELECT reltuples FROM pg_class WHERE oid = c.oid)::bigint, 1) AS bytes_per_entry, pg_size_pretty(pg_relation_size(c.oid)) AS index_size FROM pg_class c WHERE c.relkind = 'i' AND (c.reloptions IS NULL OR NOT c.reloptions::text ~* 'fillfactor') AND pg_relation_size(c.oid) / GREATEST((SELECT reltuples FROM pg_class WHERE oid = c.oid)::bigint, 1) > :bytes_threshold AND c.relnamespace NOT IN (SELECT oid FROM pg_namespace WHERE nspname IN ('pg_catalog', 'information_schema')) ORDER BY bytes_per_entry DESC LIMIT 10"}	{"condition": "bytes_per_entry > :bytes_threshold AND no custom fillfactor", "description": "Wide index entries with default fillfactor leave less room for new entries, causing frequent page splits"}	{"bytes_threshold": 200}	2026-02-25 00:28:52.405273
5137	postgresql	log_scan	Scan PostgreSQL logs for deadlock detail entries	{"pattern": "deadlock detected|Process \\\\d+ waits for .* on relation"}	{"condition": "match_found", "description": "Deadlock log entries reveal the specific tables and lock types involved in circular waits"}	\N	2026-02-25 00:28:52.405273
5138	postgresql	query	Check current lock dependencies for potential deadlock patterns	{"sql": "SELECT blocked_locks.pid AS blocked_pid, blocked_activity.query AS blocked_query, blocking_locks.pid AS blocking_pid, blocking_activity.query AS blocking_query FROM pg_catalog.pg_locks blocked_locks JOIN pg_catalog.pg_stat_activity blocked_activity ON blocked_activity.pid = blocked_locks.pid JOIN pg_catalog.pg_locks blocking_locks ON blocking_locks.locktype = blocked_locks.locktype AND blocking_locks.relation = blocked_locks.relation AND blocking_locks.pid != blocked_locks.pid JOIN pg_catalog.pg_stat_activity blocking_activity ON blocking_activity.pid = blocking_locks.pid WHERE NOT blocked_locks.granted"}	{"condition": "row_count > 0", "description": "Active lock dependencies show current lock ordering patterns that may lead to deadlocks"}	\N	2026-02-25 00:28:52.405273
5139	postgresql	query	Find long-running transactions	{"sql": "SELECT pid, usename, state, xact_start, now() - xact_start AS xact_duration, query FROM pg_stat_activity WHERE xact_start IS NOT NULL AND now() - xact_start > interval ':duration_minutes minutes' ORDER BY xact_start ASC LIMIT 10"}	{"condition": "row_count > 0", "description": "Long-running transactions hold locks for extended periods, increasing deadlock probability"}	{"duration_minutes": 5}	2026-02-25 00:28:52.405273
5140	postgresql	query	Check if long transactions hold locks	{"sql": "SELECT l.pid, l.locktype, l.relation::regclass AS table_name, l.mode, a.xact_start, now() - a.xact_start AS xact_duration FROM pg_locks l JOIN pg_stat_activity a ON l.pid = a.pid WHERE a.xact_start IS NOT NULL AND now() - a.xact_start > interval ':duration_minutes minutes' AND l.granted ORDER BY a.xact_start ASC"}	{"condition": "row_count > 0", "description": "Long transactions holding locks confirm high deadlock risk window"}	{"duration_minutes": 5}	2026-02-25 00:28:52.405273
5144	postgresql	query	Check for sessions using explicit row-level locks	{"sql": "SELECT pid, query, state FROM pg_stat_activity WHERE query ~* 'FOR\\\\s+(UPDATE|SHARE|NO\\\\s+KEY\\\\s+UPDATE|KEY\\\\s+SHARE)' AND state = 'active'"}	{"condition": "row_count > 0", "description": "Active queries with explicit locking clauses may conflict with each other"}	\N	2026-02-25 00:28:52.405273
5145	postgresql	query	Check for lock conflicts between sessions	{"sql": "SELECT blocked.pid AS blocked_pid, blocked.query AS blocked_query, blocker.pid AS blocker_pid, blocker.query AS blocker_query, l.mode AS blocked_mode FROM pg_locks l JOIN pg_stat_activity blocked ON l.pid = blocked.pid JOIN pg_locks bl ON bl.relation = l.relation AND bl.pid != l.pid JOIN pg_stat_activity blocker ON bl.pid = blocker.pid WHERE NOT l.granted"}	{"condition": "row_count > 0", "description": "Active lock conflicts between sessions using explicit lock modes confirm incompatible locking patterns"}	\N	2026-02-25 00:28:52.405273
5146	postgresql	query	Check for deadlocks involving index and heap locks	{"sql": "SELECT deadlocks FROM pg_stat_database WHERE datname = current_database() AND deadlocks > :threshold"}	{"condition": "deadlocks > :threshold", "description": "Deadlocks present in the system"}	{"threshold": 0}	2026-02-25 00:28:52.405273
5147	postgresql	query	Check for concurrent index scan and modification patterns	{"sql": "SELECT l.locktype, l.relation::regclass, l.mode, l.granted, a.query FROM pg_locks l JOIN pg_stat_activity a ON l.pid = a.pid WHERE l.locktype IN ('relation', 'tuple') AND a.state = 'active' AND NOT l.granted ORDER BY l.relation"}	{"condition": "row_count > 0 AND mix of SELECT and modification queries on same relations", "description": "Concurrent reads with index lookups and writes on the same tables can create circular dependencies"}	\N	2026-02-25 00:28:52.405273
6227	postgresql	query	Check pgaudit installation status	{"sql": "SELECT extname, extversion FROM pg_extension WHERE extname = 'pgaudit'"}	{"condition": "row_count = 0", "description": "pgaudit not installed — no SQL-level audit trail"}	\N	2026-02-25 00:28:52.405273
5157	postgresql	query	Check for repeated identical queries in active sessions	{"sql": "SELECT query, count(*) AS session_count FROM pg_stat_activity WHERE state = 'active' AND query !~* '^(SELECT|EXPLAIN|SHOW)' GROUP BY query HAVING count(*) > :duplicate_threshold ORDER BY session_count DESC LIMIT 10"}	{"condition": "session_count > :duplicate_threshold", "description": "Many identical active write queries suggest aggressive retry without backoff"}	{"duplicate_threshold": 5}	2026-02-25 00:28:52.405273
5158	postgresql	query	Check total lock count in the system	{"sql": "SELECT count(*) AS total_locks, count(DISTINCT pid) AS lock_holders FROM pg_locks"}	{"condition": "total_locks > :lock_threshold", "description": "Very high lock count approaches shared memory limits and can cause lock table exhaustion"}	{"lock_threshold": 10000}	2026-02-25 00:28:52.405273
5159	postgresql	config_check	Check max_locks_per_transaction configuration	{"sql": "SELECT name, setting FROM pg_settings WHERE name = 'max_locks_per_transaction'"}	{"condition": "setting reviewed relative to actual lock count", "description": "max_locks_per_transaction limits the shared lock table size; exceeding it causes lock failures"}	\N	2026-02-25 00:28:52.405273
5160	postgresql	query	Find blocking sessions with granted locks	{"sql": "SELECT blocked.pid AS blocked_pid, blocked.query AS blocked_query, blocked.wait_event, blocker.pid AS blocker_pid, blocker.query AS blocker_query, blocker.state AS blocker_state, now() - blocker.xact_start AS blocker_xact_duration FROM pg_stat_activity blocked JOIN pg_locks bl ON bl.pid = blocked.pid AND NOT bl.granted JOIN pg_locks gl ON gl.locktype = bl.locktype AND gl.relation = bl.relation AND gl.pid != bl.pid AND gl.granted JOIN pg_stat_activity blocker ON blocker.pid = gl.pid WHERE blocked.state = 'active' ORDER BY blocker_xact_duration DESC"}	{"condition": "row_count > 0", "description": "Sessions blocked by other sessions holding locks confirm active lock wait timeout risk"}	\N	2026-02-25 00:28:52.405273
5161	postgresql	query	Find tables with high sequential scan counts and lock waits	{"sql": "SELECT t.schemaname, t.relname, t.seq_scan, t.seq_tup_read, pg_size_pretty(pg_relation_size(t.schemaname || '.' || t.relname)) AS table_size FROM pg_stat_user_tables t WHERE t.seq_scan > :scan_threshold AND pg_relation_size(t.schemaname || '.' || t.relname) > :size_threshold ORDER BY t.seq_tup_read DESC LIMIT 10"}	{"condition": "seq_scan > :scan_threshold", "description": "Large tables with frequent sequential scans generate excessive row locking"}	{"scan_threshold": 100, "size_threshold": 10485760}	2026-02-25 00:28:52.405273
5162	postgresql	query	Check for lock waits on those tables	{"sql": "SELECT count(*) AS lock_waiters FROM pg_locks WHERE NOT granted AND relation IS NOT NULL AND relation::regclass::text NOT LIKE 'pg_%'"}	{"condition": "lock_waiters > :waiter_threshold", "description": "Lock waits on tables with heavy sequential scans confirm blocking from unoptimized queries"}	{"waiter_threshold": 1}	2026-02-25 00:28:52.405273
5163	postgresql	query	Find write-heavy tables with high sequential scan ratio	{"sql": "SELECT schemaname, relname, seq_scan, idx_scan, n_tup_upd + n_tup_del AS write_ops, seq_scan::float / GREATEST(seq_scan + idx_scan, 1) AS seq_ratio FROM pg_stat_user_tables WHERE (n_tup_upd + n_tup_del) > :write_threshold AND seq_scan::float / GREATEST(seq_scan + idx_scan, 1) > :seq_threshold ORDER BY write_ops DESC LIMIT 10"}	{"condition": "seq_ratio > :seq_threshold AND write_ops > :write_threshold", "description": "Write-heavy tables with high sequential scan ratio indicate UPDATE/DELETE without supporting indexes"}	{"seq_threshold": 0.5, "write_threshold": 1000}	2026-02-25 00:28:52.405273
