5327	postgresql	query	Find queries with cast operations and high resource usage	{"sql": "SELECT queryid, query, calls, rows, total_exec_time / NULLIF(calls, 0) AS avg_exec_ms FROM pg_stat_statements WHERE (query ~* '::' OR query ~* 'CAST\\\\(') AND calls > :min_calls AND total_exec_time / NULLIF(calls, 0) > :min_exec_ms ORDER BY total_exec_time DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Queries with type casts and high execution time suggest estimation errors from type mismatch"}	{"min_calls": 5, "min_exec_ms": 500}	2026-02-25 00:28:52.405273
5310	postgresql	query	Check index size ratio as fragmentation indicator	{"sql": "SELECT s.schemaname, s.relname, s.indexrelname, pg_relation_size(s.indexrelid) AS index_bytes, pg_relation_size(s.relid) AS table_bytes, CASE WHEN pg_relation_size(s.relid) > 0 THEN round(pg_relation_size(s.indexrelid) * 100.0 / pg_relation_size(s.relid), 1) ELSE 0 END AS index_to_table_pct FROM pg_stat_user_indexes s JOIN pg_index i ON s.indexrelid = i.indexrelid WHERE i.indisprimary AND pg_relation_size(s.indexrelid) > :min_bytes ORDER BY index_to_table_pct DESC LIMIT 10"}	{"condition": "index_to_table_pct > :threshold_pct", "description": "Primary key index disproportionately large relative to table suggests fragmentation from page splits"}	{"min_bytes": 10485760, "threshold_pct": 50}	2026-02-25 00:28:52.405273
