5366	postgresql	query	Find blocking chains preventing worker progress	{"sql": "SELECT blocked.pid AS blocked_pid, blocked.usename AS blocked_user, blocking.pid AS blocking_pid, blocking.usename AS blocking_user, blocked.query AS blocked_query, blocking.query AS blocking_query, now() - blocking.xact_start AS blocking_duration FROM pg_stat_activity blocked JOIN pg_locks bl ON bl.pid = blocked.pid AND NOT bl.granted JOIN pg_locks gl ON gl.locktype = bl.locktype AND gl.database IS NOT DISTINCT FROM bl.database AND gl.relation IS NOT DISTINCT FROM bl.relation AND gl.page IS NOT DISTINCT FROM bl.page AND gl.tuple IS NOT DISTINCT FROM bl.tuple AND gl.transactionid IS NOT DISTINCT FROM bl.transactionid AND gl.classid IS NOT DISTINCT FROM bl.classid AND gl.objid IS NOT DISTINCT FROM bl.objid AND gl.objsubid IS NOT DISTINCT FROM bl.objsubid AND gl.pid != bl.pid AND gl.granted JOIN pg_stat_activity blocking ON blocking.pid = gl.pid WHERE now() - blocking.xact_start > interval ':threshold_minutes minutes'"}	{"condition": "row_count > 0", "description": "Blocked processes with long-running blockers are consuming worker slots without making progress"}	{"threshold_minutes": 5}	2026-02-25 00:28:52.405273
