5406	postgresql	query	Check per-table buffer cache miss rates	{"sql": "SELECT schemaname, relname, heap_blks_read, heap_blks_hit, CASE WHEN heap_blks_hit + heap_blks_read > 0 THEN round(heap_blks_hit * 100.0 / (heap_blks_hit + heap_blks_read), 2) ELSE 100 END AS hit_ratio_pct FROM pg_statio_user_tables WHERE heap_blks_read > :min_reads ORDER BY heap_blks_read DESC LIMIT 20"}	{"condition": "hit_ratio_pct < :target_ratio", "description": "Low hit ratio on specific tables confirms data not being cached, forcing disk IO"}	{"min_reads": 10000, "target_ratio": 90}	2026-02-25 00:28:52.405273
5407	postgresql	query	Find tables with high sequential scan count and missing indexes	{"sql": "SELECT schemaname, relname, seq_scan, seq_tup_read, idx_scan, n_live_tup, pg_size_pretty(pg_relation_size(schemaname || '.' || relname)) AS table_size FROM pg_stat_user_tables WHERE seq_scan > :min_seq_scans AND (idx_scan IS NULL OR idx_scan = 0) AND n_live_tup > :min_rows ORDER BY seq_tup_read DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with many sequential scans and zero index scans are missing necessary indexes"}	{"min_rows": 1000, "min_seq_scans": 50}	2026-02-25 00:28:52.405273
5408	postgresql	query	Find indexed columns with very low distinct values	{"sql": "SELECT s.schemaname, s.tablename, s.attname, s.n_distinct, idx.indexrelname, t.n_live_tup FROM pg_stats s JOIN pg_stat_user_tables t ON s.schemaname = t.schemaname AND s.tablename = t.relname JOIN pg_stat_user_indexes idx ON idx.schemaname = s.schemaname AND idx.relname = s.tablename WHERE s.n_distinct > 0 AND s.n_distinct < :low_cardinality AND t.n_live_tup > :min_rows ORDER BY s.n_distinct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexed columns with very few distinct values provide low selectivity, making index scan less efficient than seq scan"}	{"min_rows": 10000, "low_cardinality": 10}	2026-02-25 00:28:52.405273
5409	postgresql	query	Find queries with leading wildcard LIKE patterns	{"sql": "SELECT queryid, query, calls, mean_exec_time FROM pg_stat_statements WHERE query ~* 'LIKE\\\\s+''%' AND mean_exec_time > :slow_threshold_ms ORDER BY mean_exec_time DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Queries with leading wildcard LIKE patterns cannot use B-tree indexes, forcing sequential scans"}	{"slow_threshold_ms": 500}	2026-02-25 00:28:52.405273
5410	postgresql	query	Find slow queries with type cast operators	{"sql": "SELECT queryid, query, calls, mean_exec_time, shared_blks_read FROM pg_stat_statements WHERE (query ~* '::' OR query ~* 'CAST') AND mean_exec_time > :slow_threshold_ms AND shared_blks_read > :min_reads ORDER BY shared_blks_read DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Slow queries with type casts and high block reads suggest implicit conversion preventing index usage"}	{"min_reads": 1000, "slow_threshold_ms": 500}	2026-02-25 00:28:52.405273
5414	postgresql	query	Find slow queries with OR conditions	{"sql": "SELECT queryid, query, calls, mean_exec_time, shared_blks_read FROM pg_stat_statements WHERE query ~* '\\\\bOR\\\\b' AND mean_exec_time > :slow_threshold_ms ORDER BY shared_blks_read DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Slow queries with OR conditions suggest at least one OR branch cannot use an index"}	{"slow_threshold_ms": 500}	2026-02-25 00:28:52.405273
5415	postgresql	query	Find tables where sequential scan is dominant despite indexes existing	{"sql": "SELECT t.schemaname, t.relname, t.seq_scan, t.idx_scan, count(i.indexrelid) AS index_count, t.n_live_tup FROM pg_stat_user_tables t JOIN pg_stat_user_indexes i ON t.relid = i.relid WHERE t.seq_scan > t.idx_scan * :ratio AND t.seq_scan > :min_scans GROUP BY t.schemaname, t.relname, t.seq_scan, t.idx_scan, t.n_live_tup HAVING count(i.indexrelid) > 0 ORDER BY t.seq_scan DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with indexes but dominant sequential scans suggest optimizer prefers scans for unselective queries"}	{"ratio": 5, "min_scans": 100}	2026-02-25 00:28:52.405273
5416	postgresql	query	Find indexes with high heap fetch rates	{"sql": "SELECT schemaname, relname, indexrelname, idx_scan, idx_tup_read, idx_tup_fetch, pg_size_pretty(pg_relation_size(indexrelid)) AS index_size FROM pg_stat_user_indexes WHERE idx_scan > :min_scans AND idx_tup_fetch > 0 ORDER BY idx_tup_fetch DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "High heap fetch counts indicate index is not covering, requiring additional table access for non-indexed columns"}	{"min_scans": 100}	2026-02-25 00:28:52.405273
5417	postgresql	query	Find queries returning large percentage of table rows	{"sql": "SELECT queryid, query, calls, rows / NULLIF(calls, 0) AS avg_rows_returned, mean_exec_time FROM pg_stat_statements WHERE rows / NULLIF(calls, 0) > :min_rows_per_call AND mean_exec_time > :slow_threshold_ms ORDER BY rows / NULLIF(calls, 0) DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Queries returning many rows per call confirm optimizer choosing scan is correct for large result sets"}	{"min_rows_per_call": 50000, "slow_threshold_ms": 500}	2026-02-25 00:28:52.405273
5418	postgresql	query	Find small tables with indexes that are rarely used	{"sql": "SELECT t.schemaname, t.relname, t.n_live_tup, t.seq_scan, s.indexrelname, s.idx_scan, pg_size_pretty(pg_relation_size(s.indexrelid)) AS index_size FROM pg_stat_user_tables t JOIN pg_stat_user_indexes s ON t.relid = s.relid WHERE t.n_live_tup < :max_rows AND t.seq_scan > s.idx_scan * :ratio ORDER BY t.seq_scan DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Small tables where sequential scan dominates over index scan — index overhead exceeds benefit"}	{"ratio": 10, "max_rows": 1000}	2026-02-25 00:28:52.405273
5419	postgresql	query	Find composite indexes and their column order	{"sql": "SELECT i.indexrelid::regclass AS index_name, i.indrelid::regclass AS table_name, array_agg(a.attname ORDER BY k.n) AS index_columns, s.idx_scan FROM pg_index i JOIN pg_stat_user_indexes s ON s.indexrelid = i.indexrelid CROSS JOIN LATERAL unnest(i.indkey) WITH ORDINALITY AS k(attnum, n) JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum WHERE i.indnatts > 1 AND s.idx_scan < :max_scans GROUP BY i.indexrelid, i.indrelid, s.idx_scan ORDER BY s.idx_scan ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Composite indexes with low scan counts may indicate queries skip the leading column"}	{"max_scans": 10}	2026-02-25 00:28:52.405273
