5535	postgresql	query	Find sessions waiting for locks	{"sql": "SELECT blocked.pid AS blocked_pid, blocked.usename AS blocked_user, blocked.query AS blocked_query, now() - blocked.query_start AS wait_duration, blocking.pid AS blocking_pid, blocking.usename AS blocking_user, blocking.state AS blocking_state, blocking.query AS blocking_query FROM pg_stat_activity blocked JOIN pg_locks bl ON blocked.pid = bl.pid JOIN pg_locks gl ON bl.locktype = gl.locktype AND bl.database IS NOT DISTINCT FROM gl.database AND bl.relation IS NOT DISTINCT FROM gl.relation AND bl.page IS NOT DISTINCT FROM gl.page AND bl.tuple IS NOT DISTINCT FROM gl.tuple AND bl.pid != gl.pid JOIN pg_stat_activity blocking ON gl.pid = blocking.pid WHERE NOT bl.granted AND gl.granted"}	{"condition": "row_count > 0", "description": "Blocked sessions waiting for granted locks confirm lock contention causing long transactions"}	\N	2026-02-25 00:28:52.405273
