5604	postgresql	query	Find large tables with high dead tuple accumulation	{"sql": "SELECT schemaname, relname, n_live_tup, n_dead_tup, ROUND(n_dead_tup::numeric / NULLIF(n_live_tup, 0) * 100, 2) AS dead_pct, last_autovacuum FROM pg_stat_user_tables WHERE n_live_tup > 1000000 AND n_dead_tup > n_live_tup * 0.1 ORDER BY n_dead_tup DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Large tables with >10% dead tuples confirm autovacuum triggers too infrequently"}	\N	2026-02-25 00:28:52.405273
5605	postgresql	query	Check replication connections and their feedback status	{"sql": "SELECT client_addr, application_name, state, backend_xmin, sent_lsn, replay_lsn FROM pg_stat_replication"}	{"condition": "row_count > 0 AND backend_xmin IS NULL", "description": "Replicas with NULL backend_xmin are not sending hot_standby_feedback"}	\N	2026-02-25 00:28:52.405273
5607	postgresql	query	Check pg_class catalog size and dead tuples	{"sql": "SELECT relname, n_live_tup, n_dead_tup, n_tup_ins, n_tup_del, pg_size_pretty(pg_total_relation_size(relid)) AS total_size FROM pg_stat_sys_tables WHERE relname IN ('pg_class', 'pg_attribute', 'pg_type', 'pg_depend') ORDER BY n_dead_tup DESC"}	{"condition": "n_dead_tup > :threshold_dead_tuples", "description": "High dead tuple count in system catalogs indicates excessive temp table creation/deletion"}	{"threshold_dead_tuples": 10000}	2026-02-25 00:28:52.405273
5608	postgresql	query	Check XID age on system catalog tables	{"sql": "SELECT c.oid::regclass AS table_name, age(c.relfrozenxid) AS xid_age FROM pg_class c WHERE c.relname IN ('pg_class', 'pg_attribute', 'pg_type') ORDER BY age(c.relfrozenxid) DESC"}	{"condition": "xid_age > :threshold_age", "description": "System catalog tables with high XID age confirm temp table churn blocking catalog VACUUM"}	{"threshold_age": 200000000}	2026-02-25 00:28:52.405273
5609	postgresql	query	Find active FDW-related sessions with long-running transactions	{"sql": "SELECT pid, usename, application_name, state, wait_event_type, wait_event, query, now() - xact_start AS xact_age, backend_xmin FROM pg_stat_activity WHERE state = 'active' AND (query ~* 'foreign|fdw|dblink' OR wait_event_type = 'Extension') AND now() - xact_start > interval ':threshold_minutes minutes'"}	{"condition": "row_count > 0", "description": "Long-running FDW queries hold transaction IDs and prevent VACUUM advancement"}	{"threshold_minutes": 30}	2026-02-25 00:28:52.405273
5611	postgresql	query	Check checkpoint and bgwriter performance statistics	{"sql": "SELECT checkpoints_timed, checkpoints_req, checkpoint_write_time, checkpoint_sync_time, buffers_checkpoint, buffers_clean, maxwritten_clean, buffers_backend, buffers_backend_fsync FROM pg_stat_bgwriter"}	{"condition": "checkpoints_req > checkpoints_timed * 0.5 OR buffers_backend_fsync > 0 OR maxwritten_clean > 0", "description": "Frequent requested checkpoints, backend fsyncs, or maxwritten_clean indicate bgwriter/checkpoint stalls"}	\N	2026-02-25 00:28:52.405273
5612	postgresql	config_check	Check checkpoint configuration for bottlenecks	{"sql": "SELECT name, setting, unit FROM pg_settings WHERE name IN ('checkpoint_completion_target', 'checkpoint_timeout', 'max_wal_size', 'bgwriter_delay', 'bgwriter_lru_maxpages') ORDER BY name"}	{"condition": "checkpoint_completion_target < '0.9' OR max_wal_size::int < 1024", "description": "Suboptimal checkpoint settings can cause checkpoint stalls affecting VACUUM progress"}	\N	2026-02-25 00:28:52.405273
5613	postgresql	query	Check for excessive backend processes and stats overhead	{"sql": "SELECT COUNT(*) AS total_backends, COUNT(*) FILTER (WHERE state = 'active') AS active, COUNT(*) FILTER (WHERE state = 'idle') AS idle, COUNT(*) FILTER (WHERE state = 'idle in transaction') AS idle_in_tx, (SELECT setting::int FROM pg_settings WHERE name = 'max_connections') AS max_connections FROM pg_stat_activity"}	{"condition": "total_backends > max_connections * 0.8", "description": "Near-maximum connection count creates stats collector overhead that may delay XID tracking"}	\N	2026-02-25 00:28:52.405273
5614	postgresql	query	Check if the server is in recovery mode	{"sql": "SELECT pg_is_in_recovery() AS in_recovery, CASE WHEN pg_is_in_recovery() THEN pg_last_wal_replay_lsn() END AS last_replay_lsn, CASE WHEN pg_is_in_recovery() THEN pg_last_xact_replay_timestamp() END AS last_replay_time"}	{"condition": "in_recovery = true", "description": "Server in recovery mode has limited VACUUM capability"}	\N	2026-02-25 00:28:52.405273
5615	postgresql	query	Check database XID age on recovering server	{"sql": "SELECT datname, age(datfrozenxid) AS xid_age FROM pg_database ORDER BY xid_age DESC"}	{"condition": "xid_age > :threshold_age", "description": "High XID age during recovery confirms freezing cannot proceed until recovery completes"}	{"threshold_age": 300000000}	2026-02-25 00:28:52.405273
5616	postgresql	query	Find tables with high update counts and TOAST tables	{"sql": "SELECT s.schemaname, s.relname, s.n_tup_upd, s.n_tup_hot_upd, s.n_dead_tup, pg_size_pretty(pg_total_relation_size(s.relid)) AS total_size, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size FROM pg_stat_user_tables s JOIN pg_class c ON s.relid = c.oid JOIN pg_class t ON c.reltoastrelid = t.oid WHERE s.n_tup_upd > :threshold_updates AND c.reltoastrelid != 0 ORDER BY pg_relation_size(t.oid) DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Tables with high updates and large TOAST tables indicate TOAST bloat from column updates"}	{"threshold_updates": 10000}	2026-02-25 00:28:52.405273
5617	postgresql	query	Check for TOAST-eligible column types in high-update tables	{"sql": "SELECT c.relname AS table_name, a.attname AS column_name, t.typname AS data_type, a.attstorage AS storage_strategy FROM pg_attribute a JOIN pg_class c ON a.attrelid = c.oid JOIN pg_type t ON a.atttypid = t.oid JOIN pg_stat_user_tables s ON c.oid = s.relid WHERE s.n_tup_upd > :threshold_updates AND a.attstorage IN ('x', 'e', 'm') AND a.attnum > 0 AND NOT a.attisdropped ORDER BY s.n_tup_upd DESC"}	{"condition": "row_count > 0", "description": "TOAST-eligible columns (text, jsonb, bytea) on high-update tables confirm the bloat source"}	{"threshold_updates": 10000}	2026-02-25 00:28:52.405273
5618	postgresql	query	Check TOAST table sizes and vacuum activity	{"sql": "SELECT c.relname AS parent_table, t.relname AS toast_table, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size, pg_size_pretty(pg_total_relation_size(c.oid)) AS total_size, s.n_dead_tup AS parent_dead_tuples, s.last_autovacuum AS parent_last_vacuum FROM pg_class c JOIN pg_class t ON c.reltoastrelid = t.oid JOIN pg_stat_user_tables s ON c.oid = s.relid WHERE c.reltoastrelid != 0 ORDER BY pg_relation_size(t.oid) DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Large TOAST tables suggest dead tuples accumulating without adequate vacuuming"}	\N	2026-02-25 00:28:52.405273
5640	postgresql	query	Check for superuser accounts with login capability	{"sql": "SELECT rolname, rolsuper, rolcanlogin FROM pg_roles WHERE rolsuper = true AND rolcanlogin = true"}	{"condition": "row_count > 0", "description": "Superuser accounts with login on a network-exposed instance are a security risk"}	\N	2026-02-25 00:28:52.405273
6126	postgresql	query	Check for logical replication rootcauseations	{"sql": "SELECT pubname, puballtables, pubinsert, pubupdate, pubdelete FROM pg_publication"}	{"condition": "row_count > 0", "description": "Logical replication publications configured — data sent to subscribers"}	\N	2026-02-25 00:28:52.405273
5619	postgresql	query	Compare TOAST table size to main table data	{"sql": "SELECT c.relname AS parent_table, pg_size_pretty(pg_relation_size(c.oid)) AS main_size, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size, ROUND(pg_relation_size(t.oid)::numeric / NULLIF(pg_relation_size(c.oid), 0) * 100) AS toast_to_main_pct FROM pg_class c JOIN pg_class t ON c.reltoastrelid = t.oid WHERE c.reltoastrelid != 0 AND pg_relation_size(t.oid) > :threshold_bytes ORDER BY pg_relation_size(t.oid) DESC LIMIT 10"}	{"condition": "toast_to_main_pct > 200", "description": "TOAST table larger than 2x the main table strongly suggests dead tuple bloat"}	{"threshold_bytes": 104857600}	2026-02-25 00:28:52.405273
