5620	postgresql	query	Find tables with large TOAST tables and EXTENDED storage columns	{"sql": "SELECT c.relname AS table_name, a.attname AS column_name, t.typname AS data_type, a.attstorage AS storage, pg_size_pretty(pg_relation_size(tc.oid)) AS toast_size FROM pg_attribute a JOIN pg_class c ON a.attrelid = c.oid JOIN pg_type t ON a.atttypid = t.oid JOIN pg_class tc ON c.reltoastrelid = tc.oid WHERE a.attstorage = 'x' AND a.attnum > 0 AND NOT a.attisdropped AND pg_relation_size(tc.oid) > :threshold_bytes ORDER BY pg_relation_size(tc.oid) DESC"}	{"condition": "row_count > 0", "description": "Tables with EXTENDED storage on bytea/jsonb columns may store incompressible data"}	{"threshold_bytes": 104857600}	2026-02-25 00:28:52.405273
5621	postgresql	query	Find long-running transactions holding back VACUUM	{"sql": "SELECT pid, usename, state, xact_start, now() - xact_start AS xact_age, backend_xmin, age(backend_xmin) AS xmin_age FROM pg_stat_activity WHERE backend_xmin IS NOT NULL ORDER BY age(backend_xmin) DESC LIMIT 5"}	{"condition": "xmin_age > :threshold_age", "description": "Old backend_xmin prevents VACUUM from removing dead TOAST tuples"}	{"threshold_age": 1000000}	2026-02-25 00:28:52.405273
5622	postgresql	query	Check TOAST table sizes for affected tables	{"sql": "SELECT c.relname AS parent_table, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size, s.n_dead_tup, s.last_autovacuum FROM pg_class c JOIN pg_class t ON c.reltoastrelid = t.oid JOIN pg_stat_user_tables s ON c.oid = s.relid WHERE c.reltoastrelid != 0 AND pg_relation_size(t.oid) > :toast_threshold ORDER BY pg_relation_size(t.oid) DESC"}	{"condition": "row_count > 0", "description": "Large TOAST tables with dead tuples confirm long transactions are blocking TOAST cleanup"}	{"toast_threshold": 52428800}	2026-02-25 00:28:52.405273
