6336	oracle	query	ora_check_unclean_startup_alert_log	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE (message_text LIKE '%crash recovery%' OR message_text LIKE '%instance recovery%' OR message_text LIKE '%Beginning crash recovery%' OR message_text LIKE '%Completed redo application%') AND originating_timestamp > SYSDATE - 7 ORDER BY originating_timestamp DESC"}	{"condition": "row_count > 0", "description": "Crash recovery messages confirm unclean shutdown from power failure or server crash"}	\N	2026-02-28 12:19:19.580455
5624	postgresql	query	Find frequently-updated columns with non-optimal TOAST strategy	{"sql": "SELECT c.relname AS table_name, a.attname AS column_name, CASE a.attstorage WHEN 'p' THEN 'PLAIN' WHEN 'e' THEN 'EXTERNAL' WHEN 'm' THEN 'MAIN' WHEN 'x' THEN 'EXTENDED' END AS strategy, t.typname AS data_type, s.n_tup_upd FROM pg_attribute a JOIN pg_class c ON a.attrelid = c.oid JOIN pg_type t ON a.atttypid = t.oid JOIN pg_stat_user_tables s ON c.oid = s.relid WHERE a.attstorage IN ('e', 'm') AND a.attnum > 0 AND NOT a.attisdropped AND s.n_tup_upd > :threshold_updates ORDER BY s.n_tup_upd DESC"}	{"condition": "row_count > 0", "description": "EXTERNAL/MAIN strategy on frequently-updated columns forces TOAST storage without compression benefit"}	{"threshold_updates": 10000}	2026-02-25 00:28:52.405273
5625	postgresql	query	Check toast_tuple_target settings on tables with TOAST	{"sql": "SELECT c.relname AS table_name, (SELECT option_value FROM pg_options_to_table(c.reloptions) WHERE option_name = 'toast_tuple_target') AS toast_tuple_target, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size FROM pg_class c JOIN pg_class t ON c.reltoastrelid = t.oid WHERE c.reloptions IS NOT NULL AND c.reloptions::text LIKE '%toast_tuple_target%' ORDER BY pg_relation_size(t.oid) DESC"}	{"condition": "row_count > 0", "description": "Custom toast_tuple_target may prevent compression of mid-sized values"}	\N	2026-02-25 00:28:52.405273
5626	postgresql	query	Find tables with high modification counts and large TOAST tables	{"sql": "SELECT s.relname, s.n_tup_ins, s.n_tup_upd, s.n_tup_del, s.n_dead_tup, s.last_autovacuum, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size FROM pg_stat_user_tables s JOIN pg_class c ON s.relid = c.oid JOIN pg_class t ON c.reltoastrelid = t.oid WHERE c.reltoastrelid != 0 AND (s.n_tup_ins + s.n_tup_upd + s.n_tup_del) > :threshold_modifications AND pg_relation_size(t.oid) > :toast_threshold ORDER BY pg_relation_size(t.oid) DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "High modification count with large TOAST tables confirms bulk DML bloat"}	{"toast_threshold": 104857600, "threshold_modifications": 100000}	2026-02-25 00:28:52.405273
5627	postgresql	query	Find large tables with default scale factor and TOAST bloat	{"sql": "SELECT s.relname, s.n_live_tup, s.n_dead_tup, ROUND(s.n_dead_tup::numeric / NULLIF(s.n_live_tup, 0) * 100, 2) AS dead_pct, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size, (SELECT setting FROM pg_settings WHERE name = 'autovacuum_vacuum_scale_factor') AS global_scale_factor FROM pg_stat_user_tables s JOIN pg_class c ON s.relid = c.oid JOIN pg_class t ON c.reltoastrelid = t.oid WHERE s.n_live_tup > 1000000 AND c.reltoastrelid != 0 AND pg_relation_size(t.oid) > :toast_threshold ORDER BY pg_relation_size(t.oid) DESC"}	{"condition": "row_count > 0", "description": "Large tables with default scale factor and significant TOAST size need per-table vacuum tuning"}	{"toast_threshold": 104857600}	2026-02-25 00:28:52.405273
5641	postgresql	query	Find well-known default account names with elevated privileges	{"sql": "SELECT rolname, rolsuper, rolcreaterole, rolcreatedb, rolcanlogin FROM pg_roles WHERE rolname IN ('postgres', 'admin', 'root', 'dba', 'dbadmin', 'pgadmin', 'replication') AND rolcanlogin = true"}	{"condition": "row_count > 1", "description": "Multiple well-known account names with login suggest no hardening checklist was applied"}	\N	2026-02-25 00:28:52.405273
5628	postgresql	query	Check TOAST table size relative to expected compressed size	{"sql": "SELECT c.relname AS table_name, pg_size_pretty(pg_relation_size(c.oid)) AS main_size, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size, a.attname AS toast_column, ty.typname AS data_type FROM pg_class c JOIN pg_class t ON c.reltoastrelid = t.oid JOIN pg_attribute a ON a.attrelid = c.oid JOIN pg_type ty ON a.atttypid = ty.oid WHERE c.reltoastrelid != 0 AND a.attstorage = 'x' AND a.attnum > 0 AND NOT a.attisdropped AND pg_relation_size(t.oid) > :threshold_bytes ORDER BY pg_relation_size(t.oid) DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Large TOAST tables with EXTENDED storage may contain poorly-compressible data"}	{"threshold_bytes": 209715200}	2026-02-25 00:28:52.405273
5629	postgresql	query	Find tables with high updates and TOAST columns	{"sql": "SELECT s.relname, s.n_tup_upd, s.n_tup_hot_upd, pg_size_pretty(pg_relation_size(s.relid)) AS main_size, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size FROM pg_stat_user_tables s JOIN pg_class c ON s.relid = c.oid JOIN pg_class t ON c.reltoastrelid = t.oid WHERE s.n_tup_upd > :threshold_updates AND c.reltoastrelid != 0 ORDER BY s.n_tup_upd DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "High update counts on tables with TOAST columns create TOAST pointer overhead in the main heap"}	{"threshold_updates": 100000}	2026-02-25 00:28:52.405273
