5631	postgresql	query	Check for growing TOAST tables with recent but insufficient vacuuming	{"sql": "SELECT s.relname, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size, s.last_autovacuum, s.n_dead_tup FROM pg_stat_user_tables s JOIN pg_class c ON s.relid = c.oid JOIN pg_class t ON c.reltoastrelid = t.oid WHERE c.reltoastrelid != 0 AND s.last_autovacuum IS NOT NULL AND pg_relation_size(t.oid) > :toast_threshold ORDER BY pg_relation_size(t.oid) DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Large TOAST tables with recent vacuum but still large indicate VACUUM is throttled"}	{"toast_threshold": 104857600}	2026-02-25 00:28:52.405273
5632	postgresql	query	Find inherited tables with TOAST tables	{"sql": "SELECT i.inhparent::regclass AS parent_table, i.inhrelid::regclass AS child_table, pg_size_pretty(pg_relation_size(t.oid)) AS child_toast_size FROM pg_inherits i JOIN pg_class c ON i.inhrelid = c.oid JOIN pg_class t ON c.reltoastrelid = t.oid WHERE c.reltoastrelid != 0 ORDER BY pg_relation_size(t.oid) DESC"}	{"condition": "row_count > 0", "description": "Inherited tables with TOAST tables may propagate bloat patterns from parent"}	\N	2026-02-25 00:28:52.405273
5633	postgresql	query	Find partitioned tables with TOAST tables across partitions	{"sql": "SELECT p.relname AS parent_partition, c.relname AS partition_name, pg_size_pretty(pg_relation_size(t.oid)) AS toast_size FROM pg_inherits i JOIN pg_class p ON i.inhparent = p.oid JOIN pg_class c ON i.inhrelid = c.oid JOIN pg_class t ON c.reltoastrelid = t.oid WHERE c.reltoastrelid != 0 AND p.relkind = 'p' ORDER BY p.relname, pg_relation_size(t.oid) DESC"}	{"condition": "row_count > 0", "description": "Each partition has its own TOAST table, multiplying potential bloat"}	\N	2026-02-25 00:28:52.405273
