5791	postgresql	query	Find non-admin accounts owning schemas or with CREATE privilege	{"sql": "SELECT n.nspname AS schema_name, r.rolname AS owner, r.rolsuper, r.rolcreatedb FROM pg_namespace n JOIN pg_roles r ON n.nspowner = r.oid WHERE n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast') AND r.rolcanlogin = true AND NOT r.rolsuper ORDER BY n.nspname"}	{"condition": "row_count > :max_schema_owners", "description": "Multiple login accounts own schemas — typical of dev practices carried to production"}	{"max_schema_owners": 2}	2026-02-25 00:28:52.405273
5792	postgresql	query	Find roles granted ALL PRIVILEGES on schemas	{"sql": "SELECT grantee, table_schema, string_agg(DISTINCT privilege_type, ', ') AS privileges, COUNT(DISTINCT table_name) AS table_count FROM information_schema.table_privileges WHERE grantee NOT IN ('postgres', 'PUBLIC') AND table_schema NOT IN ('pg_catalog', 'information_schema') GROUP BY grantee, table_schema HAVING COUNT(DISTINCT privilege_type) >= 6 ORDER BY table_count DESC"}	{"condition": "row_count > :threshold", "description": "Multiple grantees with ALL PRIVILEGES across many tables — convenience granting pattern"}	{"threshold": 3}	2026-02-25 00:28:52.405273
