5837	postgresql	query	Find login roles with no owned objects and no grants	{"sql": "SELECT r.rolname FROM pg_roles r WHERE r.rolcanlogin = true AND r.rolname NOT IN ('postgres') AND NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.relowner = r.oid) AND NOT EXISTS (SELECT 1 FROM information_schema.table_privileges tp WHERE tp.grantee = r.rolname AND tp.table_schema NOT IN ('pg_catalog', 'information_schema')) AND NOT EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.member = r.oid)"}	{"condition": "row_count > :threshold", "description": "Login roles with no objects, no grants, no role memberships — migrated without purpose"}	{"threshold": 3}	2026-02-25 00:28:52.405273
5838	postgresql	query	Find login roles with only SELECT privileges and no recent activity	{"sql": "SELECT r.rolname, r.rolvaliduntil FROM pg_roles r WHERE r.rolcanlogin = true AND NOT r.rolsuper AND NOT r.rolcreatedb AND NOT r.rolcreaterole AND r.rolname NOT IN (SELECT DISTINCT usename FROM pg_stat_activity WHERE usename IS NOT NULL) AND EXISTS (SELECT 1 FROM information_schema.table_privileges tp WHERE tp.grantee = r.rolname AND tp.privilege_type = 'SELECT') AND NOT EXISTS (SELECT 1 FROM information_schema.table_privileges tp WHERE tp.grantee = r.rolname AND tp.privilege_type IN ('INSERT', 'UPDATE', 'DELETE'))"}	{"condition": "row_count > 0", "description": "Inactive read-only accounts left active — perceived as low-risk but expand attack surface"}	\N	2026-02-25 00:28:52.405273
5839	postgresql	query	Find roles with file operation privileges	{"sql": "SELECT r.rolname, r.rolsuper, m.roleid, g.rolname AS granted_role FROM pg_roles r LEFT JOIN pg_auth_members m ON m.member = r.oid LEFT JOIN pg_roles g ON g.oid = m.roleid WHERE r.rolcanlogin = true AND (r.rolsuper = true OR g.rolname IN ('pg_read_server_files', 'pg_write_server_files', 'pg_execute_server_program')) ORDER BY r.rolname"}	{"condition": "row_count > :expected_count", "description": "More accounts than expected with file operation capabilities"}	{"expected_count": 1}	2026-02-25 00:28:52.405273
5840	postgresql	query	Check for pg_read/write_server_files role usage	{"sql": "SELECT g.rolname AS file_role, COUNT(m.member) AS member_count FROM pg_roles g LEFT JOIN pg_auth_members m ON m.roleid = g.oid WHERE g.rolname IN ('pg_read_server_files', 'pg_write_server_files', 'pg_execute_server_program') GROUP BY g.rolname"}	{"condition": "member_count = 0", "description": "File operation roles not used — applications likely use superuser COPY instead"}	\N	2026-02-25 00:28:52.405273
