5847	postgresql	query	Find inactive accounts with file operation roles	{"sql": "SELECT r.rolname, g.rolname AS file_role FROM pg_roles r JOIN pg_auth_members m ON m.member = r.oid JOIN pg_roles g ON g.oid = m.roleid WHERE g.rolname IN ('pg_read_server_files', 'pg_write_server_files', 'pg_execute_server_program') AND r.rolcanlogin = true AND r.rolname NOT IN (SELECT DISTINCT usename FROM pg_stat_activity WHERE usename IS NOT NULL)"}	{"condition": "row_count > 0", "description": "Inactive accounts retain file operation roles — granted for troubleshooting, never revoked"}	\N	2026-02-25 00:28:52.405273
5848	postgresql	query	Find ETL/backup tool accounts with file privileges	{"sql": "SELECT r.rolname, r.rolsuper, string_agg(g.rolname, ', ') AS granted_roles FROM pg_roles r LEFT JOIN pg_auth_members m ON m.member = r.oid LEFT JOIN pg_roles g ON g.oid = m.roleid WHERE r.rolcanlogin = true AND r.rolname ~* '(etl|airflow|nifi|talend|informatica|pentaho|pgbackrest|barman|pgdump|wal_e|pg_basebackup)' AND (r.rolsuper = true OR g.rolname IN ('pg_read_server_files', 'pg_write_server_files', 'pg_execute_server_program')) GROUP BY r.rolname, r.rolsuper"}	{"condition": "row_count > 0", "description": "ETL/backup tool accounts with file operation privileges"}	\N	2026-02-25 00:28:52.405273
