5852	postgresql	query	Find shared accounts with file roles	{"sql": "SELECT a.usename, COUNT(DISTINCT a.client_addr) AS source_count, string_agg(DISTINCT g.rolname, ', ') AS file_roles FROM pg_stat_activity a JOIN pg_roles r ON a.usename = r.rolname JOIN pg_auth_members m ON m.member = r.oid JOIN pg_roles g ON g.oid = m.roleid WHERE g.rolname IN ('pg_read_server_files', 'pg_write_server_files', 'pg_execute_server_program') AND a.backend_type = 'client backend' GROUP BY a.usename HAVING COUNT(DISTINCT a.client_addr) > 1"}	{"condition": "row_count > 0", "description": "Shared accounts with file privileges — multiple sources can access filesystem"}	\N	2026-02-25 00:28:52.405273
5853	postgresql	query	Count members of file operation roles	{"sql": "SELECT g.rolname, COUNT(m.member) AS member_count FROM pg_roles g JOIN pg_auth_members m ON m.roleid = g.oid WHERE g.rolname IN ('pg_read_server_files', 'pg_write_server_files', 'pg_execute_server_program') GROUP BY g.rolname HAVING COUNT(m.member) > :max_members"}	{"condition": "row_count > 0", "description": "File operation roles granted to many accounts — provisioning script error"}	{"max_members": 3}	2026-02-25 00:28:52.405273
5854	postgresql	query	Find accounts with file roles that are not service or admin accounts	{"sql": "SELECT r.rolname, g.rolname AS file_role, r.rolsuper FROM pg_roles r JOIN pg_auth_members m ON m.member = r.oid JOIN pg_roles g ON g.oid = m.roleid WHERE g.rolname IN ('pg_read_server_files', 'pg_write_server_files', 'pg_execute_server_program') AND r.rolcanlogin = true AND NOT r.rolsuper AND r.rolname NOT IN (SELECT DISTINCT usename FROM pg_stat_activity WHERE usename IS NOT NULL)"}	{"condition": "row_count > 0", "description": "Non-admin, inactive accounts with file roles — likely emergency grants not revoked"}	\N	2026-02-25 00:28:52.405273
