5860	postgresql	query	Find foreign tables providing cross-database access	{"sql": "SELECT ft.foreign_table_schema, ft.foreign_table_name, ft.foreign_server_name FROM information_schema.foreign_tables ft ORDER BY ft.foreign_table_schema, ft.foreign_table_name"}	{"condition": "row_count > :threshold", "description": "Many foreign tables suggest application-level cross-database dependency"}	{"threshold": 5}	2026-02-25 00:28:52.405273
5861	postgresql	query	Check schema ownership diversity	{"sql": "SELECT n.nspname, r.rolname AS owner, r.rolsuper FROM pg_namespace n JOIN pg_roles r ON n.nspowner = r.oid WHERE n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast', 'pg_temp_1', 'pg_toast_temp_1') ORDER BY n.nspname"}	{"condition": "COUNT(DISTINCT owner) > :max_owners", "description": "Multiple distinct schema owners create complex ownership chains within one database"}	{"max_owners": 2}	2026-02-25 00:28:52.405273
5862	postgresql	query	Find SECURITY DEFINER functions enabling cross-schema access	{"sql": "SELECT n.nspname AS schema, p.proname AS function_name, r.rolname AS owner, p.prosecdef AS security_definer FROM pg_proc p JOIN pg_namespace n ON p.pronamespace = n.oid JOIN pg_roles r ON p.proowner = r.oid WHERE p.prosecdef = true AND n.nspname NOT IN ('pg_catalog', 'information_schema') ORDER BY n.nspname, p.proname"}	{"condition": "row_count > :threshold", "description": "SECURITY DEFINER functions bridge schemas — implicit cross-schema privilege escalation"}	{"threshold": 3}	2026-02-25 00:28:52.405273
