5867	postgresql	query	Find foreign servers with test/dev naming patterns	{"sql": "SELECT s.srvname, s.srvoptions FROM pg_foreign_server s WHERE s.srvname ~* '(test|dev|staging|local|tmp|temp|sandbox)' OR s.srvoptions::text ~* '(localhost|127\\\\.0\\\\.0\\\\.1|test|dev|staging)'"}	{"condition": "row_count > 0", "description": "Foreign servers with dev/test indicators in production database"}	\N	2026-02-25 00:28:52.405273
5868	postgresql	query	Check foreign servers and their user mapping breadth	{"sql": "SELECT s.srvname, s.srvowner::regrole AS owner, COUNT(DISTINCT um.umuser) AS mapped_users, COUNT(DISTINCT ft.foreign_table_name) AS foreign_tables FROM pg_foreign_server s LEFT JOIN pg_user_mapping um ON um.umserver = s.oid LEFT JOIN information_schema.foreign_tables ft ON ft.foreign_server_name = s.srvname GROUP BY s.srvname, s.srvowner HAVING COUNT(DISTINCT um.umuser) > :max_mappings OR COUNT(DISTINCT ft.foreign_table_name) > :max_tables"}	{"condition": "row_count > 0", "description": "Foreign servers with many user mappings or tables — likely third-party app requirement"}	{"max_tables": 10, "max_mappings": 3}	2026-02-25 00:28:52.405273
5869	postgresql	query	Find user mappings storing credentials	{"sql": "SELECT s.srvname, um.umuser::regrole AS local_user, um.umoptions FROM pg_user_mapping um JOIN pg_foreign_server s ON um.umserver = s.oid WHERE um.umoptions IS NOT NULL"}	{"condition": "row_count > 0", "description": "User mappings with stored credentials — remote access credentials embedded in catalog"}	\N	2026-02-25 00:28:52.405273
5870	postgresql	query	Check if USAGE is granted broadly across schemas	{"sql": "SELECT n.nspname, n.nspacl::text FROM pg_namespace n WHERE n.nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast', 'public') AND (n.nspacl IS NULL OR n.nspacl::text LIKE '%=U%')"}	{"condition": "row_count > 0", "description": "Non-public schemas have USAGE grant for PUBLIC — no schema isolation"}	\N	2026-02-25 00:28:52.405273
5938	postgresql	config_check	Find non-default configuration with configuration file source	{"sql": "SELECT name, setting, boot_val, source, sourcefile, sourceline FROM pg_settings WHERE source = 'configuration file' AND setting != boot_val ORDER BY name"}	{"condition": "row_count > :threshold", "description": "Many parameters changed in config file — check if changes are documented"}	{"threshold": 15}	2026-02-25 00:28:52.405273
5871	postgresql	query	Find privileges granted WITH GRANT OPTION	{"sql": "SELECT grantee, table_schema, table_name, privilege_type, is_grantable FROM information_schema.table_privileges WHERE is_grantable = 'YES' AND grantee NOT IN ('postgres', 'PUBLIC') AND table_schema NOT IN ('pg_catalog', 'information_schema') ORDER BY grantee, table_schema, table_name"}	{"condition": "row_count > :threshold", "description": "Many privileges with GRANT OPTION — delegation is broadly enabled"}	{"threshold": 10}	2026-02-25 00:28:52.405273
5872	postgresql	query	Find grantees with GRANT OPTION on many tables	{"sql": "SELECT grantee, COUNT(DISTINCT table_schema || '.' || table_name) AS grantable_objects FROM information_schema.table_privileges WHERE is_grantable = 'YES' AND grantee NOT IN ('postgres') AND table_schema NOT IN ('pg_catalog', 'information_schema') GROUP BY grantee HAVING COUNT(DISTINCT table_schema || '.' || table_name) > :threshold ORDER BY grantable_objects DESC"}	{"condition": "row_count > 0", "description": "Users can delegate access to many objects — broad GRANT OPTION"}	{"threshold": 20}	2026-02-25 00:28:52.405273
5873	postgresql	query	Count distinct users with GRANT OPTION	{"sql": "SELECT COUNT(DISTINCT grantee) AS delegators FROM information_schema.table_privileges WHERE is_grantable = 'YES' AND grantee NOT IN ('postgres') AND table_schema NOT IN ('pg_catalog', 'information_schema')"}	{"condition": "delegators > :max_delegators", "description": "Many users can delegate permissions — decentralized, uncontrolled access management"}	{"max_delegators": 3}	2026-02-25 00:28:52.405273
5874	postgresql	query	Find GRANT OPTION holders	{"sql": "SELECT grantee, COUNT(*) AS grantable_count FROM information_schema.table_privileges WHERE is_grantable = 'YES' AND grantee NOT IN ('postgres') GROUP BY grantee ORDER BY grantable_count DESC"}	{"condition": "row_count > 0", "description": "GRANT OPTION holders exist"}	\N	2026-02-25 00:28:52.405273
5875	postgresql	config_check	Check if GRANT statements are logged	{"sql": "SELECT name, setting FROM pg_settings WHERE name = 'log_statement'"}	{"condition": "setting NOT IN ('ddl', 'all')", "description": "GRANT statements (DDL) not logged — delegation occurs without audit trail"}	\N	2026-02-25 00:28:52.405273
5876	postgresql	config_check	Check log_statement and pgAudit for GRANT monitoring	{"sql": "SELECT current_setting('pgaudit.log', true) AS pgaudit_log, (SELECT setting FROM pg_settings WHERE name = 'log_statement') AS log_statement"}	{"condition": "(pgaudit_log IS NULL OR (pgaudit_log NOT LIKE '%role%' AND pgaudit_log NOT LIKE '%all%')) AND log_statement NOT IN ('ddl', 'all')", "description": "Neither pgAudit role class nor log_statement captures GRANT activity"}	\N	2026-02-25 00:28:52.405273
5877	postgresql	query	Find multi-level GRANT OPTION delegation	{"sql": "SELECT grantee, grantor, table_schema, table_name, privilege_type FROM information_schema.table_privileges WHERE is_grantable = 'YES' AND grantor != 'postgres' AND grantee NOT IN ('postgres', 'PUBLIC') AND table_schema NOT IN ('pg_catalog', 'information_schema') ORDER BY grantor, grantee"}	{"condition": "row_count > 0", "description": "Non-postgres grantor with GRANT OPTION — privilege delegation chain in progress"}	\N	2026-02-25 00:28:52.405273
5878	postgresql	query	Find ADMIN OPTION on predefined roles	{"sql": "SELECT r.rolname AS member, g.rolname AS granted_role, m.admin_option FROM pg_auth_members m JOIN pg_roles r ON m.member = r.oid JOIN pg_roles g ON m.roleid = g.oid WHERE m.admin_option = true AND g.rolname IN ('pg_read_all_data', 'pg_write_all_data', 'pg_read_all_settings', 'pg_read_all_stats', 'pg_execute_server_program', 'pg_read_server_files', 'pg_write_server_files', 'pg_signal_backend', 'pg_monitor')"}	{"condition": "row_count > 0", "description": "ADMIN OPTION on sensitive predefined roles — can delegate powerful capabilities"}	\N	2026-02-25 00:28:52.405273
5879	postgresql	query	Find all ADMIN OPTION grants	{"sql": "SELECT r.rolname AS member, g.rolname AS granted_role, m.admin_option FROM pg_auth_members m JOIN pg_roles r ON m.member = r.oid JOIN pg_roles g ON m.roleid = g.oid WHERE m.admin_option = true ORDER BY g.rolname, r.rolname"}	{"condition": "row_count > :threshold", "description": "Many ADMIN OPTION grants — default configurations not reviewed"}	{"threshold": 5}	2026-02-25 00:28:52.405273
5880	postgresql	query	Find roles with ADMIN OPTION that can self-escalate	{"sql": "SELECT r.rolname AS member, g.rolname AS granted_role, g.rolsuper, g.rolcreatedb, g.rolcreaterole FROM pg_auth_members m JOIN pg_roles r ON m.member = r.oid JOIN pg_roles g ON m.roleid = g.oid WHERE m.admin_option = true AND (g.rolsuper = true OR g.rolcreatedb = true OR g.rolcreaterole = true OR g.rolname IN ('pg_read_all_data', 'pg_write_all_data', 'pg_execute_server_program'))"}	{"condition": "row_count > 0", "description": "Users with ADMIN OPTION on privileged roles — can grant these to themselves or others"}	\N	2026-02-25 00:28:52.405273
5881	postgresql	query	Find users with elevated privileges AND GRANT OPTION	{"sql": "SELECT DISTINCT tp.grantee FROM information_schema.table_privileges tp WHERE tp.is_grantable = 'YES' AND tp.grantee IN (SELECT rolname FROM pg_roles WHERE rolsuper = true OR rolcreatedb = true OR rolcreaterole = true) AND tp.grantee NOT IN ('postgres') AND tp.table_schema NOT IN ('pg_catalog', 'information_schema')"}	{"condition": "row_count > 0", "description": "Privileged users with GRANT OPTION — can grant same privileges to others"}	\N	2026-02-25 00:28:52.405273
5899	postgresql	query	Find accounts with server file read capability	{"sql": "SELECT r.rolname, r.rolsuper, g.rolname AS file_role FROM pg_roles r LEFT JOIN pg_auth_members m ON m.member = r.oid LEFT JOIN pg_roles g ON g.oid = m.roleid AND g.rolname = 'pg_read_server_files' WHERE r.rolcanlogin = true AND (r.rolsuper = true OR g.rolname IS NOT NULL)"}	{"condition": "row_count > :expected_count", "description": "More accounts than expected can read server files via COPY FROM"}	{"expected_count": 1}	2026-02-25 00:28:52.405273
5882	postgresql	query	Find uniform GRANT OPTION patterns suggesting template scripts	{"sql": "SELECT grantee, table_schema, COUNT(*) AS tables_with_grant, COUNT(DISTINCT privilege_type) AS privilege_types FROM information_schema.table_privileges WHERE is_grantable = 'YES' AND grantee NOT IN ('postgres') AND table_schema NOT IN ('pg_catalog', 'information_schema') GROUP BY grantee, table_schema HAVING COUNT(*) > :min_tables ORDER BY tables_with_grant DESC"}	{"condition": "row_count > 0 AND tables_with_grant > 10", "description": "GRANT OPTION on many tables for same user/schema — likely from provisioning template"}	{"min_tables": 10}	2026-02-25 00:28:52.405273
5883	postgresql	query	Count total GRANT OPTION grants and delegators	{"sql": "SELECT COUNT(*) AS total_grantable, COUNT(DISTINCT grantee) AS distinct_delegators FROM information_schema.table_privileges WHERE is_grantable = 'YES' AND grantee NOT IN ('postgres') AND table_schema NOT IN ('pg_catalog', 'information_schema')"}	{"condition": "total_grantable > :max_grantable OR distinct_delegators > :max_delegators", "description": "Excessive GRANT OPTION usage without apparent controls"}	{"max_grantable": 50, "max_delegators": 5}	2026-02-25 00:28:52.405273
5884	postgresql	query	Find inactive grantees with GRANT OPTION	{"sql": "SELECT grantee, COUNT(*) AS grantable_count FROM information_schema.table_privileges WHERE is_grantable = 'YES' AND grantee NOT IN ('postgres', 'PUBLIC') AND grantee NOT IN (SELECT DISTINCT usename FROM pg_stat_activity WHERE usename IS NOT NULL) AND table_schema NOT IN ('pg_catalog', 'information_schema') GROUP BY grantee ORDER BY grantable_count DESC"}	{"condition": "row_count > 0", "description": "Inactive users retain GRANT OPTION — legacy configuration never cleaned up"}	\N	2026-02-25 00:28:52.405273
