5955	postgresql	query	Count foreign tables granting cross-database access	{"sql": "SELECT ft.foreign_table_schema, ft.foreign_table_name, ft.foreign_server_name, (SELECT COUNT(*) FROM information_schema.role_table_grants rtg WHERE rtg.table_schema = ft.foreign_table_schema AND rtg.table_name = ft.foreign_table_name AND rtg.grantee != 'postgres') AS grantee_count FROM information_schema.foreign_tables ft ORDER BY grantee_count DESC"}	{"condition": "grantee_count > :threshold", "description": "Many users granted access to foreign tables — inheriting remote privileges"}	{"threshold": 3}	2026-02-25 00:28:52.405273
