5961	postgresql	query	Find roles with foreign server USAGE through group membership	{"sql": "SELECT r.rolname AS member, g.rolname AS via_group, s.srvname FROM pg_roles r JOIN pg_auth_members m ON m.member = r.oid JOIN pg_roles g ON g.oid = m.roleid CROSS JOIN pg_foreign_server s WHERE has_server_privilege(g.rolname, s.srvname, 'USAGE') AND r.rolcanlogin = true"}	{"condition": "row_count > :threshold", "description": "Login roles inherit foreign server access through group — may not realize scope"}	{"threshold": 3}	2026-02-25 00:28:52.405273
5962	postgresql	query	Check foreign server connection targets	{"sql": "SELECT s.srvname, s.srvoptions::text FROM pg_foreign_server s WHERE s.srvoptions IS NOT NULL"}	{"condition": "row_count > 0", "description": "Foreign servers configured — check if target hosts are in segmented networks"}	\N	2026-02-25 00:28:52.405273
5963	postgresql	query	Find foreign servers without recent foreign table activity	{"sql": "SELECT s.srvname, s.srvowner::regrole AS owner, COUNT(ft.foreign_table_name) AS table_count FROM pg_foreign_server s LEFT JOIN information_schema.foreign_tables ft ON ft.foreign_server_name = s.srvname GROUP BY s.srvname, s.srvowner ORDER BY table_count"}	{"condition": "table_count = 0", "description": "Foreign servers exist with no foreign tables — configuration artifacts from setup"}	\N	2026-02-25 00:28:52.405273
5964	postgresql	query	Check foreign server SSL options	{"sql": "SELECT s.srvname, s.srvoptions::text FROM pg_foreign_server s WHERE s.srvoptions::text NOT LIKE '%sslmode%' OR s.srvoptions::text LIKE '%sslmode=disable%' OR s.srvoptions::text LIKE '%sslmode=allow%' OR s.srvoptions::text LIKE '%sslmode=prefer%'"}	{"condition": "row_count > 0", "description": "Foreign servers without enforced SSL — credentials sent in cleartext"}	\N	2026-02-25 00:28:52.405273
