5983	postgresql	config_check	Check for partial SSL setup	{"sql": "SELECT (SELECT setting FROM pg_settings WHERE name = 'ssl') AS ssl_status, (SELECT setting FROM pg_settings WHERE name = 'ssl_cert_file') AS cert_file, (SELECT setting FROM pg_settings WHERE name = 'ssl_key_file') AS key_file, (SELECT COUNT(*) FROM pg_hba_file_rules WHERE type = 'hostssl') AS hostssl_rules"}	{"condition": "(ssl_status = 'on' AND hostssl_rules = 0) OR (ssl_status = 'off' AND cert_file != '')", "description": "Partial SSL configuration — started but not completed or enforced"}	\N	2026-02-25 00:28:52.405273
5984	postgresql	query	Check for deprecated TLS versions in active connections	{"sql": "SELECT s.version AS tls_version, a.application_name, a.client_addr, COUNT(*) AS connections FROM pg_stat_ssl s JOIN pg_stat_activity a ON s.pid = a.pid WHERE s.ssl = true AND s.version IN ('TLSv1', 'TLSv1.1') GROUP BY s.version, a.application_name, a.client_addr ORDER BY connections DESC"}	{"condition": "row_count > 0", "description": "Connections using TLS 1.0 or 1.1 — legacy application dependencies"}	\N	2026-02-25 00:28:52.405273
