6090	postgresql	query	Check for broad pg_hba rules and listen on all interfaces	{"sql": "SELECT (SELECT setting FROM pg_settings WHERE name = 'listen_addresses') AS listen_addr, (SELECT COUNT(*) FROM pg_hba_file_rules WHERE address IN ('0.0.0.0/0', '::/0')) AS open_rules"}	{"condition": "listen_addr IN ('*', '0.0.0.0') AND open_rules > 0", "description": "Listening on all interfaces with open pg_hba rules — relying only on pg_hba.conf"}	\N	2026-02-25 00:28:52.405273
6091	postgresql	config_check	Check for non-standard port and data directory	{"sql": "SELECT name, setting FROM pg_settings WHERE name IN ('port', 'data_directory', 'config_file') ORDER BY name"}	{"condition": "port != '5432' AND data_directory LIKE '%/tmp/%' OR data_directory LIKE '%home%'", "description": "Non-standard port or data directory in user space — potential shadow IT"}	\N	2026-02-25 00:28:52.405273
6092	postgresql	query	Find trust or password auth entries for broad networks	{"sql": "SELECT line_number, type, database, user_name, address, auth_method FROM pg_hba_file_rules WHERE auth_method IN ('trust', 'password') AND type IN ('host', 'hostssl', 'hostnossl') AND address NOT IN ('127.0.0.1', '::1', '127.0.0.1/32', '::1/128')"}	{"condition": "row_count > 0", "description": "Trust or plaintext password auth on network connections — likely temporary rule left permanent"}	\N	2026-02-25 00:28:52.405273
6093	postgresql	query	Check for hostname-based pg_hba entries	{"sql": "SELECT line_number, type, database, user_name, address, auth_method FROM pg_hba_file_rules WHERE type IN ('host', 'hostssl') AND address IS NOT NULL AND address !~ '^[0-9]+\\\\.' AND address !~ '^::' AND address NOT IN ('all', 'samehost', 'samenet', '0.0.0.0/0', '::/0')"}	{"condition": "row_count > 0", "description": "Hostname-based entries depend on DNS — DNS misconfiguration could expose database"}	\N	2026-02-25 00:28:52.405273
6094	postgresql	query	Check pg_hba.conf for default-deny pattern	{"sql": "SELECT line_number, type, database, user_name, address, auth_method FROM pg_hba_file_rules ORDER BY line_number DESC LIMIT 3"}	{"condition": "last rule is NOT 'host all all 0.0.0.0/0 reject'", "description": "No explicit reject-all rule at end of pg_hba.conf"}	\N	2026-02-25 00:28:52.405273
6095	postgresql	query	Check for overly permissive rules before implicit deny	{"sql": "SELECT line_number, type, address, auth_method FROM pg_hba_file_rules WHERE type IN ('host', 'hostssl') AND (address IN ('0.0.0.0/0', '::/0') OR address LIKE '%/8' OR address LIKE '%/16')"}	{"condition": "row_count > 0", "description": "Broad allow rules exist without explicit default-deny"}	\N	2026-02-25 00:28:52.405273
6096	postgresql	config_check	Check listen_addresses and pg_hba openness	{"sql": "SELECT (SELECT setting FROM pg_settings WHERE name = 'listen_addresses') AS listen_addr, (SELECT COUNT(*) FROM pg_hba_file_rules WHERE type IN ('host', 'hostssl') AND address NOT IN ('127.0.0.1', '::1', '127.0.0.1/32', '::1/128')) AS remote_rules"}	{"condition": "listen_addr IN ('*', '0.0.0.0') AND remote_rules > 0", "description": "Listening on all interfaces with remote access rules — no host-level firewall evidence"}	\N	2026-02-25 00:28:52.405273
