6159	postgresql	query	Find PII-suggestive columns stored as plain text	{"sql": "SELECT c.table_schema, c.table_name, c.column_name, c.data_type FROM information_schema.columns c WHERE c.column_name ~* '(ssn|social_security|credit_card|card_number|passport|tax_id|national_id)' AND c.data_type IN ('character varying', 'text', 'character', 'integer', 'bigint') AND c.table_schema NOT IN ('pg_catalog', 'information_schema')"}	{"condition": "row_count > 0", "description": "PII columns stored as plain text — not encrypted at column level"}	\N	2026-02-25 00:28:52.405273
6160	postgresql	query	Find indexed PII columns	{"sql": "SELECT t.relname AS table_name, a.attname AS column_name, i.relname AS index_name FROM pg_index ix JOIN pg_class t ON t.oid = ix.indrelid JOIN pg_class i ON i.oid = ix.indexrelid JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum = ANY(ix.indkey) JOIN pg_namespace n ON n.oid = t.relnamespace WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND a.attname ~* '(ssn|social_security|credit_card|email|phone|passport|tax_id)'"}	{"condition": "row_count > 0", "description": "PII columns have indexes — encryption would break searchability"}	\N	2026-02-25 00:28:52.405273
6161	postgresql	query	Find high-throughput tables with PII columns	{"sql": "SELECT s.relname, s.seq_scan + s.idx_scan AS total_scans, s.n_tup_ins + s.n_tup_upd AS total_writes FROM pg_stat_user_tables s WHERE s.relname IN (SELECT DISTINCT table_name FROM information_schema.columns WHERE column_name ~* '(ssn|credit_card|email|phone|passport|tax_id)' AND table_schema NOT IN ('pg_catalog', 'information_schema')) ORDER BY total_scans DESC LIMIT 10"}	{"condition": "total_scans > :threshold", "description": "High-throughput PII tables — encryption overhead is a legitimate performance concern"}	{"threshold": 100000}	2026-02-25 00:28:52.405273
