6231	oracle	query	ORA detect inactive sessions held beyond threshold	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.machine, s.status, s.logon_time, s.last_call_et AS seconds_since_last_activity FROM v$session s WHERE s.type = 'USER' AND s.status = 'INACTIVE' AND s.last_call_et > :threshold_seconds ORDER BY s.last_call_et DESC"}	{"condition": "row_count > :min_leaked_sessions", "description": "Multiple inactive sessions held beyond threshold indicate potential connection leaks"}	{"threshold_seconds": 1800, "min_leaked_sessions": 5}	2026-02-28 12:19:19.580455
6232	oracle	query	ORA check session resource utilization pressure	{"sql": "SELECT r.current_utilization AS current_sessions, r.max_utilization AS peak_sessions, r.limit_value AS max_sessions, ROUND(r.current_utilization / NULLIF(TO_NUMBER(DECODE(r.limit_value, 'UNLIMITED', '99999', r.limit_value)), 0) * 100, 1) AS utilization_pct FROM v$resource_limit r WHERE r.resource_name = 'sessions'"}	{"condition": "utilization_pct > :threshold_pct", "description": "Session utilization nearing capacity confirms leaked connections are causing resource pressure"}	{"threshold_pct": 75}	2026-02-28 12:19:19.580455
6233	oracle	query	ORA identify top leaking application programs	{"sql": "SELECT s.program, s.machine, COUNT(*) AS inactive_count, MAX(s.last_call_et) AS max_idle_seconds FROM v$session s WHERE s.type = 'USER' AND s.status = 'INACTIVE' AND s.last_call_et > :threshold_seconds GROUP BY s.program, s.machine ORDER BY inactive_count DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0 AND max(inactive_count) > :min_per_app", "description": "Concentration of idle sessions from a single program confirms application-level connection leak"}	{"min_per_app": 3, "threshold_seconds": 1800}	2026-02-28 12:19:19.580455
6234	oracle	query	ORA find long-running active sessions	{"sql": "SELECT s.sid, s.serial#, s.username, s.sql_id, s.program, s.machine, s.last_call_et AS seconds_active, sq.sql_text FROM v$session s LEFT JOIN v$sql sq ON s.sql_id = sq.sql_id AND s.sql_child_number = sq.child_number WHERE s.status = 'ACTIVE' AND s.type = 'USER' AND s.last_call_et > :threshold_seconds ORDER BY s.last_call_et DESC"}	{"condition": "row_count > 0", "description": "Active sessions running longer than threshold indicate slow queries consuming connections"}	{"threshold_seconds": 300}	2026-02-28 12:19:19.580455
6235	oracle	query	ORA check slow query execution statistics	{"sql": "SELECT sql_id, executions, elapsed_time / 1000000 AS elapsed_secs, cpu_time / 1000000 AS cpu_secs, buffer_gets, disk_reads, rows_processed, ROUND(elapsed_time / NULLIF(executions, 0) / 1000000, 2) AS avg_elapsed_secs FROM v$sql WHERE sql_id IN (SELECT sql_id FROM v$session WHERE status = 'ACTIVE' AND type = 'USER' AND last_call_et > :threshold_seconds) ORDER BY elapsed_time DESC"}	{"condition": "avg_elapsed_secs > :slow_threshold", "description": "High average elapsed time per execution confirms slow queries draining connections"}	{"slow_threshold": 60, "threshold_seconds": 300}	2026-02-28 12:19:19.580455
6238	oracle	query	ORA detect blocked sessions waiting on locks	{"sql": "SELECT s.sid AS waiting_sid, s.serial# AS waiting_serial, s.username AS waiting_user, s.program AS waiting_program, s.seconds_in_wait, s.event, bs.sid AS blocking_sid, bs.serial# AS blocking_serial, bs.username AS blocking_user, bs.program AS blocking_program FROM v$session s JOIN v$session bs ON s.blocking_session = bs.sid WHERE s.blocking_session IS NOT NULL ORDER BY s.seconds_in_wait DESC"}	{"condition": "row_count > 0", "description": "Sessions blocked by other sessions indicate lock contention consuming connections"}	\N	2026-02-28 12:19:19.580455
6239	oracle	query	ORA identify lock wait chains depth	{"sql": "SELECT LEVEL AS chain_depth, SYS_CONNECT_BY_PATH(sid, ' -> ') AS blocking_chain, sid, serial#, username, program, event, seconds_in_wait FROM v$session START WITH blocking_session IS NULL AND sid IN (SELECT blocking_session FROM v$session WHERE blocking_session IS NOT NULL) CONNECT BY PRIOR sid = blocking_session ORDER BY chain_depth DESC"}	{"condition": "max(chain_depth) > 1", "description": "Deep blocking chains indicate cascading lock contention consuming multiple connections"}	\N	2026-02-28 12:19:19.580455
6240	oracle	query	ORA find long-running open transactions	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.machine, s.status, t.start_time, ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400) AS transaction_age_secs, t.used_ublk AS undo_blocks, t.used_urec AS undo_records FROM v$transaction t JOIN v$session s ON t.ses_addr = s.saddr WHERE s.type = 'USER' ORDER BY transaction_age_secs DESC"}	{"condition": "transaction_age_secs > :threshold_seconds", "description": "Transactions open beyond threshold suggest application holding connections during non-DB work"}	{"threshold_seconds": 600}	2026-02-28 12:19:19.580455
6265	oracle	query	ORA check recent deadlock rate correlation	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-00060%' AND originating_timestamp > SYSTIMESTAMP - INTERVAL '24' HOUR ORDER BY originating_timestamp DESC"}	{"condition": "row_count > :min_deadlocks", "description": "Recent deadlocks coinciding with long-running transactions confirms the causal relationship"}	{"min_deadlocks": 1}	2026-02-28 12:19:19.580455
6241	oracle	query	ORA check if long transactions are inactive	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.status, s.last_call_et AS idle_seconds, ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400) AS txn_age_secs FROM v$transaction t JOIN v$session s ON t.ses_addr = s.saddr WHERE s.type = 'USER' AND s.status = 'INACTIVE' AND s.last_call_et > :idle_threshold ORDER BY txn_age_secs DESC"}	{"condition": "row_count > 0", "description": "Inactive sessions with open transactions confirm application holds connections during external processing"}	{"idle_threshold": 300}	2026-02-28 12:19:19.580455
6243	oracle	query	ORA check for full table scans in active queries	{"sql": "SELECT sp.sql_id, sp.plan_hash_value, sp.operation, sp.options, sp.object_name, sp.cost, sp.cardinality FROM v$sql_plan sp WHERE sp.sql_id IN (SELECT sql_id FROM v$session WHERE status = 'ACTIVE' AND type = 'USER' AND last_call_et > :threshold_seconds) AND sp.operation = 'TABLE ACCESS' AND sp.options = 'FULL' AND sp.object_name IS NOT NULL ORDER BY sp.cost DESC"}	{"condition": "row_count > 0", "description": "Full table scans on active queries confirm unoptimized execution plans holding connections"}	{"threshold_seconds": 60}	2026-02-28 12:19:19.580455
6244	oracle	query	ORA find sniped or killed sessions still in session table	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.machine, s.status, s.last_call_et AS seconds_since_last_call, s.logon_time FROM v$session s WHERE s.type = 'USER' AND (s.status = 'SNIPED' OR (s.status = 'INACTIVE' AND s.last_call_et > :stale_threshold)) ORDER BY s.last_call_et DESC"}	{"condition": "row_count > :min_stale", "description": "SNIPED or very long-idle sessions suggest connection pool is not validating connections before reuse"}	{"min_stale": 3, "stale_threshold": 7200}	2026-02-28 12:19:19.580455
6245	oracle	query	ORA check IDLE_TIME resource limit configuration	{"sql": "SELECT p.profile, p.resource_name, p.limit FROM dba_profiles p WHERE p.resource_name = 'IDLE_TIME' AND p.profile IN (SELECT DISTINCT profile FROM dba_users WHERE account_status = 'OPEN') ORDER BY p.profile"}	{"condition": "limit = 'UNLIMITED' OR limit = 'DEFAULT'", "description": "No IDLE_TIME limit means Oracle won't terminate stale sessions, relying on application-side validation"}	\N	2026-02-28 12:19:19.580455
6249	oracle	query	ORA check alert log for ORA-00018 or ORA-00020 errors	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-00018%' OR message_text LIKE '%ORA-00020%' OR message_text LIKE '%maximum number of processes%' AND originating_timestamp > SYSTIMESTAMP - INTERVAL '7' DAY ORDER BY originating_timestamp DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "ORA-00018 (max sessions exceeded) or ORA-00020 (max processes exceeded) in alert log confirms the limit was hit"}	\N	2026-02-28 12:19:19.580455
6250	oracle	query	ORA count idle sessions by program and duration	{"sql": "SELECT s.program, s.machine, COUNT(*) AS idle_count, ROUND(AVG(s.last_call_et)) AS avg_idle_seconds, MAX(s.last_call_et) AS max_idle_seconds FROM v$session s WHERE s.type = 'USER' AND s.status = 'INACTIVE' GROUP BY s.program, s.machine HAVING COUNT(*) > :min_idle ORDER BY idle_count DESC"}	{"condition": "row_count > 0", "description": "Programs with many idle sessions indicate connection pools not releasing idle connections"}	{"min_idle": 5}	2026-02-28 12:19:19.580455
6254	oracle	query	ORA find sessions with unreachable client processes	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.machine, s.status, s.logon_time, s.last_call_et AS seconds_idle, p.spid AS server_pid FROM v$session s JOIN v$process p ON s.paddr = p.addr WHERE s.type = 'USER' AND s.status = 'INACTIVE' AND s.last_call_et > :orphan_threshold ORDER BY s.last_call_et DESC"}	{"condition": "row_count > :min_orphans", "description": "Sessions idle beyond threshold from applications that have shut down indicate connection pool not drained"}	{"min_orphans": 3, "orphan_threshold": 3600}	2026-02-28 12:19:19.580455
6456	oracle	query	ora-check-backup-failed-during-snapshot-window	{"sql": "SELECT session_key, input_type, status, start_time, end_time, output_bytes_display, elapsed_seconds FROM v$rman_backup_job_details WHERE status = 'FAILED' AND start_time > SYSDATE - :recent_days ORDER BY start_time DESC"}	{"condition": "row_count > 0", "description": "Recent RMAN backup failures may correlate with VM snapshot freeze operations"}	{"recent_days": 7}	2026-02-28 12:19:19.580455
6257	oracle	query	ORA identify sessions with high network wait proportion	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.machine, se.event, se.total_waits, ROUND(se.time_waited_micro / 1000000, 2) AS network_wait_secs FROM v$session_event se JOIN v$session s ON se.sid = s.sid WHERE se.wait_class = 'Network' AND se.event LIKE 'SQL*Net%' AND se.time_waited_micro > :min_wait_micro AND s.type = 'USER' ORDER BY se.time_waited_micro DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Sessions with significant network wait time confirm latency is impacting connection holding time"}	{"min_wait_micro": 5000000}	2026-02-28 12:19:19.580455
6258	oracle	query	ORA check deadlock trace files from alert log	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-00060%' AND originating_timestamp > SYSTIMESTAMP - INTERVAL '7' DAY ORDER BY originating_timestamp DESC"}	{"condition": "row_count > 0", "description": "ORA-00060 (deadlock detected) occurrences in alert log confirm deadlock events"}	\N	2026-02-28 12:19:19.580455
6468	oracle	query	ora-check-rman-compression-config	{"sql": "SELECT conf#, name, value FROM v$rman_configuration WHERE name LIKE '%COMPRESSION%' OR name LIKE '%DEVICE%'"}	{"condition": "row_count = 0 OR value NOT LIKE '%COMPRESSED%'", "description": "RMAN compression is not configured or explicitly disabled, causing larger backup sizes"}	\N	2026-02-28 12:19:19.580455
6261	oracle	query	ORA check TM lock contention on unindexed FK tables	{"sql": "SELECT o.owner, o.object_name, o.object_type, l.sid, l.type, DECODE(l.lmode, 0, 'None', 1, 'Null', 2, 'Row-S', 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS lock_mode, DECODE(l.request, 0, 'None', 1, 'Null', 2, 'Row-S', 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS request_mode FROM v$lock l JOIN dba_objects o ON l.id1 = o.object_id WHERE l.type = 'TM' AND l.request > 0 ORDER BY o.object_name"}	{"condition": "row_count > 0", "description": "TM (table-level) lock contention confirms unindexed foreign keys are causing lock escalation"}	\N	2026-02-28 12:19:19.580455
6262	oracle	query	ORA check for table-level TM lock contention	{"sql": "SELECT o.owner, o.object_name, l.sid, s.username, s.program, DECODE(l.lmode, 0, 'None', 2, 'Row-S', 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS lock_mode, DECODE(l.request, 0, 'None', 2, 'Row-S', 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS request_mode FROM v$lock l JOIN dba_objects o ON l.id1 = o.object_id JOIN v$session s ON l.sid = s.sid WHERE l.type = 'TM' AND (l.lmode >= 4 OR l.request >= 4) ORDER BY o.object_name"}	{"condition": "row_count > 0", "description": "Share or higher TM locks indicate table-level locking beyond normal row-level DML"}	\N	2026-02-28 12:19:19.580455
6264	oracle	query	ORA find long-running transactions with lock counts	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, t.start_time, ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400) AS txn_age_secs, t.used_ublk AS undo_blocks, (SELECT COUNT(*) FROM v$lock l WHERE l.sid = s.sid AND l.type IN ('TX', 'TM')) AS lock_count FROM v$transaction t JOIN v$session s ON t.ses_addr = s.saddr WHERE ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400) > :threshold_seconds ORDER BY txn_age_secs DESC"}	{"condition": "row_count > 0 AND max(lock_count) > :min_locks", "description": "Long-running transactions with multiple locks increase deadlock probability"}	{"min_locks": 3, "threshold_seconds": 300}	2026-02-28 12:19:19.580455
11363	mysql	query	Check if any audit plugin is providing logging	{"sql": "SELECT PLUGIN_NAME, PLUGIN_STATUS FROM information_schema.PLUGINS WHERE PLUGIN_NAME LIKE '%audit%'"}	{"condition": "row_count = 0", "description": "No audit plugin and general log disabled means no SQL activity logging at all"}	\N	2026-03-01 06:30:58.706791
6266	oracle	query	ORA find foreign key constraints with parent tables under DML	{"sql": "SELECT c.owner, c.table_name AS child_table, c.constraint_name, rc.table_name AS parent_table, cc.column_name FROM dba_constraints c JOIN dba_constraints rc ON c.r_constraint_name = rc.constraint_name AND c.r_owner = rc.owner JOIN dba_cons_columns cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner WHERE c.constraint_type = 'R' AND c.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB') AND rc.table_name IN (SELECT object_name FROM dba_objects o JOIN v$lock l ON o.object_id = l.id1 WHERE l.type = 'TM' AND l.lmode >= 3) ORDER BY c.owner, parent_table"}	{"condition": "row_count > 0", "description": "Active DML locks on parent tables with foreign key children indicate FK-driven lock dependencies"}	\N	2026-02-28 12:19:19.580455
6268	oracle	query	ora_find_sqls_with_multiple_plans	{"sql": "SELECT sql_id, COUNT(DISTINCT plan_hash_value) AS plan_count, SUM(executions) AS total_executions FROM v$sql WHERE parsing_schema_name NOT IN ('SYS','SYSTEM','DBSNMP') AND executions > 10 GROUP BY sql_id HAVING COUNT(DISTINCT plan_hash_value) > 1 ORDER BY plan_count DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "SQL statements with multiple execution plans may acquire locks in different orders across executions"}	\N	2026-02-28 12:19:19.580455
6270	oracle	query	ora_recent_deadlock_traces_alert_log	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-00060%' AND originating_timestamp > SYSDATE - :lookback_days ORDER BY originating_timestamp DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "ORA-00060 deadlock errors in alert log corroborate deadlock occurrence alongside plan instability"}	{"lookback_days": 7}	2026-02-28 12:19:19.580455
6286	oracle	query	ora_check_long_transactions_with_savepoints	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, t.start_time, (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400 AS duration_secs, t.used_ublk AS undo_blocks FROM v$transaction t JOIN v$session s ON t.ses_addr = s.saddr WHERE (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400 > :min_duration_secs ORDER BY duration_secs DESC"}	{"condition": "row_count > 0", "description": "Long-running transactions with undo usage suggest complex savepoint/rollback patterns holding locks"}	{"min_duration_secs": 300}	2026-02-28 12:19:19.580455
6271	oracle	query	ora_find_row_lock_contention_sessions	{"sql": "SELECT l1.sid AS blocking_sid, l2.sid AS waiting_sid, o.object_name, o.object_type, s1.username AS blocking_user, s2.username AS waiting_user, s2.sql_id AS waiting_sql_id FROM v$lock l1 JOIN v$lock l2 ON l1.id1 = l2.id1 AND l1.id2 = l2.id2 AND l1.block = 1 AND l2.request > 0 JOIN v$session s1 ON l1.sid = s1.sid JOIN v$session s2 ON l2.sid = s2.sid LEFT JOIN v$locked_object lo ON lo.session_id = l1.sid LEFT JOIN dba_objects o ON lo.object_id = o.object_id WHERE l1.type = 'TX'"}	{"condition": "row_count > 0", "description": "Active TX lock contention shows multiple sessions competing for the same data"}	\N	2026-02-28 12:19:19.580455
6272	oracle	query	ora_check_high_enqueue_wait_rate	{"sql": "SELECT event, total_waits, time_waited_micro / 1000000 AS time_waited_secs, average_wait / 100 AS avg_wait_secs FROM v$system_event WHERE event LIKE 'enq: TX%' AND total_waits > :min_waits ORDER BY total_waits DESC"}	{"condition": "row_count > 0 AND total_waits > min_waits", "description": "High TX enqueue waits confirm heavy row-level contention"}	{"min_waits": 100}	2026-02-28 12:19:19.580455
6322	oracle	query	ora_check_datafile_status_for_corruption	{"sql": "SELECT file#, status, name, recover, fuzzy FROM v$datafile_header WHERE status != 'ONLINE' OR recover = 'YES' OR fuzzy = 'YES'"}	{"condition": "row_count > 0", "description": "Datafiles needing recovery or in fuzzy state indicate corruption or crash recovery issues"}	\N	2026-02-28 12:19:19.580455
6273	oracle	query	ora_deadlock_frequency_check	{"sql": "SELECT TO_CHAR(originating_timestamp, 'YYYY-MM-DD HH24') AS hour, COUNT(*) AS deadlock_count FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-00060%' AND originating_timestamp > SYSDATE - :lookback_days GROUP BY TO_CHAR(originating_timestamp, 'YYYY-MM-DD HH24') ORDER BY deadlock_count DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Deadlock occurrences correlating with high concurrency hours confirms the root cause"}	{"lookback_days": 7}	2026-02-28 12:19:19.580455
6274	oracle	query	ora_find_full_scan_sqls_with_locks	{"sql": "SELECT sa.sql_id, sa.sql_text, sa.executions, sa.buffer_gets, sa.disk_reads, sa.rows_processed FROM v$sqlarea sa WHERE sa.executions > 0 AND sa.buffer_gets / GREATEST(sa.executions, 1) > :buffer_gets_threshold AND sa.parsing_schema_name NOT IN ('SYS','SYSTEM') ORDER BY sa.buffer_gets DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "SQL statements with high buffer gets per execution likely perform full table scans"}	{"buffer_gets_threshold": 10000}	2026-02-28 12:19:19.580455
6292	oracle	query	ora_check_tm_lock_contention	{"sql": "SELECT event, total_waits, time_waited_micro / 1000000 AS time_waited_secs FROM v$system_event WHERE event LIKE 'enq: TM%' AND total_waits > 0 ORDER BY total_waits DESC"}	{"condition": "row_count > 0", "description": "TM (table-level DML) enqueue waits confirm table-level lock contention from unindexed FKs"}	\N	2026-02-28 12:19:19.580455
6275	oracle	query	ora_check_full_scan_plans	{"sql": "SELECT p.sql_id, p.operation, p.options, p.object_name, p.object_type FROM v$sql_plan p WHERE p.operation = 'TABLE ACCESS' AND p.options = 'FULL' AND p.sql_id IN (SELECT sql_id FROM v$sqlarea WHERE buffer_gets / GREATEST(executions, 1) > :buffer_gets_threshold AND parsing_schema_name NOT IN ('SYS','SYSTEM'))"}	{"condition": "row_count > 0", "description": "Confirmed TABLE ACCESS FULL operations on user tables — these acquire more row locks than index-based access"}	{"buffer_gets_threshold": 10000}	2026-02-28 12:19:19.580455
6276	oracle	query	ora_correlate_full_scans_with_deadlocks	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-00060%' AND originating_timestamp > SYSDATE - 7 ORDER BY originating_timestamp DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Deadlocks occurring alongside full-scan queries confirm missing indexes as contributing factor"}	\N	2026-02-28 12:19:19.580455
