6391	oracle	query	ora-check-active-rman-sessions	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.status, s.event, s.wait_class, s.seconds_in_wait, s.sql_id, sl.sofar, sl.totalwork, ROUND(sl.sofar / NULLIF(sl.totalwork, 0) * 100, 1) AS pct_complete, sl.elapsed_seconds, sl.time_remaining FROM v$session s LEFT JOIN v$session_longops sl ON s.sid = sl.sid AND s.serial# = sl.serial# WHERE s.program LIKE '%rman%' AND s.status = 'ACTIVE' ORDER BY s.seconds_in_wait DESC"}	{"condition": "seconds_in_wait > :stuck_threshold_seconds", "description": "RMAN session waiting for extended time with no progress indicates stuck backup"}	{"stuck_threshold_seconds": 3600}	2026-02-28 12:19:19.580455
