6658	oracle	query	ora-priv-creep: find users with excessive role accumulation	{"sql": "SELECT grantee, COUNT(*) AS role_count, LISTAGG(granted_role, ', ') WITHIN GROUP (ORDER BY granted_role) AS roles FROM dba_role_privs WHERE grantee NOT IN ('SYS', 'SYSTEM') AND grantee IN (SELECT username FROM dba_users WHERE oracle_maintained = 'N' AND account_status = 'OPEN') GROUP BY grantee HAVING COUNT(*) > :threshold_roles ORDER BY role_count DESC"}	{"condition": "row_count > 0", "description": "Users with many roles may have accumulated privileges through unchecked role changes"}	{"threshold_roles": 5}	2026-02-28 12:19:19.580455
6659	oracle	query	ora-priv-creep: count total effective privileges per user	{"sql": "SELECT rp.grantee, COUNT(DISTINCT sp.privilege) AS total_sys_privs, (SELECT COUNT(DISTINCT granted_role) FROM dba_role_privs rp2 WHERE rp2.grantee = rp.grantee) AS direct_roles FROM dba_role_privs rp JOIN role_sys_privs sp ON sp.role = rp.granted_role WHERE rp.grantee NOT IN ('SYS', 'SYSTEM') AND rp.grantee IN (SELECT username FROM dba_users WHERE oracle_maintained = 'N') GROUP BY rp.grantee HAVING COUNT(DISTINCT sp.privilege) > :threshold_privs ORDER BY total_sys_privs DESC"}	{"condition": "row_count > 0", "description": "Users with large numbers of effective system privileges through roles confirm privilege creep"}	{"threshold_privs": 20}	2026-02-28 12:19:19.580455
6660	oracle	query	ora-temp-priv-not-revoked: find DBA role on non-admin users	{"sql": "SELECT rp.grantee, rp.granted_role, rp.admin_option, rp.default_role, u.created, u.last_login FROM dba_role_privs rp JOIN dba_users u ON u.username = rp.grantee WHERE rp.granted_role IN ('DBA', 'SYSDBA', 'SYSOPER', 'SYSBACKUP') AND rp.grantee NOT IN ('SYS', 'SYSTEM') AND u.oracle_maintained = 'N' AND u.account_status = 'OPEN' ORDER BY rp.grantee"}	{"condition": "row_count > 0", "description": "Non-system users with DBA or SYS* roles may have temporary escalations that were never revoked"}	\N	2026-02-28 12:19:19.580455
6661	oracle	query	ora-temp-priv-not-revoked: check audit trail for recent GRANT operations	{"sql": "SELECT username, obj_name, action_name, TO_CHAR(timestamp, 'YYYY-MM-DD HH24:MI:SS') AS grant_time FROM dba_audit_trail WHERE action_name IN ('GRANT ROLE', 'GRANT') AND timestamp > SYSDATE - 90 ORDER BY timestamp DESC"}	{"condition": "row_count > 0", "description": "Recent privilege grants without corresponding revokes confirm temporary escalations left in place"}	\N	2026-02-28 12:19:19.580455
