6662	oracle	query	ora-tool-priv-esc: check sessions from management tools with elevated privileges	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.module, s.machine, s.osuser, s.logon_time FROM v$session s WHERE s.program IN ('SQL Developer', 'sqldev.exe', 'TOAD.exe', 'toad.exe', 'Toad for Oracle', 'plsqldev.exe', 'PL/SQL Developer', 'dbvis.exe', 'DBeaver', 'sqlplus.exe', 'sqlplus') AND s.username IN (SELECT grantee FROM dba_role_privs WHERE granted_role = 'DBA') AND s.username NOT IN ('SYS', 'SYSTEM') ORDER BY s.logon_time DESC"}	{"condition": "row_count > 0", "description": "Management tools connected with DBA-privileged accounts indicate tool-mediated privilege escalation risk"}	\N	2026-02-28 12:19:19.580455
6667	oracle	query	ora-long-txn-undo: find long-running active transactions	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.machine, s.status, t.start_time, ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 24 * 60, 1) AS duration_minutes, t.used_ublk * (SELECT value FROM v$parameter WHERE name = 'db_block_size') / 1048576 AS undo_mb FROM v$transaction t JOIN v$session s ON s.saddr = t.ses_addr WHERE (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 24 * 60 > :threshold_minutes ORDER BY duration_minutes DESC"}	{"condition": "row_count > 0", "description": "Long-running transactions consuming UNDO space and preventing space reclamation"}	{"threshold_minutes": 60}	2026-02-28 12:19:19.580455
6669	oracle	query	ora-idle-in-txn: find inactive sessions with open transactions	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.machine, s.status, s.last_call_et AS idle_seconds, t.start_time, t.used_ublk, t.used_urec FROM v$session s JOIN v$transaction t ON t.ses_addr = s.saddr WHERE s.status = 'INACTIVE' AND s.last_call_et > :threshold_idle_seconds ORDER BY s.last_call_et DESC"}	{"condition": "row_count > 0", "description": "Inactive sessions with open transactions are holding UNDO and lock resources"}	{"threshold_idle_seconds": 1800}	2026-02-28 12:19:19.580455
6670	oracle	query	ora-idle-in-txn: check if idle sessions are blocking others	{"sql": "SELECT s.sid AS blocking_sid, s.username AS blocking_user, s.status AS blocking_status, s.last_call_et AS idle_seconds, w.sid AS waiting_sid, w.username AS waiting_user, w.event AS wait_event FROM v$session s JOIN v$session w ON w.blocking_session = s.sid WHERE s.status = 'INACTIVE' AND EXISTS (SELECT 1 FROM v$transaction t WHERE t.ses_addr = s.saddr) ORDER BY s.last_call_et DESC"}	{"condition": "row_count > 0", "description": "Idle sessions with open transactions that block other sessions confirms the problem"}	\N	2026-02-28 12:19:19.580455
6671	oracle	query	ORA find in-doubt distributed transactions	{"sql": "SELECT local_tran_id, global_tran_id, state, mixed, host, commit# FROM dba_2pc_pending ORDER BY state"}	{"condition": "row_count > 0", "description": "In-doubt distributed transactions block undo cleanup and can prevent segment reuse"}	\N	2026-02-28 12:19:19.580455
6673	oracle	query	ORA check Data Guard standby apply lag	{"sql": "SELECT dest_id, status, type, gap_status, archived_seq#, applied_seq#, (archived_seq# - applied_seq#) AS apply_lag_sequences FROM v$archive_dest_status WHERE type = 'PHYSICAL' OR type = 'LOGICAL' ORDER BY dest_id"}	{"condition": "apply_lag_sequences > :lag_threshold", "description": "Standby apply lag indicates redo logs cannot be reused, causing log space pressure"}	{"lag_threshold": 10}	2026-02-28 12:19:19.580455
6674	oracle	query	ORA check archived log retention impact	{"sql": "SELECT name, TO_CHAR(first_time, 'YYYY-MM-DD HH24:MI:SS') AS first_time, TO_CHAR(next_time, 'YYYY-MM-DD HH24:MI:SS') AS next_time, applied, deleted, status FROM v$archived_log WHERE applied = 'NO' AND deleted = 'NO' ORDER BY first_time DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > :min_unapplied", "description": "Many unapplied archived logs confirm standby lag is preventing log cleanup"}	{"min_unapplied": 20}	2026-02-28 12:19:19.580455
6675	oracle	query	ORA check undo retention guarantee and standby config	{"sql": "SELECT name, value FROM v$parameter WHERE name IN ('undo_retention', 'undo_management', 'undo_tablespace') ORDER BY name"}	{"condition": "row_count > 0", "description": "Undo retention parameters determine how long Oracle keeps undo for read consistency"}	\N	2026-02-28 12:19:19.580455
6677	oracle	query	ORA check for active Data Guard standby destinations	{"sql": "SELECT dest_id, dest_name, status, type, target, schedule FROM v$archive_dest WHERE status = 'VALID' AND target = 'STANDBY_LOGFILE' ORDER BY dest_id"}	{"condition": "row_count > 0", "description": "Active standby destinations with queries may extend undo retention on primary"}	\N	2026-02-28 12:19:19.580455
6678	oracle	query	ORA find DDL locks blocking background processes	{"sql": "SELECT l.sid, s.username, s.program, s.module, o.owner, o.object_name, o.object_type, DECODE(l.lmode, 0, 'None', 1, 'Null', 2, 'Row-S', 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS lock_mode FROM v$lock l JOIN dba_objects o ON l.id1 = o.object_id JOIN v$session s ON l.sid = s.sid WHERE l.type = 'TM' AND l.lmode >= 5 AND s.type = 'USER' ORDER BY o.object_name"}	{"condition": "row_count > 0", "description": "Exclusive or S/Row-X table locks from user sessions can block background maintenance operations"}	\N	2026-02-28 12:19:19.580455
6682	oracle	query	ORA check I/O wait events for user vs background	{"sql": "SELECT s.type AS session_type, se.event, SUM(se.total_waits) AS total_waits, ROUND(SUM(se.time_waited_micro) / 1000000, 2) AS total_wait_secs FROM v$session_event se JOIN v$session s ON se.sid = s.sid WHERE se.wait_class = 'User I/O' GROUP BY s.type, se.event ORDER BY total_wait_secs DESC"}	{"condition": "total_wait_secs > :io_threshold", "description": "Significant I/O waits for both user and background sessions indicate I/O contention"}	{"io_threshold": 60}	2026-02-28 12:19:19.580455
6683	oracle	query	ORA check resource manager consumer group I/O usage	{"sql": "SELECT se.event, se.total_waits, ROUND(se.time_waited_micro / 1000000, 2) AS wait_secs, ROUND(se.time_waited_micro / NULLIF(se.total_waits, 0) / 1000, 2) AS avg_wait_ms FROM v$system_event se WHERE se.wait_class = 'User I/O' AND se.total_waits > 0 ORDER BY se.time_waited_micro DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "avg_wait_ms > :latency_threshold", "description": "High average I/O wait indicates disk subsystem is saturated by combined user and maintenance load"}	{"latency_threshold": 20}	2026-02-28 12:19:19.580455
6685	oracle	query	ORA check sort segment usage by session	{"sql": "SELECT ss.tablespace, ss.username, ss.session_num, ss.blocks, ROUND(ss.blocks * (SELECT block_size FROM dba_tablespaces WHERE tablespace_name = ss.tablespace AND ROWNUM = 1) / 1024 / 1024) AS used_mb FROM v$sort_usage ss ORDER BY ss.blocks DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Active sort segments from user sessions that may be blocking temp space cleanup"}	\N	2026-02-28 12:19:19.580455
