6695	oracle	query	ORA check auto stats operation history for failures	{"sql": "SELECT operation, target, start_time, end_time, status, (EXTRACT(HOUR FROM (end_time - start_time)) * 3600 + EXTRACT(MINUTE FROM (end_time - start_time)) * 60 + EXTRACT(SECOND FROM (end_time - start_time))) AS duration_secs FROM dba_optstat_operations WHERE operation = 'gather_database_stats (auto)' AND status != 'COMPLETED' AND start_time > SYSTIMESTAMP - INTERVAL '30' DAY ORDER BY start_time DESC"}	{"condition": "row_count > 0", "description": "Auto stats operations that did not complete indicate timeout or failure during collection"}	\N	2026-02-28 12:19:19.580455
6697	oracle	query	ORA check incremental statistics preference on partitioned tables	{"sql": "SELECT dt.owner, dt.table_name, dt.partitioning_type, dt.partition_count, DBMS_STATS.GET_PREFS('INCREMENTAL', dt.owner, dt.table_name) AS incremental_setting FROM dba_part_tables dt WHERE dt.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB', 'WMSYS') ORDER BY dt.partition_count DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "incremental_setting = 'TRUE'", "description": "Partitioned tables with incremental stats enabled need proper synopsis management"}	\N	2026-02-28 12:19:19.580455
6701	oracle	query	ORA check auto stats operation completion rate	{"sql": "SELECT status, COUNT(*) AS operation_count FROM dba_optstat_operations WHERE operation LIKE '%auto%' AND start_time > SYSTIMESTAMP - INTERVAL '30' DAY GROUP BY status ORDER BY operation_count DESC"}	{"condition": "any status != 'COMPLETED'", "description": "Non-completed auto stats operations confirm maintenance windows are too short"}	\N	2026-02-28 12:19:19.580455
6704	oracle	query	ORA check cursor invalidation after stats refresh	{"sql": "SELECT sql_id, plan_hash_value, executions, first_load_time, last_active_time, invalidations, loads, is_obsolete FROM v$sql WHERE executions > :min_executions AND invalidations = 0 AND TO_DATE(first_load_time, 'YYYY-MM-DD/HH24:MI:SS') < SYSDATE - :days_old ORDER BY executions DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > :min_stale_cursors", "description": "Frequently executed cursors with zero invalidations and old first_load_time may be using stale plans"}	{"days_old": 7, "min_executions": 1000, "min_stale_cursors": 5}	2026-02-28 12:19:19.580455
8478	oracle	query	ORA check for TX row lock contention between same-object transactions	{"sql": "SELECT event, total_waits, ROUND(time_waited_micro / 1000000, 2) AS time_waited_secs, ROUND(time_waited_micro / NULLIF(total_waits, 0) / 1000, 2) AS avg_wait_ms FROM v$system_event WHERE event = 'enq: TX - row lock contention' ORDER BY time_waited_micro DESC"}	{"condition": "total_waits > :contention_threshold", "description": "TX row lock contention confirms UPDATE operations conflicting within transactions"}	{"contention_threshold": 100}	2026-02-28 12:19:19.580455
6709	oracle	query	ORA check for direct-path load hint in recent SQL	{"sql": "SELECT sql_id, SUBSTR(sql_text, 1, 200) AS sql_preview, executions, last_active_time FROM v$sql WHERE (UPPER(sql_text) LIKE '%APPEND%' OR UPPER(sql_text) LIKE '%PARALLEL%INSERT%' OR UPPER(sql_text) LIKE '%CREATE%TABLE%AS%SELECT%' OR UPPER(sql_text) LIKE '%ALTER%TABLE%EXCHANGE%') AND last_active_time > SYSDATE - :recent_days ORDER BY last_active_time DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Recent direct-path loads or CTAS operations confirm bulk operations that may skip stats tracking"}	{"recent_days": 7}	2026-02-28 12:19:19.580455
