6740	oracle	query	ora_check_index_space_utilization	{"sql": "SELECT owner, segment_name, segment_type, bytes/1024/1024 AS size_mb, blocks, extents FROM dba_segments WHERE segment_type LIKE 'INDEX%' AND bytes > 100*1024*1024 ORDER BY bytes DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Large indexes with high space usage may indicate fragmentation from random inserts"}	\N	2026-02-28 12:19:19.580455
6715	oracle	query	ora_check_stats_preferences	{"sql": "SELECT DBMS_STATS.GET_PREFS('STALE_PERCENT') AS global_stale_pct, DBMS_STATS.GET_PREFS('ESTIMATE_PERCENT') AS global_estimate_pct, DBMS_STATS.GET_PREFS('DEGREE') AS global_degree, DBMS_STATS.GET_PREFS('METHOD_OPT') AS global_method_opt, DBMS_STATS.GET_PREFS('CASCADE') AS global_cascade, DBMS_STATS.GET_PREFS('NO_INVALIDATE') AS global_no_invalidate FROM dual"}	{"condition": "STALE_PERCENT is high (default 10%)", "description": "High stale percentage means Oracle waits for significant data changes before considering stats stale"}	\N	2026-02-28 12:19:19.580455
6717	oracle	query	ora_find_long_running_transactions	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, t.start_time, (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400 AS duration_secs, t.used_ublk AS undo_blocks, t.used_urec AS undo_records FROM v$transaction t JOIN v$session s ON t.ses_addr = s.saddr WHERE (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400 > :min_duration_secs ORDER BY duration_secs DESC"}	{"condition": "row_count > 0", "description": "Long-running transactions prevent undo segment reuse, consuming undo space and risking ORA-01555"}	{"min_duration_secs": 3600}	2026-02-28 12:19:19.580455
6718	oracle	query	ora_check_snapshot_too_old_errors	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-01555%' AND originating_timestamp > SYSDATE - :lookback_days ORDER BY originating_timestamp DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "ORA-01555 errors confirm undo segments being overwritten before long transactions finish reading"}	{"lookback_days": 7}	2026-02-28 12:19:19.580455
6719	oracle	query	ora_check_undo_generation_rate	{"sql": "SELECT TO_CHAR(begin_time, 'YYYY-MM-DD HH24:MI') AS period, undoblks, txncount, maxquerylen, maxconcurrency, unxpstealcnt, expstealcnt FROM v$undostat WHERE begin_time > SYSDATE - 1 ORDER BY begin_time DESC FETCH FIRST 24 ROWS ONLY"}	{"condition": "high undoblks values", "description": "High undo block consumption indicates heavy DML workload generating significant undo"}	\N	2026-02-28 12:19:19.580455
6720	oracle	query	ora_check_undo_tablespace_usage	{"sql": "SELECT tablespace_name, ROUND(SUM(bytes) / 1048576, 2) AS total_mb, ROUND(SUM(CASE WHEN status = 'UNEXPIRED' THEN bytes ELSE 0 END) / 1048576, 2) AS unexpired_mb, ROUND(SUM(CASE WHEN status = 'EXPIRED' THEN bytes ELSE 0 END) / 1048576, 2) AS expired_mb, ROUND(SUM(CASE WHEN status = 'ACTIVE' THEN bytes ELSE 0 END) / 1048576, 2) AS active_mb FROM dba_undo_extents GROUP BY tablespace_name"}	{"condition": "active_mb or unexpired_mb is high relative to total_mb", "description": "High active or unexpired undo usage confirms DML workload is outpacing undo capacity"}	\N	2026-02-28 12:19:19.580455
6722	oracle	query	ora_check_redo_generation_spikes	{"sql": "SELECT TO_CHAR(begin_time, 'YYYY-MM-DD HH24:MI') AS period, undoblks, txncount FROM v$undostat WHERE undoblks > :undo_threshold AND begin_time > SYSDATE - 1 ORDER BY undoblks DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Undo block spikes during bulk insert/delete periods confirm excessive undo generation"}	{"undo_threshold": 10000}	2026-02-28 12:19:19.580455
6725	oracle	query	ora_check_index_split_activity	{"sql": "SELECT name, value FROM v$sysstat WHERE name LIKE '%leaf node splits%' OR name LIKE '%branch node splits%' OR name LIKE '%leaf node 90-10%' ORDER BY name"}	{"condition": "leaf node splits value is high", "description": "High leaf node split counts indicate index fragmentation from non-sequential inserts"}	\N	2026-02-28 12:19:19.580455
6727	oracle	query	ora_analyze_index_space_usage	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.leaf_blocks, i.distinct_keys, i.num_rows AS index_rows, t.num_rows AS table_rows, CASE WHEN t.num_rows > 0 AND i.leaf_blocks > 0 THEN ROUND(i.leaf_blocks * (SELECT value FROM v$parameter WHERE name = 'db_block_size') / 1048576, 2) ELSE 0 END AS index_size_mb FROM dba_indexes i JOIN dba_tables t ON i.table_owner = t.owner AND i.table_name = t.table_name WHERE i.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND i.index_type = 'NORMAL' AND t.num_rows > 10000 ORDER BY i.leaf_blocks DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Large indexes relative to table row count may indicate index bloat from unreclaimed deleted entries"}	\N	2026-02-28 12:19:19.580455
6728	oracle	query	ora_check_index_stats_for_deleted_entries	{"sql": "SELECT owner, index_name, del_lf_rows_len, lf_rows_len, ROUND(del_lf_rows_len / GREATEST(lf_rows_len, 1) * 100, 1) AS pct_deleted FROM index_stats WHERE del_lf_rows_len / GREATEST(lf_rows_len, 1) > :delete_threshold"}	{"condition": "pct_deleted > 20", "description": "High percentage of deleted leaf row space in index confirms bloat from unreclaimed entries"}	{"delete_threshold": 0.2}	2026-02-28 12:19:19.580455
6732	oracle	query	ora_check_row_migration_stats	{"sql": "SELECT name, value FROM v$sysstat WHERE name = 'table fetch continued row'"}	{"condition": "value > :migration_threshold", "description": "High 'table fetch continued row' statistic confirms frequent row migration causing extra I/O"}	{"migration_threshold": 10000}	2026-02-28 12:19:19.580455
6734	oracle	query	ora_find_unused_columns	{"sql": "SELECT owner, table_name, count FROM dba_unused_col_tabs WHERE owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') ORDER BY count DESC"}	{"condition": "row_count > 0", "description": "Tables with unused (marked for drop) columns confirm frequent schema modifications affecting internal structure"}	\N	2026-02-28 12:19:19.580455
6736	oracle	query	ora_check_index_leaf_block_splits	{"sql": "SELECT name, value FROM v$sysstat WHERE name LIKE '%leaf node splits%' OR name LIKE '%branch node splits%'"}	{"condition": "leaf node splits > :split_threshold", "description": "High leaf node split count confirms index fragmentation from DML activity"}	{"split_threshold": 10000}	2026-02-28 12:19:19.580455
6737	oracle	query	ora_check_block_split_statistics	{"sql": "SELECT name, value FROM v$sysstat WHERE name IN ('leaf node splits', 'leaf node 90-10 splits', 'branch node splits', 'root node splits')"}	{"condition": "leaf node splits > 0 AND ratio of 50-50 splits is high", "description": "50-50 leaf node splits (total - 90-10) indicate random inserts causing block splits"}	\N	2026-02-28 12:19:19.580455
6741	oracle	query	ora_analyze_index_leaf_block_splits	{"sql": "SELECT name, value FROM v$sysstat WHERE name LIKE '%leaf node splits%' OR name LIKE '%branch node splits%' OR name LIKE '%leaf node 90-10 splits%'"}	{"condition": "leaf node splits value > leaf node 90-10 splits value * 2", "description": "High ratio of 50-50 splits vs 90-10 splits confirms random key pattern causing fragmentation"}	\N	2026-02-28 12:19:19.580455
