6763	oracle	query	ora_check_segment_allocated_vs_used	{"sql": "SELECT s.owner, s.segment_name, s.segment_type, s.bytes/1024/1024 AS alloc_mb, t.num_rows * t.avg_row_len / 1024 / 1024 AS data_mb, ROUND((1 - (t.num_rows * t.avg_row_len / NULLIF(s.bytes, 0))) * 100, 1) AS waste_pct FROM dba_segments s JOIN dba_tables t ON s.owner = t.owner AND s.segment_name = t.table_name WHERE s.segment_type = 'TABLE' AND s.bytes > 50*1024*1024 AND t.num_rows * t.avg_row_len < s.bytes * 0.3 ORDER BY waste_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Segments with >70% wasted space confirm empty pages from delete operations not reclaimed"}	\N	2026-02-28 12:19:19.580455
