7437	oracle	query	ORA find scheduler jobs with end dates in the past	{"sql": "SELECT owner, job_name, job_type, enabled, state, last_start_date, next_run_date, end_date, run_count, failure_count FROM dba_scheduler_jobs WHERE (end_date < SYSTIMESTAMP AND end_date IS NOT NULL) OR (next_run_date IS NULL AND state = 'COMPLETED') AND owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'EXFSYS') ORDER BY end_date DESC"}	{"condition": "row_count > 0", "description": "Jobs with expired end dates or completed state with no next run confirm expired schedules"}	\N	2026-02-28 12:19:19.580455
7439	oracle	query	ORA find disabled jobs with high failure counts	{"sql": "SELECT owner, job_name, job_type, enabled, state, failure_count, max_failures, last_start_date, last_run_duration FROM dba_scheduler_jobs WHERE (state = 'BROKEN' OR (enabled = 'FALSE' AND failure_count > 0) OR (failure_count >= NVL(max_failures, 999999) AND max_failures IS NOT NULL)) AND owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'EXFSYS') ORDER BY failure_count DESC"}	{"condition": "row_count > 0", "description": "Jobs in BROKEN state or disabled after exceeding max_failures confirm retry limit reached"}	\N	2026-02-28 12:19:19.580455
7440	oracle	query	ORA check recent failure reasons for disabled jobs	{"sql": "SELECT job_name, status, error#, additional_info, TO_CHAR(log_date, 'YYYY-MM-DD HH24:MI:SS') AS log_date FROM dba_scheduler_job_run_details WHERE status = 'FAILED' AND job_name IN (SELECT job_name FROM dba_scheduler_jobs WHERE state = 'BROKEN' OR (enabled = 'FALSE' AND failure_count > 0)) ORDER BY log_date DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Failure history confirms the job was disabled due to repeated failures"}	\N	2026-02-28 12:19:19.580455
