7449	oracle	query	ORA check jobs that missed execution during startup	{"sql": "SELECT owner, job_name, last_start_date, next_run_date, state, failure_count FROM dba_scheduler_jobs WHERE enabled = 'TRUE' AND state = 'SCHEDULED' AND next_run_date < SYSTIMESTAMP AND owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS') ORDER BY next_run_date"}	{"condition": "row_count > 0", "description": "Jobs with past next_run_date that haven't executed may have been blocked during startup"}	\N	2026-02-28 12:19:19.580455
7450	oracle	query	ORA find jobs with missing schedule references	{"sql": "SELECT sj.owner, sj.job_name, sj.schedule_name, sj.schedule_owner, sj.enabled, sj.state FROM dba_scheduler_jobs sj WHERE sj.schedule_name IS NOT NULL AND NOT EXISTS (SELECT 1 FROM dba_scheduler_schedules ss WHERE ss.schedule_name = sj.schedule_name AND ss.owner = sj.schedule_owner) AND sj.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS') ORDER BY sj.owner, sj.job_name"}	{"condition": "row_count > 0", "description": "Jobs referencing nonexistent schedules cannot determine next execution time"}	\N	2026-02-28 12:19:19.580455
