7455	oracle	query	ORA check window group membership for jobs	{"sql": "SELECT sj.owner, sj.job_name, sj.schedule_name, sj.enabled, sj.state, wg.window_name, wg.window_group_name FROM dba_scheduler_jobs sj LEFT JOIN dba_scheduler_wingroup_members wg ON sj.schedule_name = wg.window_group_name WHERE sj.schedule_type = 'WINDOW' OR sj.schedule_type = 'WINDOW_GROUP' AND sj.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS') ORDER BY sj.owner, sj.job_name"}	{"condition": "row_count > 0", "description": "Jobs attached to maintenance windows will only run when the window is open"}	\N	2026-02-28 12:19:19.580455
7456	oracle	query	ORA check database and instance state	{"sql": "SELECT i.instance_name, i.status, i.database_status, i.active_state, i.logins, d.open_mode, d.database_role, d.log_mode FROM v$instance i, v$database d"}	{"condition": "status != 'OPEN' OR logins = 'RESTRICTED' OR active_state != 'NORMAL' OR open_mode != 'READ WRITE'", "description": "Database in restricted mode, suspend, recovery, or read-only prevents job execution"}	\N	2026-02-28 12:19:19.580455
