7482	oracle	query	ora_check_dblink_usage_in_jobs	{"sql": "SELECT p.sql_id, p.operation, p.options, p.object_name, sa.sql_text FROM v$sql_plan p JOIN v$sqlarea sa ON p.sql_id = sa.sql_id WHERE p.operation = 'REMOTE' OR p.object_name LIKE '%@%' OR sa.sql_text LIKE '%@%' ORDER BY sa.elapsed_time DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "SQL using database links (REMOTE operations) are subject to network latency"}	\N	2026-02-28 12:19:19.580455
7465	oracle	query	ORA check for plan changes in recently failed or slow jobs	{"sql": "SELECT job_name, status, error#, EXTRACT(HOUR FROM run_duration) * 3600 + EXTRACT(MINUTE FROM run_duration) * 60 + EXTRACT(SECOND FROM run_duration) AS duration_secs, TO_CHAR(log_date, 'YYYY-MM-DD HH24:MI:SS') AS log_date FROM dba_scheduler_job_run_details WHERE (status = 'FAILED' OR EXTRACT(HOUR FROM run_duration) > :slow_hours) AND log_date > SYSTIMESTAMP - INTERVAL '7' DAY AND owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS') ORDER BY duration_secs DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Recently slow or failed jobs coinciding with stale stats suggest plan regression"}	{"slow_hours": 2}	2026-02-28 12:19:19.580455
7469	oracle	query	ora_check_blocking_session_for_jobs	{"sql": "SELECT w.waiting_session AS job_sid, w.holding_session AS blocker_sid, w.lock_type, w.mode_held, w.mode_requested, sb.username AS blocker_user, sb.program AS blocker_program FROM dba_waiters w JOIN v$session sb ON w.holding_session = sb.sid WHERE w.waiting_session IN (SELECT session_id FROM dba_scheduler_running_jobs)"}	{"condition": "row_count > 0", "description": "Identified blocking sessions preventing scheduler jobs from completing"}	\N	2026-02-28 12:19:19.580455
7470	oracle	query	ora_check_job_deadlock_errors	{"sql": "SELECT log_id, log_date, job_name, status, error#, additional_info FROM dba_scheduler_job_run_details WHERE error# = 60 AND log_date > SYSDATE - :lookback_days ORDER BY log_date DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Scheduler jobs failing with error 60 (ORA-00060 deadlock) confirm deadlock interference"}	{"lookback_days": 7}	2026-02-28 12:19:19.580455
7471	oracle	query	ora_check_job_duration_variance	{"sql": "SELECT job_name, COUNT(*) AS runs, AVG(EXTRACT(SECOND FROM actual_start_date - req_start_date) + EXTRACT(MINUTE FROM actual_start_date - req_start_date) * 60) AS avg_delay_secs, MAX(EXTRACT(SECOND FROM run_duration) + EXTRACT(MINUTE FROM run_duration) * 60 + EXTRACT(HOUR FROM run_duration) * 3600) AS max_duration_secs, MIN(EXTRACT(SECOND FROM run_duration) + EXTRACT(MINUTE FROM run_duration) * 60 + EXTRACT(HOUR FROM run_duration) * 3600) AS min_duration_secs FROM dba_scheduler_job_run_details WHERE log_date > SYSDATE - :lookback_days GROUP BY job_name HAVING MAX(EXTRACT(SECOND FROM run_duration) + EXTRACT(MINUTE FROM run_duration) * 60 + EXTRACT(HOUR FROM run_duration) * 3600) > 3 * MIN(EXTRACT(SECOND FROM run_duration) + EXTRACT(MINUTE FROM run_duration) * 60 + EXTRACT(HOUR FROM run_duration) * 3600) ORDER BY max_duration_secs DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Jobs with high duration variance (max > 3x min) suggest intermittent contention from deadlock retries"}	{"lookback_days": 7}	2026-02-28 12:19:19.580455
7473	oracle	query	ora_check_temp_tablespace_usage_during_jobs	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, su.tablespace, su.blocks * (SELECT value FROM v$parameter WHERE name = 'db_block_size') / 1048576 AS temp_usage_mb FROM v$sort_usage su JOIN v$session s ON su.session_addr = s.saddr WHERE s.program LIKE '%J0%' OR s.sid IN (SELECT session_id FROM dba_scheduler_running_jobs) ORDER BY temp_usage_mb DESC"}	{"condition": "row_count > 0 AND temp_usage_mb is significant", "description": "Scheduler job sessions consuming significant temp space confirm sort/hash spill from insufficient PGA"}	\N	2026-02-28 12:19:19.580455
7474	oracle	query	ora_check_cpu_wait_for_jobs	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.event, s.wait_class, s.seconds_in_wait FROM v$session s WHERE s.wait_class = 'Scheduler' OR s.event LIKE 'resmgr%' AND s.sid IN (SELECT session_id FROM dba_scheduler_running_jobs)"}	{"condition": "row_count > 0", "description": "Sessions waiting on Resource Manager or Scheduler events indicate CPU throttling"}	\N	2026-02-28 12:19:19.580455
7477	oracle	query	ora_check_io_intensive_job_sqls	{"sql": "SELECT sa.sql_id, sa.sql_text, sa.disk_reads, sa.buffer_gets, sa.executions, sa.elapsed_time / 1000000 AS elapsed_secs FROM v$sqlarea sa WHERE sa.sql_id IN (SELECT s.sql_id FROM v$session s WHERE s.sid IN (SELECT session_id FROM dba_scheduler_running_jobs)) ORDER BY sa.disk_reads DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0 AND disk_reads is high", "description": "High disk reads for SQL executed by scheduler jobs confirms I/O-bound batch processing"}	\N	2026-02-28 12:19:19.580455
7478	oracle	query	ora_find_job_sqls_with_full_scans	{"sql": "SELECT p.sql_id, p.object_name, p.operation, p.options, sa.sql_text, sa.executions, sa.buffer_gets, sa.disk_reads FROM v$sql_plan p JOIN v$sqlarea sa ON p.sql_id = sa.sql_id WHERE p.operation = 'TABLE ACCESS' AND p.options = 'FULL' AND sa.parsing_schema_name NOT IN ('SYS','SYSTEM') AND sa.buffer_gets / GREATEST(sa.executions, 1) > :buffer_threshold ORDER BY sa.buffer_gets DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "SQL with full table scans and high buffer gets per execution are candidates for index optimization"}	{"buffer_threshold": 50000}	2026-02-28 12:19:19.580455
7480	oracle	query	ora_check_sql_with_filter_no_index	{"sql": "SELECT p.sql_id, p.object_name, p.filter_predicates, p.access_predicates, sa.buffer_gets / GREATEST(sa.executions, 1) AS gets_per_exec, sa.disk_reads / GREATEST(sa.executions, 1) AS reads_per_exec FROM v$sql_plan p JOIN v$sqlarea sa ON p.sql_id = sa.sql_id WHERE p.operation = 'TABLE ACCESS' AND p.options = 'FULL' AND p.filter_predicates IS NOT NULL AND sa.buffer_gets / GREATEST(sa.executions, 1) > :min_gets AND sa.parsing_schema_name NOT IN ('SYS','SYSTEM') ORDER BY gets_per_exec DESC FETCH FIRST 15 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Full table scans with filter predicates indicate missing indexes on the filtered columns"}	{"min_gets": 10000}	2026-02-28 12:19:19.580455
7485	oracle	query	ora_check_stats_lock_contention	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.event, s.seconds_in_wait FROM v$session s WHERE s.program LIKE '%eAGT%' OR s.module LIKE '%DBMS_STATS%' AND s.status = 'ACTIVE'"}	{"condition": "row_count > 0", "description": "Active DBMS_STATS sessions confirm statistics gathering running alongside user jobs"}	\N	2026-02-28 12:19:19.580455
7487	oracle	query	ora_check_temp_segment_consumers	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, su.tablespace, su.blocks * (SELECT value FROM v$parameter WHERE name = 'db_block_size') / 1048576 AS temp_mb, su.segtype FROM v$sort_usage su JOIN v$session s ON su.session_addr = s.saddr ORDER BY temp_mb DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Sessions consuming significant temp space — check if scheduler jobs are the largest consumers"}	\N	2026-02-28 12:19:19.580455
7491	oracle	query	ora_check_plan_cardinality_misestimate	{"sql": "SELECT sql_id, plan_hash_value, id, operation, options, object_name, cardinality AS estimated_rows, bytes FROM v$sql_plan WHERE sql_id IN (SELECT sql_id FROM v$sqlarea WHERE elapsed_time / GREATEST(executions, 1) > :min_elapsed_per_exec AND parsing_schema_name NOT IN ('SYS','SYSTEM')) AND operation LIKE '%JOIN%' ORDER BY sql_id, id"}	{"condition": "row_count > 0", "description": "Join operations with potentially misestimated cardinality confirm suboptimal join ordering"}	{"min_elapsed_per_exec": 60000000}	2026-02-28 12:19:19.580455
