7493	oracle	query	ora_check_utl_http_usage	{"sql": "SELECT sql_id, sql_text FROM v$sql WHERE UPPER(sql_text) LIKE '%UTL_HTTP%' OR UPPER(sql_text) LIKE '%UTL_TCP%' OR UPPER(sql_text) LIKE '%HTTPURITYPE%' FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "SQL using UTL_HTTP or UTL_TCP makes external calls subject to network and API latency"}	\N	2026-02-28 12:19:19.580455
7494	oracle	query	ora_check_job_schedules	{"sql": "SELECT owner, job_name, repeat_interval, start_date, next_run_date, enabled, job_class, schedule_name FROM dba_scheduler_jobs WHERE enabled = 'TRUE' AND owner NOT IN ('SYS','SYSTEM','DBSNMP','ORACLE_OCM') ORDER BY next_run_date"}	{"condition": "row_count > 0", "description": "Review scheduled job start times to identify jobs running during business hours"}	\N	2026-02-28 12:19:19.580455
7496	oracle	query	ora_check_job_duration_vs_window	{"sql": "SELECT jrd.job_name, jrd.actual_start_date, jrd.run_duration, jrd.status, j.schedule_name, j.max_run_duration FROM dba_scheduler_job_run_details jrd JOIN dba_scheduler_jobs j ON jrd.job_name = j.job_name AND jrd.owner = j.owner WHERE jrd.log_date > SYSDATE - :lookback_days AND jrd.owner NOT IN ('SYS','SYSTEM','DBSNMP') AND jrd.run_duration > j.max_run_duration AND j.max_run_duration IS NOT NULL ORDER BY jrd.run_duration DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Jobs exceeding MAX_RUN_DURATION confirm runtime overflows that may overlap with business hours"}	{"lookback_days": 7}	2026-02-28 12:19:19.580455
7497	oracle	query	ora_check_long_running_job_history	{"sql": "SELECT job_name, actual_start_date, run_duration, status FROM dba_scheduler_job_run_details WHERE owner NOT IN ('SYS','SYSTEM','DBSNMP') AND log_date > SYSDATE - :lookback_days AND EXTRACT(HOUR FROM run_duration) * 3600 + EXTRACT(MINUTE FROM run_duration) * 60 + EXTRACT(SECOND FROM run_duration) > :max_duration_secs ORDER BY run_duration DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Jobs with excessively long runtimes are likely overflowing their maintenance windows"}	{"lookback_days": 7, "max_duration_secs": 14400}	2026-02-28 12:19:19.580455
7499	oracle	query	ora_check_job_time_zone_settings	{"sql": "SELECT owner, job_name, start_date, repeat_interval, next_run_date, EXTRACT(TIMEZONE_HOUR FROM start_date) AS tz_hour, EXTRACT(TIMEZONE_MINUTE FROM start_date) AS tz_min FROM dba_scheduler_jobs WHERE enabled = 'TRUE' AND owner NOT IN ('SYS','SYSTEM','DBSNMP') ORDER BY next_run_date"}	{"condition": "row_count > 0", "description": "Review job start_date timezone components for mismatches with expected local time"}	\N	2026-02-28 12:19:19.580455
7500	oracle	query	ora_check_job_retry_configuration	{"sql": "SELECT owner, job_name, max_failures, failure_count, restart_on_failure, retry_count FROM dba_scheduler_jobs WHERE enabled = 'TRUE' AND (max_failures > 1 OR restart_on_failure = 'TRUE') AND owner NOT IN ('SYS','SYSTEM','DBSNMP') ORDER BY failure_count DESC"}	{"condition": "row_count > 0", "description": "Jobs with retry/restart configuration may re-execute during peak hours after overnight failures"}	\N	2026-02-28 12:19:19.580455
9015	oracle	query	Oracle find Oracle-maintained accounts in OPEN status	{"sql": "SELECT username, account_status, profile, TO_CHAR(created, 'YYYY-MM-DD') AS created, default_tablespace, oracle_maintained FROM dba_users WHERE oracle_maintained = 'Y' AND account_status = 'OPEN' AND username NOT IN ('SYS', 'SYSTEM') ORDER BY username"}	{"condition": "row_count > :threshold", "description": "Multiple Oracle-maintained internal accounts left unlocked — likely not understanding which accounts are needed"}	{"threshold": 5}	2026-02-28 12:19:19.580455
7501	oracle	query	ora_check_failed_job_retries_in_business_hours	{"sql": "SELECT job_name, actual_start_date, status, error#, additional_info FROM dba_scheduler_job_run_details WHERE status = 'FAILED' AND EXTRACT(HOUR FROM actual_start_date) BETWEEN :biz_start AND :biz_end AND log_date > SYSDATE - :lookback_days AND owner NOT IN ('SYS','SYSTEM','DBSNMP') ORDER BY actual_start_date DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Failed job retries executing during business hours confirm retry-induced peak-hour activity"}	{"biz_end": 18, "biz_start": 8, "lookback_days": 7}	2026-02-28 12:19:19.580455
7503	oracle	query	ora_check_recently_modified_job_schedules	{"sql": "SELECT owner, job_name, start_date, repeat_interval, last_start_date, next_run_date, comments FROM dba_scheduler_jobs WHERE enabled = 'TRUE' AND owner NOT IN ('SYS','SYSTEM','DBSNMP','ORACLE_OCM') ORDER BY last_start_date DESC NULLS LAST FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Review active job schedules for recent changes — comments field may indicate undocumented modifications"}	\N	2026-02-28 12:19:19.580455
7504	oracle	query	ora_check_scheduler_audit_trail	{"sql": "SELECT log_id, log_date, job_name, operation, status, additional_info FROM dba_scheduler_job_log WHERE operation IN ('MODIFY', 'CREATE', 'ALTER') AND log_date > SYSDATE - :lookback_days ORDER BY log_date DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Recent MODIFY/ALTER operations on scheduler jobs confirm schedule changes"}	{"lookback_days": 30}	2026-02-28 12:19:19.580455
7505	oracle	query	ora_check_job_start_time_drift	{"sql": "SELECT job_name, req_start_date, actual_start_date, EXTRACT(SECOND FROM (actual_start_date - req_start_date)) + EXTRACT(MINUTE FROM (actual_start_date - req_start_date)) * 60 AS drift_seconds, status FROM dba_scheduler_job_run_details WHERE log_date > SYSDATE - :lookback_days AND owner NOT IN ('SYS','SYSTEM','DBSNMP') AND ABS(EXTRACT(SECOND FROM (actual_start_date - req_start_date)) + EXTRACT(MINUTE FROM (actual_start_date - req_start_date)) * 60) > :max_drift_secs ORDER BY ABS(drift_seconds) DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Jobs with significant drift between requested and actual start time indicate timing issues"}	{"lookback_days": 7, "max_drift_secs": 300}	2026-02-28 12:19:19.580455
