7561	oracle	query	ora-check-tablespace-free-space-pct	{"sql": "SELECT df.tablespace_name, ROUND(df.total_mb, 1) AS total_mb, ROUND(df.total_mb - NVL(fs.free_mb, 0), 1) AS used_mb, ROUND(NVL(fs.free_mb, 0), 1) AS free_mb, ROUND((df.total_mb - NVL(fs.free_mb, 0)) / df.total_mb * 100, 1) AS pct_used FROM (SELECT tablespace_name, SUM(bytes) / 1024 / 1024 AS total_mb FROM dba_data_files GROUP BY tablespace_name) df LEFT JOIN (SELECT tablespace_name, SUM(bytes) / 1024 / 1024 AS free_mb FROM dba_free_space GROUP BY tablespace_name) fs ON df.tablespace_name = fs.tablespace_name WHERE (df.total_mb - NVL(fs.free_mb, 0)) / df.total_mb * 100 > :threshold_pct ORDER BY pct_used DESC"}	{"condition": "row_count > 0", "description": "Tablespaces exceeding usage threshold — insufficient space allocated"}	{"threshold_pct": 85}	2026-02-28 12:19:19.580455
