8180	oracle	query	ORA find parallel plans with hash group by operations	{"sql": "SELECT sp.sql_id, sp.plan_hash_value, sp.operation, sp.options, sp.other_tag, sq.executions, ROUND(sq.elapsed_time / NULLIF(sq.executions, 0) / 1000000, 2) AS avg_secs FROM v$sql_plan sp JOIN v$sql sq ON sp.sql_id = sq.sql_id AND sp.plan_hash_value = sq.plan_hash_value WHERE sp.operation = 'HASH' AND sp.options = 'GROUP BY' AND sp.other_tag LIKE '%P->%' AND sq.px_servers_executions > 0 ORDER BY sq.elapsed_time DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Parallel hash group by operations are candidates for distribution skew"}	\N	2026-02-28 12:19:19.580455
8182	oracle	query	ORA check PX coordinator wait events	{"sql": "SELECT event, total_waits, ROUND(time_waited_micro / 1000000, 2) AS time_waited_secs, ROUND(time_waited_micro / NULLIF(total_waits, 0) / 1000, 2) AS avg_wait_ms FROM v$system_event WHERE event LIKE 'PX%' ORDER BY time_waited_micro DESC"}	{"condition": "time_waited_secs > :px_wait_threshold", "description": "High PX coordinator wait times indicate overhead from merging parallel worker results"}	{"px_wait_threshold": 10}	2026-02-28 12:19:19.580455
8183	oracle	query	ORA check OS CPU and context switch statistics	{"sql": "SELECT stat_name, value FROM v$osstat WHERE stat_name IN ('NUM_CPUS', 'NUM_CPU_CORES', 'BUSY_TIME', 'IDLE_TIME', 'SYS_TIME', 'USER_TIME') ORDER BY stat_name"}	{"condition": "SYS_TIME / (SYS_TIME + USER_TIME) > :sys_ratio", "description": "High system time ratio relative to user time indicates excessive context switching"}	{"sys_ratio": 0.3}	2026-02-28 12:19:19.580455
