8186	oracle	query	ORA check direct path read wait times for parallel scans	{"sql": "SELECT event, total_waits, ROUND(time_waited_micro / 1000000, 2) AS time_waited_secs, ROUND(time_waited_micro / NULLIF(total_waits, 0) / 1000, 2) AS avg_wait_ms FROM v$system_event WHERE event IN ('direct path read', 'direct path read temp', 'cell smart table scan') ORDER BY time_waited_micro DESC"}	{"condition": "avg_wait_ms > :io_threshold", "description": "High average direct path read wait indicates I/O subsystem not keeping up with parallel demand"}	{"io_threshold": 10}	2026-02-28 12:19:19.580455
8187	oracle	query	ORA find parallel plans with nested loops	{"sql": "SELECT sp.sql_id, sp.plan_hash_value, sp.operation, sp.options, sp.cardinality AS estimated_rows, sp.cost, sq.executions, ROUND(sq.elapsed_time / NULLIF(sq.executions, 0) / 1000000, 2) AS avg_secs FROM v$sql_plan sp JOIN v$sql sq ON sp.sql_id = sq.sql_id AND sp.plan_hash_value = sq.plan_hash_value WHERE sp.operation = 'NESTED LOOPS' AND sp.other_tag LIKE '%P->%' AND sp.cardinality > :cardinality_threshold ORDER BY sp.cardinality DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "cardinality > :cardinality_threshold", "description": "Parallel nested loop with high cardinality indicates excessive inner loop iterations"}	{"cardinality_threshold": 10000}	2026-02-28 12:19:19.580455
8188	oracle	query	ORA check parallel DML execution in recent SQL	{"sql": "SELECT sq.sql_id, SUBSTR(sq.sql_text, 1, 100) AS sql_preview, sq.executions, sq.px_servers_executions, ROUND(sq.elapsed_time / NULLIF(sq.executions, 0) / 1000000, 2) AS avg_secs, sq.rows_processed FROM v$sql sq WHERE sq.px_servers_executions > 0 AND (UPPER(sq.sql_text) LIKE 'INSERT%' OR UPPER(sq.sql_text) LIKE 'UPDATE%' OR UPPER(sq.sql_text) LIKE 'DELETE%' OR UPPER(sq.sql_text) LIKE 'MERGE%') ORDER BY sq.elapsed_time DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Parallel DML operations identified with potential coordination overhead"}	\N	2026-02-28 12:19:19.580455
