8458	oracle	query	ora-long-txn-lock: find long-running transactions holding locks	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, t.start_time, ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 24 * 60, 1) AS duration_minutes, (SELECT COUNT(*) FROM v$lock l WHERE l.sid = s.sid AND l.type = 'TX') AS tx_lock_count FROM v$transaction t JOIN v$session s ON s.saddr = t.ses_addr WHERE (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 24 * 60 > :threshold_minutes ORDER BY duration_minutes DESC"}	{"condition": "row_count > 0", "description": "Long-running transactions holding locks cause blocking"}	{"threshold_minutes": 10}	2026-02-28 12:19:19.580455
8459	oracle	query	ora-long-txn-lock: check blocked sessions count	{"sql": "SELECT blocking_session AS blocker_sid, COUNT(*) AS blocked_count, MAX(seconds_in_wait) AS max_wait_secs FROM v$session WHERE blocking_session IS NOT NULL GROUP BY blocking_session HAVING COUNT(*) > :threshold_blocked ORDER BY blocked_count DESC"}	{"condition": "row_count > 0", "description": "Sessions blocking multiple others confirms long transaction lock contention"}	{"threshold_blocked": 2}	2026-02-28 12:19:19.580455
8460	oracle	query	ora-lock-escalation: find table-level locks	{"sql": "SELECT l.sid, s.username, s.program, o.object_name, o.object_type, l.type, DECODE(l.lmode, 0, 'None', 1, 'Null', 2, 'Row-S (SS)', 3, 'Row-X (SX)', 4, 'Share', 5, 'S/Row-X (SSX)', 6, 'Exclusive') AS lock_mode, DECODE(l.request, 0, 'None', 1, 'Null', 2, 'Row-S', 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS request_mode FROM v$lock l JOIN v$session s ON s.sid = l.sid JOIN dba_objects o ON o.object_id = l.id1 WHERE l.type = 'TM' AND l.lmode >= 4 ORDER BY l.lmode DESC"}	{"condition": "row_count > 0", "description": "Table-level Share or Exclusive locks indicate lock escalation beyond row-level"}	\N	2026-02-28 12:19:19.580455
8461	oracle	query	ora-lock-escalation: check for LOCK TABLE statements in SQL	{"sql": "SELECT sql_id, executions, SUBSTR(sql_text, 1, 200) AS sql_text FROM v$sqlarea WHERE UPPER(sql_text) LIKE '%LOCK TABLE%' AND parsing_schema_name NOT IN ('SYS', 'SYSTEM') AND last_active_time > SYSDATE - 7 ORDER BY executions DESC"}	{"condition": "row_count > 0", "description": "Explicit LOCK TABLE statements confirm intentional lock escalation"}	\N	2026-02-28 12:19:19.580455
8464	oracle	query	ora-mixed-lock-modes: find sessions with explicit table locks	{"sql": "SELECT l.sid, s.username, s.program, o.object_name, DECODE(l.lmode, 2, 'Row-S', 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS held_mode, DECODE(l.request, 0, 'None', 2, 'Row-S', 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS requested_mode FROM v$lock l JOIN v$session s ON s.sid = l.sid JOIN dba_objects o ON o.object_id = l.id1 WHERE l.type = 'TM' AND (l.lmode >= 4 OR l.request >= 4) ORDER BY l.lmode DESC, o.object_name"}	{"condition": "row_count > 0", "description": "Sessions holding or requesting Share/Exclusive table locks indicate mixed lock mode usage"}	\N	2026-02-28 12:19:19.580455
8465	oracle	query	ora-index-deadlock: check for ITL-related waits	{"sql": "SELECT event, total_waits, time_waited, average_wait FROM v$system_event WHERE event LIKE '%enq: TX - allocate ITL entry%' OR event LIKE '%enq: TX - index contention%' OR event LIKE '%enq: TX - row lock contention%' ORDER BY time_waited DESC"}	{"condition": "row_count > 0", "description": "TX enqueue waits for index contention or ITL entry indicate index-level lock issues"}	\N	2026-02-28 12:19:19.580455
8466	oracle	query	ora-index-deadlock: check deadlock trace files	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-00060%' AND originating_timestamp > SYSTIMESTAMP - INTERVAL '7' DAY ORDER BY originating_timestamp DESC"}	{"condition": "row_count > 0", "description": "Deadlock events combined with index contention waits confirm index-based deadlocks"}	\N	2026-02-28 12:19:19.580455
8467	oracle	query	ora-uk-pk-lock-contention: check for TX row lock contention	{"sql": "SELECT event, total_waits, time_waited, ROUND(average_wait, 4) AS avg_wait_secs FROM v$system_event WHERE event = 'enq: TX - row lock contention' AND total_waits > :threshold_waits ORDER BY time_waited DESC"}	{"condition": "row_count > 0", "description": "TX row lock contention can indicate unique key constraint conflicts"}	{"threshold_waits": 100}	2026-02-28 12:19:19.580455
8468	oracle	query	ora-uk-pk-lock-contention: find sessions waiting on unique constraint	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.event, s.p1text, s.p2text, s.p3text, s.seconds_in_wait, s.sql_id FROM v$session s WHERE s.event = 'enq: TX - row lock contention' AND s.state = 'WAITING' ORDER BY s.seconds_in_wait DESC"}	{"condition": "row_count > 0", "description": "Sessions currently waiting on TX row lock contention confirm unique key enforcement blocking"}	\N	2026-02-28 12:19:19.580455
8469	oracle	query	ora-pq-lock-contention: check for PX-related lock waits	{"sql": "SELECT event, total_waits, time_waited, average_wait FROM v$system_event WHERE (event LIKE 'PX%' OR event LIKE '%parallel%' OR event = 'enq: PS - contention') AND total_waits > :threshold_waits ORDER BY time_waited DESC"}	{"condition": "row_count > 0", "description": "PX-related wait events indicate parallel execution lock contention"}	{"threshold_waits": 100}	2026-02-28 12:19:19.580455
8470	oracle	query	ora-pq-lock-contention: check parallel DML lock issues	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.event, s.seconds_in_wait FROM v$session s WHERE s.event LIKE '%PX%' OR s.event = 'enq: TM - contention' AND EXISTS (SELECT 1 FROM v$px_session px WHERE px.sid = s.sid) ORDER BY s.seconds_in_wait DESC"}	{"condition": "row_count > 0", "description": "PX sessions experiencing lock contention confirm parallel execution causing blocking"}	\N	2026-02-28 12:19:19.580455
8471	oracle	query	ora-bitmap-index-contention: find bitmap indexes on DML-heavy tables	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.index_type, t.num_rows, ROUND(s.bytes / 1048576, 1) AS index_mb FROM dba_indexes i JOIN dba_tables t ON t.owner = i.table_owner AND t.table_name = i.table_name LEFT JOIN dba_segments s ON s.owner = i.owner AND s.segment_name = i.index_name WHERE i.index_type = 'BITMAP' AND i.owner NOT IN ('SYS', 'SYSTEM') ORDER BY t.num_rows DESC"}	{"condition": "row_count > 0", "description": "Bitmap indexes on OLTP tables cause severe DML contention"}	\N	2026-02-28 12:19:19.580455
8472	oracle	query	ora-bitmap-index-contention: check for TX contention from bitmap locks	{"sql": "SELECT event, total_waits, time_waited FROM v$system_event WHERE event = 'enq: TX - row lock contention' AND total_waits > :threshold_waits ORDER BY time_waited DESC"}	{"condition": "row_count > 0", "description": "TX row lock contention combined with bitmap indexes confirms bitmap-induced blocking"}	{"threshold_waits": 500}	2026-02-28 12:19:19.580455
8476	oracle	query	ora-serializable-lock: check for ORA-08177 serialization failures	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-08177%' AND originating_timestamp > SYSTIMESTAMP - INTERVAL '7' DAY ORDER BY originating_timestamp DESC"}	{"condition": "row_count > 0", "description": "ORA-08177 serialization failure errors confirm SERIALIZABLE isolation causing contention"}	\N	2026-02-28 12:19:19.580455
8477	oracle	query	ORA find transactions with multiple active SQL on same objects	{"sql": "SELECT l.sid, s.username, s.program, COUNT(DISTINCT l.id1) AS locked_objects, COUNT(*) AS total_locks, DECODE(MAX(l.lmode), 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive', 'Other') AS max_lock_mode FROM v$lock l JOIN v$session s ON l.sid = s.sid WHERE l.type = 'TM' AND s.type = 'USER' GROUP BY l.sid, s.username, s.program HAVING COUNT(DISTINCT l.id1) > 1 ORDER BY total_locks DESC"}	{"condition": "row_count > 0", "description": "Sessions with TM locks on multiple objects indicate UPDATE operations within same transaction on different tables"}	\N	2026-02-28 12:19:19.580455
8479	oracle	query	ORA check deadlock frequency in recent period	{"sql": "SELECT TO_CHAR(originating_timestamp, 'YYYY-MM-DD HH24') AS deadlock_hour, COUNT(*) AS deadlock_count FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-00060%' AND originating_timestamp > SYSTIMESTAMP - INTERVAL '7' DAY GROUP BY TO_CHAR(originating_timestamp, 'YYYY-MM-DD HH24') ORDER BY deadlock_hour DESC"}	{"condition": "sum(deadlock_count) > :min_deadlocks", "description": "Repeated deadlocks without reduction over time suggest applications are not retrying properly"}	{"min_deadlocks": 10}	2026-02-28 12:19:19.580455
8480	oracle	query	ORA check if same SQL IDs appear in repeated deadlocks	{"sql": "SELECT ash.sql_id, COUNT(*) AS deadlock_samples, sq.sql_text FROM v$active_session_history ash LEFT JOIN v$sql sq ON ash.sql_id = sq.sql_id WHERE ash.event = 'enq: TX - row lock contention' AND ash.sample_time > SYSTIMESTAMP - INTERVAL '7' DAY GROUP BY ash.sql_id, sq.sql_text HAVING COUNT(*) > :repeat_threshold ORDER BY deadlock_samples DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Same SQL IDs repeatedly involved in lock contention confirm missing retry/rollback handling"}	{"repeat_threshold": 5}	2026-02-28 12:19:19.580455
8481	oracle	query	ORA check for exclusive TM locks on tables	{"sql": "SELECT o.owner, o.object_name, o.object_type, l.sid, s.username, s.program, DECODE(l.lmode, 2, 'Row-S', 3, 'Row-X', 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS lock_mode, l.ctime AS lock_hold_secs FROM v$lock l JOIN dba_objects o ON l.id1 = o.object_id JOIN v$session s ON l.sid = s.sid WHERE l.type = 'TM' AND l.lmode >= 4 ORDER BY l.ctime DESC"}	{"condition": "row_count > 0", "description": "Share or higher TM locks indicate table-level locking beyond normal row-level DML"}	\N	2026-02-28 12:19:19.580455
8483	oracle	query	ORA find blocking sessions and their waiters	{"sql": "SELECT s.sid AS blocking_sid, s.serial# AS blocking_serial, s.username AS blocking_user, s.program AS blocking_program, s.status AS blocking_status, s.last_call_et AS blocking_idle_secs, w.sid AS waiting_sid, w.username AS waiting_user, w.event AS wait_event, w.seconds_in_wait FROM v$session s JOIN v$session w ON s.sid = w.blocking_session WHERE w.blocking_session IS NOT NULL ORDER BY w.seconds_in_wait DESC"}	{"condition": "row_count > 0", "description": "Active blocking chains confirm sessions holding locks preventing others from proceeding"}	\N	2026-02-28 12:19:19.580455
8484	oracle	query	ORA check SQL of blocking sessions	{"sql": "SELECT s.sid, s.sql_id, sq.sql_text, s.last_call_et AS idle_secs FROM v$session s LEFT JOIN v$sql sq ON s.sql_id = sq.sql_id AND s.sql_child_number = sq.child_number WHERE s.sid IN (SELECT DISTINCT blocking_session FROM v$session WHERE blocking_session IS NOT NULL) ORDER BY s.last_call_et DESC"}	{"condition": "row_count > 0", "description": "SQL of blocking sessions shows the uncommitted operation holding locks"}	\N	2026-02-28 12:19:19.580455
8485	oracle	query	ORA find active queries with full table scan plans	{"sql": "SELECT sp.sql_id, sp.object_name, sp.operation, sp.options, sp.cost, sp.cardinality, sq.executions, ROUND(sq.elapsed_time / NULLIF(sq.executions, 0) / 1000000, 2) AS avg_secs FROM v$sql_plan sp JOIN v$sql sq ON sp.sql_id = sq.sql_id WHERE sp.operation = 'TABLE ACCESS' AND sp.options = 'FULL' AND sp.sql_id IN (SELECT sql_id FROM v$session WHERE status = 'ACTIVE' AND type = 'USER') AND sp.object_name IS NOT NULL ORDER BY sp.cost DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Active queries with full table scans lock more rows than necessary"}	\N	2026-02-28 12:19:19.580455
8486	oracle	query	ORA check concurrent lock waits on scanned tables	{"sql": "SELECT event, total_waits, ROUND(time_waited_micro / 1000000, 2) AS time_waited_secs FROM v$system_event WHERE event = 'enq: TX - row lock contention' AND total_waits > 0"}	{"condition": "total_waits > :wait_threshold", "description": "Row lock contention confirms full scans are blocking concurrent row access"}	{"wait_threshold": 100}	2026-02-28 12:19:19.580455
8487	oracle	query	ORA find DML with full table scans in active sessions	{"sql": "SELECT sp.sql_id, sp.object_name, sp.operation, sp.options, sq.sql_text FROM v$sql_plan sp JOIN v$sql sq ON sp.sql_id = sq.sql_id WHERE sp.operation = 'TABLE ACCESS' AND sp.options = 'FULL' AND (UPPER(sq.sql_text) LIKE 'UPDATE%' OR UPPER(sq.sql_text) LIKE 'DELETE%') AND sp.sql_id IN (SELECT sql_id FROM v$session WHERE status = 'ACTIVE') ORDER BY sp.cost DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "DML statements with full table scans indicate missing indexes on filter columns"}	\N	2026-02-28 12:19:19.580455
8488	oracle	query	ORA find high-row-count DML in active transactions	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.sql_id, sq.rows_processed, sq.sql_text, t.used_ublk AS undo_blocks, ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400) AS txn_age_secs FROM v$session s JOIN v$transaction t ON s.saddr = t.ses_addr LEFT JOIN v$sql sq ON s.sql_id = sq.sql_id WHERE t.used_ublk > :undo_threshold ORDER BY t.used_ublk DESC"}	{"condition": "undo_blocks > :undo_threshold", "description": "Large undo block usage indicates bulk DML modifying many rows with extended lock hold time"}	{"undo_threshold": 10000}	2026-02-28 12:19:19.580455
8489	oracle	query	ORA find exclusive or share TM locks	{"sql": "SELECT o.owner, o.object_name, l.sid, s.username, s.program, DECODE(l.lmode, 4, 'Share', 5, 'S/Row-X', 6, 'Exclusive') AS lock_mode, l.ctime AS hold_secs FROM v$lock l JOIN dba_objects o ON l.id1 = o.object_id JOIN v$session s ON l.sid = s.sid WHERE l.type = 'TM' AND l.lmode >= 4 ORDER BY l.ctime DESC"}	{"condition": "row_count > 0", "description": "Share or Exclusive TM locks block all DML on the table"}	\N	2026-02-28 12:19:19.580455
9392	oracle	query	ora_check_scheduler_suspicious_jobs	{"sql": "SELECT owner, job_name, program_name, job_type, job_action, enabled, auto_drop FROM dba_scheduler_jobs WHERE owner NOT IN ('SYS','SYSTEM','DBSNMP','ORACLE_OCM') AND enabled = 'TRUE' AND (job_type = 'EXECUTABLE' OR UPPER(job_action) LIKE '%UTL_HTTP%' OR UPPER(job_action) LIKE '%UTL_TCP%' OR UPPER(job_action) LIKE '%DBMS_JAVA%') ORDER BY owner, job_name"}	{"condition": "row_count > 0", "description": "Scheduler jobs executing OS commands or making network calls could be persistence mechanisms"}	\N	2026-02-28 12:19:19.580455
8491	oracle	query	ORA find idle sessions with open transactions and locks	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.status, s.last_call_et AS idle_secs, t.start_time, (SELECT COUNT(*) FROM v$lock l WHERE l.sid = s.sid AND l.type IN ('TX', 'TM')) AS lock_count FROM v$session s JOIN v$transaction t ON s.saddr = t.ses_addr WHERE s.status = 'INACTIVE' AND s.last_call_et > :idle_threshold ORDER BY s.last_call_et DESC"}	{"condition": "row_count > 0 AND lock_count > 0", "description": "Idle sessions with open transactions holding locks confirm idle-in-transaction pattern"}	{"idle_threshold": 300}	2026-02-28 12:19:19.580455
8492	oracle	query	ORA check deadlock frequency in recent period [PERF-SQL-LC-002-RC07]	{"sql": "SELECT COUNT(*) AS deadlock_count, TO_CHAR(MIN(originating_timestamp), 'YYYY-MM-DD HH24:MI:SS') AS first_deadlock, TO_CHAR(MAX(originating_timestamp), 'YYYY-MM-DD HH24:MI:SS') AS last_deadlock FROM v$diag_alert_ext WHERE message_text LIKE '%ORA-00060%' AND originating_timestamp > SYSTIMESTAMP - INTERVAL '24' HOUR"}	{"condition": "deadlock_count > :frequency_threshold", "description": "High deadlock frequency means Oracle spends significant resources detecting and resolving deadlocks"}	{"frequency_threshold": 50}	2026-02-28 12:19:19.580455
8493	oracle	query	ORA check buffer busy waits and ITL contention	{"sql": "SELECT event, total_waits, ROUND(time_waited_micro / 1000000, 2) AS time_waited_secs, ROUND(time_waited_micro / NULLIF(total_waits, 0) / 1000, 2) AS avg_wait_ms FROM v$system_event WHERE event IN ('buffer busy waits', 'enq: TX - allocate ITL entry', 'enq: TX - index contention') ORDER BY time_waited_micro DESC"}	{"condition": "total_waits > :contention_threshold", "description": "Buffer busy waits or ITL contention indicate hot block from sequential inserts"}	{"contention_threshold": 1000}	2026-02-28 12:19:19.580455
8495	oracle	query	ORA check library cache and row cache lock waits	{"sql": "SELECT event, total_waits, ROUND(time_waited_micro / 1000000, 2) AS time_waited_secs, ROUND(time_waited_micro / NULLIF(total_waits, 0) / 1000, 2) AS avg_wait_ms FROM v$system_event WHERE event IN ('library cache lock', 'library cache pin', 'row cache lock', 'enq: TM - contention') ORDER BY time_waited_micro DESC"}	{"condition": "total_waits > :wait_threshold", "description": "Library cache or row cache lock waits indicate DDL blocking concurrent operations"}	{"wait_threshold": 100}	2026-02-28 12:19:19.580455
8510	oracle	query	ora_find_tm_lock_sources	{"sql": "SELECT l.sid, l.type, l.lmode, l.request, o.object_name, o.object_type, s.username, s.program FROM v$lock l JOIN v$locked_object lo ON l.sid = lo.session_id JOIN dba_objects o ON lo.object_id = o.object_id JOIN v$session s ON l.sid = s.sid WHERE l.type = 'TM' AND (l.lmode >= 4 OR l.request >= 4) ORDER BY l.sid"}	{"condition": "row_count > 0", "description": "Sessions holding or requesting TM locks at level 4+ (SHARE or higher) confirm table-level lock escalation"}	\N	2026-02-28 12:19:19.580455
8496	oracle	query	ORA find DDL operations in active sessions	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.sql_id, SUBSTR(sq.sql_text, 1, 200) AS sql_preview FROM v$session s LEFT JOIN v$sql sq ON s.sql_id = sq.sql_id WHERE s.status = 'ACTIVE' AND s.type = 'USER' AND (UPPER(sq.sql_text) LIKE 'ALTER%' OR UPPER(sq.sql_text) LIKE 'CREATE%INDEX%' OR UPPER(sq.sql_text) LIKE 'DROP%' OR UPPER(sq.sql_text) LIKE 'TRUNCATE%') ORDER BY s.last_call_et DESC"}	{"condition": "row_count > 0", "description": "Active DDL operations confirm they are the source of metadata lock contention"}	\N	2026-02-28 12:19:19.580455
8497	oracle	query	ORA find inactive sessions with open transactions and locks	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.status, s.last_call_et AS idle_secs, ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 86400) AS txn_age_secs, t.used_ublk AS undo_blocks, (SELECT COUNT(*) FROM v$lock l WHERE l.sid = s.sid AND l.type IN ('TX', 'TM') AND l.lmode > 0) AS held_locks FROM v$session s JOIN v$transaction t ON s.saddr = t.ses_addr WHERE s.status = 'INACTIVE' AND s.last_call_et > :idle_threshold AND EXISTS (SELECT 1 FROM v$lock l WHERE l.sid = s.sid AND l.type IN ('TX', 'TM') AND l.lmode > 0) ORDER BY s.last_call_et DESC"}	{"condition": "row_count > 0", "description": "Idle sessions with open transactions and held locks confirm lock hold during non-DB operations"}	{"idle_threshold": 60}	2026-02-28 12:19:19.580455
8498	oracle	query	ORA check session utilization vs limits	{"sql": "SELECT r.current_utilization, r.max_utilization, DECODE(r.limit_value, 'UNLIMITED', 999999, TO_NUMBER(r.limit_value)) AS session_limit, ROUND(r.current_utilization / NULLIF(DECODE(r.limit_value, 'UNLIMITED', 999999, TO_NUMBER(r.limit_value)), 0) * 100, 1) AS utilization_pct FROM v$resource_limit r WHERE r.resource_name = 'sessions'"}	{"condition": "utilization_pct > :threshold_pct", "description": "High session utilization indicates connection pool is nearing exhaustion"}	{"threshold_pct": 85}	2026-02-28 12:19:19.580455
8499	oracle	query	ORA check proportion of sessions waiting on locks	{"sql": "SELECT COUNT(*) AS total_user_sessions, COUNT(CASE WHEN event LIKE 'enq:%' THEN 1 END) AS lock_waiting_sessions, ROUND(COUNT(CASE WHEN event LIKE 'enq:%' THEN 1 END) / NULLIF(COUNT(*), 0) * 100, 1) AS lock_wait_pct FROM v$session WHERE type = 'USER'"}	{"condition": "lock_wait_pct > :lock_wait_threshold", "description": "High percentage of sessions waiting on locks confirms pool exhaustion from lock contention"}	{"lock_wait_threshold": 20}	2026-02-28 12:19:19.580455
