8502	oracle	query	ORA check for enqueue allocation failures	{"sql": "SELECT originating_timestamp, message_text FROM v$diag_alert_ext WHERE message_text LIKE '%enqueue%' AND (message_text LIKE '%ORA-00054%' OR message_text LIKE '%ORA-00055%' OR message_text LIKE '%ORA-00056%') AND originating_timestamp > SYSTIMESTAMP - INTERVAL '7' DAY ORDER BY originating_timestamp DESC"}	{"condition": "row_count > 0", "description": "Enqueue allocation errors confirm internal lock structures are exhausted"}	\N	2026-02-28 12:19:19.580455
8503	oracle	query	ORA check for active statistics gathering sessions	{"sql": "SELECT s.sid, s.serial#, s.module, s.action, s.status, s.last_call_et, SUBSTR(sq.sql_text, 1, 200) AS sql_preview FROM v$session s LEFT JOIN v$sql sq ON s.sql_id = sq.sql_id WHERE s.module LIKE '%DBMS_STATS%' OR s.action LIKE '%gather%' OR (sq.sql_text IS NOT NULL AND UPPER(sq.sql_text) LIKE '%DBMS_STATS%') ORDER BY s.last_call_et DESC"}	{"condition": "row_count > 0", "description": "Active DBMS_STATS sessions may hold locks preventing concurrent DML"}	\N	2026-02-28 12:19:19.580455
8504	oracle	query	ORA check for sessions blocked by stats gathering	{"sql": "SELECT w.sid, w.username, w.event, w.seconds_in_wait, w.blocking_session, bs.module AS blocker_module FROM v$session w LEFT JOIN v$session bs ON w.blocking_session = bs.sid WHERE w.blocking_session IS NOT NULL AND (bs.module LIKE '%DBMS_STATS%' OR bs.action LIKE '%gather%')"}	{"condition": "row_count > 0", "description": "Sessions blocked by DBMS_STATS confirm statistics collection is causing DML contention"}	\N	2026-02-28 12:19:19.580455
8505	oracle	query	ORA find long-running queries with held locks	{"sql": "SELECT s.sid, s.serial#, s.username, s.program, s.sql_id, s.last_call_et AS active_secs, (SELECT COUNT(*) FROM v$lock l WHERE l.sid = s.sid AND l.type IN ('TX', 'TM') AND l.lmode > 0) AS held_locks FROM v$session s WHERE s.status = 'ACTIVE' AND s.type = 'USER' AND s.last_call_et > :duration_threshold AND EXISTS (SELECT 1 FROM v$lock l WHERE l.sid = s.sid AND l.type IN ('TX', 'TM') AND l.lmode > 0) ORDER BY s.last_call_et DESC"}	{"condition": "row_count > 0", "description": "Long-running active queries holding locks prevent other transactions from accessing locked resources"}	{"duration_threshold": 60}	2026-02-28 12:19:19.580455
