8606	oracle	query	ora-check-lob-segment-sizes	{"sql": "SELECT l.owner, l.table_name, l.column_name, l.segment_name, ROUND(s.bytes / 1024 / 1024, 1) AS lob_mb, l.securefile FROM dba_lobs l JOIN dba_segments s ON l.owner = s.owner AND l.segment_name = s.segment_name WHERE l.owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP', 'OUTLN', 'XDB') ORDER BY s.bytes DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Large LOB segments — LOB access loads data into PGA memory"}	\N	2026-02-28 12:19:19.580455
