8620	oracle	query	ora_check_parallel_query_memory_usage	{"sql": "SELECT s.SQL_ID, s.SID, px.DEGREE, px.REQ_DEGREE, px.SID AS coordinator_sid, ROUND(SUM(ss.VALUE) / 1048576, 1) AS pga_mb FROM V$PX_SESSION px JOIN V$SESSION s ON px.SID = s.SID JOIN V$SESSTAT ss ON s.SID = ss.SID JOIN V$STATNAME sn ON ss.STATISTIC# = sn.STATISTIC# WHERE sn.NAME = 'session pga memory' GROUP BY s.SQL_ID, s.SID, px.DEGREE, px.REQ_DEGREE, px.SID ORDER BY pga_mb DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0 AND DEGREE > :max_degree", "description": "Parallel queries with high degree consuming significant PGA"}	{"max_degree": 8}	2026-02-28 12:19:19.580455
