9002	oracle	query	ora_securefile_lob_compression_config	{"sql": "SELECT l.owner, l.table_name, l.column_name, l.segment_name, l.securefile, l.compression, s.bytes / 1024 / 1024 AS lob_size_mb FROM dba_lobs l JOIN dba_segments s ON l.owner = s.owner AND l.segment_name = s.segment_name WHERE l.securefile = 'YES' AND l.compression != 'NONE' AND l.owner NOT IN ('SYS', 'SYSTEM') ORDER BY s.bytes DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "SecureFile LOBs with compression enabled — check if compression is effective"}	\N	2026-02-28 12:19:19.580455
9003	oracle	query	ora_lob_segment_size_vs_table	{"sql": "SELECT l.owner, l.table_name, l.column_name, l.segment_name, ts.bytes / 1024 / 1024 AS table_size_mb, ls.bytes / 1024 / 1024 AS lob_size_mb, ROUND(ls.bytes / GREATEST(ts.bytes, 1) * 100, 1) AS lob_to_table_pct FROM dba_lobs l JOIN dba_segments ts ON l.owner = ts.owner AND l.table_name = ts.segment_name AND ts.segment_type = 'TABLE' JOIN dba_segments ls ON l.owner = ls.owner AND l.segment_name = ls.segment_name WHERE l.owner NOT IN ('SYS', 'SYSTEM') AND ls.bytes > :min_lob_size ORDER BY lob_to_table_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "any lob_to_table_pct > :bloat_threshold", "description": "LOB segments disproportionately large compared to table — possible bloat"}	{"min_lob_size": 104857600, "bloat_threshold": 500}	2026-02-28 12:19:19.580455
9004	oracle	query	ora_long_transactions_blocking_lob_cleanup	{"sql": "SELECT s.sid, s.serial#, s.username, t.start_time, ROUND((SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 24, 1) AS tx_age_hours FROM v$transaction t JOIN v$session s ON t.ses_addr = s.saddr WHERE (SYSDATE - TO_DATE(t.start_time, 'MM/DD/YY HH24:MI:SS')) * 24 > :hours_threshold ORDER BY tx_age_hours DESC"}	{"condition": "row_count > 0", "description": "Long-running transactions preventing LOB space reclamation"}	{"hours_threshold": 4}	2026-02-28 12:19:19.580455
9005	oracle	query	Oracle check LOB segment sizes vs table data	{"sql": "SELECT l.table_name, l.column_name, l.segment_name, s.bytes / 1048576 AS lob_size_mb, t.num_rows, ROUND(s.bytes / NULLIF(t.num_rows, 0), 0) AS bytes_per_row FROM dba_lobs l JOIN dba_segments s ON l.segment_name = s.segment_name AND l.owner = s.owner JOIN dba_tables t ON l.table_name = t.table_name AND l.owner = t.owner WHERE l.owner NOT IN ('SYS', 'SYSTEM') AND s.bytes > :min_lob_size_bytes ORDER BY s.bytes DESC FETCH FIRST 15 ROWS ONLY"}	{"condition": "row_count > 0 with disproportionately large LOB segments", "description": "LOB segments much larger than expected for row count indicate bloat from unreclaimed space"}	{"min_lob_size_bytes": 104857600}	2026-02-28 12:19:19.580455
