9169	oracle	query	ora_check_tablespace_free_space_for_audit	{"sql": "SELECT ts.TABLESPACE_NAME, ROUND(SUM(df.BYTES) / 1048576, 1) AS total_mb, ROUND(SUM(NVL(fs.BYTES, 0)) / 1048576, 1) AS free_mb, ROUND((1 - SUM(NVL(fs.BYTES, 0)) / NULLIF(SUM(df.BYTES), 0)) * 100, 1) AS pct_used FROM DBA_TABLESPACES ts JOIN DBA_DATA_FILES df ON ts.TABLESPACE_NAME = df.TABLESPACE_NAME LEFT JOIN (SELECT TABLESPACE_NAME, SUM(BYTES) AS BYTES FROM DBA_FREE_SPACE GROUP BY TABLESPACE_NAME) fs ON ts.TABLESPACE_NAME = fs.TABLESPACE_NAME WHERE ts.TABLESPACE_NAME IN (SELECT TABLESPACE_NAME FROM DBA_SEGMENTS WHERE SEGMENT_NAME IN ('AUD$', 'FGA_LOG$') OR OWNER = 'AUDSYS') GROUP BY ts.TABLESPACE_NAME"}	{"condition": "pct_used > :threshold_pct", "description": "Tablespace containing audit data is nearly full"}	{"threshold_pct": 85}	2026-02-28 12:19:19.580455
