10670	mysql	query	Identify large secondary indexes on frequently inserted tables	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.CARDINALITY, s.SEQ_IN_INDEX, ROUND(t.INDEX_LENGTH / 1024 / 1024, 2) AS total_index_mb FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND s.INDEX_NAME != 'PRIMARY' AND s.SEQ_IN_INDEX = 1 AND t.INDEX_LENGTH > 10485760 ORDER BY t.INDEX_LENGTH DESC LIMIT 20"}	{"condition": "row_count > 0 AND total_index_mb > 100", "description": "Large secondary indexes on active tables are susceptible to split-inducing insert patterns"}	{"threshold_index_mb": 100}	2026-03-01 06:30:58.706791
10671	mysql	query	Check table fragmentation from delete/insert churn	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb, ROUND(DATA_FREE / 1024 / 1024, 2) AS free_mb, ROUND(DATA_FREE / (DATA_LENGTH + INDEX_LENGTH + DATA_FREE) * 100, 1) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND DATA_FREE > 52428800 ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "fragmentation_pct > 30", "description": "Fragmentation above 30% indicates accumulated page splits from random operations"}	{"threshold_pct": 30, "min_free_bytes": 52428800}	2026-03-01 06:30:58.706791
