10953	mysql	query	Find indexes with identical column sets but different names	{"sql": "SELECT s1.TABLE_SCHEMA, s1.TABLE_NAME, s1.INDEX_NAME AS index1, s2.INDEX_NAME AS index2 FROM (SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME) s1 JOIN (SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME) s2 ON s1.TABLE_SCHEMA = s2.TABLE_SCHEMA AND s1.TABLE_NAME = s2.TABLE_NAME AND s1.cols = s2.cols AND s1.INDEX_NAME < s2.INDEX_NAME"}	{"condition": "row_count > 0", "description": "Duplicate indexes with different names found"}	\N	2026-03-01 06:30:58.706791
