10960	mysql	query	Find indexes on boolean-like columns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.DATA_TYPE, c.COLUMN_TYPE, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE (c.DATA_TYPE IN ('tinyint', 'bit', 'enum') OR c.COLUMN_TYPE = 'tinyint(1)') AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND t.TABLE_ROWS > :min_rows AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes on boolean/flag columns with very low selectivity found"}	{"min_rows": 10000}	2026-03-01 06:30:58.706791
