10961	mysql	query	Find indexes with very low cardinality on large tables	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.CARDINALITY < :max_cardinality AND t.TABLE_ROWS > :min_rows AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with very few distinct values relative to table size"}	{"min_rows": 10000, "max_cardinality": 300}	2026-03-01 06:30:58.706791
10962	mysql	query	Find indexes with cardinality under 5	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.DATA_TYPE, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 6) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE s.CARDINALITY < 5 AND t.TABLE_ROWS > :min_rows AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with fewer than 5 distinct values on large tables"}	{"min_rows": 10000}	2026-03-01 06:30:58.706791
10963	mysql	query	Find indexes on columns with low cardinality and ENUM/status patterns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.COLUMN_TYPE FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE (c.COLUMN_NAME LIKE '%status%' OR c.COLUMN_NAME LIKE '%state%' OR c.COLUMN_NAME LIKE '%type%' OR c.DATA_TYPE = 'enum') AND s.CARDINALITY < :max_cardinality AND t.TABLE_ROWS > :min_rows AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY t.TABLE_ROWS DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Status-type columns with low cardinality indexes found"}	{"min_rows": 10000, "max_cardinality": 20}	2026-03-01 06:30:58.706791
10964	mysql	query	Find date column indexes with low cardinality relative to row count	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.DATA_TYPE, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.DATA_TYPE IN ('date', 'datetime', 'timestamp') AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND t.TABLE_ROWS > :min_rows AND ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) < :selectivity_threshold AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Date indexes with low selectivity — many rows per date value"}	{"min_rows": 100000, "selectivity_threshold": 1}	2026-03-01 06:30:58.706791
10965	mysql	query	Find categorical indexes with very low selectivity	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.CARDINALITY < :max_distinct AND t.TABLE_ROWS > :min_rows AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Low-cardinality indexes found with very low selectivity"}	{"min_rows": 50000, "max_distinct": 50}	2026-03-01 06:30:58.706791
10966	mysql	query	Find composite indexes with low-cardinality leading column	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME AS leading_column, s.CARDINALITY AS leading_cardinality, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS leading_selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.CARDINALITY < :max_cardinality AND t.TABLE_ROWS > :min_rows AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND EXISTS (SELECT 1 FROM information_schema.STATISTICS s2 WHERE s2.TABLE_SCHEMA = s.TABLE_SCHEMA AND s2.TABLE_NAME = s.TABLE_NAME AND s2.INDEX_NAME = s.INDEX_NAME AND s2.SEQ_IN_INDEX > 1) ORDER BY leading_selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Composite indexes with non-selective leading columns found"}	{"min_rows": 10000, "max_cardinality": 10}	2026-03-01 06:30:58.706791
