10967	mysql	query	Find indexes with very low selectivity on large tables	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, t.CREATE_TIME, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) < :selectivity_threshold AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND t.TABLE_ROWS > :min_rows AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with very low selectivity on mature tables"}	{"min_rows": 100000, "selectivity_threshold": 0.1}	2026-03-01 06:30:58.706791
