10972	mysql	query	Find nullable indexed columns with low cardinality	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.IS_NULLABLE, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.IS_NULLABLE = 'YES' AND s.CARDINALITY IS NOT NULL AND t.TABLE_ROWS > :min_rows AND ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) < :selectivity_threshold AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Nullable columns with very low selectivity suggesting high NULL proportion"}	{"min_rows": 10000, "selectivity_threshold": 1}	2026-03-01 06:30:58.706791
