10986	mysql	query	Find tables with wide primary keys	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, GROUP_CONCAT(c.COLUMN_NAME ORDER BY s.SEQ_IN_INDEX) AS pk_columns, SUM(CASE WHEN c.DATA_TYPE IN ('char', 'varchar') THEN c.CHARACTER_MAXIMUM_LENGTH WHEN c.DATA_TYPE IN ('binary', 'varbinary') THEN c.CHARACTER_MAXIMUM_LENGTH WHEN c.DATA_TYPE = 'bigint' THEN 8 WHEN c.DATA_TYPE = 'int' THEN 4 ELSE 8 END) AS pk_width_bytes FROM information_schema.COLUMNS c JOIN information_schema.STATISTICS s ON c.TABLE_SCHEMA = s.TABLE_SCHEMA AND c.TABLE_NAME = s.TABLE_NAME AND c.COLUMN_NAME = s.COLUMN_NAME WHERE s.INDEX_NAME = 'PRIMARY' AND c.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY c.TABLE_SCHEMA, c.TABLE_NAME HAVING pk_width_bytes > :threshold ORDER BY pk_width_bytes DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with wide primary keys that inflate secondary indexes"}	{"threshold": 16}	2026-03-01 06:30:58.706791
10988	mysql	query	Find indexes with wide VARCHAR columns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.SUB_PART, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.DATA_TYPE IN ('varchar', 'varbinary') AND c.CHARACTER_MAXIMUM_LENGTH > :width_threshold AND s.SUB_PART IS NULL AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY c.CHARACTER_MAXIMUM_LENGTH DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with wide VARCHAR columns found"}	{"width_threshold": 100}	2026-03-01 06:30:58.706791
10989	mysql	query	Find composite indexes with high total key width	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, COUNT(*) AS col_count, GROUP_CONCAT(CONCAT(s.COLUMN_NAME, '(', COALESCE(c.CHARACTER_MAXIMUM_LENGTH, 8), ')') ORDER BY s.SEQ_IN_INDEX) AS columns_with_width, SUM(CASE WHEN c.DATA_TYPE IN ('varchar', 'char') THEN c.CHARACTER_MAXIMUM_LENGTH * 4 WHEN c.DATA_TYPE IN ('int') THEN 4 WHEN c.DATA_TYPE IN ('bigint') THEN 8 ELSE 8 END) AS estimated_key_bytes FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND s.INDEX_NAME != 'PRIMARY' GROUP BY s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME HAVING col_count > :col_threshold AND estimated_key_bytes > :byte_threshold ORDER BY estimated_key_bytes DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Composite indexes with excessively wide total key size"}	{"col_threshold": 3, "byte_threshold": 500}	2026-03-01 06:30:58.706791
10990	mysql	query	Find indexes with wide leading columns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH, s.CARDINALITY FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE s.SEQ_IN_INDEX = 1 AND c.DATA_TYPE IN ('char', 'varchar') AND c.CHARACTER_MAXIMUM_LENGTH > :width_threshold AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY c.CHARACTER_MAXIMUM_LENGTH DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Leading index columns wider than typical discrimination needs"}	{"width_threshold": 50}	2026-03-01 06:30:58.706791
