10992	mysql	query	Find indexes with wide columns using multi-byte character sets	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, c.CHARACTER_MAXIMUM_LENGTH, c.CHARACTER_SET_NAME, c.COLLATION_NAME, CASE WHEN c.CHARACTER_SET_NAME = 'utf8mb4' THEN c.CHARACTER_MAXIMUM_LENGTH * 4 WHEN c.CHARACTER_SET_NAME = 'utf8' THEN c.CHARACTER_MAXIMUM_LENGTH * 3 WHEN c.CHARACTER_SET_NAME = 'latin1' THEN c.CHARACTER_MAXIMUM_LENGTH ELSE c.CHARACTER_MAXIMUM_LENGTH * 4 END AS max_byte_width FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.CHARACTER_SET_NAME IN ('utf8mb4', 'utf8mb3', 'utf8') AND c.CHARACTER_MAXIMUM_LENGTH > :width_threshold AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY max_byte_width DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with wide columns using multi-byte character sets"}	{"width_threshold": 100}	2026-03-01 06:30:58.706791
