11003	mysql	query	Find sessions waiting on row locks held by other transactions	{"sql": "SELECT r.trx_id AS waiting_trx_id, r.trx_mysql_thread_id AS waiting_thread, r.trx_query AS waiting_query, r.trx_started AS waiting_since, b.trx_id AS blocking_trx_id, b.trx_mysql_thread_id AS blocking_thread, b.trx_query AS blocking_query, b.trx_started AS blocking_since, TIMESTAMPDIFF(SECOND, r.trx_started, NOW()) AS waiting_seconds FROM information_schema.INNODB_TRX r JOIN performance_schema.data_lock_waits w ON r.trx_id = w.REQUESTING_ENGINE_TRANSACTION_ID JOIN information_schema.INNODB_TRX b ON b.trx_id = w.BLOCKING_ENGINE_TRANSACTION_ID WHERE TIMESTAMPDIFF(SECOND, r.trx_started, NOW()) > 30"}	{"condition": "row_count > 0", "description": "Transactions waiting on locks held by other active transactions"}	{"threshold_seconds": 30}	2026-03-01 06:30:58.706791
