11868	mysql	query	Find indexed columns without histogram statistics used in frequent queries	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.COLUMN_NAME, s.CARDINALITY, (SELECT COUNT(*) FROM information_schema.COLUMN_STATISTICS cs WHERE cs.SCHEMA_NAME = s.TABLE_SCHEMA AND cs.TABLE_NAME = s.TABLE_NAME AND cs.COLUMN_NAME = s.COLUMN_NAME) AS has_histogram FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND s.SEQ_IN_INDEX = 1 ORDER BY s.CARDINALITY ASC LIMIT 20;"}	{"condition": "has_histogram = 0 for frequently queried columns", "description": "Indexed columns without histograms rely on basic cardinality estimates which may be insufficient"}	\N	2026-03-01 06:30:58.706791
11869	mysql	query	Check partitioned tables for stale statistics	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, PARTITION_NAME, TABLE_ROWS, UPDATE_TIME FROM information_schema.PARTITIONS WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND PARTITION_NAME IS NOT NULL AND (UPDATE_TIME IS NULL OR UPDATE_TIME < DATE_SUB(NOW(), INTERVAL 7 DAY)) ORDER BY TABLE_ROWS DESC LIMIT 20;"}	{"condition": "row_count > 0", "description": "Partitions with stale or missing update timestamps indicate outdated statistics"}	\N	2026-03-01 06:30:58.706791
11871	mysql	query	Check for multi-column predicates without composite indexes	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%WHERE%AND%' AND SUM_ROWS_EXAMINED > 10 * SUM_ROWS_SENT AND COUNT_STAR > 100 AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10;"}	{"condition": "row_count > 0 with high examine-to-sent ratio", "description": "Multi-column WHERE clauses with high examine:sent ratio suggest optimizer assuming column independence"}	\N	2026-03-01 06:30:58.706791
11884	mysql	query	Check InnoDB I/O thread configuration	{"sql": "SELECT @@global.innodb_read_io_threads AS read_threads, @@global.innodb_write_io_threads AS write_threads, @@global.innodb_use_native_aio AS native_aio, @@global.innodb_io_capacity AS io_capacity;"}	{"condition": "read_threads < 4 OR native_aio = 0 OR io_capacity < 200", "description": "Low I/O thread count, disabled AIO, or low I/O capacity limits InnoDB's ability to schedule I/O efficiently"}	\N	2026-03-01 06:30:58.706791
11872	mysql	query	Find generated columns with indexes	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, c.COLUMN_NAME, c.GENERATION_EXPRESSION, c.EXTRA FROM information_schema.COLUMNS c WHERE c.GENERATION_EXPRESSION IS NOT NULL AND c.GENERATION_EXPRESSION != '' AND c.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND EXISTS (SELECT 1 FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME) LIMIT 20;"}	{"condition": "row_count > 0", "description": "Generated columns with indexes may have stale statistics when base column data changes"}	\N	2026-03-01 06:30:58.706791
11873	mysql	query	Check index cardinality accuracy	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, COLUMN_NAME, CARDINALITY, (SELECT TABLE_ROWS FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA = s.TABLE_SCHEMA AND t.TABLE_NAME = s.TABLE_NAME) AS total_rows FROM information_schema.STATISTICS s WHERE SEQ_IN_INDEX = 1 AND CARDINALITY > 0 AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY TABLE_SCHEMA, TABLE_NAME LIMIT 20;"}	{"condition": "cardinality seems improbable relative to table size", "description": "Index cardinality that seems too high or too low relative to total rows suggests outdated density estimates"}	\N	2026-03-01 06:30:58.706791
11874	mysql	query	Check for stale histograms on growing datasets	{"sql": "SELECT cs.SCHEMA_NAME, cs.TABLE_NAME, cs.COLUMN_NAME, JSON_EXTRACT(cs.HISTOGRAM, '$.\\"last-updated\\"') AS last_updated, t.TABLE_ROWS, t.UPDATE_TIME FROM information_schema.COLUMN_STATISTICS cs JOIN information_schema.TABLES t ON cs.SCHEMA_NAME = t.TABLE_SCHEMA AND cs.TABLE_NAME = t.TABLE_NAME WHERE t.UPDATE_TIME > JSON_UNQUOTE(JSON_EXTRACT(cs.HISTOGRAM, '$.\\"last-updated\\"'));"}	{"condition": "row_count > 0", "description": "Tables modified after histogram creation may have values outside the histogram range"}	\N	2026-03-01 06:30:58.706791
11875	mysql	query	Find datetime column histograms that may be stale	{"sql": "SELECT cs.SCHEMA_NAME, cs.TABLE_NAME, cs.COLUMN_NAME, JSON_EXTRACT(cs.HISTOGRAM, '$.\\"last-updated\\"') AS last_updated, JSON_EXTRACT(cs.HISTOGRAM, '$.\\"data-type\\"') AS data_type FROM information_schema.COLUMN_STATISTICS cs JOIN information_schema.COLUMNS c ON cs.SCHEMA_NAME = c.TABLE_SCHEMA AND cs.TABLE_NAME = c.TABLE_NAME AND cs.COLUMN_NAME = c.COLUMN_NAME WHERE c.DATA_TYPE IN ('datetime', 'timestamp', 'date') AND JSON_EXTRACT(cs.HISTOGRAM, '$.\\"last-updated\\"') < DATE_SUB(NOW(), INTERVAL 3 DAY);"}	{"condition": "row_count > 0", "description": "Datetime histograms older than 3 days don't cover current time-series data"}	\N	2026-03-01 06:30:58.706791
11876	mysql	query	Check InnoDB I/O metrics	{"sql": "SELECT (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'os_pending_reads') AS pending_reads, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'os_pending_writes') AS pending_writes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_reads') AS data_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_writes') AS data_writes;"}	{"condition": "pending_reads > 64 OR pending_writes > 64", "description": "High pending I/O requests indicate storage cannot keep up with MySQL demand"}	\N	2026-03-01 06:30:58.706791
11877	mysql	query	Check if InnoDB I/O capacity is saturated	{"sql": "SELECT @@global.innodb_io_capacity AS io_capacity, @@global.innodb_io_capacity_max AS io_capacity_max, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_wait_free') AS wait_free;"}	{"condition": "wait_free > 0", "description": "Buffer pool waiting for free pages confirms I/O is the bottleneck"}	\N	2026-03-01 06:30:58.706791
11878	mysql	query	Check InnoDB file I/O timing	{"sql": "SELECT EVENT_NAME, COUNT_STAR, SUM_TIMER_WAIT / 1000000000 AS total_wait_ms, AVG_TIMER_WAIT / 1000000 AS avg_wait_us, MAX_TIMER_WAIT / 1000000 AS max_wait_us FROM performance_schema.file_summary_by_event_name WHERE EVENT_NAME LIKE '%innodb%' AND COUNT_STAR > 0 ORDER BY SUM_TIMER_WAIT DESC LIMIT 10;"}	{"condition": "avg_wait_us > 1000 (1ms)", "description": "Average I/O wait exceeding 1ms indicates slow storage subsystem"}	\N	2026-03-01 06:30:58.706791
11879	mysql	query	Check InnoDB flush method and fsync overhead	{"sql": "SELECT @@global.innodb_flush_method AS flush_method, @@global.innodb_flush_log_at_trx_commit AS flush_log_at_commit, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_os_log_fsyncs') AS log_fsyncs, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_fsyncs') AS data_fsyncs;"}	{"condition": "flush_log_at_commit = 1 AND high fsync count", "description": "innodb_flush_log_at_trx_commit=1 with no BBU means every commit triggers a synchronous write to disk"}	\N	2026-03-01 06:30:58.706791
11880	mysql	query	Check I/O wait patterns across file types	{"sql": "SELECT FILE_NAME, COUNT_READ, COUNT_WRITE, SUM_TIMER_READ / 1000000000 AS read_wait_ms, SUM_TIMER_WRITE / 1000000000 AS write_wait_ms FROM performance_schema.file_summary_by_instance WHERE FILE_NAME LIKE '%ibdata%' OR FILE_NAME LIKE '%ibd' OR FILE_NAME LIKE '%ib_logfile%' OR FILE_NAME LIKE '%binlog%' ORDER BY SUM_TIMER_READ + SUM_TIMER_WRITE DESC LIMIT 10;"}	{"condition": "all file types showing high wait times uniformly", "description": "Uniform high latency across all file types suggests a shared storage controller bottleneck"}	\N	2026-03-01 06:30:58.706791
12129	postgresql	sql_query	Detect transactions from unexpected applications	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM information_schema.GLOBAL_STATUS WHERE VARIABLE_NAME IN ('Connection_errors_max_connections', 'Aborted_connects') ORDER BY VARIABLE_NAME"}	{"condition": "Connection_errors_max_connections > 0", "description": "Any refused connections confirms max_connections has been exceeded"}	\N	2026-04-03 08:56:47.258705
11881	mysql	query	Check for fragmented tables with high DATA_FREE	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, DATA_LENGTH, DATA_FREE, ROUND(DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) * 100, 2) AS fragmentation_pct, TABLE_ROWS FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND DATA_FREE > 0 AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY DATA_FREE DESC LIMIT 10;"}	{"condition": "fragmentation_pct > 15", "description": "Tables with more than 15% fragmentation waste I/O reading sparse pages"}	\N	2026-03-01 06:30:58.706791
11882	mysql	query	Check ratio of random to sequential reads	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_reads') AS random_disk_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_ahead') AS readahead_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_reads') AS total_reads;"}	{"condition": "random_disk_reads >> readahead_pages", "description": "Random disk reads far exceeding sequential read-ahead indicates random I/O dominated workload"}	\N	2026-03-01 06:30:58.706791
