11887	mysql	query	Check read-ahead effectiveness	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_ahead') AS readahead_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_ahead_evicted') AS readahead_evicted, @@global.innodb_read_ahead_threshold AS readahead_threshold;"}	{"condition": "readahead_evicted / readahead_pages > 0.5 OR readahead_pages is very low", "description": "High read-ahead eviction rate means prefetched pages are wasted, or low read-ahead means sequential scans are not optimized"}	\N	2026-03-01 06:30:58.706791
11888	mysql	query	Check I/O latency consistency across file types	{"sql": "SELECT SUBSTRING_INDEX(FILE_NAME, '/', -1) AS file_short, COUNT_READ, COUNT_WRITE, SUM_TIMER_READ / NULLIF(COUNT_READ, 0) / 1000000 AS avg_read_us, SUM_TIMER_WRITE / NULLIF(COUNT_WRITE, 0) / 1000000 AS avg_write_us FROM performance_schema.file_summary_by_instance WHERE (FILE_NAME LIKE '%.ibd' OR FILE_NAME LIKE '%ib_logfile%' OR FILE_NAME LIKE '%ibdata%') AND COUNT_READ + COUNT_WRITE > 100 ORDER BY avg_read_us DESC LIMIT 10;"}	{"condition": "avg_read_us > 2000 across all files", "description": "Uniformly high latency across all MySQL files suggests network storage path saturation"}	\N	2026-03-01 06:30:58.706791
11889	mysql	query	Check for write latency spikes suggesting cache overflow	{"sql": "SELECT EVENT_NAME, AVG_TIMER_WAIT / 1000000 AS avg_us, MAX_TIMER_WAIT / 1000000 AS max_us, COUNT_STAR FROM performance_schema.file_summary_by_event_name WHERE EVENT_NAME LIKE '%innodb%log%' AND COUNT_STAR > 100;"}	{"condition": "max_us > 100000 AND avg_us < 1000", "description": "Occasional extreme write latency spikes with low average suggests SSD/controller cache overflow"}	\N	2026-03-01 06:30:58.706791
