11891	mysql	query	Check for INSERT-related deadlocks	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks') AS deadlock_count, DIGEST_TEXT, SUM_ERRORS FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%INSERT%' AND SUM_ERRORS > 0 AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_ERRORS DESC LIMIT 5;"}	{"condition": "deadlock_count > 0 AND INSERT errors present", "description": "INSERT errors combined with deadlocks suggest unique key constraint deadlocks"}	\N	2026-03-01 06:30:58.706791
11905	mysql	query	Check connection utilization	{"sql": "SELECT @@global.max_connections AS max_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS threads_connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_running') AS threads_running, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connection_errors_max_connections') AS max_conn_errors;"}	{"condition": "threads_connected > max_connections * 0.9 OR max_conn_errors > 0", "description": "Connection pool near capacity or connection rejections indicate exhaustion"}	\N	2026-03-01 06:30:58.706791
12136	postgresql	sql_query	Detect privilege escalation in active transactions	{"sql": "SHOW ENGINE INNODB STATUS"}	{"condition": "LATEST DETECTED DEADLOCK section present with conflicting lock orders", "description": "Deadlock section shows which transactions were involved and what locks they held/requested"}	\N	2026-04-03 08:57:21.470364
11906	mysql	query	Check foreign key constraints and their indexes	{"sql": "SELECT rc.CONSTRAINT_SCHEMA, rc.TABLE_NAME AS child_table, rc.REFERENCED_TABLE_NAME AS parent_table, kcu.COLUMN_NAME AS fk_column, kcu.REFERENCED_COLUMN_NAME AS ref_column FROM information_schema.REFERENTIAL_CONSTRAINTS rc JOIN information_schema.KEY_COLUMN_USAGE kcu ON rc.CONSTRAINT_SCHEMA = kcu.CONSTRAINT_SCHEMA AND rc.CONSTRAINT_NAME = kcu.CONSTRAINT_NAME WHERE rc.CONSTRAINT_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys');"}	{"condition": "foreign key columns exist", "description": "Foreign key relationships found — verify indexes exist on both sides"}	\N	2026-03-01 06:30:58.706791
11908	mysql	query	Check lock wait timeout and timeout frequency	{"sql": "SELECT @@global.innodb_lock_wait_timeout AS lock_wait_timeout, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_timeouts') AS lock_timeouts, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS lock_waits;"}	{"condition": "lock_timeouts > 0 AND lock_timeouts / lock_waits > 0.1", "description": "More than 10% of lock waits resulting in timeouts suggests lock_wait_timeout is too short or there are persistent blocking issues"}	\N	2026-03-01 06:30:58.706791
11909	mysql	query	Check isolation level and gap lock indicators	{"sql": "SELECT @@global.transaction_isolation AS isolation, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS lock_waits, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_timeouts') AS timeouts;"}	{"condition": "isolation = 'REPEATABLE-READ' AND lock_waits is high", "description": "REPEATABLE-READ gap locks can block INSERT operations in ranges between existing keys"}	\N	2026-03-01 06:30:58.706791
11910	mysql	query	Check row lock wait metrics	{"sql": "SELECT (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS row_lock_waits, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_time') AS row_lock_time_ms, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_time_avg') AS avg_lock_time_ms;"}	{"condition": "row_lock_waits > 1000 per hour AND avg_lock_time_ms > 100", "description": "High row lock wait count with significant average wait time indicates contention"}	\N	2026-03-01 06:30:58.706791
11926	mysql	query	Find long-running transactions with row locks	{"sql": "SELECT trx_id, trx_started, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS duration_sec, trx_rows_locked, trx_rows_modified, trx_isolation_level FROM information_schema.INNODB_TRX WHERE trx_rows_locked > 0 AND TIMESTAMPDIFF(SECOND, trx_started, NOW()) > 60 ORDER BY duration_sec DESC LIMIT 10;"}	{"condition": "row_count > 0", "description": "Transactions holding locks for more than 60 seconds block concurrent access"}	\N	2026-03-01 06:30:58.706791
11911	mysql	query	Check for MyISAM tables and table lock waits	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Table_locks_waited') AS table_lock_waits, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Table_locks_immediate') AS table_lock_immediate, (SELECT COUNT(*) FROM information_schema.TABLES WHERE ENGINE = 'MyISAM' AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys')) AS myisam_tables;"}	{"condition": "table_lock_waits > 0 OR myisam_tables > 0", "description": "Table lock waits or MyISAM tables indicate table-level lock contention"}	\N	2026-03-01 06:30:58.706791
13692	mariadb	query	Check if standard async replication is configured	{"sql": "SELECT CHANNEL_NAME, SERVICE_STATE FROM performance_schema.replication_connection_status"}	{"condition": "row_count > 0", "description": "Standard replication without Group Replication means no built-in consensus"}	\N	2026-05-11 22:17:39.229791
11913	mysql	query	Check for global lock status	{"sql": "SELECT ID, USER, HOST, COMMAND, TIME, STATE, LEFT(INFO, 200) AS query FROM information_schema.PROCESSLIST WHERE STATE LIKE '%Waiting for global read lock%' OR STATE LIKE '%Waiting for table flush%' OR INFO LIKE '%FLUSH TABLE%READ LOCK%' ORDER BY TIME DESC;"}	{"condition": "row_count > 0", "description": "Sessions waiting for or holding global read locks block all write operations"}	\N	2026-03-01 06:30:58.706791
11914	mysql	query	Check lock types in current wait scenarios	{"sql": "SELECT LOCK_TYPE, LOCK_MODE, LOCK_STATUS, LOCK_DATA, COUNT(*) AS cnt FROM performance_schema.data_locks GROUP BY LOCK_TYPE, LOCK_MODE, LOCK_STATUS, LOCK_DATA ORDER BY cnt DESC LIMIT 20;"}	{"condition": "GAP or next-key lock modes with high counts", "description": "High gap or next-key lock counts indicate InnoDB is locking index ranges unnecessarily wide"}	\N	2026-03-01 06:30:58.706791
11915	mysql	query	Check adaptive hash index contention	{"sql": "SELECT @@global.innodb_adaptive_hash_index AS ahi_enabled, @@global.innodb_adaptive_hash_index_parts AS ahi_parts, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'adaptive_hash_searches') AS ahi_searches, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'adaptive_hash_searches_btree') AS btree_searches;"}	{"condition": "ahi_enabled = 1 AND ahi_searches / (ahi_searches + btree_searches) < 0.5", "description": "Adaptive hash index is enabled but has low hit ratio, suggesting it may be causing more contention than benefit"}	\N	2026-03-01 06:30:58.706791
11916	mysql	query	Check buffer pool instance configuration	{"sql": "SELECT @@global.innodb_buffer_pool_size AS pool_size, @@global.innodb_buffer_pool_instances AS pool_instances, ROUND(@@global.innodb_buffer_pool_size / @@global.innodb_buffer_pool_instances / 1024 / 1024, 0) AS mb_per_instance;"}	{"condition": "pool_instances = 1 AND pool_size > 1073741824", "description": "Single buffer pool instance with >1GB creates a contention bottleneck under high concurrency"}	\N	2026-03-01 06:30:58.706791
11917	mysql	query	Check redo log write wait metrics	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_log_waits') AS log_waits, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_log_write_requests') AS write_requests, @@global.innodb_flush_log_at_trx_commit AS flush_at_commit;"}	{"condition": "log_waits > 0 AND log_waits / write_requests > 0.01", "description": "Redo log waits indicate serialization on the log writer, a throughput bottleneck"}	\N	2026-03-01 06:30:58.706791
11918	mysql	query	Check doublewrite metrics	{"sql": "SELECT @@global.innodb_doublewrite AS doublewrite_enabled, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_dblwr_pages_written') AS dblwr_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_dblwr_writes') AS dblwr_writes;"}	{"condition": "doublewrite_enabled = 1 AND dblwr_pages / dblwr_writes < 4", "description": "Low pages-per-write ratio on doublewrite suggests inefficient batching, adding write overhead"}	\N	2026-03-01 06:30:58.706791
11919	mysql	query	Check purge thread configuration and lag	{"sql": "SELECT @@global.innodb_purge_threads AS purge_threads, @@global.innodb_purge_batch_size AS batch_size, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'trx_rseg_history_len') AS history_len;"}	{"condition": "history_len > 10000 AND purge_threads < 4", "description": "Growing history list with few purge threads indicates purge is a bottleneck"}	\N	2026-03-01 06:30:58.706791
11920	mysql	query	Check change buffer metrics	{"sql": "SELECT @@global.innodb_change_buffering AS change_buffering, @@global.innodb_change_buffer_max_size AS max_size_pct, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'ibuf_merges') AS merges, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'ibuf_merges_insert') AS merge_inserts;"}	{"condition": "merges is high relative to uptime AND max_size_pct > 25", "description": "High change buffer merge rate indicates secondary index updates are being deferred and merged, potentially causing contention"}	\N	2026-03-01 06:30:58.706791
