7553	oracle	query	ora-check-table-space-waste	{"sql": "SELECT owner, table_name, ROUND(blocks * 8192 / 1024 / 1024, 1) AS allocated_mb, num_rows, avg_row_len, ROUND(num_rows * avg_row_len / 1024 / 1024, 1) AS estimated_data_mb, ROUND((blocks * 8192 - num_rows * avg_row_len) / NULLIF(blocks * 8192, 0) * 100, 1) AS waste_pct FROM ALL_TABLES WHERE owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP', 'OUTLN', 'XDB') AND blocks > 1000 AND num_rows > 0 AND ROUND((blocks * 8192 - num_rows * avg_row_len) / NULLIF(blocks * 8192, 0) * 100, 1) > :waste_threshold ORDER BY waste_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with high wasted space percentage indicate storage bloat from insufficient maintenance"}	{"waste_threshold": 50}	2026-02-28 12:19:19.580455
12039	mysql	query	Find subquery patterns with aggregate functions	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED / NULLIF(COUNT_STAR, 0) AS avg_rows_examined, SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0) AS examine_to_sent_ratio, SUM_TIMER_WAIT / 1e12 / NULLIF(COUNT_STAR, 0) AS avg_sec FROM performance_schema.events_statements_summary_by_digest WHERE (DIGEST_TEXT LIKE '%(%SELECT COUNT%' OR DIGEST_TEXT LIKE '%(%SELECT SUM%' OR DIGEST_TEXT LIKE '%(%SELECT AVG%' OR DIGEST_TEXT LIKE '%(%SELECT MAX%' OR DIGEST_TEXT LIKE '%(%SELECT MIN%') AND SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0) > 100 AND COUNT_STAR > 5 ORDER BY examine_to_sent_ratio DESC LIMIT 20;"}	{"condition": "aggregate subqueries with very high examine-to-sent ratio", "description": "Correlated aggregate subqueries scan the inner table fully per outer row; with N outer rows and M inner rows, total work is O(N*M)"}	\N	2026-03-01 06:30:58.706791
