836	sqlserver	query	Check CDC log scan latency and change table sizes	{"sql": "IF OBJECT_ID('cdc.change_tables') IS NOT NULL BEGIN\\nSELECT\\n  ct.capture_instance,\\n  OBJECT_NAME(ct.source_object_id) AS source_table,\\n  p.rows AS change_table_rows,\\n  au.total_pages * 8 / 1024 AS change_table_mb,\\n  ls.latency AS scan_latency_sec,\\n  ls.empty_scan_count,\\n  ls.command_count\\nFROM cdc.change_tables ct\\nJOIN sys.partitions p ON p.object_id = ct.object_id AND p.index_id <= 1\\nJOIN sys.allocation_units au ON au.container_id = p.hobt_id\\nLEFT JOIN (\\n  SELECT TOP 1 latency, empty_scan_count, command_count\\n  FROM sys.dm_cdc_log_scan_sessions\\n  ORDER BY start_time DESC\\n) ls ON 1=1\\nWHERE au.type_desc = 'IN_ROW_DATA'\\nORDER BY change_table_mb DESC\\nEND ELSE BEGIN\\nSELECT NULL AS no_cdc WHERE 1=0\\nEND"}	{"condition": "change_table_mb > 100 OR scan_latency_sec > 60", "description": "CDC change tables growing large or log scan falling behind"}	null	2026-02-23 20:18:31.389317
