993	sqlserver	query	Check VLF count and log file sizing	{"sql": "SELECT db.name AS database_name,\\n  mf.size * 8 / 1024 AS log_file_size_mb,\\n  mf.growth * 8 / 1024 AS growth_increment_mb,\\n  mf.is_percent_growth,\\n  ls.used_log_space_in_percent,\\n  vlf.vlf_count\\nFROM sys.databases db\\nJOIN sys.master_files mf ON db.database_id = mf.database_id\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nCROSS APPLY (\\n  SELECT COUNT(*) AS vlf_count\\n  FROM sys.dm_db_log_info(db.database_id)\\n) vlf\\nWHERE mf.type_desc = 'LOG'\\n  AND db.database_id > 4\\n  AND vlf.vlf_count > 100\\nORDER BY vlf.vlf_count DESC"}	{"condition": "vlf_count > 100", "description": "Excessive VLF count indicating log file grew through many small auto-growth events"}	null	2026-02-23 20:18:31.389458
995	sqlserver	query	Check recovery model and log backup history	{"sql": "SELECT d.name AS database_name,\\n  d.recovery_model_desc,\\n  d.log_reuse_wait_desc,\\n  ls.total_log_size_in_bytes / 1048576 AS log_size_mb,\\n  ls.used_log_space_in_percent,\\n  b.last_log_backup,\\n  DATEDIFF(DAY, b.last_log_backup, GETDATE()) AS days_since_log_backup\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nOUTER APPLY (\\n  SELECT MAX(bs.backup_finish_date) AS last_log_backup\\n  FROM msdb.dbo.backupset bs\\n  WHERE bs.database_name = d.name AND bs.type = 'L'\\n) b\\nWHERE d.recovery_model_desc = 'FULL'\\n  AND d.database_id > 4\\n  AND d.state_desc = 'ONLINE'\\n  AND (b.last_log_backup IS NULL OR DATEDIFF(DAY, b.last_log_backup, GETDATE()) > 1)"}	{"condition": "row_count > 0 with last_log_backup IS NULL or days_since_log_backup > 1", "description": "FULL recovery databases with no log backup schedule or severely stale backups"}	null	2026-02-23 20:18:31.389459
996	sqlserver	query	Confirm log is growing due to missing log backups	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  ls.total_log_size_in_bytes / 1048576 AS log_size_mb,\\n  ls.used_log_space_in_percent,\\n  df.size * 8 / 1024 AS allocated_log_mb,\\n  CASE WHEN d.log_reuse_wait_desc = 'LOG_BACKUP' THEN 'YES' ELSE 'NO' END AS blocked_by_missing_log_backup\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nJOIN sys.master_files df ON d.database_id = df.database_id AND df.type_desc = 'LOG'\\nWHERE d.recovery_model_desc = 'FULL'\\n  AND d.database_id > 4\\n  AND (d.log_reuse_wait_desc = 'LOG_BACKUP' OR ls.used_log_space_in_percent > 60)\\nORDER BY ls.used_log_space_in_percent DESC"}	{"condition": "log_reuse_wait_desc = 'LOG_BACKUP' with high used_log_space_in_percentage", "description": "Confirmed: FULL recovery with log growth blocked by missing log backups"}	null	2026-02-23 20:18:31.38946
1006	sqlserver	query	Check Query Store status across databases	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  CASE\\n    WHEN qso.desired_state_desc IS NULL THEN 'NOT_AVAILABLE'\\n    ELSE qso.desired_state_desc\\n  END AS query_store_desired,\\n  CASE\\n    WHEN qso.actual_state_desc IS NULL THEN 'NOT_AVAILABLE'\\n    ELSE qso.actual_state_desc\\n  END AS query_store_actual,\\n  qso.current_storage_size_mb,\\n  qso.max_storage_size_mb,\\n  qso.stale_query_threshold_days\\nFROM sys.databases d\\nLEFT JOIN sys.database_query_store_options qso ON d.database_id = DB_ID(d.name)\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'\\n  AND (qso.actual_state_desc IS NULL OR qso.actual_state_desc <> 'READ_WRITE')\\nORDER BY d.name"}	{"condition": "row_count > 0", "description": "User databases without Query Store actively collecting performance baselines"}	null	2026-02-23 20:18:31.389466
1168	sqlserver	query	Check for plan cache memory pressure notifications	{"sql": "SELECT name, type, pages_kb, pages_in_use_kb, entries_count, entries_in_use_count, CASE WHEN pages_kb > 1000000 THEN 'HIGH_MEMORY_USAGE' WHEN entries_count > 50000 THEN 'HIGH_ENTRY_COUNT' ELSE 'OK' END AS cache_status FROM sys.dm_os_memory_cache_counters WHERE type IN ('CACHESTORE_SQLCP', 'CACHESTORE_OBJCP', 'CACHESTORE_PHDR') ORDER BY pages_kb DESC"}	{"condition": "evictable_entries > entries_in_use_count or total entries > 10000", "description": "Large number of evictable entries or excessive total plan count indicates cache maintenance is insufficient"}	null	2026-02-23 20:18:31.389564
1007	sqlserver	query	Check for any performance baseline collection mechanisms	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.databases\\n   WHERE database_id > 4 AND state_desc = 'ONLINE') AS total_user_databases,\\n  (SELECT COUNT(*)\\n   FROM sys.databases d\\n   JOIN sys.database_query_store_options qso ON d.database_id = DB_ID(d.name)\\n   WHERE d.database_id > 4 AND qso.actual_state_desc = 'READ_WRITE') AS query_store_enabled_count,\\n  (SELECT COUNT(*) FROM sys.dm_exec_query_stats) AS cached_plan_count,\\n  CASE\\n    WHEN (SELECT COUNT(*)\\n          FROM sys.databases d\\n          JOIN sys.database_query_store_options qso ON d.database_id = DB_ID(d.name)\\n          WHERE d.database_id > 4 AND qso.actual_state_desc = 'READ_WRITE') = 0\\n    THEN 'NO_BASELINE — no databases have Query Store enabled for upgrade validation'\\n    ELSE 'PARTIAL_BASELINE — some databases have Query Store, verify coverage'\\n  END AS baseline_assessment"}	{"condition": "baseline_assessment = 'NO_BASELINE'", "description": "No performance baseline data being collected — upgrade success cannot be objectively measured"}	null	2026-02-23 20:18:31.389467
3235	sqlserver	query	Check for SQL authentication without additional hardening	{"sql": "SELECT c.session_id, c.auth_scheme, c.encrypt_option, s.login_name, s.host_name FROM sys.dm_exec_connections c JOIN sys.dm_exec_sessions s ON c.session_id = s.session_id WHERE s.is_user_process = 1"}	{"condition": "windows_auth_only = 0 AND (logins_no_policy > 0 OR unencrypted_endpoints > 0)", "description": "SQL authentication enabled without password policy — port obscurity being used as substitute for real security controls"}	null	2026-02-23 20:18:31.390865
1011	sqlserver	query	Verify absence of plan regression detection capability	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.databases WHERE database_id > 4 AND state_desc = 'ONLINE') AS total_databases,\\n  (SELECT COUNT(*)\\n   FROM sys.databases d\\n   JOIN sys.database_query_store_options qso ON d.database_id = DB_ID(d.name)\\n   WHERE d.database_id > 4\\n     AND qso.actual_state_desc = 'READ_WRITE'\\n     AND qso.current_storage_size_mb >= 1) AS baseline_ready_count,\\n  CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) AS major_version,\\n  CASE\\n    WHEN CAST(SERVERPROPERTY('ProductMajorVersion') AS INT) < 13\\n    THEN 'Query Store not available — requires SQL Server 2016+'\\n    ELSE 'Query Store available but not adequately configured'\\n  END AS assessment_gap"}	{"condition": "baseline_ready_count = 0 or baseline_ready_count < total_databases / 2", "description": "Majority of databases lack upgrade risk assessment instrumentation"}	null	2026-02-23 20:18:31.38947
1012	sqlserver	query	Count databases and assess estate complexity	{"sql": "SELECT\\n  COUNT(*) AS total_user_databases,\\n  SUM(CASE WHEN d.state_desc <> 'ONLINE' THEN 1 ELSE 0 END) AS offline_databases,\\n  COUNT(DISTINCT d.compatibility_level) AS distinct_compat_levels,\\n  MIN(d.compatibility_level) AS oldest_compat_level,\\n  MAX(d.compatibility_level) AS newest_compat_level,\\n  SUM(CAST(mf.size AS BIGINT)) * 8 / 1024 / 1024 AS total_data_size_gb\\nFROM sys.databases d\\nJOIN sys.master_files mf ON d.database_id = mf.database_id AND mf.type = 0\\nWHERE d.database_id > 4"}	{"condition": "total_user_databases > 10 or distinct_compat_levels > 1", "description": "Multiple databases with varying compatibility levels increase upgrade complexity"}	null	2026-02-23 20:18:31.389471
13737	mariadb	query	Check Group Replication certification statistics	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME LIKE 'group_replication%' AND (VARIABLE_NAME LIKE '%conflict%' OR VARIABLE_NAME LIKE '%certif%' OR VARIABLE_NAME LIKE '%rolled_back%')"}	{"condition": "row_count > 0", "description": "Certification conflict counters indicate transaction ordering issues"}	\N	2026-05-11 22:17:39.229791
13738	mariadb	query	Check Group Replication member connectivity	{"sql": "SELECT MEMBER_ID, MEMBER_HOST, MEMBER_PORT, MEMBER_STATE FROM performance_schema.replication_group_members ORDER BY MEMBER_HOST"}	{"condition": "row_count > 0", "description": "Unreachable members indicate network partition"}	\N	2026-05-11 22:17:39.229791
1017	sqlserver	query	Check for proactive health collection mechanisms	{"sql": "SELECT\\n  CASE WHEN EXISTS (SELECT 1 FROM msdb.dbo.sysjobs WHERE name LIKE '%health%' OR name LIKE '%monitor%' OR name LIKE '%check%' AND enabled = 1)\\n    THEN 1 ELSE 0 END AS has_health_jobs,\\n  CASE WHEN EXISTS (SELECT 1 FROM msdb.dbo.sysmail_profile)\\n    THEN 1 ELSE 0 END AS database_mail_configured,\\n  (SELECT COUNT(*) FROM sys.databases d\\n   LEFT JOIN sys.database_query_store_options qso ON d.database_id = DB_ID(d.name)\\n   WHERE d.database_id > 4 AND (qso.actual_state_desc IS NULL OR qso.actual_state_desc = 'OFF')) AS databases_without_query_store,\\n  (SELECT COUNT(*) FROM sys.databases WHERE database_id > 4) AS total_user_databases,\\n  CASE\\n    WHEN NOT EXISTS (SELECT 1 FROM msdb.dbo.sysmail_profile)\\n      AND (SELECT COUNT(*) FROM msdb.dbo.sysalerts WHERE enabled = 1) < 5\\n      AND (SELECT COUNT(*) FROM sys.databases d\\n           JOIN sys.database_query_store_options qso ON d.database_id = DB_ID(d.name)\\n           WHERE d.database_id > 4 AND qso.actual_state_desc = 'READ_WRITE') = 0\\n    THEN 'OVERCONFIDENT — no monitoring, no alerts, no baselines'\\n    ELSE 'SOME_MONITORING'\\n  END AS stability_assessment"}	{"condition": "stability_assessment = 'OVERCONFIDENT'", "description": "No health monitoring infrastructure — stability perception is unfounded, discouraging proactive upgrades"}	null	2026-02-23 20:18:31.389475
1043	sqlserver	query	Check if Query Store has sufficient baseline data	{"sql": "SELECT d.name AS database_name,\\n  qso.actual_state_desc,\\n  qso.current_storage_size_mb,\\n  qso.max_storage_size_mb,\\n  CAST(qso.current_storage_size_mb AS FLOAT) / NULLIF(qso.max_storage_size_mb, 0) * 100 AS pct_used,\\n  qso.stale_query_threshold_days\\nFROM sys.databases d\\nJOIN sys.database_query_store_options qso\\n  ON d.database_id = DB_ID(d.name)\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'\\n  AND d.is_query_store_on = 1\\n  AND (qso.actual_state_desc <> 'READ_WRITE'\\n    OR CAST(qso.current_storage_size_mb AS FLOAT) / NULLIF(qso.max_storage_size_mb, 0) > 0.90\\n    OR qso.stale_query_threshold_days < 14)"}	{"condition": "row_count > 0", "description": "Query Store is near capacity, in wrong state, or has short retention — insufficient for post-patch regression analysis"}	null	2026-02-23 20:18:31.389483
1523	sqlserver	query	Check foreign memory access ratio	{"sql": "SELECT mn.memory_node_id, mn.pages_kb AS local_pages_kb, mn.foreign_committed_kb, mn.target_kb, CASE WHEN mn.foreign_committed_kb > mn.pages_kb * 0.1 THEN 'HIGH_FOREIGN_MEMORY' ELSE 'OK' END AS numa_status FROM sys.dm_os_memory_nodes mn WHERE mn.memory_node_id <> 64"}	{"condition": "foreign_committed_kb > 0 on multiple NUMA nodes", "description": "Foreign memory allocation indicates cross-NUMA access patterns — cache line bouncing likely"}	null	2026-02-23 20:18:31.389495
1138	sqlserver	query	Check for regressed plans and cardinality estimation warnings in cached plans	{"sql": "SELECT TOP 10\\n  qs.plan_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.execution_count,\\n  qp.query_plan.exist('//Warnings/ColumnsWithNoStatistics') AS missing_stats_warning,\\n  qp.query_plan.exist('//Warnings/PlanAffectingConvert') AS implicit_convert_warning,\\n  qp.query_plan.value('(//RelOp/@EstimateRows)[1]', 'float') AS first_op_estimated_rows,\\n  qp.query_plan.value('(//RelOp/@EstimatedRowsRead)[1]', 'float') AS first_op_estimated_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_actual_rows\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 50000\\n  AND qs.execution_count > 3\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "missing_stats_warning = 1 OR implicit_convert_warning = 1 OR first_op_estimated_rows differs > 10x from avg_actual_rows", "description": "Execution plans with missing statistics warnings, implicit conversion warnings, or large estimation errors confirm inadequate cardinality estimation is causing the optimizer to choose buffer-heavy plans"}	null	2026-02-23 20:18:31.389545
1185	sqlserver	query	Check I/O impact of forwarded records	{"sql": "SELECT\\n  OBJECT_NAME(ios.object_id) AS table_name,\\n  ios.forwarded_fetch_count,\\n  ios.leaf_insert_count,\\n  ios.leaf_update_count,\\n  ios.leaf_delete_count,\\n  ios.range_scan_count,\\n  ios.singleton_lookup_count\\nFROM sys.dm_db_index_operational_stats(DB_ID(), NULL, NULL, NULL) ios\\nWHERE ios.forwarded_fetch_count > 100\\nORDER BY ios.forwarded_fetch_count DESC"}	{"condition": "forwarded_fetch_count > 100 on tables with range scans", "description": "Forwarded record fetches causing extra I/O during heap scans"}	null	2026-02-23 20:18:31.389576
1191	sqlserver	query	Check plan cache bucket density and size pressure	{"sql": "SELECT name, type, pages_kb, pages_in_use_kb, entries_count, entries_in_use_count, CAST(pages_in_use_kb * 100.0 / NULLIF(pages_kb, 0) AS DECIMAL(5,1)) AS usage_pct FROM sys.dm_os_memory_cache_counters WHERE type IN ('CACHESTORE_SQLCP', 'CACHESTORE_OBJCP') ORDER BY pages_kb DESC"}	{"condition": "bucket_utilization_pct > 80 OR entries_count > 50000", "description": "High bucket utilization or excessive plan cache entries indicate oversaturated plan cache hash tables, increasing lookup contention"}	null	2026-02-23 20:18:31.38958
1203	sqlserver	query	Check CMEMTHREAD waits and plan cache hash chain density	{"sql": "SELECT cc.name, cc.type, cc.pages_kb, cc.entries_count, (SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats WHERE wait_type = 'CMEMTHREAD') AS cmemthread_wait_ms, (SELECT SUM(waiting_tasks_count) FROM sys.dm_os_wait_stats WHERE wait_type = 'CMEMTHREAD') AS cmemthread_waits FROM sys.dm_os_memory_cache_counters cc WHERE cc.type IN ('CACHESTORE_SQLCP', 'CACHESTORE_OBJCP') ORDER BY cc.pages_kb DESC"}	{"condition": "CMEMTHREAD wait_time_ms > 10000 OR avg_chain_length > 10", "description": "CMEMTHREAD waits or long hash chain lengths indicate plan cache lookups are expensive due to excessive entries per bucket"}	null	2026-02-23 20:18:31.389586
2764	sqlserver	query	Check audit file age and gap after last restart	{"sql": "SELECT a.name AS audit_name, a.type_desc, CASE WHEN a.is_state_enabled = 1 THEN 'ENABLED' ELSE 'DISABLED' END AS status, a.on_failure_desc, a.queue_delay, sfa.log_file_path AS audit_file_path, sfa.max_file_size, sfa.max_rollover_files FROM sys.server_audits a LEFT JOIN sys.server_file_audits sfa ON a.audit_id = sfa.audit_id"}	{"condition": "oldest_audit_event close to last_restart (no historical data survived restart)", "description": "Audit history lost on restart — ephemeral storage confirmed"}	null	2026-02-23 20:18:31.390069
1359	sqlserver	query	Check for THREADPOOL or memory pressure from unconstrained connections	{"sql": "SELECT wait_type, waiting_tasks_count,\\n  wait_time_ms, max_wait_time_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('THREADPOOL', 'RESOURCE_SEMAPHORE',\\n  'CMEMTHREAD', 'SOS_RESERVEDMEMBLOCKLIST')\\n  AND waiting_tasks_count > 0\\nUNION ALL\\nSELECT 'MEMORY_PRESSURE' AS wait_type,\\n  CAST(CASE WHEN CAST(system_low_memory_signal_state AS VARCHAR(10)) = 'Clear' THEN 0 ELSE 1 END AS BIGINT) AS waiting_tasks_count,\\n  CAST(0 AS BIGINT) AS wait_time_ms,\\n  CAST(0 AS BIGINT) AS max_wait_time_ms\\nFROM sys.dm_os_sys_memory\\nORDER BY wait_time_ms DESC"}	{"condition": "THREADPOOL or RESOURCE_SEMAPHORE waits present OR system_low_memory_signal_state is not Clear", "description": "Worker thread exhaustion, memory grant waits, or OS memory pressure signals confirm that the unconstrained connection count has pushed the server beyond its resource capacity"}	null	2026-02-23 20:18:31.389693
1369	sqlserver	query	Check for cardinality estimation issues in TVP query plans	{"sql": "SELECT TOP 20 qs.query_hash, COUNT(*) AS plan_variations, SUM(qs.execution_count) AS total_executions, MAX(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS max_avg_reads, MIN(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS min_avg_reads, SUBSTRING(MIN(st.text), 1, 200) AS sample_query FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st WHERE st.text LIKE '%table%type%' OR st.text LIKE '%TABLE%TYPE%' GROUP BY qs.query_hash HAVING COUNT(*) > 1 ORDER BY COUNT(*) DESC"}	{"condition": "cpu_variance_ratio > 10", "description": "TVP procedures with >10x CPU variance — cardinality misestimation from fixed estimate of 1 row"}	null	2026-02-23 20:18:31.3897
2751	sqlserver	query	Check audit on_failure configuration and recent audit errors	{"sql": "SELECT sa.name, sfa.log_file_path,\\n  sa.on_failure_desc, sa.is_state_enabled,\\n  sa.type_desc AS log_type\\nFROM sys.server_audits sa\\nLEFT JOIN sys.server_file_audits sfa ON sa.audit_id = sfa.audit_id\\nWHERE sa.type_desc = 'FILE'\\n  AND (sa.is_state_enabled = 0\\n    OR sa.on_failure_desc = 'SHUTDOWN')"}	{"condition": "file-based audits that are disabled or configured with SHUTDOWN on failure", "description": "File-based audit disabled or at risk of shutting down server on write failure"}	null	2026-02-23 20:18:31.389725
2752	sqlserver	log_scan	Check error log for audit write failures	{"sql": "CREATE TABLE #log(LogDate DATETIME, ProcessInfo NVARCHAR(50), Text NVARCHAR(MAX)); INSERT INTO #log EXEC xp_readerrorlog 0, 1, N'audit'; INSERT INTO #log EXEC xp_readerrorlog 0, 1, N'Cannot open file'; SELECT * FROM #log ORDER BY LogDate DESC; DROP TABLE #log;", "pattern": "audit|Cannot open file|Access is denied", "description": "Audit file write errors in SQL Server error log"}	{"condition": "error entries related to audit file access", "description": "SQL Server service account cannot write to audit file path"}	null	2026-02-23 20:18:31.389726
1615	sqlserver	query	Check partition-level modification patterns	{"sql": "SELECT OBJECT_SCHEMA_NAME(p.object_id) + '.' + OBJECT_NAME(p.object_id) AS table_name, p.partition_number, p.rows, ps.row_count, ps.in_row_used_page_count * 8 / 1024 AS in_row_mb FROM sys.partitions p JOIN sys.dm_db_partition_stats ps ON p.partition_id = ps.partition_id WHERE p.index_id IN (0, 1) AND p.rows > 0 AND OBJECT_SCHEMA_NAME(p.object_id) NOT IN ('sys') ORDER BY p.rows DESC"}	{"condition": "partitions with high modification_counter and stale last_updated", "description": "Individual partitions with significant data changes but statistics not refreshed"}	null	2026-02-23 20:18:31.38985
