2622	sqlserver	query	Check all non-sa blank-password logins as potential app defaults	{"sql": "SELECT sp.name, sp.create_date,\\n  sl.is_policy_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE PWDCOMPARE('', sl.password_hash) = 1\\n  AND sp.type_desc = 'SQL_LOGIN'\\n  AND sp.name NOT IN ('sa')"}	{"condition": "row_count > 0", "description": "Non-sa SQL logins with blank passwords — application provisioning default suspected"}	null	2026-02-23 20:18:31.390281
1469	sqlserver	query	Find indexes with high scan-to-seek ratio or low selectivity	{"sql": "SELECT TOP 20 OBJECT_SCHEMA_NAME(ius.object_id) + '.' + OBJECT_NAME(ius.object_id) AS table_name, i.name AS index_name, i.type_desc, ius.user_seeks, ius.user_scans, ius.user_lookups, CASE WHEN ius.user_seeks + ius.user_scans = 0 THEN 0 ELSE CAST(ius.user_scans * 100.0 / (ius.user_seeks + ius.user_scans) AS DECIMAL(5,1)) END AS scan_pct FROM sys.dm_db_index_usage_stats ius JOIN sys.indexes i ON ius.object_id = i.object_id AND ius.index_id = i.index_id WHERE ius.database_id = DB_ID() AND i.type_desc <> 'HEAP' AND ius.user_seeks + ius.user_scans > 100 ORDER BY scan_pct DESC"}	{"condition": "max_equal_rows > 10% of table_rows, or user_lookups >> user_seeks", "description": "Indexes where the most common key value covers >10% of the table, or where key lookups vastly exceed seeks, indicate low selectivity"}	null	2026-02-23 20:18:31.389764
1479	sqlserver	query	Check for current blocking chains and lock waits	{"sql": "SELECT\\n  r.session_id,\\n  r.blocking_session_id,\\n  r.wait_type,\\n  r.wait_time AS wait_ms,\\n  r.wait_resource,\\n  r.command,\\n  DB_NAME(r.database_id) AS database_name,\\n  SUBSTRING(st.text, (r.statement_start_offset/2)+1,\\n    ((CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE r.statement_end_offset END - r.statement_start_offset)/2)+1) AS blocked_query,\\n  bs.login_name AS blocker_login,\\n  bst.text AS blocker_query\\nFROM sys.dm_exec_requests r\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nLEFT JOIN sys.dm_exec_sessions bs JOIN sys.dm_exec_connections conn_bs ON bs.session_id = conn_bs.session_id ON r.blocking_session_id = bs.session_id\\nOUTER APPLY sys.dm_exec_sql_text(conn_bs.most_recent_sql_handle) bst\\nWHERE r.blocking_session_id > 0\\nORDER BY r.wait_time DESC"}	{"condition": "blocking chains present with wait_ms > 5000", "description": "Active blocking chains with sessions waiting more than 5 seconds indicate significant lock contention"}	null	2026-02-23 20:18:31.38977
3929	postgresql	query	Check for data loss indicators from wrong bootstrap	{"sql": "SELECT d.datname, sd.xact_commit, sd.xact_rollback FROM pg_database d JOIN pg_stat_database sd ON d.oid = sd.datid WHERE d.datallowconn ORDER BY d.datname"}	{"condition": "row_count > 0", "description": "Transaction counts for verifying data consistency after bootstrap"}	\N	2026-02-25 00:28:52.405273
2767	sqlserver	query	Check audit file size and rollover configuration	{"sql": "SELECT a.name AS audit_name, a.type_desc, CASE WHEN a.is_state_enabled = 1 THEN 'ENABLED' ELSE 'DISABLED' END AS status, a.on_failure_desc, a.queue_delay, sfa.log_file_path AS audit_file_path, sfa.max_file_size, sfa.max_rollover_files FROM sys.server_audits a LEFT JOIN sys.server_file_audits sfa ON a.audit_id = sfa.audit_id"}	{"condition": "max_file_size < 100 OR (max_file_size * max_rollover_files < 1024 AND max_rollover_files > 0)", "description": "Small file size and/or limited rollover — audit data retention too short"}	null	2026-02-23 20:18:31.390071
1487	sqlserver	query	Check OS memory state and RESOURCE_SEMAPHORE waits	{"sql": "SELECT sm.total_physical_memory_kb / 1024 AS total_memory_mb, sm.available_physical_memory_kb / 1024 AS available_memory_mb, sm.system_memory_state_desc, (SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats WHERE wait_type = 'RESOURCE_SEMAPHORE') AS resource_semaphore_wait_ms, (SELECT SUM(waiting_tasks_count) FROM sys.dm_os_wait_stats WHERE wait_type = 'RESOURCE_SEMAPHORE') AS resource_semaphore_waits, pm.physical_memory_in_use_kb / 1024 AS sql_memory_in_use_mb FROM sys.dm_os_sys_memory sm CROSS JOIN sys.dm_os_process_memory pm"}	{"condition": "system_memory_state_desc contains 'Low' or available_physical_mb < 512 or process_physical_memory_low = 1", "description": "Low system memory state or minimal available physical memory confirms memory pressure forcing page faults and swapping"}	null	2026-02-23 20:18:31.389775
