1872	sqlserver	query	Calculate total storage overhead from wide key propagation	{"sql": "SELECT TOP 20 OBJECT_SCHEMA_NAME(i.object_id) + '.' + OBJECT_NAME(i.object_id) AS table_name, i.name AS index_name, SUM(ic.max_length) AS total_key_bytes, COUNT(ic2.column_id) AS key_column_count, ps.reserved_page_count * 8 / 1024 AS index_size_mb FROM sys.indexes i JOIN sys.index_columns ic2 ON i.object_id = ic2.object_id AND i.index_id = ic2.index_id AND ic2.is_included_column = 0 JOIN sys.columns ic ON i.object_id = ic.object_id AND ic2.column_id = ic.column_id JOIN sys.dm_db_partition_stats ps ON i.object_id = ps.object_id AND i.index_id = ps.index_id WHERE i.type = 2 GROUP BY i.object_id, i.name, ps.reserved_page_count HAVING SUM(ic.max_length) > 100 ORDER BY total_key_bytes DESC"}	{"condition": "nc_index_count >= 3 AND clustered_key_bytes > 16", "description": "Wide clustered key propagated across multiple nonclustered indexes — significant per-row overhead"}	null	2026-02-23 20:18:31.390018
1880	sqlserver	query	Check density of leading column to assess selectivity	{"sql": "SELECT TOP 20 OBJECT_SCHEMA_NAME(s.object_id) + '.' + OBJECT_NAME(s.object_id) AS table_name, s.name AS stat_name, COL_NAME(s.object_id, sc.column_id) AS leading_column, sp.rows AS stat_rows, sp.modification_counter, STATS_DATE(s.object_id, s.stats_id) AS last_updated FROM sys.stats s JOIN sys.stats_columns sc ON s.object_id = sc.object_id AND s.stats_id = sc.stats_id AND sc.stats_column_id = 1 CROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp WHERE sp.rows > 0 AND OBJECT_SCHEMA_NAME(s.object_id) NOT IN ('sys') ORDER BY sp.rows DESC"}	{"condition": "all_density > 0.01 AND col_width > 50", "description": "Leading column is both wide and non-selective (density > 1%) — poor seek efficiency with high key width cost"}	null	2026-02-23 20:18:31.390023
2763	sqlserver	query	Check if running in container and audit file path	{"sql": "SELECT\\n  SERVERPROPERTY('ComputerNamePhysicalNetBIOS') AS hostname,\\n  SERVERPROPERTY('MachineName') AS machine_name,\\n  sa.name AS audit_name,\\n  sfa.log_file_path,\\n  sa.type_desc,\\n  sa.is_state_enabled,\\n  (SELECT COUNT(*) FROM sys.dm_os_loaded_modules\\n   WHERE name LIKE '%container%' OR name LIKE '%docker%') AS container_hint\\nFROM sys.server_audits sa\\nLEFT JOIN sys.server_file_audits sfa ON sa.audit_id = sfa.audit_id\\nWHERE sa.type_desc = 'FILE'"}	{"condition": "audit_file_path on non-persistent storage (e.g., /var/opt/mssql/ without mount)", "description": "Audit files stored on ephemeral container filesystem"}	null	2026-02-23 20:18:31.390069
