2024	sqlserver	query	Find long-running transactions with active expensive queries	{"sql": "SELECT t.transaction_id, t.name AS tran_name, t.transaction_begin_time, DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS duration_sec, s.session_id, s.login_name, s.host_name, r.command, r.wait_type, SUBSTRING(st.text, 1, 200) AS sql_text FROM sys.dm_tran_active_transactions t JOIN sys.dm_tran_session_transactions tst ON t.transaction_id = tst.transaction_id JOIN sys.dm_exec_sessions s ON tst.session_id = s.session_id LEFT JOIN sys.dm_exec_requests r ON s.session_id = r.session_id OUTER APPLY sys.dm_exec_sql_text(r.sql_handle) st WHERE t.transaction_begin_time < DATEADD(MINUTE, -5, GETDATE()) ORDER BY t.transaction_begin_time"}	{"condition": "row_count > 0", "description": "Active transactions running over 30 seconds that contain queries consuming significant CPU (>5s) or logical reads (>100K) indicate expensive operations are extending transaction duration"}	null	2026-02-23 20:18:31.390116
2026	sqlserver	query	Find sessions with open transactions waiting on external resources	{"sql": "SELECT s.session_id, DATEDIFF(SECOND, at.transaction_begin_time, GETDATE()) AS transaction_duration_sec, s.status AS session_status, r.wait_type, r.wait_time AS wait_time_ms, r.last_wait_type, s.program_name, s.host_name, st.text AS last_sql FROM sys.dm_tran_active_transactions at JOIN sys.dm_tran_session_transactions tst ON at.transaction_id = tst.transaction_id JOIN sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id ON s.session_id = tst.session_id LEFT JOIN sys.dm_exec_requests r ON r.session_id = s.session_id OUTER APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) st WHERE at.transaction_type = 1 AND DATEDIFF(SECOND, at.transaction_begin_time, GETDATE()) > 30 AND (r.wait_type IN ('ASYNC_NETWORK_IO', 'OLEDB', 'CLR_AUTO_EVENT', 'CLR_MANUAL_EVENT', 'PREEMPTIVE_OS_WAITFORSINGLEOBJECT', 'PREEMPTIVE_OS_PIPEOPS', 'PREEMPTIVE_HTTP_EVENT_WAIT') OR s.status = 'sleeping') ORDER BY transaction_duration_sec DESC"}	{"condition": "row_count > 0 AND session has open transaction with external wait type or sleeping status", "description": "Sessions with open transactions waiting on external I/O types (OLEDB for linked servers, CLR events, ASYNC_NETWORK_IO for client processing, PREEMPTIVE waits for OS calls) or sleeping while holding a transaction indicate external operations are extending transaction duration"}	null	2026-02-23 20:18:31.390117
2028	sqlserver	query	Find sleeping sessions with open transactions and idle duration	{"sql": "SELECT s.session_id, DATEDIFF(SECOND, at.transaction_begin_time, GETDATE()) AS transaction_duration_sec, DATEDIFF(SECOND, s.last_request_end_time, GETDATE()) AS idle_since_last_request_sec, s.open_transaction_count, s.status, s.program_name, s.host_name, s.login_name, st.text AS last_sql FROM sys.dm_tran_active_transactions at JOIN sys.dm_tran_session_transactions tst ON at.transaction_id = tst.transaction_id JOIN sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id ON s.session_id = tst.session_id OUTER APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) st WHERE at.transaction_type = 1 AND s.status = 'sleeping' AND s.open_transaction_count > 0 AND DATEDIFF(SECOND, s.last_request_end_time, GETDATE()) > 10 ORDER BY idle_since_last_request_sec DESC"}	{"condition": "row_count > 0 AND idle_since_last_request_sec > 10", "description": "Sleeping sessions with open transactions that have been idle for more than 10 seconds indicate the application is performing processing between SQL commands while holding the transaction open"}	null	2026-02-23 20:18:31.390118
2030	sqlserver	query	Find sessions with implicit transactions enabled	{"sql": "SELECT s.session_id, CASE WHEN (@@OPTIONS & 2) = 2 THEN 1 ELSE 0 END AS implicit_transactions_on, s.status, s.open_transaction_count, s.program_name, s.host_name, s.login_name, DATEDIFF(SECOND, s.last_request_end_time, GETDATE()) AS idle_seconds, st.text AS last_sql FROM sys.dm_exec_sessions s\\nJOIN sys.dm_exec_connections c ON s.session_id = c.session_id OUTER APPLY sys.dm_exec_sql_text(c.most_recent_sql_handle) st WHERE s.is_user_process = 1 AND s.open_transaction_count > 0 AND s.status = 'sleeping' ORDER BY s.open_transaction_count DESC"}	{"condition": "row_count > 0 AND sessions have open_transaction_count > 0 while sleeping", "description": "Sleeping sessions with open transactions may have IMPLICIT_TRANSACTIONS ON, causing every statement to begin a transaction that the application never explicitly commits"}	null	2026-02-23 20:18:31.39012
2049	sqlserver	query	Check memory grant details and resource pool configuration	{"sql": "SELECT mg.session_id, mg.granted_memory_kb, mg.used_memory_kb, mg.required_memory_kb, mg.ideal_memory_kb, mg.max_used_memory_kb, mg.grant_time, mg.query_cost, rp.name AS resource_pool, SUBSTRING(st.text, 1, 200) AS query_text FROM sys.dm_exec_query_memory_grants mg CROSS APPLY sys.dm_exec_sql_text(mg.sql_handle) st LEFT JOIN sys.resource_governor_resource_pools rp ON mg.pool_id = rp.pool_id"}	{"condition": "queries waiting with no grant_time and large requested_mb", "description": "Specific queries queued for memory grants"}	null	2026-02-23 20:18:31.390132
