2678	sqlserver	query	Check if SQL logins use connection string patterns typical of dev environments	{"sql": "SELECT sp.name, sp.create_date,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s\\n   WHERE s.login_name = sp.name\\n     AND (s.program_name LIKE '%Visual Studio%' OR s.program_name LIKE '%SSMS%'\\n       OR s.program_name LIKE '%debug%' OR s.program_name LIKE '%localhost%'\\n       OR s.program_name LIKE '%DevTools%')) AS dev_tool_sessions,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions s\\n   WHERE s.login_name = sp.name AND s.is_user_process = 1) AS total_sessions\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\n  AND SERVERPROPERTY('IsIntegratedSecurityOnly') = 0"}	{"condition": "SQL logins with development tool sessions or dev-named logins present", "description": "Mixed Mode with development-style usage indicates dev/prod parity as the driver"}	null	2026-02-23 20:18:31.390534
2681	sqlserver	query	Check for service-account-pattern SQL logins in Mixed Mode	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  sp.name, sp.type_desc, sp.create_date,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE()) AS password_age_days,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE login_name = sp.name AND is_user_process = 1) AS active_sessions\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE SERVERPROPERTY('IsIntegratedSecurityOnly') = 0\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\n  AND (sp.name LIKE '%svc%' OR sp.name LIKE '%service%' OR sp.name LIKE '%app%'\\n    OR sp.name LIKE '%api%' OR sp.name LIKE '%web%' OR sp.name LIKE '%batch%'\\n    OR sp.name LIKE '%etl%' OR sp.name LIKE '%job%')"}	{"condition": "row_count > 0 with password_age_days > 365", "description": "Service-account SQL logins with stale passwords — passwords likely hardcoded in connection strings"}	null	2026-02-23 20:18:31.390536
2684	sqlserver	query	Check for recent SQL login creation indicating ongoing use	{"sql": "SELECT sp.name, sp.create_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  sl.is_policy_checked, sl.is_expiration_checked\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\n  AND DATEDIFF(DAY, sp.create_date, GETDATE()) < 365\\nORDER BY sp.create_date DESC"}	{"condition": "SQL logins created within the past year", "description": "New SQL logins still being created — no policy prevents SQL Authentication usage"}	null	2026-02-23 20:18:31.390538
3158	sqlserver	query	Check for workload patterns sensitive to tempdb performance	{"sql": "SELECT SUM(fsu.user_object_reserved_page_count) * 8 / 1024 AS user_objects_mb, SUM(fsu.internal_object_reserved_page_count) * 8 / 1024 AS internal_objects_mb, SUM(fsu.version_store_reserved_page_count) * 8 / 1024 AS version_store_mb, SUM(fsu.unallocated_extent_page_count) * 8 / 1024 AS free_mb, (SELECT COUNT(*) FROM sys.master_files WHERE database_id = 2 AND type_desc = 'ROWS') AS tempdb_data_files FROM tempdb.sys.dm_db_file_space_usage fsu"}	{"condition": "total_tempdb_alloc_pages > 100000 OR active_tempdb_sessions > 50", "description": "Heavy tempdb usage — TDE enabling would encrypt tempdb and potentially impact performance"}	null	2026-02-23 20:18:31.390819
2685	sqlserver	query	Check for SQL logins with sysadmin or high-privilege roles in Mixed Mode	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  sp.name, sp.type_desc,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin,\\n  IS_SRVROLEMEMBER('securityadmin', sp.name) AS is_securityadmin,\\n  IS_SRVROLEMEMBER('serveradmin', sp.name) AS is_serveradmin,\\n  sl.is_policy_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS active_sessions\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE SERVERPROPERTY('IsIntegratedSecurityOnly') = 0\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND (IS_SRVROLEMEMBER('sysadmin', sp.name) = 1\\n    OR IS_SRVROLEMEMBER('securityadmin', sp.name) = 1\\n    OR IS_SRVROLEMEMBER('serveradmin', sp.name) = 1)"}	{"condition": "row_count > 0", "description": "Privileged SQL logins in Mixed Mode — credentials can be captured and replayed for lateral movement"}	null	2026-02-23 20:18:31.390538
2701	sqlserver	query	Check for project-pattern or temporary logins still enabled	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date, sp.modify_date,\\n  sp.is_disabled,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS account_age_days,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  CASE WHEN sp.type = 'S'\\n    THEN sl.is_expiration_checked ELSE NULL END AS has_expiration,\\n  CASE WHEN sp.type = 'S'\\n    THEN LOGINPROPERTY(sp.name, 'DaysUntilExpiration') ELSE NULL END AS days_until_expiry\\nFROM sys.server_principals sp\\nLEFT JOIN sys.sql_logins sl ON sp.principal_id = sl.principal_id\\nWHERE sp.type IN ('S', 'U')\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND (sp.name LIKE '%proj%' OR sp.name LIKE '%project%' OR sp.name LIKE '%migration%'\\n    OR sp.name LIKE '%temp%' OR sp.name LIKE '%tmp%' OR sp.name LIKE '%pilot%'\\n    OR sp.name LIKE '%poc%' OR sp.name LIKE '%trial%' OR sp.name LIKE '%phase%')"}	{"condition": "project-pattern accounts older than 180 days still enabled", "description": "Temporary project logins remain enabled long after likely project completion"}	null	2026-02-23 20:18:31.390549
2771	sqlserver	query	Check audit destination and retention configuration	{"sql": "SELECT a.name AS audit_name, a.type_desc, CASE WHEN a.is_state_enabled = 1 THEN 'ENABLED' ELSE 'DISABLED' END AS status, a.on_failure_desc, a.queue_delay, sfa.log_file_path AS audit_file_path, sfa.max_file_size, sfa.max_rollover_files FROM sys.server_audits a LEFT JOIN sys.server_file_audits sfa ON a.audit_id = sfa.audit_id"}	{"condition": "destination = FILE with local path and no evidence of external shipping", "description": "Audit files stored locally only — at risk of loss from disk failure, breach, or tampering"}	null	2026-02-23 20:18:31.390574
2828	sqlserver	query	Check for deployment tool sessions performing DDL	{"sql": "SELECT s.program_name, s.login_name, s.host_name,\\n  COUNT(*) AS session_count,\\n  c.auth_scheme\\nFROM sys.dm_exec_sessions s LEFT JOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND (s.program_name LIKE '%SQLAgent%'\\n    OR s.program_name LIKE '%SQLCMD%'\\n    OR s.program_name LIKE '%dacfx%'\\n    OR s.program_name LIKE '%DacServices%'\\n    OR s.program_name LIKE '%Deploy%'\\n    OR s.program_name LIKE '%Octopus%'\\n    OR s.program_name LIKE '%TeamCity%'\\n    OR s.program_name LIKE '%Azure DevOps%')\\nGROUP BY s.program_name, s.login_name, s.host_name, c.auth_scheme"}	{"condition": "deployment tool sessions found", "description": "Automated deployment tools are executing SQL — their DDL changes may not be audited if audit is scoped by principal"}	null	2026-02-23 20:18:31.390608
2702	sqlserver	query	Check for SQL logins without password expiration that have no recent activity	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date,\\n  sl.is_expiration_checked,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS account_age_days,\\n  DATEDIFF(DAY, sp.modify_date, GETDATE()) AS days_since_modified,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\n  AND sl.is_expiration_checked = 0\\n  AND (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) IS NULL\\n  AND DATEDIFF(DAY, sp.modify_date, GETDATE()) > 90"}	{"condition": "non-expiring SQL logins with no recent sessions and inactive > 90 days", "description": "SQL logins without expiration and no recent use — temporary access likely never revoked"}	null	2026-02-23 20:18:31.39055
