2729	sqlserver	query	Check for inconsistent hardening across security settings	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_only_auth,\\n  (SELECT is_disabled FROM sys.server_principals WHERE name = 'sa') AS sa_disabled,\\n  (SELECT COUNT(*) FROM sys.sql_logins sl\\n   JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\n   WHERE sp.is_disabled = 0 AND sl.is_policy_checked = 0\\n     AND sp.name NOT LIKE '##%') AS logins_no_policy,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'cross db ownership chaining') AS cross_db_chaining,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'clr enabled') AS clr_enabled,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'xp_cmdshell') AS xp_cmdshell,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'Ole Automation Procedures') AS ole_automation,\\n  (SELECT COUNT(*) FROM sys.server_audits WHERE is_state_enabled = 1) AS active_audits"}	{"condition": "some settings hardened but others left at defaults (e.g., sa disabled but xp_cmdshell enabled, or audit enabled but cross_db_chaining on)", "description": "Inconsistent hardening — some security controls applied but others missed, indicating incomplete documentation"}	null	2026-02-23 20:18:31.390565
2734	sqlserver	query	Check for SQL auth connections from container-pattern hostnames	{"sql": "SELECT s.login_name, s.host_name, s.program_name,\\n  COUNT(*) AS session_count,\\n  MIN(s.login_time) AS earliest_login,\\n  MAX(s.login_time) AS latest_login,\\n  c.auth_scheme\\nFROM sys.dm_exec_sessions s LEFT JOIN sys.dm_exec_connections c ON s.session_id = c.session_id\\nWHERE s.is_user_process = 1\\n  AND (s.host_name LIKE '%-%-%-%-%' -- UUID-style container names\\n    OR s.host_name LIKE 'ip-%'\\n    OR LEN(s.host_name) > 30\\n    OR s.host_name LIKE '%-deployment-%'\\n    OR s.host_name LIKE 'pod-%')\\n  AND c.auth_scheme = 'SQL'\\nGROUP BY s.login_name, s.host_name, s.program_name, c.auth_scheme\\nORDER BY session_count DESC"}	{"condition": "SQL auth sessions from container/pod hostnames", "description": "Container workloads connecting with SQL authentication — credentials likely stored in environment variables or configmaps"}	null	2026-02-23 20:18:31.390568
