3092	sqlserver	query	Check for linked servers with RPC out and stored credentials	{"sql": "SELECT s.name AS linked_server_name,\\n  s.data_source,\\n  s.is_rpc_out_enabled,\\n  s.is_data_access_enabled,\\n  ll.remote_name,\\n  ll.uses_self_credential,\\n  CASE WHEN ll.local_principal_id = 0 THEN 'DEFAULT_MAPPING' ELSE 'SPECIFIC_LOGIN' END AS mapping_scope,\\n  CASE\\n    WHEN s.is_rpc_out_enabled = 1 AND ll.uses_self_credential = 0 AND ll.remote_name IS NOT NULL\\n      THEN 'ESCALATION_RISK: RPC + stored credential'\\n    ELSE 'LIMITED_RISK'\\n  END AS risk_assessment\\nFROM sys.servers s\\nJOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nWHERE s.is_linked = 1\\n  AND s.is_rpc_out_enabled = 1\\n  AND ll.uses_self_credential = 0\\n  AND ll.remote_name IS NOT NULL"}	{"condition": "linked servers with RPC out enabled and stored remote credentials", "description": "RPC out allows EXECUTE AT on remote server using stored credential — privilege escalation possible"}	null	2026-02-23 20:18:31.390782
3105	sqlserver	query	Check if multiple distinct users access linked servers via default mapping	{"sql": "SELECT s.name AS linked_server, COUNT(DISTINCT qs_login.login_name) AS distinct_users_using_linked_server, STRING_AGG(qs_login.login_name, ', ') AS login_names FROM sys.servers s JOIN sys.linked_logins ll ON s.server_id = ll.server_id CROSS APPLY (SELECT DISTINCT sess.login_name FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st CROSS APPLY (SELECT TOP 1 es.login_name FROM sys.dm_exec_sessions es WHERE es.session_id = qs.plan_handle) sess WHERE st.text LIKE '%' + s.name + '%' OR st.text LIKE '%OPENQUERY%' + s.name + '%') qs_login WHERE s.is_linked = 1 AND ll.local_principal_id = 0 AND ll.remote_name IS NOT NULL GROUP BY s.name HAVING COUNT(DISTINCT qs_login.login_name) > 1"}	{"condition": "multiple distinct logins accessing linked server through shared default mapping", "description": "Different users share a single remote credential on the linked server — actions cannot be attributed to individual users"}	null	2026-02-23 20:18:31.390792
2932	sqlserver	query	Check for old accounts with sysadmin that also have explicit bulk/assembly grants	{"sql": "SELECT sp.name AS login_name, sp.create_date, DATEDIFF(DAY, sp.create_date, GETDATE()) AS account_age_days, (SELECT STRING_AGG(r.name, ', ') FROM (SELECT DISTINCT sr.name FROM sys.server_role_members srm2 JOIN sys.server_principals sr ON srm2.role_principal_id = sr.principal_id AND sr.type = 'R' WHERE srm2.member_principal_id = sp.principal_id) r) AS server_roles, (SELECT STRING_AGG(p.permission_name, ', ') FROM (SELECT DISTINCT perm.permission_name FROM sys.server_permissions perm WHERE perm.grantee_principal_id = sp.principal_id AND perm.state_desc = 'GRANT' AND perm.permission_name IN ('ADMINISTER BULK OPERATIONS', 'EXTERNAL ACCESS ASSEMBLY', 'UNSAFE ASSEMBLY', 'CONTROL SERVER')) p) AS explicit_permissions FROM sys.server_principals sp LEFT JOIN sys.server_role_members srm ON sp.principal_id = srm.member_principal_id LEFT JOIN sys.server_principals sr ON srm.role_principal_id = sr.principal_id AND sr.type = 'R' LEFT JOIN sys.server_permissions perm ON sp.principal_id = perm.grantee_principal_id AND perm.state_desc = 'GRANT' AND perm.permission_name IN ('ADMINISTER BULK OPERATIONS', 'EXTERNAL ACCESS ASSEMBLY', 'UNSAFE ASSEMBLY', 'CONTROL SERVER') WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND sp.name NOT IN ('sa') AND sp.type IN ('S', 'U', 'G') AND (sr.name IN ('sysadmin', 'bulkadmin') OR perm.permission_name IS NOT NULL) GROUP BY sp.name, sp.create_date, sp.principal_id HAVING COUNT(DISTINCT COALESCE(sr.name, '')) + COUNT(DISTINCT COALESCE(perm.permission_name, '')) > 2"}	{"condition": "row_count > 0", "description": "Accounts with redundant overlapping privilege grants — sysadmin already includes bulkadmin and assembly rights, yet explicit grants also exist"}	null	2026-02-23 20:18:31.390679
3199	sqlserver	query	Check for Extended Events sessions tracking TLS/connection details	{"sql": "SELECT s.name AS session_name, se.event_name FROM sys.dm_xe_sessions s JOIN sys.dm_xe_session_events se ON s.address = se.event_session_address"}	{"condition": "row_count = 0", "description": "No Extended Events session tracking TLS handshakes or connection cipher details"}	null	2026-02-23 20:18:31.390734
3088	sqlserver	query	Check linked server credentials for overprivileged remote accounts	{"sql": "SELECT s.name AS linked_server_name,\\n  s.data_source,\\n  s.product,\\n  ll.remote_name,\\n  CASE\\n    WHEN ll.remote_name IN ('sa', 'SA', 'dbo') THEN 'CRITICAL_OVERPRIVILEGED'\\n    WHEN ll.remote_name LIKE '%admin%' OR ll.remote_name LIKE '%sysadmin%'\\n      OR ll.remote_name LIKE '%root%' OR ll.remote_name LIKE '%superuser%'\\n      THEN 'LIKELY_OVERPRIVILEGED'\\n    ELSE 'CHECK_REMOTE_PERMISSIONS'\\n  END AS privilege_assessment,\\n  CASE WHEN ll.local_principal_id = 0 THEN 'DEFAULT_FOR_ALL' ELSE 'SPECIFIC_LOGIN' END AS mapping_scope\\nFROM sys.servers s\\nJOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nWHERE s.is_linked = 1\\n  AND ll.uses_self_credential = 0\\n  AND ll.remote_name IS NOT NULL"}	{"condition": "linked servers use remote accounts named sa, admin, or similar high-privilege patterns", "description": "Linked server credentials map to high-privilege remote accounts — violates least-privilege principle"}	null	2026-02-23 20:18:31.390778
3086	sqlserver	query	Check for linked servers with stored credentials	{"sql": "SELECT s.name AS linked_server_name,\\n  s.product,\\n  s.provider,\\n  s.data_source,\\n  ll.uses_self_credential,\\n  ll.remote_name,\\n  CASE\\n    WHEN ll.uses_self_credential = 0 AND ll.remote_name IS NOT NULL THEN 'STATIC_CREDENTIAL'\\n    WHEN ll.uses_self_credential = 1 THEN 'SELF_MAPPING'\\n    ELSE 'NO_CREDENTIAL'\\n  END AS credential_type\\nFROM sys.servers s\\nJOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nWHERE s.is_linked = 1\\n  AND ll.uses_self_credential = 0\\n  AND ll.remote_name IS NOT NULL"}	{"condition": "linked servers with static credentials (uses_self_credentials = 0 with remote_name mapped)", "description": "Linked servers store static credentials in SQL Server metadata — credentials are not encrypted at rest and can be extracted"}	null	2026-02-23 20:18:31.390777
3087	sqlserver	query	Check scope of static credential exposure	{"sql": "SELECT s.name AS linked_server_name,\\n  s.data_source,\\n  ll.remote_name AS stored_remote_login,\\n  sp.name AS local_login_mapped,\\n  sp.type_desc AS login_type,\\n  CASE WHEN ll.local_principal_id = 0 THEN 'DEFAULT_MAPPING_ALL_LOGINS' ELSE 'SPECIFIC_LOGIN' END AS mapping_scope\\nFROM sys.servers s\\nJOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nLEFT JOIN sys.server_principals sp ON ll.local_principal_id = sp.principal_id\\nWHERE s.is_linked = 1\\n  AND ll.uses_self_credential = 0\\n  AND ll.remote_name IS NOT NULL\\nORDER BY s.name, mapping_scope"}	{"condition": "static credentials mapped, especially DEFAULT_MAPPING_ALL_LOGINS", "description": "Static credentials stored for linked server access — default mappings expose credentials to all local logins"}	null	2026-02-23 20:18:31.390778
3089	sqlserver	query	Check linked server RPC and data access capabilities indicating broad privileges	{"sql": "SELECT s.name AS linked_server_name,\\n  s.data_source,\\n  s.is_rpc_out_enabled,\\n  s.is_data_access_enabled,\\n  s.is_remote_login_enabled,\\n  ll.remote_name,\\n  CASE\\n    WHEN s.is_rpc_out_enabled = 1 AND s.is_data_access_enabled = 1\\n      THEN 'FULL_ACCESS - RPC + data access enabled'\\n    WHEN s.is_rpc_out_enabled = 1\\n      THEN 'RPC_ENABLED - can execute remote procedures'\\n    WHEN s.is_data_access_enabled = 1\\n      THEN 'DATA_ACCESS - can query remote data'\\n    ELSE 'RESTRICTED'\\n  END AS access_level\\nFROM sys.servers s\\nJOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nWHERE s.is_linked = 1\\n  AND ll.uses_self_credential = 0\\n  AND ll.remote_name IS NOT NULL\\n  AND (s.is_rpc_out_enabled = 1 OR s.is_data_access_enabled = 1)"}	{"condition": "linked servers with both RPC and data access enabled using stored credentials", "description": "Linked servers with full access capabilities and stored credentials — overprivileged access to remote servers"}	null	2026-02-23 20:18:31.390779
3090	sqlserver	query	Check for linked servers with default (rootcause) login mappings	{"sql": "SELECT s.name AS linked_server_name,\\n  s.data_source,\\n  s.product,\\n  ll.local_principal_id,\\n  CASE WHEN ll.local_principal_id = 0 THEN 'DEFAULT_MAPPING_ALL_USERS' ELSE sp.name END AS local_login,\\n  ll.uses_self_credential,\\n  ll.remote_name,\\n  CASE\\n    WHEN ll.local_principal_id = 0 AND ll.uses_self_credential = 0 AND ll.remote_name IS NOT NULL\\n      THEN 'CRITICAL: All local logins map to single remote credential'\\n    WHEN ll.local_principal_id = 0 AND ll.uses_self_credential = 1\\n      THEN 'WARNING: All local logins pass through their own credentials'\\n    WHEN ll.local_principal_id = 0 AND ll.remote_name IS NULL\\n      THEN 'DEFAULT: Connections not made (no mapping)'\\n    ELSE 'SPECIFIC: Individual login mapping'\\n  END AS exposure_level\\nFROM sys.servers s\\nJOIN sys.linked_logins ll ON s.server_id = ll.server_id\\nLEFT JOIN sys.server_principals sp ON ll.local_principal_id = sp.principal_id\\nWHERE s.is_linked = 1"}	{"condition": "linked servers with local_principal_id = 0 (default mapping) and uses_self_credentials = 0 with a remote_name", "description": "Default mapping sends all local logins to the remote server using a shared credential — any database user can access the linked server"}	null	2026-02-23 20:18:31.39078
