3351	sqlserver	query	Check Extended Events query duration thresholds	{"sql": "IF OBJECT_ID('sys.dm_xe_session_event_predicates') IS NOT NULL\\nBEGIN\\nSELECT ses.name AS session_name,\\n  sese.event_name,\\n  sesef.name AS filter_field,\\n  sesef.operator,\\n  sesef.value AS threshold_value\\nFROM sys.dm_xe_sessions ses\\nJOIN sys.dm_xe_session_events sese ON ses.address = sese.event_session_address\\nLEFT JOIN sys.dm_xe_session_event_actions sesea ON sese.event_session_address = sesea.event_session_address\\n  AND sese.event_name = sesea.event_name\\nOUTER APPLY (\\n  SELECT p.name, p.operator, p.value\\n  FROM sys.dm_xe_session_event_predicates p\\n  WHERE p.event_session_address = sese.event_session_address\\n    AND p.event_name = sese.event_name\\n) sesef\\nWHERE sese.event_name IN ('sql_batch_completed', 'sql_statement_completed',\\n  'rpc_completed', 'query_post_execution_showplan',\\n  'query_post_compilation_showplan')\\nORDER BY ses.name, sese.event_name\\nEND\\nELSE\\nBEGIN\\nSELECT NULL AS not_available WHERE 1=0\\nEND"}	{"condition": "query events with no duration filter or very low threshold (< 1000000 microseconds)", "description": "XE query events without duration predicates or with sub-second thresholds capture nearly all queries including fast PII lookups"}	null	2026-02-23 20:18:31.390932
3446	postgresql	query	Check backup user role attributes	{"sql": "SELECT rolname, rolsuper, rolreplication, rolcreatedb FROM pg_roles WHERE rolname = current_user"}	{"condition": "rolsuper = true OR rolreplication = true", "description": "Backup user should have SUPERUSER or REPLICATION privilege for pg_basebackup"}	{"backup_user": "postgres"}	2026-02-25 00:28:52.405273
3748	postgresql	query	Check XID age advancement vs oldest active transaction	{"sql": "SELECT datname, age(datfrozenxid) AS db_xid_age, (SELECT backend_xmin::text FROM pg_stat_activity WHERE backend_xmin IS NOT NULL ORDER BY age(backend_xmin) DESC LIMIT 1) AS oldest_xmin, (SELECT age(backend_xmin) FROM pg_stat_activity WHERE backend_xmin IS NOT NULL ORDER BY age(backend_xmin) DESC LIMIT 1) AS oldest_xmin_age FROM pg_database WHERE datname = current_database()"}	{"condition": "oldest_xmin_age > 100000", "description": "Old backend_xmin confirms long-running transactions preventing freeze advancement"}	\N	2026-02-25 00:28:52.405273
3757	postgresql	query	Check transaction rate from pg_stat_database	{"sql": "SELECT d.datname, sd.xact_commit + sd.xact_rollback AS total_xacts, sd.xact_commit, sd.xact_rollback, age(d.datfrozenxid) AS xid_age, (SELECT setting::bigint FROM pg_settings WHERE name = 'autovacuum_freeze_max_age') AS freeze_max_age FROM pg_database d JOIN pg_stat_database sd ON d.oid = sd.datid WHERE d.datallowconn ORDER BY sd.xact_commit + sd.xact_rollback DESC"}	{"condition": "total_xacts > 1000000", "description": "High transaction volume databases consume XIDs rapidly"}	\N	2026-02-25 00:28:52.405273
3793	postgresql	query	Check if any integrity monitoring is configured	{"sql": "SELECT d.datname, sd.checksum_failures, sd.checksum_last_failure, sd.stats_reset FROM pg_database d JOIN pg_stat_database sd ON d.oid = sd.datid WHERE d.datallowconn ORDER BY d.datname"}	{"condition": "row_count > 0", "description": "Baseline integrity statistics available for monitoring"}	\N	2026-02-25 00:28:52.405273
3825	postgresql	query	Check replication conflict statistics	{"sql": "SELECT datname, confl_tablespace, confl_lock, confl_snapshot, confl_bufferpin, confl_deadlock FROM pg_stat_database_conflicts WHERE (confl_lock + confl_snapshot + confl_bufferpin) > 0 ORDER BY (confl_lock + confl_snapshot + confl_bufferpin) DESC"}	{"condition": "row_count > 0", "description": "Replication conflicts indicate standby queries interfering with WAL replay"}	\N	2026-02-25 00:28:52.405273
4122	postgresql	query	Verify no WAL senders for the disconnected slot	{"sql": "SELECT s.slot_name, r.pid AS sender_pid, r.state FROM pg_replication_slots s LEFT JOIN pg_stat_replication r ON s.active_pid = r.pid WHERE s.active = false AND r.pid IS NULL"}	{"condition": "row_count > 0", "description": "Slot without corresponding WAL sender confirms replica is down"}	\N	2026-02-25 00:28:52.405273
4160	postgresql	query	Find orphaned logical slots	{"sql": "SELECT s.slot_name, s.plugin, s.active, s.restart_lsn, pg_wal_lsn_diff(pg_current_wal_lsn(), s.restart_lsn) AS retained_bytes FROM pg_replication_slots s LEFT JOIN pg_stat_replication r ON s.active_pid = r.pid WHERE s.slot_type = 'logical' AND s.active = false AND r.pid IS NULL"}	{"condition": "row_count > 0", "description": "Logical slot with no active consumer or subscription"}	\N	2026-02-25 00:28:52.405273
4647	postgresql	query	Check current server version and compatibility-relevant settings	{"sql": "SELECT current_setting('server_version') AS version, current_setting('server_version_num')::int AS version_num, d.datcollate AS lc_collate, current_setting('server_encoding') AS encoding FROM pg_database d WHERE d.datname = current_database()"}	{"condition": "row_count > 0", "description": "Record current version and locale settings; PostgreSQL 15+ changed default collation provider to ICU, requiring locale migration before upgrading from pre-15 versions"}	\N	2026-02-25 00:28:52.405273
7882	oracle	query	ora_check_stale_table_statistics	{"sql": "SELECT owner, table_name, num_rows, last_analyzed, stale_stats, stattype_locked FROM ALL_TAB_STATISTICS WHERE stale_stats = 'YES' AND owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP', 'OUTLN', 'MDSYS', 'XDB') ORDER BY num_rows DESC FETCH FIRST 30 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with stale statistics cause optimizer to make poor selectivity estimates"}	\N	2026-02-28 12:19:19.580455
4889	postgresql	query	Find skewed columns commonly used in GROUP BY	{"sql": "SELECT s.schemaname, s.tablename, s.attname, s.n_distinct, array_length(string_to_array(s.most_common_vals::text, ','), 1) AS mcv_count FROM pg_stats s WHERE s.most_common_freqs IS NOT NULL AND s.most_common_freqs[1] > :skew_threshold AND s.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY s.most_common_freqs[1] DESC LIMIT 15"}	{"condition": "most_common_freqs[1] > 0.1", "description": "Columns where the most common value exceeds 10% frequency cause aggregation skew"}	{"skew_threshold": 0.1}	2026-02-25 00:28:52.405273
4906	postgresql	query	Check statistics staleness for commonly filtered columns	{"sql": "SELECT s.schemaname, s.tablename, s.attname, s.n_distinct, s.null_frac, array_length(string_to_array(s.most_common_vals::text, ','), 1) AS mcv_count, array_length(string_to_array(s.histogram_bounds::text, ','), 1) AS histogram_buckets FROM pg_stats s JOIN pg_stat_user_tables t ON s.schemaname = t.schemaname AND s.tablename = t.relname WHERE t.n_mod_since_analyze > :mod_threshold AND s.histogram_bounds IS NOT NULL AND s.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY t.n_mod_since_analyze DESC LIMIT 15"}	{"condition": "row_count > 0", "description": "Columns with histograms on tables with high modification counts have potentially stale distribution data"}	{"mod_threshold": 10000}	2026-02-25 00:28:52.405273
4910	postgresql	query	Check for stale histogram boundaries on modified tables	{"sql": "SELECT s.schemaname, s.tablename, s.attname, (string_to_array(s.histogram_bounds::text, ','))[1] AS hist_min, (string_to_array(s.histogram_bounds::text, ','))[array_length(string_to_array(s.histogram_bounds::text, ','), 1)] AS hist_max, t.n_mod_since_analyze FROM pg_stats s JOIN pg_stat_user_tables t ON s.schemaname = t.schemaname AND s.tablename = t.relname WHERE s.histogram_bounds IS NOT NULL AND t.n_mod_since_analyze > :mod_threshold AND s.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY t.n_mod_since_analyze DESC LIMIT 15"}	{"condition": "row_count > 0 AND n_mod_since_analyze > mod_threshold", "description": "Histograms on heavily modified tables may have min/max boundaries that no longer reflect actual data range"}	{"mod_threshold": 50000}	2026-02-25 00:28:52.405273
4920	postgresql	query	Check histogram bounds on timestamp columns	{"sql": "SELECT s.schemaname, s.tablename, s.attname, (string_to_array(s.histogram_bounds::text, ','))[array_length(string_to_array(s.histogram_bounds::text, ','), 1)] AS hist_max, t.last_analyze, t.last_autoanalyze, t.n_mod_since_analyze FROM pg_stats s JOIN pg_stat_user_tables t ON s.schemaname = t.schemaname AND s.tablename = t.relname JOIN pg_attribute a ON a.attrelid = (SELECT oid FROM pg_class WHERE relname = s.tablename) AND a.attname = s.attname JOIN pg_type tp ON a.atttypid = tp.oid WHERE tp.typname IN ('timestamp', 'timestamptz', 'date') AND s.histogram_bounds IS NOT NULL AND s.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY t.n_mod_since_analyze DESC LIMIT 10"}	{"condition": "hist_max significantly behind current date", "description": "Timestamp histogram maximum behind current data range causes underestimation of recent queries"}	\N	2026-02-25 00:28:52.405273
4931	postgresql	query	Check block read timing if enabled	{"sql": "SELECT datname, blks_read, blk_read_time, CASE WHEN blks_read > 0 THEN ROUND((blk_read_time / blks_read)::numeric, 2) ELSE 0 END AS avg_read_ms FROM pg_stat_database WHERE datname = current_database() AND blk_read_time > 0"}	{"condition": "avg_read_ms > :latency_threshold", "description": "High average read latency across all block reads suggests controller-level bottleneck"}	{"latency_threshold": 5}	2026-02-25 00:28:52.405273
4947	postgresql	query	Check WAL sync latency from pg_stat_wal	{"sql": "SELECT current_setting('server_version_num')::int AS version_num, CASE WHEN current_setting('server_version_num')::int >= 140000 THEN 'pg_stat_wal available' ELSE 'pg_stat_wal not available (PG14+)' END AS wal_stats_status"}	{"condition": "avg_sync_ms > :sync_threshold_ms", "description": "High average fsync time suggests write cache not absorbing syncs (battery failure causes write-through)"}	{"sync_threshold_ms": 5}	2026-02-25 00:28:52.405273
4955	postgresql	query	Check WAL write latency for contention evidence	{"sql": "SELECT current_setting('server_version_num')::int AS version_num, CASE WHEN current_setting('server_version_num')::int >= 140000 THEN 'pg_stat_wal available' ELSE 'pg_stat_wal not available (PG14+)' END AS wal_stats_status"}	{"condition": "avg_sync_ms > :latency_threshold_ms", "description": "Elevated WAL sync latency when data I/O is concurrent confirms shared storage contention"}	{"latency_threshold_ms": 3}	2026-02-25 00:28:52.405273
