6418	oracle	query	ora_check_backup_set_expiration	{"sql": "SELECT RECID AS BS_KEY, BACKUP_TYPE, COMPLETION_TIME, KEEP, KEEP_UNTIL FROM v$backup_set WHERE BACKUP_TYPE IN ('D') ORDER BY COMPLETION_TIME DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Expired or deleted full backups found — retention policy or manual deletion removed the base backup"}	\N	2026-02-28 12:19:19.580455
5119	postgresql	query	Find FK-supporting indexes with low usage	{"sql": "SELECT c.conrelid::regclass AS table_name, c.conname AS fk_name, a.attname AS fk_column, s.indexrelname, s.idx_scan FROM pg_constraint c JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey) JOIN pg_stat_user_indexes s ON s.relid = c.conrelid AND a.attnum = ANY(string_to_array((SELECT indkey::text FROM pg_index WHERE indexrelid = s.indexrelid), ' ')::smallint[]) WHERE c.contype = 'f' AND s.idx_scan < 100 ORDER BY s.idx_scan ASC LIMIT 20"}	{"condition": "idx_scan < :scan_threshold", "description": "Low-usage indexes on FK columns of rarely-joined tables add write overhead without benefit"}	{"scan_threshold": 10}	2026-02-25 00:28:52.405273
