6260	oracle	query	ORA find unindexed foreign keys	{"sql": "SELECT c.owner, c.table_name, c.constraint_name, cc.column_name, cc.position FROM ALL_CONSTRAINTS c JOIN ALL_CONS_COLUMNS cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner WHERE c.constraint_type = 'R' AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ic WHERE ic.table_owner = cc.owner AND ic.table_name = cc.table_name AND ic.column_name = cc.column_name AND ic.column_position = cc.position) AND c.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB', 'WMSYS') ORDER BY c.owner, c.table_name"}	{"condition": "row_count > 0", "description": "Foreign keys without supporting indexes cause full table locks when parent table is modified"}	\N	2026-02-28 12:19:19.580455
5170	postgresql	query	Find tables with SERIAL/IDENTITY primary keys and high insert rate	{"sql": "SELECT t.schemaname, t.relname, t.n_tup_ins FROM pg_stat_user_tables t WHERE t.n_tup_ins > 1000 AND EXISTS (SELECT 1 FROM pg_index idx JOIN pg_attribute a ON a.attrelid = idx.indrelid AND a.attnum = idx.indkey[0] JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE idx.indrelid = (SELECT oid FROM pg_class WHERE relname = t.relname LIMIT 1) AND idx.indisprimary AND pg_get_expr(d.adbin, d.adrelid) ~* 'nextval') ORDER BY t.n_tup_ins DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Tables with SERIAL/sequence PKs and high insert rate concentrate inserts on rightmost B-tree page"}	{"insert_threshold": 100000}	2026-02-25 00:28:52.405273
5326	postgresql	query	Find columns with large type definitions but small actual data	{"sql": "SELECT s.schemaname, s.tablename, s.attname, pg_catalog.format_type(a.atttypid, a.atttypmod) AS declared_type, s.avg_width AS actual_avg_width FROM pg_stats s JOIN pg_attribute a ON a.attrelid = (s.schemaname || '.' || s.tablename)::regclass AND a.attname = s.attname WHERE s.schemaname NOT IN ('pg_catalog', 'information_schema') AND a.atttypid IN ('text'::regtype, 'varchar'::regtype, 'bytea'::regtype) AND s.avg_width < :max_actual_width ORDER BY s.avg_width ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Columns declared as unbounded types but storing short values may cause planner to overestimate sort/hash memory"}	{"max_actual_width": 100}	2026-02-25 00:28:52.405273
