6282	oracle	query	ora_find_unindexed_foreign_keys	{"sql": "SELECT c.owner, c.table_name, c.constraint_name, cc.column_name, r.table_name AS referenced_table FROM ALL_CONSTRAINTS c JOIN ALL_CONS_COLUMNS cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner JOIN ALL_CONSTRAINTS r ON c.r_constraint_name = r.constraint_name AND c.r_owner = r.owner WHERE c.constraint_type = 'R' AND c.owner NOT IN ('SYS','SYSTEM','DBSNMP') AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ic WHERE ic.table_owner = cc.owner AND ic.table_name = cc.table_name AND ic.column_name = cc.column_name AND ic.column_position = cc.position)"}	{"condition": "row_count > 0", "description": "Unindexed foreign keys cause Oracle to lock the entire child table during parent modifications"}	\N	2026-02-28 12:19:19.580455
