6525	oracle	query	ora_cascade_on_large_tables_risk	{"sql": "SELECT c.owner, c.table_name, c.constraint_name, c.delete_rule, s.num_rows AS parent_rows, ct.num_rows AS child_rows FROM ALL_CONSTRAINTS c JOIN ALL_TABLES s ON c.r_owner = s.owner AND c.r_constraint_name IN (SELECT constraint_name FROM ALL_CONSTRAINTS WHERE owner = s.owner AND table_name = s.table_name AND constraint_type IN ('P', 'U')) JOIN ALL_TABLES ct ON c.owner = ct.owner AND c.table_name = ct.table_name WHERE c.constraint_type = 'R' AND c.delete_rule = 'CASCADE' AND c.owner NOT IN ('SYS', 'SYSTEM') AND ct.num_rows > :min_rows ORDER BY ct.num_rows DESC"}	{"condition": "row_count > 0", "description": "Cascade delete on large tables poses significant data loss risk"}	{"min_rows": 10000}	2026-02-28 12:19:19.580455
