6684	oracle	query	ORA check temporary tablespace usage and allocation	{"sql": "SELECT ts.tablespace_name, ts.contents, ROUND(SUM(tu.bytes_used) / 1024 / 1024) AS used_mb, ROUND(SUM(tu.bytes_free) / 1024 / 1024) AS free_mb FROM v$temp_space_header tu JOIN dba_tablespaces ts ON tu.tablespace_name = ts.tablespace_name WHERE ts.contents = 'TEMPORARY' GROUP BY ts.tablespace_name, ts.contents"}	{"condition": "used_mb > :temp_threshold_mb", "description": "High temporary tablespace usage may indicate orphaned temp segments from disconnected sessions"}	{"temp_threshold_mb": 5000}	2026-02-28 12:19:19.580455
6690	oracle	query	ORA check table modification tracking	{"sql": "SELECT tm.table_owner, tm.table_name, tm.inserts, tm.updates, tm.deletes, tm.inserts + tm.updates + tm.deletes AS total_modifications, ts.num_rows, CASE WHEN ts.num_rows > 0 THEN ROUND((tm.inserts + tm.updates + tm.deletes) / ts.num_rows * 100, 2) ELSE NULL END AS modification_pct, ts.stale_stats FROM ALL_TAB_MODIFICATIONS tm JOIN ALL_TAB_STATISTICS ts ON tm.table_owner = ts.owner AND tm.table_name = ts.table_name WHERE tm.table_owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB') AND ts.stale_stats = 'NO' AND (tm.inserts + tm.updates + tm.deletes) > :min_mods ORDER BY total_modifications DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 AND max(modification_pct) > :pct_threshold", "description": "Tables with significant modifications but stats marked as current may have drift not captured by staleness threshold"}	{"min_mods": 10000, "pct_threshold": 5}	2026-02-28 12:19:19.580455
6692	oracle	query	ORA find unique indexes with outdated statistics	{"sql": "SELECT di.owner, di.index_name, di.table_name, di.uniqueness, di.num_rows AS idx_num_rows, dt.num_rows AS tab_num_rows, di.last_analyzed AS idx_last_analyzed, dt.last_analyzed AS tab_last_analyzed FROM ALL_INDEXES di JOIN ALL_TABLES dt ON di.table_owner = dt.owner AND di.table_name = dt.table_name WHERE di.uniqueness = 'UNIQUE' AND di.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB') AND (di.last_analyzed < dt.last_analyzed - INTERVAL '7' DAY OR di.last_analyzed IS NULL) AND dt.num_rows > :min_rows ORDER BY dt.num_rows DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Unique indexes with stale statistics may cause optimizer to underestimate cardinality for range predicates"}	{"min_rows": 10000}	2026-02-28 12:19:19.580455
6696	oracle	query	ORA find large tables with stale statistics [HLTH-SQL-DM-002-RC05]	{"sql": "SELECT owner, table_name, num_rows, blocks, ROUND(blocks * 8 / 1024) AS size_mb, last_analyzed, stale_stats FROM ALL_TAB_STATISTICS WHERE stale_stats = 'YES' AND owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB', 'WMSYS') AND blocks > :min_blocks ORDER BY blocks DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Large tables with stale stats confirm the auto stats job cannot complete them within the maintenance window"}	{"min_blocks": 100000}	2026-02-28 12:19:19.580455
6698	oracle	query	ORA check partition statistics freshness vs locked partitions	{"sql": "SELECT owner AS table_owner, table_name, partition_name, num_rows, last_analyzed, stale_stats, stattype_locked FROM dba_tab_statistics WHERE object_type = 'PARTITION' AND owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB', 'WMSYS') AND (stale_stats = 'YES' OR stattype_locked IS NOT NULL) ORDER BY owner, table_name, partition_name FETCH FIRST 30 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Stale or locked partition statistics prevent incremental global stats aggregation"}	\N	2026-02-28 12:19:19.580455
6699	oracle	query	ORA check modification counts vs staleness threshold	{"sql": "SELECT tm.table_owner, tm.table_name, tm.inserts + tm.updates + tm.deletes AS total_mods, ts.num_rows, CASE WHEN ts.num_rows > 0 THEN ROUND((tm.inserts + tm.updates + tm.deletes) / ts.num_rows * 100, 2) ELSE NULL END AS mod_pct, ts.stale_stats, ts.last_analyzed FROM ALL_TAB_MODIFICATIONS tm JOIN ALL_TAB_STATISTICS ts ON tm.table_owner = ts.owner AND tm.table_name = ts.table_name WHERE tm.table_owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB') AND ts.stale_stats = 'NO' AND ts.num_rows > :min_rows AND (tm.inserts + tm.updates + tm.deletes) > :min_mods ORDER BY total_mods DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 AND max(mod_pct) BETWEEN :low_pct AND :high_pct", "description": "Tables with modifications between low and staleness thresholds have data drift not triggering auto refresh"}	{"low_pct": 3, "high_pct": 10, "min_mods": 5000, "min_rows": 100000}	2026-02-28 12:19:19.580455
12087	mysql	query	Check audit log max size configuration	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME IN ('audit_log_max_size', 'audit_log_rotate_on_size')"}	{"condition": "audit_log_max_size set to a value that forces early pruning", "description": "A low audit_log_max_size effectively creates a space quota that overrides time-based retention"}	\N	2026-03-01 06:30:58.706791
6700	oracle	query	ORA check maintenance window duration vs stats completion	{"sql": "SELECT window_name, TO_CHAR(next_start_date, 'YYYY-MM-DD HH24:MI:SS') AS next_run, duration FROM dba_scheduler_windows WHERE window_name LIKE '%MAINTENANCE%' OR window_name IN ('MONDAY_WINDOW', 'TUESDAY_WINDOW', 'WEDNESDAY_WINDOW', 'THURSDAY_WINDOW', 'FRIDAY_WINDOW', 'SATURDAY_WINDOW', 'SUNDAY_WINDOW') ORDER BY window_name"}	{"condition": "row_count > 0", "description": "Maintenance windows define available time for stats collection"}	\N	2026-02-28 12:19:19.580455
6708	oracle	query	ORA find tables with stale stats after recent bulk loads	{"sql": "SELECT ts.owner, ts.table_name, ts.num_rows, ts.last_analyzed, ts.stale_stats, dt.last_analyzed AS tab_last_analyzed, ROUND(SYSDATE - ts.last_analyzed) AS days_stale FROM ALL_TAB_STATISTICS ts JOIN ALL_TABLES dt ON ts.owner = dt.owner AND ts.table_name = dt.table_name WHERE ts.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB', 'WMSYS') AND ts.stale_stats = 'YES' AND ts.num_rows > :min_rows ORDER BY ts.num_rows DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with stale statistics after apparent data growth indicate bulk load bypassed stats tracking"}	{"min_rows": 100000}	2026-02-28 12:19:19.580455
6710	oracle	query	ora_find_volatile_tables_stale_stats	{"sql": "SELECT t.owner, t.table_name, t.num_rows, t.last_analyzed, m.inserts, m.updates, m.deletes, m.inserts + m.updates + m.deletes AS total_dml, m.timestamp AS last_dml_time FROM ALL_TABLES t JOIN ALL_TAB_MODIFICATIONS m ON t.owner = m.table_owner AND t.table_name = m.table_name WHERE t.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND (m.inserts + m.updates + m.deletes) > :min_dml_changes ORDER BY total_dml DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with high DML activity since last statistics gather are operating with stale statistics"}	{"min_dml_changes": 50000}	2026-02-28 12:19:19.580455
6711	oracle	query	ora_check_stale_stats_flag	{"sql": "SELECT owner, table_name, num_rows, last_analyzed, stale_stats FROM ALL_TAB_STATISTICS WHERE stale_stats = 'YES' AND owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') ORDER BY num_rows DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables flagged as STALE by Oracle statistics monitoring confirm statistics lag behind DML activity"}	\N	2026-02-28 12:19:19.580455
6721	oracle	query	ora_check_high_dml_tables	{"sql": "SELECT table_owner, table_name, inserts, deletes, updates, timestamp AS last_flush FROM ALL_TAB_MODIFICATIONS WHERE (inserts > :min_inserts AND deletes > :min_deletes) AND table_owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') ORDER BY inserts + deletes DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 AND tables have both high inserts and high deletes", "description": "Tables with both high inserts and high deletes suggest load-then-purge patterns"}	{"min_deletes": 50000, "min_inserts": 100000}	2026-02-28 12:19:19.580455
6724	oracle	query	ora_check_row_chaining_stats	{"sql": "SELECT owner, table_name, chain_cnt, num_rows, ROUND(chain_cnt / GREATEST(num_rows, 1) * 100, 2) AS chain_pct FROM ALL_TABLES WHERE owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND chain_cnt > :min_chain_count AND num_rows > 0 ORDER BY chain_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 AND chain_pct > 5", "description": "High chained/migrated row percentage confirms insufficient PCTFREE causing row migration"}	{"min_chain_count": 100}	2026-02-28 12:19:19.580455
7268	oracle	query	ora-check-db-version-info	{"sql": "SELECT BANNER_FULL, BANNER_LEGACY, BANNER FROM v$version WHERE BANNER LIKE 'Oracle Database%'"}	{"condition": "row_count > 0", "description": "Current database version retrieved for comparison with standby version"}	\N	2026-02-28 12:19:19.580455
6726	oracle	query	ora_find_indexes_with_high_clustering_factor	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.clustering_factor, t.num_rows, t.blocks, ROUND(i.clustering_factor / GREATEST(t.blocks, 1), 1) AS cf_ratio FROM ALL_INDEXES i JOIN ALL_TABLES t ON i.table_owner = t.owner AND i.table_name = t.table_name WHERE i.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND t.num_rows > 10000 AND i.clustering_factor / GREATEST(t.blocks, 1) > :cf_threshold ORDER BY cf_ratio DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with high clustering factor relative to table blocks indicate random data distribution causing splits"}	{"cf_threshold": 5}	2026-02-28 12:19:19.580455
13702	mariadb	query	Check relay log space usage indicating backlog	{"sql": "SELECT VARIABLE_VALUE AS relay_log_space FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Relay_log_space'"}	{"condition": "relay_log_space > 1073741824", "description": "Relay log space over 1GB indicates significant backlog"}	{"relay_log_threshold_bytes": 1073741824}	2026-05-11 22:17:39.229791
6731	oracle	query	ora_find_tables_with_varchar_updates	{"sql": "SELECT t.owner, t.table_name, t.avg_row_len, t.pct_free, t.chain_cnt, t.num_rows, COUNT(c.column_name) AS varchar_cols FROM dba_tables t JOIN dba_tab_columns c ON t.owner = c.owner AND t.table_name = c.table_name JOIN dba_tab_modifications m ON t.owner = m.table_owner AND t.table_name = m.table_name WHERE c.data_type IN ('VARCHAR2','NVARCHAR2','CLOB','NCLOB') AND t.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND m.updates > 10000 AND t.num_rows > 1000 GROUP BY t.owner, t.table_name, t.avg_row_len, t.pct_free, t.chain_cnt, t.num_rows HAVING COUNT(c.column_name) > 0 ORDER BY MAX(m.updates) DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with VARCHAR columns and high update rates are candidates for row migration"}	{"min_updates": 10000}	2026-02-28 12:19:19.580455
6733	oracle	query	ora_find_tables_with_many_columns	{"sql": "SELECT owner, table_name, COUNT(*) AS column_count, MAX(column_id) AS max_column_id FROM ALL_TAB_COLUMNS WHERE owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') GROUP BY owner, table_name HAVING COUNT(*) > :column_threshold OR MAX(column_id) > COUNT(*) + 5 ORDER BY column_count DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 OR max_column_id > column_count", "description": "Tables with many columns or gaps in column_id (from dropped columns) indicate frequent schema changes"}	{"column_threshold": 100}	2026-02-28 12:19:19.580455
6735	oracle	query	ora_find_high_dml_tables_with_indexes	{"sql": "SELECT m.table_owner, m.table_name, m.inserts, m.updates, m.deletes, m.inserts + m.updates + m.deletes AS total_dml, (SELECT COUNT(*) FROM ALL_INDEXES i WHERE i.table_owner = m.table_owner AND i.table_name = m.table_name) AS index_count FROM ALL_TAB_MODIFICATIONS m WHERE m.table_owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND (m.inserts + m.updates + m.deletes) > :min_dml ORDER BY total_dml DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 AND index_count > 0", "description": "Tables with heavy DML and multiple indexes are candidates for index fragmentation"}	{"min_dml": 100000}	2026-02-28 12:19:19.580455
6739	oracle	query	ora_check_index_clustering_factor	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.clustering_factor, t.num_rows, ROUND(i.clustering_factor / NULLIF(t.num_rows, 0), 2) AS cf_ratio FROM ALL_INDEXES i JOIN ALL_TABLES t ON i.table_owner = t.owner AND i.table_name = t.table_name WHERE i.index_type = 'NORMAL' AND t.num_rows > 10000 AND i.clustering_factor / NULLIF(t.num_rows, 0) > :cf_threshold ORDER BY cf_ratio DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "High clustering factor relative to row count indicates data is not ordered by index key, causing random I/O"}	{"cf_threshold": 0.8}	2026-02-28 12:19:19.580455
6746	oracle	query	ora_check_table_row_chaining_stats	{"sql": "SELECT owner, table_name, num_rows, chain_cnt, ROUND(chain_cnt / NULLIF(num_rows, 0) * 100, 2) AS chain_pct, avg_row_len, pct_free FROM ALL_TABLES WHERE chain_cnt > 0 AND num_rows > 1000 AND chain_cnt / NULLIF(num_rows, 0) > :chain_threshold ORDER BY chain_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "High chain_cnt indicates row migration from updates increasing row size"}	{"chain_threshold": 0.05}	2026-02-28 12:19:19.580455
6752	oracle	query	ora_check_table_space_usage_below_hwm	{"sql": "SELECT owner, table_name, num_rows, blocks, empty_blocks, avg_space, avg_row_len, ROUND(num_rows * avg_row_len / NULLIF(blocks * 8192, 0) * 100, 1) AS density_pct FROM ALL_TABLES WHERE num_rows > 1000 AND blocks > 100 AND num_rows * avg_row_len / NULLIF(blocks * 8192, 0) < :density_threshold ORDER BY density_pct ASC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with low block density indicate wasted space from previous delete/update operations"}	{"density_threshold": 0.3}	2026-02-28 12:19:19.580455
6755	oracle	query	ora_check_indexes_in_unusable_state	{"sql": "SELECT owner, index_name, table_name, status, last_analyzed FROM ALL_INDEXES WHERE status IN ('UNUSABLE', 'N/A') ORDER BY owner, index_name"}	{"condition": "row_count > 0", "description": "Unusable indexes after bulk loads indicate direct path operations without index rebuild"}	\N	2026-02-28 12:19:19.580455
6761	oracle	query	ora_check_column_histogram_skew	{"sql": "SELECT c.owner, c.table_name, c.column_name, c.num_distinct, c.density, c.histogram, c.num_buckets FROM ALL_TAB_COL_STATISTICS c JOIN ALL_IND_COLUMNS ic ON c.owner = ic.table_owner AND c.table_name = ic.table_name AND c.column_name = ic.column_name WHERE c.histogram IN ('FREQUENCY', 'TOP-FREQUENCY', 'HYBRID') AND c.num_distinct < 1000 ORDER BY c.num_distinct FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Columns with frequency histograms confirm skewed data distribution in indexed columns"}	\N	2026-02-28 12:19:19.580455
6764	oracle	query	ora_check_index_modification_monitoring	{"sql": "SELECT owner AS table_owner, name AS index_name, total_access_count, total_exec_count, total_rows_returned, last_used FROM dba_index_usage WHERE total_access_count > :update_threshold ORDER BY total_access_count DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with high update counts indicate they cover frequently-updated columns"}	{"update_threshold": 100000}	2026-02-28 12:19:19.580455
6767	oracle	query	ora-check-table-row-movement-for-shrink	{"sql": "SELECT owner, table_name, ROUND(blocks * 8192 / 1024 / 1024, 1) AS allocated_mb, num_rows, avg_row_len, ROUND(num_rows * avg_row_len / 1024 / 1024, 1) AS estimated_data_mb, ROUND(blocks * 8192 / 1024 / 1024 - num_rows * avg_row_len / 1024 / 1024, 1) AS wasted_mb, row_movement FROM ALL_TABLES WHERE owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP', 'OUTLN') AND blocks * 8192 > :size_threshold_bytes AND ROUND((blocks * 8192 - num_rows * avg_row_len) / NULLIF(blocks * 8192, 0) * 100, 1) > :waste_pct ORDER BY wasted_mb DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Large tables with significant wasted space confirm slow maintenance issue — segment shrink needed"}	{"waste_pct": 30, "size_threshold_bytes": 1073741824}	2026-02-28 12:19:19.580455
6775	oracle	query	ora-check-tables-auto-stats-disabled	{"sql": "SELECT owner, table_name, DBMS_STATS.GET_PREFS('AUTOSTATS_TARGET', owner, table_name) AS autostats_target, DBMS_STATS.GET_PREFS('STALE_PERCENT', owner, table_name) AS stale_percent, t.last_analyzed, ROUND(SYSDATE - t.last_analyzed) AS days_since_analyzed FROM ALL_TABLES t WHERE t.owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP', 'OUTLN', 'XDB') AND t.num_rows > 1000 AND t.last_analyzed < SYSDATE - :stale_days ORDER BY t.num_rows DESC FETCH FIRST 30 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with stale statistics and potentially disabled auto-gathering"}	{"stale_days": 30}	2026-02-28 12:19:19.580455
6777	oracle	query	ora-check-locked-statistics	{"sql": "SELECT owner, table_name, stattype_locked, num_rows, last_analyzed FROM ALL_TAB_STATISTICS WHERE stattype_locked IS NOT NULL AND owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP', 'OUTLN', 'XDB') ORDER BY num_rows DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with locked statistics will not be updated by auto-gather — equivalent to disabled maintenance"}	\N	2026-02-28 12:19:19.580455
6803	oracle	query	ora-check-job-run-conflicts	{"sql": "SELECT j1.job_name AS job1, TO_CHAR(j1.actual_start_date, 'YYYY-MM-DD HH24:MI:SS') AS start1, TO_CHAR(j1.run_duration) AS duration1, j2.job_name AS job2, TO_CHAR(j2.actual_start_date, 'YYYY-MM-DD HH24:MI:SS') AS start2, TO_CHAR(j2.run_duration) AS duration2 FROM dba_scheduler_job_run_details j1 JOIN dba_scheduler_job_run_details j2 ON j1.actual_start_date BETWEEN j2.actual_start_date AND j2.actual_start_date + j2.run_duration AND j1.job_name != j2.job_name WHERE j1.actual_start_date > SYSDATE - 14 AND j1.status = 'FAILED' ORDER BY j1.actual_start_date DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Failed jobs overlapping with other running jobs confirm scheduling conflicts"}	\N	2026-02-28 12:19:19.580455
6815	oracle	query	ora_check_failed_scheduler_jobs_undetected	{"sql": "SELECT JOB_NAME, STATUS, ERROR#, TO_CHAR(ACTUAL_START_DATE, 'YYYY-MM-DD HH24:MI:SS') AS ACTUAL_START_DATE, TO_CHAR(RUN_DURATION) AS RUN_DURATION, ADDITIONAL_INFO FROM DBA_SCHEDULER_JOB_RUN_DETAILS WHERE STATUS = 'FAILED' AND ACTUAL_START_DATE > SYSDATE - 7 ORDER BY ACTUAL_START_DATE DESC"}	{"condition": "row_count > 0", "description": "Failed scheduler jobs detected — if these went unnoticed, monitoring has gaps"}	{"days_back": 7}	2026-02-28 12:19:19.580455
9637	oracle	query	ORA check UTL_INADDR access grants	{"sql": "SELECT grantee, privilege FROM ALL_TAB_PRIVS WHERE table_name = 'UTL_INADDR' AND privilege = 'EXECUTE' AND grantee NOT IN ('SYS', 'SYSTEM', 'DBA') ORDER BY grantee"}	{"condition": "row_count > 0", "description": "Non-DBA users with UTL_INADDR access can perform DNS lookups from the database"}	\N	2026-02-28 12:19:19.580455
6875	oracle	query	ora-check-instance-health-status	{"sql": "SELECT instance_name, status, database_status, active_state, blocked FROM v$instance"}	{"condition": "status != 'OPEN' OR database_status != 'ACTIVE' OR blocked = 'YES'", "description": "Instance is not in healthy OPEN/ACTIVE state, which would cause health check probes to fail"}	\N	2026-02-28 12:19:19.580455
