7302	oracle	query	ora_archive_dest_repeated_failures	{"sql": "SELECT d.dest_id, ds.status, ds.error, d.fail_date, d.fail_sequence, d.failure_count, d.reopen_secs, d.max_failure FROM v$archive_dest d JOIN v$archive_dest_status ds ON d.dest_id = ds.dest_id WHERE d.failure_count > :min_failures ORDER BY d.failure_count DESC"}	{"condition": "row_count > 0", "description": "Repeated archive destination failures indicate network flapping"}	{"min_failures": 3}	2026-02-28 12:19:19.580455
