7466	oracle	query	ORA check for table bloat and row chaining	{"sql": "SELECT owner, table_name, num_rows, blocks, empty_blocks, avg_space, chain_cnt, avg_row_len, CASE WHEN blocks > 0 AND num_rows > 0 THEN ROUND(num_rows * avg_row_len / (blocks * 8192) * 100, 1) ELSE NULL END AS fill_pct FROM ALL_TABLES WHERE chain_cnt > :chain_threshold AND owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB', 'WMSYS') ORDER BY chain_cnt DESC NULLS LAST FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with high row chaining or low fill percentage indicate space management issues degrading scans"}	{"chain_threshold": 1000}	2026-02-28 12:19:19.580455
