9174	oracle	query	ora_check_audit_table_privilege_grants	{"sql": "SELECT GRANTEE, PRIVILEGE, TABLE_NAME, GRANTOR FROM ALL_TAB_PRIVS WHERE TABLE_NAME IN ('AUD$', 'FGA_LOG$') AND PRIVILEGE IN ('DELETE', 'UPDATE', 'INSERT', 'ALTER') AND GRANTEE NOT IN ('SYS', 'SYSTEM')"}	{"condition": "row_count > 0", "description": "Non-SYS users have DML privileges on audit tables — audit data can be tampered"}	\N	2026-02-28 12:19:19.580455
8347	oracle	query	ora-check-low-cardinality-btree-indexes	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.index_type, i.distinct_keys, t.num_rows, ROUND(i.distinct_keys / NULLIF(t.num_rows, 0) * 100, 2) AS selectivity_pct FROM ALL_INDEXES i JOIN ALL_TABLES t ON i.table_owner = t.owner AND i.table_name = t.table_name WHERE i.index_type = 'NORMAL' AND i.owner NOT IN ('SYS', 'SYSTEM') AND t.num_rows > :row_threshold AND i.distinct_keys / NULLIF(t.num_rows, 0) < :selectivity_threshold ORDER BY selectivity_pct FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "B-tree indexes on low cardinality columns (low selectivity) are inefficient — bitmap indexes may be more appropriate"}	{"row_threshold": 10000, "selectivity_threshold": 0.01}	2026-02-28 12:19:19.580455
8348	oracle	query	ora-check-nullable-indexed-columns	{"sql": "SELECT ic.table_owner, ic.table_name, ic.column_name, ic.index_name, tc.nullable, tc.num_nulls, tc.num_distinct, t.num_rows, ROUND(tc.num_nulls/NULLIF(t.num_rows, 0)*100, 1) AS null_pct FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COLUMNS tc ON ic.table_owner = tc.owner AND ic.table_name = tc.table_name AND ic.column_name = tc.column_name JOIN ALL_TABLES t ON ic.table_owner = t.owner AND ic.table_name = t.table_name WHERE tc.nullable = 'Y' AND tc.num_nulls > t.num_rows * :null_ratio AND ic.table_owner NOT IN ('SYS', 'SYSTEM') ORDER BY null_pct DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes on highly nullable columns are mostly empty (Oracle B-tree excludes all-NULL entries), wasting space and maintenance overhead"}	{"null_ratio": 0.5}	2026-02-28 12:19:19.580455
8353	oracle	query	ora-check-invisible-indexes	{"sql": "SELECT owner, index_name, table_name, index_type, status, visibility FROM ALL_INDEXES WHERE visibility = 'INVISIBLE' AND owner NOT IN ('SYS', 'SYSTEM') ORDER BY owner, table_name"}	{"condition": "row_count > 0", "description": "INVISIBLE indexes exist that are maintained but hidden from the optimizer — may have been left invisible unintentionally"}	\N	2026-02-28 12:19:19.580455
8377	oracle	query	ora_tables_with_high_delete_rate	{"sql": "SELECT table_owner, table_name, inserts, updates, deletes, ROUND(deletes / GREATEST(inserts + updates + deletes, 1) * 100, 1) AS delete_pct FROM ALL_TAB_MODIFICATIONS WHERE table_owner NOT IN ('SYS', 'SYSTEM') AND deletes > :min_deletes ORDER BY deletes DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with high delete rates — corresponding indexes are likely fragmented"}	{"min_deletes": 10000}	2026-02-28 12:19:19.580455
10900	mysql	query	Check existing indexes on frequently scanned tables	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, GROUP_CONCAT(s.COLUMN_NAME ORDER BY s.SEQ_IN_INDEX) AS index_columns, MAX(t.TABLE_ROWS) AS TABLE_ROWS FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND t.TABLE_ROWS > 10000 GROUP BY s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME ORDER BY TABLE_ROWS DESC"}	{"condition": "single_column_indexes_only", "description": "Tables with only single-column indexes when queries use multi-column filters"}	\N	2026-03-01 06:30:58.706791
14736	mariadb	query	Identify admin users with SUPER or ALL PRIVILEGES	{"sql": "SELECT u.User, u.Host, alu.FILTERNAME FROM mysql.user u LEFT JOIN mysql.audit_log_user alu ON u.User = alu.USER AND u.Host = alu.HOST WHERE u.Super_priv = 'Y' OR u.Create_priv = 'Y'"}	{"condition": "any_row_has_null_filtername_or_exclusion_filter", "description": "Admin users with SUPER or CREATE privileges have no audit filter or an exclusion filter"}	\N	2026-05-11 22:17:39.229791
8354	oracle	query	ora-check-prefix-redundant-indexes	{"sql": "SELECT a.owner, a.index_name AS redundant_index, a.table_name, b.index_name AS superseding_index, (SELECT LISTAGG(column_name, ', ') WITHIN GROUP (ORDER BY column_position) FROM ALL_IND_COLUMNS WHERE index_owner = a.owner AND index_name = a.index_name) AS redundant_cols, (SELECT LISTAGG(column_name, ', ') WITHIN GROUP (ORDER BY column_position) FROM ALL_IND_COLUMNS WHERE index_owner = b.owner AND index_name = b.index_name) AS superseding_cols FROM ALL_INDEXES a JOIN ALL_INDEXES b ON a.table_owner = b.table_owner AND a.table_name = b.table_name AND a.index_name != b.index_name WHERE a.owner NOT IN ('SYS', 'SYSTEM') AND a.uniqueness = 'NONUNIQUE' AND (SELECT COUNT(*) FROM ALL_IND_COLUMNS WHERE index_owner = a.owner AND index_name = a.index_name) < (SELECT COUNT(*) FROM ALL_IND_COLUMNS WHERE index_owner = b.owner AND index_name = b.index_name) AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ac WHERE ac.index_owner = a.owner AND ac.index_name = a.index_name AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS bc WHERE bc.index_owner = b.owner AND bc.index_name = b.index_name AND bc.column_name = ac.column_name AND bc.column_position = ac.column_position)) FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes whose columns are a leading prefix of another index are redundant and waste DML overhead"}	\N	2026-02-28 12:19:19.580455
8359	oracle	query	ora_unused_index_monitoring_check	{"sql": "SELECT di.owner, di.index_name, di.table_name, di.index_type, di.status, di.num_rows, di.last_analyzed FROM ALL_INDEXES di WHERE di.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB', 'WMSYS', 'ORDSYS') AND di.index_type NOT IN ('LOB') AND di.status = 'VALID' AND di.index_name NOT LIKE 'SYS_%' AND NOT EXISTS (SELECT 1 FROM ALL_CONSTRAINTS dc WHERE dc.constraint_type IN ('P', 'U') AND dc.index_name = di.index_name AND dc.owner = di.owner) ORDER BY di.num_rows DESC NULLS LAST FETCH FIRST 50 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Non-constraint indexes found — need usage verification"}	\N	2026-02-28 12:19:19.580455
8361	oracle	query	ora_high_dml_tables_with_many_indexes	{"sql": "SELECT t.owner, t.table_name, t.num_rows, (SELECT COUNT(*) FROM ALL_INDEXES i WHERE i.table_owner = t.owner AND i.table_name = t.table_name) AS index_count, s.inserts + s.updates + s.deletes AS dml_count FROM ALL_TABLES t JOIN ALL_TAB_MODIFICATIONS s ON t.owner = s.table_owner AND t.table_name = s.table_name WHERE t.owner NOT IN ('SYS', 'SYSTEM') AND (SELECT COUNT(*) FROM ALL_INDEXES i WHERE i.table_owner = t.owner AND i.table_name = t.table_name) > :index_threshold ORDER BY dml_count DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "High-DML tables with many indexes — optimizer may avoid some due to maintenance cost"}	{"index_threshold": 5}	2026-02-28 12:19:19.580455
8362	oracle	query	ora_invisible_or_unusable_indexes	{"sql": "SELECT owner, index_name, table_name, index_type, status, visibility FROM ALL_INDEXES WHERE owner NOT IN ('SYS', 'SYSTEM') AND (status = 'UNUSABLE' OR visibility = 'INVISIBLE') ORDER BY owner, table_name"}	{"condition": "row_count > 0", "description": "Unusable or invisible indexes found — optimizer cannot use these"}	\N	2026-02-28 12:19:19.580455
8363	oracle	query	ora_local_partitioned_index_status	{"sql": "SELECT di.owner, di.index_name, di.table_name, di.partitioned, di.index_type, ip.partition_name, ip.status FROM ALL_INDEXES di LEFT JOIN ALL_IND_PARTITIONS ip ON di.owner = ip.index_owner AND di.index_name = ip.index_name WHERE di.owner NOT IN ('SYS', 'SYSTEM') AND di.partitioned = 'YES' AND (ip.status = 'UNUSABLE' OR ip.status IS NULL) ORDER BY di.owner, di.index_name FETCH FIRST 30 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Partitioned indexes with unusable partitions found"}	\N	2026-02-28 12:19:19.580455
8367	oracle	query	ora_composite_index_leading_column_analysis	{"sql": "SELECT ic.index_owner, ic.index_name, ic.table_name, ic.column_name, ic.column_position, di.distinct_keys FROM ALL_IND_COLUMNS ic JOIN ALL_INDEXES di ON ic.index_owner = di.owner AND ic.index_name = di.index_name WHERE ic.index_owner NOT IN ('SYS', 'SYSTEM') AND ic.column_position = 1 AND di.index_type = 'NORMAL' AND (SELECT COUNT(*) FROM ALL_IND_COLUMNS ic2 WHERE ic2.index_owner = ic.index_owner AND ic2.index_name = ic.index_name) > 1 ORDER BY di.distinct_keys DESC FETCH FIRST 30 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Composite indexes found — verify queries include leading column"}	\N	2026-02-28 12:19:19.580455
8370	oracle	query	ora_text_index_availability_check	{"sql": "SELECT owner, index_name, table_name, index_type FROM ALL_INDEXES WHERE index_type IN ('DOMAIN', 'FUNCTION-BASED DOMAIN') AND owner NOT IN ('SYS', 'SYSTEM', 'CTXSYS') ORDER BY owner, index_name"}	{"condition": "row_count = 0", "description": "No Oracle Text domain indexes exist — text search relies on expensive full scans"}	\N	2026-02-28 12:19:19.580455
8374	oracle	query	ora_guid_primary_key_tables	{"sql": "SELECT t.owner, t.table_name, c.column_name, c.data_type, c.data_length FROM dba_constraints con JOIN dba_cons_columns cc ON con.constraint_name = cc.constraint_name AND con.owner = cc.owner JOIN dba_tab_columns c ON cc.owner = c.owner AND cc.table_name = c.table_name AND cc.column_name = c.column_name JOIN dba_tables t ON con.owner = t.owner AND con.table_name = t.table_name WHERE con.constraint_type = 'P' AND con.owner NOT IN ('SYS', 'SYSTEM') AND c.data_type = 'RAW' AND c.data_length = 16 ORDER BY t.num_rows DESC NULLS LAST FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with GUID/RAW(16) primary keys found — index fragmentation risk"}	\N	2026-02-28 12:19:19.580455
8381	oracle	query	ora_index_pctfree_configuration	{"sql": "SELECT owner, index_name, table_name, pct_free, leaf_blocks, num_rows, distinct_keys FROM ALL_INDEXES WHERE owner NOT IN ('SYS', 'SYSTEM') AND pct_free < :pctfree_threshold AND index_type = 'NORMAL' AND num_rows > :min_rows ORDER BY num_rows DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with low PCTFREE — insufficient space for growth causing splits"}	{"min_rows": 10000, "pctfree_threshold": 5}	2026-02-28 12:19:19.580455
8383	oracle	query	ora_nullable_indexed_columns_with_updates	{"sql": "SELECT ic.index_owner, ic.index_name, ic.table_name, ic.column_name, tc.nullable, tm.updates FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COLUMNS tc ON ic.table_owner = tc.owner AND ic.table_name = tc.table_name AND ic.column_name = tc.column_name JOIN ALL_TAB_MODIFICATIONS tm ON ic.table_owner = tm.table_owner AND ic.table_name = tm.table_name WHERE ic.index_owner NOT IN ('SYS', 'SYSTEM') AND tc.nullable = 'Y' AND tm.updates > :update_threshold ORDER BY tm.updates DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Nullable indexed columns with high update rates — NULL to non-NULL expansion risk"}	{"update_threshold": 10000}	2026-02-28 12:19:19.580455
8656	oracle	query	ora-check-stale-stats-for-memory-queries	{"sql": "SELECT owner, table_name, num_rows, blocks, last_analyzed, stale_stats, (SYSDATE - last_analyzed) AS days_since_analyzed FROM ALL_TAB_STATISTICS WHERE owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP') AND stale_stats = 'YES' AND num_rows > :row_threshold ORDER BY num_rows DESC FETCH FIRST 15 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Large tables with stale statistics cause the optimizer to underestimate or overestimate memory needs for sorts and hash joins"}	{"row_threshold": 10000}	2026-02-28 12:19:19.580455
8391	oracle	query	ora_index_compression_effectiveness	{"sql": "SELECT di.owner, di.index_name, di.prefix_length, di.leaf_blocks AS compressed_leaves, ROUND(di.num_rows / GREATEST(di.leaf_blocks, 1)) AS rows_per_leaf FROM ALL_INDEXES di WHERE di.compression = 'ENABLED' AND di.owner NOT IN ('SYS', 'SYSTEM') AND di.leaf_blocks > 0 ORDER BY di.leaf_blocks DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Compressed index leaf density retrieved — low density may indicate compression not helping"}	\N	2026-02-28 12:19:19.580455
8394	oracle	query	Oracle find exact duplicate indexes by column list	{"sql": "SELECT a.table_name, a.index_name AS index1, b.index_name AS index2, a.cols AS column_list, a.uniqueness FROM (SELECT i.table_name, i.index_name, i.uniqueness, LISTAGG(c.column_name, ',') WITHIN GROUP (ORDER BY c.column_position) AS cols FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS c ON i.index_name = c.index_name AND i.owner = c.index_owner WHERE i.owner NOT IN ('SYS', 'SYSTEM', 'OUTLN', 'XDB') GROUP BY i.table_name, i.index_name, i.uniqueness) a JOIN (SELECT i.table_name, i.index_name, i.uniqueness, LISTAGG(c.column_name, ',') WITHIN GROUP (ORDER BY c.column_position) AS cols FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS c ON i.index_name = c.index_name AND i.owner = c.index_owner WHERE i.owner NOT IN ('SYS', 'SYSTEM', 'OUTLN', 'XDB') GROUP BY i.table_name, i.index_name, i.uniqueness) b ON a.table_name = b.table_name AND a.cols = b.cols AND a.index_name < b.index_name ORDER BY a.table_name, a.index_name"}	{"condition": "row_count > 0", "description": "Indexes with identical column lists on the same table are exact duplicates"}	\N	2026-02-28 12:19:19.580455
8395	oracle	query	Oracle find overlapping composite index prefixes	{"sql": "SELECT a.table_name, a.index_name AS narrow_index, a.cols AS narrow_cols, a.col_count AS narrow_count, b.index_name AS wide_index, b.cols AS wide_cols, b.col_count AS wide_count FROM (SELECT i.owner, i.table_name, i.index_name, COUNT(*) AS col_count, LISTAGG(c.column_name, ',') WITHIN GROUP (ORDER BY c.column_position) AS cols FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS c ON i.index_name = c.index_name AND i.owner = c.index_owner WHERE i.owner NOT IN ('SYS', 'SYSTEM', 'OUTLN', 'XDB') GROUP BY i.owner, i.table_name, i.index_name) a JOIN (SELECT i.owner, i.table_name, i.index_name, COUNT(*) AS col_count, LISTAGG(c.column_name, ',') WITHIN GROUP (ORDER BY c.column_position) AS cols FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS c ON i.index_name = c.index_name AND i.owner = c.index_owner WHERE i.owner NOT IN ('SYS', 'SYSTEM', 'OUTLN', 'XDB') GROUP BY i.owner, i.table_name, i.index_name) b ON a.table_name = b.table_name AND a.owner = b.owner AND a.index_name != b.index_name AND a.col_count < b.col_count AND b.cols LIKE a.cols || ',%' ORDER BY a.table_name"}	{"condition": "row_count > 0", "description": "Narrow indexes whose columns are a leading prefix of wider indexes are redundant"}	\N	2026-02-28 12:19:19.580455
8397	oracle	query	Oracle find indexes with similar naming patterns on same table	{"sql": "SELECT a.table_name, a.index_name AS idx1, b.index_name AS idx2, a.cols AS cols1, b.cols AS cols2 FROM (SELECT i.owner, i.table_name, i.index_name, LISTAGG(c.column_name, ',') WITHIN GROUP (ORDER BY c.column_position) AS cols FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS c ON i.index_name = c.index_name AND i.owner = c.index_owner WHERE i.owner NOT IN ('SYS', 'SYSTEM', 'OUTLN', 'XDB') AND i.index_type = 'NORMAL' GROUP BY i.owner, i.table_name, i.index_name) a JOIN (SELECT i.owner, i.table_name, i.index_name, LISTAGG(c.column_name, ',') WITHIN GROUP (ORDER BY c.column_position) AS cols FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS c ON i.index_name = c.index_name AND i.owner = c.index_owner WHERE i.owner NOT IN ('SYS', 'SYSTEM', 'OUTLN', 'XDB') AND i.index_type = 'NORMAL' GROUP BY i.owner, i.table_name, i.index_name) b ON a.table_name = b.table_name AND a.owner = b.owner AND a.index_name < b.index_name AND (a.cols = b.cols OR a.cols LIKE b.cols || ',%' OR b.cols LIKE a.cols || ',%') ORDER BY a.table_name"}	{"condition": "row_count > 0", "description": "Multiple indexes with same or overlapping columns on same table from independent creation"}	\N	2026-02-28 12:19:19.580455
8398	oracle	query	Oracle find suspected backup/test indexes by naming	{"sql": "SELECT i.index_name, i.table_name, i.status FROM dba_indexes i WHERE i.owner NOT IN ('SYS', 'SYSTEM', 'OUTLN', 'XDB') AND (i.index_name LIKE '%BACKUP%' OR i.index_name LIKE '%OLD%' OR i.index_name LIKE '%TMP%' OR i.index_name LIKE '%TEST%' OR i.index_name LIKE '%COPY%' OR i.index_name LIKE '%_V2' OR i.index_name LIKE '%_NEW') ORDER BY i.table_name, i.index_name"}	{"condition": "row_count > 0", "description": "Indexes with backup/test naming conventions indicate intentional duplicates not cleaned up"}	\N	2026-02-28 12:19:19.580455
14718	mariadb	config_check	Check active configuration and included directories	{"sql": "SELECT @@general_log AS general_log, @@datadir AS datadir"}	{"condition": "general_log = 0", "description": "General log is disabled, possibly by override file"}	\N	2026-05-11 22:17:39.229791
8400	oracle	query	Oracle find indexes that are prefix of PK/unique constraints	{"sql": "SELECT idx.index_name AS redundant_index, idx.cols AS redundant_cols, pk.constraint_name, pk.index_name AS pk_index, pk.cols AS pk_cols FROM (SELECT i.owner, i.table_name, i.index_name, LISTAGG(c.column_name, ',') WITHIN GROUP (ORDER BY c.column_position) AS cols, COUNT(*) AS col_count FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS c ON i.index_name = c.index_name AND i.owner = c.index_owner WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND i.uniqueness = 'NONUNIQUE' GROUP BY i.owner, i.table_name, i.index_name) idx JOIN (SELECT co.owner, co.table_name, co.constraint_name, co.index_name, LISTAGG(cc.column_name, ',') WITHIN GROUP (ORDER BY cc.position) AS cols FROM ALL_CONSTRAINTS co JOIN ALL_CONS_COLUMNS cc ON co.constraint_name = cc.constraint_name AND co.owner = cc.owner WHERE co.constraint_type IN ('P', 'U') AND co.index_name IS NOT NULL GROUP BY co.owner, co.table_name, co.constraint_name, co.index_name) pk ON idx.table_name = pk.table_name AND idx.owner = pk.owner AND idx.index_name != pk.index_name AND pk.cols LIKE idx.cols || '%' ORDER BY idx.table_name"}	{"condition": "row_count > 0", "description": "Non-unique indexes whose columns are a prefix of a PK/unique index are redundant"}	\N	2026-02-28 12:19:19.580455
8494	oracle	query	ORA check for right-hand index contention	{"sql": "SELECT di.owner, di.index_name, di.table_name, di.uniqueness, CASE WHEN dic.column_name IN (SELECT column_name FROM ALL_TAB_COLUMNS WHERE data_type LIKE '%NUMBER%' AND identity_column = 'YES') THEN 'IDENTITY_COLUMN' ELSE 'OTHER' END AS key_type FROM ALL_INDEXES di JOIN ALL_IND_COLUMNS dic ON di.owner = dic.index_owner AND di.index_name = dic.index_name WHERE dic.column_position = 1 AND di.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB') ORDER BY di.owner, di.table_name"}	{"condition": "key_type = 'IDENTITY_COLUMN'", "description": "Indexes on identity/sequence columns create right-hand insert pattern causing hot block"}	\N	2026-02-28 12:19:19.580455
9019	oracle	query	ora-multi-vendor-complexity: check database links to other systems	{"sql": "SELECT owner, db_link, username, host, created FROM ALL_DB_LINKS ORDER BY created DESC"}	{"condition": "row_count > 0", "description": "Database links indicate multi-system integration requiring coordinated account management"}	\N	2026-02-28 12:19:19.580455
14737	mariadb	query	List service accounts with DDL privileges	{"sql": "SELECT User, Host, Create_priv, Alter_priv, Drop_priv FROM mysql.user WHERE Create_priv = 'Y' OR Alter_priv = 'Y' OR Drop_priv = 'Y' ORDER BY User"}	{"condition": "row_count > 0", "description": "Accounts with DDL privileges exist"}	\N	2026-05-11 22:17:39.229791
8402	oracle	query	Oracle find manual indexes duplicating constraint indexes	{"sql": "SELECT c.constraint_name, c.index_name AS constraint_index, i.index_name AS manual_index, c.table_name FROM ALL_CONSTRAINTS c JOIN ALL_INDEXES i ON c.table_name = i.table_name AND c.owner = i.owner AND c.index_name != i.index_name WHERE c.constraint_type IN ('P', 'U') AND c.owner NOT IN ('SYS', 'SYSTEM') AND EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ci WHERE ci.index_name = c.index_name AND ci.index_owner = c.owner AND ci.column_name IN (SELECT column_name FROM ALL_IND_COLUMNS WHERE index_name = i.index_name AND index_owner = i.owner) GROUP BY ci.index_name HAVING COUNT(*) = (SELECT COUNT(*) FROM ALL_IND_COLUMNS WHERE index_name = i.index_name AND index_owner = i.owner)) ORDER BY c.table_name"}	{"condition": "row_count > 0", "description": "Manual indexes duplicating constraint-generated indexes are redundant"}	\N	2026-02-28 12:19:19.580455
8404	oracle	query	Oracle find indexes on very low cardinality columns	{"sql": "SELECT i.index_name, i.table_name, tc.column_name, tc.num_distinct, t.num_rows, ROUND(tc.num_distinct / NULLIF(t.num_rows, 0) * 100, 4) AS selectivity_pct FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS ic ON i.index_name = ic.index_name AND i.owner = ic.index_owner JOIN ALL_TAB_COL_STATISTICS tc ON ic.table_name = tc.table_name AND ic.column_name = tc.column_name AND ic.index_owner = tc.owner JOIN ALL_TABLES t ON i.table_name = t.table_name AND i.owner = t.owner WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND tc.num_distinct <= 3 AND t.num_rows > :min_rows AND ic.column_position = 1 ORDER BY t.num_rows DESC"}	{"condition": "row_count > 0", "description": "Indexes on columns with 2-3 distinct values have poor selectivity and waste resources"}	{"min_rows": 10000}	2026-02-28 12:19:19.580455
8405	oracle	query	Oracle find indexes on low-cardinality categorical columns	{"sql": "SELECT i.index_name, i.table_name, tc.column_name, tc.num_distinct, t.num_rows FROM dba_indexes i JOIN dba_ind_columns ic ON i.index_name = ic.index_name AND i.owner = ic.index_owner JOIN dba_tab_col_statistics tc ON ic.table_name = tc.table_name AND ic.column_name = tc.column_name AND ic.index_owner = tc.owner JOIN dba_tables t ON i.table_name = t.table_name AND i.owner = t.owner WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND tc.num_distinct BETWEEN 4 AND 250 AND t.num_rows > 100000 AND ic.column_position = 1 ORDER BY t.num_rows / NULLIF(tc.num_distinct, 0) DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 with high avg_rows_per_value", "description": "Indexes on categorical columns where each value matches many rows are poorly selective"}	{"min_rows": 100000, "min_avg_rows": 1000}	2026-02-28 12:19:19.580455
8410	oracle	query	Oracle find composite indexes with low-cardinality leading column	{"sql": "SELECT i.index_name, i.table_name, lead_col.column_name AS leading_column, lead_stats.num_distinct AS lead_distinct, t.num_rows, ROUND(lead_stats.num_distinct / NULLIF(t.num_rows, 0) * 100, 4) AS lead_selectivity_pct FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS lead_col ON i.index_name = lead_col.index_name AND i.owner = lead_col.index_owner AND lead_col.column_position = 1 JOIN ALL_TAB_COL_STATISTICS lead_stats ON lead_col.table_name = lead_stats.table_name AND lead_col.column_name = lead_stats.column_name AND lead_col.index_owner = lead_stats.owner JOIN ALL_TABLES t ON i.table_name = t.table_name AND i.owner = t.owner WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND lead_stats.num_distinct < :max_lead_distinct AND t.num_rows > :min_rows AND (SELECT COUNT(*) FROM ALL_IND_COLUMNS WHERE index_name = i.index_name AND index_owner = i.owner) >= 2 ORDER BY lead_selectivity_pct ASC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 with very low lead_selectivity_pct", "description": "Composite indexes with non-selective leading columns force inefficient index range scans"}	{"min_rows": 100000, "max_lead_distinct": 20}	2026-02-28 12:19:19.580455
8419	oracle	query	Oracle find tables with excessive index count	{"sql": "SELECT table_owner, table_name, COUNT(*) AS index_count, SUM(leaf_blocks) AS total_leaf_blocks FROM ALL_INDEXES WHERE table_owner NOT IN ('SYS', 'SYSTEM') AND status = 'VALID' GROUP BY table_owner, table_name HAVING COUNT(*) > :max_indexes ORDER BY index_count DESC"}	{"condition": "row_count > 0", "description": "Tables with more indexes than recommended — each index adds DML overhead"}	{"max_indexes": 8}	2026-02-28 12:19:19.580455
8424	oracle	query	Oracle find overlapping composite indexes by leading columns	{"sql": "SELECT a.index_owner, a.table_name, a.index_name AS index1, b.index_name AS index2, a.column_name AS shared_leading_column FROM ALL_IND_COLUMNS a JOIN ALL_IND_COLUMNS b ON a.table_owner = b.table_owner AND a.table_name = b.table_name AND a.column_name = b.column_name AND a.column_position = 1 AND b.column_position = 1 AND a.index_name < b.index_name WHERE a.index_owner NOT IN ('SYS', 'SYSTEM') ORDER BY a.table_owner, a.table_name, a.index_name"}	{"condition": "row_count > 0", "description": "Multiple indexes on same table share the same leading column — candidates for consolidation"}	\N	2026-02-28 12:19:19.580455
8427	oracle	query	Oracle find wide composite indexes	{"sql": "SELECT i.owner, i.index_name, i.table_name, COUNT(ic.column_name) AS column_count, LISTAGG(ic.column_name, ', ') WITHIN GROUP (ORDER BY ic.column_position) AS columns FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS ic ON i.owner = ic.index_owner AND i.index_name = ic.index_name WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND i.index_type = 'NORMAL' GROUP BY i.owner, i.index_name, i.table_name HAVING COUNT(ic.column_name) >= :min_columns ORDER BY column_count DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Wide composite indexes found — may be created for individual column queries rather than composite access"}	{"min_columns": 4}	2026-02-28 12:19:19.580455
8433	oracle	query	Oracle check total index count vs table count	{"sql": "SELECT (SELECT COUNT(*) FROM ALL_INDEXES WHERE owner NOT IN ('SYS', 'SYSTEM')) AS total_indexes, (SELECT COUNT(*) FROM ALL_TABLES WHERE owner NOT IN ('SYS', 'SYSTEM')) AS total_tables, ROUND((SELECT COUNT(*) FROM ALL_INDEXES WHERE owner NOT IN ('SYS', 'SYSTEM')) / NULLIF((SELECT COUNT(*) FROM ALL_TABLES WHERE owner NOT IN ('SYS', 'SYSTEM')), 0), 2) AS indexes_per_table FROM dual"}	{"condition": "indexes_per_table > :threshold", "description": "Average indexes per table exceeds threshold — index sprawl without maintenance policy"}	{"threshold": 5}	2026-02-28 12:19:19.580455
8741	oracle	query	Oracle check index fragmentation via blevel	{"sql": "SELECT owner, index_name, table_name, blevel, leaf_blocks, distinct_keys, ROUND(leaf_blocks * 8192 / 1024 / 1024) AS index_mb FROM ALL_INDEXES WHERE owner NOT IN ('SYS', 'SYSTEM') AND blevel > :max_blevel AND leaf_blocks > 1000 ORDER BY blevel DESC, leaf_blocks DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with deep B-tree levels — fragmentation increasing index access I/O"}	{"max_blevel": 3}	2026-02-28 12:19:19.580455
13800	mariadb	query	Check for large table scans indicating volume spike	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, AVG_TIMER_WAIT/1000000000 AS avg_ms, FIRST_SEEN, LAST_SEEN FROM performance_schema.events_statements_summary_by_digest WHERE SUM_ROWS_EXAMINED > :row_threshold ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries examining large row counts suggest volume spike in source data"}	{"row_threshold": 10000000}	2026-05-11 22:17:39.229791
8436	oracle	query	Oracle find tables with wide primary keys	{"sql": "SELECT cc.owner, cc.table_name, cc.constraint_name, COUNT(cc.column_name) AS pk_column_count, SUM(tc.avg_col_len) AS pk_avg_bytes FROM ALL_CONS_COLUMNS cc JOIN ALL_CONSTRAINTS c ON cc.owner = c.owner AND cc.constraint_name = c.constraint_name JOIN ALL_TAB_COLUMNS tc ON cc.owner = tc.owner AND cc.table_name = tc.table_name AND cc.column_name = tc.column_name WHERE c.constraint_type = 'P' AND cc.owner NOT IN ('SYS', 'SYSTEM') GROUP BY cc.owner, cc.table_name, cc.constraint_name HAVING SUM(tc.avg_col_len) > :width_threshold OR COUNT(cc.column_name) > 3 ORDER BY SUM(tc.avg_col_len) DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with wide or multi-column primary keys — every secondary index includes ROWID + PK overhead"}	{"width_threshold": 50}	2026-02-28 12:19:19.580455
8439	oracle	query	Oracle find composite indexes with large total key width	{"sql": "SELECT ic.index_owner, ic.index_name, ic.table_name, COUNT(*) AS num_columns, SUM(tc.avg_col_len) AS total_avg_key_width, LISTAGG(ic.column_name || '(' || tc.avg_col_len || 'B)', ', ') WITHIN GROUP (ORDER BY ic.column_position) AS column_details FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COLUMNS tc ON ic.table_owner = tc.owner AND ic.table_name = tc.table_name AND ic.column_name = tc.column_name WHERE ic.index_owner NOT IN ('SYS', 'SYSTEM') GROUP BY ic.index_owner, ic.index_name, ic.table_name HAVING SUM(tc.avg_col_len) > :width_threshold AND COUNT(*) >= 3 ORDER BY total_avg_key_width DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Composite indexes with combined key width exceeding threshold — large index entries reducing cache efficiency"}	{"width_threshold": 100}	2026-02-28 12:19:19.580455
8442	oracle	query	ora-nonselective-leading-col: find indexes with low-selectivity leading columns	{"sql": "SELECT ic.index_owner, ic.index_name, ic.column_name, ic.column_position, tc.num_distinct, tc.num_nulls, t.num_rows, ROUND(tc.num_distinct / NULLIF(t.num_rows, 0) * 100, 2) AS selectivity_pct FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COL_STATISTICS tc ON tc.owner = ic.table_owner AND tc.table_name = ic.table_name AND tc.column_name = ic.column_name JOIN ALL_TABLES t ON t.owner = ic.table_owner AND t.table_name = ic.table_name WHERE ic.column_position = 1 AND ic.index_owner NOT IN ('SYS', 'SYSTEM') AND t.num_rows > 10000 AND tc.num_distinct / NULLIF(t.num_rows, 0) < :threshold_selectivity ORDER BY selectivity_pct FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Leading index columns with low selectivity reduce index range scan efficiency"}	{"threshold_selectivity": 0.01}	2026-02-28 12:19:19.580455
8450	oracle	query	ora-binary-index-key: find indexes on RAW/binary columns	{"sql": "SELECT ic.index_owner, ic.index_name, ic.table_name, ic.column_name, tc.data_type, tc.data_length FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COLUMNS tc ON tc.owner = ic.table_owner AND tc.table_name = ic.table_name AND tc.column_name = ic.column_name WHERE tc.data_type IN ('RAW', 'LONG RAW') AND ic.index_owner NOT IN ('SYS', 'SYSTEM') ORDER BY tc.data_length DESC"}	{"condition": "row_count > 0", "description": "Indexes on RAW columns contain binary data that widens index entries"}	\N	2026-02-28 12:19:19.580455
8453	oracle	query	ora-index-width-opt: find composite indexes with suboptimal column ordering	{"sql": "SELECT ic.index_owner, ic.index_name, ic.table_name, ic.column_name, ic.column_position FROM dba_ind_columns ic WHERE ic.index_owner NOT IN ('SYS', 'SYSTEM') AND ic.index_name IN (SELECT index_name FROM dba_ind_columns GROUP BY index_owner, index_name HAVING COUNT(*) >= 3) ORDER BY ic.index_owner, ic.index_name, ic.column_position FETCH FIRST 30 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Review column ordering in composite indexes for width optimization opportunities"}	\N	2026-02-28 12:19:19.580455
8500	oracle	query	ORA find unindexed foreign key columns	{"sql": "SELECT c.owner, c.table_name AS child_table, cc.column_name, c.constraint_name, rc.table_name AS parent_table FROM ALL_CONSTRAINTS c JOIN ALL_CONS_COLUMNS cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner JOIN ALL_CONSTRAINTS rc ON c.r_constraint_name = rc.constraint_name AND c.r_owner = rc.owner WHERE c.constraint_type = 'R' AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ic WHERE ic.table_owner = cc.owner AND ic.table_name = cc.table_name AND ic.column_name = cc.column_name AND ic.column_position = cc.position) AND c.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB') ORDER BY c.owner, c.table_name"}	{"condition": "row_count > 0", "description": "Unindexed foreign keys cause Share TM locks on child table during parent DML"}	\N	2026-02-28 12:19:19.580455
8501	oracle	query	ORA check enqueue resource utilization	{"sql": "SELECT resource_name, current_utilization, max_utilization, limit_value, CASE WHEN TRIM(limit_value) != 'UNLIMITED' AND REGEXP_LIKE(TRIM(limit_value), '^[0-9]+$') THEN ROUND(max_utilization / NULLIF(TO_NUMBER(TRIM(limit_value)), 0) * 100, 1) ELSE NULL END AS peak_pct FROM v$resource_limit WHERE resource_name IN ('enqueue_locks', 'enqueue_resources', 'dml_locks') ORDER BY resource_name"}	{"condition": "peak_pct > :threshold_pct", "description": "High enqueue resource utilization indicates lock structure exhaustion"}	{"threshold_pct": 80}	2026-02-28 12:19:19.580455
14719	mariadb	log_scan	Check error log for configuration loading messages	{"sql": "SELECT @@log_error AS error_log_path"}	{"condition": "error_log contains references to included config files", "description": "Multiple config files may override audit settings"}	\N	2026-05-11 22:17:39.229791
8519	oracle	query	ora_find_bitmap_indexes_on_dml_tables	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.index_type, m.inserts + m.updates + m.deletes AS total_dml FROM ALL_INDEXES i JOIN ALL_TAB_MODIFICATIONS m ON i.table_owner = m.table_owner AND i.table_name = m.table_name WHERE i.index_type = 'BITMAP' AND i.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND (m.inserts + m.updates + m.deletes) > :min_dml ORDER BY total_dml DESC"}	{"condition": "row_count > 0", "description": "Bitmap indexes on tables with significant DML activity cause severe lock contention"}	{"min_dml": 1000}	2026-02-28 12:19:19.580455
8535	oracle	query	ora_check_high_pctfree_tables [PERF-SQL-LC-004-RC04]	{"sql": "SELECT owner, table_name, pct_free, num_rows, blocks, avg_row_len FROM ALL_TABLES WHERE pct_free > :max_pctfree AND owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND num_rows > 10000 ORDER BY blocks DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with excessive PCTFREE waste space and may increase I/O for full scans"}	{"max_pctfree": 30}	2026-02-28 12:19:19.580455
8545	oracle	query	ora_check_initrans_settings	{"sql": "SELECT owner, table_name, ini_trans, max_trans, pct_free FROM ALL_TABLES WHERE owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND ini_trans < :min_initrans AND num_rows > 10000 ORDER BY num_rows DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with low INITRANS may not have enough ITL slots for concurrent transactions on the same block"}	{"min_initrans": 3}	2026-02-28 12:19:19.580455
8561	oracle	query	ora_check_idle_txn_blocking_others	{"sql": "SELECT b.sid AS blocker_sid, b.serial# AS blocker_serial, b.username AS blocker_user, b.program AS blocker_program, b.status AS blocker_status, w.sid AS waiter_sid FROM v$session w JOIN v$session b ON w.blocking_session = b.sid WHERE b.status = 'INACTIVE' AND b.taddr IS NOT NULL"}	{"condition": "row_count > 0", "description": "Inactive sessions blocking active sessions confirm application processing delay causing lock contention"}	\N	2026-02-28 12:19:19.580455
8581	oracle	query	ora_check_memory_pressure_indicators	{"sql": "SELECT name, TO_CHAR(value) AS value FROM v$pgastat WHERE name IN ('over allocation count', 'extra bytes read/written', 'cache hit percentage', 'maximum PGA allocated') UNION ALL SELECT 'buffer_cache_hit_pct', TO_CHAR(ROUND((1 - physical.value / (db_block_gets.value + consistent_gets.value)) * 100, 2)) FROM v$sysstat physical, v$sysstat db_block_gets, v$sysstat consistent_gets WHERE physical.name = 'physical reads' AND db_block_gets.name = 'db block gets' AND consistent_gets.name = 'consistent gets'"}	{"condition": "over allocation count > 0 OR cache hit percentage < 80 OR buffer_cache_hit_pct < 90", "description": "PGA over-allocation or low cache hit ratios confirm insufficient RAM allocation"}	\N	2026-02-28 12:19:19.580455
