8601	oracle	query	ora-check-bloated-tables-in-cache	{"sql": "SELECT owner, table_name, ROUND(blocks * 8192 / 1024 / 1024, 1) AS allocated_mb, num_rows, avg_row_len, ROUND(num_rows * avg_row_len / 1024 / 1024, 1) AS data_mb, ROUND((blocks * 8192 - num_rows * avg_row_len) / NULLIF(blocks * 8192, 0) * 100, 1) AS waste_pct FROM ALL_TABLES WHERE owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP', 'OUTLN', 'XDB') AND blocks > 10000 AND num_rows > 0 AND (blocks * 8192 - num_rows * avg_row_len) / NULLIF(blocks * 8192, 0) * 100 > :waste_threshold ORDER BY blocks DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with high space waste consume more buffer cache blocks than data warrants"}	{"waste_threshold": 40}	2026-02-28 12:19:19.580455
8603	oracle	query	ora-check-sql-tuning-advisor-findings	{"sql": "SELECT sql_id, SUBSTR(sql_text, 1, 200) AS sql_text, buffer_gets, executions FROM v$sql WHERE buffer_gets / NULLIF(executions, 0) > 100000 ORDER BY buffer_gets DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Top resource-consuming SQL with full table scans confirms missing optimization"}	{"cost_threshold": 10000}	2026-02-28 12:19:19.580455
8609	oracle	query	ora-check-stale-missing-statistics	{"sql": "SELECT owner, table_name, num_rows, last_analyzed, stale_stats, ROUND(SYSDATE - last_analyzed) AS days_stale FROM ALL_TAB_STATISTICS WHERE (stale_stats = 'YES' OR last_analyzed IS NULL) AND owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP', 'OUTLN', 'XDB') AND (num_rows > 1000 OR num_rows IS NULL) ORDER BY num_rows DESC NULLS FIRST FETCH FIRST 30 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with stale or missing statistics — optimizer relies on default assumptions"}	\N	2026-02-28 12:19:19.580455
8619	oracle	query	ora_check_column_histogram_skew [PERF-SQL-MEM-002-RC07]	{"sql": "SELECT tc.TABLE_NAME, tc.COLUMN_NAME, tc.NUM_DISTINCT, tc.NUM_NULLS, tc.HISTOGRAM FROM DBA_TAB_COLUMNS tc WHERE tc.HISTOGRAM != 'NONE' AND tc.OWNER NOT IN ('SYS', 'SYSTEM') AND tc.NUM_DISTINCT < 100 ORDER BY tc.TABLE_NAME, tc.COLUMN_NAME FETCH FIRST 30 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Histogram data confirms data skew on join columns"}	{"low_cardinality": 100}	2026-02-28 12:19:19.580455
8622	oracle	query	ora_find_wide_row_tables	{"sql": "SELECT t.OWNER, t.TABLE_NAME, t.AVG_ROW_LEN, t.NUM_ROWS, ROUND(t.AVG_ROW_LEN * t.NUM_ROWS / 1048576, 1) AS estimated_data_mb, (SELECT COUNT(*) FROM ALL_TAB_COLUMNS c WHERE c.TABLE_NAME = t.TABLE_NAME AND c.OWNER = t.OWNER AND c.DATA_TYPE IN ('CLOB', 'BLOB', 'NCLOB', 'LONG', 'LONG RAW')) AS lob_columns FROM ALL_TABLES t WHERE t.AVG_ROW_LEN > :wide_row_threshold AND t.NUM_ROWS > :min_rows AND t.OWNER NOT IN ('SYS', 'SYSTEM') ORDER BY t.AVG_ROW_LEN DESC FETCH FIRST 15 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with very wide rows that consume excessive memory during query processing"}	{"min_rows": 10000, "wide_row_threshold": 2000}	2026-02-28 12:19:19.580455
8633	oracle	query	ora_compare_active_data_to_cache	{"sql": "SELECT ROUND((SELECT CURRENT_SIZE FROM V$SGA_DYNAMIC_COMPONENTS WHERE COMPONENT = 'DEFAULT buffer cache') / 1048576, 1) AS cache_size_mb, (SELECT VALUE FROM V$SYSSTAT WHERE NAME = 'physical reads') AS phys_reads, (SELECT VALUE FROM V$SYSSTAT WHERE NAME = 'consistent gets') + (SELECT VALUE FROM V$SYSSTAT WHERE NAME = 'db block gets') AS logical_reads FROM DUAL"}	{"condition": "phys_reads / NULLIF(logical_reads, 0) > :phys_read_ratio", "description": "High physical to logical read ratio — working set exceeds cache"}	{"phys_read_ratio": 0.15}	2026-02-28 12:19:19.580455
8637	oracle	query	ora_find_fragmented_indexes_wasting_cache	{"sql": "SELECT i.OWNER, i.INDEX_NAME, i.TABLE_NAME, i.BLEVEL, i.LEAF_BLOCKS, i.CLUSTERING_FACTOR, t.BLOCKS AS table_blocks, ROUND(i.CLUSTERING_FACTOR / NULLIF(t.BLOCKS, 0), 2) AS cf_ratio FROM ALL_INDEXES i JOIN ALL_TABLES t ON i.TABLE_NAME = t.TABLE_NAME AND i.OWNER = t.OWNER WHERE i.BLEVEL > :max_blevel AND t.NUM_ROWS > :min_rows AND i.OWNER NOT IN ('SYS', 'SYSTEM') ORDER BY i.LEAF_BLOCKS DESC FETCH FIRST 15 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with excessive depth and poor clustering consuming extra buffer cache"}	{"min_rows": 100000, "max_blevel": 3}	2026-02-28 12:19:19.580455
8640	oracle	query	ora_find_oversized_column_definitions	{"sql": "SELECT c.OWNER, c.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE, c.DATA_LENGTH, c.AVG_COL_LEN, ROUND((c.DATA_LENGTH - NVL(c.AVG_COL_LEN, 0)) / NULLIF(c.DATA_LENGTH, 0) * 100, 1) AS waste_pct FROM ALL_TAB_COLUMNS c WHERE c.DATA_TYPE IN ('VARCHAR2', 'NVARCHAR2', 'RAW') AND c.DATA_LENGTH > :max_length AND c.AVG_COL_LEN IS NOT NULL AND c.AVG_COL_LEN < c.DATA_LENGTH * 0.1 AND c.OWNER NOT IN ('SYS', 'SYSTEM') ORDER BY waste_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Columns with large declared length but small actual usage"}	{"max_length": 1000}	2026-02-28 12:19:19.580455
