8643	oracle	query	ora_check_index_split_indicator	{"sql": "SELECT i.INDEX_NAME, i.TABLE_NAME, i.LEAF_BLOCKS, i.DISTINCT_KEYS, ROUND(i.DISTINCT_KEYS / NULLIF(i.LEAF_BLOCKS, 0), 1) AS keys_per_leaf FROM ALL_INDEXES i WHERE i.DISTINCT_KEYS / NULLIF(i.LEAF_BLOCKS, 0) < :density_threshold AND i.LEAF_BLOCKS > :min_leaves AND i.OWNER NOT IN ('SYS', 'SYSTEM') ORDER BY keys_per_leaf FETCH FIRST 15 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with low key density per leaf block — 50/50 splits from random inserts"}	{"min_leaves": 1000, "density_threshold": 50}	2026-02-28 12:19:19.580455
