8658	oracle	query	ora-check-columns-without-histograms	{"sql": "SELECT tc.owner, tc.table_name, tc.column_name, tc.num_distinct, tc.density, tc.histogram, t.num_rows, ROUND(tc.num_distinct / NULLIF(t.num_rows, 0) * 100, 2) AS distinct_pct FROM ALL_TAB_COL_STATISTICS tc JOIN ALL_TABLES t ON tc.owner = t.owner AND tc.table_name = t.table_name WHERE tc.owner NOT IN ('SYS', 'SYSTEM') AND tc.histogram = 'NONE' AND t.num_rows > :row_threshold AND tc.num_distinct < t.num_rows * :skew_ratio ORDER BY t.num_rows DESC FETCH FIRST 15 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Columns with low distinct values but no histogram may have skewed data that causes optimizer estimation errors"}	{"skew_ratio": 0.1, "row_threshold": 10000}	2026-02-28 12:19:19.580455
