623	sqlserver	query	Check merge replication conflicts with timestamp analysis	{"sql": "IF OBJECT_ID('MSmerge_conflicts_info') IS NOT NULL BEGIN\\nSELECT ct.tablenick, ct.rowguid, ct.origin_datasource, ct.conflict_type, ct.reason_code, ct.reason_text, ct.create_date, ct.pubid FROM MSmerge_conflicts_info ct WHERE ct.create_date > DATEADD(day, -7, GETDATE()) ORDER BY ct.create_date DESC\\nEND ELSE BEGIN\\nSELECT NULL AS not_configured WHERE 1=0\\nEND"}	{"condition": "row_count > 0", "description": "Merge replication conflicts detected — check if origin_datasource timestamps show clock skew patterns"}	null	2026-02-23 20:18:31.389219
632	sqlserver	query	Check for unresolved or recent conflicts	{"sql": "IF OBJECT_ID('sys.merge_articles') IS NOT NULL BEGIN\\nSELECT ct.name AS conflict_table, a.name AS article,\\n  p.name AS publication,\\n  (SELECT COUNT(*) FROM sys.objects WHERE name = ct.name AND type = 'U') AS table_exists\\nFROM sys.objects ct\\nJOIN sys.merge_articles a ON ct.object_id = a.conflict_table_id\\nJOIN sys.merge_publications p ON a.pubid = p.pubid\\nWHERE ct.type = 'U'\\n  AND (a.article_resolver IS NULL OR a.article_resolver = '')\\nORDER BY ct.create_date DESC\\nEND ELSE BEGIN\\nSELECT NULL AS no_merge_replication WHERE 1=0\\nEND"}	{"condition": "conflict tables exist for articles with default resolver", "description": "Conflicts occurring on articles without explicit conflict resolution configuration"}	null	2026-02-23 20:18:31.389224
799	sqlserver	query	Check SQL Server Audit file configuration and size	{"sql": "SELECT a.name AS audit_name, CASE WHEN a.is_state_enabled = 1 THEN 'ENABLED' ELSE 'DISABLED' END AS audit_status, a.type_desc AS audit_type, a.on_failure_desc, a.queue_delay, sfa.max_file_size, sfa.max_rollover_files, sfa.log_file_path FROM sys.server_audits a LEFT JOIN sys.server_file_audits sfa ON a.audit_id = sfa.audit_id"}	{"condition": "max_rollover_files = 0 OR max_rollover_files > 100", "description": "Active audit with unlimited or excessive rollover files — files will accumulate without bound"}	null	2026-02-23 20:18:31.389338
800	sqlserver	query	Check Extended Events sessions with file targets	{"sql": "SELECT ses.name AS session_name,\\n  st.target_name,\\n  CAST(stc.column_value AS nvarchar(256)) AS filename,\\n  CAST(stcm.column_value AS bigint) AS max_file_size_bytes,\\n  CAST(stcr.column_value AS int) AS max_rollover_files\\nFROM sys.dm_xe_sessions ses\\nJOIN sys.dm_xe_session_targets st ON ses.address = st.event_session_address\\nLEFT JOIN sys.dm_xe_session_object_columns stc\\n  ON st.event_session_address = stc.event_session_address\\n  AND st.target_name = stc.object_name AND stc.column_name = 'filename'\\nLEFT JOIN sys.dm_xe_session_object_columns stcm\\n  ON st.event_session_address = stcm.event_session_address\\n  AND st.target_name = stcm.object_name AND stcm.column_name = 'max_file_size'\\nLEFT JOIN sys.dm_xe_session_object_columns stcr\\n  ON st.event_session_address = stcr.event_session_address\\n  AND st.target_name = stcr.object_name AND stcr.column_name = 'max_rollover_files'\\nWHERE st.target_name = 'event_file'\\n  AND (CAST(stcr.column_value AS int) = 0 OR CAST(stcr.column_value AS int) > 50)"}	{"condition": "max_rollover_files = 0 OR > 50", "description": "Extended Events file targets with unlimited or excessive rollover — files accumulate on disk"}	null	2026-02-23 20:18:31.389339
11600	mysql	config_check	Check RSA rootcause key configuration for caching_sha2_password	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'caching_sha2_password_public_key_path') AS caching_sha2_password_public_key_path, @@sha256_password_public_key_path AS sha256_password_public_key_path"}	{"condition": "value IS NOT NULL AND value != ''", "description": "RSA key paths are configured for authentication"}	\N	2026-03-01 06:30:58.706791
850	sqlserver	query	Verify frequent auto-growth events from default trace	{"sql": "SELECT DB_NAME(t.DatabaseId) AS database_name,\\n  t.FileName,\\n  COUNT(*) AS growth_events_7d,\\n  SUM(t.IntegerData * 8 / 1024) AS total_growth_mb,\\n  AVG(t.Duration / 1000) AS avg_duration_ms\\nFROM sys.fn_trace_gettable((SELECT path FROM sys.traces WHERE is_default = 1), DEFAULT) t\\nJOIN sys.trace_events te ON t.EventClass = te.trace_event_id\\nWHERE te.name IN ('Data File Auto Grow', 'Log File Auto Grow')\\n  AND t.StartTime > DATEADD(day, -7, GETDATE())\\nGROUP BY t.DatabaseId, t.FileName\\nHAVING COUNT(*) > 5\\nORDER BY growth_events_7d DESC"}	{"condition": "growth_events_7d > 5", "description": "Multiple growth events per week confirm increments are too small"}	null	2026-02-23 20:18:31.389368
852	sqlserver	query	Check for recent auto-growth events correlated with bulk loads	{"sql": "SELECT\\n  te.name AS event_name,\\n  DB_NAME(t.DatabaseId) AS database_name,\\n  t.FileName,\\n  t.IntegerData * 8 / 1024 AS growth_mb,\\n  t.Duration / 1000 AS duration_ms,\\n  t.StartTime\\nFROM sys.fn_trace_gettable((SELECT path FROM sys.traces WHERE is_default = 1), DEFAULT) t\\nJOIN sys.trace_events te ON t.EventClass = te.trace_event_id\\nWHERE te.name IN ('Data File Auto Grow', 'Log File Auto Grow')\\n  AND t.StartTime > DATEADD(hour, -4, GETDATE())\\nORDER BY t.StartTime DESC"}	{"condition": "row_count > 3 in last 4 hours", "description": "Multiple recent auto-growth events coinciding with bulk operations"}	null	2026-02-23 20:18:31.389369
862	sqlserver	query	Check for recent auto-growth events that went unmonitored	{"sql": "SELECT DB_NAME(t.DatabaseId) AS database_name,\\n  COUNT(*) AS growth_events,\\n  MAX(t.StartTime) AS last_growth_time,\\n  SUM(t.IntegerData * 8 / 1024) AS total_growth_mb\\nFROM sys.fn_trace_gettable((SELECT path FROM sys.traces WHERE is_default = 1), DEFAULT) t\\nJOIN sys.trace_events te ON t.EventClass = te.trace_event_id\\nWHERE te.name IN ('Data File Auto Grow', 'Log File Auto Grow')\\n  AND t.StartTime > DATEADD(day, -7, GETDATE())\\nGROUP BY t.DatabaseId\\nHAVING COUNT(*) > 3\\nORDER BY growth_events DESC"}	{"condition": "growth_events > 3 with no alerts configured", "description": "Frequent auto-growth events occurring with no monitoring in place"}	null	2026-02-23 20:18:31.389376
902	sqlserver	query	Check for memory-related errors and access violations	{"sql": "CREATE TABLE #log(LogDate DATETIME, ProcessInfo NVARCHAR(50), Text NVARCHAR(MAX)); INSERT INTO #log EXEC xp_readerrorlog 0, 1, N'Access violation'; INSERT INTO #log EXEC xp_readerrorlog 0, 1, N'stack dump'; INSERT INTO #log EXEC xp_readerrorlog 0, 1, N'AppDomain'; SELECT * FROM #log ORDER BY LogDate DESC; DROP TABLE #log;"}	{"condition": "row_count > 0", "description": "Access violations or stack dumps indicating memory corruption"}	null	2026-02-23 20:18:31.3894
916	sqlserver	query	Check if running in a virtual machine	{"sql": "SELECT virtual_machine_type,\\n  virtual_machine_type_desc,\\n  softnuma_configuration_desc,\\n  socket_count, cores_per_socket, numa_node_count\\nFROM sys.dm_os_sys_info"}	{"condition": "hypervisor_present = 1", "description": "SQL Server is running inside a virtual machine"}	null	2026-02-23 20:18:31.389407
985	sqlserver	query	Check for databases with version store log reuse wait	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  d.snapshot_isolation_state_desc,\\n  d.is_read_committed_snapshot_on,\\n  ls.total_log_size_in_bytes / 1048576 AS log_size_mb,\\n  ls.used_log_space_in_percent\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nWHERE d.log_reuse_wait_desc = 'ACTIVE_TRANSACTION'\\n  AND (d.snapshot_isolation_state_desc = 'ON'\\n    OR d.is_read_committed_snapshot_on = 1)\\n  AND ls.used_log_space_in_percent > 50"}	{"condition": "row_count > 0", "description": "Databases with snapshot isolation enabled and log blocked by active transactions"}	null	2026-02-23 20:18:31.389453
986	sqlserver	query	Check version store size and longest running transaction	{"sql": "SELECT (SELECT SUM(version_store_reserved_page_count) * 8 / 1024 FROM tempdb.sys.dm_db_file_space_usage) AS version_store_mb, t.transaction_id, t.name AS tran_name, t.transaction_begin_time, DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS duration_sec, s.login_name, s.host_name FROM sys.dm_tran_active_transactions t LEFT JOIN sys.dm_tran_session_transactions st ON t.transaction_id = st.transaction_id LEFT JOIN sys.dm_exec_sessions s ON st.session_id = s.session_id WHERE t.transaction_begin_time < DATEADD(MINUTE, -5, GETDATE()) ORDER BY t.transaction_begin_time ASC"}	{"condition": "version_store_mb > 100 or elapsed_time_seconds > 300", "description": "Large version store with long-running snapshot transactions preventing cleanup"}	null	2026-02-23 20:18:31.389453
987	sqlserver	query	Check current log_reuse_wait status across all databases	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  d.recovery_model_desc,\\n  ls.total_log_size_in_bytes / 1048576 AS log_size_mb,\\n  ls.used_log_space_in_percent,\\n  d.state_desc\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nWHERE d.log_reuse_wait_desc NOT IN ('NOTHING', 'CHECKPOINT')\\n  AND d.database_id > 4\\n  AND ls.used_log_space_in_percent > 50\\nORDER BY ls.used_log_space_in_percent DESC"}	{"condition": "row_count > 0 with log_reuse_wait_desc indicating active blocking condition", "description": "Databases with non-trivial log reuse wait and high log utilization"}	null	2026-02-23 20:18:31.389454
1069	sqlserver	query	Check system drive space and tempdb location	{"sql": "SELECT DISTINCT\\n  vs.volume_mount_point,\\n  vs.available_bytes / 1073741824 AS available_gb,\\n  vs.total_bytes / 1073741824 AS total_gb,\\n  mf.physical_name,\\n  DB_NAME(mf.database_id) AS db_name,\\n  vs.available_bytes\\nFROM sys.master_files mf\\nCROSS APPLY sys.dm_os_volume_stats(mf.database_id, mf.file_id) vs\\nWHERE mf.database_id IN (1, 2, 3, 4)\\nORDER BY vs.available_bytes ASC"}	{"condition": "available_gb < 5 on any system database volume", "description": "Low space on system database volumes (master, msdb, model, tempdb) directly blocks CU installation"}	null	2026-02-23 20:18:31.389501
1402	sqlserver	query	Check scheduler load and runnable task queue	{"sql": "SELECT scheduler_id, cpu_id,\\n  current_tasks_count, runnable_tasks_count,\\n  active_workers_count, work_queue_count,\\n  context_switches_count, load_factor,\\n  yield_count\\nFROM sys.dm_os_schedulers\\nWHERE scheduler_id < 255 AND is_online = 1\\nORDER BY runnable_tasks_count DESC"}	{"condition": "runnable_task_count > 2 on multiple schedulers", "description": "Tasks queued waiting for CPU on multiple schedulers — thread over-subscription"}	null	2026-02-23 20:18:31.389568
988	sqlserver	query	Correlate log reuse wait reason with underlying condition	{"sql": "SELECT d.name AS database_name,\\n  d.log_reuse_wait_desc,\\n  ls.used_log_space_in_percent,\\n  CASE d.log_reuse_wait_desc\\n    WHEN 'LOG_BACKUP' THEN 'Full recovery with no log backups. Last backup: ' + ISNULL(CONVERT(VARCHAR, b.last_log_backup), 'NEVER')\\n    WHEN 'ACTIVE_TRANSACTION' THEN 'Open transaction since: ' + ISNULL(CONVERT(VARCHAR, t.oldest_begin, 120), 'unknown')\\n    WHEN 'REPLICATION' THEN 'Log reader agent behind or distribution agent stalled'\\n    WHEN 'AVAILABILITY_REPLICA' THEN 'AG secondary not caught up'\\n    WHEN 'DATABASE_MIRRORING' THEN 'Mirror session behind'\\n    ELSE d.log_reuse_wait_desc + ' — investigate manually'\\n  END AS diagnosis\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nOUTER APPLY (\\n  SELECT MAX(bs.backup_finish_date) AS last_log_backup\\n  FROM msdb.dbo.backupset bs\\n  WHERE bs.database_name = d.name AND bs.type = 'L'\\n) b\\nOUTER APPLY (\\n  SELECT MIN(at2.transaction_begin_time) AS oldest_begin\\n  FROM sys.dm_tran_active_transactions at2\\n  JOIN sys.dm_tran_database_transactions dt ON at2.transaction_id = dt.transaction_id\\n  WHERE dt.database_id = d.database_id\\n) t\\nWHERE d.log_reuse_wait_desc NOT IN ('NOTHING', 'CHECKPOINT')\\n  AND d.database_id > 4\\n  AND ls.used_log_space_in_percent > 50\\nORDER BY ls.used_log_space_in_percent DESC"}	{"condition": "blocking condition active and unresolved", "description": "Confirmed log reuse blocked by specific unaddressed condition with diagnostic detail"}	null	2026-02-23 20:18:31.389454
989	sqlserver	query	Check for recent backup failures and log backup gaps	{"sql": "SELECT d.name AS database_name,\\n  d.recovery_model_desc,\\n  d.log_reuse_wait_desc,\\n  ls.used_log_space_in_percent,\\n  b.last_log_backup,\\n  DATEDIFF(HOUR, b.last_log_backup, GETDATE()) AS hours_since_last_log_backup\\nFROM sys.databases d\\nCROSS APPLY sys.dm_db_log_space_usage ls\\nOUTER APPLY (\\n  SELECT MAX(bs.backup_finish_date) AS last_log_backup\\n  FROM msdb.dbo.backupset bs\\n  WHERE bs.database_name = d.name AND bs.type = 'L'\\n) b\\nWHERE d.recovery_model_desc = 'FULL'\\n  AND d.database_id > 4\\n  AND (b.last_log_backup IS NULL OR DATEDIFF(HOUR, b.last_log_backup, GETDATE()) > 4)\\n  AND ls.used_log_space_in_percent > 50"}	{"condition": "row_count > 0 with hours_since_last_log_backup > 4", "description": "FULL recovery databases with stale or missing log backups and growing logs"}	null	2026-02-23 20:18:31.389455
994	sqlserver	query	Confirm log is undersized relative to usage patterns	{"sql": "SELECT DB_NAME(database_id) AS database_name,\\n  total_log_size_in_bytes / 1048576 AS total_log_mb,\\n  used_log_space_in_bytes / 1048576 AS used_log_mb,\\n  used_log_space_in_percent,\\n  log_space_in_bytes_since_last_backup / 1048576 AS log_since_backup_mb\\nFROM sys.dm_db_log_space_usage\\nWHERE database_id > 4\\n  AND used_log_space_in_percent > 70\\nORDER BY used_log_space_in_percent DESC"}	{"condition": "used_log_space_in_percentage > 70", "description": "Log files consistently near capacity, confirming insufficient pre-sizing"}	null	2026-02-23 20:18:31.389459
1009	sqlserver	query	Check if hitting edition resource limits	{"sql": "SELECT SERVERPROPERTY('Edition') AS edition, SERVERPROPERTY('ProductVersion') AS version, sm.total_physical_memory_kb / 1024 AS total_memory_mb, si.cpu_count AS logical_cpus, si.max_workers_count, (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE counter_name = 'Target Server Memory (KB)' AND object_name LIKE '%Memory Manager%') / 1024 AS target_memory_mb, CASE WHEN CAST(SERVERPROPERTY('Edition') AS VARCHAR(100)) LIKE '%Express%' THEN 'EXPRESS_LIMITED' WHEN CAST(SERVERPROPERTY('Edition') AS VARCHAR(100)) LIKE '%Standard%' THEN 'STANDARD_LIMITED' ELSE 'ENTERPRISE' END AS edition_tier FROM sys.dm_os_sys_memory sm CROSS JOIN sys.dm_os_sys_info si"}	{"condition": "resource_pressure IN ('CRITICAL', 'WARNING')", "description": "Instance hitting edition resource limits, confirming budget/licensing constraint"}	null	2026-02-23 20:18:31.389468
1491	sqlserver	query	Check for ghost records and forwarded records in indexes	{"sql": "SELECT TOP 10 OBJECT_SCHEMA_NAME(ips.object_id) + '.' + OBJECT_NAME(ips.object_id) AS table_name, i.name AS index_name, ips.index_type_desc, ips.ghost_record_count, ips.forwarded_record_count, ips.page_count, ips.avg_fragmentation_in_percent FROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips JOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id WHERE ips.ghost_record_count > 100 OR ips.forwarded_record_count > 100 ORDER BY ips.ghost_record_count + ISNULL(ips.forwarded_record_count, 0) DESC"}	{"condition": "ghost_record_count > 1000 OR forwarded_fetch_count > 10000 OR ghost_pct > 10", "description": "High ghost record counts indicate delayed cleanup of deleted rows; high forwarded fetch counts indicate heap bloat from row expansion"}	null	2026-02-23 20:18:31.389777
1010	sqlserver	query	Check Query Store adoption and data retention	{"sql": "SELECT d.name AS database_name,\\n  d.compatibility_level,\\n  qso.desired_state_desc,\\n  qso.actual_state_desc,\\n  qso.current_storage_size_mb,\\n  qso.max_storage_size_mb,\\n  qso.stale_query_threshold_days,\\n  qso.interval_length_minutes AS stats_interval_min,\\n  qso.size_based_cleanup_mode_desc,\\n  CASE\\n    WHEN qso.actual_state_desc IS NULL OR qso.actual_state_desc = 'OFF'\\n    THEN 'NO_RISK_BASELINE'\\n    WHEN qso.current_storage_size_mb < 1\\n    THEN 'INSUFFICIENT_DATA'\\n    WHEN qso.stale_query_threshold_days < 14\\n    THEN 'SHORT_RETENTION'\\n    ELSE 'ADEQUATE'\\n  END AS risk_assessment_readiness\\nFROM sys.databases d\\nLEFT JOIN sys.database_query_store_options qso ON d.database_id = DB_ID(d.name)\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "risk_assessment_readiness IN ('NO_RISK_BASELINE', 'INSUFFICIENT_DATA', 'SHORT_RETENTION')", "description": "Databases without adequate Query Store data for upgrade risk assessment"}	null	2026-02-23 20:18:31.389469
1013	sqlserver	query	Detect cross-database dependencies	{"sql": "SELECT\\n  OBJECT_NAME(referencing_id, DB_ID()) AS referencing_object,\\n  referenced_database_name,\\n  referenced_schema_name,\\n  referenced_entity_name,\\n  referencing_class_desc COLLATE DATABASE_DEFAULT AS class_info\\nFROM sys.sql_expression_dependencies\\nWHERE referenced_database_name IS NOT NULL\\n  AND referenced_database_name <> DB_NAME()\\nUNION ALL\\nSELECT DISTINCT\\n  'Linked server: ' + s.name,\\n  s.data_source AS referenced_database,\\n  NULL, NULL,\\n  s.provider_string COLLATE DATABASE_DEFAULT\\nFROM sys.servers s\\nWHERE s.is_linked = 1"}	{"condition": "row_count > 0", "description": "Cross-database references or linked servers creating upgrade dependency chains"}	null	2026-02-23 20:18:31.389471
1015	sqlserver	query	Check if workload exceeds edition capabilities	{"sql": "SELECT SERVERPROPERTY('Edition') AS edition, sm.total_physical_memory_kb / 1024 AS total_memory_mb, si.cpu_count AS logical_cpus, (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE counter_name = 'Batch Requests/sec') AS batch_requests_sec, (SELECT cntr_value FROM sys.dm_os_performance_counters WHERE counter_name = 'User Connections') AS user_connections, (SELECT SUM(signal_wait_time_ms) * 100.0 / NULLIF(SUM(wait_time_ms), 0) FROM sys.dm_os_wait_stats) AS cpu_signal_wait_pct FROM sys.dm_os_sys_memory sm CROSS JOIN sys.dm_os_sys_info si"}	{"condition": "capacity_assessment IN ('OUTGROWING_EXPRESS', 'PRODUCTION_ON_EXPRESS')", "description": "Workload exceeds free/evaluation edition capabilities — license procurement needed for upgrade"}	null	2026-02-23 20:18:31.389473
1042	sqlserver	query	Check Query Store configuration across databases	{"sql": "SELECT d.name AS database_name,\\n  d.is_query_store_on,\\n  qso.desired_state_desc,\\n  qso.actual_state_desc,\\n  qso.current_storage_size_mb,\\n  qso.max_storage_size_mb,\\n  qso.stale_query_threshold_days,\\n  qso.query_capture_mode_desc\\nFROM sys.databases d\\nLEFT JOIN sys.database_query_store_options qso\\n  ON d.database_id = DB_ID(d.name)\\nWHERE d.database_id > 4\\n  AND d.state_desc = 'ONLINE'"}	{"condition": "any database has is_query_store_on = 0 OR actual_state_desc = 'READ_ONLY' OR actual_state_desc = 'ERROR'", "description": "Query Store not enabled, in read-only (full), or in error state"}	null	2026-02-23 20:18:31.389483
1123	sqlserver	query	Find top queries by logical reads (buffer pool consumption)	{"sql": "SELECT TOP 15\\n  qs.total_logical_reads,\\n  qs.execution_count,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.total_physical_reads,\\n  qs.total_physical_reads / NULLIF(qs.execution_count, 0) AS avg_physical_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows_returned,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 with avg_logical_reads > 10000", "description": "Queries consuming more than 10,000 logical reads per execution are pulling excessive pages into the buffer pool"}	null	2026-02-23 20:18:31.389535
1364	sqlserver	query	Check plan cache pressure via memory clerks and performance counters	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Cache Object Counts'\\n   AND object_name LIKE '%Plan Cache%'\\n   AND instance_name = '_Total') AS total_cached_plans,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Cache Pages'\\n   AND object_name LIKE '%Plan Cache%'\\n   AND instance_name = '_Total') AS cache_pages,\\n  mc.pages_kb / 1024 AS cache_mb,\\n  mc.pages_kb / 1024 AS in_use_mb\\nFROM sys.dm_os_memory_clerks mc\\nWHERE mc.type = 'CACHESTORE_SQLCP'"}	{"condition": "cache_mb is high but plan counts are low relative to compilations", "description": "Cache memory occupied but plans still being evicted — fragmentation"}	null	2026-02-23 20:18:31.389648
1124	sqlserver	query	Correlate high-read queries with low selectivity (reads vs rows returned)	{"sql": "SELECT TOP 10\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows_returned,\\n  CASE\\n    WHEN qs.total_rows / NULLIF(qs.execution_count, 0) = 0 THEN 0\\n    ELSE (qs.total_logical_reads / NULLIF(qs.execution_count, 0)) /\\n         NULLIF(qs.total_rows / NULLIF(qs.execution_count, 0), 0)\\n  END AS reads_per_row,\\n  qs.execution_count,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.execution_count > 5\\nORDER BY reads_per_row DESC"}	{"condition": "reads_per_row > 100", "description": "Queries reading hundreds of pages per row returned are highly unselective, scanning far more data than needed and polluting the buffer pool with transient pages"}	null	2026-02-23 20:18:31.389536
13641	mariadb	query	Check for tables that exist on replica but may differ from primary	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, ENGINE, ROW_FORMAT, CREATE_TIME, UPDATE_TIME FROM information_schema.TABLES WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND TABLE_TYPE = 'BASE TABLE' ORDER BY TABLE_SCHEMA, TABLE_NAME"}	{"condition": "row_count > 0", "description": "Table inventory provides baseline for schema comparison"}	\N	2026-05-11 22:17:39.229791
1136	sqlserver	query	Correlate stale statistics with queries that have large actual vs estimated row differences	{"sql": "SELECT TOP 10\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_logical_reads,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows_returned,\\n  qs.last_rows AS last_actual_rows,\\n  qs.min_rows AS min_rows,\\n  qs.max_rows AS max_rows,\\n  qs.total_spills,\\n  qs.execution_count,\\n  SUBSTRING(st.text, (qs.statement_start_offset/2)+1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset)/2)+1) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND qs.max_rows > qs.min_rows * 10\\n  AND qs.execution_count > 5\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 with max_rows / min_rows > 10", "description": "Queries with wild variation in actual row counts across executions, combined with high logical reads, confirm stale statistics are causing plan quality degradation and buffer pool waste"}	null	2026-02-23 20:18:31.389544
1398	sqlserver	query	Find parallel aggregation queries with skew indicators	{"sql": "SELECT TOP 20 qs.query_hash, SUM(qs.execution_count) AS total_execs, SUM(qs.total_worker_time) / NULLIF(SUM(qs.execution_count), 0) AS avg_cpu_us, SUM(qs.total_elapsed_time) / NULLIF(SUM(qs.execution_count), 0) AS avg_elapsed_us, MAX(qs.max_dop) AS max_dop_used, SUM(qs.total_grant_kb) / NULLIF(SUM(qs.execution_count), 0) AS avg_grant_kb, SUBSTRING(MIN(st.text), 1, 200) AS sample_query FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st WHERE qs.max_dop > 1 AND qs.total_elapsed_time / NULLIF(qs.execution_count, 0) > qs.total_worker_time / NULLIF(qs.execution_count, 0) * 3 GROUP BY qs.query_hash ORDER BY avg_elapsed_us DESC"}	{"condition": "parallel aggregations with elapsed_to_cpu_ratio > 2", "description": "Parallel aggregations where threads are idle — GROUP BY key is skewed"}	null	2026-02-23 20:18:31.389714
1153	sqlserver	query	Analyze plan cache entries by client application source	{"sql": "SELECT TOP 20 qs.query_hash, COUNT(DISTINCT qs.sql_handle) AS text_variants, COUNT(DISTINCT qs.plan_handle) AS plan_variants, SUM(qs.execution_count) AS total_executions, SUM(cp.size_in_bytes) / 1024 AS total_plan_kb, (SELECT STRING_AGG(sub.txt, ' | ') FROM (SELECT DISTINCT SUBSTRING(st2.text, 1, 80) AS txt FROM sys.dm_exec_query_stats qs2 CROSS APPLY sys.dm_exec_sql_text(qs2.sql_handle) st2 JOIN sys.dm_exec_cached_plans cp2 ON qs2.plan_handle = cp2.plan_handle WHERE cp2.objtype = 'Adhoc' AND qs2.query_hash = qs.query_hash) sub) AS query_samples FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st JOIN sys.dm_exec_cached_plans cp ON qs.plan_handle = cp.plan_handle WHERE cp.objtype = 'Adhoc' GROUP BY qs.query_hash HAVING COUNT(DISTINCT qs.sql_handle) > 5 ORDER BY text_variants DESC"}	{"condition": "row_count > 0 with text_variants > 5", "description": "Multiple text variants for the same query hash indicate different applications or drivers generating similar queries with textual differences"}	null	2026-02-23 20:18:31.389553
1164	sqlserver	query	Check for similar query patterns differing only by literal values	{"sql": "SELECT TOP 20 qs.query_hash, COUNT(*) AS plan_count, SUM(qs.execution_count) AS total_executions, AVG(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS avg_logical_reads, MIN(SUBSTRING(st.text, 1, 200)) AS sample_query FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st GROUP BY qs.query_hash HAVING COUNT(*) > 3 ORDER BY COUNT(*) DESC"}	{"condition": "query_hash with plan_variations > 5", "description": "Same query structure (same query_hash) with multiple plan entries means literal values are not parameterized"}	null	2026-02-23 20:18:31.389561
1393	sqlserver	query	Check tempdb spill file activity	{"sql": "SELECT SUM(fsu.internal_object_reserved_page_count) * 8 / 1024 AS internal_objects_mb, SUM(fsu.user_object_reserved_page_count) * 8 / 1024 AS user_objects_mb, SUM(fsu.version_store_reserved_page_count) * 8 / 1024 AS version_store_mb, SUM(fsu.unallocated_extent_page_count) * 8 / 1024 AS free_mb, (SELECT SUM(wait_time_ms) FROM sys.dm_os_wait_stats WHERE wait_type LIKE 'PAGEIO%' OR wait_type = 'IO_COMPLETION') AS io_wait_ms FROM tempdb.sys.dm_db_file_space_usage fsu"}	{"condition": "internal_alloc_pages is high", "description": "Significant tempdb internal object allocation — sort/hash spills from parallel operations"}	null	2026-02-23 20:18:31.389561
1167	sqlserver	query	Check plan cache size relative to buffer pool and recompilation rate	{"sql": "SELECT\\n  (SELECT SUM(CAST(size_in_bytes AS BIGINT)) / 1048576\\n   FROM sys.dm_exec_cached_plans) AS total_plan_cache_mb,\\n  (SELECT SUM(pages_kb) / 1024 FROM sys.dm_os_memory_clerks\\n   WHERE type = 'MEMORYCLERK_SQLBUFFERPOOL') AS buffer_pool_mb,\\n  (SELECT SUM(pages_kb) / 1024 FROM sys.dm_os_memory_clerks\\n   WHERE type IN ('CACHESTORE_SQLCP', 'CACHESTORE_OBJCP')) AS plan_stores_mb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Compilations/sec'\\n     AND instance_name = '') AS compilations,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Re-Compilations/sec'\\n     AND instance_name = '') AS recompilations"}	{"condition": "plan_stores_mb > buffer_pool_mb * 0.25 OR recompilations > compilations * 0.10", "description": "Plan cache consuming over 25% of buffer pool or recompilation rate exceeds 10% of compilations"}	null	2026-02-23 20:18:31.389563
1197	sqlserver	query	Check for internal memory pressure notifications	{"sql": "SELECT TOP 10 mc.type, mc.name, SUM(mc.pages_kb) AS total_kb, SUM(mc.virtual_memory_committed_kb) AS vm_committed_kb, (SELECT process_physical_memory_low FROM sys.dm_os_process_memory) AS physical_memory_low, (SELECT process_virtual_memory_low FROM sys.dm_os_process_memory) AS virtual_memory_low FROM sys.dm_os_memory_clerks mc GROUP BY mc.type, mc.name ORDER BY total_kb DESC"}	{"condition": "process_physical_memory_low = 1 OR used_mb < target_mb * 0.5", "description": "OS-level physical memory low notifications or resource governor pool under-utilization confirm insufficient memory for plan cache growth"}	null	2026-02-23 20:18:31.389565
1368	sqlserver	query	Find procedures using table-valued parameters	{"sql": "SELECT TOP 20 OBJECT_NAME(ps.object_id) AS procedure_name, ps.execution_count, ps.total_logical_reads / NULLIF(ps.execution_count, 0) AS avg_reads, ps.total_worker_time / NULLIF(ps.execution_count, 0) AS avg_cpu_us, SUBSTRING(st.text, 1, 200) AS procedure_text FROM sys.dm_exec_procedure_stats ps CROSS APPLY sys.dm_exec_sql_text(ps.sql_handle) st WHERE st.text LIKE '%table%type%' OR st.text LIKE '%TABLE%TYPE%' ORDER BY ps.total_logical_reads DESC"}	{"condition": "procedures found with TVP parameters and high CPU variance (max_worker_time >> avg_cpu_us)", "description": "Procedures with TVPs showing unstable execution times due to varying input sizes"}	null	2026-02-23 20:18:31.389699
13645	mariadb	query	Check InnoDB checkpoint age and pending writes	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME IN ('log_lsn_checkpoint_age', 'buffer_flush_batch_total_pages', 'buffer_flush_adaptive_total_pages', 'os_pending_writes')"}	{"condition": "row_count > 0", "description": "High checkpoint age or pending writes indicate aggressive flushing activity"}	\N	2026-05-11 22:17:39.229791
1378	sqlserver	query	Check how many cached parallel plans have low estimated cost	{"sql": "SELECT TOP 20 qs.query_hash, COUNT(DISTINCT qs.plan_handle) AS plan_count, MAX(qs.total_worker_time / NULLIF(qs.execution_count, 0)) AS max_avg_cpu_us, MAX(qs.total_elapsed_time / NULLIF(qs.execution_count, 0)) AS max_avg_elapsed_us, SUM(qs.execution_count) AS total_execs, SUBSTRING(MIN(st.text), 1, 200) AS sample_query FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st WHERE qs.total_worker_time / NULLIF(qs.execution_count, 0) < 1000 AND qs.total_elapsed_time / NULLIF(qs.execution_count, 0) > qs.total_worker_time / NULLIF(qs.execution_count, 0) * 2 GROUP BY qs.query_hash HAVING COUNT(DISTINCT qs.plan_handle) >= 1 ORDER BY max_avg_elapsed_us DESC"}	{"condition": "total_parallel_plans > 100", "description": "Large number of cached parallel plans suggests threshold is too low"}	null	2026-02-23 20:18:31.389707
1381	sqlserver	query	Check thread and scheduler pressure from excessive parallelism	{"sql": "SELECT\\n  SUM(current_tasks_count) AS total_tasks,\\n  SUM(runnable_tasks_count) AS runnable_tasks,\\n  SUM(pending_disk_io_count) AS pending_io,\\n  MAX(load_factor) AS max_load_factor,\\n  AVG(load_factor) AS avg_load_factor\\nFROM sys.dm_os_schedulers\\nWHERE scheduler_id < 255 AND is_online = 1"}	{"condition": "runnable_tasks > online_schedulers * 2 or max_load_factor > avg_load_factor * 3", "description": "Scheduler overloaded — too many parallel threads competing for CPU"}	null	2026-02-23 20:18:31.389709
1400	sqlserver	query	Find parallel plans with many exchange operators	{"sql": "SELECT TOP 20 qs.query_hash, COUNT(DISTINCT qs.plan_handle) AS plan_count, SUM(qs.execution_count) AS total_execs, MAX(qs.max_dop) AS max_dop_used, SUM(qs.total_worker_time) / NULLIF(SUM(qs.execution_count), 0) AS avg_cpu_us, SUM(qs.total_elapsed_time) / NULLIF(SUM(qs.execution_count), 0) AS avg_elapsed_us, SUBSTRING(MIN(st.text), 1, 200) AS sample_query FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st WHERE qs.max_dop > 4 GROUP BY qs.query_hash ORDER BY avg_cpu_us DESC"}	{"condition": "exchange_count > 4 per query plan", "description": "Plans with many exchange operators — each adds synchronization overhead"}	null	2026-02-23 20:18:31.389715
1412	sqlserver	query	Check scheduler context switches and yields	{"sql": "SELECT scheduler_id, cpu_id,\\n  context_switches_count,\\n  yield_count,\\n  current_tasks_count,\\n  runnable_tasks_count,\\n  active_workers_count,\\n  work_queue_count,\\n  CASE WHEN yield_count > 0\\n    THEN context_switches_count / yield_count ELSE 0 END AS switches_per_yield\\nFROM sys.dm_os_schedulers\\nWHERE status = 'VISIBLE ONLINE'\\n  AND is_idle = 0\\nORDER BY context_switches_count DESC"}	{"condition": "context_switch_count very high relative to yield_count, or runnable_tasks_count > 1 persistently", "description": "High context switch counts indicate schedulers constantly swapping between tasks rather than letting them complete"}	null	2026-02-23 20:18:31.38972
1418	sqlserver	query	Find duplicate query patterns with different literal values	{"sql": "SELECT TOP 20\\n  COUNT(*) AS duplicate_plans,\\n  SUM(CAST(cp.size_in_bytes AS BIGINT)) / 1024 AS total_kb,\\n  MIN(cp.usecounts) AS min_uses,\\n  MAX(cp.usecounts) AS max_uses,\\n  MIN(SUBSTRING(st.text, 1, 100)) AS query_pattern_sample\\nFROM sys.dm_exec_cached_plans cp\\nCROSS APPLY sys.dm_exec_sql_text(cp.plan_handle) st\\nWHERE cp.objtype = 'Adhoc'\\n  AND cp.usecounts = 1\\nGROUP BY SUBSTRING(st.text, 1, 60)\\nHAVING COUNT(*) > 10\\nORDER BY COUNT(*) DESC"}	{"condition": "duplicate_plans > 10 for same query pattern prefix with different literal values", "description": "Multiple plans sharing the same query prefix but varying only in literal values confirms non-parameterized ad-hoc queries"}	null	2026-02-23 20:18:31.389731
8956	oracle	query	ora-check-deferred-constraints	{"sql": "SELECT owner, constraint_name, table_name, constraint_type, deferrable, deferred, status FROM ALL_CONSTRAINTS WHERE deferrable = 'DEFERRABLE' AND deferred = 'DEFERRED' AND owner NOT IN ('SYS', 'SYSTEM') ORDER BY owner, table_name"}	{"condition": "row_count > 0", "description": "Deferred constraints accumulate validation work until commit time, potentially causing slow commits"}	\N	2026-02-28 12:19:19.580455
1440	sqlserver	query	Check plan cache size and eviction indicators	{"sql": "SELECT name, type, pages_kb, pages_in_use_kb, entries_count, entries_in_use_count, CASE WHEN entries_count - entries_in_use_count > entries_count * 0.5 THEN 'HIGH_EVICTION' ELSE 'OK' END AS eviction_status FROM sys.dm_os_memory_cache_counters WHERE type IN ('CACHESTORE_SQLCP', 'CACHESTORE_OBJCP', 'CACHESTORE_PHDR') ORDER BY pages_kb DESC"}	{"condition": "single_use_mb is a large proportion of total_mb, or total plan cache entries very high", "description": "Large single-use plan footprint squeezes out reusable plans, causing eviction and recompilation of important queries"}	null	2026-02-23 20:18:31.389745
1460	sqlserver	query	Check overall CPU utilization driven by SQL Server	{"sql": "SELECT TOP 10\\n  record_id,\\n  SQLProcessUtilization AS sql_cpu_pct,\\n  SystemIdle AS idle_pct,\\n  100 - SystemIdle - SQLProcessUtilization AS other_process_cpu_pct,\\n  EventTime\\nFROM (\\n  SELECT\\n    CAST(record AS XML).value('(./Record/@id)[1]', 'int') AS record_id,\\n    CAST(record AS XML).value('(./Record/SchedulerMonitorEvent/SystemHealth/SystemIdle)[1]', 'int') AS SystemIdle,\\n    CAST(record AS XML).value('(./Record/SchedulerMonitorEvent/SystemHealth/ProcessUtilization)[1]', 'int') AS SQLProcessUtilization,\\n    timestamp AS EventTime\\n  FROM sys.dm_os_ring_buffers\\n  WHERE ring_buffer_type = N'RING_BUFFER_SCHEDULER_MONITOR'\\n    AND record LIKE '%<SystemHealth>%'\\n) AS cpu_data\\nORDER BY record_id DESC"}	{"condition": "sql_cpu_pct > 70 consistently across recent samples", "description": "SQL Server consuming >70% CPU confirms that the expensive frequent queries are causing system-level CPU pressure"}	null	2026-02-23 20:18:31.389759
1473	sqlserver	query	Find plans with implicit conversion warnings	{"sql": "SELECT TOP 20 qs.query_hash, SUM(qs.execution_count) AS total_execs, SUM(qs.total_logical_reads) / NULLIF(SUM(qs.execution_count), 0) AS avg_reads, SUM(qs.total_worker_time) / NULLIF(SUM(qs.execution_count), 0) AS avg_cpu_us, SUBSTRING(MIN(st.text), 1, 200) AS sample_query FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st GROUP BY qs.query_hash HAVING SUM(qs.total_logical_reads) / NULLIF(SUM(qs.execution_count), 0) > 10000 ORDER BY avg_reads DESC"}	{"condition": "convert_warning_count > 0, especially seek_plan_converts > 0", "description": "PlanAffectingConvert warnings in execution plans indicate implicit conversions that prevent index seeks"}	null	2026-02-23 20:18:31.389766
1498	sqlserver	query	Check for long-running open transactions holding resources	{"sql": "SELECT t.transaction_id, t.name AS tran_name, t.transaction_begin_time, DATEDIFF(SECOND, t.transaction_begin_time, GETDATE()) AS duration_sec, s.session_id, s.login_name, s.host_name, s.program_name, r.blocking_session_id, SUBSTRING(st.text, 1, 200) AS last_sql FROM sys.dm_tran_active_transactions t JOIN sys.dm_tran_session_transactions tst ON t.transaction_id = tst.transaction_id JOIN sys.dm_exec_sessions s ON tst.session_id = s.session_id LEFT JOIN sys.dm_exec_requests r ON s.session_id = r.session_id OUTER APPLY sys.dm_exec_sql_text(r.sql_handle) st WHERE t.transaction_begin_time < DATEADD(MINUTE, -5, GETDATE()) ORDER BY t.transaction_begin_time"}	{"condition": "transactions open for > 60 seconds", "description": "Long-running transactions hold locks for extended periods, prevent ghost cleanup, bloat the version store, and block other transactions — all consuming CPU indirectly"}	null	2026-02-23 20:18:31.389782
1549	sqlserver	query	Check period column statistics coverage	{"sql": "SELECT t.name AS table_name, SCHEMA_NAME(t.schema_id) AS schema_name, t.temporal_type_desc, COL_NAME(t.object_id, t.history_retention_period) AS history_period FROM sys.tables t WHERE t.temporal_type <> 0"}	{"condition": "period columns without statistics or with stale statistics", "description": "Period columns (SysStartTime, SysEndTime) without adequate statistics for temporal queries (FOR SYSTEM_TIME)"}	null	2026-02-23 20:18:31.38981
1582	sqlserver	query	Check scheduler contention on single NUMA node	{"sql": "SELECT scheduler_id, parent_node_id,\\n  current_tasks_count, runnable_tasks_count,\\n  active_workers_count, load_factor,\\n  yield_count, context_switches_count\\nFROM sys.dm_os_schedulers\\nWHERE scheduler_id < 255 AND is_online = 1\\nORDER BY runnable_tasks_count DESC"}	{"condition": "runnable_task_count > 1 on multiple schedulers with single parent_node_id", "description": "All schedulers on same NUMA node competing for shared L3 cache and memory bandwidth"}	null	2026-02-23 20:18:31.38983
1592	sqlserver	query	Check memory node contention from cross-NUMA access	{"sql": "SELECT mn.memory_node_id, mn.pages_kb, mn.foreign_committed_kb, mn.target_kb, CASE WHEN mn.foreign_committed_kb > mn.pages_kb * 0.1 THEN 'CROSS_NUMA_CONTENTION' ELSE 'OK' END AS numa_status FROM sys.dm_os_memory_nodes mn WHERE mn.memory_node_id <> 64"}	{"condition": "foreign_committed_kb > 0 indicates cross-NUMA memory access", "description": "Memory allocated on foreign NUMA nodes — parallel threads accessing remote memory with higher latency"}	null	2026-02-23 20:18:31.389836
1625	sqlserver	query	Find computed columns and their statistics status	{"sql": "SELECT OBJECT_SCHEMA_NAME(cc.object_id) + '.' + OBJECT_NAME(cc.object_id) AS table_name, cc.name AS computed_column, cc.definition, cc.is_persisted, s.name AS stat_name, STATS_DATE(s.object_id, s.stats_id) AS stats_date FROM sys.computed_columns cc LEFT JOIN sys.stats_columns sc ON cc.object_id = sc.object_id AND cc.column_id = sc.column_id LEFT JOIN sys.stats s ON sc.object_id = s.object_id AND sc.stats_id = s.stats_id ORDER BY cc.object_id"}	{"condition": "computed columns with NULL stats_name (no statistics) or high modification_counter", "description": "Computed columns without statistics or with stale statistics"}	null	2026-02-23 20:18:31.389857
