2582	sqlserver	query	Check for queries near or exceeding cost limits	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.execution_count,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  p.query_plan.value('(//RelOp/@EstimatedTotalSubtreeCost)[1]', 'float') AS estimated_cost,\\n  (SELECT CAST(value_in_use AS FLOAT) FROM sys.configurations WHERE name = 'query governor cost limit') AS governor_limit,\\n  SUBSTRING(t.text, 1, 400) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE p.query_plan.value('(//RelOp/@EstimatedTotalSubtreeCost)[1]', 'float') >\\n  (SELECT CAST(value_in_use AS FLOAT) * 0.8 FROM sys.configurations WHERE name = 'query governor cost limit')\\n  AND (SELECT CAST(value_in_use AS FLOAT) FROM sys.configurations WHERE name = 'query governor cost limit') > 0\\nORDER BY estimated_cost DESC"}	{"condition": "estimated_cost approaching or exceeding governor_limit", "description": "Queries with estimated cost near the governor limit confirm cost-based query termination causing rollbacks"}	null	2026-02-23 20:18:31.390479
2613	sqlserver	query	Check for test/dev-named logins with blank passwords	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  sp.create_date, sp.modify_date,\\n  sl.is_policy_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_login\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE PWDCOMPARE('', sl.password_hash) = 1\\n  AND sp.type_desc = 'SQL_LOGIN'\\n  AND (sp.name LIKE '%test%' OR sp.name LIKE '%dev%' OR sp.name LIKE '%temp%'\\n    OR sp.name LIKE '%demo%' OR sp.name LIKE '%qa%' OR sp.name LIKE '%staging%'\\n    OR sp.name LIKE '%tmp%' OR sp.name LIKE '%sample%')"}	{"condition": "row_count > 0", "description": "Test/dev accounts with blank passwords exist in production"}	null	2026-02-23 20:18:31.390493
2626	sqlserver	query	Check all blank-password logins regardless of batch pattern	{"sql": "SELECT sp.name, sp.create_date,\\n  sl.is_policy_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE PWDCOMPARE('', sl.password_hash) = 1\\n  AND sp.type_desc = 'SQL_LOGIN'"}	{"condition": "row_count > 0", "description": "Blank-password logins present — may be from a single-run batch script"}	null	2026-02-23 20:18:31.390501
