2628	sqlserver	query	Check SQL logins with password policy enforcement disabled	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  sp.create_date, sp.modify_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND (sl.is_policy_checked = 0 OR sl.is_expiration_checked = 0)"}	{"condition": "row_count > 0", "description": "Active SQL logins with CHECK_POLICY or CHECK_EXPIRATION disabled"}	null	2026-02-23 20:18:31.390502
2629	sqlserver	query	Assess overall password policy enforcement ratio	{"sql": "SELECT\\n  COUNT(*) AS total_sql_logins,\\n  SUM(CASE WHEN sl.is_policy_checked = 0 THEN 1 ELSE 0 END) AS no_policy,\\n  SUM(CASE WHEN sl.is_expiration_checked = 0 THEN 1 ELSE 0 END) AS no_expiration,\\n  SUM(CASE WHEN sl.is_policy_checked = 0 AND sl.is_expiration_checked = 0 THEN 1 ELSE 0 END) AS no_both,\\n  ROUND(SUM(CASE WHEN sl.is_policy_checked = 0 THEN 1.0 ELSE 0 END) / NULLIF(COUNT(*), 0) * 100, 1) AS pct_no_policy\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "pct_no_policy > 50", "description": "Majority of SQL logins have no password policy — default configuration was never hardened"}	null	2026-02-23 20:18:31.390503
2631	sqlserver	query	Check if common weak passwords are in use on policy-disabled logins	{"sql": "SELECT sp.name,\\n  PWDCOMPARE('', sl.password_hash) AS is_blank,\\n  PWDCOMPARE('password', sl.password_hash) AS is_password,\\n  PWDCOMPARE('Password1', sl.password_hash) AS is_Password1,\\n  PWDCOMPARE('123456', sl.password_hash) AS is_123456,\\n  PWDCOMPARE(sp.name, sl.password_hash) AS is_same_as_login,\\n  PWDCOMPARE('P@ssw0rd', sl.password_hash) AS is_Passw0rd,\\n  PWDCOMPARE('admin', sl.password_hash) AS is_admin,\\n  PWDCOMPARE('sa', sl.password_hash) AS is_sa\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sl.is_policy_checked = 0\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "any PWDCOMPARE returns 1", "description": "Weak/common passwords detected on logins with policy enforcement disabled"}	null	2026-02-23 20:18:31.390504
2632	sqlserver	query	Check for old logins with policy disabled serving legacy applications	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n  sp.create_date, sp.modify_date,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS age_days,\\n  DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE()) AS password_age_days\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sl.is_policy_checked = 0\\n  AND DATEDIFF(DAY, sp.create_date, GETDATE()) > 365\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "row_count > 0 with password_age_days > 365", "description": "Long-standing SQL logins with policy disabled and stale passwords — legacy compatibility suspected"}	null	2026-02-23 20:18:31.390504
2634	sqlserver	query	Check for logins with CHECK_EXPIRATION disabled despite CHECK_POLICY being on	{"sql": "SELECT sp.name, sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE()) AS password_age_days,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sl.is_policy_checked = 1\\n  AND sl.is_expiration_checked = 0\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "row_count > 0 with password_age_days > 90", "description": "Logins with complexity but no expiration — passwords may be strong but never rotated (violates most compliance frameworks)"}	null	2026-02-23 20:18:31.390506
2635	sqlserver	query	Check for logins with policy disabled and no password length enforcement	{"sql": "SELECT sp.name, sp.type_desc,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  LEN(sp.name) AS login_name_length,\\n  PWDCOMPARE('', sl.password_hash) AS is_blank,\\n  PWDCOMPARE(sp.name, sl.password_hash) AS is_same_as_login,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sl.is_policy_checked = 0\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "row_count > 0", "description": "SQL logins with CHECK_POLICY = OFF — Windows complexity requirements bypassed entirely"}	null	2026-02-23 20:18:31.390506
2636	sqlserver	query	Check for high-connection logins with policy disabled	{"sql": "SELECT sp.name, sp.type_desc,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  (SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS active_sessions,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Logins/sec' AND instance_name = '') AS logins_per_sec\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sl.is_policy_checked = 0\\n  AND sp.name NOT LIKE '##%'\\nORDER BY active_sessions DESC"}	{"condition": "policy-disabled logins with high active session counts", "description": "High-connection SQL logins with policy disabled — performance concern suspected as justification"}	null	2026-02-23 20:18:31.390507
