2638	sqlserver	query	Check for interactive user logins with weak policy settings	{"sql": "SELECT sp.name, sp.type_desc,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  sp.create_date,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  DATEDIFF(DAY, CAST(LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS datetime), GETDATE()) AS password_age_days,\\n  LOGINPROPERTY(sp.name, 'PasswordHashAlgorithm') AS hash_algorithm,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name\\n    AND program_name NOT LIKE '%Agent%' AND program_name NOT LIKE '%Job%') AS last_interactive_login\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND (sl.is_policy_checked = 0 OR sl.is_expiration_checked = 0)\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE '%svc%'\\n  AND sp.name NOT LIKE '%service%'\\n  AND sp.name NOT LIKE '%app%'"}	{"condition": "row_count > 0 with password_age_days > 180", "description": "Interactive user logins with weak policy and stale passwords — friction avoidance suspected"}	null	2026-02-23 20:18:31.390508
2642	sqlserver	query	Check password policy enforcement consistency across all SQL logins	{"sql": "SELECT\\n  COUNT(*) AS total_sql_logins,\\n  SUM(CASE WHEN sl.is_policy_checked = 1 THEN 1 ELSE 0 END) AS policy_enforced_count,\\n  SUM(CASE WHEN sl.is_policy_checked = 0 THEN 1 ELSE 0 END) AS policy_not_enforced_count,\\n  SUM(CASE WHEN sl.is_expiration_checked = 1 THEN 1 ELSE 0 END) AS expiration_enforced_count,\\n  SUM(CASE WHEN sl.is_expiration_checked = 0 THEN 1 ELSE 0 END) AS expiration_not_enforced_count,\\n  CAST(SUM(CASE WHEN sl.is_policy_checked = 0 THEN 1 ELSE 0 END) AS FLOAT) /\\n    NULLIF(COUNT(*), 0) * 100 AS pct_without_policy\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'"}	{"condition": "policy_not_enforced_count > 0 AND pct_without_policy > 20", "description": "Significant fraction of SQL logins lack policy enforcement — no centralized standard"}	null	2026-02-23 20:18:31.39051
2647	sqlserver	query	Check for inconsistent policy enforcement across SQL logins	{"sql": "SELECT\\n  sl.is_policy_checked,\\n  sl.is_expiration_checked,\\n  COUNT(*) AS login_count,\\n  STRING_AGG(sp.name, ', ') WITHIN GROUP (ORDER BY sp.name) AS logins\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\nGROUP BY sl.is_policy_checked, sl.is_expiration_checked\\nORDER BY sl.is_policy_checked, sl.is_expiration_checked"}	{"condition": "more than one combination of (is_policy_enforced, is_expiration_enforced) exists", "description": "Multiple different policy enforcement combinations across logins — no consistent documented standard"}	null	2026-02-23 20:18:31.390513
2782	sqlserver	query	Measure effective retention period under current rollover	{"sql": "SELECT a.name AS audit_name, a.type_desc, CASE WHEN a.is_state_enabled = 1 THEN 'ENABLED' ELSE 'DISABLED' END AS status, a.on_failure_desc, a.queue_delay, sfa.log_file_path AS audit_file_path, sfa.max_file_size, sfa.max_rollover_files FROM sys.server_audits a LEFT JOIN sys.server_file_audits sfa ON a.audit_id = sfa.audit_id"}	{"condition": "retention_days < 90", "description": "Circular overwrite limiting retention below compliance requirements"}	null	2026-02-23 20:18:31.390514
2652	sqlserver	query	Check if service account login has sysadmin or excessive permissions	{"sql": "SELECT sp.name AS login_name, sp.type_desc AS login_type, CASE WHEN IS_SRVROLEMEMBER('sysadmin', sp.name) = 1 THEN 'sysadmin' WHEN IS_SRVROLEMEMBER('securityadmin', sp.name) = 1 THEN 'securityadmin' WHEN IS_SRVROLEMEMBER('serveradmin', sp.name) = 1 THEN 'serveradmin' ELSE 'standard' END AS role_level FROM sys.server_principals sp WHERE sp.type IN ('S', 'U', 'G') AND sp.name NOT LIKE '##%' AND sp.is_disabled = 0 ORDER BY CASE WHEN IS_SRVROLEMEMBER('sysadmin', sp.name) = 1 THEN 0 ELSE 1 END, sp.name"}	{"condition": "is_sysadmin = 1 for LocalSystem or a domain account with broad access", "description": "Service account has sysadmin — OS compromise gives full database control"}	null	2026-02-23 20:18:31.390516
2670	sqlserver	query	Check for per-database user isolation pattern	{"sql": "SELECT sp.name AS login_name, sp.default_database_name,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  (SELECT COUNT(*) FROM sys.database_principals dp\\n   WHERE dp.sid = sp.sid AND dp.type_desc = 'SQL_USER') AS db_user_mappings\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\n  AND sp.default_database_name NOT IN ('master', 'tempdb', 'msdb', 'model')\\nORDER BY sp.default_database_name, sp.name"}	{"condition": "multiple logins each with a distinct default_database_name", "description": "Per-tenant SQL logins with database isolation — Mixed Mode required for multi-tenant SQL auth"}	null	2026-02-23 20:18:31.390529
2675	sqlserver	query	Check for Mixed Mode with contractor-pattern SQL logins	{"sql": "SELECT\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_auth_only,\\n  sp.name, sp.type_desc, sp.create_date, sp.is_disabled,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE SERVERPROPERTY('IsIntegratedSecurityOnly') = 0\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\n  AND (sp.name LIKE '%contractor%' OR sp.name LIKE '%vendor%' OR sp.name LIKE '%extern%'\\n    OR sp.name LIKE '%consult%' OR sp.name LIKE '%partner%' OR sp.name LIKE '%3rd%'\\n    OR sp.name LIKE '%third%' OR sp.name LIKE '%guest%' OR sp.name LIKE '%temp_%')"}	{"condition": "row_count > 0", "description": "SQL logins with contractor/external naming patterns found — Mixed Mode likely enabled for external access"}	null	2026-02-23 20:18:31.390531
2676	sqlserver	query	Check for SQL logins that are not domain-joined patterns	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  (SELECT MAX(login_time) FROM sys.dm_exec_sessions WHERE login_name = sp.name) AS last_session,\\n  (SELECT COUNT(*) FROM sys.server_principals WHERE type IN ('U', 'G') AND is_disabled = 0) AS windows_login_count\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name <> 'sa'\\nORDER BY sp.create_date DESC"}	{"condition": "SQL logins exist alongside Windows logins — external users given SQL auth instead of AD guest/trust", "description": "Non-domain SQL logins in Mixed Mode suggest external contractor access pattern"}	null	2026-02-23 20:18:31.390532
6056	postgresql	query	Find functions using manual quoting functions	{"sql": "SELECT n.nspname AS schema_name, p.proname AS function_name FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind NOT IN ('a', 'w') AND pg_get_functiondef(p.oid) ~* '(quote_literal|quote_ident|quote_nullable)' AND pg_get_functiondef(p.oid) ~* 'EXECUTE'"}	{"condition": "row_count > 0", "description": "Functions relying on manual quoting instead of parameterized execution"}	\N	2026-02-25 00:28:52.405273
2686	sqlserver	query	Check for SQL logins connecting from multiple hosts	{"sql": "SELECT sp.name, COUNT(DISTINCT s.host_name) AS distinct_hosts, (SELECT STRING_AGG(h.host_name, ', ') FROM (SELECT DISTINCT s2.host_name FROM sys.dm_exec_sessions s2 WHERE s2.login_name = sp.name AND s2.is_user_process = 1) h) AS host_names, COUNT(*) AS total_sessions FROM sys.sql_logins sl JOIN sys.server_principals sp ON sl.principal_id = sp.principal_id JOIN sys.dm_exec_sessions s ON s.login_name = sp.name WHERE sp.is_disabled = 0 AND sp.name NOT LIKE '##%' AND s.is_user_process = 1 AND SERVERPROPERTY('IsIntegratedSecurityOnly') = 0 GROUP BY sp.name, sp.principal_id HAVING COUNT(DISTINCT s.host_name) > 1"}	{"condition": "SQL logins connecting from multiple distinct hosts", "description": "SQL credentials used from multiple hosts — lateral movement pattern or shared credentials"}	null	2026-02-23 20:18:31.390539
2711	sqlserver	query	Find logins with concurrent sessions from multiple hosts	{"sql": "SELECT s.login_name, s.original_login_name, COUNT(DISTINCT s.host_name) AS distinct_hosts, COUNT(*) AS total_sessions, MIN(s.login_time) AS earliest_session, MAX(s.login_time) AS latest_session, (SELECT STRING_AGG(p.program_name, ', ') FROM (SELECT DISTINCT s2.program_name FROM sys.dm_exec_sessions s2 WHERE s2.login_name = s.login_name AND s2.original_login_name = s.original_login_name AND s2.is_user_process = 1) p) AS programs FROM sys.dm_exec_sessions s WHERE s.is_user_process = 1 GROUP BY s.login_name, s.original_login_name HAVING COUNT(DISTINCT s.host_name) > 1 OR COUNT(DISTINCT s.program_name) > 2 ORDER BY distinct_hosts DESC"}	{"condition": "logins connecting from multiple hosts or many distinct programs", "description": "Shared service accounts detected — multiple hosts/apps use the same login, preventing individual dormancy classification"}	null	2026-02-23 20:18:31.390546
2774	sqlserver	query	Measure actual retention period from audit files	{"sql": "SELECT a.name AS audit_name, a.type_desc, CASE WHEN a.is_state_enabled = 1 THEN 'ENABLED' ELSE 'DISABLED' END AS status, a.on_failure_desc, a.queue_delay, sfa.log_file_path AS audit_file_path, sfa.max_file_size, sfa.max_rollover_files FROM sys.server_audits a LEFT JOIN sys.server_file_audits sfa ON a.audit_id = sfa.audit_id"}	{"condition": "actual_retention_days < 90", "description": "Effective retention shorter than minimum compliance requirements"}	null	2026-02-23 20:18:31.390576
2704	sqlserver	query	Check dev/test logins for weak security settings	{"sql": "SELECT sp.name, sp.create_date,\\n  sl.is_policy_checked, sl.is_expiration_checked,\\n  PWDCOMPARE('', sl.password_hash) AS is_blank,\\n  PWDCOMPARE('password', sl.password_hash) AS is_password,\\n  PWDCOMPARE(sp.name, sl.password_hash) AS is_same_as_login,\\n  PWDCOMPARE('test', sl.password_hash) AS is_test,\\n  PWDCOMPARE('dev', sl.password_hash) AS is_dev,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin\\nFROM sys.sql_logins sl\\nJOIN sys.server_principals sp ON sl.principal_id = sp.principal_id\\nWHERE sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND (sp.name LIKE '%test%' OR sp.name LIKE '%dev%' OR sp.name LIKE '%debug%'\\n    OR sp.name LIKE '%qa%' OR sp.name LIKE '%staging%' OR sp.name LIKE '%demo%'\\n    OR sp.name LIKE '%sample%' OR sp.name LIKE '%sandbox%')"}	{"condition": "test/dev accounts with weak passwords (blank, 'password', same-as-login, 'test', 'dev')", "description": "Test/dev accounts with weak security settings in production — migrated without hardening"}	null	2026-02-23 20:18:31.390551
2705	sqlserver	query	Enumerate all logins and assess inventory health	{"sql": "SELECT\\n  COUNT(*) AS total_logins,\\n  SUM(CASE WHEN sp.is_disabled = 0 THEN 1 ELSE 0 END) AS enabled_logins,\\n  SUM(CASE WHEN sp.is_disabled = 1 THEN 1 ELSE 0 END) AS disabled_logins,\\n  SUM(CASE WHEN sp.type = 'S' AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS active_sql_logins,\\n  SUM(CASE WHEN sp.type IN ('U', 'G') AND sp.is_disabled = 0 THEN 1 ELSE 0 END) AS active_windows_logins,\\n  SUM(CASE WHEN sp.is_disabled = 0 AND ls.last_login IS NULL THEN 1 ELSE 0 END) AS enabled_no_session,\\n  MIN(sp.create_date) AS oldest_login_date,\\n  MAX(sp.create_date) AS newest_login_date\\nFROM sys.server_principals sp\\nLEFT JOIN (SELECT login_name, MAX(login_time) AS last_login FROM sys.dm_exec_sessions GROUP BY login_name) ls ON ls.login_name = sp.name\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'NT %'\\n  AND sp.name NOT IN ('sa')"}	{"condition": "enabled_no_session > 5 or total_logins > 20 with many inactive", "description": "Many enabled logins with no current sessions — no account inventory managing lifecycle"}	null	2026-02-23 20:18:31.390551
4553	postgresql	query	Check system resources and PostgreSQL version age	{"sql": "SELECT current_setting('server_version') AS version, current_setting('server_version_num')::integer AS version_num, pg_postmaster_start_time() AS start_time, current_setting('max_connections')::integer AS max_conn, current_setting('shared_buffers') AS shared_buffers"}	{"condition": "version_num < :outdated_threshold", "description": "Running significantly outdated PostgreSQL with minimal resource configuration suggests budget or resource constraints"}	{"outdated_threshold": 140000}	2026-02-25 00:28:52.405273
2714	sqlserver	query	Cross-reference unknown logins with database-level usage	{"sql": "SELECT sp.name AS login_name, sp.create_date,\\n  DATEDIFF(DAY, sp.create_date, GETDATE()) AS age_days,\\n  (SELECT MAX(s.login_time) FROM sys.dm_exec_sessions s WHERE s.login_name = sp.name) AS last_session,\\n  (SELECT COUNT(*) FROM sys.server_role_members srm WHERE srm.member_principal_id = sp.principal_id) AS server_roles,\\n  (SELECT COUNT(*) FROM sys.databases d\\n   CROSS APPLY (SELECT 1 AS col1 FROM sys.server_principals sp2\\n     WHERE sp2.name = sp.name) x\\n   WHERE d.state = 0 AND d.database_id > 4) AS accessible_databases\\nFROM sys.server_principals sp\\nWHERE sp.type IN ('S', 'U', 'G')\\n  AND sp.is_disabled = 0\\n  AND sp.principal_id > 10\\n  AND sp.name NOT LIKE '##%'\\n  AND sp.name NOT LIKE 'svc_%'\\n  AND sp.name NOT LIKE 'app_%'\\n  AND sp.type_desc <> 'WINDOWS_LOGIN'\\nORDER BY sp.create_date ASC"}	{"condition": "logins older than 90 days with no identifiable owner", "description": "Legacy logins with unclear ownership — cannot determine who to contact for dormancy review"}	null	2026-02-23 20:18:31.390556
2901	sqlserver	query	Check for shared logins with concurrent sessions from multiple hosts	{"sql": "SELECT s.login_name, COUNT(*) AS total_sessions, COUNT(DISTINCT s.host_name) AS distinct_hosts, COUNT(DISTINCT s.program_name) AS distinct_programs, (SELECT STRING_AGG(h.host_name, ', ') FROM (SELECT DISTINCT s2.host_name FROM sys.dm_exec_sessions s2 JOIN sys.server_principals sp2 ON s2.login_name = sp2.name WHERE s2.login_name = s.login_name AND s2.is_user_process = 1 AND sp2.type_desc = 'SQL_LOGIN' AND sp2.name NOT LIKE '##%') h) AS host_list FROM sys.dm_exec_sessions s JOIN sys.server_principals sp ON s.login_name = sp.name WHERE s.is_user_process = 1 AND sp.type_desc = 'SQL_LOGIN' AND sp.name NOT LIKE '##%' GROUP BY s.login_name HAVING COUNT(DISTINCT s.host_name) > 1"}	{"condition": "row_count > 0", "description": "SQL logins actively used from multiple distinct hosts — strong indicator of shared credentials"}	null	2026-02-23 20:18:31.390564
4953	postgresql	query	Compare WAL and data directory paths	{"sql": "SELECT current_setting('data_directory') AS data_dir, current_setting('data_directory') || '/pg_wal' AS wal_dir_default"}	{"condition": "wal_dir_default IS NOT NULL", "description": "WAL directory inside data directory means they share the same filesystem by default"}	\N	2026-02-25 00:28:52.405273
2739	sqlserver	query	Check for residual recovery artifacts	{"sql": "SELECT sp.name, sp.type_desc, sp.create_date,\\n  sp.modify_date, sp.is_disabled,\\n  LOGINPROPERTY(sp.name, 'PasswordLastSetTime') AS password_last_set,\\n  IS_SRVROLEMEMBER('sysadmin', sp.name) AS is_sysadmin,\\n  (SELECT sl.is_policy_checked FROM sys.sql_logins sl WHERE sl.principal_id = sp.principal_id) AS policy_enforced\\nFROM sys.server_principals sp\\nWHERE sp.type_desc = 'SQL_LOGIN'\\n  AND sp.is_disabled = 0\\n  AND sp.name NOT LIKE '##%'\\n  AND IS_SRVROLEMEMBER('sysadmin', sp.name) = 1\\n  AND ((SELECT sl.is_policy_checked FROM sys.sql_logins sl WHERE sl.principal_id = sp.principal_id) = 0\\n    OR sp.name LIKE '%admin%' OR sp.name LIKE '%temp%' OR sp.name LIKE '%recovery%'\\n    OR sp.name LIKE '%emergency%')"}	{"condition": "sysadmin SQL logins with no password policy or recovery-pattern names", "description": "Recovery artifacts: sysadmin logins created during single-user mode recovery without proper hardening"}	null	2026-02-23 20:18:31.390572
2740	sqlserver	query	Check for deprecated or legacy security configurations	{"sql": "SELECT\\n  SERVERPROPERTY('ProductVersion') AS sql_version,\\n  SERVERPROPERTY('ProductLevel') AS service_pack,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'remote access') AS remote_access_legacy,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'scan for startup procs') AS scan_startup_procs,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'allow updates') AS allow_direct_updates,\\n  (SELECT CAST(value_in_use AS INT) FROM sys.configurations WHERE name = 'default trace enabled') AS default_trace,\\n  (SELECT COUNT(*) FROM sys.server_principals\\n   WHERE type_desc = 'SQL_LOGIN' AND is_disabled = 0\\n     AND name NOT LIKE '##%'\\n     AND (SELECT is_policy_checked FROM sys.sql_logins sl WHERE sl.principal_id = sys.server_principals.principal_id) = 0) AS logins_no_policy,\\n  SERVERPROPERTY('IsIntegratedSecurityOnly') AS windows_only_auth"}	{"condition": "remote_access_legacy = 1 or scan_startup_procs = 1 or logins_no_policy > 0 on a modern SQL Server version", "description": "Legacy security settings on modern SQL Server — configuration based on outdated templates"}	null	2026-02-23 20:18:31.390573
