3036	sqlserver	query	Check if guest account is enabled on sample/test databases	{"sql": "SELECT d.name AS database_name,\\n  (SELECT CASE WHEN HAS_DBACCESS(d.name) = 1 THEN 'ACCESSIBLE' ELSE 'RESTRICTED' END) AS current_user_access,\\n  d.user_access_desc,\\n  (SELECT dp.name + ': ' + CAST(perm.permission_name COLLATE DATABASE_DEFAULT AS NVARCHAR(128))\\n   FROM sys.database_permissions perm\\n   JOIN sys.database_principals dp ON perm.grantee_principal_id = dp.principal_id\\n   WHERE dp.name = 'guest'\\n     AND perm.permission_name = 'CONNECT'\\n     AND perm.state_desc IN ('GRANT', 'GRANT_WITH_GRANT_OPTION')) AS guest_connect_status\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND d.state = 0\\n  AND (d.name IN ('AdventureWorks', 'AdventureWorks2012', 'AdventureWorks2014', 'AdventureWorks2016', 'AdventureWorks2017', 'AdventureWorks2019', 'AdventureWorksDW', 'AdventureWorksLT', 'Northwind', 'pubs', 'WideWorldImporters', 'WideWorldImportersDW')\\n    OR d.name LIKE '%test%' OR d.name LIKE '%dev%' OR d.name LIKE '%sample%' OR d.name LIKE '%demo%' OR d.name LIKE '%sandbox%')"}	{"condition": "guest account has CONNECT permission or databases have MULTI_USER access", "description": "Sample/test databases accessible to guest or broadly accessible — RBAC controls are insufficient"}	null	2026-02-23 20:18:31.390745
3074	sqlserver	query	Check for trace flags in startup parameters	{"sql": "SELECT registry_key, value_name, CAST(value_data AS NVARCHAR(256)) AS value_data\\nFROM sys.dm_server_registry\\nWHERE registry_key LIKE '%MSSQLServer\\\\Parameters%'\\n  AND CAST(value_data AS NVARCHAR(256)) LIKE '-T%'"}	{"condition": "startup parameters contain -T trace flags", "description": "Trace flags are configured as persistent startup parameters — they survive service restarts"}	null	2026-02-23 20:18:31.390769
3077	sqlserver	query	Check startup parameter trace flags for drift from standard configuration	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_server_registry\\n   WHERE registry_key LIKE '%MSSQLServer\\\\Parameters%'\\n     AND CAST(value_data AS NVARCHAR(256)) LIKE '-T%') AS startup_trace_flag_count,\\n  (SELECT STRING_AGG(REPLACE(CAST(value_data AS NVARCHAR(256)), '-T', ''), ', ')\\n   FROM sys.dm_server_registry\\n   WHERE registry_key LIKE '%MSSQLServer\\\\Parameters%'\\n     AND CAST(value_data AS NVARCHAR(256)) LIKE '-T%') AS startup_trace_flags,\\n  CAST(SERVERPROPERTY('ProductVersion') AS NVARCHAR(128)) AS sql_version,\\n  CAST(SERVERPROPERTY('MachineName') AS NVARCHAR(128)) AS machine_name,\\n  (SELECT sqlserver_start_time FROM sys.dm_os_sys_info) AS last_restart"}	{"condition": "startup trace flags present — requires comparison with organizational baseline", "description": "Trace flags differ from standard build configuration — configuration drift detected"}	null	2026-02-23 20:18:31.390772
