3758	postgresql	query	Estimate time to wraparound at current rate	{"sql": "SELECT d.datname, age(d.datfrozenxid) AS current_xid_age, 2147483647 - age(d.datfrozenxid) AS remaining_xids, sd.xact_commit + sd.xact_rollback AS total_xacts_since_reset, EXTRACT(EPOCH FROM (NOW() - sd.stats_reset)) AS seconds_since_reset, CASE WHEN (sd.xact_commit + sd.xact_rollback) > 0 AND EXTRACT(EPOCH FROM (NOW() - sd.stats_reset)) > 0 THEN ROUND(((2147483647 - age(d.datfrozenxid))::numeric / ((sd.xact_commit + sd.xact_rollback)::numeric / EXTRACT(EPOCH FROM (NOW() - sd.stats_reset))::numeric) / 3600), 2) ELSE NULL END AS estimated_hours_to_wraparound FROM pg_database d JOIN pg_stat_database sd ON d.oid = sd.datid WHERE d.datallowconn AND sd.stats_reset IS NOT NULL ORDER BY age(d.datfrozenxid) DESC"}	{"condition": "estimated_hours_to_wraparound < 720", "description": "Less than 30 days to wraparound at current transaction rate requires immediate attention"}	\N	2026-02-25 00:28:52.405273
4659	postgresql	query	Check table-level I/O patterns for thrashing evidence	{"sql": "SELECT t.schemaname, t.relname, pg_size_pretty(pg_total_relation_size(t.relid)) AS total_size, t.seq_scan, t.idx_scan, t.n_tup_ins + t.n_tup_upd + t.n_tup_del AS dml_ops, s.heap_blks_read, s.heap_blks_hit, CASE WHEN s.heap_blks_hit + s.heap_blks_read > 0 THEN round(s.heap_blks_hit::numeric / (s.heap_blks_hit + s.heap_blks_read) * 100, 2) ELSE 100 END AS table_hit_ratio FROM pg_stat_user_tables t JOIN pg_statio_user_tables s USING (relid) WHERE t.seq_scan + t.idx_scan > :min_access_count ORDER BY s.heap_blks_read DESC LIMIT 15"}	{"condition": "table_hit_ratio < :table_hit_threshold", "description": "Tables with low individual hit ratios despite being frequently accessed confirm working set thrashing in the buffer pool"}	{"min_access_count": 100, "table_hit_threshold": 90.0}	2026-02-25 00:28:52.405273
4675	postgresql	query	Estimate table bloat from actual vs expected page count	{"sql": "SELECT t.schemaname, t.tablename, pg_size_pretty(pg_total_relation_size(t.schemaname || '.' || t.tablename)) AS total_size, pg_size_pretty(pg_relation_size(t.schemaname || '.' || t.tablename)) AS table_size FROM pg_tables t JOIN pg_stat_user_tables s ON t.schemaname = s.schemaname AND t.tablename = s.relname WHERE s.n_dead_tup > :dead_threshold ORDER BY pg_total_relation_size(t.schemaname || '.' || t.tablename) DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Large tables with high dead tuple counts are prime bloat candidates"}	{"dead_threshold": 10000}	2026-02-25 00:28:52.405273
4908	postgresql	query	Check statistics target for columns with high cardinality	{"sql": "SELECT s.schemaname, s.tablename, s.attname, s.n_distinct, array_length(string_to_array(s.histogram_bounds::text, ','), 1) AS histogram_buckets, (SELECT attstattarget FROM pg_attribute a JOIN pg_class c ON a.attrelid = c.oid WHERE c.relname = s.tablename AND a.attname = s.attname AND a.attstattarget > 0 LIMIT 1) AS custom_target FROM pg_stats s WHERE s.n_distinct > :high_cardinality AND s.schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY s.n_distinct DESC LIMIT 15"}	{"condition": "histogram_buckets < 100 AND n_distinct > 10000", "description": "High-cardinality columns with default histogram bucket count may have insufficient detail"}	{"high_cardinality": 10000}	2026-02-25 00:28:52.405273
4935	postgresql	query	Check average block read time	{"sql": "SELECT datname, blks_read, blk_read_time, CASE WHEN blks_read > 0 THEN ROUND((blk_read_time / blks_read)::numeric, 2) ELSE 0 END AS avg_read_ms FROM pg_stat_database WHERE datname = current_database() AND blk_read_time > 0"}	{"condition": "avg_read_ms > :hdd_threshold", "description": "Average read latency above threshold indicates HDD-level performance (SSDs typically <1ms)"}	{"hdd_threshold": 3}	2026-02-25 00:28:52.405273
4943	postgresql	query	Check for elevated I/O write latency suggesting network issues	{"sql": "SELECT datname, blks_read, blk_read_time, blk_write_time, CASE WHEN blks_read > 0 THEN ROUND((blk_read_time / blks_read)::numeric, 2) ELSE 0 END AS avg_read_ms FROM pg_stat_database WHERE datname = current_database() AND (blk_read_time > 0 OR blk_write_time > 0)"}	{"condition": "avg_read_ms > :network_latency_threshold", "description": "Consistently high I/O latency may indicate network storage path saturation"}	{"network_latency_threshold": 10}	2026-02-25 00:28:52.405273
4951	postgresql	query	Check WAL sync frequency relative to writes	{"sql": "SELECT current_setting('server_version_num')::int AS version_num, CASE WHEN current_setting('server_version_num')::int >= 140000 THEN 'pg_stat_wal available' ELSE 'pg_stat_wal not available (PG14+)' END AS wal_stats_status"}	{"condition": "sync_to_write_ratio > :ratio_threshold", "description": "High sync-to-write ratio means nearly every write triggers a sync (small transactions not batching)"}	{"ratio_threshold": 0.8}	2026-02-25 00:28:52.405273
4959	postgresql	query	Check WAL write frequency relative to buffer size	{"sql": "SELECT current_setting('server_version_num')::int AS version_num, CASE WHEN current_setting('server_version_num')::int >= 140000 THEN 'pg_stat_wal available' ELSE 'pg_stat_wal not available (PG14+)' END AS wal_stats_status"}	{"condition": "full_flush_ratio > :flush_ratio_threshold", "description": "High ratio of buffer-full flushes to total writes indicates buffer too small for workload"}	{"flush_ratio_threshold": 0.1}	2026-02-25 00:28:52.405273
4961	postgresql	query	Measure commit latency via WAL sync statistics	{"sql": "SELECT current_setting('server_version_num')::int AS version_num, CASE WHEN current_setting('server_version_num')::int >= 140000 THEN 'pg_stat_wal available' ELSE 'pg_stat_wal not available (PG14+)' END AS wal_stats_status"}	{"condition": "avg_sync_ms > :sync_latency_ms", "description": "Each commit pays this sync latency cost; high values confirm synchronous commit overhead"}	{"sync_latency_ms": 1}	2026-02-25 00:28:52.405273
4994	postgresql	query	Check WAL volume generated per checkpoint interval	{"sql": "SELECT current_setting('server_version_num')::int AS version_num, CASE WHEN current_setting('server_version_num')::int >= 140000 THEN 'pg_stat_wal available' ELSE 'pg_stat_wal not available (PG14+)' END AS wal_stats_status"}	{"condition": "fpi_ratio > :fpi_ratio_threshold", "description": "High ratio of full page images to total WAL records confirms significant I/O amplification from full_page_writes"}	{"fpi_ratio_threshold": 0.3}	2026-02-25 00:28:52.405273
6474	oracle	query	ora-check-diagnostic-dest-trace-files	{"sql": "SELECT name, value FROM v$diag_info WHERE name = 'ADR Home'"}	{"condition": "row_count > 0", "description": "ADR home exists and can be checked for accumulated trace and core dump files"}	\N	2026-02-28 12:19:19.580455
5241	postgresql	query	Check table age approaching wraparound threshold	{"sql": "SELECT s.schemaname, s.relname, age(c.relfrozenxid) AS xid_age, (SELECT setting::bigint FROM pg_settings WHERE name = 'autovacuum_freeze_max_age') AS freeze_max_age FROM pg_stat_user_tables s JOIN pg_class c ON c.oid = s.relid WHERE age(c.relfrozenxid) > (SELECT setting::bigint FROM pg_settings WHERE name = 'autovacuum_freeze_max_age') * :threshold_ratio ORDER BY age(c.relfrozenxid) DESC LIMIT 10"}	{"condition": "xid_age > freeze_max_age * :threshold_ratio", "description": "Tables with XID age approaching freeze_max_age trigger aggressive autovacuum"}	{"threshold_ratio": 0.8}	2026-02-25 00:28:52.405273
5807	postgresql	query	Check rootcause schema-level privileges	{"sql": "SELECT nspname, has_schema_privilege('public', nspname, 'CREATE') AS can_create, has_schema_privilege('public', nspname, 'USAGE') AS can_use FROM pg_namespace WHERE nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast', 'pg_temp_1', 'pg_toast_temp_1') ORDER BY nspname"}	{"condition": "can_create = true", "description": "PUBLIC has CREATE privilege on schemas — any user can create objects"}	\N	2026-02-25 00:28:52.405273
5812	postgresql	query	Enumerate all rootcause privileges across objects	{"sql": "SELECT 'schema' AS object_type, nspname AS object_name, nspacl::text AS acl FROM pg_namespace WHERE nspacl::text LIKE '%=U%' AND nspname NOT IN ('pg_catalog', 'information_schema', 'pg_toast') UNION ALL SELECT 'function', n.nspname || '.' || p.proname, p.proacl::text FROM pg_proc p JOIN pg_namespace n ON p.pronamespace = n.oid WHERE p.proacl::text LIKE '%=X/%' AND n.nspname NOT IN ('pg_catalog', 'information_schema') UNION ALL SELECT 'table', schemaname || '.' || tablename, tableowner FROM pg_tables WHERE schemaname NOT IN ('pg_catalog', 'information_schema') AND has_table_privilege('public', schemaname || '.' || tablename, 'SELECT')"}	{"condition": "row_count > :threshold", "description": "Many objects accessible by PUBLIC — no audit has restricted them"}	{"threshold": 10}	2026-02-25 00:28:52.405273
5813	postgresql	query	Find rootcause SELECT grants on user tables	{"sql": "SELECT schemaname, tablename FROM pg_tables WHERE schemaname NOT IN ('pg_catalog', 'information_schema', 'pg_toast') AND has_table_privilege('public', schemaname || '.' || tablename, 'SELECT') ORDER BY schemaname, tablename"}	{"condition": "row_count > 0", "description": "PUBLIC can SELECT from user tables — extended beyond system catalog defaults"}	\N	2026-02-25 00:28:52.405273
5907	postgresql	query	Check for superuser accounts accepting remote connections	{"sql": "SELECT r.rolname FROM pg_roles r WHERE r.rolsuper = true AND r.rolcanlogin = true AND EXISTS (SELECT 1 FROM pg_hba_file_rules hba WHERE hba.type IN ('host', 'hostssl') AND (hba.user_name @> ARRAY[r.rolname::text] OR hba.user_name @> ARRAY['all']::text[]))"}	{"condition": "row_count > 0", "description": "Superuser accounts accept remote connections — remote COPY FROM possible"}	\N	2026-02-25 00:28:52.405273
6055	postgresql	query	Find functions using EXECUTE with string concatenation	{"sql": "SELECT n.nspname AS schema_name, p.proname AS function_name, pg_get_functiondef(p.oid) AS function_def FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind NOT IN ('a', 'w') AND pg_get_functiondef(p.oid) ~* 'EXECUTE\\\\s+.*(\\\\|\\\\||concat|format\\\\s*\\\\()' AND pg_get_functiondef(p.oid) !~* 'EXECUTE\\\\s+.*USING'"}	{"condition": "row_count > 0", "description": "Functions using EXECUTE with concatenation but not parameterized USING clause"}	\N	2026-02-25 00:28:52.405273
6060	postgresql	query	Count dynamic SQL functions vs total functions	{"sql": "SELECT (SELECT COUNT(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind NOT IN ('a', 'w') AND pg_get_functiondef(p.oid) ~* 'EXECUTE') AS dynamic_sql_count, (SELECT COUNT(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind NOT IN ('a', 'w')) AS total_function_count"}	{"condition": "dynamic_sql_count > :threshold AND dynamic_sql_count * 100 / NULLIF(total_function_count, 0) > :pct_threshold", "description": "Significant proportion of functions use dynamic SQL requiring review"}	{"threshold": 5, "pct_threshold": 20}	2026-02-25 00:28:52.405273
6061	postgresql	query	Find functions mixing static and dynamic SQL constructs	{"sql": "SELECT n.nspname, p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind NOT IN ('a', 'w') AND pg_get_functiondef(p.oid) ~* 'EXECUTE' AND pg_get_functiondef(p.oid) ~* '(SELECT|INSERT|UPDATE|DELETE)\\\\s+' AND pg_get_functiondef(p.oid) ~* '\\\\|\\\\|'"}	{"condition": "row_count > 0", "description": "Functions mixing static SQL with dynamic concatenated EXECUTE"}	\N	2026-02-25 00:28:52.405273
6062	postgresql	query	Find functions with dynamic identifier construction	{"sql": "SELECT n.nspname, p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind NOT IN ('a', 'w') AND (pg_get_functiondef(p.oid) ~* 'EXECUTE.*format\\\\s*\\\\(' OR pg_get_functiondef(p.oid) ~* 'EXECUTE.*\\\\|\\\\|.*\\\\.(table|schema|column)' OR pg_get_functiondef(p.oid) ~* 'quote_ident')"}	{"condition": "row_count > 0", "description": "Functions dynamically constructing table/column identifiers"}	\N	2026-02-25 00:28:52.405273
6063	postgresql	query	Find functions using EXECUTE with concatenation and no USING	{"sql": "SELECT n.nspname, p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind NOT IN ('a', 'w') AND pg_get_functiondef(p.oid) ~* 'EXECUTE\\\\s*\\\\(' AND pg_get_functiondef(p.oid) !~* 'USING'"}	{"condition": "row_count > 0", "description": "Functions using direct EXECUTE without parameter binding"}	\N	2026-02-25 00:28:52.405273
6068	postgresql	query	Find stored procedures with unsafe EXECUTE and no USING	{"sql": "SELECT n.nspname, p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_language l ON l.oid = p.prolang WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND p.prokind NOT IN ('a', 'w') AND l.lanname = 'plpgsql' AND pg_get_functiondef(p.oid) ~* 'EXECUTE' AND pg_get_functiondef(p.oid) !~* 'USING' AND pg_get_functiondef(p.oid) ~* '\\\\|\\\\|'"}	{"condition": "row_count > 0", "description": "PL/pgSQL functions with EXECUTE + concatenation but no USING clause"}	\N	2026-02-25 00:28:52.405273
6134	postgresql	query	Check for deprecated configuration parameters and features	{"sql": "SELECT name, setting, category FROM pg_settings WHERE name IN ('default_with_oids', 'wal_level', 'vacuum_defer_cleanup_age') AND setting != '0'"}	{"condition": "row_count > 0", "description": "Deprecated features in use — blocking upgrade path"}	\N	2026-02-25 00:28:52.405273
6152	postgresql	query	Check for extension dependency chains	{"sql": "SELECT e.extname, d.refobjid::regclass::text AS depends_on FROM pg_depend d JOIN pg_extension e ON e.oid = d.objid WHERE d.deptype = 'e' AND d.classid = 'pg_extension'::regclass UNION ALL SELECT e1.extname, e2.extname::text FROM pg_extension e1 JOIN pg_depend d ON d.objid = e1.oid JOIN pg_extension e2 ON e2.oid = d.refobjid WHERE d.deptype = 'n'"}	{"condition": "row_count > :threshold", "description": "Multiple extension dependency chains — complex update requirements"}	{"threshold": 3}	2026-02-25 00:28:52.405273
6267	oracle	query	ORA verify unindexed FK columns causing table locks	{"sql": "SELECT c.owner, c.table_name, c.constraint_name, cc.column_name, CASE WHEN EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ic WHERE ic.table_owner = cc.owner AND ic.table_name = cc.table_name AND ic.column_name = cc.column_name) THEN 'INDEXED' ELSE 'NOT_INDEXED' END AS fk_index_status FROM ALL_CONSTRAINTS c JOIN ALL_CONS_COLUMNS cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner WHERE c.constraint_type = 'R' AND c.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB') AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ic WHERE ic.table_owner = cc.owner AND ic.table_name = cc.table_name AND ic.column_name = cc.column_name) ORDER BY c.owner, c.table_name"}	{"condition": "row_count > 0", "description": "Unindexed foreign key columns cause full table locks on child table during parent DML, creating hidden dependencies"}	\N	2026-02-28 12:19:19.580455
6269	oracle	query	ora_check_deadlocks_for_multiplan_sqls	{"sql": "SELECT s1.sid AS blocking_sid, s2.sid AS waiting_sid, s1.sql_id AS blocking_sql_id, s2.sql_id AS waiting_sql_id, s2.event, s2.wait_class FROM v$lock l1 JOIN v$lock l2 ON l1.id1 = l2.id1 AND l1.id2 = l2.id2 AND l1.block = 1 AND l2.request > 0 JOIN v$session s1 ON l1.sid = s1.sid JOIN v$session s2 ON l2.sid = s2.sid WHERE s2.sql_id IN (SELECT sql_id FROM v$sql GROUP BY sql_id HAVING COUNT(DISTINCT plan_hash_value) > 1) FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Deadlocks involving multi-plan SQL statements confirms plan variation lock ordering"}	\N	2026-02-28 12:19:19.580455
6283	oracle	query	ora_find_triggers_with_dml	{"sql": "SELECT t.owner, t.table_name, t.trigger_name, t.trigger_type, t.triggering_event FROM ALL_TRIGGERS t WHERE t.status = 'ENABLED' AND t.owner NOT IN ('SYS','SYSTEM','DBSNMP') AND t.trigger_type LIKE '%ROW%' AND t.triggering_event IN ('INSERT','UPDATE','DELETE','INSERT OR UPDATE','INSERT OR DELETE','UPDATE OR DELETE','INSERT OR UPDATE OR DELETE') ORDER BY t.owner, t.table_name"}	{"condition": "row_count > 0", "description": "Row-level triggers that perform DML on other tables acquire additional implicit locks"}	\N	2026-02-28 12:19:19.580455
6291	oracle	query	ora_find_all_unindexed_fk_columns	{"sql": "SELECT c.owner, c.table_name, c.constraint_name, cc.column_name, r.table_name AS parent_table FROM ALL_CONSTRAINTS c JOIN ALL_CONS_COLUMNS cc ON c.constraint_name = cc.constraint_name AND c.owner = cc.owner JOIN ALL_CONSTRAINTS r ON c.r_constraint_name = r.constraint_name AND c.r_owner = r.owner WHERE c.constraint_type = 'R' AND c.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ic WHERE ic.table_owner = cc.owner AND ic.table_name = cc.table_name AND ic.column_name = cc.column_name) ORDER BY c.owner, c.table_name"}	{"condition": "row_count > 0", "description": "Unindexed FK columns cause full child-table locks on parent updates/deletes in Oracle"}	\N	2026-02-28 12:19:19.580455
