6634	oracle	query	ora-schema-owner-priv: identify schema owners with large object counts	{"sql": "SELECT owner, object_type, COUNT(*) AS object_count FROM ALL_OBJECTS WHERE owner NOT IN ('SYS', 'SYSTEM', 'DBSNMP', 'OUTLN', 'MDSYS', 'ORDSYS', 'ORDDATA', 'CTXSYS', 'ANONYMOUS', 'EXFSYS', 'DMSYS', 'WMSYS', 'XDB', 'APPQOSSYS', 'DBSFWUSER', 'GSMADMIN_INTERNAL') AND object_type IN ('TABLE', 'VIEW', 'PROCEDURE', 'FUNCTION', 'PACKAGE', 'TRIGGER', 'SEQUENCE') GROUP BY owner, object_type HAVING COUNT(*) > 10 ORDER BY owner, object_count DESC"}	{"condition": "row_count > 0", "description": "Schema owners with many objects have implicit full control over all those objects"}	\N	2026-02-28 12:19:19.580455
6637	oracle	query	ora-trigger-priv-esc: check trigger bodies for privileged operations	{"sql": "SELECT t.owner, t.trigger_name, t.table_owner, t.table_name, s.text AS trigger_body_line FROM dba_triggers t JOIN dba_source s ON t.owner = s.owner AND t.trigger_name = s.name AND s.type = 'TRIGGER' WHERE t.status = 'ENABLED' AND (UPPER(s.text) LIKE '%EXECUTE IMMEDIATE%' OR UPPER(s.text) LIKE '%DBMS_SQL%' OR UPPER(s.text) LIKE '%ALTER%USER%' OR UPPER(s.text) LIKE '%GRANT%' OR UPPER(s.text) LIKE '%CREATE%USER%' OR UPPER(s.text) LIKE '%DBMS_SCHEDULER%') AND t.owner NOT IN ('SYS', 'SYSTEM') ORDER BY t.owner, t.trigger_name"}	{"condition": "row_count > 0", "description": "Triggers containing dynamic SQL or privilege-modifying operations confirm potential privilege escalation"}	\N	2026-02-28 12:19:19.580455
