6762	oracle	query	ora_check_table_empty_blocks_above_hwm	{"sql": "SELECT owner, table_name, num_rows, blocks, empty_blocks, avg_space, ROUND(empty_blocks / NULLIF(blocks + empty_blocks, 0) * 100, 1) AS empty_pct FROM ALL_TABLES WHERE empty_blocks > 0 AND num_rows > 0 AND blocks > 100 AND empty_blocks / NULLIF(blocks + empty_blocks, 0) > :empty_threshold ORDER BY empty_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "High ratio of empty blocks indicates space waste from delete operations not reclaimed"}	{"empty_threshold": 0.3}	2026-02-28 12:19:19.580455
6707	oracle	query	ORA check staleness of locked table statistics	{"sql": "SELECT ts.owner, ts.table_name, ts.num_rows, ts.last_analyzed, ts.stale_stats, ROUND(SYSDATE - ts.last_analyzed) AS days_since_analyzed, tm.inserts + tm.updates + tm.deletes AS total_mods FROM ALL_TAB_STATISTICS ts LEFT JOIN ALL_TAB_MODIFICATIONS tm ON ts.owner = tm.table_owner AND ts.table_name = tm.table_name WHERE ts.stattype_locked IS NOT NULL AND ts.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB', 'WMSYS', 'OUTLN') AND (ts.stale_stats = 'YES' OR ts.last_analyzed < SYSDATE - :stale_days) ORDER BY total_mods DESC NULLS LAST FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Locked tables with stale statistics or recent modifications confirm stats are suppressed"}	{"stale_days": 30}	2026-02-28 12:19:19.580455
6712	oracle	query	ora_check_auto_stats_job_status	{"sql": "SELECT client_name, window_name, window_start_time, window_end_time, window_duration, jobs_created, jobs_started, jobs_completed FROM dba_autotask_client_history WHERE client_name = 'auto optimizer stats collection' ORDER BY window_start_time DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0 AND recent runs show completion", "description": "Auto optimizer stats collection job history shows whether it is running and completing"}	\N	2026-02-28 12:19:19.580455
6714	oracle	query	ora_count_tables_with_stale_stats	{"sql": "SELECT COUNT(*) AS stale_count FROM ALL_TAB_STATISTICS WHERE stale_stats = 'YES' AND owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB')"}	{"condition": "stale_count > :max_stale_tables", "description": "Large number of tables with stale statistics indicates auto stats job is insufficient"}	{"max_stale_tables": 50}	2026-02-28 12:19:19.580455
6716	oracle	query	ora_count_stale_tables_by_threshold	{"sql": "SELECT t.owner, t.table_name, t.num_rows, m.inserts + m.updates + m.deletes AS total_changes, ROUND((m.inserts + m.updates + m.deletes) / GREATEST(t.num_rows, 1) * 100, 1) AS change_pct FROM ALL_TABLES t JOIN ALL_TAB_MODIFICATIONS m ON t.owner = m.table_owner AND t.table_name = m.table_name WHERE t.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND t.num_rows > 0 AND (m.inserts + m.updates + m.deletes) / GREATEST(t.num_rows, 1) BETWEEN 0.05 AND 0.10 ORDER BY total_changes DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with 5-10% change rate would benefit from a lower stale_percent threshold but are not yet considered stale"}	\N	2026-02-28 12:19:19.580455
