6738	oracle	query	ora_check_index_pctfree_settings	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.pct_free, i.leaf_blocks, i.distinct_keys, i.num_rows FROM ALL_INDEXES i WHERE i.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND i.pct_free < :min_pctfree AND i.index_type = 'NORMAL' AND i.num_rows > 10000 ORDER BY i.leaf_blocks DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with low PCTFREE have less room for new entries, causing more frequent block splits"}	{"min_pctfree": 10}	2026-02-28 12:19:19.580455
6742	oracle	query	ora_check_low_pctfree_tables	{"sql": "SELECT owner, table_name, pct_free, num_rows, chain_cnt, ROUND(chain_cnt / NULLIF(num_rows, 0) * 100, 2) AS chain_pct FROM ALL_TABLES WHERE pct_free < :pctfree_threshold AND num_rows > 10000 AND chain_cnt > 0 ORDER BY chain_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 AND any chain_pct > 5", "description": "Tables with low PCTFREE and significant row chaining indicate fragmentation from undersized free space"}	{"pctfree_threshold": 5}	2026-02-28 12:19:19.580455
6744	oracle	query	ora_check_high_pctfree_tables	{"sql": "SELECT owner, table_name, pct_free, num_rows, blocks, avg_row_len, ROUND(num_rows * avg_row_len / (blocks * 8192) * 100, 1) AS actual_fill_pct FROM ALL_TABLES WHERE pct_free > :high_pctfree AND num_rows > 10000 AND blocks > 100 ORDER BY pct_free DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with very high PCTFREE waste significant space, increasing I/O for full scans"}	{"high_pctfree": 30}	2026-02-28 12:19:19.580455
