6760	oracle	query	ora_check_index_key_distribution_skew	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.distinct_keys, i.num_rows, i.avg_leaf_blocks_per_key, i.avg_data_blocks_per_key, ROUND(i.num_rows / NULLIF(i.distinct_keys, 0), 1) AS avg_rows_per_key FROM ALL_INDEXES i WHERE i.index_type = 'NORMAL' AND i.num_rows > 10000 AND i.num_rows / NULLIF(i.distinct_keys, 0) > :skew_threshold ORDER BY avg_rows_per_key DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "High average rows per key with wide variation indicates uneven data distribution"}	{"skew_threshold": 100}	2026-02-28 12:19:19.580455
