7966	oracle	query	ora_check_index_clustering_factor [PERF-SQL-CE-005-RC01]	{"sql": "SELECT i.INDEX_NAME, i.TABLE_NAME, i.CLUSTERING_FACTOR, t.NUM_ROWS, t.BLOCKS, ROUND(i.CLUSTERING_FACTOR / NULLIF(t.NUM_ROWS, 0), 4) AS cf_ratio FROM ALL_INDEXES i JOIN ALL_TABLES t ON i.TABLE_NAME = t.TABLE_NAME AND i.OWNER = t.OWNER WHERE i.INDEX_NAME IN (SELECT INDEX_NAME FROM ALL_CONSTRAINTS WHERE CONSTRAINT_TYPE = 'P') AND ((i.OWNER, i.TABLE_NAME) IN (SELECT cc.OWNER, cc.TABLE_NAME FROM ALL_CONS_COLUMNS cc JOIN ALL_TAB_COLUMNS c ON cc.TABLE_NAME = c.TABLE_NAME AND cc.COLUMN_NAME = c.COLUMN_NAME AND cc.OWNER = c.OWNER WHERE (c.DATA_TYPE = 'RAW' AND c.DATA_LENGTH = 16) OR (c.DATA_TYPE IN ('VARCHAR2', 'CHAR') AND c.DATA_LENGTH >= 32))) AND i.OWNER NOT IN ('SYS', 'SYSTEM') ORDER BY cf_ratio DESC"}	{"condition": "cf_ratio > :threshold", "description": "High clustering factor ratio confirms random UUID distribution in index"}	{"threshold": 0.5}	2026-02-28 12:19:19.580455
