7980	oracle	query	ora_check_fk_index_maintenance_overhead	{"sql": "SELECT fk.OWNER, fk.TABLE_NAME AS child_table, fk.CONSTRAINT_NAME, fk.R_CONSTRAINT_NAME, c2.TABLE_NAME AS parent_table, COUNT(ic.COLUMN_NAME) AS fk_columns FROM ALL_CONSTRAINTS fk JOIN ALL_CONSTRAINTS c2 ON fk.R_CONSTRAINT_NAME = c2.CONSTRAINT_NAME AND fk.R_OWNER = c2.OWNER JOIN ALL_CONS_COLUMNS ic ON fk.CONSTRAINT_NAME = ic.CONSTRAINT_NAME AND fk.OWNER = ic.OWNER WHERE fk.CONSTRAINT_TYPE = 'R' AND fk.OWNER NOT IN ('SYS', 'SYSTEM') GROUP BY fk.OWNER, fk.TABLE_NAME, fk.CONSTRAINT_NAME, fk.R_CONSTRAINT_NAME, c2.TABLE_NAME ORDER BY fk.TABLE_NAME"}	{"condition": "row_count > 0", "description": "Foreign key relationships found"}	\N	2026-02-28 12:19:19.580455
