8201	oracle	query	ora_find_bulk_loaded_tables_stale	{"sql": "SELECT t.owner, t.table_name, t.num_rows, t.last_analyzed, m.inserts, m.updates, m.deletes, m.inserts + m.updates + m.deletes AS total_changes, ROUND((m.inserts + m.updates + m.deletes) / GREATEST(t.num_rows, 1) * 100, 1) AS change_pct FROM ALL_TABLES t JOIN ALL_TAB_MODIFICATIONS m ON t.owner = m.table_owner AND t.table_name = m.table_name WHERE t.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','XDB') AND (m.inserts + m.updates + m.deletes) > :min_changes AND t.num_rows > 0 ORDER BY change_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0 AND change_pct > 50", "description": "Tables with >50% data changes since last statistics gather confirm bulk operations without stats refresh"}	{"min_changes": 100000}	2026-02-28 12:19:19.580455
