8373	oracle	query	ora_small_table_excessive_indexes	{"sql": "SELECT t.owner, t.table_name, t.num_rows, t.blocks, (SELECT COUNT(*) FROM ALL_INDEXES i WHERE i.table_owner = t.owner AND i.table_name = t.table_name) AS index_count FROM ALL_TABLES t WHERE t.owner NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB') AND t.num_rows < :small_table_threshold AND (SELECT COUNT(*) FROM ALL_INDEXES i WHERE i.table_owner = t.owner AND i.table_name = t.table_name) > :min_indexes ORDER BY index_count DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Small tables with multiple indexes — indexes are wasteful and unused"}	{"min_indexes": 2, "small_table_threshold": 100}	2026-02-28 12:19:19.580455
8378	oracle	query	ora_indexed_column_update_frequency	{"sql": "SELECT ic.index_owner, ic.index_name, ic.table_name, ic.column_name, tm.updates, tm.inserts, tm.deletes FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_MODIFICATIONS tm ON ic.table_owner = tm.table_owner AND ic.table_name = tm.table_name WHERE ic.index_owner NOT IN ('SYS', 'SYSTEM') AND tm.updates > :update_threshold ORDER BY tm.updates DESC FETCH FIRST 30 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes on frequently updated columns found — high fragmentation risk"}	{"update_threshold": 50000}	2026-02-28 12:19:19.580455
8379	oracle	query	ora_index_blevel_degradation	{"sql": "SELECT owner, index_name, table_name, blevel, leaf_blocks, distinct_keys, clustering_factor, last_analyzed FROM ALL_INDEXES WHERE owner NOT IN ('SYS', 'SYSTEM') AND blevel > :blevel_threshold AND index_type = 'NORMAL' ORDER BY blevel DESC, leaf_blocks DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "High B-tree level indexes confirm degradation from frequent updates"}	{"blevel_threshold": 3}	2026-02-28 12:19:19.580455
8384	oracle	query	ora_row_migration_chain_count	{"sql": "SELECT owner, table_name, chain_cnt, num_rows, ROUND(chain_cnt / GREATEST(num_rows, 1) * 100, 1) AS chain_pct FROM ALL_TABLES WHERE owner NOT IN ('SYS', 'SYSTEM') AND chain_cnt > :min_chains ORDER BY chain_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "High row chaining/migration count confirms row expansion impacting index"}	{"min_chains": 100}	2026-02-28 12:19:19.580455
8385	oracle	query	ora_varchar2_indexed_column_analysis	{"sql": "SELECT ic.index_owner, ic.index_name, ic.table_name, ic.column_name, tc.data_type, tc.data_length, tc.avg_col_len, di.leaf_blocks, di.num_rows FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COLUMNS tc ON ic.table_owner = tc.owner AND ic.table_name = tc.table_name AND ic.column_name = tc.column_name JOIN ALL_INDEXES di ON ic.index_owner = di.owner AND ic.index_name = di.index_name WHERE ic.index_owner NOT IN ('SYS', 'SYSTEM') AND tc.data_type LIKE 'VARCHAR2%' AND tc.data_length > 100 AND di.num_rows > :min_rows ORDER BY tc.data_length DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "VARCHAR2 indexed columns with large max length — susceptible to size increase bloat"}	{"min_rows": 10000}	2026-02-28 12:19:19.580455
8420	oracle	query	Oracle check DML activity on over-indexed tables	{"sql": "SELECT table_owner, table_name, inserts, updates, deletes, (inserts + updates + deletes) AS total_dml, TO_CHAR(timestamp, 'YYYY-MM-DD') AS since FROM ALL_TAB_MODIFICATIONS WHERE (table_owner, table_name) IN (SELECT table_owner, table_name FROM ALL_INDEXES WHERE table_owner NOT IN ('SYS', 'SYSTEM') GROUP BY table_owner, table_name HAVING COUNT(*) > 8) ORDER BY (inserts + updates + deletes) DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "total_dml > :dml_threshold", "description": "High DML activity on over-indexed tables — excessive index maintenance consuming resources"}	{"dml_threshold": 100000}	2026-02-28 12:19:19.580455
8401	oracle	query	Oracle find FK columns with multiple supporting indexes	{"sql": "SELECT fk.constraint_name, fk.table_name, fk_cols.cols AS fk_columns, COUNT(DISTINCT i.index_name) AS supporting_indexes FROM ALL_CONSTRAINTS fk JOIN (SELECT owner, constraint_name, LISTAGG(column_name, ',') WITHIN GROUP (ORDER BY position) AS cols FROM ALL_CONS_COLUMNS GROUP BY owner, constraint_name) fk_cols ON fk.constraint_name = fk_cols.constraint_name AND fk.owner = fk_cols.owner JOIN ALL_IND_COLUMNS ic ON fk.table_name = ic.table_name AND fk.owner = ic.index_owner JOIN ALL_INDEXES i ON ic.index_name = i.index_name AND ic.index_owner = i.owner WHERE fk.constraint_type = 'R' AND fk.owner NOT IN ('SYS', 'SYSTEM') GROUP BY fk.constraint_name, fk.table_name, fk_cols.cols HAVING COUNT(DISTINCT i.index_name) > 1 ORDER BY supporting_indexes DESC"}	{"condition": "row_count > 0", "description": "Foreign keys with multiple supporting indexes have redundant index coverage"}	\N	2026-02-28 12:19:19.580455
8403	oracle	query	Oracle find IOTs with redundant secondary indexes	{"sql": "SELECT t.table_name, t.iot_type, i.index_name, i.index_type, LISTAGG(c.column_name, ',') WITHIN GROUP (ORDER BY c.column_position) AS idx_cols FROM ALL_TABLES t JOIN ALL_INDEXES i ON t.table_name = i.table_name AND t.owner = i.owner JOIN ALL_IND_COLUMNS c ON i.index_name = c.index_name AND i.owner = c.index_owner WHERE t.iot_type = 'IOT' AND i.index_type != 'IOT - TOP' AND t.owner NOT IN ('SYS', 'SYSTEM') GROUP BY t.table_name, t.iot_type, i.index_name, i.index_type ORDER BY t.table_name"}	{"condition": "row_count > 0 with secondary indexes on IOT PK columns", "description": "Secondary indexes on IOT primary key columns are redundant since the table is organized by PK"}	\N	2026-02-28 12:19:19.580455
8406	oracle	query	Oracle find single-column indexes with 2-3 distinct values	{"sql": "SELECT i.index_name, i.table_name, ic.column_name, tc.num_distinct, t.num_rows, ROUND(100.0 / NULLIF(tc.num_distinct, 0), 1) AS pct_per_value FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS ic ON i.index_name = ic.index_name AND i.owner = ic.index_owner JOIN ALL_TAB_COL_STATISTICS tc ON ic.table_name = tc.table_name AND ic.column_name = tc.column_name AND ic.index_owner = tc.owner JOIN ALL_TABLES t ON i.table_name = t.table_name AND i.owner = t.owner WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND tc.num_distinct IN (2, 3) AND t.num_rows > :min_rows AND (SELECT COUNT(*) FROM ALL_IND_COLUMNS WHERE index_name = i.index_name AND index_owner = i.owner) = 1 ORDER BY t.num_rows DESC"}	{"condition": "row_count > 0", "description": "Single-column indexes with only 2-3 distinct values are ineffective (33-50% selectivity per value)"}	{"min_rows": 50000}	2026-02-28 12:19:19.580455
8408	oracle	query	Oracle find date indexes with poor selectivity	{"sql": "SELECT i.index_name, i.table_name, ic.column_name, tc.num_distinct, t.num_rows, ROUND(t.num_rows / NULLIF(tc.num_distinct, 0), 0) AS avg_rows_per_date FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS ic ON i.index_name = ic.index_name AND i.owner = ic.index_owner JOIN ALL_TAB_COLUMNS tc ON ic.table_name = tc.table_name AND ic.column_name = tc.column_name AND ic.index_owner = tc.owner JOIN ALL_TABLES t ON i.table_name = t.table_name AND i.owner = t.owner WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND tc.data_type IN ('DATE', 'TIMESTAMP(6)') AND ic.column_position = 1 AND t.num_rows > :min_rows AND t.num_rows / NULLIF(tc.num_distinct, 0) > :avg_threshold ORDER BY avg_rows_per_date DESC FETCH FIRST 15 ROWS ONLY"}	{"condition": "row_count > 0 with very high avg_rows_per_date", "description": "Date columns where many rows share the same value make the index poorly selective"}	{"min_rows": 100000, "avg_threshold": 5000}	2026-02-28 12:19:19.580455
8409	oracle	query	Oracle find indexes with dominant categorical values	{"sql": "SELECT i.index_name, i.table_name, ic.column_name, tc.num_distinct, t.num_rows, tc.density FROM ALL_INDEXES i JOIN ALL_IND_COLUMNS ic ON i.index_name = ic.index_name AND i.owner = ic.index_owner JOIN ALL_TAB_COL_STATISTICS tc ON ic.table_name = tc.table_name AND ic.column_name = tc.column_name AND ic.index_owner = tc.owner JOIN ALL_TABLES t ON i.table_name = t.table_name AND i.owner = t.owner WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND tc.num_distinct BETWEEN 2 AND 50 AND tc.density > :density_threshold AND t.num_rows > :min_rows AND ic.column_position = 1 ORDER BY tc.density DESC FETCH FIRST 15 ROWS ONLY"}	{"condition": "row_count > 0 with high density values", "description": "High density (1/num_distinct without histograms) on categorical columns indicates poor selectivity"}	{"min_rows": 100000, "density_threshold": 0.1}	2026-02-28 12:19:19.580455
8411	oracle	query	Oracle find indexes without histograms on skewed columns	{"sql": "SELECT i.owner, i.index_name, i.table_name, ic.column_name, tc.num_distinct, tc.num_nulls, tc.histogram FROM ALL_IND_COLUMNS ic JOIN ALL_INDEXES i ON ic.index_owner = i.owner AND ic.index_name = i.index_name JOIN ALL_TAB_COL_STATISTICS tc ON ic.table_owner = tc.owner AND ic.table_name = tc.table_name AND ic.column_name = tc.column_name WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND tc.histogram = 'NONE' AND tc.num_distinct < 100 AND ic.column_position = 1 ORDER BY tc.num_distinct ASC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes on low-cardinality columns without histograms — created without analyzing data distribution"}	\N	2026-02-28 12:19:19.580455
8413	oracle	query	Oracle find indexes with stale statistics	{"sql": "SELECT i.owner, i.index_name, i.table_name, i.distinct_keys, TO_CHAR(i.last_analyzed, 'YYYY-MM-DD') AS index_analyzed, TO_CHAR(t.last_analyzed, 'YYYY-MM-DD') AS table_analyzed, t.num_rows, ts.stale_stats FROM ALL_INDEXES i JOIN ALL_TABLES t ON i.table_owner = t.owner AND i.table_name = t.table_name JOIN ALL_TAB_STATISTICS ts ON t.owner = ts.owner AND t.table_name = ts.table_name WHERE i.owner NOT IN ('SYS', 'SYSTEM') AND (ts.stale_stats = 'YES' OR i.last_analyzed < SYSDATE - 30) AND t.num_rows > 10000 ORDER BY t.num_rows DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with stale statistics on large tables — selectivity estimates may be wrong"}	\N	2026-02-28 12:19:19.580455
8417	oracle	query	Oracle check for missing function-based indexes on UPPER/LOWER	{"sql": "SELECT ie.index_owner, ie.index_name, ie.table_name, ie.column_position FROM dba_ind_expressions ie JOIN dba_indexes i ON ie.index_owner = i.owner AND ie.index_name = i.index_name WHERE i.index_type = 'FUNCTION-BASED NORMAL' ORDER BY ie.index_owner, ie.index_name"}	{"condition": "row_count = 0", "description": "No function-based indexes on UPPER/LOWER — case-insensitive queries cannot use any index"}	\N	2026-02-28 12:19:19.580455
8418	oracle	query	Oracle find indexed columns with high NULL percentage	{"sql": "SELECT ic.index_owner, ic.index_name, ic.table_name, ic.column_name, tc.num_nulls, t.num_rows, ROUND(tc.num_nulls/NULLIF(t.num_rows, 0)*100, 2) AS null_pct FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COL_STATISTICS tc ON ic.table_owner = tc.owner AND ic.table_name = tc.table_name AND ic.column_name = tc.column_name JOIN ALL_TABLES t ON ic.table_owner = t.owner AND ic.table_name = t.table_name WHERE ic.index_owner NOT IN ('SYS', 'SYSTEM') AND tc.num_nulls > 0 AND t.num_rows > 10000 AND ic.column_position = 1 AND ROUND(tc.num_nulls/NULLIF(t.num_rows, 0)*100, 2) > :null_threshold ORDER BY null_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Leading index columns with high NULL percentage — B-tree index excludes these rows"}	{"null_threshold": 30}	2026-02-28 12:19:19.580455
8421	oracle	query	Oracle find tables with many single-column indexes	{"sql": "SELECT i.table_owner, i.table_name, COUNT(*) AS single_col_indexes FROM ALL_INDEXES i WHERE i.table_owner NOT IN ('SYS', 'SYSTEM') AND i.uniqueness = 'NONUNIQUE' AND (SELECT COUNT(*) FROM ALL_IND_COLUMNS ic WHERE ic.index_owner = i.owner AND ic.index_name = i.index_name) = 1 GROUP BY i.table_owner, i.table_name HAVING COUNT(*) > :threshold ORDER BY single_col_indexes DESC"}	{"condition": "row_count > 0", "description": "Tables with many individual single-column indexes — should be consolidated into composite indexes"}	{"threshold": 5}	2026-02-28 12:19:19.580455
8429	oracle	query	Oracle find FK indexes and their usage	{"sql": "SELECT cc.owner, cc.table_name, cc.constraint_name, cc.column_name, i.index_name, i.uniqueness FROM ALL_CONS_COLUMNS cc JOIN ALL_CONSTRAINTS c ON cc.owner = c.owner AND cc.constraint_name = c.constraint_name JOIN ALL_IND_COLUMNS ic ON cc.owner = ic.index_owner AND cc.table_name = ic.table_name AND cc.column_name = ic.column_name AND ic.column_position = 1 JOIN ALL_INDEXES i ON ic.index_owner = i.owner AND ic.index_name = i.index_name WHERE c.constraint_type = 'R' AND cc.owner NOT IN ('SYS', 'SYSTEM') ORDER BY cc.owner, cc.table_name"}	{"condition": "row_count > :threshold", "description": "Many foreign key indexes exist — not all may be needed for the actual query workload"}	{"threshold": 20}	2026-02-28 12:19:19.580455
8430	oracle	query	Oracle check unindexed FKs that DO need indexes for locking	{"sql": "SELECT c.owner, c.table_name, c.constraint_name, cc.column_name FROM ALL_CONSTRAINTS c JOIN ALL_CONS_COLUMNS cc ON c.owner = cc.owner AND c.constraint_name = cc.constraint_name WHERE c.constraint_type = 'R' AND c.owner NOT IN ('SYS', 'SYSTEM') AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ic WHERE ic.table_owner = cc.owner AND ic.table_name = cc.table_name AND ic.column_name = cc.column_name AND ic.column_position = 1) ORDER BY c.owner, c.table_name"}	{"condition": "row_count > 0", "description": "Unindexed foreign keys found — these cause table-level locks during parent key updates in Oracle"}	\N	2026-02-28 12:19:19.580455
8431	oracle	query	Oracle find duplicate indexes by column prefix	{"sql": "SELECT a.owner, a.table_name, a.index_name AS redundant_index, b.index_name AS covering_index, (SELECT LISTAGG(column_name, ',') WITHIN GROUP (ORDER BY column_position) FROM ALL_IND_COLUMNS WHERE index_owner = a.owner AND index_name = a.index_name) AS redundant_cols, (SELECT LISTAGG(column_name, ',') WITHIN GROUP (ORDER BY column_position) FROM ALL_IND_COLUMNS WHERE index_owner = b.owner AND index_name = b.index_name) AS covering_cols FROM ALL_INDEXES a JOIN ALL_INDEXES b ON a.table_owner = b.table_owner AND a.table_name = b.table_name AND a.index_name != b.index_name WHERE a.owner NOT IN ('SYS', 'SYSTEM') AND (SELECT COUNT(*) FROM ALL_IND_COLUMNS WHERE index_owner = a.owner AND index_name = a.index_name) < (SELECT COUNT(*) FROM ALL_IND_COLUMNS WHERE index_owner = b.owner AND index_name = b.index_name) AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ac LEFT JOIN ALL_IND_COLUMNS bc ON ac.column_name = bc.column_name AND ac.column_position = bc.column_position AND bc.index_owner = b.owner AND bc.index_name = b.index_name WHERE ac.index_owner = a.owner AND ac.index_name = a.index_name AND bc.column_name IS NULL) ORDER BY a.owner, a.table_name"}	{"condition": "row_count > 0", "description": "Indexes fully covered by another wider composite index — redundant and can be dropped"}	\N	2026-02-28 12:19:19.580455
8695	oracle	query	ora_histogram_skew_on_parallel_columns	{"sql": "SELECT owner, table_name, column_name, num_distinct, num_nulls, histogram, num_buckets FROM ALL_TAB_COL_STATISTICS WHERE owner NOT IN ('SYS', 'SYSTEM') AND histogram != 'NONE' AND num_distinct > 0 AND num_buckets < num_distinct / 10 ORDER BY num_distinct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Columns with skewed distributions that may cause parallel data skew"}	\N	2026-02-28 12:19:19.580455
8438	oracle	query	Oracle find indexes with wide VARCHAR2 key columns	{"sql": "SELECT ic.index_owner, ic.index_name, ic.table_name, ic.column_name, tc.data_type, tc.data_length, tc.avg_col_len FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COLUMNS tc ON ic.table_owner = tc.owner AND ic.table_name = tc.table_name AND ic.column_name = tc.column_name WHERE ic.index_owner NOT IN ('SYS', 'SYSTEM') AND tc.data_type = 'VARCHAR2' AND tc.data_length > :width_threshold ORDER BY tc.data_length DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with wide VARCHAR2 columns — variable-length keys reduce index density and cache hit ratio"}	{"width_threshold": 100}	2026-02-28 12:19:19.580455
8447	oracle	query	ora-index-charset-expansion: find indexes on VARCHAR2 columns with multi-byte potential	{"sql": "SELECT ic.index_owner, ic.index_name, ic.column_name, tc.data_type, tc.data_length, tc.char_length, tc.char_used FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COLUMNS tc ON tc.owner = ic.table_owner AND tc.table_name = ic.table_name AND tc.column_name = ic.column_name WHERE tc.data_type IN ('VARCHAR2', 'NVARCHAR2', 'CHAR', 'NCHAR') AND tc.data_length > 100 AND ic.index_owner NOT IN ('SYS', 'SYSTEM') ORDER BY tc.data_length DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes on wide character columns in multi-byte databases confirm expansion risk"}	\N	2026-02-28 12:19:19.580455
8448	oracle	query	ora-nullable-index-key: find indexes with nullable columns	{"sql": "SELECT ic.index_owner, ic.index_name, ic.column_name, ic.column_position, tc.nullable, tc.num_nulls, t.num_rows, ROUND(tc.num_nulls / NULLIF(t.num_rows, 0) * 100, 1) AS null_pct FROM ALL_IND_COLUMNS ic JOIN ALL_TAB_COLUMNS tc ON tc.owner = ic.table_owner AND tc.table_name = ic.table_name AND tc.column_name = ic.column_name JOIN ALL_TABLES t ON t.owner = ic.table_owner AND t.table_name = ic.table_name WHERE tc.nullable = 'Y' AND tc.num_nulls > 0 AND ic.index_owner NOT IN ('SYS', 'SYSTEM') AND t.num_rows > 1000 ORDER BY null_pct DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes with nullable columns - Oracle B-tree indexes exclude all-NULL rows"}	\N	2026-02-28 12:19:19.580455
8451	oracle	query	ora-redundant-index-col: find overlapping composite indexes	{"sql": "SELECT a.index_owner, a.index_name AS index1, b.index_name AS index2, a.table_name, COUNT(*) AS shared_leading_columns FROM ALL_IND_COLUMNS a JOIN ALL_IND_COLUMNS b ON b.table_owner = a.table_owner AND b.table_name = a.table_name AND b.column_name = a.column_name AND b.column_position = a.column_position AND b.index_name != a.index_name WHERE a.column_position <= 3 AND a.index_owner NOT IN ('SYS', 'SYSTEM') GROUP BY a.index_owner, a.index_name, b.index_name, a.table_name HAVING COUNT(*) >= 2 ORDER BY shared_leading_columns DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Indexes sharing leading columns indicate redundancy"}	\N	2026-02-28 12:19:19.580455
8864	oracle	query	ora_check_distinct_in_correlated_subquery	{"sql": "SELECT sql_id, SUBSTR(sql_text, 1, 300) AS sql_preview, executions, elapsed_time/1000000 AS elapsed_sec, buffer_gets FROM v$sql WHERE UPPER(sql_text) LIKE '%SELECT DISTINCT%' AND (UPPER(sql_text) LIKE '%EXISTS%' OR UPPER(sql_text) LIKE '% IN (SELECT%') AND elapsed_time / NULLIF(executions, 0) > :slow_threshold_us ORDER BY elapsed_time DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Slow queries with DISTINCT inside correlated subqueries indicate unnecessary sort operations"}	{"slow_threshold_us": 5000000}	2026-02-28 12:19:19.580455
8462	oracle	query	ora-fk-lock-contention: find unindexed foreign keys	{"sql": "SELECT c.owner, c.table_name, c.constraint_name, cc.column_name, c.r_constraint_name FROM ALL_CONSTRAINTS c JOIN ALL_CONS_COLUMNS cc ON cc.owner = c.owner AND cc.constraint_name = c.constraint_name WHERE c.constraint_type = 'R' AND c.owner NOT IN ('SYS', 'SYSTEM') AND NOT EXISTS (SELECT 1 FROM ALL_IND_COLUMNS ic WHERE ic.table_owner = c.owner AND ic.table_name = c.table_name AND ic.column_name = cc.column_name AND ic.column_position = 1) ORDER BY c.owner, c.table_name"}	{"condition": "row_count > 0", "description": "Unindexed foreign key columns cause table-level locks on child table during parent DML"}	\N	2026-02-28 12:19:19.580455
8517	oracle	query	ora_check_buffer_busy_waits	{"sql": "SELECT event, total_waits, time_waited_micro / 1000000 AS time_waited_secs FROM v$system_event WHERE event = 'buffer busy waits' AND total_waits > 1000"}	{"condition": "total_waits > min_waits", "description": "Buffer busy waits indicate contention on specific data or index blocks"}	{"min_waits": 1000}	2026-02-28 12:19:19.580455
8578	oracle	query	ora_check_maintenance_tasks_running	{"sql": "SELECT client_name, job_status, TO_CHAR(job_start_time, 'YYYY-MM-DD HH24:MI:SS') AS job_start_time, TO_CHAR(job_duration) AS job_duration, window_name FROM dba_autotask_job_history WHERE job_start_time > SYSDATE - 1 AND job_status IN ('RUNNING', 'FAILED', 'STOPPED') ORDER BY job_start_time DESC"}	{"condition": "row_count > 0", "description": "Active or failed auto-maintenance tasks may be blocking user operations"}	\N	2026-02-28 12:19:19.580455
8618	oracle	query	ora_check_hash_join_skew_in_workareas	{"sql": "SELECT wa.SQL_ID, wa.OPERATION_TYPE, wa.ACTUAL_MEM_USED / 1048576 AS actual_mb, wa.TEMPSEG_SIZE / 1048576 AS temp_mb FROM V$SQL_WORKAREA_ACTIVE wa WHERE wa.OPERATION_TYPE LIKE '%HASH%' ORDER BY wa.ACTUAL_MEM_USED DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Hash operations using significantly more memory than estimated — data skew likely"}	{"ratio_threshold": 3.0}	2026-02-28 12:19:19.580455
8627	oracle	query	ora_check_stale_table_statistics [PERF-SQL-MEM-002-RC14]	{"sql": "SELECT OWNER, TABLE_NAME, STALE_STATS, LAST_ANALYZED, NUM_ROWS, STATTYPE_LOCKED FROM DBA_TAB_STATISTICS WHERE STALE_STATS = 'YES' AND OWNER NOT IN ('SYS', 'SYSTEM', 'MDSYS', 'CTXSYS', 'XDB') AND NUM_ROWS > :min_rows ORDER BY NUM_ROWS DESC FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Tables with stale statistics — optimizer will misestimate cardinality and memory needs"}	{"min_rows": 10000}	2026-02-28 12:19:19.580455
8669	oracle	query	ora-check-wide-row-memory-usage	{"sql": "SELECT sql_id, ROUND(rows_processed/NULLIF(executions, 0)) AS rows_per_exec, ROUND(elapsed_time/1000000/NULLIF(executions, 0), 2) AS avg_sec FROM v$sql WHERE, 0) > :row_threshold ORDER BY,"}	{"condition": "row_count > 0", "description": "Queries processing many rows with high temp space confirm wide result sets exceeding PGA capacity"}	{"row_threshold": 10000, "temp_threshold": 104857600}	2026-02-28 12:19:19.580455
8670	oracle	query	ora-check-histogram-type-coverage	{"sql": "SELECT tc.owner, tc.table_name, tc.column_name, tc.num_distinct, tc.histogram, tc.num_buckets, t.num_rows FROM ALL_TAB_COL_STATISTICS tc JOIN ALL_TABLES t ON tc.owner = t.owner AND tc.table_name = t.table_name WHERE tc.owner NOT IN ('SYS', 'SYSTEM') AND tc.histogram IN ('HEIGHT BALANCED', 'HYBRID') AND tc.num_buckets < tc.num_distinct AND tc.num_distinct BETWEEN 255 AND :distinct_limit AND t.num_rows > :row_threshold ORDER BY tc.num_distinct DESC FETCH FIRST 10 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Height-balanced or hybrid histograms with fewer buckets than distinct values have coverage gaps for some value ranges"}	{"row_threshold": 10000, "distinct_limit": 10000}	2026-02-28 12:19:19.580455
