12178	informix	query	Detect expensive queries (informix)	{"sql": "SELECT FIRST 50 s.sid, s.username, s.hostname, s.progname, sq.sql_statement, sq.sql_totaltime / CASE WHEN sq.sql_executions = 0 THEN 1 ELSE sq.sql_executions END AS avg_time, sq.sql_totaltime, sq.sql_executions, sq.sql_rowsprocessed FROM sysmaster:syssqlstat sq JOIN sysmaster:syssessions s ON s.sid = sq.sql_sid WHERE sq.sql_executions > 0 ORDER BY avg_time DESC"}	{"condition": "row_count > 0", "description": "Returns the most expensive queries by average execution time from sysmaster:syssqlstat"}	\N	2026-04-10 05:38:44.839449
12179	informix	query	Detect high CPU sessions (informix)	{"sql": "SELECT s.sid, s.username, s.hostname, s.progname, s.connected AS connect_time, p.usr_cpu + p.sys_cpu AS total_cpu, p.num_reads + p.num_writes AS total_io FROM sysmaster:syssessions s JOIN sysmaster:syssesprof p ON s.sid = p.sid WHERE p.usr_cpu + p.sys_cpu > 0 ORDER BY total_cpu DESC"}	{"condition": "row_count > 0", "description": "Identifies sessions consuming the most CPU from sysmaster:syssesprof"}	\N	2026-04-10 05:38:44.839449
12180	informix	query	Detect buffer pool pressure (informix)	{"sql": "SELECT p.name AS counter_name, p.value FROM sysmaster:sysprofile p WHERE p.name IN ('bufreads', 'bufwrites', 'pagreads', 'pagwrites', 'bufwaits', 'flushes') ORDER BY p.name"}	{"condition": "row_count > 0", "description": "Returns buffer pool read/write counters and wait metrics from sysprofile"}	\N	2026-04-10 05:38:44.839449
12181	informix	query	Detect deadlocks (informix)	{"sql": "SELECT p.name, p.value FROM sysmaster:sysprofile p WHERE p.name IN ('deadlks', 'lktouts', 'lockwts', 'lockreqs') ORDER BY p.name"}	{"condition": "row_count > 0", "description": "Returns deadlock count, lock timeouts, lock waits, and lock requests from sysprofile"}	\N	2026-04-10 05:38:44.839449
12182	informix	query	Detect blocking sessions (informix)	{"sql": "SELECT lk.owner AS blocker_sid, lk.waiter AS blocked_sid, bs.username AS blocker_user, ws.username AS blocked_user, bs.progname AS blocker_prog, ws.progname AS blocked_prog, lk.dbsname, lk.tabname, lk.type AS lock_type FROM sysmaster:syslocks lk JOIN sysmaster:syssessions bs ON bs.sid = lk.owner JOIN sysmaster:syssessions ws ON ws.sid = lk.waiter WHERE lk.waiter > 0 ORDER BY lk.waiter"}	{"condition": "row_count > 0", "description": "Detects sessions blocked by other sessions via sysmaster:syslocks"}	\N	2026-04-10 05:38:44.839449
12183	informix	query	Detect long-running transactions (informix)	{"sql": "SELECT t.tx_id, t.tx_logbeg, t.tx_loguniq, s.sid, s.username, s.hostname, s.progname, DBINFO('utc_current') - t.tx_begtime AS duration_seconds FROM sysmaster:systrans t JOIN sysmaster:syssessions s ON s.sid = t.tx_owner WHERE t.tx_begtime > 0 ORDER BY duration_seconds DESC"}	{"condition": "row_count > 0", "description": "Returns active transactions sorted by duration from sysmaster:systrans"}	\N	2026-04-10 05:38:44.839449
12184	informix	query	Detect logical log status (informix)	{"sql": "SELECT number AS log_number, size, used, is_archived, is_backed_up, is_current, is_new FROM sysmaster:syslogfil ORDER BY number"}	{"condition": "row_count > 0", "description": "Returns logical log file status, usage, and backup state"}	\N	2026-04-10 05:38:44.839449
12185	informix	query	Detect chunk I/O stats (informix)	{"sql": "SELECT c.chknum, d.name AS dbspace_name, c.reads, c.writes, c.pagesread, c.pageswritten, c.readtime, c.writetime, CASE WHEN c.reads > 0 THEN c.readtime / c.reads ELSE 0 END AS avg_read_time, CASE WHEN c.writes > 0 THEN c.writetime / c.writes ELSE 0 END AS avg_write_time FROM sysmaster:syschkio c JOIN sysmaster:syschunks ch ON ch.chknum = c.chknum JOIN sysmaster:sysdbspaces d ON d.dbsnum = ch.dbsnum WHERE c.reads + c.writes > 0 ORDER BY avg_read_time DESC"}	{"condition": "row_count > 0", "description": "Returns per-chunk I/O latency from sysmaster:syschkio"}	\N	2026-04-10 05:38:44.839449
12186	informix	query	Detect connection count vs max (informix)	{"sql": "SELECT (SELECT COUNT(*) FROM sysmaster:syssessions WHERE sid > 0) AS current_sessions, (SELECT cf_effective FROM sysmaster:syscfgtab WHERE cf_name = 'NETTYPE') AS max_configured"}	{"condition": "row_count > 0", "description": "Returns current session count vs configured maximum"}	\N	2026-04-10 05:38:44.839449
12187	informix	query	Detect tables with sequential scans (informix)	{"sql": "SELECT t.dbsname, t.tabname, p.seqscans, p.totalrows, p.rowsread, CASE WHEN p.totalrows > 0 THEN ROUND(p.rowsread * 100.0 / p.totalrows, 2) ELSE 0 END AS scan_pct FROM sysmaster:sysptprof p JOIN sysmaster:systabnames t ON t.partnum = p.partnum WHERE p.seqscans > 100 AND p.totalrows > 1000 ORDER BY p.seqscans DESC"}	{"condition": "row_count > 0", "description": "Tables with high sequential scan counts likely need indexes"}	\N	2026-04-10 05:38:44.839449
12188	informix	query	Detect extent fragmentation (informix)	{"sql": "SELECT t.dbsname, t.tabname, COUNT(*) AS extent_count FROM sysmaster:sysextents e JOIN sysmaster:systabnames t ON t.partnum = e.pe_partnum GROUP BY t.dbsname, t.tabname HAVING COUNT(*) > 20 ORDER BY extent_count DESC"}	{"condition": "row_count > 0", "description": "Tables with many extents are fragmented and may have degraded I/O performance"}	\N	2026-04-10 05:38:44.839449
12189	informix	query	Detect tables with no statistics (informix)	{"sql": "SELECT t.dbsname, t.tabname, p.totalrows, p.ustlowts AS last_stats_time FROM sysmaster:sysptprof p JOIN sysmaster:systabnames t ON t.partnum = p.partnum WHERE p.ustlowts = 0 AND p.totalrows > 100 ORDER BY p.totalrows DESC"}	{"condition": "row_count > 0", "description": "Tables that have never had statistics updated will produce poor query plans"}	\N	2026-04-10 05:38:44.839449
12190	informix	query	Detect dbspace usage (informix)	{"sql": "SELECT d.name AS dbspace_name, d.nchunks, SUM(c.chksize) AS total_pages, SUM(c.nfree) AS free_pages, ROUND((1 - SUM(c.nfree) * 1.0 / NULLIF(SUM(c.chksize), 0)) * 100, 2) AS used_pct FROM sysmaster:sysdbspaces d JOIN sysmaster:syschunks c ON c.dbsnum = d.dbsnum GROUP BY d.name, d.nchunks HAVING ROUND((1 - SUM(c.nfree) * 1.0 / NULLIF(SUM(c.chksize), 0)) * 100, 2) > 80 ORDER BY used_pct DESC"}	{"condition": "row_count > 0", "description": "Dbspaces with usage above 80% are at risk of running out of space"}	\N	2026-04-10 05:38:44.839449
12191	informix	query	Detect default admin accounts (informix)	{"sql": "SELECT username, usertype FROM sysuser:sysusers WHERE username IN ('informix', 'root') AND usertype = 'D'"}	{"condition": "row_count > 0", "description": "Default Informix admin accounts (informix, root) still active with DBA privileges"}	\N	2026-04-10 05:38:44.839449
12192	informix	query	Detect audit configuration (informix)	{"sql": "SELECT adtmode, adtpath, adterr FROM sysmaster:sysadtinfo"}	{"condition": "row_count > 0", "description": "Checks if Informix audit (ADTMODE) is enabled and configured"}	\N	2026-04-10 05:38:44.839449
12193	informix	query	Detect SSL/TLS configuration (informix)	{"sql": "SELECT cf_name, cf_effective FROM sysmaster:syscfgtab WHERE cf_name IN ('USEOSTIME', 'IFX_FIPS_MODE', 'SSL_PROTOCOL', 'SECURITY_LOCALCONNECTION')"}	{"condition": "row_count > 0", "description": "Checks Informix SSL/TLS and security configuration parameters"}	\N	2026-04-10 05:38:44.839449
12194	informix	query	Detect Informix version (informix)	{"sql": "SELECT DBINFO('version', 'full') AS version_full, DBINFO('version', 'major') AS version_major, DBINFO('version', 'minor') AS version_minor, DBINFO('version', 'os') AS version_os FROM systables WHERE tabid = 1"}	{"condition": "row_count > 0", "description": "Returns the Informix server version for patch level assessment"}	\N	2026-04-10 05:38:44.839449
12195	informix	query	Detect users with DBA privilege (informix)	{"sql": "SELECT username, usertype FROM sysuser:sysusers WHERE usertype = 'D' ORDER BY username"}	{"condition": "row_count > 0", "description": "Lists all users with DBA (Database Administrator) privilege — potential over-provisioning"}	\N	2026-04-10 05:38:44.839449
14744	mariadb	query	Check for defined roles in MySQL	{"sql": "SELECT User, Host FROM mysql.user WHERE account_locked = 'Y' AND password_expired = 'Y' AND authentication_string = ''"}	{"condition": "row_count == 0", "description": "No roles defined in the system indicates RBAC is not implemented"}	\N	2026-05-11 22:17:39.229791
12196	informix	query	Detect dormant accounts (informix)	{"sql": "SELECT u.username, u.usertype FROM sysuser:sysusers u WHERE u.username NOT IN (SELECT DISTINCT username FROM sysmaster:syssessions) AND u.usertype IN ('D', 'R') ORDER BY u.username"}	{"condition": "row_count > 0", "description": "Users with DBA or RESOURCE privilege who have no active sessions may be dormant"}	\N	2026-04-10 05:38:44.839449
