12198	informix	query	Detect listening port (informix)	{"sql": "SELECT cf_name, cf_effective FROM sysmaster:syscfgtab WHERE cf_name IN ('NETTYPE', 'DBSERVERNAME', 'DBSERVERALIASES') ORDER BY cf_name"}	{"condition": "row_count > 0", "description": "Returns network configuration including listening interfaces"}	\N	2026-04-10 05:38:44.839449
12199	informix	query	Detect active sessions snapshot (informix)	{"sql": "SELECT s.sid, s.username, s.uid, s.hostname, s.progname, s.connected, s.pid FROM sysmaster:syssessions s WHERE s.sid > 0 ORDER BY s.sid"}	{"condition": "row_count > 0", "description": "Returns all active sessions for connection monitoring"}	\N	2026-04-10 05:38:44.839449
12200	informix	query	Detect active transactions snapshot (informix)	{"sql": "SELECT t.tx_id, t.tx_owner AS sid, s.username, s.hostname, s.progname, t.tx_logbeg, t.tx_loguniq, t.tx_flags FROM sysmaster:systrans t JOIN sysmaster:syssessions s ON s.sid = t.tx_owner ORDER BY t.tx_id"}	{"condition": "row_count > 0", "description": "Returns all active transactions for transaction monitoring"}	\N	2026-04-10 05:38:44.839449
12202	informix	query	Detect checkpoint stats (informix)	{"sql": "SELECT p.name, p.value FROM sysmaster:sysprofile p WHERE p.name IN ('numckpts', 'ckptwaits', 'fgwrites', 'lru_writes', 'chunk_writes') ORDER BY p.name"}	{"condition": "row_count > 0", "description": "Checkpoint and flush counters from sysprofile — high ckptwaits indicates checkpoint I/O pressure"}	\N	2026-04-10 05:38:44.839449
12204	oracle	query	Discover sensitive columns in schema (oracle)	{"sql": "SELECT owner AS schema_name, table_name, column_name, data_type, data_length, CASE WHEN LOWER(column_name) LIKE '%ssn%' OR LOWER(column_name) LIKE '%social_security%' THEN 'SSN' WHEN LOWER(column_name) LIKE '%credit_card%' OR LOWER(column_name) LIKE '%card_number%' OR LOWER(column_name) LIKE '%cvv%' THEN 'Credit Card' WHEN LOWER(column_name) LIKE '%password%' OR LOWER(column_name) LIKE '%passwd%' OR LOWER(column_name) LIKE '%secret%' OR LOWER(column_name) LIKE '%api_key%' THEN 'Credential' WHEN LOWER(column_name) LIKE '%email%' THEN 'Email' WHEN LOWER(column_name) LIKE '%phone%' OR LOWER(column_name) LIKE '%mobile%' THEN 'Phone' WHEN LOWER(column_name) LIKE '%birth%' OR LOWER(column_name) LIKE '%dob%' THEN 'Date of Birth' WHEN LOWER(column_name) LIKE '%salary%' OR LOWER(column_name) LIKE '%income%' THEN 'Financial' WHEN LOWER(column_name) LIKE '%bank_account%' OR LOWER(column_name) LIKE '%iban%' THEN 'Bank Account' WHEN LOWER(column_name) LIKE '%national_id%' OR LOWER(column_name) LIKE '%passport%' OR LOWER(column_name) LIKE '%tax_id%' THEN 'Government ID' WHEN LOWER(column_name) LIKE '%medical%' OR LOWER(column_name) LIKE '%diagnosis%' THEN 'Medical' ELSE 'Other Sensitive' END AS pii_category FROM all_tab_columns WHERE owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','MDSYS','ORDSYS','CTXSYS','XDB','WMSYS') AND (LOWER(column_name) LIKE '%ssn%' OR LOWER(column_name) LIKE '%social_security%' OR LOWER(column_name) LIKE '%credit_card%' OR LOWER(column_name) LIKE '%card_number%' OR LOWER(column_name) LIKE '%cvv%' OR LOWER(column_name) LIKE '%password%' OR LOWER(column_name) LIKE '%passwd%' OR LOWER(column_name) LIKE '%secret%' OR LOWER(column_name) LIKE '%api_key%' OR LOWER(column_name) LIKE '%email%' OR LOWER(column_name) LIKE '%phone%' OR LOWER(column_name) LIKE '%mobile%' OR LOWER(column_name) LIKE '%birth%' OR LOWER(column_name) LIKE '%dob%' OR LOWER(column_name) LIKE '%salary%' OR LOWER(column_name) LIKE '%income%' OR LOWER(column_name) LIKE '%bank_account%' OR LOWER(column_name) LIKE '%iban%' OR LOWER(column_name) LIKE '%national_id%' OR LOWER(column_name) LIKE '%passport%' OR LOWER(column_name) LIKE '%tax_id%' OR LOWER(column_name) LIKE '%medical%' OR LOWER(column_name) LIKE '%diagnosis%' OR LOWER(column_name) LIKE '%ip_address%' OR LOWER(column_name) LIKE '%biometric%') ORDER BY pii_category, owner, table_name"}	{"condition": "row_count > 0", "description": "Columns with names suggesting PII/sensitive data found in database schema"}	\N	2026-04-12 09:08:19.580332
12205	postgresql	query	Discover sensitive columns in schema (postgresql)	{"sql": "SELECT table_schema AS schema_name, table_name, column_name, data_type, character_maximum_length, CASE WHEN column_name ~ '(ssn|social_security)' THEN 'SSN' WHEN column_name ~ '(credit_card|card_number|cvv|cvc)' THEN 'Credit Card' WHEN column_name ~ '(password|passwd|secret|api_key|apikey)' THEN 'Credential' WHEN column_name ~ '(email|e_mail)' THEN 'Email' WHEN column_name ~ '(phone|mobile|cell)' THEN 'Phone' WHEN column_name ~ '(birth|dob|date_of_birth)' THEN 'Date of Birth' WHEN column_name ~ '(salary|income|wage)' THEN 'Financial' WHEN column_name ~ '(bank_account|iban|routing)' THEN 'Bank Account' WHEN column_name ~ '(national_id|passport|driver_license|tax_id|id_number)' THEN 'Government ID' WHEN column_name ~ '(medical|diagnosis|health)' THEN 'Medical' WHEN column_name ~ '(ip_address|mac_address|biometric)' THEN 'Technical PII' ELSE 'Other Sensitive' END AS pii_category FROM information_schema.columns WHERE table_schema NOT IN ('information_schema', 'pg_catalog', 'pg_toast') AND column_name ~ '(ssn|social_security|credit_card|card_number|cvv|cvc|password|passwd|secret|api_key|email|phone|mobile|birth|dob|salary|income|bank_account|iban|national_id|passport|driver_license|tax_id|medical|diagnosis|ip_address|biometric)' ORDER BY pii_category, table_schema, table_name"}	{"condition": "row_count > 0", "description": "Columns with names suggesting PII/sensitive data found in database schema"}	\N	2026-04-12 09:08:19.580332
12206	mysql	query	Discover sensitive columns in schema (mysql)	{"sql": "SELECT table_schema AS schema_name, table_name, column_name, data_type, character_maximum_length, CASE WHEN column_name LIKE '%ssn%' OR column_name LIKE '%social_security%' THEN 'SSN' WHEN column_name LIKE '%credit_card%' OR column_name LIKE '%card_number%' OR column_name LIKE '%cvv%' THEN 'Credit Card' WHEN column_name LIKE '%password%' OR column_name LIKE '%passwd%' OR column_name LIKE '%secret%' OR column_name LIKE '%api_key%' THEN 'Credential' WHEN column_name LIKE '%email%' THEN 'Email' WHEN column_name LIKE '%phone%' OR column_name LIKE '%mobile%' THEN 'Phone' WHEN column_name LIKE '%birth%' OR column_name LIKE '%dob%' THEN 'Date of Birth' WHEN column_name LIKE '%salary%' OR column_name LIKE '%income%' THEN 'Financial' WHEN column_name LIKE '%bank_account%' OR column_name LIKE '%iban%' THEN 'Bank Account' WHEN column_name LIKE '%national_id%' OR column_name LIKE '%passport%' OR column_name LIKE '%tax_id%' THEN 'Government ID' WHEN column_name LIKE '%medical%' OR column_name LIKE '%diagnosis%' THEN 'Medical' ELSE 'Other Sensitive' END AS pii_category FROM information_schema.columns WHERE table_schema NOT IN ('information_schema', 'mysql', 'performance_schema', 'sys') AND (column_name LIKE '%ssn%' OR column_name LIKE '%social_security%' OR column_name LIKE '%credit_card%' OR column_name LIKE '%card_number%' OR column_name LIKE '%cvv%' OR column_name LIKE '%password%' OR column_name LIKE '%passwd%' OR column_name LIKE '%secret%' OR column_name LIKE '%api_key%' OR column_name LIKE '%email%' OR column_name LIKE '%phone%' OR column_name LIKE '%mobile%' OR column_name LIKE '%birth%' OR column_name LIKE '%dob%' OR column_name LIKE '%salary%' OR column_name LIKE '%income%' OR column_name LIKE '%bank_account%' OR column_name LIKE '%iban%' OR column_name LIKE '%national_id%' OR column_name LIKE '%passport%' OR column_name LIKE '%tax_id%' OR column_name LIKE '%medical%' OR column_name LIKE '%diagnosis%' OR column_name LIKE '%ip_address%' OR column_name LIKE '%biometric%') ORDER BY pii_category, table_schema, table_name"}	{"condition": "row_count > 0", "description": "Columns with names suggesting PII/sensitive data found in database schema"}	\N	2026-04-12 09:08:19.580332
12207	sqlserver	query	Detect sensitive columns actively queried (sqlserver)	{"sql": "SELECT s.name AS schema_name, t.name AS table_name, c.name AS column_name, ius.user_seeks + ius.user_scans + ius.user_lookups AS total_reads, ius.last_user_seek, ius.last_user_scan, CASE WHEN c.name LIKE '%ssn%' OR c.name LIKE '%social_security%' THEN 'SSN' WHEN c.name LIKE '%credit_card%' OR c.name LIKE '%card_number%' OR c.name LIKE '%cvv%' THEN 'Credit Card' WHEN c.name LIKE '%password%' OR c.name LIKE '%passwd%' OR c.name LIKE '%secret%' OR c.name LIKE '%api_key%' THEN 'Credential' WHEN c.name LIKE '%email%' THEN 'Email' WHEN c.name LIKE '%phone%' OR c.name LIKE '%mobile%' THEN 'Phone' WHEN c.name LIKE '%salary%' OR c.name LIKE '%income%' THEN 'Financial' WHEN c.name LIKE '%bank_account%' OR c.name LIKE '%iban%' THEN 'Bank Account' WHEN c.name LIKE '%national_id%' OR c.name LIKE '%passport%' OR c.name LIKE '%tax_id%' THEN 'Government ID' WHEN c.name LIKE '%medical%' OR c.name LIKE '%diagnosis%' THEN 'Medical' ELSE 'Other Sensitive' END AS pii_category FROM sys.columns c JOIN sys.tables t ON t.object_id = c.object_id JOIN sys.schemas s ON s.schema_id = t.schema_id JOIN sys.dm_db_index_usage_stats ius ON ius.object_id = t.object_id AND ius.database_id = DB_ID() WHERE t.is_ms_shipped = 0 AND (ius.user_seeks + ius.user_scans + ius.user_lookups) > 0 AND (c.name LIKE '%ssn%' OR c.name LIKE '%credit_card%' OR c.name LIKE '%password%' OR c.name LIKE '%email%' OR c.name LIKE '%phone%' OR c.name LIKE '%salary%' OR c.name LIKE '%bank_account%' OR c.name LIKE '%national_id%' OR c.name LIKE '%passport%' OR c.name LIKE '%tax_id%' OR c.name LIKE '%medical%' OR c.name LIKE '%diagnosis%' OR c.name LIKE '%birth%' OR c.name LIKE '%dob%' OR c.name LIKE '%ip_address%' OR c.name LIKE '%biometric%' OR c.name LIKE '%secret%' OR c.name LIKE '%api_key%' OR c.name LIKE '%iban%' OR c.name LIKE '%income%') ORDER BY total_reads DESC"}	{"condition": "row_count > 0", "description": "Tables with sensitive columns are being actively read — PII data is in use"}	\N	2026-04-12 09:08:19.580332
13657	mariadb	query	Check for binary log not found errors	{"sql": "SELECT CHANNEL_NAME, SERVICE_STATE, LAST_ERROR_NUMBER, LAST_ERROR_MESSAGE, LAST_ERROR_TIMESTAMP FROM performance_schema.replication_connection_status WHERE LAST_ERROR_NUMBER IN (1236, 13114)"}	{"condition": "row_count > 0", "description": "Error 1236 (Could not find first log file) indicates binary logs were purged"}	\N	2026-05-11 22:17:39.229791
12208	oracle	query	Detect sensitive columns actively queried (oracle)	{"sql": "SELECT c.owner AS schema_name, c.table_name, c.column_name, s.num_rows, s.last_analyzed, CASE WHEN LOWER(c.column_name) LIKE '%ssn%' THEN 'SSN' WHEN LOWER(c.column_name) LIKE '%credit_card%' OR LOWER(c.column_name) LIKE '%card_number%' THEN 'Credit Card' WHEN LOWER(c.column_name) LIKE '%password%' OR LOWER(c.column_name) LIKE '%secret%' THEN 'Credential' WHEN LOWER(c.column_name) LIKE '%email%' THEN 'Email' WHEN LOWER(c.column_name) LIKE '%phone%' OR LOWER(c.column_name) LIKE '%mobile%' THEN 'Phone' WHEN LOWER(c.column_name) LIKE '%salary%' OR LOWER(c.column_name) LIKE '%income%' THEN 'Financial' WHEN LOWER(c.column_name) LIKE '%national_id%' OR LOWER(c.column_name) LIKE '%passport%' THEN 'Government ID' WHEN LOWER(c.column_name) LIKE '%medical%' OR LOWER(c.column_name) LIKE '%diagnosis%' THEN 'Medical' ELSE 'Other Sensitive' END AS pii_category FROM all_tab_columns c JOIN all_tables s ON s.owner = c.owner AND s.table_name = c.table_name WHERE c.owner NOT IN ('SYS','SYSTEM','DBSNMP','OUTLN','MDSYS','ORDSYS','CTXSYS','XDB') AND s.num_rows > 0 AND (LOWER(c.column_name) LIKE '%ssn%' OR LOWER(c.column_name) LIKE '%credit_card%' OR LOWER(c.column_name) LIKE '%password%' OR LOWER(c.column_name) LIKE '%email%' OR LOWER(c.column_name) LIKE '%phone%' OR LOWER(c.column_name) LIKE '%salary%' OR LOWER(c.column_name) LIKE '%bank_account%' OR LOWER(c.column_name) LIKE '%national_id%' OR LOWER(c.column_name) LIKE '%passport%' OR LOWER(c.column_name) LIKE '%tax_id%' OR LOWER(c.column_name) LIKE '%medical%' OR LOWER(c.column_name) LIKE '%diagnosis%' OR LOWER(c.column_name) LIKE '%birth%' OR LOWER(c.column_name) LIKE '%secret%' OR LOWER(c.column_name) LIKE '%api_key%' OR LOWER(c.column_name) LIKE '%iban%' OR LOWER(c.column_name) LIKE '%income%' OR LOWER(c.column_name) LIKE '%biometric%') ORDER BY s.num_rows DESC"}	{"condition": "row_count > 0", "description": "Tables with sensitive columns contain data and are in active use"}	\N	2026-04-12 09:08:19.580332
12218	oracle	query	Check whether session is outside maintenance window	{"sql": "SELECT s.USERNAME, q.SQL_TEXT, TO_CHAR(SYSDATE,'HH24') AS current_hour\\n     FROM V$SESSION s JOIN V$SQL q ON s.SQL_ID = q.SQL_ID\\n     WHERE s.STATUS = 'ACTIVE'\\n       AND q.COMMAND_TYPE IN (2,6,7,9)\\n       AND s.USERNAME IN (SELECT GRANTEE FROM DBA_ROLE_PRIVS WHERE GRANTED_ROLE = 'DBA')\\n       AND TO_NUMBER(TO_CHAR(SYSDATE,'HH24')) NOT BETWEEN 2 AND 5"}	{"condition": "row_count > 0", "description": "DBA DML outside 02:00-05:00 maintenance window"}	\N	2037-05-21 15:01:08.062236
