12238	sqlserver	query	Verify the account is a service account by checking its description or role membership	{"sql": "SELECT sp.name, sp.type_desc, sp.is_disabled,\\n            ISNULL(ep.value, 'No description') AS description\\n     FROM sys.server_principals sp\\n     LEFT JOIN sys.extended_properties ep ON ep.major_id = sp.principal_id AND ep.name = 'AccountType'\\n     WHERE sp.name LIKE '%svc%' OR sp.name LIKE '%service%' OR sp.name LIKE '%api%'"}	{"condition": "row_count > 0", "description": "Confirmed service accounts exist and show interactive sessions"}	\N	2037-05-21 15:01:08.062236
12239	mysql	query	Check processlist for service accounts using interactive clients	{"sql": "SELECT ID, USER, HOST, COMMAND, TIME, INFO\\n     FROM INFORMATION_SCHEMA.PROCESSLIST\\n     WHERE USER REGEXP '(svc|service|app|api|etl|batch|bot|daemon)'\\n       AND COMMAND != 'Sleep'\\n       AND HOST NOT REGEXP '^(10\\\\.|172\\\\.|192\\\\.168\\\\.)'"}	{"condition": "row_count > 0", "description": "Service account active from non-internal network address  -- possible interactive session"}	\N	2037-05-21 15:01:08.062236
12240	mysql	query	Check if account has only expected application-level privileges	{"sql": "SELECT GRANTEE, PRIVILEGE_TYPE, IS_GRANTABLE\\n     FROM INFORMATION_SCHEMA.USER_PRIVILEGES\\n     WHERE GRANTEE REGEXP '(svc|service|app|api)'\\n       AND PRIVILEGE_TYPE NOT IN ('SELECT','INSERT','UPDATE','DELETE','EXECUTE')"}	{"condition": "row_count > 0", "description": "Service account holds unexpected privilege types beyond standard application grants"}	\N	2037-05-21 15:01:08.062236
12241	oracle	query	Check V$SESSION for service accounts with interactive program names	{"sql": "SELECT USERNAME, PROGRAM, MACHINE, TERMINAL, LOGON_TIME, STATUS\\n     FROM V$SESSION\\n     WHERE (UPPER(PROGRAM) LIKE '%SQLPLUS%' OR UPPER(PROGRAM) LIKE '%SQLDEV%'\\n            OR UPPER(PROGRAM) LIKE '%TOAD%'  OR UPPER(PROGRAM) LIKE '%DBEAVER%')\\n       AND UPPER(USERNAME) LIKE ANY(ARRAY['%SVC%','%SERVICE%','%APP%','%API%','%ETL%'])"}	{"condition": "row_count > 0", "description": "Service account connected via interactive Oracle client tool"}	\N	2037-05-21 15:01:08.062236
12242	oracle	query	Verify account has application-only role assignments	{"sql": "SELECT GRANTEE, GRANTED_ROLE, ADMIN_OPTION, DEFAULT_ROLE\\n     FROM DBA_ROLE_PRIVS\\n     WHERE UPPER(GRANTEE) REGEXP_LIKE GRANTEE, '(SVC|SERVICE|APP|API|ETL)'\\n       AND GRANTED_ROLE NOT IN ('CONNECT','RESOURCE')"}	{"condition": "row_count > 0", "description": "Service account holds roles beyond CONNECT/RESOURCE  -- privilege misuse risk"}	\N	2037-05-21 15:01:08.062236
12243	postgresql	query	Check active sessions for privilege-elevating commands	{"sql": "SELECT pid, usename, query, query_start, client_addr\\n     FROM pg_stat_activity\\n     WHERE state = 'active'\\n       AND query ~* '^\\\\s*(GRANT|SET\\\\s+ROLE|CREATE\\\\s+ROLE|ALTER\\\\s+ROLE|SECURITY\\\\s+DEFINER)'"}	{"condition": "row_count > 0", "description": "Active session executing privilege-escalation command"}	\N	2037-05-21 15:01:08.062236
12244	postgresql	query	Check if the account had lower privileges at login vs current effective role	{"sql": "SELECT pid, usename, query\\n     FROM pg_stat_activity\\n     WHERE query ~* 'SET\\\\s+ROLE\\\\s+\\\\w+'\\n       AND usename NOT IN (SELECT rolname FROM pg_roles WHERE rolsuper = true)"}	{"condition": "row_count > 0", "description": "Non-superuser account switching roles mid-session  -- escalation pattern detected"}	\N	2037-05-21 15:01:08.062236
12245	sqlserver	query	Check running requests for EXECUTE AS or GRANT statements	{"sql": "SELECT s.login_name, s.original_login_name, t.text, r.start_time\\n     FROM sys.dm_exec_sessions s\\n     JOIN sys.dm_exec_requests r ON s.session_id = r.session_id\\n     CROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\n     WHERE t.text LIKE '%EXECUTE AS%'\\n        OR t.text LIKE '%GRANT%SERVER ROLE%'\\n        OR t.text LIKE '%ALTER SERVER ROLE%'"}	{"condition": "row_count > 0", "description": "Session executing impersonation or server-role grant command"}	\N	2037-05-21 15:01:08.062236
12246	sqlserver	query	Compare original_login_name vs login_name for impersonation gap	{"sql": "SELECT session_id, login_name, original_login_name, status\\n     FROM sys.dm_exec_sessions\\n     WHERE login_name != original_login_name\\n       AND is_user_process = 1"}	{"condition": "row_count > 0", "description": "Impersonation active  -- login_name differs from original_login_name"}	\N	2037-05-21 15:01:08.062236
12247	mysql	query	Check PROCESSLIST for active GRANT or privilege-changing statements	{"sql": "SELECT ID, USER, HOST, DB, TIME, INFO\\n     FROM INFORMATION_SCHEMA.PROCESSLIST\\n     WHERE COMMAND = 'Query'\\n       AND (INFO LIKE '%GRANT %' OR INFO LIKE '%SET ROLE%'\\n            OR INFO LIKE '%CREATE USER%' OR INFO LIKE '%ALTER USER%')"}	{"condition": "row_count > 0", "description": "Active session issuing privilege-granting or role-change command"}	\N	2037-05-21 15:01:08.062236
12248	mysql	query	Check if the issuing account itself lacks GRANT OPTION	{"sql": "SELECT GRANTEE, PRIVILEGE_TYPE, IS_GRANTABLE\\n     FROM INFORMATION_SCHEMA.USER_PRIVILEGES\\n     WHERE GRANTEE IN (\\n         SELECT CONCAT('''',USER,'''','@',''',HOST,'''')\\n         FROM INFORMATION_SCHEMA.PROCESSLIST\\n         WHERE INFO LIKE '%GRANT %'\\n     )\\n     AND IS_GRANTABLE = 'NO'"}	{"condition": "row_count > 0", "description": "Account issuing GRANT does not hold GRANT OPTION  -- unauthorized escalation attempt"}	\N	2037-05-21 15:01:08.062236
12249	oracle	query	Check V$SQL for recent GRANT or ALTER SESSION SET ROLE statements	{"sql": "SELECT s.USERNAME, q.SQL_TEXT, s.LOGON_TIME, s.STATUS\\n     FROM V$SESSION s JOIN V$SQL q ON s.SQL_ID = q.SQL_ID\\n     WHERE (UPPER(q.SQL_TEXT) LIKE '%GRANT %'\\n            OR UPPER(q.SQL_TEXT) LIKE '%ALTER SESSION SET ROLE%'\\n            OR UPPER(q.SQL_TEXT) LIKE '%DBMS_PRIVILEGE_CAPTURE%')"}	{"condition": "row_count > 0", "description": "Session executing GRANT or SET ROLE mid-connection"}	\N	2037-05-21 15:01:08.062236
