12252	postgresql	query	Check if the source IP also falls outside approved CIDR ranges	{"sql": "SELECT pid, usename, application_name, client_addr\\n     FROM pg_stat_activity\\n     WHERE application_name NOT IN ('app_main','app_reporting','etl_service','monitoring')\\n       AND client_addr IS NOT NULL\\n       AND NOT (client_addr << '10.0.0.0/8'::inet\\n             OR client_addr << '172.16.0.0/12'::inet\\n             OR client_addr << '192.168.0.0/16'::inet)"}	{"condition": "row_count > 0", "description": "Unregistered app connecting from external IP  -- high-confidence unknown source"}	\N	2037-05-21 15:01:08.062236
12253	sqlserver	query	Check program_name against approved registry	{"sql": "SELECT s.session_id, s.login_name, s.program_name, s.host_name, s.client_interface_name\\n     FROM sys.dm_exec_sessions s\\n     WHERE s.is_user_process = 1\\n       AND s.program_name NOT IN (\\n           'AppMain','ReportingService','ETLAgent','SqlAgent',\\n           'Microsoft SQL Server Management Studio - Query', -- remove in prod\\n           '.Net SqlClient Data Provider'\\n       )\\n       AND s.program_name NOT LIKE '%SQLAgent%'"}	{"condition": "row_count > 0", "description": "Active session from unregistered program_name"}	\N	2037-05-21 15:01:08.062236
12254	sqlserver	query	Correlate host_name with approved server inventory	{"sql": "SELECT s.host_name, COUNT(*) AS session_count\\n     FROM sys.dm_exec_sessions s\\n     WHERE s.is_user_process = 1\\n       AND s.program_name NOT IN ('AppMain','ReportingService','ETLAgent')\\n     GROUP BY s.host_name"}	{"condition": "row_count > 0", "description": "Unregistered application sessions grouped by host  -- identify rogue source"}	\N	2037-05-21 15:01:08.062236
12255	mysql	query	Check performance_schema.accounts for unknown programs	{"sql": "SELECT pa.USER, pa.HOST, pa.CURRENT_CONNECTIONS, pa.TOTAL_CONNECTIONS\\n     FROM performance_schema.accounts pa\\n     WHERE pa.HOST NOT REGEXP '^(10\\\\.|172\\\\.(1[6-9]|2[0-9]|3[01])\\\\.|192\\\\.168\\\\.)'\\n       AND pa.USER NOT IN ('replication','monitoring','backup','root')\\n       AND pa.CURRENT_CONNECTIONS > 0"}	{"condition": "row_count > 0", "description": "Active connections from hosts outside approved internal ranges"}	\N	2037-05-21 15:01:08.062236
