12258	oracle	query	Check CLIENT_INFO for additional application registration data	{"sql": "SELECT USERNAME, CLIENT_INFO, MACHINE, COUNT(*) AS sessions\\n     FROM V$SESSION\\n     WHERE TYPE = 'USER' AND CLIENT_INFO IS NULL AND STATUS = 'ACTIVE'\\n     GROUP BY USERNAME, CLIENT_INFO, MACHINE"}	{"condition": "row_count > 0", "description": "Sessions with no CLIENT_INFO registration suggest rogue or unregistered tool"}	\N	2037-05-21 15:01:08.062236
12259	postgresql	query	Check for queries with unusual table-join depth or column count	{"sql": "SELECT query, calls, total_exec_time, rows, userid::regrole AS username\\n     FROM pg_stat_statements\\n     WHERE (SELECT COUNT(*) FROM REGEXP_MATCHES(query, 'JOIN', 'gi')) > 6\\n        OR query ~* 'UNION\\\\s+ALL'\\n        OR query ~* 'INTO\\\\s+OUTFILE'\\n        OR query ~* 'COPY\\\\s+.+\\\\s+TO'\\n     ORDER BY total_exec_time DESC\\n     LIMIT 20"}	{"condition": "row_count > 0", "description": "Query with unusual JOIN depth, UNION ALL, or file-copy pattern detected"}	\N	2037-05-21 15:01:08.062236
12260	postgresql	query	Check for never-seen-before query fingerprints (new queryid)	{"sql": "SELECT queryid, query, calls, userid::regrole\\n     FROM pg_stat_statements\\n     WHERE calls = 1\\n       AND query !~* '^\\\\s*(BEGIN|COMMIT|ROLLBACK|SET|SHOW|EXPLAIN)'\\n       AND LENGTH(query) > 200\\n     ORDER BY total_exec_time DESC\\n     LIMIT 20"}	{"condition": "row_count > 0", "description": "Single-execution long queries with new queryid  -- potential manually crafted SQL"}	\N	2037-05-21 15:01:08.062236
12261	sqlserver	query	Check Query Store for single-execution anomalous plans	{"sql": "SELECT qt.query_sql_text, rs.count_executions, rs.avg_duration, qp.query_plan\\n     FROM sys.query_store_query_text qt\\n     JOIN sys.query_store_query q ON q.query_text_id = qt.query_text_id\\n     JOIN sys.query_store_plan qp ON qp.query_id = q.query_id\\n     JOIN sys.query_store_runtime_stats rs ON rs.plan_id = qp.plan_id\\n     WHERE rs.count_executions = 1\\n       AND rs.avg_duration > 10000000\\n       AND qt.query_sql_text NOT LIKE '%sys.%'\\n     ORDER BY rs.avg_duration DESC"}	{"condition": "row_count > 0", "description": "Single-execution long-running query with no historical baseline"}	\N	2037-05-21 15:01:08.062236
12332	postgresql	query	Check pg_stat_statements for recurring tautology digest	{"sql": "SELECT query, calls, userid::regrole AS username\\n   FROM pg_stat_statements\\n   WHERE query ~* 'OR\\\\s+1\\\\s*=\\\\s*1' OR query ~* 'OR\\\\s+true'\\n   ORDER BY calls DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Tautology pattern in statement history — not a one-off"}	\N	2037-05-21 15:01:55.837417
12262	sqlserver	query	Scan plan cache for queries with unusually high logical reads	{"sql": "SELECT TOP 20 st.text, qs.execution_count, qs.total_logical_reads / qs.execution_count AS avg_reads\\n     FROM sys.dm_exec_query_stats qs\\n     CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\n     WHERE qs.execution_count = 1\\n       AND qs.total_logical_reads > 100000\\n     ORDER BY avg_reads DESC"}	{"condition": "row_count > 0", "description": "New query with extreme logical read count  -- unknown/anomalous pattern"}	\N	2037-05-21 15:01:08.062236
12263	mysql	query	Check statement history for high-scan full-table queries	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, AVG_TIMER_WAIT/1000000000 AS avg_ms,\\n            SUM_ROWS_EXAMINED, SUM_ROWS_SENT\\n     FROM performance_schema.events_statements_summary_by_digest\\n     WHERE COUNT_STAR = 1\\n       AND SUM_ROWS_EXAMINED > 1000000\\n       AND DIGEST_TEXT NOT LIKE '%information_schema%'\\n     ORDER BY SUM_ROWS_EXAMINED DESC\\n     LIMIT 20"}	{"condition": "row_count > 0", "description": "Single-execution query scanning >1M rows  -- anomalous pattern"}	\N	2037-05-21 15:01:08.062236
12264	mysql	query	Check for queries with UNION or multi-table joins not in baseline digest list	{"sql": "SELECT DIGEST, DIGEST_TEXT, COUNT_STAR\\n     FROM performance_schema.events_statements_summary_by_digest\\n     WHERE (DIGEST_TEXT LIKE '%UNION%' OR DIGEST_TEXT LIKE '%JOIN%JOIN%JOIN%')\\n       AND COUNT_STAR < 3\\n       AND LAST_SEEN > NOW() - INTERVAL 1 HOUR\\n     ORDER BY LAST_SEEN DESC"}	{"condition": "row_count > 0", "description": "Recent complex UNION or deep-join query with near-zero historical frequency"}	\N	2037-05-21 15:01:08.062236
12265	oracle	query	Check V$SQL for single-execution queries with high buffer gets	{"sql": "SELECT SQL_ID, SQL_TEXT, EXECUTIONS, BUFFER_GETS, DISK_READS,\\n            FIRST_LOAD_TIME, LAST_ACTIVE_TIME\\n     FROM V$SQL\\n     WHERE EXECUTIONS = 1\\n       AND BUFFER_GETS > 100000\\n       AND PARSING_USER_ID NOT IN (SELECT USER_ID FROM DBA_USERS WHERE USERNAME IN ('SYS','SYSTEM'))\\n     ORDER BY BUFFER_GETS DESC\\n     FETCH FIRST 20 ROWS ONLY"}	{"condition": "row_count > 0", "description": "Single-execution query with unusually high buffer gets  -- not in baseline"}	\N	2037-05-21 15:01:08.062236
12266	oracle	query	Compare SQL_ID against AWR baseline SQL summary	{"sql": "SELECT sql_id, elapsed_time_total, executions_total, buffer_gets_total\\n     FROM DBA_HIST_SQLSTAT\\n     WHERE snap_id IN (SELECT snap_id FROM DBA_HIST_SNAPSHOT WHERE BEGIN_INTERVAL_TIME > SYSDATE-1)\\n     MINUS\\n     SELECT sql_id, elapsed_time_total, executions_total, buffer_gets_total\\n     FROM DBA_HIST_SQLSTAT\\n     WHERE snap_id IN (SELECT snap_id FROM DBA_HIST_SNAPSHOT WHERE BEGIN_INTERVAL_TIME BETWEEN SYSDATE-7 AND SYSDATE-1)"}	{"condition": "row_count > 0", "description": "SQL IDs present in last 24h not seen in prior 7-day baseline  -- new unknown queries"}	\N	2037-05-21 15:01:08.062236
12267	postgresql	query	Check pg_stat_activity for external IP connections	{"sql": "SELECT pid, usename, application_name, client_addr, client_hostname, state\\n     FROM pg_stat_activity\\n     WHERE client_addr IS NOT NULL\\n       AND NOT (client_addr << '10.0.0.0/8'::inet\\n             OR client_addr << '172.16.0.0/12'::inet\\n             OR client_addr << '192.168.0.0/16'::inet\\n             OR client_addr = '127.0.0.1'::inet)"}	{"condition": "row_count > 0", "description": "Active session from IP outside approved private ranges"}	\N	2037-05-21 15:01:08.062236
