12276	postgresql	query	Check whether account has any automated/scheduled job association	{"sql": "SELECT rolname, rolcanlogin, rolvaliduntil, pg_catalog.shobj_description(oid, 'pg_authid') AS comment\\n     FROM pg_roles\\n     WHERE rolname IN (\\n         SELECT usename FROM pg_stat_activity\\n         WHERE state != 'idle'\\n           AND EXTRACT(HOUR FROM NOW() AT TIME ZONE 'UTC') NOT BETWEEN 6 AND 20\\n     )"}	{"condition": "row_count > 0", "description": "Account metadata does not indicate a scheduled/service role  -- off-hours access suspicious"}	\N	2037-05-21 15:01:08.062236
12277	sqlserver	query	Check dm_exec_sessions for human accounts outside business hours	{"sql": "SELECT login_name, program_name, host_name, login_time, status,\\n            DATEPART(HOUR, GETUTCDATE()) AS utc_hour\\n     FROM sys.dm_exec_sessions\\n     WHERE is_user_process = 1\\n       AND login_name NOT LIKE '%svc%' AND login_name NOT LIKE '%service%'\\n         AND login_name NOT LIKE '%agent%' AND login_name NOT LIKE 'NT %'\\n       AND DATEPART(HOUR, GETUTCDATE()) NOT BETWEEN 6 AND 20"}	{"condition": "row_count > 0", "description": "Human account active outside 06:00-20:00 UTC"}	\N	2037-05-21 15:01:08.062236
12278	sqlserver	query	Verify login has no SQL Agent job scheduled at this hour	{"sql": "SELECT j.name AS job_name, s.name AS schedule_name, s.active_start_time, s.active_end_time\\n     FROM msdb.dbo.sysjobs j\\n     JOIN msdb.dbo.sysjobschedules js ON js.job_id = j.job_id\\n     JOIN msdb.dbo.sysschedules s ON s.schedule_id = js.schedule_id\\n     WHERE j.enabled = 1\\n       AND s.active_start_time / 10000 NOT BETWEEN 6 AND 20"}	{"condition": "row_count = 0", "description": "No scheduled jobs at this hour  -- off-hours activity is not automated"}	\N	2037-05-21 15:01:08.062236
12279	mysql	query	Check processlist hour for non-service accounts	{"sql": "SELECT ID, USER, HOST, DB, COMMAND, TIME, INFO,\\n            HOUR(UTC_TIMESTAMP()) AS utc_hour\\n     FROM INFORMATION_SCHEMA.PROCESSLIST\\n     WHERE USER NOT REGEXP '(svc|service|app|etl|batch|monitor|backup|replication)'\\n       AND COMMAND != 'Sleep'\\n       AND HOUR(UTC_TIMESTAMP()) NOT BETWEEN 6 AND 20"}	{"condition": "row_count > 0", "description": "Human-type account executing queries outside business hours"}	\N	2037-05-21 15:01:08.062236
12280	mysql	query	Check account event scheduler or scheduled event association	{"sql": "SELECT EVENT_SCHEMA, EVENT_NAME, STATUS, EXECUTE_AT, INTERVAL_VALUE, INTERVAL_FIELD, DEFINER\\n     FROM INFORMATION_SCHEMA.EVENTS\\n     WHERE STATUS = 'ENABLED'\\n       AND DEFINER IN (\\n           SELECT CONCAT(USER,'@',SUBSTRING_INDEX(HOST,':',1))\\n           FROM INFORMATION_SCHEMA.PROCESSLIST\\n           WHERE HOUR(UTC_TIMESTAMP()) NOT BETWEEN 6 AND 20\\n       )"}	{"condition": "row_count = 0", "description": "No scheduled events for this account at this hour  -- off-hours access unplanned"}	\N	2037-05-21 15:01:08.062236
