12599	postgresql	query	Find sessions holding exclusive locks on large tables	{"sql": "SELECT l.pid, a.usename, c.relname, c.reltuples::bigint AS est_rows,\\n          l.mode, now() - a.query_start AS lock_age\\n   FROM pg_locks l\\n   JOIN pg_class c ON c.oid = l.relation\\n   JOIN pg_stat_activity a ON a.pid = l.pid\\n   WHERE l.granted\\n     AND l.mode IN ('ExclusiveLock','AccessExclusiveLock','RowExclusiveLock')\\n     AND c.reltuples > 100000\\n     AND now() - a.query_start > interval '10 minutes'\\n   ORDER BY c.reltuples DESC"}	{"condition": "row_count > 0", "description": "Session holds exclusive lock on large table for over 10 minutes  -- potential lock abuse"}	\N	2037-05-21 15:06:06.772318
12600	postgresql	query	Count sessions blocked by the lock holder	{"sql": "SELECT count(*) AS blocked_count\\n   FROM pg_stat_activity\\n   WHERE wait_event_type = 'Lock'"}	{"condition": "row_count > 0", "description": "Blocked sessions downstream of lock holder  -- exclusive lock causing active contention"}	\N	2037-05-21 15:06:06.772318
12601	sqlserver	query	Find extended exclusive locks on large tables	{"sql": "SELECT tl.request_session_id AS spid, s.login_name,\\n          OBJECT_NAME(tl.resource_associated_entity_id) AS table_name,\\n          p.rows AS est_rows, tl.request_mode, tl.request_status,\\n          DATEDIFF(minute, s.last_request_start_time, GETDATE()) AS lock_minutes\\n   FROM sys.dm_tran_locks tl\\n   JOIN sys.dm_exec_sessions s ON s.session_id = tl.request_session_id\\n   JOIN sys.partitions p ON p.object_id = tl.resource_associated_entity_id\\n   WHERE tl.resource_type = 'OBJECT'\\n     AND tl.request_mode IN ('X','SCH-M')\\n     AND p.rows > 100000\\n     AND DATEDIFF(minute, s.last_request_start_time, GETDATE()) > 10"}	{"condition": "row_count > 0", "description": "Exclusive lock held on large table for over 10 minutes  -- lock abuse pattern"}	\N	2037-05-21 15:06:06.772318
