2231	sqlserver	query	Check for queries with scalar UDF calls or implicit conversions in plans	{"sql": "SELECT TOP 10\\n  qs.sql_handle,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  p.query_plan.value('count(//UserDefinedFunction)', 'int') AS udf_count,\\n  p.query_plan.value('count(//Warnings/PlanAffectingConvert)', 'int') AS convert_warnings,\\n  p.query_plan.value('count(//NestedLoops)', 'int') AS nested_loop_count,\\n  LEFT(REPLACE(REPLACE(REPLACE(t.text, NCHAR(0), N''), CHAR(13), N' '), CHAR(10), N' '), 4000) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_worker_time / NULLIF(qs.execution_count, 0) > 1000000\\nORDER BY qs.total_worker_time DESC"}	{"condition": "udf_count > 0 OR convert_warnings > 0 OR nested_loop_count > 5", "description": "Scalar UDFs, implicit conversions, or excessive nested loops indicate poor query design patterns"}	null	2026-02-23 20:18:31.390245
2235	sqlserver	query	Check for plans with estimation warnings indicating join order issues	{"sql": "SELECT TOP 10\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.last_rows AS actual_rows,\\n  qs.last_elapsed_time / 1000 AS last_elapsed_ms,\\n  p.query_plan.value('count(//Warnings/SpillToTempDb)', 'int') AS spill_warnings,\\n  p.query_plan.value('count(//Warnings[@CardinalityEstimationModelVersion])', 'int') AS ce_warnings,\\n  p.query_plan.value('(//RelOp/@EstimateRows)[1]', 'float') AS first_op_estimated_rows,\\n  LEFT(REPLACE(REPLACE(REPLACE(t.text, NCHAR(0), N''), CHAR(13), N' '), CHAR(10), N' '), 4000) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 100000\\n  AND (p.query_plan.exist('//Warnings/SpillToTempDb') = 1\\n    OR p.query_plan.exist('//Warnings') = 1)\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "spill_warnings > 0 OR ce_warnings > 0", "description": "Spill warnings or CE model warnings in multi-join plans confirm suboptimal join ordering due to estimation errors"}	null	2026-02-23 20:18:31.390248
2234	sqlserver	query	Check for expensive multi-join queries with cardinality estimation warnings	{"sql": "SELECT TOP 15\\n  qs.sql_handle, qs.plan_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_cpu_ms,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.total_rows / NULLIF(qs.execution_count, 0) AS avg_rows,\\n  p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\" or @PhysicalOp=\\"Merge Join\\" or @PhysicalOp=\\"Nested Loops\\"])', 'int') AS join_count,\\n  LEFT(REPLACE(REPLACE(REPLACE(t.text, NCHAR(0), N''), CHAR(13), N' '), CHAR(10), N' '), 4000) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) p\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 100000\\n  AND p.query_plan.value('count(//RelOp[@PhysicalOp=\\"Hash Match\\" or @PhysicalOp=\\"Merge Join\\" or @PhysicalOp=\\"Nested Loops\\"])', 'int') >= 3\\nORDER BY avg_reads DESC"}	{"condition": "row_count > 0 AND join_count >= 3 AND avg_reads > 100000", "description": "Multi-join queries with high logical reads indicate possible suboptimal join ordering"}	null	2026-02-23 20:18:31.390247
11191	mysql	query	Check for SELECT * and full join patterns	{"sql": "SELECT\\n    t.TABLE_SCHEMA,\\n    t.TABLE_NAME,\\n    s.COLUMN_NAME,\\n    s.CARDINALITY,\\n    t.TABLE_ROWS,\\n    ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) AS selectivity_pct\\nFROM information_schema.STATISTICS s\\nJOIN information_schema.TABLES t\\n  ON s.TABLE_SCHEMA = t.TABLE_SCHEMA\\n AND s.TABLE_NAME   = t.TABLE_NAME\\nWHERE t.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys')\\n  AND t.TABLE_ROWS > 10000\\n  AND s.SEQ_IN_INDEX = 1\\n  AND ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) < 5\\nORDER BY t.TABLE_ROWS DESC\\nLIMIT 30"}	{"condition": "row_count > 0", "description": "Queries with full joins (no index on join column) confirm poor query design"}	\N	2026-03-01 06:30:58.706791
11192	mysql	query	Find queries with high row examination and multiple table joins	{"sql": "SELECT\\n    t.TABLE_SCHEMA,\\n    t.TABLE_NAME,\\n    s.COLUMN_NAME,\\n    s.CARDINALITY,\\n    t.TABLE_ROWS,\\n    ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) AS selectivity_pct\\nFROM information_schema.STATISTICS s\\nJOIN information_schema.TABLES t\\n  ON s.TABLE_SCHEMA = t.TABLE_SCHEMA\\n AND s.TABLE_NAME   = t.TABLE_NAME\\nWHERE t.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys')\\n  AND t.TABLE_ROWS > 10000\\n  AND s.SEQ_IN_INDEX = 1\\n  AND ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) < 5\\nORDER BY t.TABLE_ROWS DESC\\nLIMIT 30"}	{"condition": "row_count > 0", "description": "Join queries examining many rows with full join scans suggest suboptimal join order"}	{"min_rows": 100000}	2026-03-01 06:30:58.706791
2247	sqlserver	query	Check compilation resource consumption	{"sql": "SELECT\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Compilations/sec' AND object_name LIKE '%SQL Statistics%') AS compilations_sec,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'SQL Re-Compilations/sec' AND object_name LIKE '%SQL Statistics%') AS recompilations_sec,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans\\n   WHERE cacheobjtype = 'Compiled Plan' AND usecounts = 1) AS single_use_plans,\\n  (SELECT COUNT(*) FROM sys.dm_exec_cached_plans\\n   WHERE cacheobjtype = 'Compiled Plan') AS total_cached_plans,\\n  (SELECT SUM(CAST(size_in_bytes AS BIGINT)) / 1024 / 1024 FROM sys.dm_exec_cached_plans) AS plan_cache_mb"}	{"condition": "single_use_plans > total_cached_plans * 0.5 OR recompilations_sec > compilations_sec * 0.1", "description": "High single-use plan ratio or frequent recompilations suggest complex ad-hoc queries overwhelming the optimizer"}	null	2026-02-23 20:18:31.390255
