2337	sqlserver	query	Verify scan operators in execution plans for LIKE queries	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  LEFT(REPLACE(REPLACE(REPLACE(SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1), NCHAR(0), N''), CHAR(13), N' '), CHAR(10), N' '), 4000) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) LIKE '%LIKE ''[%]%'\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "scan_count > 0 AND like_predicate_count > 0", "description": "Execution plans with scan operators and LIKE predicates confirm leading wildcards preventing index seeks"}	null	2026-02-23 20:18:31.390315
2336	sqlserver	query	Check plan cache for queries with table scans and high logical reads	{"sql": "SELECT TOP 20\\n  qs.sql_handle,\\n  qs.total_logical_reads / NULLIF(qs.execution_count, 0) AS avg_reads,\\n  qs.total_elapsed_time / NULLIF(qs.execution_count, 0) / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  LEFT(REPLACE(REPLACE(REPLACE(SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1), NCHAR(0), N''), CHAR(13), N' '), CHAR(10), N' '), 4000) AS query_text\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) t\\nWHERE qs.total_logical_reads / NULLIF(qs.execution_count, 0) > 10000\\n  AND SUBSTRING(t.text, (qs.statement_start_offset / 2) + 1,\\n    (CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(t.text)\\n     ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2 + 1) LIKE '%LIKE ''[%]%'\\nORDER BY qs.total_logical_reads DESC"}	{"condition": "row_count > 0 AND avg_reads > 10000", "description": "Expensive queries containing LIKE with leading wildcard patterns"}	null	2026-02-23 20:18:31.390315
2373	sqlserver	query	Check for parameterized plans with sniffed values visible in plan XML	{"sql": "SELECT TOP 20 qs.query_hash, COUNT(DISTINCT qs.plan_handle) AS plan_count, SUM(qs.execution_count) AS total_execs, MIN(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS min_avg_reads, MAX(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS max_avg_reads, LEFT(REPLACE(REPLACE(REPLACE(SUBSTRING(MIN(st.text), 1, 200), NCHAR(0), N''), CHAR(13), N' '), CHAR(10), N' '), 200) AS sample_query FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st GROUP BY qs.query_hash HAVING COUNT(DISTINCT qs.plan_handle) > 1 AND MAX(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) > MIN(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) * 5 ORDER BY plan_count DESC"}	{"condition": "param_count > 0 AND (sniffed_value_1 <> runtime_value_1 OR avg_spills > 0)", "description": "Parameterized plans with compiled values differing from runtime values or spills confirm parameter sniffing"}	null	2026-02-23 20:18:31.390341
2372	sqlserver	query	Check for stored procedures with high variance in execution times	{"sql": "SELECT TOP 20 qs.query_hash, COUNT(DISTINCT qs.plan_handle) AS plan_count, SUM(qs.execution_count) AS total_execs, MIN(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS min_avg_reads, MAX(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) AS max_avg_reads, LEFT(REPLACE(REPLACE(REPLACE(SUBSTRING(MIN(st.text), 1, 200), NCHAR(0), N''), CHAR(13), N' '), CHAR(10), N' '), 200) AS sample_query FROM sys.dm_exec_query_stats qs CROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st GROUP BY qs.query_hash HAVING COUNT(DISTINCT qs.plan_handle) > 1 AND MAX(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) > MIN(qs.total_logical_reads / NULLIF(qs.execution_count, 0)) * 5 ORDER BY plan_count DESC"}	{"condition": "row_count > 0 AND time_variance_ratio > 10", "description": "Queries where max execution time exceeds min by 10x+ indicate parameter-sensitive plans"}	null	2026-02-23 20:18:31.39034
