13124	mariadb	query	Find long-sleeping sessions	{"sql": "SELECT id, user, host, db, command, time AS idle_seconds, state, LEFT(info, 200) AS last_query FROM information_schema.PROCESSLIST WHERE command = 'Sleep' AND time > 300 ORDER BY time DESC"}	{"condition": "row_count > 5", "description": "Multiple sessions sleeping for extended periods indicate potential connection leaks"}	{"threshold_seconds": 300}	2026-05-11 22:17:39.229791
13125	mariadb	query	Check connection utilization pressure	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS max_connections, ROUND((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') / (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') * 100, 1) AS utilization_pct"}	{"condition": "utilization_pct > 70", "description": "Connection pool nearing capacity confirms leaked connections are causing pressure"}	{"threshold_pct": 70}	2026-05-11 22:17:39.229791
13126	mariadb	query	Check for connection refusals	{"sql": "SELECT VARIABLE_VALUE AS connection_errors FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connection_errors_max_connections'"}	{"condition": "connection_errors > 0", "description": "Non-zero max_connections errors confirm pool exhaustion from leaked connections"}	\N	2026-05-11 22:17:39.229791
13127	mariadb	query	Find long-running active queries	{"sql": "SELECT id, user, host, db, command, time AS running_seconds, state, LEFT(info, 200) AS query_text FROM information_schema.PROCESSLIST WHERE command != 'Sleep' AND command != 'Daemon' AND time > 60 AND info IS NOT NULL ORDER BY time DESC"}	{"condition": "row_count > 0", "description": "Active queries running longer than threshold are holding connections"}	{"threshold_seconds": 60}	2026-05-11 22:17:39.229791
13128	mariadb	query	Check slow query digest patterns	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR AS exec_count, ROUND(AVG_TIMER_WAIT / 1000000000, 2) AS avg_seconds, ROUND(MAX_TIMER_WAIT / 1000000000, 2) AS max_seconds, SUM_ROWS_EXAMINED, SUM_ROWS_SENT FROM performance_schema.events_statements_summary_by_digest WHERE AVG_TIMER_WAIT > 60000000000 ORDER BY AVG_TIMER_WAIT DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Query digests with average execution over 60 seconds confirm systematic slow query issue"}	{"threshold_ns": 60000000000}	2026-05-11 22:17:39.229791
13131	mariadb	query	Check for active lock waits	{"sql": "SELECT waiting_trx_id, waiting_pid AS waiting_thread, waiting_query, blocking_trx_id, blocking_pid AS blocking_thread, blocking_query, wait_age FROM sys.innodb_lock_waits ORDER BY wait_age DESC"}	{"condition": "row_count > 0", "description": "Active lock waits indicate blocked queries holding connections"}	\N	2026-05-11 22:17:39.229791
13132	mariadb	query	Check blocked query count relative to connections	{"sql": "SELECT COUNT(*) AS blocked_count, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS total_connected, ROUND(COUNT(*) / (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') * 100, 1) AS blocked_pct FROM performance_schema.data_lock_waits"}	{"condition": "blocked_pct > 10", "description": "Significant percentage of connections blocked by locks confirms connection pool drain"}	{"threshold_pct": 10}	2026-05-11 22:17:39.229791
13133	mariadb	query	Find long-running open transactions	{"sql": "SELECT trx_id, trx_state, trx_started, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS duration_seconds, trx_mysql_thread_id, trx_query, trx_rows_locked, trx_rows_modified FROM information_schema.INNODB_TRX WHERE TIMESTAMPDIFF(SECOND, trx_started, NOW()) > 300 ORDER BY duration_seconds DESC"}	{"condition": "row_count > 0", "description": "Transactions open for more than 5 minutes indicate application holding connections"}	{"threshold_seconds": 300}	2026-05-11 22:17:39.229791
13134	mariadb	query	Correlate with sleeping thread state	{"sql": "SELECT t.trx_id, t.trx_mysql_thread_id, p.command, p.time AS idle_seconds, TIMESTAMPDIFF(SECOND, t.trx_started, NOW()) AS trx_duration FROM information_schema.INNODB_TRX t JOIN information_schema.PROCESSLIST p ON t.trx_mysql_thread_id = p.id WHERE p.command = 'Sleep' AND TIMESTAMPDIFF(SECOND, t.trx_started, NOW()) > 300"}	{"condition": "row_count > 0", "description": "Sleeping threads with open transactions confirm connection held during app-level processing"}	{"threshold_seconds": 300}	2026-05-11 22:17:39.229791
13135	mariadb	query	Find queries doing full table scans	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR AS exec_count, SUM_NO_INDEX_USED AS no_index_count, ROUND(SUM_TIMER_WAIT / 1000000000000, 2) AS total_seconds, ROUND(AVG_TIMER_WAIT / 1000000000, 2) AS avg_ms, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0), 0) AS rows_ratio FROM performance_schema.events_statements_summary_by_digest WHERE SUM_NO_INDEX_USED > 0 AND AVG_TIMER_WAIT > 1000000000 ORDER BY SUM_TIMER_WAIT DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Queries without index usage and high execution time indicate unoptimized SQL"}	{"threshold_avg_ms": 1000}	2026-05-11 22:17:39.229791
13136	mariadb	query	Check rows examined vs rows sent ratio	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0), 0) AS scan_ratio FROM performance_schema.events_statements_summary_by_digest WHERE SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0) > 1000 AND COUNT_STAR > 10 ORDER BY scan_ratio DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "High rows-examined-to-rows-sent ratio confirms missing indexes or poor query design"}	{"threshold_ratio": 1000}	2026-05-11 22:17:39.229791
