13372	mariadb	config_check	Check purge lag configuration	{"sql": "SELECT @@innodb_max_purge_lag AS max_purge_lag, @@innodb_max_purge_lag_delay AS purge_lag_delay, @@innodb_purge_batch_size AS purge_batch_size"}	{"condition": "max_purge_lag = 0 OR purge_batch_size < 300", "description": "Default purge lag configuration may be too conservative for high-write workloads"}	{"threshold_batch": 300}	2026-05-11 22:17:39.229791
13373	mariadb	query	Check undo tablespace growth	{"sql": "SELECT NAME, FILE_SIZE, ROUND(FILE_SIZE / 1024 / 1024, 2) AS size_mb FROM information_schema.INNODB_TABLESPACES WHERE SPACE_TYPE = 'Undo' ORDER BY FILE_SIZE DESC"}	{"condition": "size_mb > 1024", "description": "Undo tablespace over 1GB indicates purge not keeping up"}	{"threshold_mb": 1024}	2026-05-11 22:17:39.229791
13374	mariadb	config_check	Check if global auto-recalculation of statistics is disabled	{"sql": "SELECT @@global.innodb_stats_auto_recalc AS auto_recalc, @@global.innodb_stats_persistent AS persistent_stats"}	{"condition": "auto_recalc = 0 OR persistent_stats = 1", "description": "Auto-recalculation disabled or persistent stats enabled means statistics may become stale"}	\N	2026-05-11 22:17:39.229791
13375	mariadb	query	Identify tables with stale statistics based on modification counter	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, t.TABLE_ROWS, s.N_ROWS AS stats_rows, s.LAST_UPDATE AS stats_last_update, ABS(CAST(t.TABLE_ROWS AS SIGNED) - CAST(s.N_ROWS AS SIGNED)) AS row_drift FROM information_schema.TABLES t JOIN mysql.innodb_table_stats s ON s.database_name = t.TABLE_SCHEMA AND s.table_name = t.TABLE_NAME WHERE t.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND ABS(CAST(t.TABLE_ROWS AS SIGNED) - CAST(s.N_ROWS AS SIGNED)) > (s.N_ROWS * 0.2) ORDER BY row_drift DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with significant drift between actual row count and stored statistics indicate stale pinned statistics"}	{"drift_threshold_pct": 20}	2026-05-11 22:17:39.229791
13376	mariadb	query	Check per-table STATS_AUTO_RECALC setting overrides	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, CREATE_OPTIONS FROM information_schema.TABLES WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND CREATE_OPTIONS LIKE '%stats_auto_recalc=0%'"}	{"condition": "row_count > 0", "description": "Tables explicitly configured with stats_auto_recalc=0 will not update statistics automatically"}	\N	2026-05-11 22:17:39.229791
13377	mariadb	query	Check tables with high modification count since last ANALYZE	{"sql": "SELECT s.database_name, s.table_name, s.n_rows AS stats_rows, s.last_update AS stats_last_update, TIMESTAMPDIFF(HOUR, s.last_update, NOW()) AS hours_since_update FROM mysql.innodb_table_stats s WHERE s.database_name NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND TIMESTAMPDIFF(HOUR, s.last_update, NOW()) > :stale_hours ORDER BY hours_since_update DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with statistics not updated for extended period after potential bulk operations"}	{"stale_hours": 24}	2026-05-11 22:17:39.229791
13378	mariadb	query	Compare estimated rows versus actual handler statistics	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, t.TABLE_ROWS AS estimated_rows, t.DATA_LENGTH, t.AVG_ROW_LENGTH, s.n_rows AS stats_rows FROM information_schema.TABLES t JOIN mysql.innodb_table_stats s ON s.database_name = t.TABLE_SCHEMA AND s.table_name = t.TABLE_NAME WHERE t.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND t.TABLE_ROWS > 1000 AND ABS(CAST(t.TABLE_ROWS AS SIGNED) - CAST(s.N_ROWS AS SIGNED)) > (GREATEST(t.TABLE_ROWS, s.N_ROWS) * 0.3) ORDER BY ABS(CAST(t.TABLE_ROWS AS SIGNED) - CAST(s.N_ROWS AS SIGNED)) DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Large discrepancy between estimated and stats rows indicates statistics were not refreshed after bulk operations"}	{"drift_threshold_pct": 30}	2026-05-11 22:17:39.229791
13379	mariadb	query	Check tables with high row modification rate	{"sql": "SELECT NAME AS table_name, NUM_ROWS, MODIFIED_COUNTER AS rows_modified_since_analyze, ROUND(MODIFIED_COUNTER / GREATEST(NUM_ROWS, 1) * 100, 1) AS pct_modified FROM information_schema.INNODB_TABLESTATS WHERE NUM_ROWS > 1000 AND MODIFIED_COUNTER > (NUM_ROWS * :threshold_pct / 100) ORDER BY MODIFIED_COUNTER DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables where modification counter exceeds threshold percentage of total rows"}	{"threshold_pct": 10}	2026-05-11 22:17:39.229791
13380	mariadb	config_check	Check auto-recalc threshold configuration	{"sql": "SELECT @@global.innodb_stats_auto_recalc AS auto_recalc, @@global.innodb_stats_persistent_sample_pages AS sample_pages, @@global.innodb_stats_transient_sample_pages AS transient_pages"}	{"condition": "auto_recalc = 1", "description": "Auto-recalc is enabled but may not keep up with high modification rate"}	\N	2026-05-11 22:17:39.229791
13381	mariadb	query	Verify statistics staleness via last update timestamp	{"sql": "SELECT s.database_name, s.table_name, s.n_rows, s.last_update, TIMESTAMPDIFF(MINUTE, s.last_update, NOW()) AS minutes_since_update FROM mysql.innodb_table_stats s WHERE s.database_name NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY minutes_since_update DESC LIMIT 20"}	{"condition": "minutes_since_update > :stale_minutes", "description": "Statistics not refreshed recently despite high modification rate confirms volatile table issue"}	{"stale_minutes": 60}	2026-05-11 22:17:39.229791
13382	mariadb	config_check	Check InnoDB statistics configuration parameters	{"sql": "SELECT @@global.innodb_stats_auto_recalc AS auto_recalc, @@global.innodb_stats_persistent AS persistent_stats, @@global.innodb_stats_persistent_sample_pages AS persistent_sample_pages, @@global.innodb_stats_transient_sample_pages AS transient_sample_pages"}	{"condition": "persistent_sample_pages < 20 OR transient_sample_pages < 8", "description": "Low sample page counts lead to less accurate statistics; default of 20 persistent pages may be insufficient for large tables"}	\N	2026-05-11 22:17:39.229791
13383	mariadb	query	Identify large tables where 10% modification threshold is too high	{"sql": "SELECT NAME AS table_name, NUM_ROWS, MODIFIED_COUNTER AS rows_modified, ROUND(MODIFIED_COUNTER / GREATEST(NUM_ROWS, 1) * 100, 1) AS pct_modified FROM information_schema.INNODB_TABLESTATS WHERE NUM_ROWS > 100000 AND MODIFIED_COUNTER > 0 AND MODIFIED_COUNTER < (NUM_ROWS * 0.10) ORDER BY NUM_ROWS DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Large tables with modifications below 10% threshold will not trigger auto-recalculation despite potentially stale statistics"}	\N	2026-05-11 22:17:39.229791
13384	mariadb	query	Check for long-running transactions in InnoDB	{"sql": "SELECT trx_id, trx_state, trx_started, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS trx_duration_sec, trx_mysql_thread_id, trx_rows_locked, trx_rows_modified FROM information_schema.INNODB_TRX WHERE TIMESTAMPDIFF(SECOND, trx_started, NOW()) > :threshold_seconds ORDER BY trx_started ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Long-running transactions holding back InnoDB purge from cleaning old row versions"}	{"threshold_seconds": 300}	2026-05-11 22:17:39.229791
13386	mariadb	query	Check handler statistics for high modification rates	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME IN ('Handler_update', 'Handler_delete', 'Handler_write', 'Innodb_rows_updated', 'Innodb_rows_deleted', 'Innodb_rows_inserted')"}	{"condition": "Innodb_rows_updated + Innodb_rows_deleted > :threshold", "description": "High cumulative update/delete rate indicates significant row churn"}	{"threshold": 1000000}	2026-05-11 22:17:39.229791
13387	mariadb	query	Check for tablespace bloat via free space ratio	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, DATA_LENGTH, DATA_FREE, ROUND(DATA_FREE / GREATEST(DATA_LENGTH, 1) * 100, 1) AS free_pct FROM information_schema.TABLES WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND ENGINE = 'InnoDB' AND DATA_FREE > :min_free_bytes AND DATA_FREE > DATA_LENGTH * :free_threshold ORDER BY DATA_FREE DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with high DATA_FREE relative to DATA_LENGTH indicate bloat from frequent modifications"}	{"free_threshold": 0.3, "min_free_bytes": 10485760}	2026-05-11 22:17:39.229791
13388	mariadb	query	Check tables with high free space indicating post-delete bloat	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, DATA_LENGTH, DATA_FREE, INDEX_LENGTH, ROUND(DATA_FREE / GREATEST(DATA_LENGTH + INDEX_LENGTH, 1) * 100, 1) AS bloat_pct FROM information_schema.TABLES WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND ENGINE = 'InnoDB' AND DATA_FREE > :min_free_bytes ORDER BY DATA_FREE DESC LIMIT 20"}	{"condition": "row_count > 0 AND bloat_pct > :bloat_threshold", "description": "High free space ratio indicates bulk deletes left reclaimable space in tablespace"}	{"min_free_bytes": 52428800, "bloat_threshold": 30}	2026-05-11 22:17:39.229791
13389	mariadb	query	Check InnoDB purge lag for undo accumulation	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME IN ('trx_rseg_history_len', 'innodb_purge_trx_id_age')"}	{"condition": "trx_rseg_history_len > :history_threshold", "description": "Elevated history list indicates pending purge of deleted row versions"}	{"history_threshold": 5000}	2026-05-11 22:17:39.229791
13390	mariadb	query	Identify tables using UUID or random primary keys	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE, c.COLUMN_TYPE FROM information_schema.COLUMNS c JOIN information_schema.KEY_COLUMN_USAGE k ON c.TABLE_SCHEMA = k.TABLE_SCHEMA AND c.TABLE_NAME = k.TABLE_NAME AND c.COLUMN_NAME = k.COLUMN_NAME WHERE k.CONSTRAINT_NAME = 'PRIMARY' AND c.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND (c.DATA_TYPE IN ('binary', 'varbinary', 'char', 'varchar') AND c.CHARACTER_MAXIMUM_LENGTH >= 32) ORDER BY c.TABLE_SCHEMA, c.TABLE_NAME"}	{"condition": "row_count > 0", "description": "Tables with string/binary primary keys that may contain UUIDs causing random inserts"}	\N	2026-05-11 22:17:39.229791
13391	mariadb	query	Check tablespace fragmentation for identified tables	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, DATA_LENGTH, DATA_FREE, INDEX_LENGTH, ROUND(DATA_FREE / GREATEST(DATA_LENGTH, 1) * 100, 1) AS fragmentation_pct FROM information_schema.TABLES WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND ENGINE = 'InnoDB' AND DATA_FREE > :min_free_bytes ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "row_count > 0 AND fragmentation_pct > :frag_threshold", "description": "High fragmentation percentage confirms page splits from random key inserts"}	{"frag_threshold": 20, "min_free_bytes": 10485760}	2026-05-11 22:17:39.229791
