14006	mariadb	query	Find duplicate digest patterns with different full query texts	{"sql": "SELECT DIGEST, COUNT(*) AS variant_count, MIN(DIGEST_TEXT) AS sample_text FROM performance_schema.events_statements_summary_by_digest WHERE SCHEMA_NAME IS NOT NULL GROUP BY DIGEST HAVING COUNT(*) > 1 ORDER BY variant_count DESC LIMIT 20"}	{"condition": "row_count > 5", "description": "Multiple entries per digest indicate syntactic variations preventing cache hits"}	{"threshold_variants": 5}	2026-05-11 22:17:39.229791
14007	mariadb	query	Verify low cache hit ratio	{"sql": "SELECT ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Qcache_hits') AS DECIMAL) / NULLIF(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Qcache_hits') AS DECIMAL) + CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_select') AS DECIMAL), 0) * 100, 1) AS hit_ratio_pct"}	{"condition": "hit_ratio_pct < 10", "description": "Very low hit ratio confirms query text variations prevent effective caching"}	{"threshold_pct": 10}	2026-05-11 22:17:39.229791
14008	mariadb	query	Find tables with UUID/CHAR/BINARY primary keys	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, k.COLUMN_NAME, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH, t.TABLE_ROWS FROM information_schema.TABLES t JOIN information_schema.KEY_COLUMN_USAGE k ON t.TABLE_SCHEMA = k.TABLE_SCHEMA AND t.TABLE_NAME = k.TABLE_NAME AND k.CONSTRAINT_NAME = 'PRIMARY' JOIN information_schema.COLUMNS c ON k.TABLE_SCHEMA = c.TABLE_SCHEMA AND k.TABLE_NAME = c.TABLE_NAME AND k.COLUMN_NAME = c.COLUMN_NAME WHERE t.ENGINE = 'InnoDB' AND t.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND (c.DATA_TYPE IN ('char', 'varchar', 'binary', 'varbinary') AND c.CHARACTER_MAXIMUM_LENGTH IN (32, 36)) ORDER BY t.TABLE_ROWS DESC"}	{"condition": "row_count > 0", "description": "Tables with 32/36-character PK columns likely use UUID values"}	\N	2026-05-11 22:17:39.229791
14009	mariadb	query	Check InnoDB page split metrics for affected tables	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME IN ('index_page_splits', 'index_page_reorg_attempts', 'index_page_reorg_successful') AND STATUS = 'enabled'"}	{"condition": "index_page_splits > 10000", "description": "High page split count confirms random insertion pattern from UUID PKs"}	{"threshold_splits": 10000}	2026-05-11 22:17:39.229791
14010	mariadb	query	Check overall InnoDB page split rate	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME IN ('index_page_splits', 'index_page_reorg_attempts', 'index_page_reorg_successful')"}	{"condition": "index_page_splits > 5000", "description": "Elevated page split count suggests secondary index fragmentation"}	{"threshold_splits": 5000}	2026-05-11 22:17:39.229791
14011	mariadb	query	Identify large secondary indexes on frequently inserted tables	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.CARDINALITY, s.SEQ_IN_INDEX, ROUND(t.INDEX_LENGTH / 1024 / 1024, 2) AS total_index_mb FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND s.INDEX_NAME != 'PRIMARY' AND s.SEQ_IN_INDEX = 1 AND t.INDEX_LENGTH > 10485760 ORDER BY t.INDEX_LENGTH DESC LIMIT 20"}	{"condition": "row_count > 0 AND total_index_mb > 100", "description": "Large secondary indexes on active tables are susceptible to split-inducing insert patterns"}	{"threshold_index_mb": 100}	2026-05-11 22:17:39.229791
14012	mariadb	query	Check table fragmentation from delete/insert churn	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb, ROUND(DATA_FREE / 1024 / 1024, 2) AS free_mb, ROUND(DATA_FREE / (DATA_LENGTH + INDEX_LENGTH + DATA_FREE) * 100, 1) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND DATA_FREE > 52428800 ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "fragmentation_pct > 30", "description": "Fragmentation above 30% indicates accumulated page splits from random operations"}	{"threshold_pct": 30, "min_free_bytes": 52428800}	2026-05-11 22:17:39.229791
14013	mariadb	query	Check page split and merge metrics	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME IN ('index_page_splits', 'index_page_merge_attempts', 'index_page_merge_successful', 'index_page_reorg_attempts')"}	{"condition": "index_page_splits > index_page_merge_successful * 2", "description": "Splits significantly exceeding merges confirms continuous tree fragmentation"}	\N	2026-05-11 22:17:39.229791
14014	mariadb	query	Check page split frequency	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_splits'"}	{"condition": "COUNT > 10000", "description": "High page split count with default MERGE_THRESHOLD confirms pages splitting due to being fully packed"}	{"threshold_splits": 10000}	2026-05-11 22:17:39.229791
14015	mariadb	query	Check table insert pattern by examining PK type and fragmentation	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, k.COLUMN_NAME, c.DATA_TYPE, t.TABLE_ROWS, ROUND(t.DATA_FREE / (t.DATA_LENGTH + t.DATA_FREE) * 100, 1) AS fragmentation_pct FROM information_schema.TABLES t JOIN information_schema.KEY_COLUMN_USAGE k ON t.TABLE_SCHEMA = k.TABLE_SCHEMA AND t.TABLE_NAME = k.TABLE_NAME AND k.CONSTRAINT_NAME = 'PRIMARY' JOIN information_schema.COLUMNS c ON k.TABLE_SCHEMA = c.TABLE_SCHEMA AND k.TABLE_NAME = c.TABLE_NAME AND k.COLUMN_NAME = c.COLUMN_NAME WHERE t.ENGINE = 'InnoDB' AND t.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND c.DATA_TYPE NOT IN ('int', 'bigint', 'smallint', 'mediumint', 'tinyint') AND t.DATA_FREE > 10485760 ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "row_count > 0 AND fragmentation_pct > 20", "description": "Non-integer PK tables with high fragmentation suggest random insert patterns"}	{"threshold_pct": 20}	2026-05-11 22:17:39.229791
14016	mariadb	query	Verify high page split rate	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_splits'"}	{"condition": "COUNT > 5000", "description": "High page splits with non-sequential PK confirms fill factor inadequate for insert pattern"}	{"threshold_splits": 5000}	2026-05-11 22:17:39.229791
14017	mariadb	query	Check for index latch contention from concurrent inserts	{"sql": "SELECT EVENT_NAME, COUNT_STAR, SUM_TIMER_WAIT / 1000000000 AS total_wait_ms FROM performance_schema.events_waits_summary_global_by_event_name WHERE EVENT_NAME LIKE '%index%latch%' OR EVENT_NAME LIKE '%btr%' AND COUNT_STAR > 0 ORDER BY SUM_TIMER_WAIT DESC LIMIT 10"}	{"condition": "total_wait_ms > 5000", "description": "Significant index latch waits indicate B-tree contention from concurrent inserts"}	{"threshold_wait_ms": 5000}	2026-05-11 22:17:39.229791
14018	mariadb	query	Check concurrent insert activity	{"sql": "SELECT COUNT(*) AS inserting_threads FROM information_schema.PROCESSLIST WHERE COMMAND = 'Query' AND INFO LIKE 'INSERT%'"}	{"condition": "inserting_threads > 10", "description": "Many concurrent INSERT operations confirm high-concurrency insert pattern"}	{"threshold_threads": 10}	2026-05-11 22:17:39.229791
14019	mariadb	query	Verify page split rate is elevated	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_splits'"}	{"condition": "COUNT > 10000", "description": "High page split count with concurrent inserts confirms split cascades"}	{"threshold_splits": 10000}	2026-05-11 22:17:39.229791
14020	mariadb	query	Check page split and reorganization metrics	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME IN ('index_page_splits', 'index_page_reorg_attempts', 'index_page_reorg_successful', 'index_page_merge_attempts', 'index_page_merge_successful')"}	{"condition": "index_page_splits > 50000", "description": "Very high page split count suggests cascade splits propagating through B-tree levels"}	{"threshold_splits": 50000}	2026-05-11 22:17:39.229791
14021	mariadb	query	Check write I/O impact from page splits	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_pages_written') AS pages_written, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_writes') AS data_writes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_write_requests') AS write_requests"}	{"condition": "pages_written > 100000", "description": "High page write volume confirms I/O amplification from cascade splits"}	{"threshold_writes": 100000}	2026-05-11 22:17:39.229791
14022	mariadb	query	Find tables with large average row size	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, ROUND(AVG_ROW_LENGTH, 0) AS avg_row_bytes, ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb, ROUND(16384 / NULLIF(AVG_ROW_LENGTH, 0), 0) AS rows_per_page FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND AVG_ROW_LENGTH > 2000 AND TABLE_ROWS > 1000 ORDER BY AVG_ROW_LENGTH DESC LIMIT 20"}	{"condition": "rows_per_page < 8", "description": "Fewer than 8 rows per 16KB page means pages fill quickly and split more often"}	{"threshold_rows_per_page": 8}	2026-05-11 22:17:39.229791
14023	mariadb	query	Check page split count	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_splits'"}	{"condition": "COUNT > 5000", "description": "Elevated page splits with large row sizes confirms row-width-induced splitting"}	{"threshold_splits": 5000}	2026-05-11 22:17:39.229791
14024	mariadb	query	Find tables with UUID-style primary keys and high insert rates	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, k.COLUMN_NAME, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH, t.TABLE_ROWS FROM information_schema.TABLES t JOIN information_schema.KEY_COLUMN_USAGE k ON t.TABLE_SCHEMA = k.TABLE_SCHEMA AND t.TABLE_NAME = k.TABLE_NAME AND k.CONSTRAINT_NAME = 'PRIMARY' JOIN information_schema.COLUMNS c ON k.TABLE_SCHEMA = c.TABLE_SCHEMA AND k.TABLE_NAME = c.TABLE_NAME AND k.COLUMN_NAME = c.COLUMN_NAME WHERE t.ENGINE = 'InnoDB' AND t.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND ((c.DATA_TYPE IN ('char', 'varchar', 'binary', 'varbinary') AND c.CHARACTER_MAXIMUM_LENGTH IN (32, 36)) OR c.DATA_TYPE = 'binary' AND c.CHARACTER_MAXIMUM_LENGTH = 16) AND t.TABLE_ROWS > 10000 ORDER BY t.TABLE_ROWS DESC"}	{"condition": "row_count > 0", "description": "Tables with UUID-typed PKs and substantial row counts"}	\N	2026-05-11 22:17:39.229791
14025	mariadb	query	Check concurrent insert thread count and page split rate	{"sql": "SELECT (SELECT COUNT(*) FROM information_schema.PROCESSLIST WHERE COMMAND = 'Query' AND INFO LIKE 'INSERT%') AS insert_threads, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_splits') AS page_splits, (SELECT SUM_TIMER_WAIT / 1000000000 FROM performance_schema.events_waits_summary_global_by_event_name WHERE EVENT_NAME LIKE '%index%latch%' ORDER BY SUM_TIMER_WAIT DESC LIMIT 1) AS index_latch_wait_ms"}	{"condition": "insert_threads > 5 AND page_splits > 20000", "description": "Multiple concurrent inserters with high page splits confirms UUID-driven contention"}	{"threshold_splits": 20000, "threshold_threads": 5}	2026-05-11 22:17:39.229791
14026	mariadb	query	Check table fragmentation after recent rebuild	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb, ROUND(DATA_FREE / 1024 / 1024, 2) AS free_mb, UPDATE_TIME, CREATE_TIME FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND DATA_FREE > 52428800 AND TABLE_ROWS > 10000 ORDER BY DATA_FREE DESC LIMIT 20"}	{"condition": "row_count > 0 AND free_mb > 50", "description": "Significant free space accumulating after rebuild suggests pages splitting from tight packing"}	{"threshold_free_mb": 50}	2026-05-11 22:17:39.229791
14027	mariadb	query	Check MERGE_THRESHOLD on affected indexes	{"sql": "SELECT t.NAME AS table_name, i.NAME AS index_name, i.MERGE_THRESHOLD FROM information_schema.INNODB_INDEXES i JOIN information_schema.INNODB_TABLES t ON i.TABLE_ID = t.TABLE_ID WHERE t.NAME NOT LIKE 'mysql/%' AND t.NAME NOT LIKE 'sys/%' AND i.MERGE_THRESHOLD >= 50 ORDER BY t.NAME"}	{"condition": "row_count > 0", "description": "Default MERGE_THRESHOLD of 50% during rebuild leaves no room for subsequent inserts"}	\N	2026-05-11 22:17:39.229791
14028	mariadb	query	Identify secondary indexes with high fragmentation	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, CARDINALITY, SUB_PART, NULLABLE FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND INDEX_NAME != 'PRIMARY' AND SEQ_IN_INDEX = 1 ORDER BY CARDINALITY DESC LIMIT 30"}	{"condition": "row_count > 0", "description": "Secondary indexes with high cardinality are candidates for split issues"}	\N	2026-05-11 22:17:39.229791
14029	mariadb	query	Check INDEX_LENGTH growth rate vs DATA_LENGTH	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb, ROUND(INDEX_LENGTH / 1024 / 1024, 2) AS index_mb, ROUND(INDEX_LENGTH / NULLIF(DATA_LENGTH, 0), 2) AS index_ratio FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND INDEX_LENGTH > 52428800 ORDER BY index_ratio DESC LIMIT 20"}	{"condition": "index_ratio > 1.5", "description": "Index size significantly exceeding data size suggests secondary index fragmentation from page splits"}	{"threshold_ratio": 1.5}	2026-05-11 22:17:39.229791
14030	mariadb	query	Find tables with many foreign key indexes	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, COUNT(*) AS fk_count FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_NAME IS NOT NULL AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') GROUP BY TABLE_SCHEMA, TABLE_NAME HAVING COUNT(*) >= 3 ORDER BY fk_count DESC"}	{"condition": "row_count > 0", "description": "Tables with 3+ foreign keys have proportionally more index maintenance during inserts"}	{"threshold_fk_count": 3}	2026-05-11 22:17:39.229791
14031	mariadb	query	Check page split rate and insert volume	{"sql": "SELECT (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_splits') AS page_splits, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_rows_inserted') AS rows_inserted, ROUND(CAST((SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_splits') AS DECIMAL) / NULLIF(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_rows_inserted') AS DECIMAL), 0) * 100, 2) AS splits_per_insert_pct"}	{"condition": "splits_per_insert_pct > 5", "description": "More than 5% page-split-to-insert ratio indicates FK index overhead multiplying splits"}	{"threshold_pct": 5}	2026-05-11 22:17:39.229791
14032	mariadb	query	Find secondary indexes with low cardinality relative to table size	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.INDEX_NAME != 'PRIMARY' AND s.SEQ_IN_INDEX = 1 AND t.TABLE_ROWS > 10000 AND s.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND s.CARDINALITY < t.TABLE_ROWS * 0.01 ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "selectivity_pct < 1", "description": "Indexes with less than 1% selectivity concentrate inserts on very few leaf pages"}	{"threshold_selectivity_pct": 1}	2026-05-11 22:17:39.229791
14033	mariadb	query	Check for elevated page splits on active workload	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME IN ('index_page_splits', 'index_page_reorg_attempts')"}	{"condition": "index_page_splits > 5000", "description": "Active page splits combined with low-cardinality indexes confirm hot-spot splitting"}	{"threshold_splits": 5000}	2026-05-11 22:17:39.229791
14034	mariadb	query	Check current connection utilization vs max_connections	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS max_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Max_used_connections') AS peak_connections, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS DECIMAL) * 100, 1) AS utilization_pct"}	{"condition": "utilization_pct > 80", "description": "Connection utilization above 80% indicates pool exhaustion risk"}	{"threshold_pct": 80}	2026-05-11 22:17:39.229791
14035	mariadb	query	Check for connection errors from pool exhaustion	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connection_errors_max_connections') AS max_conn_errors, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_connects') AS aborted_connects"}	{"condition": "max_conn_errors > 0", "description": "Connection errors from max_connections limit confirm pool exhaustion"}	\N	2026-05-11 22:17:39.229791
14036	mariadb	query	Find long-running transactions	{"sql": "SELECT trx_id, trx_state, trx_started, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS duration_seconds, trx_rows_locked, trx_rows_modified, trx_isolation_level FROM information_schema.INNODB_TRX WHERE TIMESTAMPDIFF(SECOND, trx_started, NOW()) > 60 ORDER BY trx_started ASC"}	{"condition": "row_count > 0", "description": "Transactions running longer than 60 seconds hold connections open unnecessarily"}	{"threshold_seconds": 60}	2026-05-11 22:17:39.229791
14037	mariadb	query	Find idle connections held beyond threshold	{"sql": "SELECT ID, USER, HOST, DB, COMMAND, TIME AS idle_seconds, STATE FROM information_schema.PROCESSLIST WHERE COMMAND = 'Sleep' AND TIME > 300 ORDER BY TIME DESC"}	{"condition": "row_count > 10", "description": "Many connections sleeping for over 5 minutes indicate connection leaks"}	{"threshold_count": 10, "threshold_seconds": 300}	2026-05-11 22:17:39.229791
14038	mariadb	query	Check connection growth trend	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current_connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_running') AS current_running, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Max_used_connections') AS peak_connections"}	{"condition": "current_connected > current_running * 5", "description": "Connected threads far exceeding running threads confirms many leaked idle connections"}	{"threshold_ratio": 5}	2026-05-11 22:17:39.229791
14039	mariadb	query	Find currently running slow queries	{"sql": "SELECT ID, USER, HOST, DB, COMMAND, TIME AS running_seconds, STATE, LEFT(INFO, 200) AS query_text FROM information_schema.PROCESSLIST WHERE COMMAND = 'Query' AND TIME > 30 ORDER BY TIME DESC"}	{"condition": "row_count > 3", "description": "Multiple queries running over 30 seconds consume connections for extended periods"}	{"threshold_count": 3, "threshold_seconds": 30}	2026-05-11 22:17:39.229791
14040	mariadb	query	Check slow query log status	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Slow_queries') AS slow_queries, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'long_query_time') AS long_query_time, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'slow_query_log') AS slow_log_enabled"}	{"condition": "slow_queries > 100", "description": "High slow query count confirms connection occupation from slow queries"}	{"threshold_slow_queries": 100}	2026-05-11 22:17:39.229791
14041	mariadb	query	Check deadlock history	{"sql": "SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks'"}	{"condition": "VARIABLE_VALUE > 0", "description": "Deadlocks occurred which could leave connections in inconsistent state"}	\N	2026-05-11 22:17:39.229791
14042	mariadb	query	Count connections per source host	{"sql": "SELECT SUBSTRING_INDEX(HOST, ':', 1) AS client_host, USER, COUNT(*) AS connection_count FROM information_schema.PROCESSLIST WHERE USER NOT IN ('system user', 'event_scheduler') GROUP BY client_host, USER ORDER BY connection_count DESC"}	{"condition": "row_count > 3", "description": "Connections from many distinct hosts indicate multiple app instances competing"}	{"threshold_hosts": 3}	2026-05-11 22:17:39.229791
14043	mariadb	query	Check total connection pressure	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS max_conn, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS DECIMAL) * 100, 1) AS utilization_pct"}	{"condition": "utilization_pct > 70", "description": "High utilization from multiple sources confirms competing application instances"}	{"threshold_pct": 70}	2026-05-11 22:17:39.229791
14044	mariadb	query	Check for sessions blocked by lock holders	{"sql": "SELECT COUNT(*) AS blocked_sessions FROM sys.innodb_lock_waits"}	{"condition": "blocked_sessions > 3", "description": "Multiple blocked sessions indicate lock contention holding connections"}	{"threshold_blocked": 3}	2026-05-11 22:17:39.229791
14045	mariadb	query	Identify the blocking transactions	{"sql": "SELECT blocking_trx_id, blocking_pid AS blocking_thread, blocking_query, wait_age FROM sys.innodb_lock_waits ORDER BY wait_age DESC"}	{"condition": "duration_seconds > 30", "description": "Long-running blocking transactions confirm lock contention consuming connections"}	{"threshold_seconds": 30}	2026-05-11 22:17:39.229791
14046	mariadb	query	Find very old idle connections	{"sql": "SELECT ID, USER, HOST, DB, COMMAND, TIME AS idle_seconds, STATE FROM information_schema.PROCESSLIST WHERE COMMAND = 'Sleep' AND TIME > 3600 ORDER BY TIME DESC"}	{"condition": "row_count > 5", "description": "Connections idle for over 1 hour suggest stale connections not validated by pool"}	{"threshold_count": 5, "threshold_seconds": 3600}	2026-05-11 22:17:39.229791
14047	mariadb	config_check	Check MySQL timeout settings	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME IN ('wait_timeout', 'interactive_timeout', 'net_read_timeout', 'net_write_timeout')"}	{"condition": "wait_timeout > 3600", "description": "High wait_timeout allows stale connections to persist indefinitely"}	{"threshold_timeout": 3600}	2026-05-11 22:17:39.229791
14048	mariadb	query	Identify users or hosts with disproportionate connection counts	{"sql": "SELECT USER, SUBSTRING_INDEX(HOST, ':', 1) AS client_host, COUNT(*) AS conn_count, SUM(CASE WHEN COMMAND = 'Sleep' THEN 1 ELSE 0 END) AS idle_count, ROUND(SUM(CASE WHEN COMMAND = 'Sleep' THEN 1 ELSE 0 END) / COUNT(*) * 100, 1) AS idle_pct FROM information_schema.PROCESSLIST WHERE USER NOT IN ('system user', 'event_scheduler') GROUP BY USER, client_host ORDER BY conn_count DESC"}	{"condition": "conn_count > 20 AND idle_pct > 80", "description": "Single user/host with 20+ connections mostly idle indicates middleware pool hoarding"}	{"threshold_idle_pct": 80, "threshold_connections": 20}	2026-05-11 22:17:39.229791
14049	mariadb	config_check	Check connection timeout settings	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME IN ('wait_timeout', 'interactive_timeout', 'net_read_timeout', 'net_write_timeout', 'connect_timeout')"}	{"condition": "wait_timeout > 7200", "description": "wait_timeout above 2 hours allows stuck connections to consume slots for extended periods"}	{"threshold_timeout": 7200}	2026-05-11 22:17:39.229791
14050	mariadb	query	Count connections stuck for extended periods	{"sql": "SELECT COUNT(*) AS stuck_connections, MAX(TIME) AS max_idle_seconds FROM information_schema.PROCESSLIST WHERE COMMAND = 'Sleep' AND TIME > 7200"}	{"condition": "stuck_connections > 0", "description": "Connections idle for hours confirms timeout settings are too permissive"}	{"threshold_seconds": 7200}	2026-05-11 22:17:39.229791
14051	mariadb	query	Check for accumulating idle connections	{"sql": "SELECT COUNT(*) AS sleeping_connections, MAX(TIME) AS max_idle_seconds, AVG(TIME) AS avg_idle_seconds FROM information_schema.PROCESSLIST WHERE COMMAND = 'Sleep'"}	{"condition": "sleeping_connections > 20 AND avg_idle_seconds > 600", "description": "Many connections sleeping with high average idle time indicates connection leaks"}	{"threshold_avg_idle": 600, "threshold_connections": 20}	2026-05-11 22:17:39.229791
14052	mariadb	config_check	Check idle connection timeout settings	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME IN ('wait_timeout', 'interactive_timeout')"}	{"condition": "wait_timeout >= 28800", "description": "Default or very high wait_timeout (8+ hours) allows leaked connections to persist"}	{"threshold_timeout": 28800}	2026-05-11 22:17:39.229791
14053	mariadb	query	Find long-lived idle connections	{"sql": "SELECT COUNT(*) AS old_idle_connections, MAX(TIME) AS max_idle_seconds FROM information_schema.PROCESSLIST WHERE COMMAND = 'Sleep' AND TIME > 3600"}	{"condition": "old_idle_connections > 5", "description": "Multiple connections idle for hours confirms insufficient timeout settings"}	{"threshold_count": 5, "threshold_seconds": 3600}	2026-05-11 22:17:39.229791
14054	mariadb	query	Identify hosts with disproportionate connection counts	{"sql": "SELECT SUBSTRING_INDEX(HOST, ':', 1) AS client_host, COUNT(*) AS total_connections, SUM(CASE WHEN COMMAND = 'Sleep' THEN 1 ELSE 0 END) AS idle_connections, ROUND(SUM(CASE WHEN COMMAND = 'Sleep' THEN 1 ELSE 0 END) / COUNT(*) * 100, 1) AS idle_pct, MAX(TIME) AS max_idle_seconds FROM information_schema.PROCESSLIST WHERE USER NOT IN ('system user', 'event_scheduler') GROUP BY client_host HAVING COUNT(*) > 10 ORDER BY total_connections DESC"}	{"condition": "idle_pct > 80 AND total_connections > 20", "description": "Single host with many mostly-idle connections suggests middleware buffering"}	{"threshold_idle_pct": 80, "threshold_connections": 20}	2026-05-11 22:17:39.229791
14055	mariadb	query	Check if connection pool is growing over time	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Max_used_connections') AS peak, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_clients') AS aborted"}	{"condition": "current > peak * 0.9", "description": "Current connections near historical peak suggests sustained connection accumulation"}	\N	2026-05-11 22:17:39.229791
14056	mariadb	query	Find abandoned open transactions	{"sql": "SELECT trx_id, trx_state, trx_started, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS duration_seconds, trx_rows_locked, trx_rows_modified, trx_isolation_level, trx_mysql_thread_id FROM information_schema.INNODB_TRX WHERE TIMESTAMPDIFF(SECOND, trx_started, NOW()) > 600 ORDER BY trx_started ASC"}	{"condition": "row_count > 0", "description": "Transactions open for over 10 minutes without completion are likely abandoned"}	{"threshold_seconds": 600}	2026-05-11 22:17:39.229791
