14057	mariadb	query	Check if abandoned transactions are on idle connections	{"sql": "SELECT p.ID, p.USER, p.HOST, p.COMMAND, p.TIME AS idle_seconds, t.trx_state, TIMESTAMPDIFF(SECOND, t.trx_started, NOW()) AS trx_duration FROM information_schema.INNODB_TRX t JOIN information_schema.PROCESSLIST p ON t.trx_mysql_thread_id = p.ID WHERE p.COMMAND = 'Sleep' AND TIMESTAMPDIFF(SECOND, t.trx_started, NOW()) > 300 ORDER BY t.trx_started ASC"}	{"condition": "row_count > 0", "description": "Idle connections with open transactions confirm abandoned transactions holding connections"}	{"threshold_seconds": 300}	2026-05-11 22:17:39.229791
14058	mariadb	query	Find clusters of connections from batch-like patterns	{"sql": "SELECT USER, SUBSTRING_INDEX(HOST, ':', 1) AS client_host, COUNT(*) AS total, SUM(CASE WHEN COMMAND = 'Sleep' THEN 1 ELSE 0 END) AS idle, SUM(CASE WHEN COMMAND = 'Query' THEN 1 ELSE 0 END) AS active, MAX(TIME) AS max_time FROM information_schema.PROCESSLIST WHERE USER NOT IN ('system user', 'event_scheduler') GROUP BY USER, client_host HAVING total > 5 AND idle > active ORDER BY total DESC"}	{"condition": "idle > active * 3", "description": "Many more idle than active connections from same source suggests batch failure with unreleased connections"}	{"threshold_ratio": 3}	2026-05-11 22:17:39.229791
14059	mariadb	query	Check for open transactions on idle batch connections	{"sql": "SELECT p.ID, p.USER, p.HOST, p.COMMAND, p.TIME, t.trx_state, t.trx_rows_modified FROM information_schema.PROCESSLIST p LEFT JOIN information_schema.INNODB_TRX t ON p.ID = t.trx_mysql_thread_id WHERE p.COMMAND = 'Sleep' AND p.TIME > 600 ORDER BY p.TIME DESC LIMIT 20"}	{"condition": "row_count > 3", "description": "Multiple idle connections with or without open transactions from batch jobs confirm unreleased connections"}	{"threshold_count": 3}	2026-05-11 22:17:39.229791
14060	mariadb	query	Check connection creation rate vs active connections	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current_connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_created') AS threads_created, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') AS uptime_seconds, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') AS DECIMAL), 1) AS connections_per_second"}	{"condition": "connections_per_second > 10", "description": "More than 10 new connections per second suggests no connection pooling"}	{"threshold_per_second": 10}	2026-05-11 22:17:39.229791
14061	mariadb	query	Check thread cache efficiency	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_created') AS threads_created, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'thread_cache_size') AS thread_cache_size, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_created') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS DECIMAL) * 100, 1) AS thread_creation_pct"}	{"condition": "thread_creation_pct > 50", "description": "High thread creation percentage means most connections require new thread allocation"}	{"threshold_pct": 50}	2026-05-11 22:17:39.229791
14062	mariadb	query	Check connection creation vs reuse rate	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_created') AS threads_created, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current_connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_cached') AS threads_cached"}	{"condition": "threads_created > current_connected * 10", "description": "Thread creation count far exceeding current connections indicates frequent connection cycling"}	{"threshold_ratio": 10}	2026-05-11 22:17:39.229791
14063	mariadb	query	Check aborted client connections	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_clients') AS aborted_clients, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_clients') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS DECIMAL) * 100, 1) AS abort_pct"}	{"condition": "abort_pct > 5", "description": "High abort rate suggests connections being forcibly closed by pool timeout settings"}	{"threshold_pct": 5}	2026-05-11 22:17:39.229791
14064	mariadb	query	Check for high connection rate with low concurrent usage	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current_connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') AS uptime, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') AS DECIMAL), 1) AS conn_per_sec"}	{"condition": "conn_per_sec > 5 AND current_connected < 20", "description": "High connection rate with low concurrent connections indicates connect-execute-disconnect pattern"}	{"threshold_current": 20, "threshold_conn_per_sec": 5}	2026-05-11 22:17:39.229791
14065	mariadb	query	Check SSL handshake overhead	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Ssl_accepts') AS ssl_accepts, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections"}	{"condition": "ssl_accepts > total_connections * 0.5", "description": "Many SSL handshakes relative to connections adds significant per-connection overhead"}	\N	2026-05-11 22:17:39.229791
14066	mariadb	query	Count distinct application hosts with connection pools	{"sql": "SELECT SUBSTRING_INDEX(HOST, ':', 1) AS client_host, USER, COUNT(*) AS connections FROM information_schema.PROCESSLIST WHERE USER NOT IN ('system user', 'event_scheduler') GROUP BY client_host, USER ORDER BY connections DESC"}	{"condition": "COUNT(DISTINCT client_host) > 5", "description": "Many distinct hosts indicate multiple backend instances each with own pool"}	{"threshold_hosts": 5}	2026-05-11 22:17:39.229791
14727	mariadb	config_check	Check audit log connection policy	{"sql": "SHOW GLOBAL VARIABLES LIKE 'audit_log_connection_policy'"}	{"condition": "value != 'ALL'", "description": "Connection policy not set to ALL means some connection events including failures may be excluded"}	\N	2026-05-11 22:17:39.229791
14067	mariadb	query	Check total connection consumption	{"sql": "SELECT ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS DECIMAL) * 100, 1) AS utilization_pct"}	{"condition": "utilization_pct > 50", "description": "Significant connection utilization from multiple small pools confirms distributed pool overhead"}	{"threshold_pct": 50}	2026-05-11 22:17:39.229791
14068	mariadb	query	Check for high frequency of simple validation queries	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_TIMER_WAIT / 1000000000 AS total_ms FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT IN ('SELECT ? ', 'SELECT @@version_comment LIMIT ? ', 'SELECT ? AS `val`') OR DIGEST_TEXT LIKE 'SELECT %1%' ORDER BY COUNT_STAR DESC LIMIT 10"}	{"condition": "COUNT_STAR > 100000", "description": "Extremely high count of validation queries indicates overly frequent health checks"}	{"threshold_count": 100000}	2026-05-11 22:17:39.229791
14069	mariadb	query	Check connection abort rate from failed health checks	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_clients') AS aborted_clients, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_connects') AS aborted_connects, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections"}	{"condition": "aborted_clients > total_connections * 0.01", "description": "Aborted connections exceeding 1% of total confirms health check failures causing disconnects"}	{"threshold_pct": 1}	2026-05-11 22:17:39.229791
