14071	mariadb	query	Check for high rate of connection creation with low reuse	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_created') AS threads_created, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_cached') AS threads_cached, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_clients') AS aborted_clients"}	{"condition": "threads_created > connections * 0.5", "description": "Creating threads for more than half of all connections indicates very low reuse"}	{"threshold_ratio": 0.5}	2026-05-11 22:17:39.229791
14072	mariadb	query	Check connection error patterns	{"sql": "SELECT EVENT_NAME, SUM_ERRORS, SUM_WARNINGS FROM performance_schema.events_statements_summary_global_by_event_name WHERE EVENT_NAME LIKE '%com_connect%' OR EVENT_NAME LIKE '%com_quit%' ORDER BY SUM_ERRORS DESC LIMIT 10"}	{"condition": "SUM_ERRORS > 100", "description": "Connection errors suggest driver timeouts forcing reconnection"}	{"threshold_errors": 100}	2026-05-11 22:17:39.229791
14073	mariadb	query	Check server uptime and connection rate since last start	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') AS uptime_seconds, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Max_used_connections') AS peak_connections, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') AS DECIMAL), 1) AS conn_per_sec"}	{"condition": "uptime_seconds < 3600 AND conn_per_sec > 20", "description": "Recent restart with very high connection rate indicates post-failover connection storm"}	{"threshold_uptime": 3600, "threshold_conn_per_sec": 20}	2026-05-11 22:17:39.229791
14074	mariadb	query	Check if connections are approaching max	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS max_conn, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connection_errors_max_connections') AS max_conn_errors"}	{"condition": "connected > max_conn * 0.8 OR max_conn_errors > 0", "description": "Connections near max or rejected connections confirm post-event connection storm"}	\N	2026-05-11 22:17:39.229791
14075	mariadb	query	Check connection rate vs query rate	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Queries') AS total_queries, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Queries') AS DECIMAL) / NULLIF(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS DECIMAL), 0), 1) AS queries_per_connection"}	{"condition": "queries_per_connection < 5", "description": "Fewer than 5 queries per connection indicates connect-execute-disconnect pattern"}	{"threshold_queries_per_conn": 5}	2026-05-11 22:17:39.229791
