14077	mariadb	query	Check prepared statement usage rate	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_stmt_prepare') AS stmt_prepare, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_stmt_execute') AS stmt_execute, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Queries') AS total_queries, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_stmt_execute') AS DECIMAL) / NULLIF(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Queries') AS DECIMAL), 0) * 100, 1) AS prepared_pct"}	{"condition": "prepared_pct < 5", "description": "Less than 5% prepared statement usage means queries are parsed from scratch each time"}	{"threshold_pct": 5}	2026-05-11 22:17:39.229791
14728	mariadb	config_check	Check audit log policy overall	{"sql": "SHOW GLOBAL VARIABLES LIKE 'audit_log_policy'"}	{"condition": "value NOT IN ('ALL', 'LOGINS')", "description": "If audit_log_policy excludes LOGINS, login failure events are not captured"}	\N	2026-05-11 22:17:39.229791
14078	mariadb	query	Check prepare-to-execute ratio	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_stmt_prepare') AS prepares, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_stmt_execute') AS executes, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_stmt_execute') AS DECIMAL) / NULLIF(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_stmt_prepare') AS DECIMAL), 0), 1) AS exec_per_prepare"}	{"condition": "exec_per_prepare < 2", "description": "Low executions per prepare confirms statements are not being cached and reused"}	{"threshold_ratio": 2}	2026-05-11 22:17:39.229791
14079	mariadb	query	Check aborted connection rate	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_connects') AS aborted_connects, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_clients') AS aborted_clients, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, ROUND((CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_connects') AS DECIMAL) + CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_clients') AS DECIMAL)) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS DECIMAL) * 100, 2) AS total_abort_pct"}	{"condition": "total_abort_pct > 3", "description": "Abort rate above 3% indicates frequent connection failures and reconnections"}	{"threshold_pct": 3}	2026-05-11 22:17:39.229791
14080	mariadb	query	Check thread creation overhead from reconnections	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_created') AS threads_created, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_created') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS DECIMAL) * 100, 1) AS creation_pct"}	{"condition": "creation_pct > 20", "description": "High thread creation percentage confirms frequent reconnections from validation failures"}	{"threshold_pct": 20}	2026-05-11 22:17:39.229791
14081	mariadb	query	Check current connection utilization and errors	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS max_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Max_used_connections') AS peak_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connection_errors_max_connections') AS max_conn_errors"}	{"condition": "max_conn_errors > 0 OR current_connections >= max_connections * 0.95", "description": "Connection errors or utilization above 95% confirms max_connections reached"}	\N	2026-05-11 22:17:39.229791
14082	mariadb	query	Identify connection sources contributing to exhaustion	{"sql": "SELECT USER, SUBSTRING_INDEX(HOST, ':', 1) AS client_host, COUNT(*) AS conn_count FROM information_schema.PROCESSLIST WHERE USER NOT IN ('system user', 'event_scheduler') GROUP BY USER, client_host ORDER BY conn_count DESC LIMIT 20"}	{"condition": "row_count > 3", "description": "Multiple sources confirm cumulative demand exceeding capacity"}	\N	2026-05-11 22:17:39.229791
14083	mariadb	query	Check for rapid connection attempt rate	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') AS uptime, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connection_errors_max_connections') AS rejected, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Aborted_connects') AS aborted"}	{"condition": "rejected > 0 AND aborted > 0", "description": "Both rejected and aborted connections indicate cascading connection failures"}	\N	2026-05-11 22:17:39.229791
14084	mariadb	query	Check connection error types	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME LIKE 'Connection_errors_%' AND CAST(VARIABLE_VALUE AS UNSIGNED) > 0"}	{"condition": "row_count > 1", "description": "Multiple connection error types indicate cascading connection storm"}	\N	2026-05-11 22:17:39.229791
14085	mariadb	query	Count distinct users and hosts connecting	{"sql": "SELECT COUNT(DISTINCT USER) AS distinct_users, COUNT(DISTINCT SUBSTRING_INDEX(HOST, ':', 1)) AS distinct_hosts, COUNT(*) AS total_connections FROM information_schema.PROCESSLIST WHERE USER NOT IN ('system user', 'event_scheduler')"}	{"condition": "distinct_users > 3 OR distinct_hosts > 5", "description": "Multiple distinct users or hosts indicate separate microservice pools"}	{"threshold_hosts": 5, "threshold_users": 3}	2026-05-11 22:17:39.229791
14086	mariadb	query	Check if total connections approaching limit	{"sql": "SELECT ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS DECIMAL) * 100, 1) AS utilization_pct, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connection_errors_max_connections') AS rejected"}	{"condition": "utilization_pct > 70 OR rejected > 0", "description": "High utilization from multiple services confirms multiplied demand exceeding capacity"}	{"threshold_pct": 70}	2026-05-11 22:17:39.229791
14087	mariadb	config_check	Check current max_connections setting	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS current_max, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Max_used_connections') AS peak_used, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connection_errors_max_connections') AS rejected"}	{"condition": "peak_used >= current_max * 0.95 OR rejected > 0", "description": "Peak connections reaching or exceeding max_connections confirms limit is actively constraining"}	\N	2026-05-11 22:17:39.229791
14088	mariadb	config_check	Check if max_connections is set low	{"sql": "SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections'"}	{"condition": "VARIABLE_VALUE <= 151", "description": "Default max_connections (151) is too low for most production workloads"}	{"default_max": 151}	2026-05-11 22:17:39.229791
14089	mariadb	query	Count administrative and monitoring connections	{"sql": "SELECT USER, COUNT(*) AS conn_count, GROUP_CONCAT(DISTINCT COMMAND ORDER BY COMMAND) AS commands FROM information_schema.PROCESSLIST WHERE USER IN ('root', 'admin', 'monitor', 'replication', 'backup', 'zabbix', 'prometheus', 'datadog', 'nagios', 'newrelic') OR USER LIKE '%monitor%' OR USER LIKE '%backup%' OR USER LIKE '%admin%' GROUP BY USER ORDER BY conn_count DESC"}	{"condition": "row_count > 2", "description": "Multiple administrative users consuming connection slots"}	\N	2026-05-11 22:17:39.229791
14090	mariadb	query	Check if admin connections impact capacity	{"sql": "SELECT (SELECT COUNT(*) FROM information_schema.PROCESSLIST WHERE USER IN ('root', 'admin', 'monitor', 'replication', 'backup', 'zabbix', 'prometheus', 'datadog', 'nagios', 'newrelic') OR USER LIKE '%monitor%' OR USER LIKE '%backup%') AS admin_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS max_connections"}	{"condition": "admin_connections > max_connections * 0.1", "description": "Administrative connections consuming more than 10% of max_connections impacts application"}	{"threshold_pct": 10}	2026-05-11 22:17:39.229791
14091	mariadb	query	Count replication-related connections	{"sql": "SELECT COUNT(*) AS repl_connections FROM information_schema.PROCESSLIST WHERE USER = 'system user' OR COMMAND IN ('Binlog Dump', 'Binlog Dump GTID') OR USER LIKE 'repl%'"}	{"condition": "repl_connections > 3", "description": "Multiple replication connections consuming connection slots"}	{"threshold_count": 3}	2026-05-11 22:17:39.229791
14092	mariadb	query	Check remaining capacity after replication	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS total_connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS max_conn, (SELECT COUNT(*) FROM information_schema.PROCESSLIST WHERE USER = 'system user' OR COMMAND LIKE 'Binlog Dump%') AS repl_threads"}	{"condition": "total_connected - repl_threads > max_conn * 0.85", "description": "Application connections approaching max after accounting for replication confirms slot competition"}	\N	2026-05-11 22:17:39.229791
14093	mariadb	query	Find long-idle connections from potentially old app instances	{"sql": "SELECT SUBSTRING_INDEX(HOST, ':', 1) AS client_host, USER, COUNT(*) AS connections, SUM(CASE WHEN COMMAND = 'Sleep' AND TIME > 1800 THEN 1 ELSE 0 END) AS old_idle, MAX(TIME) AS max_idle_seconds FROM information_schema.PROCESSLIST WHERE USER NOT IN ('system user', 'event_scheduler') GROUP BY client_host, USER HAVING old_idle > 0 ORDER BY old_idle DESC"}	{"condition": "old_idle > 5", "description": "Connections idle for over 30 minutes suggest stale connections from old deployments"}	{"threshold_idle": 1800, "threshold_count": 5}	2026-05-11 22:17:39.229791
14094	mariadb	query	Check if stale connections impact total capacity	{"sql": "SELECT (SELECT COUNT(*) FROM information_schema.PROCESSLIST WHERE COMMAND = 'Sleep' AND TIME > 1800) AS stale_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS total_connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'max_connections') AS max_conn"}	{"condition": "stale_connections > total_connected * 0.1", "description": "Stale connections exceeding 10% of total confirms deployment cleanup issue"}	{"threshold_pct": 10}	2026-05-11 22:17:39.229791
14095	mariadb	query	Find long-running transactions with lock waits	{"sql": "SELECT trx_id, trx_state, trx_started, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS duration_seconds, trx_rows_locked, trx_rows_modified, trx_mysql_thread_id FROM information_schema.INNODB_TRX WHERE trx_state = 'LOCK WAIT' OR TIMESTAMPDIFF(SECOND, trx_started, NOW()) > 600 ORDER BY trx_started ASC"}	{"condition": "row_count > 0", "description": "Transactions in LOCK WAIT state or running over 10 minutes indicate stuck batch connections"}	{"threshold_seconds": 600}	2026-05-11 22:17:39.229791
