14101	mariadb	query	Check MySQL memory usage	{"sql": "SELECT (SELECT SUM(CURRENT_NUMBER_OF_BYTES_USED) / 1024 / 1024 FROM performance_schema.memory_summary_global_by_event_name) AS total_mysql_mb, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'innodb_buffer_pool_size') / 1024 / 1024 AS buffer_pool_mb, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current_connections"}	{"condition": "total_mysql_mb > buffer_pool_mb * 1.5", "description": "Total MySQL memory significantly exceeding buffer pool indicates per-connection memory pressure"}	\N	2026-05-11 22:17:39.229791
14103	mariadb	query	Find queries with full table scans and high execution count	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR AS exec_count, SUM_ROWS_EXAMINED AS total_rows_examined, SUM_ROWS_SENT AS total_rows_sent, ROUND(SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0), 0) AS examine_to_send_ratio, ROUND(SUM_TIMER_WAIT / 1000000000000, 2) AS total_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_NO_INDEX_USED > 0 AND COUNT_STAR > 100 AND SCHEMA_NAME IS NOT NULL ORDER BY SUM_TIMER_WAIT DESC LIMIT 20"}	{"condition": "examine_to_send_ratio > 100", "description": "Examining 100x more rows than returned indicates full table scans with poor selectivity"}	{"threshold_ratio": 100}	2026-05-11 22:17:39.229791
14104	mariadb	query	Check global select scan statistics	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Select_scan') AS full_table_scans, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Select_range') AS range_scans, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_read_rnd_next') AS seq_reads"}	{"condition": "full_table_scans > range_scans", "description": "More full table scans than range scans confirms inefficient access patterns"}	\N	2026-05-11 22:17:39.229791
14105	mariadb	query	Find top CPU-consuming queries by total execution time	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR AS exec_count, ROUND(SUM_TIMER_WAIT / 1000000000000, 2) AS total_seconds, ROUND(AVG_TIMER_WAIT / 1000000000, 2) AS avg_ms, SUM_ROWS_EXAMINED, SUM_ROWS_SENT FROM performance_schema.events_statements_summary_by_digest WHERE SCHEMA_NAME IS NOT NULL ORDER BY SUM_TIMER_WAIT DESC LIMIT 20"}	{"condition": "exec_count > 1000 AND total_seconds > 60", "description": "Queries with 1000+ executions and 60+ seconds total time are significant CPU consumers"}	{"threshold_executions": 1000, "threshold_total_seconds": 60}	2026-05-11 22:17:39.229791
