14107	mariadb	query	Find queries with highest rows examined	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, SUM_NO_INDEX_USED, SUM_NO_GOOD_INDEX_USED, ROUND(SUM_TIMER_WAIT / 1000000000000, 2) AS total_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_ROWS_EXAMINED > 1000000 AND SCHEMA_NAME IS NOT NULL ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 20"}	{"condition": "SUM_ROWS_EXAMINED > 1000000", "description": "Queries examining over 1 million rows indicate full table scans consuming CPU"}	{"threshold_rows": 1000000}	2026-05-11 22:17:39.229791
14108	mariadb	query	Check handler read statistics for sequential access pattern	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_read_rnd_next') AS seq_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_read_key') AS index_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_read_first') AS first_reads"}	{"condition": "seq_reads > index_reads * 10", "description": "Sequential reads far exceeding index reads confirms full table scan pattern"}	{"threshold_ratio": 10}	2026-05-11 22:17:39.229791
14109	mariadb	query	Find queries without good index usage	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_NO_INDEX_USED, SUM_NO_GOOD_INDEX_USED, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_TIMER_WAIT / 1000000000000, 2) AS total_seconds FROM performance_schema.events_statements_summary_by_digest WHERE (SUM_NO_INDEX_USED > 0 OR SUM_NO_GOOD_INDEX_USED > 0) AND COUNT_STAR > 50 AND SCHEMA_NAME IS NOT NULL ORDER BY SUM_TIMER_WAIT DESC LIMIT 20"}	{"condition": "row_count > 5", "description": "Multiple frequently-executed queries without index usage indicates missing indexes"}	{"threshold_queries": 5}	2026-05-11 22:17:39.229791
14110	mariadb	query	Check tables with potential missing indexes	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb, (SELECT COUNT(*) FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME AND s.SEQ_IN_INDEX = 1) AS index_count FROM information_schema.TABLES t WHERE ENGINE = 'InnoDB' AND TABLE_ROWS > 10000 AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY TABLE_ROWS DESC LIMIT 20"}	{"condition": "index_count <= 1", "description": "Large tables with only the PRIMARY index are candidates for missing secondary indexes"}	\N	2026-05-11 22:17:39.229791
