14112	mariadb	query	Check for queries with poor row estimate accuracy	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0), 0) AS examine_to_send_ratio FROM performance_schema.events_statements_summary_by_digest WHERE SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0) > 1000 AND COUNT_STAR > 10 AND SCHEMA_NAME IS NOT NULL ORDER BY examine_to_send_ratio DESC LIMIT 10"}	{"condition": "examine_to_send_ratio > 1000", "description": "Extreme examine-to-send ratio suggests optimizer choosing wrong plan due to stale statistics"}	{"threshold_ratio": 1000}	2026-05-11 22:17:39.229791
14113	mariadb	query	Find indexes with low cardinality relative to table size	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.SEQ_IN_INDEX = 1 AND t.TABLE_ROWS > 10000 AND s.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND s.CARDINALITY < t.TABLE_ROWS * 0.05 AND s.INDEX_NAME != 'PRIMARY' ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "selectivity_pct < 5", "description": "Indexes with less than 5% selectivity return too many rows to be useful"}	{"threshold_selectivity_pct": 5}	2026-05-11 22:17:39.229791
14114	mariadb	query	Check for queries using these low-selectivity indexes	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0), 0) AS examine_ratio FROM performance_schema.events_statements_summary_by_digest WHERE SUM_NO_GOOD_INDEX_USED > 0 AND COUNT_STAR > 10 AND SCHEMA_NAME IS NOT NULL ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10"}	{"condition": "examine_ratio > 100", "description": "High row examination ratio with index usage confirms non-selective index overhead"}	{"threshold_ratio": 100}	2026-05-11 22:17:39.229791
14117	mariadb	query	Find queries with type conversion warnings	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_WARNINGS, SUM_ROWS_EXAMINED, SUM_NO_INDEX_USED, ROUND(SUM_TIMER_WAIT / 1000000000000, 2) AS total_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_WARNINGS > 0 AND SUM_NO_INDEX_USED > 0 AND COUNT_STAR > 10 AND SCHEMA_NAME IS NOT NULL ORDER BY SUM_TIMER_WAIT DESC LIMIT 20"}	{"condition": "row_count > 0 AND SUM_WARNINGS > 0", "description": "Queries with warnings and no index usage may indicate implicit type conversion"}	\N	2026-05-11 22:17:39.229791
14118	mariadb	query	Check for common type mismatch patterns in column definitions	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME, DATA_TYPE, COLUMN_TYPE FROM information_schema.COLUMNS WHERE DATA_TYPE IN ('varchar', 'char') AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND COLUMN_NAME IN (SELECT COLUMN_NAME FROM information_schema.STATISTICS WHERE INDEX_NAME != 'PRIMARY' AND SEQ_IN_INDEX = 1 AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys')) LIMIT 30"}	{"condition": "row_count > 0", "description": "Indexed VARCHAR/CHAR columns are common targets for implicit conversion when compared to integers"}	\N	2026-05-11 22:17:39.229791
14119	mariadb	query	Check stored function call frequency	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_call_procedure') AS procedure_calls, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Queries') AS total_queries"}	{"condition": "procedure_calls > total_queries * 0.1", "description": "Stored procedure calls exceeding 10% of total queries indicates heavy function usage"}	{"threshold_pct": 10}	2026-05-11 22:17:39.229791
14120	mariadb	query	Find queries with high per-row processing cost	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_TIMER_WAIT / 1000000000 / NULLIF(SUM_ROWS_SENT, 0), 2) AS ms_per_row_sent FROM performance_schema.events_statements_summary_by_digest WHERE SUM_ROWS_SENT > 0 AND COUNT_STAR > 10 AND SCHEMA_NAME IS NOT NULL ORDER BY ms_per_row_sent DESC LIMIT 20"}	{"condition": "ms_per_row_sent > 10", "description": "More than 10ms per row returned suggests per-row function call overhead"}	{"threshold_ms": 10}	2026-05-11 22:17:39.229791
14121	mariadb	query	Check for high cursor fetch operations	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_stmt_fetch') AS cursor_fetches, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_stmt_execute') AS stmt_executes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Queries') AS total_queries"}	{"condition": "cursor_fetches > total_queries * 0.05", "description": "Cursor fetches exceeding 5% of total queries indicates cursor-heavy processing"}	{"threshold_pct": 5}	2026-05-11 22:17:39.229791
14122	mariadb	query	Find currently active cursor-based queries	{"sql": "SELECT p.ID, p.USER, p.HOST, p.DB, p.TIME, p.STATE, LEFT(p.INFO, 200) AS query_text FROM information_schema.PROCESSLIST p WHERE p.STATE LIKE '%Sending%' OR p.STATE LIKE '%executing%' AND p.TIME > 10 ORDER BY p.TIME DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Long-running queries in executing state may be cursor-based procedures"}	{"threshold_seconds": 10}	2026-05-11 22:17:39.229791
