14125	mariadb	query	Check sort spill statistics	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_merge_passes') AS sort_merge_passes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_rows') AS sort_rows, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_disk_tables') AS disk_tmp_tables, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_tables') AS total_tmp_tables"}	{"condition": "sort_merge_passes > 1000 OR disk_tmp_tables > total_tmp_tables * 0.25", "description": "High sort merge passes or disk temp tables indicate sort/hash spill to disk"}	{"threshold_disk_pct": 25, "threshold_merge_passes": 1000}	2026-05-11 22:17:39.229791
14126	mariadb	config_check	Check sort buffer and temp table memory limits	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME IN ('sort_buffer_size', 'tmp_table_size', 'max_heap_table_size', 'join_buffer_size')"}	{"condition": "sort_buffer_size < 2097152", "description": "Sort buffer under 2MB may cause frequent sort spills to disk"}	{"threshold_bytes": 2097152}	2026-05-11 22:17:39.229791
14127	mariadb	config_check	Check buffer pool size relative to data size	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'innodb_buffer_pool_size') / 1024 / 1024 / 1024 AS pool_gb, (SELECT SUM(DATA_LENGTH + INDEX_LENGTH) / 1024 / 1024 / 1024 FROM information_schema.TABLES WHERE ENGINE = 'InnoDB') AS data_gb"}	{"condition": "pool_gb < data_gb * 0.5", "description": "Buffer pool smaller than half the total data size is likely insufficient"}	\N	2026-05-11 22:17:39.229791
14128	mariadb	query	Check table fragmentation levels	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb, ROUND(INDEX_LENGTH / 1024 / 1024, 2) AS index_mb, ROUND(DATA_FREE / 1024 / 1024, 2) AS free_mb, ROUND(DATA_FREE / (DATA_LENGTH + INDEX_LENGTH + DATA_FREE) * 100, 1) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND DATA_LENGTH > 10485760 AND DATA_FREE > 10485760 ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "fragmentation_pct > 20", "description": "Tables with over 20% free space have significant fragmentation causing extra page reads"}	{"threshold_pct": 20}	2026-05-11 22:17:39.229791
