14130	mariadb	query	Check for long-running transactions preventing purge	{"sql": "SELECT COUNT(*) AS old_transactions, MIN(TIMESTAMPDIFF(SECOND, trx_started, NOW())) AS min_age_seconds FROM information_schema.INNODB_TRX WHERE TIMESTAMPDIFF(SECOND, trx_started, NOW()) > 300"}	{"condition": "old_transactions > 0", "description": "Long-running transactions preventing purge from cleaning dead rows"}	{"threshold_seconds": 300}	2026-05-11 22:17:39.229791
14131	mariadb	query	Check InnoDB background thread activity	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_flushed') AS pages_flushed, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_os_log_fsyncs') AS log_fsyncs, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_fsyncs') AS data_fsyncs, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'trx_rseg_history_len') AS history_len"}	{"condition": "pages_flushed > 100000 AND history_len > 5000", "description": "High page flush rate with purge backlog indicates competing background work"}	{"threshold_flushed": 100000, "threshold_history": 5000}	2026-05-11 22:17:39.229791
14132	mariadb	config_check	Check background thread configuration	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME IN ('innodb_purge_threads', 'innodb_page_cleaners', 'innodb_io_capacity', 'innodb_io_capacity_max')"}	{"condition": "innodb_io_capacity > 2000", "description": "High I/O capacity setting allows aggressive background flushing that competes with queries"}	{"threshold_io_capacity": 2000}	2026-05-11 22:17:39.229791
14133	mariadb	query	Check connection creation rate	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS total_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') AS uptime, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connections') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') AS DECIMAL), 1) AS conn_per_sec, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Queries') AS total_queries"}	{"condition": "conn_per_sec > 20", "description": "More than 20 connections per second indicates excessive connection churn"}	{"threshold_per_second": 20}	2026-05-11 22:17:39.229791
