14136	mariadb	query	Check AHI contention via wait events	{"sql": "SELECT EVENT_NAME, COUNT_STAR, SUM_TIMER_WAIT / 1000000000 AS total_wait_ms FROM performance_schema.events_waits_summary_global_by_event_name WHERE EVENT_NAME LIKE '%hash%' OR EVENT_NAME LIKE '%btr0sea%' ORDER BY SUM_TIMER_WAIT DESC LIMIT 5"}	{"condition": "total_wait_ms > 5000", "description": "Significant AHI-related wait time confirms latch contention"}	{"threshold_wait_ms": 5000}	2026-05-11 22:17:39.229791
14137	mariadb	query	Check AHI hit ratio and partition configuration	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_adaptive_hash_searches') AS ahi_hits, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_adaptive_hash_searches_btree') AS btree_searches, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'innodb_adaptive_hash_index_parts') AS ahi_parts"}	{"condition": "ahi_parts < 8", "description": "Low AHI partition count increases contention. Default is 8, increase for high concurrency."}	{"threshold_parts": 8}	2026-05-11 22:17:39.229791
14138	mariadb	query	Check running threads vs available capacity	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_running') AS running_threads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS connected_threads, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'innodb_thread_concurrency') AS thread_concurrency"}	{"condition": "running_threads > 32", "description": "More than 32 running threads on most systems causes excessive context switching"}	{"threshold_running": 32}	2026-05-11 22:17:39.229791
