14152	mariadb	query	Check temporary table creation frequency	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_tables') AS tmp_tables, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_disk_tables') AS tmp_disk_tables, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Queries') AS total_queries, ROUND(CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_tables') AS DECIMAL) / CAST((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Queries') AS DECIMAL) * 100, 1) AS tmp_table_pct"}	{"condition": "tmp_table_pct > 20", "description": "Temporary tables created for over 20% of queries indicates heavy temp table usage"}	{"threshold_pct": 20}	2026-05-11 22:17:39.229791
