14167	mariadb	query	Find queries with high per-execution overhead	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, ROUND(AVG_TIMER_WAIT / 1000000000, 2) AS avg_total_ms, ROUND(SUM_ROWS_EXAMINED / NULLIF(COUNT_STAR, 0), 0) AS avg_rows_examined FROM performance_schema.events_statements_summary_by_digest WHERE COUNT_STAR > 100 AND AVG_TIMER_WAIT / 1000000000 > 10 AND SUM_ROWS_EXAMINED / NULLIF(COUNT_STAR, 0) < 100 AND SCHEMA_NAME IS NOT NULL ORDER BY AVG_TIMER_WAIT DESC LIMIT 20"}	{"condition": "avg_total_ms > 10 AND avg_rows_examined < 100", "description": "Queries taking >10ms but examining <100 rows have parse/optimize overhead exceeding execution"}	{"threshold_ms": 10, "threshold_rows": 100}	2026-05-11 22:17:39.229791
14168	mariadb	config_check	Check optimizer search depth configuration	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME IN ('optimizer_search_depth', 'optimizer_prune_level', 'optimizer_switch')"}	{"condition": "optimizer_search_depth > 10", "description": "High optimizer search depth increases optimization time for complex queries"}	{"threshold_depth": 10}	2026-05-11 22:17:39.229791
14169	mariadb	query	Measure current commit rate per second	{"sql": "SELECT gs1.VARIABLE_VALUE AS commits_now, SLEEP(1), gs2.VARIABLE_VALUE AS commits_after, (gs2.VARIABLE_VALUE - gs1.VARIABLE_VALUE) AS commits_per_sec FROM (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_commit') gs1, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_commit') gs2"}	{"condition": "commits_per_sec > threshold", "description": "High commit rate indicates many small transactions"}	{"threshold": 1000}	2026-05-11 22:17:39.229791
