14173	mariadb	query	Check log write wait events in performance_schema	{"sql": "SELECT EVENT_NAME, COUNT_STAR, SUM_TIMER_WAIT / 1000000000 AS total_wait_ms, AVG_TIMER_WAIT / 1000000000 AS avg_wait_ms FROM performance_schema.events_waits_summary_global_by_event_name WHERE EVENT_NAME LIKE '%innodb_log%' OR EVENT_NAME LIKE '%log_sys%' ORDER BY SUM_TIMER_WAIT DESC"}	{"condition": "avg_wait_ms > threshold_ms", "description": "High average wait time on log-related events confirms slow log writes"}	{"threshold_ms": 5}	2026-05-11 22:17:39.229791
14174	mariadb	config_check	Check InnoDB log buffer size setting	{"sql": "SELECT @@innodb_log_buffer_size / 1048576 AS log_buffer_mb"}	{"condition": "log_buffer_mb < threshold_mb", "description": "Log buffer smaller than recommended size for write-heavy workloads"}	{"threshold_mb": 64}	2026-05-11 22:17:39.229791
