14245	mariadb	query	Find small tables with indexes that generate full scans	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, t.TABLE_ROWS, t.DATA_LENGTH / 1024 AS data_kb, COUNT(DISTINCT s.INDEX_NAME) AS index_count FROM information_schema.TABLES t LEFT JOIN information_schema.STATISTICS s ON t.TABLE_SCHEMA = s.TABLE_SCHEMA AND t.TABLE_NAME = s.TABLE_NAME WHERE t.ENGINE = 'InnoDB' AND t.TABLE_ROWS < :row_threshold AND t.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY t.TABLE_SCHEMA, t.TABLE_NAME, t.TABLE_ROWS, t.DATA_LENGTH HAVING index_count > 1 ORDER BY t.TABLE_ROWS ASC LIMIT 20"}	{"condition": "small_tables_with_indexes", "description": "Small tables with indexes where optimizer may choose full scan"}	{"row_threshold": 1000}	2026-05-11 22:17:39.229791
14246	mariadb	query	Find indexes with low cardinality	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE t.TABLE_ROWS > :min_rows AND s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) < :selectivity_threshold AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with very low selectivity (few distinct values relative to table size)"}	{"min_rows": 10000, "selectivity_threshold": 0.01}	2026-05-11 22:17:39.229791
