14269	mariadb	query	Check for unused composite indexes	{"sql": "SELECT OBJECT_SCHEMA, OBJECT_NAME, INDEX_NAME, COUNT_READ, COUNT_WRITE FROM performance_schema.table_io_waits_summary_by_index_usage WHERE INDEX_NAME IS NOT NULL AND COUNT_READ = 0 AND OBJECT_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY OBJECT_SCHEMA, OBJECT_NAME"}	{"condition": "composite_indexes_with_zero_reads", "description": "Composite indexes with zero reads suggest queries do not use the leading columns"}	\N	2026-05-11 22:17:39.229791
14270	mariadb	query	Find full-text indexes	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, GROUP_CONCAT(COLUMN_NAME) AS columns FROM information_schema.STATISTICS WHERE INDEX_TYPE = 'FULLTEXT' AND TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME"}	{"condition": "row_count > 0", "description": "Full-text indexes exist on the server"}	\N	2026-05-11 22:17:39.229791
14271	mariadb	query	Check for LIKE queries on tables with full-text indexes	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%LIKE%' AND SUM_ROWS_EXAMINED > :row_threshold AND COUNT_STAR > :min_executions ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10"}	{"condition": "like_queries_on_fulltext_tables", "description": "LIKE queries performing full scans on tables that have full-text indexes confirms the FTS index is unused"}	{"row_threshold": 10000, "min_executions": 5}	2026-05-11 22:17:39.229791
14272	mariadb	query	Find indexes with zero or very low cardinality estimates	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.CARDINALITY IS NULL OR (t.TABLE_ROWS > 1000 AND s.CARDINALITY = 0) AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY t.TABLE_ROWS DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with NULL or zero cardinality on non-empty tables have stale statistics"}	\N	2026-05-11 22:17:39.229791
