14274	mariadb	query	Find indexes on nearly empty tables	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, t.TABLE_ROWS, COUNT(DISTINCT s.INDEX_NAME) AS index_count FROM information_schema.TABLES t JOIN information_schema.STATISTICS s ON t.TABLE_SCHEMA = s.TABLE_SCHEMA AND t.TABLE_NAME = s.TABLE_NAME WHERE t.TABLE_ROWS < :row_threshold AND s.INDEX_NAME != 'PRIMARY' AND t.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY t.TABLE_SCHEMA, t.TABLE_NAME, t.TABLE_ROWS HAVING index_count > 0 ORDER BY t.TABLE_ROWS ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Non-primary indexes exist on nearly empty tables"}	{"row_threshold": 100}	2026-05-11 22:17:39.229791
14275	mariadb	query	Find tables with UUID/binary primary keys	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH, c.COLUMN_TYPE FROM information_schema.COLUMNS c JOIN information_schema.STATISTICS s ON c.TABLE_SCHEMA = s.TABLE_SCHEMA AND c.TABLE_NAME = s.TABLE_NAME AND c.COLUMN_NAME = s.COLUMN_NAME WHERE s.INDEX_NAME = 'PRIMARY' AND (c.DATA_TYPE IN ('binary', 'varbinary') AND c.CHARACTER_MAXIMUM_LENGTH = 16 OR c.DATA_TYPE = 'char' AND c.CHARACTER_MAXIMUM_LENGTH = 36 OR c.DATA_TYPE = 'varchar' AND c.CHARACTER_MAXIMUM_LENGTH = 36) AND c.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema')"}	{"condition": "row_count > 0", "description": "Tables with UUID-sized primary keys found"}	\N	2026-05-11 22:17:39.229791
14276	mariadb	query	Check InnoDB data-to-index ratio indicating fragmentation	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, DATA_LENGTH / 1048576 AS data_mb, INDEX_LENGTH / 1048576 AS index_mb, DATA_FREE / 1048576 AS free_mb, ROUND(DATA_FREE / NULLIF(DATA_LENGTH, 0) * 100, 2) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND DATA_FREE > :min_free_bytes ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "fragmentation_pct > threshold", "description": "High DATA_FREE relative to DATA_LENGTH indicates page splits from random inserts"}	{"threshold": 20, "min_free_bytes": 1048576}	2026-05-11 22:17:39.229791
14277	mariadb	query	Find tables with high free space indicating delete fragmentation	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, DATA_LENGTH / 1048576 AS data_mb, DATA_FREE / 1048576 AS free_mb, ROUND(DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) * 100, 2) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) > :threshold ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with high free space percentage indicating fragmentation from deletes"}	{"threshold": 0.2}	2026-05-11 22:17:39.229791
