14279	mariadb	query	Check handler update rate	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME IN ('Handler_update', 'Handler_write', 'Handler_delete')"}	{"condition": "Handler_update > threshold", "description": "High update rate increases likelihood of indexed column modifications causing fragmentation"}	{"threshold": 100000}	2026-05-11 22:17:39.229791
14280	mariadb	query	Check table fragmentation on frequently updated tables	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, DATA_LENGTH / 1048576 AS data_mb, DATA_FREE / 1048576 AS free_mb, ROUND(DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) * 100, 2) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND DATA_FREE > 1048576 AND TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "fragmentation_pct > threshold", "description": "High fragmentation on frequently updated tables confirms update-driven page splits"}	{"threshold": 15}	2026-05-11 22:17:39.229791
14281	mariadb	query	Check for tables with high insert rate and fragmentation	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, t.TABLE_ROWS, t.DATA_FREE / 1048576 AS free_mb, ROUND(t.DATA_FREE / NULLIF(t.DATA_LENGTH + t.DATA_FREE, 0) * 100, 2) AS fragmentation_pct, w.COUNT_WRITE AS write_ops FROM information_schema.TABLES t LEFT JOIN performance_schema.table_io_waits_summary_by_table w ON t.TABLE_SCHEMA = w.OBJECT_SCHEMA AND t.TABLE_NAME = w.OBJECT_NAME WHERE t.ENGINE = 'InnoDB' AND t.DATA_FREE > :min_free AND w.COUNT_WRITE > :min_writes AND t.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "high_fragmentation_with_high_writes", "description": "Tables with both high write activity and high fragmentation suggest mixed insert patterns"}	{"min_free": 10485760, "min_writes": 10000}	2026-05-11 22:17:39.229791
14282	mariadb	query	Find tables with many nullable columns and high update rate	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, COUNT(*) AS nullable_columns, t.TABLE_ROWS FROM information_schema.COLUMNS c JOIN information_schema.TABLES t ON c.TABLE_SCHEMA = t.TABLE_SCHEMA AND c.TABLE_NAME = t.TABLE_NAME WHERE c.IS_NULLABLE = 'YES' AND t.ENGINE = 'InnoDB' AND t.TABLE_ROWS > :min_rows AND c.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY c.TABLE_SCHEMA, c.TABLE_NAME, t.TABLE_ROWS HAVING nullable_columns > :nullable_threshold ORDER BY nullable_columns DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with many nullable columns are susceptible to row expansion"}	{"min_rows": 10000, "nullable_threshold": 5}	2026-05-11 22:17:39.229791
