14284	mariadb	query	Find tables with large variable-length columns	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, COUNT(*) AS varchar_count, SUM(c.CHARACTER_MAXIMUM_LENGTH) AS total_max_length FROM information_schema.COLUMNS c JOIN information_schema.TABLES t ON c.TABLE_SCHEMA = t.TABLE_SCHEMA AND c.TABLE_NAME = t.TABLE_NAME WHERE c.DATA_TYPE IN ('varchar', 'varbinary', 'text', 'blob') AND t.ENGINE = 'InnoDB' AND t.TABLE_ROWS > :min_rows AND c.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY c.TABLE_SCHEMA, c.TABLE_NAME HAVING varchar_count > :varchar_threshold ORDER BY total_max_length DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with many variable-length columns susceptible to row expansion"}	{"min_rows": 10000, "varchar_threshold": 3}	2026-05-11 22:17:39.229791
14285	mariadb	query	Check fragmentation level	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, DATA_LENGTH / 1048576 AS data_mb, DATA_FREE / 1048576 AS free_mb, ROUND(DATA_FREE / NULLIF(DATA_LENGTH, 0) * 100, 2) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND DATA_FREE / NULLIF(DATA_LENGTH, 0) > :threshold AND TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "high_fragmentation", "description": "High fragmentation on tables with variable-length columns confirms update-driven expansion"}	{"threshold": 0.15}	2026-05-11 22:17:39.229791
14286	mariadb	query	Find non-sequential primary keys	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE, c.COLUMN_TYPE, c.EXTRA FROM information_schema.COLUMNS c JOIN information_schema.STATISTICS s ON c.TABLE_SCHEMA = s.TABLE_SCHEMA AND c.TABLE_NAME = s.TABLE_NAME AND c.COLUMN_NAME = s.COLUMN_NAME WHERE s.INDEX_NAME = 'PRIMARY' AND c.EXTRA NOT LIKE '%auto_increment%' AND c.DATA_TYPE NOT IN ('int', 'bigint', 'smallint', 'tinyint', 'mediumint') AND c.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema')"}	{"condition": "row_count > 0", "description": "Primary keys on non-integer, non-auto-increment columns found"}	\N	2026-05-11 22:17:39.229791
14287	mariadb	query	Check fragmentation on those tables	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, DATA_FREE / 1048576 AS free_mb, ROUND(DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) * 100, 2) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND DATA_FREE > :min_free ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "fragmentation_pct > threshold", "description": "High fragmentation on tables with non-sequential PKs confirms the issue"}	{"min_free": 1048576, "threshold": 15}	2026-05-11 22:17:39.229791
14288	mariadb	query	Find fragmented tables	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS, DATA_LENGTH / 1048576 AS data_mb, DATA_FREE / 1048576 AS free_mb, ROUND(DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) * 100, 2) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND DATA_FREE > :min_free_bytes AND DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) > :threshold AND TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY fragmentation_pct DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with significant fragmentation indicating no maintenance"}	{"threshold": 0.2, "min_free_bytes": 10485760}	2026-05-11 22:17:39.229791
