14291	mariadb	query	Find duplicate indexes with same column structure	{"sql": "SELECT s1.TABLE_SCHEMA, s1.TABLE_NAME, s1.INDEX_NAME AS index1, s2.INDEX_NAME AS index2, GROUP_CONCAT(s1.COLUMN_NAME ORDER BY s1.SEQ_IN_INDEX) AS columns FROM information_schema.STATISTICS s1 JOIN information_schema.STATISTICS s2 ON s1.TABLE_SCHEMA = s2.TABLE_SCHEMA AND s1.TABLE_NAME = s2.TABLE_NAME AND s1.SEQ_IN_INDEX = s2.SEQ_IN_INDEX AND s1.COLUMN_NAME = s2.COLUMN_NAME AND s1.INDEX_NAME < s2.INDEX_NAME WHERE s1.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY s1.TABLE_SCHEMA, s1.TABLE_NAME, s1.INDEX_NAME, s2.INDEX_NAME HAVING COUNT(*) = (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = s1.TABLE_SCHEMA AND TABLE_NAME = s1.TABLE_NAME AND INDEX_NAME = s1.INDEX_NAME) AND COUNT(*) = (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = s1.TABLE_SCHEMA AND TABLE_NAME = s1.TABLE_NAME AND INDEX_NAME = s2.INDEX_NAME)"}	{"condition": "row_count > 0", "description": "Exact duplicate indexes found on the same table"}	\N	2026-05-11 22:17:39.229791
14292	mariadb	query	Find indexes that are prefixes of other indexes	{"sql": "SELECT r.table_schema, r.table_name, r.redundant_index_name, r.redundant_index_columns, r.dominant_index_name, r.dominant_index_columns FROM sys.schema_redundant_indexes r ORDER BY r.table_schema, r.table_name"}	{"condition": "row_count > 0", "description": "Redundant indexes found where one is a prefix of another"}	\N	2026-05-11 22:17:39.229791
14293	mariadb	query	Find narrow indexes that are prefixes of wider indexes	{"sql": "SELECT r.table_schema, r.table_name, r.redundant_index_name, r.redundant_index_columns, r.dominant_index_name, r.dominant_index_columns, r.sql_drop_index FROM sys.schema_redundant_indexes r WHERE LENGTH(r.redundant_index_columns) - LENGTH(REPLACE(r.redundant_index_columns, ',', '')) < LENGTH(r.dominant_index_columns) - LENGTH(REPLACE(r.dominant_index_columns, ',', '')) ORDER BY r.table_schema, r.table_name"}	{"condition": "row_count > 0", "description": "Narrow indexes found that are strict subsets of wider indexes"}	\N	2026-05-11 22:17:39.229791
14294	mariadb	query	Find indexes with identical column sets but different names	{"sql": "SELECT s1.TABLE_SCHEMA, s1.TABLE_NAME, s1.INDEX_NAME AS index1, s2.INDEX_NAME AS index2 FROM (SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME) s1 JOIN (SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS cols FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME) s2 ON s1.TABLE_SCHEMA = s2.TABLE_SCHEMA AND s1.TABLE_NAME = s2.TABLE_NAME AND s1.cols = s2.cols AND s1.INDEX_NAME < s2.INDEX_NAME"}	{"condition": "row_count > 0", "description": "Duplicate indexes with different names found"}	\N	2026-05-11 22:17:39.229791
14295	mariadb	query	Find indexes with test/backup naming patterns	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS columns FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND (INDEX_NAME LIKE '%test%' OR INDEX_NAME LIKE '%tmp%' OR INDEX_NAME LIKE '%temp%' OR INDEX_NAME LIKE '%backup%' OR INDEX_NAME LIKE '%old%' OR INDEX_NAME LIKE '%copy%' OR INDEX_NAME LIKE '%bak%' OR INDEX_NAME LIKE '%v2%' OR INDEX_NAME LIKE '%new%') GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME"}	{"condition": "row_count > 0", "description": "Indexes with test/backup naming conventions found"}	\N	2026-05-11 22:17:39.229791
14296	mariadb	query	Find redundant indexes using sys schema	{"sql": "SELECT table_schema, table_name, redundant_index_name, redundant_index_columns, dominant_index_name, dominant_index_columns, sql_drop_index FROM sys.schema_redundant_indexes ORDER BY table_schema, table_name"}	{"condition": "row_count > 0", "description": "Redundant indexes found — may be orphaned from migration"}	\N	2026-05-11 22:17:39.229791
14297	mariadb	query	Check for migration-pattern index names	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND (INDEX_NAME LIKE 'idx_%_%_old' OR INDEX_NAME LIKE '%_migrated' OR INDEX_NAME LIKE '%_pre_%' OR INDEX_NAME LIKE '%_deprecated%' OR INDEX_NAME REGEXP '[0-9]{8,}') GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME"}	{"condition": "migration_indexes_found", "description": "Indexes with migration-related naming patterns suggest incomplete cleanup"}	\N	2026-05-11 22:17:39.229791
14298	mariadb	query	Find unique indexes that overlap with primary key	{"sql": "SELECT s1.TABLE_SCHEMA, s1.TABLE_NAME, s1.INDEX_NAME AS unique_index, s1.COLUMN_NAME AS unique_col, s2.INDEX_NAME AS pk_index, s2.COLUMN_NAME AS pk_col FROM information_schema.STATISTICS s1 JOIN information_schema.STATISTICS s2 ON s1.TABLE_SCHEMA = s2.TABLE_SCHEMA AND s1.TABLE_NAME = s2.TABLE_NAME AND s1.COLUMN_NAME = s2.COLUMN_NAME WHERE s1.NON_UNIQUE = 0 AND s1.INDEX_NAME != 'PRIMARY' AND s2.INDEX_NAME = 'PRIMARY' AND s1.SEQ_IN_INDEX = 1 AND s1.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema')"}	{"condition": "row_count > 0", "description": "Unique indexes found that overlap with the primary key"}	\N	2026-05-11 22:17:39.229791
14299	mariadb	query	Find foreign key columns with multiple supporting indexes	{"sql": "SELECT kcu.TABLE_SCHEMA, kcu.TABLE_NAME, kcu.COLUMN_NAME, kcu.CONSTRAINT_NAME, COUNT(DISTINCT s.INDEX_NAME) AS index_count, GROUP_CONCAT(DISTINCT s.INDEX_NAME) AS indexes FROM information_schema.KEY_COLUMN_USAGE kcu JOIN information_schema.STATISTICS s ON kcu.TABLE_SCHEMA = s.TABLE_SCHEMA AND kcu.TABLE_NAME = s.TABLE_NAME AND kcu.COLUMN_NAME = s.COLUMN_NAME WHERE kcu.REFERENCED_TABLE_NAME IS NOT NULL AND kcu.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY kcu.TABLE_SCHEMA, kcu.TABLE_NAME, kcu.COLUMN_NAME, kcu.CONSTRAINT_NAME HAVING index_count > 1"}	{"condition": "row_count > 0", "description": "Foreign key columns with multiple supporting indexes — only one is needed"}	\N	2026-05-11 22:17:39.229791
14300	mariadb	query	Find non-constraint indexes duplicating constraint indexes	{"sql": "SELECT r.table_schema, r.table_name, r.redundant_index_name, r.redundant_index_columns, r.dominant_index_name, r.dominant_index_columns FROM sys.schema_redundant_indexes r WHERE r.dominant_index_name = 'PRIMARY' OR r.dominant_index_name IN (SELECT INDEX_NAME FROM information_schema.STATISTICS WHERE NON_UNIQUE = 0 AND TABLE_SCHEMA = r.table_schema AND TABLE_NAME = r.table_name)"}	{"condition": "row_count > 0", "description": "Manual indexes found that duplicate auto-created constraint indexes"}	\N	2026-05-11 22:17:39.229791
14309	mariadb	query	Find tables with potentially stale statistics	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, t.TABLE_ROWS, t.UPDATE_TIME, ist.LAST_UPDATE, ist.N_ROWS AS stats_rows FROM information_schema.TABLES t LEFT JOIN mysql.innodb_table_stats ist ON t.TABLE_SCHEMA = ist.database_name AND t.TABLE_NAME = ist.table_name WHERE t.ENGINE = 'InnoDB' AND t.TABLE_ROWS > :min_rows AND t.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND (ist.LAST_UPDATE IS NULL OR ist.LAST_UPDATE < DATE_SUB(NOW(), INTERVAL :days DAY)) ORDER BY t.TABLE_ROWS DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with stale InnoDB statistics found"}	{"days": 7, "min_rows": 10000}	2026-05-11 22:17:39.229791
14301	mariadb	query	Find indexes on boolean-like columns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.DATA_TYPE, c.COLUMN_TYPE, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE (c.DATA_TYPE IN ('tinyint', 'bit', 'enum') OR c.COLUMN_TYPE = 'tinyint(1)') AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND t.TABLE_ROWS > :min_rows AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes on boolean/flag columns with very low selectivity found"}	{"min_rows": 10000}	2026-05-11 22:17:39.229791
14302	mariadb	query	Find indexes with very low cardinality on large tables	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.CARDINALITY < :max_cardinality AND t.TABLE_ROWS > :min_rows AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with very few distinct values relative to table size"}	{"min_rows": 10000, "max_cardinality": 300}	2026-05-11 22:17:39.229791
14303	mariadb	query	Find indexes with cardinality under 5	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.DATA_TYPE, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 6) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE s.CARDINALITY < 5 AND t.TABLE_ROWS > :min_rows AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with fewer than 5 distinct values on large tables"}	{"min_rows": 10000}	2026-05-11 22:17:39.229791
14304	mariadb	query	Find indexes on columns with low cardinality and ENUM/status patterns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.COLUMN_TYPE FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE (c.COLUMN_NAME LIKE '%status%' OR c.COLUMN_NAME LIKE '%state%' OR c.COLUMN_NAME LIKE '%type%' OR c.DATA_TYPE = 'enum') AND s.CARDINALITY < :max_cardinality AND t.TABLE_ROWS > :min_rows AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY t.TABLE_ROWS DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Status-type columns with low cardinality indexes found"}	{"min_rows": 10000, "max_cardinality": 20}	2026-05-11 22:17:39.229791
14305	mariadb	query	Find date column indexes with low cardinality relative to row count	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.DATA_TYPE, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.DATA_TYPE IN ('date', 'datetime', 'timestamp') AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND t.TABLE_ROWS > :min_rows AND ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) < :selectivity_threshold AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Date indexes with low selectivity — many rows per date value"}	{"min_rows": 100000, "selectivity_threshold": 1}	2026-05-11 22:17:39.229791
14306	mariadb	query	Find categorical indexes with very low selectivity	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.CARDINALITY < :max_distinct AND t.TABLE_ROWS > :min_rows AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Low-cardinality indexes found with very low selectivity"}	{"min_rows": 50000, "max_distinct": 50}	2026-05-11 22:17:39.229791
14307	mariadb	query	Find composite indexes with low-cardinality leading column	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME AS leading_column, s.CARDINALITY AS leading_cardinality, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS leading_selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.CARDINALITY < :max_cardinality AND t.TABLE_ROWS > :min_rows AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND EXISTS (SELECT 1 FROM information_schema.STATISTICS s2 WHERE s2.TABLE_SCHEMA = s.TABLE_SCHEMA AND s2.TABLE_NAME = s.TABLE_NAME AND s2.INDEX_NAME = s.INDEX_NAME AND s2.SEQ_IN_INDEX > 1) ORDER BY leading_selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Composite indexes with non-selective leading columns found"}	{"min_rows": 10000, "max_cardinality": 10}	2026-05-11 22:17:39.229791
14308	mariadb	query	Find indexes with very low selectivity on large tables	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, t.CREATE_TIME, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME WHERE ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) < :selectivity_threshold AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND t.TABLE_ROWS > :min_rows AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with very low selectivity on mature tables"}	{"min_rows": 100000, "selectivity_threshold": 0.1}	2026-05-11 22:17:39.229791
14310	mariadb	query	Compare stored cardinality with estimated reality	{"sql": "SELECT iis.database_name, iis.table_name, iis.index_name, iis.stat_name, iis.stat_value, iis.last_update FROM mysql.innodb_index_stats iis WHERE iis.stat_name = 'n_diff_pfx01' AND iis.database_name NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY iis.last_update ASC LIMIT 20"}	{"condition": "stale_cardinality_estimates", "description": "Old cardinality estimates may mask actual low selectivity"}	\N	2026-05-11 22:17:39.229791
14311	mariadb	query	Find queries with warnings and poor index usage	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_WARNINGS, SUM_NO_GOOD_INDEX_USED, SUM_ROWS_EXAMINED, SUM_ROWS_SENT FROM performance_schema.events_statements_summary_by_digest WHERE SUM_WARNINGS > 0 AND SUM_NO_GOOD_INDEX_USED > 0 AND COUNT_STAR > :min_executions ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries with type conversion warnings and poor index usage"}	{"min_executions": 5}	2026-05-11 22:17:39.229791
14312	mariadb	query	Find indexed columns with case-insensitive collation	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, c.COLUMN_NAME, c.COLLATION_NAME, s.INDEX_NAME, s.CARDINALITY, t.TABLE_ROWS FROM information_schema.COLUMNS c JOIN information_schema.STATISTICS s ON c.TABLE_SCHEMA = s.TABLE_SCHEMA AND c.TABLE_NAME = s.TABLE_NAME AND c.COLUMN_NAME = s.COLUMN_NAME JOIN information_schema.TABLES t ON c.TABLE_SCHEMA = t.TABLE_SCHEMA AND c.TABLE_NAME = t.TABLE_NAME WHERE c.COLLATION_NAME LIKE '%_ci' AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND t.TABLE_ROWS > :min_rows AND c.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY t.TABLE_ROWS DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexed columns with case-insensitive collation that may reduce selectivity"}	{"min_rows": 10000}	2026-05-11 22:17:39.229791
14313	mariadb	query	Find nullable indexed columns with low cardinality	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, c.IS_NULLABLE, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.IS_NULLABLE = 'YES' AND s.CARDINALITY IS NOT NULL AND t.TABLE_ROWS > :min_rows AND ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 4) < :selectivity_threshold AND s.SEQ_IN_INDEX = 1 AND s.INDEX_NAME != 'PRIMARY' AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY selectivity_pct ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Nullable columns with very low selectivity suggesting high NULL proportion"}	{"min_rows": 10000, "selectivity_threshold": 1}	2026-05-11 22:17:39.229791
14314	mariadb	query	Check write activity on these tables	{"sql": "SELECT OBJECT_SCHEMA, OBJECT_NAME, COUNT_WRITE, COUNT_READ, ROUND(COUNT_WRITE / NULLIF(COUNT_READ, 0), 2) AS write_read_ratio FROM performance_schema.table_io_waits_summary_by_table WHERE OBJECT_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND COUNT_WRITE > :min_writes ORDER BY COUNT_WRITE DESC LIMIT 20"}	{"condition": "high_write_activity", "description": "Write-heavy tables with many indexes confirm over-indexing impact"}	{"min_writes": 10000}	2026-05-11 22:17:39.229791
14315	mariadb	query	Find tables with many single-column indexes	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, COUNT(*) AS single_col_index_count FROM (SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND INDEX_NAME != 'PRIMARY' GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME HAVING COUNT(*) = 1) sub GROUP BY TABLE_SCHEMA, TABLE_NAME HAVING single_col_index_count > :threshold ORDER BY single_col_index_count DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with many single-column indexes suggesting defensive indexing"}	{"threshold": 4}	2026-05-11 22:17:39.229791
14316	mariadb	query	Find tables with multiple unused indexes	{"sql": "SELECT u.OBJECT_SCHEMA, u.OBJECT_NAME, COUNT(*) AS unused_index_count, (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = u.OBJECT_SCHEMA AND TABLE_NAME = u.OBJECT_NAME AND INDEX_NAME != 'PRIMARY') AS total_indexes FROM performance_schema.table_io_waits_summary_by_index_usage u WHERE u.INDEX_NAME IS NOT NULL AND u.COUNT_READ = 0 AND u.OBJECT_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY u.OBJECT_SCHEMA, u.OBJECT_NAME HAVING unused_index_count > :threshold ORDER BY unused_index_count DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with multiple unused indexes confirming historical accumulation"}	{"threshold": 2}	2026-05-11 22:17:39.229791
14317	mariadb	query	Find redundant overlapping indexes	{"sql": "SELECT table_schema, table_name, redundant_index_name, redundant_index_columns, dominant_index_name, dominant_index_columns, sql_drop_index FROM sys.schema_redundant_indexes ORDER BY table_schema, table_name"}	{"condition": "row_count > 0", "description": "Overlapping indexes found that could be consolidated"}	\N	2026-05-11 22:17:39.229791
14318	mariadb	query	Find completely unused indexes with sufficient uptime	{"sql": "SELECT u.OBJECT_SCHEMA, u.OBJECT_NAME, u.INDEX_NAME, u.COUNT_READ, u.COUNT_WRITE, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') / 86400 AS uptime_days FROM performance_schema.table_io_waits_summary_by_index_usage u WHERE u.INDEX_NAME IS NOT NULL AND u.COUNT_READ = 0 AND u.OBJECT_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Uptime') > :min_uptime ORDER BY u.COUNT_WRITE DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with zero reads after extended uptime are likely anticipatory"}	{"min_uptime": 2592000}	2026-05-11 22:17:39.229791
14319	mariadb	query	Find unused indexes on tables with active DML	{"sql": "SELECT u.OBJECT_SCHEMA, u.OBJECT_NAME, u.INDEX_NAME, u.COUNT_READ, u.COUNT_WRITE FROM performance_schema.table_io_waits_summary_by_index_usage u WHERE u.INDEX_NAME IS NOT NULL AND u.COUNT_READ = 0 AND u.COUNT_WRITE > :min_writes AND u.OBJECT_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY u.COUNT_WRITE DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Active tables with never-read indexes suggest decommissioned batch processes"}	{"min_writes": 10000}	2026-05-11 22:17:39.229791
14320	mariadb	query	Find composite indexes with many columns	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, COUNT(*) AS column_count, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS columns FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND INDEX_NAME != 'PRIMARY' GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME HAVING column_count > :threshold ORDER BY column_count DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Wide composite indexes with many columns found"}	{"threshold": 4}	2026-05-11 22:17:39.229791
14321	mariadb	query	Check if foreign key indexes are read	{"sql": "SELECT OBJECT_SCHEMA, OBJECT_NAME, INDEX_NAME, COUNT_READ, COUNT_WRITE FROM performance_schema.table_io_waits_summary_by_index_usage WHERE COUNT_READ = 0 AND INDEX_NAME IS NOT NULL AND OBJECT_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema')"}	{"condition": "fk_indexes_unused_for_reads", "description": "FK indexes with zero reads on rarely-joined tables are unnecessary overhead"}	\N	2026-05-11 22:17:39.229791
14322	mariadb	query	Find index redundancy pairs	{"sql": "SELECT table_schema, table_name, redundant_index_name, redundant_index_columns, dominant_index_name, dominant_index_columns, sql_drop_index FROM sys.schema_redundant_indexes ORDER BY table_schema, table_name"}	{"condition": "row_count > 0", "description": "Redundant index pairs found where wider index covers narrower"}	\N	2026-05-11 22:17:39.229791
14323	mariadb	query	List all unused indexes using sys schema	{"sql": "SELECT * FROM sys.schema_unused_indexes WHERE object_schema NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY object_schema, object_name"}	{"condition": "row_count > threshold", "description": "Multiple unused indexes exist despite available statistics showing non-use"}	{"threshold": 5}	2026-05-11 22:17:39.229791
14324	mariadb	query	Count unused indexes per table	{"sql": "SELECT OBJECT_SCHEMA, OBJECT_NAME, COUNT(*) AS unused_count FROM performance_schema.table_io_waits_summary_by_index_usage WHERE INDEX_NAME IS NOT NULL AND COUNT_READ = 0 AND OBJECT_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY OBJECT_SCHEMA, OBJECT_NAME HAVING COUNT(*) > :threshold ORDER BY unused_count DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with multiple unused indexes indicate no cleanup policy"}	{"threshold": 3}	2026-05-11 22:17:39.229791
14325	mariadb	query	Check for any scheduled maintenance events	{"sql": "SELECT EVENT_SCHEMA, EVENT_NAME, STATUS, LAST_EXECUTED FROM information_schema.EVENTS WHERE EVENT_NAME LIKE '%index%' OR EVENT_NAME LIKE '%maintenance%' OR EVENT_NAME LIKE '%cleanup%'"}	{"condition": "no_maintenance_events", "description": "No scheduled events for index maintenance confirms lack of policy"}	\N	2026-05-11 22:17:39.229791
14326	mariadb	query	Check index to data size ratio	{"sql": "SELECT TABLE_SCHEMA, SUM(DATA_LENGTH) / 1048576 AS total_data_mb, SUM(INDEX_LENGTH) / 1048576 AS total_index_mb, ROUND(SUM(INDEX_LENGTH) / NULLIF(SUM(DATA_LENGTH), 0) * 100, 2) AS index_data_ratio_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY TABLE_SCHEMA ORDER BY index_data_ratio_pct DESC"}	{"condition": "index_data_ratio_pct > threshold", "description": "Index size exceeding data size indicates over-indexing consuming buffer pool"}	{"threshold": 100}	2026-05-11 22:17:39.229791
14327	mariadb	query	Find tables with wide primary keys	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, GROUP_CONCAT(c.COLUMN_NAME ORDER BY s.SEQ_IN_INDEX) AS pk_columns, SUM(CASE WHEN c.DATA_TYPE IN ('char', 'varchar') THEN c.CHARACTER_MAXIMUM_LENGTH WHEN c.DATA_TYPE IN ('binary', 'varbinary') THEN c.CHARACTER_MAXIMUM_LENGTH WHEN c.DATA_TYPE = 'bigint' THEN 8 WHEN c.DATA_TYPE = 'int' THEN 4 ELSE 8 END) AS pk_width_bytes FROM information_schema.COLUMNS c JOIN information_schema.STATISTICS s ON c.TABLE_SCHEMA = s.TABLE_SCHEMA AND c.TABLE_NAME = s.TABLE_NAME AND c.COLUMN_NAME = s.COLUMN_NAME WHERE s.INDEX_NAME = 'PRIMARY' AND c.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY c.TABLE_SCHEMA, c.TABLE_NAME HAVING pk_width_bytes > :threshold ORDER BY pk_width_bytes DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with wide primary keys that inflate secondary indexes"}	{"threshold": 16}	2026-05-11 22:17:39.229791
14328	mariadb	query	Check secondary index overhead from wide PK	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, idx.idx_cnt - 1 AS secondary_indexes, ROUND(t.INDEX_LENGTH / 1048576, 2) AS index_mb, ROUND(t.DATA_LENGTH / 1048576, 2) AS data_mb, ROUND(t.INDEX_LENGTH / NULLIF(t.DATA_LENGTH, 0) * 100, 2) AS index_ratio FROM information_schema.TABLES t JOIN (SELECT TABLE_SCHEMA AS ts, TABLE_NAME AS tn, COUNT(DISTINCT INDEX_NAME) AS idx_cnt FROM information_schema.STATISTICS GROUP BY TABLE_SCHEMA, TABLE_NAME) idx ON t.TABLE_SCHEMA = idx.ts AND t.TABLE_NAME = idx.tn WHERE idx.idx_cnt > 2 AND t.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY index_ratio DESC LIMIT 20"}	{"condition": "high_index_ratio", "description": "High index-to-data ratio with wide PK confirms index inflation"}	\N	2026-05-11 22:17:39.229791
14329	mariadb	query	Find indexes with wide VARCHAR columns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.SUB_PART, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.DATA_TYPE IN ('varchar', 'varbinary') AND c.CHARACTER_MAXIMUM_LENGTH > :width_threshold AND s.SUB_PART IS NULL AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY c.CHARACTER_MAXIMUM_LENGTH DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with wide VARCHAR columns found"}	{"width_threshold": 100}	2026-05-11 22:17:39.229791
14330	mariadb	query	Find composite indexes with high total key width	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, COUNT(*) AS col_count, GROUP_CONCAT(CONCAT(s.COLUMN_NAME, '(', COALESCE(c.CHARACTER_MAXIMUM_LENGTH, 8), ')') ORDER BY s.SEQ_IN_INDEX) AS columns_with_width, SUM(CASE WHEN c.DATA_TYPE IN ('varchar', 'char') THEN c.CHARACTER_MAXIMUM_LENGTH * 4 WHEN c.DATA_TYPE IN ('int') THEN 4 WHEN c.DATA_TYPE IN ('bigint') THEN 8 ELSE 8 END) AS estimated_key_bytes FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND s.INDEX_NAME != 'PRIMARY' GROUP BY s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME HAVING col_count > :col_threshold AND estimated_key_bytes > :byte_threshold ORDER BY estimated_key_bytes DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Composite indexes with excessively wide total key size"}	{"col_threshold": 3, "byte_threshold": 500}	2026-05-11 22:17:39.229791
14331	mariadb	query	Find indexes with wide leading columns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH, s.CARDINALITY FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE s.SEQ_IN_INDEX = 1 AND c.DATA_TYPE IN ('char', 'varchar') AND c.CHARACTER_MAXIMUM_LENGTH > :width_threshold AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY c.CHARACTER_MAXIMUM_LENGTH DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Leading index columns wider than typical discrimination needs"}	{"width_threshold": 50}	2026-05-11 22:17:39.229791
14332	mariadb	query	Find functional indexes	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.EXPRESSION, c.GENERATION_EXPRESSION FROM information_schema.STATISTICS s LEFT JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE s.EXPRESSION IS NOT NULL AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema')"}	{"condition": "row_count > 0", "description": "Functional indexes that may produce wide key values"}	\N	2026-05-11 22:17:39.229791
14333	mariadb	query	Find indexes with wide columns using multi-byte character sets	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, c.CHARACTER_MAXIMUM_LENGTH, c.CHARACTER_SET_NAME, c.COLLATION_NAME, CASE WHEN c.CHARACTER_SET_NAME = 'utf8mb4' THEN c.CHARACTER_MAXIMUM_LENGTH * 4 WHEN c.CHARACTER_SET_NAME = 'utf8' THEN c.CHARACTER_MAXIMUM_LENGTH * 3 WHEN c.CHARACTER_SET_NAME = 'latin1' THEN c.CHARACTER_MAXIMUM_LENGTH ELSE c.CHARACTER_MAXIMUM_LENGTH * 4 END AS max_byte_width FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.CHARACTER_SET_NAME IN ('utf8mb4', 'utf8mb3', 'utf8') AND c.CHARACTER_MAXIMUM_LENGTH > :width_threshold AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY max_byte_width DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with wide columns using multi-byte character sets"}	{"width_threshold": 100}	2026-05-11 22:17:39.229791
14748	mariadb	query	Check ratio of privileged to total users	{"sql": "SELECT (SELECT COUNT(*) FROM mysql.user WHERE Super_priv = 'Y' AND User NOT IN ('root', 'mysql.sys', 'mysql.session', 'mysql.infoschema')) AS admin_count, (SELECT COUNT(*) FROM mysql.user WHERE User NOT IN ('mysql.sys', 'mysql.session', 'mysql.infoschema')) AS total_count"}	{"condition": "admin_count / total_count > :ratio_threshold", "description": "High ratio of admin to total users confirms least privilege is not enforced"}	{"ratio_threshold": 0.3}	2026-05-11 22:17:39.229791
14334	mariadb	query	Find indexes with many nullable columns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, COUNT(*) AS total_cols, SUM(CASE WHEN c.IS_NULLABLE = 'YES' THEN 1 ELSE 0 END) AS nullable_cols FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') GROUP BY s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME HAVING nullable_cols > :threshold ORDER BY nullable_cols DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexes with many nullable columns adding per-entry overhead"}	{"threshold": 2}	2026-05-11 22:17:39.229791
14335	mariadb	query	Find indexes on binary/blob columns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, s.SUB_PART, c.DATA_TYPE, c.CHARACTER_MAXIMUM_LENGTH FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE c.DATA_TYPE IN ('binary', 'varbinary', 'blob', 'mediumblob', 'longblob', 'geometry', 'point') AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema')"}	{"condition": "row_count > 0", "description": "Indexes on binary/blob columns creating wide keys"}	\N	2026-05-11 22:17:39.229791
14336	mariadb	query	Find composite indexes with potentially redundant columns	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, GROUP_CONCAT(s.COLUMN_NAME ORDER BY s.SEQ_IN_INDEX) AS index_columns, COUNT(*) AS col_count FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') AND s.INDEX_NAME != 'PRIMARY' GROUP BY s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME HAVING col_count > :threshold ORDER BY col_count DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Wide composite indexes that may contain redundant columns"}	{"threshold": 4}	2026-05-11 22:17:39.229791
14337	mariadb	query	Find indexed columns with potentially oversized types	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.COLUMN_NAME, c.DATA_TYPE, c.COLUMN_TYPE, c.CHARACTER_MAXIMUM_LENGTH FROM information_schema.STATISTICS s JOIN information_schema.COLUMNS c ON s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME WHERE (c.DATA_TYPE = 'bigint' OR (c.DATA_TYPE = 'varchar' AND c.CHARACTER_MAXIMUM_LENGTH > :varchar_threshold) OR c.DATA_TYPE = 'char' AND c.CHARACTER_MAXIMUM_LENGTH > :char_threshold) AND s.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema') ORDER BY c.CHARACTER_MAXIMUM_LENGTH DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Indexed columns using wider types than may be necessary"}	{"char_threshold": 50, "varchar_threshold": 100}	2026-05-11 22:17:39.229791
14338	mariadb	query	Check InnoDB deadlock history	{"sql": "SHOW ENGINE INNODB STATUS"}	{"condition": "LATEST DETECTED DEADLOCK section exists", "description": "InnoDB records the most recent deadlock with transaction details showing lock ordering"}	\N	2026-05-11 22:17:39.229791
14339	mariadb	query	Check deadlock count from performance_schema	{"sql": "SELECT VARIABLE_VALUE AS deadlock_count FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks'"}	{"condition": "deadlock_count > threshold", "description": "Non-zero and growing deadlock count confirms ongoing deadlock issues"}	{"threshold": 0}	2026-05-11 22:17:39.229791
14340	mariadb	query	Check if deadlocks correlate with long transactions	{"sql": "SELECT VARIABLE_VALUE AS deadlock_count FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks'"}	{"condition": "deadlock_count > 0", "description": "Active deadlocks alongside long-running transactions confirms correlation"}	\N	2026-05-11 22:17:39.229791
14341	mariadb	query	Find foreign keys and check for supporting indexes	{"sql": "SELECT tc.TABLE_SCHEMA, tc.TABLE_NAME, tc.CONSTRAINT_NAME, kcu.COLUMN_NAME, kcu.REFERENCED_TABLE_NAME, kcu.REFERENCED_COLUMN_NAME FROM information_schema.TABLE_CONSTRAINTS tc JOIN information_schema.KEY_COLUMN_USAGE kcu ON tc.TABLE_SCHEMA = kcu.TABLE_SCHEMA AND tc.TABLE_NAME = kcu.TABLE_NAME AND tc.CONSTRAINT_NAME = kcu.CONSTRAINT_NAME WHERE tc.CONSTRAINT_TYPE = 'FOREIGN KEY' AND tc.TABLE_SCHEMA NOT IN ('mysql', 'sys', 'information_schema', 'performance_schema')"}	{"condition": "foreign_keys_exist", "description": "Foreign key constraints exist that may cause lock dependencies"}	\N	2026-05-11 22:17:39.229791
14342	mariadb	query	Find queries using explicit locking	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_LOCK_TIME / 1000000000 AS total_lock_ms FROM performance_schema.events_statements_summary_by_digest WHERE (DIGEST_TEXT LIKE '%FOR UPDATE%' OR DIGEST_TEXT LIKE '%FOR SHARE%' OR DIGEST_TEXT LIKE '%LOCK IN SHARE MODE%') AND COUNT_STAR > :min_executions ORDER BY SUM_LOCK_TIME DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries using explicit locking that may create lock incompatibilities"}	{"min_executions": 5}	2026-05-11 22:17:39.229791
14343	mariadb	query	Check for deadlocks	{"sql": "SELECT VARIABLE_VALUE AS deadlocks FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks'"}	{"condition": "deadlocks > 0", "description": "Deadlocks alongside explicit locking usage confirms lock mode conflicts"}	\N	2026-05-11 22:17:39.229791
14369	mariadb	query	Check InnoDB undo log growth from bulk operations	{"sql": "SELECT trx_id, trx_state, trx_started, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS duration_seconds, trx_rows_locked, trx_rows_modified FROM information_schema.INNODB_TRX WHERE trx_rows_modified > 10000 ORDER BY trx_rows_modified DESC"}	{"condition": "row_count > 0", "description": "Transactions modifying more than 10000 rows confirm large batch operations"}	{"threshold_rows": 10000}	2026-05-11 22:17:39.229791
14344	mariadb	query	Find sessions waiting on row locks held by other transactions	{"sql": "SELECT r.trx_id AS waiting_trx_id, r.trx_mysql_thread_id AS waiting_thread, r.trx_query AS waiting_query, r.trx_started AS waiting_since, b.trx_id AS blocking_trx_id, b.trx_mysql_thread_id AS blocking_thread, b.trx_query AS blocking_query, b.trx_started AS blocking_since, TIMESTAMPDIFF(SECOND, r.trx_started, NOW()) AS waiting_seconds FROM information_schema.INNODB_TRX r JOIN performance_schema.data_lock_waits w ON r.trx_id = w.REQUESTING_ENGINE_TRANSACTION_ID JOIN information_schema.INNODB_TRX b ON b.trx_id = w.BLOCKING_ENGINE_TRANSACTION_ID WHERE TIMESTAMPDIFF(SECOND, r.trx_started, NOW()) > 30"}	{"condition": "row_count > 0", "description": "Transactions waiting on locks held by other active transactions"}	{"threshold_seconds": 30}	2026-05-11 22:17:39.229791
14345	mariadb	query	Check if blocking transactions are also long-running	{"sql": "SELECT b.trx_id, b.trx_mysql_thread_id, b.trx_state, b.trx_started, TIMESTAMPDIFF(SECOND, b.trx_started, NOW()) AS blocking_duration_seconds, b.trx_rows_locked, b.trx_rows_modified FROM information_schema.INNODB_TRX b WHERE b.trx_id IN (SELECT BLOCKING_ENGINE_TRANSACTION_ID FROM performance_schema.data_lock_waits) AND TIMESTAMPDIFF(SECOND, b.trx_started, NOW()) > 60 ORDER BY blocking_duration_seconds DESC"}	{"condition": "row_count > 0", "description": "Blocking transactions themselves are long-running, confirming synchronous wait pattern"}	{"threshold_seconds": 60}	2026-05-11 22:17:39.229791
14346	mariadb	query	Verify transactions originate from same application context	{"sql": "SELECT p1.USER AS waiting_user, p1.HOST AS waiting_host, p1.DB AS waiting_db, p2.USER AS blocking_user, p2.HOST AS blocking_host, p2.DB AS blocking_db FROM performance_schema.data_lock_waits w JOIN information_schema.PROCESSLIST p1 ON p1.ID = (SELECT trx_mysql_thread_id FROM information_schema.INNODB_TRX WHERE trx_id = w.REQUESTING_ENGINE_TRANSACTION_ID) JOIN information_schema.PROCESSLIST p2 ON p2.ID = (SELECT trx_mysql_thread_id FROM information_schema.INNODB_TRX WHERE trx_id = w.BLOCKING_ENGINE_TRANSACTION_ID) WHERE p1.USER = p2.USER AND p1.DB = p2.DB"}	{"condition": "row_count > 0", "description": "Same user and database confirms application-level synchronous wait pattern"}	\N	2026-05-11 22:17:39.229791
14347	mariadb	query	Find long-running active queries exceeding expected duration	{"sql": "SELECT t.THREAD_ID, t.PROCESSLIST_ID, t.PROCESSLIST_USER, t.PROCESSLIST_DB, t.PROCESSLIST_TIME, t.PROCESSLIST_STATE, LEFT(t.PROCESSLIST_INFO, 200) AS query_text FROM performance_schema.threads t WHERE t.PROCESSLIST_COMMAND = 'Query' AND t.PROCESSLIST_TIME > 300 AND t.TYPE = 'FOREGROUND' ORDER BY t.PROCESSLIST_TIME DESC"}	{"condition": "row_count > 0", "description": "Active queries running longer than 5 minutes may indicate runaway execution"}	{"threshold_seconds": 300}	2026-05-11 22:17:39.229791
14348	mariadb	query	Check execution plan cost via statement digest history	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds, ROUND(MAX_TIMER_WAIT / 1000000000000, 2) AS max_seconds, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0), 0) AS rows_examined_per_sent FROM performance_schema.events_statements_summary_by_digest WHERE AVG_TIMER_WAIT > 60000000000000 AND SUM_ROWS_EXAMINED / NULLIF(COUNT_STAR, 0) > 1000000 ORDER BY AVG_TIMER_WAIT DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "High rows_examined_per_sent ratio indicates full table scans or plan regression"}	{"min_avg_seconds": 60, "min_rows_examined_per_execution": 1000000}	2026-05-11 22:17:39.229791
14349	mariadb	query	Check for full table scans in slow queries	{"sql": "SELECT DIGEST_TEXT, SUM_NO_INDEX_USED, SUM_NO_GOOD_INDEX_USED, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, COUNT_STAR FROM performance_schema.events_statements_summary_by_digest WHERE (SUM_NO_INDEX_USED > 0 OR SUM_NO_GOOD_INDEX_USED > 0) AND AVG_TIMER_WAIT > 60000000000000 ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries with no index usage and high row examination confirm optimizer plan degradation"}	\N	2026-05-11 22:17:39.229791
14350	mariadb	query	Identify queries using disk-based temp tables	{"sql": "SELECT DIGEST_TEXT, SUM_CREATED_TMP_DISK_TABLES, SUM_CREATED_TMP_TABLES, COUNT_STAR, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds, SUM_ROWS_EXAMINED FROM performance_schema.events_statements_summary_by_digest WHERE SUM_CREATED_TMP_DISK_TABLES > 0 ORDER BY SUM_CREATED_TMP_DISK_TABLES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Specific queries creating disk temporary tables identified"}	\N	2026-05-11 22:17:39.229791
14351	mariadb	config_check	Check tmp_table_size and max_heap_table_size settings	{"sql": "SELECT @@tmp_table_size AS tmp_table_size, @@max_heap_table_size AS max_heap_table_size, @@sort_buffer_size AS sort_buffer_size, @@join_buffer_size AS join_buffer_size"}	{"condition": "tmp_table_size < 67108864", "description": "tmp_table_size below 64MB may be insufficient for complex queries"}	{"min_tmp_table_size": 67108864}	2026-05-11 22:17:39.229791
14352	mariadb	query	Check for active DDL or maintenance operations	{"sql": "SELECT p.ID, p.USER, p.HOST, p.DB, p.COMMAND, p.TIME, p.STATE, LEFT(p.INFO, 200) AS query_text FROM information_schema.PROCESSLIST p WHERE p.COMMAND IN ('Query', 'Execute') AND (p.INFO LIKE 'ALTER%' OR p.INFO LIKE 'OPTIMIZE%' OR p.INFO LIKE 'ANALYZE%' OR p.INFO LIKE 'REPAIR%' OR p.INFO LIKE 'CHECK%') AND p.TIME > 10"}	{"condition": "row_count > 0", "description": "Active maintenance operations that have been running for more than 10 seconds"}	{"threshold_seconds": 10}	2026-05-11 22:17:39.229791
14353	mariadb	query	Check for metadata lock waits caused by maintenance	{"sql": "SELECT t.THREAD_ID, t.PROCESSLIST_ID, t.PROCESSLIST_USER, t.PROCESSLIST_TIME, t.PROCESSLIST_STATE, LEFT(t.PROCESSLIST_INFO, 200) AS query_text FROM performance_schema.threads t WHERE t.PROCESSLIST_STATE LIKE '%Waiting for table metadata lock%' AND t.PROCESSLIST_TIME > 5 ORDER BY t.PROCESSLIST_TIME DESC"}	{"condition": "row_count > 0", "description": "Sessions waiting for metadata locks confirm maintenance is blocking other transactions"}	{"threshold_seconds": 5}	2026-05-11 22:17:39.229791
14354	mariadb	query	Verify metadata lock contention details	{"sql": "SELECT OBJECT_TYPE, OBJECT_SCHEMA, OBJECT_NAME, LOCK_TYPE, LOCK_DURATION, LOCK_STATUS, OWNER_THREAD_ID FROM performance_schema.metadata_locks WHERE LOCK_STATUS = 'PENDING' ORDER BY OBJECT_SCHEMA, OBJECT_NAME"}	{"condition": "row_count > 0", "description": "Pending metadata locks confirm maintenance operations are blocking forward progress"}	\N	2026-05-11 22:17:39.229791
14355	mariadb	query	Calculate total MySQL memory allocation	{"sql": "SELECT @@innodb_buffer_pool_size AS buffer_pool_bytes, @@key_buffer_size AS key_buffer_bytes, @@max_connections AS max_connections, @@sort_buffer_size AS sort_buffer_bytes, @@join_buffer_size AS join_buffer_bytes, @@thread_stack AS thread_stack_bytes, @@innodb_buffer_pool_size + @@key_buffer_size + (@@max_connections * (@@sort_buffer_size + @@join_buffer_size + @@read_buffer_size + @@read_rnd_buffer_size + @@thread_stack)) AS estimated_total_bytes"}	{"condition": "estimated_total_bytes is calculable", "description": "Collect total memory allocation parameters for comparison with available RAM"}	\N	2026-05-11 22:17:39.229791
14356	mariadb	query	Check InnoDB buffer pool utilization and page evictions	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME IN ('Innodb_buffer_pool_pages_total', 'Innodb_buffer_pool_pages_free', 'Innodb_buffer_pool_pages_data', 'Innodb_buffer_pool_read_requests', 'Innodb_buffer_pool_reads', 'Innodb_buffer_pool_wait_free') ORDER BY VARIABLE_NAME"}	{"condition": "Innodb_buffer_pool_pages_free < Innodb_buffer_pool_pages_total * 0.05", "description": "Less than 5% free pages indicates buffer pool memory pressure"}	{"min_free_pct": 0.05}	2026-05-11 22:17:39.229791
14357	mariadb	query	Check for swap usage indicators	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME IN ('Innodb_buffer_pool_reads', 'Innodb_buffer_pool_read_requests') ORDER BY VARIABLE_NAME"}	{"condition": "Innodb_buffer_pool_reads / Innodb_buffer_pool_read_requests > 0.01", "description": "Physical read ratio above 1% suggests insufficient memory for caching"}	{"max_physical_read_ratio": 0.01}	2026-05-11 22:17:39.229791
14358	mariadb	query	Compare buffer pool size to total data size	{"sql": "SELECT @@innodb_buffer_pool_size AS buffer_pool_size, (SELECT SUM(DATA_LENGTH + INDEX_LENGTH) FROM information_schema.TABLES WHERE ENGINE = 'InnoDB') AS total_innodb_size, ROUND(@@innodb_buffer_pool_size / NULLIF((SELECT SUM(DATA_LENGTH + INDEX_LENGTH) FROM information_schema.TABLES WHERE ENGINE = 'InnoDB'), 0) * 100, 1) AS buffer_to_data_pct"}	{"condition": "buffer_to_data_pct < 80", "description": "Buffer pool covering less than 80% of total InnoDB data indicates undersizing"}	{"min_buffer_to_data_pct": 80}	2026-05-11 22:17:39.229791
14359	mariadb	query	Check for buffer pool wait events	{"sql": "SELECT VARIABLE_VALUE AS wait_free FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_wait_free'"}	{"condition": "wait_free > 0", "description": "Non-zero wait_free confirms buffer pool exhaustion requiring free page waits"}	\N	2026-05-11 22:17:39.229791
14360	mariadb	query	Check current and maximum connection counts	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS current_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Max_used_connections') AS max_used_connections, @@max_connections AS max_allowed_connections, ROUND((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') / @@max_connections * 100, 1) AS utilization_pct"}	{"condition": "utilization_pct > 70", "description": "Connection utilization above 70% indicates connection pressure"}	{"threshold_pct": 70}	2026-05-11 22:17:39.229791
14361	mariadb	query	Calculate per-connection memory footprint	{"sql": "SELECT @@sort_buffer_size + @@join_buffer_size + @@read_buffer_size + @@read_rnd_buffer_size + @@thread_stack + @@binlog_cache_size + @@tmp_table_size AS per_connection_bytes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS active_connections, (@@sort_buffer_size + @@join_buffer_size + @@read_buffer_size + @@read_rnd_buffer_size + @@thread_stack + @@binlog_cache_size + @@tmp_table_size) * (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS total_connection_memory"}	{"condition": "total_connection_memory > 1073741824", "description": "Total connection memory exceeding 1GB indicates excessive per-connection memory consumption"}	{"threshold_bytes": 1073741824}	2026-05-11 22:17:39.229791
14362	mariadb	query	Check memory allocation via performance_schema	{"sql": "SELECT EVENT_NAME, SUM(CURRENT_NUMBER_OF_BYTES_USED) AS current_bytes, SUM(COUNT_ALLOC) AS allocation_count FROM performance_schema.memory_summary_by_thread_by_event_name WHERE EVENT_NAME LIKE 'memory/sql/%' GROUP BY EVENT_NAME ORDER BY current_bytes DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Memory instrumentation shows per-thread memory consumption patterns"}	\N	2026-05-11 22:17:39.229791
14363	mariadb	query	Find queries with high rows examined to rows sent ratio	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0), 0) AS exam_to_sent_ratio, SUM_CREATED_TMP_DISK_TABLES, SUM_CREATED_TMP_TABLES, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_ROWS_EXAMINED > 100000 ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10"}	{"condition": "exam_to_sent_ratio > 1000", "description": "Queries examining 1000x more rows than sent indicate wasteful memory and CPU usage"}	{"min_ratio": 1000}	2026-05-11 22:17:39.229791
14364	mariadb	query	Check for queries creating disk-based temporary tables	{"sql": "SELECT DIGEST_TEXT, SUM_CREATED_TMP_DISK_TABLES, SUM_CREATED_TMP_TABLES, SUM_SORT_MERGE_PASSES, SUM_ROWS_EXAMINED, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_CREATED_TMP_DISK_TABLES > 0 OR SUM_SORT_MERGE_PASSES > 0 ORDER BY SUM_CREATED_TMP_DISK_TABLES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries creating disk temp tables or needing sort merge passes confirm memory-intensive workload"}	\N	2026-05-11 22:17:39.229791
14365	mariadb	query	Check total memory usage via performance_schema	{"sql": "SELECT EVENT_NAME, CURRENT_NUMBER_OF_BYTES_USED, HIGH_NUMBER_OF_BYTES_USED FROM performance_schema.memory_summary_global_by_event_name WHERE CURRENT_NUMBER_OF_BYTES_USED > 10485760 ORDER BY CURRENT_NUMBER_OF_BYTES_USED DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Memory allocations exceeding 10MB per event category"}	{"threshold_bytes": 10485760}	2026-05-11 22:17:39.229791
14366	mariadb	query	Check for accumulated prepared statements	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME IN ('Prepared_stmt_count', 'Com_stmt_prepare', 'Com_stmt_close', 'Com_stmt_execute') ORDER BY VARIABLE_NAME"}	{"condition": "Prepared_stmt_count > 100", "description": "High number of prepared statements that have not been closed suggests a leak"}	{"threshold_count": 100}	2026-05-11 22:17:39.229791
14367	mariadb	query	Check for long-running connections with high memory	{"sql": "SELECT t.THREAD_ID, t.PROCESSLIST_ID, t.PROCESSLIST_USER, t.PROCESSLIST_TIME, SUM(m.CURRENT_NUMBER_OF_BYTES_USED) AS thread_memory_bytes FROM performance_schema.threads t JOIN performance_schema.memory_summary_by_thread_by_event_name m ON t.THREAD_ID = m.THREAD_ID WHERE t.TYPE = 'FOREGROUND' GROUP BY t.THREAD_ID, t.PROCESSLIST_ID, t.PROCESSLIST_USER, t.PROCESSLIST_TIME HAVING thread_memory_bytes > 52428800 ORDER BY thread_memory_bytes DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Individual threads consuming >50MB indicate potential memory leak"}	{"threshold_bytes": 52428800}	2026-05-11 22:17:39.229791
14368	mariadb	query	Find active bulk DML operations	{"sql": "SELECT p.ID, p.USER, p.TIME, p.STATE, LEFT(p.INFO, 200) AS query_text FROM information_schema.PROCESSLIST p WHERE p.COMMAND = 'Query' AND (p.INFO LIKE 'INSERT%INTO%SELECT%' OR p.INFO LIKE 'UPDATE%SET%' OR p.INFO LIKE 'DELETE%FROM%' OR p.INFO LIKE 'LOAD DATA%' OR p.INFO LIKE 'INSERT%VALUES%') AND p.TIME > 30 ORDER BY p.TIME DESC"}	{"condition": "row_count > 0", "description": "Long-running bulk DML operations detected"}	{"threshold_seconds": 30}	2026-05-11 22:17:39.229791
14370	mariadb	query	Check for active stored procedure executions	{"sql": "SELECT t.THREAD_ID, t.PROCESSLIST_ID, t.PROCESSLIST_USER, t.PROCESSLIST_TIME, t.PROCESSLIST_STATE, LEFT(t.PROCESSLIST_INFO, 200) AS query_text FROM performance_schema.threads t WHERE t.PROCESSLIST_COMMAND = 'Query' AND t.PROCESSLIST_INFO LIKE 'CALL %' AND t.PROCESSLIST_TIME > 30 ORDER BY t.PROCESSLIST_TIME DESC"}	{"condition": "row_count > 0", "description": "Long-running stored procedure calls detected"}	{"threshold_seconds": 30}	2026-05-11 22:17:39.229791
14371	mariadb	query	Check memory consumption by stored procedure threads	{"sql": "SELECT m.THREAD_ID, m.EVENT_NAME, SUM(m.CURRENT_NUMBER_OF_BYTES_USED) AS memory_bytes FROM performance_schema.memory_summary_by_thread_by_event_name m WHERE m.THREAD_ID IN (SELECT THREAD_ID FROM performance_schema.threads WHERE PROCESSLIST_COMMAND = 'Query' AND PROCESSLIST_INFO LIKE 'CALL %') AND m.CURRENT_NUMBER_OF_BYTES_USED > 0 GROUP BY m.THREAD_ID, m.EVENT_NAME ORDER BY memory_bytes DESC LIMIT 20"}	{"condition": "memory_bytes > 10485760", "description": "Stored procedure threads consuming more than 10MB indicate memory-heavy procedures"}	{"threshold_bytes": 10485760}	2026-05-11 22:17:39.229791
