14375	mariadb	query	Check ratio of sleeping to active connections	{"sql": "SELECT SUM(CASE WHEN COMMAND = 'Sleep' THEN 1 ELSE 0 END) AS sleeping_connections, SUM(CASE WHEN COMMAND != 'Sleep' THEN 1 ELSE 0 END) AS active_connections, COUNT(*) AS total_connections, ROUND(SUM(CASE WHEN COMMAND = 'Sleep' THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) * 100, 1) AS sleep_pct FROM information_schema.PROCESSLIST WHERE USER != 'system user'"}	{"condition": "sleep_pct > 80", "description": "More than 80% sleeping connections indicate pool oversizing"}	{"threshold_sleep_pct": 80}	2026-05-11 22:17:39.229791
14376	mariadb	query	Check long-idle sleeping connections	{"sql": "SELECT USER, HOST, COUNT(*) AS connection_count, MAX(TIME) AS max_idle_seconds, AVG(TIME) AS avg_idle_seconds FROM information_schema.PROCESSLIST WHERE COMMAND = 'Sleep' AND TIME > 300 GROUP BY USER, HOST ORDER BY connection_count DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Connections idle for more than 5 minutes from same hosts confirm pool misconfiguration"}	{"threshold_idle_seconds": 300}	2026-05-11 22:17:39.229791
14377	mariadb	query	Check total per-connection memory being held	{"sql": "SELECT SUM(CASE WHEN COMMAND = 'Sleep' THEN 1 ELSE 0 END) * (@@sort_buffer_size + @@join_buffer_size + @@read_buffer_size + @@thread_stack) AS idle_connection_memory_bytes FROM information_schema.PROCESSLIST WHERE USER != 'system user'"}	{"condition": "idle_connection_memory_bytes > 104857600", "description": "Idle connections holding more than 100MB of memory confirms pool waste"}	{"threshold_bytes": 104857600}	2026-05-11 22:17:39.229791
