14405	mariadb	query	Find queries with high execution time variance and sort spills	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds, ROUND(MAX_TIMER_WAIT / 1000000000000, 2) AS max_seconds, ROUND(MAX_TIMER_WAIT / NULLIF(AVG_TIMER_WAIT, 0), 1) AS variance_ratio, SUM_SORT_MERGE_PASSES, SUM_CREATED_TMP_DISK_TABLES FROM performance_schema.events_statements_summary_by_digest WHERE COUNT_STAR > 5 AND MAX_TIMER_WAIT / NULLIF(AVG_TIMER_WAIT, 0) > 20 AND (SUM_SORT_MERGE_PASSES > 0 OR SUM_CREATED_TMP_DISK_TABLES > 0) ORDER BY variance_ratio DESC LIMIT 10"}	{"condition": "variance_ratio > 20", "description": "High execution time variance with sort spills suggests data skew affecting some executions"}	{"threshold_variance": 20}	2026-05-11 22:17:39.229791
14406	mariadb	query	Check concurrent query execution count	{"sql": "SELECT COUNT(*) AS active_queries, SUM(CASE WHEN PROCESSLIST_STATE LIKE '%sort%' THEN 1 ELSE 0 END) AS sorting_queries, SUM(CASE WHEN PROCESSLIST_STATE LIKE '%tmp%' THEN 1 ELSE 0 END) AS temp_table_queries FROM performance_schema.threads WHERE TYPE = 'FOREGROUND' AND PROCESSLIST_COMMAND = 'Query'"}	{"condition": "sorting_queries > 5", "description": "Multiple concurrent sorting queries multiply sort_buffer_size memory usage"}	{"threshold_sorting": 5}	2026-05-11 22:17:39.229791
14407	mariadb	query	Calculate total sort memory in use	{"sql": "SELECT @@sort_buffer_size AS per_sort_buffer, COUNT(*) AS concurrent_queries, @@sort_buffer_size * COUNT(*) AS estimated_sort_memory FROM performance_schema.threads WHERE TYPE = 'FOREGROUND' AND PROCESSLIST_COMMAND = 'Query'"}	{"condition": "estimated_sort_memory > 268435456", "description": "Total concurrent sort memory exceeding 256MB indicates memory multiplication"}	{"threshold_bytes": 268435456}	2026-05-11 22:17:39.229791
14408	mariadb	query	Find tables with wide rows	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, AVG_ROW_LENGTH, TABLE_ROWS, DATA_LENGTH FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'performance_schema', 'information_schema', 'sys') AND AVG_ROW_LENGTH > 1000 ORDER BY AVG_ROW_LENGTH DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with average row length above 1KB may cause sort memory issues"}	{"threshold_avg_row_length": 1000}	2026-05-11 22:17:39.229791
14409	mariadb	query	Check sort spills on wide-row tables	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_merge_passes') AS sort_merge_passes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_disk_tables') AS disk_tmp_tables, @@sort_buffer_size AS sort_buffer_size"}	{"condition": "sort_merge_passes > 0", "description": "Sort merge passes confirm sorts are exceeding sort_buffer_size"}	\N	2026-05-11 22:17:39.229791
14410	mariadb	query	Find queries with high rows examined and sort spills	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, SUM_SORT_MERGE_PASSES, SUM_CREATED_TMP_DISK_TABLES, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_SORT_MERGE_PASSES > 0 AND DIGEST_TEXT LIKE 'SELECT %*%FROM%' ORDER BY SUM_SORT_MERGE_PASSES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "SELECT * queries with sort spills identified"}	\N	2026-05-11 22:17:39.229791
14643	mariadb	query	Find non-root accounts with empty passwords	{"sql": "SELECT User, Host, plugin, password_last_changed, account_locked FROM mysql.user WHERE (authentication_string = '' OR authentication_string IS NULL) AND User NOT IN ('root', 'mysql.sys', 'mysql.session', 'mysql.infoschema', '') AND account_locked = 'N' ORDER BY password_last_changed"}	{"condition": "row_count > 0", "description": "Application-created accounts with empty passwords detected"}	\N	2026-05-11 22:17:39.229791
14411	mariadb	query	Check disk temp table creation for wide result sets	{"sql": "SELECT DIGEST_TEXT, SUM_CREATED_TMP_DISK_TABLES, SUM_CREATED_TMP_TABLES, SUM_SORT_MERGE_PASSES, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_CREATED_TMP_DISK_TABLES > 0 AND SUM_SORT_MERGE_PASSES > 0 ORDER BY SUM_CREATED_TMP_DISK_TABLES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Combined disk temp tables and sort spills confirm wide result set memory issues"}	\N	2026-05-11 22:17:39.229791
14412	mariadb	query	Find queries with high sort merge passes relative to executions	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_SORT_MERGE_PASSES, SUM_SORT_ROWS, SUM_SORT_SCAN, SUM_SORT_RANGE, ROUND(SUM_SORT_MERGE_PASSES / NULLIF(COUNT_STAR, 0), 1) AS passes_per_exec, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_SORT_MERGE_PASSES / NULLIF(COUNT_STAR, 0) > 2 ORDER BY passes_per_exec DESC LIMIT 10"}	{"condition": "passes_per_exec > 2", "description": "Multiple sort merge passes per execution indicate multiple sort operations in one query"}	{"threshold_passes_per_exec": 2}	2026-05-11 22:17:39.229791
14413	mariadb	query	Check for combined disk temp tables and sort spills	{"sql": "SELECT DIGEST_TEXT, SUM_SORT_MERGE_PASSES, SUM_CREATED_TMP_DISK_TABLES, SUM_CREATED_TMP_TABLES, SUM_ROWS_EXAMINED, ROUND(SUM_SORT_MERGE_PASSES / NULLIF(COUNT_STAR, 0), 1) AS passes_per_exec FROM performance_schema.events_statements_summary_by_digest WHERE SUM_SORT_MERGE_PASSES / NULLIF(COUNT_STAR, 0) > 2 AND SUM_CREATED_TMP_DISK_TABLES > 0 ORDER BY passes_per_exec DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Confirmed: queries with multiple sort operations creating disk temp tables"}	\N	2026-05-11 22:17:39.229791
14414	mariadb	query	Find queries with sort operations that have indexes available	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_SORT_MERGE_PASSES, SUM_SORT_ROWS, SUM_NO_GOOD_INDEX_USED, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0), 0) AS exam_ratio FROM performance_schema.events_statements_summary_by_digest WHERE SUM_NO_GOOD_INDEX_USED > 0 AND SUM_SORT_MERGE_PASSES > 0 ORDER BY SUM_SORT_MERGE_PASSES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries flagged with no_good_index_used and sort spills indicate wrong index column order"}	\N	2026-05-11 22:17:39.229791
14415	mariadb	query	Check for unused indexes on frequently queried tables	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, s.SEQ_IN_INDEX, s.COLUMN_NAME, t.COUNT_READ FROM information_schema.STATISTICS s LEFT JOIN performance_schema.table_io_waits_summary_by_index_usage t ON s.TABLE_SCHEMA = t.OBJECT_SCHEMA AND s.TABLE_NAME = t.OBJECT_NAME AND s.INDEX_NAME = t.INDEX_NAME WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'performance_schema', 'information_schema', 'sys') AND s.SEQ_IN_INDEX = 1 ORDER BY s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME LIMIT 30"}	{"condition": "row_count > 0", "description": "Index leading columns listed for analysis of column order effectiveness"}	\N	2026-05-11 22:17:39.229791
14416	mariadb	query	Find queries with high select range check and sort spills	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_SELECT_RANGE_CHECK, SUM_SELECT_SCAN, SUM_SORT_MERGE_PASSES, SUM_ROWS_EXAMINED, SUM_ROWS_SENT FROM performance_schema.events_statements_summary_by_digest WHERE SUM_SORT_MERGE_PASSES > 0 AND SUM_ROWS_EXAMINED > SUM_ROWS_SENT * 10 ORDER BY SUM_SORT_MERGE_PASSES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries examining many more rows than sent with sort spills indicate non-covering index lookups"}	\N	2026-05-11 22:17:39.229791
14417	mariadb	query	Check handler read patterns for non-covering index scans	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME IN ('Handler_read_key', 'Handler_read_next', 'Handler_read_rnd', 'Handler_read_rnd_next') ORDER BY VARIABLE_NAME"}	{"condition": "Handler_read_rnd > 0", "description": "Handler_read_rnd indicates random row lookups after index scan (non-covering index pattern)"}	\N	2026-05-11 22:17:39.229791
14418	mariadb	query	Check for histogram statistics coverage	{"sql": "SELECT COUNT(*) AS histogram_count FROM information_schema.COLUMN_STATISTICS"}	{"condition": "histogram_count < 10", "description": "Very few or no histogram statistics suggest optimizer is using default estimates"}	{"min_histograms": 10}	2026-05-11 22:17:39.229791
14419	mariadb	query	Find queries with sort spills on tables without histograms	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_SORT_MERGE_PASSES, SUM_CREATED_TMP_DISK_TABLES, SUM_ROWS_EXAMINED, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_SORT_MERGE_PASSES > 0 ORDER BY SUM_SORT_MERGE_PASSES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Sort spills combined with missing histograms confirm poor selectivity estimation"}	\N	2026-05-11 22:17:39.229791
14420	mariadb	config_check	Check sort and join buffer sizes	{"sql": "SELECT @@sort_buffer_size AS sort_buffer_size, @@join_buffer_size AS join_buffer_size, @@tmp_table_size AS tmp_table_size, @@max_heap_table_size AS max_heap_table_size, @@read_buffer_size AS read_buffer_size, @@read_rnd_buffer_size AS read_rnd_buffer_size"}	{"condition": "sort_buffer_size < 2097152", "description": "sort_buffer_size below 2MB may be insufficient for medium-complexity queries"}	{"min_sort_buffer": 2097152}	2026-05-11 22:17:39.229791
14421	mariadb	query	Check sort spill frequency	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_merge_passes') AS sort_merge_passes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_rows') AS sort_rows, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_disk_tables') AS disk_tmp_tables, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_tables') AS total_tmp_tables"}	{"condition": "sort_merge_passes > 100 OR disk_tmp_tables / total_tmp_tables > 0.10", "description": "High sort merge passes or >10% disk temp tables confirm buffer undersizing"}	{"threshold_passes": 100, "threshold_disk_pct": 0.1}	2026-05-11 22:17:39.229791
14422	mariadb	query	Check buffer pool size relative to data volume	{"sql": "SELECT @@innodb_buffer_pool_size AS buffer_pool_size, (SELECT SUM(DATA_LENGTH + INDEX_LENGTH) FROM information_schema.TABLES WHERE ENGINE = 'InnoDB') AS total_data_size, ROUND(@@innodb_buffer_pool_size / NULLIF((SELECT SUM(DATA_LENGTH + INDEX_LENGTH) FROM information_schema.TABLES WHERE ENGINE = 'InnoDB'), 0) * 100, 1) AS coverage_pct"}	{"condition": "coverage_pct < 50", "description": "Buffer pool covering less than 50% of data indicates insufficient RAM allocation"}	{"min_coverage_pct": 50}	2026-05-11 22:17:39.229791
14446	mariadb	query	Check concurrent active query count and workload	{"sql": "SELECT COUNT(*) AS active_queries, SUM(CASE WHEN TIME > 5 THEN 1 ELSE 0 END) AS long_running, SUM(CASE WHEN STATE LIKE '%Sending data%' THEN 1 ELSE 0 END) AS sending_data FROM information_schema.PROCESSLIST WHERE COMMAND = 'Query' AND USER != 'system user'"}	{"condition": "long_running > 3", "description": "Multiple long-running queries competing for buffer pool resources"}	{"threshold_long_running": 3}	2026-05-11 22:17:39.229791
14423	mariadb	query	Check buffer pool size and page statistics	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_total') AS total_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_free') AS free_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_data') AS data_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_wait_free') AS wait_free_count, @@innodb_buffer_pool_size AS configured_size"}	{"condition": "free_pages / total_pages < 0.05 OR wait_free_count > 0", "description": "Less than 5% free pages or non-zero wait-free count indicates undersized buffer pool"}	{"min_free_pct": 0.05}	2026-05-11 22:17:39.229791
14782	mariadb	query	Verify no LDAP or PAM plugins installed	{"sql": "SELECT PLUGIN_NAME, PLUGIN_STATUS FROM information_schema.PLUGINS WHERE PLUGIN_NAME IN ('authentication_ldap_sasl', 'authentication_ldap_simple', 'authentication_pam', 'authentication_kerberos') AND PLUGIN_STATUS = 'ACTIVE'"}	{"condition": "row_count == 0", "description": "No enterprise auth plugins active confirms MySQL is not integrated with HR/identity systems"}	\N	2026-05-11 22:17:39.229791
14424	mariadb	query	Check disk read rate from buffer pool misses	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_reads') AS physical_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_requests') AS logical_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_reads') AS data_reads"}	{"condition": "physical_reads / logical_reads > 0.01", "description": "Physical read ratio above 1% confirms buffer pool cannot serve workload from cache"}	{"max_physical_ratio": 0.01}	2026-05-11 22:17:39.229791
14425	mariadb	query	Compare active table sizes to buffer pool	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, ROUND((DATA_LENGTH + INDEX_LENGTH) / 1048576, 1) AS size_mb FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'performance_schema', 'information_schema', 'sys') ORDER BY DATA_LENGTH + INDEX_LENGTH DESC LIMIT 20"}	{"condition": "SUM(size_mb) > buffer_pool_size_mb", "description": "Top tables exceed buffer pool size, causing working set eviction"}	\N	2026-05-11 22:17:39.229791
14426	mariadb	query	Check page eviction metrics	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_flushed') AS pages_flushed, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_ahead_evicted') AS read_ahead_evicted, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_data') AS data_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_old') AS old_pages"}	{"condition": "read_ahead_evicted > 0 OR old_pages / data_pages > 0.37", "description": "Evicted read-ahead pages or high old-pages ratio indicates active churn"}	\N	2026-05-11 22:17:39.229791
14427	mariadb	query	Find queries performing full table scans	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_NO_INDEX_USED, SUM_ROWS_EXAMINED, SUM_ROWS_SENT, ROUND(SUM_ROWS_EXAMINED / NULLIF(SUM_ROWS_SENT, 0), 0) AS exam_ratio, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_NO_INDEX_USED > 0 AND SUM_ROWS_EXAMINED > 10000 ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries with no index usage examining many rows"}	{"min_rows_examined": 10000}	2026-05-11 22:17:39.229791
14428	mariadb	query	Check buffer pool read-ahead eviction from full scans	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_ahead') AS read_ahead, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_ahead_evicted') AS read_ahead_evicted, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_reads') AS disk_reads"}	{"condition": "read_ahead_evicted > 0 OR disk_reads > 0", "description": "Read-ahead evictions confirm full scans pushing useful data out of buffer pool"}	\N	2026-05-11 22:17:39.229791
14429	mariadb	query	Check handler read patterns for full scans	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_read_rnd_next') AS sequential_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_read_key') AS index_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_read_first') AS first_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Select_scan') AS select_scans"}	{"condition": "sequential_reads / (sequential_reads + index_reads) > 0.5", "description": "More than 50% sequential reads indicates predominance of full table scans"}	{"threshold_ratio": 0.5}	2026-05-11 22:17:39.229791
14430	mariadb	query	Identify specific queries doing full scans on large tables	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_NO_INDEX_USED, SUM_ROWS_EXAMINED, ROUND(AVG_TIMER_WAIT / 1000000000000, 2) AS avg_seconds FROM performance_schema.events_statements_summary_by_digest WHERE SUM_NO_INDEX_USED > 0 AND SUM_ROWS_EXAMINED > 100000 ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Full scan queries on large tables that flush buffer pool confirmed"}	{"min_rows": 100000}	2026-05-11 22:17:39.229791
14431	mariadb	query	Check table fragmentation via data free	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, DATA_LENGTH, INDEX_LENGTH, DATA_FREE, ROUND(DATA_FREE / NULLIF(DATA_LENGTH + INDEX_LENGTH, 0) * 100, 1) AS fragmentation_pct FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'performance_schema', 'information_schema', 'sys') AND DATA_FREE > 10485760 ORDER BY DATA_FREE DESC LIMIT 20"}	{"condition": "fragmentation_pct > 20", "description": "Tables with more than 20% free space indicate significant fragmentation"}	{"threshold_pct": 20}	2026-05-11 22:17:39.229791
14432	mariadb	query	Check InnoDB tablespace fragmentation	{"sql": "SELECT NAME, FILE_SIZE, ALLOCATED_SIZE, ROUND((FILE_SIZE - ALLOCATED_SIZE) / NULLIF(FILE_SIZE, 0) * 100, 1) AS overhead_pct FROM information_schema.INNODB_TABLESPACES WHERE SPACE_TYPE = 'Single' ORDER BY FILE_SIZE DESC LIMIT 20"}	{"condition": "overhead_pct > 15", "description": "Tablespace overhead above 15% indicates internal fragmentation"}	{"threshold_pct": 15}	2026-05-11 22:17:39.229791
14433	mariadb	query	Check dirty page ratio in buffer pool	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_dirty') AS dirty_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_total') AS total_pages, ROUND((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_dirty') / NULLIF((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_pages_total'), 0) * 100, 1) AS dirty_pct"}	{"condition": "dirty_pct > 50", "description": "More than 50% dirty pages indicates heavy write activity consuming buffer pool"}	{"threshold_pct": 50}	2026-05-11 22:17:39.229791
14690	mariadb	query	Check privileges on socket-authenticated accounts	{"sql": "SELECT User, Host, Super_priv, Grant_priv FROM mysql.user WHERE plugin IN ('auth_socket', 'unix_socket') AND account_locked = 'N' AND (Super_priv = 'Y' OR Grant_priv = 'Y')"}	{"condition": "row_count > 0", "description": "Privileged accounts with trust-based authentication are security risks"}	\N	2026-05-11 22:17:39.229791
14434	mariadb	query	Check DML operation rates	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_rows_inserted') AS rows_inserted, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_rows_updated') AS rows_updated, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_rows_deleted') AS rows_deleted, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_writes') AS data_writes"}	{"condition": "rows_inserted + rows_updated + rows_deleted > 0", "description": "High cumulative DML activity confirmed"}	\N	2026-05-11 22:17:39.229791
14435	mariadb	query	Find tables with wide average row lengths	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, AVG_ROW_LENGTH, TABLE_ROWS, DATA_LENGTH, ROUND(16384.0 / NULLIF(AVG_ROW_LENGTH, 0), 0) AS rows_per_page FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND TABLE_SCHEMA NOT IN ('mysql', 'performance_schema', 'information_schema', 'sys') AND AVG_ROW_LENGTH > 4000 ORDER BY AVG_ROW_LENGTH DESC LIMIT 20"}	{"condition": "rows_per_page < 4", "description": "Fewer than 4 rows per 16KB page indicates wide row waste"}	{"min_rows_per_page": 4}	2026-05-11 22:17:39.229791
14436	mariadb	query	Check column types in wide-row tables	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME, DATA_TYPE, CHARACTER_MAXIMUM_LENGTH, NUMERIC_PRECISION FROM information_schema.COLUMNS WHERE DATA_TYPE IN ('varchar', 'char', 'text', 'blob', 'mediumtext', 'longtext', 'mediumblob', 'longblob') AND CHARACTER_MAXIMUM_LENGTH > 1000 AND TABLE_SCHEMA NOT IN ('mysql', 'performance_schema', 'information_schema', 'sys') ORDER BY CHARACTER_MAXIMUM_LENGTH DESC LIMIT 30"}	{"condition": "row_count > 0", "description": "Wide VARCHAR/TEXT columns identified that could be normalized or compressed"}	\N	2026-05-11 22:17:39.229791
14437	mariadb	query	Find unused indexes via performance_schema	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.INDEX_NAME, t.COUNT_STAR, t.COUNT_READ, t.COUNT_WRITE FROM information_schema.STATISTICS s LEFT JOIN performance_schema.table_io_waits_summary_by_index_usage t ON s.TABLE_SCHEMA = t.OBJECT_SCHEMA AND s.TABLE_NAME = t.OBJECT_NAME AND s.INDEX_NAME = t.INDEX_NAME WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'performance_schema', 'information_schema', 'sys') AND s.INDEX_NAME != 'PRIMARY' AND s.SEQ_IN_INDEX = 1 AND (t.COUNT_STAR IS NULL OR t.COUNT_STAR = 0) ORDER BY s.TABLE_SCHEMA, s.TABLE_NAME LIMIT 30"}	{"condition": "row_count > 0", "description": "Indexes with zero reads and zero writes since last reset are unused"}	\N	2026-05-11 22:17:39.229791
14438	mariadb	query	Calculate total index size for unused indexes	{"sql": "SELECT SUM(stat.STAT_VALUE * 16384) AS unused_index_bytes FROM mysql.innodb_index_stats stat WHERE stat.stat_name = 'size' AND stat.database_name NOT IN ('mysql', 'performance_schema', 'information_schema', 'sys') AND stat.index_name != 'PRIMARY' AND CONCAT(stat.database_name, '.', stat.table_name, '.', stat.index_name) NOT IN (SELECT CONCAT(OBJECT_SCHEMA, '.', OBJECT_NAME, '.', INDEX_NAME) FROM performance_schema.table_io_waits_summary_by_index_usage WHERE COUNT_STAR > 0)"}	{"condition": "unused_index_bytes > 104857600", "description": "More than 100MB of unused indexes wasting buffer pool space"}	{"threshold_bytes": 104857600}	2026-05-11 22:17:39.229791
14439	mariadb	query	Check for non-auto-increment primary keys on large tables	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE, c.EXTRA, t.TABLE_ROWS FROM information_schema.COLUMNS c JOIN information_schema.TABLES t ON c.TABLE_SCHEMA = t.TABLE_SCHEMA AND c.TABLE_NAME = t.TABLE_NAME WHERE c.COLUMN_KEY = 'PRI' AND c.EXTRA NOT LIKE '%auto_increment%' AND c.DATA_TYPE IN ('varchar', 'char', 'binary', 'varbinary') AND t.TABLE_ROWS > 10000 AND c.TABLE_SCHEMA NOT IN ('mysql', 'performance_schema', 'information_schema', 'sys') ORDER BY t.TABLE_ROWS DESC LIMIT 20"}	{"condition": "row_count > 0", "description": "Tables with non-sequential PKs are prone to random inserts causing page splits"}	\N	2026-05-11 22:17:39.229791
14440	mariadb	query	Check InnoDB merge operations indicating page splits	{"sql": "SELECT NAME, COUNT FROM information_schema.INNODB_METRICS WHERE NAME IN ('index_page_splits', 'index_page_merge_attempts', 'index_page_merge_successful', 'index_page_reorg_attempts') AND STATUS = 'enabled'"}	{"condition": "index_page_splits > 1000", "description": "High page split count confirms random insert fragmentation"}	{"threshold_splits": 1000}	2026-05-11 22:17:39.229791
14441	mariadb	query	Check for high select scan rate	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Select_scan') AS select_scans, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Select_range') AS select_ranges, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_read_rnd_next') AS sequential_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Handler_read_key') AS index_reads"}	{"condition": "select_scans > select_ranges * 2", "description": "Full scans significantly outnumbering range scans indicates analytical workload pattern"}	\N	2026-05-11 22:17:39.229791
