14544	mariadb	query	Check buffer pool hit ratio and disk reads	{"sql": "SELECT (1 - (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_reads') / NULLIF((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_requests'), 0)) * 100 AS hit_ratio_pct, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_reads') AS physical_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_reads') AS data_reads"}	{"condition": "hit_ratio_pct < 99", "description": "Buffer pool hit ratio below 99% indicates significant page cache misses"}	{"min_hit_ratio": 99}	2026-05-11 22:17:39.229791
14545	mariadb	query	Check IO wait events confirming disk reads	{"sql": "SELECT EVENT_NAME, COUNT_STAR, ROUND(SUM_TIMER_WAIT / 1000000000000, 2) AS total_seconds, ROUND(AVG_TIMER_WAIT / 1000000000, 2) AS avg_ms FROM performance_schema.events_waits_summary_global_by_event_name WHERE EVENT_NAME LIKE 'wait/io/file/innodb/innodb_data_file%' ORDER BY SUM_TIMER_WAIT DESC LIMIT 5"}	{"condition": "total_seconds > 10", "description": "Significant time spent waiting on InnoDB data file reads confirms cache misses"}	{"threshold_seconds": 10}	2026-05-11 22:17:39.229791
14546	mariadb	query	Check ratio of disk to memory temporary tables	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_disk_tables') AS disk_tables, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_tables') AS mem_tables, ROUND((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_disk_tables') / NULLIF((SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_tables'), 0) * 100, 2) AS disk_pct"}	{"condition": "disk_pct > :threshold_pct", "description": "High ratio of disk to memory temporary tables suggests hash join memory pressure"}	{"threshold_pct": 25}	2026-05-11 22:17:39.229791
14547	mariadb	query	Identify queries using hash joins with large result sets	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_CREATED_TMP_DISK_TABLES, SUM_CREATED_TMP_TABLES, AVG_TIMER_WAIT/1000000000 AS avg_ms FROM performance_schema.events_statements_summary_by_digest WHERE SUM_CREATED_TMP_DISK_TABLES > 0 ORDER BY SUM_CREATED_TMP_DISK_TABLES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries creating disk temporary tables confirm hash join memory pressure"}	\N	2026-05-11 22:17:39.229791
14548	mariadb	query	Find UNION queries creating disk temporary tables	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_CREATED_TMP_DISK_TABLES, SUM_SORT_MERGE_PASSES, AVG_TIMER_WAIT/1000000000 AS avg_ms FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%UNION%' AND DIGEST_TEXT NOT LIKE '%UNION ALL%' AND SUM_CREATED_TMP_DISK_TABLES > 0 ORDER BY SUM_CREATED_TMP_DISK_TABLES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "UNION queries without ALL creating disk temp tables confirm dedup spill"}	\N	2026-05-11 22:17:39.229791
14550	mariadb	query	Check for queries with high sort rows and disk sorts	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_SORT_ROWS, SUM_SORT_MERGE_PASSES, SUM_CREATED_TMP_DISK_TABLES, AVG_TIMER_WAIT/1000000000 AS avg_ms FROM performance_schema.events_statements_summary_by_digest WHERE SUM_SORT_MERGE_PASSES > 0 AND SUM_SORT_ROWS > :threshold ORDER BY SUM_SORT_MERGE_PASSES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Queries with sort merge passes and many sorted rows suggest late materialization sort spill"}	{"threshold": 10000}	2026-05-11 22:17:39.229791
14551	mariadb	config_check	Check max_length_for_sort_data setting	{"sql": "SELECT @@max_length_for_sort_data AS max_length_for_sort_data, @@sort_buffer_size AS sort_buffer_size"}	{"condition": "max_length_for_sort_data > 1024", "description": "High max_length_for_sort_data means wider rows are included in sort buffer, increasing spill risk"}	\N	2026-05-11 22:17:39.229791
