14554	mariadb	query	Check histogram staleness via last update time	{"sql": "SELECT SCHEMA_NAME, TABLE_NAME, COLUMN_NAME, HISTOGRAM->>'$.\\"last-updated\\"' AS last_updated, HISTOGRAM->>'$.\\"number-of-buckets-specified\\"' AS buckets FROM information_schema.COLUMN_STATISTICS ORDER BY last_updated ASC LIMIT 20"}	{"condition": "row_count > 0", "description": "Histograms exist; check if they are stale"}	\N	2026-05-11 22:17:39.229791
14555	mariadb	query	Check for disk temp tables on GROUP BY queries	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_CREATED_TMP_DISK_TABLES, SUM_ROWS_EXAMINED, AVG_TIMER_WAIT/1000000000 AS avg_ms FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%GROUP BY%' AND SUM_CREATED_TMP_DISK_TABLES > 0 ORDER BY SUM_CREATED_TMP_DISK_TABLES DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "GROUP BY queries spilling to disk suggest cardinality underestimation"}	\N	2026-05-11 22:17:39.229791
14556	mariadb	query	Find long-idle open transactions	{"sql": "SELECT trx.TRX_ID, trx.TRX_STATE, trx.TRX_STARTED, TIMESTAMPDIFF(SECOND, trx.TRX_STARTED, NOW()) AS trx_duration_sec, trx.TRX_ROWS_LOCKED, trx.TRX_ROWS_MODIFIED, p.USER, p.HOST, p.COMMAND, p.TIME AS idle_time_sec, LEFT(p.INFO, 200) AS last_query FROM information_schema.INNODB_TRX trx JOIN information_schema.PROCESSLIST p ON trx.TRX_MYSQL_THREAD_ID = p.ID WHERE p.COMMAND = 'Sleep' AND TIMESTAMPDIFF(SECOND, trx.TRX_STARTED, NOW()) > :threshold_sec ORDER BY trx_duration_sec DESC"}	{"condition": "row_count > 0", "description": "Open transactions with sleeping connections indicate waiting for external input"}	{"threshold_sec": 300}	2026-05-11 22:17:39.229791
14557	mariadb	query	Check if idle transactions hold locks	{"sql": "SELECT trx.TRX_ID, trx.TRX_ROWS_LOCKED, trx.TRX_LOCK_MEMORY_BYTES, COUNT(dl.ENGINE_LOCK_ID) AS lock_count FROM information_schema.INNODB_TRX trx LEFT JOIN performance_schema.data_locks dl ON trx.TRX_ID = dl.ENGINE_TRANSACTION_ID WHERE TIMESTAMPDIFF(SECOND, trx.TRX_STARTED, NOW()) > :threshold_sec GROUP BY trx.TRX_ID, trx.TRX_ROWS_LOCKED, trx.TRX_LOCK_MEMORY_BYTES HAVING lock_count > 0"}	{"condition": "row_count > 0", "description": "Idle transactions holding locks confirm user interaction pattern"}	{"threshold_sec": 300}	2026-05-11 22:17:39.229791
14558	mariadb	query	Find long-running transactions with sleeping connections	{"sql": "SELECT trx.TRX_ID, trx.TRX_STATE, trx.TRX_STARTED, TIMESTAMPDIFF(SECOND, trx.TRX_STARTED, NOW()) AS trx_duration_sec, trx.TRX_ROWS_MODIFIED, p.USER, p.HOST, p.COMMAND, p.TIME AS idle_time_sec FROM information_schema.INNODB_TRX trx JOIN information_schema.PROCESSLIST p ON trx.TRX_MYSQL_THREAD_ID = p.ID WHERE p.COMMAND = 'Sleep' AND trx.TRX_ROWS_MODIFIED > 0 AND TIMESTAMPDIFF(SECOND, trx.TRX_STARTED, NOW()) > :threshold_sec ORDER BY trx_duration_sec DESC"}	{"condition": "row_count > 0", "description": "Transactions with modifications but currently sleeping suggest external call during transaction"}	{"threshold_sec": 60}	2026-05-11 22:17:39.229791
14559	mariadb	query	Check connection pattern for intermittent activity	{"sql": "SELECT ess.THREAD_ID, ess.COUNT_STAR AS statement_count, ess.SUM_TIMER_WAIT/1000000000000 AS total_exec_sec, ess.SUM_LOCK_TIME/1000000000000 AS total_lock_sec FROM performance_schema.events_statements_summary_by_thread_by_event_name ess JOIN performance_schema.threads t ON ess.THREAD_ID = t.THREAD_ID WHERE t.PROCESSLIST_COMMAND = 'Sleep' AND ess.COUNT_STAR > 1 ORDER BY ess.SUM_TIMER_WAIT DESC LIMIT 10"}	{"condition": "row_count > 0", "description": "Multiple statements executed but connection now sleeping suggests API call pattern"}	\N	2026-05-11 22:17:39.229791
14560	mariadb	query	Find transactions with high rows examined but currently idle	{"sql": "SELECT trx.TRX_ID, trx.TRX_STATE, trx.TRX_STARTED, TIMESTAMPDIFF(SECOND, trx.TRX_STARTED, NOW()) AS trx_duration_sec, trx.TRX_ROWS_LOCKED, trx.TRX_ROWS_MODIFIED, p.USER, p.HOST, p.COMMAND, p.TIME AS idle_time_sec FROM information_schema.INNODB_TRX trx JOIN information_schema.PROCESSLIST p ON trx.TRX_MYSQL_THREAD_ID = p.ID WHERE p.COMMAND = 'Sleep' AND TIMESTAMPDIFF(SECOND, trx.TRX_STARTED, NOW()) > :threshold_sec ORDER BY trx_duration_sec DESC"}	{"condition": "row_count > 0", "description": "Open transactions that are idle indicate application-side processing"}	{"threshold_sec": 120}	2026-05-11 22:17:39.229791
