15203	mariadb	query	Find tables with high modification counter after bulk ops	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS AS num_rows, UPDATE_TIME, ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb FROM information_schema.TABLES WHERE TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_ROWS > 1000 AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY TABLE_ROWS DESC LIMIT 20"}	{"condition": "pct_modified > 50", "description": "Tables where more than 50% of rows were modified suggest a bulk operation that changed data distribution significantly"}	\N	2026-05-11 22:17:39.229791
15204	mariadb	query	Check histogram statistics status	{"sql": "SELECT SCHEMA_NAME, TABLE_NAME, COLUMN_NAME, JSON_EXTRACT(HISTOGRAM, '$.\\"last-updated\\"') AS last_updated, JSON_EXTRACT(HISTOGRAM, '$.\\"number-of-buckets-specified\\"') AS buckets FROM information_schema.COLUMN_STATISTICS ORDER BY last_updated ASC LIMIT 20;"}	{"condition": "last_updated is older than 7 days OR no histograms exist", "description": "Histogram statistics are stale or missing for columns used in WHERE clauses"}	\N	2026-05-11 22:17:39.229791
15205	mariadb	query	Check for columns with indexes but no histogram statistics	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.COLUMN_NAME, s.CARDINALITY FROM information_schema.STATISTICS s LEFT JOIN information_schema.COLUMN_STATISTICS cs ON s.TABLE_SCHEMA = cs.SCHEMA_NAME AND s.TABLE_NAME = cs.TABLE_NAME AND s.COLUMN_NAME = cs.COLUMN_NAME WHERE cs.COLUMN_NAME IS NULL AND s.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND s.SEQ_IN_INDEX = 1 ORDER BY s.TABLE_SCHEMA, s.TABLE_NAME LIMIT 20;"}	{"condition": "row_count > 0", "description": "Indexed columns without histogram statistics rely solely on index cardinality which may be insufficiently detailed"}	\N	2026-05-11 22:17:39.229791
15206	mariadb	query	Check statistics sample page configuration	{"sql": "SELECT @@global.innodb_stats_persistent_sample_pages AS global_sample_pages, TABLE_SCHEMA, TABLE_NAME, CREATE_OPTIONS FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND CREATE_OPTIONS LIKE '%STATS_SAMPLE_PAGES%' AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys');"}	{"condition": "global_sample_pages <= 8 OR per-table override is very low", "description": "Low sample page count produces imprecise cardinality estimates, especially on large tables with skewed data"}	\N	2026-05-11 22:17:39.229791
15207	mariadb	query	Check composite index cardinality	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS columns, GROUP_CONCAT(CARDINALITY ORDER BY SEQ_IN_INDEX) AS cardinalities FROM information_schema.STATISTICS WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND INDEX_NAME != 'PRIMARY' GROUP BY TABLE_SCHEMA, TABLE_NAME, INDEX_NAME HAVING COUNT(*) > 1 ORDER BY TABLE_SCHEMA, TABLE_NAME LIMIT 20;"}	{"condition": "cardinality values show unexpected patterns (e.g., later columns with higher cardinality than leading columns)", "description": "Composite index cardinality statistics may not reflect current data distribution"}	\N	2026-05-11 22:17:39.229791
15208	mariadb	query	Check histogram coverage vs actual data range	{"sql": "SELECT SCHEMA_NAME, TABLE_NAME, COLUMN_NAME, JSON_EXTRACT(HISTOGRAM, '$.\\"last-updated\\"') AS last_updated, JSON_EXTRACT(HISTOGRAM, '$.\\"number-of-buckets-specified\\"') AS buckets, JSON_EXTRACT(HISTOGRAM, '$.\\"data-type\\"') AS data_type FROM information_schema.COLUMN_STATISTICS WHERE JSON_EXTRACT(HISTOGRAM, '$.\\"last-updated\\"') < DATE_SUB(NOW(), INTERVAL 7 DAY);"}	{"condition": "row_count > 0 with stale histograms", "description": "Histograms updated more than 7 days ago may not cover new data ranges"}	\N	2026-05-11 22:17:39.229791
15209	mariadb	query	Find indexed columns without histogram statistics used in frequent queries	{"sql": "SELECT s.TABLE_SCHEMA, s.TABLE_NAME, s.COLUMN_NAME, s.CARDINALITY, (SELECT COUNT(*) FROM information_schema.COLUMN_STATISTICS cs WHERE cs.SCHEMA_NAME = s.TABLE_SCHEMA AND cs.TABLE_NAME = s.TABLE_NAME AND cs.COLUMN_NAME = s.COLUMN_NAME) AS has_histogram FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND s.SEQ_IN_INDEX = 1 ORDER BY s.CARDINALITY ASC LIMIT 20;"}	{"condition": "has_histogram = 0 for frequently queried columns", "description": "Indexed columns without histograms rely on basic cardinality estimates which may be insufficient"}	\N	2026-05-11 22:17:39.229791
15210	mariadb	query	Check partitioned tables for stale statistics	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, PARTITION_NAME, TABLE_ROWS, UPDATE_TIME FROM information_schema.PARTITIONS WHERE TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND PARTITION_NAME IS NOT NULL AND (UPDATE_TIME IS NULL OR UPDATE_TIME < DATE_SUB(NOW(), INTERVAL 7 DAY)) ORDER BY TABLE_ROWS DESC LIMIT 20;"}	{"condition": "row_count > 0", "description": "Partitions with stale or missing update timestamps indicate outdated statistics"}	\N	2026-05-11 22:17:39.229791
15211	mariadb	query	Check for tables with high modification counter after archival	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_ROWS AS num_rows, UPDATE_TIME, ROUND(DATA_LENGTH / 1024 / 1024, 2) AS data_mb FROM information_schema.TABLES WHERE TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_ROWS > 1000 AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY TABLE_ROWS DESC LIMIT 20"}	{"condition": "row_diff is large (>20% difference between info_schema and InnoDB estimates)", "description": "Large discrepancy between row estimates suggests statistics haven't caught up after data changes"}	\N	2026-05-11 22:17:39.229791
15212	mariadb	query	Check for multi-column predicates without composite indexes	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ROWS_EXAMINED, SUM_ROWS_SENT FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%WHERE%AND%' AND SUM_ROWS_EXAMINED > 10 * SUM_ROWS_SENT AND COUNT_STAR > 100 AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10;"}	{"condition": "row_count > 0 with high examine-to-sent ratio", "description": "Multi-column WHERE clauses with high examine:sent ratio suggest optimizer assuming column independence"}	\N	2026-05-11 22:17:39.229791
15213	mariadb	query	Find generated columns with indexes	{"sql": "SELECT c.TABLE_SCHEMA, c.TABLE_NAME, c.COLUMN_NAME, c.GENERATION_EXPRESSION, c.EXTRA FROM information_schema.COLUMNS c WHERE c.GENERATION_EXPRESSION IS NOT NULL AND c.GENERATION_EXPRESSION != '' AND c.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND EXISTS (SELECT 1 FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA = c.TABLE_SCHEMA AND s.TABLE_NAME = c.TABLE_NAME AND s.COLUMN_NAME = c.COLUMN_NAME) LIMIT 20;"}	{"condition": "row_count > 0", "description": "Generated columns with indexes may have stale statistics when base column data changes"}	\N	2026-05-11 22:17:39.229791
15214	mariadb	query	Check index cardinality accuracy	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, INDEX_NAME, COLUMN_NAME, CARDINALITY, (SELECT TABLE_ROWS FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA = s.TABLE_SCHEMA AND t.TABLE_NAME = s.TABLE_NAME) AS total_rows FROM information_schema.STATISTICS s WHERE SEQ_IN_INDEX = 1 AND CARDINALITY > 0 AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY TABLE_SCHEMA, TABLE_NAME LIMIT 20;"}	{"condition": "cardinality seems improbable relative to table size", "description": "Index cardinality that seems too high or too low relative to total rows suggests outdated density estimates"}	\N	2026-05-11 22:17:39.229791
15215	mariadb	query	Check for stale histograms on growing datasets	{"sql": "SELECT cs.SCHEMA_NAME, cs.TABLE_NAME, cs.COLUMN_NAME, JSON_EXTRACT(cs.HISTOGRAM, '$.\\"last-updated\\"') AS last_updated, t.TABLE_ROWS, t.UPDATE_TIME FROM information_schema.COLUMN_STATISTICS cs JOIN information_schema.TABLES t ON cs.SCHEMA_NAME = t.TABLE_SCHEMA AND cs.TABLE_NAME = t.TABLE_NAME WHERE t.UPDATE_TIME > JSON_UNQUOTE(JSON_EXTRACT(cs.HISTOGRAM, '$.\\"last-updated\\"'));"}	{"condition": "row_count > 0", "description": "Tables modified after histogram creation may have values outside the histogram range"}	\N	2026-05-11 22:17:39.229791
15216	mariadb	query	Find datetime column histograms that may be stale	{"sql": "SELECT cs.SCHEMA_NAME, cs.TABLE_NAME, cs.COLUMN_NAME, JSON_EXTRACT(cs.HISTOGRAM, '$.\\"last-updated\\"') AS last_updated, JSON_EXTRACT(cs.HISTOGRAM, '$.\\"data-type\\"') AS data_type FROM information_schema.COLUMN_STATISTICS cs JOIN information_schema.COLUMNS c ON cs.SCHEMA_NAME = c.TABLE_SCHEMA AND cs.TABLE_NAME = c.TABLE_NAME AND cs.COLUMN_NAME = c.COLUMN_NAME WHERE c.DATA_TYPE IN ('datetime', 'timestamp', 'date') AND JSON_EXTRACT(cs.HISTOGRAM, '$.\\"last-updated\\"') < DATE_SUB(NOW(), INTERVAL 3 DAY);"}	{"condition": "row_count > 0", "description": "Datetime histograms older than 3 days don't cover current time-series data"}	\N	2026-05-11 22:17:39.229791
15217	mariadb	query	Check InnoDB I/O metrics	{"sql": "SELECT (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'os_pending_reads') AS pending_reads, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'os_pending_writes') AS pending_writes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_reads') AS data_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_writes') AS data_writes;"}	{"condition": "pending_reads > 64 OR pending_writes > 64", "description": "High pending I/O requests indicate storage cannot keep up with MySQL demand"}	\N	2026-05-11 22:17:39.229791
15218	mariadb	query	Check if InnoDB I/O capacity is saturated	{"sql": "SELECT @@global.innodb_io_capacity AS io_capacity, @@global.innodb_io_capacity_max AS io_capacity_max, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_wait_free') AS wait_free;"}	{"condition": "wait_free > 0", "description": "Buffer pool waiting for free pages confirms I/O is the bottleneck"}	\N	2026-05-11 22:17:39.229791
15219	mariadb	query	Check InnoDB file I/O timing	{"sql": "SELECT EVENT_NAME, COUNT_STAR, SUM_TIMER_WAIT / 1000000000 AS total_wait_ms, AVG_TIMER_WAIT / 1000000 AS avg_wait_us, MAX_TIMER_WAIT / 1000000 AS max_wait_us FROM performance_schema.file_summary_by_event_name WHERE EVENT_NAME LIKE '%innodb%' AND COUNT_STAR > 0 ORDER BY SUM_TIMER_WAIT DESC LIMIT 10;"}	{"condition": "avg_wait_us > 1000 (1ms)", "description": "Average I/O wait exceeding 1ms indicates slow storage subsystem"}	\N	2026-05-11 22:17:39.229791
15220	mariadb	query	Check InnoDB flush method and fsync overhead	{"sql": "SELECT @@global.innodb_flush_method AS flush_method, @@global.innodb_flush_log_at_trx_commit AS flush_log_at_commit, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_os_log_fsyncs') AS log_fsyncs, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_fsyncs') AS data_fsyncs;"}	{"condition": "flush_log_at_commit = 1 AND high fsync count", "description": "innodb_flush_log_at_trx_commit=1 with no BBU means every commit triggers a synchronous write to disk"}	\N	2026-05-11 22:17:39.229791
15221	mariadb	query	Check I/O wait patterns across file types	{"sql": "SELECT FILE_NAME, COUNT_READ, COUNT_WRITE, SUM_TIMER_READ / 1000000000 AS read_wait_ms, SUM_TIMER_WRITE / 1000000000 AS write_wait_ms FROM performance_schema.file_summary_by_instance WHERE FILE_NAME LIKE '%ibdata%' OR FILE_NAME LIKE '%ibd' OR FILE_NAME LIKE '%ib_logfile%' OR FILE_NAME LIKE '%binlog%' ORDER BY SUM_TIMER_READ + SUM_TIMER_WRITE DESC LIMIT 10;"}	{"condition": "all file types showing high wait times uniformly", "description": "Uniform high latency across all file types suggests a shared storage controller bottleneck"}	\N	2026-05-11 22:17:39.229791
15222	mariadb	query	Check for fragmented tables with high DATA_FREE	{"sql": "SELECT TABLE_SCHEMA, TABLE_NAME, DATA_LENGTH, DATA_FREE, ROUND(DATA_FREE / NULLIF(DATA_LENGTH + DATA_FREE, 0) * 100, 2) AS fragmentation_pct, TABLE_ROWS FROM information_schema.TABLES WHERE ENGINE = 'InnoDB' AND DATA_FREE > 0 AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') ORDER BY DATA_FREE DESC LIMIT 10;"}	{"condition": "fragmentation_pct > 15", "description": "Tables with more than 15% fragmentation waste I/O reading sparse pages"}	\N	2026-05-11 22:17:39.229791
15223	mariadb	query	Check ratio of random to sequential reads	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_reads') AS random_disk_reads, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_ahead') AS readahead_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_data_reads') AS total_reads;"}	{"condition": "random_disk_reads >> readahead_pages", "description": "Random disk reads far exceeding sequential read-ahead indicates random I/O dominated workload"}	\N	2026-05-11 22:17:39.229791
15224	mariadb	query	Check average I/O latency per file operation	{"sql": "SELECT EVENT_NAME, COUNT_STAR, AVG_TIMER_WAIT / 1000000 AS avg_wait_us FROM performance_schema.file_summary_by_event_name WHERE EVENT_NAME LIKE '%innodb%data%' AND COUNT_STAR > 1000 ORDER BY AVG_TIMER_WAIT DESC LIMIT 5;"}	{"condition": "avg_wait_us > 5000 (5ms)", "description": "Average I/O latency exceeding 5ms per operation is characteristic of spinning disks under load"}	\N	2026-05-11 22:17:39.229791
