15226	mariadb	query	Check for variable I/O latency suggesting contention	{"sql": "SELECT EVENT_NAME, COUNT_STAR, AVG_TIMER_WAIT / 1000000 AS avg_wait_us, MAX_TIMER_WAIT / 1000000 AS max_wait_us, (MAX_TIMER_WAIT / NULLIF(AVG_TIMER_WAIT, 0)) AS max_to_avg_ratio FROM performance_schema.file_summary_by_event_name WHERE EVENT_NAME LIKE '%innodb%' AND COUNT_STAR > 100 ORDER BY max_to_avg_ratio DESC LIMIT 5;"}	{"condition": "max_to_avg_ratio > 100", "description": "Very high max-to-average latency ratio suggests intermittent contention from shared storage"}	\N	2026-05-11 22:17:39.229791
15227	mariadb	query	Check for periodic I/O latency spikes	{"sql": "SELECT EVENT_NAME, MAX_TIMER_WAIT / 1000000000 AS max_wait_ms FROM performance_schema.file_summary_by_event_name WHERE EVENT_NAME LIKE '%innodb%data%' AND MAX_TIMER_WAIT > 1000000000000;"}	{"condition": "max_wait_ms > 1000 (1 second)", "description": "I/O operations taking more than 1 second suggest storage array maintenance or rebuild activity"}	\N	2026-05-11 22:17:39.229791
15228	mariadb	query	Check read-ahead effectiveness	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_ahead') AS readahead_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_buffer_pool_read_ahead_evicted') AS readahead_evicted, @@global.innodb_read_ahead_threshold AS readahead_threshold;"}	{"condition": "readahead_evicted / readahead_pages > 0.5 OR readahead_pages is very low", "description": "High read-ahead eviction rate means prefetched pages are wasted, or low read-ahead means sequential scans are not optimized"}	\N	2026-05-11 22:17:39.229791
15229	mariadb	query	Check I/O latency consistency across file types	{"sql": "SELECT SUBSTRING_INDEX(FILE_NAME, '/', -1) AS file_short, COUNT_READ, COUNT_WRITE, SUM_TIMER_READ / NULLIF(COUNT_READ, 0) / 1000000 AS avg_read_us, SUM_TIMER_WRITE / NULLIF(COUNT_WRITE, 0) / 1000000 AS avg_write_us FROM performance_schema.file_summary_by_instance WHERE (FILE_NAME LIKE '%.ibd' OR FILE_NAME LIKE '%ib_logfile%' OR FILE_NAME LIKE '%ibdata%') AND COUNT_READ + COUNT_WRITE > 100 ORDER BY avg_read_us DESC LIMIT 10;"}	{"condition": "avg_read_us > 2000 across all files", "description": "Uniformly high latency across all MySQL files suggests network storage path saturation"}	\N	2026-05-11 22:17:39.229791
15230	mariadb	query	Check for write latency spikes suggesting cache overflow	{"sql": "SELECT EVENT_NAME, AVG_TIMER_WAIT / 1000000 AS avg_us, MAX_TIMER_WAIT / 1000000 AS max_us, COUNT_STAR FROM performance_schema.file_summary_by_event_name WHERE EVENT_NAME LIKE '%innodb%log%' AND COUNT_STAR > 100;"}	{"condition": "max_us > 100000 AND avg_us < 1000", "description": "Occasional extreme write latency spikes with low average suggests SSD/controller cache overflow"}	\N	2026-05-11 22:17:39.229791
15231	mariadb	query	Check recent deadlock information	{"sql": "SHOW ENGINE INNODB STATUS;"}	{"condition": "LATEST DETECTED DEADLOCK section shows index lock conflicts", "description": "InnoDB status shows deadlocks involving different index lock orders"}	\N	2026-05-11 22:17:39.229791
15232	mariadb	query	Check for INSERT-related deadlocks	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks') AS deadlock_count, DIGEST_TEXT, SUM_ERRORS FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%INSERT%' AND SUM_ERRORS > 0 AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_ERRORS DESC LIMIT 5;"}	{"condition": "deadlock_count > 0 AND INSERT errors present", "description": "INSERT errors combined with deadlocks suggest unique key constraint deadlocks"}	\N	2026-05-11 22:17:39.229791
15406	mariadb	query	Check sort-related global status counters	{"sql": "SELECT gs.VARIABLE_NAME, gs.VARIABLE_VALUE FROM performance_schema.global_status gs WHERE gs.VARIABLE_NAME IN ('Sort_merge_passes', 'Sort_rows', 'Sort_range', 'Sort_scan') UNION ALL SELECT 'sort_buffer_size', CAST(@@sort_buffer_size AS CHAR)"}	{"condition": "Sort_merge_passes > 0", "description": "Sort_merge_passes > 0 indicates sorts that exceeded sort_buffer_size and required multi-pass merge sort using temporary files"}	\N	2026-05-11 22:17:39.229791
15233	mariadb	query	Check for page split activity and deadlocks	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks') AS deadlocks, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_splits') AS page_splits, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_merge_attempts') AS merge_attempts;"}	{"condition": "deadlocks > 0 AND page_splits is high relative to uptime", "description": "High page split rate correlating with deadlocks suggests split-related lock contention"}	\N	2026-05-11 22:17:39.229791
15234	mariadb	query	Check default and session isolation levels	{"sql": "SELECT @@global.transaction_isolation AS global_isolation, (SELECT COUNT(*) FROM information_schema.INNODB_TRX WHERE trx_isolation_level = 'SERIALIZABLE') AS serializable_trx, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks') AS deadlocks;"}	{"condition": "global_isolation = 'SERIALIZABLE' OR serializable_trx > 0", "description": "SERIALIZABLE isolation converts all SELECT to SELECT ... LOCK IN SHARE MODE, increasing deadlock probability"}	\N	2026-05-11 22:17:39.229791
15235	mariadb	query	Check for multi-statement transaction deadlocks	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks') AS deadlocks, trx_id, trx_state, trx_rows_locked, trx_rows_modified, trx_query FROM information_schema.INNODB_TRX WHERE trx_rows_locked > 10 AND trx_rows_modified > 1 ORDER BY trx_rows_locked DESC LIMIT 10;"}	{"condition": "deadlocks > 0 AND transactions with multiple row modifications and many locks", "description": "Transactions modifying multiple rows with many locks suggest multi-statement UPDATE patterns prone to deadlocks"}	\N	2026-05-11 22:17:39.229791
15236	mariadb	query	Check for deadlock error frequency	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_ERRORS, ROUND(SUM_ERRORS / NULLIF(COUNT_STAR, 0) * 100, 2) AS error_pct, LAST_SEEN FROM performance_schema.events_statements_summary_by_digest WHERE SUM_ERRORS > 0 AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_ERRORS DESC LIMIT 10;"}	{"condition": "high error_pct on DML statements", "description": "High error percentage on specific DML statements suggests deadlock errors not being retried"}	\N	2026-05-11 22:17:39.229791
15237	mariadb	query	Check for transactions with many row locks	{"sql": "SELECT trx_id, trx_state, trx_rows_locked, trx_rows_modified, trx_lock_structs, trx_mysql_thread_id, LEFT(trx_query, 200) AS query_prefix FROM information_schema.INNODB_TRX WHERE trx_rows_locked > 5000 ORDER BY trx_rows_locked DESC LIMIT 10;"}	{"condition": "trx_rows_locked > 5000", "description": "Transactions holding more than 5000 row locks indicate potential lock escalation-like behavior"}	\N	2026-05-11 22:17:39.229791
15238	mariadb	query	Find blocking transactions	{"sql": "SELECT waiting_trx_id, waiting_pid AS waiting_thread, waiting_query, blocking_trx_id, blocking_pid AS blocking_thread, blocking_query, wait_age FROM sys.innodb_lock_waits"}	{"condition": "row_count > 0", "description": "Active lock waits confirm blocking transactions are holding locks"}	\N	2026-05-11 22:17:39.229791
15239	mariadb	query	Find long-running queries without index usage	{"sql": "SELECT TRX_ID, TRX_ROWS_LOCKED, TRX_ROWS_MODIFIED, TRX_QUERY, TIMESTAMPDIFF(SECOND, TRX_STARTED, NOW()) AS duration_sec FROM information_schema.INNODB_TRX WHERE TRX_ROWS_LOCKED > 1000 AND TRX_QUERY IS NOT NULL ORDER BY TRX_ROWS_LOCKED DESC LIMIT 10"}	{"condition": "trx_rows_locked > 1000 AND duration > 5 seconds", "description": "Queries locking many rows for extended periods suggest full table scans under locking reads"}	\N	2026-05-11 22:17:39.229791
15240	mariadb	query	Find DML statements with no index used and many rows locked	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_NO_INDEX_USED, SUM_ROWS_EXAMINED, SUM_ROWS_AFFECTED FROM performance_schema.events_statements_summary_by_digest WHERE SUM_NO_INDEX_USED > 0 AND (DIGEST_TEXT LIKE '%UPDATE%' OR DIGEST_TEXT LIKE '%DELETE%') AND SUM_ROWS_EXAMINED > 1000 ORDER BY SUM_ROWS_EXAMINED DESC LIMIT 10;"}	{"condition": "row_count > 0", "description": "UPDATE/DELETE without index usage examining many rows locks all examined rows"}	\N	2026-05-11 22:17:39.229791
15241	mariadb	query	Find transactions with very high row modification counts	{"sql": "SELECT trx_id, trx_state, trx_started, trx_rows_locked, trx_rows_modified, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS duration_sec FROM information_schema.INNODB_TRX WHERE trx_rows_modified > 10000 OR trx_rows_locked > 50000 ORDER BY trx_rows_locked DESC LIMIT 10;"}	{"condition": "trx_rows_modified > 10000 OR trx_rows_locked > 50000", "description": "Bulk operations modifying many rows hold locks for extended periods, blocking concurrent access"}	\N	2026-05-11 22:17:39.229791
15242	mariadb	query	Check for transactions with extreme row lock counts	{"sql": "SELECT trx_id, trx_rows_locked, trx_lock_structs, trx_isolation_level, LEFT(trx_query, 200) AS query FROM information_schema.INNODB_TRX WHERE trx_rows_locked > 10000 ORDER BY trx_rows_locked DESC LIMIT 5;"}	{"condition": "trx_rows_locked > 10000", "description": "Very high row lock count effectively blocks all access, similar to table-level lock escalation"}	\N	2026-05-11 22:17:39.229791
15243	mariadb	query	Find idle connections with active transactions and locks	{"sql": "SELECT t.trx_id, t.trx_started, t.trx_rows_locked, t.trx_lock_structs, p.ID, p.USER, p.HOST, p.COMMAND, p.TIME AS idle_seconds FROM information_schema.INNODB_TRX t JOIN information_schema.PROCESSLIST p ON t.trx_mysql_thread_id = p.ID WHERE p.COMMAND = 'Sleep' AND t.trx_rows_locked > 0 ORDER BY p.TIME DESC LIMIT 10;"}	{"condition": "row_count > 0 AND idle_seconds > 60", "description": "Idle connections holding row locks block other transactions from accessing those rows"}	\N	2026-05-11 22:17:39.229791
15244	mariadb	query	Check deadlock detection configuration and frequency	{"sql": "SELECT @@global.innodb_deadlock_detect AS deadlock_detect, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_deadlocks') AS deadlock_count;"}	{"condition": "deadlock_detect = ON AND deadlock_count is high relative to uptime", "description": "Frequent deadlock detection cycles consume CPU and can delay lock resolution"}	\N	2026-05-11 22:17:39.229791
15245	mariadb	query	Check auto-increment lock mode and contention	{"sql": "SELECT @@global.innodb_autoinc_lock_mode AS lock_mode, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS lock_waits, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'index_page_splits') AS page_splits;"}	{"condition": "lock_mode < 2 AND lock_waits is high", "description": "innodb_autoinc_lock_mode < 2 (interleaved) uses table-level AUTO-INC lock for bulk inserts"}	\N	2026-05-11 22:17:39.229791
15246	mariadb	query	Check connection utilization	{"sql": "SELECT @@global.max_connections AS max_connections, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_connected') AS threads_connected, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Threads_running') AS threads_running, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Connection_errors_max_connections') AS max_conn_errors;"}	{"condition": "threads_connected > max_connections * 0.9 OR max_conn_errors > 0", "description": "Connection pool near capacity or connection rejections indicate exhaustion"}	\N	2026-05-11 22:17:39.229791
15247	mariadb	query	Check foreign key constraints and their indexes	{"sql": "SELECT rc.CONSTRAINT_SCHEMA, rc.TABLE_NAME AS child_table, rc.REFERENCED_TABLE_NAME AS parent_table, kcu.COLUMN_NAME AS fk_column, kcu.REFERENCED_COLUMN_NAME AS ref_column FROM information_schema.REFERENTIAL_CONSTRAINTS rc JOIN information_schema.KEY_COLUMN_USAGE kcu ON rc.CONSTRAINT_SCHEMA = kcu.CONSTRAINT_SCHEMA AND rc.CONSTRAINT_NAME = kcu.CONSTRAINT_NAME WHERE rc.CONSTRAINT_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys');"}	{"condition": "foreign key columns exist", "description": "Foreign key relationships found — verify indexes exist on both sides"}	\N	2026-05-11 22:17:39.229791
15248	mariadb	query	Check InnoDB lock waits related to FK operations	{"sql": "SELECT (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS total_lock_waits;"}	{"condition": "total_lock_waits is high relative to uptime", "description": "High lock wait count may include FK-related shared lock acquisitions on parent tables"}	\N	2026-05-11 22:17:39.229791
15249	mariadb	query	Check lock wait timeout and timeout frequency	{"sql": "SELECT @@global.innodb_lock_wait_timeout AS lock_wait_timeout, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_timeouts') AS lock_timeouts, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS lock_waits;"}	{"condition": "lock_timeouts > 0 AND lock_timeouts / lock_waits > 0.1", "description": "More than 10% of lock waits resulting in timeouts suggests lock_wait_timeout is too short or there are persistent blocking issues"}	\N	2026-05-11 22:17:39.229791
15250	mariadb	query	Check isolation level and gap lock indicators	{"sql": "SELECT @@global.transaction_isolation AS isolation, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS lock_waits, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_timeouts') AS timeouts;"}	{"condition": "isolation = 'REPEATABLE-READ' AND lock_waits is high", "description": "REPEATABLE-READ gap locks can block INSERT operations in ranges between existing keys"}	\N	2026-05-11 22:17:39.229791
15251	mariadb	query	Check row lock wait metrics	{"sql": "SELECT (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS row_lock_waits, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_time') AS row_lock_time_ms, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_time_avg') AS avg_lock_time_ms;"}	{"condition": "row_lock_waits > 1000 per hour AND avg_lock_time_ms > 100", "description": "High row lock wait count with significant average wait time indicates contention"}	\N	2026-05-11 22:17:39.229791
15252	mariadb	query	Check for MyISAM tables and table lock waits	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Table_locks_waited') AS table_lock_waits, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Table_locks_immediate') AS table_lock_immediate, (SELECT COUNT(*) FROM information_schema.TABLES WHERE ENGINE = 'MyISAM' AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys')) AS myisam_tables;"}	{"condition": "table_lock_waits > 0 OR myisam_tables > 0", "description": "Table lock waits or MyISAM tables indicate table-level lock contention"}	\N	2026-05-11 22:17:39.229791
15253	mariadb	query	Check InnoDB mutex and semaphore waits	{"sql": "SHOW ENGINE INNODB MUTEX;"}	{"condition": "mutex waits with high os_waits count", "description": "High OS wait counts on InnoDB mutexes indicate internal contention bottlenecks"}	\N	2026-05-11 22:17:39.229791
15254	mariadb	query	Check for global lock status	{"sql": "SELECT ID, USER, HOST, COMMAND, TIME, STATE, LEFT(INFO, 200) AS query FROM information_schema.PROCESSLIST WHERE STATE LIKE '%Waiting for global read lock%' OR STATE LIKE '%Waiting for table flush%' OR INFO LIKE '%FLUSH TABLE%READ LOCK%' ORDER BY TIME DESC;"}	{"condition": "row_count > 0", "description": "Sessions waiting for or holding global read locks block all write operations"}	\N	2026-05-11 22:17:39.229791
15255	mariadb	query	Check lock types in current wait scenarios	{"sql": "SELECT LOCK_TYPE, LOCK_MODE, LOCK_STATUS, LOCK_DATA, COUNT(*) AS cnt FROM performance_schema.data_locks GROUP BY LOCK_TYPE, LOCK_MODE, LOCK_STATUS, LOCK_DATA ORDER BY cnt DESC LIMIT 20;"}	{"condition": "GAP or next-key lock modes with high counts", "description": "High gap or next-key lock counts indicate InnoDB is locking index ranges unnecessarily wide"}	\N	2026-05-11 22:17:39.229791
15256	mariadb	query	Check adaptive hash index contention	{"sql": "SELECT @@global.innodb_adaptive_hash_index AS ahi_enabled, @@global.innodb_adaptive_hash_index_parts AS ahi_parts, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'adaptive_hash_searches') AS ahi_searches, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'adaptive_hash_searches_btree') AS btree_searches;"}	{"condition": "ahi_enabled = 1 AND ahi_searches / (ahi_searches + btree_searches) < 0.5", "description": "Adaptive hash index is enabled but has low hit ratio, suggesting it may be causing more contention than benefit"}	\N	2026-05-11 22:17:39.229791
15257	mariadb	query	Check buffer pool instance configuration	{"sql": "SELECT @@global.innodb_buffer_pool_size AS pool_size, @@global.innodb_buffer_pool_instances AS pool_instances, ROUND(@@global.innodb_buffer_pool_size / @@global.innodb_buffer_pool_instances / 1024 / 1024, 0) AS mb_per_instance;"}	{"condition": "pool_instances = 1 AND pool_size > 1073741824", "description": "Single buffer pool instance with >1GB creates a contention bottleneck under high concurrency"}	\N	2026-05-11 22:17:39.229791
15258	mariadb	query	Check redo log write wait metrics	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_log_waits') AS log_waits, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_log_write_requests') AS write_requests, @@global.innodb_flush_log_at_trx_commit AS flush_at_commit;"}	{"condition": "log_waits > 0 AND log_waits / write_requests > 0.01", "description": "Redo log waits indicate serialization on the log writer, a throughput bottleneck"}	\N	2026-05-11 22:17:39.229791
15259	mariadb	query	Check doublewrite metrics	{"sql": "SELECT @@global.innodb_doublewrite AS doublewrite_enabled, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_dblwr_pages_written') AS dblwr_pages, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_dblwr_writes') AS dblwr_writes;"}	{"condition": "doublewrite_enabled = 1 AND dblwr_pages / dblwr_writes < 4", "description": "Low pages-per-write ratio on doublewrite suggests inefficient batching, adding write overhead"}	\N	2026-05-11 22:17:39.229791
15260	mariadb	query	Check purge thread configuration and lag	{"sql": "SELECT @@global.innodb_purge_threads AS purge_threads, @@global.innodb_purge_batch_size AS batch_size, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'trx_rseg_history_len') AS history_len;"}	{"condition": "history_len > 10000 AND purge_threads < 4", "description": "Growing history list with few purge threads indicates purge is a bottleneck"}	\N	2026-05-11 22:17:39.229791
15261	mariadb	query	Check change buffer metrics	{"sql": "SELECT @@global.innodb_change_buffering AS change_buffering, @@global.innodb_change_buffer_max_size AS max_size_pct, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'ibuf_merges') AS merges, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'ibuf_merges_insert') AS merge_inserts;"}	{"condition": "merges is high relative to uptime AND max_size_pct > 25", "description": "High change buffer merge rate indicates secondary index updates are being deferred and merged, potentially causing contention"}	\N	2026-05-11 22:17:39.229791
15262	mariadb	query	Check temporary table usage and disk temp tables	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_tables') AS tmp_tables, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Created_tmp_disk_tables') AS tmp_disk_tables, @@global.tmp_table_size AS tmp_table_size, @@global.max_heap_table_size AS max_heap_size, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'internal_tmp_mem_storage_engine') AS tmp_engine"}	{"condition": "tmp_disk_tables / tmp_tables > 0.25", "description": "More than 25% of temporary tables spilling to disk indicates memory-based temp tables are too small"}	\N	2026-05-11 22:17:39.229791
15263	mariadb	query	Check for SELECT ... LOCK IN SHARE MODE or FOR SHARE usage	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_LOCK_TIME / 1000000 AS total_lock_time_ms FROM performance_schema.events_statements_summary_by_digest WHERE (DIGEST_TEXT LIKE '%LOCK IN SHARE MODE%' OR DIGEST_TEXT LIKE '%FOR SHARE%') AND COUNT_STAR > 10 AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_LOCK_TIME DESC LIMIT 10;"}	{"condition": "row_count > 0", "description": "Explicit shared lock requests create contention with concurrent modifications"}	\N	2026-05-11 22:17:39.229791
15264	mariadb	query	Check for SELECT FOR UPDATE usage patterns	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_LOCK_TIME / 1000000 AS total_lock_time_ms, SUM_ROWS_EXAMINED FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%FOR UPDATE%' AND COUNT_STAR > 10 AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_LOCK_TIME DESC LIMIT 10;"}	{"condition": "row_count > 0 AND SUM_ROWS_EXAMINED is high", "description": "SELECT FOR UPDATE locking many rows creates exclusive locks that block all concurrent access"}	\N	2026-05-11 22:17:39.229791
15265	mariadb	query	Check isolation level configuration	{"sql": "SELECT @@global.transaction_isolation AS global_isolation, (SELECT COUNT(*) FROM information_schema.INNODB_TRX) AS active_trx, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS lock_waits;"}	{"condition": "global_isolation = 'SERIALIZABLE' OR (global_isolation = 'REPEATABLE-READ' AND lock_waits is very high)", "description": "Higher isolation levels increase lock scope and contention"}	\N	2026-05-11 22:17:39.229791
15266	mariadb	query	Check for gap lock waits in data_locks	{"sql": "SELECT LOCK_TYPE, LOCK_MODE, COUNT(*) AS lock_count FROM performance_schema.data_locks WHERE LOCK_TYPE = 'RECORD' AND LOCK_MODE LIKE '%GAP%' GROUP BY LOCK_TYPE, LOCK_MODE;"}	{"condition": "lock_count > 100", "description": "High gap lock count indicates REPEATABLE-READ gap locking is causing contention"}	\N	2026-05-11 22:17:39.229791
15267	mariadb	query	Find long-running transactions with row locks	{"sql": "SELECT trx_id, trx_started, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS duration_sec, trx_rows_locked, trx_rows_modified, trx_isolation_level FROM information_schema.INNODB_TRX WHERE trx_rows_locked > 0 AND TIMESTAMPDIFF(SECOND, trx_started, NOW()) > 60 ORDER BY duration_sec DESC LIMIT 10;"}	{"condition": "row_count > 0", "description": "Transactions holding locks for more than 60 seconds block concurrent access"}	\N	2026-05-11 22:17:39.229791
15268	mariadb	query	Check autocommit configuration	{"sql": "SELECT @@global.autocommit AS global_autocommit, (SELECT COUNT(*) FROM information_schema.INNODB_TRX WHERE trx_autocommit_non_locking = 0) AS explicit_trx;"}	{"condition": "global_autocommit = 0", "description": "autocommit=OFF means every query starts an implicit transaction that holds locks until explicit COMMIT"}	\N	2026-05-11 22:17:39.229791
15269	mariadb	query	Find transactions with long duration but low modification count	{"sql": "SELECT trx_id, trx_started, TIMESTAMPDIFF(SECOND, trx_started, NOW()) AS duration_sec, trx_rows_modified, trx_rows_locked, p.COMMAND, p.STATE FROM information_schema.INNODB_TRX t JOIN information_schema.PROCESSLIST p ON t.trx_mysql_thread_id = p.ID WHERE TIMESTAMPDIFF(SECOND, trx_started, NOW()) > 30 AND (trx_rows_modified < 10 OR p.COMMAND = 'Sleep') ORDER BY duration_sec DESC LIMIT 10;"}	{"condition": "duration_sec > 30 AND trx_rows_modified < 10", "description": "Long transactions modifying few rows suggest the transaction scope is wider than necessary"}	\N	2026-05-11 22:17:39.229791
15270	mariadb	query	Check INSERT rate and auto-increment mode	{"sql": "SELECT @@global.innodb_autoinc_lock_mode AS autoinc_mode, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_insert') AS insert_count, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Innodb_row_lock_waits') AS lock_waits;"}	{"condition": "autoinc_mode < 2 AND insert_count is high AND lock_waits > 0", "description": "High INSERT rate with conservative auto-increment lock mode creates serialization"}	\N	2026-05-11 22:17:39.229791
15271	mariadb	query	Check for tables with foreign keys and high lock waits	{"sql": "SELECT rc.TABLE_NAME AS child_table, rc.REFERENCED_TABLE_NAME AS parent_table, COUNT(*) AS fk_count FROM information_schema.REFERENTIAL_CONSTRAINTS rc WHERE rc.CONSTRAINT_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') GROUP BY rc.TABLE_NAME, rc.REFERENCED_TABLE_NAME HAVING fk_count > 0;"}	{"condition": "row_count > 0", "description": "Foreign key relationships require shared locks on parent rows during child operations, amplifying total lock count"}	\N	2026-05-11 22:17:39.229791
15272	mariadb	query	Check for row-level lock waits on specific records	{"sql": "SELECT OBJECT_SCHEMA, OBJECT_NAME, LOCK_TYPE, LOCK_MODE, LOCK_DATA, COUNT(*) AS wait_count FROM performance_schema.data_lock_waits dlw JOIN performance_schema.data_locks dl ON dlw.BLOCKING_ENGINE_LOCK_ID = dl.ENGINE_LOCK_ID GROUP BY OBJECT_SCHEMA, OBJECT_NAME, LOCK_TYPE, LOCK_MODE, LOCK_DATA ORDER BY wait_count DESC LIMIT 10;"}	{"condition": "row_count > 0 AND specific LOCK_DATA values appear repeatedly", "description": "Same row IDs appearing in multiple lock waits confirm hot row contention"}	\N	2026-05-11 22:17:39.229791
15273	mariadb	query	Check for SELECT followed by UPDATE patterns	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_LOCK_TIME / 1000000 AS lock_time_ms FROM performance_schema.events_statements_summary_by_digest WHERE (DIGEST_TEXT LIKE '%FOR UPDATE%' OR DIGEST_TEXT LIKE '%LOCK IN SHARE MODE%') AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_LOCK_TIME DESC LIMIT 10;"}	{"condition": "row_count > 0 with high lock_time", "description": "SELECT with explicit locking followed by UPDATE creates lock conversion contention"}	\N	2026-05-11 22:17:39.229791
15579	mariadb	query	PRI-008-RC01 No recent binlog (mysql)	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'log_bin' AND LOWER(VARIABLE_VALUE) = 'off'"}	{"condition": "row_count > 0", "description": "binary logging disabled — no PITR possible"}	\N	2026-05-11 22:17:39.229791
15275	mariadb	query	Check for ON DUPLICATE KEY UPDATE frequency	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_LOCK_TIME / 1000000 AS lock_time_ms FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%ON DUPLICATE KEY UPDATE%' AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_LOCK_TIME DESC LIMIT 10;"}	{"condition": "row_count > 0 AND lock_time_ms is high", "description": "INSERT ON DUPLICATE KEY UPDATE acquires exclusive locks, creating contention on frequently updated rows"}	\N	2026-05-11 22:17:39.229791
15276	mariadb	query	Check for REPLACE INTO usage	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_LOCK_TIME / 1000000 AS lock_time_ms, SUM_ROWS_AFFECTED FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%REPLACE%' AND LAST_SEEN > DATE_SUB(NOW(), INTERVAL 1 HOUR) ORDER BY SUM_LOCK_TIME DESC LIMIT 10;"}	{"condition": "row_count > 0 AND SUM_ROWS_AFFECTED > COUNT_STAR * 2", "description": "REPLACE affecting 2+ rows per statement (DELETE + INSERT) generates more lock events than UPDATE"}	\N	2026-05-11 22:17:39.229791
15277	mariadb	query	Check lock distribution across indexes	{"sql": "SELECT OBJECT_SCHEMA, OBJECT_NAME, INDEX_NAME, LOCK_MODE, COUNT(*) AS lock_count FROM performance_schema.data_locks WHERE LOCK_TYPE = 'RECORD' GROUP BY OBJECT_SCHEMA, OBJECT_NAME, INDEX_NAME, LOCK_MODE ORDER BY lock_count DESC LIMIT 20;"}	{"condition": "secondary index locks with high counts", "description": "High lock counts on secondary indexes indicate contention from concurrent DML on indexed columns"}	\N	2026-05-11 22:17:39.229791
15278	mariadb	query	Check InnoDB semaphore waits	{"sql": "SHOW ENGINE INNODB STATUS;"}	{"condition": "SEMAPHORES section shows active waits or long wait times", "description": "InnoDB semaphore waits indicate internal latch contention"}	\N	2026-05-11 22:17:39.229791
15279	mariadb	query	Check spin wait configuration	{"sql": "SELECT @@global.innodb_spin_wait_delay AS spin_delay, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'innodb_spin_wait_pause_multiplier') AS pause_multiplier, @@global.innodb_sync_spin_loops AS sync_spin_loops"}	{"condition": "sync_spin_loops > 30 AND high CPU usage observed", "description": "High spin loop count before OS wait causes CPU waste on busy-wait loops"}	\N	2026-05-11 22:17:39.229791
15280	mariadb	query	Check table_open_cache and dictionary access patterns	{"sql": "SELECT @@global.table_open_cache AS open_cache, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Open_tables') AS open_tables, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Opened_tables') AS total_opened, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Table_open_cache_misses') AS cache_misses;"}	{"condition": "cache_misses > 0 AND open_tables = open_cache", "description": "Table open cache is full and missing, requiring frequent dictionary lookups that contend on dict_sys mutex"}	\N	2026-05-11 22:17:39.229791
15281	mariadb	query	Check transaction throughput and mutex metrics	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_commit') AS commits, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Com_rollback') AS rollbacks, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'trx_rseg_history_len') AS history_len;"}	{"condition": "commits + rollbacks > 10000 per second", "description": "Very high transaction rate can cause contention on the transaction system mutex"}	\N	2026-05-11 22:17:39.229791
15282	mariadb	query	Check tablespace and I/O thread configuration	{"sql": "SELECT VARIABLE_NAME, VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME IN ('innodb_file_per_table', 'innodb_read_io_threads', 'innodb_write_io_threads', 'innodb_data_file_path') ORDER BY VARIABLE_NAME"}	{"condition": "tablespace_count > 1000 AND file_per_table = 1", "description": "Very many tablespace files can cause fil_system mutex contention during file open/close operations"}	\N	2026-05-11 22:17:39.229791
15283	mariadb	query	Check lock system metrics	{"sql": "SELECT (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_waits') AS lock_waits, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'lock_row_lock_time') AS lock_time_total, (SELECT COUNT(*) FROM performance_schema.data_locks) AS current_locks;"}	{"condition": "current_locks > 10000", "description": "Very high number of active locks indicates lock system mutex may be a bottleneck"}	\N	2026-05-11 22:17:39.229791
15284	mariadb	query	Check undo tablespace configuration	{"sql": "SELECT @@global.innodb_undo_tablespaces AS undo_tablespaces, @@global.innodb_rollback_segments AS rollback_segments, (SELECT COUNT FROM information_schema.INNODB_METRICS WHERE NAME = 'trx_rseg_history_len') AS history_len;"}	{"condition": "undo_tablespaces < 4 OR rollback_segments < 128", "description": "Few undo tablespaces or rollback segments create contention on rseg allocation under high write load"}	\N	2026-05-11 22:17:39.229791
15285	mariadb	query	Check table open cache efficiency	{"sql": "SELECT @@global.table_open_cache AS cache_size, @@global.table_open_cache_instances AS cache_instances, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Table_open_cache_overflows') AS cache_overflows, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Table_open_cache_misses') AS cache_misses;"}	{"condition": "cache_overflows > 0 OR cache_instances = 1", "description": "Table cache overflows or single cache instance causes LOCK_open contention"}	\N	2026-05-11 22:17:39.229791
15286	mariadb	query	Check metadata lock statistics	{"sql": "SELECT COUNT(*) AS total_mdl_locks, SUM(CASE WHEN LOCK_STATUS = 'PENDING' THEN 1 ELSE 0 END) AS pending_locks, SUM(CASE WHEN LOCK_TYPE = 'EXCLUSIVE' THEN 1 ELSE 0 END) AS exclusive_locks FROM performance_schema.metadata_locks;"}	{"condition": "total_mdl_locks > 1000 OR pending_locks > 10", "description": "Very high MDL lock count or many pending locks indicate MDL subsystem contention"}	\N	2026-05-11 22:17:39.229791
