15326	mariadb	query	Find tables with skewed data distribution but no histograms	{"sql": "SELECT t.TABLE_SCHEMA, t.TABLE_NAME, s.COLUMN_NAME, s.CARDINALITY, t.TABLE_ROWS, ROUND(s.CARDINALITY / NULLIF(t.TABLE_ROWS, 0) * 100, 2) AS selectivity_pct FROM information_schema.STATISTICS s JOIN information_schema.TABLES t ON s.TABLE_SCHEMA = t.TABLE_SCHEMA AND s.TABLE_NAME = t.TABLE_NAME LEFT JOIN information_schema.COLUMN_STATISTICS cs ON cs.SCHEMA_NAME = s.TABLE_SCHEMA AND cs.TABLE_NAME = s.TABLE_NAME AND cs.COLUMN_NAME = s.COLUMN_NAME WHERE t.TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys') AND t.TABLE_ROWS > 10000 AND cs.COLUMN_NAME IS NULL AND s.SEQ_IN_INDEX = 1 ORDER BY t.TABLE_ROWS DESC LIMIT 30;"}	{"condition": "large tables with indexed columns missing histograms", "description": "Tables with >10K rows and indexed columns but no histograms may have undetected data skew"}	\N	2026-05-11 22:17:39.229791
6277	oracle	query	ora_find_concurrent_sessions_same_objects	{"sql": "SELECT lo.session_id AS sid, o.object_name, o.object_type, s.sql_id, s.username, s.program FROM v$locked_object lo JOIN dba_objects o ON lo.object_id = o.object_id JOIN v$session s ON lo.session_id = s.sid WHERE s.username NOT IN ('SYS','SYSTEM') AND s.status = 'ACTIVE' ORDER BY o.object_name, lo.session_id"}	{"condition": "row_count > 0", "description": "Multiple sessions holding locks on the same objects may acquire them in different orders"}	\N	2026-02-28 12:19:19.580455
