15410	mariadb	query	Check tmp_table_size and max_heap_table_size	{"sql": "SELECT @@tmp_table_size AS tmp_table_size, @@max_heap_table_size AS max_heap_table_size, LEAST(@@tmp_table_size, @@max_heap_table_size) AS effective_limit;"}	{"condition": "effective limit is small relative to GROUP BY cardinality", "description": "The effective in-memory temp table size is MIN(tmp_table_size, max_heap_table_size). Default is 16MB. High-cardinality GROUP BY may need more."}	\N	2026-05-11 22:17:39.229791
15411	mariadb	query	Find DISTINCT queries creating disk temp tables	{"sql": "SELECT DIGEST_TEXT, COUNT_STAR, SUM_CREATED_TMP_DISK_TABLES / NULLIF(COUNT_STAR, 0) AS avg_disk_tmp_tables, SUM_ROWS_EXAMINED / NULLIF(COUNT_STAR, 0) AS avg_rows_examined, SUM_ROWS_SENT / NULLIF(COUNT_STAR, 0) AS avg_rows_sent FROM performance_schema.events_statements_summary_by_digest WHERE DIGEST_TEXT LIKE '%DISTINCT%' AND SUM_CREATED_TMP_DISK_TABLES > 0 AND COUNT_STAR > 5 ORDER BY SUM_CREATED_TMP_DISK_TABLES DESC LIMIT 20;"}	{"condition": "DISTINCT queries spilling to disk", "description": "DISTINCT on many rows or wide columns exceeds in-memory deduplication capacity"}	\N	2026-05-11 22:17:39.229791
15412	mariadb	query	Check sort buffer configuration and spill rate	{"sql": "SELECT @@sort_buffer_size AS sort_buffer_size, @@join_buffer_size AS join_buffer_size, @@tmp_table_size AS tmp_table_size, @@max_heap_table_size AS max_heap_table_size, (SELECT VARIABLE_VALUE FROM performance_schema.global_variables WHERE VARIABLE_NAME = 'temptable_max_ram') AS temptable_max_ram, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_merge_passes') AS sort_merge_passes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_rows') AS sort_rows"}	{"condition": "sort_buffer_size at default (256KB) with Sort_merge_passes > 0", "description": "Default sort_buffer_size of 256KB is often too small for analytical or reporting queries"}	\N	2026-05-11 22:17:39.229791
15413	mariadb	query	Calculate sort spill ratio	{"sql": "SELECT (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_merge_passes') AS sort_merge_passes, (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_scan') + (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'Sort_range') AS total_sorts;"}	{"condition": "sort_merge_passes / total_sorts > 0.01", "description": "More than 1% of sorts requiring merge passes indicates sort_buffer_size is undersized for the workload"}	\N	2026-05-11 22:17:39.229791
