324	sqlserver	query	Check dynamic quorum vote assignments	{"sql": "SELECT cm.member_name, cm.member_type_desc, cm.member_state_desc,\\n  cm.number_of_quorum_votes,\\n  c.quorum_type_desc, c.quorum_state_desc\\nFROM sys.dm_hadr_cluster c\\nCROSS JOIN sys.dm_hadr_cluster_members cm\\nORDER BY cm.number_of_quorum_votes DESC, cm.member_name"}	{"condition": "row_count > 0", "description": "Dynamic quorum has adjusted votes in an unexpected way reducing resilience"}	null	2026-02-23 20:18:31.389022
524	sqlserver	query	Check transaction log backup frequency and retention	{"sql": "SELECT bs.database_name,\\n  COUNT(*) AS log_backups_last_7d,\\n  MIN(bs.backup_finish_date) AS oldest_log_backup,\\n  MAX(bs.backup_finish_date) AS newest_log_backup,\\n  DATEDIFF(HOUR, MAX(bs.backup_finish_date), GETDATE()) AS hours_since_last_log_backup,\\n  AVG(DATEDIFF(MINUTE, bs.backup_start_date, bs.backup_finish_date)) AS avg_backup_duration_min\\nFROM msdb.dbo.backupset bs\\nWHERE bs.type = 'L'\\n  AND bs.backup_finish_date > DATEADD(day, -7, GETDATE())\\nGROUP BY bs.database_name\\nHAVING COUNT(*) < 24\\n  OR DATEDIFF(HOUR, MAX(bs.backup_finish_date), GETDATE()) > 6\\nORDER BY log_backups_last_7d ASC"}	{"condition": "row_count > 0", "description": "Infrequent log backups limit the granularity and window of point-in-time recovery"}	null	2026-02-23 20:18:31.389161
312	sqlserver	query	Check AG role and database state for health probe validation	{"sql": "SELECT ag.name AS ag_name,\\n  ars.role_desc,\\n  d.name AS db_name, d.state_desc,\\n  d.is_read_only,\\n  ags.synchronization_health_desc\\nFROM sys.availability_groups ag\\nJOIN sys.dm_hadr_availability_replica_states ars ON ag.group_id = ars.group_id\\nJOIN sys.dm_hadr_availability_group_states ags ON ag.group_id = ags.group_id\\nJOIN sys.dm_hadr_database_replica_states drs ON ars.replica_id = drs.replica_id\\nJOIN sys.databases d ON drs.database_id = d.database_id\\nWHERE ars.is_local = 1\\n  AND (d.state_desc <> 'ONLINE'\\n    OR ags.synchronization_health_desc <> 'HEALTHY')"}	{"condition": "row_count > 0", "description": "AG databases in non-online state causing health probe query to fail"}	null	2026-02-23 20:18:31.389023
