855	sqlserver	query	Check file sizes vs volume capacity	{"sql": "SELECT DB_NAME(mf.database_id) AS database_name,\\n  mf.name AS file_name,\\n  mf.type_desc,\\n  CAST(mf.size AS BIGINT) * 8 / 1024 AS file_size_mb,\\n  vs.total_bytes / 1048576 AS volume_total_mb,\\n  vs.available_bytes / 1048576 AS volume_free_mb,\\n  CAST(vs.available_bytes * 100.0 / NULLIF(vs.total_bytes, 0) AS DECIMAL(5,2)) AS volume_free_pct,\\n  mf.max_size,\\n  CASE WHEN mf.max_size = -1 THEN 'UNLIMITED'\\n    WHEN mf.max_size = 0 THEN 'NO GROWTH'\\n    ELSE CAST(CAST(mf.max_size AS BIGINT) * 8 / 1024 AS VARCHAR) + ' MB'\\n  END AS max_size_desc\\nFROM sys.master_files mf\\nCROSS APPLY sys.dm_os_volume_stats(mf.database_id, mf.file_id) vs\\nWHERE mf.database_id > 4\\nORDER BY vs.available_bytes ASC"}	{"condition": "row_count > 0", "description": "Volume hosting database files running low on free space"}	null	2026-02-23 20:18:31.389371
