147	sqlserver	query	Check database size growth trend	{"sql": "SELECT database_name,\\n  MIN(CASE WHEN backup_start_date > DATEADD(day, -90, GETDATE()) AND backup_start_date < DATEADD(day, -60, GETDATE()) THEN backup_size END) AS size_90d_ago,\\n  MIN(CASE WHEN backup_start_date > DATEADD(day, -30, GETDATE()) THEN backup_size END) AS size_30d_ago,\\n  MAX(backup_size) AS current_size,\\n  CAST(100.0 * (MAX(backup_size) - MIN(CASE WHEN backup_start_date > DATEADD(day, -90, GETDATE()) AND backup_start_date < DATEADD(day, -60, GETDATE()) THEN backup_size END)) / NULLIF(MIN(CASE WHEN backup_start_date > DATEADD(day, -90, GETDATE()) AND backup_start_date < DATEADD(day, -60, GETDATE()) THEN backup_size END), 0) AS decimal(5,1)) AS growth_pct_90d\\nFROM msdb.dbo.backupset\\nWHERE type = 'D'\\n  AND backup_start_date > DATEADD(day, -90, GETDATE())\\nGROUP BY database_name\\nHAVING MAX(backup_size) > MIN(CASE WHEN backup_start_date > DATEADD(day, -90, GETDATE()) AND backup_start_date < DATEADD(day, -60, GETDATE()) THEN backup_size END) * 1.5"}	{"condition": "row_count > 0", "description": "Database size grew >50% in 90 days — backup volume may be undersized"}	null	2026-02-23 20:18:31.388916
