304	sqlserver	query	Check secondary replica readiness for promotion	{"sql": "SELECT ar.replica_server_name,\\n  ar.availability_mode_desc, ar.failover_mode_desc,\\n  ars.role_desc, ars.operational_state_desc,\\n  ars.connected_state_desc, ars.synchronization_health_desc,\\n  drs.synchronization_state_desc, drs.is_suspended,\\n  drs.log_send_queue_size, drs.redo_queue_size,\\n  CASE\\n    WHEN ar.failover_mode_desc <> 'AUTOMATIC' THEN 'NOT AUTO-FAILOVER'\\n    WHEN ar.availability_mode_desc <> 'SYNCHRONOUS_COMMIT' THEN 'NOT SYNC-COMMIT'\\n    WHEN drs.synchronization_state_desc <> 'SYNCHRONIZED' THEN 'NOT SYNCHRONIZED'\\n    WHEN drs.is_suspended = 1 THEN 'DATA MOVEMENT SUSPENDED'\\n    WHEN ars.connected_state_desc <> 'CONNECTED' THEN 'DISCONNECTED'\\n    ELSE 'READY' END AS promotion_blocker\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nWHERE ars.role_desc = 'SECONDARY'"}	{"condition": "row_count > 0", "description": "Secondary replicas that cannot accept automatic failover due to missing prerequisites"}	null	2026-02-23 20:18:31.389017
