821	sqlserver	query	Check for sessions performing large data modifications	{"sql": "SELECT s.session_id,\\n  s.login_name,\\n  s.host_name,\\n  s.program_name,\\n  r.command,\\n  r.status,\\n  r.total_elapsed_time / 60000 AS elapsed_min,\\n  r.writes AS pages_written,\\n  r.logical_reads,\\n  tdt.database_transaction_log_bytes_used / 1048576.0 AS log_used_mb,\\n  r.row_count AS rows_affected,\\n  t.text AS query_text\\nFROM sys.dm_exec_requests r\\nJOIN sys.dm_exec_sessions s ON r.session_id = s.session_id\\nJOIN sys.dm_tran_session_transactions tst ON s.session_id = tst.session_id\\nJOIN sys.dm_tran_database_transactions tdt ON tst.transaction_id = tdt.transaction_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE r.command IN ('INSERT', 'BULK INSERT', 'SELECT INTO', 'UPDATE', 'DELETE')\\n  AND (r.writes > 10000 OR tdt.database_transaction_log_bytes_used > 52428800)\\nORDER BY tdt.database_transaction_log_bytes_used DESC"}	{"condition": "row_count > 0", "description": "Active sessions performing large uncontrolled data modifications"}	null	2026-02-23 20:18:31.389352
