720	sqlserver	query	Identify sessions with highest tempdb allocation (likely Agent job sessions)	{"sql": "SELECT TOP 10\\n  t.session_id,\\n  t.user_objects_alloc_page_count * 8 / 1024 AS user_alloc_mb,\\n  t.internal_objects_alloc_page_count * 8 / 1024 AS internal_alloc_mb,\\n  r.command, r.status,\\n  SUBSTRING(st.text, (r.statement_start_offset / 2) + 1,\\n    ((CASE r.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE r.statement_end_offset END - r.statement_start_offset) / 2) + 1) AS current_query,\\n  s.program_name\\nFROM sys.dm_db_task_space_usage t\\nJOIN sys.dm_exec_requests r ON t.session_id = r.session_id\\nCROSS APPLY sys.dm_exec_sql_text(r.sql_handle) st\\nJOIN sys.dm_exec_sessions s ON t.session_id = s.session_id\\nWHERE (t.user_objects_alloc_page_count + t.internal_objects_alloc_page_count) > 1000\\nORDER BY (t.user_objects_alloc_page_count + t.internal_objects_alloc_page_count) DESC"}	{"condition": "row_count > 0", "description": "Agent job sessions consuming significant tempdb through spill or temp table operations"}	null	2026-02-23 20:18:31.389285
