958	sqlserver	query	Check for suspect pages or corruption on replicated databases	{"sql": "SELECT d.name AS database_name,\\n  d.is_published, d.is_subscribed, d.is_merge_published,\\n  sp.event_type, sp.error_count, sp.last_update_date\\nFROM sys.databases d\\nLEFT JOIN msdb.dbo.suspect_pages sp ON d.database_id = sp.database_id\\nWHERE (d.is_published = 1 OR d.is_subscribed = 1 OR d.is_merge_published = 1)\\n  AND (sp.event_type IS NOT NULL OR d.state_desc <> 'ONLINE')\\nORDER BY sp.last_update_date DESC"}	{"condition": "row_count > 0", "description": "Corruption on databases participating in replication — corruption may have propagated from publisher to subscriber or vice versa in merge replication"}	null	2026-02-23 20:18:31.389436
