794	sqlserver	query	Check for highly fragmented indexes	{"sql": "SELECT DB_NAME() AS database_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.index_type_desc,\\n  ips.avg_fragmentation_in_percent,\\n  ips.page_count,\\n  ips.fragment_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.avg_fragmentation_in_percent > 30\\n  AND ips.page_count > 1000\\n  AND ips.index_id > 0\\nORDER BY ips.avg_fragmentation_in_percent DESC"}	{"condition": "row_count > 0", "description": "Significant index fragmentation confirms lack of regular index maintenance"}	null	2026-02-23 20:18:31.389335
