778	sqlserver	query	Check ETL job steps for INSERT without MERGE or upsert pattern	{"sql": "SELECT j.name AS job_name, js.step_id, js.step_name,\\n  SUBSTRING(js.command, 1, 500) AS command_preview,\\n  CASE\\n    WHEN js.command LIKE '%MERGE%' THEN 'HAS_MERGE'\\n    WHEN js.command LIKE '%NOT EXISTS%INSERT%' THEN 'HAS_NOT_EXISTS_CHECK'\\n    WHEN js.command LIKE '%INSERT%SELECT%' AND js.command NOT LIKE '%NOT EXISTS%' AND js.command NOT LIKE '%EXCEPT%'\\n      THEN 'INSERT_WITHOUT_DEDUP'\\n    WHEN js.command LIKE '%BULK INSERT%' THEN 'BULK_INSERT_NO_DEDUP'\\n    ELSE 'OTHER'\\n  END AS idempotency_pattern\\nFROM msdb.dbo.sysjobsteps js\\nJOIN msdb.dbo.sysjobs j ON js.job_id = j.job_id\\nWHERE j.enabled = 1\\n  AND (js.command LIKE '%INSERT%' OR js.command LIKE '%BULK INSERT%')\\n  AND js.command NOT LIKE '%MERGE%'\\n  AND js.command NOT LIKE '%NOT EXISTS%'\\n  AND js.command NOT LIKE '%EXCEPT%'\\nORDER BY j.name, js.step_id"}	{"condition": "row_count > 0", "description": "ETL job steps use plain INSERT without idempotent duplicate handling"}	null	2026-02-23 20:18:31.389324
