328	sqlserver	query	Check cluster size and failure tolerance	{"sql": "SELECT\\n  (SELECT COUNT(*) FROM sys.dm_hadr_cluster_members WHERE member_type_desc = 'CLUSTER_NODE') AS node_count,\\n  (SELECT COUNT(*) FROM sys.dm_hadr_cluster_members WHERE member_type_desc <> 'CLUSTER_NODE') AS witness_count,\\n  c.quorum_type_desc,\\n  CASE \\n    WHEN (SELECT COUNT(*) FROM sys.dm_hadr_cluster_members WHERE member_type_desc = 'CLUSTER_NODE') <= 2\\n      AND (SELECT COUNT(*) FROM sys.dm_hadr_cluster_members WHERE member_type_desc <> 'CLUSTER_NODE') = 0\\n    THEN 'CRITICALLY_UNDERSIZED'\\n    WHEN (SELECT COUNT(*) FROM sys.dm_hadr_cluster_members WHERE member_type_desc = 'CLUSTER_NODE') <= 2\\n    THEN 'MINIMAL'\\n    ELSE 'ADEQUATE' END AS sizing_assessment\\nFROM sys.dm_hadr_cluster c"}	{"condition": "row_count > 0", "description": "Cluster has too few nodes for meaningful failure tolerance"}	null	2026-02-23 20:18:31.389031
525	sqlserver	query	Check backup retention completeness	{"sql": "SELECT bs.database_name,\\n  MIN(bs.backup_finish_date) AS oldest_available_backup,\\n  DATEDIFF(DAY, MIN(bs.backup_finish_date), GETDATE()) AS retention_days,\\n  COUNT(CASE WHEN bs.type = 'D' THEN 1 END) AS full_backups,\\n  COUNT(CASE WHEN bs.type = 'L' THEN 1 END) AS log_backups\\nFROM msdb.dbo.backupset bs\\nWHERE bs.database_name IN (\\n  SELECT name FROM sys.databases\\n  WHERE database_id > 4 AND recovery_model_desc = 'FULL')\\nGROUP BY bs.database_name\\nHAVING DATEDIFF(DAY, MIN(bs.backup_finish_date), GETDATE()) < 3\\nORDER BY retention_days ASC"}	{"condition": "row_count > 0", "description": "Backup retention is too short — PITR window is limited to a few days"}	null	2026-02-23 20:18:31.389162
