394	sqlserver	query	Check synchronous replica availability and wait stats	{"sql": "SELECT ar.replica_server_name,\\n  ar.availability_mode_desc, ar.failover_mode_desc,\\n  ars.connected_state_desc, ars.synchronization_health_desc,\\n  drs.synchronization_state_desc,\\n  drs.log_send_queue_size,\\n  ws.wait_time_ms AS hadr_sync_commit_wait_ms,\\n  ws.waiting_tasks_count AS hadr_sync_commit_waits\\nFROM sys.availability_replicas ar\\nJOIN sys.dm_hadr_availability_replica_states ars ON ar.replica_id = ars.replica_id\\nLEFT JOIN sys.dm_hadr_database_replica_states drs ON ar.replica_id = drs.replica_id\\nCROSS APPLY (\\n  SELECT wait_time_ms, waiting_tasks_count\\n  FROM sys.dm_os_wait_stats WHERE wait_type = 'HADR_SYNC_COMMIT'\\n) ws\\nWHERE ar.availability_mode_desc = 'SYNCHRONOUS_COMMIT'\\n  AND (ars.connected_state_desc = 'DISCONNECTED'\\n    OR drs.synchronization_state_desc <> 'SYNCHRONIZED')"}	{"condition": "row_count > 0", "description": "Synchronous commit replicas unreachable — transactions waiting for remote hardening"}	null	2026-02-23 20:18:31.389075
