698	sqlserver	query	Check index fragmentation and ghost records on large tables	{"sql": "SELECT TOP 20\\n  OBJECT_SCHEMA_NAME(ips.object_id) AS schema_name,\\n  OBJECT_NAME(ips.object_id) AS table_name,\\n  i.name AS index_name,\\n  ips.index_type_desc,\\n  ips.avg_fragmentation_in_percent,\\n  ips.ghost_record_count,\\n  ips.version_ghost_record_count,\\n  ips.page_count,\\n  ips.record_count,\\n  ips.forwarded_record_count\\nFROM sys.dm_db_index_physical_stats(DB_ID(), NULL, NULL, NULL, 'LIMITED') ips\\nJOIN sys.indexes i ON ips.object_id = i.object_id AND ips.index_id = i.index_id\\nWHERE ips.page_count > 1000\\n  AND (ips.avg_fragmentation_in_percent > 30\\n    OR ips.ghost_record_count > 5000\\n    OR ips.forwarded_record_count > 1000)\\nORDER BY ips.ghost_record_count DESC, ips.avg_fragmentation_in_percent DESC"}	{"condition": "row_count > 0", "description": "Significant fragmentation, ghost records, or forwarded records degrading I/O performance"}	null	2026-02-23 20:18:31.38927
