735	sqlserver	query	Check for jobs executed outside their schedule during business hours	{"sql": "SELECT j.name AS job_name,\\n  h.run_date, h.run_time,\\n  STUFF(STUFF(RIGHT('000000' + CAST(h.run_time AS varchar(6)), 6), 5, 0, ':'), 3, 0, ':') AS run_time_fmt,\\n  h.run_status,\\n  ((h.run_duration / 10000) * 3600 + ((h.run_duration % 10000) / 100) * 60 + (h.run_duration % 100)) AS duration_sec,\\n  s.active_start_time AS scheduled_start,\\n  CASE WHEN s.schedule_id IS NULL THEN 'NO_SCHEDULE_MATCH'\\n    WHEN ABS(h.run_time - s.active_start_time) > 500 THEN 'OFF_SCHEDULE'\\n    ELSE 'ON_SCHEDULE' END AS trigger_type\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nLEFT JOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nLEFT JOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE h.step_id = 0\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n  AND h.run_time BETWEEN 70000 AND 190000\\n  AND (s.schedule_id IS NULL OR ABS(h.run_time - s.active_start_time) > 500)\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Jobs that ran during business hours but not at their scheduled time, suggesting manual trigger"}	null	2026-02-23 20:18:31.389294
