810	sqlserver	query	Check tempdb metadata contention (PFS, GAM, SGAM page latch waits)	{"sql": "SELECT wait_type,\\n  waiting_tasks_count,\\n  wait_time_ms,\\n  wait_time_ms / NULLIF(waiting_tasks_count, 0) AS avg_wait_ms\\nFROM sys.dm_os_wait_stats\\nWHERE wait_type IN ('PAGELATCH_UP', 'PAGELATCH_EX', 'PAGELATCH_SH')\\n  AND waiting_tasks_count > 100\\nUNION ALL\\nSELECT 'TEMPDB_METADATA_CONTENTION' AS wait_type,\\n  SUM(page_latch_wait_count) AS waiting_tasks_count,\\n  SUM(page_latch_wait_in_ms) AS wait_time_ms,\\n  SUM(page_latch_wait_in_ms) / NULLIF(SUM(page_latch_wait_count), 0) AS avg_wait_ms\\nFROM tempdb.sys.dm_db_index_operational_stats(DB_ID('tempdb'), NULL, NULL, NULL)\\nWHERE page_latch_wait_count > 0"}	{"condition": "row_count > 0", "description": "Tempdb metadata contention from excessive temp object creation/drop — indicates metadata pressure"}	null	2026-02-23 20:18:31.389345
