712	sqlserver	query	Find cached query plans with table scans and high logical reads	{"sql": "SELECT TOP 20\\n  qs.total_logical_reads / qs.execution_count AS avg_logical_reads,\\n  qs.total_elapsed_time / qs.execution_count / 1000 AS avg_elapsed_ms,\\n  qs.execution_count,\\n  SUBSTRING(st.text, (qs.statement_start_offset / 2) + 1,\\n    ((CASE qs.statement_end_offset WHEN -1 THEN DATALENGTH(st.text)\\n      ELSE qs.statement_end_offset END - qs.statement_start_offset) / 2) + 1) AS query_text,\\n  qp.query_plan\\nFROM sys.dm_exec_query_stats qs\\nCROSS APPLY sys.dm_exec_sql_text(qs.sql_handle) st\\nCROSS APPLY sys.dm_exec_query_plan(qs.plan_handle) qp\\nWHERE qs.total_logical_reads / qs.execution_count > 50000\\n  AND CAST(qp.query_plan AS nvarchar(max)) LIKE '%Table Scan%'\\nORDER BY avg_logical_reads DESC"}	{"condition": "row_count > 0", "description": "Queries with table scans performing excessive logical reads, likely part of Agent job steps"}	null	2026-02-23 20:18:31.38928
