464	sqlserver	query	Check CHECKDB job execution history for failures	{"sql": "SELECT j.name AS job_name, j.enabled,\\n  h.step_name, h.run_date, h.run_time, h.run_duration,\\n  h.run_status,\\n  CASE h.run_status\\n    WHEN 0 THEN 'Failed'\\n    WHEN 1 THEN 'Succeeded'\\n    WHEN 2 THEN 'Retry'\\n    WHEN 3 THEN 'Cancelled'\\n    WHEN 4 THEN 'In Progress'\\n  END AS status_desc,\\n  h.message\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobsteps js ON j.job_id = js.job_id\\nJOIN msdb.dbo.sysjobhistory h ON j.job_id = h.job_id AND js.step_id = h.step_id\\nWHERE (js.command LIKE '%CHECKDB%' OR js.command LIKE '%DBCC%CHECK%'\\n  OR js.command LIKE '%DatabaseIntegrityCheck%'\\n  OR j.name LIKE '%integrity%' OR j.name LIKE '%checkdb%')\\n  AND h.run_status IN (0, 3)\\n  AND h.run_date > CAST(CONVERT(VARCHAR(8), DATEADD(DAY, -30, GETDATE()), 112) AS INT)\\nORDER BY h.run_date DESC, h.run_time DESC"}	{"condition": "row_count > 0", "description": "Integrity check jobs failing or being cancelled"}	null	2026-02-23 20:18:31.38912
