738	sqlserver	query	Compare recent execution times to detect pattern change	{"sql": "SELECT j.name AS job_name,\\n  h.run_date, h.run_time,\\n  CASE WHEN h.run_time BETWEEN 70000 AND 190000 THEN 'BUSINESS_HOURS' ELSE 'OFF_PEAK' END AS time_window,\\n  CASE WHEN h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -7, GETDATE()), 112))\\n    THEN 'RECENT' ELSE 'OLDER' END AS period\\nFROM msdb.dbo.sysjobhistory h\\nJOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id\\nWHERE h.step_id = 0\\n  AND h.run_status IN (0, 1)\\n  AND h.run_date >= CONVERT(int, CONVERT(varchar(8), DATEADD(day, -30, GETDATE()), 112))\\n  AND j.name IN (\\n    SELECT j2.name FROM msdb.dbo.sysjobs j2\\n    JOIN msdb.dbo.sysjobschedules jss2 ON j2.job_id = jss2.job_id\\n    JOIN msdb.dbo.sysschedules s2 ON jss2.schedule_id = s2.schedule_id\\n    WHERE s2.date_modified > DATEADD(day, -30, GETDATE())\\n  )\\nORDER BY j.name, h.run_date, h.run_time"}	{"condition": "row_count > 0", "description": "Execution pattern shifted from off-peak to business hours after schedule modification"}	null	2026-02-23 20:18:31.389297
797	sqlserver	query	Check tempdb space usage by session	{"sql": "SELECT\\n  tsu.session_id,\\n  tsu.internal_objects_alloc_page_count * 8.0 / 1024 AS internal_alloc_mb,\\n  tsu.internal_objects_dealloc_page_count * 8.0 / 1024 AS internal_dealloc_mb,\\n  tsu.user_objects_alloc_page_count * 8.0 / 1024 AS user_obj_alloc_mb,\\n  tsu.user_objects_dealloc_page_count * 8.0 / 1024 AS user_obj_dealloc_mb,\\n  (tsu.user_objects_alloc_page_count - tsu.user_objects_dealloc_page_count) * 8.0 / 1024 AS user_obj_outstanding_mb,\\n  s.login_name, s.host_name, s.program_name,\\n  t.text AS current_query\\nFROM sys.dm_db_session_space_usage tsu\\nJOIN sys.dm_exec_sessions s ON tsu.session_id = s.session_id\\nLEFT JOIN sys.dm_exec_requests r ON tsu.session_id = r.session_id\\nOUTER APPLY sys.dm_exec_sql_text(r.sql_handle) t\\nWHERE (tsu.user_objects_alloc_page_count - tsu.user_objects_dealloc_page_count) > 12800\\nORDER BY user_obj_outstanding_mb DESC"}	{"condition": "row_count > 0", "description": "Sessions holding more than 100 MB of temp table allocations in tempdb"}	null	2026-02-23 20:18:31.389337
