737	sqlserver	query	Check for recently modified job schedules	{"sql": "SELECT j.name AS job_name,\\n  s.name AS schedule_name,\\n  s.date_modified,\\n  s.active_start_time,\\n  STUFF(STUFF(RIGHT('000000' + CAST(s.active_start_time AS varchar(6)), 6), 5, 0, ':'), 3, 0, ':') AS start_time_fmt,\\n  s.freq_type, s.freq_interval, s.freq_subday_type,\\n  s.enabled,\\n  CASE WHEN s.active_start_time BETWEEN 70000 AND 190000 THEN 'BUSINESS_HOURS' ELSE 'OFF_PEAK' END AS time_window,\\n  j.date_modified AS job_modified\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jss ON j.job_id = jss.job_id\\nJOIN msdb.dbo.sysschedules s ON jss.schedule_id = s.schedule_id\\nWHERE (s.date_modified > DATEADD(day, -30, GETDATE())\\n  OR j.date_modified > DATEADD(day, -30, GETDATE()))\\n  AND j.enabled = 1\\nORDER BY CASE WHEN s.date_modified > j.date_modified THEN s.date_modified ELSE j.date_modified END DESC"}	{"condition": "row_count > 0", "description": "Recently modified schedules now targeting business hours"}	null	2026-02-23 20:18:31.389296
