801	sqlserver	query	Check volume free space for all database file locations	{"sql": "SELECT DISTINCT\\n  vs.volume_mount_point,\\n  vs.logical_volume_name,\\n  CAST(vs.total_bytes / 1073741824.0 AS decimal(18,2)) AS total_gb,\\n  CAST(vs.available_bytes / 1073741824.0 AS decimal(18,2)) AS free_gb,\\n  CAST((vs.total_bytes - vs.available_bytes) * 100.0 / vs.total_bytes AS decimal(5,1)) AS pct_used,\\n  STRING_AGG(d.name, ', ') WITHIN GROUP (ORDER BY d.name) AS databases_on_volume\\nFROM sys.master_files mf\\nCROSS APPLY sys.dm_os_volume_stats(mf.database_id, mf.file_id) vs\\nJOIN sys.databases d ON mf.database_id = d.database_id\\nGROUP BY vs.volume_mount_point, vs.logical_volume_name, vs.total_bytes, vs.available_bytes\\nHAVING CAST(vs.available_bytes / 1073741824.0 AS decimal(18,2)) < 10\\n  OR CAST((vs.total_bytes - vs.available_bytes) * 100.0 / vs.total_bytes AS decimal(5,1)) > 90\\nORDER BY pct_used DESC"}	{"condition": "row_count > 0", "description": "Volume hosting database files has less than 10 GB free or is over 90% used"}	null	2026-02-23 20:18:31.38934
669	sqlserver	query	Check jobs scheduled during suspicious hours	{"sql": "SELECT j.name AS job_name,\\n  s.name AS schedule_name,\\n  s.active_start_time,\\n  STUFF(STUFF(RIGHT('000000' + CAST(s.active_start_time AS varchar(6)), 6), 3, 0, ':'), 6, 0, ':') AS formatted_start_time,\\n  s.freq_type,\\n  ja.run_requested_date AS last_run,\\n  ja.next_scheduled_run_date AS next_run\\nFROM msdb.dbo.sysjobs j\\nJOIN msdb.dbo.sysjobschedules jsc ON j.job_id = jsc.job_id\\nJOIN msdb.dbo.sysschedules s ON jsc.schedule_id = s.schedule_id\\nLEFT JOIN msdb.dbo.sysjobactivity ja ON j.job_id = ja.job_id\\n  AND ja.session_id = (SELECT MAX(session_id) FROM msdb.dbo.syssessions)\\nWHERE j.enabled = 1 AND s.enabled = 1\\n  AND ja.next_scheduled_run_date IS NOT NULL\\nORDER BY s.active_start_time"}	{"condition": "row_count > 0", "description": "Jobs running at unexpected hours may indicate timezone mismatch (e.g., maintenance scheduled for 2AM local but running at 2AM UTC)"}	null	2026-02-23 20:18:31.389249
352	sqlserver	query	Check version store size and snapshot isolation settings	{"sql": "SELECT d.name, d.snapshot_isolation_state_desc,\\n  d.is_read_committed_snapshot_on,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Version Store Size (KB)') AS version_store_kb,\\n  (SELECT cntr_value FROM sys.dm_os_performance_counters\\n   WHERE counter_name = 'Longest Transaction Running Time') AS longest_tran_sec,\\n  d.log_reuse_wait_desc\\nFROM sys.databases d\\nWHERE d.database_id > 4\\n  AND (d.snapshot_isolation_state_desc = 'ON'\\n    OR d.is_read_committed_snapshot_on = 1)"}	{"condition": "row_count > 0", "description": "Large version store indicating long-running snapshot transactions"}	null	2026-02-23 20:18:31.389047
221	sqlserver	query	Check for stale statistics with high modification counters	{"sql": "SELECT OBJECT_SCHEMA_NAME(s.object_id) AS schema_name,\\n  OBJECT_NAME(s.object_id) AS table_name,\\n  s.name AS stats_name, sp.last_updated,\\n  sp.rows, sp.modification_counter,\\n  CASE WHEN sp.rows > 0\\n    THEN CAST(100.0 * sp.modification_counter / sp.rows AS decimal(5,1))\\n    ELSE 0 END AS pct_modified\\nFROM sys.stats s\\nCROSS APPLY sys.dm_db_stats_properties(s.object_id, s.stats_id) sp\\nWHERE sp.modification_counter > 0\\n  AND sp.last_updated < DATEADD(day, -7, GETDATE())\\nORDER BY sp.modification_counter DESC"}	{"condition": "row_count > 0", "description": "Statistics with significant modifications but not recently updated"}	null	2026-02-23 20:18:31.388961
