12121	sqlserver	sql_query	Detect after-hours transaction activity	{"sql": "SELECT s.session_id, s.login_name, s.host_name, s.program_name, t.transaction_id, tat.transaction_begin_time, DATEDIFF(SECOND, tat.transaction_begin_time, GETDATE()) AS duration_seconds, DATEPART(HOUR, tat.transaction_begin_time) AS start_hour FROM sys.dm_exec_sessions s JOIN sys.dm_tran_session_transactions t ON t.session_id = s.session_id JOIN sys.dm_tran_active_transactions tat ON tat.transaction_id = t.transaction_id WHERE s.is_user_process = 1 AND (DATEPART(HOUR, tat.transaction_begin_time) < 7 OR DATEPART(HOUR, tat.transaction_begin_time) >= 19) AND s.login_name NOT IN ('sa', 'app_user', 'svc_app', 'etl_service') AND s.login_name NOT LIKE '##%' AND s.login_name NOT LIKE '%$' AND NOT (COALESCE(s.program_name, '') LIKE '%.Net SqlClient Data Provider%' OR COALESCE(s.program_name, '') LIKE '%JDBC%' OR COALESCE(s.program_name, '') LIKE '%jTDS%' OR COALESCE(s.program_name, '') LIKE '%ODBC%' OR COALESCE(s.program_name, '') LIKE 'SQLAlchemy%' OR COALESCE(s.program_name, '') LIKE 'pyodbc%' OR COALESCE(s.program_name, '') LIKE 'python%' OR COALESCE(s.program_name, '') LIKE 'PHP%' OR COALESCE(s.program_name, '') LIKE 'node%' OR (COALESCE(s.program_name, '') <> '' AND LOWER(s.login_name) LIKE '%' + LOWER(s.program_name) + '%')) ORDER BY tat.transaction_begin_time"}	{"condition": "row_count > 0", "description": "Active transactions started outside business hours (before 07:00 or after 19:00) by a non-applicative login may indicate unauthorized or suspicious activity"}	\N	2026-04-03 08:55:36.625782
12163	mysql	sql_query	Detect after-hours transaction activity	{"sql": "SELECT t.trx_id, t.trx_mysql_thread_id, p.USER AS trx_user, p.HOST AS trx_host, p.DB AS trx_db, t.trx_started, TIMESTAMPDIFF(SECOND, t.trx_started, NOW()) AS duration_seconds, HOUR(t.trx_started) AS start_hour, t.trx_state, t.trx_rows_locked, t.trx_rows_modified FROM information_schema.INNODB_TRX t JOIN information_schema.PROCESSLIST p ON p.ID = t.trx_mysql_thread_id WHERE (HOUR(t.trx_started) < 7 OR HOUR(t.trx_started) >= 19) AND p.USER NOT IN ('root','mysql.sys','mysql.session','event_scheduler','app_user','svc_app','etl_service') ORDER BY t.trx_started"}	{"condition": "row_count > 0", "description": "Active transactions started outside business hours (before 07:00 or after 19:00) by a non-applicative login may indicate unauthorized or suspicious activity"}	\N	2026-04-03 08:57:21.470364
