15591	mariadb	query	PRI-001-RC15 Sensitive cols in events_statements / innodb_trx (mysql)	{"sql": "WITH sensitive_cols AS (SELECT c.table_schema AS schema_name, c.table_name, c.column_name, CASE WHEN LOWER(c.column_name) LIKE '%password%' OR LOWER(c.column_name) LIKE '%pass%' THEN 'Password' WHEN LOWER(c.column_name) LIKE '%secret%' OR LOWER(c.column_name) LIKE '%token%' OR LOWER(c.column_name) LIKE '%key%' THEN 'Credential' WHEN LOWER(c.column_name) LIKE '%credit%' OR LOWER(c.column_name) LIKE '%card%' THEN 'Credit Card' WHEN LOWER(c.column_name) LIKE '%ssn%' THEN 'SSN' WHEN LOWER(c.column_name) LIKE '%email%' THEN 'Email' WHEN LOWER(c.column_name) LIKE '%phone%' THEN 'Phone' WHEN LOWER(c.column_name) LIKE '%address%' THEN 'Address' WHEN LOWER(c.column_name) LIKE '%dob%' OR LOWER(c.column_name) LIKE '%birth%' THEN 'Date of Birth' WHEN LOWER(c.column_name) LIKE '%salary%' THEN 'Salary' WHEN LOWER(c.column_name) LIKE '%passport%' THEN 'Passport' WHEN LOWER(c.column_name) LIKE '%medical%' OR LOWER(c.column_name) LIKE '%diagnosis%' THEN 'Medical' WHEN LOWER(c.column_name) LIKE '%teudat%' THEN 'Teudat Zehut' ELSE 'Other Sensitive' END AS pii_category FROM information_schema.columns c WHERE c.table_schema NOT IN ('information_schema','mysql','performance_schema','sys') AND (LOWER(c.column_name) LIKE '%password%' OR LOWER(c.column_name) LIKE '%pass%' OR LOWER(c.column_name) LIKE '%secret%' OR LOWER(c.column_name) LIKE '%token%' OR LOWER(c.column_name) LIKE '%key%' OR LOWER(c.column_name) LIKE '%credit%' OR LOWER(c.column_name) LIKE '%card%' OR LOWER(c.column_name) LIKE '%ssn%' OR LOWER(c.column_name) LIKE '%email%' OR LOWER(c.column_name) LIKE '%phone%' OR LOWER(c.column_name) LIKE '%address%' OR LOWER(c.column_name) LIKE '%dob%' OR LOWER(c.column_name) LIKE '%birth%' OR LOWER(c.column_name) LIKE '%salary%' OR LOWER(c.column_name) LIKE '%passport%' OR LOWER(c.column_name) LIKE '%medical%' OR LOWER(c.column_name) LIKE '%diagnosis%' OR LOWER(c.column_name) LIKE '%teudat%')) SELECT 'cached_plan' AS source, NULL AS session_id, NULL AS transaction_id, d.count_star AS execution_count, d.last_seen AS last_execution_time, NULL AS avg_reads, d.avg_timer_wait / 1000000000 AS avg_cpu_ms, NULL AS transaction_begin_time, sc.schema_name, sc.table_name, sc.column_name, sc.pii_category, LEFT(d.digest_text, 4000) AS query_text, NULL AS login_name FROM performance_schema.events_statements_summary_by_digest d JOIN sensitive_cols sc ON d.digest_text LIKE CONCAT('%', sc.table_name, '%') WHERE d.digest_text IS NOT NULL UNION ALL SELECT 'active_transaction' AS source, trx.trx_mysql_thread_id AS session_id, trx.trx_id AS transaction_id, NULL, NULL, NULL, NULL, trx.trx_started AS transaction_begin_time, sc.schema_name, sc.table_name, sc.column_name, sc.pii_category, LEFT(trx.trx_query, 4000) AS query_text, p.user AS login_name FROM information_schema.innodb_trx trx JOIN sensitive_cols sc ON trx.trx_query LIKE CONCAT('%', sc.table_name, '%') LEFT JOIN information_schema.processlist p ON p.id = trx.trx_mysql_thread_id WHERE trx.trx_state = 'RUNNING' AND trx.trx_query IS NOT NULL ORDER BY 1, 5 DESC"}	{"severity": "high", "condition": "row_count > 0", "description": "Sensitive columns referenced by performance_schema digest (cached) or innodb_trx (active) — requires performance_schema enabled"}	\N	2026-05-11 22:17:39.229791
