an' AS source, CAST(NULL AS NUMBER) AS session_id, CAST(NULL AS VARCHAR2(50)) AS transaction_id, sql.executions AS execution_count, sql.last_active_time AS last_execution_time, sql.buffer_gets / NULLIF(sql.executions, 0) AS avg_reads, sql.cpu_time / NULLIF(sql.executions, 0) / 1000 AS avg_cpu_ms, CAST(NULL AS DATE) AS transaction_begin_time, sc.schema_name, sc.table_name, sc.column_name, sc.pii_category, SUBSTR(sql.sql_text, 1, 4000) AS query_text, CAST(NULL AS VARCHAR2(128)) AS login_name FROM v$sql sql JOIN sensitive_cols sc ON UPPER(sql.sql_text) LIKE '%' || UPPER(sc.table_name) || '%' WHERE sql.sql_text IS NOT NULL UNION ALL SELECT 'active_transaction' AS source, s.sid AS session_id, t.xidusn || '.' || t.xidslot || '.' || t.xidsqn AS transaction_id, CAST(NULL AS NUMBER), CAST(NULL AS DATE), CAST(NULL AS NUMBER), CAST(NULL AS NUMBER), t.start_date AS transaction_begin_time, sc.schema_name, sc.table_name, sc.column_name, sc.pii_category, SUBSTR(sql.sql_text, 1, 4000) AS query_text, s.username AS login_name FROM v$transaction t JOIN v$session s ON s.taddr = t.addr JOIN v$sql sql ON sql.sql_id = COALESCE(s.sql_id, s.prev_sql_id) JOIN sensitive_cols sc ON UPPER(sql.sql_text) LIKE '%' || UPPER(sc.table_name) || '%' WHERE s.type = 'USER' AND sql.sql_text IS NOT NULL ORDER BY 1, 5 DESC NULLS LAST"}	{"severity": "high", "condition": "row_count > 0", "description": "Sensitive columns referenced by cached plans (V$SQL) or active transactions (V$TRANSACTION) — historical + uncommitted PII exposure"}	\N	2026-05-01 11:10:17.578908
13067	postgresql	query	PRI-001-RC15 Sensitive cols in pg_stat_statements / pg_stat_activity (postgresql)	{"sql": "WITH sensitive_cols AS (SELECT n.nspname AS schema_name, c.relname AS table_name, a.attname AS column_name, CASE WHEN a.attname ~ '(password|pass)' THEN 'Password' WHEN a.attname ~ '(secret|token|key)' THEN 'Credential' WHEN a.attname ~ '(credit|card)' THEN 'Credit Card' WHEN a.attname ~ 'ssn' THEN 'SSN' WHEN a.attname ~ 'email' THEN 'Email' WHEN a.attname ~ 'phone' THEN 'Phone' WHEN a.attname ~ 'address' THEN 'Address' WHEN a.attname ~ '(dob|birth)' THEN 'Date of Birth' WHEN a.attname ~ 'salary' THEN 'Salary' WHEN a.attname ~ 'passport' THEN 'Passport' WHEN a.attname ~ '(medical|diagnosis)' THEN 'Medical' WHEN a.attname ~ 'teudat' THEN 'Teudat Zehut' ELSE 'Other Sensitive' END AS pii_category FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE c.relkind = 'r' AND a.attnum > 0 AND NOT a.attisdropped AND n.nspname NOT IN ('pg_catalog','information_schema','pg_toast') AND a.attname ~ '(password|pass|secret|token|key|credit|card|ssn|email|phone|address|dob|birth|salary|passport|medical|diagnosis|teudat)') SELECT 'cached_plan' AS source, NULL::INT AS session_id, NULL::TEXT AS transaction_id, pss.calls AS execution_count, NULL::TIMESTAMPTZ AS last_execution_time, (pss.shared_blks_read / NULLIF(pss.calls, 0))::BIGINT AS avg_reads, pss.mean_exec_time::NUMERIC AS avg_cpu_ms, NULL::TIMESTAMPTZ AS transaction_begin_time, sc.schema_name, sc.table_name, sc.column_name, sc.pii_category, LEFT(pss.query, 4000) AS query_text, pg_get_userbyid(pss.userid) AS login_name FROM pg_stat_statements pss JOIN sensitive_cols sc ON pss.query ILIKE '%' || sc.table_name || '%' UNION ALL SELECT 'active_transaction' AS source, psa.pid::INT AS session_id, psa.backend_xid::TEXT AS transaction_id, NULL::BIGINT, NULL::TIMESTAMPTZ, NULL::BIGINT, NULL::NUMERIC, psa.xact_start AS transaction_begin_time, sc.schema_name, sc.table_name, sc.column_name, sc.pii_category, LEFT(psa.query, 4000) AS query_text, psa.usename AS login_name FROM pg_stat_activity psa JOIN sensitive_cols sc ON psa.query ILIKE '%' || sc.table_name || '%' WHERE psa.xact_start IS NOT NULL AND psa.pid <> pg_backend_pid() AND psa.backend_type = 'client backend' ORDER BY 1, 5 DESC NULLS LAST"}	{"severity": "high", "condition": "row_count > 0", "description": "Sensitive columns referenced by pg_stat_statements (cached) or pg_stat_activity (open transactions) — requires pg_stat_statements extension"}	\N	2026-05-01 11:10:17.578908
13065	sqlserver	query	PRI-001-RC15 Sensitive cols in query_stats / active_tx (sqlserver)	{"sql": "SET NOCOUNT ON;\\n\\nIF OBJECT_ID('tempdb..#sensitive_cols') IS NOT NULL DROP TABLE #sensitive_cols;\\nCREATE TABLE #sensitive_cols (\\n    db_name      sysname,\\n    schema_name  sysname,\\n    table_name   sysname,\\n    column_name  sysname,\\n    pii_category nvarchar(50)\\n);\\n\\nDECLARE @sql nvarchar(max) = N'';\\nSELECT @sql = @sql + N'\\nUSE ' + QUOTENAME(name) + N';\\nINSERT INTO #sensitive_cols (db_name, schema_name, table_name, column_name, pii_category)\\nSELECT DB_NAME(), s.name, t.name, c.name,\\n  CASE\\n    WHEN LOWER(c.name) LIKE ''%password%'' OR LOWER(c.name) LIKE ''%pass%'' THEN ''Password''\\n    WHEN LOWER(c.name) LIKE ''%secret%''   OR LOWER(c.name) LIKE ''%token%'' OR LOWER(c.name) LIKE ''%key%'' THEN ''Credential''\\n    WHEN LOWER(c.name) LIKE ''%credit%''   OR LOWER(c.name) LIKE ''%card%''  THEN ''Credit Card''\\n    WHEN LOWER(c.name) LIKE ''%ssn%''      THEN ''SSN''\\n    WHEN LOWER(c.name) LIKE ''%email%''    THEN ''Email''\\n    WHEN LOWER(c.name) LIKE ''%phone%''    THEN ''Phone''\\n    WHEN LOWER(c.name) LIKE ''%address%''  THEN ''Address''\\n    WHEN LOWER(c.name) LIKE ''%dob%''      OR LOWER(c.name) LIKE ''%birth%'' THEN ''Date of Birth''\\n    WHEN LOWER(c.name) LIKE ''%salary%''   THEN ''Salary''\\n    WHEN LOWER(c.name) LIKE ''%passport%'' THEN ''Passport''\\n    WHEN LOWER(c.name) LIKE ''%medical%''  OR LOWER(c.name) LIKE ''%diagnosis%'' THEN ''Medical''\\n    WHEN LOWER(c.name) LIKE ''%teudat%''   THEN ''Teudat Zehut''\\n    ELSE ''Other Sensitive''\\n  END\\nFROM sys.tables  t\\nJOIN sys.columns c ON c.object_id = t.object_id\\nJOIN sys.schemas s ON s.schema_id = t.schema_id\\nWHERE t.is_ms_shipped = 0\\n  AND (LOWER(c.name) LIKE ''%password%'' OR LOWER(c.name) LIKE ''%pass%''\\n    OR LOWER(c.name) LIKE ''%secret%''   OR LOWER(c.name) LIKE ''%token%'' OR LOWER(c.name) LIKE ''%key%''\\n    OR LOWER(c.name) LIKE ''%credit%''   OR LOWER(c.name) LIKE ''%card%''\\n    OR LOWER(c.name) LIKE ''%ssn%''\\n    OR LOWER(c.name) LIKE ''%email%''\\n    OR LOWER(c.name) LIKE ''%phone%''\\n    OR LOWER(c.name) LIKE ''%address%''\\n    OR LOWER(c.name) LIKE ''%dob%''      OR LOWER(c.name) LIKE ''%birth%''\\n    OR LOWER(c.name) LIKE ''%salary%''\\n    OR LOWER(c.name) LIKE ''%passport%''\\n    OR LOWER(c.name) LIKE ''%medical%''  OR LOWER(c.name) LIKE ''%diagnosis%''\\n    OR LOWER(c.name) LIKE ''%teudat%'');\\n'\\nFROM sys.databases\\nWHERE state = 0\\n  AND database_id > 4\\n  AND HAS_DBACCESS(name) = 1\\n  AND name NOT IN ('distribution', 'ReportServer', 'ReportServerTempDB', 'SSISDB');\\n\\nEXEC sp_executesql @sql;\\n\\nSELECT top 100 'cached_plan'         AS source,\\n       CAST(NULL AS INT)     AS session_id,\\n       CAST(NULL AS BIGINT)  AS transaction_id,\\n       qs.execution_count,\\n       qs.last_execution_time,\\n       qs.total_logical_reads / NULLIF(qs.execution_count, 0)         AS avg_reads,\\n       qs.total_worker_time / NULLIF(qs.execution_count, 0) / 1000    AS avg_cpu_ms,\\n       CAST(NULL AS DATETIME) AS transaction_begin_time,\\n       sc.db_name, sc.schema_name, sc.table_name, sc.column_name, sc.pii_category,\\n       LEFT(t.text, 4000)    AS query_text,\\n       CAST(NULL AS sysname) AS login_name\\nFROM sys.dm_exec_query_stats AS qs WITH (NOLOCK)\\nCROSS APPLY sys.dm_exec_sql_text(qs.plan_handle) AS t\\nJOIN #sensitive_cols sc ON t.text LIKE '%' + sc.table_name + '%'\\nWHERE t.text IS NOT NULL\\n  AND LEFT(t.text, 4000) NOT LIKE '%tempdb..#sensitive_cols%'\\nUNION ALL\\nSELECT 'active_transaction'  AS source,\\n       ses.session_id,\\n       tat.transaction_id,\\n       CAST(NULL AS BIGINT)  AS execution_count,\\n       CAST(NULL AS DATETIME) AS last_execution_time,\\n       CAST(NULL AS BIGINT)  AS avg_reads,\\n       CAST(NULL AS BIGINT)  AS avg_cpu_ms,\\n       tat.transaction_begin_time,\\n       sc.db_name, sc.schema_name, sc.table_name, sc.column_name, sc.pii_category,\\n       LEFT(t.text, 4000)    AS query_text,\\n       ses.login_name AS login_name\\nFROM sys.dm_tran_active_transactions    tat\\nJOIN sys.dm_tran_session_transactions   sts ON sts.transaction_id = tat.transaction_id\\nJOIN sys.dm_exec_sessions               ses ON ses.session_id     = sts.session_id\\nJOIN sys.dm_exec_connections            con ON con.session_id     = sts.session_id\\nCROSS APPLY sys.dm_exec_sql_text(con.most_recent_sql_handle) AS t\\nJOIN #sensitive_cols sc ON t.text LIKE '%' + sc.table_name + '%'\\nWHERE tat.transaction_state = 2\\n  AND ses.is_user_process   = 1\\n  AND t.text IS NOT NULL\\n  AND LEFT(t.text, 4000) NOT LIKE '%tempdb..#sensitive_cols%'\\nORDER BY source, last_execution_time;"}	{"severity": "high", "condition": "row_count > 0", "description": "Sensitive columns referenced by cached query plans or active transactions — historical + uncommitted PII exposure"}	\N	2026-05-01 11:00:40.200119
