15595	sqlserver	query	Detect SEC-SQL-AUTHZ-001-RC01 (sqlserver)	{"sql": "\\nSET NOCOUNT ON;\\nIF OBJECT_ID('tempdb..#access') IS NOT NULL DROP TABLE #access;\\nCREATE TABLE #access (server SYSNAME NULL, database_name SYSNAME NULL, login_name SYSNAME NULL, database_user SYSNAME NULL, principal_type NVARCHAR(60) NULL, roles NVARCHAR(MAX) NULL, permissions NVARCHAR(MAX) NULL, login_status NVARCHAR(40) NULL);\\nDECLARE @db SYSNAME; DECLARE @sql NVARCHAR(MAX);\\nDECLARE db_cursor CURSOR LOCAL FAST_FORWARD FOR\\n    SELECT name FROM sys.databases\\n    WHERE state = 0 AND database_id > 4 AND HAS_DBACCESS(name) = 1\\n      AND name NOT IN ('master','model','msdb','tempdb','distribution','ReportServer','ReportServerTempDB','SSISDB');\\nOPEN db_cursor; FETCH NEXT FROM db_cursor INTO @db;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n    SET @sql = N'USE ' + QUOTENAME(@db) + N';\\nINSERT INTO #access (server, database_name, login_name, database_user, principal_type, roles, permissions, login_status)\\nSELECT @@SERVERNAME, DB_NAME(), sp.name, dp.name, dp.type_desc, r.roles, g.permissions, CASE WHEN sp.name IS NOT NULL THEN ''mapped'' WHEN dp.authentication_type_desc = ''INSTANCE'' THEN ''ORPHANED'' WHEN dp.authentication_type_desc = ''DATABASE'' THEN ''contained'' WHEN dp.authentication_type_desc = ''NONE'' THEN ''no-login'' ELSE dp.authentication_type_desc END\\nFROM sys.database_principals AS dp\\nLEFT JOIN sys.server_principals AS sp ON sp.sid = dp.sid\\nLEFT JOIN ( SELECT drm.member_principal_id AS member_id, STRING_AGG(rolep.name COLLATE DATABASE_DEFAULT, '','') WITHIN GROUP (ORDER BY rolep.name) AS roles\\n    FROM sys.database_role_members AS drm INNER JOIN sys.database_principals AS rolep ON rolep.principal_id = drm.role_principal_id\\n    GROUP BY drm.member_principal_id ) AS r ON r.member_id = dp.principal_id\\nLEFT JOIN ( SELECT perm.grantee_principal_id AS grantee_id, STRING_AGG(perm.state_desc COLLATE DATABASE_DEFAULT + '' '' + perm.permission_name + '' ON '' +\\n        CASE perm.class WHEN 0 THEN DB_NAME()\\n            WHEN 1 THEN ISNULL(QUOTENAME(SCHEMA_NAME(o.schema_id)) + ''.'', '''') + ISNULL(o.name, ''(object_id '' + CAST(perm.major_id AS NVARCHAR(20)) + '')'')\\n            WHEN 3 THEN ISNULL(s.name, ''(schema_id '' + CAST(perm.major_id AS NVARCHAR(20)) + '')'')\\n            ELSE perm.class_desc + '' (major_id '' + CAST(perm.major_id AS NVARCHAR(20)) + '')'' END, '', '') AS permissions\\n    FROM sys.database_permissions AS perm\\n    LEFT JOIN sys.objects AS o ON perm.class = 1 AND o.object_id = perm.major_id\\n    LEFT JOIN sys.schemas AS s ON perm.class = 3 AND s.schema_id = perm.major_id\\n    GROUP BY perm.grantee_principal_id ) AS g ON g.grantee_id = dp.principal_id\\nWHERE dp.type IN (''S'',''U'',''G'',''E'',''X'') AND dp.is_fixed_role = 0 AND dp.principal_id >= 5\\n  AND dp.name NOT IN (''sys'',''INFORMATION_SCHEMA'',''guest'');';\\n    EXEC sys.sp_executesql @sql;\\n    FETCH NEXT FROM db_cursor INTO @db;\\nEND\\nCLOSE db_cursor; DEALLOCATE db_cursor;\\nSELECT server, database_name, login_name, database_user, principal_type, roles, permissions, login_status FROM #access ORDER BY database_name, database_user;\\nDROP TABLE #access;\\n"}	{"condition": "row_count > 0", "description": "Database principals with their roles and permission grants across all user databases"}	\N	2026-06-10 10:41:19.763449
15600	postgresql	query	Detect SEC-SQL-AUTHZ-001-RC01 (postgresql)	{"sql": "SELECT\\n  coalesce(host(inet_server_addr()), 'localhost')          AS server,\\n  current_database()                                       AS database_name,\\n  CASE WHEN r.rolcanlogin THEN r.rolname END               AS login_name,\\n  r.rolname                                                AS database_user,\\n  CASE WHEN r.rolsuper THEN 'SUPERUSER'\\n       WHEN r.rolcanlogin THEN 'LOGIN' ELSE 'ROLE' END     AS principal_type,\\n  (SELECT string_agg(g.rolname, ', ' ORDER BY g.rolname)\\n     FROM pg_auth_members m JOIN pg_roles g ON g.oid = m.roleid\\n    WHERE m.member = r.oid)                                AS roles,\\n  (SELECT string_agg(DISTINCT tp.privilege_type, ', ')\\n     FROM information_schema.role_table_grants tp\\n    WHERE tp.grantee = r.rolname)                          AS permissions,\\n  CASE WHEN r.rolcanlogin THEN 'login' ELSE 'no-login' END AS login_status\\nFROM pg_roles r\\nWHERE r.rolname NOT LIKE 'pg\\\\_%'\\nORDER BY r.rolname", "condition": "row_count > 0", "description": "Database access & privilege inventory (logins, roles, grants)"}	\N	\N	2026-06-13 07:18:03.021344
15601	oracle	query	Detect SEC-SQL-AUTHZ-001-RC01 (oracle)	{"sql": "SELECT\\n  sys_context('USERENV','SERVER_HOST')  AS server,\\n  sys_context('USERENV','DB_NAME')      AS database_name,\\n  u.username                            AS login_name,\\n  u.username                            AS database_user,\\n  'USER'                                AS principal_type,\\n  (SELECT LISTAGG(rp.granted_role, ', ') WITHIN GROUP (ORDER BY rp.granted_role)\\n     FROM dba_role_privs rp WHERE rp.grantee = u.username) AS roles,\\n  (SELECT LISTAGG(sp.privilege, ', ') WITHIN GROUP (ORDER BY sp.privilege)\\n     FROM dba_sys_privs sp WHERE sp.grantee = u.username)  AS permissions,\\n  u.account_status                      AS login_status\\nFROM dba_users u\\nWHERE u.oracle_maintained = 'N'\\nORDER BY u.username", "condition": "row_count > 0", "description": "Database access & privilege inventory (logins, roles, grants)"}	\N	\N	2026-06-13 07:18:03.021344
15602	mysql	query	Detect SEC-SQL-AUTHZ-001-RC01 (mysql)	{"sql": "SELECT\\n  @@hostname                                          AS server,\\n  NULL                                                AS database_name,\\n  CONCAT(u.User, '@', u.Host)                         AS login_name,\\n  CONCAT(u.User, '@', u.Host)                         AS database_user,\\n  'USER'                                              AS principal_type,\\n  (SELECT GROUP_CONCAT(CONCAT(re.FROM_USER,'@',re.FROM_HOST) ORDER BY re.FROM_USER SEPARATOR ', ')\\n     FROM mysql.role_edges re WHERE re.TO_USER=u.User AND re.TO_HOST=u.Host) AS roles,\\n  (SELECT GROUP_CONCAT(DISTINCT up.PRIVILEGE_TYPE ORDER BY up.PRIVILEGE_TYPE SEPARATOR ', ')\\n     FROM information_schema.USER_PRIVILEGES up\\n    WHERE up.GRANTEE = CONCAT(\\"'\\", u.User, \\"'@'\\", u.Host, \\"'\\")) AS permissions,\\n  CASE WHEN u.account_locked='Y' THEN 'locked' ELSE 'active' END AS login_status\\nFROM mysql.user u\\nORDER BY u.User, u.Host", "condition": "row_count > 0", "description": "Database access & privilege inventory (logins, roles, grants)"}	\N	\N	2026-06-13 07:18:03.021344
15603	mariadb	query	Detect SEC-SQL-AUTHZ-001-RC01 (mariadb)	{"sql": "SELECT\\n  @@hostname                                          AS server,\\n  NULL                                                AS database_name,\\n  CONCAT(u.User, '@', u.Host)                         AS login_name,\\n  CONCAT(u.User, '@', u.Host)                         AS database_user,\\n  CASE WHEN u.is_role='Y' THEN 'ROLE' ELSE 'USER' END AS principal_type,\\n  (SELECT GROUP_CONCAT(rm.Role ORDER BY rm.Role SEPARATOR ', ')\\n     FROM mysql.roles_mapping rm WHERE rm.User=u.User AND rm.Host=u.Host) AS roles,\\n  (SELECT GROUP_CONCAT(DISTINCT up.PRIVILEGE_TYPE ORDER BY up.PRIVILEGE_TYPE SEPARATOR ', ')\\n     FROM information_schema.USER_PRIVILEGES up\\n    WHERE up.GRANTEE = CONCAT(\\"'\\", u.User, \\"'@'\\", u.Host, \\"'\\")) AS permissions,\\n  'active'                                            AS login_status\\nFROM mysql.user u\\nORDER BY u.User, u.Host", "condition": "row_count > 0", "description": "Database access & privilege inventory (logins, roles, grants)"}	\N	\N	2026-06-13 07:18:03.021344
15604	informix	query	Detect SEC-SQL-AUTHZ-001-RC01 (informix)	{"sql": "SELECT\\n  DBINFO('dbname')   AS server,\\n  DBINFO('dbname')   AS database_name,\\n  TRIM(u.username)   AS login_name,\\n  TRIM(u.username)   AS database_user,\\n  CASE u.usertype WHEN 'D' THEN 'DBA' WHEN 'R' THEN 'RESOURCE'\\n       WHEN 'C' THEN 'CONNECT' ELSE u.usertype END AS principal_type,\\n  CAST(NULL AS VARCHAR(255)) AS roles,\\n  u.usertype         AS permissions,\\n  'active'           AS login_status\\nFROM sysusers u\\nORDER BY u.username", "condition": "row_count > 0", "description": "Database access & privilege inventory (logins, roles, grants)"}	\N	\N	2026-06-13 07:18:03.021344
